window.HSK_DATA["7-9-p4"] = [{"id":"阿拉伯语","hanzi":"阿拉伯语","pinyin":"Ālābóyǔ","meaning_vi":"tiếng Ả Rập","explanation":"阿拉伯 (A-lạp-bá – phiên âm \"Arab\") + 语 (ngữ – ngôn ngữ) → tiếng Ả Rập.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他会说阿拉伯语。","pinyin":"Tā huì shuō Ālābóyǔ.","vi":"Anh ấy biết nói tiếng Ả Rập."},{"type":"simple","zh":"她在大学里学了四年阿拉伯语。","pinyin":"Tā zài dàxué lǐ xuéle sì nián Ālābóyǔ.","vi":"Cô ấy đã học tiếng Ả Rập bốn năm ở đại học."},{"type":"compound","zh":"虽然阿拉伯语很难学，但是他坚持每天练习。","pinyin":"Suīrán Ālābóyǔ hěn nán xué, dànshì tā jiānchí měitiān liànxí.","vi":"Tuy tiếng Ả Rập rất khó học nhưng anh ấy kiên trì luyện tập mỗi ngày."}],"related":[{"hanzi":"阿拉伯","pinyin":"Ālābó","vi":"Ả Rập"},{"hanzi":"外语","pinyin":"wàiyǔ","vi":"ngoại ngữ"},{"hanzi":"英语","pinyin":"Yīngyǔ","vi":"tiếng Anh"},{"hanzi":"语言","pinyin":"yǔyán","vi":"ngôn ngữ"}],"traditional":"阿拉伯語"},{"id":"哎","hanzi":"哎","pinyin":"āi","meaning_vi":"này, ơ, ôi (thán từ)","explanation":"哎 (ai – tiếng than) → thán từ dùng để gọi người khác chú ý, hoặc tỏ ý ngạc nhiên, không hài lòng.","hsk_level":"7-9","tags":["tro-tu","giao-tiep"],"image":"🙋","examples":[{"type":"basic","zh":"哎，你等等我！","pinyin":"Āi, nǐ děngdeng wǒ!","vi":"Này, đợi tôi với!"},{"type":"simple","zh":"哎，你的钱包掉在地上了。","pinyin":"Āi, nǐ de qiánbāo diào zài dìshang le.","vi":"Này, ví của bạn rơi xuống đất rồi."},{"type":"compound","zh":"哎，如果你明天有空，就来我家吃饭吧。","pinyin":"Āi, rúguǒ nǐ míngtiān yǒukòng, jiù lái wǒ jiā chīfàn ba.","vi":"Này, nếu mai bạn rảnh thì đến nhà tôi ăn cơm nhé."}],"related":[{"hanzi":"哎呀","pinyin":"āiyā","vi":"ôi chao"},{"hanzi":"唉","pinyin":"āi","vi":"haizz"},{"hanzi":"喂","pinyin":"wèi","vi":"này, alô"},{"hanzi":"哎哟","pinyin":"āiyō","vi":"ối"}]},{"id":"哎呀","hanzi":"哎呀","pinyin":"āiyā","meaning_vi":"ôi chao, trời ơi","explanation":"哎 (ai) + 呀 (nha) – đều là tiếng cảm thán → \"ôi chao\", biểu lộ ngạc nhiên, tiếc nuối hoặc than phiền.","hsk_level":"7-9","tags":["tro-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"哎呀，我忘带钥匙了！","pinyin":"Āiyā, wǒ wàng dài yàoshi le!","vi":"Ôi chao, tôi quên mang chìa khóa rồi!"},{"type":"simple","zh":"哎呀，这件衣服怎么这么贵啊！","pinyin":"Āiyā, zhè jiàn yīfu zěnme zhème guì a!","vi":"Trời ơi, cái áo này sao đắt thế!"},{"type":"compound","zh":"哎呀，要是早点出门，我们就不会迟到了。","pinyin":"Āiyā, yàoshi zǎodiǎn chūmén, wǒmen jiù bú huì chídào le.","vi":"Ôi chao, nếu ra khỏi nhà sớm hơn thì chúng ta đã không bị muộn rồi."}],"related":[{"hanzi":"哎","pinyin":"āi","vi":"này"},{"hanzi":"哎哟","pinyin":"āiyō","vi":"ối"},{"hanzi":"天哪","pinyin":"tiānna","vi":"trời ơi"},{"hanzi":"糟糕","pinyin":"zāogāo","vi":"hỏng rồi"}]},{"id":"癌","hanzi":"癌","pinyin":"ái","meaning_vi":"ung thư","explanation":"癌 (nham – khối u ác tính) → bệnh ung thư; thường dùng trong từ ghép như 肺癌, 癌症.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🎗️","examples":[{"type":"basic","zh":"他得了肺癌。","pinyin":"Tā déle fèi'ái.","vi":"Ông ấy bị ung thư phổi."},{"type":"simple","zh":"吸烟会大大增加患癌的风险。","pinyin":"Xīyān huì dàdà zēngjiā huàn'ái de fēngxiǎn.","vi":"Hút thuốc làm tăng mạnh nguy cơ mắc ung thư."},{"type":"compound","zh":"如果癌细胞发现得早，治愈的机会就大得多。","pinyin":"Rúguǒ áixìbāo fāxiàn de zǎo, zhìyù de jīhuì jiù dà de duō.","vi":"Nếu tế bào ung thư được phát hiện sớm thì cơ hội chữa khỏi lớn hơn nhiều."}],"related":[{"hanzi":"癌症","pinyin":"áizhèng","vi":"bệnh ung thư"},{"hanzi":"肿瘤","pinyin":"zhǒngliú","vi":"khối u"},{"hanzi":"肺癌","pinyin":"fèi'ái","vi":"ung thư phổi"},{"hanzi":"化疗","pinyin":"huàliáo","vi":"hóa trị"}]},{"id":"艾滋病","hanzi":"艾滋病","pinyin":"àizībìng","meaning_vi":"bệnh AIDS, HIV/AIDS","explanation":"艾滋 (ngải tư – phiên âm \"AIDS\") + 病 (bệnh) → bệnh AIDS, hội chứng suy giảm miễn dịch mắc phải.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"艾滋病可以预防。","pinyin":"Àizībìng kěyǐ yùfáng.","vi":"Bệnh AIDS có thể phòng ngừa."},{"type":"simple","zh":"每年十二月一日是世界艾滋病日。","pinyin":"Měinián Shí'èryuè yī rì shì shìjiè àizībìng rì.","vi":"Ngày 1 tháng 12 hằng năm là Ngày Thế giới phòng chống AIDS."},{"type":"compound","zh":"虽然艾滋病目前还不能根治，但是可以用药物控制。","pinyin":"Suīrán àizībìng mùqián hái bù néng gēnzhì, dànshì kěyǐ yòng yàowù kòngzhì.","vi":"Tuy hiện nay AIDS chưa thể chữa tận gốc nhưng có thể kiểm soát bằng thuốc."}],"related":[{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"传染","pinyin":"chuánrǎn","vi":"lây nhiễm"},{"hanzi":"免疫","pinyin":"miǎnyì","vi":"miễn dịch"},{"hanzi":"癌症","pinyin":"áizhèng","vi":"ung thư"}]},{"id":"爱面子","hanzi":"爱面子","pinyin":"àimiànzi","meaning_vi":"sĩ diện, trọng thể diện, sợ mất mặt","explanation":"爱 (ái – thích) + 面子 (diện tử – thể diện) → thích giữ thể diện, sợ bị người khác coi thường.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😤","examples":[{"type":"basic","zh":"他特别爱面子。","pinyin":"Tā tèbié àimiànzi.","vi":"Anh ta cực kỳ sĩ diện."},{"type":"simple","zh":"爱面子的人很难承认自己的错误。","pinyin":"Àimiànzi de rén hěn nán chéngrèn zìjǐ de cuòwù.","vi":"Người sĩ diện rất khó thừa nhận sai lầm của mình."},{"type":"compound","zh":"因为他爱面子，所以明明不懂也不愿意问。","pinyin":"Yīnwèi tā àimiànzi, suǒyǐ míngmíng bù dǒng yě bú yuànyì wèn.","vi":"Vì sĩ diện nên dù rõ ràng không hiểu anh ấy cũng không chịu hỏi."}],"related":[{"hanzi":"面子","pinyin":"miànzi","vi":"thể diện"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"},{"hanzi":"要面子","pinyin":"yàomiànzi","vi":"giữ thể diện"},{"hanzi":"虚荣","pinyin":"xūróng","vi":"hư vinh"}],"traditional":"愛面子"},{"id":"碍事","hanzi":"碍事","pinyin":"àishì","meaning_vi":"vướng víu, cản trở; (phủ định) không sao, không hề gì","explanation":"碍 (ngại – cản trở) + 事 (sự – việc) → làm vướng việc; dạng phủ định 不碍事 nghĩa là \"không sao, không hề gì\".","hsk_level":"7-9","tags":["tinh-tu","sinh-hoat"],"image":"🚧","examples":[{"type":"basic","zh":"这把椅子真碍事。","pinyin":"Zhè bǎ yǐzi zhēn àishì.","vi":"Cái ghế này vướng quá."},{"type":"simple","zh":"箱子放在走廊里有点儿碍事。","pinyin":"Xiāngzi fàng zài zǒuláng lǐ yǒudiǎnr àishì.","vi":"Để vali ở hành lang hơi vướng."},{"type":"compound","zh":"虽然他的腿上擦破了一点儿皮，但是不碍事。","pinyin":"Suīrán tā de tuǐ shang cā pòle yìdiǎnr pí, dànshì bú àishì.","vi":"Tuy chân anh ấy bị trầy chút da nhưng không sao cả."}],"related":[{"hanzi":"妨碍","pinyin":"fáng'ài","vi":"cản trở"},{"hanzi":"障碍","pinyin":"zhàng'ài","vi":"chướng ngại"},{"hanzi":"不要紧","pinyin":"búyàojǐn","vi":"không sao"},{"hanzi":"碍手碍脚","pinyin":"àishǒu'àijiǎo","vi":"vướng tay vướng chân"}],"traditional":"礙事"},{"id":"安定","hanzi":"安定","pinyin":"āndìng","meaning_vi":"ổn định, yên ổn; làm cho ổn định","explanation":"安 (an – yên) + 定 (định – ổn định) → yên ổn, ổn định; cũng dùng như động từ \"làm ổn định (lòng người, xã hội)\".","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"社会很安定。","pinyin":"Shèhuì hěn āndìng.","vi":"Xã hội rất ổn định."},{"type":"simple","zh":"他终于过上了安定的生活。","pinyin":"Tā zhōngyúguò shangle āndìng de shēnghuó.","vi":"Anh ấy cuối cùng đã có cuộc sống ổn định."},{"type":"compound","zh":"只有社会安定了，经济才能持续健康地发展。","pinyin":"Zhǐyǒu shèhuì āndìng le, jīngjì cáinéng chíxù jiànkāng de fāzhǎn.","vi":"Chỉ khi xã hội ổn định thì kinh tế mới phát triển bền vững, lành mạnh được."}],"related":[{"hanzi":"稳定","pinyin":"wěndìng","vi":"ổn định"},{"hanzi":"安宁","pinyin":"ānníng","vi":"yên bình"},{"hanzi":"动荡","pinyin":"dòngdàng","vi":"biến động"},{"hanzi":"安稳","pinyin":"ānwěn","vi":"yên ổn"}]},{"id":"安眠药","hanzi":"安眠药","pinyin":"ānmiányào","meaning_vi":"thuốc ngủ","explanation":"安 (an – yên) + 眠 (miên – ngủ) + 药 (dược – thuốc) → thuốc giúp ngủ yên.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"她每晚吃安眠药。","pinyin":"Tā měi wǎn chī ānmiányào.","vi":"Cô ấy tối nào cũng uống thuốc ngủ."},{"type":"simple","zh":"医生不建议长期服用安眠药。","pinyin":"Yīshēng bú jiànyì chángqī fúyòng ānmiányào.","vi":"Bác sĩ không khuyên dùng thuốc ngủ lâu dài."},{"type":"compound","zh":"即使失眠很严重，你也不能随便吃安眠药。","pinyin":"Jíshǐ shīmián hěn yánzhòng, nǐ yě bù néng suíbiàn chī ānmiányào.","vi":"Dù mất ngủ nặng đến đâu, bạn cũng không được tùy tiện uống thuốc ngủ."}],"related":[{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"睡眠","pinyin":"shuìmián","vi":"giấc ngủ"},{"hanzi":"药片","pinyin":"yàopiàn","vi":"viên thuốc"},{"hanzi":"镇静剂","pinyin":"zhènjìngjì","vi":"thuốc an thần"}],"traditional":"安眠藥"},{"id":"安心","hanzi":"安心","pinyin":"ānxīn","meaning_vi":"yên tâm, an tâm; chuyên tâm","explanation":"安 (an – yên) + 心 (tâm – lòng) → lòng yên ổn, yên tâm; cũng có nghĩa chuyên tâm làm việc gì.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"你安心养病吧。","pinyin":"Nǐ ānxīn yǎngbìng ba.","vi":"Bạn cứ yên tâm dưỡng bệnh đi."},{"type":"simple","zh":"孩子到家后妈妈才安心睡觉。","pinyin":"Háizi dàojiā hòu māma cái ānxīn shuìjiào.","vi":"Con về đến nhà rồi mẹ mới yên tâm đi ngủ."},{"type":"compound","zh":"只要你按时打电话回家，父母就会很安心。","pinyin":"Zhǐyào nǐ ànshí dǎdiànhuà huíjiā, fùmǔ jiù huì hěn ānxīn.","vi":"Chỉ cần bạn gọi điện về nhà đúng giờ thì bố mẹ sẽ rất yên tâm."}],"related":[{"hanzi":"放心","pinyin":"fàngxīn","vi":"yên tâm"},{"hanzi":"安稳","pinyin":"ānwěn","vi":"yên ổn"},{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"}]},{"id":"按键","hanzi":"按键","pinyin":"ànjiàn","meaning_vi":"phím bấm, nút bấm; bấm phím","explanation":"按 (án – ấn) + 键 (kiện – phím) → phím, nút để bấm trên thiết bị; cũng chỉ hành động bấm phím.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"⌨️","examples":[{"type":"basic","zh":"这个按键坏了。","pinyin":"Zhè ge ànjiàn huàile.","vi":"Phím này hỏng rồi."},{"type":"simple","zh":"手机侧面有一个音量按键。","pinyin":"Shǒujī cèmiàn yǒu yí ge yīnliàng ànjiàn.","vi":"Bên cạnh điện thoại có một nút âm lượng."},{"type":"compound","zh":"如果遥控器的按键没反应，就换一下电池。","pinyin":"Rúguǒ yáokòngqì de ànjiàn méi fǎnyìng, jiù huàn yíxià diànchí.","vi":"Nếu nút trên điều khiển không phản ứng thì thay pin đi."}],"related":[{"hanzi":"键盘","pinyin":"jiànpán","vi":"bàn phím"},{"hanzi":"按钮","pinyin":"ànniǔ","vi":"nút bấm"},{"hanzi":"开关","pinyin":"kāiguān","vi":"công tắc"},{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"}],"traditional":"按鍵"},{"id":"按理说","hanzi":"按理说","pinyin":"ànlǐshuō","meaning_vi":"theo lý mà nói, lẽ ra","explanation":"按 (án – theo) + 理 (lý – lẽ) + 说 (thuyết – nói) → theo lẽ thường mà nói; thường đi kèm ý thực tế lại khác.","hsk_level":"7-9","tags":["pho-tu","giao-tiep"],"image":"🤔","examples":[{"type":"basic","zh":"按理说他该到了。","pinyin":"Ànlǐshuō tā gāi dào le.","vi":"Theo lý thì anh ấy đáng lẽ đã tới rồi."},{"type":"simple","zh":"按理说这个价格已经很便宜了。","pinyin":"Ànlǐshuō zhè ge jiàgé yǐjīng hěn piányi le.","vi":"Theo lý mà nói giá này đã rất rẻ rồi."},{"type":"compound","zh":"按理说他应该很高兴，可是他却一句话也不说。","pinyin":"Ànlǐshuō tā yīnggāi hěn gāoxìng, kěshì tā què yíjùhuà yě bù shuō.","vi":"Lẽ ra anh ấy phải rất vui, nhưng anh ấy lại chẳng nói câu nào."}],"related":[{"hanzi":"按说","pinyin":"ànshuō","vi":"lẽ ra"},{"hanzi":"照理","pinyin":"zhàolǐ","vi":"theo lẽ"},{"hanzi":"一般来说","pinyin":"yìbānláishuō","vi":"nói chung"},{"hanzi":"道理","pinyin":"dàolǐ","vi":"đạo lý"}],"traditional":"按理說"},{"id":"按说","hanzi":"按说","pinyin":"ànshuō","meaning_vi":"lẽ ra, theo lẽ thường","explanation":"按 (án – theo) + 说 (thuyết – nói) → theo lẽ thường mà nói, lẽ ra; giống 按理说 nhưng ngắn gọn hơn.","hsk_level":"7-9","tags":["pho-tu"],"image":"🧐","examples":[{"type":"basic","zh":"按说他不会忘。","pinyin":"Ànshuō tā bú huì wàng.","vi":"Lẽ ra anh ấy không quên đâu."},{"type":"simple","zh":"按说这时候飞机早该起飞了。","pinyin":"Ànshuō zhè shíhou fēijī zǎo gāi qǐfēi le.","vi":"Theo lẽ thường giờ này máy bay đã cất cánh từ lâu rồi."},{"type":"compound","zh":"按说春天已经到了，但是天气还是这么冷。","pinyin":"Ànshuō chūntiān yǐjīng dào le, dànshì tiānqì háishi zhème lěng.","vi":"Lẽ ra mùa xuân đã đến rồi, thế mà trời vẫn lạnh như vậy."}],"related":[{"hanzi":"按理说","pinyin":"ànlǐshuō","vi":"theo lý mà nói"},{"hanzi":"本来","pinyin":"běnlái","vi":"vốn dĩ"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"nên"},{"hanzi":"照说","pinyin":"zhàoshuō","vi":"lẽ ra"}],"traditional":"按說"},{"id":"凹","hanzi":"凹","pinyin":"āo","meaning_vi":"lõm, trũng","explanation":"凹 (ao – lõm) → chữ tượng hình, phần giữa trũng xuống; trái nghĩa với 凸 (đột – lồi).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥄","examples":[{"type":"basic","zh":"地面凹下去一块。","pinyin":"Dìmiàn āo xiàqu yíkuài.","vi":"Mặt đất lõm xuống một chỗ."},{"type":"simple","zh":"我的车门被撞得凹了进去。","pinyin":"Wǒ de chēmén bèi zhuàng de āole jìnqu.","vi":"Cửa xe của tôi bị đâm lõm vào."},{"type":"compound","zh":"因为瓶子被踩了一脚，所以中间凹了下去。","pinyin":"Yīnwèi píngzi bèi cǎile yì jiǎo, suǒyǐ zhōngjiān āole xiàqu.","vi":"Vì cái chai bị giẫm một cái nên giữa thân bị lõm xuống."}],"related":[{"hanzi":"凸","pinyin":"tū","vi":"lồi"},{"hanzi":"凹凸","pinyin":"āotū","vi":"lồi lõm"},{"hanzi":"凹陷","pinyin":"āoxiàn","vi":"lõm xuống"},{"hanzi":"坑","pinyin":"kēng","vi":"hố"}]},{"id":"傲","hanzi":"傲","pinyin":"ào","meaning_vi":"kiêu ngạo, ngạo mạn; kiêu hãnh, bất khuất","explanation":"傲 (ngạo – kiêu ngạo) → tự cao coi thường người khác; cũng chỉ khí phách không chịu khuất phục (傲骨).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😏","examples":[{"type":"basic","zh":"他为人太傲了。","pinyin":"Tā wéirén tài ào le.","vi":"Tính anh ta quá kiêu ngạo."},{"type":"simple","zh":"梅花在寒风中傲然开放。","pinyin":"Méihuā zài hánfēng zhōng àorán kāifàng.","vi":"Hoa mai kiêu hãnh nở trong gió lạnh."},{"type":"compound","zh":"虽然他有才华，但是太傲，所以朋友不多。","pinyin":"Suīrán tā yǒu cáihuá, dànshì tài ào, suǒyǐ péngyou bù duō.","vi":"Tuy anh ấy có tài nhưng quá kiêu ngạo nên không có nhiều bạn."}],"related":[{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"kiêu ngạo"},{"hanzi":"傲慢","pinyin":"àomàn","vi":"ngạo mạn"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"傲气","pinyin":"àoqì","vi":"thói kiêu căng"}]},{"id":"八卦","hanzi":"八卦","pinyin":"bāguà","meaning_vi":"bát quái; chuyện phiếm, buôn chuyện, tin đồn","explanation":"八 (bát – tám) + 卦 (quái – quẻ) → tám quẻ trong Kinh Dịch; nghĩa hiện đại: chuyện phiếm, tin lá cải, thích buôn chuyện.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"☯️","examples":[{"type":"basic","zh":"她最爱聊八卦。","pinyin":"Tā zuì ài liáo bāguà.","vi":"Cô ấy thích buôn chuyện nhất."},{"type":"simple","zh":"这本杂志专门报道明星的八卦新闻。","pinyin":"Zhè běn zázhì zhuānmén bàodào míngxīng de bāguà xīnwén.","vi":"Tạp chí này chuyên đưa tin lá cải về ngôi sao."},{"type":"compound","zh":"如果你总是传别人的八卦，大家就不会信任你。","pinyin":"Rúguǒ nǐ zǒngshì chuán biérén de bāguà, dàjiā jiù bú huì xìnrèn nǐ.","vi":"Nếu bạn cứ đi đồn chuyện người khác thì mọi người sẽ không tin bạn."}],"related":[{"hanzi":"闲话","pinyin":"xiánhuà","vi":"chuyện phiếm"},{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn"},{"hanzi":"绯闻","pinyin":"fēiwén","vi":"scandal tình ái"},{"hanzi":"易经","pinyin":"Yìjīng","vi":"Kinh Dịch"}]},{"id":"芭蕾","hanzi":"芭蕾","pinyin":"bālěi","meaning_vi":"múa ba lê","explanation":"芭蕾 (ba lôi – phiên âm \"ballet\") → múa ba lê; thường nói đầy đủ là 芭蕾舞.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🩰","examples":[{"type":"basic","zh":"她从小学芭蕾。","pinyin":"Tā cóng xiǎoxué bālěi.","vi":"Cô ấy học ba lê từ nhỏ."},{"type":"simple","zh":"我们周末去剧院看了一场芭蕾舞。","pinyin":"Wǒmen zhōumò qù jùyuàn kànle yì chǎng bālěiwǔ.","vi":"Cuối tuần chúng tôi đến nhà hát xem một buổi múa ba lê."},{"type":"compound","zh":"虽然练芭蕾很辛苦，但是她从来没想过放弃。","pinyin":"Suīrán liàn bālěi hěn xīnkǔ, dànshì tā cónglái méi xiǎngguo fàngqì.","vi":"Tuy tập ba lê rất vất vả nhưng cô ấy chưa từng nghĩ sẽ bỏ cuộc."}],"related":[{"hanzi":"芭蕾舞","pinyin":"bālěiwǔ","vi":"múa ba lê"},{"hanzi":"舞蹈","pinyin":"wǔdǎo","vi":"múa"},{"hanzi":"舞者","pinyin":"wǔzhě","vi":"vũ công"},{"hanzi":"天鹅湖","pinyin":"Tiān'éhú","vi":"Hồ Thiên Nga"}]},{"id":"靶子","hanzi":"靶子","pinyin":"bǎzi","meaning_vi":"bia (bắn), mục tiêu","explanation":"靶 (bá – bia bắn) + 子 (tử – hậu tố) → tấm bia để tập bắn; nghĩa bóng: đối tượng bị công kích, chỉ trích.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🎯","examples":[{"type":"basic","zh":"他打中了靶子。","pinyin":"Tā dǎzhòngle bǎzi.","vi":"Anh ấy bắn trúng bia."},{"type":"simple","zh":"他成了大家批评的靶子。","pinyin":"Tā chéngle dàjiā pīpíng de bǎzi.","vi":"Anh ấy trở thành mục tiêu chỉ trích của mọi người."},{"type":"compound","zh":"只要你瞄准靶子中心，就一定能打出好成绩。","pinyin":"Zhǐyào nǐ miáozhǔn bǎzi zhōngxīn, jiù yídìng néng dǎ chū hǎo chéngjì.","vi":"Chỉ cần bạn ngắm vào tâm bia thì nhất định sẽ bắn được thành tích tốt."}],"related":[{"hanzi":"射击","pinyin":"shèjī","vi":"bắn súng"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"靶心","pinyin":"bǎxīn","vi":"hồng tâm"},{"hanzi":"瞄准","pinyin":"miáozhǔn","vi":"ngắm"}]},{"id":"坝","hanzi":"坝","pinyin":"bà","meaning_vi":"đập (nước), đê","explanation":"坝 (bá – đập) → công trình chắn nước như đập, đê; thường gặp trong 大坝, 水坝.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"河上修了一座坝。","pinyin":"Hé shang xiūle yí zuò bà.","vi":"Trên sông xây một con đập."},{"type":"simple","zh":"这座大坝每年能发很多电。","pinyin":"Zhè zuò dàbà měinián néng fā hěn duō diàn.","vi":"Con đập lớn này mỗi năm phát được rất nhiều điện."},{"type":"compound","zh":"一旦这座坝出现裂缝，下游的村庄就会有危险。","pinyin":"Yídàn zhè zuò bà chūxiàn lièfèng, xiàyóu de cūnzhuāng jiù huì yǒu wēixiǎn.","vi":"Một khi con đập này xuất hiện vết nứt thì các làng ở hạ lưu sẽ gặp nguy hiểm."}],"related":[{"hanzi":"大坝","pinyin":"dàbà","vi":"đập lớn"},{"hanzi":"水坝","pinyin":"shuǐbà","vi":"đập nước"},{"hanzi":"堤","pinyin":"dī","vi":"đê"},{"hanzi":"水库","pinyin":"shuǐkù","vi":"hồ chứa nước"}],"traditional":"壩"},{"id":"百分比","hanzi":"百分比","pinyin":"bǎifēnbǐ","meaning_vi":"tỷ lệ phần trăm","explanation":"百 (bách – trăm) + 分 (phân – phần) + 比 (tỷ – tỷ lệ) → tỷ lệ tính trên một trăm phần.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"这个百分比很高。","pinyin":"Zhè ge bǎifēnbǐ hěn gāo.","vi":"Tỷ lệ phần trăm này rất cao."},{"type":"simple","zh":"请用百分比表示每个班的及格率。","pinyin":"Qǐng yòng bǎifēnbǐ biǎoshì měi ge bān de jígé lǜ.","vi":"Hãy biểu thị tỷ lệ đạt của mỗi lớp bằng phần trăm."},{"type":"compound","zh":"虽然人数增加了，但是女生所占的百分比反而下降了。","pinyin":"Suīrán rénshù zēngjiā le, dànshì nǚshēng suǒ zhàn de bǎifēnbǐ fǎn'ér xiàjiàng le.","vi":"Tuy số người tăng lên nhưng tỷ lệ phần trăm nữ sinh lại giảm."}],"related":[{"hanzi":"比例","pinyin":"bǐlì","vi":"tỷ lệ"},{"hanzi":"百分之","pinyin":"bǎifēnzhī","vi":"phần trăm"},{"hanzi":"比率","pinyin":"bǐlǜ","vi":"tỷ suất"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"}]},{"id":"百合","hanzi":"百合","pinyin":"bǎihé","meaning_vi":"hoa bách hợp, hoa loa kèn","explanation":"百 (bách – trăm) + 合 (hợp – hợp lại) → cây bách hợp, củ gồm nhiều vảy hợp lại; hoa tượng trưng cho \"trăm năm hòa hợp\".","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"💐","examples":[{"type":"basic","zh":"她喜欢白色的百合。","pinyin":"Tā xǐhuan báisè de bǎihé.","vi":"Cô ấy thích hoa bách hợp trắng."},{"type":"simple","zh":"婚礼上摆满了新鲜的百合花。","pinyin":"Hūnlǐ shang bǎimǎnle xīnxiān de bǎihéhuā.","vi":"Đám cưới bày đầy hoa bách hợp tươi."},{"type":"compound","zh":"因为百合象征百年好合，所以人们常把它送给新人。","pinyin":"Yīnwèi bǎihé xiàngzhēng bǎinián hǎo hé, suǒyǐ rénmen cháng bǎ tā sònggěi xīnrén.","vi":"Vì hoa bách hợp tượng trưng cho trăm năm hạnh phúc nên người ta thường tặng nó cho cô dâu chú rể."}],"related":[{"hanzi":"玫瑰","pinyin":"méigui","vi":"hoa hồng"},{"hanzi":"鲜花","pinyin":"xiānhuā","vi":"hoa tươi"},{"hanzi":"百年好合","pinyin":"bǎiniánhǎohé","vi":"trăm năm hạnh phúc"},{"hanzi":"花束","pinyin":"huāshù","vi":"bó hoa"}]},{"id":"百科全书","hanzi":"百科全书","pinyin":"bǎikēquánshū","meaning_vi":"bách khoa toàn thư","explanation":"百 (bách – trăm) + 科 (khoa – ngành) + 全 (toàn – đầy đủ) + 书 (thư – sách) → bộ sách tổng hợp kiến thức mọi ngành; nghĩa bóng chỉ người hiểu biết rộng.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他是个活百科全书。","pinyin":"Tā shì ge huó bǎikēquánshū.","vi":"Anh ấy là một cuốn bách khoa toàn thư sống."},{"type":"simple","zh":"我在图书馆查了一下百科全书。","pinyin":"Wǒ zài túshūguǎn chále yíxià bǎikēquánshū.","vi":"Tôi đã tra bách khoa toàn thư ở thư viện."},{"type":"compound","zh":"虽然网上资料很多，但是百科全书的内容更可靠。","pinyin":"Suīrán wǎngshàng zīliào hěn duō, dànshì bǎikēquánshū de nèiróng gèng kěkào.","vi":"Tuy trên mạng có nhiều tài liệu nhưng nội dung bách khoa toàn thư đáng tin cậy hơn."}],"related":[{"hanzi":"词典","pinyin":"cídiǎn","vi":"từ điển"},{"hanzi":"百科","pinyin":"bǎikē","vi":"bách khoa"},{"hanzi":"工具书","pinyin":"gōngjùshū","vi":"sách tra cứu"},{"hanzi":"知识","pinyin":"zhīshi","vi":"kiến thức"}],"traditional":"百科全書"},{"id":"摆放","hanzi":"摆放","pinyin":"bǎifàng","meaning_vi":"bày, sắp xếp, đặt (đồ vật)","explanation":"摆 (bãi – bày) + 放 (phóng – đặt) → bày đặt đồ vật vào vị trí nhất định.","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🪑","examples":[{"type":"basic","zh":"桌上摆放着鲜花。","pinyin":"Zhuō shang bǎifàngzhe xiānhuā.","vi":"Trên bàn bày hoa tươi."},{"type":"simple","zh":"书架上的书摆放得非常整齐。","pinyin":"Shūjià shang de shū bǎifàng de fēicháng zhěngqí.","vi":"Sách trên giá được xếp rất ngay ngắn."},{"type":"compound","zh":"如果家具摆放得合理，房间就会显得更宽敞。","pinyin":"Rúguǒ jiājù bǎifàng de hélǐ, fángjiān jiù huì xiǎnde gèng kuānchang.","vi":"Nếu đồ nội thất được bố trí hợp lý thì căn phòng sẽ trông rộng rãi hơn."}],"related":[{"hanzi":"摆设","pinyin":"bǎishè","vi":"bày biện"},{"hanzi":"放置","pinyin":"fàngzhì","vi":"đặt để"},{"hanzi":"布置","pinyin":"bùzhì","vi":"bố trí"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"sắp xếp"}],"traditional":"擺放"},{"id":"摆平","hanzi":"摆平","pinyin":"bǎipíng","meaning_vi":"dàn xếp, giải quyết ổn thỏa; đối xử công bằng","explanation":"摆 (bãi – đặt) + 平 (bình – phẳng) → đặt cho cân bằng; nghĩa thường dùng trong khẩu ngữ: dàn xếp, giải quyết xong việc.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"这件事我来摆平。","pinyin":"Zhè jiàn shì wǒ lái bǎipíng.","vi":"Việc này để tôi dàn xếp."},{"type":"simple","zh":"他花了一个星期才把这场纠纷摆平。","pinyin":"Tā huāle yí ge xīngqī cái bǎ zhè chǎng jiūfēn bǎipíng.","vi":"Anh ấy mất cả tuần mới dàn xếp xong vụ tranh chấp này."},{"type":"compound","zh":"只要经理出面，这个麻烦就能很快摆平。","pinyin":"Zhǐyào jīnglǐ chūmiàn, zhè ge máfan jiù néng hěn kuài bǎipíng.","vi":"Chỉ cần giám đốc ra mặt thì rắc rối này sẽ nhanh chóng được giải quyết."}],"related":[{"hanzi":"解决","pinyin":"jiějué","vi":"giải quyết"},{"hanzi":"处理","pinyin":"chǔlǐ","vi":"xử lý"},{"hanzi":"调解","pinyin":"tiáojiě","vi":"hòa giải"},{"hanzi":"搞定","pinyin":"gǎodìng","vi":"xử lý xong"}],"traditional":"擺平"},{"id":"摆设","hanzi":"摆设","pinyin":"bǎishè","meaning_vi":"bày biện, trang trí; đồ bày biện, vật để làm cảnh","explanation":"摆 (bãi – bày) + 设 (thiết – sắp đặt) → bày biện đồ đạc trong phòng; danh từ (thường đọc bǎi she) chỉ đồ trang trí, nghĩa bóng là thứ \"chỉ để làm cảnh\".","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏺","examples":[{"type":"basic","zh":"客厅摆设很简单。","pinyin":"Kètīng bǎishè hěn jiǎndān.","vi":"Phòng khách bày biện rất đơn giản."},{"type":"simple","zh":"这台跑步机在家里成了摆设。","pinyin":"Zhè tái pǎobùjī zài jiālǐ chéngle bǎishè.","vi":"Cái máy chạy bộ này ở nhà đã thành đồ để làm cảnh."},{"type":"compound","zh":"虽然房间不大，但是摆设得很有品位。","pinyin":"Suīrán fángjiān búdà, dànshì bǎishè de hěn yǒu pǐnwèi.","vi":"Tuy phòng không lớn nhưng được bày biện rất có gu."}],"related":[{"hanzi":"摆放","pinyin":"bǎifàng","vi":"bày đặt"},{"hanzi":"装饰","pinyin":"zhuāngshì","vi":"trang trí"},{"hanzi":"陈设","pinyin":"chénshè","vi":"bày biện"},{"hanzi":"家具","pinyin":"jiājù","vi":"đồ nội thất"}],"traditional":"擺設"},{"id":"拜会","hanzi":"拜会","pinyin":"bàihuì","meaning_vi":"thăm viếng, hội kiến (trang trọng, ngoại giao)","explanation":"拜 (bái – bái kiến) + 会 (hội – gặp) → đến gặp chính thức, thường dùng trong ngoại giao.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"大使拜会了总理。","pinyin":"Dàshǐ bàihuìle zǒnglǐ.","vi":"Đại sứ đã hội kiến thủ tướng."},{"type":"simple","zh":"代表团明天将拜会当地政府官员。","pinyin":"Dàibiǎotuán míngtiān jiāng bàihuì dāngdì zhèngfǔ guānyuán.","vi":"Ngày mai đoàn đại biểu sẽ đến thăm các quan chức chính quyền địa phương."},{"type":"compound","zh":"因为时间紧张，所以外长只拜会了两位领导人。","pinyin":"Yīnwèi shíjiān jǐnzhāng, suǒyǐ wàizhǎng zhǐ bàihuìle liǎng wèi lǐngdǎorén.","vi":"Vì thời gian eo hẹp nên ngoại trưởng chỉ hội kiến hai nhà lãnh đạo."}],"related":[{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm hỏi"},{"hanzi":"会见","pinyin":"huìjiàn","vi":"hội kiến"},{"hanzi":"拜见","pinyin":"bàijiàn","vi":"bái kiến"},{"hanzi":"访问","pinyin":"fǎngwèn","vi":"chuyến thăm"}],"traditional":"拜會"},{"id":"拜见","hanzi":"拜见","pinyin":"bàijiàn","meaning_vi":"bái kiến, đến chào (bề trên)","explanation":"拜 (bái – vái chào) + 见 (kiến – gặp) → đến gặp và chào hỏi người bề trên, người lớn tuổi một cách cung kính.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我去拜见老师。","pinyin":"Wǒqù bàijiàn lǎoshī.","vi":"Tôi đi chào thầy."},{"type":"simple","zh":"新女婿第一次上门拜见岳父母。","pinyin":"Xīn nǚxu dìyīcì shàngmén bàijiàn yuè fùmǔ.","vi":"Con rể mới lần đầu đến nhà chào bố mẹ vợ."},{"type":"compound","zh":"既然到了北京，你就应该去拜见一下你的老师。","pinyin":"Jìrán dàole Běijīng, nǐ jiù yīnggāi qù bàijiàn yíxià nǐ de lǎoshī.","vi":"Đã đến Bắc Kinh rồi thì bạn nên đến chào thầy mình một chút."}],"related":[{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm hỏi"},{"hanzi":"拜会","pinyin":"bàihuì","vi":"hội kiến"},{"hanzi":"看望","pinyin":"kànwàng","vi":"thăm nom"},{"hanzi":"长辈","pinyin":"zhǎngbèi","vi":"bậc trên"}],"traditional":"拜見"},{"id":"扳","hanzi":"扳","pinyin":"bān","meaning_vi":"vặn, bẻ, kéo; gỡ lại (tỷ số, tình thế)","explanation":"扳 (ban – vặn, kéo) → dùng tay kéo hoặc vặn vật cố định; nghĩa bóng: gỡ lại, lật ngược tình thế (扳回).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔧","examples":[{"type":"basic","zh":"他扳动了开关。","pinyin":"Tā bāndòngle kāiguān.","vi":"Anh ấy gạt công tắc."},{"type":"simple","zh":"下半场主队扳回了一个球。","pinyin":"Xiàbànchǎng zhǔduì bānhuíle yí ge qiú.","vi":"Hiệp hai đội chủ nhà gỡ lại một bàn."},{"type":"compound","zh":"虽然他用力扳了半天，但是螺丝还是一动不动。","pinyin":"Suīrán tā yònglì bānle bàn tiān, dànshì luósī háishi yídòngbudòng.","vi":"Tuy anh ấy dùng sức vặn mãi nhưng con ốc vẫn không nhúc nhích."}],"related":[{"hanzi":"扳手","pinyin":"bānshou","vi":"cờ lê"},{"hanzi":"扳回","pinyin":"bānhuí","vi":"gỡ lại"},{"hanzi":"拧","pinyin":"nǐng","vi":"vặn"},{"hanzi":"掰","pinyin":"bāi","vi":"bẻ"}]},{"id":"颁奖","hanzi":"颁奖","pinyin":"bānjiǎng","meaning_vi":"trao giải, trao thưởng","explanation":"颁 (ban – ban phát) + 奖 (thưởng – giải thưởng) → trao giải thưởng.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏆","examples":[{"type":"basic","zh":"校长为我们颁奖。","pinyin":"Xiàozhǎng wèi wǒmen bānjiǎng.","vi":"Hiệu trưởng trao giải cho chúng tôi."},{"type":"simple","zh":"颁奖典礼将在今晚八点举行。","pinyin":"Bānjiǎngdiǎnlǐ jiāng zài jīnwǎn bā diǎn jǔxíng.","vi":"Lễ trao giải sẽ diễn ra lúc tám giờ tối nay."},{"type":"compound","zh":"主持人一宣布开始颁奖，全场就安静了下来。","pinyin":"Zhǔchírén yì xuānbù kāishǐ bānjiǎng, quánchǎng jiù ānjìngle xiàlai.","vi":"Người dẫn chương trình vừa tuyên bố bắt đầu trao giải, cả hội trường liền im lặng."}],"related":[{"hanzi":"获奖","pinyin":"huòjiǎng","vi":"đoạt giải"},{"hanzi":"奖杯","pinyin":"jiǎngbēi","vi":"cúp"},{"hanzi":"颁发","pinyin":"bānfā","vi":"trao tặng"},{"hanzi":"典礼","pinyin":"diǎnlǐ","vi":"lễ"}],"traditional":"頒獎"},{"id":"斑点","hanzi":"斑点","pinyin":"bāndiǎn","meaning_vi":"đốm, vết lốm đốm","explanation":"斑 (ban – vằn, vết loang) + 点 (điểm – chấm) → các chấm, đốm khác màu trên bề mặt.","hsk_level":"7-9","tags":["danh-tu"],"image":"🐞","examples":[{"type":"basic","zh":"苹果上有斑点。","pinyin":"Píngguǒ shang yǒu bāndiǎn.","vi":"Trên quả táo có đốm."},{"type":"simple","zh":"这只小狗身上长着黑色的斑点。","pinyin":"Zhè zhī xiǎogǒu shēnshang zhǎngzhe hēisè de bāndiǎn.","vi":"Con chó con này có đốm đen trên người."},{"type":"compound","zh":"如果脸上突然出现很多斑点，你最好去看看医生。","pinyin":"Rúguǒ liǎn shang tūrán chūxiàn hěn duō bāndiǎn, nǐ zuìhǎo qù kànkan yīshēng.","vi":"Nếu trên mặt bỗng xuất hiện nhiều đốm, bạn nên đi khám bác sĩ."}],"related":[{"hanzi":"雀斑","pinyin":"quèbān","vi":"tàn nhang"},{"hanzi":"污点","pinyin":"wūdiǎn","vi":"vết bẩn"},{"hanzi":"斑马","pinyin":"bānmǎ","vi":"ngựa vằn"},{"hanzi":"斑纹","pinyin":"bānwén","vi":"vằn"}],"traditional":"斑點"},{"id":"办不到","hanzi":"办不到","pinyin":"bànbudào","meaning_vi":"không làm được, không thể làm nổi","explanation":"办 (biện – làm) + 不 (bất – không) + 到 (đáo – đạt tới) → bổ ngữ khả năng dạng phủ định: không làm nổi.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🙅","examples":[{"type":"basic","zh":"这件事我办不到。","pinyin":"Zhè jiàn shì wǒ bànbudào.","vi":"Việc này tôi không làm được."},{"type":"simple","zh":"一天之内完成这么多工作根本办不到。","pinyin":"Yì tiān zhīnèi wánchéng zhème duō gōngzuò gēnběn bànbudào.","vi":"Hoàn thành chừng ấy việc trong một ngày là hoàn toàn không thể."},{"type":"compound","zh":"即使你给我再多的钱，这种违法的事我也办不到。","pinyin":"Jíshǐ nǐ gěi wǒ zài duō de qián, zhè zhǒng wéifǎ de shì wǒ yě bànbudào.","vi":"Dù anh cho tôi bao nhiêu tiền, việc phạm pháp kiểu này tôi cũng không làm."}],"related":[{"hanzi":"办得到","pinyin":"bàndedào","vi":"làm được"},{"hanzi":"做不到","pinyin":"zuòbudào","vi":"không làm được"},{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"办事","pinyin":"bànshì","vi":"làm việc"}],"traditional":"辦不到"},{"id":"半边天","hanzi":"半边天","pinyin":"bànbiāntiān","meaning_vi":"nửa bầu trời (chỉ phụ nữ)","explanation":"半 (bán – nửa) + 边 (biên – bên) + 天 (thiên – trời) → nửa bầu trời; ví phụ nữ gánh vác một nửa xã hội (từ câu \"妇女能顶半边天\").","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👩","examples":[{"type":"basic","zh":"妇女能顶半边天。","pinyin":"Fùnǚ néng dǐng bànbiāntiān.","vi":"Phụ nữ có thể gánh vác nửa bầu trời."},{"type":"simple","zh":"女性在科技领域也撑起了半边天。","pinyin":"Nǚxìng zài kējì lǐngyù yě chēng qǐle bànbiāntiān.","vi":"Phụ nữ cũng gánh vác nửa bầu trời trong lĩnh vực công nghệ."},{"type":"compound","zh":"虽然过去女性地位很低，但是现在她们已经是社会的半边天。","pinyin":"Suīrán guòqù nǚxìng dìwèi hěn dī, dànshì xiànzài tāmen yǐjīng shì shèhuì de bànbiāntiān.","vi":"Tuy trước đây địa vị phụ nữ rất thấp nhưng nay họ đã là nửa bầu trời của xã hội."}],"related":[{"hanzi":"妇女","pinyin":"fùnǚ","vi":"phụ nữ"},{"hanzi":"女性","pinyin":"nǚxìng","vi":"nữ giới"},{"hanzi":"男女平等","pinyin":"nánnǚpíngděng","vi":"nam nữ bình đẳng"},{"hanzi":"半边","pinyin":"bànbiān","vi":"một nửa"}],"traditional":"半邊天"},{"id":"半场","hanzi":"半场","pinyin":"bànchǎng","meaning_vi":"hiệp (nửa trận đấu), nửa sân","explanation":"半 (bán – nửa) + 场 (trường – trận, sân) → nửa trận đấu hoặc nửa sân thi đấu.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"⚽","examples":[{"type":"basic","zh":"上半场结束了。","pinyin":"Shàngbànchǎng jiéshù le.","vi":"Hiệp một kết thúc rồi."},{"type":"simple","zh":"他在下半场打进了一个漂亮的球。","pinyin":"Tā zài xiàbànchǎng dǎjìnle yí ge piàoliang de qiú.","vi":"Anh ấy ghi một bàn đẹp ở hiệp hai."},{"type":"compound","zh":"虽然上半场落后两球，但是他们最后反败为胜。","pinyin":"Suīrán shàngbànchǎng luòhòu liǎng qiú, dànshì tāmen zuìhòu fǎn bài wéi shèng.","vi":"Tuy hiệp một bị dẫn hai bàn nhưng cuối cùng họ đã lội ngược dòng giành chiến thắng."}],"related":[{"hanzi":"上半场","pinyin":"shàngbànchǎng","vi":"hiệp một"},{"hanzi":"下半场","pinyin":"xiàbànchǎng","vi":"hiệp hai"},{"hanzi":"中场","pinyin":"zhōngchǎng","vi":"giữa trận"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"trận đấu"}],"traditional":"半場"},{"id":"半岛","hanzi":"半岛","pinyin":"bàndǎo","meaning_vi":"bán đảo","explanation":"半 (bán – nửa) + 岛 (đảo – hòn đảo) → bán đảo, phần đất ba mặt giáp nước.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏝️","examples":[{"type":"basic","zh":"这是一个半岛。","pinyin":"Zhè shì yígebàn dǎo.","vi":"Đây là một bán đảo."},{"type":"simple","zh":"山东半岛位于中国东部沿海。","pinyin":"Shāndōngbàndǎo wèiyú Zhōngguó Dōngbù yánhǎi.","vi":"Bán đảo Sơn Đông nằm ở vùng ven biển phía đông Trung Quốc."},{"type":"compound","zh":"因为这个半岛三面环海，所以气候非常湿润。","pinyin":"Yīnwèi zhè ge bàndǎo sān miàn huán hǎi, suǒyǐ qìhòu fēicháng shīrùn.","vi":"Vì bán đảo này ba mặt giáp biển nên khí hậu rất ẩm."}],"related":[{"hanzi":"岛屿","pinyin":"dǎoyǔ","vi":"hải đảo"},{"hanzi":"海湾","pinyin":"hǎiwān","vi":"vịnh"},{"hanzi":"大陆","pinyin":"Dàlù","vi":"đại lục"},{"hanzi":"海岸","pinyin":"hǎi'àn","vi":"bờ biển"}],"traditional":"半島"},{"id":"半路","hanzi":"半路","pinyin":"bànlù","meaning_vi":"nửa đường, giữa chừng","explanation":"半 (bán – nửa) + 路 (lộ – đường) → nửa đường; nghĩa bóng: giữa chừng (半路放弃 – bỏ cuộc giữa chừng).","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"车在半路坏了。","pinyin":"Chē zài bànlù huàile.","vi":"Xe hỏng giữa đường."},{"type":"simple","zh":"我在回家的半路上遇见了老同学。","pinyin":"Wǒ zài huíjiā de bànlù shang yùjiànle lǎo tóngxué.","vi":"Trên đường về nhà tôi gặp bạn học cũ."},{"type":"compound","zh":"既然这件事已经开始了，就不要半路放弃。","pinyin":"Jìrán zhè jiàn shì yǐjīng kāishǐ le, jiù bú yào bànlù fàngqì.","vi":"Việc này đã bắt đầu rồi thì đừng bỏ cuộc giữa chừng."}],"related":[{"hanzi":"中途","pinyin":"zhōngtú","vi":"giữa chừng"},{"hanzi":"途中","pinyin":"túzhōng","vi":"trên đường"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"路上","pinyin":"lùshang","vi":"trên đường"}]},{"id":"半数","hanzi":"半数","pinyin":"bànshù","meaning_vi":"một nửa (số lượng)","explanation":"半 (bán – nửa) + 数 (số – con số) → một nửa tổng số.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"🌓","examples":[{"type":"basic","zh":"半数人同意了。","pinyin":"Bànshù rén tóngyì le.","vi":"Một nửa số người đã đồng ý."},{"type":"simple","zh":"超过半数的学生选择了线上课程。","pinyin":"Chāoguò bànshù de xuésheng xuǎnzéle xiànshàng kèchéng.","vi":"Hơn một nửa số học sinh chọn khóa học trực tuyến."},{"type":"compound","zh":"只要有半数以上的人赞成，这个方案就能通过。","pinyin":"Zhǐyào yǒu bànshù yǐshàng de rén zànchéng, zhè ge fāng'àn jiù néng tōngguò.","vi":"Chỉ cần hơn một nửa số người tán thành thì phương án này sẽ được thông qua."}],"related":[{"hanzi":"一半","pinyin":"yíbàn","vi":"một nửa"},{"hanzi":"多数","pinyin":"duōshù","vi":"đa số"},{"hanzi":"少数","pinyin":"shǎoshù","vi":"thiểu số"},{"hanzi":"过半","pinyin":"guòbàn","vi":"quá nửa"}],"traditional":"半數"},{"id":"伴","hanzi":"伴","pinyin":"bàn","meaning_vi":"bạn, người đi cùng; đi kèm, bầu bạn","explanation":"伴 (bạn – bạn bè, người đi cùng) → người cùng đi, cùng làm; động từ: đi kèm, bầu bạn (伴随, 陪伴).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👫","examples":[{"type":"basic","zh":"路上有个伴儿。","pinyin":"Lùshang yǒu ge bànr.","vi":"Trên đường có người đi cùng."},{"type":"simple","zh":"优美的歌声伴着我们进入梦乡。","pinyin":"Yōuměi de gēshēng bànzhe wǒmen jìnrù mèngxiāng.","vi":"Tiếng hát du dương đưa chúng tôi vào giấc ngủ."},{"type":"compound","zh":"如果你一个人去旅行害怕，我就给你作个伴。","pinyin":"Rúguǒ nǐ yígerén qù lǚxíng hàipà, wǒ jiù gěi nǐ zuò ge bàn.","vi":"Nếu bạn sợ đi du lịch một mình thì tôi sẽ đi cùng bạn."}],"related":[{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"bạn đồng hành"},{"hanzi":"陪伴","pinyin":"péibàn","vi":"bầu bạn"},{"hanzi":"伴侣","pinyin":"bànlǚ","vi":"bạn đời"},{"hanzi":"伴随","pinyin":"bànsuí","vi":"đi kèm"}]},{"id":"拌","hanzi":"拌","pinyin":"bàn","meaning_vi":"trộn","explanation":"拌 (bạn – trộn) → trộn đều các thứ với nhau; thường dùng trong nấu ăn (拌面, 凉拌).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🥗","examples":[{"type":"basic","zh":"把面拌一拌。","pinyin":"Bǎ miàn bàn yi bàn.","vi":"Trộn mì lên đi."},{"type":"simple","zh":"妈妈用醋和辣油拌了一盘黄瓜。","pinyin":"Māma yòng cù hé là yóu bànle yì pán huángguā.","vi":"Mẹ dùng giấm và dầu ớt trộn một đĩa dưa chuột."},{"type":"compound","zh":"如果你把沙拉拌得太早，菜叶就会变软。","pinyin":"Rúguǒ nǐ bǎ shālā bàn de tài zǎo, cài yè jiù huì biànruǎn.","vi":"Nếu bạn trộn salad quá sớm thì lá rau sẽ bị nhũn."}],"related":[{"hanzi":"凉拌","pinyin":"liángbàn","vi":"trộn nguội"},{"hanzi":"搅拌","pinyin":"jiǎobàn","vi":"khuấy trộn"},{"hanzi":"拌面","pinyin":"bànmiàn","vi":"mì trộn"},{"hanzi":"混合","pinyin":"hùnhé","vi":"trộn lẫn"}]},{"id":"扮","hanzi":"扮","pinyin":"bàn","meaning_vi":"hóa trang, giả làm, đóng vai; làm (vẻ mặt)","explanation":"扮 (ban – trang điểm, hóa trang) → hóa trang thành, đóng vai ai đó; cũng chỉ làm ra vẻ mặt (扮鬼脸 – làm mặt quỷ).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"他扮成了圣诞老人。","pinyin":"Tā bàn chéngle Shèngdànlǎorén.","vi":"Anh ấy hóa trang thành ông già Noel."},{"type":"simple","zh":"小女孩冲着镜子扮了个鬼脸。","pinyin":"Xiǎo nǚhái chòngzhe jìngzi bànle ge guǐliǎn.","vi":"Cô bé làm mặt quỷ trước gương."},{"type":"compound","zh":"虽然他在戏里扮坏人，但是生活中他非常善良。","pinyin":"Suīrán tā zài xì lǐ bàn huàirén, dànshì shēnghuó zhōng tā fēicháng shànliáng.","vi":"Tuy trong phim anh ấy đóng vai người xấu nhưng ngoài đời anh ấy rất tốt bụng."}],"related":[{"hanzi":"打扮","pinyin":"dǎban","vi":"ăn diện"},{"hanzi":"扮演","pinyin":"bànyǎn","vi":"đóng vai"},{"hanzi":"装扮","pinyin":"zhuāngbàn","vi":"hóa trang"},{"hanzi":"化妆","pinyin":"huàzhuāng","vi":"trang điểm"}]},{"id":"帮手","hanzi":"帮手","pinyin":"bāngshǒu","meaning_vi":"người phụ giúp, trợ thủ","explanation":"帮 (bang – giúp) + 手 (thủ – tay, người làm) → người phụ giúp công việc.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🙌","examples":[{"type":"basic","zh":"他是我的好帮手。","pinyin":"Tā shì wǒ de hǎo bāngshǒu.","vi":"Anh ấy là trợ thủ đắc lực của tôi."},{"type":"simple","zh":"女儿已经成了妈妈做饭的小帮手。","pinyin":"Nǚ'ér yǐjīng chéngle māma zuòfàn de xiǎo bāngshǒu.","vi":"Con gái đã trở thành người phụ bếp nhỏ của mẹ."},{"type":"compound","zh":"要是你一个人搬不动，我就给你找个帮手。","pinyin":"Yàoshi nǐ yígerén bān budòng, wǒ jiù gěi nǐ zhǎo ge bāngshǒu.","vi":"Nếu một mình bạn không bê nổi thì tôi tìm cho bạn một người phụ."}],"related":[{"hanzi":"助手","pinyin":"zhùshǒu","vi":"trợ lý"},{"hanzi":"帮忙","pinyin":"bāngmáng","vi":"giúp đỡ"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"bạn đồng hành"}],"traditional":"幫手"},{"id":"棒球","hanzi":"棒球","pinyin":"bàngqiú","meaning_vi":"bóng chày","explanation":"棒 (bổng – gậy) + 球 (cầu – bóng) → môn bóng chày, dùng gậy đánh bóng.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"⚾","examples":[{"type":"basic","zh":"他爱打棒球。","pinyin":"Tā ài dǎ bàngqiú.","vi":"Anh ấy thích chơi bóng chày."},{"type":"simple","zh":"棒球在日本和美国非常受欢迎。","pinyin":"Bàngqiú zài Rìběn hé Měiguó fēicháng shòuhuānyíng.","vi":"Bóng chày rất được ưa chuộng ở Nhật Bản và Mỹ."},{"type":"compound","zh":"虽然我看不懂棒球规则，但是现场气氛让我很兴奋。","pinyin":"Suīrán wǒ kànbudǒng bàngqiú guīzé, dànshì xiànchǎng qìfēn ràng wǒ hěn xīngfèn.","vi":"Tuy tôi không hiểu luật bóng chày nhưng không khí tại sân khiến tôi rất phấn khích."}],"related":[{"hanzi":"球棒","pinyin":"qiúbàng","vi":"gậy bóng chày"},{"hanzi":"垒球","pinyin":"lěiqiú","vi":"bóng mềm"},{"hanzi":"篮球","pinyin":"lánqiú","vi":"bóng rổ"},{"hanzi":"足球","pinyin":"zúqiú","vi":"bóng đá"}]},{"id":"煲","hanzi":"煲","pinyin":"bāo","meaning_vi":"hầm, nấu nhỏ lửa; nồi","explanation":"煲 (bảo – nồi sâu lòng) → nồi; động từ: hầm, nấu lâu bằng lửa nhỏ (gốc tiếng Quảng Đông, như 煲汤).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"妈妈在煲汤。","pinyin":"Māma zài bāotāng.","vi":"Mẹ đang hầm canh."},{"type":"simple","zh":"这锅鸡汤已经煲了三个小时。","pinyin":"Zhè guō jītāng yǐjīng bāole sān ge xiǎoshí.","vi":"Nồi canh gà này đã hầm ba tiếng rồi."},{"type":"compound","zh":"只要用小火慢慢煲，汤的味道就会特别浓。","pinyin":"Zhǐyào yòng xiǎo huǒ mànmàn bāo, tāng de wèidao jiù huì tèbié nóng.","vi":"Chỉ cần hầm từ từ bằng lửa nhỏ thì vị canh sẽ rất đậm."}],"related":[{"hanzi":"煲汤","pinyin":"bāotāng","vi":"hầm canh"},{"hanzi":"炖","pinyin":"dùn","vi":"hầm"},{"hanzi":"熬","pinyin":"áo","vi":"ninh"},{"hanzi":"电饭煲","pinyin":"diànfànbāo","vi":"nồi cơm điện"}]},{"id":"保暖","hanzi":"保暖","pinyin":"bǎonuǎn","meaning_vi":"giữ ấm","explanation":"保 (bảo – giữ) + 暖 (noãn – ấm) → giữ ấm cơ thể hoặc giữ nhiệt.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🧣","examples":[{"type":"basic","zh":"冬天要注意保暖。","pinyin":"Dōngtiān yào zhùyì bǎonuǎn.","vi":"Mùa đông phải chú ý giữ ấm."},{"type":"simple","zh":"这件羽绒服的保暖效果特别好。","pinyin":"Zhè jiàn yǔróngfú de bǎonuǎn xiàoguǒ tèbié hǎo.","vi":"Áo lông vũ này giữ ấm cực tốt."},{"type":"compound","zh":"如果晚上不注意保暖，第二天就容易感冒。","pinyin":"Rúguǒ wǎnshang bú zhùyì bǎonuǎn, dì'èrtiān jiù róngyì gǎnmào.","vi":"Nếu buổi tối không chú ý giữ ấm thì hôm sau dễ bị cảm."}],"related":[{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"ấm áp"},{"hanzi":"保温","pinyin":"bǎowēn","vi":"giữ nhiệt"},{"hanzi":"御寒","pinyin":"yùhán","vi":"chống rét"},{"hanzi":"着凉","pinyin":"zháoliáng","vi":"bị lạnh"}]},{"id":"报废","hanzi":"报废","pinyin":"bàofèi","meaning_vi":"thải bỏ, báo hỏng, thanh lý (đồ hư hỏng)","explanation":"报 (báo – báo cáo) + 废 (phế – bỏ đi) → khai báo là đồ hỏng, không dùng được nữa và loại bỏ.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"🗑️","examples":[{"type":"basic","zh":"这辆车报废了。","pinyin":"Zhè liàng chē bàofèi le.","vi":"Chiếc xe này đã bị thải bỏ."},{"type":"simple","zh":"工厂把一批旧机器全部报废了。","pinyin":"Gōngchǎng bǎ yìpī jiù jīqì quánbù bàofèi le.","vi":"Nhà máy đã thanh lý toàn bộ một lô máy cũ."},{"type":"compound","zh":"因为发动机进水了，所以这台车只能报废。","pinyin":"Yīnwèi fādòngjī jìnshuǐ le, suǒyǐ zhè tái chē zhǐnéng bàofèi.","vi":"Vì động cơ bị ngập nước nên chiếc xe này chỉ có thể thải bỏ."}],"related":[{"hanzi":"作废","pinyin":"zuòfèi","vi":"hết hiệu lực"},{"hanzi":"废品","pinyin":"fèipǐn","vi":"phế phẩm"},{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"},{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hỏng"}],"traditional":"報廢"},{"id":"报亭","hanzi":"报亭","pinyin":"bàotíng","meaning_vi":"sạp báo, quầy báo","explanation":"报 (báo – báo chí) + 亭 (đình – chòi nhỏ) → quầy nhỏ bán báo chí bên đường.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"📰","examples":[{"type":"basic","zh":"路口有个报亭。","pinyin":"Lùkǒu yǒu ge bàotíng.","vi":"Ở ngã tư có một sạp báo."},{"type":"simple","zh":"他每天早上在报亭买一份报纸。","pinyin":"Tā měitiān zǎoshang zài bàotíng mǎi yí fèn bàozhǐ.","vi":"Mỗi sáng anh ấy mua một tờ báo ở sạp báo."},{"type":"compound","zh":"自从大家都用手机看新闻，街上的报亭就越来越少了。","pinyin":"Zìcóng dàjiā dōu yòng shǒujī kàn xīnwén, jiēshang de bàotíng jiù yuèláiyuè shǎo le.","vi":"Từ khi mọi người đều đọc tin trên điện thoại, sạp báo trên phố ngày càng ít đi."}],"related":[{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"báo giấy"},{"hanzi":"杂志","pinyin":"zázhì","vi":"tạp chí"},{"hanzi":"书报摊","pinyin":"shūbàotān","vi":"sạp sách báo"},{"hanzi":"亭子","pinyin":"tíngzi","vi":"cái chòi"}],"traditional":"報亭"},{"id":"豹","hanzi":"豹","pinyin":"bào","meaning_vi":"con báo","explanation":"豹 (báo – con báo) → loài thú họ mèo có lông đốm, chạy rất nhanh.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐆","examples":[{"type":"basic","zh":"豹跑得非常快。","pinyin":"Bào pǎo de fēicháng kuài.","vi":"Báo chạy rất nhanh."},{"type":"simple","zh":"一只豹悄悄地爬上了大树。","pinyin":"Yì zhī bào qiāoqiāo de páshangle dà shù.","vi":"Một con báo lặng lẽ trèo lên cây lớn."},{"type":"compound","zh":"虽然豹的身体不如狮子大，但是它非常灵活。","pinyin":"Suīrán bào de shēntǐ bùrú shīzi dà, dànshì tā fēicháng línghuó.","vi":"Tuy thân hình báo không to bằng sư tử nhưng nó rất nhanh nhẹn."}],"related":[{"hanzi":"猎豹","pinyin":"lièbào","vi":"báo săn"},{"hanzi":"老虎","pinyin":"lǎohǔ","vi":"hổ"},{"hanzi":"狮子","pinyin":"shīzi","vi":"sư tử"},{"hanzi":"豹子","pinyin":"bàozi","vi":"con báo"}]},{"id":"爆冷门","hanzi":"爆冷门","pinyin":"bàolěngmén","meaning_vi":"bất ngờ thắng, có kết quả ngoài dự đoán","explanation":"爆 (bạo – nổ) + 冷门 (lãnh môn – \"cửa lạnh\", ít người chú ý) → kết quả bất ngờ ngoài dự đoán, nhất là trong thi đấu (kẻ yếu thắng).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"😮","examples":[{"type":"basic","zh":"比赛爆冷门了！","pinyin":"Bǐsài bàolěngmén le!","vi":"Trận đấu có kết quả bất ngờ!"},{"type":"simple","zh":"一支无名小队在世界杯上爆冷门。","pinyin":"Yì zhī wúmíng xiǎoduì zài Shìjièbēi shang bàolěngmén.","vi":"Một đội bóng vô danh gây bất ngờ lớn ở World Cup."},{"type":"compound","zh":"虽然大家都看好卫冕冠军，但是比赛还是爆冷门了。","pinyin":"Suīrán dàjiā dōu kànhǎo wèimiǎn guànjūn, dànshì bǐsài háishi bàolěngmén le.","vi":"Tuy ai cũng đánh giá cao nhà đương kim vô địch nhưng trận đấu vẫn có kết quả bất ngờ."}],"related":[{"hanzi":"冷门","pinyin":"lěngmén","vi":"ít người chú ý"},{"hanzi":"热门","pinyin":"rèmén","vi":"được ưa chuộng"},{"hanzi":"黑马","pinyin":"hēimǎ","vi":"ngựa ô"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"}],"traditional":"爆冷門"},{"id":"爆竹","hanzi":"爆竹","pinyin":"bàozhú","meaning_vi":"pháo (đốt)","explanation":"爆 (bạo – nổ) + 竹 (trúc – tre) → pháo; thời xưa người ta đốt ống tre cho nổ để xua tà khí.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧨","examples":[{"type":"basic","zh":"外面在放爆竹。","pinyin":"Wàimiàn zài fàngbàozhú.","vi":"Bên ngoài đang đốt pháo."},{"type":"simple","zh":"春节的夜晚到处都是爆竹声。","pinyin":"Chūnjié de yèwǎn dàochù dōu shì bàozhú shēng.","vi":"Đêm Tết khắp nơi vang tiếng pháo."},{"type":"compound","zh":"因为燃放爆竹会污染空气，所以很多城市禁止燃放。","pinyin":"Yīnwèi ránfàng bàozhú huì wūrǎn kōngqì, suǒyǐ hěn duō chéngshì jìnzhǐ ránfàng.","vi":"Vì đốt pháo gây ô nhiễm không khí nên nhiều thành phố cấm đốt."}],"related":[{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo dây"},{"hanzi":"烟花","pinyin":"yānhuā","vi":"pháo hoa"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết"},{"hanzi":"放炮","pinyin":"fàngpào","vi":"đốt pháo"}]},{"id":"备用","hanzi":"备用","pinyin":"bèiyòng","meaning_vi":"dự phòng, để dành khi cần","explanation":"备 (bị – chuẩn bị) + 用 (dụng – dùng) → chuẩn bị sẵn để dùng khi cần.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🔋","examples":[{"type":"basic","zh":"这是备用钥匙。","pinyin":"Zhè shì bèiyòng yàoshi.","vi":"Đây là chìa khóa dự phòng."},{"type":"simple","zh":"出门旅行最好带一块备用电池。","pinyin":"Chūmén lǚxíng zuìhǎo dài yíkuài bèiyòng diànchí.","vi":"Đi du lịch tốt nhất nên mang một cục pin dự phòng."},{"type":"compound","zh":"万一主电源断了，备用发电机就会自动启动。","pinyin":"Wànyī zhǔ diànyuán duàn le, bèiyòng fādiànjī jiù huì zìdòng qǐdòng.","vi":"Lỡ nguồn điện chính bị mất thì máy phát dự phòng sẽ tự khởi động."}],"related":[{"hanzi":"备份","pinyin":"bèifèn","vi":"bản sao lưu"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"chuẩn bị"},{"hanzi":"储备","pinyin":"chǔbèi","vi":"dự trữ"},{"hanzi":"备胎","pinyin":"bèitāi","vi":"lốp dự phòng"}],"traditional":"備用"},{"id":"背面","hanzi":"背面","pinyin":"bèimiàn","meaning_vi":"mặt sau, mặt trái","explanation":"背 (bối – lưng, phía sau) + 面 (diện – mặt) → mặt sau của một vật.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"请看纸的背面。","pinyin":"Qǐngkàn zhǐ de bèimiàn.","vi":"Xin xem mặt sau tờ giấy."},{"type":"simple","zh":"他在照片背面写下了日期。","pinyin":"Tā zài zhàopiàn bèimiàn xiěxiàle rìqī.","vi":"Anh ấy viết ngày tháng ở mặt sau tấm ảnh."},{"type":"compound","zh":"如果正面写不下，你就写在纸的背面。","pinyin":"Rúguǒ zhèngmiàn xiě buxià, nǐ jiù xiě zài zhǐ de bèimiàn.","vi":"Nếu mặt trước viết không đủ thì bạn viết ở mặt sau tờ giấy."}],"related":[{"hanzi":"正面","pinyin":"zhèngmiàn","vi":"mặt trước"},{"hanzi":"反面","pinyin":"fǎnmiàn","vi":"mặt trái"},{"hanzi":"背后","pinyin":"bèihòu","vi":"phía sau"},{"hanzi":"侧面","pinyin":"cèmiàn","vi":"mặt bên"}]},{"id":"被捕","hanzi":"被捕","pinyin":"bèibǔ","meaning_vi":"bị bắt, bị bắt giữ","explanation":"被 (bị – bị) + 捕 (bộ – bắt) → bị bắt giữ.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚔","examples":[{"type":"basic","zh":"小偷当场被捕。","pinyin":"Xiǎotōu dāngchǎng bèibǔ.","vi":"Tên trộm bị bắt tại chỗ."},{"type":"simple","zh":"那名嫌疑人昨晚在机场被捕。","pinyin":"Nà míng xiányírén zuówǎn zài jīchǎng bèibǔ.","vi":"Nghi phạm đó bị bắt tại sân bay tối qua."},{"type":"compound","zh":"虽然他逃了三年，但是最后还是被捕了。","pinyin":"Suīrán tā táole sān nián, dànshì zuìhòu háishi bèibǔ le.","vi":"Tuy hắn trốn ba năm nhưng cuối cùng vẫn bị bắt."}],"related":[{"hanzi":"逮捕","pinyin":"dàibǔ","vi":"bắt giữ"},{"hanzi":"拘留","pinyin":"jūliú","vi":"tạm giữ"},{"hanzi":"嫌疑人","pinyin":"xiányírén","vi":"nghi phạm"},{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"}]},{"id":"奔","hanzi":"奔","pinyin":"bēn","meaning_vi":"chạy nhanh, lao đi; chạy trốn","explanation":"奔 (bôn – chạy) → chạy vội, lao nhanh (奔跑, 奔向); thời xưa còn chỉ bỏ nhà theo người yêu (私奔).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"马在草原上飞奔。","pinyin":"Mǎ zài cǎoyuán shang fēibēn.","vi":"Ngựa phi nước đại trên thảo nguyên."},{"type":"simple","zh":"孩子们欢笑着奔向大海。","pinyin":"Háizimen huānxiàozhe bēnxiàng dàhǎi.","vi":"Bọn trẻ cười vui chạy ùa ra biển."},{"type":"compound","zh":"一听到着火的消息，消防员就奔向了现场。","pinyin":"Yì tīngdào zháohuǒ de xiāoxi, xiāofángyuán jiù bēnxiàngle xiànchǎng.","vi":"Vừa nghe tin cháy, lính cứu hỏa liền lao đến hiện trường."}],"related":[{"hanzi":"奔跑","pinyin":"bēnpǎo","vi":"chạy"},{"hanzi":"飞奔","pinyin":"fēibēn","vi":"phi nhanh"},{"hanzi":"私奔","pinyin":"sībēn","vi":"bỏ trốn theo nhau"},{"hanzi":"奔波","pinyin":"bēnbō","vi":"bôn ba"}]},{"id":"本分","hanzi":"本分","pinyin":"běnfèn","meaning_vi":"bổn phận; an phận, thật thà đúng mực","explanation":"本 (bản – vốn) + 分 (phận – phần) → phần việc vốn thuộc về mình, bổn phận; tính từ: an phận, đúng mực, thật thà.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📏","examples":[{"type":"basic","zh":"这是我的本分。","pinyin":"Zhè shì wǒ de běnfèn.","vi":"Đây là bổn phận của tôi."},{"type":"simple","zh":"他是个老实本分的农民。","pinyin":"Tā shì ge lǎoshi běnfèn de nóngmín.","vi":"Ông ấy là một người nông dân thật thà an phận."},{"type":"compound","zh":"既然你当了老师，就要尽到教书育人的本分。","pinyin":"Jìrán nǐ dāngle lǎoshī, jiùyào jìndào jiāoshū yùrén de běnfèn.","vi":"Đã làm giáo viên thì phải làm tròn bổn phận dạy học, giáo dục con người."}],"related":[{"hanzi":"职责","pinyin":"zhízé","vi":"chức trách"},{"hanzi":"义务","pinyin":"yìwù","vi":"nghĩa vụ"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"守本分","pinyin":"shǒuběnfèn","vi":"giữ bổn phận"}]},{"id":"本色","hanzi":"本色","pinyin":"běnsè","meaning_vi":"bản sắc, bản chất vốn có; màu gốc","explanation":"本 (bản – gốc) + 色 (sắc – màu) → màu sắc vốn có; nghĩa bóng: bản chất, phẩm chất thật của con người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌿","examples":[{"type":"basic","zh":"他保持着军人本色。","pinyin":"Tā bǎochízhe jūnrén běnsè.","vi":"Anh ấy giữ được bản sắc người lính."},{"type":"simple","zh":"这部电影展现了农民朴实的本色。","pinyin":"Zhè bù diànyǐng zhǎnxiànle nóngmín pǔshí de běnsè.","vi":"Bộ phim này thể hiện bản chất chất phác của người nông dân."},{"type":"compound","zh":"即使当了大老板，他也没有改变勤俭的本色。","pinyin":"Jíshǐ dāngle dà lǎobǎn, tā yě méiyǒu gǎibiàn qínjiǎn de běnsè.","vi":"Dù đã thành ông chủ lớn, anh ấy vẫn không thay đổi bản chất cần kiệm."}],"related":[{"hanzi":"本性","pinyin":"běnxìng","vi":"bản tính"},{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"特色","pinyin":"tèsè","vi":"đặc sắc"},{"hanzi":"原色","pinyin":"yuánsè","vi":"màu gốc"}]},{"id":"笨蛋","hanzi":"笨蛋","pinyin":"bèndàn","meaning_vi":"đồ ngốc, thằng ngốc","explanation":"笨 (bổn – ngốc) + 蛋 (đản – trứng, dùng để mắng) → đồ ngốc (lời mắng, đôi khi dùng thân mật).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤪","examples":[{"type":"basic","zh":"你这个笨蛋！","pinyin":"Nǐ zhè ge bèndàn!","vi":"Đồ ngốc này!"},{"type":"simple","zh":"他觉得自己像个笨蛋一样被骗了。","pinyin":"Tā juéde zìjǐ xiàng ge bèndàn yíyàng bèi piàn le.","vi":"Anh ấy thấy mình bị lừa như một thằng ngốc."},{"type":"compound","zh":"如果连这么简单的题都不会，别人就会说你是笨蛋。","pinyin":"Rúguǒ lián zhème jiǎndān de tí dōu bú huì, biérén jiù huì shuō nǐ shì bèndàn.","vi":"Nếu đến bài dễ thế này cũng không làm được thì người ta sẽ bảo bạn là đồ ngốc."}],"related":[{"hanzi":"傻瓜","pinyin":"shǎguā","vi":"đồ ngốc"},{"hanzi":"笨","pinyin":"bèn","vi":"ngốc"},{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"糊涂","pinyin":"hútu","vi":"hồ đồ"}]},{"id":"笨重","hanzi":"笨重","pinyin":"bènzhòng","meaning_vi":"nặng nề, cồng kềnh","explanation":"笨 (bổn – vụng) + 重 (trọng – nặng) → to nặng, cồng kềnh, khó di chuyển.","hsk_level":"7-9","tags":["tinh-tu","do-vat"],"image":"🪨","examples":[{"type":"basic","zh":"这个箱子很笨重。","pinyin":"Zhè ge xiāngzi hěn bènzhòng.","vi":"Cái thùng này rất cồng kềnh."},{"type":"simple","zh":"工人们把笨重的机器抬上了卡车。","pinyin":"Gōngrénmen bǎ bènzhòng de jīqì tái shangle kǎchē.","vi":"Công nhân khiêng cỗ máy nặng nề lên xe tải."},{"type":"compound","zh":"虽然这台老电脑很笨重，但是爷爷一直舍不得扔。","pinyin":"Suīrán zhè tái lǎo diànnǎo hěn bènzhòng, dànshì yéye yìzhí shěbude rēng.","vi":"Tuy chiếc máy tính cũ này rất cồng kềnh nhưng ông vẫn không nỡ vứt."}],"related":[{"hanzi":"沉重","pinyin":"chénzhòng","vi":"nặng nề"},{"hanzi":"轻便","pinyin":"qīngbiàn","vi":"nhẹ gọn"},{"hanzi":"笨拙","pinyin":"bènzhuō","vi":"vụng về"},{"hanzi":"庞大","pinyin":"pángdà","vi":"đồ sộ"}]},{"id":"绷","hanzi":"绷","pinyin":"bēng","meaning_vi":"căng, kéo căng; khâu lược","explanation":"绷 (băng – căng) → kéo căng ra; cũng chỉ khâu lược tạm; 绷着脸 (đọc běng) là nghiêm mặt.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"把绳子绷紧。","pinyin":"Bǎ shéngzi bēngjǐn.","vi":"Kéo căng sợi dây."},{"type":"simple","zh":"这件衬衫绷在他身上太紧了。","pinyin":"Zhè jiàn chènshān bēng zài tā shēnshang tài jǐn le.","vi":"Cái áo sơ mi này bó căng trên người anh ấy."},{"type":"compound","zh":"如果吉他的琴弦绷得太紧，就很容易断。","pinyin":"Rúguǒ jítā de qínxián bēng de tài jǐn, jiù hěn róngyì duàn.","vi":"Nếu dây đàn ghi-ta căng quá thì rất dễ đứt."}],"related":[{"hanzi":"绷带","pinyin":"bēngdài","vi":"băng gạc"},{"hanzi":"紧绷","pinyin":"jǐnbēng","vi":"căng chặt"},{"hanzi":"拉紧","pinyin":"lājǐn","vi":"kéo căng"},{"hanzi":"松","pinyin":"sōng","vi":"lỏng"}],"traditional":"繃"},{"id":"绷带","hanzi":"绷带","pinyin":"bēngdài","meaning_vi":"băng (y tế), băng gạc","explanation":"绷 (băng – căng, quấn) + 带 (đái – dải) → dải băng quấn vết thương.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"他手上缠着绷带。","pinyin":"Tā shǒushang chánzhe bēngdài.","vi":"Tay anh ấy quấn băng."},{"type":"simple","zh":"护士轻轻地给病人换了绷带。","pinyin":"Hùshi qīngqīng de gěi bìngrén huànle bēngdài.","vi":"Y tá nhẹ nhàng thay băng cho bệnh nhân."},{"type":"compound","zh":"如果伤口又出血了，就马上换一条新绷带。","pinyin":"Rúguǒ shāngkǒu yòu chūxiě le, jiù mǎshàng huàn yì tiáo xīn bēngdài.","vi":"Nếu vết thương lại chảy máu thì lập tức thay băng mới."}],"related":[{"hanzi":"纱布","pinyin":"shābù","vi":"gạc"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"包扎","pinyin":"bāozā","vi":"băng bó"},{"hanzi":"创可贴","pinyin":"chuāngkětiē","vi":"băng cá nhân"}],"traditional":"繃帶"},{"id":"比不上","hanzi":"比不上","pinyin":"bǐbushàng","meaning_vi":"không bằng, không sánh được","explanation":"比 (tỷ – so) + 不上 (bất thượng – không lên tới) → bổ ngữ khả năng: so không bằng.","hsk_level":"7-9","tags":["dong-tu"],"image":"📉","examples":[{"type":"basic","zh":"我比不上他。","pinyin":"Wǒ bǐbushàng tā.","vi":"Tôi không bằng anh ấy."},{"type":"simple","zh":"外面的饭菜比不上妈妈做的。","pinyin":"Wàimiàn de fàncài bǐbushàng māma zuò de.","vi":"Cơm bên ngoài không bằng mẹ nấu."},{"type":"compound","zh":"虽然这款手机便宜，但是质量比不上名牌。","pinyin":"Suīrán zhè kuǎn shǒujī piányi, dànshì zhìliàng bǐbushàng míngpái.","vi":"Tuy điện thoại này rẻ nhưng chất lượng không bằng hàng hiệu."}],"related":[{"hanzi":"比得上","pinyin":"bǐdeshàng","vi":"sánh được"},{"hanzi":"不如","pinyin":"bùrú","vi":"không bằng"},{"hanzi":"赶不上","pinyin":"gǎnbushàng","vi":"không theo kịp"},{"hanzi":"不及","pinyin":"bùjí","vi":"không bằng"}]},{"id":"比起","hanzi":"比起","pinyin":"bǐqǐ","meaning_vi":"so với","explanation":"比 (tỷ – so) + 起 (khởi) → \"so với…\", thường đứng đầu câu theo mẫu 比起A，B更…","hsk_level":"7-9","tags":["gioi-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"比起夏天，我更喜欢冬天。","pinyin":"Bǐqǐ xiàtiān, wǒ gèng xǐhuan dōngtiān.","vi":"So với mùa hè, tôi thích mùa đông hơn."},{"type":"simple","zh":"比起去年，今年的收入增加了不少。","pinyin":"Bǐqǐ qùnián, jīnnián de shōurù zēngjiāle bùshǎo.","vi":"So với năm ngoái, thu nhập năm nay tăng không ít."},{"type":"compound","zh":"比起坐飞机，坐火车虽然慢一点，但是可以欣赏风景。","pinyin":"Bǐqǐ zuòfēijī, zuò huǒchē suīrán màn yìdiǎn, dànshì kěyǐ xīnshǎng fēngjǐng.","vi":"So với đi máy bay, đi tàu tuy chậm hơn một chút nhưng có thể ngắm cảnh."}],"related":[{"hanzi":"比较","pinyin":"bǐjiào","vi":"so sánh"},{"hanzi":"相比","pinyin":"xiāngbǐ","vi":"so với"},{"hanzi":"与其","pinyin":"yǔqí","vi":"thà"},{"hanzi":"对比","pinyin":"duìbǐ","vi":"đối chiếu"}]},{"id":"比试","hanzi":"比试","pinyin":"bǐshi","meaning_vi":"thi thố, so tài; khoa tay ướm thử","explanation":"比 (tỷ – so) + 试 (thí – thử) → so tài cao thấp; cũng chỉ làm động tác ướm, khoa tay thử.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🤺","examples":[{"type":"basic","zh":"咱们比试比试！","pinyin":"Zánmen bǐshi bǐshi!","vi":"Chúng ta so tài xem nào!"},{"type":"simple","zh":"两个武林高手在山顶比试了一场。","pinyin":"Liǎng ge wǔlín gāoshǒu zài shāndǐng bǐshile yì chǎng.","vi":"Hai cao thủ võ lâm so tài một trận trên đỉnh núi."},{"type":"compound","zh":"如果你不服气，我们就到操场上比试一下。","pinyin":"Rúguǒ nǐ bùfúqì, wǒmen jiù dào cāochǎng shang bǐshi yíxià.","vi":"Nếu cậu không phục thì chúng ta ra sân so tài một chút."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"较量","pinyin":"jiàoliàng","vi":"đọ sức"},{"hanzi":"比武","pinyin":"bǐwǔ","vi":"thi võ"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"}],"traditional":"比試"},{"id":"必不可少","hanzi":"必不可少","pinyin":"bìbù-kěshǎo","meaning_vi":"không thể thiếu, thiết yếu","explanation":"必 (tất – ắt) + 不可 (bất khả – không thể) + 少 (thiểu – thiếu) → ắt không thể thiếu, cực kỳ cần thiết.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔑","examples":[{"type":"basic","zh":"水是必不可少的。","pinyin":"Shuǐ shì bìbùkěshǎo de.","vi":"Nước là thứ không thể thiếu."},{"type":"simple","zh":"护照是出国旅行必不可少的证件。","pinyin":"Hùzhào shì chūguó lǚxíng bìbùkěshǎo de zhèngjiàn.","vi":"Hộ chiếu là giấy tờ không thể thiếu khi đi du lịch nước ngoài."},{"type":"compound","zh":"要想学好外语，每天练习是必不可少的，所以你不能偷懒。","pinyin":"Yào xiǎng xuéhǎo wàiyǔ, měitiān liànxí shì bìbùkěshǎo de, suǒyǐ nǐ bù néng tōulǎn.","vi":"Muốn học giỏi ngoại ngữ thì luyện tập mỗi ngày là không thể thiếu, nên bạn không được lười."}],"related":[{"hanzi":"不可缺少","pinyin":"bùkěquēshǎo","vi":"không thể thiếu"},{"hanzi":"必需","pinyin":"bìxū","vi":"thiết yếu"},{"hanzi":"必要","pinyin":"bìyào","vi":"cần thiết"},{"hanzi":"可有可无","pinyin":"kěyǒukěwú","vi":"có cũng được"}]},{"id":"必定","hanzi":"必定","pinyin":"bìdìng","meaning_vi":"nhất định, ắt hẳn","explanation":"必 (tất – ắt) + 定 (định – chắc chắn) → nhất định, chắc chắn sẽ.","hsk_level":"7-9","tags":["pho-tu"],"image":"✅","examples":[{"type":"basic","zh":"他必定会来。","pinyin":"Tā bìdìng huì lái.","vi":"Anh ấy nhất định sẽ đến."},{"type":"simple","zh":"这次比赛我们必定能拿到冠军。","pinyin":"Zhè cì bǐsài wǒmen bìdìng néng nádào guànjūn.","vi":"Lần thi đấu này chúng ta nhất định giành chức vô địch."},{"type":"compound","zh":"只要大家团结一心，我们就必定能克服困难。","pinyin":"Zhǐyào dàjiā tuánjié yìxīn, wǒmen jiù bìdìng néng kèfú kùnnan.","vi":"Chỉ cần mọi người đồng lòng thì chúng ta nhất định vượt qua được khó khăn."}],"related":[{"hanzi":"一定","pinyin":"yídìng","vi":"nhất định"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"chắc chắn"},{"hanzi":"必然","pinyin":"bìrán","vi":"tất nhiên"},{"hanzi":"必须","pinyin":"bìxū","vi":"phải"}]},{"id":"避难","hanzi":"避难","pinyin":"bìnàn","meaning_vi":"lánh nạn, tị nạn","explanation":"避 (tị – tránh) + 难 (nạn – tai nạn) → tránh tai họa, lánh nạn; cũng chỉ xin tị nạn chính trị.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"⛺","examples":[{"type":"basic","zh":"村民上山避难。","pinyin":"Cūnmín shàngshān bìnàn.","vi":"Dân làng lên núi lánh nạn."},{"type":"simple","zh":"很多难民逃到邻国避难。","pinyin":"Hěn duō nànmín táo dào Línguó bìnàn.","vi":"Nhiều người chạy sang nước láng giềng lánh nạn."},{"type":"compound","zh":"一旦台风登陆，海边的居民就要到避难所避难。","pinyin":"Yídàn táifēng dēnglù, hǎibiān de jūmín jiùyào dào bìnànsuǒ bìnàn.","vi":"Một khi bão đổ bộ, cư dân ven biển phải đến nơi trú ẩn để lánh nạn."}],"related":[{"hanzi":"避难所","pinyin":"bìnànsuǒ","vi":"nơi trú ẩn"},{"hanzi":"难民","pinyin":"nànmín","vi":"người tị nạn"},{"hanzi":"逃难","pinyin":"táonàn","vi":"chạy nạn"},{"hanzi":"躲避","pinyin":"duǒbì","vi":"tránh né"}],"traditional":"避難"},{"id":"编号","hanzi":"编号","pinyin":"biānhào","meaning_vi":"đánh số; số hiệu, mã số","explanation":"编 (biên – sắp xếp) + 号 (hiệu – số) → đánh số thứ tự; số hiệu.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔢","examples":[{"type":"basic","zh":"请记下编号。","pinyin":"Qǐng jìxià biānhào.","vi":"Hãy ghi lại số hiệu."},{"type":"simple","zh":"每台电脑都有自己的编号。","pinyin":"Měi tái diànnǎo dōu yǒu zìjǐ de biānhào.","vi":"Mỗi máy tính đều có mã số riêng."},{"type":"compound","zh":"如果你把文件按日期编号，以后就很容易找到。","pinyin":"Rúguǒ nǐ bǎ wénjiàn àn rìqī biānhào, yǐhòu jiù hěn róngyì zhǎodào.","vi":"Nếu bạn đánh số tài liệu theo ngày thì sau này rất dễ tìm."}],"related":[{"hanzi":"号码","pinyin":"hàomǎ","vi":"số"},{"hanzi":"序号","pinyin":"xùhào","vi":"số thứ tự"},{"hanzi":"编码","pinyin":"biānmǎ","vi":"mã hóa"},{"hanzi":"代号","pinyin":"dàihào","vi":"mật danh"}],"traditional":"編號"},{"id":"变异","hanzi":"变异","pinyin":"biànyì","meaning_vi":"biến dị, đột biến, biến chủng","explanation":"变 (biến – thay đổi) + 异 (dị – khác) → biến đổi thành khác đi; thuật ngữ sinh học: biến dị, biến chủng.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"病毒发生了变异。","pinyin":"Bìngdú fāshēngle biànyì.","vi":"Virus đã biến dị."},{"type":"simple","zh":"科学家正在研究这种变异的基因。","pinyin":"Kēxuéjiā zhèngzài yánjiū zhè zhǒng biànyì de jīyīn.","vi":"Các nhà khoa học đang nghiên cứu loại gen biến dị này."},{"type":"compound","zh":"因为病毒不断变异，所以疫苗也需要不断更新。","pinyin":"Yīnwèi bìngdú búduàn biànyì, suǒyǐ yìmiáo yě xūyào búduàn gēngxīn.","vi":"Vì virus liên tục biến dị nên vắc-xin cũng cần liên tục cập nhật."}],"related":[{"hanzi":"突变","pinyin":"tūbiàn","vi":"đột biến"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"},{"hanzi":"遗传","pinyin":"yíchuán","vi":"di truyền"}],"traditional":"變異"},{"id":"便道","hanzi":"便道","pinyin":"biàndào","meaning_vi":"vỉa hè, lối đi bộ; đường tắt; đường tạm","explanation":"便 (tiện – tiện lợi) + 道 (đạo – đường) → đường đi tiện lợi: vỉa hè, đường tắt hoặc đường tạm.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚶","examples":[{"type":"basic","zh":"行人请走便道。","pinyin":"Xíngrén qǐng zǒu biàndào.","vi":"Người đi bộ xin đi trên vỉa hè."},{"type":"simple","zh":"施工期间车辆只能走旁边的便道。","pinyin":"Shīgōng qījiān chēliàng zhǐnéng zǒu pángbiān de biàndào.","vi":"Trong thời gian thi công xe cộ chỉ được đi đường tạm bên cạnh."},{"type":"compound","zh":"如果抄这条便道，我们就能早十分钟到。","pinyin":"Rúguǒ chāo zhè tiáo biàndào, wǒmen jiù néng zǎo shí fēnzhōng dào.","vi":"Nếu đi tắt đường này thì chúng ta có thể đến sớm mười phút."}],"related":[{"hanzi":"人行道","pinyin":"rénxíngdào","vi":"vỉa hè"},{"hanzi":"近路","pinyin":"jìnlù","vi":"đường tắt"},{"hanzi":"小路","pinyin":"xiǎolù","vi":"đường nhỏ"},{"hanzi":"马路","pinyin":"mǎlù","vi":"đường cái"}]},{"id":"便饭","hanzi":"便饭","pinyin":"biànfàn","meaning_vi":"bữa cơm thường, cơm nhà","explanation":"便 (tiện – đơn giản) + 饭 (phạn – cơm) → bữa cơm bình thường; 家常便饭 còn chỉ chuyện thường ngày, \"chuyện cơm bữa\".","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍚","examples":[{"type":"basic","zh":"来家里吃个便饭吧。","pinyin":"Lái jiālǐ chī ge biànfàn ba.","vi":"Đến nhà ăn bữa cơm thường nhé."},{"type":"simple","zh":"加班对他来说已经是家常便饭了。","pinyin":"Jiābān duì tā lái shuō yǐjīng shì jiāchángbiànfàn le.","vi":"Tăng ca đối với anh ấy đã là chuyện cơm bữa."},{"type":"compound","zh":"虽然只是一顿便饭，但是大家吃得很开心。","pinyin":"Suīrán zhǐshì yí dùn biànfàn, dànshì dàjiā chī de hěn kāixīn.","vi":"Tuy chỉ là bữa cơm thường nhưng mọi người ăn rất vui."}],"related":[{"hanzi":"家常便饭","pinyin":"jiāchángbiànfàn","vi":"chuyện cơm bữa"},{"hanzi":"家常菜","pinyin":"jiāchángcài","vi":"món ăn gia đình"},{"hanzi":"饭菜","pinyin":"fàncài","vi":"cơm canh"},{"hanzi":"宴席","pinyin":"yànxí","vi":"tiệc"}],"traditional":"便飯"},{"id":"便捷","hanzi":"便捷","pinyin":"biànjié","meaning_vi":"tiện lợi nhanh chóng","explanation":"便 (tiện – tiện lợi) + 捷 (tiệp – nhanh) → vừa tiện vừa nhanh.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"⚡","examples":[{"type":"basic","zh":"网上购物很便捷。","pinyin":"Wǎngshàng gòuwù hěn biànjié.","vi":"Mua sắm trực tuyến rất tiện lợi."},{"type":"simple","zh":"地铁为市民提供了便捷的交通。","pinyin":"Dìtiě wèi shìmín tígōngle biànjié de jiāotōng.","vi":"Tàu điện ngầm mang lại giao thông nhanh tiện cho người dân."},{"type":"compound","zh":"自从有了手机支付，买东西就变得更加便捷了。","pinyin":"Zìcóng yǒule shǒujī zhīfù, mǎidōngxi jiù biànde gèngjiā biànjié le.","vi":"Từ khi có thanh toán qua điện thoại, mua sắm trở nên tiện lợi hơn."}],"related":[{"hanzi":"方便","pinyin":"fāngbiàn","vi":"tiện lợi"},{"hanzi":"快捷","pinyin":"kuàijié","vi":"nhanh chóng"},{"hanzi":"便利","pinyin":"biànlì","vi":"thuận tiện"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền phức"}]},{"id":"辩","hanzi":"辩","pinyin":"biàn","meaning_vi":"tranh luận, biện luận","explanation":"辩 (biện – biện luận) → dùng lời lẽ để tranh luận phải trái (辩论, 争辩).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"真理越辩越明。","pinyin":"Zhēnlǐ yuè biàn yuè míng.","vi":"Chân lý càng tranh luận càng sáng tỏ."},{"type":"simple","zh":"他为自己的观点辩了很久。","pinyin":"Tā wèi zìjǐ de guāndiǎn biànle hěn jiǔ.","vi":"Anh ấy biện luận cho quan điểm của mình rất lâu."},{"type":"compound","zh":"虽然他百般狡辩，但是证据摆在眼前。","pinyin":"Suīrán tā bǎibān jiǎobiàn, dànshì zhèngjù bǎi zài yǎnqián.","vi":"Tuy hắn ngụy biện đủ đường nhưng chứng cứ đã bày ra trước mắt."}],"related":[{"hanzi":"辩论","pinyin":"biànlùn","vi":"tranh luận"},{"hanzi":"争辩","pinyin":"zhēngbiàn","vi":"cãi lý"},{"hanzi":"狡辩","pinyin":"jiǎobiàn","vi":"ngụy biện"},{"hanzi":"辩护","pinyin":"biànhù","vi":"bào chữa"}],"traditional":"辯"},{"id":"标","hanzi":"标","pinyin":"biāo","meaning_vi":"đánh dấu, ghi; nhãn, dấu hiệu","explanation":"标 (tiêu – ngọn, dấu hiệu) → dấu hiệu, nhãn; động từ: ghi, đánh dấu (标价, 标出).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏷️","examples":[{"type":"basic","zh":"价格标在哪儿？","pinyin":"Jiàgé biāo zài nǎr?","vi":"Giá được ghi ở đâu?"},{"type":"simple","zh":"老师用红笔标出了文章的错字。","pinyin":"Lǎoshī yòng hóng bǐ biāo chūle wénzhāng de cuòzì.","vi":"Thầy dùng bút đỏ đánh dấu các lỗi chính tả trong bài."},{"type":"compound","zh":"如果你把重点标出来，复习的时候就省事多了。","pinyin":"Rúguǒ nǐ bǎ zhòngdiǎn biāo chulai, fùxí de shíhou jiù shěngshì duō le.","vi":"Nếu bạn đánh dấu trọng điểm thì lúc ôn tập sẽ đỡ việc hơn nhiều."}],"related":[{"hanzi":"标记","pinyin":"biāojì","vi":"đánh dấu"},{"hanzi":"标签","pinyin":"biāoqiān","vi":"nhãn"},{"hanzi":"标志","pinyin":"biāozhì","vi":"biểu tượng"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"}],"traditional":"標"},{"id":"标签","hanzi":"标签","pinyin":"biāoqiān","meaning_vi":"nhãn, tem nhãn; thẻ tag","explanation":"标 (tiêu – dấu hiệu) + 签 (thiêm – thẻ nhỏ) → nhãn dán ghi thông tin; nghĩa mở rộng: \"cái mác\" gán cho ai, thẻ tag trên mạng.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔖","examples":[{"type":"basic","zh":"衣服上有标签。","pinyin":"Yīfu shang yǒu biāoqiān.","vi":"Trên áo có mác."},{"type":"simple","zh":"买食品时要仔细看包装上的标签。","pinyin":"Mǎi shípǐn shí yào zǐxì kàn bāozhuāng shang de biāoqiān.","vi":"Khi mua thực phẩm phải xem kỹ nhãn trên bao bì."},{"type":"compound","zh":"不要随便给别人贴标签，因为每个人都是复杂的。","pinyin":"Bú yào suíbiàn gěi biérén tiē biāoqiān, yīnwèi měigerén dōu shì fùzá de.","vi":"Đừng tùy tiện gán mác cho người khác, vì ai cũng phức tạp cả."}],"related":[{"hanzi":"商标","pinyin":"shāngbiāo","vi":"nhãn hiệu"},{"hanzi":"标价","pinyin":"biāojià","vi":"niêm yết giá"},{"hanzi":"贴","pinyin":"tiē","vi":"dán"},{"hanzi":"价签","pinyin":"jiàqiān","vi":"tem giá"}],"traditional":"標籤"},{"id":"标示","hanzi":"标示","pinyin":"biāoshì","meaning_vi":"chỉ rõ, ghi rõ, đánh dấu","explanation":"标 (tiêu – dấu hiệu) + 示 (thị – cho thấy) → dùng ký hiệu, chữ viết để chỉ rõ cho người khác thấy.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪧","examples":[{"type":"basic","zh":"地图上标示了出口。","pinyin":"Dìtú shang biāoshìle chūkǒu.","vi":"Trên bản đồ có ghi rõ lối ra."},{"type":"simple","zh":"包装上清楚地标示着保质期。","pinyin":"Bāozhuāng shang qīngchu de biāoshìzhe bǎozhìqī.","vi":"Trên bao bì ghi rõ hạn sử dụng."},{"type":"compound","zh":"如果危险区域没有标示清楚，游客就很容易出事。","pinyin":"Rúguǒ wēixiǎn qūyù méiyǒu biāoshì qīngchu, yóukè jiù hěn róngyì chūshì.","vi":"Nếu khu vực nguy hiểm không được đánh dấu rõ thì du khách rất dễ gặp nạn."}],"related":[{"hanzi":"标明","pinyin":"biāomíng","vi":"ghi rõ"},{"hanzi":"标注","pinyin":"biāozhù","vi":"chú thích"},{"hanzi":"表示","pinyin":"biǎoshì","vi":"biểu thị"},{"hanzi":"指示","pinyin":"zhǐshì","vi":"chỉ dẫn"}],"traditional":"標示"},{"id":"别看","hanzi":"别看","pinyin":"biékàn","meaning_vi":"đừng thấy… mà tưởng, tuy… nhưng","explanation":"别 (biệt – đừng) + 看 (khán – nhìn) → \"đừng nhìn bề ngoài\", dùng mở đầu ý: tuy bề ngoài thế này nhưng thực tế khác.","hsk_level":"7-9","tags":["lien-tu"],"image":"👀","examples":[{"type":"basic","zh":"别看他小，懂得可多了。","pinyin":"Biékàn tā xiǎo, dǒngde kě duō le.","vi":"Đừng thấy nó nhỏ, nó biết nhiều lắm đấy."},{"type":"simple","zh":"别看这家店不大，生意却特别好。","pinyin":"Biékàn zhè jiā diàn búdà, shēngyi què tèbié hǎo.","vi":"Đừng thấy cửa hàng này nhỏ, buôn bán lại cực kỳ đắt khách."},{"type":"compound","zh":"别看她平时不爱说话，但是一上台就特别自信。","pinyin":"Biékàn tā píngshí bú ài shuōhuà, dànshì yí shàngtái jiù tèbié zìxìn.","vi":"Đừng thấy cô ấy bình thường ít nói, vừa lên sân khấu là cực kỳ tự tin."}],"related":[{"hanzi":"虽然","pinyin":"suīrán","vi":"tuy"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"mặc dù"},{"hanzi":"看上去","pinyin":"kànshangqu","vi":"trông có vẻ"},{"hanzi":"其实","pinyin":"qíshí","vi":"thật ra"}],"traditional":"別看"},{"id":"别说","hanzi":"别说","pinyin":"biéshuō","meaning_vi":"đừng nói chi, huống chi, chưa kể","explanation":"别 (biệt – đừng) + 说 (thuyết – nói) → \"đừng nói…\", dùng nhấn mạnh: việc dễ còn không được, huống gì việc khó.","hsk_level":"7-9","tags":["lien-tu"],"image":"🙊","examples":[{"type":"basic","zh":"别说你，我也不会。","pinyin":"Biéshuō nǐ, wǒ yě bú huì.","vi":"Đừng nói là cậu, đến tôi cũng không biết."},{"type":"simple","zh":"别说是英语，他连汉语都说不好。","pinyin":"Biéshuō shì Yīngyǔ, tā lián Hànyǔ dōu shuō bu hǎo.","vi":"Đừng nói tiếng Anh, đến tiếng Trung anh ta còn nói không tốt."},{"type":"compound","zh":"别说买房子了，就是租房子，他也负担不起。","pinyin":"Biéshuō mǎi fángzi le, jiùshì zū fángzi, tā yě fùdān bu qǐ.","vi":"Đừng nói mua nhà, ngay cả thuê nhà anh ấy cũng không kham nổi."}],"related":[{"hanzi":"何况","pinyin":"hékuàng","vi":"huống hồ"},{"hanzi":"更不用说","pinyin":"gèngbúyòngshuō","vi":"càng khỏi phải nói"},{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"},{"hanzi":"连","pinyin":"lián","vi":"ngay cả"}],"traditional":"別說"},{"id":"别提了","hanzi":"别提了","pinyin":"biétíle","meaning_vi":"đừng nhắc nữa (tệ lắm, khỏi nói)","explanation":"别 (biệt – đừng) + 提 (đề – nhắc) + 了 (trợ từ) → \"đừng nhắc nữa\", khẩu ngữ biểu thị chuyện quá tệ, không muốn kể lại.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"😩","examples":[{"type":"basic","zh":"别提了，我又输了。","pinyin":"Biétíle, wǒ yòu shū le.","vi":"Đừng nhắc nữa, tôi lại thua rồi."},{"type":"simple","zh":"别提了，昨天的面试糟透了。","pinyin":"Biétíle, zuótiān de miànshì zāotòule.","vi":"Đừng nhắc nữa, buổi phỏng vấn hôm qua tệ hết chỗ nói."},{"type":"compound","zh":"别提了，因为下大雨，我们的旅行全泡汤了。","pinyin":"Biétíle, yīnwèi xià dàyǔ, wǒmen de lǚxíng quán pàotāng le.","vi":"Đừng nhắc nữa, vì mưa to nên chuyến đi của chúng tôi hỏng hết."}],"related":[{"hanzi":"算了","pinyin":"suànle","vi":"thôi bỏ đi"},{"hanzi":"别说了","pinyin":"biéshuōle","vi":"đừng nói nữa"},{"hanzi":"提起","pinyin":"tíqǐ","vi":"nhắc đến"},{"hanzi":"糟透了","pinyin":"zāotòule","vi":"tệ hết chỗ nói"}],"traditional":"別提了"},{"id":"滨海","hanzi":"滨海","pinyin":"bīnhǎi","meaning_vi":"ven biển, giáp biển","explanation":"滨 (tân – bờ nước) + 海 (hải – biển) → ở ven biển, sát biển; cũng là địa danh (khu Tân Hải, Thiên Tân).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🏖️","examples":[{"type":"basic","zh":"这是一座滨海城市。","pinyin":"Zhè shì yí zuò bīnhǎi chéngshì.","vi":"Đây là một thành phố ven biển."},{"type":"simple","zh":"我们沿着滨海公路开了一整天。","pinyin":"Wǒmen yánzhe bīnhǎi gōnglù kāile yìzhěngtiān.","vi":"Chúng tôi lái xe dọc con đường ven biển cả ngày."},{"type":"compound","zh":"因为气候温和，所以很多老人喜欢在滨海小城养老。","pinyin":"Yīnwèi qìhòu wēnhé, suǒyǐ hěn duō lǎorén xǐhuan zài bīnhǎi xiǎochéng yǎnglǎo.","vi":"Vì khí hậu ôn hòa nên nhiều người già thích dưỡng lão ở thị trấn ven biển."}],"related":[{"hanzi":"沿海","pinyin":"yánhǎi","vi":"duyên hải"},{"hanzi":"海滨","pinyin":"hǎibīn","vi":"bờ biển"},{"hanzi":"海边","pinyin":"hǎibiān","vi":"bờ biển"},{"hanzi":"内陆","pinyin":"Nèilù","vi":"nội địa"}],"traditional":"濱海"},{"id":"缤纷","hanzi":"缤纷","pinyin":"bīnfēn","meaning_vi":"rực rỡ, muôn màu; lả tả","explanation":"缤 (tân) + 纷 (phân – nhiều, rối rít) → nhiều và đan xen rực rỡ (五彩缤纷); cũng tả hoa lá rơi lả tả.","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🎨","examples":[{"type":"basic","zh":"花园里五彩缤纷。","pinyin":"Huāyuán lǐ wǔcǎibīnfēn.","vi":"Khu vườn rực rỡ muôn màu."},{"type":"simple","zh":"一到秋天，山上就落叶缤纷。","pinyin":"Yí dào qiūtiān, shān shang jiù luòyè bīnfēn.","vi":"Cứ đến mùa thu, trên núi lá rụng lả tả muôn màu."},{"type":"compound","zh":"一到晚上，广场上的灯光就变得五彩缤纷。","pinyin":"Yí dào wǎnshang, guǎngchǎng shang de dēngguāng jiù biànde wǔcǎibīnfēn.","vi":"Cứ đến tối, ánh đèn ở quảng trường lại trở nên rực rỡ muôn màu."}],"related":[{"hanzi":"五彩缤纷","pinyin":"wǔcǎibīnfēn","vi":"rực rỡ sắc màu"},{"hanzi":"多彩","pinyin":"duōcǎi","vi":"nhiều màu"},{"hanzi":"绚丽","pinyin":"xuànlì","vi":"lộng lẫy"},{"hanzi":"纷纷","pinyin":"fēnfēn","vi":"lả tả"}],"traditional":"繽紛"},{"id":"冰棍儿","hanzi":"冰棍儿","pinyin":"bīnggùnr","meaning_vi":"kem que","explanation":"冰 (băng – đá) + 棍 (côn – que) + 儿 (nhi – hậu tố) → que đá lạnh, tức kem que.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍦","examples":[{"type":"basic","zh":"我想吃冰棍儿。","pinyin":"Wǒ xiǎng chī bīnggùnr.","vi":"Tôi muốn ăn kem que."},{"type":"simple","zh":"小时候一根冰棍儿只要五分钱。","pinyin":"Xiǎoshíhou yìgēn bīnggùnr zhǐyào wǔ fēnqián.","vi":"Hồi nhỏ một que kem chỉ năm xu."},{"type":"compound","zh":"因为天气太热，所以冰棍儿刚买来就化了。","pinyin":"Yīnwèi tiānqì tài rè, suǒyǐ bīnggùnr gāng mǎi lái jiù huà le.","vi":"Vì trời quá nóng nên que kem vừa mua đã chảy."}],"related":[{"hanzi":"冰淇淋","pinyin":"bīngqílín","vi":"kem"},{"hanzi":"雪糕","pinyin":"xuěgāo","vi":"kem que"},{"hanzi":"冷饮","pinyin":"lěngyǐn","vi":"đồ uống lạnh"},{"hanzi":"冰块","pinyin":"bīngkuài","vi":"đá viên"}],"traditional":"冰棍兒"},{"id":"冰山","hanzi":"冰山","pinyin":"bīngshān","meaning_vi":"núi băng, tảng băng trôi","explanation":"冰 (băng) + 山 (sơn – núi) → núi băng, tảng băng trôi; 冰山一角 nghĩa bóng là \"phần nổi của tảng băng\".","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🧊","examples":[{"type":"basic","zh":"船撞上了冰山。","pinyin":"Chuán zhuàngshangle bīngshān.","vi":"Con tàu đâm vào tảng băng."},{"type":"simple","zh":"这些问题只是冰山一角。","pinyin":"Zhèxiē wèntí zhǐshì bīngshānyìjiǎo.","vi":"Những vấn đề này chỉ là phần nổi của tảng băng."},{"type":"compound","zh":"因为全球变暖，所以南极的冰山正在快速融化。","pinyin":"Yīnwèi quánqiúbiànnuǎn, suǒyǐ nánjí de bīngshān zhèngzài kuàisù rónghuà.","vi":"Vì trái đất nóng lên nên các núi băng ở Nam Cực đang tan nhanh."}],"related":[{"hanzi":"冰川","pinyin":"bīngchuān","vi":"sông băng"},{"hanzi":"冰山一角","pinyin":"bīngshānyìjiǎo","vi":"phần nổi tảng băng"},{"hanzi":"南极","pinyin":"nánjí","vi":"Nam Cực"},{"hanzi":"融化","pinyin":"rónghuà","vi":"tan chảy"}]},{"id":"秉承","hanzi":"秉承","pinyin":"bǐngchéng","meaning_vi":"tiếp nối, kế thừa, tuân theo","explanation":"秉 (bỉnh – cầm giữ) + 承 (thừa – tiếp nhận) → nhận lấy và giữ theo (ý chỉ, truyền thống, tinh thần).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"我们秉承传统。","pinyin":"Wǒmen bǐngchéng chuántǒng.","vi":"Chúng tôi kế thừa truyền thống."},{"type":"simple","zh":"这家老店一直秉承诚信经营的理念。","pinyin":"Zhè jiālǎo diàn yìzhí bǐngchéng chéngxìn jīngyíng de lǐniàn.","vi":"Cửa hàng lâu năm này luôn giữ theo triết lý kinh doanh trung thực."},{"type":"compound","zh":"只要秉承先辈的精神，我们就一定能把事业做大。","pinyin":"Zhǐyào bǐngchéng xiānbèi de jīngshén, wǒmen jiù yídìng néng bǎ shìyè zuòdà.","vi":"Chỉ cần tiếp nối tinh thần của cha ông thì chúng ta nhất định làm sự nghiệp lớn mạnh."}],"related":[{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"},{"hanzi":"遵循","pinyin":"zūnxún","vi":"tuân theo"},{"hanzi":"发扬","pinyin":"fāyáng","vi":"phát huy"}]},{"id":"并行","hanzi":"并行","pinyin":"bìngxíng","meaning_vi":"song song, tiến hành song song","explanation":"并 (tịnh – cùng) + 行 (hành – đi) → cùng đi sóng đôi; nghĩa rộng: tiến hành song song cùng lúc.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛤️","examples":[{"type":"basic","zh":"两条铁路并行。","pinyin":"Liǎng tiáo tiělù bìngxíng.","vi":"Hai tuyến đường sắt chạy song song."},{"type":"simple","zh":"这两个项目可以同时并行推进。","pinyin":"Zhè liǎng ge xiàngmù kěyǐ tóngshí bìngxíng tuījìn.","vi":"Hai dự án này có thể đẩy mạnh song song cùng lúc."},{"type":"compound","zh":"如果几个任务并行处理，效率就会大大提高。","pinyin":"Rúguǒ jǐ ge rènwu bìngxíng chǔlǐ, xiàolǜ jiù huì dàdà tígāo.","vi":"Nếu xử lý song song vài nhiệm vụ thì hiệu suất sẽ tăng mạnh."}],"related":[{"hanzi":"平行","pinyin":"píngxíng","vi":"song song"},{"hanzi":"同时","pinyin":"tóngshí","vi":"đồng thời"},{"hanzi":"并存","pinyin":"bìngcún","vi":"cùng tồn tại"},{"hanzi":"并肩","pinyin":"bìngjiān","vi":"kề vai"}],"traditional":"並行"},{"id":"剥","hanzi":"剥","pinyin":"bāo","meaning_vi":"bóc, lột (vỏ)","explanation":"剥 (bác – lột) → bóc vỏ, lột da (khẩu ngữ đọc bāo); trong từ ghép văn viết đọc bō (剥削 – bóc lột).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍊","examples":[{"type":"basic","zh":"我给你剥个橘子。","pinyin":"Wǒ gěi nǐ bāo ge júzi.","vi":"Để tôi bóc cho bạn quả quýt."},{"type":"simple","zh":"奶奶每天下午坐在门口剥花生。","pinyin":"Nǎinai měitiān xiàwǔ zuò zài ménkǒu bāo huāshēng.","vi":"Chiều nào bà cũng ngồi trước cửa bóc lạc."},{"type":"compound","zh":"只要先把鸡蛋泡在冷水里，蛋壳就很好剥。","pinyin":"Zhǐyào xiān bǎ jīdàn pào zài lěngshuǐ lǐ, dànké jiù hěn hǎo bāo.","vi":"Chỉ cần ngâm trứng vào nước lạnh trước thì vỏ trứng rất dễ bóc."}],"related":[{"hanzi":"剥皮","pinyin":"bāopí","vi":"lột vỏ"},{"hanzi":"剥削","pinyin":"bōxuē","vi":"bóc lột"},{"hanzi":"削","pinyin":"xiāo","vi":"gọt"},{"hanzi":"皮","pinyin":"pí","vi":"vỏ"}],"traditional":"剝"},{"id":"伯伯","hanzi":"伯伯","pinyin":"bóbo","meaning_vi":"bác (anh của bố); bác (gọi người lớn tuổi)","explanation":"伯 (bá – anh cả, bác) lặp lại → bác, anh trai của bố; cũng dùng gọi thân mật đàn ông lớn tuổi hơn bố.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👴","examples":[{"type":"basic","zh":"伯伯来看我们了。","pinyin":"Bóbo lái kàn wǒmen le.","vi":"Bác đến thăm chúng tôi."},{"type":"simple","zh":"邻居王伯伯每天早上都去公园打太极。","pinyin":"Línjū wáng bóbo měitiān zǎo Shangdōu qù gōngyuán dǎtàijí.","vi":"Bác Vương hàng xóm sáng nào cũng ra công viên tập thái cực quyền."},{"type":"compound","zh":"虽然伯伯年纪大了，但是身体还很硬朗。","pinyin":"Suīrán bóbo niánjì dà le, dànshì shēntǐ hái hěn yìnglang.","vi":"Tuy bác đã có tuổi nhưng sức khỏe vẫn rất dẻo dai."}],"related":[{"hanzi":"叔叔","pinyin":"shūshu","vi":"chú"},{"hanzi":"伯父","pinyin":"bófù","vi":"bác"},{"hanzi":"伯母","pinyin":"bómǔ","vi":"bác gái"},{"hanzi":"舅舅","pinyin":"jiùjiu","vi":"cậu"}]},{"id":"补给","hanzi":"补给","pinyin":"bǔjǐ","meaning_vi":"tiếp tế, cung cấp bổ sung","explanation":"补 (bổ – bù thêm) + 给 (cấp – cung cấp) → tiếp tế, bổ sung vật tư (lương thực, nước, đạn dược…).","hsk_level":"7-9","tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"部队需要补给。","pinyin":"Bùduì xūyào bǔjǐ.","vi":"Quân đội cần tiếp tế."},{"type":"simple","zh":"运动员在补给站喝了几口水。","pinyin":"Yùndòngyuán zài bǔjǐzhàn hēle jǐ kǒushuǐ.","vi":"Vận động viên uống vài ngụm nước ở trạm tiếp tế."},{"type":"compound","zh":"如果船上的补给用完了，我们就只能靠岸。","pinyin":"Rúguǒ chuán shang de bǔjǐ yòng wánle, wǒmen jiù zhǐnéng kào'àn.","vi":"Nếu đồ tiếp tế trên tàu dùng hết thì chúng ta chỉ có thể cập bờ."}],"related":[{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"补充","pinyin":"bǔchōng","vi":"bổ sung"},{"hanzi":"物资","pinyin":"wùzī","vi":"vật tư"},{"hanzi":"后勤","pinyin":"hòuqín","vi":"hậu cần"}],"traditional":"補給"},{"id":"不得而知","hanzi":"不得而知","pinyin":"bùdé-érzhī","meaning_vi":"không thể biết được, chưa rõ","explanation":"不得 (bất đắc – không thể) + 而 (nhi – mà) + 知 (tri – biết) → không cách nào biết được.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"❓","examples":[{"type":"basic","zh":"结果不得而知。","pinyin":"Jiéguǒ bùdé ér zhī.","vi":"Kết quả chưa thể biết được."},{"type":"simple","zh":"这封信的作者是谁至今不得而知。","pinyin":"Zhè fēng xìn de zuòzhě shì shéi zhìjīn bùdé ér zhī.","vi":"Tác giả bức thư này là ai đến nay vẫn chưa rõ."},{"type":"compound","zh":"虽然警方调查了很久，但是真相仍然不得而知。","pinyin":"Suīrán jǐngfāng diàochále hěn jiǔ, dànshì zhēnxiàng réngrán bùdé ér zhī.","vi":"Tuy cảnh sát điều tra rất lâu nhưng sự thật vẫn chưa thể biết được."}],"related":[{"hanzi":"不知","pinyin":"bùzhī","vi":"không biết"},{"hanzi":"未知","pinyin":"wèizhī","vi":"chưa biết"},{"hanzi":"无从知晓","pinyin":"wúcóngzhīxiǎo","vi":"không cách nào biết"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"}]},{"id":"不定","hanzi":"不定","pinyin":"búdìng","meaning_vi":"không cố định, bất định, chưa chắc","explanation":"不 (bất – không) + 定 (định – cố định) → không cố định, thất thường; phó từ: chưa chắc, chưa biết chừng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🎲","examples":[{"type":"basic","zh":"天气阴晴不定。","pinyin":"Tiānqì yīn qíng búdìng.","vi":"Thời tiết lúc nắng lúc râm thất thường."},{"type":"simple","zh":"他每天回家的时间都不定。","pinyin":"Tā měitiān huíjiā de shíjiān dōu búdìng.","vi":"Giờ anh ấy về nhà mỗi ngày đều không cố định."},{"type":"compound","zh":"因为他的工作地点不定，所以很少回家。","pinyin":"Yīnwèi tā de gōngzuò dìdiǎn búdìng, suǒyǐ hěn shǎo huíjiā.","vi":"Vì nơi làm việc của anh ấy không cố định nên ít khi về nhà."}],"related":[{"hanzi":"说不定","pinyin":"shuōbudìng","vi":"không chừng"},{"hanzi":"不一定","pinyin":"bùyídìng","vi":"chưa chắc"},{"hanzi":"稳定","pinyin":"wěndìng","vi":"ổn định"},{"hanzi":"固定","pinyin":"gùdìng","vi":"cố định"}]},{"id":"不服","hanzi":"不服","pinyin":"bùfú","meaning_vi":"không phục, không chịu (chấp nhận)","explanation":"不 (bất) + 服 (phục – phục tùng) → không chịu khuất phục, không chấp nhận (phán quyết, kết quả…).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"他输了还不服。","pinyin":"Tā shūle hái bùfú.","vi":"Nó thua rồi mà vẫn không phục."},{"type":"simple","zh":"很多球迷对裁判的判罚表示不服。","pinyin":"Hěn duō qiúmí duì cáipàn de pànfá biǎoshì bùfú.","vi":"Nhiều cổ động viên tỏ ra không phục quyết định của trọng tài."},{"type":"compound","zh":"如果你对结果不服，就可以向上级部门申诉。","pinyin":"Rúguǒ nǐ duì jiéguǒ bùfú, jiù kěyǐ xiàng shàngjí bùmén shēnsù.","vi":"Nếu bạn không phục kết quả thì có thể khiếu nại lên cơ quan cấp trên."}],"related":[{"hanzi":"不服气","pinyin":"bùfúqì","vi":"không phục"},{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"},{"hanzi":"佩服","pinyin":"pèifú","vi":"khâm phục"},{"hanzi":"抗议","pinyin":"kàngyì","vi":"phản đối"}]},{"id":"不服气","hanzi":"不服气","pinyin":"bùfúqì","meaning_vi":"không phục, không cam lòng, ấm ức","explanation":"不 (bất) + 服气 (phục khí – tâm phục) → trong lòng không phục, không chịu thua.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💢","examples":[{"type":"basic","zh":"他一脸不服气。","pinyin":"Tā yì liǎn bùfúqì.","vi":"Mặt nó đầy vẻ không phục."},{"type":"simple","zh":"弟弟不服气地瞪了哥哥一眼。","pinyin":"Dìdi bùfúqì de dèngle gēge yìyǎn.","vi":"Cậu em ấm ức lườm anh một cái."},{"type":"compound","zh":"虽然这次输了，但是他很不服气，决定明年再来。","pinyin":"Suīrán zhè cì shū le, dànshì tā hěn bùfúqì, juédìng míngnián zài lái.","vi":"Tuy lần này thua nhưng cậu ấy rất không phục, quyết định năm sau lại đến."}],"related":[{"hanzi":"不服","pinyin":"bùfú","vi":"không phục"},{"hanzi":"服气","pinyin":"fúqì","vi":"phục"},{"hanzi":"不甘心","pinyin":"bùgānxīn","vi":"không cam lòng"},{"hanzi":"认输","pinyin":"rènshū","vi":"chịu thua"}],"traditional":"不服氣"},{"id":"不解","hanzi":"不解","pinyin":"bùjiě","meaning_vi":"không hiểu, khó hiểu; không gỡ được","explanation":"不 (bất) + 解 (giải – hiểu, gỡ) → không hiểu nổi, lấy làm khó hiểu; trong văn viết còn nghĩa \"không gỡ được\" (不解之缘).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"😕","examples":[{"type":"basic","zh":"他感到很不解。","pinyin":"Tā gǎndào hěn bùjiě.","vi":"Anh ấy cảm thấy rất khó hiểu."},{"type":"simple","zh":"大家对他的突然离开感到不解。","pinyin":"Dàjiā duì tā de tūrán líkāi gǎndào bùjiě.","vi":"Mọi người không hiểu nổi việc anh ấy đột ngột rời đi."},{"type":"compound","zh":"虽然他解释了半天，但是我还是有些不解。","pinyin":"Suīrán tā jiěshìle bàn tiān, dànshì wǒ háishi yǒuxiē bùjiě.","vi":"Tuy anh ấy giải thích mãi nhưng tôi vẫn hơi khó hiểu."}],"related":[{"hanzi":"疑惑","pinyin":"yíhuò","vi":"nghi hoặc"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"hiểu"},{"hanzi":"不解之缘","pinyin":"bùjiězhīyuán","vi":"mối duyên gắn bó"},{"hanzi":"困惑","pinyin":"kùnhuò","vi":"bối rối"}]},{"id":"不经意","hanzi":"不经意","pinyin":"bùjīngyì","meaning_vi":"vô tình, không để ý, tình cờ","explanation":"不 (bất) + 经意 (kinh ý – để ý) → không để ý, vô tình; thường dùng 不经意间 (lúc không để ý).","hsk_level":"7-9","tags":["pho-tu"],"image":"🍃","examples":[{"type":"basic","zh":"他不经意地笑了。","pinyin":"Tā bùjīngyì de xiào le.","vi":"Anh ấy vô tình mỉm cười."},{"type":"simple","zh":"我在不经意间听到了他们的谈话。","pinyin":"Wǒ zài bùjīngyì jiān tīngdàole tāmen de tánhuà.","vi":"Tôi tình cờ nghe được cuộc nói chuyện của họ."},{"type":"compound","zh":"虽然只是一句不经意的话，但是深深地伤害了她。","pinyin":"Suīrán zhǐshì yíjù bùjīngyì dehuà, dànshì shēnshēn de shānghàile tā.","vi":"Tuy chỉ là một câu nói vô tình nhưng đã làm cô ấy tổn thương sâu sắc."}],"related":[{"hanzi":"无意","pinyin":"wúyì","vi":"vô ý"},{"hanzi":"随意","pinyin":"suíyì","vi":"tùy ý"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"留意","pinyin":"liúyì","vi":"để ý"}],"traditional":"不經意"},{"id":"不肯","hanzi":"不肯","pinyin":"bùkěn","meaning_vi":"không chịu, không muốn","explanation":"不 (bất) + 肯 (khẳng – chịu, bằng lòng) → không chịu làm việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙅‍♂️","examples":[{"type":"basic","zh":"他不肯道歉。","pinyin":"Tā bùkěn dàoqiàn.","vi":"Anh ta không chịu xin lỗi."},{"type":"simple","zh":"孩子哭着不肯去幼儿园。","pinyin":"Háizi kūzhe bùkěn qù yòu'éryuán.","vi":"Đứa trẻ khóc không chịu đi mẫu giáo."},{"type":"compound","zh":"即使大家都劝他休息，他也不肯放下工作。","pinyin":"Jíshǐ dàjiā dōu quàn tā xiūxi, tā yě bùkěn fàngxià gōngzuò.","vi":"Dù mọi người khuyên nghỉ ngơi, anh ấy cũng không chịu buông công việc."}],"related":[{"hanzi":"肯","pinyin":"kěn","vi":"chịu"},{"hanzi":"拒绝","pinyin":"jùjué","vi":"từ chối"},{"hanzi":"不愿意","pinyin":"búyuànyì","vi":"không muốn"},{"hanzi":"答应","pinyin":"dāying","vi":"đồng ý"}]},{"id":"不理","hanzi":"不理","pinyin":"bùlǐ","meaning_vi":"phớt lờ, không thèm để ý","explanation":"不 (bất) + 理 (lý – để ý, quan tâm) → không thèm để ý, không đáp lại.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙄","examples":[{"type":"basic","zh":"她生气了，不理我。","pinyin":"Tā shēngqì le, bùlǐ wǒ.","vi":"Cô ấy giận rồi, không thèm để ý tôi."},{"type":"simple","zh":"他对别人的批评一概不理。","pinyin":"Tā duì biérén de pīpíng yígài bùlǐ.","vi":"Anh ấy hoàn toàn phớt lờ lời phê bình của người khác."},{"type":"compound","zh":"如果你总是不理他，他就会以为你讨厌他。","pinyin":"Rúguǒ nǐ zǒngshì bùlǐ tā, tā jiù huì yǐwéi nǐ tǎoyàn tā.","vi":"Nếu bạn cứ phớt lờ cậu ấy thì cậu ấy sẽ tưởng bạn ghét cậu ấy."}],"related":[{"hanzi":"理睬","pinyin":"lǐcǎi","vi":"để ý"},{"hanzi":"不管","pinyin":"bùguǎn","vi":"không quan tâm"},{"hanzi":"忽视","pinyin":"hūshì","vi":"xem nhẹ"},{"hanzi":"冷落","pinyin":"lěngluò","vi":"ghẻ lạnh"}]},{"id":"不利于","hanzi":"不利于","pinyin":"búlìyú","meaning_vi":"bất lợi cho, có hại cho","explanation":"不利 (bất lợi) + 于 (vu – đối với) → không có lợi, có hại cho cái gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"熬夜不利于健康。","pinyin":"Áoyè búlìyú jiànkāng.","vi":"Thức khuya có hại cho sức khỏe."},{"type":"simple","zh":"过度开发不利于环境保护。","pinyin":"Guòdù kāifā búlìyú huánjìngbǎohù.","vi":"Khai thác quá mức bất lợi cho việc bảo vệ môi trường."},{"type":"compound","zh":"虽然批评很重要，但是太严厉的批评不利于孩子成长。","pinyin":"Suīrán pīpíng hěn zhòngyào, dànshì tài yánlì de pīpíng búlìyú háizi chéngzhǎng.","vi":"Tuy phê bình rất quan trọng nhưng phê bình quá nghiêm khắc bất lợi cho sự trưởng thành của trẻ."}],"related":[{"hanzi":"有利于","pinyin":"yǒulìyú","vi":"có lợi cho"},{"hanzi":"不利","pinyin":"búlì","vi":"bất lợi"},{"hanzi":"有害","pinyin":"yǒuhài","vi":"có hại"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"}],"traditional":"不利於"},{"id":"不难","hanzi":"不难","pinyin":"bùnán","meaning_vi":"không khó, dễ dàng","explanation":"不 (bất) + 难 (nan – khó) → không khó; thường dùng 不难看出 (dễ dàng nhận ra).","hsk_level":"7-9","tags":["tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"这道题不难。","pinyin":"Zhè dào tí bùnán.","vi":"Bài này không khó."},{"type":"simple","zh":"从他的表情不难看出他很紧张。","pinyin":"Cóng tā de biǎoqíng bùnán kànchū tā hěn jǐnzhāng.","vi":"Từ nét mặt anh ấy dễ dàng nhận ra anh ấy rất căng thẳng."},{"type":"compound","zh":"只要掌握了方法，学好汉字其实不难。","pinyin":"Zhǐyào zhǎngwòle fāngfǎ, xuéhǎo hànzì qíshí bùnán.","vi":"Chỉ cần nắm được phương pháp thì học tốt chữ Hán thật ra không khó."}],"related":[{"hanzi":"容易","pinyin":"róngyì","vi":"dễ"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"đơn giản"},{"hanzi":"困难","pinyin":"kùnnan","vi":"khó khăn"},{"hanzi":"不易","pinyin":"búyì","vi":"không dễ"}],"traditional":"不難"},{"id":"不平","hanzi":"不平","pinyin":"bùpíng","meaning_vi":"gồ ghề, không bằng phẳng; bất bình, bất công","explanation":"不 (bất) + 平 (bình – phẳng, công bằng) → không phẳng; nghĩa bóng: bất công, bất bình (愤愤不平).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"这条路坑坑洼洼，很不平。","pinyin":"Zhè tiáo lù kēng kēngwā wā, hěn bùpíng.","vi":"Con đường này lồi lõm, rất gồ ghề."},{"type":"simple","zh":"他对不公平的待遇感到愤愤不平。","pinyin":"Tā duì bù gōngpíng de dàiyù gǎndào fènfènbùpíng.","vi":"Anh ấy bất bình trước sự đối xử không công bằng."},{"type":"compound","zh":"如果路面不平，骑车的时候就要特别小心。","pinyin":"Rúguǒ lùmiàn bùpíng, qíchē de shíhou jiùyào tèbié xiǎoxīn.","vi":"Nếu mặt đường gồ ghề thì khi đi xe đạp phải đặc biệt cẩn thận."}],"related":[{"hanzi":"公平","pinyin":"gōngpíng","vi":"công bằng"},{"hanzi":"不公","pinyin":"bùgōng","vi":"bất công"},{"hanzi":"平坦","pinyin":"píngtǎn","vi":"bằng phẳng"},{"hanzi":"愤愤不平","pinyin":"fènfènbùpíng","vi":"bất bình phẫn uất"}]},{"id":"不起眼","hanzi":"不起眼","pinyin":"bùqǐyǎn","meaning_vi":"không nổi bật, tầm thường, không bắt mắt","explanation":"不 (bất) + 起眼 (khởi nhãn – bắt mắt) → không thu hút ánh nhìn, trông bình thường.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"这家小店很不起眼。","pinyin":"Zhè jiā xiǎodiàn hěn bùqǐyǎn.","vi":"Quán nhỏ này trông rất bình thường."},{"type":"simple","zh":"这个不起眼的小零件其实非常重要。","pinyin":"Zhè ge bùqǐyǎn de xiǎo língjiàn qíshí fēicháng zhòngyào.","vi":"Linh kiện nhỏ không bắt mắt này thực ra rất quan trọng."},{"type":"compound","zh":"虽然他外表不起眼，但是他是公司最好的工程师。","pinyin":"Suīrán tā wàibiǎo bùqǐyǎn, dànshì tā shì gōngsī zuìhǎo de gōngchéngshī.","vi":"Tuy vẻ ngoài anh ấy không nổi bật nhưng anh ấy là kỹ sư giỏi nhất công ty."}],"related":[{"hanzi":"平凡","pinyin":"píngfán","vi":"bình thường"},{"hanzi":"普通","pinyin":"pǔtōng","vi":"phổ thông"},{"hanzi":"显眼","pinyin":"xiǎnyǎn","vi":"nổi bật"},{"hanzi":"醒目","pinyin":"xǐngmù","vi":"bắt mắt"}]},{"id":"不容","hanzi":"不容","pinyin":"bùróng","meaning_vi":"không cho phép, không thể (dung thứ)","explanation":"不 (bất) + 容 (dung – dung chứa, cho phép) → không cho phép, không thể; thường gặp 不容忽视, 不容置疑.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"事实不容否认。","pinyin":"Shìshí bùróng fǒurèn.","vi":"Sự thật không thể chối cãi."},{"type":"simple","zh":"环境污染问题已经不容忽视了。","pinyin":"Huánjìng wūrǎn wèntí yǐjīng bùróng hūshì le.","vi":"Vấn đề ô nhiễm môi trường đã không thể xem nhẹ được nữa."},{"type":"compound","zh":"因为时间紧迫，所以我们不容有半点儿犹豫。","pinyin":"Yīnwèi shíjiān jǐnpò, suǒyǐ wǒmen bùróng yǒu bàn diǎnr yóuyù.","vi":"Vì thời gian gấp gáp nên chúng ta không được phép do dự chút nào."}],"related":[{"hanzi":"不许","pinyin":"bùxǔ","vi":"không cho"},{"hanzi":"容许","pinyin":"róngxǔ","vi":"cho phép"},{"hanzi":"不容忽视","pinyin":"bùrónghūshì","vi":"không thể xem nhẹ"},{"hanzi":"不准","pinyin":"bùzhǔn","vi":"cấm"}]},{"id":"不如说","hanzi":"不如说","pinyin":"bùrúshuō","meaning_vi":"chi bằng nói, đúng hơn là","explanation":"不如 (bất như – chẳng bằng) + 说 (thuyết – nói) → chi bằng nói là; thường dùng theo mẫu 与其说A，不如说B.","hsk_level":"7-9","tags":["lien-tu"],"image":"💭","examples":[{"type":"basic","zh":"与其说是运气，不如说是实力。","pinyin":"Yǔqíshuō shì yùnqi, bùrúshuō shì shílì.","vi":"Nói là may mắn chi bằng nói là thực lực."},{"type":"simple","zh":"他不是生气，不如说是有点儿失望。","pinyin":"Tā bú shì shēngqì, bùrúshuō shì yǒudiǎnr shīwàng.","vi":"Anh ấy không phải giận, đúng hơn là hơi thất vọng."},{"type":"compound","zh":"与其说他是我的老师，不如说他是我最好的朋友。","pinyin":"Yǔqíshuō tā shì wǒ de lǎoshī, bùrúshuō tā shì wǒ zuìhǎo de péngyou.","vi":"Nói thầy ấy là thầy giáo của tôi, chi bằng nói thầy ấy là người bạn thân nhất của tôi."}],"related":[{"hanzi":"与其","pinyin":"yǔqí","vi":"thà rằng"},{"hanzi":"不如","pinyin":"bùrú","vi":"chẳng bằng"},{"hanzi":"倒不如","pinyin":"dàobùrú","vi":"chi bằng"},{"hanzi":"换句话说","pinyin":"huànjùhuàshuō","vi":"nói cách khác"}],"traditional":"不如說"},{"id":"不慎","hanzi":"不慎","pinyin":"búshèn","meaning_vi":"bất cẩn, sơ ý","explanation":"不 (bất) + 慎 (thận – cẩn thận) → không cẩn thận, sơ ý; thường dùng trong văn viết, tin tức.","hsk_level":"7-9","tags":["pho-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他不慎摔倒了。","pinyin":"Tā búshèn shuāidǎo le.","vi":"Anh ấy sơ ý bị ngã."},{"type":"simple","zh":"一名游客不慎掉进了湖里。","pinyin":"Yì míng yóukè búshèn diào jìnle Húlǐ.","vi":"Một du khách sơ ý rơi xuống hồ."},{"type":"compound","zh":"如果在家里用电不慎，就可能引起火灾。","pinyin":"Rúguǒ zài jiālǐ yòng diàn búshèn, jiù kěnéng yǐnqǐ huǒzāi.","vi":"Nếu ở nhà sử dụng điện bất cẩn thì có thể gây hỏa hoạn."}],"related":[{"hanzi":"不小心","pinyin":"bùxiǎoxīn","vi":"không cẩn thận"},{"hanzi":"谨慎","pinyin":"jǐnshèn","vi":"thận trọng"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"cẩu thả"},{"hanzi":"疏忽","pinyin":"shūhu","vi":"sơ suất"}]},{"id":"不适","hanzi":"不适","pinyin":"búshì","meaning_vi":"khó chịu, không khỏe, mệt mỏi","explanation":"不 (bất – không) + 适 (thích – thích hợp, dễ chịu) → cơ thể không dễ chịu, thấy khó ở.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"我身体有点儿不适。","pinyin":"Wǒ shēntǐ yǒudiǎnr búshì.","vi":"Tôi thấy người hơi khó chịu."},{"type":"simple","zh":"坐了一天车，她感到头晕不适。","pinyin":"Zuòle yì tiānchē, tā gǎndào tóuyūn búshì.","vi":"Đi xe cả ngày, cô ấy thấy chóng mặt khó chịu."},{"type":"compound","zh":"如果吃药后感到不适，就要马上告诉医生。","pinyin":"Rúguǒ chīyào hòu gǎndào búshì, jiùyào mǎshàng gàosu yīshēng.","vi":"Nếu uống thuốc xong thấy khó chịu thì phải báo ngay cho bác sĩ."}],"related":[{"hanzi":"舒适","pinyin":"shūshì","vi":"dễ chịu"},{"hanzi":"难受","pinyin":"nánshòu","vi":"khó chịu"},{"hanzi":"不舒服","pinyin":"bùshūfu","vi":"không khỏe"},{"hanzi":"适应","pinyin":"shìyìng","vi":"thích nghi"}],"traditional":"不適"},{"id":"不算","hanzi":"不算","pinyin":"búsuàn","meaning_vi":"không tính, không được coi là","explanation":"不 (bất – không) + 算 (toán – tính) → không tính vào, hoặc không được xem là (thường đi với tính từ: 不算贵 – không tính là đắt).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧮","examples":[{"type":"basic","zh":"这件衣服不算贵。","pinyin":"Zhè jiàn yīfu búsuàn guì.","vi":"Bộ quần áo này không tính là đắt."},{"type":"simple","zh":"迟到五分钟以上的人不算出席。","pinyin":"Chídào wǔ fēnzhōng yǐshàng de rén búsuàn chūxí.","vi":"Người đến muộn quá năm phút không tính là có mặt."},{"type":"compound","zh":"虽然他的汉语不算流利，但是日常交流没问题。","pinyin":"Suīrán tā de Hànyǔ búsuàn liúlì, dànshì rìcháng jiāoliú méi wèntí.","vi":"Tuy tiếng Trung của anh ấy không tính là lưu loát nhưng giao tiếp hằng ngày không thành vấn đề."}],"related":[{"hanzi":"算","pinyin":"suàn","vi":"tính, coi là"},{"hanzi":"算是","pinyin":"suànshì","vi":"coi như là"},{"hanzi":"不能算","pinyin":"bùnéngsuàn","vi":"không thể tính"},{"hanzi":"计算","pinyin":"jìsuàn","vi":"tính toán"}]},{"id":"不同寻常","hanzi":"不同寻常","pinyin":"bùtóng-xúncháng","meaning_vi":"khác thường, không bình thường, đặc biệt","explanation":"不同 (bất đồng – không giống) + 寻常 (tầm thường – bình thường) → khác hẳn mức bình thường, rất đặc biệt.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"今天的气氛不同寻常。","pinyin":"Jīntiān de qìfēn bùtóng xúncháng.","vi":"Không khí hôm nay khác thường."},{"type":"simple","zh":"这次会议对公司有着不同寻常的意义。","pinyin":"Zhè cì huìyì duì gōngsī yǒuzhe bùtóng xúncháng de yìyì.","vi":"Cuộc họp lần này có ý nghĩa đặc biệt đối với công ty."},{"type":"compound","zh":"因为他的表现不同寻常，所以老师特别注意他。","pinyin":"Yīnwèi tā de biǎoxiàn bùtóng xúncháng, suǒyǐ lǎoshī tèbié zhùyì tā.","vi":"Vì biểu hiện của cậu ấy khác thường nên thầy giáo đặc biệt chú ý đến cậu."}],"related":[{"hanzi":"寻常","pinyin":"xúncháng","vi":"bình thường"},{"hanzi":"非同寻常","pinyin":"fēitóngxúncháng","vi":"phi thường"},{"hanzi":"特殊","pinyin":"tèshū","vi":"đặc biệt"},{"hanzi":"异常","pinyin":"yìcháng","vi":"bất thường"}],"traditional":"不同尋常"},{"id":"不为人知","hanzi":"不为人知","pinyin":"bùwéi-rénzhī","meaning_vi":"không ai biết, ít người biết đến","explanation":"不 (bất) + 为 (vi – bị) + 人知 (nhân tri – người biết) → không bị người khác biết, giữ kín.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤫","examples":[{"type":"basic","zh":"这是一段不为人知的历史。","pinyin":"Zhè shì yí duàn bù wéirén zhī de lìshǐ.","vi":"Đây là một đoạn lịch sử ít người biết."},{"type":"simple","zh":"每个人心里都有一些不为人知的秘密。","pinyin":"Měigèrén xīnlǐ dōu yǒuyìxiē bù wéirén zhī de mìmì.","vi":"Trong lòng mỗi người đều có vài bí mật không ai biết."},{"type":"compound","zh":"虽然他现在很成功，但是背后有很多不为人知的辛苦。","pinyin":"Suīrán tā xiànzài hěn chénggōng, dànshì bèihòu yǒu hěn duō bù wéirén zhī de xīnkǔ.","vi":"Tuy bây giờ anh ấy rất thành công nhưng phía sau có biết bao vất vả không ai biết."}],"related":[{"hanzi":"鲜为人知","pinyin":"xiǎnwéirénzhī","vi":"ít ai biết"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"},{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"che giấu"}],"traditional":"不為人知"},{"id":"不亚于","hanzi":"不亚于","pinyin":"búyàyú","meaning_vi":"không kém, không thua kém","explanation":"不 (bất – không) + 亚 (á – kém, thứ hai) + 于 (vu – so với) → không kém hơn so với…","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"她的厨艺不亚于厨师。","pinyin":"Tā de chúyì búyàyú chúshī.","vi":"Tay nghề nấu ăn của cô ấy không thua đầu bếp."},{"type":"simple","zh":"这部电影的影响力不亚于一本畅销书。","pinyin":"Zhè bù diànyǐng de yǐngxiǎnglì búyàyú yì běn chàngxiāoshū.","vi":"Sức ảnh hưởng của bộ phim này không kém một cuốn sách bán chạy."},{"type":"compound","zh":"虽然他是新手，但是他的速度不亚于老员工。","pinyin":"Suīrán tā shì xīnshǒu, dànshì tā de sùdù búyàyú lǎo yuángōng.","vi":"Tuy là người mới nhưng tốc độ của anh ấy không thua nhân viên lâu năm."}],"related":[{"hanzi":"亚军","pinyin":"yàjūn","vi":"á quân"},{"hanzi":"不如","pinyin":"bùrú","vi":"không bằng"},{"hanzi":"比得上","pinyin":"bǐdeshàng","vi":"sánh được"},{"hanzi":"不次于","pinyin":"búcìyú","vi":"không kém"}],"traditional":"不亞於"},{"id":"不已","hanzi":"不已","pinyin":"bùyǐ","meaning_vi":"không ngừng, mãi không thôi","explanation":"不 (bất – không) + 已 (dĩ – dừng, thôi) → không dừng lại; đặt sau động từ chỉ cảm xúc: 感动不已, 激动不已.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"观众们感动不已。","pinyin":"Guānzhòngmen gǎndòng bùyǐ.","vi":"Khán giả xúc động mãi không thôi."},{"type":"simple","zh":"听到这个好消息，全家人激动不已。","pinyin":"Tīngdào zhè gè hǎo xiāoxi, quán jiārén jīdòng bùyǐ.","vi":"Nghe tin vui này, cả nhà xúc động không thôi."},{"type":"compound","zh":"虽然事情已经过去很久了，但是他想起来还是后悔不已。","pinyin":"Suīrán shìqing yǐjīng guòqù hěn jiǔ le, dànshì tā xiǎngqǐlái háishi hòuhuǐ bùyǐ.","vi":"Tuy chuyện đã qua lâu rồi nhưng anh ấy nghĩ lại vẫn hối hận mãi."}],"related":[{"hanzi":"不停","pinyin":"bùtíng","vi":"không ngừng"},{"hanzi":"不断","pinyin":"búduàn","vi":"liên tục"},{"hanzi":"激动","pinyin":"jīdòng","vi":"xúc động"},{"hanzi":"赞叹不已","pinyin":"zàntànbùyǐ","vi":"khen mãi không thôi"}]},{"id":"不宜","hanzi":"不宜","pinyin":"bùyí","meaning_vi":"không nên, không thích hợp","explanation":"不 (bất – không) + 宜 (nghi – thích hợp) → không thích hợp để làm gì; hay dùng trong lời khuyên, văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"孕妇不宜喝酒。","pinyin":"Yùnfù bùyí hējiǔ.","vi":"Phụ nữ mang thai không nên uống rượu."},{"type":"simple","zh":"刚吃完饭不宜马上做剧烈运动。","pinyin":"Gāng chīwán fàn bùyí mǎshàng zuò jùliè yùndòng.","vi":"Vừa ăn xong không nên vận động mạnh ngay."},{"type":"compound","zh":"即使天气很热，空调温度也不宜调得太低。","pinyin":"Jíshǐ tiānqì hěn rè, kōngtiáo wēndù yě bùyí tiáo de tài dī.","vi":"Dù trời rất nóng cũng không nên chỉnh nhiệt độ điều hòa quá thấp."}],"related":[{"hanzi":"适宜","pinyin":"shìyí","vi":"thích hợp"},{"hanzi":"不应该","pinyin":"bùyīnggāi","vi":"không nên"},{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"不适合","pinyin":"búshìhé","vi":"không phù hợp"}]},{"id":"不用说","hanzi":"不用说","pinyin":"búyòngshuō","meaning_vi":"khỏi phải nói, đương nhiên","explanation":"不用 (không cần) + 说 (nói) → không cần nói cũng rõ; dùng nhấn mạnh điều hiển nhiên.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤐","examples":[{"type":"basic","zh":"不用说，他又迟到了。","pinyin":"Búyòngshuō, tā yòu chídào le.","vi":"Khỏi phải nói, anh ta lại đến muộn."},{"type":"simple","zh":"这么好的机会，不用说大家都想参加。","pinyin":"Zhème hǎo de jīhuì, búyòngshuō dàjiā dōu xiǎng cānjiā.","vi":"Cơ hội tốt thế này, khỏi phải nói ai cũng muốn tham gia."},{"type":"compound","zh":"连老师都不会做这道题，不用说我们学生了。","pinyin":"Lián lǎoshī dōu bú huì zuò zhè dào tí, búyòngshuō wǒmen xuésheng le.","vi":"Đến thầy giáo còn không giải được bài này, nói gì đến học sinh chúng tôi."}],"related":[{"hanzi":"别说","pinyin":"biéshuō","vi":"đừng nói chi"},{"hanzi":"当然","pinyin":"dāngrán","vi":"đương nhiên"},{"hanzi":"显然","pinyin":"xiǎnrán","vi":"rõ ràng"},{"hanzi":"更不用说","pinyin":"gèngbúyòngshuō","vi":"càng khỏi phải nói"}],"traditional":"不用說"},{"id":"不正之风","hanzi":"不正之风","pinyin":"búzhèng-zhīfēng","meaning_vi":"tác phong không lành mạnh, thói xấu, tệ nạn","explanation":"不正 (bất chính – không ngay thẳng) + 之 (chi – của) + 风 (phong – phong khí, thói) → thói làm ăn, cư xử không đúng đắn trong xã hội, cơ quan.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🌪️","examples":[{"type":"basic","zh":"我们要坚决反对不正之风。","pinyin":"Wǒmen yào jiānjué fǎnduì bú zhèng zhī fēng.","vi":"Chúng ta phải kiên quyết chống lại thói xấu."},{"type":"simple","zh":"送礼请客的不正之风影响了公平竞争。","pinyin":"Sònglǐ qǐngkè de bú zhèng zhī fēng yǐngxiǎngle gōngpíng jìngzhēng.","vi":"Thói biếu quà mời mọc không lành mạnh đã ảnh hưởng đến cạnh tranh công bằng."},{"type":"compound","zh":"如果不及时纠正这种不正之风，就会损害公司的形象。","pinyin":"Rúguǒ bù jíshí jiūzhèng zhè zhǒng bú zhèng zhī fēng, jiù huì sǔnhài gōngsī de xíngxiàng.","vi":"Nếu không kịp thời uốn nắn thói xấu này thì sẽ làm tổn hại hình ảnh công ty."}],"related":[{"hanzi":"风气","pinyin":"fēngqì","vi":"phong khí"},{"hanzi":"歪风","pinyin":"wāifēng","vi":"thói xấu"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"tham nhũng"},{"hanzi":"正气","pinyin":"zhèngqì","vi":"chính khí"}],"traditional":"不正之風"},{"id":"不知","hanzi":"不知","pinyin":"bùzhī","meaning_vi":"không biết","explanation":"不 (bất – không) + 知 (tri – biết) → không biết; văn viết, hay dùng ở đầu câu hỏi gián tiếp: 不知您…","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"❓","examples":[{"type":"basic","zh":"不知他去哪儿了。","pinyin":"Bùzhī tā qùnǎr le.","vi":"Không biết anh ấy đi đâu rồi."},{"type":"simple","zh":"不知您明天上午有没有时间？","pinyin":"Bùzhī nín míngtiān shàngwǔ yǒuméiyǒu shíjiān?","vi":"Không biết sáng mai ngài có thời gian không?"},{"type":"compound","zh":"他看了半天说明书，还是不知从哪儿开始安装。","pinyin":"Tā kànle bàn tiān shuōmíngshū, háishi bùzhī cóng nǎr kāishǐ ānzhuāng.","vi":"Anh ấy đọc hướng dẫn mãi mà vẫn không biết lắp ráp từ đâu."}],"related":[{"hanzi":"不知道","pinyin":"bùzhīdào","vi":"không biết"},{"hanzi":"知道","pinyin":"zhīdao","vi":"biết"},{"hanzi":"不知不觉","pinyin":"bùzhībùjué","vi":"bất giác"},{"hanzi":"无知","pinyin":"wúzhī","vi":"vô tri"}]},{"id":"不准","hanzi":"不准","pinyin":"bùzhǔn","meaning_vi":"không được phép, cấm","explanation":"不 (bất – không) + 准 (chuẩn – cho phép) → không cho phép, cấm làm gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛔","examples":[{"type":"basic","zh":"这里不准抽烟。","pinyin":"Zhèlǐ bùzhǔn chōuyān.","vi":"Ở đây cấm hút thuốc."},{"type":"simple","zh":"妈妈不准我晚上十点以后回家。","pinyin":"Māma bùzhǔn wǒ wǎnshang shí diǎn yǐhòu huíjiā.","vi":"Mẹ không cho tôi về nhà sau mười giờ tối."},{"type":"compound","zh":"考试的时候不准带手机，否则就算作弊。","pinyin":"Kǎoshì de shíhou bùzhǔn dài shǒujī, fǒuzé jiùsuàn zuòbì.","vi":"Khi thi không được mang điện thoại, nếu không sẽ bị coi là gian lận."}],"related":[{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"},{"hanzi":"不许","pinyin":"bùxǔ","vi":"không cho"},{"hanzi":"批准","pinyin":"pīzhǔn","vi":"phê chuẩn"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"}],"traditional":"不準"},{"id":"猜谜","hanzi":"猜谜","pinyin":"cāimí","meaning_vi":"đoán câu đố, giải đố","explanation":"猜 (sai – đoán) + 谜 (mê – câu đố) → đoán câu đố; nghĩa bóng: đoán mò.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🧩","examples":[{"type":"basic","zh":"孩子们喜欢猜谜。","pinyin":"Háizimen xǐhuan cāimí.","vi":"Bọn trẻ thích giải câu đố."},{"type":"simple","zh":"元宵节晚上，大家一起看花灯、猜谜语。","pinyin":"Yuánxiāojié wǎnshang, dàjiā yìqǐ kàn huādēng, cāi míyǔ.","vi":"Tối rằm tháng Giêng, mọi người cùng ngắm đèn hoa và đoán câu đố."},{"type":"compound","zh":"你有话就直说吧，别让我在这儿猜谜了。","pinyin":"Nǐ yǒu huà jiù zhíshuō ba, bié ràng wǒ zài zhèr cāimí le.","vi":"Có gì thì cứ nói thẳng đi, đừng bắt tôi ngồi đoán mò nữa."}],"related":[{"hanzi":"谜语","pinyin":"míyǔ","vi":"câu đố"},{"hanzi":"谜底","pinyin":"mídǐ","vi":"lời giải đố"},{"hanzi":"猜","pinyin":"cāi","vi":"đoán"},{"hanzi":"灯谜","pinyin":"dēngmí","vi":"câu đố đèn lồng"}],"traditional":"猜謎"},{"id":"猜想","hanzi":"猜想","pinyin":"cāixiǎng","meaning_vi":"đoán, phỏng đoán, giả thuyết","explanation":"猜 (sai – đoán) + 想 (tưởng – nghĩ) → nghĩ và đoán chừng; danh từ: giả thuyết.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"我猜想他已经走了。","pinyin":"Wǒ cāixiǎng tā yǐjīng zǒu le.","vi":"Tôi đoán anh ấy đã đi rồi."},{"type":"simple","zh":"这只是我的猜想，还需要更多证据。","pinyin":"Zhè zhǐshì wǒ de cāixiǎng, hái xūyào gèng duō zhèngjù.","vi":"Đây chỉ là phỏng đoán của tôi, còn cần thêm chứng cứ."},{"type":"compound","zh":"既然你也猜想他不会来，那我们就先开始吧。","pinyin":"Jìrán nǐ yě cāixiǎng tā bú huì lái, nà wǒmen jiù xiān kāishǐ ba.","vi":"Nếu bạn cũng đoán anh ấy sẽ không đến thì chúng ta bắt đầu trước đi."}],"related":[{"hanzi":"猜测","pinyin":"cāicè","vi":"suy đoán"},{"hanzi":"推测","pinyin":"tuīcè","vi":"suy luận"},{"hanzi":"假设","pinyin":"jiǎshè","vi":"giả thiết"},{"hanzi":"想象","pinyin":"xiǎngxiàng","vi":"tưởng tượng"}]},{"id":"财经","hanzi":"财经","pinyin":"cáijīng","meaning_vi":"tài chính và kinh tế","explanation":"财 (tài – tiền của) + 经 (kinh – kinh tế) → lĩnh vực tài chính và kinh tế.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💹","examples":[{"type":"basic","zh":"他每天看财经新闻。","pinyin":"Tā měitiān kàn cáijīng xīnwén.","vi":"Ngày nào anh ấy cũng xem tin tài chính."},{"type":"simple","zh":"她毕业于一所有名的财经大学。","pinyin":"Tā bìyè yú yì suǒ yǒumíng de cáijīng dàxué.","vi":"Cô ấy tốt nghiệp một trường đại học tài chính kinh tế nổi tiếng."},{"type":"compound","zh":"虽然他不是学财经的，但是对股票很了解。","pinyin":"Suīrán tā bú shì xué cáijīng de, dànshì duì gǔpiào hěn liǎojiě.","vi":"Tuy anh ấy không học tài chính nhưng rất am hiểu cổ phiếu."}],"related":[{"hanzi":"财政","pinyin":"cáizhèng","vi":"tài chính"},{"hanzi":"经济","pinyin":"jīngjì","vi":"kinh tế"},{"hanzi":"金融","pinyin":"jīnróng","vi":"tài chính, tiền tệ"},{"hanzi":"财务","pinyin":"cáiwù","vi":"tài vụ"}],"traditional":"財經"},{"id":"财物","hanzi":"财物","pinyin":"cáiwù","meaning_vi":"tài sản, của cải, đồ đạc có giá trị","explanation":"财 (tài – tiền của) + 物 (vật – đồ vật) → tiền bạc và đồ đạc có giá trị.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"请保管好自己的财物。","pinyin":"Qǐng bǎoguǎn hǎo zìjǐ de cáiwù.","vi":"Xin hãy giữ gìn tài sản của mình."},{"type":"simple","zh":"小偷偷走了他家里的不少财物。","pinyin":"Xiǎo tōutōu zǒule tā jiālǐ de bùshǎo cáiwù.","vi":"Tên trộm đã lấy đi khá nhiều tài sản trong nhà anh ấy."},{"type":"compound","zh":"如果在车上丢失财物，就请联系司机。","pinyin":"Rúguǒ zài chē shang diūshī cáiwù, jiù qǐng liánxì sījī.","vi":"Nếu đánh rơi đồ đạc có giá trị trên xe thì xin liên hệ tài xế."}],"related":[{"hanzi":"财产","pinyin":"cáichǎn","vi":"tài sản"},{"hanzi":"钱财","pinyin":"qiáncái","vi":"tiền của"},{"hanzi":"物品","pinyin":"wùpǐn","vi":"đồ vật"},{"hanzi":"贵重","pinyin":"guìzhòng","vi":"quý giá"}],"traditional":"財物"},{"id":"裁","hanzi":"裁","pinyin":"cái","meaning_vi":"cắt (vải, giấy), cắt giảm","explanation":"裁 (tài – cắt may) → cắt theo kích thước; mở rộng: cắt giảm (裁员), phán xét (裁判).","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"把纸裁成两半。","pinyin":"Bǎ zhǐ cái chéng liǎng bàn.","vi":"Cắt tờ giấy làm đôi."},{"type":"simple","zh":"裁缝先量好尺寸，再开始裁布料。","pinyin":"Cáifeng xiān liáng hǎo chǐcùn, zài kāishǐ cái bùliào.","vi":"Thợ may đo kích thước trước rồi mới bắt đầu cắt vải."},{"type":"compound","zh":"因为订单减少，所以公司决定裁掉一部分员工。","pinyin":"Yīnwèi dìngdān jiǎnshǎo, suǒyǐ gōngsī juédìng cái diào yíbùfen yuángōng.","vi":"Vì đơn hàng giảm nên công ty quyết định cắt giảm một số nhân viên."}],"related":[{"hanzi":"裁员","pinyin":"cáiyuán","vi":"cắt giảm nhân sự"},{"hanzi":"裁判","pinyin":"cáipàn","vi":"trọng tài"},{"hanzi":"裁缝","pinyin":"cáifeng","vi":"thợ may"},{"hanzi":"剪","pinyin":"jiǎn","vi":"cắt"}]},{"id":"采","hanzi":"采","pinyin":"cǎi","meaning_vi":"hái, ngắt, thu thập, chọn lấy","explanation":"采 (thái – hái lượm) → hái, ngắt; mở rộng: thu thập, khai thác, lựa chọn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍃","examples":[{"type":"basic","zh":"她在山上采茶。","pinyin":"Tā zài shān shang cǎichá.","vi":"Cô ấy hái chè trên núi."},{"type":"simple","zh":"蜜蜂整天忙着在花丛中采花蜜。","pinyin":"Mìfēng zhěngtiān mángzhe zài huācóng zhōng cǎi huāmì.","vi":"Ong cả ngày bận rộn hút mật trong khóm hoa."},{"type":"compound","zh":"这些蘑菇虽然好看，但是不能随便采来吃。","pinyin":"Zhèxiē mógu suīrán hǎokàn, dànshì bù néng suíbiàn cǎi lái chī.","vi":"Mấy cây nấm này tuy đẹp nhưng không được tùy tiện hái về ăn."}],"related":[{"hanzi":"采摘","pinyin":"cǎizhāi","vi":"hái"},{"hanzi":"采集","pinyin":"cǎijí","vi":"thu thập"},{"hanzi":"采访","pinyin":"cǎifǎng","vi":"phỏng vấn"},{"hanzi":"采用","pinyin":"cǎiyòng","vi":"áp dụng"}],"traditional":"採"},{"id":"采矿","hanzi":"采矿","pinyin":"cǎikuàng","meaning_vi":"khai thác mỏ, khai khoáng","explanation":"采 (thái – khai thác) + 矿 (khoáng – mỏ, quặng) → khai thác khoáng sản.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"⛏️","examples":[{"type":"basic","zh":"这里禁止采矿。","pinyin":"Zhèlǐ jìnzhǐ cǎikuàng.","vi":"Ở đây cấm khai thác mỏ."},{"type":"simple","zh":"他在一家采矿公司当工程师。","pinyin":"Tā zài yìjiā cǎikuàng gōngsī dāng gōngchéngshī.","vi":"Anh ấy làm kỹ sư ở một công ty khai khoáng."},{"type":"compound","zh":"虽然采矿能带来收入，但是也会破坏环境。","pinyin":"Suīrán cǎikuàng néng dàilái shōurù, dànshì yě huì pòhuài huánjìng.","vi":"Tuy khai thác mỏ mang lại thu nhập nhưng cũng sẽ phá hoại môi trường."}],"related":[{"hanzi":"矿山","pinyin":"kuàngshān","vi":"mỏ"},{"hanzi":"矿工","pinyin":"kuànggōng","vi":"thợ mỏ"},{"hanzi":"开采","pinyin":"kāicǎi","vi":"khai thác"},{"hanzi":"煤矿","pinyin":"méikuàng","vi":"mỏ than"}],"traditional":"採礦"},{"id":"彩电","hanzi":"彩电","pinyin":"cǎidiàn","meaning_vi":"ti vi màu","explanation":"彩 (thái – màu sắc) + 电 (điện – nói tắt 电视, ti vi) → ti vi màu.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"📺","examples":[{"type":"basic","zh":"我家买了一台新彩电。","pinyin":"Wǒ jiā mǎile yì tái xīn cǎidiàn.","vi":"Nhà tôi mua một chiếc ti vi màu mới."},{"type":"simple","zh":"八十年代，彩电还是很贵的家用电器。","pinyin":"Bāshí niándài, cǎidiàn háishi hěn guì de jiāyòng diànqì.","vi":"Những năm tám mươi, ti vi màu vẫn còn là đồ điện gia dụng rất đắt."},{"type":"compound","zh":"以前全村只有一台彩电，所以大家都去他家看节目。","pinyin":"Yǐqián quán cūn zhǐyǒu yì tái cǎidiàn, suǒyǐ dàjiā dōu qù tā jiā kàn jiémù.","vi":"Trước kia cả làng chỉ có một chiếc ti vi màu nên mọi người đều đến nhà anh ấy xem chương trình."}],"related":[{"hanzi":"电视","pinyin":"diànshì","vi":"ti vi"},{"hanzi":"电视机","pinyin":"diànshìjī","vi":"máy thu hình"},{"hanzi":"冰箱","pinyin":"bīngxiāng","vi":"tủ lạnh"},{"hanzi":"家电","pinyin":"jiādiàn","vi":"đồ điện gia dụng"}],"traditional":"彩電"},{"id":"彩霞","hanzi":"彩霞","pinyin":"cǎixiá","meaning_vi":"ráng mây, ráng chiều","explanation":"彩 (thái – nhiều màu) + 霞 (hà – ráng mây) → mây nhuộm màu rực rỡ lúc bình minh, hoàng hôn.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌅","examples":[{"type":"basic","zh":"天边飘着彩霞。","pinyin":"Tiānbiān piāozhe cǎixiá.","vi":"Ráng mây trôi nơi chân trời."},{"type":"simple","zh":"傍晚的彩霞把整个湖面染成了红色。","pinyin":"Bàngwǎn de cǎixiá bǎ zhěnggè húmiàn rǎn chéngle hóngsè.","vi":"Ráng chiều nhuộm đỏ cả mặt hồ."},{"type":"compound","zh":"只要明天是晴天，我们就能在山顶看到彩霞。","pinyin":"Zhǐyào míngtiān shì qíngtiān, wǒmen jiù néng zài shāndǐng kàndào cǎixiá.","vi":"Chỉ cần mai trời nắng là chúng ta có thể ngắm ráng mây trên đỉnh núi."}],"related":[{"hanzi":"晚霞","pinyin":"wǎnxiá","vi":"ráng chiều"},{"hanzi":"朝霞","pinyin":"zhāoxiá","vi":"ráng sáng"},{"hanzi":"云彩","pinyin":"yúncai","vi":"mây"},{"hanzi":"夕阳","pinyin":"xīyáng","vi":"mặt trời lặn"}]},{"id":"菜市场","hanzi":"菜市场","pinyin":"càishìchǎng","meaning_vi":"chợ, chợ thực phẩm","explanation":"菜 (thái – rau, thức ăn) + 市场 (thị trường – chợ) → chợ bán rau, thịt, cá, đồ ăn tươi.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🥬","examples":[{"type":"basic","zh":"妈妈去菜市场了。","pinyin":"Māma qù càishìchǎng le.","vi":"Mẹ đi chợ rồi."},{"type":"simple","zh":"菜市场里的蔬菜比超市新鲜多了。","pinyin":"Càishìchǎng lǐ de shūcài bǐ chāoshì xīnxiān duō le.","vi":"Rau ở chợ tươi hơn siêu thị nhiều."},{"type":"compound","zh":"如果你想买活鱼，就得早点儿去菜市场。","pinyin":"Rúguǒ nǐ xiǎng mǎi huóyú, jiù děi zǎodiǎnr qù càishìchǎng.","vi":"Nếu muốn mua cá sống thì phải ra chợ sớm một chút."}],"related":[{"hanzi":"市场","pinyin":"shìchǎng","vi":"chợ, thị trường"},{"hanzi":"超市","pinyin":"chāoshì","vi":"siêu thị"},{"hanzi":"买菜","pinyin":"mǎicài","vi":"đi chợ mua thức ăn"},{"hanzi":"农贸市场","pinyin":"nóngmàoshìchǎng","vi":"chợ nông sản"}],"traditional":"菜市場"},{"id":"参见","hanzi":"参见","pinyin":"cānjiàn","meaning_vi":"xem, tham khảo; bái kiến","explanation":"参 (tham – tham khảo) + 见 (kiến – xem) → xem thêm ở chỗ khác (dùng trong sách); nghĩa cũ: vào yết kiến bề trên.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📑","examples":[{"type":"basic","zh":"详细内容请参见附录。","pinyin":"Xiángxì nèiróng qǐng cānjiàn fùlù.","vi":"Nội dung chi tiết xin xem phần phụ lục."},{"type":"simple","zh":"关于这个问题，可以参见本书第三章。","pinyin":"Guānyú zhè gè wèntí, kěyǐ cānjiàn běn shū dì sān zhāng.","vi":"Về vấn đề này có thể tham khảo chương ba của cuốn sách."},{"type":"compound","zh":"如果你还有疑问，就请参见网站上的说明。","pinyin":"Rúguǒ nǐ háiyǒu yíwèn, jiù qǐng cānjiàn wǎngzhàn shang de shuōmíng.","vi":"Nếu bạn còn thắc mắc thì xin xem phần hướng dẫn trên trang web."}],"related":[{"hanzi":"参考","pinyin":"cānkǎo","vi":"tham khảo"},{"hanzi":"参看","pinyin":"cānkàn","vi":"xem tham khảo"},{"hanzi":"拜见","pinyin":"bàijiàn","vi":"bái kiến"},{"hanzi":"参照","pinyin":"cānzhào","vi":"đối chiếu"}],"traditional":"參見"},{"id":"参军","hanzi":"参军","pinyin":"cānjūn","meaning_vi":"nhập ngũ, tòng quân","explanation":"参 (tham – tham gia) + 军 (quân – quân đội) → gia nhập quân đội.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🎖️","examples":[{"type":"basic","zh":"他十八岁就参军了。","pinyin":"Tā shíbā suì jiù cānjūn le.","vi":"Anh ấy nhập ngũ từ năm mười tám tuổi."},{"type":"simple","zh":"大学毕业以后，他决定报名参军。","pinyin":"Dàxué bìyè yǐhòu, tā juédìng bàomíng cānjūn.","vi":"Tốt nghiệp đại học xong, anh ấy quyết định đăng ký nhập ngũ."},{"type":"compound","zh":"虽然父母舍不得他走，但是还是支持他参军。","pinyin":"Suīrán fùmǔ shěbude tā zǒu, dànshì háishi zhīchí tā cānjūn.","vi":"Tuy bố mẹ không nỡ để anh đi nhưng vẫn ủng hộ anh nhập ngũ."}],"related":[{"hanzi":"军人","pinyin":"jūnrén","vi":"quân nhân"},{"hanzi":"当兵","pinyin":"dāngbīng","vi":"đi lính"},{"hanzi":"入伍","pinyin":"rùwǔ","vi":"nhập ngũ"},{"hanzi":"退伍","pinyin":"tuìwǔ","vi":"xuất ngũ"}],"traditional":"參軍"},{"id":"餐桌","hanzi":"餐桌","pinyin":"cānzhuō","meaning_vi":"bàn ăn","explanation":"餐 (xan – bữa ăn) + 桌 (trác – cái bàn) → bàn dùng để ăn cơm.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🍽️","examples":[{"type":"basic","zh":"餐桌上摆满了菜。","pinyin":"Cānzhuō shang bǎimǎnle cài.","vi":"Trên bàn ăn bày đầy thức ăn."},{"type":"simple","zh":"吃完饭以后，请把餐桌擦干净。","pinyin":"Chīwán fàn yǐhòu, qǐng bǎ cānzhuō cā gānjìng.","vi":"Ăn xong xin hãy lau sạch bàn ăn."},{"type":"compound","zh":"虽然餐桌不大，但是坐六个人也够了。","pinyin":"Suīrán cānzhuō búdà, dànshì zuò liù gè rén yě gòu le.","vi":"Tuy bàn ăn không lớn nhưng ngồi sáu người cũng đủ."}],"related":[{"hanzi":"饭桌","pinyin":"fànzhuō","vi":"bàn ăn"},{"hanzi":"餐厅","pinyin":"cāntīng","vi":"nhà hàng, phòng ăn"},{"hanzi":"桌子","pinyin":"zhuōzi","vi":"cái bàn"},{"hanzi":"餐具","pinyin":"cānjù","vi":"bộ đồ ăn"}]},{"id":"残","hanzi":"残","pinyin":"cán","meaning_vi":"tàn, hư hỏng, khuyết tật, còn sót lại","explanation":"残 (tàn – tổn hại, sót lại) → bị hư hại, không còn nguyên vẹn; thừa lại (残茶, 残雪).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥀","examples":[{"type":"basic","zh":"这本书已经残了。","pinyin":"Zhè běn shū yǐjīng cán le.","vi":"Cuốn sách này đã rách nát rồi."},{"type":"simple","zh":"那场事故使他的左腿残了。","pinyin":"Nà chǎng shìgù shǐ tā de zuǒ tuǐ cán le.","vi":"Vụ tai nạn đó khiến chân trái của anh ấy bị tật."},{"type":"compound","zh":"虽然他身体残了，但是从来没有放弃过梦想。","pinyin":"Suīrán tā shēntǐ cán le, dànshì cónglái méiyǒu fàngqìguò mèngxiǎng.","vi":"Tuy cơ thể bị khuyết tật nhưng anh ấy chưa bao giờ từ bỏ ước mơ."}],"related":[{"hanzi":"残疾","pinyin":"cánjí","vi":"tàn tật"},{"hanzi":"残酷","pinyin":"cánkù","vi":"tàn khốc"},{"hanzi":"残缺","pinyin":"cánquē","vi":"khuyết thiếu"},{"hanzi":"残忍","pinyin":"cánrěn","vi":"tàn nhẫn"}],"traditional":"殘"},{"id":"惨白","hanzi":"惨白","pinyin":"cǎnbái","meaning_vi":"trắng bệch, tái nhợt","explanation":"惨 (thảm – thê thảm) + 白 (bạch – trắng) → trắng một cách đáng sợ, thường tả sắc mặt khi sợ hãi, ốm yếu.","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"😨","examples":[{"type":"basic","zh":"他的脸色惨白。","pinyin":"Tā de liǎnsè cǎnbái.","vi":"Sắc mặt anh ấy trắng bệch."},{"type":"simple","zh":"听到这个消息，她吓得脸都惨白了。","pinyin":"Tīngdào zhè gè xiāoxi, tā xià de liǎn dōu cǎnbái le.","vi":"Nghe tin này, cô ấy sợ đến tái mét cả mặt."},{"type":"compound","zh":"因为一夜没睡，所以他的脸色惨白惨白的。","pinyin":"Yīnwèi yí yè méi shuì, suǒyǐ tā de liǎnsè cǎnbái cǎnbái de.","vi":"Vì thức trắng cả đêm nên mặt anh ấy tái nhợt."}],"related":[{"hanzi":"苍白","pinyin":"cāngbái","vi":"nhợt nhạt"},{"hanzi":"脸色","pinyin":"liǎnsè","vi":"sắc mặt"},{"hanzi":"雪白","pinyin":"xuěbái","vi":"trắng như tuyết"},{"hanzi":"惨","pinyin":"cǎn","vi":"thê thảm"}],"traditional":"慘白"},{"id":"掺","hanzi":"掺","pinyin":"chān","meaning_vi":"pha, trộn lẫn","explanation":"掺 (sam – pha trộn) → trộn thứ này vào thứ khác, thường là pha lẫn tạp chất.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥣","examples":[{"type":"basic","zh":"酒里掺了水。","pinyin":"Jiǔ lǐ chānle shuǐ.","vi":"Rượu bị pha nước."},{"type":"simple","zh":"做馒头的时候可以在面粉里掺一点儿玉米粉。","pinyin":"Zuò mántou de shíhou kěyǐ zài miànfěn lǐ chān yìdiǎnr yùmǐfěn.","vi":"Khi làm màn thầu có thể trộn một ít bột ngô vào bột mì."},{"type":"compound","zh":"如果在沙子里掺水泥，就能让地面更结实。","pinyin":"Rúguǒ zài shāzi lǐ chān shuǐní, jiù néng ràng dìmiàn gèng jiēshi.","vi":"Nếu trộn xi măng vào cát thì có thể làm mặt đất chắc hơn."}],"related":[{"hanzi":"掺杂","pinyin":"chānzá","vi":"trộn lẫn"},{"hanzi":"混合","pinyin":"hùnhé","vi":"hỗn hợp"},{"hanzi":"搀和","pinyin":"chānhuo","vi":"pha trộn"},{"hanzi":"拌","pinyin":"bàn","vi":"trộn"}],"traditional":"摻"},{"id":"藏品","hanzi":"藏品","pinyin":"cángpǐn","meaning_vi":"hiện vật sưu tầm, đồ sưu tập","explanation":"藏 (tàng – cất giữ) + 品 (phẩm – vật phẩm) → đồ vật được sưu tầm, cất giữ (bảo tàng, nhà sưu tập).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"这些藏品很珍贵。","pinyin":"Zhèxiē cángpǐn hěn zhēnguì.","vi":"Những hiện vật này rất quý."},{"type":"simple","zh":"博物馆展出了一百多件古代藏品。","pinyin":"Bówùguǎn zhǎnchūle yī bǎi duō jiàn gǔdài cángpǐn.","vi":"Bảo tàng trưng bày hơn một trăm hiện vật cổ."},{"type":"compound","zh":"虽然这件藏品很小，但是价值上百万。","pinyin":"Suīrán zhè jiàn cángpǐn hěn xiǎo, dànshì jiàzhí shàng bǎiwàn.","vi":"Tuy món đồ sưu tầm này nhỏ nhưng giá trị lên tới cả triệu."}],"related":[{"hanzi":"收藏","pinyin":"shōucáng","vi":"sưu tầm"},{"hanzi":"珍藏","pinyin":"zhēncáng","vi":"cất giữ quý"},{"hanzi":"文物","pinyin":"wénwù","vi":"văn vật"},{"hanzi":"展品","pinyin":"zhǎnpǐn","vi":"vật trưng bày"}]},{"id":"藏身","hanzi":"藏身","pinyin":"cángshēn","meaning_vi":"ẩn náu, trốn","explanation":"藏 (tàng – giấu) + 身 (thân – thân mình) → giấu mình, ẩn náu ở đâu đó.","hsk_level":"7-9","tags":["dong-tu"],"image":"🫣","examples":[{"type":"basic","zh":"小猫藏身在床下。","pinyin":"Xiǎomāo cángshēn zài chuáng xià.","vi":"Con mèo con trốn dưới gầm giường."},{"type":"simple","zh":"逃犯藏身在山里的一个小木屋中。","pinyin":"Táofàn cángshēn zài shān lǐ de yí gè xiǎo mù wū zhōng.","vi":"Tên tội phạm bỏ trốn ẩn náu trong một căn nhà gỗ nhỏ trên núi."},{"type":"compound","zh":"即使他藏身在别的城市，警察也很快找到了他。","pinyin":"Jíshǐ tā cángshēn zài biéde chéngshì, jǐngchá yě hěn kuài zhǎodàole tā.","vi":"Dù hắn trốn ở thành phố khác, cảnh sát cũng nhanh chóng tìm ra."}],"related":[{"hanzi":"躲藏","pinyin":"duǒcáng","vi":"trốn tránh"},{"hanzi":"藏身之处","pinyin":"cángshēnzhīchù","vi":"chỗ ẩn náu"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"躲","pinyin":"duǒ","vi":"trốn"}]},{"id":"操控","hanzi":"操控","pinyin":"cāokòng","meaning_vi":"điều khiển, thao túng","explanation":"操 (thao – cầm nắm, điều khiển) + 控 (khống – khống chế) → điều khiển máy móc; nghĩa xấu: thao túng.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🎮","examples":[{"type":"basic","zh":"他会操控无人机。","pinyin":"Tā huì cāokòng wúrénjī.","vi":"Anh ấy biết điều khiển máy bay không người lái."},{"type":"simple","zh":"这台机器可以用手机远程操控。","pinyin":"Zhè tái jīqì kěyǐ yòng shǒujī yuǎnchéng cāokòng.","vi":"Chiếc máy này có thể điều khiển từ xa bằng điện thoại."},{"type":"compound","zh":"一旦市场被少数人操控，普通投资者就会受到损失。","pinyin":"Yídàn shìchǎng bèi shǎoshù rén cāokòng, pǔtōng tóuzīzhě jiù huì shòudào sǔnshī.","vi":"Một khi thị trường bị số ít người thao túng, nhà đầu tư bình thường sẽ chịu thiệt hại."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"khống chế"},{"hanzi":"操纵","pinyin":"cāozòng","vi":"thao túng"},{"hanzi":"操作","pinyin":"cāozuò","vi":"thao tác"},{"hanzi":"遥控","pinyin":"yáokòng","vi":"điều khiển từ xa"}]},{"id":"槽","hanzi":"槽","pinyin":"cáo","meaning_vi":"máng, rãnh, khe","explanation":"槽 (tào – máng ăn) → máng đựng thức ăn gia súc; mở rộng: rãnh, khe lõm.","hsk_level":"7-9","tags":["danh-tu"],"image":"🕳️","examples":[{"type":"basic","zh":"马在槽边吃草。","pinyin":"Mǎ zài cáo biān chīcǎo.","vi":"Con ngựa ăn cỏ bên máng."},{"type":"simple","zh":"这块木板中间有一条深深的槽。","pinyin":"Zhè kuài mùbǎn zhōngjiān yǒu yì tiáo shēnshēn de cáo.","vi":"Giữa tấm gỗ này có một đường rãnh sâu."},{"type":"compound","zh":"只要把卡片插进这个槽里，机器就会自动读取。","pinyin":"Zhǐyào bǎ kǎpiàn chājìn zhè gè cáo lǐ, jīqì jiù huì zìdòng dúqǔ.","vi":"Chỉ cần cắm thẻ vào khe này là máy sẽ tự động đọc."}],"related":[{"hanzi":"水槽","pinyin":"shuǐcáo","vi":"bồn rửa"},{"hanzi":"跳槽","pinyin":"tiàocáo","vi":"nhảy việc"},{"hanzi":"吐槽","pinyin":"tǔcáo","vi":"than phiền, chê"},{"hanzi":"沟","pinyin":"gōu","vi":"rãnh"}]},{"id":"蹭","hanzi":"蹭","pinyin":"cèng","meaning_vi":"cọ, quẹt; ăn ké, đi ké","explanation":"蹭 (tặng – cọ xát) → cọ, quẹt vào; khẩu ngữ: lợi dụng để hưởng ké (蹭饭, 蹭车).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐈","examples":[{"type":"basic","zh":"小猫一直在我腿上蹭来蹭去。","pinyin":"Xiǎomāo yìzhí zài wǒ tuǐ shang cèng lái cèng qù.","vi":"Con mèo con cọ qua cọ lại vào chân tôi."},{"type":"simple","zh":"他一没钱就到朋友家蹭饭。","pinyin":"Tā yì méi qián jiù dào péngyou jiā cèngfàn.","vi":"Anh ta cứ hết tiền là đến nhà bạn ăn chực."},{"type":"compound","zh":"我的车虽然只被蹭了一下，但是修起来要花不少钱。","pinyin":"Wǒ de chē suīrán zhǐ bèi cèngle yíxià, dànshì xiū qǐlái yào huā bùshǎo qián.","vi":"Xe tôi tuy chỉ bị quẹt nhẹ một cái nhưng sửa thì tốn khá nhiều tiền."}],"related":[{"hanzi":"蹭饭","pinyin":"cèngfàn","vi":"ăn chực"},{"hanzi":"蹭车","pinyin":"cèngchē","vi":"đi xe ké"},{"hanzi":"摩擦","pinyin":"mócā","vi":"ma sát"},{"hanzi":"擦","pinyin":"cā","vi":"lau, cọ"}]},{"id":"插手","hanzi":"插手","pinyin":"chāshǒu","meaning_vi":"nhúng tay, can thiệp","explanation":"插 (sáp – cắm vào) + 手 (thủ – tay) → thò tay vào; can dự vào việc người khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"✋","examples":[{"type":"basic","zh":"这件事你别插手。","pinyin":"Zhè jiàn shì nǐ bié chāshǒu.","vi":"Việc này anh đừng nhúng tay vào."},{"type":"simple","zh":"父母不应该过多插手孩子的婚姻。","pinyin":"Fùmǔ bù yīnggāi guòduō chāshǒu háizi de hūnyīn.","vi":"Cha mẹ không nên can thiệp quá nhiều vào hôn nhân của con cái."},{"type":"compound","zh":"如果你随便插手别人的家事，就可能引起误会。","pinyin":"Rúguǒ nǐ suíbiàn chāshǒu biérén de jiāshì, jiù kěnéng yǐnqǐ wùhuì.","vi":"Nếu bạn tùy tiện nhúng tay vào chuyện nhà người khác thì có thể gây hiểu lầm."}],"related":[{"hanzi":"干涉","pinyin":"gānshè","vi":"can thiệp"},{"hanzi":"插嘴","pinyin":"chāzuǐ","vi":"xen vào nói"},{"hanzi":"过问","pinyin":"guòwèn","vi":"hỏi đến"},{"hanzi":"管闲事","pinyin":"guǎnxiánshì","vi":"lo chuyện bao đồng"}]},{"id":"插图","hanzi":"插图","pinyin":"chātú","meaning_vi":"tranh minh họa","explanation":"插 (sáp – chèn vào) + 图 (đồ – hình vẽ) → hình vẽ chèn vào sách, báo.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🖼️","examples":[{"type":"basic","zh":"这本书有很多插图。","pinyin":"Zhè běn shū yǒu hěn duō chātú.","vi":"Cuốn sách này có rất nhiều tranh minh họa."},{"type":"simple","zh":"她专门给儿童读物画插图。","pinyin":"Tā zhuānmén gěi értóng dúwù huà chātú.","vi":"Cô ấy chuyên vẽ tranh minh họa cho sách thiếu nhi."},{"type":"compound","zh":"因为书里的插图很生动，所以孩子们都爱看。","pinyin":"Yīnwèi shū lǐ de chātú hěn shēngdòng, suǒyǐ háizimen dōu ài kàn.","vi":"Vì tranh minh họa trong sách rất sinh động nên bọn trẻ đều thích xem."}],"related":[{"hanzi":"图片","pinyin":"túpiàn","vi":"hình ảnh"},{"hanzi":"插画","pinyin":"chāhuà","vi":"tranh minh họa"},{"hanzi":"封面","pinyin":"fēngmiàn","vi":"bìa sách"},{"hanzi":"图画","pinyin":"túhuà","vi":"tranh vẽ"}],"traditional":"插圖"},{"id":"查找","hanzi":"查找","pinyin":"cházhǎo","meaning_vi":"tra tìm, tìm kiếm","explanation":"查 (tra – tra xét) + 找 (trảo – tìm) → tra cứu để tìm ra thông tin, đồ vật.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"我在网上查找资料。","pinyin":"Wǒ zài wǎngshang cházhǎo zīliào.","vi":"Tôi tìm tài liệu trên mạng."},{"type":"simple","zh":"你可以用这个功能查找文件里的关键词。","pinyin":"Nǐ kěyǐ yòng zhè gè gōngnéng cházhǎo wénjiàn lǐ de guānjiàncí.","vi":"Bạn có thể dùng chức năng này để tìm từ khóa trong tệp."},{"type":"compound","zh":"虽然大家查找了一整天，但是还是没找到问题的原因。","pinyin":"Suīrán dàjiā cházhǎole yìzhěngtiān, dànshì háishi méi zhǎodào wèntí de yuányīn.","vi":"Tuy mọi người tìm kiếm cả ngày nhưng vẫn không tìm ra nguyên nhân của vấn đề."}],"related":[{"hanzi":"寻找","pinyin":"xúnzhǎo","vi":"tìm kiếm"},{"hanzi":"搜索","pinyin":"sōusuǒ","vi":"tìm kiếm"},{"hanzi":"查询","pinyin":"cháxún","vi":"tra cứu"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"}]},{"id":"茶馆儿","hanzi":"茶馆儿","pinyin":"cháguǎnr","meaning_vi":"quán trà","explanation":"茶 (trà) + 馆儿 (quán – nơi phục vụ) → quán bán trà, nơi người ta ngồi uống trà, trò chuyện.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🍵","examples":[{"type":"basic","zh":"我们去茶馆儿坐坐吧。","pinyin":"Wǒmen qù cháguǎnr zuò zuo ba.","vi":"Chúng ta đi quán trà ngồi một lát nhé."},{"type":"simple","zh":"爷爷每天早上都去茶馆儿喝茶聊天。","pinyin":"Yéye měitiān zǎo Shangdōu qù cháguǎnr hēchá liáotiān.","vi":"Sáng nào ông cũng đến quán trà uống trà tán gẫu."},{"type":"compound","zh":"虽然那家茶馆儿很旧，但是来的客人特别多。","pinyin":"Suīrán nà jiā cháguǎnr hěn jiù, dànshì lái de kèrén tèbié duō.","vi":"Tuy quán trà đó cũ kỹ nhưng khách đến rất đông."}],"related":[{"hanzi":"茶馆","pinyin":"cháguǎn","vi":"quán trà"},{"hanzi":"茶叶","pinyin":"cháyè","vi":"lá trà"},{"hanzi":"饭馆儿","pinyin":"fànguǎnr","vi":"quán ăn"},{"hanzi":"咖啡馆","pinyin":"kāfēiguǎn","vi":"quán cà phê"}],"traditional":"茶館兒"},{"id":"察看","hanzi":"察看","pinyin":"chákàn","meaning_vi":"quan sát kỹ, xem xét","explanation":"察 (sát – xét kỹ) + 看 (khán – nhìn) → nhìn kỹ để nắm tình hình.","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"医生察看了伤口。","pinyin":"Yīshēng chákànle shāngkǒu.","vi":"Bác sĩ xem xét vết thương."},{"type":"simple","zh":"台风过后，村长挨家挨户察看损失情况。","pinyin":"Táifēng guòhòu, cūnzhǎng āijiā'āihù chákàn sǔnshī qíngkuàng.","vi":"Sau cơn bão, trưởng thôn đến từng nhà xem xét tình hình thiệt hại."},{"type":"compound","zh":"即使机器看起来正常，也要定期察看一下。","pinyin":"Jíshǐ jīqì kànqǐlái zhèngcháng, yě yào dìngqī chákàn yíxià.","vi":"Dù máy móc trông có vẻ bình thường cũng phải định kỳ kiểm tra."}],"related":[{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"查看","pinyin":"chákàn","vi":"xem xét"},{"hanzi":"视察","pinyin":"shìchá","vi":"thị sát"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"}]},{"id":"差额","hanzi":"差额","pinyin":"chā'é","meaning_vi":"khoản chênh lệch, số tiền chênh","explanation":"差 (sai – chênh lệch) + 额 (ngạch – mức, số lượng) → phần chênh lệch giữa hai con số.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"➖","examples":[{"type":"basic","zh":"差额由我来补。","pinyin":"Chā'é yóu wǒ lái bǔ.","vi":"Khoản chênh lệch để tôi bù."},{"type":"simple","zh":"两种方案的费用差额大概是两千元。","pinyin":"Liǎng zhǒng fāng'àn de fèiyòng chā'é dàgài shì liǎng qiān yuán.","vi":"Chênh lệch chi phí giữa hai phương án khoảng hai nghìn tệ."},{"type":"compound","zh":"如果新手机比旧的贵，你只要付差额就行了。","pinyin":"Rúguǒ xīnshǒu jī bǐ jiù de guì, nǐ zhǐyào fù chā'é jiù xíng le.","vi":"Nếu điện thoại mới đắt hơn cái cũ thì bạn chỉ cần trả phần chênh lệch là được."}],"related":[{"hanzi":"差价","pinyin":"chājià","vi":"chênh lệch giá"},{"hanzi":"差距","pinyin":"chājù","vi":"khoảng cách"},{"hanzi":"余额","pinyin":"yú'é","vi":"số dư"},{"hanzi":"金额","pinyin":"jīn'é","vi":"số tiền"}],"traditional":"差額"},{"id":"禅杖","hanzi":"禅杖","pinyin":"chánzhàng","meaning_vi":"thiền trượng, gậy của nhà sư","explanation":"禅 (thiền – nhà Phật) + 杖 (trượng – cây gậy) → cây gậy nhà sư mang theo.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🦯","examples":[{"type":"basic","zh":"老和尚拄着禅杖。","pinyin":"Lǎo héshang zhǔzhe chánzhàng.","vi":"Vị sư già chống thiền trượng."},{"type":"simple","zh":"小说里的鲁智深手里总是拿着一根禅杖。","pinyin":"Xiǎoshuō lǐ de lǔ zhì shēn shǒulǐ zǒngshì názhe yìgēn chánzhàng.","vi":"Lỗ Trí Thâm trong tiểu thuyết lúc nào cũng cầm một cây thiền trượng."},{"type":"compound","zh":"虽然这根禅杖很重，但是他拿起来毫不费力。","pinyin":"Suīrán zhè gēn chánzhàng hěn zhòng, dànshì tā ná qǐlái háobú fèilì.","vi":"Tuy cây thiền trượng này rất nặng nhưng ông ấy cầm lên chẳng tốn sức."}],"related":[{"hanzi":"和尚","pinyin":"héshang","vi":"nhà sư"},{"hanzi":"拐杖","pinyin":"guǎizhàng","vi":"gậy chống"},{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"禅","pinyin":"chán","vi":"thiền"}],"traditional":"禪杖"},{"id":"缠","hanzi":"缠","pinyin":"chán","meaning_vi":"quấn, cuốn; đeo bám","explanation":"缠 (triền – quấn quanh) → quấn vòng quanh vật gì; nghĩa bóng: bám riết, quấy rầy.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧶","examples":[{"type":"basic","zh":"他手上缠着绷带。","pinyin":"Tā shǒushang chánzhe bēngdài.","vi":"Tay anh ấy quấn băng."},{"type":"simple","zh":"孩子一直缠着妈妈，要她讲故事。","pinyin":"Háizi yìzhí chánzhe māma, yào tā jiǎng gùshi.","vi":"Đứa bé cứ bám lấy mẹ, đòi mẹ kể chuyện."},{"type":"compound","zh":"如果耳机线缠在一起，就很难解开了。","pinyin":"Rúguǒ ěrjī xiàn chán zài yìqǐ, jiù hěn nán jiěkāi le.","vi":"Nếu dây tai nghe bị cuốn rối vào nhau thì rất khó gỡ ra."}],"related":[{"hanzi":"缠绕","pinyin":"chánrào","vi":"quấn quanh"},{"hanzi":"纠缠","pinyin":"jiūchán","vi":"quấy rầy"},{"hanzi":"难缠","pinyin":"nánchán","vi":"khó chơi"},{"hanzi":"绕","pinyin":"rào","vi":"vòng quanh"}],"traditional":"纏"},{"id":"产","hanzi":"产","pinyin":"chǎn","meaning_vi":"sinh, đẻ; sản xuất, sản ra","explanation":"产 (sản – sinh ra) → sinh đẻ; mở rộng: làm ra sản phẩm, có xuất xứ ở đâu (产于…).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏭","examples":[{"type":"basic","zh":"这里盛产苹果。","pinyin":"Zhèlǐ shèngchǎn píngguǒ.","vi":"Nơi đây sản xuất nhiều táo."},{"type":"simple","zh":"这种茶产于云南的高山上。","pinyin":"Zhè zhǒng chá chǎn yú Yúnnán de gāoshān shang.","vi":"Loại trà này được sản xuất trên vùng núi cao Vân Nam."},{"type":"compound","zh":"因为今年雨水充足，所以每亩地多产了两百斤粮食。","pinyin":"Yīnwèi jīnnián yǔshuǐ chōngzú, suǒyǐ měi mǔ dì duōchǎnle liǎng bǎi jīn liángshi.","vi":"Vì năm nay mưa đầy đủ nên mỗi mẫu ruộng sản xuất thêm hai trăm cân lương thực."}],"related":[{"hanzi":"生产","pinyin":"shēngchǎn","vi":"sản xuất"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"},{"hanzi":"出产","pinyin":"chūchǎn","vi":"sản xuất ra"},{"hanzi":"产量","pinyin":"chǎnliàng","vi":"sản lượng"}],"traditional":"產"},{"id":"产地","hanzi":"产地","pinyin":"chǎndì","meaning_vi":"nơi sản xuất, xuất xứ","explanation":"产 (sản – sản xuất) + 地 (địa – nơi) → nơi làm ra hoặc nuôi trồng sản phẩm.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏷️","examples":[{"type":"basic","zh":"这瓶酒的产地是法国。","pinyin":"Zhè píng jiǔ de chǎndì shì Fǎguó.","vi":"Xuất xứ của chai rượu này là Pháp."},{"type":"simple","zh":"买水果的时候，最好看一下产地。","pinyin":"Mǎi shuǐguǒ de shíhou, zuì hǎokàn yíxià chǎndì.","vi":"Khi mua hoa quả tốt nhất nên xem nơi sản xuất."},{"type":"compound","zh":"虽然产地不同，但是这两种大米的味道差不多。","pinyin":"Suīrán chǎndì bùtóng, dànshì zhè liǎng zhǒng dàmǐ de wèidao chàbuduō.","vi":"Tuy xuất xứ khác nhau nhưng mùi vị hai loại gạo này gần như nhau."}],"related":[{"hanzi":"原产地","pinyin":"yuánchǎndì","vi":"nơi xuất xứ"},{"hanzi":"出产","pinyin":"chūchǎn","vi":"sản xuất ra"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"}],"traditional":"產地"},{"id":"铲","hanzi":"铲","pinyin":"chǎn","meaning_vi":"xúc, xẻng; san phẳng, trừ bỏ","explanation":"铲 (sản – cái xẻng) → dùng xẻng xúc, cào; nghĩa bóng: diệt trừ tận gốc (铲除).","hsk_level":"7-9","tags":["dong-tu"],"image":"🪏","examples":[{"type":"basic","zh":"他在门口铲雪。","pinyin":"Tā zài ménkǒu chǎn xuě.","vi":"Anh ấy xúc tuyết ở trước cửa."},{"type":"simple","zh":"工人们用了一上午才把路上的沙土铲干净。","pinyin":"Gōngrénmen yòngle yí shàngwǔ cái bǎ lùshang de shātǔ chǎn gānjìng.","vi":"Công nhân mất cả buổi sáng mới xúc sạch cát đất trên đường."},{"type":"compound","zh":"如果不把这些杂草铲掉，就会影响庄稼生长。","pinyin":"Rúguǒ bù bǎ zhèxiē zácǎo chǎn diào, jiù huì yǐngxiǎng zhuāngjia shēngzhǎng.","vi":"Nếu không giẫy sạch đám cỏ dại này thì sẽ ảnh hưởng đến sự phát triển của cây trồng."}],"related":[{"hanzi":"铲子","pinyin":"chǎnzi","vi":"cái xẻng"},{"hanzi":"铲除","pinyin":"chǎnchú","vi":"diệt trừ"},{"hanzi":"挖","pinyin":"wā","vi":"đào"},{"hanzi":"锄","pinyin":"chú","vi":"cuốc"}],"traditional":"鏟"},{"id":"铲子","hanzi":"铲子","pinyin":"chǎnzi","meaning_vi":"cái xẻng; cái sạn (nấu bếp)","explanation":"铲 (sản – xẻng) + 子 (tử – hậu tố danh từ) → cái xẻng; trong bếp là cái sạn để đảo thức ăn.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪏","examples":[{"type":"basic","zh":"把铲子递给我。","pinyin":"Bǎ chǎnzi dìgěi wǒ.","vi":"Đưa cái xẻng cho tôi."},{"type":"simple","zh":"妈妈用铲子把鸡蛋翻了过来。","pinyin":"Māma yòng chǎnzi bǎ jīdàn fānle guòlái.","vi":"Mẹ dùng sạn lật quả trứng lại."},{"type":"compound","zh":"虽然孩子们只有小铲子，但是很快就挖好了一个沙坑。","pinyin":"Suīrán háizimen zhǐyǒu xiǎochǎnzi, dànshì hěn kuài jiù wā hǎole yí gè shākēng.","vi":"Tuy bọn trẻ chỉ có xẻng nhỏ nhưng đã nhanh chóng đào xong một hố cát."}],"related":[{"hanzi":"铲","pinyin":"chǎn","vi":"xúc"},{"hanzi":"锅铲","pinyin":"guōchǎn","vi":"sạn nấu ăn"},{"hanzi":"锄头","pinyin":"chútou","vi":"cái cuốc"},{"hanzi":"工具","pinyin":"gōngjù","vi":"dụng cụ"}],"traditional":"鏟子"},{"id":"常人","hanzi":"常人","pinyin":"chángrén","meaning_vi":"người thường, người bình thường","explanation":"常 (thường – bình thường) + 人 (nhân – người) → người bình thường, đa số mọi người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧍","examples":[{"type":"basic","zh":"他有常人没有的耐心。","pinyin":"Tā yǒu chángrén méiyǒu de nàixīn.","vi":"Anh ấy có sự kiên nhẫn mà người thường không có."},{"type":"simple","zh":"这种训练强度是常人难以承受的。","pinyin":"Zhè zhǒng xùnliàn qiángdù shì chángrén nányǐ chéngshòu de.","vi":"Cường độ luyện tập này người bình thường khó mà chịu nổi."},{"type":"compound","zh":"虽然她看不见，但是生活能力一点儿也不比常人差。","pinyin":"Suīrán tā kànbujiàn, dànshì shēnghuó nénglì yìdiǎnr yě bùbǐ chángrén chà.","vi":"Tuy cô ấy không nhìn thấy nhưng khả năng tự lo cuộc sống chẳng kém gì người thường."}],"related":[{"hanzi":"普通人","pinyin":"pǔtōngrén","vi":"người bình thường"},{"hanzi":"平常","pinyin":"píngcháng","vi":"bình thường"},{"hanzi":"常识","pinyin":"chángshí","vi":"thường thức"},{"hanzi":"凡人","pinyin":"fánrén","vi":"người phàm"}]},{"id":"常温","hanzi":"常温","pinyin":"chángwēn","meaning_vi":"nhiệt độ thường, nhiệt độ phòng","explanation":"常 (thường – bình thường) + 温 (ôn – nhiệt độ) → nhiệt độ bình thường trong phòng (khoảng 15–25°C).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌡️","examples":[{"type":"basic","zh":"这种牛奶可以常温保存。","pinyin":"Zhè zhǒng niúnǎi kěyǐ chángwēn bǎocún.","vi":"Loại sữa này có thể bảo quản ở nhiệt độ thường."},{"type":"simple","zh":"蛋糕在常温下只能放一天。","pinyin":"Dàngāo zài chángwēn xià zhǐnéng fàng yì tiān.","vi":"Bánh ngọt ở nhiệt độ phòng chỉ để được một ngày."},{"type":"compound","zh":"如果药品要求常温保存，就不要放进冰箱。","pinyin":"Rúguǒ yàopǐn yāoqiú chángwēn bǎocún, jiù bú yào fàngjìn bīngxiāng.","vi":"Nếu thuốc yêu cầu bảo quản ở nhiệt độ thường thì đừng cho vào tủ lạnh."}],"related":[{"hanzi":"室温","pinyin":"shìwēn","vi":"nhiệt độ phòng"},{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"低温","pinyin":"dīwēn","vi":"nhiệt độ thấp"},{"hanzi":"高温","pinyin":"gāowēn","vi":"nhiệt độ cao"}],"traditional":"常溫"},{"id":"嫦娥","hanzi":"嫦娥","pinyin":"Cháng'é","meaning_vi":"Hằng Nga (chị Hằng)","explanation":"嫦娥 (Hằng Nga) → nàng tiên sống trên cung trăng trong truyền thuyết Trung Quốc; cũng là tên chương trình thám hiểm Mặt Trăng của Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🌕","examples":[{"type":"basic","zh":"嫦娥住在月亮上。","pinyin":"Cháng'é zhùzài yuèliang shang.","vi":"Hằng Nga sống trên mặt trăng."},{"type":"simple","zh":"中秋节的时候，奶奶总给我们讲嫦娥的故事。","pinyin":"Zhōngqiūjié de shíhou, nǎinai zǒng gěi wǒmen jiǎng Cháng'é de gùshi.","vi":"Mỗi dịp Trung thu, bà lại kể cho chúng tôi nghe chuyện Hằng Nga."},{"type":"compound","zh":"虽然嫦娥奔月只是传说，但是人类真的登上了月球。","pinyin":"Suīrán Cháng'é bēnyuè zhǐshì chuánshuō, dànshì rénlèi zhēn de dēngshàngle yuèqiú.","vi":"Tuy Hằng Nga bay lên cung trăng chỉ là truyền thuyết nhưng con người đã thật sự đặt chân lên Mặt Trăng."}],"related":[{"hanzi":"月亮","pinyin":"yuèliang","vi":"mặt trăng"},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vi":"Tết Trung thu"},{"hanzi":"玉兔","pinyin":"yùtù","vi":"thỏ ngọc"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"}]},{"id":"厂家","hanzi":"厂家","pinyin":"chǎngjiā","meaning_vi":"nhà sản xuất, nhà máy","explanation":"厂 (xưởng – nhà máy) + 家 (gia – đơn vị, nhà) → doanh nghiệp, nhà máy sản xuất ra sản phẩm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"我们直接从厂家进货。","pinyin":"Wǒmen zhíjiē cóng chǎngjiā jìnhuò.","vi":"Chúng tôi nhập hàng trực tiếp từ nhà sản xuất."},{"type":"simple","zh":"产品有质量问题，可以找厂家退换。","pinyin":"Chǎnpǐn yǒu zhìliàng wèntí, kěyǐ zhǎo chǎngjiā tuìhuàn.","vi":"Sản phẩm có vấn đề về chất lượng thì có thể tìm nhà sản xuất để đổi trả."},{"type":"compound","zh":"因为厂家直接销售，所以价格比商店便宜很多。","pinyin":"Yīnwèi chǎngjiā zhíjiē xiāoshòu, suǒyǐ jiàgé bǐ shāngdiàn piányi hěn duō.","vi":"Vì nhà sản xuất bán trực tiếp nên giá rẻ hơn cửa hàng nhiều."}],"related":[{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"nhà máy"},{"hanzi":"厂商","pinyin":"chǎngshāng","vi":"nhà sản xuất"},{"hanzi":"生产","pinyin":"shēngchǎn","vi":"sản xuất"},{"hanzi":"商家","pinyin":"shāngjiā","vi":"người bán"}],"traditional":"廠家"},{"id":"抄袭","hanzi":"抄袭","pinyin":"chāoxí","meaning_vi":"đạo văn, sao chép, ăn cắp ý tưởng","explanation":"抄 (sao – chép) + 袭 (tập – theo, noi theo) → chép lại tác phẩm, ý tưởng của người khác làm của mình.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"他的论文是抄袭的。","pinyin":"Tā de lùnwén shì chāoxí de.","vi":"Luận văn của anh ta là đạo văn."},{"type":"simple","zh":"这家公司被指控抄袭别人的设计。","pinyin":"Zhè jiā gōngsī bèi zhǐkòng chāoxí biérén de shèjì.","vi":"Công ty này bị cáo buộc sao chép thiết kế của người khác."},{"type":"compound","zh":"一旦被发现抄袭，作者就会失去读者的信任。","pinyin":"Yídàn bèi fāxiàn chāoxí, zuòzhě jiù huì shīqù dúzhě de xìnrèn.","vi":"Một khi bị phát hiện đạo văn, tác giả sẽ mất lòng tin của độc giả."}],"related":[{"hanzi":"抄","pinyin":"chāo","vi":"chép"},{"hanzi":"复制","pinyin":"fùzhì","vi":"sao chép"},{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"},{"hanzi":"原创","pinyin":"yuánchuàng","vi":"nguyên tác"}],"traditional":"抄襲"},{"id":"超车","hanzi":"超车","pinyin":"chāochē","meaning_vi":"vượt xe","explanation":"超 (siêu – vượt qua) + 车 (xa – xe) → lái xe vượt lên xe phía trước.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"这里不能超车。","pinyin":"Zhèlǐ bù néng chāochē.","vi":"Ở đây không được vượt xe."},{"type":"simple","zh":"那辆卡车在弯道上强行超车。","pinyin":"Nà liàng kǎchē zài wāndào shang qiángxíng chāochē.","vi":"Chiếc xe tải đó cố tình vượt xe ở khúc cua."},{"type":"compound","zh":"如果你想在这条路上超车，就要先打转向灯。","pinyin":"Rúguǒ nǐ xiǎng zài zhè tiáo lùshang chāochē, jiùyào xiān dǎ zhuǎnxiàngdēng.","vi":"Nếu bạn muốn vượt xe trên con đường này thì phải bật xi nhan trước."}],"related":[{"hanzi":"超速","pinyin":"chāosù","vi":"chạy quá tốc độ"},{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt qua"},{"hanzi":"车道","pinyin":"chēdào","vi":"làn xe"},{"hanzi":"违章","pinyin":"wéizhāng","vi":"vi phạm luật"}],"traditional":"超車"},{"id":"超速","hanzi":"超速","pinyin":"chāosù","meaning_vi":"vượt quá tốc độ, chạy quá tốc độ","explanation":"超 (siêu – vượt quá) + 速 (tốc – tốc độ) → vượt quá tốc độ cho phép.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚨","examples":[{"type":"basic","zh":"他开车超速了。","pinyin":"Tā kāichē chāosù le.","vi":"Anh ấy lái xe quá tốc độ."},{"type":"simple","zh":"因为超速，他被罚了两百块钱。","pinyin":"Yīnwèi chāosù, tā bèi fále liǎng bǎi kuài qián.","vi":"Vì chạy quá tốc độ, anh ấy bị phạt hai trăm tệ."},{"type":"compound","zh":"即使深夜路上没有别的车，也不能超速行驶。","pinyin":"Jíshǐ shēnyè lùshang méiyǒu biéde chē, yě bù néng chāosù xíngshǐ.","vi":"Dù đêm khuya trên đường không có xe nào khác cũng không được chạy quá tốc độ."}],"related":[{"hanzi":"车速","pinyin":"chēsù","vi":"tốc độ xe"},{"hanzi":"限速","pinyin":"xiànsù","vi":"giới hạn tốc độ"},{"hanzi":"超车","pinyin":"chāochē","vi":"vượt xe"},{"hanzi":"罚款","pinyin":"fákuǎn","vi":"phạt tiền"}]},{"id":"朝着","hanzi":"朝着","pinyin":"cháozhe","meaning_vi":"hướng về, về phía","explanation":"朝 (triều – hướng về) + 着 (trợ từ) → hướng về phía; dùng cả nghĩa cụ thể và trừu tượng (朝着目标努力).","hsk_level":"7-9","tags":["gioi-tu"],"image":"🧭","examples":[{"type":"basic","zh":"他朝着我走过来。","pinyin":"Tā cháozhe wǒ zǒu guòlái.","vi":"Anh ấy đi về phía tôi."},{"type":"simple","zh":"我们要朝着自己的目标不断努力。","pinyin":"Wǒmen yào cháozhe zìjǐ de mùbiāo búduàn nǔlì.","vi":"Chúng ta phải không ngừng nỗ lực hướng tới mục tiêu của mình."},{"type":"compound","zh":"只要朝着这个方向一直走，你就能看到车站。","pinyin":"Zhǐyào cháozhe zhè gè fāngxiàng yì zhízǒu, nǐ jiù néng kàndào chēzhàn.","vi":"Chỉ cần đi thẳng theo hướng này là bạn sẽ thấy nhà ga."}],"related":[{"hanzi":"朝","pinyin":"cháo","vi":"hướng về"},{"hanzi":"向着","pinyin":"xiàngzhe","vi":"hướng về"},{"hanzi":"对着","pinyin":"duìzhe","vi":"đối diện"},{"hanzi":"往","pinyin":"wǎng","vi":"về phía"}],"traditional":"朝著"},{"id":"吵嘴","hanzi":"吵嘴","pinyin":"chǎozuǐ","meaning_vi":"cãi nhau, cãi vã","explanation":"吵 (sảo – ồn ào, cãi) + 嘴 (chủy – miệng) → cãi nhau bằng lời, thường chuyện nhỏ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"他们俩又吵嘴了。","pinyin":"Tāmen liǎ yòu chǎozuǐ le.","vi":"Hai người họ lại cãi nhau rồi."},{"type":"simple","zh":"小两口为了一点儿小事吵嘴了。","pinyin":"Xiǎoliǎngkǒu wèile yìdiǎnr xiǎoshì chǎozuǐ le.","vi":"Đôi vợ chồng trẻ cãi nhau vì chuyện vặt."},{"type":"compound","zh":"虽然兄弟俩经常吵嘴，但是感情一直很好。","pinyin":"Suīrán xiōngdì liǎ jīngcháng chǎozuǐ, dànshì gǎnqíng yìzhí hěn hǎo.","vi":"Tuy hai anh em hay cãi nhau nhưng tình cảm vẫn luôn rất tốt."}],"related":[{"hanzi":"吵架","pinyin":"chǎojià","vi":"cãi nhau"},{"hanzi":"争吵","pinyin":"zhēngchǎo","vi":"tranh cãi"},{"hanzi":"斗嘴","pinyin":"dòuzuǐ","vi":"đấu khẩu"},{"hanzi":"拌嘴","pinyin":"bànzuǐ","vi":"cãi vặt"}]},{"id":"车道","hanzi":"车道","pinyin":"chēdào","meaning_vi":"làn xe, làn đường","explanation":"车 (xa – xe) + 道 (đạo – đường) → phần đường dành cho xe chạy; cũng chỉ lối xe vào nhà.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"请走右边的车道。","pinyin":"Qǐng zǒu yòubian de chēdào.","vi":"Xin đi làn đường bên phải."},{"type":"simple","zh":"这条高速公路有六条车道。","pinyin":"Zhè tiáo gāosùgōnglù yǒu liù tiáo chēdào.","vi":"Đường cao tốc này có sáu làn xe."},{"type":"compound","zh":"如果你要左转，就得提前换到左边的车道。","pinyin":"Rúguǒ nǐ yào zuǒzhuǎn, jiù děi tíqián huàn dào zuǒbian de chēdào.","vi":"Nếu bạn muốn rẽ trái thì phải chuyển sang làn bên trái từ sớm."}],"related":[{"hanzi":"马路","pinyin":"mǎlù","vi":"đường phố"},{"hanzi":"人行道","pinyin":"rénxíngdào","vi":"vỉa hè"},{"hanzi":"公路","pinyin":"gōnglù","vi":"quốc lộ"},{"hanzi":"超车","pinyin":"chāochē","vi":"vượt xe"}],"traditional":"車道"},{"id":"车祸","hanzi":"车祸","pinyin":"chēhuò","meaning_vi":"tai nạn giao thông","explanation":"车 (xa – xe) + 祸 (họa – tai họa) → tai họa do xe cộ gây ra.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"💥","examples":[{"type":"basic","zh":"他出了车祸。","pinyin":"Tā chūle chēhuò.","vi":"Anh ấy bị tai nạn giao thông."},{"type":"simple","zh":"昨天这个路口发生了一起严重的车祸。","pinyin":"Zuótiān zhè gè lùkǒu fāshēngle yìqǐ yánzhòng de chēhuò.","vi":"Hôm qua ở ngã tư này xảy ra một vụ tai nạn giao thông nghiêm trọng."},{"type":"compound","zh":"因为司机酒后开车，所以引起了这场车祸。","pinyin":"Yīnwèi sījī jiǔhòu kāichē, suǒyǐ yǐnqǐle zhè chǎng chēhuò.","vi":"Vì tài xế lái xe sau khi uống rượu nên đã gây ra vụ tai nạn này."}],"related":[{"hanzi":"交通事故","pinyin":"jiāotōngshìgù","vi":"tai nạn giao thông"},{"hanzi":"事故","pinyin":"shìgù","vi":"sự cố"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"撞车","pinyin":"zhuàngchē","vi":"đâm xe"}],"traditional":"車禍"},{"id":"车间","hanzi":"车间","pinyin":"chējiān","meaning_vi":"phân xưởng, xưởng sản xuất","explanation":"车 (xa – máy móc) + 间 (gian – gian phòng) → khu vực sản xuất trong nhà máy.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"他在车间工作。","pinyin":"Tā zài chējiān gōngzuò.","vi":"Anh ấy làm việc ở phân xưởng."},{"type":"simple","zh":"车间里的机器每天运转十几个小时。","pinyin":"Chējiān lǐ de jīqì měitiān yùnzhuǎn shíjǐ gè xiǎoshí.","vi":"Máy móc trong phân xưởng mỗi ngày vận hành hơn mười tiếng."},{"type":"compound","zh":"进车间以前，所有人都必须戴好安全帽。","pinyin":"Jìn chējiān yǐqián, suǒyǒurén dōu bìxū dài hǎo ānquánmào.","vi":"Trước khi vào phân xưởng, tất cả mọi người đều phải đội mũ bảo hộ."}],"related":[{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"nhà máy"},{"hanzi":"工人","pinyin":"gōngrén","vi":"công nhân"},{"hanzi":"厂房","pinyin":"chǎngfáng","vi":"nhà xưởng"},{"hanzi":"主任","pinyin":"zhǔrèn","vi":"chủ nhiệm, quản đốc"}],"traditional":"車間"},{"id":"车轮","hanzi":"车轮","pinyin":"chēlún","meaning_vi":"bánh xe","explanation":"车 (xa – xe) + 轮 (luân – bánh xe) → bánh xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛞","examples":[{"type":"basic","zh":"车轮陷进了泥里。","pinyin":"Chēlún xiàn jìnle ní lǐ.","vi":"Bánh xe bị lún vào bùn."},{"type":"simple","zh":"自行车的前车轮被钉子扎破了。","pinyin":"Zìxíngchē de qián chēlún bèi dīngzi zhā pò le.","vi":"Bánh trước xe đạp bị đinh đâm thủng."},{"type":"compound","zh":"虽然车轮看起来没问题，但是最好还是检查一下气压。","pinyin":"Suīrán chēlún kànqǐlái méi wèntí, dànshì zuìhǎo háishi jiǎnchá yíxià qìyā.","vi":"Tuy bánh xe trông không có vấn đề gì nhưng tốt nhất vẫn nên kiểm tra áp suất lốp."}],"related":[{"hanzi":"轮子","pinyin":"lúnzi","vi":"bánh xe"},{"hanzi":"轮胎","pinyin":"lúntāi","vi":"lốp xe"},{"hanzi":"车轴","pinyin":"chēzhóu","vi":"trục xe"},{"hanzi":"方向盘","pinyin":"fāngxiàngpán","vi":"vô lăng"}],"traditional":"車輪"},{"id":"车速","hanzi":"车速","pinyin":"chēsù","meaning_vi":"tốc độ xe","explanation":"车 (xa – xe) + 速 (tốc – tốc độ) → tốc độ xe chạy.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⏱️","examples":[{"type":"basic","zh":"请降低车速。","pinyin":"Qǐng jiàngdī chēsù.","vi":"Xin giảm tốc độ xe."},{"type":"simple","zh":"下雨天路滑，司机应该控制好车速。","pinyin":"Xià yǔtiān lù huá, sījī yīnggāi kòngzhì hǎo chēsù.","vi":"Ngày mưa đường trơn, tài xế nên kiểm soát tốc độ xe."},{"type":"compound","zh":"如果在雨天车速太快，就很难及时刹车。","pinyin":"Rúguǒ zài yǔtiān chēsù tài kuài, jiù hěn nán jíshí shāchē.","vi":"Nếu trời mưa mà xe chạy quá nhanh thì rất khó phanh kịp."}],"related":[{"hanzi":"速度","pinyin":"sùdù","vi":"tốc độ"},{"hanzi":"超速","pinyin":"chāosù","vi":"quá tốc độ"},{"hanzi":"限速","pinyin":"xiànsù","vi":"giới hạn tốc độ"},{"hanzi":"刹车","pinyin":"shāchē","vi":"phanh xe"}],"traditional":"車速"},{"id":"车位","hanzi":"车位","pinyin":"chēwèi","meaning_vi":"chỗ đỗ xe","explanation":"车 (xa – xe) + 位 (vị – chỗ) → vị trí để đỗ xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🅿️","examples":[{"type":"basic","zh":"这里没有车位了。","pinyin":"Zhèlǐ méiyǒu chēwèi le.","vi":"Ở đây hết chỗ đỗ xe rồi."},{"type":"simple","zh":"小区里的车位越来越难找了。","pinyin":"Xiǎoqū lǐ de chēwèi yuèláiyuè nán zhǎo le.","vi":"Chỗ đỗ xe trong khu dân cư ngày càng khó tìm."},{"type":"compound","zh":"因为市中心车位太少，所以我一般坐地铁去上班。","pinyin":"Yīnwèi shìzhōngxīn chēwèi tài shǎo, suǒyǐ wǒ yìbān zuò dìtiě qù shàngbān.","vi":"Vì ở trung tâm thành phố quá ít chỗ đỗ xe nên tôi thường đi tàu điện ngầm đi làm."}],"related":[{"hanzi":"停车","pinyin":"tíngchē","vi":"đỗ xe"},{"hanzi":"停车场","pinyin":"tíngchēchǎng","vi":"bãi đỗ xe"},{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"},{"hanzi":"车库","pinyin":"chēkù","vi":"ga ra"}],"traditional":"車位"},{"id":"车型","hanzi":"车型","pinyin":"chēxíng","meaning_vi":"mẫu xe, kiểu xe","explanation":"车 (xa – xe) + 型 (hình – kiểu mẫu) → kiểu, mẫu mã của một loại xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚙","examples":[{"type":"basic","zh":"这款车型很受欢迎。","pinyin":"Zhè kuǎn chēxíng hěn shòuhuānyíng.","vi":"Mẫu xe này rất được ưa chuộng."},{"type":"simple","zh":"今年的车展上出现了很多新车型。","pinyin":"Jīnnián de chēzhǎn shang chūxiànle hěn duō xīn chēxíng.","vi":"Triển lãm ô tô năm nay xuất hiện nhiều mẫu xe mới."},{"type":"compound","zh":"虽然两款车型外观很像，但是发动机完全不同。","pinyin":"Suīrán liǎng kuǎn chēxíng wàiguān hěn xiàng, dànshì fādòngjī wánquán bùtóng.","vi":"Tuy hai mẫu xe trông rất giống nhau nhưng động cơ hoàn toàn khác."}],"related":[{"hanzi":"型号","pinyin":"xínghào","vi":"mẫu mã"},{"hanzi":"款式","pinyin":"kuǎnshì","vi":"kiểu dáng"},{"hanzi":"品牌","pinyin":"pǐnpái","vi":"thương hiệu"},{"hanzi":"汽车","pinyin":"qìchē","vi":"ô tô"}],"traditional":"車型"},{"id":"车轴","hanzi":"车轴","pinyin":"chēzhóu","meaning_vi":"trục xe, trục bánh xe","explanation":"车 (xa – xe) + 轴 (trục – trục quay) → thanh trục nối hai bánh xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⚙️","examples":[{"type":"basic","zh":"这辆车的车轴断了。","pinyin":"Zhè liàng chē de chēzhóu duàn le.","vi":"Trục của chiếc xe này bị gãy."},{"type":"simple","zh":"修车师傅给车轴上了一点儿油。","pinyin":"Xiūchē shīfu gěi chēzhóu shàngle yìdiǎnr yóu.","vi":"Thợ sửa xe tra một ít dầu vào trục xe."},{"type":"compound","zh":"如果车轴出了问题，车子就不能继续开了。","pinyin":"Rúguǒ chēzhóu chūle wèntí, chēzi jiù bù néng jìxù kāi le.","vi":"Nếu trục xe có vấn đề thì xe không thể chạy tiếp được."}],"related":[{"hanzi":"车轮","pinyin":"chēlún","vi":"bánh xe"},{"hanzi":"轴","pinyin":"zhóu","vi":"trục"},{"hanzi":"轮胎","pinyin":"lúntāi","vi":"lốp xe"},{"hanzi":"零件","pinyin":"língjiàn","vi":"linh kiện"}],"traditional":"車軸"},{"id":"扯","hanzi":"扯","pinyin":"chě","meaning_vi":"kéo, xé; tán gẫu, nói lan man","explanation":"扯 (xả – lôi kéo) → kéo, giật, xé; khẩu ngữ: nói chuyện phiếm, nói lạc đề (闲扯, 别扯了).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧵","examples":[{"type":"basic","zh":"别扯我的衣服。","pinyin":"Bié chě wǒ de yīfu.","vi":"Đừng kéo áo tôi."},{"type":"simple","zh":"他一生气，就把信扯成了两半。","pinyin":"Tā yì shēngqì, jiù bǎ xìn chě chéngle liǎng bàn.","vi":"Anh ấy vừa nổi giận liền xé bức thư làm đôi."},{"type":"compound","zh":"我们是在谈工作，你别把话题扯到别的地方去。","pinyin":"Wǒmen shì zài tán gōngzuò, nǐ bié bǎ huàtí chě dào biéde dìfang qù.","vi":"Chúng ta đang bàn công việc, anh đừng lái câu chuyện sang chỗ khác."}],"related":[{"hanzi":"拉","pinyin":"lā","vi":"kéo"},{"hanzi":"撕","pinyin":"sī","vi":"xé"},{"hanzi":"闲扯","pinyin":"xiánchě","vi":"tán gẫu"},{"hanzi":"胡扯","pinyin":"húchě","vi":"nói nhảm"}]},{"id":"撤","hanzi":"撤","pinyin":"chè","meaning_vi":"rút, rút lui; dỡ bỏ, bãi bỏ","explanation":"撤 (triệt – rút đi, bỏ đi) → rút người hoặc vật khỏi chỗ cũ; bãi bỏ (撤职, 撤销).","hsk_level":"7-9","tags":["dong-tu"],"image":"↩️","examples":[{"type":"basic","zh":"把桌子上的盘子撤了吧。","pinyin":"Bǎ zhuōzi shang de pánzi chèle ba.","vi":"Dọn đĩa trên bàn đi."},{"type":"simple","zh":"洪水来之前，村民们都撤到了山上。","pinyin":"Hóngshuǐ lái zhīqián, cūnmínmen dōu chè dàole shān shang.","vi":"Trước khi lũ đến, dân làng đều rút lên núi."},{"type":"compound","zh":"一旦发现危险，所有人就必须马上撤出大楼。","pinyin":"Yídàn fāxiàn wēixiǎn, suǒyǒurén jiù bìxū mǎshàng chèchū dàlóu.","vi":"Một khi phát hiện nguy hiểm, mọi người phải lập tức rút khỏi tòa nhà."}],"related":[{"hanzi":"撤离","pinyin":"chèlí","vi":"sơ tán"},{"hanzi":"撤退","pinyin":"chètuì","vi":"rút lui"},{"hanzi":"撤销","pinyin":"chèxiāo","vi":"hủy bỏ"},{"hanzi":"撤换","pinyin":"chèhuàn","vi":"thay thế"}]},{"id":"撤换","hanzi":"撤换","pinyin":"chèhuàn","meaning_vi":"cách chức và thay người, thay thế","explanation":"撤 (triệt – rút bỏ) + 换 (hoán – thay đổi) → rút người/vật cũ ra và thay bằng cái mới.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"教练撤换了守门员。","pinyin":"Jiàoliàn chèhuànle shǒuményuán.","vi":"Huấn luyện viên đã thay thủ môn."},{"type":"simple","zh":"由于工作失误，他被撤换了。","pinyin":"Yóuyú gōngzuò shīwù, tā bèi chèhuàn le.","vi":"Do sai sót trong công việc, anh ấy đã bị thay thế."},{"type":"compound","zh":"如果项目经理再不改进，公司就会考虑撤换他。","pinyin":"Rúguǒ xiàngmù jīnglǐ zài bù gǎijìn, gōngsī jiù huì kǎolǜ chèhuàn tā.","vi":"Nếu giám đốc dự án còn không cải thiện, công ty sẽ cân nhắc thay ông ấy."}],"related":[{"hanzi":"更换","pinyin":"gēnghuàn","vi":"thay đổi"},{"hanzi":"替换","pinyin":"tìhuàn","vi":"thay thế"},{"hanzi":"撤职","pinyin":"chèzhí","vi":"cách chức"},{"hanzi":"调换","pinyin":"diàohuàn","vi":"hoán đổi"}],"traditional":"撤換"},{"id":"沉浸","hanzi":"沉浸","pinyin":"chénjìn","meaning_vi":"đắm chìm, chìm đắm","explanation":"沉 (trầm – chìm) + 浸 (tẩm – ngâm) → ngâm chìm trong nước; nghĩa bóng: đắm chìm trong cảm xúc, suy nghĩ, không khí.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🫧","examples":[{"type":"basic","zh":"他沉浸在音乐中。","pinyin":"Tā chénjìn zài yīnyuè zhōng.","vi":"Anh ấy đắm chìm trong âm nhạc."},{"type":"simple","zh":"全家人都沉浸在过年的欢乐气氛里。","pinyin":"Quán jiārén dōu chénjìn zài guònián de huānlè qìfēn lǐ.","vi":"Cả nhà đắm chìm trong không khí vui vẻ ngày Tết."},{"type":"compound","zh":"虽然比赛已经结束了，但是球迷们还沉浸在胜利的喜悦中。","pinyin":"Suīrán bǐsài yǐjīng jiéshù le, dànshì qiúmímen hái chénjìn zài shènglì de xǐyuè zhōng.","vi":"Tuy trận đấu đã kết thúc nhưng người hâm mộ vẫn đắm chìm trong niềm vui chiến thắng."}],"related":[{"hanzi":"陶醉","pinyin":"táozuì","vi":"say mê"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"mê muội"},{"hanzi":"投入","pinyin":"tóurù","vi":"nhập tâm"},{"hanzi":"沉醉","pinyin":"chénzuì","vi":"say sưa"}]},{"id":"趁着","hanzi":"趁着","pinyin":"chènzhe","meaning_vi":"nhân lúc, thừa lúc","explanation":"趁 (sấn – nhân dịp) + 着 (trợ từ) → nhân lúc có điều kiện thuận lợi để làm gì.","hsk_level":"7-9","tags":["gioi-tu"],"image":"⏳","examples":[{"type":"basic","zh":"趁着天晴，我们去爬山吧。","pinyin":"Chènzhe tiān qíng, wǒmen qù páshān ba.","vi":"Nhân lúc trời nắng, chúng ta đi leo núi đi."},{"type":"simple","zh":"她趁着午休时间去银行办了点儿事。","pinyin":"Tā chènzhe wǔxiū shíjiān qù yínháng bànle diǎnr shì.","vi":"Cô ấy nhân giờ nghỉ trưa ra ngân hàng làm chút việc."},{"type":"compound","zh":"趁着年轻多学点儿东西，将来就不会后悔。","pinyin":"Chènzhe niánqīng duō xué diǎnr dōngxi, jiānglái jiù bú huì hòuhuǐ.","vi":"Nhân lúc còn trẻ hãy học thêm nhiều thứ, sau này sẽ không hối hận."}],"related":[{"hanzi":"趁","pinyin":"chèn","vi":"nhân lúc"},{"hanzi":"乘机","pinyin":"chéngjī","vi":"thừa cơ"},{"hanzi":"利用","pinyin":"lìyòng","vi":"tận dụng"},{"hanzi":"趁机","pinyin":"chènjī","vi":"nhân cơ hội"}],"traditional":"趁著"},{"id":"称作","hanzi":"称作","pinyin":"chēngzuò","meaning_vi":"được gọi là, gọi là","explanation":"称 (xưng – gọi) + 作 (tác – làm, là) → gọi là, được xưng là.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🏷️","examples":[{"type":"basic","zh":"这种花被称作“花中之王”。","pinyin":"Zhè zhǒng huābèi chēngzuò \"huā zhōng zhī wáng\".","vi":"Loài hoa này được gọi là \"vua của các loài hoa\"."},{"type":"simple","zh":"人们把这座城市称作“春城”。","pinyin":"Rénmen bǎ zhè zuò chéngshì chēngzuò \"chūnchéng\".","vi":"Người ta gọi thành phố này là \"thành phố mùa xuân\"."},{"type":"compound","zh":"虽然大家都把他称作专家，但是他觉得自己还要多学习。","pinyin":"Suīrán dàjiā dōu bǎ tā chēngzuò zhuānjiā, dànshì tā juéde zìjǐ hái yào duō xuéxí.","vi":"Tuy mọi người đều gọi anh ấy là chuyên gia nhưng anh ấy thấy mình còn phải học hỏi nhiều."}],"related":[{"hanzi":"称为","pinyin":"chēngwéi","vi":"gọi là"},{"hanzi":"叫做","pinyin":"jiàozuò","vi":"gọi là"},{"hanzi":"称呼","pinyin":"chēnghu","vi":"xưng hô"},{"hanzi":"名称","pinyin":"míngchēng","vi":"tên gọi"}],"traditional":"稱作"},{"id":"成才","hanzi":"成才","pinyin":"chéngcái","meaning_vi":"thành tài, nên người","explanation":"成 (thành – trở thành) + 才 (tài – người có tài) → trở thành người có ích, có tài năng.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"父母都希望孩子成才。","pinyin":"Fùmǔ dōu xīwàng háizi chéngcái.","vi":"Cha mẹ nào cũng mong con thành tài."},{"type":"simple","zh":"在老师的帮助下，很多贫困学生都成才了。","pinyin":"Zài lǎoshī de bāngzhù xià, hěn duō pínkùn xuésheng dōu chéngcái le.","vi":"Nhờ sự giúp đỡ của thầy cô, nhiều học sinh nghèo đã thành tài."},{"type":"compound","zh":"只要肯努力，即使条件不好，也能成才。","pinyin":"Zhǐyào kěn nǔlì, jíshǐ tiáojiàn bù hǎo, yě néng chéngcái.","vi":"Chỉ cần chịu cố gắng, dù điều kiện không tốt cũng có thể thành tài."}],"related":[{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"成长","pinyin":"chéngzhǎng","vi":"trưởng thành"},{"hanzi":"培养","pinyin":"péiyǎng","vi":"bồi dưỡng"}]},{"id":"成家","hanzi":"成家","pinyin":"chéngjiā","meaning_vi":"lập gia đình, kết hôn","explanation":"成 (thành – tạo nên) + 家 (gia – gia đình) → lập gia đình riêng (thường nói về nam giới); 成家立业 – lập gia đình, dựng sự nghiệp.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"💍","examples":[{"type":"basic","zh":"他三十岁才成家。","pinyin":"Tā sānshí suì cái chéngjiā.","vi":"Anh ấy ba mươi tuổi mới lập gia đình."},{"type":"simple","zh":"哥哥成家以后就搬出去住了。","pinyin":"Gēge chéngjiā yǐhòu jiù bānchūqù zhù le.","vi":"Anh trai lập gia đình xong thì dọn ra ở riêng."},{"type":"compound","zh":"虽然他早就成家了，但是每个周末都回来看父母。","pinyin":"Suīrán tā zǎojiù chéngjiā le, dànshì měi gè zhōumò dōu huílái kàn fùmǔ.","vi":"Tuy anh ấy đã lập gia đình từ lâu nhưng cuối tuần nào cũng về thăm bố mẹ."}],"related":[{"hanzi":"结婚","pinyin":"jiéhūn","vi":"kết hôn"},{"hanzi":"成家立业","pinyin":"chéngjiālìyè","vi":"thành gia lập nghiệp"},{"hanzi":"家庭","pinyin":"jiātíng","vi":"gia đình"},{"hanzi":"娶妻","pinyin":"qǔqī","vi":"lấy vợ"}]},{"id":"成年","hanzi":"成年","pinyin":"chéngnián","meaning_vi":"trưởng thành, thành niên; quanh năm","explanation":"成 (thành – hoàn thành) + 年 (niên – tuổi) → đủ tuổi trưởng thành; cũng có nghĩa: cả năm, quanh năm (khẩu ngữ).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧑","examples":[{"type":"basic","zh":"他已经成年了。","pinyin":"Tā yǐjīng chéngnián le.","vi":"Cậu ấy đã đủ tuổi trưởng thành rồi."},{"type":"simple","zh":"未成年人不能在这里买酒。","pinyin":"Wèichéngniánrén bù néng zài zhèlǐ mǎi jiǔ.","vi":"Người chưa thành niên không được mua rượu ở đây."},{"type":"compound","zh":"即使孩子已经成年了，父母也还是会为他担心。","pinyin":"Jíshǐ háizi yǐjīng chéngnián le, fùmǔ yě háishi huì wèi tā dānxīn.","vi":"Dù con đã trưởng thành, cha mẹ vẫn lo lắng cho nó."}],"related":[{"hanzi":"成人","pinyin":"chéngrén","vi":"người lớn"},{"hanzi":"未成年","pinyin":"wèichéngnián","vi":"chưa thành niên"},{"hanzi":"青年","pinyin":"qīngnián","vi":"thanh niên"},{"hanzi":"长大","pinyin":"zhǎngdà","vi":"lớn lên"}]},{"id":"成问题","hanzi":"成问题","pinyin":"chéngwèntí","meaning_vi":"thành vấn đề, có vấn đề","explanation":"成 (thành – trở thành) + 问题 (vấn đề) → trở thành vấn đề; thường dùng 不成问题 – không thành vấn đề.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"这点儿钱不成问题。","pinyin":"Zhè diǎnr qián bùchéng wèntí.","vi":"Chút tiền này không thành vấn đề."},{"type":"simple","zh":"人手不够，按时完成就成问题了。","pinyin":"Rénshǒu búgòu, ànshí wán chéngjiù chéngwèntí le.","vi":"Thiếu người thì hoàn thành đúng hạn sẽ thành vấn đề."},{"type":"compound","zh":"只要大家一起帮忙，搬家就不成问题。","pinyin":"Zhǐyào dàjiā yìqǐ bāngmáng, bānjiā jiù bùchéng wèntí.","vi":"Chỉ cần mọi người cùng giúp thì chuyển nhà không thành vấn đề."}],"related":[{"hanzi":"问题","pinyin":"wèntí","vi":"vấn đề"},{"hanzi":"没问题","pinyin":"méiwèntí","vi":"không có vấn đề"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền phức"},{"hanzi":"困难","pinyin":"kùnnan","vi":"khó khăn"}],"traditional":"成問題"},{"id":"成型","hanzi":"成型","pinyin":"chéngxíng","meaning_vi":"thành hình, định hình","explanation":"成 (thành – tạo thành) + 型 (hình – khuôn, hình dạng) → có được hình dạng nhất định; vật liệu được tạo hình.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"计划已经基本成型。","pinyin":"Jìhuà yǐjīng jīběn chéngxíng.","vi":"Kế hoạch về cơ bản đã thành hình."},{"type":"simple","zh":"塑料放进模具里，冷却以后就成型了。","pinyin":"Sùliào fàngjìn mújù lǐ, lěngquè yǐhòu jiù chéngxíng le.","vi":"Nhựa cho vào khuôn, sau khi nguội thì thành hình."},{"type":"compound","zh":"虽然新产品还没有完全成型，但是大家已经很期待了。","pinyin":"Suīrán xīnchǎnpǐn hái méiyǒu wánquán chéngxíng, dànshì dàjiā yǐjīng hěn qīdài le.","vi":"Tuy sản phẩm mới còn chưa hoàn toàn thành hình nhưng mọi người đã rất mong đợi."}],"related":[{"hanzi":"成形","pinyin":"chéngxíng","vi":"thành hình"},{"hanzi":"定型","pinyin":"dìngxíng","vi":"định hình"},{"hanzi":"模型","pinyin":"móxíng","vi":"mô hình"},{"hanzi":"形成","pinyin":"xíngchéng","vi":"hình thành"}]},{"id":"承载","hanzi":"承载","pinyin":"chéngzài","meaning_vi":"chịu tải, gánh đỡ, chở","explanation":"承 (thừa – đỡ, nhận) + 载 (tải – chở) → chịu được sức nặng; nghĩa bóng: mang theo (ký ức, kỳ vọng…).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌉","examples":[{"type":"basic","zh":"这座桥承载不了大货车。","pinyin":"Zhè zuò qiáo chéngzài bùliǎo dà huòchē.","vi":"Cây cầu này không chịu nổi xe tải lớn."},{"type":"simple","zh":"这条老街承载着几代人的回忆。","pinyin":"Zhè tiáo lǎojiē chéngzàizhe jǐdàirén de huíyì.","vi":"Con phố cổ này mang theo ký ức của mấy thế hệ."},{"type":"compound","zh":"如果电梯超过了承载能力，就会自动报警。","pinyin":"Rúguǒ diàntī chāoguòle chéngzài nénglì, jiù huì zìdòng bàojǐng.","vi":"Nếu thang máy vượt quá tải trọng thì sẽ tự động báo động."}],"related":[{"hanzi":"承受","pinyin":"chéngshòu","vi":"chịu đựng"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"},{"hanzi":"载重","pinyin":"zàizhòng","vi":"tải trọng"},{"hanzi":"承担","pinyin":"chéngdān","vi":"đảm nhận"}],"traditional":"承載"},{"id":"诚心诚意","hanzi":"诚心诚意","pinyin":"chéngxīn-chéngyì","meaning_vi":"thành tâm thành ý, hết lòng thành thật","explanation":"诚心 (thành tâm) + 诚意 (thành ý) → lặp lại để nhấn mạnh: hết sức chân thành, xuất phát từ đáy lòng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🙏","examples":[{"type":"basic","zh":"我诚心诚意向你道歉。","pinyin":"Wǒ chéngxīnchéngyì xiàng nǐ dàoqiàn.","vi":"Tôi thành tâm thành ý xin lỗi bạn."},{"type":"simple","zh":"他诚心诚意地邀请我们去他家做客。","pinyin":"Tā chéngxīnchéngyì de yāoqǐng wǒmen qù tā jiā zuòkè.","vi":"Anh ấy chân thành mời chúng tôi đến nhà chơi."},{"type":"compound","zh":"只要你诚心诚意地帮助别人，别人就会信任你。","pinyin":"Zhǐyào nǐ chéngxīnchéngyì de bāngzhù biérén, biérén jiù huì xìnrèn nǐ.","vi":"Chỉ cần bạn thật lòng giúp đỡ người khác, người khác sẽ tin tưởng bạn."}],"related":[{"hanzi":"真心实意","pinyin":"zhēnxīnshíyì","vi":"thật lòng thật dạ"},{"hanzi":"诚恳","pinyin":"chéngkěn","vi":"thành khẩn"},{"hanzi":"诚意","pinyin":"chéngyì","vi":"thành ý"},{"hanzi":"虚情假意","pinyin":"xūqíngjiǎyì","vi":"giả dối"}],"traditional":"誠心誠意"},{"id":"城墙","hanzi":"城墙","pinyin":"chéngqiáng","meaning_vi":"tường thành","explanation":"城 (thành – thành trì) + 墙 (tường – bức tường) → bức tường bao quanh thành phố thời xưa.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏯","examples":[{"type":"basic","zh":"这段城墙有六百年了。","pinyin":"Zhè duàn chéngqiáng yǒu liù bǎinián le.","vi":"Đoạn tường thành này đã sáu trăm năm."},{"type":"simple","zh":"游客可以在西安的城墙上骑自行车。","pinyin":"Yóukè kěyǐ zài Xī'ān de chéngqiáng shang qí zìxíngchē.","vi":"Du khách có thể đạp xe trên tường thành Tây An."},{"type":"compound","zh":"虽然城墙已经很旧了，但是依然非常坚固。","pinyin":"Suīrán chéngqiáng yǐjīng hěn jiù le, dànshì yīrán fēicháng jiāngù.","vi":"Tuy tường thành đã rất cũ nhưng vẫn vô cùng kiên cố."}],"related":[{"hanzi":"长城","pinyin":"Chángchéng","vi":"Vạn Lý Trường Thành"},{"hanzi":"城门","pinyin":"chéngmén","vi":"cổng thành"},{"hanzi":"墙壁","pinyin":"qiángbì","vi":"bức tường"},{"hanzi":"古城","pinyin":"gǔchéng","vi":"thành cổ"}],"traditional":"城牆"},{"id":"乘人之危","hanzi":"乘人之危","pinyin":"chéngrén-zhīwēi","meaning_vi":"thừa lúc người gặp nạn, lợi dụng lúc khó khăn","explanation":"乘 (thừa – lợi dụng) + 人之危 (nhân chi nguy – lúc người khác nguy khốn) → nhân lúc người ta gặp khó để ép buộc, trục lợi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦅","examples":[{"type":"basic","zh":"我们不能乘人之危。","pinyin":"Wǒmen bù néng chéngrénzhīwēi.","vi":"Chúng ta không được thừa nước đục thả câu."},{"type":"simple","zh":"他趁朋友急需用钱的时候压低价格，真是乘人之危。","pinyin":"Tā chèn péngyou jíxū yòngqián de shíhou yādī jiàgé, zhēn shì chéngrénzhīwēi.","vi":"Hắn ép giá đúng lúc bạn đang cần tiền gấp, thật là lợi dụng lúc người khác khó khăn."},{"type":"compound","zh":"即使生意再难做，也不能乘人之危赚钱。","pinyin":"Jíshǐ shēngyi zài nán zuò, yě bù néng chéngrénzhīwēi zhuànqián.","vi":"Dù làm ăn khó khăn đến đâu cũng không được lợi dụng lúc người khác gặp nạn để kiếm tiền."}],"related":[{"hanzi":"趁火打劫","pinyin":"chènhuǒdǎjié","vi":"thừa nước đục thả câu"},{"hanzi":"落井下石","pinyin":"luòjǐngxiàshí","vi":"ném đá xuống giếng"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"雪中送炭","pinyin":"xuězhōngsòngtàn","vi":"giúp người lúc hoạn nạn"}]},{"id":"橙汁","hanzi":"橙汁","pinyin":"chéngzhī","meaning_vi":"nước cam","explanation":"橙 (chanh – quả cam) + 汁 (trấp – nước ép) → nước cam ép.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🍊","examples":[{"type":"basic","zh":"我要一杯橙汁。","pinyin":"Wǒ yào yì bēi chéngzhī.","vi":"Cho tôi một cốc nước cam."},{"type":"simple","zh":"早上喝一杯鲜榨橙汁对身体很好。","pinyin":"Zǎoshang hē yì bēi xiān zhà chéngzhī duì shēntǐ hěn hǎo.","vi":"Buổi sáng uống một cốc nước cam vắt rất tốt cho sức khỏe."},{"type":"compound","zh":"因为孩子不爱喝白开水，所以妈妈常给他做橙汁。","pinyin":"Yīnwèi háizi bú ài hē báikāishuǐ, suǒyǐ māma cháng gěi tā zuò chéngzhī.","vi":"Vì con không thích uống nước lọc nên mẹ thường làm nước cam cho con."}],"related":[{"hanzi":"橙子","pinyin":"chéngzi","vi":"quả cam"},{"hanzi":"果汁","pinyin":"guǒzhī","vi":"nước ép trái cây"},{"hanzi":"苹果汁","pinyin":"píngguǒzhī","vi":"nước táo"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"đồ uống"}]},{"id":"逞能","hanzi":"逞能","pinyin":"chěngnéng","meaning_vi":"khoe tài, ra vẻ giỏi giang","explanation":"逞 (sính – phô bày) + 能 (năng – tài năng) → phô trương khả năng của mình, thường quá sức.","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"你别逞能了。","pinyin":"Nǐ bié chěngnéng le.","vi":"Cậu đừng có ra vẻ giỏi nữa."},{"type":"simple","zh":"他喝了酒还逞能开车，结果出了事。","pinyin":"Tā hēle jiǔ hái chěngnéng kāichē, jiéguǒ chūleshì.","vi":"Anh ta uống rượu còn ra vẻ giỏi lái xe, kết quả gặp chuyện."},{"type":"compound","zh":"如果搬不动就叫人帮忙，千万别逞能。","pinyin":"Rúguǒ bān budòng jiù jiào rén bāngmáng, qiānwàn bié chěngnéng.","vi":"Nếu bê không nổi thì gọi người giúp, tuyệt đối đừng cố tỏ ra giỏi."}],"related":[{"hanzi":"逞强","pinyin":"chěngqiáng","vi":"tỏ ra mạnh mẽ"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"能干","pinyin":"nénggàn","vi":"giỏi giang"},{"hanzi":"显摆","pinyin":"xiǎnbai","vi":"khoe mẽ"}]},{"id":"逞强","hanzi":"逞强","pinyin":"chěngqiáng","meaning_vi":"cố tỏ ra mạnh, gắng gượng","explanation":"逞 (sính – phô bày) + 强 (cường – mạnh) → cố tỏ ra mình mạnh, giỏi hơn khả năng thực tế.","hsk_level":"7-9","tags":["dong-tu"],"image":"🦸","examples":[{"type":"basic","zh":"生病了就别逞强。","pinyin":"Shēngbìngle jiù bié chěngqiáng.","vi":"Ốm rồi thì đừng gắng gượng nữa."},{"type":"simple","zh":"她总是逞强，从来不让别人帮忙。","pinyin":"Tā zǒngshì chěngqiáng, cóngláibú ràng biérén bāngmáng.","vi":"Cô ấy lúc nào cũng cố tỏ ra mạnh mẽ, chẳng bao giờ để người khác giúp."},{"type":"compound","zh":"虽然他嘴上逞强说不累，但是脸上全是汗。","pinyin":"Suīrán tā zuǐ shang chěngqiáng shuō bú lèi, dànshì liǎn shang quán shì hàn.","vi":"Tuy ngoài miệng cố tỏ ra mạnh nói không mệt nhưng mặt anh ấy đầy mồ hôi."}],"related":[{"hanzi":"逞能","pinyin":"chěngnéng","vi":"khoe tài"},{"hanzi":"要强","pinyin":"yàoqiáng","vi":"hiếu thắng"},{"hanzi":"好强","pinyin":"hàoqiáng","vi":"hiếu thắng"},{"hanzi":"示弱","pinyin":"shìruò","vi":"tỏ ra yếu"}],"traditional":"逞強"},{"id":"吃不上","hanzi":"吃不上","pinyin":"chībushàng","meaning_vi":"không có mà ăn, không kịp ăn","explanation":"吃 (ngật – ăn) + 不上 (không lên tới) → không có điều kiện để được ăn, hoặc không kịp ăn.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍚","examples":[{"type":"basic","zh":"以前穷得吃不上饭。","pinyin":"Yǐqián qióng de chībushàng fàn.","vi":"Trước kia nghèo đến mức không có cơm ăn."},{"type":"simple","zh":"再不快点儿走，我们就吃不上午饭了。","pinyin":"Zài búkuài diǎnr zǒu, wǒmen jiù chībushàng wǔfàn le.","vi":"Không đi nhanh lên thì chúng ta sẽ không kịp ăn trưa đâu."},{"type":"compound","zh":"虽然那时候家里常常吃不上肉，但是大家过得很开心。","pinyin":"Suīrán nàshíhou jiālǐ chángcháng chībushàng ròu, dànshì dàjiā guòde hěn kāixīn.","vi":"Tuy hồi đó nhà thường không có thịt ăn nhưng mọi người sống rất vui."}],"related":[{"hanzi":"吃得上","pinyin":"chīdeshàng","vi":"có mà ăn"},{"hanzi":"吃不饱","pinyin":"chībubǎo","vi":"ăn không no"},{"hanzi":"吃不下","pinyin":"chībuxià","vi":"ăn không nổi"},{"hanzi":"挨饿","pinyin":"ái'è","vi":"chịu đói"}]},{"id":"痴呆","hanzi":"痴呆","pinyin":"chīdāi","meaning_vi":"đần độn, lú lẫn; chứng sa sút trí tuệ","explanation":"痴 (si – ngây dại) + 呆 (ngai – đờ đẫn) → ngây dại, chậm chạp; y học: chứng sa sút trí tuệ (老年痴呆).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🧠","examples":[{"type":"basic","zh":"他吓得目光痴呆。","pinyin":"Tā xià de mùguāng chīdāi.","vi":"Anh ấy sợ đến ánh mắt đờ đẫn."},{"type":"simple","zh":"奶奶得了老年痴呆，常常认不出家人。","pinyin":"Nǎinai déle lǎonián chīdāi, chángcháng rèn bu chūjiārén.","vi":"Bà mắc chứng lẫn ở người già, thường không nhận ra người nhà."},{"type":"compound","zh":"如果老人多动脑、多运动，就能降低痴呆的风险。","pinyin":"Rúguǒ lǎorén duō dòngnǎo, duō yùndòng, jiù néng jiàngdī chīdāi de fēngxiǎn.","vi":"Nếu người già chịu động não và vận động nhiều thì có thể giảm nguy cơ sa sút trí tuệ."}],"related":[{"hanzi":"发呆","pinyin":"fādāi","vi":"ngẩn người"},{"hanzi":"老年痴呆","pinyin":"lǎoniánchīdāi","vi":"chứng lẫn ở người già"},{"hanzi":"记忆力","pinyin":"jìyìlì","vi":"trí nhớ"},{"hanzi":"糊涂","pinyin":"hútu","vi":"hồ đồ"}],"traditional":"癡呆"},{"id":"痴心","hanzi":"痴心","pinyin":"chīxīn","meaning_vi":"si tình, lòng say mê","explanation":"痴 (si – say mê) + 心 (tâm – lòng) → tấm lòng say mê đến mức si dại, thường trong tình yêu.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💘","examples":[{"type":"basic","zh":"她对他一片痴心。","pinyin":"Tā duì tā yípiàn chīxīn.","vi":"Cô ấy một lòng si mê anh ta."},{"type":"simple","zh":"他痴心地等了她整整十年。","pinyin":"Tā chīxīn de děngle tā zhěngzhěng shí nián.","vi":"Anh ấy si tình chờ cô ấy suốt mười năm."},{"type":"compound","zh":"虽然他一片痴心，但是对方根本不在乎。","pinyin":"Suīrán tā yípiàn chīxīn, dànshì duìfāng gēnběnbú zàihu.","vi":"Tuy anh ấy một lòng si mê nhưng đối phương chẳng hề bận tâm."}],"related":[{"hanzi":"痴情","pinyin":"chīqíng","vi":"si tình"},{"hanzi":"痴迷","pinyin":"chīmí","vi":"mê mẩn"},{"hanzi":"真心","pinyin":"zhēnxīn","vi":"thật lòng"},{"hanzi":"妄想","pinyin":"wàngxiǎng","vi":"vọng tưởng"}],"traditional":"癡心"},{"id":"迟迟","hanzi":"迟迟","pinyin":"chíchí","meaning_vi":"chậm chạp, mãi mà không, chần chừ","explanation":"迟 (trì – chậm) lặp lại → kéo dài rất chậm; thường đi với 不/没: 迟迟不来 – mãi không đến.","hsk_level":"7-9","tags":["pho-tu"],"image":"🐢","examples":[{"type":"basic","zh":"他迟迟没有回复。","pinyin":"Tā chíchí méiyǒu huífù.","vi":"Anh ấy mãi vẫn chưa trả lời."},{"type":"simple","zh":"那家公司迟迟不肯给工人发工资。","pinyin":"Nà jiā gōngsī chíchí bùkěn gěi gōngrén fā gōngzī.","vi":"Công ty đó cứ chần chừ không chịu trả lương cho công nhân."},{"type":"compound","zh":"因为天气一直不好，所以飞机迟迟不能起飞。","pinyin":"Yīnwèi tiānqì yìzhí bù hǎo, suǒyǐ fēijī chíchí bù néng qǐfēi.","vi":"Vì thời tiết mãi không tốt nên máy bay chậm chạp không thể cất cánh."}],"related":[{"hanzi":"迟到","pinyin":"chídào","vi":"đến muộn"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"hoãn lại"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"一直","pinyin":"yìzhí","vi":"mãi, luôn"}],"traditional":"遲遲"},{"id":"持","hanzi":"持","pinyin":"chí","meaning_vi":"cầm, nắm; giữ, duy trì","explanation":"持 (trì – cầm giữ) → cầm trong tay; mở rộng: giữ vững, duy trì (坚持, 保持); văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"他手持一把雨伞。","pinyin":"Tā shǒu chí yì bǎ yǔsǎn.","vi":"Anh ấy tay cầm một chiếc ô."},{"type":"simple","zh":"请持有效证件到窗口办理。","pinyin":"Qǐng chí yǒuxiào zhèngjiàn dào chuāngkǒu bànlǐ.","vi":"Xin mang giấy tờ hợp lệ đến quầy để làm thủ tục."},{"type":"compound","zh":"对于这个方案，虽然有人持反对意见，但是大多数人支持。","pinyin":"Duìyú zhè gè fāng'àn, suīrán yǒurén chí fǎnduì yìjiàn, dànshì dàduōshù rén zhīchí.","vi":"Về phương án này, tuy có người giữ ý kiến phản đối nhưng đa số ủng hộ."}],"related":[{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"},{"hanzi":"保持","pinyin":"bǎochí","vi":"duy trì"},{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"主持","pinyin":"zhǔchí","vi":"chủ trì"}]},{"id":"尺度","hanzi":"尺度","pinyin":"chǐdù","meaning_vi":"thước đo, tiêu chuẩn, mức độ","explanation":"尺 (xích – thước) + 度 (độ – mức độ) → thước đo, chuẩn mực để đánh giá; giới hạn được phép.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"📏","examples":[{"type":"basic","zh":"评价的尺度要统一。","pinyin":"Píngjià de chǐdù yào tǒngyī.","vi":"Thước đo đánh giá phải thống nhất."},{"type":"simple","zh":"这部电影的尺度比较大，不适合孩子看。","pinyin":"Zhè bù diànyǐng de chǐdù bǐjiào dà, bú shìhé háizi kàn.","vi":"Bộ phim này khá táo bạo, không phù hợp cho trẻ con xem."},{"type":"compound","zh":"虽然每个人的审美尺度不同，但是大家都觉得这幅画很美。","pinyin":"Suīrán měigèrén de shěnměi chǐdù bùtóng, dànshì dàjiā dōu juéde zhè fú huà hěn měi.","vi":"Tuy thước đo thẩm mỹ của mỗi người khác nhau nhưng ai cũng thấy bức tranh này rất đẹp."}],"related":[{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"尺寸","pinyin":"chǐcùn","vi":"kích thước"},{"hanzi":"分寸","pinyin":"fēncun","vi":"chừng mực"},{"hanzi":"准则","pinyin":"zhǔnzé","vi":"chuẩn tắc"}]},{"id":"耻辱","hanzi":"耻辱","pinyin":"chǐrǔ","meaning_vi":"nỗi nhục, sỉ nhục","explanation":"耻 (sỉ – xấu hổ) + 辱 (nhục – nhục nhã) → điều nhục nhã, mất danh dự.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"这是我们的耻辱。","pinyin":"Zhè shì wǒmen de chǐrǔ.","vi":"Đây là nỗi nhục của chúng ta."},{"type":"simple","zh":"输掉这场比赛被他们看作一次耻辱。","pinyin":"Shūdiào zhè chǎng bǐsài bèi tāmen kànzuò yí cì chǐrǔ.","vi":"Thua trận đấu này bị họ xem là một nỗi nhục."},{"type":"compound","zh":"即使受到了耻辱，他也没有放弃，反而更加努力了。","pinyin":"Jíshǐ shòudàole chǐrǔ, tā yě méiyǒu fàngqì, fǎn'ér gèngjiā nǔlì le.","vi":"Dù phải chịu nhục, anh ấy cũng không bỏ cuộc mà còn cố gắng hơn."}],"related":[{"hanzi":"羞耻","pinyin":"xiūchǐ","vi":"xấu hổ"},{"hanzi":"侮辱","pinyin":"wǔrǔ","vi":"làm nhục"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vinh quang"},{"hanzi":"耻笑","pinyin":"chǐxiào","vi":"chê cười"}],"traditional":"恥辱"},{"id":"耻笑","hanzi":"耻笑","pinyin":"chǐxiào","meaning_vi":"chê cười, chế giễu","explanation":"耻 (sỉ – làm nhục) + 笑 (tiếu – cười) → cười chê, chế nhạo khiến người khác xấu hổ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😏","examples":[{"type":"basic","zh":"别耻笑别人的缺点。","pinyin":"Bié chǐxiào biérén de quēdiǎn.","vi":"Đừng chê cười khuyết điểm của người khác."},{"type":"simple","zh":"他因为口音很重，常常被同学耻笑。","pinyin":"Tā yīnwèi kǒuyīn hěn zhòng, chángcháng bèi tóngxué chǐxiào.","vi":"Vì giọng địa phương nặng, cậu ấy thường bị bạn học chế giễu."},{"type":"compound","zh":"即使被别人耻笑，她也坚持做自己喜欢的事。","pinyin":"Jíshǐ bèi biérén chǐxiào, tā yě jiānchí zuòzìjǐ xǐhuan de shì.","vi":"Dù bị người khác chê cười, cô ấy vẫn kiên trì làm điều mình thích."}],"related":[{"hanzi":"嘲笑","pinyin":"cháoxiào","vi":"chế nhạo"},{"hanzi":"讥笑","pinyin":"jīxiào","vi":"giễu cợt"},{"hanzi":"耻辱","pinyin":"chǐrǔ","vi":"nỗi nhục"},{"hanzi":"取笑","pinyin":"qǔxiào","vi":"trêu chọc"}],"traditional":"恥笑"},{"id":"充","hanzi":"充","pinyin":"chōng","meaning_vi":"nạp, sạc; làm đầy, nhồi đầy; giả làm, mạo nhận","explanation":"充 (sung – đầy, lấp đầy) → làm cho đầy, nạp vào; cũng dùng với nghĩa giả làm, đóng vai (充当, 冒充).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔋","examples":[{"type":"basic","zh":"手机该充电了。","pinyin":"Shǒujī gāi chōngdiàn le.","vi":"Điện thoại cần sạc rồi."},{"type":"simple","zh":"自行车的轮胎没气了，得去充气。","pinyin":"Zìxíngchē de lúntāi méi qì le, děi qù chōngqì.","vi":"Lốp xe đạp hết hơi rồi, phải đi bơm hơi."},{"type":"compound","zh":"如果你不熟悉情况，就别在会上充内行。","pinyin":"Rúguǒ nǐ bù shúxī qíngkuàng, jiù bié zài huì shang chōng nèiháng.","vi":"Nếu bạn không nắm rõ tình hình thì đừng làm ra vẻ người trong nghề ở cuộc họp."}],"related":[{"hanzi":"充电","pinyin":"chōngdiàn","vi":"sạc điện"},{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"充当","pinyin":"chōngdāng","vi":"đảm nhận vai trò"},{"hanzi":"冒充","pinyin":"màochōng","vi":"giả mạo"}]},{"id":"冲刺","hanzi":"冲刺","pinyin":"chōngcì","meaning_vi":"nước rút, bứt phá, dốc sức về đích","explanation":"冲 (xung – lao tới) + 刺 (thứ – đâm) → lao mạnh về phía trước; chỉ chạy nước rút hoặc dốc toàn lực ở giai đoạn cuối.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"最后一圈开始冲刺。","pinyin":"Zuìhòu yìquān kāishǐ chōngcì.","vi":"Vòng cuối bắt đầu chạy nước rút."},{"type":"simple","zh":"高考前一个月是全班冲刺的关键时期。","pinyin":"Gāokǎo qián yí gèyuè shì quánbān chōngcì de guānjiàn shíqī.","vi":"Một tháng trước kỳ thi đại học là giai đoạn nước rút then chốt của cả lớp."},{"type":"compound","zh":"虽然他一开始落后，但是最后冲刺时超过了所有人。","pinyin":"Suīrán tā yì kāishǐ luòhòu, dànshì zuìhòu chōngcì shí chāoguòle suǒyǒurén.","vi":"Tuy lúc đầu bị tụt lại nhưng khi nước rút cuối cùng anh ấy đã vượt qua tất cả."}],"related":[{"hanzi":"冲","pinyin":"chōng","vi":"lao tới"},{"hanzi":"冲锋","pinyin":"chōngfēng","vi":"xung phong"},{"hanzi":"终点","pinyin":"zhōngdiǎn","vi":"đích"},{"hanzi":"全力","pinyin":"quánlì","vi":"toàn lực"}],"traditional":"衝刺"},{"id":"冲浪","hanzi":"冲浪","pinyin":"chōnglàng","meaning_vi":"lướt sóng","explanation":"冲 (xung – lao tới) + 浪 (lãng – sóng) → lao theo con sóng, tức môn lướt sóng; nghĩa bóng: lướt mạng (网上冲浪).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏄","examples":[{"type":"basic","zh":"他夏天常去海边冲浪。","pinyin":"Tā xiàtiān cháng qù hǎibiān chōnglàng.","vi":"Mùa hè anh ấy hay ra biển lướt sóng."},{"type":"simple","zh":"这片海滩的浪很大，特别适合冲浪。","pinyin":"Zhè piàn hǎitān de làng hěn dà, tèbié shìhé chōnglàng.","vi":"Bãi biển này sóng rất lớn, đặc biệt thích hợp để lướt sóng."},{"type":"compound","zh":"因为从小在海边长大，所以她十岁就学会了冲浪。","pinyin":"Yīnwèi cóngxiǎo zài hǎibiān zhǎngdà, suǒyǐ tā shí suì jiù xuéhuìle chōnglàng.","vi":"Vì lớn lên bên bờ biển nên cô ấy biết lướt sóng từ năm mười tuổi."}],"related":[{"hanzi":"冲浪板","pinyin":"chōnglàngbǎn","vi":"ván lướt sóng"},{"hanzi":"海浪","pinyin":"hǎilàng","vi":"sóng biển"},{"hanzi":"潜水","pinyin":"qiánshuǐ","vi":"lặn"},{"hanzi":"游泳","pinyin":"yóuyǒng","vi":"bơi"}],"traditional":"衝浪"},{"id":"冲撞","hanzi":"冲撞","pinyin":"chōngzhuàng","meaning_vi":"va chạm, đâm vào; xúc phạm, mạo phạm","explanation":"冲 (xung – lao tới) + 撞 (chàng – đâm, va) → đâm sầm vào; nghĩa bóng: nói năng, cư xử mạo phạm người khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"两辆车发生了冲撞。","pinyin":"Liǎng liàng chē fāshēngle chōngzhuàng.","vi":"Hai chiếc xe đã va chạm nhau."},{"type":"simple","zh":"他说话太直，不小心冲撞了长辈。","pinyin":"Tā shuōhuà tài zhí, bù xiǎoxīn chōngzhuàngle zhǎngbèi.","vi":"Anh ấy nói quá thẳng, vô tình mạo phạm bậc bề trên."},{"type":"compound","zh":"即使你心里不服，也不应该当众冲撞老师。","pinyin":"Jíshǐ nǐ xīnli bùfú, yě bù yīnggāi dāngzhòng chōngzhuàng lǎoshī.","vi":"Dù trong lòng không phục, bạn cũng không nên mạo phạm thầy giáo trước mặt mọi người."}],"related":[{"hanzi":"碰撞","pinyin":"pèngzhuàng","vi":"va chạm"},{"hanzi":"冲突","pinyin":"chōngtū","vi":"xung đột"},{"hanzi":"得罪","pinyin":"dézuì","vi":"đắc tội"},{"hanzi":"顶撞","pinyin":"dǐngzhuàng","vi":"cãi lại"}],"traditional":"衝撞"},{"id":"宠","hanzi":"宠","pinyin":"chǒng","meaning_vi":"cưng chiều, nuông chiều, sủng ái","explanation":"宠 (sủng – yêu chiều) → yêu thương quá mức, nuông chiều; thường nói 宠孩子, 宠物.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥰","examples":[{"type":"basic","zh":"奶奶特别宠孙子。","pinyin":"Nǎinai tèbié chǒng sūnzi.","vi":"Bà nội đặc biệt cưng chiều cháu trai."},{"type":"simple","zh":"他把女儿宠得什么家务都不会做。","pinyin":"Tā bǎ nǚ'ér chǒng de shénme jiāwù dōu bú huì zuò.","vi":"Anh ấy chiều con gái đến mức việc nhà gì cũng không biết làm."},{"type":"compound","zh":"如果父母一直宠着孩子，孩子就很难学会独立。","pinyin":"Rúguǒ fùmǔ yìzhí chǒngzhe háizi, háizi jiù hěn nán xuéhuì dúlì.","vi":"Nếu bố mẹ cứ nuông chiều mãi thì con cái rất khó học được tự lập."}],"related":[{"hanzi":"宠爱","pinyin":"chǒng'ài","vi":"cưng chiều"},{"hanzi":"宠物","pinyin":"chǒngwù","vi":"thú cưng"},{"hanzi":"溺爱","pinyin":"nì'ài","vi":"nuông chiều quá mức"},{"hanzi":"娇惯","pinyin":"jiāoguàn","vi":"chiều hư"}],"traditional":"寵"},{"id":"宠爱","hanzi":"宠爱","pinyin":"chǒng'ài","meaning_vi":"cưng chiều, sủng ái, yêu chiều","explanation":"宠 (sủng – yêu chiều) + 爱 (ái – yêu) → yêu thương chiều chuộng đặc biệt, thường từ người trên dành cho người dưới.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💕","examples":[{"type":"basic","zh":"她是全家最受宠爱的孩子。","pinyin":"Tā shì quánjiā zuì shòu chǒng'ài de háizi.","vi":"Cô bé là đứa trẻ được cả nhà cưng chiều nhất."},{"type":"simple","zh":"这只小狗深受主人的宠爱。","pinyin":"Zhè zhī xiǎogǒu shēnshòu zhǔrén de chǒng'ài.","vi":"Chú chó nhỏ này rất được chủ cưng chiều."},{"type":"compound","zh":"虽然父母很宠爱他，但是从不满足他不合理的要求。","pinyin":"Suīrán fùmǔ hěn chǒng'ài tā, dànshì cóng bù mǎnzú tā bù hélǐ de yāoqiú.","vi":"Tuy bố mẹ rất cưng chiều cậu nhưng chưa bao giờ đáp ứng những đòi hỏi vô lý của cậu."}],"related":[{"hanzi":"宠","pinyin":"chǒng","vi":"chiều"},{"hanzi":"疼爱","pinyin":"téng'ài","vi":"thương yêu"},{"hanzi":"溺爱","pinyin":"nì'ài","vi":"nuông chiều quá mức"},{"hanzi":"偏爱","pinyin":"piān'ài","vi":"thiên vị"}],"traditional":"寵愛"},{"id":"仇","hanzi":"仇","pinyin":"chóu","meaning_vi":"thù, mối thù, căm thù, kẻ thù","explanation":"仇 (cừu – thù hận) → mối thù hằn giữa người với người; đọc chóu (là họ thì đọc Qiú).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"⚔️","examples":[{"type":"basic","zh":"他们两家有仇。","pinyin":"Tāmen liǎng jiā yǒu chóu.","vi":"Hai nhà họ có thù với nhau."},{"type":"simple","zh":"他一直想为死去的父亲报仇。","pinyin":"Tā yìzhí xiǎng wèi sǐqù de fùqīn bàochóu.","vi":"Anh ta luôn muốn báo thù cho người cha đã mất."},{"type":"compound","zh":"既然误会已经解开了，你们就别再记仇了。","pinyin":"Jìrán wùhuì yǐjīng jiěkāi le, nǐmen jiù bié zài jìchóu le.","vi":"Hiểu lầm đã được giải tỏa rồi thì các bạn đừng để bụng thù hằn nữa."}],"related":[{"hanzi":"报仇","pinyin":"bàochóu","vi":"báo thù"},{"hanzi":"仇人","pinyin":"chóurén","vi":"kẻ thù"},{"hanzi":"仇恨","pinyin":"chóuhèn","vi":"căm thù"},{"hanzi":"记仇","pinyin":"jìchóu","vi":"thù dai"}]},{"id":"仇人","hanzi":"仇人","pinyin":"chóurén","meaning_vi":"kẻ thù, cừu nhân","explanation":"仇 (cừu – thù) + 人 (nhân – người) → người có thù oán với mình, kẻ thù riêng.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"😠","examples":[{"type":"basic","zh":"他们见面像仇人一样。","pinyin":"Tāmen jiànmiàn xiàng chóurén yíyàng.","vi":"Họ gặp nhau như kẻ thù."},{"type":"simple","zh":"一点小事让两个好朋友变成了仇人。","pinyin":"Yìdiǎn xiǎoshì ràng liǎng gè hǎopéngyou biàn chéngle chóurén.","vi":"Một chuyện nhỏ đã khiến hai người bạn thân trở thành kẻ thù."},{"type":"compound","zh":"虽然他们曾经是仇人，但是后来成了合作伙伴。","pinyin":"Suīrán tāmen céngjīng shì chóurén, dànshì hòulái chéngle hézuò huǒbàn.","vi":"Tuy họ từng là kẻ thù nhưng sau này lại trở thành đối tác."}],"related":[{"hanzi":"仇","pinyin":"chóu","vi":"thù"},{"hanzi":"敌人","pinyin":"dírén","vi":"kẻ địch"},{"hanzi":"恩人","pinyin":"ēnrén","vi":"ân nhân"},{"hanzi":"冤家","pinyin":"yuānjia","vi":"oan gia"}]},{"id":"稠","hanzi":"稠","pinyin":"chóu","meaning_vi":"đặc, sánh; đông đúc, dày đặc","explanation":"稠 (trù – đặc, dày) → chất lỏng đặc sánh; cũng chỉ đông đúc, dày đặc (人口稠密).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥣","examples":[{"type":"basic","zh":"这碗粥煮得太稠了。","pinyin":"Zhè wǎn zhōu zhǔ de tài chóu le.","vi":"Bát cháo này nấu đặc quá."},{"type":"simple","zh":"酸奶放了一夜以后变得更稠了。","pinyin":"Suānnǎi fàngle yí yè yǐhòu biànde gèng chóu le.","vi":"Sữa chua để qua một đêm thì trở nên đặc hơn."},{"type":"compound","zh":"如果汤煮得太稠了，你就再往锅里加一点开水。","pinyin":"Rúguǒ tāng zhǔ de tài chóu le, nǐ jiù zài wǎng guō Lijiā yìdiǎn kāishuǐ.","vi":"Nếu canh nấu đặc quá thì bạn cho thêm chút nước sôi vào nồi."}],"related":[{"hanzi":"稀","pinyin":"xī","vi":"loãng"},{"hanzi":"稠密","pinyin":"chóumì","vi":"dày đặc"},{"hanzi":"浓","pinyin":"nóng","vi":"đậm, đặc"},{"hanzi":"黏","pinyin":"nián","vi":"dính"}]},{"id":"筹","hanzi":"筹","pinyin":"chóu","meaning_vi":"gom, huy động (tiền); trù tính, lo liệu; thẻ đếm","explanation":"筹 (trù – thẻ tre dùng để tính) → tính toán, lên kế hoạch; quyên, gom góp (tiền); còn chỉ thẻ, phỉnh.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧮","examples":[{"type":"basic","zh":"大家一起筹钱给他治病。","pinyin":"Dàjiā yìqǐ chóuqián gěi tā zhìbìng.","vi":"Mọi người cùng góp tiền chữa bệnh cho anh ấy."},{"type":"simple","zh":"学校正在为新图书馆筹集资金。","pinyin":"Xuéxiào zhèngzài wèi xīn túshūguǎn chóují zījīn.","vi":"Nhà trường đang gây quỹ cho thư viện mới."},{"type":"compound","zh":"因为一时筹不到钱，所以这个项目只能推迟。","pinyin":"Yīnwèi yìshí chóu búdào qián, suǒyǐ zhè ge xiàngmù zhǐnéng tuīchí.","vi":"Vì nhất thời chưa gom được tiền nên dự án này đành phải hoãn lại."}],"related":[{"hanzi":"筹备","pinyin":"chóubèi","vi":"trù bị"},{"hanzi":"筹集","pinyin":"chóují","vi":"gom góp"},{"hanzi":"筹款","pinyin":"chóukuǎn","vi":"gây quỹ"},{"hanzi":"统筹","pinyin":"tǒngchóu","vi":"điều phối chung"}],"traditional":"籌"},{"id":"筹办","hanzi":"筹办","pinyin":"chóubàn","meaning_vi":"trù bị, lo liệu tổ chức","explanation":"筹 (trù – tính toán) + 办 (biện – làm, lo) → lên kế hoạch và chuẩn bị tổ chức một sự kiện, công việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🗂️","examples":[{"type":"basic","zh":"他们正在筹办婚礼。","pinyin":"Tāmen zhèngzài chóubàn hūnlǐ.","vi":"Họ đang lo liệu tổ chức đám cưới."},{"type":"simple","zh":"公司派她负责筹办年终晚会。","pinyin":"Gōngsī pài tā fùzé chóubàn niánzhōng wǎnhuì.","vi":"Công ty giao cho cô ấy phụ trách tổ chức tiệc cuối năm."},{"type":"compound","zh":"虽然筹办时间很紧，但是展览还是按时开幕了。","pinyin":"Suīrán chóubàn shíjiān hěn jǐn, dànshì zhǎnlǎn háishi ànshí kāimù le.","vi":"Tuy thời gian chuẩn bị rất gấp nhưng triển lãm vẫn khai mạc đúng hạn."}],"related":[{"hanzi":"筹备","pinyin":"chóubèi","vi":"trù bị"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"tổ chức"},{"hanzi":"操办","pinyin":"cāobàn","vi":"lo liệu"},{"hanzi":"主办","pinyin":"zhǔbàn","vi":"đứng ra tổ chức"}],"traditional":"籌辦"},{"id":"筹措","hanzi":"筹措","pinyin":"chóucuò","meaning_vi":"xoay xở (tiền), huy động, gom góp","explanation":"筹 (trù – tính toán) + 措 (thố – sắp đặt) → tìm cách xoay xở, huy động (tiền bạc, vật tư).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他四处筹措学费。","pinyin":"Tā sìchù chóucuò xuéfèi.","vi":"Anh ấy chạy vạy khắp nơi để xoay tiền học phí."},{"type":"simple","zh":"村里正在想办法筹措修路的资金。","pinyin":"Cūnli zhèngzài xiǎngbànfǎ chóucuò xiūlù de zījīn.","vi":"Làng đang tìm cách huy động vốn để sửa đường."},{"type":"compound","zh":"如果能及时筹措到资金，工厂就能继续生产。","pinyin":"Rúguǒ néng jíshí chóucuò dào zījīn, gōngchǎng jiù néng jìxù shēngchǎn.","vi":"Nếu kịp thời huy động được vốn thì nhà máy có thể tiếp tục sản xuất."}],"related":[{"hanzi":"筹集","pinyin":"chóují","vi":"gom góp"},{"hanzi":"筹款","pinyin":"chóukuǎn","vi":"gây quỹ"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"},{"hanzi":"融资","pinyin":"róngzī","vi":"huy động vốn"}],"traditional":"籌措"},{"id":"丑闻","hanzi":"丑闻","pinyin":"chǒuwén","meaning_vi":"vụ bê bối, tai tiếng, scandal","explanation":"丑 (xú – xấu xa) + 闻 (văn – tin tức nghe được) → tin xấu gây tai tiếng, vụ bê bối.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📰","examples":[{"type":"basic","zh":"这件丑闻震惊了全国。","pinyin":"Zhè jiàn chǒuwén zhènjīngle quánguó.","vi":"Vụ bê bối này đã chấn động cả nước."},{"type":"simple","zh":"那位明星因为一桩丑闻失去了很多广告。","pinyin":"Nà wèi míngxīng yīnwèi yì zhuāng chǒuwén shīqùle hěn duō guǎnggào.","vi":"Ngôi sao đó mất rất nhiều hợp đồng quảng cáo vì một vụ bê bối."},{"type":"compound","zh":"一旦丑闻被媒体曝光，公司的股价就会大跌。","pinyin":"Yídàn chǒuwén bèi méitǐbàoguāng, gōngsī de gǔjià jiù huì dàdiē.","vi":"Một khi vụ bê bối bị báo chí phanh phui, giá cổ phiếu công ty sẽ lao dốc."}],"related":[{"hanzi":"绯闻","pinyin":"fēiwén","vi":"tin đồn tình ái"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"},{"hanzi":"丑事","pinyin":"chǒushì","vi":"chuyện xấu"},{"hanzi":"曝光","pinyin":"bàoguāng","vi":"phơi bày"}],"traditional":"醜聞"},{"id":"瞅","hanzi":"瞅","pinyin":"chǒu","meaning_vi":"nhìn, ngó, liếc (khẩu ngữ)","explanation":"瞅 (thu – nhìn) gồm 目 (mắt) + 秋 → liếc nhìn, ngó qua; từ khẩu ngữ phương Bắc.","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"你瞅瞅这是什么？","pinyin":"Nǐ chǒu chou zhè shì shénme?","vi":"Bạn ngó xem đây là cái gì?"},{"type":"simple","zh":"他偷偷瞅了一眼桌上的信。","pinyin":"Tā tōutōu chǒule yìyǎn zhuō shang de xìn.","vi":"Anh ta lén liếc một cái lá thư trên bàn."},{"type":"compound","zh":"虽然她嘴上说不在乎，但是一直往门口瞅。","pinyin":"Suīrán tā zuǐ shang shuō bú zàihu, dànshì yìzhí wǎng ménkǒu chǒu.","vi":"Tuy miệng nói không quan tâm nhưng cô ấy cứ ngó ra cửa mãi."}],"related":[{"hanzi":"看","pinyin":"kàn","vi":"nhìn"},{"hanzi":"瞧","pinyin":"qiáo","vi":"nhìn, xem"},{"hanzi":"盯","pinyin":"dīng","vi":"nhìn chằm chằm"},{"hanzi":"瞥","pinyin":"piē","vi":"liếc"}]},{"id":"出版社","hanzi":"出版社","pinyin":"chūbǎnshè","meaning_vi":"nhà xuất bản","explanation":"出版 (xuất bản – in ấn phát hành) + 社 (xã – tổ chức) → đơn vị chuyên xuất bản sách báo.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"📚","examples":[{"type":"basic","zh":"她在一家出版社工作。","pinyin":"Tā zài yìjiā chūbǎnshè gōngzuò.","vi":"Cô ấy làm việc ở một nhà xuất bản."},{"type":"simple","zh":"这本小说由北京一家出版社出版。","pinyin":"Zhè běn xiǎoshuō yóu Běijīng yìjiā chūbǎnshè chūbǎn.","vi":"Cuốn tiểu thuyết này do một nhà xuất bản ở Bắc Kinh phát hành."},{"type":"compound","zh":"虽然被好几家出版社拒绝过，但是他从没放弃写作。","pinyin":"Suīrán bèi hǎojǐ jiā chūbǎnshè jùjué guo, dànshì tā cóng méi fàngqì xiězuò.","vi":"Tuy từng bị mấy nhà xuất bản từ chối nhưng anh ấy chưa bao giờ bỏ viết."}],"related":[{"hanzi":"出版","pinyin":"chūbǎn","vi":"xuất bản"},{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập"},{"hanzi":"书店","pinyin":"shūdiàn","vi":"hiệu sách"},{"hanzi":"报社","pinyin":"bàoshè","vi":"tòa soạn báo"}]},{"id":"出厂","hanzi":"出厂","pinyin":"chūchǎng","meaning_vi":"xuất xưởng","explanation":"出 (xuất – ra) + 厂 (xưởng – nhà máy) → hàng hóa thành phẩm rời nhà máy; thường gặp 出厂价, 出厂日期.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这批货已经出厂了。","pinyin":"Zhè pī huò yǐjīng chūchǎng le.","vi":"Lô hàng này đã xuất xưởng rồi."},{"type":"simple","zh":"每台机器出厂前都要经过严格检查。","pinyin":"Měi tái jīqì chūchǎng qián dōu yào jīngguò yángé jiǎnchá.","vi":"Mỗi chiếc máy trước khi xuất xưởng đều phải qua kiểm tra nghiêm ngặt."},{"type":"compound","zh":"如果产品质量不合格，就绝对不能出厂。","pinyin":"Rúguǒ chǎnpǐn zhìliàng bù hégé, jiù juéduì bù néng chūchǎng.","vi":"Nếu chất lượng sản phẩm không đạt thì tuyệt đối không được xuất xưởng."}],"related":[{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"nhà máy"},{"hanzi":"出厂价","pinyin":"chūchǎngjià","vi":"giá xuất xưởng"},{"hanzi":"出货","pinyin":"chūhuò","vi":"xuất hàng"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"}],"traditional":"出廠"},{"id":"出丑","hanzi":"出丑","pinyin":"chūchǒu","meaning_vi":"bẽ mặt, làm trò cười, xấu mặt","explanation":"出 (xuất – lộ ra) + 丑 (xú – xấu) → để lộ cái xấu ra trước mọi người, bị bẽ mặt.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙈","examples":[{"type":"basic","zh":"我可不想当众出丑。","pinyin":"Wǒ kěbù xiǎng dāngzhòng chūchǒu.","vi":"Tôi không muốn bị bẽ mặt trước đám đông đâu."},{"type":"simple","zh":"他第一次上台就忘了词，在全校面前出丑了。","pinyin":"Tā dìyīcì shàngtái jiù wàngle cí, zài quán xiào miànqián chūchǒu le.","vi":"Lần đầu lên sân khấu anh ấy đã quên lời, bẽ mặt trước cả trường."},{"type":"compound","zh":"因为怕在面试时出丑，所以她提前练习了很多遍。","pinyin":"Yīnwèi pà zài miànshì shí chūchǒu, suǒyǐ tā tíqián liànxíle hěn duō biàn.","vi":"Vì sợ bẽ mặt khi phỏng vấn nên cô ấy đã luyện tập trước rất nhiều lần."}],"related":[{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"},{"hanzi":"出洋相","pinyin":"chūyángxiàng","vi":"làm trò cười"},{"hanzi":"难堪","pinyin":"nánkān","vi":"khó xử"},{"hanzi":"丑","pinyin":"chǒu","vi":"xấu"}],"traditional":"出醜"},{"id":"出道","hanzi":"出道","pinyin":"chūdào","meaning_vi":"ra mắt, debut, bắt đầu sự nghiệp","explanation":"出 (xuất – ra) + 道 (đạo – con đường, nghề) → bước vào nghề; nay thường nói nghệ sĩ chính thức ra mắt công chúng.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎤","examples":[{"type":"basic","zh":"这个歌手十六岁就出道了。","pinyin":"Zhè ge gēshǒu shíliù suì jiù chūdào le.","vi":"Ca sĩ này ra mắt từ năm mười sáu tuổi."},{"type":"simple","zh":"他们组合出道三年就拿了大奖。","pinyin":"Tāmen zǔhé chūdào sān nián jiù nále dàjiǎng.","vi":"Nhóm nhạc của họ ra mắt được ba năm đã giành giải lớn."},{"type":"compound","zh":"虽然她出道很早，但是一直到三十岁才真正走红。","pinyin":"Suīrán tā chūdào hěn zǎo, dànshì yì zhídào sānshí suì cái zhēnzhèng zǒuhóng.","vi":"Tuy cô ấy ra mắt rất sớm nhưng phải đến ba mươi tuổi mới thật sự nổi tiếng."}],"related":[{"hanzi":"走红","pinyin":"zǒuhóng","vi":"nổi tiếng"},{"hanzi":"新人","pinyin":"xīnrén","vi":"người mới"},{"hanzi":"艺人","pinyin":"yìrén","vi":"nghệ sĩ"},{"hanzi":"首秀","pinyin":"shǒuxiù","vi":"màn ra mắt"}]},{"id":"出风头","hanzi":"出风头","pinyin":"chūfēngtou","meaning_vi":"nổi bật, khoe khoang, chơi trội","explanation":"出 (xuất – đưa ra) + 风头 (phong đầu – sự nổi bật) → cố làm nổi bật bản thân, thích được chú ý; thường mang ý chê.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🌟","examples":[{"type":"basic","zh":"他总爱出风头。","pinyin":"Tā zǒng ài chūfēngtou.","vi":"Anh ta lúc nào cũng thích chơi trội."},{"type":"simple","zh":"她在晚会上唱了一首歌，大出风头。","pinyin":"Tā zài wǎnhuì shang chàngle yìshǒugē, dà chūfēngtou.","vi":"Cô ấy hát một bài ở buổi tiệc và nổi bật hẳn lên."},{"type":"compound","zh":"如果你只想出风头，就很难得到同事的信任。","pinyin":"Rúguǒ nǐ zhǐ xiǎngchū fēngtou, jiù hěn nándé dào tóngshì de xìnrèn.","vi":"Nếu bạn chỉ muốn chơi trội thì rất khó có được sự tin tưởng của đồng nghiệp."}],"related":[{"hanzi":"风头","pinyin":"fēngtou","vi":"sự nổi bật"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"显摆","pinyin":"xiǎnbai","vi":"khoe mẽ"},{"hanzi":"低调","pinyin":"dīdiào","vi":"kín tiếng"}],"traditional":"出風頭"},{"id":"出局","hanzi":"出局","pinyin":"chūjú","meaning_vi":"bị loại, ra khỏi cuộc chơi","explanation":"出 (xuất – ra) + 局 (cục – ván, cuộc) → ra khỏi ván đấu, bị loại; nghĩa rộng: bị gạt ra khỏi cuộc cạnh tranh.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🚫","examples":[{"type":"basic","zh":"我们队第一轮就出局了。","pinyin":"Wǒmen duì dìyīlún jiù chūjú le.","vi":"Đội chúng tôi bị loại ngay từ vòng một."},{"type":"simple","zh":"这家老公司在激烈的竞争中出局了。","pinyin":"Zhè jiālǎo gōngsī zài jīliè de jìngzhēng zhōng chūjú le.","vi":"Công ty lâu năm này đã bị loại khỏi cuộc cạnh tranh khốc liệt."},{"type":"compound","zh":"如果这场比赛再输，我们就彻底出局了。","pinyin":"Rúguǒ zhè chǎng bǐsài zài shū, wǒmen jiù chèdǐ chūjú le.","vi":"Nếu thua thêm trận này thì chúng ta bị loại hoàn toàn."}],"related":[{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"},{"hanzi":"晋级","pinyin":"jìnjí","vi":"đi tiếp"},{"hanzi":"出线","pinyin":"chūxiàn","vi":"vượt qua vòng"},{"hanzi":"局","pinyin":"jú","vi":"ván, cuộc"}]},{"id":"出具","hanzi":"出具","pinyin":"chūjù","meaning_vi":"cấp, xuất trình (giấy tờ), đưa ra","explanation":"出 (xuất – đưa ra) + 具 (cụ – đầy đủ, soạn) → lập và cấp ra văn bản, chứng nhận; dùng trong văn phong hành chính.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📄","examples":[{"type":"basic","zh":"医院出具了诊断证明。","pinyin":"Yīyuàn chūjùle zhěnduàn zhèngmíng.","vi":"Bệnh viện đã cấp giấy chứng nhận chẩn đoán."},{"type":"simple","zh":"申请签证需要银行出具存款证明。","pinyin":"Shēnqǐng qiānzhèng xūyào yínháng chūjù cúnkuǎn zhèngmíng.","vi":"Xin thị thực cần ngân hàng cấp giấy xác nhận số dư."},{"type":"compound","zh":"只要你出具有效证件，我们就可以为你办理。","pinyin":"Zhǐyào nǐ chūjù yǒuxiào zhèngjiàn, wǒmen jiù kě yǐwèi nǐ bànlǐ.","vi":"Chỉ cần bạn xuất trình giấy tờ hợp lệ là chúng tôi có thể làm thủ tục cho bạn."}],"related":[{"hanzi":"出示","pinyin":"chūshì","vi":"xuất trình"},{"hanzi":"开具","pinyin":"kāijù","vi":"cấp, lập"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"giấy chứng nhận"},{"hanzi":"发票","pinyin":"fāpiào","vi":"hóa đơn"}]},{"id":"出口成章","hanzi":"出口成章","pinyin":"chūkǒu-chéngzhāng","meaning_vi":"nói ra thành văn, ăn nói lưu loát, xuất khẩu thành chương","explanation":"Nghĩa đen: mở miệng là thành bài văn → người ăn nói trôi chảy, có văn chương, tài hùng biện.","hsk_level":"7-9","tags":["thanh-ngu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他说话出口成章。","pinyin":"Tā shuōhuà chūkǒuchéngzhāng.","vi":"Anh ấy ăn nói lưu loát như văn."},{"type":"simple","zh":"这位老教授学问深厚，讲课时出口成章。","pinyin":"Zhè wèi lǎo jiàoshòu xuéwèn shēnhòu, jiǎng kèshí chūkǒuchéngzhāng.","vi":"Vị giáo sư già này học vấn uyên thâm, giảng bài mở miệng là thành văn."},{"type":"compound","zh":"要想出口成章，就得平时多读书、多积累。","pinyin":"Yào xiǎng chūkǒuchéngzhāng, jiù děi píngshí duō dúshū, duō jīlěi.","vi":"Muốn ăn nói lưu loát thành văn thì ngày thường phải đọc nhiều, tích lũy nhiều."}],"related":[{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"},{"hanzi":"能说会道","pinyin":"néngshuōhuìdào","vi":"khéo ăn nói"},{"hanzi":"妙语连珠","pinyin":"miàoyǔliánzhū","vi":"lời hay liên tiếp"},{"hanzi":"笨嘴拙舌","pinyin":"bènzuǐzhuōshé","vi":"vụng ăn nói"}]},{"id":"出毛病","hanzi":"出毛病","pinyin":"chūmáobìng","meaning_vi":"bị hỏng, trục trặc, có vấn đề","explanation":"出 (xuất – phát sinh) + 毛病 (mao bệnh – lỗi, tật) → phát sinh lỗi, máy móc hư hỏng hoặc sự việc gặp trục trặc.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"🔧","examples":[{"type":"basic","zh":"我的电脑又出毛病了。","pinyin":"Wǒ de diànnǎo yòu chūmáobìng le.","vi":"Máy tính của tôi lại trục trặc rồi."},{"type":"simple","zh":"车开到半路发动机突然出毛病了。","pinyin":"Chē kāi dào bànlù fādòngjī tūrán chūmáobìng le.","vi":"Xe chạy đến nửa đường thì động cơ đột nhiên bị hỏng."},{"type":"compound","zh":"如果洗衣机再出毛病，我们就换一台新的。","pinyin":"Rúguǒ xǐyījī zài chūmáobìng, wǒmen jiù huàn yì tái xīn de.","vi":"Nếu máy giặt lại hỏng nữa thì chúng ta mua cái mới."}],"related":[{"hanzi":"毛病","pinyin":"máobìng","vi":"lỗi, tật"},{"hanzi":"故障","pinyin":"gùzhàng","vi":"sự cố"},{"hanzi":"坏了","pinyin":"huàile","vi":"hỏng rồi"},{"hanzi":"修理","pinyin":"xiūlǐ","vi":"sửa chữa"}]},{"id":"出难题","hanzi":"出难题","pinyin":"chūnántí","meaning_vi":"làm khó, đặt câu hỏi hóc búa","explanation":"出 (xuất – đưa ra) + 难题 (nan đề – vấn đề khó) → đưa ra bài toán khó; nghĩa bóng: cố ý gây khó dễ cho người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"❓","examples":[{"type":"basic","zh":"老师给我们出难题了。","pinyin":"Lǎoshī gěi wǒmen chūnántí le.","vi":"Thầy giáo ra đề khó cho chúng tôi rồi."},{"type":"simple","zh":"客户总给我们出难题，要求越来越高。","pinyin":"Kèhù zǒng gěi wǒmen chūnántí, yāoqiú yuèláiyuè gāo.","vi":"Khách hàng luôn làm khó chúng tôi, yêu cầu ngày càng cao."},{"type":"compound","zh":"虽然他故意出难题，但是她还是从容地解决了。","pinyin":"Suīrán tā gùyì chūnántí, dànshì tā háishi cóngróng de jiějué le.","vi":"Tuy anh ta cố tình làm khó nhưng cô ấy vẫn ung dung giải quyết."}],"related":[{"hanzi":"难题","pinyin":"nántí","vi":"bài toán khó"},{"hanzi":"刁难","pinyin":"diāonàn","vi":"làm khó dễ"},{"hanzi":"为难","pinyin":"wéinán","vi":"làm khó"},{"hanzi":"难住","pinyin":"nánzhù","vi":"làm bí"}],"traditional":"出難題"},{"id":"出任","hanzi":"出任","pinyin":"chūrèn","meaning_vi":"nhậm chức, đảm nhiệm (chức vụ)","explanation":"出 (xuất – ra) + 任 (nhậm – đảm nhận chức) → ra nhận một chức vụ; văn phong trang trọng.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他将出任公司总经理。","pinyin":"Tā jiāng chūrèn gōngsī zǒngjīnglǐ.","vi":"Ông ấy sẽ nhậm chức tổng giám đốc công ty."},{"type":"simple","zh":"她去年出任了这所大学的校长。","pinyin":"Tā qùnián chūrènle zhè suǒ dàxué de xiàozhǎng.","vi":"Năm ngoái bà ấy nhậm chức hiệu trưởng trường đại học này."},{"type":"compound","zh":"虽然他从没管理过大公司，但是董事会还是请他出任总裁。","pinyin":"Suīrán tā cóng méi guǎnlǐguo dàgōngsī, dànshì dǒngshìhuì háishi qǐng tā chūrèn zǒngcái.","vi":"Tuy anh ấy chưa từng quản lý công ty lớn nhưng hội đồng quản trị vẫn mời anh ấy làm chủ tịch điều hành."}],"related":[{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"就任","pinyin":"jiùrèn","vi":"nhậm chức"},{"hanzi":"上任","pinyin":"shàngrèn","vi":"nhậm chức"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"rời chức"}]},{"id":"出山","hanzi":"出山","pinyin":"chūshān","meaning_vi":"ra núi, tái xuất, ra làm việc","explanation":"出 (xuất – ra) + 山 (sơn – núi) → ẩn sĩ rời núi ra làm quan; nghĩa nay: người có tài ra mặt đảm nhận việc hoặc tái xuất.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"⛰️","examples":[{"type":"basic","zh":"老教练终于答应出山了。","pinyin":"Lǎo jiàoliàn zhōngyú dāying chūshān le.","vi":"Huấn luyện viên lão làng cuối cùng đã đồng ý tái xuất."},{"type":"simple","zh":"刘备三顾茅庐，才请诸葛亮出山。","pinyin":"Liúbèi sāngùmáolú, cái qǐng Zhūgěliàng chūshān.","vi":"Lưu Bị ba lần đến lều tranh mới mời được Gia Cát Lượng ra giúp."},{"type":"compound","zh":"如果您肯再次出山，球队就有希望了。","pinyin":"Rúguǒ nín kěn zàicì chūshān, qiúduì jiù yǒuxīwàng le.","vi":"Nếu ông chịu tái xuất một lần nữa thì đội bóng sẽ có hy vọng."}],"related":[{"hanzi":"复出","pinyin":"fùchū","vi":"tái xuất"},{"hanzi":"隐居","pinyin":"yǐnjū","vi":"ở ẩn"},{"hanzi":"出马","pinyin":"chūmǎ","vi":"ra tay"},{"hanzi":"退隐","pinyin":"tuìyǐn","vi":"lui về ở ẩn"}]},{"id":"出示","hanzi":"出示","pinyin":"chūshì","meaning_vi":"xuất trình, đưa ra cho xem","explanation":"出 (xuất – lấy ra) + 示 (thị – cho xem) → lấy ra cho người khác xem (vé, giấy tờ, chứng cứ).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🪪","examples":[{"type":"basic","zh":"请出示您的护照。","pinyin":"Qǐng chūshì nín de hùzhào.","vi":"Xin vui lòng xuất trình hộ chiếu của quý khách."},{"type":"simple","zh":"进站时乘客需要出示车票和身份证。","pinyin":"Jìnzhàn shí chéngkè xūyào chūshì chēpiào hé shēnfènzhèng.","vi":"Khi vào ga hành khách cần xuất trình vé và căn cước."},{"type":"compound","zh":"如果对方出示不了证据，法院就不会支持他的要求。","pinyin":"Rúguǒ duìfāng chūshì bùliǎo zhèngjù, fǎyuàn jiù bú huì zhīchí tā de yāoqiú.","vi":"Nếu đối phương không đưa ra được chứng cứ thì tòa sẽ không chấp nhận yêu cầu của anh ta."}],"related":[{"hanzi":"出具","pinyin":"chūjù","vi":"cấp (giấy tờ)"},{"hanzi":"展示","pinyin":"zhǎnshì","vi":"trưng bày"},{"hanzi":"证件","pinyin":"zhèngjiàn","vi":"giấy tờ"},{"hanzi":"示意","pinyin":"shìyì","vi":"ra hiệu"}]},{"id":"出手","hanzi":"出手","pinyin":"chūshǒu","meaning_vi":"ra tay; bán ra; chi tiêu, tiêu tiền","explanation":"出 (xuất – đưa ra) + 手 (thủ – tay) → đưa tay ra hành động; còn có nghĩa bán hàng ra, tiêu tiền (出手大方 = chi tiêu hào phóng).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤜","examples":[{"type":"basic","zh":"他出手很大方。","pinyin":"Tā chūshǒu hěn dàfang.","vi":"Anh ấy chi tiền rất hào phóng."},{"type":"simple","zh":"那套房子他想尽快出手。","pinyin":"Nà tào fángzi tā xiǎng jǐnkuài chūshǒu.","vi":"Căn nhà đó anh ấy muốn bán đi càng sớm càng tốt."},{"type":"compound","zh":"一旦看到有人被欺负，他就会马上出手帮忙。","pinyin":"Yídàn kàndào yǒurén bèi qīfu, tā jiù huì mǎshàng chūshǒu bāngmáng.","vi":"Hễ thấy có người bị bắt nạt là anh ấy lập tức ra tay giúp đỡ."}],"related":[{"hanzi":"动手","pinyin":"dòngshǒu","vi":"ra tay"},{"hanzi":"出售","pinyin":"chūshòu","vi":"bán ra"},{"hanzi":"下手","pinyin":"xiàshǒu","vi":"ra tay"},{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"}]},{"id":"出头","hanzi":"出头","pinyin":"chūtóu","meaning_vi":"thoát cảnh khó khăn; đứng ra, ra mặt; hơn, ngoài (số tròn)","explanation":"出 (xuất – ra) + 头 (đầu) → ló đầu ra; nghĩa bóng: thoát cảnh khó, đứng ra gánh vác, nổi bật; sau số chỉ “hơn một chút” (三十出头).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙋","examples":[{"type":"basic","zh":"他看起来三十岁出头。","pinyin":"Tā kànqǐlái sānshí suì chūtóu.","vi":"Anh ấy trông chừng ngoài ba mươi tuổi."},{"type":"simple","zh":"苦了这么多年，他终于熬出头了。","pinyin":"Kǔle zhème duōnián, tā zhōngyú áochūtóu le.","vi":"Khổ cực bao nhiêu năm, cuối cùng anh ấy cũng đã thoát cảnh khó khăn."},{"type":"compound","zh":"既然没人敢说话，那就由我来出头吧。","pinyin":"Jìrán méi rén gǎn shuōhuà, nà jiù yóu wǒ lái chūtóu ba.","vi":"Đã không ai dám lên tiếng thì để tôi đứng ra vậy."}],"related":[{"hanzi":"出面","pinyin":"chūmiàn","vi":"ra mặt"},{"hanzi":"熬出头","pinyin":"áochūtóu","vi":"vượt qua gian khổ"},{"hanzi":"露头","pinyin":"lòutóu","vi":"ló đầu"},{"hanzi":"出人头地","pinyin":"chūréntóudì","vi":"hơn người"}],"traditional":"出頭"},{"id":"出土","hanzi":"出土","pinyin":"chūtǔ","meaning_vi":"được khai quật, đào được; nhú lên khỏi mặt đất","explanation":"出 (xuất – ra) + 土 (thổ – đất) → từ dưới đất lên; chỉ cổ vật được khai quật hoặc mầm cây nhú khỏi mặt đất.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"这件文物刚刚出土。","pinyin":"Zhè jiàn wénwù gānggāng chūtǔ.","vi":"Cổ vật này vừa mới được khai quật."},{"type":"simple","zh":"博物馆展出了一批汉代出土的铜镜。","pinyin":"Bówùguǎn zhǎnchūle yìpī Hàndài chūtǔ de tóng jìng.","vi":"Bảo tàng trưng bày một loạt gương đồng thời Hán được khai quật."},{"type":"compound","zh":"因为这些竹简出土时保存完好，所以学术价值极高。","pinyin":"Yīnwèi zhèxiē zhújiǎn chūtǔ shí bǎocún wánhǎo, suǒyǐ xuéshù jiàzhí jí gāo.","vi":"Vì những thẻ tre này khi khai quật còn nguyên vẹn nên giá trị học thuật cực cao."}],"related":[{"hanzi":"文物","pinyin":"wénwù","vi":"cổ vật"},{"hanzi":"考古","pinyin":"kǎogǔ","vi":"khảo cổ"},{"hanzi":"发掘","pinyin":"fājué","vi":"khai quật"},{"hanzi":"古墓","pinyin":"gǔmù","vi":"mộ cổ"}]},{"id":"出血","hanzi":"出血","pinyin":"chūxuè","meaning_vi":"chảy máu, xuất huyết; (bóng) chi đậm tiền","explanation":"出 (xuất – ra) + 血 (huyết – máu) → máu chảy ra ngoài; khẩu ngữ còn chỉ phải bỏ ra nhiều tiền.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"他的鼻子出血了。","pinyin":"Tā de bízi chūxuè le.","vi":"Mũi anh ấy chảy máu rồi."},{"type":"simple","zh":"伤口一直出血，得赶紧去医院。","pinyin":"Shāngkǒu yìzhí chūxuè, děi gǎnjǐn qù yīyuàn.","vi":"Vết thương cứ chảy máu mãi, phải mau đến bệnh viện."},{"type":"compound","zh":"这次请客虽然让他大出血，但是大家都很开心。","pinyin":"Zhè cì qǐngkè suīrán ràng tā dàchūxuè, dànshì dàjiā dōu hěn kāixīn.","vi":"Lần mời khách này tuy khiến anh ấy tốn đậm nhưng mọi người đều rất vui."}],"related":[{"hanzi":"流血","pinyin":"liúxuè","vi":"chảy máu"},{"hanzi":"止血","pinyin":"zhǐxuè","vi":"cầm máu"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"血","pinyin":"xuè","vi":"máu"}]},{"id":"出演","hanzi":"出演","pinyin":"chūyǎn","meaning_vi":"đóng vai, tham gia diễn xuất","explanation":"出 (xuất – ra) + 演 (diễn – biểu diễn) → xuất hiện biểu diễn, đảm nhận vai trong phim, kịch.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"她出演了这部电影的女主角。","pinyin":"Tā chūyǎnle zhè bù diànyǐng de nǚzhǔjué.","vi":"Cô ấy đóng vai nữ chính của bộ phim này."},{"type":"simple","zh":"这位老演员很少出演电视剧。","pinyin":"Zhè wèi lǎo yǎnyuán hěn shǎo chūyǎn diànshìjù.","vi":"Diễn viên lão thành này rất ít khi đóng phim truyền hình."},{"type":"compound","zh":"如果他答应出演，这部戏就一定能吸引观众。","pinyin":"Rúguǒ tā dāying chūyǎn, zhè bù xì jiù yídìng néng xīyǐn guānzhòng.","vi":"Nếu anh ấy nhận lời tham gia thì vở kịch này chắc chắn sẽ thu hút khán giả."}],"related":[{"hanzi":"扮演","pinyin":"bànyǎn","vi":"đóng vai"},{"hanzi":"主演","pinyin":"zhǔyǎn","vi":"đóng chính"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"饰演","pinyin":"shìyǎn","vi":"thủ vai"}]},{"id":"出游","hanzi":"出游","pinyin":"chūyóu","meaning_vi":"đi chơi xa, đi du lịch","explanation":"出 (xuất – ra ngoài) + 游 (du – đi chơi) → ra ngoài du ngoạn, đi du lịch.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"国庆节我们全家出游。","pinyin":"Guóqìngjié wǒmen quánjiā chūyóu.","vi":"Dịp Quốc khánh cả nhà chúng tôi đi du lịch."},{"type":"simple","zh":"春天是踏青出游的好季节。","pinyin":"Chūntiān shì tàqīng chūyóu de hǎo jìjié.","vi":"Mùa xuân là mùa đẹp để đi dạo chơi ngoại ô."},{"type":"compound","zh":"如果明天下大雨，我们就取消出游计划。","pinyin":"Rúguǒ míngtiān xià dàyǔ, wǒmen jiù qǔxiāo chūyóu jìhuà.","vi":"Nếu ngày mai mưa to thì chúng ta hủy kế hoạch đi chơi."}],"related":[{"hanzi":"旅游","pinyin":"lǚyóu","vi":"du lịch"},{"hanzi":"出行","pinyin":"chūxíng","vi":"ra ngoài đi lại"},{"hanzi":"郊游","pinyin":"jiāoyóu","vi":"dã ngoại"},{"hanzi":"游客","pinyin":"yóukè","vi":"du khách"}],"traditional":"出遊"},{"id":"出主意","hanzi":"出主意","pinyin":"chūzhǔyi","meaning_vi":"góp ý, bày cách, hiến kế","explanation":"出 (xuất – đưa ra) + 主意 (chủ ý – ý kiến, cách) → đưa ra ý kiến, mách nước cho người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💡","examples":[{"type":"basic","zh":"你帮我出出主意吧。","pinyin":"Nǐ bāng wǒ chū chuzhǔyi ba.","vi":"Bạn giúp tôi nghĩ cách đi."},{"type":"simple","zh":"遇到难事时，朋友们都来给我出主意。","pinyin":"Yùdào nán shì shí, péngyoumen dōu lái gěi wǒ chūzhǔyi.","vi":"Khi gặp chuyện khó, bạn bè đều đến bày cách cho tôi."},{"type":"compound","zh":"虽然他很会出主意，但是真正做事的时候总是躲开。","pinyin":"Suīrán tā hěn huì chūzhǔyi, dànshì zhēnzhèng zuòshì de shíhou zǒngshì duǒkāi.","vi":"Tuy anh ta rất giỏi bày kế nhưng đến lúc làm thật thì luôn né tránh."}],"related":[{"hanzi":"主意","pinyin":"zhǔyi","vi":"ý kiến, cách"},{"hanzi":"建议","pinyin":"jiànyì","vi":"đề nghị"},{"hanzi":"出点子","pinyin":"chūdiǎnzi","vi":"đưa ra ý tưởng"},{"hanzi":"献计","pinyin":"xiànjì","vi":"hiến kế"}]},{"id":"出资","hanzi":"出资","pinyin":"chūzī","meaning_vi":"bỏ vốn, xuất vốn, tài trợ","explanation":"出 (xuất – bỏ ra) + 资 (tư – tiền vốn) → bỏ tiền ra để đầu tư hoặc tài trợ.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"这座桥由企业出资修建。","pinyin":"Zhè zuò qiáo yóu qǐyè chūzī xiūjiàn.","vi":"Cây cầu này do doanh nghiệp bỏ vốn xây dựng."},{"type":"simple","zh":"三个朋友共同出资开了一家咖啡馆。","pinyin":"Sān gè péngyou gòngtóng chūzī kāile yìjiā kāfēiguǎn.","vi":"Ba người bạn cùng góp vốn mở một quán cà phê."},{"type":"compound","zh":"如果政府愿意出资，这个项目就能马上启动。","pinyin":"Rúguǒ zhèngfǔ yuànyì chūzī, zhè ge xiàngmù jiù néng mǎshàng qǐdòng.","vi":"Nếu chính phủ chịu bỏ vốn thì dự án này có thể khởi động ngay."}],"related":[{"hanzi":"投资","pinyin":"tóuzī","vi":"đầu tư"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"},{"hanzi":"赞助","pinyin":"zànzhù","vi":"tài trợ"},{"hanzi":"出钱","pinyin":"chūqián","vi":"bỏ tiền"}],"traditional":"出資"},{"id":"出自","hanzi":"出自","pinyin":"chūzì","meaning_vi":"xuất phát từ, bắt nguồn từ, trích từ","explanation":"出 (xuất – ra) + 自 (tự – từ) → phát ra từ đâu; dùng nói nguồn gốc câu nói, tác phẩm, động cơ.","hsk_level":"7-9","tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"这句话出自《论语》。","pinyin":"Zhè jù huà chūzì Lúnyǔ.","vi":"Câu này trích từ sách Luận Ngữ."},{"type":"simple","zh":"这幅画出自一位十岁孩子之手。","pinyin":"Zhè fú huà chūzì yí wèi shí suì háizi zhī shǒu.","vi":"Bức tranh này do một đứa trẻ mười tuổi vẽ."},{"type":"compound","zh":"虽然他的话不好听，但是完全出自一片好心。","pinyin":"Suīrán tā dehuà bù hǎotīng, dànshì wánquán chūzì yípiàn hǎoxīn.","vi":"Tuy lời anh ấy khó nghe nhưng hoàn toàn xuất phát từ lòng tốt."}],"related":[{"hanzi":"来自","pinyin":"láizì","vi":"đến từ"},{"hanzi":"源自","pinyin":"yuánzì","vi":"bắt nguồn từ"},{"hanzi":"出处","pinyin":"chūchù","vi":"xuất xứ"},{"hanzi":"引自","pinyin":"yǐnzì","vi":"trích dẫn từ"}]},{"id":"出走","hanzi":"出走","pinyin":"chūzǒu","meaning_vi":"bỏ đi, bỏ nhà ra đi","explanation":"出 (xuất – ra) + 走 (tẩu – đi) → rời khỏi nhà hay nơi ở, thường do bất mãn hoặc bị ép.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🚶","examples":[{"type":"basic","zh":"那个男孩离家出走了。","pinyin":"Nà ge nánhái lí jiā chūzǒu le.","vi":"Cậu bé đó đã bỏ nhà ra đi."},{"type":"simple","zh":"她因为和父母吵架，一气之下出走了。","pinyin":"Tā yīnwèi hé fùmǔ chǎojià, yíqì zhīxià chūzǒu le.","vi":"Vì cãi nhau với bố mẹ, cô ấy trong cơn giận đã bỏ đi."},{"type":"compound","zh":"即使家里有矛盾，你也不能用出走来解决问题。","pinyin":"Jíshǐ jiāli yǒu máodùn, nǐ yě bù néng yòng chūzǒu lái jiějué wèntí.","vi":"Dù trong nhà có mâu thuẫn, bạn cũng không thể giải quyết vấn đề bằng cách bỏ đi."}],"related":[{"hanzi":"离家出走","pinyin":"líjiāchūzǒu","vi":"bỏ nhà ra đi"},{"hanzi":"逃走","pinyin":"táozǒu","vi":"bỏ trốn"},{"hanzi":"离开","pinyin":"líkāi","vi":"rời đi"},{"hanzi":"失踪","pinyin":"shīzōng","vi":"mất tích"}]},{"id":"初次","hanzi":"初次","pinyin":"chūcì","meaning_vi":"lần đầu, lần đầu tiên","explanation":"初 (sơ – ban đầu) + 次 (thứ – lần) → lần đầu tiên làm việc gì; thường dùng trong văn viết, lời chào trang trọng.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"1️⃣","examples":[{"type":"basic","zh":"初次见面，请多关照。","pinyin":"Chūcì jiànmiàn, qǐng duō guānzhào.","vi":"Lần đầu gặp mặt, mong được giúp đỡ nhiều."},{"type":"simple","zh":"这是她初次登台表演钢琴。","pinyin":"Zhè shì tā chūcì dēng tái biǎoyǎn gāngqín.","vi":"Đây là lần đầu cô ấy lên sân khấu biểu diễn piano."},{"type":"compound","zh":"虽然是初次出国，但是他一点儿也不紧张。","pinyin":"Suīrán shì chūcì chūguó, dànshì tā yìdiǎnr yě bù jǐnzhāng.","vi":"Tuy là lần đầu ra nước ngoài nhưng anh ấy chẳng hồi hộp chút nào."}],"related":[{"hanzi":"首次","pinyin":"shǒucì","vi":"lần đầu"},{"hanzi":"第一次","pinyin":"dìyīcì","vi":"lần thứ nhất"},{"hanzi":"初","pinyin":"chū","vi":"ban đầu"},{"hanzi":"再次","pinyin":"zàicì","vi":"lần nữa"}]},{"id":"除此之外","hanzi":"除此之外","pinyin":"chúcǐzhīwài","meaning_vi":"ngoài ra, ngoài điều này","explanation":"除 (trừ – bỏ ra) + 此 (thử – cái này) + 之外 (chi ngoại – bên ngoài) → ngoài điều này ra; dùng để bổ sung hoặc loại trừ.","hsk_level":"7-9","tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"除此之外，还有别的办法吗？","pinyin":"Chúcǐzhīwài, háiyǒu biéde bànfǎ ma?","vi":"Ngoài ra còn cách nào khác không?"},{"type":"simple","zh":"他会说英语，除此之外还会一点日语。","pinyin":"Tā huì shuō Yīngyǔ, chúcǐzhīwài hái huì yìdiǎn Rìyǔ.","vi":"Anh ấy nói được tiếng Anh, ngoài ra còn biết chút tiếng Nhật."},{"type":"compound","zh":"这个房子虽然离地铁站很近，但是除此之外没有别的优点。","pinyin":"Zhè ge fángzi suīrán lí dìtiězhàn hěn jìn, dànshì chúcǐzhīwài méiyǒu biéde yōudiǎn.","vi":"Căn nhà này tuy gần ga tàu điện ngầm nhưng ngoài điều đó ra chẳng có ưu điểm nào khác."}],"related":[{"hanzi":"此外","pinyin":"cǐwài","vi":"ngoài ra"},{"hanzi":"另外","pinyin":"lìngwài","vi":"ngoài ra"},{"hanzi":"除了","pinyin":"chúle","vi":"ngoài, trừ"},{"hanzi":"此","pinyin":"cǐ","vi":"này"}]},{"id":"除去","hanzi":"除去","pinyin":"chúqù","meaning_vi":"loại bỏ, trừ bỏ; trừ, ngoài ... ra","explanation":"除 (trừ – bỏ đi) + 去 (khứ – đi mất) → bỏ đi, loại trừ; cũng dùng như giới từ “ngoài… ra”.","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"除去杂草后花园干净多了。","pinyin":"Chúqù zácǎo hòuhuāyuán gānjìng duō le.","vi":"Nhổ bỏ cỏ dại xong, vườn hoa sạch hơn nhiều."},{"type":"simple","zh":"除去房租，他每月只剩两千块。","pinyin":"Chúqù fángzū, tā měiyuè zhǐ shèng liǎng qiān kuài.","vi":"Trừ tiền thuê nhà, mỗi tháng anh ấy chỉ còn hai nghìn tệ."},{"type":"compound","zh":"如果除去周末，我们只剩下三天时间准备。","pinyin":"Rúguǒ chúqù zhōumò, wǒmen zhǐ shèngxià sān tiān shíjiān zhǔnbèi.","vi":"Nếu trừ cuối tuần ra thì chúng ta chỉ còn ba ngày để chuẩn bị."}],"related":[{"hanzi":"去除","pinyin":"qùchú","vi":"loại bỏ"},{"hanzi":"除掉","pinyin":"chúdiào","vi":"trừ khử"},{"hanzi":"扣除","pinyin":"kòuchú","vi":"khấu trừ"},{"hanzi":"除了","pinyin":"chúle","vi":"ngoài ra"}]},{"id":"除外","hanzi":"除外","pinyin":"chúwài","meaning_vi":"trừ ra, không kể, ngoại lệ","explanation":"除 (trừ – bỏ ra) + 外 (ngoại – bên ngoài) → để ra ngoài phạm vi tính; thường đặt cuối câu: …除外.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚷","examples":[{"type":"basic","zh":"每天都开放，周一除外。","pinyin":"Měitiān dōu kāifàng, Zhōuyì chúwài.","vi":"Mở cửa hằng ngày, trừ thứ Hai."},{"type":"simple","zh":"所有费用都已付清，机票除外。","pinyin":"Suǒyǒu fèiyòng dōu yǐ fùqīng, jīpiào chúwài.","vi":"Mọi chi phí đều đã thanh toán, trừ vé máy bay."},{"type":"compound","zh":"所有人都得按时上班，但是请了假的人除外。","pinyin":"Suǒyǒurén dōu děi ànshí shàngbān, dànshì qǐngle jià de rén chúwài.","vi":"Tất cả mọi người đều phải đi làm đúng giờ, nhưng người đã xin nghỉ phép thì ngoại trừ."}],"related":[{"hanzi":"例外","pinyin":"lìwài","vi":"ngoại lệ"},{"hanzi":"除了","pinyin":"chúle","vi":"ngoài ra"},{"hanzi":"不包括","pinyin":"bùbāokuò","vi":"không bao gồm"},{"hanzi":"以外","pinyin":"yǐwài","vi":"ngoài ra"}]},{"id":"触摸","hanzi":"触摸","pinyin":"chùmō","meaning_vi":"chạm, sờ, cảm ứng","explanation":"触 (xúc – chạm) + 摸 (mô – sờ) → dùng tay chạm vào; dùng nhiều trong 触摸屏 (màn hình cảm ứng).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"👆","examples":[{"type":"basic","zh":"展品请勿触摸。","pinyin":"Zhǎnpǐn qǐngwù chùmō.","vi":"Xin đừng chạm vào hiện vật trưng bày."},{"type":"simple","zh":"轻轻触摸屏幕就能打开菜单。","pinyin":"Qīngqīng chùmō píngmù jiù néng dǎkāi càidān.","vi":"Chạm nhẹ vào màn hình là mở được menu."},{"type":"compound","zh":"虽然看不见，但是她通过触摸认出了妈妈的脸。","pinyin":"Suīrán kànbújiàn, dànshì tā tōngguò chùmō rènchūle māma de liǎn.","vi":"Tuy không nhìn thấy nhưng cô bé nhận ra khuôn mặt mẹ qua việc sờ chạm."}],"related":[{"hanzi":"触摸屏","pinyin":"chùmōpíng","vi":"màn hình cảm ứng"},{"hanzi":"抚摸","pinyin":"fǔmō","vi":"vuốt ve"},{"hanzi":"接触","pinyin":"jiēchù","vi":"tiếp xúc"},{"hanzi":"摸","pinyin":"mō","vi":"sờ"}],"traditional":"觸摸"},{"id":"揣","hanzi":"揣","pinyin":"chuāi","meaning_vi":"nhét (vào túi, áo), giấu trong người","explanation":"揣 (sủy) đọc chuāi → nhét, giấu vào trong áo, túi; đọc chuǎi thì nghĩa là đoán, ước lượng (揣测).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧥","examples":[{"type":"basic","zh":"他把手揣在兜里。","pinyin":"Tā bǎshǒu chuāi zài dōu li.","vi":"Anh ấy đút tay vào túi."},{"type":"simple","zh":"她把钱包揣进怀里，生怕被偷。","pinyin":"Tā bǎ qiánbāo chuāi jìn huáili, shēngpà bèi tōu.","vi":"Cô ấy nhét ví vào trong áo, chỉ sợ bị trộm."},{"type":"compound","zh":"因为天太冷了，所以大家都把手揣在袖子里。","pinyin":"Yīnwèi tiān tài lěng le, suǒyǐ dàjiā dōu bǎshǒu chuāi zài xiùzi li.","vi":"Vì trời lạnh quá nên mọi người đều thọc tay vào trong tay áo."}],"related":[{"hanzi":"装","pinyin":"zhuāng","vi":"đựng, cho vào"},{"hanzi":"塞","pinyin":"sāi","vi":"nhét"},{"hanzi":"口袋","pinyin":"kǒudai","vi":"túi"},{"hanzi":"揣测","pinyin":"chuǎicè","vi":"phỏng đoán"}]},{"id":"穿过","hanzi":"穿过","pinyin":"chuānguò","meaning_vi":"đi xuyên qua, băng qua","explanation":"穿 (xuyên – xuyên qua) + 过 (quá – qua) → đi xuyên từ bên này sang bên kia.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚶‍♂️","examples":[{"type":"basic","zh":"我们穿过了一片树林。","pinyin":"Wǒmen chuānguòle yípiàn shùlín.","vi":"Chúng tôi đã đi xuyên qua một khu rừng."},{"type":"simple","zh":"阳光穿过窗帘照进了卧室。","pinyin":"Yángguāng chuānguò chuānglián zhào jìnle wòshì.","vi":"Ánh nắng xuyên qua rèm cửa chiếu vào phòng ngủ."},{"type":"compound","zh":"过马路时一定要走人行横道，不能随便穿过车流。","pinyin":"Guòmǎlù shí yídìngyào zǒu Rénxíng héng dào, bù néng suíbiàn chuānguò chēliú.","vi":"Khi sang đường nhất định phải đi vạch dành cho người đi bộ, không được tùy tiện băng qua dòng xe."}],"related":[{"hanzi":"通过","pinyin":"tōngguò","vi":"đi qua"},{"hanzi":"穿越","pinyin":"chuānyuè","vi":"xuyên qua"},{"hanzi":"横穿","pinyin":"héngchuān","vi":"băng ngang"},{"hanzi":"经过","pinyin":"jīngguò","vi":"đi ngang qua"}],"traditional":"穿過"},{"id":"穿小鞋","hanzi":"穿小鞋","pinyin":"chuānxiǎoxié","meaning_vi":"bị gây khó dễ, trù dập (ngầm)","explanation":"Nghĩa đen: bắt người khác đi giày chật → kẻ có quyền ngấm ngầm trù dập, gây khó dễ cho cấp dưới; thường nói 给某人穿小鞋.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"👞","examples":[{"type":"basic","zh":"老板给他穿小鞋了。","pinyin":"Lǎobǎn gěi tā chuānxiǎoxié le.","vi":"Ông chủ đang trù dập anh ta."},{"type":"simple","zh":"她怕得罪经理以后被穿小鞋。","pinyin":"Tā pà dézuì jīnglǐ yǐhòu bèi chuānxiǎoxié.","vi":"Cô ấy sợ đắc tội với quản lý rồi sau này bị gây khó dễ."},{"type":"compound","zh":"即使你提了反对意见，领导也不应该给你穿小鞋。","pinyin":"Jíshǐ nǐ tíle fǎnduì yìjiàn, lǐngdǎo yě bù yīnggāi gěi nǐ chuānxiǎoxié.","vi":"Dù bạn có đưa ra ý kiến phản đối thì lãnh đạo cũng không nên trù dập bạn."}],"related":[{"hanzi":"刁难","pinyin":"diāonàn","vi":"làm khó dễ"},{"hanzi":"打击报复","pinyin":"dǎjībàofù","vi":"trả đũa"},{"hanzi":"为难","pinyin":"wéinán","vi":"gây khó"},{"hanzi":"整人","pinyin":"zhěngrén","vi":"chơi xỏ người"}]},{"id":"穿着","hanzi":"穿着","pinyin":"chuānzhuó","meaning_vi":"cách ăn mặc, trang phục","explanation":"穿 (xuyên – mặc) + 着 (trước – mặc, mang) → quần áo, cách ăn mặc của một người.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👗","examples":[{"type":"basic","zh":"他的穿着很讲究。","pinyin":"Tā de chuānzhuó hěn jiǎngjiu.","vi":"Cách ăn mặc của anh ấy rất cầu kỳ."},{"type":"simple","zh":"面试时穿着要整洁大方。","pinyin":"Miànshì shí chuānzhuó yào zhěngjié dàfang.","vi":"Khi phỏng vấn trang phục phải gọn gàng, lịch sự."},{"type":"compound","zh":"虽然她平时穿着朴素，但是气质非常出众。","pinyin":"Suīrán tā píngshí chuānzhuó pǔsù, dànshì qìzhì fēicháng chūzhòng.","vi":"Tuy ngày thường cô ấy ăn mặc giản dị nhưng khí chất rất nổi bật."}],"related":[{"hanzi":"打扮","pinyin":"dǎban","vi":"trang điểm, ăn diện"},{"hanzi":"服装","pinyin":"fúzhuāng","vi":"trang phục"},{"hanzi":"衣着","pinyin":"yīzhuó","vi":"y phục"},{"hanzi":"穿戴","pinyin":"chuāndài","vi":"ăn mặc"}],"traditional":"穿著"},{"id":"传承","hanzi":"传承","pinyin":"chuánchéng","meaning_vi":"truyền thừa, kế thừa và truyền lại","explanation":"传 (truyền – truyền lại) + 承 (thừa – tiếp nhận) → tiếp nhận từ đời trước và truyền cho đời sau (văn hóa, tay nghề).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"传统手艺需要传承。","pinyin":"Chuántǒng shǒuyì xūyào chuánchéng.","vi":"Nghề thủ công truyền thống cần được truyền lại."},{"type":"simple","zh":"这家人的剪纸技艺已经传承了五代。","pinyin":"Zhè jiārén de jiǎnzhǐ jìyì yǐjīng chuánchéngle Wǔdài.","vi":"Kỹ nghệ cắt giấy của gia đình này đã truyền qua năm đời."},{"type":"compound","zh":"如果没有年轻人愿意学，这门艺术就无法传承下去。","pinyin":"Rúguǒ méiyǒu niánqīngrén yuànyì xué, zhè mén yìshù jiù wúfǎ chuánchéng xiàqù.","vi":"Nếu không có người trẻ chịu học thì môn nghệ thuật này không thể truyền lại được."}],"related":[{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"truyền thống"},{"hanzi":"传人","pinyin":"chuánrén","vi":"người kế thừa"},{"hanzi":"弘扬","pinyin":"hóngyáng","vi":"phát huy"}],"traditional":"傳承"},{"id":"传奇","hanzi":"传奇","pinyin":"chuánqí","meaning_vi":"huyền thoại, truyền kỳ, ly kỳ","explanation":"传 (truyền – lưu truyền) + 奇 (kỳ – lạ) → chuyện lạ được lưu truyền; chỉ huyền thoại, nhân vật/sự tích phi thường; cũng là thể loại truyện thời Đường–Tống.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🐉","examples":[{"type":"basic","zh":"他是一位传奇人物。","pinyin":"Tā shì yí wèi chuánqí rénwù.","vi":"Ông ấy là một nhân vật huyền thoại."},{"type":"simple","zh":"这位球星的一生充满了传奇色彩。","pinyin":"Zhè wèi qiúxīng de yìshēng chōngmǎnle chuánqí sècǎi.","vi":"Cuộc đời của ngôi sao bóng đá này đầy màu sắc huyền thoại."},{"type":"compound","zh":"虽然他出身贫寒，但是靠努力书写了一段创业传奇。","pinyin":"Suīrán tā chūshēn pínhán, dànshì kào nǔlì shūxiěle yí duàn chuàngyè chuánqí.","vi":"Tuy xuất thân nghèo khó nhưng nhờ nỗ lực anh ấy đã viết nên một huyền thoại khởi nghiệp."}],"related":[{"hanzi":"传说","pinyin":"chuánshuō","vi":"truyền thuyết"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"},{"hanzi":"奇迹","pinyin":"qíjì","vi":"kỳ tích"},{"hanzi":"传奇人物","pinyin":"chuánqírénwù","vi":"nhân vật huyền thoại"}],"traditional":"傳奇"},{"id":"传人","hanzi":"传人","pinyin":"chuánrén","meaning_vi":"người kế thừa, truyền nhân, hậu duệ","explanation":"传 (truyền) + 人 (nhân – người) → người được truyền dạy để kế tục học thuật, tay nghề; cũng chỉ con cháu đời sau.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧑‍🎓","examples":[{"type":"basic","zh":"他是这门武术的传人。","pinyin":"Tā shì zhè mén wǔshù de chuánrén.","vi":"Anh ấy là truyền nhân của môn võ này."},{"type":"simple","zh":"这位老艺人一直在寻找合适的传人。","pinyin":"Zhè wèi lǎo yìrén yìzhí zài xúnzhǎo héshì de chuánrén.","vi":"Vị nghệ nhân già này luôn tìm kiếm người kế thừa phù hợp."},{"type":"compound","zh":"如果找不到传人，这门手艺就会失传。","pinyin":"Rúguǒ zhǎobúdào chuánrén, zhè mén shǒuyì jiù huì shīchuán.","vi":"Nếu không tìm được người kế thừa thì nghề thủ công này sẽ bị thất truyền."}],"related":[{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"},{"hanzi":"继承人","pinyin":"jìchéngrén","vi":"người thừa kế"},{"hanzi":"弟子","pinyin":"dìzǐ","vi":"đệ tử"},{"hanzi":"后代","pinyin":"hòudài","vi":"hậu duệ"}],"traditional":"傳人"},{"id":"传闻","hanzi":"传闻","pinyin":"chuánwén","meaning_vi":"tin đồn, lời đồn","explanation":"传 (truyền – lan truyền) + 闻 (văn – nghe) → điều nghe người ta truyền miệng, chưa được xác thực.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"这只是一个传闻。","pinyin":"Zhè zhǐshì yí gè chuánwén.","vi":"Đây chỉ là một tin đồn."},{"type":"simple","zh":"传闻他下个月要辞职了。","pinyin":"Chuánwén tā xiàgèyuè yào cízhí le.","vi":"Nghe đồn tháng sau anh ta sẽ nghỉ việc."},{"type":"compound","zh":"虽然传闻越来越多，但是公司一直没有正式回应。","pinyin":"Suīrán chuánwén yuèláiyuè duō, dànshì gōngsī yìzhí méiyǒu zhèngshì huíyìng.","vi":"Tuy tin đồn ngày càng nhiều nhưng công ty vẫn chưa phản hồi chính thức."}],"related":[{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn nhảm"},{"hanzi":"传说","pinyin":"chuánshuō","vi":"truyền thuyết"},{"hanzi":"听说","pinyin":"tīngshuō","vi":"nghe nói"},{"hanzi":"绯闻","pinyin":"fēiwén","vi":"tin đồn tình ái"}],"traditional":"傳聞"},{"id":"船桨","hanzi":"船桨","pinyin":"chuánjiǎng","meaning_vi":"mái chèo","explanation":"船 (thuyền) + 桨 (tưởng – mái chèo) → mái chèo dùng để chèo thuyền.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛶","examples":[{"type":"basic","zh":"他用力划着船桨。","pinyin":"Tā yònglì huázhe chuánjiǎng.","vi":"Anh ấy ra sức khua mái chèo."},{"type":"simple","zh":"小船的一支船桨被河水冲走了。","pinyin":"Xiǎochuán de yì zhī chuánjiǎng bèi héshuǐ chōngzǒu le.","vi":"Một mái chèo của chiếc thuyền nhỏ bị nước sông cuốn đi."},{"type":"compound","zh":"因为两个人的船桨划得不一致，所以船一直在原地打转。","pinyin":"Yīnwèi liǎng gè rén de chuánjiǎng huá de bù yízhì, suǒyǐ chuán yìzhí zài yuándì dǎzhuàn.","vi":"Vì hai người chèo không đều nhau nên thuyền cứ xoay vòng tại chỗ."}],"related":[{"hanzi":"划船","pinyin":"huáchuán","vi":"chèo thuyền"},{"hanzi":"桨","pinyin":"jiǎng","vi":"mái chèo"},{"hanzi":"小船","pinyin":"xiǎochuán","vi":"thuyền nhỏ"},{"hanzi":"船帆","pinyin":"chuánfān","vi":"cánh buồm"}],"traditional":"船槳"},{"id":"喘","hanzi":"喘","pinyin":"chuǎn","meaning_vi":"thở hổn hển, thở dốc; hen suyễn","explanation":"喘 (suyễn – thở gấp) → thở gấp, thở dốc; còn chỉ bệnh hen (哮喘).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😮‍💨","examples":[{"type":"basic","zh":"他累得直喘气。","pinyin":"Tā lèi dezhí chuǎnqì.","vi":"Anh ấy mệt đến thở hổn hển."},{"type":"simple","zh":"爬到山顶时，大家都喘得说不出话来。","pinyin":"Pá dào shāndǐng shí, dàjiā dōu chuǎn de shuōbùchū huà lái.","vi":"Leo lên đến đỉnh núi, mọi người đều thở dốc không nói nên lời."},{"type":"compound","zh":"虽然工作很忙，但是你也得停下来喘口气。","pinyin":"Suīrán gōngzuò hěn máng, dànshì nǐ yě děi tíngxiàlái chuǎn kǒuqì.","vi":"Tuy công việc rất bận nhưng bạn cũng phải dừng lại thở một chút."}],"related":[{"hanzi":"喘气","pinyin":"chuǎnqì","vi":"thở dốc"},{"hanzi":"哮喘","pinyin":"xiàochuǎn","vi":"hen suyễn"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"气喘吁吁","pinyin":"qìchuǎnxūxū","vi":"thở hồng hộc"}]},{"id":"串门","hanzi":"串门","pinyin":"chuànmén","meaning_vi":"sang chơi nhà, đi thăm nhà hàng xóm","explanation":"串 (xuyến – xâu, đi qua lại) + 门 (môn – cửa) → đi từ nhà này sang nhà khác chơi, tán gẫu.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🚪","examples":[{"type":"basic","zh":"邻居常来我家串门。","pinyin":"Línjū cháng lái wǒ jiā chuànmén.","vi":"Hàng xóm thường sang nhà tôi chơi."},{"type":"simple","zh":"过年的时候，村里人喜欢挨家挨户串门。","pinyin":"Guònián de shíhou, cūn lirén xǐhuan āijiā'āihù chuànmén.","vi":"Dịp Tết, người trong làng thích đi thăm từng nhà."},{"type":"compound","zh":"如果你周末有空，就常来我家串门吧。","pinyin":"Rúguǒ nǐ zhōumò yǒukòng, jiù cháng lái wǒ jiā chuànmén ba.","vi":"Nếu cuối tuần bạn rảnh thì thường xuyên sang nhà tôi chơi nhé."}],"related":[{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm hỏi"},{"hanzi":"做客","pinyin":"zuòkè","vi":"làm khách"},{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"},{"hanzi":"走亲戚","pinyin":"zǒuqīnqi","vi":"thăm họ hàng"}],"traditional":"串門"},{"id":"床位","hanzi":"床位","pinyin":"chuángwèi","meaning_vi":"giường (bệnh viện, khách sạn, tàu), chỗ nằm","explanation":"床 (sàng – giường) + 位 (vị – chỗ) → chỗ giường nằm được sắp xếp ở bệnh viện, ký túc xá, tàu xe.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🛏️","examples":[{"type":"basic","zh":"医院的床位不够了。","pinyin":"Yīyuàn de chuángwèi búgòu le.","vi":"Bệnh viện không đủ giường nữa."},{"type":"simple","zh":"这家青年旅社一个床位只要五十块。","pinyin":"Zhè jiā qīngnián lǚshè yí gè chuángwèi zhǐyào wǔshí kuài.","vi":"Nhà nghỉ thanh niên này một giường chỉ năm mươi tệ."},{"type":"compound","zh":"因为病人太多，所以有些病人只能在走廊加床位。","pinyin":"Yīnwèi bìngrén tài duō, suǒyǐ yǒuxiē bìngrén zhǐnéng zài zǒuláng jiā chuángwèi.","vi":"Vì bệnh nhân quá đông nên một số người chỉ được kê giường thêm ở hành lang."}],"related":[{"hanzi":"病床","pinyin":"bìngchuáng","vi":"giường bệnh"},{"hanzi":"铺位","pinyin":"pùwèi","vi":"chỗ nằm"},{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"},{"hanzi":"床","pinyin":"chuáng","vi":"giường"}]},{"id":"创","hanzi":"创","pinyin":"chuàng","meaning_vi":"sáng tạo, khởi tạo, lập ra","explanation":"创 (sáng – bắt đầu làm, tạo ra) → làm ra cái mới chưa từng có; gặp trong 创造, 创新, 创业, 创纪录.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"他创了新的世界纪录。","pinyin":"Tā chuàngle xīn de shìjiè jìlù.","vi":"Anh ấy đã lập kỷ lục thế giới mới."},{"type":"simple","zh":"这家公司今年的销售额创了新高。","pinyin":"Zhè jiā gōngsī jīnnián de xiāoshòu'é chuàngle xīngāo.","vi":"Doanh số năm nay của công ty này lập mức cao mới."},{"type":"compound","zh":"虽然创业很辛苦，但是他想闯出一番自己的事业。","pinyin":"Suīrán chuàngyè hěn xīnkǔ, dànshì tā xiǎng chuǎng chū yìfān zìjǐ de shìyè.","vi":"Tuy khởi nghiệp rất vất vả nhưng anh ấy muốn gây dựng sự nghiệp riêng."}],"related":[{"hanzi":"创造","pinyin":"chuàngzào","vi":"sáng tạo"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"đổi mới"},{"hanzi":"创业","pinyin":"chuàngyè","vi":"khởi nghiệp"},{"hanzi":"创立","pinyin":"chuànglì","vi":"sáng lập"}],"traditional":"創"},{"id":"创始人","hanzi":"创始人","pinyin":"chuàngshǐrén","meaning_vi":"người sáng lập, nhà sáng lập","explanation":"创始 (sáng thủy – bắt đầu lập ra) + 人 (nhân – người) → người đầu tiên lập nên một tổ chức, công ty, học phái.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"他是这家公司的创始人。","pinyin":"Tā shì zhè jiā gōngsī de chuàngshǐrén.","vi":"Ông ấy là người sáng lập công ty này."},{"type":"simple","zh":"这所学校的创始人是一位退休教师。","pinyin":"Zhè suǒ xuéxiào de chuàngshǐrén shì yí wèi tuìxiū jiàoshī.","vi":"Người sáng lập ngôi trường này là một giáo viên về hưu."},{"type":"compound","zh":"虽然创始人已经离开了公司，但是他的理念一直影响着大家。","pinyin":"Suīrán chuàngshǐrén yǐjīng líkāile gōngsī, dànshì tā de lǐniàn yìzhí yǐngxiǎngzhe dàjiā.","vi":"Tuy nhà sáng lập đã rời công ty nhưng triết lý của ông vẫn luôn ảnh hưởng mọi người."}],"related":[{"hanzi":"创立","pinyin":"chuànglì","vi":"sáng lập"},{"hanzi":"创办","pinyin":"chuàngbàn","vi":"thành lập"},{"hanzi":"鼻祖","pinyin":"bízǔ","vi":"ông tổ"},{"hanzi":"发起人","pinyin":"fāqǐrén","vi":"người khởi xướng"}],"traditional":"創始人"},{"id":"吹了","hanzi":"吹了","pinyin":"chuīle","meaning_vi":"đổ bể, hỏng, chia tay (khẩu ngữ)","explanation":"吹 (xuy – thổi) + 了 (liễu – rồi) → bị thổi bay mất; khẩu ngữ chỉ việc thất bại, đổ bể hoặc đôi tình nhân chia tay.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💨","examples":[{"type":"basic","zh":"他们俩早就吹了。","pinyin":"Tāmen liǎ zǎojiù chuīle.","vi":"Hai người họ chia tay từ lâu rồi."},{"type":"simple","zh":"那笔生意谈到最后还是吹了。","pinyin":"Nà bǐ shēngyi tándào zuìhòu háishi chuīle.","vi":"Thương vụ đó bàn đến cuối cùng vẫn đổ bể."},{"type":"compound","zh":"因为双方条件谈不拢，所以合作的事吹了。","pinyin":"Yīnwèi shuāngfāng tiáojiàn tánbùlǒng, suǒyǐ hézuò de shì chuīle.","vi":"Vì hai bên không thống nhất được điều kiện nên chuyện hợp tác đổ bể."}],"related":[{"hanzi":"分手","pinyin":"fēnshǒu","vi":"chia tay"},{"hanzi":"告吹","pinyin":"gàochuī","vi":"thất bại"},{"hanzi":"泡汤","pinyin":"pàotāng","vi":"đổ sông đổ biển"},{"hanzi":"黄了","pinyin":"huángle","vi":"hỏng rồi"}]},{"id":"垂","hanzi":"垂","pinyin":"chuí","meaning_vi":"rủ xuống, buông thõng, cúi xuống","explanation":"垂 (thùy – rủ xuống) → vật treo buông xuống phía dưới; cũng dùng trang trọng: 垂直 (thẳng đứng), 垂危 (nguy kịch).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌿","examples":[{"type":"basic","zh":"柳枝垂到了水面上。","pinyin":"Liǔ zhī chuí dàole shuǐmiàn shang.","vi":"Cành liễu rủ xuống tận mặt nước."},{"type":"simple","zh":"她垂着头，一句话也不说。","pinyin":"Tā chuízhe tóu, yíjùhuà yě bù shuō.","vi":"Cô ấy cúi gằm mặt, không nói một lời."},{"type":"compound","zh":"虽然考试没考好，但是你也不用垂头丧气。","pinyin":"Suīrán kǎoshì méi kǎo hǎo, dànshì nǐ yě bú yòng chuítóusàngqì.","vi":"Tuy thi không tốt nhưng bạn cũng không cần ủ rũ."}],"related":[{"hanzi":"垂直","pinyin":"chuízhí","vi":"thẳng đứng"},{"hanzi":"下垂","pinyin":"xiàchuí","vi":"rủ xuống"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ"},{"hanzi":"低垂","pinyin":"dīchuí","vi":"rủ thấp"}]},{"id":"蠢","hanzi":"蠢","pinyin":"chǔn","meaning_vi":"ngu, ngốc, đần độn","explanation":"蠢 (xuẩn – ngu dại) → ngu ngốc, vụng về; gặp trong 愚蠢 (ngu xuẩn), 蠢事 (việc ngu).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🤦","examples":[{"type":"basic","zh":"我真蠢，又忘带钥匙了。","pinyin":"Wǒ zhēn chǔn, yòu wàng dài yàoshi le.","vi":"Tôi ngốc thật, lại quên mang chìa khóa rồi."},{"type":"simple","zh":"他做了一件特别蠢的事情。","pinyin":"Tā zuòle yí jiàn tèbié chǔn de shìqing.","vi":"Anh ta đã làm một việc cực kỳ ngu ngốc."},{"type":"compound","zh":"即使他犯了错，你也不该当着别人的面骂他蠢。","pinyin":"Jíshǐ tā fànle cuò, nǐ yě bùgāi dāngzhe biérén de miàn mà tā chǔn.","vi":"Dù cậu ấy có phạm lỗi, bạn cũng không nên mắng cậu ấy ngu trước mặt người khác."}],"related":[{"hanzi":"愚蠢","pinyin":"yúchǔn","vi":"ngu xuẩn"},{"hanzi":"笨","pinyin":"bèn","vi":"đần"},{"hanzi":"傻","pinyin":"shǎ","vi":"ngốc"},{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"}]},{"id":"戳","hanzi":"戳","pinyin":"chuō","meaning_vi":"chọc, đâm, chọt","explanation":"戳 (trạc – đâm, chọc) → dùng vật nhọn hoặc ngón tay chọc vào; khẩu ngữ: 戳穿 (vạch trần).","hsk_level":"7-9","tags":["dong-tu"],"image":"👉","examples":[{"type":"basic","zh":"别用手指戳我。","pinyin":"Bié yòng shǒuzhǐ chuō wǒ.","vi":"Đừng lấy ngón tay chọc tôi."},{"type":"simple","zh":"他用筷子在纸上戳了一个洞。","pinyin":"Tāyòng kuàizi zài zhǐ shang chuōle yí gè dòng.","vi":"Anh ấy dùng đũa chọc thủng một lỗ trên tờ giấy."},{"type":"compound","zh":"虽然他的谎话被戳穿了，但是他还是不肯认错。","pinyin":"Suīrán tā de huǎnghuà bèi chuōchuān le, dànshì tā háishi bùkěn rèncuò.","vi":"Tuy lời nói dối bị vạch trần nhưng anh ta vẫn không chịu nhận lỗi."}],"related":[{"hanzi":"戳穿","pinyin":"chuōchuān","vi":"vạch trần"},{"hanzi":"刺","pinyin":"cì","vi":"đâm"},{"hanzi":"捅","pinyin":"tǒng","vi":"chọc"},{"hanzi":"邮戳","pinyin":"yóuchuō","vi":"dấu bưu điện"}]},{"id":"瓷","hanzi":"瓷","pinyin":"cí","meaning_vi":"sứ, đồ sứ","explanation":"瓷 (từ – sứ) → loại gốm nung ở nhiệt độ cao, trắng và cứng; gặp trong 瓷器, 陶瓷.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🏺","examples":[{"type":"basic","zh":"这只碗是瓷的。","pinyin":"Zhè zhī wǎn shì cí de.","vi":"Cái bát này làm bằng sứ."},{"type":"simple","zh":"景德镇出产的瓷闻名全世界。","pinyin":"Jǐngdézhèn chūchǎn de cí wénmíng quánshìjiè.","vi":"Đồ sứ do Cảnh Đức Trấn sản xuất nổi tiếng khắp thế giới."},{"type":"compound","zh":"因为瓷很容易碎，所以搬家时要包好。","pinyin":"Yīnwèi cí hěn róngyì suì, suǒyǐ bānjiā shí yào bāo hǎo.","vi":"Vì sứ rất dễ vỡ nên khi chuyển nhà phải gói kỹ."}],"related":[{"hanzi":"瓷器","pinyin":"cíqì","vi":"đồ sứ"},{"hanzi":"陶瓷","pinyin":"táocí","vi":"gốm sứ"},{"hanzi":"瓷砖","pinyin":"cízhuān","vi":"gạch men"},{"hanzi":"青花瓷","pinyin":"qīnghuācí","vi":"sứ hoa lam"}]},{"id":"瓷器","hanzi":"瓷器","pinyin":"cíqì","meaning_vi":"đồ sứ","explanation":"瓷 (từ – sứ) + 器 (khí – đồ dùng) → đồ dùng làm bằng sứ như bát, bình, ấm.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🫖","examples":[{"type":"basic","zh":"她喜欢收藏瓷器。","pinyin":"Tā xǐhuan shōucáng cíqì.","vi":"Cô ấy thích sưu tầm đồ sứ."},{"type":"simple","zh":"中国古代的瓷器曾经远销欧洲。","pinyin":"Zhōngguó gǔdài de cíqì céngjīng yuǎnxiāo Ōuzhōu.","vi":"Đồ sứ Trung Quốc thời cổ từng được bán sang tận châu Âu."},{"type":"compound","zh":"虽然这件瓷器有一道裂纹，但是依然价值连城。","pinyin":"Suīrán zhè jiàn cíqì yǒu yídào lièwén, dànshì yīrán jiàzhí Liánchéng.","vi":"Tuy món đồ sứ này có một vết rạn nhưng vẫn vô giá."}],"related":[{"hanzi":"瓷","pinyin":"cí","vi":"sứ"},{"hanzi":"陶器","pinyin":"táoqì","vi":"đồ gốm"},{"hanzi":"花瓶","pinyin":"huāpíng","vi":"bình hoa"},{"hanzi":"古董","pinyin":"gǔdǒng","vi":"đồ cổ"}]},{"id":"辞","hanzi":"辞","pinyin":"cí","meaning_vi":"thôi việc, từ chức; từ biệt; từ chối; lời lẽ, văn từ","explanation":"辞 (từ – lời; từ biệt, từ bỏ) → rời bỏ, xin thôi (辞职), từ biệt (告辞); còn chỉ lời lẽ, văn từ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📤","examples":[{"type":"basic","zh":"他把工作辞了。","pinyin":"Tā bǎ gōngzuò cí le.","vi":"Anh ấy bỏ việc rồi."},{"type":"simple","zh":"天色已晚，客人起身向主人告辞。","pinyin":"Tiānsè yǐ wǎn, kèrén qǐshēn xiàng zhǔrén gàocí.","vi":"Trời đã muộn, khách đứng dậy chào từ biệt chủ nhà."},{"type":"compound","zh":"虽然老板一再挽留，但是她还是坚持把工作辞了。","pinyin":"Suīrán lǎobǎn yízài wǎnliú, dànshì tā háishi jiānchí bǎ gōngzuò cí le.","vi":"Tuy ông chủ nhiều lần giữ lại nhưng cô ấy vẫn kiên quyết bỏ việc."}],"related":[{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"告辞","pinyin":"gàocí","vi":"cáo từ"},{"hanzi":"辞退","pinyin":"cítuì","vi":"sa thải"},{"hanzi":"推辞","pinyin":"tuīcí","vi":"từ chối"}],"traditional":"辭"},{"id":"辞去","hanzi":"辞去","pinyin":"cíqù","meaning_vi":"từ bỏ, xin thôi (chức vụ)","explanation":"辞 (từ – xin thôi) + 去 (khứ – bỏ đi) → xin thôi một chức vụ, công việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚪","examples":[{"type":"basic","zh":"他辞去了经理职务。","pinyin":"Tā cíqùle jīnglǐ zhíwù.","vi":"Ông ấy đã thôi chức giám đốc."},{"type":"simple","zh":"她辞去了银行的工作，开始自己创业。","pinyin":"Tā cíqùle yínháng de gōngzuò, kāishǐ zìjǐ chuàngyè.","vi":"Cô ấy bỏ công việc ngân hàng, bắt đầu tự khởi nghiệp."},{"type":"compound","zh":"因为身体原因，所以部长决定辞去现任职务。","pinyin":"Yīnwèi shēntǐ yuányīn, suǒyǐ bùzhǎng juédìng cíqù xiànrèn zhíwù.","vi":"Vì lý do sức khỏe nên bộ trưởng quyết định từ nhiệm chức vụ hiện tại."}],"related":[{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"辞退","pinyin":"cítuì","vi":"sa thải"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"rời nhiệm sở"},{"hanzi":"就任","pinyin":"jiùrèn","vi":"nhậm chức"}],"traditional":"辭去"},{"id":"辞退","hanzi":"辞退","pinyin":"cítuì","meaning_vi":"sa thải, cho thôi việc","explanation":"辞 (từ – cho thôi) + 退 (thoái – lui ra) → người sử dụng lao động cho nhân viên nghỉ việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🙅","examples":[{"type":"basic","zh":"公司辞退了三名员工。","pinyin":"Gōngsī cítuìle sān míng yuángōng.","vi":"Công ty đã sa thải ba nhân viên."},{"type":"simple","zh":"他因为多次迟到被老板辞退了。","pinyin":"Tā yīnwèi duōcì chídào bèi lǎobǎn cítuì le.","vi":"Anh ấy bị ông chủ cho thôi việc vì đi muộn nhiều lần."},{"type":"compound","zh":"如果公司无故辞退员工，就必须给予经济补偿。","pinyin":"Rúguǒ gōngsī wúgù cítuì yuángōng, jiù bìxū jǐyǔ jīngjì bǔcháng.","vi":"Nếu công ty sa thải nhân viên vô cớ thì bắt buộc phải bồi thường."}],"related":[{"hanzi":"解雇","pinyin":"jiěgù","vi":"sa thải"},{"hanzi":"开除","pinyin":"kāichú","vi":"đuổi việc"},{"hanzi":"炒鱿鱼","pinyin":"chǎoyóuyú","vi":"cho nghỉ việc"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"}],"traditional":"辭退"},{"id":"磁卡","hanzi":"磁卡","pinyin":"cíkǎ","meaning_vi":"thẻ từ","explanation":"磁 (từ – từ tính) + 卡 (ca – thẻ) → thẻ có dải từ lưu thông tin, dùng để gọi điện, mở cửa, thanh toán.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💳","examples":[{"type":"basic","zh":"请刷磁卡进门。","pinyin":"Qǐng shuā cíkǎ jìnmén.","vi":"Vui lòng quẹt thẻ từ để vào cửa."},{"type":"simple","zh":"以前打公用电话要用磁卡。","pinyin":"Yǐqián dǎ gōngyòng diànhuà yào yòng cíkǎ.","vi":"Trước đây gọi điện thoại công cộng phải dùng thẻ từ."},{"type":"compound","zh":"如果磁卡靠近手机太久，就可能会消磁。","pinyin":"Rúguǒ cíkǎ kàojìn shǒujī tài jiǔ, jiù kěnéng huì xiāocí.","vi":"Nếu để thẻ từ gần điện thoại quá lâu thì có thể bị khử từ."}],"related":[{"hanzi":"刷卡","pinyin":"shuākǎ","vi":"quẹt thẻ"},{"hanzi":"银行卡","pinyin":"yínhángkǎ","vi":"thẻ ngân hàng"},{"hanzi":"磁铁","pinyin":"cítiě","vi":"nam châm"},{"hanzi":"门卡","pinyin":"ménkǎ","vi":"thẻ cửa"}]},{"id":"磁盘","hanzi":"磁盘","pinyin":"cípán","meaning_vi":"đĩa từ, ổ đĩa (máy tính)","explanation":"磁 (từ – từ tính) + 盘 (bàn – đĩa) → đĩa lưu dữ liệu bằng từ tính trong máy tính.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💾","examples":[{"type":"basic","zh":"磁盘空间不足了。","pinyin":"Cípán kōngjiān bùzú le.","vi":"Dung lượng ổ đĩa không đủ rồi."},{"type":"simple","zh":"他把重要文件备份到了另一个磁盘里。","pinyin":"Tā bǎ zhòngyào wénjiàn bèifèn dàole lìngyí gè cípán li.","vi":"Anh ấy sao lưu tài liệu quan trọng sang một ổ đĩa khác."},{"type":"compound","zh":"一旦磁盘损坏，里面的数据就很难恢复。","pinyin":"Yídàn cípán sǔnhuài, lǐmiàn de shùjù jiù hěn nán huīfù.","vi":"Một khi ổ đĩa hỏng thì dữ liệu bên trong rất khó khôi phục."}],"related":[{"hanzi":"硬盘","pinyin":"yìngpán","vi":"ổ cứng"},{"hanzi":"光盘","pinyin":"guāngpán","vi":"đĩa quang"},{"hanzi":"内存","pinyin":"nèicún","vi":"bộ nhớ"},{"hanzi":"存储","pinyin":"cúnchǔ","vi":"lưu trữ"}],"traditional":"磁盤"},{"id":"伺机","hanzi":"伺机","pinyin":"sìjī","meaning_vi":"chờ thời cơ, rình cơ hội","explanation":"伺 (tứ – rình, dò) + 机 (cơ – thời cơ) → rình chờ cơ hội để hành động; thường đứng trước động từ: 伺机报复.","hsk_level":"7-9","tags":["dong-tu"],"image":"🐆","examples":[{"type":"basic","zh":"敌人正在伺机反扑。","pinyin":"Dírén zhèngzài sìjī fǎnpū.","vi":"Kẻ địch đang rình cơ hội phản công."},{"type":"simple","zh":"小偷躲在人群里伺机下手。","pinyin":"Xiǎotōu duǒ zài rénqún li sìjī xiàshǒu.","vi":"Tên trộm nấp trong đám đông chờ cơ hội ra tay."},{"type":"compound","zh":"虽然他表面上很平静，但是一直在伺机报复。","pinyin":"Suīrán tā biǎomiànshang hěn píngjìng, dànshì yìzhí zài sìjī bàofù.","vi":"Tuy bề ngoài rất bình thản nhưng hắn luôn rình cơ hội trả thù."}],"related":[{"hanzi":"时机","pinyin":"shíjī","vi":"thời cơ"},{"hanzi":"趁机","pinyin":"chènjī","vi":"nhân cơ hội"},{"hanzi":"等待","pinyin":"děngdài","vi":"chờ đợi"},{"hanzi":"伺候","pinyin":"cìhou","vi":"hầu hạ"}],"traditional":"伺機"},{"id":"刺耳","hanzi":"刺耳","pinyin":"cì'ěr","meaning_vi":"chói tai, nghe khó chịu","explanation":"刺 (thứ – đâm) + 耳 (nhĩ – tai) → âm thanh như đâm vào tai; nghĩa bóng: lời nói khó nghe.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔊","examples":[{"type":"basic","zh":"这声音太刺耳了。","pinyin":"Zhè shēngyīn tài cì'ěr le.","vi":"Âm thanh này chói tai quá."},{"type":"simple","zh":"刹车时发出了一阵刺耳的尖叫声。","pinyin":"Shāchē shí fāchūle yízhèn cì'ěr de jiān jiàoshēng.","vi":"Khi phanh xe phát ra một tràng tiếng rít chói tai."},{"type":"compound","zh":"虽然他的批评有点刺耳，但是说的都是事实。","pinyin":"Suīrán tā de pīpíng yǒudiǎn cì'ěr, dànshì shuō de dōu shì shìshí.","vi":"Tuy lời phê bình của anh ấy hơi khó nghe nhưng toàn là sự thật."}],"related":[{"hanzi":"悦耳","pinyin":"yuè'ěr","vi":"êm tai"},{"hanzi":"噪音","pinyin":"zàoyīn","vi":"tiếng ồn"},{"hanzi":"刺眼","pinyin":"cìyǎn","vi":"chói mắt"},{"hanzi":"难听","pinyin":"nántīng","vi":"khó nghe"}]},{"id":"刺骨","hanzi":"刺骨","pinyin":"cìgǔ","meaning_vi":"thấu xương, buốt giá","explanation":"刺 (thứ – đâm) + 骨 (cốt – xương) → lạnh như đâm vào tận xương, rét buốt.","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🥶","examples":[{"type":"basic","zh":"外面寒风刺骨。","pinyin":"Wàimiàn hánfēng cìgǔ.","vi":"Bên ngoài gió lạnh buốt xương."},{"type":"simple","zh":"冬天早上的河水冰冷刺骨。","pinyin":"Dōngtiān zǎoshang de héshuǐ bīnglěng cìgǔ.","vi":"Nước sông buổi sáng mùa đông lạnh buốt thấu xương."},{"type":"compound","zh":"虽然外面寒风刺骨，但是工人们仍然坚持在工地上干活。","pinyin":"Suīrán wàimiàn hánfēng cìgǔ, dànshì gōngrénmen réngrán jiānchí zài gōngdì shang gànhuó.","vi":"Tuy bên ngoài gió rét thấu xương nhưng công nhân vẫn kiên trì làm việc ở công trường."}],"related":[{"hanzi":"寒冷","pinyin":"hánlěng","vi":"giá lạnh"},{"hanzi":"冰冷","pinyin":"bīnglěng","vi":"lạnh giá"},{"hanzi":"刺","pinyin":"cì","vi":"đâm"},{"hanzi":"严寒","pinyin":"yánhán","vi":"rét đậm"}]},{"id":"赐","hanzi":"赐","pinyin":"cì","meaning_vi":"ban, ban cho, ban tặng","explanation":"赐 (tứ – ban cho) → người trên ban cho người dưới; nay dùng trong lời kính trọng như 赐教, 恩赐.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎁","examples":[{"type":"basic","zh":"这是上天赐给我们的礼物。","pinyin":"Zhè shì shàngtiān cìgěi wǒmen de lǐwù.","vi":"Đây là món quà trời ban cho chúng ta."},{"type":"simple","zh":"皇帝赐给他一块金牌和一匹好马。","pinyin":"Huángdì cìgěi tā yíkuài jīnpái hé yì pǐ hǎo mǎ.","vi":"Hoàng đế ban cho ông ấy một tấm kim bài và một con ngựa tốt."},{"type":"compound","zh":"虽然这次机会是命运所赐，但是能否抓住还要靠自己。","pinyin":"Suīrán zhè cì jīhuì shì mìngyùn suǒ cì, dànshì néngfǒu zhuāzhù hái yào kào zìjǐ.","vi":"Tuy cơ hội lần này là do số phận ban cho nhưng nắm được hay không còn phải dựa vào bản thân."}],"related":[{"hanzi":"赏赐","pinyin":"shǎngcì","vi":"ban thưởng"},{"hanzi":"恩赐","pinyin":"ēncì","vi":"ân huệ"},{"hanzi":"赐教","pinyin":"cìjiào","vi":"chỉ giáo"},{"hanzi":"赠送","pinyin":"zèngsòng","vi":"tặng"}],"traditional":"賜"},{"id":"赐教","hanzi":"赐教","pinyin":"cìjiào","meaning_vi":"chỉ giáo, chỉ bảo (kính ngữ)","explanation":"赐 (tứ – ban cho) + 教 (giáo – dạy bảo) → xin người khác ban cho lời dạy; lời khiêm tốn, lịch sự.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"请您多多赐教。","pinyin":"Qǐng nín duōduō cìjiào.","vi":"Kính mong ông chỉ giáo nhiều cho."},{"type":"simple","zh":"文章写得不好，还望各位专家赐教。","pinyin":"Wénzhāng xiě de bù hǎo, hái wàng gèwèi zhuānjiā cìjiào.","vi":"Bài viết còn kém, kính mong các chuyên gia chỉ giáo."},{"type":"compound","zh":"如果您发现有不妥之处，就请不吝赐教。","pinyin":"Rúguǒ nín fāxiàn yǒu bùtuǒ zhī chù, jiù qǐng búlìn cìjiào.","vi":"Nếu ngài phát hiện chỗ nào chưa ổn, xin đừng ngần ngại chỉ giáo."}],"related":[{"hanzi":"指教","pinyin":"zhǐjiào","vi":"chỉ giáo"},{"hanzi":"请教","pinyin":"qǐngjiào","vi":"thỉnh giáo"},{"hanzi":"指点","pinyin":"zhǐdiǎn","vi":"chỉ bảo"},{"hanzi":"赐","pinyin":"cì","vi":"ban cho"}],"traditional":"賜教"},{"id":"匆匆","hanzi":"匆匆","pinyin":"cōngcōng","meaning_vi":"vội vã, vội vàng","explanation":"匆 (thông – vội) lặp lại → rất vội vàng; thường dùng 匆匆忙忙, 来去匆匆.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"他匆匆吃了几口饭。","pinyin":"Tā cōngcōng chīle jǐ kǒu fàn.","vi":"Anh ấy vội vàng ăn vài miếng cơm."},{"type":"simple","zh":"她匆匆看了一眼手表就出门了。","pinyin":"Tā cōngcōng kànle yìyǎn shǒubiǎo jiù chūmén le.","vi":"Cô ấy vội liếc đồng hồ rồi ra khỏi nhà."},{"type":"compound","zh":"虽然我们只是匆匆见了一面，但是我对他印象很深。","pinyin":"Suīrán wǒmen zhǐshì cōngcōng jiànle yímiàn, dànshì wǒ duì tā yìnxiàng hěn shēn.","vi":"Tuy chúng tôi chỉ gặp nhau vội vàng một lần nhưng tôi có ấn tượng rất sâu về anh ấy."}],"related":[{"hanzi":"匆忙","pinyin":"cōngmáng","vi":"vội vàng"},{"hanzi":"急忙","pinyin":"jímáng","vi":"vội vã"},{"hanzi":"慌忙","pinyin":"huāngmáng","vi":"cuống quýt"},{"hanzi":"从容","pinyin":"cóngróng","vi":"ung dung"}]},{"id":"葱","hanzi":"葱","pinyin":"cōng","meaning_vi":"hành lá","explanation":"葱 (thông – cây hành) → hành lá, loại rau gia vị; 小葱 hành lá nhỏ, 大葱 hành boa-rô.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🧅","examples":[{"type":"basic","zh":"面条上撒点葱。","pinyin":"Miàntiáo shang sǎ diǎn cōng.","vi":"Rắc ít hành lá lên mì."},{"type":"simple","zh":"妈妈去菜市场买了一把葱。","pinyin":"Māma qù càishìchǎng mǎile yì bǎ cōng.","vi":"Mẹ đi chợ mua một bó hành lá."},{"type":"compound","zh":"因为孩子不吃葱，所以我做菜时都不放。","pinyin":"Yīnwèi háizi bù chī cōng, suǒyǐ wǒ zuòcài shí dōu bú fàng.","vi":"Vì con không ăn hành nên khi nấu tôi đều không cho vào."}],"related":[{"hanzi":"姜","pinyin":"jiāng","vi":"gừng"},{"hanzi":"蒜","pinyin":"suàn","vi":"tỏi"},{"hanzi":"洋葱","pinyin":"yángcōng","vi":"hành tây"},{"hanzi":"香菜","pinyin":"xiāngcài","vi":"rau mùi"}],"traditional":"蔥"},{"id":"从今以后","hanzi":"从今以后","pinyin":"cóngjīn-yǐhòu","meaning_vi":"từ nay về sau","explanation":"从 (tùng – từ) + 今 (kim – nay) + 以后 (dĩ hậu – về sau) → kể từ bây giờ trở đi; dùng khi hứa hẹn, quyết tâm thay đổi.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"🌅","examples":[{"type":"basic","zh":"从今以后我不抽烟了。","pinyin":"Cóng jīn yǐhòu wǒ bù chōuyān le.","vi":"Từ nay về sau tôi không hút thuốc nữa."},{"type":"simple","zh":"从今以后，你就是我们团队的一员了。","pinyin":"Cóng jīn yǐhòu, nǐ jiùshì wǒmen tuánduì de yìyuán le.","vi":"Từ nay về sau bạn là một thành viên của đội chúng tôi."},{"type":"compound","zh":"既然已经结婚了，从今以后我们就要互相照顾。","pinyin":"Jìrán yǐjīng jiéhūn le, cóng jīn yǐhòu wǒmen jiùyào hùxiāng zhàogù.","vi":"Đã kết hôn rồi thì từ nay về sau chúng ta phải chăm sóc lẫn nhau."}],"related":[{"hanzi":"今后","pinyin":"jīnhòu","vi":"sau này"},{"hanzi":"从此","pinyin":"cóngcǐ","vi":"từ đó"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"sau này"},{"hanzi":"从现在起","pinyin":"cóngxiànzàiqǐ","vi":"từ giờ trở đi"}],"traditional":"從今以後"},{"id":"从来不","hanzi":"从来不","pinyin":"cóngláibù","meaning_vi":"chưa bao giờ, không bao giờ","explanation":"从来 (tòng lai – từ trước đến nay) + 不 (bất – không) → từ trước tới nay không hề làm; chỉ thói quen, tính cách.","hsk_level":"7-9","tags":["pho-tu"],"image":"🙅‍♂️","examples":[{"type":"basic","zh":"他从来不喝酒。","pinyin":"Tā cóngláibù hējiǔ.","vi":"Anh ấy chưa bao giờ uống rượu."},{"type":"simple","zh":"我妈妈从来不在晚上九点以后吃东西。","pinyin":"Wǒ māma cóngláibú zài wǎnshang jiǔ diǎn yǐhòu chī dōngxi.","vi":"Mẹ tôi không bao giờ ăn gì sau chín giờ tối."},{"type":"compound","zh":"虽然他工作很忙，但是从来不错过女儿的生日。","pinyin":"Suīrán tā gōngzuò hěn máng, dànshì cóngláibú cuòguò nǚ'ér de shēngrì.","vi":"Tuy công việc rất bận nhưng anh ấy chưa bao giờ bỏ lỡ sinh nhật con gái."}],"related":[{"hanzi":"从来","pinyin":"cónglái","vi":"từ trước tới nay"},{"hanzi":"从未","pinyin":"cóngwèi","vi":"chưa từng"},{"hanzi":"从不","pinyin":"cóngbù","vi":"không bao giờ"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"luôn luôn"}],"traditional":"從來不"},{"id":"从头","hanzi":"从头","pinyin":"cóngtóu","meaning_vi":"từ đầu, lại từ đầu","explanation":"从 (tùng – từ) + 头 (đầu) → bắt đầu từ chỗ đầu tiên; hoặc làm lại lần nữa từ đầu.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"我们从头再来。","pinyin":"Wǒmen cóngtóu zài lái.","vi":"Chúng ta làm lại từ đầu."},{"type":"simple","zh":"请你把事情从头到尾讲一遍。","pinyin":"Qǐng nǐ bǎ shìqing cóngtóu dào wěi jiǎng yíbiàn.","vi":"Bạn hãy kể lại sự việc từ đầu đến cuối một lượt."},{"type":"compound","zh":"如果这次实验失败了，我们就只能从头开始。","pinyin":"Rúguǒ zhè cì shíyàn shībài le, wǒmen jiù zhǐnéng cóngtóu kāishǐ.","vi":"Nếu lần thí nghiệm này thất bại thì chúng ta chỉ còn cách bắt đầu lại từ đầu."}],"related":[{"hanzi":"重新","pinyin":"chóngxīn","vi":"lại lần nữa"},{"hanzi":"从头到尾","pinyin":"cóngtóudàowěi","vi":"từ đầu đến cuối"},{"hanzi":"开头","pinyin":"kāitóu","vi":"mở đầu"},{"hanzi":"起初","pinyin":"qǐchū","vi":"lúc đầu"}],"traditional":"從頭"},{"id":"从未","hanzi":"从未","pinyin":"cóngwèi","meaning_vi":"chưa từng, chưa bao giờ","explanation":"从 (tùng – từ) + 未 (vị – chưa) → từ trước đến giờ chưa từng xảy ra; văn viết, tương đương 从来没有.","hsk_level":"7-9","tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"我从未去过西藏。","pinyin":"Wǒ cóngwèi qùguo Xīzàng.","vi":"Tôi chưa từng đến Tây Tạng."},{"type":"simple","zh":"这种情况以前从未发生过。","pinyin":"Zhè zhǒng qíngkuàng yǐqián cóngwèi fāshēng guo.","vi":"Tình huống này trước đây chưa từng xảy ra."},{"type":"compound","zh":"虽然他从未学过画画，但是画得非常像。","pinyin":"Suīrán tā cóngwèi xuéguo huàhuà, dànshì huà de fēicháng xiàng.","vi":"Tuy anh ấy chưa từng học vẽ nhưng vẽ rất giống."}],"related":[{"hanzi":"从来没有","pinyin":"cóngláiméiyǒu","vi":"chưa bao giờ"},{"hanzi":"从不","pinyin":"cóngbù","vi":"không bao giờ"},{"hanzi":"未曾","pinyin":"wèicéng","vi":"chưa từng"},{"hanzi":"曾经","pinyin":"céngjīng","vi":"đã từng"}],"traditional":"從未"},{"id":"从业","hanzi":"从业","pinyin":"cóngyè","meaning_vi":"làm nghề, hành nghề","explanation":"从 (tùng – theo) + 业 (nghiệp – nghề) → theo đuổi, làm một nghề nào đó; thường gặp 从业人员, 从业经验.","hsk_level":"7-9","tags":["dong-tu","nghe-nghiep"],"image":"🛠️","examples":[{"type":"basic","zh":"他从业已经二十年了。","pinyin":"Tā cóngyè yǐjīng èrshí nián le.","vi":"Ông ấy làm nghề đã hai mươi năm rồi."},{"type":"simple","zh":"这一行的从业人员需要持证上岗。","pinyin":"Zhè yìháng de cóngyè rényuán xūyào chí zhèng shànggǎng.","vi":"Người làm nghề này cần có chứng chỉ mới được làm việc."},{"type":"compound","zh":"如果没有三年以上的从业经验，就不能申请这个职位。","pinyin":"Rúguǒ méiyǒu sān nián yǐshàng de cóngyè jīngyàn, jiù bù néng shēnqǐng zhè ge zhíwèi.","vi":"Nếu không có trên ba năm kinh nghiệm hành nghề thì không thể ứng tuyển vị trí này."}],"related":[{"hanzi":"就业","pinyin":"jiùyè","vi":"có việc làm"},{"hanzi":"职业","pinyin":"zhíyè","vi":"nghề nghiệp"},{"hanzi":"行业","pinyin":"hángyè","vi":"ngành nghề"},{"hanzi":"从事","pinyin":"cóngshì","vi":"làm (nghề)"}],"traditional":"從業"},{"id":"从早到晚","hanzi":"从早到晚","pinyin":"cóngzǎo-dàowǎn","meaning_vi":"từ sáng đến tối, suốt ngày","explanation":"从 (từ) + 早 (tảo – sáng) + 到 (đáo – đến) + 晚 (vãn – tối) → từ sáng đến tối, cả ngày liền.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"🌞","examples":[{"type":"basic","zh":"他从早到晚都在工作。","pinyin":"Tā cóng zǎo dào wǎn dōu zài gōngzuò.","vi":"Anh ấy làm việc từ sáng đến tối."},{"type":"simple","zh":"周末孩子从早到晚抱着手机玩游戏。","pinyin":"Zhōumò háizi cóng zǎo dào wǎn bàozhe shǒujī wán yóuxì.","vi":"Cuối tuần bọn trẻ ôm điện thoại chơi game từ sáng đến tối."},{"type":"compound","zh":"虽然她从早到晚忙个不停，但是从来不喊累。","pinyin":"Suīrán tā cóng zǎo dào wǎn máng gè bùtíng, dànshì cóngláibù hǎn lèi.","vi":"Tuy cô ấy bận rộn không ngừng từ sáng đến tối nhưng chưa bao giờ kêu mệt."}],"related":[{"hanzi":"整天","pinyin":"zhěngtiān","vi":"cả ngày"},{"hanzi":"一天到晚","pinyin":"yìtiāndàowǎn","vi":"suốt ngày"},{"hanzi":"早出晚归","pinyin":"zǎochūwǎnguī","vi":"đi sớm về khuya"},{"hanzi":"日夜","pinyin":"rìyè","vi":"ngày đêm"}],"traditional":"從早到晚"},{"id":"凑","hanzi":"凑","pinyin":"còu","meaning_vi":"góp, gom lại; xích lại gần; tình cờ","explanation":"凑 (thấu – tụ lại) → gom góp lại cho đủ; tiến sát lại gần; gặp đúng lúc (凑巧).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"大家凑点钱买礼物吧。","pinyin":"Dàjiā còu diǎn qián mǎi lǐwù ba.","vi":"Mọi người góp ít tiền mua quà nhé."},{"type":"simple","zh":"她把耳朵凑过来听我说悄悄话。","pinyin":"Tā bǎ ěrduo còu guòlái tīng wǒ shuō qiāoqiaohuà.","vi":"Cô ấy ghé tai lại nghe tôi nói thầm."},{"type":"compound","zh":"因为人数凑不够，所以这次比赛只好取消了。","pinyin":"Yīnwèi rénshù còu búgòu, suǒyǐ zhè cì bǐsài zhǐhǎo qǔxiāo le.","vi":"Vì gom không đủ người nên trận đấu lần này đành phải hủy."}],"related":[{"hanzi":"凑巧","pinyin":"còuqiǎo","vi":"tình cờ"},{"hanzi":"凑热闹","pinyin":"còurènao","vi":"góp vui"},{"hanzi":"拼凑","pinyin":"pīncòu","vi":"chắp vá"},{"hanzi":"凑合","pinyin":"còuhe","vi":"tạm được"}],"traditional":"湊"},{"id":"粗暴","hanzi":"粗暴","pinyin":"cūbào","meaning_vi":"thô bạo, lỗ mãng","explanation":"粗 (thô – thô kệch) + 暴 (bạo – hung bạo) → thô lỗ và hung dữ, không biết kiềm chế.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😤","examples":[{"type":"basic","zh":"他说话很粗暴。","pinyin":"Tā shuōhuà hěn cūbào.","vi":"Anh ta ăn nói rất thô bạo."},{"type":"simple","zh":"父母不应该用粗暴的方式教育孩子。","pinyin":"Fùmǔ bù yīnggāi yòng cūbào de fāngshì jiàoyù háizi.","vi":"Cha mẹ không nên dùng cách thô bạo để dạy con."},{"type":"compound","zh":"即使顾客态度不好，服务员也不能粗暴对待他们。","pinyin":"Jíshǐ gùkè tàidu bù hǎo, fúwùyuán yě bù néng cūbào duìdài tāmen.","vi":"Dù khách hàng thái độ không tốt, nhân viên phục vụ cũng không được đối xử thô bạo với họ."}],"related":[{"hanzi":"粗鲁","pinyin":"cūlǔ","vi":"lỗ mãng"},{"hanzi":"暴力","pinyin":"bàolì","vi":"bạo lực"},{"hanzi":"温柔","pinyin":"wēnróu","vi":"dịu dàng"},{"hanzi":"野蛮","pinyin":"yěmán","vi":"dã man"}]},{"id":"粗略","hanzi":"粗略","pinyin":"cūlüè","meaning_vi":"sơ lược, đại khái","explanation":"粗 (thô – sơ sài) + 略 (lược – sơ qua) → không chi tiết, chỉ nắm đại khái.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📝","examples":[{"type":"basic","zh":"我粗略看了一遍。","pinyin":"Wǒ cūlüè kànle yíbiàn.","vi":"Tôi đã xem lướt qua một lượt."},{"type":"simple","zh":"粗略估计，今天来了五千多名观众。","pinyin":"Cūlüè gūjì, jīntiān láile wǔ qiān duō míng guānzhòng.","vi":"Ước tính sơ bộ, hôm nay có hơn năm nghìn khán giả đến."},{"type":"compound","zh":"虽然这只是一个粗略的计划，但是方向已经很清楚了。","pinyin":"Suīrán zhè zhǐshì yí gè cūlüè de jìhuà, dànshì fāngxiàng yǐjīng hěn qīngchu le.","vi":"Tuy đây chỉ là một kế hoạch sơ lược nhưng phương hướng đã rất rõ ràng."}],"related":[{"hanzi":"大概","pinyin":"dàgài","vi":"đại khái"},{"hanzi":"大致","pinyin":"dàzhì","vi":"đại thể"},{"hanzi":"详细","pinyin":"xiángxì","vi":"chi tiết"},{"hanzi":"简略","pinyin":"jiǎnlüè","vi":"giản lược"}]},{"id":"翠绿","hanzi":"翠绿","pinyin":"cuìlǜ","meaning_vi":"xanh biếc, xanh ngọc bích","explanation":"翠 (thúy – xanh ngọc, lông chim trả) + 绿 (lục – xanh lá) → màu xanh lá tươi, trong như ngọc bích.","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🍀","examples":[{"type":"basic","zh":"山上的竹子一片翠绿。","pinyin":"Shān shang de zhúzi yípiàn cuìlǜ.","vi":"Rừng tre trên núi xanh biếc một màu."},{"type":"simple","zh":"雨后的稻田显得格外翠绿。","pinyin":"Yǔ hòu de dàotián xiǎnde géwài cuìlǜ.","vi":"Đồng lúa sau mưa trông xanh biếc lạ thường."},{"type":"compound","zh":"虽然已经入秋了，但是院子里的草依然翠绿。","pinyin":"Suīrán yǐjīng rù qiū le, dànshì yuànzi li de cǎo yīrán cuìlǜ.","vi":"Tuy đã sang thu nhưng cỏ trong sân vẫn xanh biếc."}],"related":[{"hanzi":"碧绿","pinyin":"bìlǜ","vi":"xanh biếc"},{"hanzi":"嫩绿","pinyin":"nènlǜ","vi":"xanh non"},{"hanzi":"青翠","pinyin":"qīngcuì","vi":"xanh tươi"},{"hanzi":"绿色","pinyin":"lǜsè","vi":"màu xanh lá"}],"traditional":"翠綠"},{"id":"错别字","hanzi":"错别字","pinyin":"cuòbiézì","meaning_vi":"chữ viết sai, lỗi chính tả","explanation":"错 (thác – sai) + 别 (biệt – khác, nhầm) + 字 (tự – chữ) → chữ viết sai nét hoặc dùng nhầm chữ khác.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"作文里有很多错别字。","pinyin":"Zuòwén li yǒu hěn duō cuòbiézì.","vi":"Bài văn có rất nhiều chữ viết sai."},{"type":"simple","zh":"交稿之前，请再检查一下有没有错别字。","pinyin":"Jiāo gǎo zhīqián, qǐng zài jiǎnchá yíxià yǒuméiyǒu cuòbiézì.","vi":"Trước khi nộp bản thảo, hãy kiểm tra lại xem có lỗi chính tả không."},{"type":"compound","zh":"如果简历上有错别字，就会给人留下不认真的印象。","pinyin":"Rúguǒ jiǎnlì shang yǒu cuòbiézì, jiù huì gěi rén liúxià bú rènzhēn de yìnxiàng.","vi":"Nếu sơ yếu lý lịch có chữ viết sai thì sẽ để lại ấn tượng thiếu cẩn thận."}],"related":[{"hanzi":"错字","pinyin":"cuòzì","vi":"chữ sai"},{"hanzi":"白字","pinyin":"báizì","vi":"chữ dùng nhầm"},{"hanzi":"笔画","pinyin":"bǐhuà","vi":"nét chữ"},{"hanzi":"校对","pinyin":"jiàoduì","vi":"soát lỗi"}],"traditional":"錯別字"},{"id":"错觉","hanzi":"错觉","pinyin":"cuòjué","meaning_vi":"ảo giác, cảm giác sai, nhầm tưởng","explanation":"错 (thác – sai) + 觉 (giác – cảm giác) → cảm nhận sai so với thực tế.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🌀","examples":[{"type":"basic","zh":"这只是你的错觉。","pinyin":"Zhè zhǐshì nǐ de cuòjué.","vi":"Đó chỉ là cảm giác sai của bạn thôi."},{"type":"simple","zh":"镜子让人产生房间很大的错觉。","pinyin":"Jìngzi ràng rén chǎnshēng fángjiān hěn dà de cuòjué.","vi":"Tấm gương khiến người ta có ảo giác căn phòng rất rộng."},{"type":"compound","zh":"虽然我有一种他在生气的错觉，但是其实他只是累了。","pinyin":"Suīrán wǒ yǒu yì zhǒng tā zài shēngqì de cuòjué, dànshì qíshí tā zhǐshì lèi le.","vi":"Tuy tôi có cảm giác nhầm là anh ấy đang giận nhưng thật ra anh ấy chỉ mệt thôi."}],"related":[{"hanzi":"幻觉","pinyin":"huànjué","vi":"ảo giác"},{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"},{"hanzi":"误会","pinyin":"wùhuì","vi":"hiểu lầm"},{"hanzi":"视觉","pinyin":"shìjué","vi":"thị giác"}],"traditional":"錯覺"},{"id":"错位","hanzi":"错位","pinyin":"cuòwèi","meaning_vi":"lệch vị trí, sai chỗ, trật khớp","explanation":"错 (thác – sai) + 位 (vị – vị trí) → lệch khỏi vị trí vốn có; y học chỉ trật khớp, lệch xương.","hsk_level":"7-9","tags":["dong-tu"],"image":"🦴","examples":[{"type":"basic","zh":"他的肩膀错位了。","pinyin":"Tā de jiānbǎng cuòwèi le.","vi":"Vai anh ấy bị trật khớp rồi."},{"type":"simple","zh":"打印出来的表格有几行错位了。","pinyin":"Dǎyìn chūlái de biǎogé yǒu jǐ háng cuòwèi le.","vi":"Bảng in ra có mấy dòng bị lệch."},{"type":"compound","zh":"因为骨头错位了，所以医生要先帮他复位。","pinyin":"Yīnwèi gǔtou cuòwèi le, suǒyǐ yīshēng yào xiān bāng tā fùwèi.","vi":"Vì xương bị lệch nên bác sĩ phải nắn lại trước."}],"related":[{"hanzi":"脱臼","pinyin":"tuōjiù","vi":"trật khớp"},{"hanzi":"复位","pinyin":"fùwèi","vi":"nắn lại"},{"hanzi":"位置","pinyin":"wèizhi","vi":"vị trí"},{"hanzi":"错乱","pinyin":"cuòluàn","vi":"rối loạn"}],"traditional":"錯位"},{"id":"搭建","hanzi":"搭建","pinyin":"dājiàn","meaning_vi":"dựng, dựng tạm, xây dựng","explanation":"搭 (đáp – gác, dựng) + 建 (kiến – xây) → dựng lên (thường bằng vật liệu đơn giản); nghĩa rộng: xây dựng nền tảng, khung.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛺","examples":[{"type":"basic","zh":"工人们在搭建舞台。","pinyin":"Gōngrénmen zài dājiàn wǔtái.","vi":"Công nhân đang dựng sân khấu."},{"type":"simple","zh":"他们在山脚下搭建了几个帐篷。","pinyin":"Tāmen zài shān jiǎoxià dājiànle jǐ gè zhàngpeng.","vi":"Họ dựng mấy cái lều dưới chân núi."},{"type":"compound","zh":"只要搭建好合作平台，各方就能更好地交流。","pinyin":"Zhǐyào dājiàn hǎo hézuò píngtái, gèfāng jiù néng gèng hǎo de jiāoliú.","vi":"Chỉ cần xây dựng tốt nền tảng hợp tác thì các bên có thể trao đổi tốt hơn."}],"related":[{"hanzi":"建造","pinyin":"jiànzào","vi":"xây dựng"},{"hanzi":"搭","pinyin":"dā","vi":"dựng, gác"},{"hanzi":"建立","pinyin":"jiànlì","vi":"thiết lập"},{"hanzi":"拆除","pinyin":"chāichú","vi":"tháo dỡ"}]},{"id":"打岔","hanzi":"打岔","pinyin":"dǎchà","meaning_vi":"ngắt lời, xen ngang, lái sang chuyện khác","explanation":"打 (đả – làm) + 岔 (xóa – rẽ nhánh) → làm câu chuyện rẽ sang hướng khác, cắt ngang lời người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤚","examples":[{"type":"basic","zh":"别打岔，听我说完。","pinyin":"Bié dǎchà, tīng wǒ shuō wán.","vi":"Đừng ngắt lời, nghe tôi nói hết đã."},{"type":"simple","zh":"他一提到钱的事，她就故意打岔。","pinyin":"Tā yì tídào qián de shì, tā jiù gùyì dǎchà.","vi":"Hễ anh ấy nhắc đến chuyện tiền là cô ấy cố ý lái sang chuyện khác."},{"type":"compound","zh":"如果你总是打岔，我们就永远讨论不完。","pinyin":"Rúguǒ nǐ zǒngshì dǎchà, wǒmen jiù yǒngyuǎn tǎolùn bù wán.","vi":"Nếu bạn cứ xen ngang mãi thì chúng ta sẽ không bao giờ thảo luận xong."}],"related":[{"hanzi":"插嘴","pinyin":"chāzuǐ","vi":"chen miệng"},{"hanzi":"打断","pinyin":"dǎduàn","vi":"cắt ngang"},{"hanzi":"岔开","pinyin":"chàkāi","vi":"lái đi"},{"hanzi":"转移话题","pinyin":"zhuǎnyíhuàtí","vi":"đổi chủ đề"}]},{"id":"打倒","hanzi":"打倒","pinyin":"dǎdǎo","meaning_vi":"đánh đổ, lật đổ, quật ngã","explanation":"打 (đả – đánh) + 倒 (đảo – ngã) → đánh cho ngã; nghĩa chính trị: lật đổ (khẩu hiệu “打倒…!”).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👊","examples":[{"type":"basic","zh":"他一拳把对手打倒了。","pinyin":"Tā yì quán bǎ duìshǒu dǎdǎo le.","vi":"Anh ấy đấm một cú làm đối thủ ngã gục."},{"type":"simple","zh":"再大的困难也打倒不了我们。","pinyin":"Zài dà de kùnnan yě dǎdǎo bùliǎo wǒmen.","vi":"Khó khăn lớn đến mấy cũng không quật ngã được chúng ta."},{"type":"compound","zh":"虽然他被病痛打倒过一次，但是很快又重新站了起来。","pinyin":"Suīrán tā bèi bìngtòng dǎdǎoguo yí cì, dànshì hěn kuài yòu chóngxīn zhànle qǐlái.","vi":"Tuy từng bị bệnh tật quật ngã một lần nhưng anh ấy nhanh chóng đứng dậy trở lại."}],"related":[{"hanzi":"推翻","pinyin":"tuīfān","vi":"lật đổ"},{"hanzi":"击倒","pinyin":"jīdǎo","vi":"hạ gục"},{"hanzi":"倒下","pinyin":"dǎoxià","vi":"ngã xuống"},{"hanzi":"打败","pinyin":"dǎbài","vi":"đánh bại"}]},{"id":"打盹儿","hanzi":"打盹儿","pinyin":"dǎdǔnr","meaning_vi":"chợp mắt, ngủ gật","explanation":"打 (đả – làm) + 盹儿 (độn – giấc ngủ ngắn) → ngủ lơ mơ một chút, chợp mắt.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"爷爷在沙发上打盹儿。","pinyin":"Yéye zài shāfā shang dǎdǔnr.","vi":"Ông nội đang chợp mắt trên sofa."},{"type":"simple","zh":"开会时他靠在椅子上打盹儿。","pinyin":"Kāihuì shí tā kào zài yǐzi shang dǎdǔnr.","vi":"Lúc họp anh ấy dựa vào ghế ngủ gật."},{"type":"compound","zh":"如果开车时想打盹儿，就一定要停下来休息。","pinyin":"Rúguǒ kāichē shí xiǎng dǎdǔnr, jiù yídìngyào tíngxiàlái xiūxi.","vi":"Nếu đang lái xe mà buồn ngủ muốn chợp mắt thì nhất định phải dừng lại nghỉ."}],"related":[{"hanzi":"打瞌睡","pinyin":"dǎkēshuì","vi":"ngủ gật"},{"hanzi":"午睡","pinyin":"wǔshuì","vi":"ngủ trưa"},{"hanzi":"小睡","pinyin":"xiǎoshuì","vi":"chợp mắt"},{"hanzi":"犯困","pinyin":"fànkùn","vi":"buồn ngủ"}],"traditional":"打盹兒"},{"id":"打搅","hanzi":"打搅","pinyin":"dǎjiǎo","meaning_vi":"làm phiền, quấy rầy","explanation":"打 (đả – làm) + 搅 (giảo – khuấy) → khuấy động, làm phiền người khác; cũng là câu khách sáo khi đến chơi nhà (打搅了).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🔕","examples":[{"type":"basic","zh":"对不起，打搅一下。","pinyin":"Duìbuqǐ, dǎjiǎo yíxià.","vi":"Xin lỗi, làm phiền một chút."},{"type":"simple","zh":"他正在复习，你别去打搅他。","pinyin":"Tā zhèngzài fùxí, nǐ bié qù dǎjiǎo tā.","vi":"Cậu ấy đang ôn bài, bạn đừng đến làm phiền."},{"type":"compound","zh":"既然您这么忙，我就不再多打搅您了。","pinyin":"Jìrán nín zhème máng, wǒ jiù bú zài duō dǎjiǎo nín le.","vi":"Ngài đã bận như vậy thì tôi không làm phiền ngài thêm nữa."}],"related":[{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"làm phiền"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền"},{"hanzi":"干扰","pinyin":"gānrǎo","vi":"quấy nhiễu"},{"hanzi":"搅","pinyin":"jiǎo","vi":"khuấy"}],"traditional":"打攪"},{"id":"打磨","hanzi":"打磨","pinyin":"dǎmó","meaning_vi":"mài, đánh bóng, trau chuốt","explanation":"打 (đả – làm) + 磨 (ma – mài) → mài cho nhẵn bóng; nghĩa bóng: gọt giũa, trau chuốt tác phẩm, kỹ năng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪚","examples":[{"type":"basic","zh":"木板要先打磨一下。","pinyin":"Mùbǎn yào xiān dǎmó yíxià.","vi":"Tấm gỗ phải mài nhẵn trước đã."},{"type":"simple","zh":"师傅把这块玉打磨得非常光滑。","pinyin":"Shīfu bǎ zhè kuài yù dǎmó de fēicháng guānghuá.","vi":"Người thợ mài miếng ngọc này rất nhẵn bóng."},{"type":"compound","zh":"虽然剧本写好了，但是导演还想再打磨几个月。","pinyin":"Suīrán jùběn xiě hǎo le, dànshì dǎoyǎn hái xiǎng zài dǎmó jǐ gèyuè.","vi":"Tuy kịch bản đã viết xong nhưng đạo diễn còn muốn trau chuốt thêm mấy tháng."}],"related":[{"hanzi":"磨","pinyin":"mó","vi":"mài"},{"hanzi":"抛光","pinyin":"pāoguāng","vi":"đánh bóng"},{"hanzi":"雕琢","pinyin":"diāozhuó","vi":"chạm trổ, gọt giũa"},{"hanzi":"锤炼","pinyin":"chuíliàn","vi":"tôi luyện"}]},{"id":"打通","hanzi":"打通","pinyin":"dǎtōng","meaning_vi":"khai thông, đả thông; gọi được (điện thoại)","explanation":"打 (đả – làm) + 通 (thông – thông suốt) → làm cho thông, bỏ chướng ngại; cũng nói gọi điện được (电话打通了).","hsk_level":"7-9","tags":["dong-tu"],"image":"📞","examples":[{"type":"basic","zh":"电话终于打通了。","pinyin":"Diànhuà zhōngyú dǎtōng le.","vi":"Cuối cùng cũng gọi được điện thoại."},{"type":"simple","zh":"这条隧道打通以后，开车只要十分钟。","pinyin":"Zhè tiáo suìdào dǎtōng yǐhòu, kāichē zhǐyào shí fēnzhōng.","vi":"Sau khi đường hầm này thông, lái xe chỉ mất mười phút."},{"type":"compound","zh":"如果能打通销售渠道，我们的产品就不愁卖不出去。","pinyin":"Rúguǒ néng dǎtōng xiāoshòu qúdào, wǒmen de chǎnpǐn jiù bù chóu mài bù chūqù.","vi":"Nếu khai thông được kênh tiêu thụ thì sản phẩm của chúng ta không lo không bán được."}],"related":[{"hanzi":"畅通","pinyin":"chàngtōng","vi":"thông suốt"},{"hanzi":"开通","pinyin":"kāitōng","vi":"khai thông"},{"hanzi":"接通","pinyin":"jiētōng","vi":"kết nối"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"}]},{"id":"大包大揽","hanzi":"大包大揽","pinyin":"dàbāo-dàlǎn","meaning_vi":"ôm đồm, ôm hết mọi việc","explanation":"包 (bao – bao trọn) + 揽 (lãm – ôm lấy), có 大 nhấn mạnh → ôm trọn hết mọi việc vào mình; thường mang ý chê ôm đồm.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"🫳","examples":[{"type":"basic","zh":"他什么事都大包大揽。","pinyin":"Tā shénmeshì dōu dàbāodàlǎn.","vi":"Việc gì anh ấy cũng ôm hết vào người."},{"type":"simple","zh":"父母不该对孩子的事大包大揽。","pinyin":"Fùmǔ bùgāi duì háizi de shì dàbāodàlǎn.","vi":"Cha mẹ không nên ôm đồm hết mọi việc của con cái."},{"type":"compound","zh":"如果领导事事大包大揽，下属就得不到锻炼。","pinyin":"Rúguǒ lǐngdǎo shìshì dàbāodàlǎn, xiàshǔ jiù débúdào duànliàn.","vi":"Nếu lãnh đạo việc gì cũng ôm hết thì cấp dưới không được rèn luyện."}],"related":[{"hanzi":"包办","pinyin":"bāobàn","vi":"làm thay hết"},{"hanzi":"揽活","pinyin":"lǎnhuó","vi":"nhận việc"},{"hanzi":"独揽","pinyin":"dúlǎn","vi":"độc chiếm"},{"hanzi":"一手包办","pinyin":"yìshǒubāobàn","vi":"một tay lo liệu"}],"traditional":"大包大攬"},{"id":"大笔","hanzi":"大笔","pinyin":"dàbǐ","meaning_vi":"món (tiền) lớn, khoản lớn","explanation":"大 (đại – lớn) + 笔 (bút – lượng từ của khoản tiền) → một khoản tiền lớn; thường dùng 一大笔钱, 大笔投资.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"他赚了一大笔钱。","pinyin":"Tā zhuànle yí dàbǐ qián.","vi":"Anh ấy kiếm được một khoản tiền lớn."},{"type":"simple","zh":"公司今年在研发上投入了大笔资金。","pinyin":"Gōngsī jīnnián zài yánfā shang tóurùle dàbǐ zījīn.","vi":"Năm nay công ty đã rót khoản vốn lớn vào nghiên cứu phát triển."},{"type":"compound","zh":"虽然他继承了一大笔遗产，但是生活依然很节俭。","pinyin":"Suīrán tā jìchéngle yí dàbǐ yíchǎn, dànshì shēnghuó yīrán hěn jiéjiǎn.","vi":"Tuy thừa kế một khoản di sản lớn nhưng anh ấy vẫn sống rất tiết kiệm."}],"related":[{"hanzi":"笔","pinyin":"bǐ","vi":"khoản (tiền)"},{"hanzi":"巨款","pinyin":"jùkuǎn","vi":"khoản tiền khổng lồ"},{"hanzi":"大量","pinyin":"dàliàng","vi":"lượng lớn"},{"hanzi":"一笔钱","pinyin":"yìbǐqián","vi":"một khoản tiền"}],"traditional":"大筆"},{"id":"大吃一惊","hanzi":"大吃一惊","pinyin":"dàchī-yìjīng","meaning_vi":"giật mình, kinh ngạc","explanation":"吃 (ngật – chịu) + 惊 (kinh – sợ hãi), có 大 nhấn mạnh → bị giật mình mạnh, rất kinh ngạc.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"听到消息，我大吃一惊。","pinyin":"Tīngdào xiāoxi, wǒ dàchīyìjīng.","vi":"Nghe tin, tôi giật mình kinh ngạc."},{"type":"simple","zh":"他的考试成绩让所有人大吃一惊。","pinyin":"Tā de kǎoshì chéngjì ràng suǒyǒurén dàchīyìjīng.","vi":"Kết quả thi của cậu ấy khiến tất cả mọi người kinh ngạc."},{"type":"compound","zh":"一打开门，她就大吃一惊，因为家里坐满了来给她过生日的朋友。","pinyin":"Yìdǎ kāimén, tā jiù dàchīyìjīng, yīnwèi jiāli zuò mǎnle lái gěi tā guòshēngrì de péngyou.","vi":"Vừa mở cửa cô ấy đã giật mình, vì trong nhà đầy bạn bè đến mừng sinh nhật cô."}],"related":[{"hanzi":"吃惊","pinyin":"chījīng","vi":"ngạc nhiên"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"chấn động"},{"hanzi":"目瞪口呆","pinyin":"mùdèngkǒudāi","vi":"trợn mắt há mồm"}],"traditional":"大吃一驚"},{"id":"大大咧咧","hanzi":"大大咧咧","pinyin":"dàdaliēliē","meaning_vi":"vô tư, xuề xòa, cẩu thả","explanation":"大大 + 咧咧 (liệt liệt – nói năng tùy tiện) → tính cách thoải mái, không câu nệ tiểu tiết, đôi khi đến mức cẩu thả.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🤷","examples":[{"type":"basic","zh":"她性格大大咧咧的。","pinyin":"Tā xìnggé dàdaliēliē de.","vi":"Tính cô ấy xuề xòa vô tư."},{"type":"simple","zh":"他大大咧咧地坐在了老板的椅子上。","pinyin":"Tā dàdaliēliē de zuò zài le lǎobǎn de yǐzi shang.","vi":"Anh ta vô tư ngồi phịch xuống ghế của sếp."},{"type":"compound","zh":"虽然他平时大大咧咧，但是工作起来非常细心。","pinyin":"Suīrán tā píngshí dàdaliēliē, dànshì gōngzuò qǐlái fēicháng xìxīn.","vi":"Tuy ngày thường anh ấy xuề xòa nhưng khi làm việc lại rất tỉ mỉ."}],"related":[{"hanzi":"马虎","pinyin":"mǎhu","vi":"cẩu thả"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"tùy tiện"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"sơ ý"},{"hanzi":"细心","pinyin":"xìxīn","vi":"tỉ mỉ"}]},{"id":"大地","hanzi":"大地","pinyin":"dàdì","meaning_vi":"mặt đất, đất mẹ","explanation":"大 (đại – lớn) + 地 (địa – đất) → mặt đất rộng lớn, đất mẹ; văn viết giàu hình ảnh.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌍","examples":[{"type":"basic","zh":"春风吹绿了大地。","pinyin":"Chūnfēng chuī lǜle dàdì.","vi":"Gió xuân thổi xanh mặt đất."},{"type":"simple","zh":"一场大雪把大地盖得白茫茫的。","pinyin":"Yì chǎng Dàxuě bǎ dàdì gài de báimángmáng de.","vi":"Một trận tuyết lớn phủ mặt đất trắng xóa."},{"type":"compound","zh":"虽然天还没亮，但是大地已经开始苏醒了。","pinyin":"Suīrán tiān hái méi liàng, dànshì dàdì yǐjīng kāishǐ sūxǐng le.","vi":"Tuy trời chưa sáng nhưng mặt đất đã bắt đầu thức giấc."}],"related":[{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"},{"hanzi":"天空","pinyin":"tiānkōng","vi":"bầu trời"},{"hanzi":"地球","pinyin":"dìqiú","vi":"trái đất"},{"hanzi":"大自然","pinyin":"dàzìrán","vi":"thiên nhiên"}]},{"id":"大队","hanzi":"大队","pinyin":"dàduì","meaning_vi":"đại đội, đoàn lớn, đội (sản xuất)","explanation":"大 (đại – lớn) + 队 (đội) → đơn vị đội lớn trong quân đội, công an, hoặc đội sản xuất ở nông thôn; cũng chỉ đoàn người đông.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👥","examples":[{"type":"basic","zh":"他是刑警大队的队长。","pinyin":"Tā shì xíngjǐng dàduì de duìzhǎng.","vi":"Anh ấy là đội trưởng đội cảnh sát hình sự."},{"type":"simple","zh":"大队人马浩浩荡荡地出发了。","pinyin":"Dàduì rénmǎ hàohàodàngdàng de chūfā le.","vi":"Đoàn người ngựa đông đảo rầm rộ xuất phát."},{"type":"compound","zh":"因为他走得太慢，所以很快就跟不上大队了。","pinyin":"Yīnwèi tā zǒu de tài màn, suǒyǐ hěn kuài jiù gēnbúshàng dàduì le.","vi":"Vì đi quá chậm nên anh ấy nhanh chóng không theo kịp đoàn."}],"related":[{"hanzi":"队伍","pinyin":"duìwu","vi":"đội ngũ"},{"hanzi":"中队","pinyin":"zhōngduì","vi":"trung đội"},{"hanzi":"小队","pinyin":"xiǎoduì","vi":"tiểu đội"},{"hanzi":"掉队","pinyin":"diàoduì","vi":"tụt lại"}],"traditional":"大隊"},{"id":"大家庭","hanzi":"大家庭","pinyin":"dàjiātíng","meaning_vi":"đại gia đình, tập thể lớn","explanation":"大 (đại – lớn) + 家庭 (gia đình) → gia đình nhiều thế hệ; nghĩa bóng: tập thể gắn bó như một nhà.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"我们是一个大家庭。","pinyin":"Wǒmen shì yí gè dàjiātíng.","vi":"Chúng tôi là một đại gia đình."},{"type":"simple","zh":"欢迎你加入我们公司这个大家庭。","pinyin":"Huānyíng nǐ jiārù wǒmen gōngsī zhè ge dàjiātíng.","vi":"Chào mừng bạn gia nhập đại gia đình công ty chúng tôi."},{"type":"compound","zh":"虽然大家庭生活很热闹，但是有时也会有矛盾。","pinyin":"Suīrán dàjiātíng shēnghuó hěn rènao, dànshì yǒushí yě huì yǒu máodùn.","vi":"Tuy sống trong đại gia đình rất vui nhưng đôi khi cũng có mâu thuẫn."}],"related":[{"hanzi":"家庭","pinyin":"jiātíng","vi":"gia đình"},{"hanzi":"小家庭","pinyin":"xiǎojiātíng","vi":"gia đình nhỏ"},{"hanzi":"集体","pinyin":"jítǐ","vi":"tập thể"},{"hanzi":"亲人","pinyin":"qīnrén","vi":"người thân"}]},{"id":"大街小巷","hanzi":"大街小巷","pinyin":"dàjiē-xiǎoxiàng","meaning_vi":"khắp phố phường, mọi ngóc ngách","explanation":"Nghĩa đen: phố lớn và ngõ nhỏ → khắp mọi nơi trong thành phố.","hsk_level":"7-9","tags":["thanh-ngu","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"大街小巷都很热闹。","pinyin":"Dàjiēxiǎoxiàng dōu hěn rènao.","vi":"Khắp phố phường đều rất náo nhiệt."},{"type":"simple","zh":"这首歌一夜之间传遍了大街小巷。","pinyin":"Zhè shǒu gē yí yè zhījiān chuánbiànle dàjiēxiǎoxiàng.","vi":"Bài hát này chỉ qua một đêm đã lan khắp phố phường."},{"type":"compound","zh":"每到春节，大街小巷就挂满了红灯笼。","pinyin":"Měi dào Chūnjié, dàjiēxiǎoxiàng jiù guà mǎnle hóngdēnglong.","vi":"Cứ đến Tết, khắp phố phường lại treo đầy đèn lồng đỏ."}],"related":[{"hanzi":"街道","pinyin":"jiēdào","vi":"đường phố"},{"hanzi":"胡同","pinyin":"hútòng","vi":"ngõ hẻm"},{"hanzi":"巷子","pinyin":"xiàngzi","vi":"ngõ"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"ai ai cũng biết"}]},{"id":"大款","hanzi":"大款","pinyin":"dàkuǎn","meaning_vi":"đại gia, người lắm tiền","explanation":"大 (đại – lớn) + 款 (khoản – tiền) → người có nhiều tiền; từ khẩu ngữ, đôi khi hàm ý châm biếm.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤑","examples":[{"type":"basic","zh":"他现在成了大款。","pinyin":"Tā xiànzài chéngle dàkuǎn.","vi":"Bây giờ anh ta đã thành đại gia."},{"type":"simple","zh":"那个大款一口气买了三辆跑车。","pinyin":"Nà ge dàkuǎn yìkǒuqì mǎile sān liàng pǎochē.","vi":"Gã đại gia đó mua một lèo ba chiếc xe thể thao."},{"type":"compound","zh":"虽然他是个大款，但是对朋友一点也不大方。","pinyin":"Suīrán tā shì gè dàkuǎn, dànshì duì péngyou yìdiǎn yě bú dàfang.","vi":"Tuy là đại gia nhưng anh ta chẳng hào phóng chút nào với bạn bè."}],"related":[{"hanzi":"富翁","pinyin":"fùwēng","vi":"phú ông"},{"hanzi":"土豪","pinyin":"tǔháo","vi":"đại gia mới nổi"},{"hanzi":"有钱人","pinyin":"yǒuqiánrén","vi":"người giàu"},{"hanzi":"穷人","pinyin":"qióngrén","vi":"người nghèo"}]},{"id":"大面积","hanzi":"大面积","pinyin":"dàmiànjī","meaning_vi":"diện rộng, quy mô lớn","explanation":"大 (đại – lớn) + 面积 (diện tích) → trên một diện tích rộng; nghĩa bóng: xảy ra trên quy mô lớn.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🗺️","examples":[{"type":"basic","zh":"这里发生了大面积停电。","pinyin":"Zhèlǐ fāshēngle dàmiànjī tíngdiàn.","vi":"Ở đây xảy ra mất điện diện rộng."},{"type":"simple","zh":"今年南方出现了大面积干旱。","pinyin":"Jīnnián nánfāng chūxiànle dàmiànjī gānhàn.","vi":"Năm nay miền Nam xuất hiện hạn hán trên diện rộng."},{"type":"compound","zh":"如果病虫害大面积爆发，粮食产量就会受到严重影响。","pinyin":"Rúguǒ bìngchónghài dàmiànjī bàofā, liángshi chǎnliàng jiù huì shòudào yánzhòng yǐngxiǎng.","vi":"Nếu sâu bệnh bùng phát diện rộng thì sản lượng lương thực sẽ bị ảnh hưởng nghiêm trọng."}],"related":[{"hanzi":"面积","pinyin":"miànjī","vi":"diện tích"},{"hanzi":"大规模","pinyin":"dàguīmó","vi":"quy mô lớn"},{"hanzi":"大范围","pinyin":"dàfànwéi","vi":"phạm vi rộng"},{"hanzi":"局部","pinyin":"júbù","vi":"cục bộ"}],"traditional":"大面積"},{"id":"大模大样","hanzi":"大模大样","pinyin":"dàmú-dàyàng","meaning_vi":"nghênh ngang, ung dung tự đắc","explanation":"模样 (mô dạng – dáng vẻ) chen 大 → dáng vẻ to tát, ra vẻ ta đây; chỉ thái độ ngang nhiên, không kiêng dè.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"😎","examples":[{"type":"basic","zh":"他大模大样地走了进来。","pinyin":"Tā dàmúdàyàng de zǒule jìnlái.","vi":"Anh ta nghênh ngang bước vào."},{"type":"simple","zh":"小偷居然大模大样地从正门离开了。","pinyin":"Xiǎotōu jūrán dàmúdàyàng de cóng zhèngmén líkāi le.","vi":"Tên trộm lại ung dung nghênh ngang rời đi bằng cửa chính."},{"type":"compound","zh":"虽然他是新来的，但是在会上大模大样地指挥别人。","pinyin":"Suīrán tā shì xīn lái de, dànshì zài huì shang dàmúdàyàng de zhǐhuī biérén.","vi":"Tuy là người mới nhưng anh ta nghênh ngang chỉ huy người khác trong cuộc họp."}],"related":[{"hanzi":"大摇大摆","pinyin":"dàyáodàbǎi","vi":"nghênh ngang"},{"hanzi":"模样","pinyin":"múyàng","vi":"dáng vẻ"},{"hanzi":"神气","pinyin":"shénqì","vi":"vênh váo"},{"hanzi":"谨小慎微","pinyin":"jǐnxiǎoshènwēi","vi":"rụt rè cẩn thận"}],"traditional":"大模大樣"},{"id":"大棚","hanzi":"大棚","pinyin":"dàpéng","meaning_vi":"nhà kính, nhà lưới (trồng trọt)","explanation":"大 (đại – lớn) + 棚 (bằng – lều, mái che) → lều lớn phủ màng nhựa để trồng rau quả trái vụ.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌱","examples":[{"type":"basic","zh":"大棚里种着草莓。","pinyin":"Dàpéng li zhòngzhe cǎoméi.","vi":"Trong nhà kính trồng dâu tây."},{"type":"simple","zh":"有了大棚，冬天也能吃到新鲜蔬菜。","pinyin":"Yǒule dàpéng, dōngtiān yě néng chī dào xīnxiān shūcài.","vi":"Có nhà kính rồi, mùa đông cũng ăn được rau tươi."},{"type":"compound","zh":"虽然建大棚要花不少钱，但是收益比露天种植高得多。","pinyin":"Suīrán jiàn dàpéng yào huā bùshǎo qián, dànshì shōuyì bǐ lùtiān zhòngzhí gāo de duō.","vi":"Tuy dựng nhà kính tốn khá nhiều tiền nhưng thu nhập cao hơn trồng ngoài trời nhiều."}],"related":[{"hanzi":"温室","pinyin":"wēnshì","vi":"nhà kính"},{"hanzi":"蔬菜","pinyin":"shūcài","vi":"rau"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng trọt"},{"hanzi":"棚子","pinyin":"péngzi","vi":"lều, lán"}]},{"id":"大片","hanzi":"大片","pinyin":"dàpiàn","meaning_vi":"phim bom tấn; mảng lớn, vùng rộng","explanation":"大 (đại – lớn) + 片 (phiến – mảnh; phim) → một vùng rộng lớn; khẩu ngữ hiện đại: phim bom tấn kinh phí lớn.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎞️","examples":[{"type":"basic","zh":"周末去看好莱坞大片吧。","pinyin":"Zhōumò qù kàn Hǎoláiwù dàpiàn ba.","vi":"Cuối tuần đi xem phim bom tấn Hollywood nhé."},{"type":"simple","zh":"窗外是一大片金黄的麦田。","pinyin":"Chuāng wài shì yí dàpiàn jīnhuáng de mài tián.","vi":"Ngoài cửa sổ là một cánh đồng lúa mì vàng óng bạt ngàn."},{"type":"compound","zh":"虽然这部大片投资上亿，但是票房并不理想。","pinyin":"Suīrán zhè bù dàpiàn tóuzī shàng yì, dànshì piàofáng bìngbù lǐxiǎng.","vi":"Tuy bộ phim bom tấn này đầu tư cả trăm triệu nhưng doanh thu phòng vé không như mong đợi."}],"related":[{"hanzi":"电影","pinyin":"diànyǐng","vi":"phim"},{"hanzi":"影片","pinyin":"yǐngpiàn","vi":"phim ảnh"},{"hanzi":"票房","pinyin":"piàofáng","vi":"doanh thu phòng vé"},{"hanzi":"一片","pinyin":"yípiàn","vi":"một vùng"}]},{"id":"大腕儿","hanzi":"大腕儿","pinyin":"dàwànr","meaning_vi":"ngôi sao lớn, người có tiếng (khẩu ngữ)","explanation":"大 (đại – lớn) + 腕儿 (oản – cổ tay, chỉ người có thế lực) → nhân vật nổi tiếng, có tiếng tăm trong một ngành, nhất là giới giải trí.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"⭐","examples":[{"type":"basic","zh":"他可是娱乐圈的大腕儿。","pinyin":"Tā kěshì yúlèquān de dàwànr.","vi":"Anh ấy là ngôi sao lớn của làng giải trí đấy."},{"type":"simple","zh":"这部电影请了好几个大腕儿来客串。","pinyin":"Zhè bù diànyǐng qǐngle hǎojǐ gè dàwànr lái kèchuàn.","vi":"Bộ phim này mời mấy ngôi sao lớn đóng vai khách mời."},{"type":"compound","zh":"虽然他已经是大腕儿了，但是对新人一点架子也没有。","pinyin":"Suīrán tā yǐjīng shì dàwànr le, dànshì duì xīnrén yìdiǎn jiàzi yě méiyǒu.","vi":"Tuy đã là ngôi sao lớn nhưng anh ấy chẳng hề làm cao với người mới."}],"related":[{"hanzi":"明星","pinyin":"míngxīng","vi":"ngôi sao"},{"hanzi":"名人","pinyin":"míngrén","vi":"người nổi tiếng"},{"hanzi":"大牌","pinyin":"dàpái","vi":"hàng đầu, ngôi sao"},{"hanzi":"新人","pinyin":"xīnrén","vi":"người mới"}],"traditional":"大腕兒"},{"id":"大选","hanzi":"大选","pinyin":"dàxuǎn","meaning_vi":"tổng tuyển cử, bầu cử toàn quốc","explanation":"大 (đại – lớn) + 选 (tuyển – bầu chọn) → cuộc bầu cử toàn quốc để chọn nguyên thủ hoặc quốc hội.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"今年是大选年。","pinyin":"Jīnnián shì dàxuǎn nián.","vi":"Năm nay là năm tổng tuyển cử."},{"type":"simple","zh":"这个国家每四年举行一次大选。","pinyin":"Zhè ge guójiā měi sì nián jǔxíng yí cì dàxuǎn.","vi":"Đất nước này cứ bốn năm tổ chức tổng tuyển cử một lần."},{"type":"compound","zh":"如果他在大选中获胜，就将成为最年轻的总统。","pinyin":"Rúguǒ tā zài dàxuǎn zhōng huòshèng, jiù jiāng chéngwéi zuì niánqīng de zǒngtǒng.","vi":"Nếu thắng trong tổng tuyển cử, ông ấy sẽ trở thành tổng thống trẻ nhất."}],"related":[{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"},{"hanzi":"候选人","pinyin":"hòuxuǎnrén","vi":"ứng cử viên"},{"hanzi":"总统","pinyin":"zǒngtǒng","vi":"tổng thống"}],"traditional":"大選"},{"id":"大雁","hanzi":"大雁","pinyin":"dàyàn","meaning_vi":"chim nhạn, ngỗng trời","explanation":"大 (đại – lớn) + 雁 (nhạn – chim nhạn) → ngỗng trời, loài chim di cư bay theo đàn hình chữ “人” hoặc “一”.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🪿","examples":[{"type":"basic","zh":"一群大雁飞过天空。","pinyin":"Yìqún dàyàn fēiguò tiānkōng.","vi":"Một đàn ngỗng trời bay qua bầu trời."},{"type":"simple","zh":"秋天一到，大雁就往南方飞去。","pinyin":"Qiūtiān yí dào, dàyàn jiù wǎng nánfāng fēi qù.","vi":"Mùa thu vừa đến, ngỗng trời liền bay về phương nam."},{"type":"compound","zh":"因为大雁排成队伍飞行能节省力气，所以它们总是一起飞。","pinyin":"Yīnwèi dàyàn pái chéng duìwu fēixíng néng jiéshěng lìqi, suǒyǐ tāmen zǒngshì yì qǐfēi.","vi":"Vì ngỗng trời bay theo đội hình thì tiết kiệm sức nên chúng luôn bay cùng nhau."}],"related":[{"hanzi":"雁","pinyin":"yàn","vi":"nhạn"},{"hanzi":"候鸟","pinyin":"hòuniǎo","vi":"chim di cư"},{"hanzi":"天鹅","pinyin":"tiān'é","vi":"thiên nga"},{"hanzi":"燕子","pinyin":"yànzi","vi":"chim én"}]},{"id":"大宗","hanzi":"大宗","pinyin":"dàzōng","meaning_vi":"số lượng lớn, mặt hàng chủ lực","explanation":"大 (đại – lớn) + 宗 (tông – lượng từ chỉ khối, mớ) → khối lượng lớn; 大宗商品 là hàng hóa giao dịch số lượng lớn (dầu, quặng, nông sản).","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"📦","examples":[{"type":"basic","zh":"这是一笔大宗交易。","pinyin":"Zhè shì yì bǐ dàzōng jiāoyì.","vi":"Đây là một giao dịch số lượng lớn."},{"type":"simple","zh":"石油和铁矿石都属于大宗商品。","pinyin":"Shíyóu hé tiěkuàngshí dōu shǔyú dàzōng shāngpǐn.","vi":"Dầu mỏ và quặng sắt đều thuộc nhóm hàng hóa cơ bản giao dịch số lượng lớn."},{"type":"compound","zh":"一旦大宗商品价格上涨，很多产品的成本就会跟着提高。","pinyin":"Yídàn dàzōng shāngpǐn jiàgé shàngzhǎng, hěn duō chǎnpǐn de chéng běnjiù huì gēnzhe tígāo.","vi":"Một khi giá hàng hóa cơ bản tăng, chi phí của nhiều sản phẩm cũng tăng theo."}],"related":[{"hanzi":"大批","pinyin":"dàpī","vi":"số lượng lớn"},{"hanzi":"批发","pinyin":"pīfā","vi":"bán buôn"},{"hanzi":"商品","pinyin":"shāngpǐn","vi":"hàng hóa"},{"hanzi":"零售","pinyin":"língshòu","vi":"bán lẻ"}]},{"id":"逮","hanzi":"逮","pinyin":"dǎi","meaning_vi":"bắt, tóm (khẩu ngữ)","explanation":"逮 (đãi) đọc dǎi trong khẩu ngữ → bắt, tóm được; đọc dài trong 逮捕 (bắt giữ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🪤","examples":[{"type":"basic","zh":"猫逮住了一只老鼠。","pinyin":"Māo dǎi zhùle yì zhī lǎoshǔ.","vi":"Con mèo bắt được một con chuột."},{"type":"simple","zh":"他上课玩手机被老师逮了个正着。","pinyin":"Tā shàngkè wán shǒujī bèi lǎoshī dǎile gè zhèngzháo.","vi":"Cậu ấy chơi điện thoại trong giờ học bị thầy tóm được tại trận."},{"type":"compound","zh":"如果你再迟到被经理逮到，就要扣奖金了。","pinyin":"Rúguǒ nǐ zài chídào bèi jīnglǐ dǎi dào, jiùyào kòu jiǎngjīn le.","vi":"Nếu bạn lại đi muộn mà bị quản lý bắt gặp thì sẽ bị trừ thưởng."}],"related":[{"hanzi":"抓","pinyin":"zhuā","vi":"bắt"},{"hanzi":"捉","pinyin":"zhuō","vi":"bắt"},{"hanzi":"逮捕","pinyin":"dàibǔ","vi":"bắt giữ"},{"hanzi":"抓住","pinyin":"zhuāzhù","vi":"tóm được"}]},{"id":"代理人","hanzi":"代理人","pinyin":"dàilǐrén","meaning_vi":"người đại diện, đại lý, người được ủy quyền","explanation":"代理 (đại lý – làm thay) + 人 (nhân – người) → người được ủy quyền thay mặt người khác làm việc, ký kết.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🧑‍⚖️","examples":[{"type":"basic","zh":"他是我的法律代理人。","pinyin":"Tā shì wǒ de fǎlǜ dàilǐrén.","vi":"Anh ấy là người đại diện pháp lý của tôi."},{"type":"simple","zh":"这位球星通过代理人和球队谈合同。","pinyin":"Zhè wèi qiúxīng tōngguò dàilǐrén hé qiúduì tán hétong.","vi":"Ngôi sao bóng đá này đàm phán hợp đồng với đội bóng thông qua người đại diện."},{"type":"compound","zh":"如果本人不能到场，就可以委托代理人来办理。","pinyin":"Rúguǒ běnrén bù néng dàochǎng, jiù kěyǐ wěituō dàilǐrén lái bànlǐ.","vi":"Nếu bản thân không thể có mặt thì có thể ủy quyền cho người đại diện đến làm thủ tục."}],"related":[{"hanzi":"代理","pinyin":"dàilǐ","vi":"đại lý"},{"hanzi":"委托","pinyin":"wěituō","vi":"ủy thác"},{"hanzi":"经纪人","pinyin":"jīngjìrén","vi":"người quản lý, môi giới"},{"hanzi":"律师","pinyin":"lǜshī","vi":"luật sư"}]},{"id":"带头人","hanzi":"带头人","pinyin":"dàitóurén","meaning_vi":"người dẫn đầu, người đi đầu","explanation":"带头 (đới đầu – dẫn đầu) + 人 (nhân – người) → người đi đầu, dẫn dắt tập thể.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🚩","examples":[{"type":"basic","zh":"她是村里的致富带头人。","pinyin":"Tā shì cūnli de zhìfù dàitóurén.","vi":"Cô ấy là người dẫn đầu làm giàu của làng."},{"type":"simple","zh":"这个团队需要一个有经验的带头人。","pinyin":"Zhè ge tuánduì xūyào yí gè yǒu jīngyàn de dàitóurén.","vi":"Đội này cần một người dẫn dắt có kinh nghiệm."},{"type":"compound","zh":"因为有了好的带头人，所以全村人的收入都提高了。","pinyin":"Yīnwèi yǒule hǎo de dàitóurén, suǒyǐ quán cūn rén de shōurù dōu tígāo le.","vi":"Vì có người dẫn đầu giỏi nên thu nhập của cả làng đều tăng lên."}],"related":[{"hanzi":"带头","pinyin":"dàitóu","vi":"dẫn đầu"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"领头羊","pinyin":"lǐngtóuyáng","vi":"con đầu đàn"},{"hanzi":"骨干","pinyin":"gǔgàn","vi":"nòng cốt"}],"traditional":"帶頭人"},{"id":"怠工","hanzi":"怠工","pinyin":"dàigōng","meaning_vi":"lãn công, làm việc cầm chừng","explanation":"怠 (đãi – lười biếng) + 工 (công – công việc) → cố ý làm chậm, làm cầm chừng; cũng là hình thức đình công.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🐌","examples":[{"type":"basic","zh":"工人们开始消极怠工。","pinyin":"Gōngrénmen kāishǐ xiāojí dàigōng.","vi":"Công nhân bắt đầu lãn công tiêu cực."},{"type":"simple","zh":"因为工资迟迟不发，工人们集体怠工。","pinyin":"Yīnwèi gōngzī chíchí bù fā, gōngrénmen jítǐ dàigōng.","vi":"Vì lương chậm mãi không trả, công nhân tập thể lãn công."},{"type":"compound","zh":"如果有人故意怠工，就会影响整个项目的进度。","pinyin":"Rúguǒ yǒurén gùyì dàigōng, jiù huì yǐngxiǎng zhěnggè xiàng mùde jìndù.","vi":"Nếu có người cố ý làm cầm chừng thì sẽ ảnh hưởng tiến độ cả dự án."}],"related":[{"hanzi":"罢工","pinyin":"bàgōng","vi":"đình công"},{"hanzi":"偷懒","pinyin":"tōulǎn","vi":"lười biếng"},{"hanzi":"懈怠","pinyin":"xièdài","vi":"lơ là"},{"hanzi":"磨洋工","pinyin":"móyánggōng","vi":"làm cầm chừng"}]},{"id":"单边","hanzi":"单边","pinyin":"dānbiān","meaning_vi":"đơn phương, một phía","explanation":"单 (đơn – một) + 边 (biên – phía) → chỉ từ một phía; thường dùng trong chính trị, kinh tế: 单边主义, 单边制裁.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"↔️","examples":[{"type":"basic","zh":"这是单边决定。","pinyin":"Zhè shì dānbiān juédìng.","vi":"Đây là quyết định đơn phương."},{"type":"simple","zh":"该国宣布对邻国实施单边制裁。","pinyin":"Gāi guó xuānbù duì Línguó shíshī dānbiān zhìcái.","vi":"Nước đó tuyên bố áp đặt trừng phạt đơn phương đối với nước láng giềng."},{"type":"compound","zh":"虽然单边行动见效快，但是容易引起其他国家的不满。","pinyin":"Suīrán dānbiān xíngdòng jiànxiào kuài, dànshì róngyì yǐnqǐ qítā guójiā de bùmǎn.","vi":"Tuy hành động đơn phương có hiệu quả nhanh nhưng dễ gây bất mãn cho các nước khác."}],"related":[{"hanzi":"单方面","pinyin":"dānfāngmiàn","vi":"đơn phương"},{"hanzi":"双边","pinyin":"shuāngbiān","vi":"song phương"},{"hanzi":"多边","pinyin":"duōbiān","vi":"đa phương"},{"hanzi":"单边主义","pinyin":"dānbiānzhǔyì","vi":"chủ nghĩa đơn phương"}],"traditional":"單邊"},{"id":"单身","hanzi":"单身","pinyin":"dānshēn","meaning_vi":"độc thân","explanation":"单 (đơn – một mình) + 身 (thân – bản thân) → một mình, chưa có vợ/chồng hoặc người yêu.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🙋‍♀️","examples":[{"type":"basic","zh":"她现在还单身。","pinyin":"Tā xiànzài hái dānshēn.","vi":"Hiện giờ cô ấy vẫn độc thân."},{"type":"simple","zh":"很多年轻人觉得单身生活很自由。","pinyin":"Hěn duō niánqīngrén juéde dānshēn shēnghuó hěn zìyóu.","vi":"Nhiều người trẻ thấy cuộc sống độc thân rất tự do."},{"type":"compound","zh":"虽然他已经四十岁了，但是一直单身。","pinyin":"Suīrán tā yǐjīng sìshí suì le, dànshì yìzhí dānshēn.","vi":"Tuy đã bốn mươi tuổi nhưng anh ấy vẫn độc thân."}],"related":[{"hanzi":"单身汉","pinyin":"dānshēnhàn","vi":"anh chàng độc thân"},{"hanzi":"未婚","pinyin":"wèihūn","vi":"chưa kết hôn"},{"hanzi":"已婚","pinyin":"yǐhūn","vi":"đã kết hôn"},{"hanzi":"恋爱","pinyin":"liàn'ài","vi":"yêu đương"}],"traditional":"單身"},{"id":"担","hanzi":"担","pinyin":"dān","meaning_vi":"gánh, đảm đương, chịu (trách nhiệm)","explanation":"担 (đảm – gánh vác) → gánh bằng đòn gánh; nghĩa bóng: gánh vác trách nhiệm (担责任), chịu rủi ro (担风险).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"他担着两桶水回家。","pinyin":"Tā dānzhe liǎng tǒng shuǐ huíjiā.","vi":"Anh ấy gánh hai thùng nước về nhà."},{"type":"simple","zh":"这个责任我一个人担不起。","pinyin":"Zhè ge zérèn wǒ yígèrén dān bù qǐ.","vi":"Trách nhiệm này một mình tôi không gánh nổi."},{"type":"compound","zh":"既然你做了这个决定，就要敢于担风险。","pinyin":"Jìrán nǐ zuòle zhè ge juédìng, jiùyào gǎnyú dān fēngxiǎn.","vi":"Đã đưa ra quyết định này thì bạn phải dám chịu rủi ro."}],"related":[{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"承担","pinyin":"chéngdān","vi":"gánh vác"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"}],"traditional":"擔"},{"id":"担当","hanzi":"担当","pinyin":"dāndāng","meaning_vi":"đảm đương, gánh vác; tinh thần trách nhiệm","explanation":"担 (đảm – gánh) + 当 (đương – đảm nhận) → nhận lấy và gánh vác trọng trách; danh từ: tinh thần dám chịu trách nhiệm.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"他敢于担当重任。","pinyin":"Tā gǎnyú dāndāng zhòngrèn.","vi":"Anh ấy dám gánh vác trọng trách."},{"type":"simple","zh":"她在这部电影里担当女主角。","pinyin":"Tā zài zhè bù diànyǐng li dāndāng nǚzhǔjué.","vi":"Cô ấy đảm nhận vai nữ chính trong bộ phim này."},{"type":"compound","zh":"即使出了问题，一个好领导也要有担当，不能推卸责任。","pinyin":"Jí shǐchūle wèntí, yí gè hǎo lǐngdǎo yě yàoyǒu dāndāng, bù néng tuīxiè zérèn.","vi":"Dù có xảy ra vấn đề, một lãnh đạo giỏi cũng phải dám chịu trách nhiệm, không được đùn đẩy."}],"related":[{"hanzi":"承担","pinyin":"chéngdān","vi":"gánh vác"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"责任","pinyin":"zérèn","vi":"trách nhiệm"},{"hanzi":"推卸","pinyin":"tuīxiè","vi":"đùn đẩy"}],"traditional":"擔當"},{"id":"担子","hanzi":"担子","pinyin":"dànzi","meaning_vi":"gánh, gánh nặng, trọng trách","explanation":"担 (đảm – gánh) đọc dàn + 子 → đòn gánh cùng hàng hóa; nghĩa bóng: trách nhiệm, gánh nặng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎋","examples":[{"type":"basic","zh":"他挑起了一副担子。","pinyin":"Tā tiāoqǐle yí fù dànzi.","vi":"Anh ấy gánh lên một gánh hàng."},{"type":"simple","zh":"父亲去世后，家里的担子落在了他肩上。","pinyin":"Fùqīn qùshì hòu, jiāli de dànzi luò zài le tā jiān shang.","vi":"Sau khi cha mất, gánh nặng gia đình đè lên vai anh ấy."},{"type":"compound","zh":"虽然担子很重，但是她相信自己能挑得起来。","pinyin":"Suīrán dànzi hěn zhòng, dànshì tā xiāngxìn zìjǐ néng tiāo de qǐlái.","vi":"Tuy gánh nặng rất lớn nhưng cô ấy tin mình có thể gánh vác được."}],"related":[{"hanzi":"重担","pinyin":"zhòngdàn","vi":"gánh nặng"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"},{"hanzi":"责任","pinyin":"zérèn","vi":"trách nhiệm"},{"hanzi":"扁担","pinyin":"biǎndan","vi":"đòn gánh"}],"traditional":"擔子"},{"id":"胆子","hanzi":"胆子","pinyin":"dǎnzi","meaning_vi":"gan, lá gan, sự can đảm","explanation":"胆 (đảm – mật, lá gan) + 子 → lòng can đảm; 胆子大 = gan dạ, 胆子小 = nhát gan.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🦁","examples":[{"type":"basic","zh":"他胆子特别小。","pinyin":"Tā dǎnzi tèbié xiǎo.","vi":"Cậu ấy cực kỳ nhát gan."},{"type":"simple","zh":"你胆子真大，一个人敢走夜路。","pinyin":"Nǐ dǎnzi zhēn dà, yígèrén gǎn zǒu yè lù.","vi":"Bạn gan thật, dám một mình đi đường đêm."},{"type":"compound","zh":"虽然她胆子不大，但是为了救孩子还是冲进了火场。","pinyin":"Suīrán tā dǎnzi búdà, dànshì wèile jiù háizi háishi chōngjìnle huǒchǎng.","vi":"Tuy không gan dạ gì nhưng để cứu đứa trẻ cô ấy vẫn lao vào đám cháy."}],"related":[{"hanzi":"胆量","pinyin":"dǎnliàng","vi":"lòng gan dạ"},{"hanzi":"胆小","pinyin":"dǎnxiǎo","vi":"nhát gan"},{"hanzi":"勇气","pinyin":"yǒngqì","vi":"dũng khí"},{"hanzi":"大胆","pinyin":"dàdǎn","vi":"táo bạo"}],"traditional":"膽子"},{"id":"但愿","hanzi":"但愿","pinyin":"dànyuàn","meaning_vi":"chỉ mong, ước gì","explanation":"但 (đãn – chỉ) + 愿 (nguyện – mong) → chỉ mong sao, bày tỏ hy vọng điều gì xảy ra.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🤞","examples":[{"type":"basic","zh":"但愿明天不下雨。","pinyin":"Dànyuàn míngtiān bú xiàyǔ.","vi":"Chỉ mong ngày mai trời không mưa."},{"type":"simple","zh":"但愿他能平平安安地回来。","pinyin":"Dànyuàn tā néng píngpíng ān'ān de huílái.","vi":"Chỉ mong anh ấy trở về bình an."},{"type":"compound","zh":"虽然这次准备得不太充分，但愿能顺利通过面试。","pinyin":"Suīrán zhè cì zhǔnbèi de bú tài chōngfèn, dànyuàn néng shùnlì tōngguò miànshì.","vi":"Tuy lần này chuẩn bị chưa đầy đủ lắm nhưng chỉ mong qua được buổi phỏng vấn suôn sẻ."}],"related":[{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"愿望","pinyin":"yuànwàng","vi":"nguyện vọng"},{"hanzi":"祝愿","pinyin":"zhùyuàn","vi":"chúc"},{"hanzi":"盼望","pinyin":"pànwàng","vi":"mong chờ"}],"traditional":"但願"},{"id":"当今","hanzi":"当今","pinyin":"dāngjīn","meaning_vi":"ngày nay, hiện nay, đương thời","explanation":"当 (đương – đang) + 今 (kim – nay) → thời đại hiện nay; văn viết: 当今社会, 当今世界.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"当今社会变化很快。","pinyin":"Dāngjīn shèhuì biànhuà hěn kuài.","vi":"Xã hội ngày nay thay đổi rất nhanh."},{"type":"simple","zh":"他是当今最有影响力的作家之一。","pinyin":"Tā shì dāngjīn zuì yǒu yǐngxiǎnglì de zuòjiā zhīyī.","vi":"Ông ấy là một trong những nhà văn có ảnh hưởng nhất hiện nay."},{"type":"compound","zh":"在当今世界，如果不会用电脑，就很难找到好工作。","pinyin":"Zài dāngjīn shìjiè, rúguǒ bú huì yòng diànnǎo, jiù hěn nán zhǎodào hǎo gōngzuò.","vi":"Trong thế giới ngày nay, nếu không biết dùng máy tính thì rất khó tìm được việc tốt."}],"related":[{"hanzi":"如今","pinyin":"rújīn","vi":"ngày nay"},{"hanzi":"现今","pinyin":"xiànjīn","vi":"hiện nay"},{"hanzi":"当代","pinyin":"dāngdài","vi":"đương đại"},{"hanzi":"古代","pinyin":"gǔdài","vi":"cổ đại"}],"traditional":"當今"},{"id":"当日","hanzi":"当日","pinyin":"dāngrì","meaning_vi":"ngày hôm đó, trong ngày","explanation":"当 (đương – chính lúc đó) + 日 (nhật – ngày) → đúng ngày đó, ngay trong ngày (当日有效 = có hiệu lực trong ngày).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"此票仅限当日有效。","pinyin":"Cǐ piào jǐnxiàn dāngrì yǒuxiào.","vi":"Vé này chỉ có hiệu lực trong ngày."},{"type":"simple","zh":"快递当日下单，当日就能送到。","pinyin":"Kuàidì dāngrì xiàdān, dāngrì jiù néng sòng dào.","vi":"Chuyển phát đặt hàng trong ngày là giao ngay trong ngày."},{"type":"compound","zh":"如果当日没有办完手续，就要等到下周一了。","pinyin":"Rúguǒ dāngrì méiyǒu bàn wán shǒuxù, jiùyào děngdào xià Zhōuyí le.","vi":"Nếu trong ngày hôm đó không làm xong thủ tục thì phải đợi đến thứ Hai tuần sau."}],"related":[{"hanzi":"当天","pinyin":"dāngtiān","vi":"ngày hôm đó"},{"hanzi":"当晚","pinyin":"dāngwǎn","vi":"tối hôm đó"},{"hanzi":"次日","pinyin":"cìrì","vi":"ngày hôm sau"},{"hanzi":"即日","pinyin":"jírì","vi":"ngay hôm nay"}],"traditional":"當日"},{"id":"当晚","hanzi":"当晚","pinyin":"dāngwǎn","meaning_vi":"tối hôm đó, ngay tối đó","explanation":"当 (đương – chính lúc đó) + 晚 (vãn – buổi tối) → buổi tối của chính ngày được nhắc đến.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌙","examples":[{"type":"basic","zh":"他当晚就回国了。","pinyin":"Tā dāngwǎn jiù huíguó le.","vi":"Ngay tối hôm đó anh ấy đã về nước."},{"type":"simple","zh":"比赛结束后的当晚，球员们一起庆祝。","pinyin":"Bǐsài jiéshù hòu de dāngwǎn, qiúyuánmen yìqǐ qìngzhù.","vi":"Tối hôm trận đấu kết thúc, các cầu thủ cùng nhau ăn mừng."},{"type":"compound","zh":"因为当晚下了大雨，所以演唱会被迫延期了。","pinyin":"Yīnwèi dāngwǎn xiàle dàyǔ, suǒyǐ yǎnchànghuì bèipò yánqī le.","vi":"Vì tối hôm đó mưa to nên buổi hòa nhạc buộc phải hoãn lại."}],"related":[{"hanzi":"当天","pinyin":"dāngtiān","vi":"ngày hôm đó"},{"hanzi":"当日","pinyin":"dāngrì","vi":"ngày hôm đó"},{"hanzi":"当夜","pinyin":"dāngyè","vi":"đêm hôm đó"},{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chập tối"}],"traditional":"當晚"},{"id":"当下","hanzi":"当下","pinyin":"dāngxià","meaning_vi":"hiện tại, lúc này; ngay lúc đó, lập tức","explanation":"当 (đương – đang) + 下 (hạ – dưới, lúc) → chính thời điểm đó/ngay lập tức; nay hay dùng nghĩa “hiện tại” (活在当下 = sống cho hiện tại).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"我们要活在当下。","pinyin":"Wǒmen yào huó zài dāngxià.","vi":"Chúng ta phải sống cho hiện tại."},{"type":"simple","zh":"听完他的话，我当下就决定辞职。","pinyin":"Tīng wán tā dehuà, wǒ dāngxià jiù juédìng cízhí.","vi":"Nghe xong lời anh ấy, tôi lập tức quyết định nghỉ việc."},{"type":"compound","zh":"虽然未来很重要，但是我们更应该珍惜当下。","pinyin":"Suīrán wèilái hěn zhòngyào, dànshì wǒmen gèng yīnggāi zhēnxī dāngxià.","vi":"Tuy tương lai rất quan trọng nhưng chúng ta càng nên trân trọng hiện tại."}],"related":[{"hanzi":"目前","pinyin":"mùqián","vi":"hiện nay"},{"hanzi":"眼下","pinyin":"yǎnxià","vi":"trước mắt"},{"hanzi":"立刻","pinyin":"lìkè","vi":"lập tức"},{"hanzi":"此刻","pinyin":"cǐkè","vi":"lúc này"}],"traditional":"當下"},{"id":"当着","hanzi":"当着","pinyin":"dāngzhe","meaning_vi":"trước mặt, ngay trước","explanation":"当 (đương – đối diện) + 着 → trước mặt ai đó; dùng như giới từ: 当着…的面.","hsk_level":"7-9","tags":["gioi-tu"],"image":"👁️","examples":[{"type":"basic","zh":"别当着孩子吵架。","pinyin":"Bié dāngzhe háizi chǎojià.","vi":"Đừng cãi nhau trước mặt con."},{"type":"simple","zh":"他当着全班同学的面向我道歉。","pinyin":"Tā dāngzhe quánbān tóngxué de miànxiàng wǒ dàoqiàn.","vi":"Cậu ấy xin lỗi tôi trước mặt cả lớp."},{"type":"compound","zh":"即使你不同意，也不要当着客户的面反驳经理。","pinyin":"Jíshǐ nǐ bù tóngyì, yě bú yào dāngzhe kèhù de miàn fǎnbó jīnglǐ.","vi":"Dù bạn không đồng ý cũng đừng phản bác quản lý trước mặt khách hàng."}],"related":[{"hanzi":"当面","pinyin":"dāngmiàn","vi":"trực tiếp, trước mặt"},{"hanzi":"面前","pinyin":"miànqián","vi":"trước mặt"},{"hanzi":"背着","pinyin":"bèizhe","vi":"sau lưng"},{"hanzi":"当众","pinyin":"dāngzhòng","vi":"trước đám đông"}],"traditional":"當著"},{"id":"当真","hanzi":"当真","pinyin":"dàngzhēn","meaning_vi":"coi là thật, tin là thật; thật sự","explanation":"当 (đáng – coi như) + 真 (chân – thật) → cho là thật, tin thật; cũng làm phó từ “quả thật”.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧐","examples":[{"type":"basic","zh":"我开玩笑的，你别当真。","pinyin":"Wǒ kāiwánxiào de, nǐ bié dàngzhēn.","vi":"Tôi đùa thôi, bạn đừng tưởng thật."},{"type":"simple","zh":"他随口说的话，没想到她当真了。","pinyin":"Tā suíkǒu shuō dehuà, méi xiǎngdào tā dàngzhēn le.","vi":"Lời anh ấy nói buột miệng, không ngờ cô ấy lại tin là thật."},{"type":"compound","zh":"如果你当真想学，我就每天早上教你一个小时。","pinyin":"Rúguǒ nǐ dàngzhēn xiǎng xué, wǒ jiù měitiān zǎoshang jiāo nǐ yí gè xiǎoshí.","vi":"Nếu bạn thật sự muốn học thì mỗi sáng tôi sẽ dạy bạn một tiếng."}],"related":[{"hanzi":"认真","pinyin":"rènzhēn","vi":"nghiêm túc"},{"hanzi":"果真","pinyin":"guǒzhēn","vi":"quả thật"},{"hanzi":"真的","pinyin":"zhēnde","vi":"thật sự"},{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"đùa"}],"traditional":"當真"},{"id":"到位","hanzi":"到位","pinyin":"dàowèi","meaning_vi":"đến nơi, về đủ; đâu vào đấy, chu đáo; xác đáng","explanation":"到 (đáo – đến) + 位 (vị – vị trí) → đến đúng vị trí; nghĩa rộng: làm đến nơi đến chốn, đầy đủ, chuẩn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"资金已经到位了。","pinyin":"Zījīn yǐjīng dàowèi le.","vi":"Vốn đã về đủ rồi."},{"type":"simple","zh":"他对问题的分析非常到位。","pinyin":"Tā duì wèntí de fēnxī fēicháng dàowèi.","vi":"Phân tích vấn đề của anh ấy rất xác đáng."},{"type":"compound","zh":"如果服务做得不到位，客人就不会再来了。","pinyin":"Rúguǒ fúwù zuò debúdào wèi, kèrén jiù bú huì zài lái le.","vi":"Nếu phục vụ không đến nơi đến chốn thì khách sẽ không quay lại nữa."}],"related":[{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"chính xác"},{"hanzi":"周到","pinyin":"zhōudào","vi":"chu đáo"},{"hanzi":"就位","pinyin":"jiùwèi","vi":"vào vị trí"}]},{"id":"倒卖","hanzi":"倒卖","pinyin":"dǎomài","meaning_vi":"buôn đi bán lại, đầu cơ (kiếm lời)","explanation":"倒 (đảo – chuyển qua) + 卖 (mại – bán) → mua vào rồi bán lại kiếm chênh lệch, thường là trái phép (倒卖车票).","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🎫","examples":[{"type":"basic","zh":"他倒卖演唱会门票。","pinyin":"Tā dǎomài yǎnchànghuì ménpiào.","vi":"Anh ta buôn bán lại vé hòa nhạc."},{"type":"simple","zh":"警方抓获了一伙倒卖火车票的人。","pinyin":"Jǐngfāng zhuāhuòle yì huǒ dǎomài huǒchēpiào de rén.","vi":"Cảnh sát bắt được một nhóm phe vé tàu."},{"type":"compound","zh":"如果有人倒卖文物，就会受到法律的严惩。","pinyin":"Rúguǒ yǒurén dǎomài wénwù, jiù huì shòudào fǎlǜ de yánchéng.","vi":"Nếu ai buôn bán trái phép cổ vật thì sẽ bị pháp luật trừng trị nghiêm khắc."}],"related":[{"hanzi":"倒爷","pinyin":"dǎoyé","vi":"kẻ buôn đi bán lại"},{"hanzi":"黄牛","pinyin":"huángniú","vi":"phe vé"},{"hanzi":"转卖","pinyin":"zhuǎnmài","vi":"bán lại"},{"hanzi":"投机","pinyin":"tóujī","vi":"đầu cơ"}],"traditional":"倒賣"},{"id":"倒下","hanzi":"倒下","pinyin":"dǎoxià","meaning_vi":"ngã xuống, đổ xuống, gục ngã","explanation":"倒 (đảo – ngã) + 下 (hạ – xuống) → ngã xuống; nghĩa bóng: suy sụp, gục ngã, phá sản.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌳","examples":[{"type":"basic","zh":"那棵大树倒下了。","pinyin":"Nà kē dà shù dǎoxià le.","vi":"Cây lớn đó đã đổ xuống."},{"type":"simple","zh":"他累得一回家就倒下睡着了。","pinyin":"Tā lèi de yì huíjiā jiù dǎoxià shuìzháo le.","vi":"Anh ấy mệt đến mức vừa về nhà đã ngã xuống ngủ ngay."},{"type":"compound","zh":"虽然父亲倒下了，但是全家人没有放弃希望。","pinyin":"Suīrán fùqīn dǎoxià le, dànshì quán jiārén méiyǒu fàngqì xīwàng.","vi":"Tuy người cha đã gục ngã nhưng cả nhà vẫn không từ bỏ hy vọng."}],"related":[{"hanzi":"摔倒","pinyin":"shuāidǎo","vi":"ngã"},{"hanzi":"倒塌","pinyin":"dǎotā","vi":"sụp đổ"},{"hanzi":"站起来","pinyin":"zhànqǐlái","vi":"đứng dậy"},{"hanzi":"跌倒","pinyin":"diēdǎo","vi":"vấp ngã"}]},{"id":"悼念","hanzi":"悼念","pinyin":"dàoniàn","meaning_vi":"tưởng niệm, thương tiếc (người đã mất)","explanation":"悼 (điệu – thương xót người chết) + 念 (niệm – nhớ) → nhớ thương, tưởng niệm người đã khuất.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🕯️","examples":[{"type":"basic","zh":"人们悼念遇难者。","pinyin":"Rénmen dàoniàn yùnànzhě.","vi":"Mọi người tưởng niệm các nạn nhân."},{"type":"simple","zh":"很多人献上鲜花，悼念这位老艺术家。","pinyin":"Hěn duō rén xiànshàng xiānhuā, dàoniàn zhè wèi lǎo yìshùjiā.","vi":"Rất nhiều người đặt hoa tưởng niệm vị nghệ sĩ lão thành này."},{"type":"compound","zh":"虽然他已经离开多年，但是每年都有学生来悼念他。","pinyin":"Suīrán tā yǐjīng líkāi duōnián, dànshì měinián dōu yǒu xuésheng lái dàoniàn tā.","vi":"Tuy ông đã ra đi nhiều năm nhưng năm nào cũng có học trò đến tưởng niệm."}],"related":[{"hanzi":"纪念","pinyin":"jìniàn","vi":"kỷ niệm"},{"hanzi":"哀悼","pinyin":"āidào","vi":"thương tiếc"},{"hanzi":"追悼会","pinyin":"zhuīdàohuì","vi":"lễ truy điệu"},{"hanzi":"缅怀","pinyin":"miǎnhuái","vi":"tưởng nhớ"}]},{"id":"盗","hanzi":"盗","pinyin":"dào","meaning_vi":"trộm, ăn cắp; kẻ trộm","explanation":"盗 (đạo – trộm cướp) → lấy trộm của người khác; gặp trong 盗窃, 强盗, 盗版.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🦹","examples":[{"type":"basic","zh":"他的账号被盗了。","pinyin":"Tā de zhànghào bèi dào le.","vi":"Tài khoản của anh ấy bị đánh cắp rồi."},{"type":"simple","zh":"博物馆的一件珍贵文物昨晚被盗。","pinyin":"Bówùguǎn de yí jiàn zhēnguì wénwù zuówǎn bèi dào.","vi":"Một cổ vật quý của bảo tàng bị trộm đêm qua."},{"type":"compound","zh":"如果你的银行卡被盗刷，就要马上联系银行冻结。","pinyin":"Rúguǒ nǐ de yínhángkǎ bèi dàoshuā, jiùyào mǎshàng liánxì yínháng dòngjié.","vi":"Nếu thẻ ngân hàng của bạn bị quẹt trộm thì phải liên hệ ngay ngân hàng để khóa thẻ."}],"related":[{"hanzi":"盗窃","pinyin":"dàoqiè","vi":"trộm cắp"},{"hanzi":"强盗","pinyin":"qiángdào","vi":"cường đạo"},{"hanzi":"盗版","pinyin":"dàobǎn","vi":"lậu, vi phạm bản quyền"},{"hanzi":"偷","pinyin":"tōu","vi":"trộm"}],"traditional":"盜"},{"id":"道具","hanzi":"道具","pinyin":"dàojù","meaning_vi":"đạo cụ, vật dụng (sân khấu, game)","explanation":"道 (đạo) + 具 (cụ – đồ dùng) → đồ dùng trên sân khấu, phim trường; trong game là vật phẩm.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"这把刀只是道具。","pinyin":"Zhè bǎ dāo zhǐshì dàojù.","vi":"Con dao này chỉ là đạo cụ."},{"type":"simple","zh":"他在游戏里花钱买了很多道具。","pinyin":"Tā zài yóuxì li huāqián mǎile hěn duō dàojù.","vi":"Cậu ấy bỏ tiền mua rất nhiều vật phẩm trong game."},{"type":"compound","zh":"因为道具没准备好，所以演出推迟了半个小时。","pinyin":"Yīnwèi dàojù méi zhǔnbèihǎo, suǒyǐ yǎnchū tuīchíle bàn gè xiǎoshí.","vi":"Vì đạo cụ chưa chuẩn bị xong nên buổi diễn bị lùi nửa tiếng."}],"related":[{"hanzi":"服装","pinyin":"fúzhuāng","vi":"trang phục"},{"hanzi":"布景","pinyin":"bùjǐng","vi":"phông cảnh"},{"hanzi":"舞台","pinyin":"wǔtái","vi":"sân khấu"},{"hanzi":"工具","pinyin":"gōngjù","vi":"công cụ"}]},{"id":"稻草","hanzi":"稻草","pinyin":"dàocǎo","meaning_vi":"rơm (lúa)","explanation":"稻 (đạo – cây lúa) + 草 (thảo – cỏ) → thân lúa khô sau khi gặt, tức rơm; thành ngữ: 救命稻草 (cọng rơm cứu mạng).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"屋顶是用稻草盖的。","pinyin":"Wūdǐng shì yòng dàocǎo gài de.","vi":"Mái nhà được lợp bằng rơm."},{"type":"simple","zh":"农民把稻草捆起来喂牛。","pinyin":"Nóngmín bǎ dàocǎo kǔn qǐlái wèi niú.","vi":"Nông dân bó rơm lại để cho bò ăn."},{"type":"compound","zh":"虽然这个办法不一定有用，但是对他来说是最后一根救命稻草。","pinyin":"Suīrán zhè ge bànfǎ bù yídìng yǒuyòng, dànshì duì tā lái shuō shì zuìhòu yìgēn jiùmìng dàocǎo.","vi":"Tuy cách này chưa chắc hữu dụng nhưng với anh ấy đó là cọng rơm cứu mạng cuối cùng."}],"related":[{"hanzi":"稻子","pinyin":"dàozi","vi":"cây lúa"},{"hanzi":"水稻","pinyin":"shuǐdào","vi":"lúa nước"},{"hanzi":"草帽","pinyin":"cǎomào","vi":"mũ rơm"},{"hanzi":"干草","pinyin":"gāncǎo","vi":"cỏ khô"}]},{"id":"德","hanzi":"德","pinyin":"dé","meaning_vi":"đức, đạo đức; nước Đức","explanation":"德 (đức – phẩm hạnh) → đạo đức, phẩm chất tốt (品德, 道德); cũng là viết tắt của 德国 (nước Đức).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧭","examples":[{"type":"basic","zh":"他是个有德的人。","pinyin":"Tā shì gè yǒu dé de rén.","vi":"Ông ấy là người có đức."},{"type":"simple","zh":"学校重视学生德智体全面发展。","pinyin":"Xuéxiào zhòngshì xuésheng dézhìtǐ quánmiàn fāzhǎn.","vi":"Nhà trường coi trọng sự phát triển toàn diện đức, trí, thể của học sinh."},{"type":"compound","zh":"虽然他才华出众，但是如果德不配位，也难以服众。","pinyin":"Suīrán tā cáihuá chūzhòng, dànshì rúguǒ dé bú pèi wèi, yě nányǐ fúzhòng.","vi":"Tuy anh ta tài hoa xuất chúng nhưng nếu đức không xứng với vị trí thì cũng khó khiến mọi người phục."}],"related":[{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"美德","pinyin":"měidé","vi":"mỹ đức"},{"hanzi":"德国","pinyin":"Déguó","vi":"nước Đức"}]},{"id":"地狱","hanzi":"地狱","pinyin":"dìyù","meaning_vi":"địa ngục","explanation":"地 (địa – đất) + 狱 (ngục – nhà tù) → ngục dưới lòng đất, nơi linh hồn chịu tội theo tôn giáo; nghĩa bóng: hoàn cảnh cực kỳ khổ sở.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🔥","examples":[{"type":"basic","zh":"那段日子像地狱一样。","pinyin":"Nà duàn rìzi xiàng dìyù yíyàng.","vi":"Những ngày đó như địa ngục."},{"type":"simple","zh":"故事里的坏人死后下了地狱。","pinyin":"Gùshi li de huàirén sǐhòu xiàle dìyù.","vi":"Kẻ xấu trong truyện chết rồi xuống địa ngục."},{"type":"compound","zh":"虽然战争已经结束，但是那段地狱般的经历让他终生难忘。","pinyin":"Suīrán zhànzhēng yǐjīng jiéshù, dànshì nà duàn dìyù bān de jīnglì ràng tā zhōngshēng nánwàng.","vi":"Tuy chiến tranh đã kết thúc nhưng trải nghiệm như địa ngục ấy khiến ông nhớ suốt đời."}],"related":[{"hanzi":"天堂","pinyin":"tiāntáng","vi":"thiên đường"},{"hanzi":"监狱","pinyin":"jiānyù","vi":"nhà tù"},{"hanzi":"魔鬼","pinyin":"móguǐ","vi":"ma quỷ"},{"hanzi":"人间","pinyin":"rénjiān","vi":"trần gian"}],"traditional":"地獄"},{"id":"得当","hanzi":"得当","pinyin":"dédàng","meaning_vi":"thỏa đáng, thích đáng, hợp lý","explanation":"得 (đắc – được) + 当 (đáng – thích hợp) → làm đúng mức, phù hợp; thường gặp 处理得当, 措施得当.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"他处理问题很得当。","pinyin":"Tā chǔlǐ wèntí hěn dédàng.","vi":"Anh ấy xử lý vấn đề rất thỏa đáng."},{"type":"simple","zh":"由于抢救措施得当，病人很快脱离了危险。","pinyin":"Yóuyú qiǎngjiù cuòshī dédàng, bìngrén hěn kuài tuōlíle wēixiǎn.","vi":"Nhờ biện pháp cấp cứu thích đáng, bệnh nhân nhanh chóng qua cơn nguy hiểm."},{"type":"compound","zh":"只要学习方法得当，学外语就不会太难。","pinyin":"Zhǐyào xuéxí fāngfǎ dédàng, xué wàiyǔ jiù bú huì tài nán.","vi":"Chỉ cần phương pháp học hợp lý thì học ngoại ngữ sẽ không quá khó."}],"related":[{"hanzi":"恰当","pinyin":"qiàdàng","vi":"thích hợp"},{"hanzi":"适当","pinyin":"shìdàng","vi":"thích đáng"},{"hanzi":"妥当","pinyin":"tuǒdang","vi":"ổn thỏa"},{"hanzi":"不当","pinyin":"búdàng","vi":"không thỏa đáng"}],"traditional":"得當"},{"id":"得手","hanzi":"得手","pinyin":"déshǒu","meaning_vi":"đắc thủ, thành công, trót lọt","explanation":"得 (đắc – được) + 手 (thủ – tay) → vào được tay, việc làm trót lọt; thường dùng cho kẻ gian (小偷得手).","hsk_level":"7-9","tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"小偷没有得手。","pinyin":"Xiǎotōu méiyǒu déshǒu.","vi":"Tên trộm đã không thành công."},{"type":"simple","zh":"骗子得手后很快就消失了。","pinyin":"Piànzi déshǒu hòu hěn kuài jiù xiāoshī le.","vi":"Kẻ lừa đảo sau khi trót lọt đã nhanh chóng biến mất."},{"type":"compound","zh":"虽然他们第一次进攻就得手了，但是后面打得很艰难。","pinyin":"Suīrán tāmen dìyīcì jìngōng jiù déshǒu le, dànshì hòumiàn dǎ de hěn jiānnán.","vi":"Tuy lần tấn công đầu họ đã thành công nhưng về sau đánh rất vất vả."}],"related":[{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"得逞","pinyin":"déchěng","vi":"đạt được mưu đồ"},{"hanzi":"顺手","pinyin":"shùnshǒu","vi":"thuận tay"},{"hanzi":"失手","pinyin":"shīshǒu","vi":"lỡ tay, thất bại"}]},{"id":"得益于","hanzi":"得益于","pinyin":"déyìyú","meaning_vi":"nhờ vào, được hưởng lợi từ","explanation":"得益 (đắc ích – được lợi) + 于 (vu – từ) → được lợi nhờ điều gì; dùng để nêu nguyên nhân tích cực.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙌","examples":[{"type":"basic","zh":"这得益于你的帮助。","pinyin":"Zhè déyìyú nǐ de bāngzhù.","vi":"Điều này là nhờ sự giúp đỡ của bạn."},{"type":"simple","zh":"他的成功得益于多年的坚持。","pinyin":"Tā de chénggōng déyìyú duōnián de jiānchí.","vi":"Thành công của anh ấy là nhờ nhiều năm kiên trì."},{"type":"compound","zh":"因为得益于交通的改善，所以这个小镇的旅游业发展得很快。","pinyin":"Yīnwèi déyìyú jiāotōng de gǎishàn, suǒyǐ zhè ge xiǎozhèn de lǚyóuyè fāzhǎn de hěn kuài.","vi":"Nhờ giao thông được cải thiện nên ngành du lịch của thị trấn nhỏ này phát triển rất nhanh."}],"related":[{"hanzi":"受益","pinyin":"shòuyì","vi":"hưởng lợi"},{"hanzi":"多亏","pinyin":"duōkuī","vi":"may nhờ"},{"hanzi":"归功于","pinyin":"guīgōngyú","vi":"quy công cho"},{"hanzi":"好处","pinyin":"hǎochu","vi":"lợi ích"}],"traditional":"得益於"},{"id":"得意扬扬","hanzi":"得意扬扬","pinyin":"déyì-yángyáng","meaning_vi":"dương dương tự đắc, đắc ý","explanation":"得意 (đắc ý – vừa lòng) + 扬扬 (dương dương – phấn chấn, khoe ra) → vẻ mặt tự mãn, khoái chí lộ rõ ra ngoài.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😏","examples":[{"type":"basic","zh":"他一脸得意扬扬。","pinyin":"Tā yì liǎn déyìyángyáng.","vi":"Mặt anh ta đầy vẻ tự đắc."},{"type":"simple","zh":"赢了比赛，他得意扬扬地走下台。","pinyin":"Yíngle bǐsài, tā déyìyángyáng de zǒu xiàtái.","vi":"Thắng cuộc thi, anh ấy dương dương tự đắc bước xuống sân khấu."},{"type":"compound","zh":"虽然这次考了第一，但是你也不能得意扬扬，看不起别人。","pinyin":"Suīrán zhè cì kǎole dìyī, dànshì nǐ yě bù néng déyìyángyáng, kànbuqǐ biérén.","vi":"Tuy lần này thi đứng đầu nhưng bạn cũng không được dương dương tự đắc, coi thường người khác."}],"related":[{"hanzi":"得意","pinyin":"déyì","vi":"đắc ý"},{"hanzi":"洋洋得意","pinyin":"yángyángdéyì","vi":"dương dương tự đắc"},{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"kiêu ngạo"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ"}],"traditional":"得意揚揚"},{"id":"灯泡","hanzi":"灯泡","pinyin":"dēngpào","meaning_vi":"bóng đèn; kỳ đà cản mũi (lóng)","explanation":"灯 (đăng – đèn) + 泡 (phao – bọng, bóng) → bóng đèn; tiếng lóng: người thứ ba vô duyên đi cùng một cặp đôi (电灯泡).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"💡","examples":[{"type":"basic","zh":"灯泡坏了，要换一个。","pinyin":"Dēngpào huàile, yào huàn yí gè.","vi":"Bóng đèn hỏng rồi, phải thay cái mới."},{"type":"simple","zh":"他站在椅子上给客厅换灯泡。","pinyin":"Tā zhàn zài yǐzi shang gěi kètīng huàn dēngpào.","vi":"Anh ấy đứng trên ghế thay bóng đèn phòng khách."},{"type":"compound","zh":"既然他们俩要约会，我就不去当电灯泡了。","pinyin":"Jìrán tāmen liǎ yào yuēhuì, wǒ jiù bú qù dāng diàndēngpào le.","vi":"Hai người họ đã hẹn hò thì tôi không đi làm kỳ đà cản mũi nữa."}],"related":[{"hanzi":"电灯","pinyin":"diàndēng","vi":"đèn điện"},{"hanzi":"台灯","pinyin":"táidēng","vi":"đèn bàn"},{"hanzi":"开关","pinyin":"kāiguān","vi":"công tắc"},{"hanzi":"节能灯","pinyin":"jiénéngdēng","vi":"đèn tiết kiệm điện"}],"traditional":"燈泡"},{"id":"凳子","hanzi":"凳子","pinyin":"dèngzi","meaning_vi":"ghế đẩu, ghế không tựa","explanation":"凳 (đắng – ghế đẩu) + 子 → ghế ngồi không có lưng tựa.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪑","examples":[{"type":"basic","zh":"请坐在凳子上。","pinyin":"Qǐngzuò zài dèngzi shang.","vi":"Mời ngồi lên ghế đẩu."},{"type":"simple","zh":"他搬了个小凳子坐在门口乘凉。","pinyin":"Tā bānle gè xiǎo dèngzi zuò zài ménkǒu chéngliáng.","vi":"Ông ấy mang cái ghế đẩu nhỏ ra ngồi hóng mát ở cửa."},{"type":"compound","zh":"因为凳子不够，所以有几个人只好站着吃饭。","pinyin":"Yīnwèi dèngzi búgòu, suǒyǐ yǒu jǐ gè rén zhǐhǎo zhànzhe chīfàn.","vi":"Vì không đủ ghế đẩu nên có mấy người đành đứng ăn cơm."}],"related":[{"hanzi":"椅子","pinyin":"yǐzi","vi":"ghế tựa"},{"hanzi":"板凳","pinyin":"bǎndèng","vi":"ghế băng"},{"hanzi":"沙发","pinyin":"shāfā","vi":"sofa"},{"hanzi":"桌子","pinyin":"zhuōzi","vi":"bàn"}]},{"id":"低调","hanzi":"低调","pinyin":"dīdiào","meaning_vi":"kín tiếng, khiêm tốn, không phô trương","explanation":"低 (đê – thấp) + 调 (điệu – giọng) → giọng thấp; nghĩa bóng: cư xử khiêm nhường, không phô trương.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🤫","examples":[{"type":"basic","zh":"他做人很低调。","pinyin":"Tā zuòrén hěn dīdiào.","vi":"Anh ấy sống rất kín tiếng."},{"type":"simple","zh":"这对明星夫妻低调地举行了婚礼。","pinyin":"Zhè duì míngxīng fūqī dīdiào de jǔxíngle hūnlǐ.","vi":"Cặp vợ chồng ngôi sao này đã tổ chức đám cưới một cách kín đáo."},{"type":"compound","zh":"虽然她家里很有钱，但是她穿着打扮一直很低调。","pinyin":"Suīrán tā jiāli hěn yǒuqián, dànshì tā chuānzhuó dǎban yìzhí hěn dīdiào.","vi":"Tuy nhà cô ấy rất giàu nhưng cách ăn mặc của cô luôn giản dị, không phô trương."}],"related":[{"hanzi":"高调","pinyin":"gāodiào","vi":"phô trương"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"张扬","pinyin":"zhāngyáng","vi":"khoa trương"},{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"}],"traditional":"低調"},{"id":"低价","hanzi":"低价","pinyin":"dījià","meaning_vi":"giá thấp, giá rẻ","explanation":"低 (đê – thấp) + 价 (giá – giá cả) → giá thấp hơn bình thường.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这家店低价出售旧书。","pinyin":"Zhè jiā diàn dījià chūshòu jiùshū.","vi":"Cửa hàng này bán sách cũ giá rẻ."},{"type":"simple","zh":"他们以低价买下了那块土地。","pinyin":"Tāmen yǐ dījià mǎixiàle nà kuài tǔdì.","vi":"Họ đã mua mảnh đất đó với giá thấp."},{"type":"compound","zh":"虽然低价很吸引人，但是质量往往没有保证。","pinyin":"Suīrán dījià hěn xīyǐnrén, dànshì zhìliàng wǎngwǎng méiyǒu bǎozhèng.","vi":"Tuy giá rẻ rất hấp dẫn nhưng chất lượng thường không được đảm bảo."}],"related":[{"hanzi":"高价","pinyin":"gāojià","vi":"giá cao"},{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"特价","pinyin":"tèjià","vi":"giá đặc biệt"},{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"}],"traditional":"低價"},{"id":"低下","hanzi":"低下","pinyin":"dīxià","meaning_vi":"thấp kém, kém; cúi (đầu) xuống","explanation":"低 (đê – thấp) + 下 (hạ – dưới) → ở mức thấp (地位低下, 效率低下); làm động từ: cúi xuống (低下头).","hsk_level":"7-9","tags":["tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"这里工作效率低下。","pinyin":"Zhèlǐ gōngzuò xiàolǜ dīxià.","vi":"Hiệu suất làm việc ở đây thấp kém."},{"type":"simple","zh":"听到批评，她害羞地低下了头。","pinyin":"Tīngdào pīpíng, tā hàixiū de dīxiàle tóu.","vi":"Nghe lời phê bình, cô ấy ngượng ngùng cúi đầu xuống."},{"type":"compound","zh":"在古代，虽然商人很有钱，但是社会地位低下。","pinyin":"Zài gǔdài, suīrán shāngrén hěn yǒuqián, dànshì shèhuì dìwèi dīxià.","vi":"Thời xưa, tuy thương nhân rất giàu nhưng địa vị xã hội lại thấp kém."}],"related":[{"hanzi":"低","pinyin":"dī","vi":"thấp"},{"hanzi":"低级","pinyin":"dījí","vi":"cấp thấp"},{"hanzi":"卑微","pinyin":"bēiwēi","vi":"hèn mọn"},{"hanzi":"高尚","pinyin":"gāoshàng","vi":"cao thượng"}]},{"id":"堤","hanzi":"堤","pinyin":"dī","meaning_vi":"đê, bờ đê","explanation":"堤 (đê – bờ đắp chắn nước) → bờ đất, đá đắp dọc sông, biển để ngăn lũ.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"河边有一道长堤。","pinyin":"Hébiān yǒu yí Dàocháng dī.","vi":"Bên sông có một con đê dài."},{"type":"simple","zh":"傍晚很多人喜欢在堤上散步。","pinyin":"Bàngwǎn hěn duō rén xǐhuan zài dī shang sànbù.","vi":"Chiều tối nhiều người thích đi dạo trên đê."},{"type":"compound","zh":"如果大堤决口，下游的村庄就会被淹没。","pinyin":"Rúguǒ dà dī juékǒu, xiàyóu de cūnzhuāng jiù huì bèi yānmò.","vi":"Nếu đê lớn bị vỡ thì các làng hạ lưu sẽ bị nhấn chìm."}],"related":[{"hanzi":"堤坝","pinyin":"dībà","vi":"đê đập"},{"hanzi":"大坝","pinyin":"dàbà","vi":"đập lớn"},{"hanzi":"河岸","pinyin":"hé'àn","vi":"bờ sông"},{"hanzi":"防洪","pinyin":"fánghóng","vi":"phòng lũ"}]},{"id":"笛子","hanzi":"笛子","pinyin":"dízi","meaning_vi":"sáo (trúc)","explanation":"笛 (địch – ống sáo) + 子 → cây sáo trúc, nhạc cụ thổi ngang truyền thống.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🪈","examples":[{"type":"basic","zh":"他会吹笛子。","pinyin":"Tā huì chuī dízi.","vi":"Anh ấy biết thổi sáo."},{"type":"simple","zh":"远处传来一阵悠扬的笛子声。","pinyin":"Yuǎnchù chuánlái yízhèn yōuyáng de dízi shēng.","vi":"Từ xa vọng lại một tràng tiếng sáo du dương."},{"type":"compound","zh":"虽然笛子看起来很简单，但是要吹好并不容易。","pinyin":"Suīrán dízi kànqǐlái hěn jiǎndān, dànshì yào chuī hǎo bìngbù róngyì.","vi":"Tuy cây sáo trông rất đơn giản nhưng thổi hay chẳng dễ chút nào."}],"related":[{"hanzi":"吹","pinyin":"chuī","vi":"thổi"},{"hanzi":"箫","pinyin":"xiāo","vi":"tiêu"},{"hanzi":"二胡","pinyin":"èrhú","vi":"đàn nhị"},{"hanzi":"乐器","pinyin":"yuèqì","vi":"nhạc cụ"}]},{"id":"底层","hanzi":"底层","pinyin":"dǐcéng","meaning_vi":"tầng dưới cùng, tầng đáy, tầng lớp dưới","explanation":"底 (để – đáy) + 层 (tầng) → tầng thấp nhất của tòa nhà; nghĩa bóng: tầng lớp thấp nhất trong xã hội, tổ chức.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🧱","examples":[{"type":"basic","zh":"他住在大楼的底层。","pinyin":"Tā zhùzài dàlóu de dǐcéng.","vi":"Anh ấy sống ở tầng trệt của tòa nhà."},{"type":"simple","zh":"这部小说描写了社会底层人民的生活。","pinyin":"Zhè bù xiǎoshuō miáoxiěle shèhuì dǐcéng rénmín de shēnghuó.","vi":"Cuốn tiểu thuyết này miêu tả cuộc sống của người dân tầng lớp đáy xã hội."},{"type":"compound","zh":"虽然他从公司最底层做起，但是十年后当上了总经理。","pinyin":"Suīrán tā cóng gōngsī zuì dǐcéng zuò qǐ, dànshì shí nián hòu dāngshàngle zǒngjīnglǐ.","vi":"Tuy bắt đầu từ vị trí thấp nhất trong công ty nhưng mười năm sau anh ấy đã thành tổng giám đốc."}],"related":[{"hanzi":"顶层","pinyin":"dǐngcéng","vi":"tầng thượng"},{"hanzi":"基层","pinyin":"jīcéng","vi":"cơ sở"},{"hanzi":"阶层","pinyin":"jiēcéng","vi":"tầng lớp"},{"hanzi":"底部","pinyin":"dǐbù","vi":"phần đáy"}],"traditional":"底層"},{"id":"底子","hanzi":"底子","pinyin":"dǐzi","meaning_vi":"nền tảng, vốn liếng, cái nền","explanation":"底 (để – đáy, nền) + 子 → phần nền, đáy; nghĩa bóng: nền tảng kiến thức, sức khỏe, gia sản.","hsk_level":"7-9","tags":["danh-tu"],"image":"🏗️","examples":[{"type":"basic","zh":"他的英语底子很好。","pinyin":"Tā de Yīngyǔ dǐzi hěn hǎo.","vi":"Nền tảng tiếng Anh của anh ấy rất tốt."},{"type":"simple","zh":"这块白底子的布上绣着红花。","pinyin":"Zhè kuài bái dǐzi de bù shang xiùzhe hónghuā.","vi":"Tấm vải nền trắng này thêu hoa đỏ."},{"type":"compound","zh":"因为数学底子薄，所以他学物理特别吃力。","pinyin":"Yīnwèi shùxué dǐzi báo, suǒyǐ tā xué wùlǐ tèbié chīlì.","vi":"Vì nền tảng toán yếu nên cậu ấy học vật lý rất vất vả."}],"related":[{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"},{"hanzi":"底","pinyin":"dǐ","vi":"đáy"},{"hanzi":"功底","pinyin":"gōngdǐ","vi":"vốn liếng tay nghề"},{"hanzi":"根基","pinyin":"gēnjī","vi":"gốc rễ"}]},{"id":"抵挡","hanzi":"抵挡","pinyin":"dǐdǎng","meaning_vi":"chống đỡ, ngăn cản, cưỡng lại","explanation":"抵 (để – chống) + 挡 (đáng – chặn) → chống lại, ngăn chặn sức tấn công hay sự cám dỗ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"这件外套能抵挡寒风。","pinyin":"Zhè jiàn wàitào néng dǐdǎng hánfēng.","vi":"Chiếc áo khoác này chắn được gió lạnh."},{"type":"simple","zh":"他终究没能抵挡住美食的诱惑。","pinyin":"Tā zhōngjiū méi néng dǐdǎng zhù měishí de yòuhuò.","vi":"Rốt cuộc anh ấy không cưỡng lại được sự cám dỗ của đồ ăn ngon."},{"type":"compound","zh":"虽然防守队员拼尽全力，但是仍然抵挡不住对方的进攻。","pinyin":"Suīrán fángshǒu duìyuán pīn jìn quánlì, dànshì réngrán dǐdǎng búzhù duìfāng de jìngōng.","vi":"Tuy các hậu vệ dốc hết sức nhưng vẫn không chống đỡ nổi đợt tấn công của đối phương."}],"related":[{"hanzi":"抵抗","pinyin":"dǐkàng","vi":"chống cự"},{"hanzi":"阻挡","pinyin":"zǔdǎng","vi":"ngăn cản"},{"hanzi":"抵御","pinyin":"dǐyù","vi":"chống lại"},{"hanzi":"挡住","pinyin":"dǎngzhù","vi":"chặn lại"}],"traditional":"抵擋"},{"id":"弟子","hanzi":"弟子","pinyin":"dìzǐ","meaning_vi":"đệ tử, học trò","explanation":"弟 (đệ – em) + 子 (tử – con) → người theo học thầy, môn đồ.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🥋","examples":[{"type":"basic","zh":"孔子有很多弟子。","pinyin":"Kǒngzǐ yǒu hěn duō dìzǐ.","vi":"Khổng Tử có rất nhiều đệ tử."},{"type":"simple","zh":"这位大师一生只收了三个弟子。","pinyin":"Zhè wèi dàshī yìshēng zhǐ shōule sān gè dìzǐ.","vi":"Vị đại sư này cả đời chỉ nhận ba đệ tử."},{"type":"compound","zh":"虽然他是师父最小的弟子，但是武功最高。","pinyin":"Suīrán tā shì shīfu zuì xiǎo de dìzǐ, dànshì wǔgōng zuì gāo.","vi":"Tuy là đệ tử nhỏ nhất của sư phụ nhưng võ công của anh ta cao nhất."}],"related":[{"hanzi":"徒弟","pinyin":"túdì","vi":"đồ đệ"},{"hanzi":"师父","pinyin":"shīfu","vi":"sư phụ"},{"hanzi":"学生","pinyin":"xuésheng","vi":"học sinh"},{"hanzi":"门徒","pinyin":"méntú","vi":"môn đồ"}]},{"id":"帝国主义","hanzi":"帝国主义","pinyin":"dìguózhǔyì","meaning_vi":"chủ nghĩa đế quốc","explanation":"帝国 (đế quốc) + 主义 (chủ nghĩa) → chính sách bành trướng, xâm lược, áp bức các nước khác để mở rộng thế lực.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏴","examples":[{"type":"basic","zh":"他们反对帝国主义。","pinyin":"Tāmen fǎnduì dìguózhǔyì.","vi":"Họ phản đối chủ nghĩa đế quốc."},{"type":"simple","zh":"这本书分析了帝国主义的历史根源。","pinyin":"Zhè běn shū fēnxīle dìguózhǔyì de lìshǐ gēnyuán.","vi":"Cuốn sách này phân tích nguồn gốc lịch sử của chủ nghĩa đế quốc."},{"type":"compound","zh":"虽然那个时代已经过去，但是帝国主义留下的影响至今还在。","pinyin":"Suīrán nà ge shídài yǐjīng guòqù, dànshì dìguózhǔyì liúxià de yǐngxiǎng zhìjīn hái zài.","vi":"Tuy thời đại đó đã qua nhưng ảnh hưởng do chủ nghĩa đế quốc để lại đến nay vẫn còn."}],"related":[{"hanzi":"帝国","pinyin":"dìguó","vi":"đế quốc"},{"hanzi":"殖民主义","pinyin":"zhímínzhǔyì","vi":"chủ nghĩa thực dân"},{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"},{"hanzi":"霸权","pinyin":"bàquán","vi":"bá quyền"}],"traditional":"帝國主義"},{"id":"递交","hanzi":"递交","pinyin":"dìjiāo","meaning_vi":"đệ trình, trao, nộp","explanation":"递 (đệ – chuyển, đưa) + 交 (giao – giao nộp) → trao tận tay, nộp lên (đơn từ, văn bản); trang trọng.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📨","examples":[{"type":"basic","zh":"他递交了辞职信。","pinyin":"Tā dìjiāole cízhíxìn.","vi":"Anh ấy đã nộp đơn xin nghỉ việc."},{"type":"simple","zh":"大使向总统递交了国书。","pinyin":"Dàshǐ xiàng zǒngtǒng dìjiāole guóshū.","vi":"Đại sứ đã trình quốc thư lên tổng thống."},{"type":"compound","zh":"如果你想参加比赛，就必须在月底前递交申请。","pinyin":"Rúguǒ nǐ xiǎng cānjiā bǐsài, jiù bìxū zài yuèdǐ qián dìjiāo shēnqǐng.","vi":"Nếu bạn muốn tham gia cuộc thi thì phải nộp đơn trước cuối tháng."}],"related":[{"hanzi":"提交","pinyin":"tíjiāo","vi":"nộp"},{"hanzi":"上交","pinyin":"shàngjiāo","vi":"nộp lên"},{"hanzi":"传递","pinyin":"chuándì","vi":"truyền"},{"hanzi":"递","pinyin":"dì","vi":"đưa"}],"traditional":"遞交"},{"id":"第一手","hanzi":"第一手","pinyin":"dìyīshǒu","meaning_vi":"trực tiếp, đầu tay, tận mắt","explanation":"第一 (đệ nhất – thứ nhất) + 手 (thủ – tay) → qua tay đầu tiên, trực tiếp có được; thường gặp 第一手资料.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔎","examples":[{"type":"basic","zh":"这是第一手资料。","pinyin":"Zhè shì dìyīshǒu zīliào.","vi":"Đây là tài liệu trực tiếp."},{"type":"simple","zh":"记者到现场获取第一手信息。","pinyin":"Jìzhě dào xiànchǎng huòqǔ dìyīshǒu xìnxī.","vi":"Phóng viên đến hiện trường lấy thông tin trực tiếp."},{"type":"compound","zh":"如果没有第一手数据，研究结论就不够可靠。","pinyin":"Rúguǒ méiyǒu dìyīshǒu shùjù, yánjiū jiélùn jiù búgòu kěkào.","vi":"Nếu không có số liệu trực tiếp thì kết luận nghiên cứu sẽ không đủ tin cậy."}],"related":[{"hanzi":"二手","pinyin":"èrshǒu","vi":"cũ, qua tay"},{"hanzi":"直接","pinyin":"zhíjiē","vi":"trực tiếp"},{"hanzi":"资料","pinyin":"zīliào","vi":"tài liệu"},{"hanzi":"亲眼","pinyin":"qīnyǎn","vi":"tận mắt"}]},{"id":"第一线","hanzi":"第一线","pinyin":"dìyīxiàn","meaning_vi":"tuyến đầu, tiền tuyến, trực tiếp","explanation":"第一 (đệ nhất) + 线 (tuyến) → tuyến đầu tiên; chỉ nơi trực tiếp làm việc, chiến đấu, sản xuất.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🛡️","examples":[{"type":"basic","zh":"医生们奋战在第一线。","pinyin":"Yīshēngmen fènzhàn zài dìyīxiàn.","vi":"Các bác sĩ chiến đấu ở tuyến đầu."},{"type":"simple","zh":"经理经常深入生产第一线了解情况。","pinyin":"Jīnglǐ jīngcháng shēnrù shēngchǎn dìyīxiàn liǎojiě qíngkuàng.","vi":"Giám đốc thường xuống tận tuyến sản xuất trực tiếp để nắm tình hình."},{"type":"compound","zh":"虽然他已经五十多岁了，但是仍然坚持在教学第一线。","pinyin":"Suīrán tā yǐjīng wǔshí duō suì le, dànshì réngrán jiānchí zài jiàoxué dìyīxiàn.","vi":"Tuy đã ngoài năm mươi nhưng ông ấy vẫn kiên trì trực tiếp đứng lớp."}],"related":[{"hanzi":"前线","pinyin":"qiánxiàn","vi":"tiền tuyến"},{"hanzi":"一线","pinyin":"yíxiàn","vi":"tuyến đầu"},{"hanzi":"基层","pinyin":"jīcéng","vi":"cơ sở"},{"hanzi":"后方","pinyin":"hòufāng","vi":"hậu phương"}],"traditional":"第一線"},{"id":"巅峰","hanzi":"巅峰","pinyin":"diānfēng","meaning_vi":"đỉnh cao, đỉnh điểm","explanation":"巅 (điên – đỉnh núi) + 峰 (phong – ngọn núi) → đỉnh núi cao nhất; nghĩa bóng: thời kỳ đỉnh cao của sự nghiệp.","hsk_level":"7-9","tags":["danh-tu"],"image":"🏔️","examples":[{"type":"basic","zh":"他正处在事业的巅峰。","pinyin":"Tā zhèng chǔzài shìyè de diānfēng.","vi":"Anh ấy đang ở đỉnh cao sự nghiệp."},{"type":"simple","zh":"那一年是这支球队的巅峰时期。","pinyin":"Nà yì nián shì zhè zhī qiúduì de diānfēng shíqī.","vi":"Năm đó là thời kỳ đỉnh cao của đội bóng này."},{"type":"compound","zh":"虽然她在巅峰时选择了退役，但是粉丝们都很理解她。","pinyin":"Suīrán tā zài diānfēng shí xuǎnzéle tuìyì, dànshì fěnsīmen dōu hěn lǐjiě tā.","vi":"Tuy cô ấy chọn giải nghệ khi đang ở đỉnh cao nhưng người hâm mộ đều rất thông cảm."}],"related":[{"hanzi":"顶峰","pinyin":"dǐngfēng","vi":"đỉnh cao"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"cao điểm"},{"hanzi":"山峰","pinyin":"shānfēng","vi":"đỉnh núi"},{"hanzi":"低谷","pinyin":"dīgǔ","vi":"đáy, thời kỳ sa sút"}],"traditional":"巔峰"},{"id":"点子","hanzi":"点子","pinyin":"diǎnzi","meaning_vi":"ý tưởng, sáng kiến; chấm, điểm","explanation":"点 (điểm – chấm) + 子 → chấm nhỏ; khẩu ngữ thông dụng: ý tưởng, mẹo hay (好点子, 出点子).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"这是个好点子！","pinyin":"Zhè shì gè hǎo diǎnzi!","vi":"Đây là một ý tưởng hay!"},{"type":"simple","zh":"她总能想出一些新奇的点子。","pinyin":"Tā zǒngnéng xiǎngchū yìxiē xīnqí de diǎnzi.","vi":"Cô ấy luôn nghĩ ra được những ý tưởng mới lạ."},{"type":"compound","zh":"如果大家都没有好点子，我们就先按原计划进行。","pinyin":"Rúguǒ dàjiā dōu méiyǒu hǎo diǎnzi, wǒmen jiù xiān àn yuán jìhuà jìnxíng.","vi":"Nếu mọi người đều chưa có ý tưởng hay thì chúng ta cứ làm theo kế hoạch cũ trước."}],"related":[{"hanzi":"主意","pinyin":"zhǔyi","vi":"ý kiến"},{"hanzi":"想法","pinyin":"xiǎngfǎ","vi":"suy nghĩ"},{"hanzi":"创意","pinyin":"chuàngyì","vi":"sáng tạo"},{"hanzi":"出点子","pinyin":"chūdiǎnzi","vi":"đưa ra ý tưởng"}],"traditional":"點子"},{"id":"电铃","hanzi":"电铃","pinyin":"diànlíng","meaning_vi":"chuông điện","explanation":"电 (điện) + 铃 (linh – chuông) → chuông chạy bằng điện, như chuông cửa, chuông trường.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔔","examples":[{"type":"basic","zh":"门口的电铃响了。","pinyin":"Ménkǒu de diànlíng xiǎng le.","vi":"Chuông điện ở cửa reo rồi."},{"type":"simple","zh":"下课的电铃一响，学生们就冲出了教室。","pinyin":"Xiàkè de diànlíng yì xiǎng, xuéshengmen jiù chōngchūle jiàoshì.","vi":"Chuông tan học vừa reo, học sinh liền ùa ra khỏi lớp."},{"type":"compound","zh":"因为门口的电铃坏了，所以客人只好敲门。","pinyin":"Yīnwèi ménkǒu de diànlíng huàile, suǒyǐ kèrén zhǐhǎo qiāomén.","vi":"Vì chuông điện ở cửa bị hỏng nên khách đành phải gõ cửa."}],"related":[{"hanzi":"门铃","pinyin":"ménlíng","vi":"chuông cửa"},{"hanzi":"铃声","pinyin":"língshēng","vi":"tiếng chuông"},{"hanzi":"闹钟","pinyin":"nàozhōng","vi":"đồng hồ báo thức"},{"hanzi":"按铃","pinyin":"ànlíng","vi":"bấm chuông"}],"traditional":"電鈴"},{"id":"电网","hanzi":"电网","pinyin":"diànwǎng","meaning_vi":"lưới điện; hàng rào điện","explanation":"电 (điện) + 网 (võng – lưới) → mạng lưới truyền tải điện; cũng chỉ lưới rào có điện.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"⚡","examples":[{"type":"basic","zh":"这个村子接入了电网。","pinyin":"Zhè ge cūnzi jiērùle diànwǎng.","vi":"Ngôi làng này đã được nối lưới điện."},{"type":"simple","zh":"监狱四周围着高压电网。","pinyin":"Jiānyù sì zhōuwéizhe gāoyā diànwǎng.","vi":"Xung quanh nhà tù có hàng rào điện cao thế."},{"type":"compound","zh":"一旦电网出现故障，整个城市就会停电。","pinyin":"Yídàn diànwǎng chūxiàn gùzhàng, zhěnggè chéngshì jiù huì tíngdiàn.","vi":"Một khi lưới điện gặp sự cố, cả thành phố sẽ mất điện."}],"related":[{"hanzi":"电力","pinyin":"diànlì","vi":"điện lực"},{"hanzi":"电线","pinyin":"diànxiàn","vi":"dây điện"},{"hanzi":"停电","pinyin":"tíngdiàn","vi":"mất điện"},{"hanzi":"发电","pinyin":"fādiàn","vi":"phát điện"}],"traditional":"電網"},{"id":"电线","hanzi":"电线","pinyin":"diànxiàn","meaning_vi":"dây điện","explanation":"电 (điện) + 线 (tuyến – dây) → dây dẫn điện.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔌","examples":[{"type":"basic","zh":"小心地上的电线。","pinyin":"Xiǎoxīn dìshang de diànxiàn.","vi":"Cẩn thận dây điện dưới đất."},{"type":"simple","zh":"老房子的电线已经老化了。","pinyin":"Lǎo fángzi de diànxiàn yǐjīng lǎohuà le.","vi":"Dây điện của ngôi nhà cũ đã bị lão hóa."},{"type":"compound","zh":"如果电线外皮破了，就要马上换掉，否则很危险。","pinyin":"Rúguǒ diànxiàn wàipí pò le, jiùyào mǎshàng huàn diào, fǒuzé hěn wēixiǎn.","vi":"Nếu vỏ dây điện bị rách thì phải thay ngay, nếu không rất nguy hiểm."}],"related":[{"hanzi":"电缆","pinyin":"diànlǎn","vi":"cáp điện"},{"hanzi":"插头","pinyin":"chātóu","vi":"phích cắm"},{"hanzi":"电网","pinyin":"diànwǎng","vi":"lưới điện"},{"hanzi":"电线杆","pinyin":"diànxiàngān","vi":"cột điện"}],"traditional":"電線"},{"id":"电信","hanzi":"电信","pinyin":"diànxìn","meaning_vi":"viễn thông","explanation":"电 (điện) + 信 (tín – tin tức) → truyền tin bằng điện, tức ngành viễn thông.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📡","examples":[{"type":"basic","zh":"他在电信公司上班。","pinyin":"Tā zài diànxìn gōngsī shàngbān.","vi":"Anh ấy làm ở công ty viễn thông."},{"type":"simple","zh":"警方提醒大家小心电信诈骗。","pinyin":"Jǐngfāng tíxǐng dàjiā xiǎoxīn diànxìn zhàpiàn.","vi":"Cảnh sát nhắc mọi người cẩn thận lừa đảo qua điện thoại."},{"type":"compound","zh":"因为电信网络升级，所以今晚手机信号可能会不稳定。","pinyin":"Yīnwèi diànxìn wǎngluò shēngjí, suǒyǐ jīnwǎn shǒujī xìnhào kěnéng huì bù wěndìng.","vi":"Vì mạng viễn thông nâng cấp nên tối nay sóng điện thoại có thể không ổn định."}],"related":[{"hanzi":"通信","pinyin":"tōngxìn","vi":"thông tin liên lạc"},{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"},{"hanzi":"运营商","pinyin":"yùnyíngshāng","vi":"nhà mạng"},{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"}],"traditional":"電信"},{"id":"垫子","hanzi":"垫子","pinyin":"diànzi","meaning_vi":"đệm, tấm lót, thảm","explanation":"垫 (điếm – lót, kê) + 子 → vật lót bên dưới cho êm hoặc sạch: đệm ghế, thảm tập.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧘","examples":[{"type":"basic","zh":"椅子上放个垫子。","pinyin":"Yǐzi shang fàng gè diànzi.","vi":"Đặt một cái đệm lên ghế."},{"type":"simple","zh":"她每天早上在瑜伽垫子上做运动。","pinyin":"Tā měitiān zǎoshang zài yújiā diànzi shang zuò yùndòng.","vi":"Mỗi sáng cô ấy tập thể dục trên thảm yoga."},{"type":"compound","zh":"因为地板太凉，所以他在下面铺了一层垫子。","pinyin":"Yīnwèi dìbǎn tài liáng, suǒyǐ tā zài xiàmiàn pūle yīcéng diànzi.","vi":"Vì sàn nhà quá lạnh nên anh ấy trải một lớp đệm bên dưới."}],"related":[{"hanzi":"坐垫","pinyin":"zuòdiàn","vi":"đệm ngồi"},{"hanzi":"靠垫","pinyin":"kàodiàn","vi":"gối tựa"},{"hanzi":"床垫","pinyin":"chuángdiàn","vi":"nệm giường"},{"hanzi":"垫","pinyin":"diàn","vi":"lót, kê"}],"traditional":"墊子"},{"id":"淀粉","hanzi":"淀粉","pinyin":"diànfěn","meaning_vi":"tinh bột","explanation":"淀 (điến – lắng đọng) + 粉 (phấn – bột) → bột lắng xuống từ ngũ cốc, khoai củ, tức tinh bột.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🥔","examples":[{"type":"basic","zh":"土豆里含有大量淀粉。","pinyin":"Tǔdòu li hányǒu dàliàng diànfěn.","vi":"Khoai tây chứa nhiều tinh bột."},{"type":"simple","zh":"炒肉前先用淀粉把肉片抓一下。","pinyin":"Chǎo ròu qián xiān yòng diànfěn bǎ ròupiàn zhuā yíxià.","vi":"Trước khi xào thịt hãy trộn thịt thái lát với chút tinh bột."},{"type":"compound","zh":"如果晚饭吃太多淀粉类食物，就容易长胖。","pinyin":"Rúguǒ wǎnfàn chī tài duō diànfěn lèi shíwù, jiù róngyì zhǎngpàng.","vi":"Nếu bữa tối ăn quá nhiều đồ ăn chứa tinh bột thì dễ tăng cân."}],"related":[{"hanzi":"面粉","pinyin":"miànfěn","vi":"bột mì"},{"hanzi":"蛋白质","pinyin":"dànbáizhì","vi":"chất đạm"},{"hanzi":"碳水化合物","pinyin":"tànshuǐ huàhéwù","vi":"carbohydrate"},{"hanzi":"粉","pinyin":"fěn","vi":"bột"}],"traditional":"澱粉"},{"id":"殿堂","hanzi":"殿堂","pinyin":"diàntáng","meaning_vi":"điện đường, cung điện; (bóng) thánh đường","explanation":"殿 (điện – cung điện) + 堂 (đường – gian nhà lớn) → tòa nhà lớn, cung điện, đền miếu; nghĩa bóng: đỉnh cao, nơi tôn nghiêm (艺术殿堂).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"寺庙的殿堂十分宏伟。","pinyin":"Sìmiào de diàntáng shífēn hóngwěi.","vi":"Điện đường của ngôi chùa vô cùng hùng vĩ."},{"type":"simple","zh":"她终于走进了音乐的最高殿堂。","pinyin":"Tā zhōngyú zǒujìnle yīnyuè de zuì gāo diàntáng.","vi":"Cuối cùng cô ấy đã bước vào thánh đường cao nhất của âm nhạc."},{"type":"compound","zh":"虽然通往科学殿堂的路很艰苦，但是他从来没有后悔过。","pinyin":"Suīrán tōngwǎng kēxué diàntáng de lù hěn jiānkǔ, dànshì tā cónglái méiyǒu hòuhuǐ guo.","vi":"Tuy con đường đến thánh đường khoa học rất gian khổ nhưng anh ấy chưa bao giờ hối hận."}],"related":[{"hanzi":"宫殿","pinyin":"gōngdiàn","vi":"cung điện"},{"hanzi":"大殿","pinyin":"dàdiàn","vi":"chính điện"},{"hanzi":"圣殿","pinyin":"shèngdiàn","vi":"thánh điện"},{"hanzi":"礼堂","pinyin":"lǐtáng","vi":"hội trường"}]},{"id":"刁难","hanzi":"刁难","pinyin":"diāonàn","meaning_vi":"làm khó, gây khó dễ, hạch sách","explanation":"刁 (điêu – xảo quyệt) + 难 (nan – khó) → cố ý gây khó khăn cho người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😈","examples":[{"type":"basic","zh":"别故意刁难他。","pinyin":"Bié gùyì diāonàn tā.","vi":"Đừng cố tình làm khó anh ấy."},{"type":"simple","zh":"那个顾客总是百般刁难服务员。","pinyin":"Nà ge gùkè zǒngshì bǎibān diāonàn fúwùyuán.","vi":"Vị khách đó luôn tìm mọi cách hạch sách nhân viên phục vụ."},{"type":"compound","zh":"即使对方处处刁难，他也始终保持礼貌。","pinyin":"Jíshǐ duìfāng chùchù diāonàn, tā yě shǐzhōng bǎochí lǐmào.","vi":"Dù đối phương gây khó dễ khắp nơi, anh ấy vẫn luôn giữ lễ độ."}],"related":[{"hanzi":"为难","pinyin":"wéinán","vi":"làm khó"},{"hanzi":"出难题","pinyin":"chūnántí","vi":"ra đề khó"},{"hanzi":"穿小鞋","pinyin":"chuānxiǎoxié","vi":"trù dập"},{"hanzi":"刁钻","pinyin":"diāozuān","vi":"xảo quyệt"}],"traditional":"刁難"},{"id":"雕","hanzi":"雕","pinyin":"diāo","meaning_vi":"chạm, khắc, điêu khắc; chim đại bàng","explanation":"雕 (điêu – chạm trổ) → khắc, chạm lên gỗ, đá, ngọc; còn chỉ loài chim săn mồi lớn.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🗿","examples":[{"type":"basic","zh":"他在木头上雕了一朵花。","pinyin":"Tā zài mùtou shang diāole yìduǒhuā.","vi":"Anh ấy khắc một bông hoa lên gỗ."},{"type":"simple","zh":"这尊石像是用一整块石头雕成的。","pinyin":"Zhè zūn shíxiàng shì yòng yì zhěng kuài shítou diāo chéng de.","vi":"Bức tượng đá này được tạc từ nguyên một khối đá."},{"type":"compound","zh":"虽然雕一件作品要花好几个月，但是他乐在其中。","pinyin":"Suīrán diāo yí jiàn zuòpǐn yào huā hǎojǐ gèyuè, dànshì tā lè zài qízhōng.","vi":"Tuy khắc một tác phẩm mất mấy tháng trời nhưng anh ấy vẫn thấy vui trong đó."}],"related":[{"hanzi":"雕刻","pinyin":"diāokè","vi":"điêu khắc"},{"hanzi":"雕塑","pinyin":"diāosù","vi":"tượng điêu khắc"},{"hanzi":"刻","pinyin":"kè","vi":"khắc"},{"hanzi":"浮雕","pinyin":"fúdiāo","vi":"phù điêu"}]},{"id":"钓鱼","hanzi":"钓鱼","pinyin":"diàoyú","meaning_vi":"câu cá; (bóng) gài bẫy, lừa","explanation":"钓 (điếu – câu) + 鱼 (ngư – cá) → dùng cần câu bắt cá; nghĩa bóng: giăng bẫy dụ người (钓鱼网站 = trang web lừa đảo).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎣","examples":[{"type":"basic","zh":"爷爷喜欢去河边钓鱼。","pinyin":"Yéye xǐhuan qù hébiān diàoyú.","vi":"Ông nội thích ra bờ sông câu cá."},{"type":"simple","zh":"千万别点开那个钓鱼网站的链接。","pinyin":"Qiānwàn bié diǎnkāi nà ge diàoyú wǎngzhàn de liànjiē.","vi":"Tuyệt đối đừng bấm vào đường link trang web lừa đảo đó."},{"type":"compound","zh":"虽然钓鱼需要很大的耐心，但是他一坐就是一整天。","pinyin":"Suīrán diàoyú xūyào hěn dà de nàixīn, dànshì tā yí zuò jiùshì yìzhěngtiān.","vi":"Tuy câu cá cần rất nhiều kiên nhẫn nhưng ông ấy hễ ngồi là ngồi suốt cả ngày."}],"related":[{"hanzi":"鱼竿","pinyin":"yúgān","vi":"cần câu"},{"hanzi":"鱼饵","pinyin":"yú'ěr","vi":"mồi câu"},{"hanzi":"捕鱼","pinyin":"bǔyú","vi":"đánh cá"},{"hanzi":"上钩","pinyin":"shànggōu","vi":"mắc câu"}],"traditional":"釣魚"},{"id":"调度","hanzi":"调度","pinyin":"diàodù","meaning_vi":"điều độ, điều phối, phân bổ","explanation":"调 (điều – điều động) + 度 (độ – tính toán) → sắp xếp, điều phối xe cộ, nhân lực, công việc; cũng chỉ người điều phối.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚦","examples":[{"type":"basic","zh":"他负责车辆调度。","pinyin":"Tā fùzé chēliàng diàodù.","vi":"Anh ấy phụ trách điều phối xe."},{"type":"simple","zh":"地铁公司临时调度了几列空车。","pinyin":"Dìtiě gōngsī línshí diàodùle jǐ liè kōng chē.","vi":"Công ty tàu điện ngầm tạm thời điều thêm mấy đoàn tàu rỗng."},{"type":"compound","zh":"如果调度不合理，工人们就会有时忙死、有时闲死。","pinyin":"Rúguǒ diàodù bù hélǐ, gōngrénmen jiù huì yǒushí máng sǐ, yǒushí xián sǐ.","vi":"Nếu điều phối không hợp lý thì công nhân sẽ lúc bận tối mắt, lúc lại rảnh rỗi."}],"related":[{"hanzi":"调配","pinyin":"diàopèi","vi":"điều phối"},{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"},{"hanzi":"指挥","pinyin":"zhǐhuī","vi":"chỉ huy"},{"hanzi":"调动","pinyin":"diàodòng","vi":"điều động"}],"traditional":"調度"},{"id":"掉队","hanzi":"掉队","pinyin":"diàoduì","meaning_vi":"tụt lại, rớt khỏi đoàn, tụt hậu","explanation":"掉 (điệu – rơi) + 队 (đội – hàng ngũ) → rơi khỏi đội ngũ, không theo kịp; nghĩa bóng: tụt hậu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🐢","examples":[{"type":"basic","zh":"他爬山时掉队了。","pinyin":"Tā páshān shí diàoduì le.","vi":"Lúc leo núi anh ấy bị tụt lại."},{"type":"simple","zh":"老师特别关心学习上掉队的学生。","pinyin":"Lǎoshī tèbié guānxīn xuéxí shang diàoduì de xuésheng.","vi":"Cô giáo đặc biệt quan tâm những học sinh bị tụt lại trong học tập."},{"type":"compound","zh":"如果不及时学习新技术，就很容易在行业中掉队。","pinyin":"Rúguǒ bù jíshí xuéxí xīnjìshù, jiù hěn róngyì zài hángyè zhōng diàoduì.","vi":"Nếu không kịp thời học công nghệ mới thì rất dễ bị tụt hậu trong ngành."}],"related":[{"hanzi":"落后","pinyin":"luòhòu","vi":"lạc hậu"},{"hanzi":"跟不上","pinyin":"gēnbúshàng","vi":"không theo kịp"},{"hanzi":"队伍","pinyin":"duìwu","vi":"đội ngũ"},{"hanzi":"领先","pinyin":"lǐngxiān","vi":"dẫn trước"}],"traditional":"掉隊"},{"id":"掉头","hanzi":"掉头","pinyin":"diàotóu","meaning_vi":"quay đầu, quay lại","explanation":"掉 (điệu – quay, xoay) + 头 (đầu) → quay đầu xe hoặc quay người theo hướng ngược lại.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"↩️","examples":[{"type":"basic","zh":"前面路口可以掉头。","pinyin":"Qiánmiàn lùkǒu kěyǐ diàotóu.","vi":"Giao lộ phía trước có thể quay đầu."},{"type":"simple","zh":"司机发现走错了路，马上掉头往回开。","pinyin":"Sījī fāxiàn zǒucuòle lù, mǎshàng diàotóu wǎng huí kāi.","vi":"Tài xế phát hiện đi nhầm đường, lập tức quay đầu chạy về."},{"type":"compound","zh":"因为这条路禁止掉头，所以我们只能再往前开一公里。","pinyin":"Yīnwèi zhè tiáo lù jìnzhǐ diàotóu, suǒyǐ wǒmen zhǐnéng zài wǎng qián kāi yì gōnglǐ.","vi":"Vì đường này cấm quay đầu nên chúng ta chỉ có thể chạy thêm một cây số nữa."}],"related":[{"hanzi":"转弯","pinyin":"zhuǎnwān","vi":"rẽ"},{"hanzi":"回头","pinyin":"huítóu","vi":"quay đầu lại"},{"hanzi":"调头","pinyin":"diàotóu","vi":"quay đầu"},{"hanzi":"倒车","pinyin":"dàochē","vi":"lùi xe"}],"traditional":"掉頭"},{"id":"爹","hanzi":"爹","pinyin":"diē","meaning_vi":"cha, bố, tía","explanation":"爹 (đa – cha) → cách gọi cha trong khẩu ngữ, nhất là ở nông thôn phương Bắc.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨","examples":[{"type":"basic","zh":"爹，我回来了！","pinyin":"Diē, wǒ huílái le!","vi":"Bố ơi, con về rồi!"},{"type":"simple","zh":"他爹是村里有名的木匠。","pinyin":"Tā diē shì cūnli yǒumíng de mùjiang.","vi":"Bố cậu ấy là người thợ mộc nổi tiếng trong làng."},{"type":"compound","zh":"虽然爹不善于表达，但是他心里一直很疼我。","pinyin":"Suīrán diē bú shànyú biǎodá, dànshì tā xīnli yìzhí hěn téng wǒ.","vi":"Tuy bố không giỏi bày tỏ nhưng trong lòng ông luôn rất thương tôi."}],"related":[{"hanzi":"爸爸","pinyin":"bàba","vi":"bố"},{"hanzi":"娘","pinyin":"niáng","vi":"mẹ"},{"hanzi":"父亲","pinyin":"fùqīn","vi":"phụ thân"},{"hanzi":"爹娘","pinyin":"diēniáng","vi":"cha mẹ"}]},{"id":"迭起","hanzi":"迭起","pinyin":"diéqǐ","meaning_vi":"liên tiếp nổi lên, dồn dập","explanation":"迭 (điệt – thay nhau, liên tiếp) + 起 (khởi – nổi lên) → liên tục xuất hiện; hay gặp 高潮迭起 (cao trào liên tiếp).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"比赛高潮迭起。","pinyin":"Bǐsài gāocháo diéqǐ.","vi":"Trận đấu cao trào dồn dập."},{"type":"simple","zh":"这部电影情节紧凑，笑点迭起。","pinyin":"Zhè bù diànyǐng qíngjié jǐncòu, xiàodiǎn diéqǐ.","vi":"Bộ phim này tình tiết chặt chẽ, tiếng cười liên tiếp."},{"type":"compound","zh":"虽然后半场险情迭起，但是我们的守门员都化解了。","pinyin":"Suīrán hòubànchǎng xiǎnqíng diéqǐ, dànshì wǒmen de shǒuményuán dōu huàjiě le.","vi":"Tuy hiệp hai liên tiếp có tình huống nguy hiểm nhưng thủ môn của chúng ta đều hóa giải được."}],"related":[{"hanzi":"此起彼伏","pinyin":"cǐqǐbǐfú","vi":"nơi này lên nơi kia xuống"},{"hanzi":"接连","pinyin":"jiēlián","vi":"liên tiếp"},{"hanzi":"频繁","pinyin":"pínfán","vi":"thường xuyên"},{"hanzi":"高潮","pinyin":"gāocháo","vi":"cao trào"}]},{"id":"叠","hanzi":"叠","pinyin":"dié","meaning_vi":"gấp, xếp chồng; lớp, chồng (lượng từ)","explanation":"叠 (điệp – chồng lên) → xếp chồng lên nhau; gấp (quần áo, giấy); làm lượng từ: một xấp, một chồng.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"👕","examples":[{"type":"basic","zh":"请把衣服叠好。","pinyin":"Qǐng bǎ yīfu dié hǎo.","vi":"Hãy gấp quần áo cho gọn."},{"type":"simple","zh":"桌上放着一叠厚厚的文件。","pinyin":"Zhuō shang fàngzhe yì dié hòu hòu de wénjiàn.","vi":"Trên bàn để một chồng tài liệu dày cộp."},{"type":"compound","zh":"因为她每天起床都叠被子，所以房间总是很整齐。","pinyin":"Yīnwèi tā měitiān qǐchuáng dōu dié bèizi, suǒyǐ fángjiān zǒngshì hěn zhěngqí.","vi":"Vì ngày nào thức dậy cô ấy cũng gấp chăn nên căn phòng luôn ngăn nắp."}],"related":[{"hanzi":"折","pinyin":"zhé","vi":"gấp"},{"hanzi":"重叠","pinyin":"chóngdié","vi":"trùng lặp"},{"hanzi":"叠加","pinyin":"diéjiā","vi":"chồng thêm"},{"hanzi":"堆","pinyin":"duī","vi":"chất đống"}],"traditional":"疊"},{"id":"钉","hanzi":"钉","pinyin":"dīng","meaning_vi":"cái đinh; bám sát","explanation":"钉 (đinh – cái đinh) đọc dīng: đinh, bám sát (钉住); đọc dìng: đóng đinh (钉钉子).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"📌","examples":[{"type":"basic","zh":"墙上有一颗钉。","pinyin":"Qiáng shang yǒu yì kē dīng.","vi":"Trên tường có một cái đinh."},{"type":"simple","zh":"他的鞋底被一颗钉扎破了。","pinyin":"Tā de xiédǐ bèi yì kē dīng zhā pò le.","vi":"Đế giày của anh ấy bị một cái đinh đâm thủng."},{"type":"compound","zh":"如果比赛时你钉住对方的前锋，我们就能守住比分。","pinyin":"Rúguǒ bǐsài shí nǐ dīng zhù duìfāng de qiánfēng, wǒmen jiù néng shǒuzhù bǐfēn.","vi":"Nếu khi thi đấu bạn bám sát tiền đạo đối phương thì chúng ta có thể giữ được tỷ số."}],"related":[{"hanzi":"钉子","pinyin":"dīngzi","vi":"cái đinh"},{"hanzi":"图钉","pinyin":"túdīng","vi":"đinh ghim"},{"hanzi":"螺丝钉","pinyin":"luósīdīng","vi":"đinh vít"},{"hanzi":"锤子","pinyin":"chuízi","vi":"búa"}],"traditional":"釘"},{"id":"钉子","hanzi":"钉子","pinyin":"dīngzi","meaning_vi":"cái đinh; (bóng) trở ngại, sự cự tuyệt","explanation":"钉 (đinh) + 子 → cái đinh; nghĩa bóng: trở ngại (碰钉子 = bị từ chối), người cản trở (钉子户).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔨","examples":[{"type":"basic","zh":"墙上钉了一颗钉子。","pinyin":"Qiáng shang dìngle yì kē dīngzi.","vi":"Trên tường đóng một cái đinh."},{"type":"simple","zh":"他去求人办事，结果碰了个钉子。","pinyin":"Tā qù qiúrén bànshì, jiéguǒ pèngle gè dīngzi.","vi":"Anh ấy đi nhờ người ta làm việc, kết quả bị từ chối thẳng thừng."},{"type":"compound","zh":"如果不把这颗钉子拔掉，椅子就会划破裤子。","pinyin":"Rúguǒ bù bǎ zhè kē dīngzi bádiào, yǐzi jiù huì huápò kùzi.","vi":"Nếu không nhổ cái đinh này ra thì ghế sẽ làm rách quần."}],"related":[{"hanzi":"钉","pinyin":"dīng","vi":"đinh"},{"hanzi":"碰钉子","pinyin":"pèngdīngzi","vi":"bị từ chối"},{"hanzi":"钉子户","pinyin":"dīngzihù","vi":"hộ bám trụ không di dời"},{"hanzi":"锤子","pinyin":"chuízi","vi":"búa"}],"traditional":"釘子"},{"id":"顶级","hanzi":"顶级","pinyin":"dǐngjí","meaning_vi":"hàng đầu, đỉnh cao, cao cấp nhất","explanation":"顶 (đỉnh – đỉnh) + 级 (cấp – cấp bậc) → cấp bậc cao nhất, hạng nhất.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥇","examples":[{"type":"basic","zh":"这是顶级的红酒。","pinyin":"Zhè shì dǐngjí de hóngjiǔ.","vi":"Đây là rượu vang hảo hạng."},{"type":"simple","zh":"他是世界顶级的网球运动员。","pinyin":"Tā shì shìjiè dǐngjí de wǎngqiú yùndòngyuán.","vi":"Anh ấy là vận động viên quần vợt hàng đầu thế giới."},{"type":"compound","zh":"虽然这家酒店是顶级的，但是服务却让人失望。","pinyin":"Suīrán zhè jiā jiǔdiàn shì dǐngjí de, dànshì fúwù què ràng rén shīwàng.","vi":"Tuy khách sạn này thuộc hạng cao cấp nhất nhưng dịch vụ lại khiến người ta thất vọng."}],"related":[{"hanzi":"顶尖","pinyin":"dǐngjiān","vi":"đỉnh cao"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"},{"hanzi":"高级","pinyin":"gāojí","vi":"cao cấp"},{"hanzi":"低级","pinyin":"dījí","vi":"cấp thấp"}],"traditional":"頂級"},{"id":"顶尖","hanzi":"顶尖","pinyin":"dǐngjiān","meaning_vi":"đỉnh cao, hàng đầu, xuất sắc nhất","explanation":"顶 (đỉnh) + 尖 (tiêm – mũi nhọn) → chóp đỉnh; nghĩa bóng: giỏi nhất, hàng đầu.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏆","examples":[{"type":"basic","zh":"她是顶尖的设计师。","pinyin":"Tā shì dǐngjiān de shèjìshī.","vi":"Cô ấy là nhà thiết kế hàng đầu."},{"type":"simple","zh":"这所大学吸引了很多顶尖人才。","pinyin":"Zhè suǒ dàxué xīyǐnle hěn duō dǐngjiān réncái.","vi":"Trường đại học này thu hút rất nhiều nhân tài hàng đầu."},{"type":"compound","zh":"如果想进入顶尖公司，就要不断提高自己的能力。","pinyin":"Rúguǒ xiǎng jìnrù dǐngjiān gōngsī, jiùyào búduàn tígāo zìjǐ de nénglì.","vi":"Nếu muốn vào công ty hàng đầu thì phải không ngừng nâng cao năng lực của mình."}],"related":[{"hanzi":"顶级","pinyin":"dǐngjí","vi":"hàng đầu"},{"hanzi":"拔尖","pinyin":"bájiān","vi":"nổi trội"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"},{"hanzi":"杰出","pinyin":"jiéchū","vi":"kiệt xuất"}],"traditional":"頂尖"},{"id":"订单","hanzi":"订单","pinyin":"dìngdān","meaning_vi":"đơn đặt hàng","explanation":"订 (đính – đặt trước) + 单 (đơn – tờ đơn) → phiếu đặt mua hàng hóa, dịch vụ.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🧾","examples":[{"type":"basic","zh":"我已经下了订单。","pinyin":"Wǒ yǐjīng xiàle dìngdān.","vi":"Tôi đã đặt đơn hàng rồi."},{"type":"simple","zh":"工厂这个月接到了很多海外订单。","pinyin":"Gōngchǎng zhè geyuè jiēdàole hěn duō hǎiwài dìngdān.","vi":"Tháng này nhà máy nhận được rất nhiều đơn hàng nước ngoài."},{"type":"compound","zh":"如果三十分钟内不付款，订单就会自动取消。","pinyin":"Rúguǒ sānshí fēnzhōng nèi bú fùkuǎn, dìngdān jiù huì zìdòng qǔxiāo.","vi":"Nếu không thanh toán trong ba mươi phút thì đơn hàng sẽ tự động bị hủy."}],"related":[{"hanzi":"下单","pinyin":"xiàdān","vi":"đặt hàng"},{"hanzi":"预订","pinyin":"yùdìng","vi":"đặt trước"},{"hanzi":"发货","pinyin":"fāhuò","vi":"giao hàng"},{"hanzi":"退货","pinyin":"tuìhuò","vi":"trả hàng"}],"traditional":"訂單"},{"id":"定为","hanzi":"定为","pinyin":"dìngwéi","meaning_vi":"định là, xác định là, ấn định là","explanation":"定 (định – quyết định) + 为 (vi – làm, là) → quyết định coi là, xếp vào; thường dùng 被定为.","hsk_level":"7-9","tags":["dong-tu"],"image":"📌","examples":[{"type":"basic","zh":"会议时间定为下周三。","pinyin":"Huìyì shíjiān dìngwéi xià Zhōusān.","vi":"Thời gian họp ấn định vào thứ Tư tuần sau."},{"type":"simple","zh":"这座古城被定为世界文化遗产。","pinyin":"Zhè zuò gǔchéng bèi dìngwéi Shìjièwénhuàyíchǎn.","vi":"Cổ thành này được công nhận là di sản văn hóa thế giới."},{"type":"compound","zh":"因为这一天发生了重要事件，所以被定为国家纪念日。","pinyin":"Yīnwèi zhè yì tiān fāshēngle zhòngyào shìjiàn, suǒyǐ bèi dìngwéi guójiā jìniànrì.","vi":"Vì ngày này đã xảy ra sự kiện quan trọng nên được định là ngày kỷ niệm quốc gia."}],"related":[{"hanzi":"确定","pinyin":"quèdìng","vi":"xác định"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"列为","pinyin":"lièwéi","vi":"xếp vào"},{"hanzi":"视为","pinyin":"shìwéi","vi":"coi là"}],"traditional":"定為"},{"id":"定做","hanzi":"定做","pinyin":"dìngzuò","meaning_vi":"đặt làm, đặt may (theo yêu cầu)","explanation":"定 (định – đặt trước) + 做 (tố – làm) → đặt người khác làm theo kích thước, yêu cầu riêng.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🧵","examples":[{"type":"basic","zh":"我想定做一套西装。","pinyin":"Wǒ xiǎng dìngzuò yítào xīzhuāng.","vi":"Tôi muốn đặt may một bộ vest."},{"type":"simple","zh":"这些家具都是按房间尺寸定做的。","pinyin":"Zhèxiē jiājù dōu shì àn fángjiān chǐcùn dìngzuò de.","vi":"Những đồ nội thất này đều được đặt làm theo kích thước căn phòng."},{"type":"compound","zh":"虽然定做的衣服比较贵，但是穿起来特别合身。","pinyin":"Suīrán dìngzuò de yīfu bǐjiào guì, dànshì chuān qǐlái tèbié héshēn.","vi":"Tuy quần áo đặt may khá đắt nhưng mặc vào rất vừa vặn."}],"related":[{"hanzi":"定制","pinyin":"dìngzhì","vi":"đặt chế tác"},{"hanzi":"订做","pinyin":"dìngzuò","vi":"đặt làm"},{"hanzi":"量身","pinyin":"liángshēn","vi":"đo người"},{"hanzi":"现成","pinyin":"xiànchéng","vi":"làm sẵn"}]},{"id":"丢掉","hanzi":"丢掉","pinyin":"diūdiào","meaning_vi":"vứt bỏ, đánh mất, từ bỏ","explanation":"丢 (đâu – mất, vứt) + 掉 (điệu – mất đi) → vứt đi hoặc làm mất; nghĩa bóng: từ bỏ (丢掉幻想).","hsk_level":"7-9","tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"把这些垃圾丢掉吧。","pinyin":"Bǎ zhèxiē lājī diūdiào ba.","vi":"Vứt đống rác này đi nhé."},{"type":"simple","zh":"他因为一次失误丢掉了工作。","pinyin":"Tā yīnwèi yí cì shīwù diūdiàole gōngzuò.","vi":"Anh ấy mất việc chỉ vì một lần sơ suất."},{"type":"compound","zh":"如果想要成功，就得丢掉那些不切实际的幻想。","pinyin":"Rúguǒ xiǎngyào chénggōng, jiù děi diūdiào nàxiē bú qiè shíjì de huànxiǎng.","vi":"Nếu muốn thành công thì phải vứt bỏ những ảo tưởng viển vông đó."}],"related":[{"hanzi":"扔掉","pinyin":"rēngdiào","vi":"vứt đi"},{"hanzi":"丢失","pinyin":"diūshī","vi":"đánh mất"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"保留","pinyin":"bǎoliú","vi":"giữ lại"}],"traditional":"丟掉"},{"id":"懂事","hanzi":"懂事","pinyin":"dǒngshì","meaning_vi":"hiểu chuyện, biết điều","explanation":"懂 (đổng – hiểu) + 事 (sự – việc) → hiểu lẽ đời, biết cư xử; thường khen trẻ em ngoan, biết điều.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧒","examples":[{"type":"basic","zh":"这孩子真懂事。","pinyin":"Zhè háizi zhēn dǒngshì.","vi":"Đứa trẻ này thật hiểu chuyện."},{"type":"simple","zh":"她很懂事，从来不让父母操心。","pinyin":"Tā hěn dǒngshì, cóngláibú ràng fùmǔ cāoxīn.","vi":"Cô bé rất hiểu chuyện, chưa bao giờ để bố mẹ phải bận lòng."},{"type":"compound","zh":"虽然他才八岁，但是已经懂事得像个小大人。","pinyin":"Suīrán tā cái bā suì, dànshì yǐjīng dǒngshì de xiàng gè xiǎo dàrén.","vi":"Tuy mới tám tuổi nhưng cậu bé đã hiểu chuyện như một người lớn tí hon."}],"related":[{"hanzi":"乖","pinyin":"guāi","vi":"ngoan"},{"hanzi":"成熟","pinyin":"chéngshú","vi":"trưởng thành"},{"hanzi":"不懂事","pinyin":"bùdǒngshì","vi":"không hiểu chuyện"},{"hanzi":"任性","pinyin":"rènxìng","vi":"bướng bỉnh"}]},{"id":"动不动","hanzi":"动不动","pinyin":"dòngbudòng","meaning_vi":"hơi một tí là, hở ra là","explanation":"动 (động) + 不 + 动 → hễ động một chút; thường đi với 就, chỉ việc dễ xảy ra (thường là điều không hay).","hsk_level":"7-9","tags":["pho-tu"],"image":"😾","examples":[{"type":"basic","zh":"他动不动就发脾气。","pinyin":"Tā dòngbudòng jiù fāpíqi.","vi":"Anh ta hơi một tí là nổi nóng."},{"type":"simple","zh":"这孩子身体弱，动不动就感冒。","pinyin":"Zhè háizi shēn tǐruò, dòngbudòng jiù gǎnmào.","vi":"Đứa trẻ này yếu, hở ra là bị cảm."},{"type":"compound","zh":"如果你动不动就请假，老板就会对你有意见。","pinyin":"Rúguǒ nǐ dòngbudòng jiù qǐngjià, lǎobǎn jiù huì duì nǐ yǒu yìjiàn.","vi":"Nếu bạn hơi một tí là xin nghỉ thì ông chủ sẽ có ý kiến với bạn."}],"related":[{"hanzi":"经常","pinyin":"jīngcháng","vi":"thường xuyên"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"luôn luôn"},{"hanzi":"一…就","pinyin":"yī…jiù","vi":"hễ… là"},{"hanzi":"随时","pinyin":"suíshí","vi":"bất cứ lúc nào"}],"traditional":"動不動"},{"id":"动弹","hanzi":"动弹","pinyin":"dòngtan","meaning_vi":"nhúc nhích, cử động","explanation":"动 (động) + 弹 (đàn – bật, nảy) → cử động thân thể, nhúc nhích; thường dùng phủ định: 动弹不得.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"🫨","examples":[{"type":"basic","zh":"他累得不想动弹。","pinyin":"Tā lèi de bù xiǎng dòngtan.","vi":"Anh ấy mệt đến mức không muốn nhúc nhích."},{"type":"simple","zh":"车里太挤了，我一点儿都动弹不了。","pinyin":"Chē li tài jǐ le, wǒ yìdiǎnr dōu dòngtan bùliǎo.","vi":"Trong xe chật quá, tôi chẳng nhúc nhích được chút nào."},{"type":"compound","zh":"因为腿被压住了，所以他半天都动弹不得。","pinyin":"Yīnwèi tuǐ bèi yāzhù le, suǒyǐ tā bàn tiān dōu dòngtan bùdé.","vi":"Vì chân bị đè nên anh ấy mãi không cử động được."}],"related":[{"hanzi":"活动","pinyin":"huódòng","vi":"vận động"},{"hanzi":"移动","pinyin":"yídòng","vi":"di chuyển"},{"hanzi":"动不了","pinyin":"dòngbùliǎo","vi":"không động đậy được"},{"hanzi":"静止","pinyin":"jìngzhǐ","vi":"đứng yên"}],"traditional":"動彈"},{"id":"动工","hanzi":"动工","pinyin":"dònggōng","meaning_vi":"khởi công, động thổ","explanation":"动 (động – bắt đầu) + 工 (công – công trình) → bắt đầu thi công công trình.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"新医院下月动工。","pinyin":"Xīn yīyuàn xiàyuè dònggōng.","vi":"Bệnh viện mới sẽ khởi công tháng sau."},{"type":"simple","zh":"这条高速公路已经正式动工了。","pinyin":"Zhè tiáo gāosùgōnglù yǐjīng zhèngshì dònggōng le.","vi":"Tuyến đường cao tốc này đã chính thức khởi công."},{"type":"compound","zh":"虽然项目去年就批准了，但是一直到今年春天才动工。","pinyin":"Suīrán xiàngmù qùnián jiù pīzhǔn le, dànshì yì zhídào jīnnián chūn tiāncái dònggōng.","vi":"Tuy dự án được phê duyệt từ năm ngoái nhưng mãi đến mùa xuân năm nay mới khởi công."}],"related":[{"hanzi":"开工","pinyin":"kāigōng","vi":"khởi công"},{"hanzi":"施工","pinyin":"shīgōng","vi":"thi công"},{"hanzi":"竣工","pinyin":"jùngōng","vi":"hoàn công"},{"hanzi":"停工","pinyin":"tínggōng","vi":"ngừng thi công"}],"traditional":"動工"},{"id":"动听","hanzi":"动听","pinyin":"dòngtīng","meaning_vi":"êm tai, hay, dễ nghe","explanation":"动 (động – làm rung động) + 听 (thính – nghe) → làm người nghe xúc động, nghe hay; dùng cho giọng hát, lời nói.","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🎶","examples":[{"type":"basic","zh":"她的歌声很动听。","pinyin":"Tā de gēshēng hěn dòngtīng.","vi":"Giọng hát của cô ấy rất êm tai."},{"type":"simple","zh":"他讲了一个非常动听的故事。","pinyin":"Tā jiǎngle yí gè fēicháng dòngtīng de gùshi.","vi":"Anh ấy kể một câu chuyện rất hay."},{"type":"compound","zh":"虽然他的话说得很动听，但是我们还是要看他怎么做。","pinyin":"Suīrán tā de huàshuō de hěn dòngtīng, dànshì wǒmen háishi yào kàn tā zěnme zuò.","vi":"Tuy lời anh ta nói rất êm tai nhưng chúng ta vẫn phải xem anh ta làm thế nào."}],"related":[{"hanzi":"好听","pinyin":"hǎotīng","vi":"hay, dễ nghe"},{"hanzi":"悦耳","pinyin":"yuè'ěr","vi":"êm tai"},{"hanzi":"动人","pinyin":"dòngrén","vi":"cảm động"},{"hanzi":"刺耳","pinyin":"cì'ěr","vi":"chói tai"}],"traditional":"動聽"},{"id":"动用","hanzi":"动用","pinyin":"dòngyòng","meaning_vi":"huy động, sử dụng, đem ra dùng","explanation":"动 (động – chuyển động) + 用 (dụng – dùng) → đem nguồn lực ra sử dụng; thường đi với 资金、力量、关系.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"不要动用这笔钱。","pinyin":"Bú yào dòngyòng zhè bǐ qián.","vi":"Đừng động đến khoản tiền này."},{"type":"simple","zh":"政府动用了直升机搜救被困游客。","pinyin":"Zhèngfǔ dòngyòngle zhíshēngjī sōujiù bèi kùn yóukè.","vi":"Chính phủ đã huy động trực thăng tìm cứu du khách bị mắc kẹt."},{"type":"compound","zh":"即使家里再困难，父母也不愿动用给我上学的钱。","pinyin":"Jíshǐ jiālǐ zài kùnnan, fùmǔ yě búyuàn dòngyòng gěi wǒ shàngxué de qián.","vi":"Dù nhà khó khăn đến đâu, bố mẹ cũng không muốn động đến tiền cho tôi đi học."}],"related":[{"hanzi":"动员","pinyin":"dòngyuán","vi":"huy động"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"},{"hanzi":"调用","pinyin":"diàoyòng","vi":"điều động sử dụng"},{"hanzi":"挪用","pinyin":"nuóyòng","vi":"dùng sai mục đích"}],"traditional":"動用"},{"id":"栋","hanzi":"栋","pinyin":"dòng","meaning_vi":"tòa, căn (lượng từ cho nhà)","explanation":"栋 (đống – xà nóc nhà) → nghĩa gốc là cây xà nóc, nay dùng làm lượng từ cho nhà cửa, tòa nhà.","hsk_level":"7-9","tags":["luong-tu","nha-cua"],"image":"🏢","examples":[{"type":"basic","zh":"这栋楼很高。","pinyin":"Zhè dòng lóu hěn gāo.","vi":"Tòa nhà này rất cao."},{"type":"simple","zh":"我们公司在那栋白色大楼的十层。","pinyin":"Wǒmen gōngsī zài nà dòng báisè dàlóu de shí céng.","vi":"Công ty chúng tôi ở tầng mười của tòa nhà màu trắng kia."},{"type":"compound","zh":"虽然这栋房子很旧，但是住起来很舒服。","pinyin":"Suīrán zhè dòng fángzi hěn jiù, dànshì zhù qǐlái hěn shūfu.","vi":"Tuy căn nhà này rất cũ nhưng ở rất thoải mái."}],"related":[{"hanzi":"座","pinyin":"zuò","vi":"tòa (lượng từ)"},{"hanzi":"楼房","pinyin":"lóufáng","vi":"nhà lầu"},{"hanzi":"栋梁","pinyin":"dòngliáng","vi":"rường cột"},{"hanzi":"幢","pinyin":"zhuàng","vi":"tòa (lượng từ)"}],"traditional":"棟"},{"id":"都会","hanzi":"都会","pinyin":"dūhuì","meaning_vi":"đô thị, thành phố lớn","explanation":"都 (đô – kinh đô) + 会 (hội – nơi tụ họp) → nơi đông người tụ hội, tức thành phố lớn.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🌆","examples":[{"type":"basic","zh":"上海是国际大都会。","pinyin":"Shànghǎi shì Guójì dàdūhuì.","vi":"Thượng Hải là đô thị quốc tế."},{"type":"simple","zh":"很多年轻人梦想在繁华的都会里打拼。","pinyin":"Hěn duō niánqīngrén mèngxiǎng zài fánhuá de dūhuì lǐ dǎpīn.","vi":"Nhiều người trẻ mơ ước lập nghiệp ở các đô thị phồn hoa."},{"type":"compound","zh":"都会生活虽然方便，可是节奏太快，让人喘不过气。","pinyin":"Dūhuì shēnghuó suīrán fāngbiàn, kěshì jiézòu tài kuài, ràng rén chuǎnbuguò qì.","vi":"Cuộc sống đô thị tuy tiện lợi nhưng nhịp độ quá nhanh khiến người ta nghẹt thở."}],"related":[{"hanzi":"都市","pinyin":"dūshì","vi":"đô thị"},{"hanzi":"城市","pinyin":"chéngshì","vi":"thành phố"},{"hanzi":"大都市","pinyin":"dàdūshì","vi":"đại đô thị"},{"hanzi":"首都","pinyin":"shǒudū","vi":"thủ đô"}],"traditional":"都會"},{"id":"兜儿","hanzi":"兜儿","pinyin":"dōur","meaning_vi":"túi (áo, quần), cái túi","explanation":"兜 (đâu – cái túi) + 儿 (nhi – hậu tố âm cuốn lưỡi) → cách nói khẩu ngữ chỉ cái túi trên quần áo.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👖","examples":[{"type":"basic","zh":"钥匙在我兜儿里。","pinyin":"Yàoshi zài wǒ dōur lǐ.","vi":"Chìa khóa ở trong túi tôi."},{"type":"simple","zh":"他把手插在兜儿里，慢慢走回家。","pinyin":"Tā bǎshǒu chā zài dōur lǐ, màn mànzǒu huíjiā.","vi":"Anh ấy đút tay vào túi, chậm rãi đi về nhà."},{"type":"compound","zh":"因为兜儿里只剩十块钱，所以他只买了一碗面。","pinyin":"Yīnwèi dōur lǐ zhǐ shèng shí kuài qián, suǒyǐ tā zhǐ mǎile yì wǎn miàn.","vi":"Vì trong túi chỉ còn mười tệ nên anh ấy chỉ mua một bát mì."}],"related":[{"hanzi":"口袋","pinyin":"kǒudai","vi":"túi"},{"hanzi":"裤兜","pinyin":"kùdōu","vi":"túi quần"},{"hanzi":"网兜","pinyin":"wǎngdōu","vi":"túi lưới"},{"hanzi":"钱包","pinyin":"qiánbāo","vi":"ví tiền"}],"traditional":"兜兒"},{"id":"抖","hanzi":"抖","pinyin":"dǒu","meaning_vi":"run, rung, giũ","explanation":"抖 (đẩu – run, rũ) → cơ thể run lên hoặc rũ mạnh một vật cho rơi bụi; còn dùng trong 抖出 (khui ra).","hsk_level":"7-9","tags":["dong-tu"],"image":"🥶","examples":[{"type":"basic","zh":"他冷得直发抖。","pinyin":"Tā lěng dezhí fādǒu.","vi":"Anh ấy lạnh đến run cầm cập."},{"type":"simple","zh":"妈妈把床单抖了抖，挂到阳台上。","pinyin":"Māma bǎ chuángdān dǒule dǒu, guà dào yángtái shang.","vi":"Mẹ giũ giũ tấm ga trải giường rồi treo ra ban công."},{"type":"compound","zh":"她一上台就紧张，连拿话筒的手都在抖。","pinyin":"Tā yí shàngtái jiù jǐnzhāng, lián ná huàtǒng de shǒu dōu zài dǒu.","vi":"Cứ lên sân khấu là cô ấy căng thẳng, ngay cả tay cầm micro cũng run."}],"related":[{"hanzi":"发抖","pinyin":"fādǒu","vi":"run rẩy"},{"hanzi":"颤抖","pinyin":"chàndǒu","vi":"run lẩy bẩy"},{"hanzi":"抖动","pinyin":"dǒudòng","vi":"rung động"},{"hanzi":"哆嗦","pinyin":"duōsuo","vi":"run cầm cập"}]},{"id":"陡","hanzi":"陡","pinyin":"dǒu","meaning_vi":"dốc đứng, dựng đứng; đột ngột","explanation":"陡 (đẩu – dốc) → độ nghiêng rất lớn, gần như dựng đứng; nghĩa phụ là đột nhiên (陡然).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"这条山路很陡。","pinyin":"Zhè tiáo shānlù hěn dǒu.","vi":"Con đường núi này rất dốc."},{"type":"simple","zh":"楼梯太陡了，老人上下要扶着栏杆。","pinyin":"Lóutī tài dǒu le, lǎorén shàngxià yào fúzhe lángān.","vi":"Cầu thang quá dốc, người già lên xuống phải vịn lan can."},{"type":"compound","zh":"因为前面的坡又陡又滑，所以我们只好推着车走。","pinyin":"Yīnwèi qiánmiàn de pō yòu dǒu yòu huá, suǒyǐ wǒmen zhǐhǎo tuīzhe chē zǒu.","vi":"Vì con dốc phía trước vừa dốc vừa trơn nên chúng tôi đành dắt xe đi."}],"related":[{"hanzi":"陡峭","pinyin":"dǒuqiào","vi":"dốc đứng"},{"hanzi":"陡坡","pinyin":"dǒupō","vi":"dốc đứng"},{"hanzi":"陡然","pinyin":"dǒurán","vi":"đột nhiên"},{"hanzi":"平缓","pinyin":"pínghuǎn","vi":"thoai thoải"}]},{"id":"斗","hanzi":"斗","pinyin":"dòu","meaning_vi":"đấu, tranh đấu, chọi","explanation":"斗 (đấu – đánh nhau, tranh đấu) → hai bên đối đầu để phân thắng thua; dùng trong 斗争, 斗智, 斗鸡.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"我们斗不过他。","pinyin":"Wǒmen dòu buguò tā.","vi":"Chúng ta đấu không lại hắn."},{"type":"simple","zh":"两只公鸡在院子里斗了起来。","pinyin":"Liǎng zhī gōngjī zài yuànzi lǐ dòule qǐlái.","vi":"Hai con gà trống đánh nhau trong sân."},{"type":"compound","zh":"如果你非要跟他斗，就要做好输的准备。","pinyin":"Rúguǒ nǐ fēiyào gēn tā dòu, jiùyào zuò hǎo shū de zhǔnbèi.","vi":"Nếu cậu nhất định đấu với hắn thì phải chuẩn bị tinh thần thua."}],"related":[{"hanzi":"斗争","pinyin":"dòuzhēng","vi":"đấu tranh"},{"hanzi":"战斗","pinyin":"zhàndòu","vi":"chiến đấu"},{"hanzi":"奋斗","pinyin":"fèndòu","vi":"phấn đấu"},{"hanzi":"斗智","pinyin":"dòuzhì","vi":"đấu trí"}],"traditional":"鬥"},{"id":"豆浆","hanzi":"豆浆","pinyin":"dòujiāng","meaning_vi":"sữa đậu nành","explanation":"豆 (đậu – hạt đậu) + 浆 (tương – chất lỏng sệt) → nước xay từ đậu nành, đồ uống buổi sáng phổ biến.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🥛","examples":[{"type":"basic","zh":"早上喝杯豆浆。","pinyin":"Zǎoshang hē bēi dòujiāng.","vi":"Buổi sáng uống ly sữa đậu nành."},{"type":"simple","zh":"他每天早上都买一杯热豆浆和两根油条。","pinyin":"Tā měitiān zǎo Shangdōu mǎi yì bēi rè dòujiāng hé liǎng gēn yóutiáo.","vi":"Sáng nào anh ấy cũng mua một ly sữa đậu nành nóng và hai cái quẩy."},{"type":"compound","zh":"如果你喝不惯牛奶，就试试自己磨的豆浆吧。","pinyin":"Rúguǒ nǐ hē bu guàn niúnǎi, jiù shìshi zìjǐ mò de dòujiāng ba.","vi":"Nếu bạn uống sữa bò không quen thì thử sữa đậu nành tự xay xem."}],"related":[{"hanzi":"豆腐","pinyin":"dòufu","vi":"đậu phụ"},{"hanzi":"黄豆","pinyin":"huángdòu","vi":"đậu nành"},{"hanzi":"油条","pinyin":"yóutiáo","vi":"quẩy"},{"hanzi":"豆奶","pinyin":"dòunǎi","vi":"sữa đậu"}],"traditional":"豆漿"},{"id":"豆子","hanzi":"豆子","pinyin":"dòuzi","meaning_vi":"hạt đậu, đậu","explanation":"豆 (đậu – hạt đậu) + 子 (tử – hậu tố danh từ) → cách gọi chung các loại hạt đậu.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🫘","examples":[{"type":"basic","zh":"她在挑豆子。","pinyin":"Tā zài tiāo dòuzi.","vi":"Cô ấy đang nhặt đậu."},{"type":"simple","zh":"奶奶把晒干的豆子装进了布袋里。","pinyin":"Nǎinai bǎ shàigān de dòuzi zhuāng jìnle bùdài lǐ.","vi":"Bà cho số đậu đã phơi khô vào túi vải."},{"type":"compound","zh":"豆子虽然看起来不起眼，但是营养非常丰富。","pinyin":"Dòuzi suīrán kànqǐlái bùqǐyǎn, dànshì yíngyǎng fēicháng fēngfù.","vi":"Hạt đậu tuy trông không bắt mắt nhưng rất giàu dinh dưỡng."}],"related":[{"hanzi":"豆浆","pinyin":"dòujiāng","vi":"sữa đậu nành"},{"hanzi":"绿豆","pinyin":"lǜdòu","vi":"đậu xanh"},{"hanzi":"黄豆","pinyin":"huángdòu","vi":"đậu nành"},{"hanzi":"豆芽","pinyin":"dòuyá","vi":"giá đỗ"}]},{"id":"独","hanzi":"独","pinyin":"dú","meaning_vi":"một mình, đơn độc, duy nhất","explanation":"独 (độc – một mình) → chỉ có một, không có ai cùng; hay dùng trong 独自, 独特, 单独.","hsk_level":"7-9","tags":["pho-tu"],"image":"🧍","examples":[{"type":"basic","zh":"他独坐在窗前。","pinyin":"Tā dú zuò zài chuāng qián.","vi":"Anh ấy ngồi một mình trước cửa sổ."},{"type":"simple","zh":"这家店独有一种用桂花做的点心。","pinyin":"Zhè jiā diàn dúyǒu yì zhǒng yòng guìhuā zuò de diǎnxin.","vi":"Quán này độc quyền có một loại bánh làm bằng hoa quế."},{"type":"compound","zh":"虽然大家都同意了，唯独他还坚持反对。","pinyin":"Suīrán dàjiā dōu tóngyì le, wéidú tā hái jiānchí fǎnduì.","vi":"Tuy mọi người đều đồng ý, riêng anh ấy vẫn kiên quyết phản đối."}],"related":[{"hanzi":"独自","pinyin":"dúzì","vi":"một mình"},{"hanzi":"单独","pinyin":"dāndú","vi":"riêng lẻ"},{"hanzi":"独特","pinyin":"dútè","vi":"độc đáo"},{"hanzi":"孤独","pinyin":"gūdú","vi":"cô độc"}],"traditional":"獨"},{"id":"独唱","hanzi":"独唱","pinyin":"dúchàng","meaning_vi":"đơn ca, hát đơn","explanation":"独 (độc – một mình) + 唱 (xướng – hát) → một người hát riêng, đối lập với 合唱.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎤","examples":[{"type":"basic","zh":"她要独唱一首歌。","pinyin":"Tā yào dúchàng yìshǒugē.","vi":"Cô ấy sẽ đơn ca một bài."},{"type":"simple","zh":"晚会上他的独唱赢得了热烈的掌声。","pinyin":"Wǎnhuì shang tā de dúchàng yíng déle rèliè de zhǎngshēng.","vi":"Tiết mục đơn ca của anh ấy ở buổi dạ hội nhận được tràng vỗ tay nhiệt liệt."},{"type":"compound","zh":"虽然她只练了一个月，但是这次独唱表现得非常出色。","pinyin":"Suīrán tā zhǐ liànle yí geyuè, dànshì zhè cì dúchàng biǎoxiàn de fēicháng chūsè.","vi":"Tuy cô ấy chỉ luyện một tháng nhưng lần đơn ca này thể hiện rất xuất sắc."}],"related":[{"hanzi":"合唱","pinyin":"héchàng","vi":"hợp xướng"},{"hanzi":"独奏","pinyin":"dúzòu","vi":"độc tấu"},{"hanzi":"歌手","pinyin":"gēshǒu","vi":"ca sĩ"},{"hanzi":"演唱","pinyin":"yǎnchàng","vi":"biểu diễn hát"}],"traditional":"獨唱"},{"id":"独家","hanzi":"独家","pinyin":"dújiā","meaning_vi":"độc quyền, riêng một nhà","explanation":"独 (độc – duy nhất) + 家 (gia – nhà, đơn vị) → chỉ một đơn vị có được; hay dùng trong 独家新闻, 独家代理.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📰","examples":[{"type":"basic","zh":"这是独家新闻。","pinyin":"Zhè shì dújiā xīnwén.","vi":"Đây là tin độc quyền."},{"type":"simple","zh":"这家电视台获得了比赛的独家转播权。","pinyin":"Zhè jiā diànshìtái huò déle bǐsài de dújiā zhuǎnbō quán.","vi":"Đài truyền hình này giành được quyền phát sóng độc quyền trận đấu."},{"type":"compound","zh":"因为这道菜用的是独家秘方，所以别的店做不出这个味道。","pinyin":"Yīnwèi zhè dào cài yòng de shì dújiā mìfāng, suǒyǐ biéde diàn zuò bu chū zhè ge wèidao.","vi":"Vì món này dùng công thức bí truyền độc quyền nên quán khác không làm ra được vị này."}],"related":[{"hanzi":"独有","pinyin":"dúyǒu","vi":"riêng có"},{"hanzi":"独占","pinyin":"dúzhàn","vi":"độc chiếm"},{"hanzi":"垄断","pinyin":"lǒngduàn","vi":"độc quyền, lũng đoạn"},{"hanzi":"专利","pinyin":"zhuānlì","vi":"bằng sáng chế"}],"traditional":"獨家"},{"id":"独身","hanzi":"独身","pinyin":"dúshēn","meaning_vi":"độc thân, sống một mình","explanation":"独 (độc – một mình) + 身 (thân – bản thân) → một thân một mình, chưa hoặc không kết hôn.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🧑","examples":[{"type":"basic","zh":"他至今仍独身。","pinyin":"Tā zhìjīn réng dúshēn.","vi":"Đến nay anh ấy vẫn độc thân."},{"type":"simple","zh":"她选择独身，把精力都放在了事业上。","pinyin":"Tā xuǎnzé dúshēn, bǎ jīnglì dōu fàng zài le shìyè shang.","vi":"Cô ấy chọn sống độc thân, dồn hết sức lực vào sự nghiệp."},{"type":"compound","zh":"即使家人一再催婚，他也坚持过独身生活。","pinyin":"Jíshǐ jiārén yízài cuīhūn, tā yě jiānchíguò dúshēn shēnghuó.","vi":"Dù gia đình liên tục giục cưới, anh ấy vẫn kiên trì sống độc thân."}],"related":[{"hanzi":"单身","pinyin":"dānshēn","vi":"độc thân"},{"hanzi":"未婚","pinyin":"wèihūn","vi":"chưa kết hôn"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"kết hôn"},{"hanzi":"光棍","pinyin":"guānggùn","vi":"trai ế"}],"traditional":"獨身"},{"id":"妒忌","hanzi":"妒忌","pinyin":"dùjì","meaning_vi":"đố kỵ, ghen tị","explanation":"妒 (đố – ghen ghét) + 忌 (kỵ – ghen, kiêng) → ghen tức khi người khác hơn mình.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"别妒忌别人。","pinyin":"Bié dùjì biérén.","vi":"Đừng ghen tị với người khác."},{"type":"simple","zh":"她很妒忌同事升职比自己快。","pinyin":"Tā hěn dùjì tóngshì shēngzhí bǐ zìjǐ kuài.","vi":"Cô ấy rất ghen tị vì đồng nghiệp thăng chức nhanh hơn mình."},{"type":"compound","zh":"与其妒忌别人的成功，不如想想自己该怎么努力。","pinyin":"Yǔqí dùjì biérén de chénggōng, bùrú xiǎng xiang zìjǐ gāi zěnme nǔlì.","vi":"Thay vì đố kỵ thành công của người khác, chi bằng nghĩ xem mình nên cố gắng thế nào."}],"related":[{"hanzi":"嫉妒","pinyin":"jídù","vi":"ghen tị"},{"hanzi":"羡慕","pinyin":"xiànmù","vi":"ngưỡng mộ"},{"hanzi":"眼红","pinyin":"yǎnhóng","vi":"thèm muốn, ganh"},{"hanzi":"吃醋","pinyin":"chīcù","vi":"ghen (tình cảm)"}]},{"id":"度假","hanzi":"度假","pinyin":"dùjià","meaning_vi":"đi nghỉ mát, nghỉ dưỡng","explanation":"度 (độ – trải qua) + 假 (giả – kỳ nghỉ) → trải qua kỳ nghỉ, đi nghỉ mát.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🏖️","examples":[{"type":"basic","zh":"我们去海边度假。","pinyin":"Wǒmen qù hǎibiān dùjià.","vi":"Chúng tôi đi biển nghỉ mát."},{"type":"simple","zh":"他们一家每年夏天都去山里度假。","pinyin":"Tāmen yìjiā měinián xiàtiān dōu qù shān lǐ dùjià.","vi":"Năm nào mùa hè cả nhà họ cũng lên núi nghỉ dưỡng."},{"type":"compound","zh":"要是公司批了年假，我就带父母去三亚度假。","pinyin":"Yàoshi gōngsī pīle niánjià, wǒ jiù dài fùmǔ qù Sānyà dùjià.","vi":"Nếu công ty duyệt phép năm, tôi sẽ đưa bố mẹ đi Tam Á nghỉ dưỡng."}],"related":[{"hanzi":"休假","pinyin":"xiūjià","vi":"nghỉ phép"},{"hanzi":"假期","pinyin":"jiàqī","vi":"kỳ nghỉ"},{"hanzi":"度假村","pinyin":"dùjiàcūn","vi":"khu nghỉ dưỡng"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"du lịch"}]},{"id":"渡过","hanzi":"渡过","pinyin":"dùguò","meaning_vi":"vượt qua (sông, khó khăn)","explanation":"渡 (độ – qua sông) + 过 (quá – qua) → vượt qua mặt nước; nghĩa bóng là vượt qua giai đoạn khó khăn (渡过难关).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚣","examples":[{"type":"basic","zh":"我们渡过了难关。","pinyin":"Wǒmen dùguòle nánguān.","vi":"Chúng tôi đã vượt qua cửa ải khó khăn."},{"type":"simple","zh":"士兵们乘小船连夜渡过了那条大河。","pinyin":"Shìbīngmen chéng xiǎochuán liányè dùguòle nà tiáo dàhé.","vi":"Binh lính đi thuyền nhỏ vượt qua con sông lớn ngay trong đêm."},{"type":"compound","zh":"只要大家团结一心，就一定能渡过这次危机。","pinyin":"Zhǐyào dàjiā tuánjié yìxīn, jiù yídìng néng dùguò zhè cì wēijī.","vi":"Chỉ cần mọi người đồng lòng thì nhất định sẽ vượt qua được cuộc khủng hoảng này."}],"related":[{"hanzi":"度过","pinyin":"dùguò","vi":"trải qua (thời gian)"},{"hanzi":"渡河","pinyin":"dùhé","vi":"qua sông"},{"hanzi":"难关","pinyin":"nánguān","vi":"cửa ải khó"},{"hanzi":"克服","pinyin":"kèfú","vi":"khắc phục"}],"traditional":"渡過"},{"id":"段落","hanzi":"段落","pinyin":"duànluò","meaning_vi":"đoạn văn, giai đoạn","explanation":"段 (đoạn – khúc) + 落 (lạc – chỗ dừng) → một đoạn có điểm dừng, chỉ đoạn văn hoặc một giai đoạn công việc.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"请读第二个段落。","pinyin":"Qǐng dú dì'èr ge duànluò.","vi":"Mời đọc đoạn văn thứ hai."},{"type":"simple","zh":"这篇文章的段落划分得很清楚。","pinyin":"Zhè piān wénzhāng de duànluò huàfēn de hěn qīngchu.","vi":"Các đoạn của bài viết này được chia rất rõ ràng."},{"type":"compound","zh":"等工作告一段落以后，我就请假回老家看看。","pinyin":"Děng gōngzuò gào yí duànluò yǐhòu, wǒ jiù qǐngjià huílǎojiā kànkan.","vi":"Đợi công việc tạm xong một giai đoạn, tôi sẽ xin nghỉ về quê thăm."}],"related":[{"hanzi":"段","pinyin":"duàn","vi":"đoạn"},{"hanzi":"章节","pinyin":"zhāngjié","vi":"chương mục"},{"hanzi":"句子","pinyin":"jùzi","vi":"câu"},{"hanzi":"告一段落","pinyin":"gàoyíduànluò","vi":"tạm xong một giai đoạn"}]},{"id":"断断续续","hanzi":"断断续续","pinyin":"duànduànxùxù","meaning_vi":"đứt quãng, lúc có lúc không","explanation":"断 (đoạn – đứt) + 续 (tục – nối), lặp lại → lúc đứt lúc nối, chỉ việc diễn ra không liên tục.","hsk_level":"7-9","tags":["tinh-tu"],"image":"〰️","examples":[{"type":"basic","zh":"雨断断续续地下着。","pinyin":"Yǔ duànduànxùxù dexià zhe.","vi":"Mưa rơi lúc có lúc không."},{"type":"simple","zh":"信号不好，他的声音断断续续的。","pinyin":"Xìnhào bù hǎo, tā de shēngyīn duànduànxùxù de.","vi":"Tín hiệu kém, giọng anh ấy cứ đứt quãng."},{"type":"compound","zh":"虽然他断断续续学了五年汉语，但是口语还不太流利。","pinyin":"Suīrán tā duànduànxùxù xuéle wǔ nián Hànyǔ, dànshì kǒuyǔ hái bú tài liúlì.","vi":"Tuy anh ấy học tiếng Trung chập chờn suốt năm năm nhưng khẩu ngữ vẫn chưa lưu loát lắm."}],"related":[{"hanzi":"时断时续","pinyin":"shíduànshíxù","vi":"lúc đứt lúc nối"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"持续","pinyin":"chíxù","vi":"kéo dài"},{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"}],"traditional":"斷斷續續"},{"id":"堆砌","hanzi":"堆砌","pinyin":"duīqì","meaning_vi":"xếp chồng, xây; (văn) chất đống từ ngữ hoa mỹ","explanation":"堆 (đôi – chồng đống) + 砌 (thế – xây gạch) → xếp chồng gạch đá; nghĩa bóng chỉ viết văn chất đống từ ngữ hoa mỹ vô ích.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"文章不要堆砌辞藻。","pinyin":"Wénzhāng bú yào duīqì cízǎo.","vi":"Viết văn đừng chất đống từ ngữ hoa mỹ."},{"type":"simple","zh":"工人用石块堆砌了一道矮墙。","pinyin":"Gōngrén yòng shíkuài duīqìle yídào ǎi qiáng.","vi":"Công nhân dùng đá xếp thành một bức tường thấp."},{"type":"compound","zh":"如果只是堆砌华丽的形容词，文章就会显得空洞。","pinyin":"Rúguǒ zhǐshì duīqì huálì de xíngróngcí, wénzhāng jiù huì xiǎnde kōngdòng.","vi":"Nếu chỉ chất đống tính từ hoa mỹ thì bài văn sẽ trở nên rỗng tuếch."}],"related":[{"hanzi":"堆积","pinyin":"duījī","vi":"chồng chất"},{"hanzi":"砌墙","pinyin":"qìqiáng","vi":"xây tường"},{"hanzi":"辞藻","pinyin":"cízǎo","vi":"từ ngữ hoa mỹ"},{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"ngắn gọn"}]},{"id":"对得起","hanzi":"对得起","pinyin":"duìdeqǐ","meaning_vi":"xứng đáng với, không phụ lòng","explanation":"对 (đối – đối với) + 得起 (đắc khởi – kham nổi) → đối xử xứng đáng, không làm ai thất vọng; phủ định là 对不起.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"我对得起良心。","pinyin":"Wǒ duìdeqǐ liángxīn.","vi":"Tôi không thẹn với lương tâm."},{"type":"simple","zh":"他拼命工作，就是想对得起父母的付出。","pinyin":"Tā pīnmìng gōngzuò, jiùshì xiǎng duìdeqǐ fùmǔ de fùchū.","vi":"Anh ấy làm việc quần quật chỉ mong không phụ công sức bố mẹ."},{"type":"compound","zh":"既然拿了这份工资，就要对得起这份工作。","pinyin":"Jìrán nále zhè fèn gōngzī, jiùyào duìdeqǐ zhè fèn gōngzuò.","vi":"Đã nhận đồng lương này thì phải làm cho xứng đáng với công việc."}],"related":[{"hanzi":"对不起","pinyin":"duìbuqǐ","vi":"xin lỗi, có lỗi với"},{"hanzi":"辜负","pinyin":"gūfù","vi":"phụ lòng"},{"hanzi":"无愧","pinyin":"wúkuì","vi":"không hổ thẹn"},{"hanzi":"看得起","pinyin":"kàndeqǐ","vi":"coi trọng"}],"traditional":"對得起"},{"id":"对弈","hanzi":"对弈","pinyin":"duìyì","meaning_vi":"đánh cờ, đấu cờ","explanation":"对 (đối – đối mặt) + 弈 (dịch – chơi cờ) → hai người ngồi đối diện đánh cờ.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"♟️","examples":[{"type":"basic","zh":"两位老人在对弈。","pinyin":"Liǎng wèi lǎorén zài duìyì.","vi":"Hai ông cụ đang đánh cờ."},{"type":"simple","zh":"他曾与世界冠军在网上对弈过一局。","pinyin":"Tā céng yǔ shìjiè guànjūn zài wǎngshàng duìyìguo yì jú.","vi":"Anh ấy từng đánh một ván cờ trên mạng với nhà vô địch thế giới."},{"type":"compound","zh":"虽然两人对弈了整整三个小时，但是最后还是和棋。","pinyin":"Suīrán liǎng rén duìyìle zhěngzhěng sān ge xiǎoshí, dànshì zuìhòu háishi héqí.","vi":"Tuy hai người đấu cờ suốt ba tiếng nhưng cuối cùng vẫn hòa."}],"related":[{"hanzi":"下棋","pinyin":"xiàqí","vi":"đánh cờ"},{"hanzi":"围棋","pinyin":"wéiqí","vi":"cờ vây"},{"hanzi":"象棋","pinyin":"xiàngqí","vi":"cờ tướng"},{"hanzi":"棋手","pinyin":"qíshǒu","vi":"kỳ thủ"}],"traditional":"對弈"},{"id":"对准","hanzi":"对准","pinyin":"duìzhǔn","meaning_vi":"nhắm vào, chĩa vào, căn chỉnh","explanation":"对 (đối – hướng về) + 准 (chuẩn – chính xác) → hướng cho thật chính xác vào một mục tiêu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"镜头对准了他。","pinyin":"Jìngtóu duìzhǔnle tā.","vi":"Ống kính chĩa vào anh ấy."},{"type":"simple","zh":"他把箭对准靶心，屏住呼吸射了出去。","pinyin":"Tā bǎ jiàn duìzhǔn bǎxīn, bǐng zhù hūxī shèle chūqù.","vi":"Anh ấy nhắm mũi tên vào hồng tâm, nín thở bắn đi."},{"type":"compound","zh":"只有对准市场需求，产品才能卖得好。","pinyin":"Zhǐyǒu duìzhǔn shìchǎng xūqiú, chǎnpǐn cáinéng mài de hǎo.","vi":"Chỉ khi nhắm đúng nhu cầu thị trường thì sản phẩm mới bán chạy."}],"related":[{"hanzi":"瞄准","pinyin":"miáozhǔn","vi":"ngắm bắn"},{"hanzi":"对着","pinyin":"duìzhe","vi":"hướng về"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"chính xác"}],"traditional":"對準"},{"id":"炖","hanzi":"炖","pinyin":"dùn","meaning_vi":"hầm, ninh","explanation":"炖 (đốn – hầm) → nấu nhỏ lửa thật lâu cho thức ăn nhừ và ra nước ngọt, như 炖汤, 炖肉.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"妈妈在炖鸡汤。","pinyin":"Māma zài dùn jītāng.","vi":"Mẹ đang hầm canh gà."},{"type":"simple","zh":"牛肉要用小火炖两个小时才会烂。","pinyin":"Niúròu yào yòng xiǎo huǒ dùn liǎng ge xiǎoshí cái huì làn.","vi":"Thịt bò phải hầm lửa nhỏ hai tiếng mới nhừ."},{"type":"compound","zh":"一旦天气转凉，奶奶就会炖一锅排骨汤给我们暖身子。","pinyin":"Yídàn tiānqì zhuǎn liáng, nǎinai jiù huì dùn yì guō páigǔ tāng gěi wǒmen nuǎn shēnzi.","vi":"Hễ trời trở lạnh, bà lại hầm một nồi canh sườn cho chúng tôi ấm người."}],"related":[{"hanzi":"煮","pinyin":"zhǔ","vi":"nấu, luộc"},{"hanzi":"炒","pinyin":"chǎo","vi":"xào"},{"hanzi":"蒸","pinyin":"zhēng","vi":"hấp"},{"hanzi":"清炖","pinyin":"qīngdùn","vi":"hầm trong"}],"traditional":"燉"},{"id":"多功能","hanzi":"多功能","pinyin":"duōgōngnéng","meaning_vi":"đa năng, nhiều chức năng","explanation":"多 (đa – nhiều) + 功能 (công năng – chức năng) → có nhiều chức năng; thường đứng trước danh từ.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🧰","examples":[{"type":"basic","zh":"这是多功能厅。","pinyin":"Zhè shì duōgōngnéng tīng.","vi":"Đây là hội trường đa năng."},{"type":"simple","zh":"我买了一台多功能料理机，能榨汁也能磨粉。","pinyin":"Wǒ mǎile yì tái duōgōngnéng liàolǐ jī, néng zhàzhī yě néng mò fěn.","vi":"Tôi mua một máy xay đa năng, vừa ép nước vừa xay bột được."},{"type":"compound","zh":"这款多功能手表虽然不贵，但是能测心率和睡眠。","pinyin":"Zhè kuǎn duōgōngnéng shǒubiǎo suīrán bú guì, dànshì néng cè xīnlǜ hé shuìmián.","vi":"Chiếc đồng hồ đa năng này tuy không đắt nhưng đo được nhịp tim và giấc ngủ."}],"related":[{"hanzi":"功能","pinyin":"gōngnéng","vi":"chức năng"},{"hanzi":"多用途","pinyin":"duōyòngtú","vi":"đa dụng"},{"hanzi":"实用","pinyin":"shíyòng","vi":"thiết thực"},{"hanzi":"单一","pinyin":"dānyī","vi":"đơn nhất"}]},{"id":"多劳多得","hanzi":"多劳多得","pinyin":"duōláo-duōdé","meaning_vi":"làm nhiều hưởng nhiều","explanation":"多 (đa – nhiều) + 劳 (lao – lao động) + 多 + 得 (đắc – được) → làm nhiều thì được nhiều; nguyên tắc phân phối theo lao động.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"我们公司多劳多得。","pinyin":"Wǒmen gōngsī duōláoduōdé.","vi":"Công ty chúng tôi làm nhiều hưởng nhiều."},{"type":"simple","zh":"计件工资体现了多劳多得的原则。","pinyin":"Jìjiàn gōngzī tǐxiànle duōláoduōdé de yuánzé.","vi":"Lương khoán sản phẩm thể hiện nguyên tắc làm nhiều hưởng nhiều."},{"type":"compound","zh":"既然是多劳多得，那么想多赚钱就得多干活。","pinyin":"Jìrán shì duōláoduōdé, nàme xiǎng duō zhuànqián jiù děi duō gànhuó.","vi":"Đã là làm nhiều hưởng nhiều thì muốn kiếm nhiều tiền phải làm nhiều việc."}],"related":[{"hanzi":"按劳分配","pinyin":"ànláofēnpèi","vi":"phân phối theo lao động"},{"hanzi":"劳动","pinyin":"láodòng","vi":"lao động"},{"hanzi":"报酬","pinyin":"bàochou","vi":"thù lao"},{"hanzi":"不劳而获","pinyin":"bùláo'érhuò","vi":"không làm mà hưởng"}],"traditional":"多勞多得"},{"id":"多年来","hanzi":"多年来","pinyin":"duōniánlái","meaning_vi":"nhiều năm qua, bao năm nay","explanation":"多年 (đa niên – nhiều năm) + 来 (lai – đến nay) → suốt nhiều năm cho tới bây giờ; thường đứng đầu câu.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"多年来他一直很忙。","pinyin":"Duōniánlái tā yìzhí hěn máng.","vi":"Nhiều năm qua anh ấy luôn bận."},{"type":"simple","zh":"多年来，她坚持每周去养老院做义工。","pinyin":"Duōniánlái, tā jiānchí měizhōu qù yǎnglǎoyuàn zuò yìgōng.","vi":"Nhiều năm nay cô ấy kiên trì mỗi tuần đến viện dưỡng lão làm tình nguyện."},{"type":"compound","zh":"虽然多年来他们很少见面，但是友谊一点儿也没变。","pinyin":"Suīrán duōniánlái tāmen hěn shǎojiàn miàn, dànshì yǒuyì yìdiǎnr yě méi biàn.","vi":"Tuy nhiều năm qua họ ít gặp nhau nhưng tình bạn chẳng hề thay đổi."}],"related":[{"hanzi":"多年","pinyin":"duōnián","vi":"nhiều năm"},{"hanzi":"近年来","pinyin":"jìnniánlái","vi":"mấy năm gần đây"},{"hanzi":"一直","pinyin":"yìzhí","vi":"luôn luôn"},{"hanzi":"长期","pinyin":"chángqī","vi":"lâu dài"}],"traditional":"多年來"},{"id":"多心","hanzi":"多心","pinyin":"duōxīn","meaning_vi":"đa nghi, nghĩ nhiều, để bụng","explanation":"多 (đa – nhiều) + 心 (tâm – lòng) → lòng nghĩ quá nhiều, hay nghi ngờ hoặc để bụng lời người khác.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🤔","examples":[{"type":"basic","zh":"你别多心。","pinyin":"Nǐ bié duōxīn.","vi":"Bạn đừng nghĩ nhiều."},{"type":"simple","zh":"我只是随口一说，你千万别多心。","pinyin":"Wǒ zhǐshì suíkǒu yìshuō, nǐ qiānwàn bié duōxīn.","vi":"Tôi chỉ buột miệng nói thôi, bạn tuyệt đối đừng để bụng."},{"type":"compound","zh":"因为她这个人很多心，所以说话的时候要注意分寸。","pinyin":"Yīnwèi tā zhè ge rén hěn duōxīn, suǒyǐ shuōhuà de shíhou yào zhùyì fēncùn.","vi":"Vì cô ấy là người hay suy diễn nên khi nói chuyện phải chú ý chừng mực."}],"related":[{"hanzi":"多疑","pinyin":"duōyí","vi":"đa nghi"},{"hanzi":"敏感","pinyin":"mǐngǎn","vi":"nhạy cảm"},{"hanzi":"疑心","pinyin":"yíxīn","vi":"nghi ngờ"},{"hanzi":"小心眼儿","pinyin":"xiǎoxīnyǎnr","vi":"hẹp hòi"}]},{"id":"多元","hanzi":"多元","pinyin":"duōyuán","meaning_vi":"đa nguyên, đa dạng","explanation":"多 (đa – nhiều) + 元 (nguyên – yếu tố gốc) → gồm nhiều yếu tố, nhiều thành phần; hay dùng trong 多元文化, 多元化.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🌈","examples":[{"type":"basic","zh":"这是多元的社会。","pinyin":"Zhè shì duōyuán de shèhuì.","vi":"Đây là một xã hội đa nguyên."},{"type":"simple","zh":"这座城市有着多元的饮食文化。","pinyin":"Zhè zuò chéngshì yǒuzhe duōyuán de yǐnshí wénhuà.","vi":"Thành phố này có văn hóa ẩm thực đa dạng."},{"type":"compound","zh":"正因为文化多元，所以这里每年都吸引大量游客。","pinyin":"Zhèng yīnwèi wénhuà duōyuán, suǒyǐ zhèlǐ měinián dōu xīyǐn dàliàng yóukè.","vi":"Chính vì văn hóa đa dạng nên nơi đây mỗi năm thu hút rất nhiều du khách."}],"related":[{"hanzi":"多元化","pinyin":"duōyuánhuà","vi":"đa dạng hóa"},{"hanzi":"多样","pinyin":"duōyàng","vi":"đa dạng"},{"hanzi":"单一","pinyin":"dānyī","vi":"đơn nhất"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"}]},{"id":"夺魁","hanzi":"夺魁","pinyin":"duókuí","meaning_vi":"đoạt giải nhất, giành ngôi đầu","explanation":"夺 (đoạt – giành lấy) + 魁 (khôi – đứng đầu) → giành vị trí đứng đầu trong cuộc thi.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"中国队再次夺魁。","pinyin":"Zhōngguó duì zàicì duókuí.","vi":"Đội Trung Quốc lại giành ngôi vô địch."},{"type":"simple","zh":"她在全国钢琴比赛中一举夺魁。","pinyin":"Tā zài quánguó gāngqín bǐsài zhōng yìjǔ duókuí.","vi":"Cô ấy đã giành ngay giải nhất cuộc thi piano toàn quốc."},{"type":"compound","zh":"尽管对手实力很强，他们还是凭借默契配合夺魁。","pinyin":"Jǐnguǎn duìshǒu shílì hěn qiáng, tāmen háishi píngjiè mòqì pèihé duókuí.","vi":"Dù đối thủ rất mạnh, họ vẫn giành ngôi đầu nhờ phối hợp ăn ý."}],"related":[{"hanzi":"夺冠","pinyin":"duóguàn","vi":"đoạt chức vô địch"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"quán quân"},{"hanzi":"夺得","pinyin":"duódé","vi":"giành được"},{"hanzi":"魁首","pinyin":"kuíshǒu","vi":"người đứng đầu"}],"traditional":"奪魁"},{"id":"舵手","hanzi":"舵手","pinyin":"duòshǒu","meaning_vi":"người lái thuyền, người cầm lái","explanation":"舵 (đà – bánh lái) + 手 (thủ – người làm) → người cầm bánh lái thuyền; nghĩa bóng là người lãnh đạo, định hướng.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🚢","examples":[{"type":"basic","zh":"舵手掌握方向。","pinyin":"Duòshǒu zhǎngwò fāngxiàng.","vi":"Người cầm lái nắm phương hướng."},{"type":"simple","zh":"老舵手在风浪中稳稳地把船开进了港口。","pinyin":"Lǎo duòshǒu zài fēnglàng zhōng wěnwěn de bǎ chuán kāi jìnle gǎngkǒu.","vi":"Người lái thuyền lão luyện vững vàng đưa thuyền vào cảng giữa sóng gió."},{"type":"compound","zh":"一个团队如果没有好的舵手，就很容易迷失方向。","pinyin":"Yí ge tuánduì rúguǒ méiyǒu hǎo de duòshǒu, jiù hěn róngyì míshī fāngxiàng.","vi":"Một tập thể nếu không có người cầm lái giỏi thì rất dễ lạc hướng."}],"related":[{"hanzi":"船长","pinyin":"chuánzhǎng","vi":"thuyền trưởng"},{"hanzi":"水手","pinyin":"shuǐshǒu","vi":"thủy thủ"},{"hanzi":"掌舵","pinyin":"zhǎngduò","vi":"cầm lái"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"}]},{"id":"俄语","hanzi":"俄语","pinyin":"Éyǔ","meaning_vi":"tiếng Nga","explanation":"俄 (Nga – nước Nga) + 语 (ngữ – ngôn ngữ) → tiếng Nga.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🪆","examples":[{"type":"basic","zh":"他会说俄语。","pinyin":"Tā huì shuō Éyǔ.","vi":"Anh ấy biết nói tiếng Nga."},{"type":"simple","zh":"她在莫斯科留学时学会了流利的俄语。","pinyin":"Tā zài Mòsīkē liúxué shí xuéhuìle liúlì de Éyǔ.","vi":"Cô ấy học được tiếng Nga lưu loát khi du học ở Moskva."},{"type":"compound","zh":"俄语的语法虽然很复杂，但是发音很好听。","pinyin":"Éyǔ de yǔfǎ suīrán hěn fùzá, dànshì fāyīn hěn hǎotīng.","vi":"Ngữ pháp tiếng Nga tuy phức tạp nhưng phát âm rất hay."}],"related":[{"hanzi":"俄罗斯","pinyin":"Éluósī","vi":"nước Nga"},{"hanzi":"英语","pinyin":"Yīngyǔ","vi":"tiếng Anh"},{"hanzi":"外语","pinyin":"wàiyǔ","vi":"ngoại ngữ"},{"hanzi":"俄文","pinyin":"Éwén","vi":"chữ Nga"}],"traditional":"俄語"},{"id":"鹅","hanzi":"鹅","pinyin":"é","meaning_vi":"con ngỗng","explanation":"鹅 (nga – con ngỗng) → loài gia cầm cổ dài, lớn hơn vịt.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🪿","examples":[{"type":"basic","zh":"河里有几只鹅。","pinyin":"Hé lǐ yǒu jǐ zhī é.","vi":"Dưới sông có mấy con ngỗng."},{"type":"simple","zh":"农场里的大白鹅一见生人就伸长脖子叫。","pinyin":"Nóngchǎng lǐ de dàbái é yí jiàn shēngrén jiù shēncháng bózi jiào.","vi":"Đàn ngỗng trắng ở nông trại cứ thấy người lạ là vươn cổ kêu."},{"type":"compound","zh":"虽然鹅看起来很温顺，但是被惹急了也会啄人。","pinyin":"Suīrán é kànqǐlái hěn wēnshùn, dànshì bèi rě jíle yě huì zhuó rén.","vi":"Tuy ngỗng trông hiền lành nhưng bị chọc giận cũng sẽ mổ người."}],"related":[{"hanzi":"天鹅","pinyin":"tiān'é","vi":"thiên nga"},{"hanzi":"鸭子","pinyin":"yāzi","vi":"con vịt"},{"hanzi":"企鹅","pinyin":"qǐ'é","vi":"chim cánh cụt"},{"hanzi":"鹅毛","pinyin":"émáo","vi":"lông ngỗng"}],"traditional":"鵝"},{"id":"厄运","hanzi":"厄运","pinyin":"èyùn","meaning_vi":"vận rủi, vận hạn","explanation":"厄 (ách – khốn khó) + 运 (vận – số mệnh) → số phận khốn khó, vận xui.","hsk_level":"7-9","tags":["danh-tu"],"image":"🌩️","examples":[{"type":"basic","zh":"他终于摆脱了厄运。","pinyin":"Tā zhōngyú bǎituōle èyùn.","vi":"Cuối cùng anh ấy đã thoát khỏi vận rủi."},{"type":"simple","zh":"一场大火让这家人陷入了厄运。","pinyin":"Yì chǎng dàhuǒ ràng zhè jiārén xiànrùle èyùn.","vi":"Một trận hỏa hoạn khiến gia đình này rơi vào cảnh khốn cùng."},{"type":"compound","zh":"即使遭遇了一连串的厄运，她也从未放弃希望。","pinyin":"Jíshǐ zāoyùle yìliánchuàn de èyùn, tā yě cóngwèi fàngqì xīwàng.","vi":"Dù gặp hàng loạt vận rủi, cô ấy chưa bao giờ từ bỏ hy vọng."}],"related":[{"hanzi":"噩运","pinyin":"èyùn","vi":"vận đen"},{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"},{"hanzi":"灾难","pinyin":"zāinàn","vi":"tai họa"},{"hanzi":"命运","pinyin":"mìngyùn","vi":"số phận"}],"traditional":"厄運"},{"id":"恶","hanzi":"恶","pinyin":"è","meaning_vi":"ác, hung dữ, xấu xa","explanation":"恶 (ác – xấu, dữ) → hung dữ, xấu xa, trái với 善; đọc ě trong 恶心 (buồn nôn), wù trong 厌恶 (ghét).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😈","examples":[{"type":"basic","zh":"他是个恶人。","pinyin":"Tā shì gè èrén.","vi":"Hắn là kẻ ác."},{"type":"simple","zh":"老人常说善有善报，恶有恶报。","pinyin":"Lǎorén cháng shuō shàn yǒu shàn bào, è yǒu èbào.","vi":"Người già thường nói ở hiền gặp lành, ác giả ác báo."},{"type":"compound","zh":"虽然他看起来很凶恶，但是心地其实很善良。","pinyin":"Suīrán tā kànqǐlái hěn xiōng'è, dànshì xīndì qíshí hěn shànliáng.","vi":"Tuy trông anh ta rất hung dữ nhưng thật ra tấm lòng rất lương thiện."}],"related":[{"hanzi":"凶恶","pinyin":"xiōng'è","vi":"hung ác"},{"hanzi":"善","pinyin":"shàn","vi":"thiện"},{"hanzi":"恶心","pinyin":"ěxin","vi":"buồn nôn"},{"hanzi":"罪恶","pinyin":"zuì'è","vi":"tội ác"}],"traditional":"惡"},{"id":"恶性","hanzi":"恶性","pinyin":"èxìng","meaning_vi":"ác tính, nghiêm trọng, tồi tệ","explanation":"恶 (ác – xấu) + 性 (tính – tính chất) → có tính chất xấu, nguy hại; dùng trong 恶性肿瘤, 恶性循环, 恶性事件.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"⚠️","examples":[{"type":"basic","zh":"这是恶性肿瘤。","pinyin":"Zhè shì èxìng zhǒngliú.","vi":"Đây là khối u ác tính."},{"type":"simple","zh":"熬夜和焦虑形成了恶性循环。","pinyin":"Áoyè hé jiāolǜ xíng chéngle èxìngxúnhuán.","vi":"Thức khuya và lo âu tạo thành vòng luẩn quẩn."},{"type":"compound","zh":"如果不及时制止恶性竞争，整个行业就会受到伤害。","pinyin":"Rúguǒ bù jíshí zhìzhǐ èxìngjìngzhēng, zhěnggè hángyè jiù huì shòudào shānghài.","vi":"Nếu không kịp thời ngăn chặn cạnh tranh không lành mạnh thì cả ngành sẽ bị tổn hại."}],"related":[{"hanzi":"良性","pinyin":"liángxìng","vi":"lành tính"},{"hanzi":"肿瘤","pinyin":"zhǒngliú","vi":"khối u"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"恶性循环","pinyin":"èxìngxúnhuán","vi":"vòng luẩn quẩn"}],"traditional":"惡性"},{"id":"略","hanzi":"略","pinyin":"lüè","meaning_vi":"hơi, sơ qua; lược bỏ, bỏ qua","explanation":"略 (lược – sơ qua, bỏ bớt) → sơ lược, giản lược; đứng trước động từ/tính từ đơn âm nghĩa là hơi, một chút (略有, 略高).","hsk_level":"7-9","tags":["pho-tu"],"image":"✂️","examples":[{"type":"basic","zh":"他比我略高一点。","pinyin":"Tā bǐ wǒ lüè gāo yìdiǎn.","vi":"Anh ấy hơi cao hơn tôi một chút."},{"type":"simple","zh":"这个方案略有改动，请大家再看一遍。","pinyin":"Zhè ge fāng'àn lüèyǒu gǎidòng, qǐng dàjiā zài kàn yíbiàn.","vi":"Phương án này có chỉnh sửa đôi chút, mời mọi người xem lại một lượt."},{"type":"compound","zh":"由于时间有限，所以细节部分我就略过不讲了。","pinyin":"Yóuyú shíjiān yǒuxiàn, suǒyǐ xìjié bùfen wǒ jiù lüèguò bù jiǎng le.","vi":"Do thời gian có hạn nên phần chi tiết tôi xin lược qua không nói."}],"related":[{"hanzi":"省略","pinyin":"shěnglüè","vi":"lược bỏ"},{"hanzi":"简略","pinyin":"jiǎnlüè","vi":"giản lược"},{"hanzi":"略微","pinyin":"lüèwēi","vi":"hơi hơi"},{"hanzi":"战略","pinyin":"zhànlüè","vi":"chiến lược"}]},{"id":"鳄鱼","hanzi":"鳄鱼","pinyin":"èyú","meaning_vi":"cá sấu","explanation":"鳄 (ngạc – cá sấu) + 鱼 (ngư – cá) → cá sấu (thực ra là bò sát, không phải cá).","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐊","examples":[{"type":"basic","zh":"河里有鳄鱼。","pinyin":"Hé lǐ yǒu èyú.","vi":"Dưới sông có cá sấu."},{"type":"simple","zh":"那条鳄鱼一动不动地趴在泥滩上晒太阳。","pinyin":"Nà tiáo èyú yídòngbudòng de pā zài ní tān shang shàitàiyáng.","vi":"Con cá sấu nằm bất động trên bãi bùn phơi nắng."},{"type":"compound","zh":"鳄鱼看似行动迟缓，可是一旦发起攻击就快得惊人。","pinyin":"Èyú kànsì xíngdòng chíhuǎn, kěshì yídàn fāqǐ gōngjī jiù kuài de jīngrén.","vi":"Cá sấu trông có vẻ chậm chạp nhưng một khi tấn công thì nhanh đến kinh người."}],"related":[{"hanzi":"鳄鱼的眼泪","pinyin":"èyú de yǎnlèi","vi":"nước mắt cá sấu"},{"hanzi":"蜥蜴","pinyin":"xīyì","vi":"thằn lằn"},{"hanzi":"爬行动物","pinyin":"páxíngdòngwù","vi":"bò sát"},{"hanzi":"河马","pinyin":"hémǎ","vi":"hà mã"}],"traditional":"鱷魚"},{"id":"恩情","hanzi":"恩情","pinyin":"ēnqíng","meaning_vi":"ân tình, ơn nghĩa","explanation":"恩 (ân – ơn) + 情 (tình – tình cảm) → tình nghĩa và ơn huệ người khác dành cho mình.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💝","examples":[{"type":"basic","zh":"父母的恩情难报。","pinyin":"Fùmǔ de ēnqíng nán bào.","vi":"Ơn nghĩa cha mẹ khó đền đáp."},{"type":"simple","zh":"他一直记着老师当年资助他上学的恩情。","pinyin":"Tā yìzhí jìzhe lǎoshī dāngnián zīzhù tā shàngxué de ēnqíng.","vi":"Anh ấy luôn ghi nhớ ơn thầy năm xưa tài trợ cho mình đi học."},{"type":"compound","zh":"为了报答邻居的恩情，他每年春节都回去看望他们。","pinyin":"Wèile bàodá línjū de ēnqíng, tā měinián Chūnjié dōu huíqù kànwàng tāmen.","vi":"Để đền ơn hàng xóm, Tết nào anh ấy cũng về thăm họ."}],"related":[{"hanzi":"恩惠","pinyin":"ēnhuì","vi":"ân huệ"},{"hanzi":"报恩","pinyin":"bào'ēn","vi":"báo ơn"},{"hanzi":"感恩","pinyin":"gǎn'ēn","vi":"biết ơn"},{"hanzi":"养育之恩","pinyin":"yǎngyùzhī'ēn","vi":"ơn dưỡng dục"}]},{"id":"耳光","hanzi":"耳光","pinyin":"ěrguāng","meaning_vi":"cái tát, bạt tai","explanation":"耳 (nhĩ – tai) + 光 (quang) → cú đánh vào vùng tai má, tức cái tát; thường nói 打耳光, 一记耳光.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"👋","examples":[{"type":"basic","zh":"她打了他一个耳光。","pinyin":"Tā dǎle tā yí ge ěrguāng.","vi":"Cô ấy tát anh ta một cái."},{"type":"simple","zh":"这次惨败像一记响亮的耳光打醒了全队。","pinyin":"Zhè cì cǎnbài xiàng yí jì xiǎngliàng de ěrguāng dǎ xǐngle quán duì.","vi":"Trận thua thảm này như một cái tát đau điếng làm cả đội tỉnh ngộ."},{"type":"compound","zh":"他刚说完那句脏话，就挨了父亲一个耳光。","pinyin":"Tā gāng shuō wán nà jù zānghuà, jiù áile fùqīn yí ge ěrguāng.","vi":"Cậu ta vừa nói xong câu chửi bậy thì đã ăn một cái tát của bố."}],"related":[{"hanzi":"巴掌","pinyin":"bāzhang","vi":"bàn tay, cái tát"},{"hanzi":"打脸","pinyin":"dǎliǎn","vi":"vả mặt"},{"hanzi":"挨打","pinyin":"áidǎ","vi":"bị đánh"},{"hanzi":"脸颊","pinyin":"liǎnjiá","vi":"gò má"}]},{"id":"二手车","hanzi":"二手车","pinyin":"èrshǒuchē","meaning_vi":"xe cũ, ô tô đã qua sử dụng","explanation":"二手 (nhị thủ – qua tay thứ hai) + 车 (xa – xe) → xe đã qua sử dụng, mua lại.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"他买了辆二手车。","pinyin":"Tā mǎile liàng èrshǒuchē.","vi":"Anh ấy mua một chiếc xe cũ."},{"type":"simple","zh":"这辆二手车才开了两万公里，车况很好。","pinyin":"Zhè liàng èrshǒuchē cái kāile liǎng wàn gōnglǐ, chēkuàng hěn hǎo.","vi":"Chiếc xe cũ này mới chạy hai vạn cây số, tình trạng rất tốt."},{"type":"compound","zh":"如果你预算不多，就先买一辆二手车练练手。","pinyin":"Rúguǒ nǐ yùsuàn bù duō, jiù xiān mǎi yí liàng èrshǒuchē liàn lianshǒu.","vi":"Nếu ngân sách không nhiều thì cứ mua tạm một chiếc xe cũ để tập lái."}],"related":[{"hanzi":"新车","pinyin":"xīnchē","vi":"xe mới"},{"hanzi":"二手房","pinyin":"èrshǒufáng","vi":"nhà cũ bán lại"},{"hanzi":"汽车","pinyin":"qìchē","vi":"ô tô"},{"hanzi":"车况","pinyin":"chēkuàng","vi":"tình trạng xe"}],"traditional":"二手車"},{"id":"发布会","hanzi":"发布会","pinyin":"fābùhuì","meaning_vi":"buổi họp báo, lễ ra mắt","explanation":"发布 (phát bố – công bố) + 会 (hội – buổi họp) → buổi họp để công bố tin tức hoặc ra mắt sản phẩm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🎙️","examples":[{"type":"basic","zh":"发布会九点开始。","pinyin":"Fābùhuì jiǔ diǎn kāishǐ.","vi":"Buổi họp báo bắt đầu lúc chín giờ."},{"type":"simple","zh":"公司将在下周举行新手机发布会。","pinyin":"Gōngsī jiāng zài xiàzhōu jǔxíng xīnshǒu jī fābùhuì.","vi":"Công ty sẽ tổ chức lễ ra mắt điện thoại mới vào tuần sau."},{"type":"compound","zh":"因为发布会现场来了太多记者，所以主办方临时加了座位。","pinyin":"Yīnwèi fābùhuì xiànchǎng láile tài duō jìzhě, suǒyǐ zhǔbànfāng línshí jiāle zuòwèi.","vi":"Vì có quá nhiều phóng viên đến buổi họp báo nên ban tổ chức phải kê thêm ghế."}],"related":[{"hanzi":"发布","pinyin":"fābù","vi":"công bố"},{"hanzi":"记者会","pinyin":"jìzhěhuì","vi":"họp báo"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"},{"hanzi":"发言人","pinyin":"fāyánrén","vi":"người phát ngôn"}],"traditional":"發佈會"},{"id":"发电机","hanzi":"发电机","pinyin":"fādiànjī","meaning_vi":"máy phát điện","explanation":"发 (phát – sinh ra) + 电 (điện) + 机 (cơ – máy) → máy sinh ra điện năng.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚡","examples":[{"type":"basic","zh":"发电机坏了。","pinyin":"Fādiànjī huàile.","vi":"Máy phát điện hỏng rồi."},{"type":"simple","zh":"停电后，商场马上启动了备用发电机。","pinyin":"Tíngdiàn hòu, shāngchǎng mǎshàng qǐdòngle bèiyòng fādiànjī.","vi":"Sau khi mất điện, trung tâm thương mại lập tức khởi động máy phát dự phòng."},{"type":"compound","zh":"如果台风导致停电，医院就会用发电机维持手术室供电。","pinyin":"Rúguǒ táifēng dǎozhì tíngdiàn, yīyuàn jiù huì yòng fādiànjī wéichí shǒushùshì gōngdiàn.","vi":"Nếu bão gây mất điện, bệnh viện sẽ dùng máy phát điện để duy trì điện cho phòng mổ."}],"related":[{"hanzi":"发电","pinyin":"fādiàn","vi":"phát điện"},{"hanzi":"电机","pinyin":"diànjī","vi":"động cơ điện"},{"hanzi":"发电站","pinyin":"fādiànzhàn","vi":"nhà máy điện"},{"hanzi":"停电","pinyin":"tíngdiàn","vi":"mất điện"}],"traditional":"發電機"},{"id":"发光","hanzi":"发光","pinyin":"fāguāng","meaning_vi":"phát sáng, tỏa sáng","explanation":"发 (phát – tỏa ra) + 光 (quang – ánh sáng) → tỏa ra ánh sáng; nghĩa bóng là thể hiện tài năng, tỏa sáng.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"✨","examples":[{"type":"basic","zh":"萤火虫会发光。","pinyin":"Yínghuǒchóng huì fāguāng.","vi":"Đom đóm biết phát sáng."},{"type":"simple","zh":"夜里，手表的指针会发光，看时间很方便。","pinyin":"Yèlǐ, shǒubiǎo de zhǐzhēn huì fāguāng, kàn shíjiān hěn fāngbiàn.","vi":"Ban đêm, kim đồng hồ phát sáng nên xem giờ rất tiện."},{"type":"compound","zh":"只要找到适合自己的位置，每个人都能发光发热。","pinyin":"Zhǐyào zhǎodào shìhé zìjǐ de wèizhi, měigerén dōu néng fāguāng fārè.","vi":"Chỉ cần tìm được vị trí phù hợp, ai cũng có thể tỏa sáng và cống hiến."}],"related":[{"hanzi":"发亮","pinyin":"fāliàng","vi":"sáng lên"},{"hanzi":"光芒","pinyin":"guāngmáng","vi":"ánh hào quang"},{"hanzi":"闪光","pinyin":"shǎnguāng","vi":"lóe sáng"},{"hanzi":"发热","pinyin":"fārè","vi":"tỏa nhiệt"}],"traditional":"發光"},{"id":"发火","hanzi":"发火","pinyin":"fāhuǒ","meaning_vi":"nổi giận, nổi nóng; bốc cháy","explanation":"发 (phát – bùng ra) + 火 (hỏa – lửa) → lửa bùng lên; thường dùng nghĩa bóng là nổi giận.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😡","examples":[{"type":"basic","zh":"他很少发火。","pinyin":"Tā hěn shǎo fāhuǒ.","vi":"Anh ấy rất ít khi nổi nóng."},{"type":"simple","zh":"老板看到报表上的错误，当场就发火了。","pinyin":"Lǎobǎn kàndào bàobiǎo shang de cuòwù, dāngchǎng jiù fāhuǒ le.","vi":"Sếp thấy lỗi trong bảng báo cáo liền nổi giận ngay tại chỗ."},{"type":"compound","zh":"即使孩子做错了事，你也不要一开口就发火。","pinyin":"Jíshǐ háizi zuòcuò leshì, nǐ yě bú yào yì kāikǒu jiù fāhuǒ.","vi":"Dù con làm sai, bạn cũng đừng vừa mở miệng đã nổi nóng."}],"related":[{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"},{"hanzi":"发脾气","pinyin":"fāpíqi","vi":"nổi cáu"},{"hanzi":"恼火","pinyin":"nǎohuǒ","vi":"bực tức"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"}],"traditional":"發火"},{"id":"发酵","hanzi":"发酵","pinyin":"fājiào","meaning_vi":"lên men; (nghĩa bóng) âm ỉ lan rộng","explanation":"发 (phát – nở ra) + 酵 (diếu – men) → vi sinh vật làm chất hữu cơ biến đổi; nghĩa bóng là sự việc dần lan rộng, nóng lên.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🍞","examples":[{"type":"basic","zh":"面团正在发酵。","pinyin":"Miàntuán zhèngzài fājiào.","vi":"Khối bột đang lên men."},{"type":"simple","zh":"这件事在网上持续发酵，引起了广泛关注。","pinyin":"Zhè jiàn shì zài wǎngshàng chíxù fājiào, yǐnqǐle guǎngfàn guānzhù.","vi":"Chuyện này liên tục lan rộng trên mạng, thu hút sự chú ý rộng rãi."},{"type":"compound","zh":"如果温度太低，酸奶就发酵不好，味道也会变差。","pinyin":"Rúguǒ wēndù tài dī, suānnǎi jiù fājiào bù hǎo, wèidao yě huì biàn chà.","vi":"Nếu nhiệt độ quá thấp, sữa chua sẽ lên men không tốt và vị cũng kém đi."}],"related":[{"hanzi":"酵母","pinyin":"jiàomǔ","vi":"men"},{"hanzi":"发面","pinyin":"fāmiàn","vi":"ủ bột"},{"hanzi":"酿造","pinyin":"niàngzào","vi":"ủ (rượu, tương)"},{"hanzi":"升温","pinyin":"shēngwēn","vi":"nóng lên"}],"traditional":"發酵"},{"id":"发脾气","hanzi":"发脾气","pinyin":"fāpíqi","meaning_vi":"nổi cáu, giận dỗi","explanation":"发 (phát – bộc lộ) + 脾气 (tì khí – tính khí) → bộc lộ tính nóng nảy, nổi cáu.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😤","examples":[{"type":"basic","zh":"孩子又在发脾气。","pinyin":"Háizi yòu zài fāpíqi.","vi":"Đứa bé lại đang ăn vạ."},{"type":"simple","zh":"他一累就爱对家里人发脾气。","pinyin":"Tā yí lèi jiù ài duìjiā lǐrén fāpíqi.","vi":"Hễ mệt là anh ấy hay cáu gắt với người nhà."},{"type":"compound","zh":"虽然她当时很想发脾气，但是还是忍住了没说话。","pinyin":"Suīrán tā dāngshí hěn xiǎng fāpíqi, dànshì háishi rěn zhùle méi shuōhuà.","vi":"Tuy lúc đó cô ấy rất muốn nổi cáu nhưng vẫn cố nhịn không nói gì."}],"related":[{"hanzi":"发火","pinyin":"fāhuǒ","vi":"nổi nóng"},{"hanzi":"脾气","pinyin":"píqi","vi":"tính khí"},{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"},{"hanzi":"耍性子","pinyin":"shuǎxìngzi","vi":"giở tính"}],"traditional":"發脾氣"},{"id":"发起人","hanzi":"发起人","pinyin":"fāqǐrén","meaning_vi":"người khởi xướng, sáng lập viên","explanation":"发起 (phát khởi – khởi xướng) + 人 (nhân – người) → người đứng ra khởi xướng một hoạt động, tổ chức.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🚩","examples":[{"type":"basic","zh":"她是活动的发起人。","pinyin":"Tā shì huódòng de fāqǐrén.","vi":"Cô ấy là người khởi xướng hoạt động."},{"type":"simple","zh":"这家公益组织的发起人是一位退休教师。","pinyin":"Zhè jiā gōngyì zǔzhī de fāqǐrén shì yí wèi tuìxiū jiàoshī.","vi":"Người sáng lập tổ chức từ thiện này là một giáo viên về hưu."},{"type":"compound","zh":"作为项目发起人，他不但要出钱，而且要负责找合作伙伴。","pinyin":"Zuòwéi xiàngmù fāqǐrén, tā búdàn yào chūqián, érqiě yào fùzé zhǎo hézuò huǒbàn.","vi":"Là người khởi xướng dự án, anh ấy không chỉ bỏ tiền mà còn phụ trách tìm đối tác."}],"related":[{"hanzi":"发起","pinyin":"fāqǐ","vi":"khởi xướng"},{"hanzi":"创始人","pinyin":"chuàngshǐrén","vi":"người sáng lập"},{"hanzi":"倡议","pinyin":"chàngyì","vi":"đề xướng"},{"hanzi":"组织者","pinyin":"zǔzhīzhě","vi":"người tổ chức"}],"traditional":"發起人"},{"id":"发热","hanzi":"发热","pinyin":"fārè","meaning_vi":"sốt, phát sốt; tỏa nhiệt","explanation":"发 (phát – sinh ra) + 热 (nhiệt – nóng) → cơ thể hoặc vật sinh nhiệt; nghĩa bóng là đầu óc nóng vội.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"孩子有点儿发热。","pinyin":"Háizi yǒudiǎnr fārè.","vi":"Đứa bé hơi sốt."},{"type":"simple","zh":"手机玩久了，背面会明显发热。","pinyin":"Shǒujī wán jiǔ le, bèimiàn huì míngxiǎn fārè.","vi":"Chơi điện thoại lâu, mặt sau sẽ nóng lên rõ rệt."},{"type":"compound","zh":"如果发热超过三天，就一定要去医院检查。","pinyin":"Rúguǒ fārè chāoguò sān tiān, jiù yídìngyào qù yīyuàn jiǎnchá.","vi":"Nếu sốt quá ba ngày thì nhất định phải đến bệnh viện kiểm tra."}],"related":[{"hanzi":"发烧","pinyin":"fāshāo","vi":"sốt"},{"hanzi":"体温","pinyin":"tǐwēn","vi":"thân nhiệt"},{"hanzi":"头脑发热","pinyin":"tóunǎofārè","vi":"nóng đầu, bốc đồng"},{"hanzi":"退烧","pinyin":"tuìshāo","vi":"hạ sốt"}],"traditional":"發熱"},{"id":"发型","hanzi":"发型","pinyin":"fàxíng","meaning_vi":"kiểu tóc","explanation":"发 (phát – tóc, đọc fà) + 型 (hình – kiểu) → kiểu dáng của mái tóc.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"💇","examples":[{"type":"basic","zh":"你换发型了？","pinyin":"Nǐ huàn fàxíng le?","vi":"Bạn đổi kiểu tóc à?"},{"type":"simple","zh":"她的新发型让她看起来年轻了好几岁。","pinyin":"Tā de xīn fàxíng ràng tā kànqǐlái niánqīngle hǎo jǐsuì.","vi":"Kiểu tóc mới khiến cô ấy trông trẻ ra mấy tuổi."},{"type":"compound","zh":"要是你不知道选什么发型，就让理发师给点建议。","pinyin":"Yàoshi nǐ bù zhīdào xuǎn shénme fàxíng, jiù ràng lǐfàshī gěi diǎn jiànyì.","vi":"Nếu bạn không biết chọn kiểu tóc nào thì nhờ thợ cắt tóc gợi ý."}],"related":[{"hanzi":"头发","pinyin":"tóufa","vi":"tóc"},{"hanzi":"理发","pinyin":"lǐfà","vi":"cắt tóc"},{"hanzi":"发廊","pinyin":"fàláng","vi":"tiệm tóc"},{"hanzi":"造型","pinyin":"zàoxíng","vi":"tạo hình"}],"traditional":"髮型"},{"id":"发作","hanzi":"发作","pinyin":"fāzuò","meaning_vi":"phát tác, lên cơn; nổi giận","explanation":"发 (phát – bộc phát) + 作 (tác – nổi lên) → bệnh tật hoặc cảm xúc đột ngột bộc phát.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"💥","examples":[{"type":"basic","zh":"他的胃病又发作了。","pinyin":"Tā de wèibìng yòu fāzuò le.","vi":"Bệnh dạ dày của anh ấy lại tái phát."},{"type":"simple","zh":"药效发作以后，病人很快就睡着了。","pinyin":"Yàoxiào fāzuò yǐhòu, bìngrén hěn kuài jiù shuìzháo le.","vi":"Sau khi thuốc ngấm, bệnh nhân nhanh chóng ngủ thiếp đi."},{"type":"compound","zh":"一旦哮喘发作，他就必须马上使用喷雾剂。","pinyin":"Yídàn xiàochuǎn fāzuò, tā jiù bìxū mǎshàng shǐyòng pēnwù jì.","vi":"Một khi lên cơn hen, anh ấy phải dùng bình xịt ngay."}],"related":[{"hanzi":"复发","pinyin":"fùfā","vi":"tái phát"},{"hanzi":"发病","pinyin":"fābìng","vi":"phát bệnh"},{"hanzi":"爆发","pinyin":"bàofā","vi":"bùng phát"},{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"}],"traditional":"發作"},{"id":"阀门","hanzi":"阀门","pinyin":"fámén","meaning_vi":"van (máy móc, ống nước)","explanation":"阀 (phiệt – van) + 门 (môn – cửa) → bộ phận như cánh cửa đóng mở dòng chất lỏng, khí.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔧","examples":[{"type":"basic","zh":"请关上煤气阀门。","pinyin":"Qǐng guānshang méiqì fámén.","vi":"Hãy khóa van ga lại."},{"type":"simple","zh":"工人拧开阀门，水立刻流进了水池。","pinyin":"Gōngrén nǐngkāi fámén, shuǐ lìkè liú jìnle shuǐchí.","vi":"Công nhân vặn mở van, nước lập tức chảy vào bể."},{"type":"compound","zh":"出门旅行之前，最好检查一下水和煤气的阀门有没有关好。","pinyin":"Chūmén lǚxíng zhīqián, zuìhǎo jiǎnchá yíxià shuǐ hé méiqì de fámén yǒuméiyǒu guān hǎo.","vi":"Trước khi đi du lịch, tốt nhất nên kiểm tra van nước và van ga đã khóa kỹ chưa."}],"related":[{"hanzi":"开关","pinyin":"kāiguān","vi":"công tắc"},{"hanzi":"水龙头","pinyin":"shuǐlóngtóu","vi":"vòi nước"},{"hanzi":"管道","pinyin":"guǎndào","vi":"đường ống"},{"hanzi":"气阀","pinyin":"qìfá","vi":"van khí"}],"traditional":"閥門"},{"id":"帆","hanzi":"帆","pinyin":"fān","meaning_vi":"cánh buồm","explanation":"帆 (phàm – buồm) → tấm vải căng trên cột thuyền để hứng gió đẩy thuyền đi.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⛵","examples":[{"type":"basic","zh":"船上挂着白帆。","pinyin":"Chuán shang guàzhe bái fān.","vi":"Trên thuyền treo cánh buồm trắng."},{"type":"simple","zh":"风一停，渔民只好把帆降了下来。","pinyin":"Fēng yì tíng, yúmín zhǐhǎo bǎ fān jiàngle xiàlái.","vi":"Gió vừa lặng, ngư dân đành hạ buồm xuống."},{"type":"compound","zh":"只要帆的角度调整得好，逆风也能前进。","pinyin":"Zhǐyào fān de jiǎodù tiáozhěng de hǎo, nìfēng yě néng qiánjìn.","vi":"Chỉ cần điều chỉnh góc buồm tốt thì ngược gió vẫn tiến được."}],"related":[{"hanzi":"帆船","pinyin":"fānchuán","vi":"thuyền buồm"},{"hanzi":"一帆风顺","pinyin":"yìfānfēngshùn","vi":"thuận buồm xuôi gió"},{"hanzi":"扬帆","pinyin":"yángfān","vi":"giương buồm"},{"hanzi":"船","pinyin":"chuán","vi":"thuyền"}]},{"id":"帆船","hanzi":"帆船","pinyin":"fānchuán","meaning_vi":"thuyền buồm","explanation":"帆 (phàm – buồm) + 船 (thuyền) → thuyền chạy bằng sức gió thổi vào buồm.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⛵","examples":[{"type":"basic","zh":"海上有艘帆船。","pinyin":"Hǎishang yǒu sōu fānchuán.","vi":"Trên biển có một chiếc thuyền buồm."},{"type":"simple","zh":"他利用暑假学会了驾驶小帆船。","pinyin":"Tā lìyòng shǔjià xuéhuìle jiàshǐ xiǎo fānchuán.","vi":"Anh ấy tận dụng kỳ nghỉ hè học được cách lái thuyền buồm nhỏ."},{"type":"compound","zh":"虽然帆船比赛很刺激，但是对天气的要求很高。","pinyin":"Suīrán fānchuán bǐsài hěn cìjī, dànshì duì tiānqì de yāoqiú hěn gāo.","vi":"Tuy đua thuyền buồm rất hấp dẫn nhưng đòi hỏi thời tiết rất cao."}],"related":[{"hanzi":"帆","pinyin":"fān","vi":"cánh buồm"},{"hanzi":"轮船","pinyin":"lúnchuán","vi":"tàu thủy"},{"hanzi":"游艇","pinyin":"yóutǐng","vi":"du thuyền"},{"hanzi":"航海","pinyin":"hánghǎi","vi":"hàng hải"}]},{"id":"凡","hanzi":"凡","pinyin":"fán","meaning_vi":"phàm là, hễ là; tầm thường","explanation":"凡 (phàm – mọi, tầm thường) → đứng đầu câu nghĩa là hễ là, tất cả (thường đi với 都); còn có nghĩa bình thường như 平凡.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"凡事都要小心。","pinyin":"Fánshì dōu yào xiǎoxīn.","vi":"Việc gì cũng phải cẩn thận."},{"type":"simple","zh":"凡年满十八岁的公民都有选举权。","pinyin":"Fán niánmǎn shíbā suì de gōngmín dōu yǒu xuǎnjǔquán.","vi":"Phàm là công dân đủ mười tám tuổi đều có quyền bầu cử."},{"type":"compound","zh":"凡是来参加活动的人，只要出示门票就能领一份礼物。","pinyin":"Fánshì lái cānjiā huódòng de rén, zhǐyào chūshì ménpiào jiù néng lǐng yí fèn lǐwù.","vi":"Hễ ai đến tham gia sự kiện, chỉ cần xuất trình vé là được nhận một phần quà."}],"related":[{"hanzi":"凡是","pinyin":"fánshì","vi":"phàm là"},{"hanzi":"平凡","pinyin":"píngfán","vi":"bình thường"},{"hanzi":"非凡","pinyin":"fēifán","vi":"phi thường"},{"hanzi":"凡人","pinyin":"fánrén","vi":"người phàm"}]},{"id":"烦闷","hanzi":"烦闷","pinyin":"fánmèn","meaning_vi":"buồn bực, phiền muộn","explanation":"烦 (phiền – phiền não) + 闷 (muộn – bí bách) → trong lòng phiền não, bức bối không thoải mái.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"他心里很烦闷。","pinyin":"Tā xīnlǐ hěn fánmèn.","vi":"Trong lòng anh ấy rất buồn bực."},{"type":"simple","zh":"连续下了一周雨，大家都觉得有些烦闷。","pinyin":"Liánxù xiàle yìzhōu yǔ, dàjiā dōu juéde yǒuxiē fánmèn.","vi":"Mưa liên tục một tuần, ai cũng thấy hơi bức bối."},{"type":"compound","zh":"每当感到烦闷的时候，她就去公园跑几圈。","pinyin":"Měidāng gǎndào fánmèn de shíhou, tā jiù qù gōngyuán pǎo jǐ quān.","vi":"Mỗi khi thấy phiền muộn, cô ấy lại ra công viên chạy vài vòng."}],"related":[{"hanzi":"烦躁","pinyin":"fánzào","vi":"bồn chồn"},{"hanzi":"郁闷","pinyin":"yùmèn","vi":"buồn bực"},{"hanzi":"苦闷","pinyin":"kǔmèn","vi":"khổ sở"},{"hanzi":"舒畅","pinyin":"shūchàng","vi":"khoan khoái"}],"traditional":"煩悶"},{"id":"烦躁","hanzi":"烦躁","pinyin":"fánzào","meaning_vi":"bồn chồn, bực bội, nóng nảy","explanation":"烦 (phiền – phiền não) + 躁 (táo – nôn nóng) → phiền lòng và nôn nóng, không ngồi yên được.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"天热让人烦躁。","pinyin":"Tiān rè ràng rén fánzào.","vi":"Trời nóng khiến người ta bực bội."},{"type":"simple","zh":"等了两个小时还没消息，他越来越烦躁。","pinyin":"Děngle liǎng ge xiǎoshí hái méi xiāoxi, tā yuèláiyuè fánzào.","vi":"Đợi hai tiếng vẫn chưa có tin, anh ấy càng lúc càng bồn chồn."},{"type":"compound","zh":"因为晚上睡不好，所以她白天总是很烦躁。","pinyin":"Yīnwèi wǎnshang shuì bu hǎo, suǒyǐ tā báitiān zǒngshì hěn fánzào.","vi":"Vì buổi tối ngủ không ngon nên ban ngày cô ấy lúc nào cũng cáu bẳn."}],"related":[{"hanzi":"烦闷","pinyin":"fánmèn","vi":"phiền muộn"},{"hanzi":"急躁","pinyin":"jízào","vi":"nóng vội"},{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình tĩnh"}],"traditional":"煩躁"},{"id":"反弹","hanzi":"反弹","pinyin":"fǎntán","meaning_vi":"bật lại, nảy lại; phục hồi trở lại","explanation":"反 (phản – ngược lại) + 弹 (đàn – bật) → bật ngược trở lại; dùng cho giá cả, cân nặng, dư luận tăng trở lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏀","examples":[{"type":"basic","zh":"球撞墙后反弹了。","pinyin":"Qiú zhuàng qiáng hòu fǎntán le.","vi":"Quả bóng đập vào tường rồi bật lại."},{"type":"simple","zh":"连跌几天后，股价今天开始反弹。","pinyin":"Lián diē jǐ tiānhòu, gǔjià jīntiān kāishǐ fǎntán.","vi":"Sau mấy ngày giảm liên tiếp, giá cổ phiếu hôm nay bắt đầu hồi phục."},{"type":"compound","zh":"如果减肥只靠节食，体重就很容易反弹。","pinyin":"Rúguǒ jiǎnféi zhǐ kào jiéshí, tǐzhòng jiù hěn róngyì fǎntán.","vi":"Nếu giảm cân chỉ dựa vào nhịn ăn thì cân nặng rất dễ tăng lại."}],"related":[{"hanzi":"回升","pinyin":"huíshēng","vi":"tăng trở lại"},{"hanzi":"弹性","pinyin":"tánxìng","vi":"tính đàn hồi"},{"hanzi":"下跌","pinyin":"xiàdiē","vi":"giảm xuống"},{"hanzi":"回弹","pinyin":"huítán","vi":"bật trở lại"}],"traditional":"反彈"},{"id":"反过来","hanzi":"反过来","pinyin":"fǎnguolái","meaning_vi":"ngược lại, đảo lại","explanation":"反 (phản – ngược) + 过来 (quá lai – qua đây) → lật ngược chiều; dùng để nói chiều ngược lại của một quan hệ.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"把衣服反过来晒。","pinyin":"Bǎ yīfu fǎnguolái shài.","vi":"Lộn trái quần áo ra mà phơi."},{"type":"simple","zh":"反过来想，这次失败也是一次机会。","pinyin":"Fǎnguolái xiǎng, zhè cì shībài yě shì yí cì jīhuì.","vi":"Nghĩ ngược lại, lần thất bại này cũng là một cơ hội."},{"type":"compound","zh":"父母关心孩子，反过来，孩子长大后也应该照顾父母。","pinyin":"Fùmǔ guānxīn háizi, fǎnguolái, háizi zhǎngdà hòu yě yīnggāi zhàogù fùmǔ.","vi":"Cha mẹ quan tâm con cái, ngược lại, con lớn lên cũng nên chăm sóc cha mẹ."}],"related":[{"hanzi":"相反","pinyin":"xiāngfǎn","vi":"trái lại"},{"hanzi":"反之","pinyin":"fǎnzhī","vi":"ngược lại"},{"hanzi":"颠倒","pinyin":"diāndǎo","vi":"đảo lộn"},{"hanzi":"倒过来","pinyin":"dàoguolái","vi":"lật ngược"}],"traditional":"反過來"},{"id":"反击","hanzi":"反击","pinyin":"fǎnjī","meaning_vi":"phản công, đánh trả","explanation":"反 (phản – trở lại) + 击 (kích – đánh) → đánh trả lại đối phương.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥊","examples":[{"type":"basic","zh":"我们开始反击了。","pinyin":"Wǒmen kāishǐ fǎnjī le.","vi":"Chúng ta bắt đầu phản công rồi."},{"type":"simple","zh":"面对网上的谣言，公司发表声明进行反击。","pinyin":"Miànduì wǎngshàng de yáoyán, gōngsī fābiǎo shēngmíng jìnxíng fǎnjī.","vi":"Trước tin đồn trên mạng, công ty ra tuyên bố để phản bác."},{"type":"compound","zh":"虽然上半场一直落后，但是他们下半场成功反击扳平了比分。","pinyin":"Suīrán shàngbànchǎng yìzhí luòhòu, dànshì tāmen xiàbànchǎng chénggōng fǎnjī bānpíngle bǐfēn.","vi":"Tuy hiệp một luôn bị dẫn trước nhưng hiệp hai họ phản công thành công và gỡ hòa."}],"related":[{"hanzi":"反攻","pinyin":"fǎngōng","vi":"phản công"},{"hanzi":"攻击","pinyin":"gōngjī","vi":"tấn công"},{"hanzi":"还击","pinyin":"huánjī","vi":"đánh trả"},{"hanzi":"防守","pinyin":"fángshǒu","vi":"phòng thủ"}],"traditional":"反擊"},{"id":"反省","hanzi":"反省","pinyin":"fǎnxǐng","meaning_vi":"tự kiểm điểm, tự xét mình","explanation":"反 (phản – quay lại) + 省 (tỉnh – xem xét) → quay lại xét xem bản thân sai ở đâu.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🪞","examples":[{"type":"basic","zh":"你该好好反省。","pinyin":"Nǐ gāi hǎohǎo fǎnxǐng.","vi":"Cậu nên tự kiểm điểm cho kỹ."},{"type":"simple","zh":"输了比赛后，教练让队员们各自反省。","pinyin":"Shūle bǐsài hòu, jiàoliàn ràng duìyuánmen gèzì fǎnxǐng.","vi":"Sau khi thua trận, huấn luyện viên bảo các cầu thủ tự kiểm điểm."},{"type":"compound","zh":"与其一味责怪别人，不如先反省一下自己的问题。","pinyin":"Yǔqí yíwèi zéguài biérén, bùrú xiān fǎnxǐng yíxià zìjǐ de wèntí.","vi":"Thay vì cứ trách người khác, chi bằng hãy tự xem lại vấn đề của mình trước."}],"related":[{"hanzi":"反思","pinyin":"fǎnsī","vi":"suy ngẫm lại"},{"hanzi":"检讨","pinyin":"jiǎntǎo","vi":"kiểm điểm"},{"hanzi":"自省","pinyin":"zìxǐng","vi":"tự xét mình"},{"hanzi":"悔改","pinyin":"huǐgǎi","vi":"hối cải"}]},{"id":"返还","hanzi":"返还","pinyin":"fǎnhuán","meaning_vi":"hoàn trả, trả lại","explanation":"返 (phản – quay về) + 还 (hoàn – trả) → trả lại cho chủ cũ hoặc người đã nộp.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"↩️","examples":[{"type":"basic","zh":"押金将全额返还。","pinyin":"Yājīn jiāng quán'é fǎnhuán.","vi":"Tiền đặt cọc sẽ được hoàn trả toàn bộ."},{"type":"simple","zh":"商家承诺七天内返还多收的费用。","pinyin":"Shāngjiā chéngnuò qī tiān nèi fǎnhuán duō shōu de fèiyòng.","vi":"Cửa hàng cam kết hoàn lại khoản phí thu thừa trong bảy ngày."},{"type":"compound","zh":"如果您在入住前取消预订，酒店就会返还一半房费。","pinyin":"Rúguǒ nín zài rùzhù qián qǔxiāo yùdìng, jiǔdiàn jiù huì fǎnhuán yíbàn fángfèi.","vi":"Nếu quý khách hủy đặt phòng trước khi nhận phòng, khách sạn sẽ hoàn lại một nửa tiền phòng."}],"related":[{"hanzi":"归还","pinyin":"guīhuán","vi":"trả lại"},{"hanzi":"退还","pinyin":"tuìhuán","vi":"hoàn trả"},{"hanzi":"退款","pinyin":"tuìkuǎn","vi":"hoàn tiền"},{"hanzi":"返现","pinyin":"fǎnxiàn","vi":"hoàn tiền mặt"}],"traditional":"返還"},{"id":"犯愁","hanzi":"犯愁","pinyin":"fànchóu","meaning_vi":"lo lắng, rầu rĩ","explanation":"犯 (phạm – mắc phải) + 愁 (sầu – lo buồn) → rơi vào trạng thái lo âu, buồn rầu.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"别为这事犯愁了。","pinyin":"Bié wèi zhè shì fànchóu le.","vi":"Đừng rầu rĩ vì chuyện này nữa."},{"type":"simple","zh":"房租又涨了，他正为下个月的生活费犯愁。","pinyin":"Fángzū yòu zhǎng le, tā zhèng wèi xiàgeyuè de shēnghuófèi fànchóu.","vi":"Tiền nhà lại tăng, anh ấy đang lo sốt vó vì tiền sinh hoạt tháng sau."},{"type":"compound","zh":"只要提前做好计划，就不用到时候再犯愁了。","pinyin":"Zhǐyào tíqián zuò hǎo jìhuà, jiù bú yòng dàoshíhou zài fànchóu le.","vi":"Chỉ cần lên kế hoạch trước thì không phải đến lúc đó mới lo."}],"related":[{"hanzi":"发愁","pinyin":"fāchóu","vi":"lo buồn"},{"hanzi":"忧愁","pinyin":"yōuchóu","vi":"âu sầu"},{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"愁眉苦脸","pinyin":"chóuméikǔliǎn","vi":"mặt mày ủ rũ"}]},{"id":"饭碗","hanzi":"饭碗","pinyin":"fànwǎn","meaning_vi":"bát cơm; (nghĩa bóng) công việc, kế sinh nhai","explanation":"饭 (phạn – cơm) + 碗 (oản – cái bát) → bát ăn cơm; nghĩa bóng là chén cơm, công việc nuôi sống bản thân.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🍚","examples":[{"type":"basic","zh":"他丢了饭碗。","pinyin":"Tā diūle fànwǎn.","vi":"Anh ấy mất việc rồi."},{"type":"simple","zh":"很多人把公务员看成是铁饭碗。","pinyin":"Hěn duō rén bǎ gōngwùyuán kànchéng shì tiěfànwǎn.","vi":"Nhiều người coi công chức là bát cơm sắt (việc ổn định)."},{"type":"compound","zh":"如果不学习新技术，你的饭碗迟早会被别人抢走。","pinyin":"Rúguǒ bù xuéxí xīnjìshù, nǐ de fànwǎn chízǎo huì bèi biérén qiǎngzǒu.","vi":"Nếu không học kỹ thuật mới, chén cơm của bạn sớm muộn cũng bị người khác giành mất."}],"related":[{"hanzi":"铁饭碗","pinyin":"tiěfànwǎn","vi":"việc ổn định suốt đời"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"công việc"},{"hanzi":"失业","pinyin":"shīyè","vi":"thất nghiệp"},{"hanzi":"碗","pinyin":"wǎn","vi":"cái bát"}],"traditional":"飯碗"},{"id":"方向盘","hanzi":"方向盘","pinyin":"fāngxiàngpán","meaning_vi":"vô lăng, tay lái","explanation":"方向 (phương hướng) + 盘 (bàn – vật hình tròn) → vòng tròn dùng để điều khiển hướng xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚘","examples":[{"type":"basic","zh":"请握紧方向盘。","pinyin":"Qǐng wò jǐn fāngxiàngpán.","vi":"Hãy nắm chặt vô lăng."},{"type":"simple","zh":"他猛地一打方向盘，避开了路中间的石头。","pinyin":"Tā měngde yìdǎ fāngxiàngpán, bìkāile lù zhōngjiān de shítou.","vi":"Anh ấy đánh mạnh tay lái, tránh được hòn đá giữa đường."},{"type":"compound","zh":"虽然我拿到驾照很久了，但是一握方向盘还是会紧张。","pinyin":"Suīrán wǒ nádào jiàzhào hěn jiǔ le, dànshì yí wò fāngxiàngpán háishi huì jǐnzhāng.","vi":"Tuy tôi có bằng lái lâu rồi nhưng cứ cầm vô lăng là vẫn căng thẳng."}],"related":[{"hanzi":"驾驶","pinyin":"jiàshǐ","vi":"lái xe"},{"hanzi":"刹车","pinyin":"shāchē","vi":"phanh"},{"hanzi":"油门","pinyin":"yóumén","vi":"chân ga"},{"hanzi":"司机","pinyin":"sījī","vi":"tài xế"}],"traditional":"方向盤"},{"id":"防盗","hanzi":"防盗","pinyin":"fángdào","meaning_vi":"chống trộm","explanation":"防 (phòng – đề phòng) + 盗 (đạo – trộm cắp) → đề phòng trộm cắp; hay đứng trước danh từ như 防盗门, 防盗锁.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🔒","examples":[{"type":"basic","zh":"这把锁能防盗。","pinyin":"Zhè bǎ suǒ néng fángdào.","vi":"Ổ khóa này chống trộm được."},{"type":"simple","zh":"小区新装了监控，加强了防盗措施。","pinyin":"Xiǎoqū xīn zhuāngle jiānkòng, jiāqiángle fángdào cuòshī.","vi":"Khu dân cư mới lắp camera, tăng cường biện pháp chống trộm."},{"type":"compound","zh":"既然附近最近常丢自行车，你就买个防盗锁吧。","pinyin":"Jìrán fùjìn zuìjìn cháng diū zìxíngchē, nǐ jiù mǎi ge fángdào suǒ ba.","vi":"Đã dạo này quanh đây hay mất xe đạp thì bạn mua một cái khóa chống trộm đi."}],"related":[{"hanzi":"防盗门","pinyin":"fángdàomén","vi":"cửa chống trộm"},{"hanzi":"小偷","pinyin":"xiǎotōu","vi":"kẻ trộm"},{"hanzi":"盗窃","pinyin":"dàoqiè","vi":"trộm cắp"},{"hanzi":"报警器","pinyin":"bàojǐngqì","vi":"thiết bị báo động"}],"traditional":"防盜"},{"id":"防盗门","hanzi":"防盗门","pinyin":"fángdàomén","meaning_vi":"cửa chống trộm","explanation":"防盗 (phòng đạo – chống trộm) + 门 (môn – cửa) → loại cửa kiên cố, có khóa an toàn để chống trộm.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🚪","examples":[{"type":"basic","zh":"我家装了防盗门。","pinyin":"Wǒ jiā zhuāngle fángdàomén.","vi":"Nhà tôi đã lắp cửa chống trộm."},{"type":"simple","zh":"这扇防盗门是钢做的，非常结实。","pinyin":"Zhè shàn fángdàomén shì gāng zuò de, fēicháng jiēshi.","vi":"Cánh cửa chống trộm này làm bằng thép, rất chắc chắn."},{"type":"compound","zh":"即使装了防盗门，出门时也要记得把窗户关好。","pinyin":"Jíshǐ zhuāngle fángdàomén, chūmén shí yě yào jìde bǎ chuānghu guān hǎo.","vi":"Dù đã lắp cửa chống trộm, khi ra ngoài cũng phải nhớ đóng kỹ cửa sổ."}],"related":[{"hanzi":"防盗","pinyin":"fángdào","vi":"chống trộm"},{"hanzi":"大门","pinyin":"dàmén","vi":"cổng lớn"},{"hanzi":"门锁","pinyin":"ménsuǒ","vi":"khóa cửa"},{"hanzi":"保险柜","pinyin":"bǎoxiǎnguì","vi":"két sắt"}],"traditional":"防盜門"},{"id":"妨害","hanzi":"妨害","pinyin":"fánghài","meaning_vi":"gây hại, làm tổn hại, cản trở","explanation":"妨 (phương – cản trở) + 害 (hại – làm hại) → cản trở và gây tổn hại; hay dùng trong văn bản pháp luật như 妨害公务.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"吸烟妨害健康。","pinyin":"Xīyān fánghài jiànkāng.","vi":"Hút thuốc gây hại cho sức khỏe."},{"type":"simple","zh":"他因妨害公务被警方带走了。","pinyin":"Tā yīn fánghài gōngwù bèi jǐngfāng dàizǒu le.","vi":"Anh ta bị cảnh sát đưa đi vì tội cản trở người thi hành công vụ."},{"type":"compound","zh":"只要不妨害别人，你在自己家里做什么都可以。","pinyin":"Zhǐ yàobù fánghài biérén, nǐ zài zìjǐ jiālǐ zuò shénme dōu kěyǐ.","vi":"Chỉ cần không làm hại người khác, bạn làm gì trong nhà mình cũng được."}],"related":[{"hanzi":"妨碍","pinyin":"fáng'ài","vi":"cản trở"},{"hanzi":"危害","pinyin":"wēihài","vi":"nguy hại"},{"hanzi":"损害","pinyin":"sǔnhài","vi":"tổn hại"},{"hanzi":"阻碍","pinyin":"zǔ'ài","vi":"ngăn trở"}]},{"id":"仿","hanzi":"仿","pinyin":"fǎng","meaning_vi":"bắt chước, mô phỏng, phỏng theo","explanation":"仿 (phỏng – bắt chước) → làm theo mẫu có sẵn; dùng trong 模仿, 仿造, 仿古.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎭","examples":[{"type":"basic","zh":"这是仿古建筑。","pinyin":"Zhè shì fǎnggǔ jiànzhù.","vi":"Đây là công trình kiến trúc phỏng cổ."},{"type":"simple","zh":"这家工厂专门仿制名牌包，已经被查封了。","pinyin":"Zhè jiā gōngchǎng zhuānmén fǎngzhì míngpái bāo, yǐjīng bèi cháfēng le.","vi":"Xưởng này chuyên làm nhái túi hàng hiệu, đã bị niêm phong."},{"type":"compound","zh":"孩子学写字时，往往先仿着字帖一笔一画地写。","pinyin":"Háizi xué xiězì shí, wǎngwǎng xiān fǎngzhe zìtiè yì bǐ yí huà de xiě.","vi":"Khi trẻ học viết, thường trước tiên phỏng theo vở mẫu viết từng nét một."}],"related":[{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"},{"hanzi":"仿造","pinyin":"fǎngzào","vi":"làm nhái"},{"hanzi":"仿佛","pinyin":"fǎngfú","vi":"dường như"},{"hanzi":"效仿","pinyin":"xiàofǎng","vi":"noi theo"}]},{"id":"访谈","hanzi":"访谈","pinyin":"fǎngtán","meaning_vi":"phỏng vấn, trò chuyện","explanation":"访 (phỏng – thăm hỏi) + 谈 (đàm – trò chuyện) → đến gặp để hỏi chuyện, phỏng vấn; hay dùng trong 访谈节目.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"我在看访谈节目。","pinyin":"Wǒ zài kàn fǎngtán jiémù.","vi":"Tôi đang xem chương trình phỏng vấn."},{"type":"simple","zh":"记者访谈了几位受灾的村民。","pinyin":"Jìzhě fǎngtánle jǐ wèi shòuzāi de cūnmín.","vi":"Phóng viên đã phỏng vấn mấy người dân làng bị nạn."},{"type":"compound","zh":"虽然访谈只有半个小时，但是嘉宾分享了很多真实经历。","pinyin":"Suīrán fǎngtán zhǐyǒu bàn ge xiǎoshí, dànshì jiābīn fēnxiǎngle hěn duō zhēnshí jīnglì.","vi":"Tuy buổi phỏng vấn chỉ có nửa tiếng nhưng khách mời đã chia sẻ nhiều trải nghiệm thật."}],"related":[{"hanzi":"采访","pinyin":"cǎifǎng","vi":"phỏng vấn"},{"hanzi":"访问","pinyin":"fǎngwèn","vi":"thăm viếng, phỏng vấn"},{"hanzi":"座谈","pinyin":"zuòtán","vi":"tọa đàm"},{"hanzi":"对话","pinyin":"duìhuà","vi":"đối thoại"}],"traditional":"訪談"},{"id":"放过","hanzi":"放过","pinyin":"fàngguò","meaning_vi":"bỏ qua, tha cho, để lỡ","explanation":"放 (phóng – thả) + 过 (quá – qua) → thả cho đi qua; nghĩa là tha cho ai hoặc để vuột mất cơ hội.","hsk_level":"7-9","tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"求你放过我吧。","pinyin":"Qiú nǐ fàngguò wǒ ba.","vi":"Xin anh tha cho tôi đi."},{"type":"simple","zh":"警察没有放过任何一个可疑的细节。","pinyin":"Jǐngchá méiyǒu fàngguò rènhé yí ge kěyí de xìjié.","vi":"Cảnh sát không bỏ qua bất kỳ chi tiết đáng ngờ nào."},{"type":"compound","zh":"这么好的机会，如果你放过了，以后就很难再遇到。","pinyin":"Zhème hǎo de jīhuì, rúguǒ nǐ fàngguò le, yǐhòu jiù hěn nán zài yùdào.","vi":"Cơ hội tốt thế này, nếu bạn để lỡ thì sau này rất khó gặp lại."}],"related":[{"hanzi":"错过","pinyin":"cuòguò","vi":"bỏ lỡ"},{"hanzi":"饶恕","pinyin":"ráoshù","vi":"tha thứ"},{"hanzi":"宽恕","pinyin":"kuānshù","vi":"khoan thứ"},{"hanzi":"不放过","pinyin":"búfàngguò","vi":"không tha"}],"traditional":"放過"},{"id":"放水","hanzi":"放水","pinyin":"fàngshuǐ","meaning_vi":"xả nước; (thể thao) cố ý thua, nhường","explanation":"放 (phóng – xả) + 水 (thủy – nước) → xả nước ra; khẩu ngữ chỉ cố tình chơi kém, nhường đối thủ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚰","examples":[{"type":"basic","zh":"水库开始放水了。","pinyin":"Shuǐkù kāishǐ fàngshuǐ le.","vi":"Hồ chứa bắt đầu xả nước rồi."},{"type":"simple","zh":"球迷怀疑这支球队在比赛中故意放水。","pinyin":"Qiúmí huáiyí zhè zhī qiúduì zài bǐsài zhōng gùyì fàngshuǐ.","vi":"Cổ động viên nghi ngờ đội bóng này cố tình buông trận."},{"type":"compound","zh":"因为下游河水上涨，所以水库暂时停止放水。","pinyin":"Yīnwèi xiàyóu héshuǐ shàngzhǎng, suǒyǐ shuǐkù zànshí tíngzhǐ fàngshuǐ.","vi":"Vì nước sông hạ lưu dâng cao nên hồ chứa tạm dừng xả nước."}],"related":[{"hanzi":"泄洪","pinyin":"xièhóng","vi":"xả lũ"},{"hanzi":"水库","pinyin":"shuǐkù","vi":"hồ chứa nước"},{"hanzi":"让球","pinyin":"ràngqiú","vi":"nhường điểm"},{"hanzi":"假球","pinyin":"jiǎqiú","vi":"bán độ"}]},{"id":"放肆","hanzi":"放肆","pinyin":"fàngsì","meaning_vi":"càn rỡ, hỗn láo, láo xược","explanation":"放 (phóng – buông thả) + 肆 (tứ – tùy tiện) → buông thả, không biết giữ phép tắc, láo xược.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😠","examples":[{"type":"basic","zh":"你太放肆了！","pinyin":"Nǐ tài fàngsì le!","vi":"Mày láo quá rồi!"},{"type":"simple","zh":"他在长辈面前说话十分放肆。","pinyin":"Tā zài zhǎngbèi miànqián shuōhuà shífēn fàngsì.","vi":"Cậu ta nói chuyện trước mặt người lớn rất hỗn láo."},{"type":"compound","zh":"老师一离开教室，几个学生就放肆地大声喧哗起来。","pinyin":"Lǎoshī yì líkāi jiàoshì, jǐ ge xuésheng jiù fàngsì de dàshēng xuānhuá qǐlái.","vi":"Thầy giáo vừa rời lớp, mấy học sinh liền ồn ào náo loạn."}],"related":[{"hanzi":"放纵","pinyin":"fàngzòng","vi":"buông thả"},{"hanzi":"无礼","pinyin":"wúlǐ","vi":"vô lễ"},{"hanzi":"嚣张","pinyin":"xiāozhāng","vi":"ngang ngược"},{"hanzi":"拘束","pinyin":"jūshù","vi":"gò bó"}]},{"id":"放映","hanzi":"放映","pinyin":"fàngyìng","meaning_vi":"chiếu (phim)","explanation":"放 (phóng – phát ra) + 映 (ánh – chiếu hình) → chiếu hình ảnh lên màn, tức chiếu phim.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"电影正在放映。","pinyin":"Diànyǐng zhèngzài fàngyìng.","vi":"Phim đang được chiếu."},{"type":"simple","zh":"这部纪录片将在全国各大影院同时放映。","pinyin":"Zhè bù jìlùpiàn jiāng zài quánguó gè dà yǐngyuàn tóngshí fàngyìng.","vi":"Bộ phim tài liệu này sẽ được chiếu đồng thời tại các rạp lớn trên toàn quốc."},{"type":"compound","zh":"由于设备出了故障，所以电影推迟了半小时放映。","pinyin":"Yóuyú shèbèi chūle gùzhàng, suǒyǐ diànyǐng tuīchíle bànxiǎoshí fàngyìng.","vi":"Do thiết bị gặp sự cố nên phim bị lùi nửa tiếng mới chiếu."}],"related":[{"hanzi":"上映","pinyin":"shàngyìng","vi":"công chiếu"},{"hanzi":"电影院","pinyin":"diànyǐngyuàn","vi":"rạp chiếu phim"},{"hanzi":"首映","pinyin":"shǒuyìng","vi":"buổi chiếu ra mắt"},{"hanzi":"播放","pinyin":"bōfàng","vi":"phát (video)"}]},{"id":"放置","hanzi":"放置","pinyin":"fàngzhì","meaning_vi":"đặt, để, bố trí","explanation":"放 (phóng – đặt) + 置 (trí – để vào) → đặt vật vào một chỗ nhất định; mang sắc thái văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"请勿随意放置物品。","pinyin":"Qǐngwù suíyì fàngzhì wùpǐn.","vi":"Vui lòng không để đồ tùy tiện."},{"type":"simple","zh":"药品应放置在儿童拿不到的地方。","pinyin":"Yàopǐn yīng fàngzhì zài értóng ná budào de dìfang.","vi":"Thuốc nên được để ở nơi trẻ em không với tới."},{"type":"compound","zh":"如果蛋糕放置时间太长，就会变干变硬。","pinyin":"Rúguǒ dàngāo fàngzhì shíjiān tài cháng, jiù huì biàn gān biànyìng.","vi":"Nếu để bánh kem quá lâu, nó sẽ bị khô và cứng."}],"related":[{"hanzi":"安放","pinyin":"ānfàng","vi":"đặt yên"},{"hanzi":"摆放","pinyin":"bǎifàng","vi":"bày đặt"},{"hanzi":"搁置","pinyin":"gēzhì","vi":"gác lại"},{"hanzi":"位置","pinyin":"wèizhi","vi":"vị trí"}]},{"id":"放纵","hanzi":"放纵","pinyin":"fàngzòng","meaning_vi":"buông thả, nuông chiều, dung túng","explanation":"放 (phóng – buông) + 纵 (túng – thả lỏng) → buông lỏng, không kiềm chế bản thân hoặc dung túng người khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍷","examples":[{"type":"basic","zh":"别太放纵自己。","pinyin":"Bié tài fàngzòng zìjǐ.","vi":"Đừng quá buông thả bản thân."},{"type":"simple","zh":"父母过分放纵孩子，只会害了他们。","pinyin":"Fùmǔ guòfèn fàngzòng háizi, zhǐ huì hàile tāmen.","vi":"Cha mẹ quá nuông chiều con cái chỉ làm hại chúng."},{"type":"compound","zh":"偶尔放纵一下没关系，但是长期这样身体会受不了。","pinyin":"Ǒu'ěr fàngzòng yíxià méiguānxi, dànshì chángqī zhèyàng shēn tǐhuì shòubuliǎo.","vi":"Thỉnh thoảng buông thả một chút không sao, nhưng kéo dài như vậy cơ thể sẽ không chịu nổi."}],"related":[{"hanzi":"纵容","pinyin":"zòngróng","vi":"dung túng"},{"hanzi":"放任","pinyin":"fàngrèn","vi":"mặc kệ"},{"hanzi":"克制","pinyin":"kèzhì","vi":"kiềm chế"},{"hanzi":"放肆","pinyin":"fàngsì","vi":"càn rỡ"}],"traditional":"放縱"},{"id":"飞往","hanzi":"飞往","pinyin":"fēiwǎng","meaning_vi":"bay đến, bay tới","explanation":"飞 (phi – bay) + 往 (vãng – hướng tới) → bay về phía một nơi nào đó.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"✈️","examples":[{"type":"basic","zh":"航班飞往北京。","pinyin":"Hángbān fēiwǎng Běijīng.","vi":"Chuyến bay bay đến Bắc Kinh."},{"type":"simple","zh":"他今晚就要飞往伦敦参加会议。","pinyin":"Tā jīnwǎn jiùyào fēiwǎng Lúndūn cānjiā huìyì.","vi":"Tối nay anh ấy sẽ bay sang London dự hội nghị."},{"type":"compound","zh":"因为大雾天气，所以飞往上海的航班全部延误了。","pinyin":"Yīnwèi dàwù tiānqì, suǒyǐ fēiwǎng Shànghǎi de hángbān quánbù yánwù le.","vi":"Vì trời sương mù dày nên các chuyến bay đến Thượng Hải đều bị hoãn."}],"related":[{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"},{"hanzi":"飞机","pinyin":"fēijī","vi":"máy bay"},{"hanzi":"航班","pinyin":"hángbān","vi":"chuyến bay"},{"hanzi":"开往","pinyin":"kāiwǎng","vi":"chạy đến"}],"traditional":"飛往"},{"id":"非金属","hanzi":"非金属","pinyin":"fēijīnshǔ","meaning_vi":"phi kim","explanation":"非 (phi – không phải) + 金属 (kim thuộc – kim loại) → nguyên tố hoặc vật liệu không phải kim loại.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧪","examples":[{"type":"basic","zh":"氧是非金属元素。","pinyin":"Yǎng shìfēi jīnshǔ yuánsù.","vi":"Oxy là nguyên tố phi kim."},{"type":"simple","zh":"大多数非金属都不容易导电。","pinyin":"Dàduōshù fēijīnshǔ dōu bù róngyì dǎodiàn.","vi":"Đa số phi kim đều không dễ dẫn điện."},{"type":"compound","zh":"虽然碳是非金属，但是石墨却能导电。","pinyin":"Suīrán tàn shìfēi jīnshǔ, dànshì shímò què néng dǎodiàn.","vi":"Tuy cacbon là phi kim nhưng than chì lại dẫn điện được."}],"related":[{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"},{"hanzi":"元素","pinyin":"yuánsù","vi":"nguyên tố"},{"hanzi":"化学","pinyin":"huàxué","vi":"hóa học"},{"hanzi":"导体","pinyin":"dǎotǐ","vi":"chất dẫn điện"}],"traditional":"非金屬"},{"id":"肥料","hanzi":"肥料","pinyin":"féiliào","meaning_vi":"phân bón","explanation":"肥 (phì – màu mỡ) + 料 (liệu – vật liệu) → chất bón làm đất màu mỡ, giúp cây lớn.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"给花施点肥料。","pinyin":"Gěi huā shī diǎn féiliào.","vi":"Bón ít phân cho hoa."},{"type":"simple","zh":"农民们正在往地里撒有机肥料。","pinyin":"Nóngmínmen zhèngzài wǎng dì lǐ sǎ yǒujī féiliào.","vi":"Nông dân đang rải phân hữu cơ xuống ruộng."},{"type":"compound","zh":"肥料虽然能提高产量，但是用多了会污染土壤。","pinyin":"Féiliào suīrán néng tígāo chǎnliàng, dànshì yòng duōle huì wūrǎn tǔrǎng.","vi":"Phân bón tuy giúp tăng sản lượng nhưng dùng nhiều sẽ gây ô nhiễm đất."}],"related":[{"hanzi":"化肥","pinyin":"huàféi","vi":"phân hóa học"},{"hanzi":"施肥","pinyin":"shīféi","vi":"bón phân"},{"hanzi":"肥沃","pinyin":"féiwò","vi":"màu mỡ"},{"hanzi":"农药","pinyin":"nóngyào","vi":"thuốc trừ sâu"}]},{"id":"肥胖","hanzi":"肥胖","pinyin":"féipàng","meaning_vi":"béo phì, mập","explanation":"肥 (phì – béo) + 胖 (bàn – mập) → cơ thể tích quá nhiều mỡ, béo phì.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🍔","examples":[{"type":"basic","zh":"肥胖影响健康。","pinyin":"Féipàng yǐngxiǎng jiànkāng.","vi":"Béo phì ảnh hưởng đến sức khỏe."},{"type":"simple","zh":"儿童肥胖问题越来越受到社会关注。","pinyin":"Értóng féipàng wèntí yuèláiyuè shòudào shèhuì guānzhù.","vi":"Vấn đề béo phì ở trẻ em ngày càng được xã hội quan tâm."},{"type":"compound","zh":"如果长期吃快餐又不运动，就很容易导致肥胖。","pinyin":"Rúguǒ chángqī chī kuàicān yòu bú yùndòng, jiù hěn róngyì dǎozhì féipàng.","vi":"Nếu ăn đồ ăn nhanh lâu dài lại không vận động thì rất dễ dẫn đến béo phì."}],"related":[{"hanzi":"胖","pinyin":"pàng","vi":"béo"},{"hanzi":"苗条","pinyin":"miáotiao","vi":"thon thả"},{"hanzi":"减肥","pinyin":"jiǎnféi","vi":"giảm cân"},{"hanzi":"超重","pinyin":"chāozhòng","vi":"thừa cân"}]},{"id":"废","hanzi":"废","pinyin":"fèi","meaning_vi":"bỏ, phế bỏ; hỏng, vô dụng","explanation":"废 (phế – bỏ đi, hỏng) → bỏ không dùng nữa, hoặc trở nên vô dụng; dùng trong 废除, 废话, 废品.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"这张纸写废了。","pinyin":"Zhè zhāng zhǐ xiě fèi le.","vi":"Tờ giấy này viết hỏng rồi."},{"type":"simple","zh":"那条旧铁路早就废了，现在长满了草。","pinyin":"Nà tiáo jiù tiělù zǎojiù fèi le, xiànzài zhǎngmǎnle cǎo.","vi":"Tuyến đường sắt cũ ấy đã bỏ từ lâu, giờ cỏ mọc đầy."},{"type":"compound","zh":"如果这只手再受伤，他的运动生涯可能就废了。","pinyin":"Rúguǒ zhè zhī shǒu zài shòushāng, tā de yùndòng shēngyá kěnéng jiù fèi le.","vi":"Nếu bàn tay này lại bị thương, sự nghiệp thể thao của anh ấy có thể tiêu tan."}],"related":[{"hanzi":"废除","pinyin":"fèichú","vi":"bãi bỏ"},{"hanzi":"废话","pinyin":"fèihuà","vi":"lời thừa"},{"hanzi":"废品","pinyin":"fèipǐn","vi":"phế phẩm"},{"hanzi":"报废","pinyin":"bàofèi","vi":"thanh lý, loại bỏ"}],"traditional":"廢"},{"id":"废物","hanzi":"废物","pinyin":"fèiwù","meaning_vi":"phế liệu, đồ bỏ đi; kẻ vô dụng","explanation":"废 (phế – bỏ đi) + 物 (vật – đồ vật) → đồ vật bỏ đi; khẩu ngữ dùng để mắng người vô dụng.","hsk_level":"7-9","tags":["danh-tu"],"image":"♻️","examples":[{"type":"basic","zh":"废物可以回收。","pinyin":"Fèiwù kěyǐ huíshōu.","vi":"Phế liệu có thể tái chế."},{"type":"simple","zh":"工厂排放的废物必须经过处理。","pinyin":"Gōngchǎng páifàng de fèiwù bìxū jīngguò chǔlǐ.","vi":"Chất thải nhà máy thải ra phải được xử lý."},{"type":"compound","zh":"即使别人骂你是废物，你也要用行动证明自己。","pinyin":"Jíshǐ biérén mà nǐ shì fèiwù, nǐ yě yào yòng xíngdòng zhèngmíng zìjǐ.","vi":"Dù người khác mắng bạn là đồ vô dụng, bạn cũng phải dùng hành động chứng minh bản thân."}],"related":[{"hanzi":"垃圾","pinyin":"lājī","vi":"rác"},{"hanzi":"废品","pinyin":"fèipǐn","vi":"phế phẩm"},{"hanzi":"废料","pinyin":"fèiliào","vi":"phế liệu"},{"hanzi":"回收","pinyin":"huíshōu","vi":"thu hồi, tái chế"}],"traditional":"廢物"},{"id":"沸沸扬扬","hanzi":"沸沸扬扬","pinyin":"fèifèi-yángyáng","meaning_vi":"xôn xao, ồn ào khắp nơi","explanation":"沸 (phí – sôi) + 扬 (dương – bốc lên), lặp lại → như nước sôi sùng sục; ví lời bàn tán lan truyền rầm rộ.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"这事闹得沸沸扬扬。","pinyin":"Zhè shì nào de fèifèiyángyáng.","vi":"Chuyện này làm ầm ĩ khắp nơi."},{"type":"simple","zh":"明星离婚的消息在网上传得沸沸扬扬。","pinyin":"Míngxīng líhūn de xiāoxi zài wǎng shàngchuán de fèifèiyángyáng.","vi":"Tin ngôi sao ly hôn lan truyền xôn xao trên mạng."},{"type":"compound","zh":"虽然外面传得沸沸扬扬，但是当事人始终没有回应。","pinyin":"Suīrán wàimiàn chuán de fèifèiyángyáng, dànshì dāngshìrén shǐzhōng méiyǒu huíyìng.","vi":"Tuy bên ngoài đồn ầm ĩ nhưng người trong cuộc trước sau vẫn không lên tiếng."}],"related":[{"hanzi":"满城风雨","pinyin":"mǎnchéngfēngyǔ","vi":"xôn xao khắp thành"},{"hanzi":"议论纷纷","pinyin":"yìlùnfēnfēn","vi":"bàn tán xôn xao"},{"hanzi":"沸腾","pinyin":"fèiténg","vi":"sôi sục"},{"hanzi":"风波","pinyin":"fēngbō","vi":"sóng gió"}],"traditional":"沸沸揚揚"},{"id":"费劲","hanzi":"费劲","pinyin":"fèijìn","meaning_vi":"tốn sức, vất vả","explanation":"费 (phí – tiêu tốn) + 劲 (kình – sức lực) → tốn nhiều sức lực mới làm được.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😓","examples":[{"type":"basic","zh":"搬这个箱子真费劲。","pinyin":"Bān zhè ge xiāngzi zhēn fèijìn.","vi":"Bê cái thùng này thật tốn sức."},{"type":"simple","zh":"他说话口音很重，听起来有点费劲。","pinyin":"Tā shuōhuà kǒuyīn hěn zhòng, tīngqǐlái yǒudiǎn fèijìn.","vi":"Anh ấy nói giọng địa phương nặng, nghe hơi vất vả."},{"type":"compound","zh":"既然这么费劲也修不好，不如直接买个新的。","pinyin":"Jìrán zhème fèijìn yě xiū bu hǎo, bùrú zhíjiē mǎi ge xīn de.","vi":"Đã tốn sức thế mà vẫn không sửa được thì chi bằng mua luôn cái mới."}],"related":[{"hanzi":"吃力","pinyin":"chīlì","vi":"vất vả"},{"hanzi":"费力","pinyin":"fèilì","vi":"tốn sức"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhàng"},{"hanzi":"力气","pinyin":"lìqi","vi":"sức lực"}],"traditional":"費勁"},{"id":"分割","hanzi":"分割","pinyin":"fēngē","meaning_vi":"chia cắt, phân chia","explanation":"分 (phân – chia) + 割 (cát – cắt) → cắt ra thành nhiều phần; dùng cho tài sản, lãnh thổ hoặc mối quan hệ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔪","examples":[{"type":"basic","zh":"财产要怎么分割？","pinyin":"Cáichǎn yào zěnme fēngē?","vi":"Tài sản phải chia thế nào?"},{"type":"simple","zh":"一条小河把村子分割成东西两部分。","pinyin":"Yì tiáo xiǎohé bǎ cūnzi fēngē chéng dōngxī liǎng bùfen.","vi":"Một con sông nhỏ chia làng thành hai phần đông và tây."},{"type":"compound","zh":"虽然两国被战争分割了多年，但是人民的感情没有断。","pinyin":"Suīrán liǎngguó bèi zhànzhēng fēngēle duōnián, dànshì rénmín de gǎnqíng méiyǒu duàn.","vi":"Tuy hai nước bị chiến tranh chia cắt nhiều năm nhưng tình cảm nhân dân không đứt đoạn."}],"related":[{"hanzi":"划分","pinyin":"huàfēn","vi":"phân chia"},{"hanzi":"切割","pinyin":"qiēgē","vi":"cắt"},{"hanzi":"分开","pinyin":"fēnkāi","vi":"tách ra"},{"hanzi":"不可分割","pinyin":"bùkěfēngē","vi":"không thể tách rời"}]},{"id":"分化","hanzi":"分化","pinyin":"fēnhuà","meaning_vi":"phân hóa, chia rẽ","explanation":"分 (phân – chia) + 化 (hóa – biến đổi) → từ một khối thống nhất biến đổi thành nhiều phần khác nhau.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🔀","examples":[{"type":"basic","zh":"贫富分化很严重。","pinyin":"Pínfù fēnhuà hěn yánzhòng.","vi":"Phân hóa giàu nghèo rất nghiêm trọng."},{"type":"simple","zh":"敌人想用金钱分化我们的队伍。","pinyin":"Dírén xiǎng yòng jīnqián fēnhuà wǒmen de duìwu.","vi":"Kẻ địch muốn dùng tiền để chia rẽ hàng ngũ chúng ta."},{"type":"compound","zh":"随着经济快速发展，城乡之间的分化也越来越明显。","pinyin":"Suízhe jīngjì kuàisù fāzhǎn, chéngxiāng zhījiān de fēnhuà yě yuèláiyuè míngxiǎn.","vi":"Cùng với kinh tế phát triển nhanh, sự phân hóa giữa thành thị và nông thôn cũng ngày càng rõ."}],"related":[{"hanzi":"分裂","pinyin":"fēnliè","vi":"phân liệt"},{"hanzi":"两极分化","pinyin":"liǎngjífēnhuà","vi":"phân hóa hai cực"},{"hanzi":"差距","pinyin":"chājù","vi":"khoảng cách"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"}]},{"id":"分赃","hanzi":"分赃","pinyin":"fēnzāng","meaning_vi":"chia của ăn cắp, chia chác","explanation":"分 (phân – chia) + 赃 (tang – của phi pháp) → chia nhau tài sản có được do phạm pháp.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"💰","examples":[{"type":"basic","zh":"小偷们在分赃。","pinyin":"Xiǎotōumen zài fēnzāng.","vi":"Bọn trộm đang chia của."},{"type":"simple","zh":"两名劫匪因为分赃不均打了起来。","pinyin":"Liǎng míng jiéfěi yīnwèi fēnzāng bùjūn dǎle qǐlái.","vi":"Hai tên cướp vì chia chác không đều mà đánh nhau."},{"type":"compound","zh":"他们刚躲进仓库准备分赃，警察就冲了进来。","pinyin":"Tāmen gāng duǒ jìn cāngkù zhǔnbèi fēnzāng, jǐngchá jiù chōngle jìnlái.","vi":"Chúng vừa trốn vào kho định chia của thì cảnh sát đã ập vào."}],"related":[{"hanzi":"赃款","pinyin":"zāngkuǎn","vi":"tiền bẩn"},{"hanzi":"赃物","pinyin":"zāngwù","vi":"tang vật"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"抢劫","pinyin":"qiǎngjié","vi":"cướp"}],"traditional":"分贓"},{"id":"芬芳","hanzi":"芬芳","pinyin":"fēnfāng","meaning_vi":"thơm ngát, hương thơm","explanation":"芬 (phân – thơm) + 芳 (phương – hương thơm) → mùi thơm dễ chịu của hoa cỏ; mang sắc thái văn chương.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌸","examples":[{"type":"basic","zh":"花园里一片芬芳。","pinyin":"Huāyuán lǐ yípiàn fēnfāng.","vi":"Khu vườn ngào ngạt hương thơm."},{"type":"simple","zh":"春天的空气里弥漫着芬芳的花香。","pinyin":"Chūntiān de kōngqì lǐ mímànzhe fēnfāng de huāxiāng.","vi":"Không khí mùa xuân lan tỏa hương hoa thơm ngát."},{"type":"compound","zh":"虽然这种花并不起眼，但是它的香气十分芬芳。","pinyin":"Suīrán zhè zhǒnghuā bìngbù qǐyǎn, dànshì tā de xiāngqì shífēn fēnfāng.","vi":"Tuy loài hoa này không bắt mắt nhưng hương của nó vô cùng thơm ngát."}],"related":[{"hanzi":"芳香","pinyin":"fāngxiāng","vi":"hương thơm"},{"hanzi":"香气","pinyin":"xiāngqì","vi":"mùi thơm"},{"hanzi":"清香","pinyin":"qīngxiāng","vi":"thơm thoang thoảng"},{"hanzi":"臭","pinyin":"chòu","vi":"thối"}]},{"id":"氛围","hanzi":"氛围","pinyin":"fēnwéi","meaning_vi":"bầu không khí, không khí","explanation":"氛 (phân – khí, không khí) + 围 (vi – bao quanh) → bầu không khí bao trùm một nơi hoặc một sự kiện.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🕯️","examples":[{"type":"basic","zh":"节日氛围很浓。","pinyin":"Jiérì fēnwéi hěn nóng.","vi":"Không khí ngày lễ rất đậm đà."},{"type":"simple","zh":"这家咖啡馆安静的氛围很适合看书。","pinyin":"Zhè jiā kāfēiguǎn ānjìng de fēnwéi hěn shìhé kànshū.","vi":"Bầu không khí yên tĩnh của quán cà phê này rất hợp để đọc sách."},{"type":"compound","zh":"只要团队里有轻松的氛围，大家的工作效率就会提高。","pinyin":"Zhǐyào tuánduì lǐ yǒu qīngsōng de fēnwéi, dàjiā de gōngzuò xiàolǜ jiù huì tígāo.","vi":"Chỉ cần nhóm có bầu không khí thoải mái thì hiệu suất làm việc sẽ tăng."}],"related":[{"hanzi":"气氛","pinyin":"qìfēn","vi":"bầu không khí"},{"hanzi":"环境","pinyin":"huánjìng","vi":"môi trường"},{"hanzi":"情调","pinyin":"qíngdiào","vi":"phong vị, không khí"},{"hanzi":"气场","pinyin":"qìchǎng","vi":"khí chất"}],"traditional":"氛圍"},{"id":"坟","hanzi":"坟","pinyin":"fén","meaning_vi":"mộ, mồ mả","explanation":"坟 (phần – mộ) → gò đất đắp lên chỗ chôn người chết.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🪦","examples":[{"type":"basic","zh":"这是爷爷的坟。","pinyin":"Zhè shì yéye de fén.","vi":"Đây là mộ của ông nội."},{"type":"simple","zh":"清明节我们回老家给祖先上坟。","pinyin":"Qīngmíngjié wǒmen huílǎojiā gěi zǔxiān shàngfén.","vi":"Tết Thanh minh chúng tôi về quê tảo mộ tổ tiên."},{"type":"compound","zh":"虽然老人去世多年，但是村里人每年都帮他扫坟。","pinyin":"Suīrán lǎorén qùshì duōnián, dànshì cūn lǐrén měinián dōu bāng tā sǎo fén.","vi":"Tuy cụ đã mất nhiều năm nhưng năm nào người trong làng cũng giúp quét mộ cho cụ."}],"related":[{"hanzi":"坟墓","pinyin":"fénmù","vi":"mồ mả"},{"hanzi":"上坟","pinyin":"shàngfén","vi":"viếng mộ"},{"hanzi":"墓地","pinyin":"mùdì","vi":"nghĩa địa"},{"hanzi":"公墓","pinyin":"gōngmù","vi":"nghĩa trang"}],"traditional":"墳"},{"id":"粉","hanzi":"粉","pinyin":"fěn","meaning_vi":"bột; phấn; bún, miến; màu hồng","explanation":"粉 (phấn – bột mịn) → chất dạng bột; còn chỉ phấn trang điểm, món bún/miến làm từ bột và màu hồng phấn.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍜","examples":[{"type":"basic","zh":"我想吃一碗米粉。","pinyin":"Wǒ xiǎng chī yì wǎn mǐfěn.","vi":"Tôi muốn ăn một bát bún gạo."},{"type":"simple","zh":"她在脸上薄薄地扑了一层粉。","pinyin":"Tā zài liǎn shang báo báode pūle yīcéng fěn.","vi":"Cô ấy đánh một lớp phấn mỏng lên mặt."},{"type":"compound","zh":"如果面粉太湿，就再加点干粉揉一揉。","pinyin":"Rúguǒ miànfěn tài shī, jiù zài jiādiǎn gānfěn róu yi róu.","vi":"Nếu bột mì ướt quá thì thêm chút bột khô rồi nhào lại."}],"related":[{"hanzi":"面粉","pinyin":"miànfěn","vi":"bột mì"},{"hanzi":"米粉","pinyin":"mǐfěn","vi":"bún gạo"},{"hanzi":"粉色","pinyin":"fěnsè","vi":"màu hồng"},{"hanzi":"粉末","pinyin":"fěnmò","vi":"bột"}]},{"id":"粉丝","hanzi":"粉丝","pinyin":"fěnsī","meaning_vi":"người hâm mộ, fan; miến","explanation":"粉 (phấn – bột) + 丝 (ti – sợi) → sợi miến làm từ bột đậu; do đồng âm với \"fans\" nên nay chủ yếu chỉ người hâm mộ.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🤩","examples":[{"type":"basic","zh":"她有很多粉丝。","pinyin":"Tā yǒu hěn duō fěnsī.","vi":"Cô ấy có rất nhiều người hâm mộ."},{"type":"simple","zh":"上千名粉丝在机场等着偶像出现。","pinyin":"Shàng qiān míng fěnsī zài jīchǎng děngzhe ǒuxiàng chūxiàn.","vi":"Hàng nghìn người hâm mộ chờ thần tượng xuất hiện ở sân bay."},{"type":"compound","zh":"虽然他的粉丝不算多，但是每个人都非常忠实。","pinyin":"Suīrán tā de fěnsī búsuàn duō, dànshì měigerén dōu fēicháng zhōngshí.","vi":"Tuy người hâm mộ của anh ấy không nhiều nhưng ai cũng rất trung thành."}],"related":[{"hanzi":"偶像","pinyin":"ǒuxiàng","vi":"thần tượng"},{"hanzi":"追星","pinyin":"zhuīxīng","vi":"đu thần tượng"},{"hanzi":"粉丝团","pinyin":"fěnsītuán","vi":"fan club"},{"hanzi":"明星","pinyin":"míngxīng","vi":"ngôi sao"}],"traditional":"粉絲"},{"id":"份额","hanzi":"份额","pinyin":"fèn'é","meaning_vi":"thị phần, phần, tỷ lệ","explanation":"份 (phần – phần chia) + 额 (ngạch – mức định) → phần được chia hoặc chiếm giữ trong tổng thể; hay dùng trong 市场份额.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🥧","examples":[{"type":"basic","zh":"我们的市场份额增加了。","pinyin":"Wǒmen de shìchǎngfèn'é zēngjiā le.","vi":"Thị phần của chúng ta đã tăng."},{"type":"simple","zh":"这家公司占据了国内手机市场三成的份额。","pinyin":"Zhè jiā gōngsī zhànjùle guónèi shǒujī shìchǎng sān chéng de fèn'é.","vi":"Công ty này chiếm ba mươi phần trăm thị phần điện thoại trong nước."},{"type":"compound","zh":"如果不及时推出新产品，我们的份额就会被对手抢走。","pinyin":"Rúguǒ bù jíshí tuīchū xīnchǎnpǐn, wǒmen de fèn'é jiù huì bèi duìshǒu qiǎngzǒu.","vi":"Nếu không kịp tung sản phẩm mới, thị phần của chúng ta sẽ bị đối thủ giành mất."}],"related":[{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"},{"hanzi":"比例","pinyin":"bǐlì","vi":"tỷ lệ"},{"hanzi":"股份","pinyin":"gǔfèn","vi":"cổ phần"},{"hanzi":"配额","pinyin":"pèi'é","vi":"hạn ngạch"}],"traditional":"份額"},{"id":"粪","hanzi":"粪","pinyin":"fèn","meaning_vi":"phân (động vật), cứt","explanation":"粪 (phẩn – phân) → chất thải của người, động vật; thường dùng cho phân động vật hoặc làm phân bón.","hsk_level":"7-9","tags":["danh-tu"],"image":"💩","examples":[{"type":"basic","zh":"地上有牛粪。","pinyin":"Dìshang yǒu niú fèn.","vi":"Dưới đất có phân bò."},{"type":"simple","zh":"农民把鸡粪堆在一起当作肥料。","pinyin":"Nóngmín bǎ jī fèn duī zài yìqǐ dàngzuò féiliào.","vi":"Nông dân gom phân gà lại làm phân bón."},{"type":"compound","zh":"遛狗时如果狗在路边拉粪，主人就应该马上清理。","pinyin":"Liùgǒu shí rúguǒ gǒu zài lùbiān lā fèn, zhǔrén jiù yīnggāi mǎshàng qīnglǐ.","vi":"Khi dắt chó đi dạo, nếu chó đi vệ sinh bên đường thì chủ phải dọn ngay."}],"related":[{"hanzi":"粪便","pinyin":"fènbiàn","vi":"phân"},{"hanzi":"肥料","pinyin":"féiliào","vi":"phân bón"},{"hanzi":"大便","pinyin":"dàbiàn","vi":"đi ngoài"},{"hanzi":"尿","pinyin":"niào","vi":"nước tiểu"}],"traditional":"糞"},{"id":"粪便","hanzi":"粪便","pinyin":"fènbiàn","meaning_vi":"phân, chất bài tiết","explanation":"粪 (phẩn – phân) + 便 (tiện – bài tiết) → chất thải từ ruột; cách nói trang trọng, dùng trong y học.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🧻","examples":[{"type":"basic","zh":"医生要检查粪便。","pinyin":"Yīshēng yào jiǎnchá fènbiàn.","vi":"Bác sĩ cần xét nghiệm phân."},{"type":"simple","zh":"科学家通过分析粪便研究动物的饮食。","pinyin":"Kēxuéjiā tōngguò fēnxī fènbiàn yánjiū dòngwù de yǐnshí.","vi":"Các nhà khoa học nghiên cứu chế độ ăn của động vật bằng cách phân tích phân."},{"type":"compound","zh":"如果粪便颜色长期不正常，就应该尽快去医院检查。","pinyin":"Rúguǒ fènbiàn yánsè chángqī bú zhèngcháng, jiù yīnggāi jǐnkuài qù yīyuàn jiǎnchá.","vi":"Nếu màu phân bất thường kéo dài thì nên sớm đến bệnh viện kiểm tra."}],"related":[{"hanzi":"粪","pinyin":"fèn","vi":"phân"},{"hanzi":"排泄","pinyin":"páixiè","vi":"bài tiết"},{"hanzi":"大便","pinyin":"dàbiàn","vi":"đi ngoài"},{"hanzi":"小便","pinyin":"xiǎobiàn","vi":"đi tiểu"}],"traditional":"糞便"},{"id":"丰富多彩","hanzi":"丰富多彩","pinyin":"fēngfù-duōcǎi","meaning_vi":"phong phú đa dạng, muôn màu muôn vẻ","explanation":"丰富 (phong phú – dồi dào) + 多彩 (đa thải – nhiều màu) → vừa dồi dào vừa nhiều màu sắc, đa dạng hấp dẫn.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎨","examples":[{"type":"basic","zh":"校园生活丰富多彩。","pinyin":"Xiàoyuán shēnghuó fēngfùduōcǎi.","vi":"Đời sống học đường muôn màu muôn vẻ."},{"type":"simple","zh":"假期里，社区组织了丰富多彩的活动。","pinyin":"Jiàqī lǐ, shèqū zǔzhīle fēngfùduōcǎi de huódòng.","vi":"Trong kỳ nghỉ, khu dân cư tổ chức nhiều hoạt động phong phú."},{"type":"compound","zh":"退休以后，他不但没闲着，而且生活过得丰富多彩。","pinyin":"Tuìxiū yǐhòu, tā búdàn méi xiánzhe, érqiě shēnghuó guòde fēngfùduōcǎi.","vi":"Sau khi nghỉ hưu, ông không những không rảnh rỗi mà còn sống rất phong phú."}],"related":[{"hanzi":"多姿多彩","pinyin":"duōzīduōcǎi","vi":"muôn màu muôn vẻ"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"},{"hanzi":"五彩缤纷","pinyin":"wǔcǎibīnfēn","vi":"rực rỡ sắc màu"},{"hanzi":"单调","pinyin":"dāndiào","vi":"đơn điệu"}],"traditional":"豐富多彩"},{"id":"风餐露宿","hanzi":"风餐露宿","pinyin":"fēngcān-lùsù","meaning_vi":"ăn gió nằm sương, dãi dầu vất vả","explanation":"风 (phong – gió) + 餐 (xan – ăn) + 露 (lộ – sương) + 宿 (túc – ngủ) → ăn trong gió, ngủ dưới sương; chỉ cuộc sống đi đường vất vả, gian khổ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏕️","examples":[{"type":"basic","zh":"他们一路风餐露宿。","pinyin":"Tāmen yílù fēngcānlùsù.","vi":"Họ dãi gió dầm sương suốt chặng đường."},{"type":"simple","zh":"地质队员常年在野外风餐露宿。","pinyin":"Dìzhì duìyuán chángnián zài yěwài fēngcānlùsù.","vi":"Các đội viên địa chất quanh năm ăn gió nằm sương ngoài thực địa."},{"type":"compound","zh":"虽然一路上风餐露宿，但是他们终于按时到达了目的地。","pinyin":"Suīrán yílùshang fēngcānlùsù, dànshì tāmen zhōngyú ànshí dàodále mùdìdì.","vi":"Tuy suốt đường ăn gió nằm sương nhưng cuối cùng họ đã đến đích đúng hẹn."}],"related":[{"hanzi":"餐风饮露","pinyin":"cānfēngyǐnlù","vi":"ăn gió uống sương"},{"hanzi":"长途跋涉","pinyin":"chángtúbáshè","vi":"lặn lội đường xa"},{"hanzi":"艰苦","pinyin":"jiānkǔ","vi":"gian khổ"},{"hanzi":"露宿","pinyin":"lùsù","vi":"ngủ ngoài trời"}],"traditional":"風餐露宿"},{"id":"风风雨雨","hanzi":"风风雨雨","pinyin":"fēngfēng-yǔyǔ","meaning_vi":"sóng gió, thăng trầm","explanation":"风 (phong – gió) + 雨 (vũ – mưa), lặp lại → gió mưa liên tiếp; ví những gian nan, thăng trầm đã trải qua.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⛈️","examples":[{"type":"basic","zh":"我们经历了风风雨雨。","pinyin":"Wǒmen jīnglìle fēngfēngyǔyǔ.","vi":"Chúng tôi đã trải qua bao sóng gió."},{"type":"simple","zh":"这对老夫妻一起走过了五十年的风风雨雨。","pinyin":"Zhè duì lǎo fūqī yìqǐ zǒuguòle wǔshí nián de fēngfēngyǔyǔ.","vi":"Đôi vợ chồng già cùng nhau đi qua năm mươi năm thăng trầm."},{"type":"compound","zh":"无论将来还有多少风风雨雨，我们都要一起面对。","pinyin":"Wúlùn jiānglái háiyǒu duōshǎo fēngfēngyǔyǔ, wǒmen dōu yào yìqǐ miànduì.","vi":"Dù sau này còn bao nhiêu sóng gió, chúng ta cũng sẽ cùng nhau đối mặt."}],"related":[{"hanzi":"风雨","pinyin":"fēngyǔ","vi":"gió mưa, gian nan"},{"hanzi":"坎坷","pinyin":"kǎnkě","vi":"gập ghềnh"},{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"},{"hanzi":"风雨同舟","pinyin":"fēngyǔtóngzhōu","vi":"đồng cam cộng khổ"}],"traditional":"風風雨雨"},{"id":"风流","hanzi":"风流","pinyin":"fēngliú","meaning_vi":"phong lưu, tài hoa; đa tình, lăng nhăng","explanation":"风 (phong – phong thái) + 流 (lưu – dòng chảy) → phong thái tài hoa, nổi bật; nay còn chỉ người đa tình, hay trăng hoa.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🎩","examples":[{"type":"basic","zh":"他年轻时很风流。","pinyin":"Tā niánqīng shí hěn fēngliú.","vi":"Hồi trẻ ông ấy rất đào hoa."},{"type":"simple","zh":"历史上有许多风流才子留下了名篇。","pinyin":"Lìshǐshang yǒu xǔduō fēngliú cáizǐ liúxiàle míngpiān.","vi":"Trong lịch sử có nhiều tài tử phong lưu để lại tác phẩm nổi tiếng."},{"type":"compound","zh":"虽然他长得英俊又风流，可是她并不喜欢这种人。","pinyin":"Suīrán tā zhǎngde yīngjùn yòu fēngliú, kěshì tā bìngbù xǐhuan zhè zhǒng rén.","vi":"Tuy anh ta đẹp trai lại đào hoa nhưng cô ấy chẳng thích kiểu người này."}],"related":[{"hanzi":"潇洒","pinyin":"xiāosǎ","vi":"phóng khoáng"},{"hanzi":"花心","pinyin":"huāxīn","vi":"lăng nhăng"},{"hanzi":"才子","pinyin":"cáizǐ","vi":"tài tử"},{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"}],"traditional":"風流"},{"id":"风情","hanzi":"风情","pinyin":"fēngqíng","meaning_vi":"phong tình, phong vị, nét duyên","explanation":"风 (phong – phong tục, phong thái) + 情 (tình – tình cảm, tình trạng) → nét riêng của một vùng (异国风情) hoặc vẻ duyên dáng quyến rũ.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💃","examples":[{"type":"basic","zh":"这里充满异国风情。","pinyin":"Zhèlǐ chōngmǎn yìguó fēngqíng.","vi":"Nơi này đậm chất phong vị nước ngoài."},{"type":"simple","zh":"古镇的小巷保留着浓浓的江南风情。","pinyin":"Gǔzhèn de xiǎoxiàng bǎoliúzhe nóng nóng de Jiāngnán fēngqíng.","vi":"Những con hẻm của thị trấn cổ giữ đậm phong vị Giang Nam."},{"type":"compound","zh":"如果你想感受当地风情，就去早市逛一逛吧。","pinyin":"Rúguǒ nǐ xiǎng gǎnshòu dāngdì fēngqíng, jiù qù zǎoshì guàng yi guàng ba.","vi":"Nếu bạn muốn cảm nhận phong vị địa phương thì hãy đi dạo chợ sáng."}],"related":[{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"风土人情","pinyin":"fēngtǔrénqíng","vi":"phong thổ nhân tình"},{"hanzi":"风光","pinyin":"fēngguāng","vi":"phong cảnh"},{"hanzi":"韵味","pinyin":"yùnwèi","vi":"nét duyên"}],"traditional":"風情"},{"id":"风沙","hanzi":"风沙","pinyin":"fēngshā","meaning_vi":"gió cát, bão cát","explanation":"风 (phong – gió) + 沙 (sa – cát) → cát bị gió cuốn bay, thường gặp ở vùng sa mạc.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"🌪️","examples":[{"type":"basic","zh":"今天风沙很大。","pinyin":"Jīntiān fēngshā hěn dà.","vi":"Hôm nay gió cát rất to."},{"type":"simple","zh":"春天北方常有风沙，出门最好戴口罩。","pinyin":"Chūntiān běifāng chángyǒu fēngshā, chūmén zuìhǎo dài kǒuzhào.","vi":"Mùa xuân miền bắc thường có gió cát, ra đường tốt nhất nên đeo khẩu trang."},{"type":"compound","zh":"为了挡住风沙，村民们在沙漠边上种了大片树林。","pinyin":"Wèile dǎngzhù fēngshā, cūnmínmen zài shāmò biānshang zhòngle dàpiàn shùlín.","vi":"Để chắn gió cát, dân làng trồng rừng cây lớn ở rìa sa mạc."}],"related":[{"hanzi":"沙尘暴","pinyin":"shāchénbào","vi":"bão cát"},{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"风暴","pinyin":"fēngbào","vi":"bão tố"},{"hanzi":"尘土","pinyin":"chéntǔ","vi":"bụi đất"}],"traditional":"風沙"},{"id":"风水","hanzi":"风水","pinyin":"fēngshuǐ","meaning_vi":"phong thủy","explanation":"风 (phong – gió) + 水 (thủy – nước) → thuật xem hướng gió, dòng nước để chọn chỗ đặt nhà, đặt mộ.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧭","examples":[{"type":"basic","zh":"这块地风水好。","pinyin":"Zhè kuài dì fēngshuǐ hǎo.","vi":"Mảnh đất này phong thủy tốt."},{"type":"simple","zh":"很多人买房前会请人看看风水。","pinyin":"Hěn duō rén mǎifáng qián huì qǐng rén kànkan fēngshuǐ.","vi":"Nhiều người trước khi mua nhà sẽ mời người xem phong thủy."},{"type":"compound","zh":"虽然他不太相信风水，但是还是按照家人的意思调整了大门。","pinyin":"Suīrán tā bú tài xiāngxìn fēngshuǐ, dànshì háishi ànzhào jiārén de yìsi tiáozhěngle dàmén.","vi":"Tuy không tin lắm vào phong thủy nhưng anh ấy vẫn sửa lại cổng theo ý gia đình."}],"related":[{"hanzi":"风水先生","pinyin":"fēngshuǐxiānsheng","vi":"thầy phong thủy"},{"hanzi":"算命","pinyin":"suànmìng","vi":"xem bói"},{"hanzi":"朝向","pinyin":"cháoxiàng","vi":"hướng nhà"},{"hanzi":"迷信","pinyin":"míxìn","vi":"mê tín"}],"traditional":"風水"},{"id":"风雨","hanzi":"风雨","pinyin":"fēngyǔ","meaning_vi":"gió mưa; gian nan, thử thách","explanation":"风 (phong – gió) + 雨 (vũ – mưa) → gió và mưa; nghĩa bóng là khó khăn, gian khổ.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"🌧️","examples":[{"type":"basic","zh":"风雨越来越大了。","pinyin":"Fēngyǔ yuèláiyuè dà le.","vi":"Gió mưa ngày càng lớn."},{"type":"simple","zh":"他不顾风雨，按时把快递送到了客户手里。","pinyin":"Tā búgù fēngyǔ, ànshí bǎ kuài dìsòng dàole kèhù shǒulǐ.","vi":"Bất chấp gió mưa, anh ấy giao hàng đến tay khách đúng giờ."},{"type":"compound","zh":"不经历风雨，怎么能见到彩虹呢？","pinyin":"Bù jīnglì fēngyǔ, zěnme néng jiàndào cǎihóng ne?","vi":"Không trải qua gió mưa, sao có thể thấy cầu vồng?"}],"related":[{"hanzi":"风风雨雨","pinyin":"fēngfēngyǔyǔ","vi":"sóng gió thăng trầm"},{"hanzi":"暴风雨","pinyin":"bàofēngyǔ","vi":"mưa bão"},{"hanzi":"风雨无阻","pinyin":"fēngyǔwúzǔ","vi":"mưa gió không cản"},{"hanzi":"艰难","pinyin":"jiānnán","vi":"gian nan"}],"traditional":"風雨"},{"id":"风云","hanzi":"风云","pinyin":"fēngyún","meaning_vi":"gió mây; thời cuộc biến động","explanation":"风 (phong – gió) + 云 (vân – mây) → gió và mây thay đổi khó lường; ví tình thế biến động hoặc nhân vật nổi bật (风云人物).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌥️","examples":[{"type":"basic","zh":"他是商界风云人物。","pinyin":"Tā shì shāngjiè fēngyún rénwù.","vi":"Ông ấy là nhân vật nổi đình đám trong giới kinh doanh."},{"type":"simple","zh":"国际风云变幻，各国都在调整政策。","pinyin":"Guójì fēngyún biànhuàn, gè guódōu zài tiáozhěng zhèngcè.","vi":"Thời cuộc quốc tế biến đổi, các nước đều đang điều chỉnh chính sách."},{"type":"compound","zh":"天有不测风云，所以出门最好随身带把伞。","pinyin":"Tiān yǒu búcè fēngyún, suǒyǐ chūmén zuìhǎo suíshēndài bǎ sǎn.","vi":"Trời có gió mây khó lường nên ra ngoài tốt nhất mang theo ô."}],"related":[{"hanzi":"风云人物","pinyin":"fēngyúnrénwù","vi":"nhân vật nổi bật"},{"hanzi":"风云变幻","pinyin":"fēngyúnbiànhuàn","vi":"thời thế biến đổi"},{"hanzi":"局势","pinyin":"júshì","vi":"cục diện"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình thế"}],"traditional":"風雲"},{"id":"风筝","hanzi":"风筝","pinyin":"fēngzheng","meaning_vi":"con diều","explanation":"风 (phong – gió) + 筝 (tranh – đàn tranh) → xưa diều gắn sáo, gió thổi kêu như đàn; nay chỉ con diều.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🪁","examples":[{"type":"basic","zh":"孩子们在放风筝。","pinyin":"Háizimen zài fàngfēngzheng.","vi":"Bọn trẻ đang thả diều."},{"type":"simple","zh":"爷爷亲手给我做了一只燕子风筝。","pinyin":"Yéye qīnshǒu gěi wǒ zuòle yì zhī yànzi fēngzheng.","vi":"Ông nội tự tay làm cho tôi một con diều hình chim én."},{"type":"compound","zh":"只要风够大，风筝就能飞得又高又稳。","pinyin":"Zhǐyào fēng gòu dà, fēngzheng jiù néng fēi de yòu gāo yòu wěn.","vi":"Chỉ cần gió đủ mạnh, diều sẽ bay vừa cao vừa vững."}],"related":[{"hanzi":"放风筝","pinyin":"fàngfēngzheng","vi":"thả diều"},{"hanzi":"线","pinyin":"xiàn","vi":"sợi dây"},{"hanzi":"风车","pinyin":"fēngchē","vi":"chong chóng"},{"hanzi":"纸鸢","pinyin":"zhǐyuān","vi":"diều giấy"}],"traditional":"風箏"},{"id":"疯子","hanzi":"疯子","pinyin":"fēngzi","meaning_vi":"người điên, kẻ khùng","explanation":"疯 (phong – điên) + 子 (tử – hậu tố) → người bị điên; cũng dùng nói đùa người làm việc liều lĩnh, cuồng nhiệt.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤪","examples":[{"type":"basic","zh":"他简直是个疯子。","pinyin":"Tā jiǎnzhí shì ge fēngzi.","vi":"Hắn đúng là đồ điên."},{"type":"simple","zh":"大家都把这个工作狂叫做“技术疯子”。","pinyin":"Dàjiā dōu bǎ zhè ge gōngzuòkuáng jiàozuò \"jìshù fēngzi\".","vi":"Mọi người gọi người cuồng việc này là \"kẻ điên kỹ thuật\"."},{"type":"compound","zh":"当初大家都说他是疯子，可是后来他真的成功了。","pinyin":"Dāngchū dàjiā dōu shuō tā shì fēngzi, kěshì hòulái tā zhēn de chénggōng le.","vi":"Hồi đầu ai cũng bảo anh ấy là kẻ điên, nhưng về sau anh ấy thật sự thành công."}],"related":[{"hanzi":"傻子","pinyin":"shǎzi","vi":"kẻ ngốc"},{"hanzi":"发疯","pinyin":"fāfēng","vi":"phát điên"},{"hanzi":"疯狂","pinyin":"fēngkuáng","vi":"điên cuồng"},{"hanzi":"精神病","pinyin":"jīngshénbìng","vi":"bệnh tâm thần"}],"traditional":"瘋子"},{"id":"蜂蜜","hanzi":"蜂蜜","pinyin":"fēngmì","meaning_vi":"mật ong","explanation":"蜂 (phong – con ong) + 蜜 (mật – mật ngọt) → mật do ong làm ra.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍯","examples":[{"type":"basic","zh":"我喝蜂蜜水。","pinyin":"Wǒ hē fēngmì shuǐ.","vi":"Tôi uống nước mật ong."},{"type":"simple","zh":"奶奶说睡前喝点蜂蜜水对嗓子好。","pinyin":"Nǎinai shuō shuì qián hē diǎn fēngmì shuǐ duì sǎngzi hǎo.","vi":"Bà nói trước khi ngủ uống chút nước mật ong tốt cho cổ họng."},{"type":"compound","zh":"蜂蜜虽然有营养，但是一岁以下的婴儿不能吃。","pinyin":"Fēngmì suīrán yǒu yíngyǎng, dànshì yí suì yǐxià de yīng'ér bù néng chī.","vi":"Mật ong tuy bổ dưỡng nhưng trẻ dưới một tuổi không được ăn."}],"related":[{"hanzi":"蜜蜂","pinyin":"mìfēng","vi":"con ong"},{"hanzi":"甜","pinyin":"tián","vi":"ngọt"},{"hanzi":"糖","pinyin":"táng","vi":"đường"},{"hanzi":"蜂巢","pinyin":"fēngcháo","vi":"tổ ong"}]},{"id":"凤凰","hanzi":"凤凰","pinyin":"fènghuáng","meaning_vi":"phượng hoàng","explanation":"凤 (phượng – chim trống) + 凰 (hoàng – chim mái) → chim thần trong truyền thuyết, tượng trưng cho điềm lành và cao quý.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🦚","examples":[{"type":"basic","zh":"凤凰是吉祥的鸟。","pinyin":"Fènghuáng shì jíxiáng de niǎo.","vi":"Phượng hoàng là loài chim điềm lành."},{"type":"simple","zh":"新娘的礼服上绣着一只金色凤凰。","pinyin":"Xīnniáng de lǐfú shang xiùzhe yì zhī jīnsè fènghuáng.","vi":"Trên lễ phục cô dâu thêu một con phượng hoàng vàng."},{"type":"compound","zh":"传说凤凰浴火之后，就能获得新生。","pinyin":"Chuánshuō fènghuáng yù huǒ zhīhòu, jiù néng huòdé xīnshēng.","vi":"Truyền thuyết kể rằng phượng hoàng sau khi tắm lửa sẽ tái sinh."}],"related":[{"hanzi":"龙","pinyin":"lóng","vi":"rồng"},{"hanzi":"麒麟","pinyin":"qílín","vi":"kỳ lân"},{"hanzi":"龙凤","pinyin":"lóngfèng","vi":"rồng phượng"},{"hanzi":"孔雀","pinyin":"kǒngquè","vi":"chim công"}],"traditional":"鳳凰"},{"id":"缝","hanzi":"缝","pinyin":"féng","meaning_vi":"khâu, may","explanation":"缝 (phùng – may vá) → dùng kim chỉ khâu lại; đọc fèng thì nghĩa là khe hở (缝隙).","hsk_level":"7-9","tags":["dong-tu","trang-phuc"],"image":"🪡","examples":[{"type":"basic","zh":"妈妈在缝扣子。","pinyin":"Māma zài féng kòuzi.","vi":"Mẹ đang khâu cúc áo."},{"type":"simple","zh":"裤子破了个洞，我自己缝了几针。","pinyin":"Kùzi pòle ge dòng, wǒ zìjǐ féngle jǐ zhēn.","vi":"Quần rách một lỗ, tôi tự khâu vài mũi."},{"type":"compound","zh":"虽然奶奶眼睛不好，但是缝的衣服还是又整齐又结实。","pinyin":"Suīrán nǎinai yǎnjing bù hǎo, dànshì féng de yīfu háishi yòu zhěngqí yòu jiēshi.","vi":"Tuy mắt bà kém nhưng quần áo bà khâu vẫn vừa đều vừa chắc."}],"related":[{"hanzi":"缝补","pinyin":"féngbǔ","vi":"may vá"},{"hanzi":"缝纫机","pinyin":"féngrènjī","vi":"máy khâu"},{"hanzi":"针线","pinyin":"zhēnxiàn","vi":"kim chỉ"},{"hanzi":"裁缝","pinyin":"cáifeng","vi":"thợ may"}],"traditional":"縫"},{"id":"缝合","hanzi":"缝合","pinyin":"fénghé","meaning_vi":"khâu lại, khâu (vết thương)","explanation":"缝 (phùng – khâu) + 合 (hợp – liền lại) → khâu cho hai mép liền lại; thường dùng trong phẫu thuật.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"伤口需要缝合。","pinyin":"Shāngkǒu xūyào fénghé.","vi":"Vết thương cần phải khâu."},{"type":"simple","zh":"医生给他缝合了手上的伤口，一共缝了五针。","pinyin":"Yīshēng gěi tā fénghéle shǒushang de shāngkǒu, yígòng féngle wǔ zhēn.","vi":"Bác sĩ khâu vết thương trên tay anh ấy, tổng cộng năm mũi."},{"type":"compound","zh":"如果伤口太深，就必须尽快到医院缝合。","pinyin":"Rúguǒ shāngkǒu tài shēn, jiù bìxū jǐnkuài dào yīyuàn fénghé.","vi":"Nếu vết thương quá sâu thì phải nhanh chóng đến bệnh viện khâu."}],"related":[{"hanzi":"拆线","pinyin":"chāixiàn","vi":"cắt chỉ"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"手术","pinyin":"shǒushù","vi":"phẫu thuật"},{"hanzi":"包扎","pinyin":"bāozā","vi":"băng bó"}],"traditional":"縫合"},{"id":"敷","hanzi":"敷","pinyin":"fū","meaning_vi":"đắp, bôi, thoa","explanation":"敷 (phu – trải, bôi lên) → bôi hoặc đắp một lớp lên bề mặt; hay dùng trong 敷面膜, 冷敷, 热敷.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🧖","examples":[{"type":"basic","zh":"她在敷面膜。","pinyin":"Tā zài fū miànmó.","vi":"Cô ấy đang đắp mặt nạ."},{"type":"simple","zh":"脚扭伤后，最好先用冰块冷敷一下。","pinyin":"Jiǎo niǔshāng hòu, zuìhǎo xiān yòng bīngkuài lěngfū yíxià.","vi":"Sau khi trẹo chân, tốt nhất trước hết nên chườm đá lạnh."},{"type":"compound","zh":"如果眼睛肿了，就用热毛巾敷几分钟。","pinyin":"Rúguǒ yǎnjing zhǒng le, jiù yòng rè máojīn fū jǐ fēnzhōng.","vi":"Nếu mắt bị sưng thì dùng khăn nóng chườm vài phút."}],"related":[{"hanzi":"涂","pinyin":"tú","vi":"bôi"},{"hanzi":"抹","pinyin":"mǒ","vi":"thoa"},{"hanzi":"面膜","pinyin":"miànmó","vi":"mặt nạ"},{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa"}]},{"id":"扶持","hanzi":"扶持","pinyin":"fúchí","meaning_vi":"hỗ trợ, nâng đỡ, giúp đỡ","explanation":"扶 (phù – đỡ) + 持 (trì – giữ) → đỡ và giữ cho đứng vững; nghĩa là hỗ trợ cho phát triển.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"政府扶持小企业。","pinyin":"Zhèngfǔ fúchí xiǎoqǐyè.","vi":"Chính phủ hỗ trợ doanh nghiệp nhỏ."},{"type":"simple","zh":"这个项目得到了当地政府的资金扶持。","pinyin":"Zhè ge xiàngmù dédàole dāngdì zhèngfǔ de zījīn fúchí.","vi":"Dự án này nhận được hỗ trợ vốn từ chính quyền địa phương."},{"type":"compound","zh":"只要大家互相扶持，就没有过不去的难关。","pinyin":"Zhǐyào dàjiā hùxiāng fúchí, jiù méiyǒu guòbuqù de nánguān.","vi":"Chỉ cần mọi người nâng đỡ lẫn nhau thì không có cửa ải nào không vượt qua."}],"related":[{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"帮扶","pinyin":"bāngfú","vi":"giúp đỡ"},{"hanzi":"扶贫","pinyin":"fúpín","vi":"xóa đói giảm nghèo"},{"hanzi":"资助","pinyin":"zīzhù","vi":"tài trợ"}]},{"id":"服用","hanzi":"服用","pinyin":"fúyòng","meaning_vi":"uống (thuốc), dùng (thuốc)","explanation":"服 (phục – uống thuốc) + 用 (dụng – dùng) → uống, dùng thuốc; cách nói trang trọng.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"每天服用两次。","pinyin":"Měitiān fúyòng liǎng cì.","vi":"Mỗi ngày uống hai lần."},{"type":"simple","zh":"这种药必须在饭后半小时服用。","pinyin":"Zhè zhǒng yào bìxū zài fàn hòubàn xiǎoshí fúyòng.","vi":"Loại thuốc này phải uống sau bữa ăn nửa tiếng."},{"type":"compound","zh":"如果服用后出现头晕，就请立即停药并咨询医生。","pinyin":"Rúguǒ fúyòng hòu chūxiàn tóuyūn, jiù qǐng lìjí tíngyào bìng zīxún yīshēng.","vi":"Nếu sau khi uống bị chóng mặt, xin ngừng thuốc ngay và hỏi ý kiến bác sĩ."}],"related":[{"hanzi":"吃药","pinyin":"chīyào","vi":"uống thuốc"},{"hanzi":"药物","pinyin":"yàowù","vi":"thuốc"},{"hanzi":"剂量","pinyin":"jìliàng","vi":"liều lượng"},{"hanzi":"口服","pinyin":"kǒufú","vi":"uống"}]},{"id":"浮力","hanzi":"浮力","pinyin":"fúlì","meaning_vi":"lực đẩy (nổi), sức nổi","explanation":"浮 (phù – nổi) + 力 (lực – sức) → lực chất lỏng đẩy vật lên trên, giúp vật nổi.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🛟","examples":[{"type":"basic","zh":"海水的浮力很大。","pinyin":"Hǎishuǐ de fúlì hěn dà.","vi":"Lực đẩy của nước biển rất lớn."},{"type":"simple","zh":"人在死海里不用游泳也能靠浮力漂着。","pinyin":"Rén zài sǐ hǎilǐ bú yòng yóuyǒng yě néng kào fúlì piāo zhe.","vi":"Người ở Biển Chết không cần bơi cũng nổi được nhờ lực đẩy."},{"type":"compound","zh":"因为木头的浮力比较大，所以古人用它来造船。","pinyin":"Yīnwèi mùtou de fúlì bǐjiào dà, suǒyǐ gǔrén yòng tā lái zàochuán.","vi":"Vì gỗ có sức nổi khá lớn nên người xưa dùng nó để đóng thuyền."}],"related":[{"hanzi":"重力","pinyin":"zhònglì","vi":"trọng lực"},{"hanzi":"浮","pinyin":"fú","vi":"nổi"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"沉","pinyin":"chén","vi":"chìm"}]},{"id":"抚养费","hanzi":"抚养费","pinyin":"fǔyǎngfèi","meaning_vi":"tiền cấp dưỡng (nuôi con)","explanation":"抚养 (phủ dưỡng – nuôi nấng) + 费 (phí – tiền) → khoản tiền phải trả để nuôi con, thường sau ly hôn.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"👶","examples":[{"type":"basic","zh":"他每月付抚养费。","pinyin":"Tā měiyuè fù fǔyǎngfèi.","vi":"Mỗi tháng anh ấy trả tiền cấp dưỡng."},{"type":"simple","zh":"法院判决男方每月支付三千元抚养费。","pinyin":"Fǎyuàn pànjué nánfāng měiyuè zhīfù sān qiān yuán fǔyǎngfèi.","vi":"Tòa tuyên người chồng mỗi tháng trả ba nghìn tệ tiền cấp dưỡng."},{"type":"compound","zh":"即使离婚了，父亲也有义务按时支付孩子的抚养费。","pinyin":"Jíshǐ líhūn le, fùqīn yě yǒu yìwù ànshí zhīfù háizi de fǔyǎngfèi.","vi":"Dù đã ly hôn, người cha vẫn có nghĩa vụ trả tiền cấp dưỡng cho con đúng hạn."}],"related":[{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi nấng"},{"hanzi":"赡养费","pinyin":"shànyǎngfèi","vi":"tiền phụng dưỡng"},{"hanzi":"离婚","pinyin":"líhūn","vi":"ly hôn"},{"hanzi":"监护权","pinyin":"jiānhùquán","vi":"quyền giám hộ"}],"traditional":"撫養費"},{"id":"斧子","hanzi":"斧子","pinyin":"fǔzi","meaning_vi":"cái rìu","explanation":"斧 (phủ – cái rìu) + 子 (tử – hậu tố) → dụng cụ có lưỡi sắc để chặt gỗ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪓","examples":[{"type":"basic","zh":"他拿着一把斧子。","pinyin":"Tā názhe yì bǎ fǔzi.","vi":"Anh ấy cầm một cái rìu."},{"type":"simple","zh":"爷爷用斧子把木头劈成了小块。","pinyin":"Yéye yòng fǔzi bǎ mùtou pī chéngle xiǎo kuài.","vi":"Ông dùng rìu bổ khúc gỗ thành từng miếng nhỏ."},{"type":"compound","zh":"虽然这把斧子很旧，但是磨一磨还能用。","pinyin":"Suīrán zhè bǎ fǔzi hěn jiù, dànshì mó yi mó hái néng yòng.","vi":"Tuy cái rìu này cũ nhưng mài một chút vẫn dùng được."}],"related":[{"hanzi":"斧头","pinyin":"fǔtóu","vi":"cái rìu"},{"hanzi":"锯子","pinyin":"jùzi","vi":"cái cưa"},{"hanzi":"砍","pinyin":"kǎn","vi":"chặt"},{"hanzi":"刀","pinyin":"dāo","vi":"con dao"}]},{"id":"俯首","hanzi":"俯首","pinyin":"fǔshǒu","meaning_vi":"cúi đầu; (nghĩa bóng) khuất phục","explanation":"俯 (phủ – cúi xuống) + 首 (thủ – đầu) → cúi đầu xuống; nghĩa bóng là chịu phục tùng (俯首称臣).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"他俯首认罪。","pinyin":"Tā fǔshǒu rènzuì.","vi":"Hắn cúi đầu nhận tội."},{"type":"simple","zh":"在困难面前，他从来不肯俯首认输。","pinyin":"Zài kùnnan miànqián, tā cónglái bùkěn fǔshǒu rènshū.","vi":"Trước khó khăn, anh ấy chưa bao giờ chịu cúi đầu nhận thua."},{"type":"compound","zh":"虽然对手实力很强，但是我们绝不会轻易俯首称臣。","pinyin":"Suīrán duìshǒu shílì hěn qiáng, dànshì wǒmen juébú huì qīngyì fǔshǒu chēng chén.","vi":"Tuy đối thủ rất mạnh nhưng chúng tôi tuyệt đối không dễ dàng khuất phục."}],"related":[{"hanzi":"低头","pinyin":"dītóu","vi":"cúi đầu"},{"hanzi":"屈服","pinyin":"qūfú","vi":"khuất phục"},{"hanzi":"抬头","pinyin":"táitóu","vi":"ngẩng đầu"},{"hanzi":"俯视","pinyin":"fǔshì","vi":"nhìn xuống"}]},{"id":"腐化","hanzi":"腐化","pinyin":"fǔhuà","meaning_vi":"thối rữa; sa đọa, tha hóa","explanation":"腐 (hủ – mục nát) + 化 (hóa – biến thành) → biến thành mục nát; nghĩa bóng chỉ tư tưởng, lối sống trở nên sa đọa.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🦠","examples":[{"type":"basic","zh":"他的生活很腐化。","pinyin":"Tā de shēnghuó hěn fǔhuà.","vi":"Lối sống của hắn rất sa đọa."},{"type":"simple","zh":"权力过于集中容易使官员腐化。","pinyin":"Quánlì guòyú jízhōng róngyì shǐ guānyuán fǔhuà.","vi":"Quyền lực quá tập trung dễ khiến quan chức tha hóa."},{"type":"compound","zh":"如果缺少监督，再好的干部也可能慢慢腐化。","pinyin":"Rúguǒ quēshǎo jiāndū, zài hǎo de gànbù yě kěnéng mànmàn fǔhuà.","vi":"Nếu thiếu giám sát, cán bộ tốt đến đâu cũng có thể dần tha hóa."}],"related":[{"hanzi":"腐败","pinyin":"fǔbài","vi":"hủ bại, tham nhũng"},{"hanzi":"腐烂","pinyin":"fǔlàn","vi":"thối rữa"},{"hanzi":"堕落","pinyin":"duòluò","vi":"sa đọa"},{"hanzi":"廉洁","pinyin":"liánjié","vi":"liêm khiết"}]},{"id":"付费","hanzi":"付费","pinyin":"fùfèi","meaning_vi":"trả tiền, trả phí","explanation":"付 (phó – trao, trả) + 费 (phí – chi phí) → trả khoản phí để dùng dịch vụ.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"这个软件要付费。","pinyin":"Zhè ge ruǎnjiàn yào fùfèi.","vi":"Phần mềm này phải trả phí."},{"type":"simple","zh":"付费会员可以免费看所有电影。","pinyin":"Fùfèi huìyuán kěyǐ miǎnfèi kàn suǒyǒu diànyǐng.","vi":"Thành viên trả phí được xem miễn phí tất cả phim."},{"type":"compound","zh":"虽然很多人不愿意为内容付费，但是好作品值得这个价钱。","pinyin":"Suīrán hěn duō rén bú yuànyì wèi nèiróng fùfèi, dànshì hǎo zuòpǐn zhíde zhè ge jiàqián.","vi":"Tuy nhiều người không muốn trả tiền cho nội dung nhưng tác phẩm hay xứng đáng với giá đó."}],"related":[{"hanzi":"付款","pinyin":"fùkuǎn","vi":"thanh toán"},{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"收费","pinyin":"shōufèi","vi":"thu phí"},{"hanzi":"会员","pinyin":"huìyuán","vi":"hội viên"}],"traditional":"付費"},{"id":"负面","hanzi":"负面","pinyin":"fùmiàn","meaning_vi":"tiêu cực, mặt trái","explanation":"负 (phụ – âm, trái) + 面 (diện – mặt) → mặt tiêu cực, xấu; đối lập với 正面.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👎","examples":[{"type":"basic","zh":"别看负面新闻。","pinyin":"Biékàn fùmiàn xīnwén.","vi":"Đừng xem tin tức tiêu cực."},{"type":"simple","zh":"长期熬夜会给身体带来很多负面影响。","pinyin":"Chángqī áoyè huì gěi shēntǐ dàilái hěn duō fùmiàn yǐngxiǎng.","vi":"Thức khuya lâu dài sẽ gây nhiều ảnh hưởng tiêu cực cho cơ thể."},{"type":"compound","zh":"一旦出现负面评价，公司就应该马上了解情况并回应。","pinyin":"Yídàn chūxiàn fùmiàn píngjià, gōngsī jiù yīnggāi mǎshàng liǎojiě qíngkuàng bìng huíyìng.","vi":"Một khi xuất hiện đánh giá tiêu cực, công ty nên lập tức tìm hiểu và phản hồi."}],"related":[{"hanzi":"正面","pinyin":"zhèngmiàn","vi":"tích cực, mặt chính"},{"hanzi":"消极","pinyin":"xiāojí","vi":"tiêu cực"},{"hanzi":"负能量","pinyin":"fùnéngliàng","vi":"năng lượng tiêu cực"},{"hanzi":"不利","pinyin":"búlì","vi":"bất lợi"}],"traditional":"負面"},{"id":"负有","hanzi":"负有","pinyin":"fùyǒu","meaning_vi":"gánh, chịu (trách nhiệm)","explanation":"负 (phụ – gánh vác) + 有 (hữu – có) → mang trên mình (trách nhiệm, nghĩa vụ); hay đi với 责任, 义务.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他负有主要责任。","pinyin":"Tā fùyǒu zhǔyào zérèn.","vi":"Anh ta chịu trách nhiệm chính."},{"type":"simple","zh":"父母对孩子的教育负有不可推卸的责任。","pinyin":"Fùmǔ duì háizi de jiàoyù fùyǒu bùkě tuīxiè de zérèn.","vi":"Cha mẹ có trách nhiệm không thể chối bỏ đối với việc giáo dục con cái."},{"type":"compound","zh":"既然你是项目负责人，就对这次失误负有责任。","pinyin":"Jìrán nǐ shì xiàngmù fùzérén, jiù duì zhè cì shīwù fùyǒu zérèn.","vi":"Đã là người phụ trách dự án thì bạn phải chịu trách nhiệm về sai sót lần này."}],"related":[{"hanzi":"承担","pinyin":"chéngdān","vi":"gánh vác"},{"hanzi":"负责","pinyin":"fùzé","vi":"phụ trách"},{"hanzi":"责任","pinyin":"zérèn","vi":"trách nhiệm"},{"hanzi":"义务","pinyin":"yìwù","vi":"nghĩa vụ"}],"traditional":"負有"},{"id":"附","hanzi":"附","pinyin":"fù","meaning_vi":"kèm theo, đính kèm; phụ thuộc, bám vào","explanation":"附 (phụ – dựa vào, kèm theo) → gắn thêm vào cái chính hoặc dựa vào; dùng trong 附近, 附件, 附上.","hsk_level":"7-9","tags":["dong-tu"],"image":"📎","examples":[{"type":"basic","zh":"信中附有照片。","pinyin":"Xìn zhōng fù yǒu zhàopiàn.","vi":"Trong thư có kèm ảnh."},{"type":"simple","zh":"报名表后面请附上一张身份证复印件。","pinyin":"Bàomíngbiǎo hòumiàn qǐng fùshang yì zhāng shēnfènzhèng fùyìnjiàn.","vi":"Sau tờ đăng ký xin đính kèm một bản sao chứng minh thư."},{"type":"compound","zh":"如果您需要详细资料，就请查看邮件所附的文件。","pinyin":"Rúguǒ nín xūyào xiángxì zīliào, jiù qǐng chákàn yóujiàn suǒ fù de wénjiàn.","vi":"Nếu quý vị cần tài liệu chi tiết, xin xem tệp đính kèm trong email."}],"related":[{"hanzi":"附件","pinyin":"fùjiàn","vi":"tệp đính kèm"},{"hanzi":"附近","pinyin":"fùjìn","vi":"gần đây"},{"hanzi":"附加","pinyin":"fùjiā","vi":"bổ sung thêm"},{"hanzi":"依附","pinyin":"yīfù","vi":"dựa dẫm"}]},{"id":"附加","hanzi":"附加","pinyin":"fùjiā","meaning_vi":"phụ thêm, bổ sung, kèm thêm","explanation":"附 (phụ – kèm) + 加 (gia – thêm) → thêm vào bên cạnh phần chính; hay dùng trong 附加费, 附加条件.","hsk_level":"7-9","tags":["dong-tu"],"image":"➕","examples":[{"type":"basic","zh":"这是附加条件。","pinyin":"Zhè shì fùjiā tiáojiàn.","vi":"Đây là điều kiện kèm theo."},{"type":"simple","zh":"旺季机票要附加一笔燃油费。","pinyin":"Wàngjì jīpiào yào fùjiā yì bǐ rányóu fèi.","vi":"Mùa cao điểm vé máy bay phải cộng thêm một khoản phí nhiên liệu."},{"type":"compound","zh":"虽然价格不高，但是合同里附加了很多限制。","pinyin":"Suīrán jiàgé bù gāo, dànshì hétong lǐ fùjiāle hěn duō xiànzhì.","vi":"Tuy giá không cao nhưng trong hợp đồng kèm thêm rất nhiều hạn chế."}],"related":[{"hanzi":"附加费","pinyin":"fùjiāfèi","vi":"phụ phí"},{"hanzi":"额外","pinyin":"éwài","vi":"ngoài định mức"},{"hanzi":"补充","pinyin":"bǔchōng","vi":"bổ sung"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"tăng thêm"}]},{"id":"复查","hanzi":"复查","pinyin":"fùchá","meaning_vi":"kiểm tra lại, tái khám","explanation":"复 (phục – lại lần nữa) + 查 (tra – kiểm tra) → kiểm tra thêm lần nữa; thường dùng khi tái khám bệnh.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"下周去医院复查。","pinyin":"Xiàzhōu qù yīyuàn fùchá.","vi":"Tuần sau đi bệnh viện tái khám."},{"type":"simple","zh":"医生让他一个月后再来复查一次。","pinyin":"Yīshēng ràng tā yí geyuè hòu zài lái fùchá yí cì.","vi":"Bác sĩ bảo anh ấy một tháng sau quay lại tái khám."},{"type":"compound","zh":"如果复查结果正常，你就可以停药了。","pinyin":"Rúguǒ fùchá jiéguǒ zhèngcháng, nǐ jiù kěyǐ tíngyào le.","vi":"Nếu kết quả tái khám bình thường thì bạn có thể ngừng thuốc."}],"related":[{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"},{"hanzi":"复诊","pinyin":"fùzhěn","vi":"tái khám"},{"hanzi":"核查","pinyin":"héchá","vi":"kiểm tra đối chiếu"},{"hanzi":"体检","pinyin":"tǐjiǎn","vi":"khám sức khỏe"}],"traditional":"復查"},{"id":"复发","hanzi":"复发","pinyin":"fùfā","meaning_vi":"tái phát","explanation":"复 (phục – lại) + 发 (phát – phát ra) → bệnh đã khỏi lại phát lại.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🔁","examples":[{"type":"basic","zh":"他的病复发了。","pinyin":"Tā de bìng fùfā le.","vi":"Bệnh của anh ấy tái phát rồi."},{"type":"simple","zh":"手术很成功，但还要防止癌症复发。","pinyin":"Shǒushù hěn chénggōng, dàn hái yào fángzhǐ áizhèng fùfā.","vi":"Ca mổ rất thành công nhưng vẫn phải đề phòng ung thư tái phát."},{"type":"compound","zh":"如果不按时吃药，旧病就很可能复发。","pinyin":"Rúguǒ bú ànshí chīyào, jiùbìng jiù hěn kěnéng fùfā.","vi":"Nếu không uống thuốc đúng giờ thì bệnh cũ rất có thể tái phát."}],"related":[{"hanzi":"发作","pinyin":"fāzuò","vi":"phát tác"},{"hanzi":"痊愈","pinyin":"quányù","vi":"khỏi hẳn"},{"hanzi":"反复","pinyin":"fǎnfù","vi":"lặp đi lặp lại"},{"hanzi":"复查","pinyin":"fùchá","vi":"tái khám"}],"traditional":"復發"},{"id":"赴","hanzi":"赴","pinyin":"fù","meaning_vi":"đi đến, tới, dự","explanation":"赴 (phó – đi tới) → đến một nơi hoặc tham dự một sự việc; mang sắc thái văn viết, như 赴宴, 赴约.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🚶","examples":[{"type":"basic","zh":"他明天赴京开会。","pinyin":"Tā míngtiān fù jīng kāihuì.","vi":"Ngày mai anh ấy đến Bắc Kinh họp."},{"type":"simple","zh":"一支医疗队已经赴灾区开展救援。","pinyin":"Yì zhī yīliáo duì yǐjīng fù zāiqū kāizhǎn jiùyuán.","vi":"Một đội y tế đã đến vùng thiên tai triển khai cứu hộ."},{"type":"compound","zh":"虽然下着大雨，但是他还是准时赴约了。","pinyin":"Suīrán xiàzhe dàyǔ, dànshì tā háishi zhǔnshí fùyuē le.","vi":"Tuy trời mưa to nhưng anh ấy vẫn đến cuộc hẹn đúng giờ."}],"related":[{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"},{"hanzi":"赴约","pinyin":"fùyuē","vi":"đến chỗ hẹn"},{"hanzi":"奔赴","pinyin":"bēnfù","vi":"lao tới"},{"hanzi":"赶赴","pinyin":"gǎnfù","vi":"vội đến"}]},{"id":"富含","hanzi":"富含","pinyin":"fùhán","meaning_vi":"giàu (chất gì), chứa nhiều","explanation":"富 (phú – giàu) + 含 (hàm – chứa) → chứa đựng nhiều (chất dinh dưỡng...).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🥦","examples":[{"type":"basic","zh":"橙子富含维生素。","pinyin":"Chéngzi fùhán wéishēngsù.","vi":"Cam giàu vitamin."},{"type":"simple","zh":"深海鱼富含对大脑有益的脂肪酸。","pinyin":"Shēn hǎiyú fùhán duì dànǎo yǒuyì de zhīfángsuān.","vi":"Cá biển sâu giàu axit béo có lợi cho não."},{"type":"compound","zh":"因为菠菜富含铁，所以贫血的人可以多吃一些。","pinyin":"Yīnwèi bōcài fùhán tiě, suǒyǐ pínxuè de rén kěyǐ duō chī yìxiē.","vi":"Vì rau chân vịt giàu sắt nên người thiếu máu có thể ăn nhiều hơn."}],"related":[{"hanzi":"含有","pinyin":"hányǒu","vi":"có chứa"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"},{"hanzi":"营养","pinyin":"yíngyǎng","vi":"dinh dưỡng"},{"hanzi":"缺乏","pinyin":"quēfá","vi":"thiếu"}]},{"id":"富豪","hanzi":"富豪","pinyin":"fùháo","meaning_vi":"phú hào, đại gia","explanation":"富 (phú – giàu) + 豪 (hào – có thế lực) → người giàu có và có thế lực.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤑","examples":[{"type":"basic","zh":"他是当地富豪。","pinyin":"Tā shì dāngdì fùháo.","vi":"Ông ấy là đại gia trong vùng."},{"type":"simple","zh":"这位富豪把一半财产捐给了慈善机构。","pinyin":"Zhè wèi fùháo bǎ yíbàn cáichǎn juāngěile císhàn jīgòu.","vi":"Vị đại gia này quyên một nửa tài sản cho tổ chức từ thiện."},{"type":"compound","zh":"虽然他已经成了富豪，但是生活依然非常简朴。","pinyin":"Suīrán tā yǐjīng chéngle fùháo, dànshì shēnghuó yīrán fēicháng jiǎnpǔ.","vi":"Tuy đã trở thành đại gia nhưng ông ấy vẫn sống rất giản dị."}],"related":[{"hanzi":"富翁","pinyin":"fùwēng","vi":"phú ông"},{"hanzi":"有钱人","pinyin":"yǒuqiánrén","vi":"người giàu"},{"hanzi":"首富","pinyin":"shǒufù","vi":"người giàu nhất"},{"hanzi":"穷人","pinyin":"qióngrén","vi":"người nghèo"}]},{"id":"富翁","hanzi":"富翁","pinyin":"fùwēng","meaning_vi":"phú ông, triệu phú","explanation":"富 (phú – giàu) + 翁 (ông – ông già) → người giàu có; hay dùng trong 百万富翁.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💰","examples":[{"type":"basic","zh":"他成了百万富翁。","pinyin":"Tā chéngle bǎiwàn fùwēng.","vi":"Anh ấy trở thành triệu phú."},{"type":"simple","zh":"一张彩票让这个普通工人变成了富翁。","pinyin":"Yì zhāng cǎipiào ràng zhè ge pǔtōng gōngrén biàn chéngle fùwēng.","vi":"Một tờ vé số biến người công nhân bình thường này thành phú ông."},{"type":"compound","zh":"即使成了富翁，他也每天坚持骑自行车上班。","pinyin":"Jíshǐ chéngle fùwēng, tā yě měitiān jiānchí qí zìxíngchē shàngbān.","vi":"Dù đã thành triệu phú, ông ấy vẫn ngày ngày đạp xe đi làm."}],"related":[{"hanzi":"富豪","pinyin":"fùháo","vi":"đại gia"},{"hanzi":"财主","pinyin":"cáizhu","vi":"địa chủ, nhà giàu"},{"hanzi":"百万富翁","pinyin":"bǎiwànfùwēng","vi":"triệu phú"},{"hanzi":"穷光蛋","pinyin":"qióngguāngdàn","vi":"kẻ nghèo rớt"}]},{"id":"腹部","hanzi":"腹部","pinyin":"fùbù","meaning_vi":"bụng, vùng bụng","explanation":"腹 (phúc – bụng) + 部 (bộ – phần) → phần bụng của cơ thể; cách nói trang trọng, dùng trong y học.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🫃","examples":[{"type":"basic","zh":"他腹部有点疼。","pinyin":"Tā fùbù yǒudiǎn téng.","vi":"Bụng anh ấy hơi đau."},{"type":"simple","zh":"仰卧起坐可以锻炼腹部的肌肉。","pinyin":"Yǎngwò qǐ zuò kěyǐ duànliàn fùbù de jīròu.","vi":"Gập bụng có thể rèn luyện cơ bụng."},{"type":"compound","zh":"如果腹部持续剧痛，就要马上去急诊。","pinyin":"Rúguǒ fùbù chíxù jùtòng, jiùyào mǎshàng qù jízhěn.","vi":"Nếu bụng đau dữ dội kéo dài thì phải đi cấp cứu ngay."}],"related":[{"hanzi":"肚子","pinyin":"dùzi","vi":"bụng"},{"hanzi":"胸部","pinyin":"xiōngbù","vi":"ngực"},{"hanzi":"腹肌","pinyin":"fùjī","vi":"cơ bụng"},{"hanzi":"腰","pinyin":"yāo","vi":"eo"}]},{"id":"改版","hanzi":"改版","pinyin":"gǎibǎn","meaning_vi":"đổi giao diện, phiên bản mới; sửa bản in","explanation":"改 (cải – sửa) + 版 (bản – bản in, phiên bản) → sửa đổi bố cục, phiên bản của báo, trang web, ứng dụng.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🆕","examples":[{"type":"basic","zh":"网站改版了。","pinyin":"Wǎngzhàn gǎibǎn le.","vi":"Trang web đã đổi giao diện."},{"type":"simple","zh":"这本杂志改版后，内容更贴近年轻人。","pinyin":"Zhè běn zázhì gǎibǎn hòu, nèiróng gèng tiējìn niánqīngrén.","vi":"Tạp chí này sau khi đổi mới, nội dung gần gũi giới trẻ hơn."},{"type":"compound","zh":"虽然应用改版后更漂亮了，可是很多老用户不习惯。","pinyin":"Suīrán yìngyòng gǎibǎn hòu gèng piàoliang le, kěshì hěn duō lǎo yònghù bù xíguàn.","vi":"Tuy ứng dụng sau khi đổi giao diện đẹp hơn nhưng nhiều người dùng cũ không quen."}],"related":[{"hanzi":"版本","pinyin":"bǎnběn","vi":"phiên bản"},{"hanzi":"更新","pinyin":"gēngxīn","vi":"cập nhật"},{"hanzi":"升级","pinyin":"shēngjí","vi":"nâng cấp"},{"hanzi":"新版","pinyin":"xīnbǎn","vi":"bản mới"}]},{"id":"改编","hanzi":"改编","pinyin":"gǎibiān","meaning_vi":"chuyển thể, cải biên","explanation":"改 (cải – sửa) + 编 (biên – biên soạn) → biên soạn lại tác phẩm sang hình thức khác, như tiểu thuyết thành phim.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"📽️","examples":[{"type":"basic","zh":"这部电影改编自小说。","pinyin":"Zhè bù diànyǐng gǎibiān zì xiǎoshuō.","vi":"Bộ phim này chuyển thể từ tiểu thuyết."},{"type":"simple","zh":"他把这首民歌改编成了流行歌曲。","pinyin":"Tā bǎ zhè shǒu míngē gǎibiān chéngle liúxíng gēqǔ.","vi":"Anh ấy cải biên bài dân ca này thành bài hát nhạc pop."},{"type":"compound","zh":"如果改编得太多，原作的味道就会丢失。","pinyin":"Rúguǒ gǎibiān de tài duō, yuánzuò de wèidao jiù huì diūshī.","vi":"Nếu cải biên quá nhiều thì hương vị của nguyên tác sẽ mất đi."}],"related":[{"hanzi":"改写","pinyin":"gǎixiě","vi":"viết lại"},{"hanzi":"原著","pinyin":"yuánzhù","vi":"nguyên tác"},{"hanzi":"翻拍","pinyin":"fānpāi","vi":"làm lại phim"},{"hanzi":"剧本","pinyin":"jùběn","vi":"kịch bản"}],"traditional":"改編"},{"id":"改动","hanzi":"改动","pinyin":"gǎidòng","meaning_vi":"sửa đổi, thay đổi","explanation":"改 (cải – sửa) + 动 (động – xê dịch) → sửa và xê dịch một phần, thường là thay đổi nhỏ.","hsk_level":"7-9","tags":["dong-tu"],"image":"✏️","examples":[{"type":"basic","zh":"计划有些改动。","pinyin":"Jìhuà yǒuxiē gǎidòng.","vi":"Kế hoạch có một số thay đổi."},{"type":"simple","zh":"编辑只改动了文章里的几个字。","pinyin":"Biānjí zhǐ gǎidòngle wénzhāng lǐ de jǐ ge zì.","vi":"Biên tập viên chỉ sửa vài chữ trong bài viết."},{"type":"compound","zh":"一旦合同签好了，任何一方都不能随意改动。","pinyin":"Yídàn hétong qiān hǎo le, rènhé yìfāng dōu bù néng suíyì gǎidòng.","vi":"Một khi hợp đồng đã ký, không bên nào được tự ý sửa đổi."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa chữa"},{"hanzi":"变动","pinyin":"biàndòng","vi":"biến động"},{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"更改","pinyin":"gēnggǎi","vi":"thay đổi"}],"traditional":"改動"},{"id":"改名","hanzi":"改名","pinyin":"gǎimíng","meaning_vi":"đổi tên","explanation":"改 (cải – đổi) + 名 (danh – tên) → đổi sang tên khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏷️","examples":[{"type":"basic","zh":"他去年改名了。","pinyin":"Tā qùnián gǎimíng le.","vi":"Năm ngoái anh ấy đã đổi tên."},{"type":"simple","zh":"这条街后来改名叫人民路。","pinyin":"Zhè tiáo jiē hòulái gǎimíng jiào rénmín lù.","vi":"Con phố này về sau đổi tên thành đường Nhân Dân."},{"type":"compound","zh":"公司改名以后，所有的合同都要重新盖章。","pinyin":"Gōngsī gǎimíng yǐhòu, suǒyǒu de hétong dōu yào chóngxīn gàizhāng.","vi":"Sau khi công ty đổi tên, mọi hợp đồng đều phải đóng dấu lại."}],"related":[{"hanzi":"更名","pinyin":"gēngmíng","vi":"đổi tên"},{"hanzi":"名字","pinyin":"míngzi","vi":"tên"},{"hanzi":"改姓","pinyin":"gǎixìng","vi":"đổi họ"},{"hanzi":"命名","pinyin":"mìngmíng","vi":"đặt tên"}]},{"id":"改日","hanzi":"改日","pinyin":"gǎirì","meaning_vi":"hôm khác, bữa khác","explanation":"改 (cải – đổi) + 日 (nhật – ngày) → đổi sang ngày khác; dùng khi hẹn lại lịch một cách lịch sự.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"📆","examples":[{"type":"basic","zh":"我们改日再聊。","pinyin":"Wǒmen gǎirì zài liáo.","vi":"Hôm khác chúng ta nói chuyện tiếp."},{"type":"simple","zh":"今天太晚了，我改日再登门拜访。","pinyin":"Jīntiān tài wǎn le, wǒ gǎirì zài dēngmén bàifǎng.","vi":"Hôm nay muộn quá rồi, hôm khác tôi sẽ đến nhà thăm."},{"type":"compound","zh":"既然你今天不方便，那我们就改日再见面吧。","pinyin":"Jìrán nǐ jīntiān bù fāngbiàn, nà wǒmen jiù gǎirì zàijiàn miàn ba.","vi":"Đã hôm nay bạn không tiện thì hôm khác chúng ta gặp nhé."}],"related":[{"hanzi":"改天","pinyin":"gǎitiān","vi":"hôm khác"},{"hanzi":"他日","pinyin":"tārì","vi":"ngày khác"},{"hanzi":"择日","pinyin":"zérì","vi":"chọn ngày"},{"hanzi":"延期","pinyin":"yánqī","vi":"hoãn lại"}]},{"id":"改为","hanzi":"改为","pinyin":"gǎiwéi","meaning_vi":"đổi thành, chuyển thành","explanation":"改 (cải – đổi) + 为 (vi – thành) → thay đổi để trở thành cái khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"会议改为线上。","pinyin":"Huìyì gǎiwéi xiànshàng.","vi":"Cuộc họp chuyển sang trực tuyến."},{"type":"simple","zh":"这座旧仓库被改为了一家书店。","pinyin":"Zhè zuò jiù cāngkù bèi gǎi wéile yìjiā shūdiàn.","vi":"Nhà kho cũ này đã được cải tạo thành hiệu sách."},{"type":"compound","zh":"由于报名人数太多，所以比赛改为分两天进行。","pinyin":"Yóuyú bàomíng rénshù tài duō, suǒyǐ bǐsài gǎiwéi fēn liǎng tiān jìnxíng.","vi":"Do số người đăng ký quá đông nên cuộc thi đổi thành tổ chức trong hai ngày."}],"related":[{"hanzi":"改成","pinyin":"gǎichéng","vi":"đổi thành"},{"hanzi":"变为","pinyin":"biànwéi","vi":"biến thành"},{"hanzi":"换成","pinyin":"huànchéng","vi":"đổi sang"},{"hanzi":"改变","pinyin":"gǎibiàn","vi":"thay đổi"}],"traditional":"改為"},{"id":"概况","hanzi":"概况","pinyin":"gàikuàng","meaning_vi":"tình hình chung, khái quát","explanation":"概 (khái – đại khái) + 况 (huống – tình hình) → tình hình chung, nét khái quát.","hsk_level":"7-9","tags":["danh-tu"],"image":"📋","examples":[{"type":"basic","zh":"请介绍公司概况。","pinyin":"Qǐng jièshào gōngsī gàikuàng.","vi":"Xin giới thiệu khái quát về công ty."},{"type":"simple","zh":"导游先给我们讲了这座城市的历史概况。","pinyin":"Dǎoyóu xiān gěi wǒmen jiǎngle zhè zuò chéngshì de lìshǐ gàikuàng.","vi":"Hướng dẫn viên trước tiên kể cho chúng tôi khái quát lịch sử thành phố này."},{"type":"compound","zh":"虽然只是概况，但是这份报告已经说明了主要问题。","pinyin":"Suīrán zhǐshì gàikuàng, dànshì zhè fèn bàogào yǐjīng shuōmíngle zhǔyào wèntí.","vi":"Tuy chỉ là khái quát nhưng bản báo cáo này đã nêu được vấn đề chính."}],"related":[{"hanzi":"概要","pinyin":"gàiyào","vi":"tóm tắt"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"tình hình"},{"hanzi":"大概","pinyin":"dàgài","vi":"đại khái"},{"hanzi":"详情","pinyin":"xiángqíng","vi":"chi tiết"}],"traditional":"概況"},{"id":"概论","hanzi":"概论","pinyin":"gàilùn","meaning_vi":"khái luận, nhập môn","explanation":"概 (khái – đại khái) + 论 (luận – bàn luận) → bàn khái quát về một môn học; hay dùng làm tên sách, môn học.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"我在读《哲学概论》。","pinyin":"Wǒ zài dú \"zhéxué gàilùn\".","vi":"Tôi đang đọc \"Khái luận triết học\"."},{"type":"simple","zh":"大一新生都要上一门《法学概论》课。","pinyin":"Dàyì xīnshēng dōu yào shàng yì mén \"fǎxué gàilùn\" kè.","vi":"Tân sinh viên năm nhất đều phải học môn \"Nhập môn luật học\"."},{"type":"compound","zh":"虽然这本概论很薄，但是把基本概念都讲清楚了。","pinyin":"Suīrán zhè běn gàilùn hěn báo, dànshì bǎ jīběn gàiniàn dōu jiǎng qīngchu le.","vi":"Tuy cuốn khái luận này mỏng nhưng đã giảng rõ mọi khái niệm cơ bản."}],"related":[{"hanzi":"导论","pinyin":"dǎolùn","vi":"dẫn luận"},{"hanzi":"概述","pinyin":"gàishù","vi":"khái quát"},{"hanzi":"入门","pinyin":"rùmén","vi":"nhập môn"},{"hanzi":"教材","pinyin":"jiàocái","vi":"giáo trình"}],"traditional":"概論"},{"id":"肝脏","hanzi":"肝脏","pinyin":"gānzàng","meaning_vi":"gan","explanation":"肝 (can – gan) + 脏 (tạng – nội tạng) → cơ quan gan trong cơ thể.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🫀","examples":[{"type":"basic","zh":"喝酒伤肝脏。","pinyin":"Hējiǔ shāng gānzàng.","vi":"Uống rượu hại gan."},{"type":"simple","zh":"肝脏是人体最重要的解毒器官。","pinyin":"Gānzàng shì réntǐ zuì zhòngyào de jiědú qìguān.","vi":"Gan là cơ quan giải độc quan trọng nhất của cơ thể."},{"type":"compound","zh":"因为他长期熬夜喝酒，所以肝脏出了问题。","pinyin":"Yīnwèi tā chángqī áoyè hējiǔ, suǒyǐ gānzàng chūle wèntí.","vi":"Vì anh ấy thường xuyên thức khuya uống rượu nên gan có vấn đề."}],"related":[{"hanzi":"肝","pinyin":"gān","vi":"gan"},{"hanzi":"心脏","pinyin":"xīnzàng","vi":"tim"},{"hanzi":"肾脏","pinyin":"shènzàng","vi":"thận"},{"hanzi":"内脏","pinyin":"nèizàng","vi":"nội tạng"}],"traditional":"肝臟"},{"id":"赶赴","hanzi":"赶赴","pinyin":"gǎnfù","meaning_vi":"vội đến, gấp rút đến","explanation":"赶 (cản – vội) + 赴 (phó – đến) → vội vàng đến một nơi để làm việc gì đó.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"消防员赶赴现场。","pinyin":"Xiāofángyuán gǎnfù xiànchǎng.","vi":"Lính cứu hỏa gấp rút đến hiện trường."},{"type":"simple","zh":"接到电话后，他连夜赶赴医院看望父亲。","pinyin":"Jiēdào diànhuà hòu, tā liányè gǎnfù yīyuàn kànwàng fùqīn.","vi":"Nhận điện thoại xong, anh ấy vội đến bệnh viện thăm bố ngay trong đêm."},{"type":"compound","zh":"一旦接到救援任务，队员们就会立即赶赴灾区。","pinyin":"Yídàn jiēdào jiùyuán rènwu, duìyuánmen jiù huì lìjí gǎnfù zāiqū.","vi":"Một khi nhận nhiệm vụ cứu hộ, các đội viên sẽ lập tức lên đường đến vùng thiên tai."}],"related":[{"hanzi":"赶往","pinyin":"gǎnwǎng","vi":"vội đến"},{"hanzi":"奔赴","pinyin":"bēnfù","vi":"lao tới"},{"hanzi":"赶到","pinyin":"gǎndào","vi":"kịp đến"},{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"}],"traditional":"趕赴"},{"id":"赶往","hanzi":"赶往","pinyin":"gǎnwǎng","meaning_vi":"vội đến, gấp rút đi tới","explanation":"赶 (cản – vội) + 往 (vãng – hướng tới) → vội vã đi về phía một nơi.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚕","examples":[{"type":"basic","zh":"我正赶往机场。","pinyin":"Wǒ zhèng gǎnwǎng jīchǎng.","vi":"Tôi đang vội ra sân bay."},{"type":"simple","zh":"下班后他匆匆赶往学校接孩子。","pinyin":"Xiàbān hòu tā cōngcōng gǎnwǎng xuéxiào jiē háizi.","vi":"Tan làm anh ấy vội vàng đến trường đón con."},{"type":"compound","zh":"虽然已经很晚了，但是我们还是决定马上赶往医院。","pinyin":"Suīrán yǐjīng hěn wǎn le, dànshì wǒmen háishi juédìng mǎshàng gǎnwǎng yīyuàn.","vi":"Tuy đã rất muộn nhưng chúng tôi vẫn quyết định lập tức đến bệnh viện."}],"related":[{"hanzi":"赶赴","pinyin":"gǎnfù","vi":"gấp rút đến"},{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"},{"hanzi":"赶路","pinyin":"gǎnlù","vi":"vội lên đường"},{"hanzi":"飞往","pinyin":"fēiwǎng","vi":"bay đến"}],"traditional":"趕往"},{"id":"敢情","hanzi":"敢情","pinyin":"gǎnqing","meaning_vi":"hóa ra, thì ra; dĩ nhiên rồi","explanation":"敢 (cảm) + 情 (tình) → từ khẩu ngữ phương Bắc, biểu thị phát hiện ra sự thật (hóa ra) hoặc khẳng định (đương nhiên).","hsk_level":"7-9","tags":["pho-tu"],"image":"💡","examples":[{"type":"basic","zh":"敢情你早知道了！","pinyin":"Gǎnqing nǐ zǎo zhīdàole!","vi":"Hóa ra cậu biết từ sớm rồi!"},{"type":"simple","zh":"敢情他不是本地人，难怪听不懂方言。","pinyin":"Gǎnqing tā bú shì běndìrén, nánguài tīngbudǒng fāngyán.","vi":"Hóa ra anh ấy không phải người địa phương, thảo nào không hiểu tiếng địa phương."},{"type":"compound","zh":"要是能去海边玩几天，那敢情好，我们马上就订票。","pinyin":"Yàoshi néng qù hǎibiān wán jǐtiān, nà gǎnqing hǎo, wǒmen mǎshàng jiù dìngpiào.","vi":"Nếu được ra biển chơi mấy ngày thì tốt quá rồi, chúng ta đặt vé ngay."}],"related":[{"hanzi":"原来","pinyin":"yuánlái","vi":"thì ra"},{"hanzi":"难怪","pinyin":"nánguài","vi":"thảo nào"},{"hanzi":"当然","pinyin":"dāngrán","vi":"đương nhiên"},{"hanzi":"怪不得","pinyin":"guàibude","vi":"chẳng trách"}]},{"id":"感","hanzi":"感","pinyin":"gǎn","meaning_vi":"cảm thấy, cảm nhận; cảm (giác)","explanation":"感 (cảm – rung động trong lòng) → cảm thấy, cảm động; làm hậu tố tạo danh từ như 责任感, 安全感.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💓","examples":[{"type":"basic","zh":"我深感荣幸。","pinyin":"Wǒ shēngǎn róngxìng.","vi":"Tôi vô cùng vinh hạnh."},{"type":"simple","zh":"她对这个新话题很感兴趣。","pinyin":"Tā duì zhè ge xīn huàtí hěn gǎnxìngqù.","vi":"Cô ấy rất hứng thú với chủ đề mới này."},{"type":"compound","zh":"虽然他嘴上不说，但是心里对父母的付出深有所感。","pinyin":"Suīrán tā zuǐ shang bù shuō, dànshì xīnlǐ duì fùmǔ de fùchū shēn yǒusuǒ gǎn.","vi":"Tuy ngoài miệng không nói nhưng trong lòng anh ấy rất cảm nhận được sự hy sinh của bố mẹ."}],"related":[{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"感谢","pinyin":"gǎnxiè","vi":"cảm ơn"},{"hanzi":"责任感","pinyin":"zérèngǎn","vi":"tinh thần trách nhiệm"}]},{"id":"干部","hanzi":"干部","pinyin":"gànbù","meaning_vi":"cán bộ","explanation":"干 (cán – cốt cán) + 部 (bộ – bộ phận) → người giữ vai trò nòng cốt, quản lý trong cơ quan, tổ chức.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是村干部。","pinyin":"Tā shì cūn gànbù.","vi":"Anh ấy là cán bộ thôn."},{"type":"simple","zh":"这批年轻干部被派到基层锻炼。","pinyin":"Zhè pī niánqīng gànbù bèi pài dào jīcéng duànliàn.","vi":"Lứa cán bộ trẻ này được cử xuống cơ sở rèn luyện."},{"type":"compound","zh":"作为一名干部，不但要会做事，而且要懂得听群众的意见。","pinyin":"Zuòwéi yì míng gànbù, búdàn yào huì zuòshì, érqiě yào dǒngde tīng qúnzhòng de yìjiàn.","vi":"Là một cán bộ, không chỉ phải biết làm việc mà còn phải biết lắng nghe ý kiến quần chúng."}],"related":[{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"班干部","pinyin":"bāngànbù","vi":"cán bộ lớp"},{"hanzi":"群众","pinyin":"qúnzhòng","vi":"quần chúng"}],"traditional":"幹部"},{"id":"干事","hanzi":"干事","pinyin":"gànshi","meaning_vi":"cán sự, người phụ trách công việc chung","explanation":"干 (cán – làm việc) + 事 (sự – công việc) → người phụ trách một mảng việc cụ thể trong tổ chức, đoàn thể.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🗂️","examples":[{"type":"basic","zh":"她是宣传干事。","pinyin":"Tā shì xuānchuán gànshi.","vi":"Cô ấy là cán sự tuyên truyền."},{"type":"simple","zh":"学生会的干事正在布置晚会会场。","pinyin":"Xuéshenghuì de gànshi zhèngzài bùzhì wǎnhuì huìchǎng.","vi":"Các cán sự hội sinh viên đang trang trí hội trường dạ hội."},{"type":"compound","zh":"虽然只是个普通干事，但是他把每件小事都做得很认真。","pinyin":"Suīrán zhǐshì ge pǔtōng gànshi, dànshì tā bǎ měi jiàn xiǎoshì dōu zuò de hěn rènzhēn.","vi":"Tuy chỉ là một cán sự bình thường nhưng anh ấy làm mọi việc nhỏ rất nghiêm túc."}],"related":[{"hanzi":"干部","pinyin":"gànbù","vi":"cán bộ"},{"hanzi":"秘书","pinyin":"mìshū","vi":"thư ký"},{"hanzi":"职员","pinyin":"zhíyuán","vi":"nhân viên"},{"hanzi":"学生会","pinyin":"xuéshenghuì","vi":"hội sinh viên"}],"traditional":"幹事"},{"id":"杠铃","hanzi":"杠铃","pinyin":"gànglíng","meaning_vi":"tạ đòn","explanation":"杠 (giang – đòn ngang) + 铃 (linh – quả chuông, ví quả tạ) → dụng cụ cử tạ gồm thanh đòn và các bánh tạ.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"他在举杠铃。","pinyin":"Tā zài jǔ gànglíng.","vi":"Anh ấy đang nâng tạ đòn."},{"type":"simple","zh":"健身房新买了几副专业杠铃。","pinyin":"Jiànshēnfáng xīn mǎile jǐ fù zhuānyè gànglíng.","vi":"Phòng gym mới mua mấy bộ tạ đòn chuyên nghiệp."},{"type":"compound","zh":"如果动作不标准，举杠铃就很容易伤到腰。","pinyin":"Rúguǒ dòngzuò bù biāozhǔn, jǔ gànglíng jiù hěn róngyì shāng dào yāo.","vi":"Nếu động tác không chuẩn thì nâng tạ đòn rất dễ chấn thương lưng."}],"related":[{"hanzi":"哑铃","pinyin":"yǎlíng","vi":"tạ tay"},{"hanzi":"举重","pinyin":"jǔzhòng","vi":"cử tạ"},{"hanzi":"健身","pinyin":"jiànshēn","vi":"tập thể hình"},{"hanzi":"器械","pinyin":"qìxiè","vi":"dụng cụ"}],"traditional":"槓鈴"},{"id":"缸","hanzi":"缸","pinyin":"gāng","meaning_vi":"chum, vại, bể","explanation":"缸 (cang – chum, vại) → đồ đựng miệng rộng đáy sâu bằng sành, sứ hoặc thủy tinh, như 水缸, 鱼缸.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🏺","examples":[{"type":"basic","zh":"鱼缸里有三条金鱼。","pinyin":"Yúgāng lǐ yǒu sāntiáo jīnyú.","vi":"Trong bể cá có ba con cá vàng."},{"type":"simple","zh":"院子里放着一口装满雨水的大缸。","pinyin":"Yuànzi lǐ fàngzhe yìkǒu zhuāngmǎn yǔshuǐ de dà gāng.","vi":"Trong sân đặt một chiếc chum lớn đầy nước mưa."},{"type":"compound","zh":"如果不经常换水，缸里的水就会发臭。","pinyin":"Rúguǒ bù jīngcháng huàn shuǐ, gāng lǐ de shuǐ jiù huì fāchòu.","vi":"Nếu không thay nước thường xuyên, nước trong bể sẽ bốc mùi."}],"related":[{"hanzi":"鱼缸","pinyin":"yúgāng","vi":"bể cá"},{"hanzi":"水缸","pinyin":"shuǐgāng","vi":"chum nước"},{"hanzi":"罐子","pinyin":"guànzi","vi":"hũ, lọ"},{"hanzi":"坛子","pinyin":"tánzi","vi":"vò"}]},{"id":"钢","hanzi":"钢","pinyin":"gāng","meaning_vi":"thép","explanation":"钢 (cương – thép) → kim loại hợp kim sắt cứng và bền; ví ý chí kiên cường (钢铁意志).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🔩","examples":[{"type":"basic","zh":"这座桥是钢做的。","pinyin":"Zhè zuò qiáo shì gāng zuò de.","vi":"Cây cầu này làm bằng thép."},{"type":"simple","zh":"这家工厂每年能生产几百万吨钢。","pinyin":"Zhè jiā gōngchǎng měinián néng shēngchǎn jǐ bǎiwàndūn gāng.","vi":"Nhà máy này mỗi năm sản xuất được vài triệu tấn thép."},{"type":"compound","zh":"虽然钢很坚硬，但是长期泡在海水里也会生锈。","pinyin":"Suīrán gāng hěn jiānyìng, dànshì chángqī pào zài hǎishuǐ lǐ yě huì shēngxiù.","vi":"Tuy thép rất cứng nhưng ngâm lâu trong nước biển cũng sẽ gỉ."}],"related":[{"hanzi":"钢铁","pinyin":"gāngtiě","vi":"gang thép"},{"hanzi":"铁","pinyin":"tiě","vi":"sắt"},{"hanzi":"不锈钢","pinyin":"búxiùgāng","vi":"thép không gỉ"},{"hanzi":"钢琴","pinyin":"gāngqín","vi":"đàn piano"}],"traditional":"鋼"},{"id":"港","hanzi":"港","pinyin":"gǎng","meaning_vi":"cảng, bến cảng; Hồng Kông","explanation":"港 (cảng – bến tàu) → nơi tàu thuyền neo đậu; cũng là tên gọi tắt của Hồng Kông (香港).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"⚓","examples":[{"type":"basic","zh":"船已经进港了。","pinyin":"Chuán yǐjīng jìn gǎng le.","vi":"Tàu đã vào cảng rồi."},{"type":"simple","zh":"这座港城每天有上百艘货轮进出。","pinyin":"Zhè zuò gǎng chéng měitiān yǒu shàng bǎi sōu huòlún jìnchū.","vi":"Thành phố cảng này mỗi ngày có hàng trăm tàu hàng ra vào."},{"type":"compound","zh":"因为台风快来了，所以渔船都提前回港避风。","pinyin":"Yīnwèi táifēng kuài lái le, suǒyǐ yúchuán dōu tíqián huí gǎng bìfēng.","vi":"Vì bão sắp đến nên tàu cá đều về cảng tránh bão sớm."}],"related":[{"hanzi":"港口","pinyin":"gǎngkǒu","vi":"bến cảng"},{"hanzi":"码头","pinyin":"mǎtóu","vi":"bến tàu"},{"hanzi":"香港","pinyin":"Xiānggǎng","vi":"Hồng Kông"},{"hanzi":"海港","pinyin":"hǎigǎng","vi":"cảng biển"}]},{"id":"高调","hanzi":"高调","pinyin":"gāodiào","meaning_vi":"phô trương, rầm rộ; lời lẽ cao siêu","explanation":"高 (cao) + 调 (điệu – giọng điệu) → giọng cao; nghĩa bóng là phô trương, gây chú ý, đối lập với 低调.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📣","examples":[{"type":"basic","zh":"他做事很高调。","pinyin":"Tā zuòshì hěn gāodiào.","vi":"Anh ta làm việc rất phô trương."},{"type":"simple","zh":"这对明星高调宣布了结婚的消息。","pinyin":"Zhè duì míngxīng gāodiào xuānbùle jiéhūn de xiāoxi.","vi":"Cặp ngôi sao này rầm rộ công bố tin kết hôn."},{"type":"compound","zh":"与其在网上高调炫富，不如低调做点实事。","pinyin":"Yǔqí zài wǎngshàng gāodiào xuànfù, bùrú dīdiào zuò diǎn shíshì.","vi":"Thay vì khoe giàu phô trương trên mạng, chi bằng lặng lẽ làm việc thiết thực."}],"related":[{"hanzi":"低调","pinyin":"dīdiào","vi":"khiêm tốn, kín tiếng"},{"hanzi":"张扬","pinyin":"zhāngyáng","vi":"phô trương"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"唱高调","pinyin":"chànggāodiào","vi":"nói suông"}],"traditional":"高調"},{"id":"高额","hanzi":"高额","pinyin":"gāo'é","meaning_vi":"mức cao, số tiền lớn","explanation":"高 (cao) + 额 (ngạch – định mức) → mức tiền, số lượng cao; thường đứng trước danh từ như 高额奖金, 高额罚款.","hsk_level":"7-9","tags":["tinh-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"他获得了高额奖金。","pinyin":"Tā huòdéle gāo'é jiǎngjīn.","vi":"Anh ấy nhận được khoản thưởng lớn."},{"type":"simple","zh":"违规停车可能会被处以高额罚款。","pinyin":"Wéiguī tíngchē kěnéng huì bèi chǔ yǐ gāo'é fákuǎn.","vi":"Đỗ xe sai quy định có thể bị phạt tiền nặng."},{"type":"compound","zh":"虽然这份工作提供高额工资，但是经常要加班到半夜。","pinyin":"Suīrán zhè fèn gōngzuò tígōng gāo'é gōngzī, dànshì jīngcháng yào jiābān dào bànyè.","vi":"Tuy công việc này trả lương cao nhưng thường phải tăng ca đến nửa đêm."}],"related":[{"hanzi":"巨额","pinyin":"jù'é","vi":"số tiền khổng lồ"},{"hanzi":"金额","pinyin":"jīn'é","vi":"số tiền"},{"hanzi":"低额","pinyin":"dī'é","vi":"mức thấp"},{"hanzi":"高昂","pinyin":"gāo'áng","vi":"đắt đỏ"}],"traditional":"高額"},{"id":"高峰期","hanzi":"高峰期","pinyin":"gāofēngqī","meaning_vi":"giờ cao điểm, thời kỳ cao điểm","explanation":"高峰 (cao phong – đỉnh cao) + 期 (kỳ – thời kỳ) → giai đoạn lượng người, xe, công việc lên cao nhất.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"现在是高峰期。","pinyin":"Xiànzài shì gāofēngqī.","vi":"Bây giờ là giờ cao điểm."},{"type":"simple","zh":"节假日是旅游景点的客流高峰期。","pinyin":"Jiéjiàrì shì lǚyóu jǐngdiǎn de kèliú gāofēngqī.","vi":"Ngày lễ là thời kỳ cao điểm lượng khách ở các điểm du lịch."},{"type":"compound","zh":"如果你在高峰期打车，就要做好多等一会儿的准备。","pinyin":"Rúguǒ nǐ zài gāofēngqī dǎchē, jiùyào zuò hǎoduō děng yíhuìr de zhǔnbèi.","vi":"Nếu bạn gọi xe vào giờ cao điểm thì phải chuẩn bị tinh thần đợi lâu hơn."}],"related":[{"hanzi":"高峰","pinyin":"gāofēng","vi":"cao điểm"},{"hanzi":"早高峰","pinyin":"zǎogāofēng","vi":"cao điểm buổi sáng"},{"hanzi":"低谷","pinyin":"dīgǔ","vi":"thấp điểm"},{"hanzi":"堵车","pinyin":"dǔchē","vi":"tắc đường"}]},{"id":"高贵","hanzi":"高贵","pinyin":"gāoguì","meaning_vi":"cao quý, sang trọng","explanation":"高 (cao) + 贵 (quý – quý giá) → cao quý về phẩm chất hoặc sang trọng về địa vị, phong thái.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"她气质很高贵。","pinyin":"Tā qìzhì hěn gāoguì.","vi":"Khí chất cô ấy rất sang trọng."},{"type":"simple","zh":"这件礼服的设计显得优雅而高贵。","pinyin":"Zhè jiàn lǐfú de shèjì xiǎnde yōuyǎ ér gāoguì.","vi":"Thiết kế chiếc lễ phục này trông thanh lịch và sang trọng."},{"type":"compound","zh":"虽然他出身并不高贵，但是品格让所有人都尊敬他。","pinyin":"Suīrán tā chūshēn bìngbù gāoguì, dànshì pǐngé ràng suǒyǒurén dōu zūnjìng tā.","vi":"Tuy xuất thân không cao quý nhưng phẩm cách của anh ấy khiến mọi người kính trọng."}],"related":[{"hanzi":"尊贵","pinyin":"zūnguì","vi":"tôn quý"},{"hanzi":"高尚","pinyin":"gāoshàng","vi":"cao thượng"},{"hanzi":"优雅","pinyin":"yōuyǎ","vi":"thanh lịch"},{"hanzi":"卑贱","pinyin":"bēijiàn","vi":"hèn mọn"}],"traditional":"高貴"},{"id":"高空","hanzi":"高空","pinyin":"gāokōng","meaning_vi":"trên cao, không trung","explanation":"高 (cao) + 空 (không – bầu trời) → khoảng không ở độ cao lớn.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🪂","examples":[{"type":"basic","zh":"禁止高空抛物。","pinyin":"Jìnzhǐ gāokōng pāo wù.","vi":"Cấm ném đồ từ trên cao."},{"type":"simple","zh":"工人们系着安全绳在高空作业。","pinyin":"Gōngrénmen jìzhe ānquán shéng zài gāokōng zuòyè.","vi":"Công nhân thắt dây an toàn làm việc trên cao."},{"type":"compound","zh":"虽然高空跳伞很刺激，但是对身体条件要求很严格。","pinyin":"Suīrán gāokōng tiàosǎn hěn cìjī, dànshì duì shēntǐ tiáojiàn yāoqiú hěn yángé.","vi":"Tuy nhảy dù trên không rất kích thích nhưng yêu cầu thể chất rất nghiêm ngặt."}],"related":[{"hanzi":"天空","pinyin":"tiānkōng","vi":"bầu trời"},{"hanzi":"低空","pinyin":"dīkōng","vi":"tầm thấp"},{"hanzi":"高处","pinyin":"gāochù","vi":"chỗ cao"},{"hanzi":"空中","pinyin":"kōngzhōng","vi":"trên không"}]},{"id":"高山","hanzi":"高山","pinyin":"gāoshān","meaning_vi":"núi cao","explanation":"高 (cao) + 山 (sơn – núi) → ngọn núi cao.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"我们爬上了高山。","pinyin":"Wǒmen páshangle gāoshān.","vi":"Chúng tôi đã leo lên núi cao."},{"type":"simple","zh":"这种茶生长在云雾缭绕的高山上。","pinyin":"Zhè zhǒng chá shēngzhǎng zài yúnwù liáorào de gāoshān shang.","vi":"Loại trà này mọc trên núi cao mây mù bao phủ."},{"type":"compound","zh":"因为高山上空气稀薄，所以登山者要慢慢适应。","pinyin":"Yīnwèi gāoshān shangkōng qì xībó, suǒyǐ dēngshān zhě yào mànmàn shìyìng.","vi":"Vì trên núi cao không khí loãng nên người leo núi phải thích nghi từ từ."}],"related":[{"hanzi":"山峰","pinyin":"shānfēng","vi":"đỉnh núi"},{"hanzi":"高原","pinyin":"gāoyuán","vi":"cao nguyên"},{"hanzi":"登山","pinyin":"dēngshān","vi":"leo núi"},{"hanzi":"平原","pinyin":"píngyuán","vi":"đồng bằng"}]},{"id":"高效","hanzi":"高效","pinyin":"gāoxiào","meaning_vi":"hiệu quả cao, hiệu suất cao","explanation":"高 (cao) + 效 (hiệu – hiệu quả) → làm việc đạt hiệu quả cao, ít tốn thời gian.","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"他工作很高效。","pinyin":"Tā gōngzuò hěn gāoxiào.","vi":"Anh ấy làm việc rất hiệu quả."},{"type":"simple","zh":"这款新电池可以高效地储存太阳能。","pinyin":"Zhè kuǎn xīn diànchí kěyǐ gāoxiào de chǔcún tàiyángnéng.","vi":"Loại pin mới này có thể lưu trữ năng lượng mặt trời hiệu quả."},{"type":"compound","zh":"只要合理安排时间，学习就能变得更高效。","pinyin":"Zhǐyào hélǐ ānpái shíjiān, xuéxí jiù néng biànde gèng gāoxiào.","vi":"Chỉ cần sắp xếp thời gian hợp lý, việc học sẽ hiệu quả hơn."}],"related":[{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"},{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu quả"},{"hanzi":"低效","pinyin":"dīxiào","vi":"kém hiệu quả"},{"hanzi":"快捷","pinyin":"kuàijié","vi":"nhanh chóng"}]},{"id":"高压","hanzi":"高压","pinyin":"gāoyā","meaning_vi":"áp suất cao, điện cao thế; áp lực lớn","explanation":"高 (cao) + 压 (áp – ép) → áp suất hoặc điện áp cao; nghĩa bóng là sức ép lớn, cách cai trị hà khắc.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔌","examples":[{"type":"basic","zh":"高压危险！","pinyin":"Gāoyā wēixiǎn!","vi":"Nguy hiểm điện cao thế!"},{"type":"simple","zh":"他长期在高压环境下工作，身体越来越差。","pinyin":"Tā chángqī zài gāoyā huánjìng xià gōngzuò, shēntǐ yuèláiyuè chà.","vi":"Anh ấy lâu ngày làm việc trong môi trường áp lực cao, sức khỏe ngày càng kém."},{"type":"compound","zh":"如果用高压锅炖肉，那么半小时就能炖烂。","pinyin":"Rúguǒ yòng gāoyāguō dùnròu, nàme bànxiǎoshí jiù néng dùn làn.","vi":"Nếu dùng nồi áp suất hầm thịt thì nửa tiếng là nhừ."}],"related":[{"hanzi":"高压锅","pinyin":"gāoyāguō","vi":"nồi áp suất"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"血压","pinyin":"xuèyā","vi":"huyết áp"},{"hanzi":"低压","pinyin":"dīyā","vi":"áp thấp"}],"traditional":"高壓"},{"id":"搞鬼","hanzi":"搞鬼","pinyin":"gǎoguǐ","meaning_vi":"giở trò, giở trò ma mãnh","explanation":"搞 (cảo – làm) + 鬼 (quỷ – ma quỷ) → làm trò ma quỷ, lén lút giở mánh khóe.","hsk_level":"7-9","tags":["dong-tu"],"image":"👻","examples":[{"type":"basic","zh":"一定是他在搞鬼。","pinyin":"Yídìng shì tā zài gǎoguǐ.","vi":"Chắc chắn là hắn đang giở trò."},{"type":"simple","zh":"电脑突然死机，好像有病毒在搞鬼。","pinyin":"Diànnǎo tūrán sǐjī, hǎoxiàng yǒu bìngdú zài gǎoguǐ.","vi":"Máy tính đột nhiên treo, hình như có virus đang quấy phá."},{"type":"compound","zh":"要是你再敢背后搞鬼，我就把事情告诉老板。","pinyin":"Yàoshi nǐ zài gǎn bèihòu gǎoguǐ, wǒ jiù bǎ shìqing gàosu lǎobǎn.","vi":"Nếu mày còn dám giở trò sau lưng, tao sẽ nói chuyện này với sếp."}],"related":[{"hanzi":"捣鬼","pinyin":"dǎoguǐ","vi":"giở trò"},{"hanzi":"耍花招","pinyin":"shuǎhuāzhāo","vi":"giở mánh khóe"},{"hanzi":"做手脚","pinyin":"zuòshǒujiǎo","vi":"giở thủ đoạn"},{"hanzi":"阴谋","pinyin":"yīnmóu","vi":"âm mưu"}]},{"id":"搞笑","hanzi":"搞笑","pinyin":"gǎoxiào","meaning_vi":"gây cười, hài hước","explanation":"搞 (cảo – làm) + 笑 (tiếu – cười) → làm cho người khác cười; khẩu ngữ, nghĩa là buồn cười, hài.","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"😂","examples":[{"type":"basic","zh":"这部电影很搞笑。","pinyin":"Zhè bù diànyǐng hěn gǎoxiào.","vi":"Bộ phim này rất hài hước."},{"type":"simple","zh":"他在视频里模仿老师，搞笑极了。","pinyin":"Tā zài shìpín lǐ mófǎng lǎoshī, gǎoxiào jíle.","vi":"Cậu ấy bắt chước thầy giáo trong video, buồn cười hết sức."},{"type":"compound","zh":"虽然他平时很严肃，但是一喝酒就变得特别搞笑。","pinyin":"Suīrán tā píngshí hěn yánsù, dànshì yì hējiǔ jiù biànde tèbié gǎoxiào.","vi":"Tuy bình thường anh ấy rất nghiêm túc nhưng cứ uống rượu là trở nên cực kỳ hài."}],"related":[{"hanzi":"幽默","pinyin":"yōumò","vi":"hài hước"},{"hanzi":"好笑","pinyin":"hǎoxiào","vi":"buồn cười"},{"hanzi":"逗","pinyin":"dòu","vi":"chọc cười"},{"hanzi":"喜剧","pinyin":"xǐjù","vi":"hài kịch"}]},{"id":"告","hanzi":"告","pinyin":"gào","meaning_vi":"báo, nói cho biết; kiện","explanation":"告 (cáo – báo cho biết) → nói cho biết, thông báo; còn có nghĩa kiện cáo (告状, 告他).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📨","examples":[{"type":"basic","zh":"我要去法院告他。","pinyin":"Wǒ yào qù fǎyuàn gào tā.","vi":"Tôi sẽ ra tòa kiện hắn."},{"type":"simple","zh":"他把这件事告到了公司总部。","pinyin":"Tā bǎ zhè jiàn shì gào dàole gōngsī zǒngbù.","vi":"Anh ấy đã khiếu nại chuyện này lên tận trụ sở công ty."},{"type":"compound","zh":"如果商家还不退款，我们就去消费者协会告他们。","pinyin":"Rúguǒ shāngjiā hái bú tuìkuǎn, wǒmen jiù qù xiāofèizhě xiéhuì gào tāmen.","vi":"Nếu cửa hàng vẫn không hoàn tiền, chúng tôi sẽ đến hội người tiêu dùng khiếu nại họ."}],"related":[{"hanzi":"告诉","pinyin":"gàosu","vi":"nói cho biết"},{"hanzi":"告状","pinyin":"gàozhuàng","vi":"mách, kiện"},{"hanzi":"控告","pinyin":"kònggào","vi":"tố cáo"},{"hanzi":"报告","pinyin":"bàogào","vi":"báo cáo"}]},{"id":"告知","hanzi":"告知","pinyin":"gàozhī","meaning_vi":"thông báo, cho biết","explanation":"告 (cáo – báo) + 知 (tri – biết) → báo cho biết; cách nói trang trọng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📢","examples":[{"type":"basic","zh":"请告知您的地址。","pinyin":"Qǐng gàozhī nín de dìzhǐ.","vi":"Xin cho biết địa chỉ của quý vị."},{"type":"simple","zh":"航空公司提前告知乘客航班取消了。","pinyin":"Hángkōng gōngsī tíqián gàozhī chéngkè hángbān qǔxiāo le.","vi":"Hãng hàng không thông báo trước cho hành khách rằng chuyến bay bị hủy."},{"type":"compound","zh":"如果您的联系方式有变化，请及时告知我们。","pinyin":"Rúguǒ nín de liánxì fāngshì yǒu biànhuà, qǐng jíshí gàozhī wǒmen.","vi":"Nếu thông tin liên lạc của quý vị thay đổi, xin kịp thời báo cho chúng tôi."}],"related":[{"hanzi":"通知","pinyin":"tōngzhī","vi":"thông báo"},{"hanzi":"告诉","pinyin":"gàosu","vi":"nói cho biết"},{"hanzi":"通告","pinyin":"tōnggào","vi":"thông cáo"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"}]},{"id":"戈壁","hanzi":"戈壁","pinyin":"Gēbì","meaning_vi":"sa mạc Gobi, sa mạc đá sỏi","explanation":"戈壁 (qua bích) là phiên âm từ tiếng Mông Cổ, nghĩa là vùng đất khô cằn → chỉ sa mạc Gobi hoặc vùng hoang mạc đá sỏi nói chung.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"戈壁上风很大。","pinyin":"Gēbì shàngfēng hěn dà.","vi":"Trên sa mạc Gobi gió rất to."},{"type":"simple","zh":"我们开车穿过了一望无际的戈壁。","pinyin":"Wǒmen kāichē chuānguòle yí wàng wújì de Gēbì.","vi":"Chúng tôi lái xe băng qua vùng sa mạc mênh mông bất tận."},{"type":"compound","zh":"虽然戈壁上几乎没有水，但是骆驼照样能走好几天。","pinyin":"Suīrán Gēbì shàng jīhū méiyǒu shuǐ, dànshì luòtuo zhàoyàng néng zǒu hǎo jǐtiān.","vi":"Tuy trên sa mạc gần như không có nước nhưng lạc đà vẫn đi được mấy ngày liền."}],"related":[{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"荒漠","pinyin":"huāngmò","vi":"hoang mạc"},{"hanzi":"草原","pinyin":"cǎoyuán","vi":"thảo nguyên"},{"hanzi":"骆驼","pinyin":"luòtuo","vi":"lạc đà"}]},{"id":"胳膊","hanzi":"胳膊","pinyin":"gēbo","meaning_vi":"cánh tay","explanation":"胳 (cách – nách, cánh tay) + 膊 (bác – cánh tay) → phần tay từ vai đến cổ tay; cách nói khẩu ngữ thường dùng.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"我的胳膊很酸。","pinyin":"Wǒ de gēbo hěn suān.","vi":"Cánh tay tôi rất mỏi."},{"type":"simple","zh":"孩子摔倒时胳膊上擦破了一块皮。","pinyin":"Háizi shuāidǎo shí gēbo shàng cā pòle yíkuài pí.","vi":"Lúc ngã, cánh tay đứa bé bị trầy một mảng da."},{"type":"compound","zh":"因为昨天搬了一整天家具，所以今天胳膊抬不起来。","pinyin":"Yīnwèi zuótiān bānle yìzhěngtiān jiājù, suǒyǐ jīntiān gēbo tái bu qǐlái.","vi":"Vì hôm qua khuân đồ đạc cả ngày nên hôm nay cánh tay không nhấc lên nổi."}],"related":[{"hanzi":"手臂","pinyin":"shǒubì","vi":"cánh tay"},{"hanzi":"胳膊肘","pinyin":"gēbozhǒu","vi":"khuỷu tay"},{"hanzi":"肩膀","pinyin":"jiānbǎng","vi":"vai"},{"hanzi":"大腿","pinyin":"dàtuǐ","vi":"đùi"}]},{"id":"搁浅","hanzi":"搁浅","pinyin":"gēqiǎn","meaning_vi":"mắc cạn; bị đình trệ, bế tắc","explanation":"搁 (các – gác, mắc lại) + 浅 (thiển – nông) → tàu thuyền kẹt chỗ nước nông; nghĩa bóng: công việc, kế hoạch bị đình lại giữa chừng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚢","examples":[{"type":"basic","zh":"一艘货船搁浅了。","pinyin":"Yì sōu huòchuán gēqiǎn le.","vi":"Một chiếc tàu hàng bị mắc cạn."},{"type":"simple","zh":"由于资金不足，这个项目暂时搁浅了。","pinyin":"Yóuyú zījīn bùzú, zhè ge xiàngmù zànshí gēqiǎn le.","vi":"Do thiếu vốn, dự án này tạm thời bị đình trệ."},{"type":"compound","zh":"如果谈判再这样拖下去，合作计划就会彻底搁浅。","pinyin":"Rúguǒ tánpàn zài zhèyàng tuō xiàqù, hézuò jìhuà jiù huì chèdǐ gēqiǎn.","vi":"Nếu đàm phán cứ kéo dài thế này thì kế hoạch hợp tác sẽ hoàn toàn bế tắc."}],"related":[{"hanzi":"搁置","pinyin":"gēzhì","vi":"gác lại"},{"hanzi":"停滞","pinyin":"tíngzhì","vi":"đình trệ"},{"hanzi":"触礁","pinyin":"chùjiāo","vi":"mắc đá ngầm"},{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"}],"traditional":"擱淺"},{"id":"搁置","hanzi":"搁置","pinyin":"gēzhì","meaning_vi":"gác lại, tạm hoãn","explanation":"搁 (các – gác, để) + 置 (trí – đặt) → để sang một bên, tạm thời không xử lý; hay dùng với 问题、计划、争议.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗄️","examples":[{"type":"basic","zh":"这件事先搁置吧。","pinyin":"Zhè jiàn shìxiān gēzhì ba.","vi":"Việc này tạm gác lại đã."},{"type":"simple","zh":"会议决定暂时搁置这项提案。","pinyin":"Huìyì juédìng zànshí gēzhì zhè xiàng tí'àn.","vi":"Cuộc họp quyết định tạm gác đề xuất này."},{"type":"compound","zh":"虽然问题被搁置了半年，但是大家始终没有忘记它。","pinyin":"Suīrán wèntí bèi gēzhìle bàn nián, dànshì dàjiā shǐzhōng méiyǒu wàngjì tā.","vi":"Tuy vấn đề bị gác lại nửa năm nhưng mọi người chưa bao giờ quên nó."}],"related":[{"hanzi":"搁浅","pinyin":"gēqiǎn","vi":"bị đình trệ"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"hoãn lại"},{"hanzi":"暂停","pinyin":"zàntíng","vi":"tạm dừng"},{"hanzi":"放置","pinyin":"fàngzhì","vi":"để, đặt"}],"traditional":"擱置"},{"id":"革命","hanzi":"革命","pinyin":"gémìng","meaning_vi":"cách mạng; làm cách mạng","explanation":"革 (cách – thay đổi) + 命 (mệnh – mệnh trời) → nghĩa gốc là đổi mệnh trời, thay triều đại; nay chỉ cuộc cách mạng hoặc sự thay đổi căn bản.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"这是一场技术革命。","pinyin":"Zhè shì yì chǎng jìshù gémìng.","vi":"Đây là một cuộc cách mạng công nghệ."},{"type":"simple","zh":"智能手机给人们的生活带来了一场革命。","pinyin":"Zhìnéng shǒujī gěi rénmen de shēnghuó dàiláile yì chǎng gémìng.","vi":"Điện thoại thông minh đã mang đến một cuộc cách mạng cho đời sống con người."},{"type":"compound","zh":"如果没有工业革命，人类社会就不会发展得这么快。","pinyin":"Rúguǒ méiyǒu Gōngyègémìng, rénlèi shèhuì jiù bú huì fāzhǎn de zhème kuài.","vi":"Nếu không có cách mạng công nghiệp thì xã hội loài người đã không phát triển nhanh như vậy."}],"related":[{"hanzi":"革新","pinyin":"géxīn","vi":"đổi mới"},{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"},{"hanzi":"变革","pinyin":"biàngé","vi":"biến đổi lớn"},{"hanzi":"起义","pinyin":"qǐyì","vi":"khởi nghĩa"}]},{"id":"格","hanzi":"格","pinyin":"gé","meaning_vi":"ô, ô vuông; khuôn khổ, quy cách","explanation":"格 (cách – ô kẻ, khuôn phép) → ô vuông kẻ sẵn, rộng ra là khuôn khổ, quy cách; gặp trong 格子, 表格, 性格.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔲","examples":[{"type":"basic","zh":"每格写一个字。","pinyin":"Měi gé xiě yí ge zì.","vi":"Mỗi ô viết một chữ."},{"type":"simple","zh":"小学生用的作文本上印满了方格。","pinyin":"Xiǎoxuéshēng yòng de zuò wénběn shàng yìn mǎnle fānggé.","vi":"Vở tập làm văn của học sinh tiểu học in kín ô vuông."},{"type":"compound","zh":"因为这张表格每格都很小，所以字要写得工整一点。","pinyin":"Yīnwèi zhè zhāng biǎogé měi gé dōu hěn xiǎo, suǒyǐ zì yào xiě de gōngzhěng yīdiǎn.","vi":"Vì mỗi ô của bảng này rất nhỏ nên chữ phải viết ngay ngắn một chút."}],"related":[{"hanzi":"格子","pinyin":"gézi","vi":"ô kẻ"},{"hanzi":"表格","pinyin":"biǎogé","vi":"bảng biểu"},{"hanzi":"规格","pinyin":"guīgé","vi":"quy cách"},{"hanzi":"性格","pinyin":"xìnggé","vi":"tính cách"}]},{"id":"个案","hanzi":"个案","pinyin":"gè'àn","meaning_vi":"trường hợp cá biệt, ca riêng lẻ","explanation":"个 (cá – riêng lẻ) + 案 (án – vụ việc) → một vụ việc, một trường hợp riêng; thường dùng để phân biệt với hiện tượng phổ biến.","hsk_level":"7-9","tags":["danh-tu"],"image":"📁","examples":[{"type":"basic","zh":"这只是个案。","pinyin":"Zhè zhǐshì gè'àn.","vi":"Đây chỉ là trường hợp cá biệt."},{"type":"simple","zh":"研究人员详细分析了十几个典型个案。","pinyin":"Yánjiū rényuán xiángxì fēnxīle shíjǐ ge diǎnxíng gè'àn.","vi":"Các nhà nghiên cứu đã phân tích chi tiết hơn chục trường hợp điển hình."},{"type":"compound","zh":"虽然这种事故只是个案，但是我们也不能掉以轻心。","pinyin":"Suīrán zhè zhǒng shìgù zhǐshì gè'àn, dànshì wǒmen yě bù néng diàoyǐqīngxīn.","vi":"Tuy loại sự cố này chỉ là trường hợp cá biệt nhưng chúng ta cũng không được lơ là."}],"related":[{"hanzi":"个别","pinyin":"gèbié","vi":"cá biệt"},{"hanzi":"案例","pinyin":"ànlì","vi":"ví dụ điển hình"},{"hanzi":"案件","pinyin":"ànjiàn","vi":"vụ án"},{"hanzi":"普遍","pinyin":"pǔbiàn","vi":"phổ biến"}],"traditional":"個案"},{"id":"个头儿","hanzi":"个头儿","pinyin":"gètóur","meaning_vi":"vóc dáng, chiều cao; kích cỡ","explanation":"个 (cá – cá thể) + 头 (đầu) + 儿 (nhi – hậu tố âm cuốn lưỡi) → khẩu ngữ chỉ vóc người hoặc kích cỡ của đồ vật, hoa quả.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"📏","examples":[{"type":"basic","zh":"他个头儿不高。","pinyin":"Tā gètóur bù gāo.","vi":"Anh ấy dáng người không cao."},{"type":"simple","zh":"今年市场上的苹果个头儿特别大。","pinyin":"Jīnnián shìchǎng shàng de píngguǒ gètóur tèbié dà.","vi":"Táo trên thị trường năm nay quả nào cũng rất to."},{"type":"compound","zh":"虽然弟弟个头儿比我矮，但是力气比我大多了。","pinyin":"Suīrán dìdi gètóur bǐ wǒ ǎi, dànshì lìqi bǐ wǒ dàduō le.","vi":"Tuy em trai thấp hơn tôi nhưng sức lực thì khỏe hơn tôi nhiều."}],"related":[{"hanzi":"个子","pinyin":"gèzi","vi":"vóc người"},{"hanzi":"身高","pinyin":"shēngāo","vi":"chiều cao"},{"hanzi":"身材","pinyin":"shēncái","vi":"dáng người"},{"hanzi":"块头","pinyin":"kuàitóu","vi":"thân hình to lớn"}],"traditional":"個頭兒"},{"id":"跟不上","hanzi":"跟不上","pinyin":"gēnbushàng","meaning_vi":"không theo kịp, tụt lại","explanation":"跟 (căn – đi theo) + 不上 (không lên được) → không bắt kịp tốc độ, trình độ của người khác hay của thời đại; trái nghĩa là 跟得上.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"我跟不上他。","pinyin":"Wǒ gēnbushàng tā.","vi":"Tôi không theo kịp anh ấy."},{"type":"simple","zh":"很多学生跟不上老师讲课的速度。","pinyin":"Hěn duō xuésheng gēnbushàng lǎoshī jiǎngkè de sùdù.","vi":"Nhiều học sinh không theo kịp tốc độ giảng bài của thầy."},{"type":"compound","zh":"如果不坚持学习新技术，你很快就会跟不上时代。","pinyin":"Rúguǒ bù jiānchí xuéxí xīnjìshù, nǐ hěn kuài jiù huì gēnbushàng shídài.","vi":"Nếu không kiên trì học công nghệ mới, bạn sẽ sớm bị tụt hậu so với thời đại."}],"related":[{"hanzi":"跟得上","pinyin":"gēndeshàng","vi":"theo kịp"},{"hanzi":"赶不上","pinyin":"gǎnbushàng","vi":"không đuổi kịp"},{"hanzi":"落后","pinyin":"luòhòu","vi":"tụt hậu"},{"hanzi":"跟随","pinyin":"gēnsuí","vi":"đi theo"}]},{"id":"耿直","hanzi":"耿直","pinyin":"gěngzhí","meaning_vi":"thẳng thắn, cương trực","explanation":"耿 (cảnh – ngay thẳng, trung thực) + 直 (trực – thẳng) → tính tình ngay thẳng, có gì nói nấy, không vòng vo.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧍","examples":[{"type":"basic","zh":"他为人很耿直。","pinyin":"Tā wéirén hěn gěngzhí.","vi":"Anh ấy làm người rất cương trực."},{"type":"simple","zh":"这位耿直的老记者从不说假话。","pinyin":"Zhè wèi gěngzhí de lǎo jìzhě cóng bù shuō jiǎhuà.","vi":"Vị nhà báo lão thành cương trực này chưa bao giờ nói dối."},{"type":"compound","zh":"因为他性格耿直，所以开会时常常得罪领导。","pinyin":"Yīnwèi tā xìnggé gěngzhí, suǒyǐ kāihuì shícháng cháng dézuì lǐngdǎo.","vi":"Vì tính tình thẳng thắn nên anh ấy hay làm mất lòng lãnh đạo khi họp."}],"related":[{"hanzi":"正直","pinyin":"zhèngzhí","vi":"chính trực"},{"hanzi":"直爽","pinyin":"zhíshuǎng","vi":"thẳng thắn"},{"hanzi":"坦率","pinyin":"tǎnshuài","vi":"bộc trực"},{"hanzi":"圆滑","pinyin":"yuánhuá","vi":"khéo đưa đẩy"}]},{"id":"更改","hanzi":"更改","pinyin":"gēnggǎi","meaning_vi":"thay đổi, sửa đổi","explanation":"更 (canh – đổi) + 改 (cải – sửa) → sửa đổi lại điều đã định như kế hoạch, thời gian, tên gọi.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"航班时间更改了。","pinyin":"Hángbān shíjiān gēnggǎi le.","vi":"Giờ chuyến bay đã thay đổi."},{"type":"simple","zh":"注册以后用户名就不能再更改了。","pinyin":"Zhùcè yǐhòu yònghùmíng jiù bù néng zài gēnggǎi le.","vi":"Sau khi đăng ký thì không thể đổi tên người dùng nữa."},{"type":"compound","zh":"如果需要更改订单，请在发货前联系客服。","pinyin":"Rúguǒ xūyào gēnggǎi dìngdān, qǐng zài fāhuò qián liánxì kèfú.","vi":"Nếu cần thay đổi đơn hàng, xin liên hệ bộ phận chăm sóc khách hàng trước khi giao hàng."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa chữa"},{"hanzi":"改变","pinyin":"gǎibiàn","vi":"thay đổi"},{"hanzi":"变更","pinyin":"biàngēng","vi":"thay đổi"},{"hanzi":"更正","pinyin":"gēngzhèng","vi":"đính chính"}]},{"id":"工科","hanzi":"工科","pinyin":"gōngkē","meaning_vi":"khối kỹ thuật, ngành kỹ thuật","explanation":"工 (công – kỹ thuật, công nghiệp) + 科 (khoa – ngành học) → các ngành học về kỹ thuật, công trình; phân biệt với 文科 và 理科.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🔧","examples":[{"type":"basic","zh":"他是工科生。","pinyin":"Tā shì gōngkē shēng.","vi":"Cậu ấy là sinh viên khối kỹ thuật."},{"type":"simple","zh":"这所大学的工科专业在全国很有名。","pinyin":"Zhè suǒ dàxué de gōngkē zhuānyè zài quánguó hěn yǒumíng.","vi":"Các ngành kỹ thuật của trường đại học này rất nổi tiếng cả nước."},{"type":"compound","zh":"虽然她读的是工科，但是毕业后当了一名作家。","pinyin":"Suīrán tā dú de shì gōngkē, dànshì bìyè hòu dāngle yì míng zuòjiā.","vi":"Tuy cô ấy học ngành kỹ thuật nhưng sau khi tốt nghiệp lại trở thành nhà văn."}],"related":[{"hanzi":"理科","pinyin":"lǐkē","vi":"khối tự nhiên"},{"hanzi":"文科","pinyin":"wénkē","vi":"khối xã hội"},{"hanzi":"工程","pinyin":"gōngchéng","vi":"công trình, kỹ thuật"},{"hanzi":"学科","pinyin":"xuékē","vi":"môn học, ngành học"}]},{"id":"工整","hanzi":"工整","pinyin":"gōngzhěng","meaning_vi":"ngay ngắn, chỉn chu, cẩn thận","explanation":"工 (công – khéo léo) + 整 (chỉnh – ngay ngắn) → làm khéo và ngay ngắn, thường dùng khen chữ viết hoặc câu đối.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📝","examples":[{"type":"basic","zh":"他的字很工整。","pinyin":"Tā de zì hěn gōngzhěng.","vi":"Chữ của anh ấy rất ngay ngắn."},{"type":"simple","zh":"她用工整的小楷抄写了一首古诗。","pinyin":"Tā yòng gōngzhěng de xiǎo kǎi chāoxiěle yì shǒu gǔshī.","vi":"Cô ấy dùng chữ khải nhỏ ngay ngắn chép lại một bài thơ cổ."},{"type":"compound","zh":"只要卷面写得工整，老师就会多给你一两分。","pinyin":"Zhǐyào juàn miàn xiě de gōngzhěng, lǎoshī jiù huì duō gěi nǐ yī liǎng fēn.","vi":"Chỉ cần bài thi viết ngay ngắn, thầy cô sẽ cho bạn thêm một hai điểm."}],"related":[{"hanzi":"整齐","pinyin":"zhěngqí","vi":"ngay ngắn"},{"hanzi":"端正","pinyin":"duānzhèng","vi":"đoan chính"},{"hanzi":"潦草","pinyin":"liáocǎo","vi":"nguệch ngoạc"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"nghiêm túc"}]},{"id":"工作量","hanzi":"工作量","pinyin":"gōngzuòliàng","meaning_vi":"khối lượng công việc","explanation":"工作 (công tác – công việc) + 量 (lượng – số lượng) → tổng lượng việc phải làm trong một khoảng thời gian.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"最近工作量很大。","pinyin":"Zuìjìn gōngzuòliàng hěn dà.","vi":"Dạo này khối lượng công việc rất lớn."},{"type":"simple","zh":"新系统上线后大家的工作量减少了一半。","pinyin":"Xīn xìtǒng shàngxiàn hòu dàjiā de gōngzuòliàng jiǎnshǎole yíbàn.","vi":"Sau khi hệ thống mới đi vào hoạt động, khối lượng công việc của mọi người giảm một nửa."},{"type":"compound","zh":"因为同事请了产假，所以我的工作量一下子翻了一倍。","pinyin":"Yīnwèi tóngshì qǐngle chǎnjià, suǒyǐ wǒ de gōngzuòliàng yíxiàzi fānle yí bèi.","vi":"Vì đồng nghiệp nghỉ thai sản nên khối lượng công việc của tôi bỗng tăng gấp đôi."}],"related":[{"hanzi":"工作","pinyin":"gōngzuò","vi":"công việc"},{"hanzi":"任务","pinyin":"rènwu","vi":"nhiệm vụ"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"},{"hanzi":"加班","pinyin":"jiābān","vi":"tăng ca"}]},{"id":"弓","hanzi":"弓","pinyin":"gōng","meaning_vi":"cái cung; khom, cong","explanation":"弓 (cung – cái cung) → vũ khí bắn tên có thân cong; cũng dùng chỉ động tác khom lưng như 弓着腰.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🏹","examples":[{"type":"basic","zh":"他拉开了弓。","pinyin":"Tā lākāile gōng.","vi":"Anh ấy giương cung lên."},{"type":"simple","zh":"古代士兵常用弓和箭作战。","pinyin":"Gǔdài shìbīng chángyòng gōng hé jiàn zuòzhàn.","vi":"Binh lính thời xưa thường dùng cung tên để chiến đấu."},{"type":"compound","zh":"虽然这把弓看起来很旧，但是射出去的箭依然很准。","pinyin":"Suīrán zhè bǎ gōng kànqǐlái hěn jiù, dànshì shè chūqù de jiàn yīrán hěn zhǔn.","vi":"Tuy cây cung này trông rất cũ nhưng mũi tên bắn ra vẫn rất chuẩn."}],"related":[{"hanzi":"弓箭","pinyin":"gōngjiàn","vi":"cung tên"},{"hanzi":"射箭","pinyin":"shèjiàn","vi":"bắn cung"},{"hanzi":"弹弓","pinyin":"dàngōng","vi":"ná cao su"},{"hanzi":"弯曲","pinyin":"wānqū","vi":"cong queo"}]},{"id":"公安局","hanzi":"公安局","pinyin":"gōng'ānjú","meaning_vi":"sở công an, cục công an","explanation":"公安 (công an – an ninh công cộng) + 局 (cục – cơ quan) → cơ quan công an cấp thành phố hoặc quận huyện.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🚓","examples":[{"type":"basic","zh":"他去公安局报案。","pinyin":"Tā qù gōng'ānjú bào'àn.","vi":"Anh ấy đến sở công an trình báo."},{"type":"simple","zh":"办护照要先到公安局出入境窗口排队。","pinyin":"Bàn hùzhào yào xiān dào gōng'ānjú chūrùjìng chuāngkǒu páiduì.","vi":"Làm hộ chiếu phải đến xếp hàng ở quầy xuất nhập cảnh của sở công an trước."},{"type":"compound","zh":"如果钱包被偷了，你就应该马上去公安局报警。","pinyin":"Rúguǒ qián bāobèi tōu le, nǐ jiù yīnggāi mǎshàng qù gōng'ānjú bàojǐng.","vi":"Nếu bị trộm ví, bạn nên lập tức đến sở công an báo án."}],"related":[{"hanzi":"公安","pinyin":"gōng'ān","vi":"công an"},{"hanzi":"派出所","pinyin":"pàichūsuǒ","vi":"đồn công an"},{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"报警","pinyin":"bàojǐng","vi":"báo cảnh sát"}]},{"id":"公车","hanzi":"公车","pinyin":"gōngchē","meaning_vi":"xe buýt; xe công","explanation":"公 (công – chung, nhà nước) + 车 (xa – xe) → xe buýt công cộng, hoặc xe của cơ quan dùng cho việc công.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚌","examples":[{"type":"basic","zh":"我坐公车上班。","pinyin":"Wǒ zuò gōngchē shàngbān.","vi":"Tôi đi xe buýt đi làm."},{"type":"simple","zh":"有些官员用公车办私事受到了处分。","pinyin":"Yǒuxiē guānyuán yòng gōngchē bàn sīshì shòudàole chǔfèn.","vi":"Một số quan chức dùng xe công làm việc riêng đã bị kỷ luật."},{"type":"compound","zh":"因为公车站就在家门口，所以她每天都不用开车。","pinyin":"Yīnwèi gōngchē zhàn jiù zài jiāmén kǒu, suǒyǐ tā měitiān dōu bú yòng kāichē.","vi":"Vì trạm xe buýt ngay trước cửa nhà nên ngày nào cô ấy cũng không phải lái xe."}],"related":[{"hanzi":"公交车","pinyin":"gōngjiāochē","vi":"xe buýt"},{"hanzi":"公共汽车","pinyin":"gōnggòngqìchē","vi":"xe buýt công cộng"},{"hanzi":"私家车","pinyin":"sījiāchē","vi":"xe riêng"},{"hanzi":"车站","pinyin":"chēzhàn","vi":"bến xe"}],"traditional":"公車"},{"id":"公费","hanzi":"公费","pinyin":"gōngfèi","meaning_vi":"kinh phí nhà nước, tiền công","explanation":"公 (công – nhà nước, tập thể) + 费 (phí – chi phí) → khoản chi do nhà nước hoặc cơ quan trả; như 公费留学, 公费医疗.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他是公费留学。","pinyin":"Tā shì gōngfèi liúxué.","vi":"Anh ấy đi du học bằng kinh phí nhà nước."},{"type":"simple","zh":"这次培训的全部费用都由公费承担。","pinyin":"Zhè cì péixùn de quánbù fèiyòng dōu yóu gōngfèi chéngdān.","vi":"Toàn bộ chi phí khóa đào tạo lần này đều do kinh phí công chi trả."},{"type":"compound","zh":"即使是公费出差，我们也要尽量节省开支。","pinyin":"Jíshǐ shì gōngfèi chūchāi, wǒmen yě yào jǐnliàng jiéshěng kāizhī.","vi":"Dù là đi công tác bằng tiền công, chúng ta cũng phải cố gắng tiết kiệm chi tiêu."}],"related":[{"hanzi":"自费","pinyin":"zìfèi","vi":"tự túc chi phí"},{"hanzi":"公款","pinyin":"gōngkuǎn","vi":"công quỹ"},{"hanzi":"经费","pinyin":"jīngfèi","vi":"kinh phí"},{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"}],"traditional":"公費"},{"id":"公共场所","hanzi":"公共场所","pinyin":"gōnggòngchǎngsuǒ","meaning_vi":"nơi công cộng","explanation":"公共 (công cộng – chung cho mọi người) + 场所 (trường sở – nơi chốn) → nơi ai cũng có thể đến như công viên, nhà ga, rạp chiếu phim.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏛️","examples":[{"type":"basic","zh":"公共场所禁止吸烟。","pinyin":"Gōnggòngchǎngsuǒ jìnzhǐ xīyān.","vi":"Cấm hút thuốc ở nơi công cộng."},{"type":"simple","zh":"在公共场所大声打电话很不礼貌。","pinyin":"Zài gōnggòngchǎngsuǒ dàshēng dǎdiànhuà hěn bù lǐmào.","vi":"Gọi điện thoại to tiếng ở nơi công cộng là rất bất lịch sự."},{"type":"compound","zh":"如果在公共场所发现可疑物品，就要立刻通知保安。","pinyin":"Rúguǒ zài gōnggòngchǎngsuǒ fāxiàn kěyí wùpǐn, jiùyào lìkè tōngzhī bǎo'ān.","vi":"Nếu phát hiện đồ vật khả nghi ở nơi công cộng thì phải báo ngay cho bảo vệ."}],"related":[{"hanzi":"场所","pinyin":"chǎngsuǒ","vi":"nơi chốn"},{"hanzi":"公共","pinyin":"gōnggòng","vi":"công cộng"},{"hanzi":"公共设施","pinyin":"gōnggòngshèshī","vi":"cơ sở vật chất công cộng"},{"hanzi":"广场","pinyin":"guǎngchǎng","vi":"quảng trường"}],"traditional":"公共場所"},{"id":"公函","hanzi":"公函","pinyin":"gōnghán","meaning_vi":"công văn, công hàm","explanation":"公 (công – việc công) + 函 (hàm – thư) → thư từ chính thức qua lại giữa các cơ quan, tổ chức.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"✉️","examples":[{"type":"basic","zh":"我们收到一份公函。","pinyin":"Wǒmen shōudào yí fèn gōnghán.","vi":"Chúng tôi nhận được một công văn."},{"type":"simple","zh":"学校向教育局发了一封公函申请经费。","pinyin":"Xuéxiào xiàng jiàoyù jú fāle yì fēng gōnghán shēnqǐng jīngfèi.","vi":"Nhà trường gửi một công văn lên sở giáo dục xin kinh phí."},{"type":"compound","zh":"如果对方不出具正式公函，我们就不能提供这些资料。","pinyin":"Rúguǒ duìfāng bù chūjù zhèngshì gōnghán, wǒmen jiù bù néng tígōng zhèxiē zīliào.","vi":"Nếu phía bên kia không đưa ra công văn chính thức thì chúng tôi không thể cung cấp những tài liệu này."}],"related":[{"hanzi":"公文","pinyin":"gōngwén","vi":"công văn"},{"hanzi":"信函","pinyin":"xìnhán","vi":"thư từ"},{"hanzi":"便函","pinyin":"biànhán","vi":"thư không chính thức"},{"hanzi":"文件","pinyin":"wénjiàn","vi":"văn bản"}]},{"id":"公开信","hanzi":"公开信","pinyin":"gōngkāixìn","meaning_vi":"thư ngỏ","explanation":"公开 (công khai) + 信 (tín – thư) → bức thư gửi một người hoặc một nhóm nhưng công bố cho mọi người cùng đọc.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"📜","examples":[{"type":"basic","zh":"她写了一封公开信。","pinyin":"Tā xiěle yì fēng gōngkāixìn.","vi":"Cô ấy đã viết một bức thư ngỏ."},{"type":"simple","zh":"几百名科学家联名发表了一封公开信。","pinyin":"Jǐ bǎi míng kēxuéjiā liánmíng fābiǎole yì fēng gōngkāixìn.","vi":"Vài trăm nhà khoa học cùng ký tên công bố một bức thư ngỏ."},{"type":"compound","zh":"虽然那封公开信只有几百字，但是在网上引起了很大反响。","pinyin":"Suīrán nà fēng gōngkāixìn zhǐyǒu jǐ bǎi zì, dànshì zài wǎngshàng yǐnqǐle hěn dà fǎnxiǎng.","vi":"Tuy bức thư ngỏ đó chỉ có vài trăm chữ nhưng đã gây tiếng vang lớn trên mạng."}],"related":[{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"书信","pinyin":"shūxìn","vi":"thư từ"},{"hanzi":"声明","pinyin":"shēngmíng","vi":"tuyên bố"},{"hanzi":"倡议书","pinyin":"chàngyìshū","vi":"thư kêu gọi"}],"traditional":"公開信"},{"id":"公款","hanzi":"公款","pinyin":"gōngkuǎn","meaning_vi":"tiền công, công quỹ","explanation":"公 (công – nhà nước, tập thể) + 款 (khoản – khoản tiền) → tiền thuộc về nhà nước hay tập thể; hay gặp trong 挪用公款, 公款吃喝.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"他挪用了公款。","pinyin":"Tā nuóyòngle gōngkuǎn.","vi":"Ông ta đã biển thủ công quỹ."},{"type":"simple","zh":"新规定严禁用公款请客送礼。","pinyin":"Xīn guīdìng yán jìnyòng gōngkuǎn qǐngkè sònglǐ.","vi":"Quy định mới nghiêm cấm dùng tiền công để mời khách, tặng quà."},{"type":"compound","zh":"一旦发现有人贪污公款，公司就会立即报警。","pinyin":"Yídàn fāxiàn yǒurén tānwū gōngkuǎn, gōngsī jiù huì lìjí bàojǐng.","vi":"Một khi phát hiện có người tham ô công quỹ, công ty sẽ lập tức báo cảnh sát."}],"related":[{"hanzi":"公费","pinyin":"gōngfèi","vi":"kinh phí công"},{"hanzi":"挪用","pinyin":"nuóyòng","vi":"biển thủ"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"}]},{"id":"公立","hanzi":"公立","pinyin":"gōnglì","meaning_vi":"công lập","explanation":"公 (công – nhà nước) + 立 (lập – lập ra) → do nhà nước lập ra và quản lý; đối lập với 私立.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🏫","examples":[{"type":"basic","zh":"这是一所公立学校。","pinyin":"Zhè shì yì suǒ gōnglì xuéxiào.","vi":"Đây là một trường công lập."},{"type":"simple","zh":"公立医院的收费一般比私立医院低。","pinyin":"Gōnglì yīyuàn de shōufèi yìbān bǐ sīlì yīyuàn dī.","vi":"Viện phí của bệnh viện công thường thấp hơn bệnh viện tư."},{"type":"compound","zh":"虽然公立大学学费便宜，但是录取分数线很高。","pinyin":"Suīrán gōnglì dàxué xuéfèi piányi, dànshì lùqǔ fēnshùxiàn hěn gāo.","vi":"Tuy học phí đại học công lập rẻ nhưng điểm chuẩn rất cao."}],"related":[{"hanzi":"私立","pinyin":"sīlì","vi":"tư thục"},{"hanzi":"国立","pinyin":"guólì","vi":"quốc lập"},{"hanzi":"公办","pinyin":"gōngbàn","vi":"do nhà nước mở"},{"hanzi":"民办","pinyin":"mínbàn","vi":"dân lập"}]},{"id":"公墓","hanzi":"公墓","pinyin":"gōngmù","meaning_vi":"nghĩa trang công cộng","explanation":"公 (công – chung) + 墓 (mộ – mồ mả) → khu chôn cất chung do nhà nước hay tập thể quản lý.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🪦","examples":[{"type":"basic","zh":"爷爷葬在公墓里。","pinyin":"Yéye zàng zài gōngmù lǐ.","vi":"Ông nội được chôn ở nghĩa trang."},{"type":"simple","zh":"清明节很多人去公墓给亲人扫墓。","pinyin":"Qīngmíngjié hěn duō rén qù gōngmù gěi qīnrén sǎomù.","vi":"Tết Thanh minh nhiều người đến nghĩa trang tảo mộ người thân."},{"type":"compound","zh":"因为城里的公墓越来越贵，所以不少家庭选择了海葬。","pinyin":"Yīnwèi chénglǐ de gōngmù yuèláiyuè guì, suǒyǐ bùshǎo jiātíng xuǎnzéle hǎizàng.","vi":"Vì đất nghĩa trang trong thành phố ngày càng đắt nên không ít gia đình chọn rải tro xuống biển."}],"related":[{"hanzi":"墓地","pinyin":"mùdì","vi":"nghĩa địa"},{"hanzi":"坟墓","pinyin":"fénmù","vi":"mồ mả"},{"hanzi":"陵园","pinyin":"língyuán","vi":"nghĩa trang, lăng viên"},{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"}]},{"id":"公顷","hanzi":"公顷","pinyin":"gōngqǐng","meaning_vi":"héc-ta","explanation":"公 (công – đơn vị hệ mét) + 顷 (khoảnh – đơn vị đo ruộng thời xưa) → đơn vị diện tích bằng 10.000 mét vuông.","hsk_level":"7-9","tags":["luong-tu","so-luong"],"image":"📐","examples":[{"type":"basic","zh":"这片林地有十公顷。","pinyin":"Zhè piàn líndì yǒu shí gōngqǐng.","vi":"Khu rừng này rộng mười héc-ta."},{"type":"simple","zh":"这个农场种了两百多公顷的小麦。","pinyin":"Zhè ge nóngchǎng zhòngle liǎng bǎi duō gōngqǐng de xiǎomài.","vi":"Nông trại này trồng hơn hai trăm héc-ta lúa mì."},{"type":"compound","zh":"虽然新校区占地五十公顷，但是教学楼还没建好。","pinyin":"Suīrán xīn xiàoqū zhàndì wǔshí gōngqǐng, dànshì jiàoxuélóu hái méi jiàn hǎo.","vi":"Tuy khu trường mới rộng năm mươi héc-ta nhưng tòa giảng đường vẫn chưa xây xong."}],"related":[{"hanzi":"亩","pinyin":"mǔ","vi":"mẫu (đơn vị Trung Quốc)"},{"hanzi":"平方米","pinyin":"píngfāngmǐ","vi":"mét vuông"},{"hanzi":"平方公里","pinyin":"píngfānggōnglǐ","vi":"ki-lô-mét vuông"},{"hanzi":"面积","pinyin":"miànjī","vi":"diện tích"}],"traditional":"公頃"},{"id":"公示","hanzi":"公示","pinyin":"gōngshì","meaning_vi":"công bố công khai, niêm yết","explanation":"公 (công – công khai) + 示 (thị – cho thấy) → đưa ra cho công chúng biết để lấy ý kiến hoặc để giám sát.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"名单已经公示了。","pinyin":"Míngdān yǐjīng gōngshì le.","vi":"Danh sách đã được niêm yết công khai."},{"type":"simple","zh":"获奖名单将在学校网站上公示一周。","pinyin":"Huòjiǎng míngdān jiāng zài xuéxiào wǎngzhàn shàng gōngshì yìzhōu.","vi":"Danh sách đoạt giải sẽ được công bố công khai một tuần trên website trường."},{"type":"compound","zh":"如果公示期间没有人提出异议，任命就正式生效。","pinyin":"Rúguǒ gōngshì qījiān méiyǒu rén tíchū yìyì, rènmìng jiù zhèngshì shēngxiào.","vi":"Nếu trong thời gian công bố không ai phản đối thì quyết định bổ nhiệm chính thức có hiệu lực."}],"related":[{"hanzi":"公布","pinyin":"gōngbù","vi":"công bố"},{"hanzi":"公告","pinyin":"gōnggào","vi":"thông cáo"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"展示","pinyin":"zhǎnshì","vi":"trưng bày"}]},{"id":"公事","hanzi":"公事","pinyin":"gōngshì","meaning_vi":"việc công, công việc chung","explanation":"公 (công – chung, cơ quan) + 事 (sự – việc) → việc của cơ quan, công việc chung; đối lập với 私事.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"我来办点公事。","pinyin":"Wǒ lái bàn diǎn gōngshì.","vi":"Tôi đến làm chút việc công."},{"type":"simple","zh":"他出差去上海处理一些公事。","pinyin":"Tā chūchāi qù Shànghǎi chǔlǐ yìxiē gōngshì.","vi":"Anh ấy đi công tác Thượng Hải giải quyết một số việc công."},{"type":"compound","zh":"虽然我们私下是朋友，但是公事还得公办。","pinyin":"Suīrán wǒmen sīxià shì péngyou, dànshì gōngshì hái děi gōngbàn.","vi":"Tuy riêng tư chúng ta là bạn nhưng việc công vẫn phải làm theo phép công."}],"related":[{"hanzi":"私事","pinyin":"sīshì","vi":"việc riêng"},{"hanzi":"公务","pinyin":"gōngwù","vi":"công vụ"},{"hanzi":"公事公办","pinyin":"gōngshìgōngbàn","vi":"việc công làm theo phép công"},{"hanzi":"办公","pinyin":"bàngōng","vi":"làm việc văn phòng"}]},{"id":"公益性","hanzi":"公益性","pinyin":"gōngyìxìng","meaning_vi":"tính công ích, vì lợi ích cộng đồng","explanation":"公益 (công ích – lợi ích chung) + 性 (tính – tính chất) → tính chất phục vụ lợi ích cộng đồng, không nhằm kiếm lời.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"这是公益性活动。","pinyin":"Zhè shì gōngyìxìng huódòng.","vi":"Đây là hoạt động mang tính công ích."},{"type":"simple","zh":"这家博物馆是公益性的，免费开放。","pinyin":"Zhè jiā bówùguǎn shì gōngyìxìng de, miǎnfèikāifàng.","vi":"Bảo tàng này mang tính công ích, mở cửa miễn phí."},{"type":"compound","zh":"虽然这个项目是公益性的，但是也需要资金支持。","pinyin":"Suīrán zhè ge xiàngmù shì gōngyìxìng de, dànshì yě xūyào zījīn zhīchí.","vi":"Tuy dự án này mang tính công ích nhưng cũng cần nguồn vốn hỗ trợ."}],"related":[{"hanzi":"公益","pinyin":"gōngyì","vi":"công ích"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"志愿者","pinyin":"zhìyuànzhě","vi":"tình nguyện viên"},{"hanzi":"非营利","pinyin":"fēiyínglì","vi":"phi lợi nhuận"}]},{"id":"公用","hanzi":"公用","pinyin":"gōngyòng","meaning_vi":"dùng chung, công cộng","explanation":"公 (công – chung) + 用 (dụng – dùng) → dùng chung cho mọi người.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"☎️","examples":[{"type":"basic","zh":"这是公用厨房。","pinyin":"Zhè shì gōngyòng chúfáng.","vi":"Đây là bếp dùng chung."},{"type":"simple","zh":"宿舍每层都有一个公用洗衣机。","pinyin":"Sùshè měi céng dōu yǒu yí ge gōngyòng xǐyījī.","vi":"Mỗi tầng ký túc xá đều có một máy giặt dùng chung."},{"type":"compound","zh":"因为卫生间是公用的，所以大家要保持干净。","pinyin":"Yīnwèi wèishēngjiān shì gōngyòng de, suǒyǐ dàjiā yào bǎochí gānjìng.","vi":"Vì nhà vệ sinh là dùng chung nên mọi người phải giữ sạch sẽ."}],"related":[{"hanzi":"公共","pinyin":"gōnggòng","vi":"công cộng"},{"hanzi":"共用","pinyin":"gòngyòng","vi":"dùng chung"},{"hanzi":"私用","pinyin":"sīyòng","vi":"dùng riêng"},{"hanzi":"公用电话","pinyin":"gōngyòngdiànhuà","vi":"điện thoại công cộng"}]},{"id":"公约","hanzi":"公约","pinyin":"gōngyuē","meaning_vi":"công ước, quy ước chung","explanation":"公 (công – chung) + 约 (ước – giao ước) → điều ước chung mà các bên cùng cam kết tuân thủ.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"各国签署了公约。","pinyin":"Gèguó qiānshǔle gōngyuē.","vi":"Các nước đã ký công ước."},{"type":"simple","zh":"小区制定了一份文明养狗公约。","pinyin":"Xiǎoqū zhìdìngle yí fèn wénmíng yǎng gǒu gōngyuē.","vi":"Khu dân cư đã đặt ra một bản quy ước nuôi chó văn minh."},{"type":"compound","zh":"既然加入了这个公约，就必须遵守其中的规定。","pinyin":"Jìrán jiārùle zhè ge gōngyuē, jiù bìxū zūnshǒu qízhōng de guīdìng.","vi":"Đã gia nhập công ước này thì phải tuân thủ các quy định trong đó."}],"related":[{"hanzi":"条约","pinyin":"tiáoyuē","vi":"điều ước"},{"hanzi":"协议","pinyin":"xiéyì","vi":"hiệp định"},{"hanzi":"签署","pinyin":"qiānshǔ","vi":"ký kết"},{"hanzi":"国际法","pinyin":"guójìfǎ","vi":"luật quốc tế"}],"traditional":"公約"},{"id":"公职","hanzi":"公职","pinyin":"gōngzhí","meaning_vi":"chức vụ nhà nước, công chức","explanation":"公 (công – nhà nước) + 职 (chức – chức vụ) → chức vụ trong cơ quan nhà nước.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🏛️","examples":[{"type":"basic","zh":"他担任公职多年。","pinyin":"Tā dānrèn gōngzhí duōnián.","vi":"Ông ấy giữ chức vụ nhà nước nhiều năm."},{"type":"simple","zh":"她辞去公职，回老家开了一家书店。","pinyin":"Tā cíqù gōngzhí, huílǎojiā kāile yìjiā shūdiàn.","vi":"Cô ấy từ bỏ chức vụ nhà nước, về quê mở một hiệu sách."},{"type":"compound","zh":"如果担任公职，就不能在公司兼职。","pinyin":"Rúguǒ dānrèn gōngzhí, jiù bù néng zài gōngsī jiānzhí.","vi":"Nếu giữ chức vụ nhà nước thì không được làm thêm ở công ty."}],"related":[{"hanzi":"公务员","pinyin":"gōngwùyuán","vi":"công chức"},{"hanzi":"职务","pinyin":"zhíwù","vi":"chức vụ"},{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"}],"traditional":"公職"},{"id":"功","hanzi":"功","pinyin":"gōng","meaning_vi":"công lao, thành tích; công phu","explanation":"功 (công) gồm 工 (công – làm việc) + 力 (lực – sức) → bỏ sức làm việc mà có thành quả, tức công lao.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏅","examples":[{"type":"basic","zh":"他立了大功。","pinyin":"Tā lìle dàgōng.","vi":"Anh ấy đã lập công lớn."},{"type":"simple","zh":"这次比赛能赢，教练功不可没。","pinyin":"Zhè cì bǐsài néng yíng, jiàoliàn gōngbùkěmò.","vi":"Trận đấu này thắng được, công của huấn luyện viên không thể phủ nhận."},{"type":"compound","zh":"虽然他立过功，但是犯了错也要受罚。","pinyin":"Suīrán tā lìguo gōng, dànshì fànle cuò yě yào shòu fá.","vi":"Tuy anh ta từng lập công nhưng phạm lỗi thì vẫn phải chịu phạt."}],"related":[{"hanzi":"功劳","pinyin":"gōngláo","vi":"công lao"},{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"立功","pinyin":"lìgōng","vi":"lập công"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu"}]},{"id":"功底","hanzi":"功底","pinyin":"gōngdǐ","meaning_vi":"nền tảng, vốn căn bản (kỹ năng)","explanation":"功 (công – công phu) + 底 (để – đáy, nền) → nền tảng kỹ năng được rèn luyện vững chắc.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🧱","examples":[{"type":"basic","zh":"他的书法功底很深。","pinyin":"Tā de shūfǎ gōngdǐ hěn shēn.","vi":"Nền tảng thư pháp của anh ấy rất sâu."},{"type":"simple","zh":"这位演员的舞蹈功底非常扎实。","pinyin":"Zhè wèi yǎnyuán de wǔdǎo gōngdǐ fēicháng zhāshi.","vi":"Nền tảng múa của diễn viên này rất vững chắc."},{"type":"compound","zh":"因为数学功底好，所以他学编程很快。","pinyin":"Yīnwèi shùxué gōngdǐ hǎo, suǒyǐ tā xué biānchéng hěn kuài.","vi":"Vì nền tảng toán học tốt nên cậu ấy học lập trình rất nhanh."}],"related":[{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu"},{"hanzi":"扎实","pinyin":"zhāshi","vi":"vững chắc"},{"hanzi":"基本功","pinyin":"jīběngōng","vi":"kỹ năng cơ bản"}]},{"id":"功力","hanzi":"功力","pinyin":"gōnglì","meaning_vi":"công lực, trình độ, tài nghệ","explanation":"功 (công – công phu) + 力 (lực – sức) → sức mạnh, trình độ có được nhờ khổ luyện; cũng chỉ hiệu lực.","hsk_level":"7-9","tags":["danh-tu"],"image":"💪","examples":[{"type":"basic","zh":"这位大师功力深厚。","pinyin":"Zhè wèi dàshī gōnglì shēnhòu.","vi":"Vị đại sư này công lực thâm hậu."},{"type":"simple","zh":"这篇文章显示出作者的文字功力。","pinyin":"Zhè piān wénzhāng xiǎnshìchū zuòzhě de wénzì gōnglì.","vi":"Bài văn này thể hiện tài nghệ viết lách của tác giả."},{"type":"compound","zh":"即使功力再深，也需要每天练习。","pinyin":"Jíshǐ gōnglì zài shēn, yě xūyào měitiān liànxí.","vi":"Dù công lực có sâu đến đâu cũng cần luyện tập mỗi ngày."}],"related":[{"hanzi":"功底","pinyin":"gōngdǐ","vi":"nền tảng"},{"hanzi":"实力","pinyin":"shílì","vi":"thực lực"},{"hanzi":"内力","pinyin":"nèilì","vi":"nội lực"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"trình độ"}]},{"id":"功率","hanzi":"功率","pinyin":"gōnglǜ","meaning_vi":"công suất","explanation":"功 (công – công cơ học) + 率 (suất – tỉ lệ) → lượng công thực hiện trong một đơn vị thời gian.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚡","examples":[{"type":"basic","zh":"这台电机功率很大。","pinyin":"Zhè tái diànjī gōnglǜ hěn dà.","vi":"Động cơ điện này công suất rất lớn."},{"type":"simple","zh":"这款吹风机的功率是两千瓦。","pinyin":"Zhè kuǎn chuīfēngjī de gōnglǜ shì liǎng qiānwǎ.","vi":"Công suất của máy sấy tóc này là hai nghìn oát."},{"type":"compound","zh":"如果电器功率太高，就容易让电路跳闸。","pinyin":"Rúguǒ diànqì gōnglǜ tài gāo, jiù róngyì ràng diànlù tiàozhá.","vi":"Nếu thiết bị điện có công suất quá cao thì dễ làm mạch điện bị nhảy cầu dao."}],"related":[{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"},{"hanzi":"瓦特","pinyin":"wǎtè","vi":"oát"},{"hanzi":"电压","pinyin":"diànyā","vi":"điện áp"},{"hanzi":"能耗","pinyin":"nénghào","vi":"mức tiêu hao năng lượng"}]},{"id":"攻","hanzi":"攻","pinyin":"gōng","meaning_vi":"tấn công, công kích; chuyên tâm nghiên cứu","explanation":"攻 (công) gồm 工 + 攵 (bộ phộc – đánh) → đánh vào, tấn công; mở rộng là dốc sức nghiên cứu (như 攻读).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"敌人开始攻城了。","pinyin":"Dírén kāishǐ gōngchéng le.","vi":"Quân địch bắt đầu công thành rồi."},{"type":"simple","zh":"他这几年一直专攻人工智能。","pinyin":"Tā zhè jǐ nián yìzhí zhuāngōng réngōngzhìnéng.","vi":"Mấy năm nay anh ấy chuyên tâm nghiên cứu trí tuệ nhân tạo."},{"type":"compound","zh":"一旦对方防线出现漏洞，我们就集中力量猛攻。","pinyin":"Yídàn duìfāng fángxiàn chūxiàn lòudòng, wǒmen jiù jízhōng lìliàng měnggōng.","vi":"Một khi hàng phòng ngự đối phương lộ sơ hở, chúng ta sẽ dồn sức tấn công mạnh."}],"related":[{"hanzi":"进攻","pinyin":"jìngōng","vi":"tiến công"},{"hanzi":"攻击","pinyin":"gōngjī","vi":"công kích"},{"hanzi":"防守","pinyin":"fángshǒu","vi":"phòng thủ"},{"hanzi":"攻读","pinyin":"gōngdú","vi":"theo học"}]},{"id":"供","hanzi":"供","pinyin":"gōng","meaning_vi":"cung cấp, cung ứng; chu cấp, nuôi (ăn học)","explanation":"亻 (nhân – người) + 共 (cộng – cùng) → đưa ra cho người khác dùng, tức cung cấp; đọc gòng thì nghĩa là cúng, khai cung.","hsk_level":"7-9","tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"这里供水不足。","pinyin":"Zhèlǐ gōngshuǐ bùzú.","vi":"Ở đây cấp nước không đủ."},{"type":"simple","zh":"父母辛苦打工供他上大学。","pinyin":"Fùmǔ xīnkǔ dǎgōng gōng tā shàng dàxué.","vi":"Bố mẹ vất vả làm thuê để nuôi anh ấy học đại học."},{"type":"compound","zh":"由于商品供不应求，所以价格一直在上涨。","pinyin":"Yóuyú shāngpǐn gōngbúyìngqiú, suǒyǐ jiàgé yìzhí zài shàngzhǎng.","vi":"Do hàng hóa cung không đủ cầu nên giá cứ tăng mãi."}],"related":[{"hanzi":"提供","pinyin":"tígōng","vi":"cung cấp"},{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"供给","pinyin":"gōngjǐ","vi":"cung cấp"},{"hanzi":"需求","pinyin":"xūqiú","vi":"nhu cầu"}]},{"id":"拱","hanzi":"拱","pinyin":"gǒng","meaning_vi":"chắp tay; uốn vòm, vồng lên; ủi (bằng mõm), chui rúc","explanation":"扌 (thủ – tay) + 共 (cộng – cùng) → chắp hai tay vào nhau; mở rộng là uốn cong như vòm, dùng mõm hoặc thân ủi đẩy.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌉","examples":[{"type":"basic","zh":"小猪用嘴拱土。","pinyin":"Xiǎo zhū yòng zuǐ gǒng tǔ.","vi":"Chú lợn con dùng mõm ủi đất."},{"type":"simple","zh":"大年初一，他向长辈们拱手拜年。","pinyin":"Dà nián chūyī, tā xiàng zhǎngbèimen gǒngshǒu bàinián.","vi":"Mùng một Tết, anh ấy chắp tay chúc Tết các bậc bề trên."},{"type":"compound","zh":"因为猫觉得冷，所以一直往被窝里拱。","pinyin":"Yīnwèi māo juéde lěng, suǒyǐ yìzhí wǎng bèi wō lǐ gǒng.","vi":"Vì con mèo thấy lạnh nên cứ chui rúc vào trong chăn."}],"related":[{"hanzi":"拱手","pinyin":"gǒngshǒu","vi":"chắp tay"},{"hanzi":"拱门","pinyin":"gǒngmén","vi":"cổng vòm"},{"hanzi":"拱桥","pinyin":"gǒngqiáo","vi":"cầu vòm"},{"hanzi":"弯曲","pinyin":"wānqū","vi":"uốn cong"}]},{"id":"共同体","hanzi":"共同体","pinyin":"gòngtóngtǐ","meaning_vi":"cộng đồng, khối cộng đồng","explanation":"共同 (cộng đồng – cùng chung) + 体 (thể – khối) → khối gồm các thành viên có chung lợi ích, mục tiêu.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"人类是命运共同体。","pinyin":"Rénlèi shì mìngyùn gòngtóngtǐ.","vi":"Nhân loại là cộng đồng chung vận mệnh."},{"type":"simple","zh":"欧洲经济共同体成立于一九五七年。","pinyin":"Ōuzhōu jīngjì gòngtóngtǐ chénglì yú yī jiǔ wǔqī nián.","vi":"Cộng đồng Kinh tế châu Âu được thành lập năm 1957."},{"type":"compound","zh":"既然我们是一个共同体，就应该互相帮助。","pinyin":"Jìrán wǒmen shì yí ge gòngtóngtǐ, jiù yīnggāi hùxiāng bāngzhù.","vi":"Đã là một cộng đồng thì chúng ta nên giúp đỡ lẫn nhau."}],"related":[{"hanzi":"共同","pinyin":"gòngtóng","vi":"chung"},{"hanzi":"社区","pinyin":"shèqū","vi":"cộng đồng dân cư"},{"hanzi":"集体","pinyin":"jítǐ","vi":"tập thể"},{"hanzi":"联盟","pinyin":"liánméng","vi":"liên minh"}],"traditional":"共同體"},{"id":"勾","hanzi":"勾","pinyin":"gōu","meaning_vi":"đánh dấu, gạch; móc; câu kết; gợi lên","explanation":"勾 (câu) có hình cái móc → vạch dấu móc, móc vào; còn nghĩa câu kết (勾结), gợi lên (勾起).","hsk_level":"7-9","tags":["dong-tu"],"image":"✔️","examples":[{"type":"basic","zh":"请勾出错别字。","pinyin":"Qǐng gōuchū cuòbiézì.","vi":"Hãy đánh dấu những chữ viết sai."},{"type":"simple","zh":"这张老照片勾起了我童年的回忆。","pinyin":"Zhè zhāng lǎo zhàopiàn gōuqǐle wǒ tóngnián de huíyì.","vi":"Tấm ảnh cũ này gợi lại ký ức tuổi thơ của tôi."},{"type":"compound","zh":"如果这道题你不会做，就先用铅笔勾一下。","pinyin":"Rúguǒ zhè dào tí nǐ bú huì zuò, jiù xiān yòng qiānbǐ gōu yíxià.","vi":"Nếu câu này em không làm được thì cứ đánh dấu bằng bút chì trước."}],"related":[{"hanzi":"勾结","pinyin":"gōujié","vi":"câu kết"},{"hanzi":"勾起","pinyin":"gōuqǐ","vi":"gợi lên"},{"hanzi":"钩","pinyin":"gōu","vi":"cái móc"},{"hanzi":"勾画","pinyin":"gōuhuà","vi":"phác họa"}]},{"id":"钩","hanzi":"钩","pinyin":"gōu","meaning_vi":"cái móc, lưỡi câu; móc vào","explanation":"钅 (kim – kim loại) + 勾 (câu – móc) → vật bằng kim loại cong như cái móc; cũng dùng như động từ móc, mắc.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪝","examples":[{"type":"basic","zh":"鱼咬钩了！","pinyin":"Yú yǎogōu le!","vi":"Cá cắn câu rồi!"},{"type":"simple","zh":"她把外套挂在门后的钩子上。","pinyin":"Tā bǎ wàitào guà zài mén hòu de gōuzi shang.","vi":"Cô ấy treo áo khoác lên cái móc sau cửa."},{"type":"compound","zh":"虽然毛衣被钉子钩破了，但是还能补好。","pinyin":"Suīrán máoyī bèi dīngzi gōupò le, dànshì hái néng bǔ hǎo.","vi":"Tuy áo len bị đinh móc rách nhưng vẫn vá lại được."}],"related":[{"hanzi":"钩子","pinyin":"gōuzi","vi":"cái móc"},{"hanzi":"鱼钩","pinyin":"yúgōu","vi":"lưỡi câu"},{"hanzi":"挂钩","pinyin":"guàgōu","vi":"móc treo, gắn liền"},{"hanzi":"勾","pinyin":"gōu","vi":"đánh dấu, móc"}],"traditional":"鉤"},{"id":"购","hanzi":"购","pinyin":"gòu","meaning_vi":"mua, thu mua","explanation":"贝 (bối – tiền) + 勾 (câu) → dùng tiền để đổi lấy hàng, tức mua; thường dùng trong từ ghép, văn viết.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"本店限购两件。","pinyin":"Běn diàn xiàngòu liǎng jiàn.","vi":"Cửa hàng giới hạn mua hai món."},{"type":"simple","zh":"公司计划下个月购入一批新电脑。","pinyin":"Gōngsī jìhuà xiàgeyuè gòu rù yìpī xīn diànnǎo.","vi":"Công ty dự định tháng sau mua vào một lô máy tính mới."},{"type":"compound","zh":"如果在网上团购，就能便宜不少。","pinyin":"Rúguǒ zài wǎngshang tuángòu, jiù néng piányi bùshǎo.","vi":"Nếu mua theo nhóm trên mạng thì sẽ rẻ hơn khá nhiều."}],"related":[{"hanzi":"购买","pinyin":"gòumǎi","vi":"mua"},{"hanzi":"购物","pinyin":"gòuwù","vi":"mua sắm"},{"hanzi":"采购","pinyin":"cǎigòu","vi":"thu mua"},{"hanzi":"收购","pinyin":"shōugòu","vi":"thu mua, mua lại"}],"traditional":"購"},{"id":"够呛","hanzi":"够呛","pinyin":"gòuqiàng","meaning_vi":"quá sức, khó chịu nổi, gay go; e là khó","explanation":"够 (cấu – đủ) + 呛 (sặc – ngạt) → đến mức ngộp thở, tức gay go, khó chịu quá mức; khẩu ngữ, cũng dùng nghĩa \"e là khó mà được\".","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😫","examples":[{"type":"basic","zh":"今天热得够呛。","pinyin":"Jīntiān rè de gòuqiàng.","vi":"Hôm nay nóng kinh khủng."},{"type":"simple","zh":"搬了一天家，大家都累得够呛。","pinyin":"Bānle yì tiān jiā, dàjiā dōu lèi de gòuqiàng.","vi":"Chuyển nhà cả ngày, ai nấy đều mệt rã rời."},{"type":"compound","zh":"虽然他答应了，但是我看这件事够呛能办成。","pinyin":"Suīrán tā dāying le, dànshì wǒ kàn zhè jiàn shì gòuqiàng néng bàn chéng.","vi":"Tuy anh ta đã nhận lời nhưng tôi thấy việc này e là khó thành."}],"related":[{"hanzi":"受不了","pinyin":"shòubuliǎo","vi":"không chịu nổi"},{"hanzi":"要命","pinyin":"yàomìng","vi":"chết mất"},{"hanzi":"难受","pinyin":"nánshòu","vi":"khó chịu"},{"hanzi":"悬","pinyin":"xuán","vi":"khó chắc"}],"traditional":"夠嗆"},{"id":"估算","hanzi":"估算","pinyin":"gūsuàn","meaning_vi":"ước tính, ước lượng","explanation":"估 (cổ – đoán định) + 算 (toán – tính) → tính toán ước chừng, không cần chính xác tuyệt đối.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"🧮","examples":[{"type":"basic","zh":"请估算一下成本。","pinyin":"Qǐng gūsuàn yíxià chéngběn.","vi":"Hãy ước tính chi phí một chút."},{"type":"simple","zh":"专家估算这次台风造成了上亿元损失。","pinyin":"Zhuānjiā gūsuàn zhè cì táifēng zào chéngle shàng yì yuán sǔnshī.","vi":"Chuyên gia ước tính cơn bão lần này gây thiệt hại hơn trăm triệu tệ."},{"type":"compound","zh":"虽然只是粗略估算，但是数字已经很接近了。","pinyin":"Suīrán zhǐshì cūlüè gūsuàn, dànshì shùzì yǐjīng hěn jiējìn le.","vi":"Tuy chỉ là ước tính sơ bộ nhưng con số đã rất sát rồi."}],"related":[{"hanzi":"估计","pinyin":"gūjì","vi":"ước đoán"},{"hanzi":"计算","pinyin":"jìsuàn","vi":"tính toán"},{"hanzi":"预算","pinyin":"yùsuàn","vi":"dự toán"},{"hanzi":"估价","pinyin":"gūjià","vi":"định giá"}]},{"id":"孤零零","hanzi":"孤零零","pinyin":"gūlínglíng","meaning_vi":"trơ trọi, lẻ loi, cô độc","explanation":"孤 (cô – lẻ loi) + 零零 (linh – lác đác, rời rạc) → lẻ loi một mình, không nơi nương tựa.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🏝️","examples":[{"type":"basic","zh":"他孤零零地坐着。","pinyin":"Tā gūlínglíng de zuò zhe.","vi":"Anh ấy ngồi lẻ loi một mình."},{"type":"simple","zh":"山顶上孤零零地立着一棵老松树。","pinyin":"Shāndǐng shang gūlínglíng de lìzhe yì kē lǎo sōngshù.","vi":"Trên đỉnh núi trơ trọi một cây thông già."},{"type":"compound","zh":"自从老伴去世以后，奶奶就孤零零一个人生活。","pinyin":"Zìcóng lǎobàn qùshì yǐhòu, nǎinai jiù gūlínglíng yīgerén shēnghuó.","vi":"Từ khi ông mất, bà sống lẻ loi một mình."}],"related":[{"hanzi":"孤单","pinyin":"gūdān","vi":"cô đơn"},{"hanzi":"孤独","pinyin":"gūdú","vi":"cô độc"},{"hanzi":"孤立","pinyin":"gūlì","vi":"cô lập"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"hiu quạnh"}]},{"id":"沽名钓誉","hanzi":"沽名钓誉","pinyin":"gūmíng-diàoyù","meaning_vi":"mua danh chuộc tiếng, câu danh tiếng","explanation":"Nghĩa đen: 沽 (cô – mua) danh, 钓 (điếu – câu) dự → mua lấy tiếng, câu lấy danh; chỉ kẻ dùng thủ đoạn để kiếm hư danh.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎣","examples":[{"type":"basic","zh":"他只是沽名钓誉。","pinyin":"Tā zhǐshì gūmíngdiàoyù.","vi":"Ông ta chỉ là mua danh chuộc tiếng."},{"type":"simple","zh":"有人批评他捐款是为了沽名钓誉。","pinyin":"Yǒurén pīpíng tā juānkuǎn shì wèile gūmíngdiàoyù.","vi":"Có người phê phán ông ấy quyên góp là để câu danh tiếng."},{"type":"compound","zh":"如果做好事只为沽名钓誉，那就失去了意义。","pinyin":"Rúguǒ zuò hǎoshì zhǐ wèi gūmíngdiàoyù, nà jiù shīqùle yìyì.","vi":"Nếu làm việc tốt chỉ để mua danh thì việc đó đã mất ý nghĩa."}],"related":[{"hanzi":"名誉","pinyin":"míngyù","vi":"danh dự"},{"hanzi":"虚名","pinyin":"xūmíng","vi":"hư danh"},{"hanzi":"欺世盗名","pinyin":"qīshìdàomíng","vi":"lừa đời lấy tiếng"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"}],"traditional":"沽名釣譽"},{"id":"古今中外","hanzi":"古今中外","pinyin":"gǔjīn-zhōngwài","meaning_vi":"xưa nay trong ngoài nước, mọi thời mọi nơi","explanation":"古今 (cổ kim – xưa nay) + 中外 (trung ngoại – trong và ngoài nước) → khắp mọi thời đại và mọi nơi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌏","examples":[{"type":"basic","zh":"古今中外都一样。","pinyin":"Gǔjīnzhōngwài dōu yíyàng.","vi":"Xưa nay trong ngoài nước đều như nhau."},{"type":"simple","zh":"他读过许多古今中外的名著。","pinyin":"Tā dúguo xǔduō gǔjīnzhōngwài de míngzhù.","vi":"Anh ấy đã đọc nhiều tác phẩm nổi tiếng xưa nay trong và ngoài nước."},{"type":"compound","zh":"无论古今中外，诚信都是做人的根本。","pinyin":"Wúlùn gǔjīnzhōngwài, chéng Xìndōu shì zuòrén de gēnběn.","vi":"Dù xưa hay nay, trong hay ngoài nước, chữ tín luôn là gốc rễ làm người."}],"related":[{"hanzi":"古今","pinyin":"gǔjīn","vi":"xưa nay"},{"hanzi":"中外","pinyin":"zhōngwài","vi":"trong và ngoài nước"},{"hanzi":"自古以来","pinyin":"zìgǔyǐlái","vi":"từ xưa đến nay"},{"hanzi":"世界各地","pinyin":"shìjiègèdì","vi":"khắp thế giới"}]},{"id":"故","hanzi":"故","pinyin":"gù","meaning_vi":"cho nên, vì vậy; cố ý; cũ; nguyên do, sự cố","explanation":"故 (cố) vốn nghĩa là nguyên do, chuyện cũ → trong văn viết dùng làm liên từ \"vì vậy\"; còn nghĩa cũ (故乡), cố ý (故意), sự cố (事故).","hsk_level":"7-9","tags":["lien-tu"],"image":"📜","examples":[{"type":"basic","zh":"因病故未出席。","pinyin":"Yīn bìnggù wèi chūxí.","vi":"Vì ốm nên không có mặt."},{"type":"simple","zh":"他明知故犯，必须受到处罚。","pinyin":"Tā míngzhīgùfàn, bìxū shòudào chǔfá.","vi":"Anh ta biết rõ mà vẫn cố phạm, phải chịu xử phạt."},{"type":"compound","zh":"因为本店装修，故暂停营业三天。","pinyin":"Yīnwèi běn diàn zhuāngxiū, gù zàntíng yíngyè sān tiān.","vi":"Vì cửa hàng sửa chữa nên tạm ngừng kinh doanh ba ngày."}],"related":[{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"故乡","pinyin":"gùxiāng","vi":"cố hương"},{"hanzi":"事故","pinyin":"shìgù","vi":"sự cố"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"cho nên"}]},{"id":"顾不得","hanzi":"顾不得","pinyin":"gùbude","meaning_vi":"không màng tới, không lo được","explanation":"顾 (cố – đoái hoài) + 不得 (bất đắc – không thể) → không thể đoái hoài tới vì có việc gấp hơn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"他顾不得休息。","pinyin":"Tā gùbude xiūxi.","vi":"Anh ấy chẳng màng nghỉ ngơi."},{"type":"simple","zh":"听到孩子哭，妈妈顾不得穿鞋就跑了出去。","pinyin":"Tīngdào háizi kū, māma gùbude chuān xié jiù pǎole chūqu.","vi":"Nghe con khóc, mẹ chẳng kịp xỏ giày đã chạy ra ngoài."},{"type":"compound","zh":"因为火车快开了，所以他顾不得吃饭就跑向车站。","pinyin":"Yīnwèi huǒchē kuài kāi le, suǒyǐ tā gùbude chīfàn jiù pǎo xiàng chēzhàn.","vi":"Vì tàu sắp chạy nên anh ấy chẳng màng ăn cơm mà chạy ngay ra ga."}],"related":[{"hanzi":"顾不上","pinyin":"gùbushàng","vi":"không lo được"},{"hanzi":"顾及","pinyin":"gùjí","vi":"đoái hoài"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"不顾","pinyin":"búgù","vi":"bất chấp"}],"traditional":"顧不得"},{"id":"顾不上","hanzi":"顾不上","pinyin":"gùbushàng","meaning_vi":"không lo nổi, không kịp quan tâm","explanation":"顾 (cố – trông nom) + 不上 (không với tới) → không đủ thời gian, sức lực để lo tới việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏳","examples":[{"type":"basic","zh":"忙得顾不上吃饭。","pinyin":"Máng de gùbushàng chīfàn.","vi":"Bận đến mức không kịp ăn cơm."},{"type":"simple","zh":"他整天加班，连孩子都顾不上管。","pinyin":"Tā zhěngtiān jiābān, lián háizi dōu gùbushàng guǎn.","vi":"Anh ấy tăng ca suốt ngày, đến con cái cũng không lo được."},{"type":"compound","zh":"一旦项目开始，他就顾不上家里的事了。","pinyin":"Yídàn xiàngmù kāishǐ, tā jiù gùbushàng jiālǐ de shì le.","vi":"Một khi dự án bắt đầu, anh ấy sẽ không lo nổi việc nhà nữa."}],"related":[{"hanzi":"顾不得","pinyin":"gùbude","vi":"không màng"},{"hanzi":"顾得上","pinyin":"gùdeshàng","vi":"lo được"},{"hanzi":"兼顾","pinyin":"jiāngù","vi":"lo cả hai"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"}],"traditional":"顧不上"},{"id":"雇","hanzi":"雇","pinyin":"gù","meaning_vi":"thuê, mướn (người)","explanation":"雇 (cố) → bỏ tiền thuê người làm việc cho mình.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🧑‍🔧","examples":[{"type":"basic","zh":"他雇了一个司机。","pinyin":"Tā gùle yí ge sījī.","vi":"Ông ấy đã thuê một tài xế."},{"type":"simple","zh":"农忙时，他们会雇几个人帮忙收稻子。","pinyin":"Nóngmáng shí, tāmen huì gù jǐ ge rén bāngmáng shōu dàozi.","vi":"Mùa vụ bận rộn, họ sẽ thuê vài người giúp gặt lúa."},{"type":"compound","zh":"如果自己忙不过来，就雇个保姆吧。","pinyin":"Rúguǒ zìjǐ máng buguò lái, jiù gù ge bǎomǔ ba.","vi":"Nếu mình lo không xuể thì thuê một người giúp việc đi."}],"related":[{"hanzi":"雇佣","pinyin":"gùyōng","vi":"thuê mướn"},{"hanzi":"雇主","pinyin":"gùzhǔ","vi":"chủ thuê"},{"hanzi":"雇员","pinyin":"gùyuán","vi":"người làm thuê"},{"hanzi":"聘请","pinyin":"pìnqǐng","vi":"mời làm"}],"traditional":"僱"},{"id":"雇员","hanzi":"雇员","pinyin":"gùyuán","meaning_vi":"nhân viên làm thuê, người lao động","explanation":"雇 (cố – thuê) + 员 (viên – người) → người được thuê làm việc.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👷","examples":[{"type":"basic","zh":"公司有五百名雇员。","pinyin":"Gōngsī yǒu wǔ bǎi míng gùyuán.","vi":"Công ty có năm trăm nhân viên."},{"type":"simple","zh":"新法律保护了临时雇员的权益。","pinyin":"Xīn fǎlǜ bǎohùle línshí gùyuán de quányì.","vi":"Luật mới bảo vệ quyền lợi của lao động thời vụ."},{"type":"compound","zh":"虽然他只是普通雇员，但是工作非常认真。","pinyin":"Suīrán tā zhǐshì pǔtōng gùyuán, dànshì gōngzuò fēicháng rènzhēn.","vi":"Tuy anh ấy chỉ là nhân viên bình thường nhưng làm việc rất nghiêm túc."}],"related":[{"hanzi":"雇主","pinyin":"gùzhǔ","vi":"chủ thuê"},{"hanzi":"员工","pinyin":"yuángōng","vi":"nhân viên"},{"hanzi":"职员","pinyin":"zhíyuán","vi":"viên chức"},{"hanzi":"雇佣","pinyin":"gùyōng","vi":"thuê mướn"}],"traditional":"雇員"},{"id":"雇主","hanzi":"雇主","pinyin":"gùzhǔ","meaning_vi":"chủ thuê, người sử dụng lao động","explanation":"雇 (cố – thuê) + 主 (chủ – người chủ) → người đứng ra thuê lao động.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"雇主要付工资。","pinyin":"Gùzhǔ yào fù gōngzī.","vi":"Chủ thuê phải trả lương."},{"type":"simple","zh":"雇主必须为员工缴纳社会保险。","pinyin":"Gùzhǔ bìxū wèi yuángōng jiǎonà shèhuì bǎoxiǎn.","vi":"Người sử dụng lao động phải đóng bảo hiểm xã hội cho nhân viên."},{"type":"compound","zh":"如果雇主拖欠工资，工人就可以去劳动部门投诉。","pinyin":"Rúguǒ gùzhǔ tuōqiàn gōngzī, gōngrén jiù kěyǐ qù láodòng bùmén tóusù.","vi":"Nếu chủ thuê nợ lương thì công nhân có thể khiếu nại lên cơ quan lao động."}],"related":[{"hanzi":"雇员","pinyin":"gùyuán","vi":"người làm thuê"},{"hanzi":"老板","pinyin":"lǎobǎn","vi":"ông chủ"},{"hanzi":"用人单位","pinyin":"yòngréndānwèi","vi":"đơn vị tuyển dụng"},{"hanzi":"劳动合同","pinyin":"láodònghétong","vi":"hợp đồng lao động"}],"traditional":"僱主"},{"id":"怪物","hanzi":"怪物","pinyin":"guàiwu","meaning_vi":"quái vật; người quái dị","explanation":"怪 (quái – kỳ lạ) + 物 (vật) → sinh vật kỳ dị đáng sợ; cũng chỉ người tính tình lập dị.","hsk_level":"7-9","tags":["danh-tu"],"image":"👹","examples":[{"type":"basic","zh":"孩子怕怪物。","pinyin":"Háizi pà guàiwu.","vi":"Trẻ con sợ quái vật."},{"type":"simple","zh":"电影里的怪物从海里爬了出来。","pinyin":"Diànyǐng lǐ de guàiwu cóng hǎilǐ pále chūlai.","vi":"Con quái vật trong phim bò lên từ dưới biển."},{"type":"compound","zh":"虽然故事里的怪物很可怕，但是孩子们还是想听。","pinyin":"Suīrán gùshi lǐ de guàiwu hěn kěpà, dànshì háizimen háishi xiǎng tīng.","vi":"Tuy con quái vật trong truyện rất đáng sợ nhưng bọn trẻ vẫn muốn nghe."}],"related":[{"hanzi":"妖怪","pinyin":"yāoguài","vi":"yêu quái"},{"hanzi":"魔鬼","pinyin":"móguǐ","vi":"ma quỷ"},{"hanzi":"怪人","pinyin":"guàirén","vi":"người kỳ quặc"},{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"}]},{"id":"怪异","hanzi":"怪异","pinyin":"guàiyì","meaning_vi":"quái dị, kỳ quái","explanation":"怪 (quái – lạ) + 异 (dị – khác thường) → kỳ lạ, khác thường đến mức khó hiểu.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👽","examples":[{"type":"basic","zh":"他打扮得很怪异。","pinyin":"Tā dǎban de hěn guàiyì.","vi":"Anh ta ăn mặc rất quái dị."},{"type":"simple","zh":"半夜里，楼上传来一阵怪异的声音。","pinyin":"Bàn yèlǐ, lóushàng chuánlái yízhèn guàiyì de shēngyīn.","vi":"Nửa đêm, trên lầu vọng xuống một tràng âm thanh kỳ quái."},{"type":"compound","zh":"虽然这幅画看起来很怪异，但是很有创意。","pinyin":"Suīrán zhè fú huà kànqǐlai hěn guàiyì, dànshì hěn yǒu chuàngyì.","vi":"Tuy bức tranh này trông rất quái dị nhưng rất sáng tạo."}],"related":[{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"},{"hanzi":"古怪","pinyin":"gǔguài","vi":"cổ quái"},{"hanzi":"诡异","pinyin":"guǐyì","vi":"quỷ dị"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"bình thường"}],"traditional":"怪異"},{"id":"关掉","hanzi":"关掉","pinyin":"guāndiào","meaning_vi":"tắt, tắt đi","explanation":"关 (quan – đóng) + 掉 (điệu – mất đi) → đóng hoặc tắt hẳn đi.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"📴","examples":[{"type":"basic","zh":"请关掉手机。","pinyin":"Qǐng guāndiào shǒujī.","vi":"Vui lòng tắt điện thoại."},{"type":"simple","zh":"出门前别忘了关掉煤气。","pinyin":"Chū ménqián bié wàngle guāndiào méiqì.","vi":"Trước khi ra ngoài đừng quên tắt ga."},{"type":"compound","zh":"如果你要睡觉，就把电视关掉吧。","pinyin":"Rúguǒ nǐ yào shuìjiào, jiù bǎ diànshì guāndiào ba.","vi":"Nếu con muốn ngủ thì tắt tivi đi."}],"related":[{"hanzi":"关上","pinyin":"guānshang","vi":"đóng lại"},{"hanzi":"打开","pinyin":"dǎkāi","vi":"mở"},{"hanzi":"关闭","pinyin":"guānbì","vi":"đóng"},{"hanzi":"开关","pinyin":"kāiguān","vi":"công tắc"}],"traditional":"關掉"},{"id":"关节","hanzi":"关节","pinyin":"guānjié","meaning_vi":"khớp xương; khâu then chốt","explanation":"关 (quan – cửa ải) + 节 (tiết – đốt) → chỗ nối giữa các đốt xương; nghĩa bóng là khâu mấu chốt.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🦴","examples":[{"type":"basic","zh":"我膝盖关节疼。","pinyin":"Wǒ xīgài guānjié téng.","vi":"Khớp gối của tôi bị đau."},{"type":"simple","zh":"运动前要先活动一下关节。","pinyin":"Yùndòng qián yào xiān huódòng yíxià guānjié.","vi":"Trước khi tập thể thao phải khởi động các khớp."},{"type":"compound","zh":"一旦关节受了伤，就要好好休息。","pinyin":"Yídàn guānjié shòule shāng, jiùyào hǎohǎo xiūxi.","vi":"Một khi khớp bị thương thì phải nghỉ ngơi cho tốt."}],"related":[{"hanzi":"膝盖","pinyin":"xīgài","vi":"đầu gối"},{"hanzi":"关节炎","pinyin":"guānjiéyán","vi":"viêm khớp"},{"hanzi":"骨头","pinyin":"gǔtou","vi":"xương"},{"hanzi":"环节","pinyin":"huánjié","vi":"khâu"}],"traditional":"關節"},{"id":"观测","hanzi":"观测","pinyin":"guāncè","meaning_vi":"quan trắc, quan sát đo đạc","explanation":"观 (quan – xem) + 测 (trắc – đo) → quan sát và đo đạc một cách khoa học.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔭","examples":[{"type":"basic","zh":"他们在观测星空。","pinyin":"Tāmen zài guāncè xīngkōng.","vi":"Họ đang quan sát bầu trời sao."},{"type":"simple","zh":"气象站每天定时观测风速和气温。","pinyin":"Qìxiàngzhàn měitiān dìngshí guāncè fēngsù héqì wēn.","vi":"Trạm khí tượng quan trắc tốc độ gió và nhiệt độ theo giờ cố định mỗi ngày."},{"type":"compound","zh":"因为今晚天气晴朗，所以很适合观测月食。","pinyin":"Yīnwèi jīnwǎn tiānqì qínglǎng, suǒyǐ hěn shìhé guāncè yuèshí.","vi":"Vì tối nay trời quang nên rất thích hợp để quan sát nguyệt thực."}],"related":[{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"测量","pinyin":"cèliáng","vi":"đo lường"},{"hanzi":"天文台","pinyin":"tiānwéntái","vi":"đài thiên văn"},{"hanzi":"监测","pinyin":"jiāncè","vi":"giám sát"}],"traditional":"觀測"},{"id":"观摩","hanzi":"观摩","pinyin":"guānmó","meaning_vi":"tham quan học hỏi, dự giờ","explanation":"观 (quan – xem) + 摩 (ma – nghiền ngẫm, học theo) → xem người khác làm để học hỏi.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"👀","examples":[{"type":"basic","zh":"老师们去观摩公开课。","pinyin":"Lǎoshīmen qù guānmó gōngkāikè.","vi":"Các thầy cô đi dự giờ tiết học mẫu."},{"type":"simple","zh":"新员工被安排到车间观摩老师傅操作。","pinyin":"Xīn yuángōng bèi ānpái dào chējiān guānmó lǎo shīfu cāozuò.","vi":"Nhân viên mới được xếp xuống phân xưởng xem thợ cả thao tác để học hỏi."},{"type":"compound","zh":"虽然只是观摩学习，但是大家都认真做了笔记。","pinyin":"Suīrán zhǐshì guānmó xuéxí, dànshì dàjiā dōu rènzhēn zuòle bǐjì.","vi":"Tuy chỉ là tham quan học hỏi nhưng mọi người đều ghi chép cẩn thận."}],"related":[{"hanzi":"观看","pinyin":"guānkàn","vi":"xem"},{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"参观","pinyin":"cānguān","vi":"tham quan"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"}],"traditional":"觀摩"},{"id":"官吏","hanzi":"官吏","pinyin":"guānlì","meaning_vi":"quan lại","explanation":"官 (quan) + 吏 (lại – viên chức nhỏ) → quan lại, người làm việc cho triều đình (thường nói về thời xưa).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏯","examples":[{"type":"basic","zh":"古代官吏要考科举。","pinyin":"Gǔdài guānlì yào kǎo kējǔ.","vi":"Quan lại thời xưa phải thi khoa cử."},{"type":"simple","zh":"这位官吏因为清廉受到百姓爱戴。","pinyin":"Zhè wèi guānlì yīnwèi qīnglián shòudào bǎixìng àidài.","vi":"Vị quan này được dân chúng yêu mến vì thanh liêm."},{"type":"compound","zh":"如果官吏贪污受贿，就会受到严厉惩罚。","pinyin":"Rúguǒ guānlì tānwū shòuhuì, jiù huì shòudào yánlì chéngfá.","vi":"Nếu quan lại tham ô nhận hối lộ thì sẽ bị trừng phạt nghiêm khắc."}],"related":[{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"官僚","pinyin":"guānliáo","vi":"quan liêu"},{"hanzi":"百姓","pinyin":"bǎixìng","vi":"dân chúng"},{"hanzi":"贪官","pinyin":"tānguān","vi":"tham quan"}]},{"id":"官僚主义","hanzi":"官僚主义","pinyin":"guānliáozhǔyì","meaning_vi":"chủ nghĩa quan liêu, bệnh quan liêu","explanation":"官僚 (quan liêu – giới quan chức) + 主义 (chủ nghĩa) → lối làm việc xa rời thực tế, thủ tục rườm rà, hách dịch.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📑","examples":[{"type":"basic","zh":"我们要反对官僚主义。","pinyin":"Wǒmen yào fǎnduì guānliáozhǔyì.","vi":"Chúng ta phải chống bệnh quan liêu."},{"type":"simple","zh":"办个证要跑十几趟，这就是官僚主义。","pinyin":"Bàn ge zhèng yào pǎo shíjǐ tàng, zhè jiùshì guānliáozhǔyì.","vi":"Làm một cái giấy phải chạy hơn chục lượt, đó chính là bệnh quan liêu."},{"type":"compound","zh":"如果官僚主义不改，老百姓就会越来越不满。","pinyin":"Rúguǒ guānliáozhǔyì bù gǎi, lǎobǎixìng jiù huì yuèláiyuè bùmǎn.","vi":"Nếu bệnh quan liêu không sửa thì dân chúng sẽ ngày càng bất mãn."}],"related":[{"hanzi":"官僚","pinyin":"guānliáo","vi":"quan liêu"},{"hanzi":"形式主义","pinyin":"xíngshìzhǔyì","vi":"chủ nghĩa hình thức"},{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"}],"traditional":"官僚主義"},{"id":"官员","hanzi":"官员","pinyin":"guānyuán","meaning_vi":"quan chức, viên chức","explanation":"官 (quan) + 员 (viên – người) → người giữ chức vụ trong cơ quan nhà nước hoặc tổ chức.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"政府官员来视察了。","pinyin":"Zhèngfǔ guānyuán lái shìchá le.","vi":"Quan chức chính phủ đã đến thị sát."},{"type":"simple","zh":"两国官员就贸易问题举行了会谈。","pinyin":"Liǎngguó guānyuán jiù màoyì wèntí jǔxíngle huìtán.","vi":"Quan chức hai nước đã hội đàm về vấn đề thương mại."},{"type":"compound","zh":"虽然他是高级官员，但是生活非常简朴。","pinyin":"Suīrán tā shì gāojí guānyuán, dànshì shēnghuó fēicháng jiǎnpǔ.","vi":"Tuy ông ấy là quan chức cấp cao nhưng sống rất giản dị."}],"related":[{"hanzi":"官吏","pinyin":"guānlì","vi":"quan lại"},{"hanzi":"公务员","pinyin":"gōngwùyuán","vi":"công chức"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"外交官","pinyin":"wàijiāoguān","vi":"nhà ngoại giao"}],"traditional":"官員"},{"id":"棺材","hanzi":"棺材","pinyin":"guāncai","meaning_vi":"quan tài","explanation":"棺 (quan – áo quan) + 材 (tài – gỗ) → hòm gỗ đựng thi hài người chết.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"⚰️","examples":[{"type":"basic","zh":"棺材是木头做的。","pinyin":"Guāncai shì mùtou zuò de.","vi":"Quan tài làm bằng gỗ."},{"type":"simple","zh":"送葬的队伍抬着棺材慢慢走向山上。","pinyin":"Sòngzàng de duìwu táizhe guāncai mànmàn zǒuxiàng shān shàng.","vi":"Đoàn đưa tang khiêng quan tài chầm chậm đi lên núi."},{"type":"compound","zh":"因为当地有这种习俗，所以老人很早就备好了棺材。","pinyin":"Yīnwèi dāngdì yǒu zhè zhǒng xísú, suǒyǐ lǎorén hěn zǎojiù bèi hǎole guāncai.","vi":"Vì địa phương có tập tục này nên người già đã chuẩn bị sẵn quan tài từ sớm."}],"related":[{"hanzi":"坟墓","pinyin":"fénmù","vi":"mồ mả"},{"hanzi":"葬礼","pinyin":"zànglǐ","vi":"tang lễ"},{"hanzi":"寿衣","pinyin":"shòuyī","vi":"áo liệm"},{"hanzi":"灵车","pinyin":"língchē","vi":"xe tang"}]},{"id":"管家","hanzi":"管家","pinyin":"guǎnjiā","meaning_vi":"quản gia, người quán xuyến việc nhà","explanation":"管 (quản – trông coi) + 家 (gia – nhà) → người trông coi việc nhà; nay cũng chỉ người quán xuyến, quản lý.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🤵","examples":[{"type":"basic","zh":"他家有个老管家。","pinyin":"Tā jiā yǒu ge lǎo guǎnjiā.","vi":"Nhà ông ấy có một lão quản gia."},{"type":"simple","zh":"管家每天早上为主人准备好报纸和咖啡。","pinyin":"Guǎnjiā měitiān zǎoshang wèi zhǔrén zhǔnbèihǎo bàozhǐ hé kāfēi.","vi":"Mỗi sáng quản gia chuẩn bị sẵn báo và cà phê cho chủ nhân."},{"type":"compound","zh":"自从妈妈出差以后，姐姐就成了家里的小管家。","pinyin":"Zìcóng māma chūchāi yǐhòu, jiějie jiù chéngle jiālǐ de xiǎo guǎnjiā.","vi":"Từ khi mẹ đi công tác, chị gái trở thành cô quản gia nhỏ của nhà."}],"related":[{"hanzi":"保姆","pinyin":"bǎomǔ","vi":"người giúp việc"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"quản lý"},{"hanzi":"主人","pinyin":"zhǔrén","vi":"chủ nhân"},{"hanzi":"仆人","pinyin":"púrén","vi":"người hầu"}]},{"id":"管教","hanzi":"管教","pinyin":"guǎnjiào","meaning_vi":"quản giáo, dạy dỗ, uốn nắn","explanation":"管 (quản – trông coi) + 教 (giáo – dạy) → trông coi và dạy dỗ cho nên người.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"👨‍👦","examples":[{"type":"basic","zh":"孩子需要管教。","pinyin":"Háizi xūyào guǎnjiào.","vi":"Trẻ con cần được dạy dỗ."},{"type":"simple","zh":"父母对他的管教一直非常严格。","pinyin":"Fùmǔ duì tā de guǎnjiào yìzhí fēicháng yángé.","vi":"Bố mẹ luôn dạy dỗ cậu ấy rất nghiêm khắc."},{"type":"compound","zh":"如果小时候不好好管教，长大后就很难改了。","pinyin":"Rúguǒ xiǎoshíhou bù hǎohǎo guǎnjiào, zhǎngdà hòu jiù hěn nán gǎi le.","vi":"Nếu lúc nhỏ không dạy dỗ cẩn thận thì lớn lên sẽ rất khó sửa."}],"related":[{"hanzi":"教育","pinyin":"jiàoyù","vi":"giáo dục"},{"hanzi":"管束","pinyin":"guǎnshù","vi":"kiềm chế"},{"hanzi":"教养","pinyin":"jiàoyǎng","vi":"giáo dưỡng"},{"hanzi":"溺爱","pinyin":"nì'ài","vi":"nuông chiều"}]},{"id":"管理费","hanzi":"管理费","pinyin":"guǎnlǐfèi","meaning_vi":"phí quản lý","explanation":"管理 (quản lý) + 费 (phí – chi phí) → khoản phí trả cho việc quản lý, như phí dịch vụ chung cư.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"每月交管理费。","pinyin":"Měiyuè jiāo guǎnlǐfèi.","vi":"Mỗi tháng đóng phí quản lý."},{"type":"simple","zh":"这个小区的物业管理费是每平米三元。","pinyin":"Zhè ge xiǎoqū de wùyè guǎnlǐfèi shì měi píngmǐ sānyuán.","vi":"Phí quản lý tòa nhà ở khu này là ba tệ mỗi mét vuông."},{"type":"compound","zh":"虽然管理费有点贵，但是小区的服务很好。","pinyin":"Suīrán guǎnlǐfèi yǒudiǎn guì, dànshì xiǎoqū de fúwù hěn hǎo.","vi":"Tuy phí quản lý hơi đắt nhưng dịch vụ của khu rất tốt."}],"related":[{"hanzi":"物业费","pinyin":"wùyèfèi","vi":"phí dịch vụ"},{"hanzi":"手续费","pinyin":"shǒuxùfèi","vi":"phí thủ tục"},{"hanzi":"费用","pinyin":"fèiyòng","vi":"chi phí"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"quản lý"}],"traditional":"管理費"},{"id":"管用","hanzi":"管用","pinyin":"guǎnyòng","meaning_vi":"có tác dụng, hiệu nghiệm, được việc","explanation":"管 (quản – lo được) + 用 (dụng – dùng) → dùng được, có hiệu quả; thường dùng trong khẩu ngữ.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"这个办法很管用。","pinyin":"Zhè ge bànfǎ hěn guǎnyòng.","vi":"Cách này rất hiệu quả."},{"type":"simple","zh":"这种药治感冒特别管用。","pinyin":"Zhè zhǒng yào zhì gǎnmào tèbié guǎnyòng.","vi":"Loại thuốc này chữa cảm đặc biệt hiệu nghiệm."},{"type":"compound","zh":"虽然奶奶的偏方很简单，但是真的挺管用。","pinyin":"Suīrán nǎinai de piānfāng hěn jiǎndān, dànshì zhēn de tǐng guǎnyòng.","vi":"Tuy bài thuốc dân gian của bà rất đơn giản nhưng thật sự khá hiệu nghiệm."}],"related":[{"hanzi":"有用","pinyin":"yǒuyòng","vi":"có ích"},{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu quả"},{"hanzi":"灵验","pinyin":"língyàn","vi":"linh nghiệm"},{"hanzi":"没用","pinyin":"méiyòng","vi":"vô dụng"}]},{"id":"贯穿","hanzi":"贯穿","pinyin":"guànchuān","meaning_vi":"xuyên suốt, xuyên qua","explanation":"贯 (quán – xâu suốt) + 穿 (xuyên – xuyên qua) → chạy xuyên qua từ đầu đến cuối.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧵","examples":[{"type":"basic","zh":"这条路贯穿全城。","pinyin":"Zhè tiáo lù guànchuān quánchéng.","vi":"Con đường này chạy xuyên suốt cả thành phố."},{"type":"simple","zh":"环保理念贯穿了整个设计过程。","pinyin":"Huánbǎo lǐniàn guànchuānle zhěnggè shèjì guòchéng.","vi":"Ý tưởng bảo vệ môi trường xuyên suốt toàn bộ quá trình thiết kế."},{"type":"compound","zh":"虽然故事很长，但是有一条主线贯穿始终。","pinyin":"Suīrán gùshi hěn cháng, dànshì yǒu yì tiáo zhǔxiàn guànchuān shǐzhōng.","vi":"Tuy câu chuyện rất dài nhưng có một mạch chính xuyên suốt từ đầu đến cuối."}],"related":[{"hanzi":"贯通","pinyin":"guàntōng","vi":"thông suốt"},{"hanzi":"穿过","pinyin":"chuānguò","vi":"đi xuyên qua"},{"hanzi":"始终","pinyin":"shǐzhōng","vi":"từ đầu đến cuối"},{"hanzi":"一以贯之","pinyin":"yìyǐguànzhī","vi":"trước sau như một"}],"traditional":"貫穿"},{"id":"惯","hanzi":"惯","pinyin":"guàn","meaning_vi":"quen; nuông chiều","explanation":"忄 (tâm – lòng) + 贯 (quán – xuyên suốt) → việc lặp đi lặp lại thành quen; còn nghĩa nuông chiều (惯孩子).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔁","examples":[{"type":"basic","zh":"我住不惯这里。","pinyin":"Wǒ zhù bu guàn zhèlǐ.","vi":"Tôi ở không quen chỗ này."},{"type":"simple","zh":"爷爷奶奶总是把孙子惯得无法无天。","pinyin":"Yéye nǎinai zǒngshì bǎ sūnzi guàn de wúfǎ wú tiān.","vi":"Ông bà lúc nào cũng nuông chiều cháu đến mức chẳng coi ai ra gì."},{"type":"compound","zh":"虽然刚来时吃不惯辣菜，但是现在我天天都想吃。","pinyin":"Suīrán gāng lái shí chī bu guàn là cài, dànshì xiànzài wǒ tiāntiān dōu xiǎng chī.","vi":"Tuy lúc mới đến ăn không quen món cay nhưng giờ ngày nào tôi cũng muốn ăn."}],"related":[{"hanzi":"习惯","pinyin":"xíguàn","vi":"thói quen"},{"hanzi":"惯例","pinyin":"guànlì","vi":"thông lệ"},{"hanzi":"娇惯","pinyin":"jiāoguàn","vi":"nuông chiều"},{"hanzi":"宠","pinyin":"chǒng","vi":"cưng chiều"}],"traditional":"慣"},{"id":"灌","hanzi":"灌","pinyin":"guàn","meaning_vi":"tưới, rót, đổ vào; ép uống","explanation":"氵 (thủy – nước) + 雚 → dẫn nước tưới vào ruộng; mở rộng là rót, đổ đầy, ép người khác uống.","hsk_level":"7-9","tags":["dong-tu"],"image":"💧","examples":[{"type":"basic","zh":"农民在灌田。","pinyin":"Nóngmín zài guàn tián.","vi":"Nông dân đang tưới ruộng."},{"type":"simple","zh":"他往保温杯里灌满了热水。","pinyin":"Tā wǎng bǎowēnbēi lǐ guàn mǎnle rèshuǐ.","vi":"Anh ấy rót đầy nước nóng vào bình giữ nhiệt."},{"type":"compound","zh":"虽然他不会喝酒，但是朋友们还是一直灌他。","pinyin":"Suīrán tā bú huì hējiǔ, dànshì péngyoumen háishi yìzhí guàn tā.","vi":"Tuy anh ấy không biết uống rượu nhưng bạn bè vẫn cứ ép anh ấy uống."}],"related":[{"hanzi":"灌溉","pinyin":"guàngài","vi":"tưới tiêu"},{"hanzi":"浇","pinyin":"jiāo","vi":"tưới"},{"hanzi":"倒","pinyin":"dào","vi":"rót"},{"hanzi":"灌输","pinyin":"guànshū","vi":"nhồi nhét, truyền bá"}]},{"id":"光碟","hanzi":"光碟","pinyin":"guāngdié","meaning_vi":"đĩa quang, đĩa CD","explanation":"光 (quang – ánh sáng) + 碟 (điệp – đĩa) → đĩa ghi dữ liệu đọc bằng tia laser.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💿","examples":[{"type":"basic","zh":"这张光碟坏了。","pinyin":"Zhè zhāng guāngdié huàile.","vi":"Chiếc đĩa CD này hỏng rồi."},{"type":"simple","zh":"他把旅行照片都刻在一张光碟里。","pinyin":"Tā bǎ lǚxíng zhàopiàn dōu kè zài yì zhāng guāngdié lǐ.","vi":"Anh ấy ghi hết ảnh du lịch vào một chiếc đĩa CD."},{"type":"compound","zh":"虽然现在很少有人用光碟，但是我还留着很多。","pinyin":"Suīrán xiànzài hěn shǎo yǒurén yòng guāngdié, dànshì wǒ hái liúzhe hěn duō.","vi":"Tuy giờ ít người dùng đĩa CD nhưng tôi vẫn giữ rất nhiều."}],"related":[{"hanzi":"光盘","pinyin":"guāngpán","vi":"đĩa quang"},{"hanzi":"碟片","pinyin":"diépiàn","vi":"đĩa phim"},{"hanzi":"光驱","pinyin":"guāngqū","vi":"ổ đĩa quang"},{"hanzi":"硬盘","pinyin":"yìngpán","vi":"ổ cứng"}]},{"id":"光泽","hanzi":"光泽","pinyin":"guāngzé","meaning_vi":"độ bóng, ánh bóng, vẻ óng ánh","explanation":"光 (quang – ánh sáng) + 泽 (trạch – bóng mượt) → ánh bóng loáng trên bề mặt vật (cũng là tên huyện Quang Trạch, Phúc Kiến).","hsk_level":"7-9","tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"珍珠有光泽。","pinyin":"Zhēnzhū yǒu guāngzé.","vi":"Ngọc trai có ánh bóng."},{"type":"simple","zh":"她的头发又黑又亮，很有光泽。","pinyin":"Tā de tóufa yòu hēi yòu liàng, hěn yǒu guāngzé.","vi":"Tóc cô ấy vừa đen vừa sáng, rất bóng mượt."},{"type":"compound","zh":"如果皮鞋经常擦油，就能保持光泽。","pinyin":"Rúguǒ píxié jīngcháng cāyóu, jiù néng bǎochí guāngzé.","vi":"Nếu giày da thường xuyên đánh xi thì sẽ giữ được độ bóng."}],"related":[{"hanzi":"光亮","pinyin":"guāngliàng","vi":"sáng bóng"},{"hanzi":"色泽","pinyin":"sèzé","vi":"màu sắc, độ bóng"},{"hanzi":"光滑","pinyin":"guānghuá","vi":"nhẵn bóng"},{"hanzi":"暗淡","pinyin":"àndàn","vi":"mờ nhạt"}],"traditional":"光澤"},{"id":"广义","hanzi":"广义","pinyin":"guǎngyì","meaning_vi":"nghĩa rộng","explanation":"广 (quảng – rộng) + 义 (nghĩa – ý nghĩa) → ý nghĩa theo phạm vi rộng; đối lập với 狭义 (nghĩa hẹp).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🔍","examples":[{"type":"basic","zh":"这是广义的文化。","pinyin":"Zhè shì guǎngyì de wénhuà.","vi":"Đây là văn hóa theo nghĩa rộng."},{"type":"simple","zh":"广义的艺术也包括烹饪和园艺。","pinyin":"Guǎngyì de yìshù yě bāokuò pēngrèn hé yuányì.","vi":"Nghệ thuật theo nghĩa rộng cũng bao gồm nấu ăn và làm vườn."},{"type":"compound","zh":"如果从广义上理解，那么音乐也是一种语言。","pinyin":"Rúguǒ cóng guǎngyì shang lǐjiě, nàme yīnyuè yě shì yì zhǒng yǔyán.","vi":"Nếu hiểu theo nghĩa rộng thì âm nhạc cũng là một loại ngôn ngữ."}],"related":[{"hanzi":"狭义","pinyin":"xiáyì","vi":"nghĩa hẹp"},{"hanzi":"含义","pinyin":"hányì","vi":"hàm nghĩa"},{"hanzi":"定义","pinyin":"dìngyì","vi":"định nghĩa"},{"hanzi":"意义","pinyin":"yìyì","vi":"ý nghĩa"}],"traditional":"廣義"},{"id":"归结","hanzi":"归结","pinyin":"guījié","meaning_vi":"quy kết, tóm lại, quy về","explanation":"归 (quy – quy về) + 结 (kết – kết lại) → gom lại, quy về một điểm chung hay kết luận.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"问题可以归结为一点。","pinyin":"Wèntí kěyǐ guījié wéi yìdiǎn.","vi":"Vấn đề có thể quy về một điểm."},{"type":"simple","zh":"他把失败归结为运气不好。","pinyin":"Tā bǎ shībài guījié wéi yùnqi bù hǎo.","vi":"Anh ta quy thất bại là do vận xui."},{"type":"compound","zh":"虽然原因很多，但是归结起来就是管理不善。","pinyin":"Suīrán yuányīn hěn duō, dànshì guījié qǐlai jiùshì guǎnlǐ búshàn.","vi":"Tuy có nhiều nguyên nhân nhưng tóm lại là do quản lý yếu kém."}],"related":[{"hanzi":"归纳","pinyin":"guīnà","vi":"quy nạp"},{"hanzi":"总结","pinyin":"zǒngjié","vi":"tổng kết"},{"hanzi":"归因","pinyin":"guīyīn","vi":"quy nguyên nhân"},{"hanzi":"概括","pinyin":"gàikuò","vi":"khái quát"}],"traditional":"歸結"},{"id":"归来","hanzi":"归来","pinyin":"guīlái","meaning_vi":"trở về, quay về","explanation":"归 (quy – về) + 来 (lai – đến) → trở về nơi cũ; sắc thái văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏡","examples":[{"type":"basic","zh":"他凯旋归来。","pinyin":"Tā kǎixuán guīlái.","vi":"Anh ấy khải hoàn trở về."},{"type":"simple","zh":"留学多年的他终于学成归来了。","pinyin":"Liúxué duōnián de tā zhōngyú xué chéng guīlái le.","vi":"Du học nhiều năm, cuối cùng anh ấy đã học thành tài trở về."},{"type":"compound","zh":"虽然离家十年，但是他归来时乡音未改。","pinyin":"Suīrán lí jiā shí nián, dànshì tā guīlái shí xiāngyīn wèi gǎi.","vi":"Tuy xa nhà mười năm nhưng khi trở về giọng quê của anh vẫn không đổi."}],"related":[{"hanzi":"回来","pinyin":"huílai","vi":"trở lại"},{"hanzi":"返回","pinyin":"fǎnhuí","vi":"quay về"},{"hanzi":"回归","pinyin":"huíguī","vi":"hồi quy"},{"hanzi":"离去","pinyin":"líqù","vi":"rời đi"}],"traditional":"歸來"},{"id":"龟","hanzi":"龟","pinyin":"guī","meaning_vi":"con rùa","explanation":"龟 (quy) là chữ tượng hình con rùa → con rùa, biểu tượng của sự trường thọ.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐢","examples":[{"type":"basic","zh":"乌龟爬得很慢。","pinyin":"Wūguī pá de hěn màn.","vi":"Con rùa bò rất chậm."},{"type":"simple","zh":"这只海龟已经活了一百多年。","pinyin":"Zhè zhī hǎiguī yǐjīng huóle yī bǎi duōnián.","vi":"Con rùa biển này đã sống hơn một trăm năm."},{"type":"compound","zh":"虽然龟走得慢，但是它最后赢了比赛。","pinyin":"Suīrán guī zǒu de màn, dànshì tā zuìhòu yíngle bǐsài.","vi":"Tuy rùa đi chậm nhưng cuối cùng nó đã thắng cuộc đua."}],"related":[{"hanzi":"乌龟","pinyin":"wūguī","vi":"con rùa"},{"hanzi":"海龟","pinyin":"hǎiguī","vi":"rùa biển"},{"hanzi":"龟壳","pinyin":"guīké","vi":"mai rùa"},{"hanzi":"龟兔赛跑","pinyin":"guītùsàipǎo","vi":"rùa và thỏ chạy đua"}],"traditional":"龜"},{"id":"桂花","hanzi":"桂花","pinyin":"guìhuā","meaning_vi":"hoa quế, hoa mộc","explanation":"桂 (quế – cây quế) + 花 (hoa) → hoa của cây mộc tê, nở vào mùa thu, rất thơm.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌼","examples":[{"type":"basic","zh":"桂花真香啊！","pinyin":"Guìhuā zhēn xiāng a!","vi":"Hoa quế thơm thật!"},{"type":"simple","zh":"每年秋天，院子里的桂花都开得很茂盛。","pinyin":"Měinián qiūtiān, yuànzi lǐ de guìhuā dōu kāi de hěn màoshèng.","vi":"Mùa thu hằng năm, hoa quế trong sân đều nở rất rộ."},{"type":"compound","zh":"因为加了桂花，所以这碗汤圆特别香。","pinyin":"Yīnwèi jiāle guìhuā, suǒyǐ zhè wǎn tāngyuán tèbié xiāng.","vi":"Vì có thêm hoa quế nên bát chè trôi nước này đặc biệt thơm."}],"related":[{"hanzi":"桂花糕","pinyin":"guìhuāgāo","vi":"bánh hoa quế"},{"hanzi":"中秋","pinyin":"Zhōngqiū","vi":"Trung thu"},{"hanzi":"荷花","pinyin":"héhuā","vi":"hoa sen"},{"hanzi":"菊花","pinyin":"júhuā","vi":"hoa cúc"}]},{"id":"滚动","hanzi":"滚动","pinyin":"gǔndòng","meaning_vi":"lăn, cuộn; chạy liên tục, luân phiên","explanation":"滚 (cổn – lăn) + 动 (động – chuyển động) → lăn tròn chuyển động; mở rộng là cuộn màn hình, chạy vòng lặp liên tục.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"石头滚动下来了。","pinyin":"Shítou gǔndòng xiàlai le.","vi":"Hòn đá lăn xuống rồi."},{"type":"simple","zh":"屏幕下方滚动播放着最新新闻。","pinyin":"Píngmù xiàfāng gǔndòng bōfàngzhe zuì xīn xīnwén.","vi":"Phía dưới màn hình đang chạy liên tục tin tức mới nhất."},{"type":"compound","zh":"如果页面太长，就用鼠标滚轮向下滚动。","pinyin":"Rúguǒ yèmiàn tài cháng, jiù yòng shǔbiāo gǔnlún xiàng xià gǔndòng.","vi":"Nếu trang quá dài thì dùng con lăn chuột để cuộn xuống."}],"related":[{"hanzi":"滚","pinyin":"gǔn","vi":"lăn"},{"hanzi":"转动","pinyin":"zhuàndòng","vi":"xoay"},{"hanzi":"滑动","pinyin":"huádòng","vi":"trượt"},{"hanzi":"滚动条","pinyin":"gǔndòngtiáo","vi":"thanh cuộn"}],"traditional":"滾動"},{"id":"棍子","hanzi":"棍子","pinyin":"gùnzi","meaning_vi":"cây gậy, que","explanation":"棍 (côn – gậy) + 子 (tử – hậu tố) → cây gậy dài.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪵","examples":[{"type":"basic","zh":"他拿着一根棍子。","pinyin":"Tā názhe yìgēn gùnzi.","vi":"Anh ấy cầm một cây gậy."},{"type":"simple","zh":"老人拄着一根木棍子慢慢走路。","pinyin":"Lǎorén zhǔzhe yìgēn mù gùnzi mànmàn zǒulù.","vi":"Ông lão chống một cây gậy gỗ chầm chậm bước đi."},{"type":"compound","zh":"虽然他手里有棍子，但是狗还是不怕他。","pinyin":"Suīrán tā shǒulǐ yǒu gùnzi, dànshì gǒu háishi bú pà tā.","vi":"Tuy trong tay anh ta có gậy nhưng con chó vẫn không sợ."}],"related":[{"hanzi":"木棍","pinyin":"mùgùn","vi":"gậy gỗ"},{"hanzi":"拐杖","pinyin":"guǎizhàng","vi":"gậy chống"},{"hanzi":"棒子","pinyin":"bàngzi","vi":"cái gậy"},{"hanzi":"竹竿","pinyin":"zhúgān","vi":"sào tre"}]},{"id":"国土","hanzi":"国土","pinyin":"Guótǔ","meaning_vi":"lãnh thổ quốc gia","explanation":"国 (quốc – nước) + 土 (thổ – đất) → đất đai thuộc chủ quyền của một quốc gia.","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"我们要保卫国土。","pinyin":"Wǒmen yào bǎowèi Guótǔ.","vi":"Chúng ta phải bảo vệ lãnh thổ."},{"type":"simple","zh":"俄罗斯是国土面积最大的国家。","pinyin":"Éluósī shì Guótǔ miànjī zuì dà de guójiā.","vi":"Nga là quốc gia có diện tích lãnh thổ lớn nhất."},{"type":"compound","zh":"虽然这个国家国土不大，但是经济非常发达。","pinyin":"Suīrán zhè ge guójiā Guótǔ búdà, dànshì jīngjì fēicháng fādá.","vi":"Tuy lãnh thổ nước này không lớn nhưng kinh tế rất phát triển."}],"related":[{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"疆土","pinyin":"jiāngtǔ","vi":"cương thổ"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"},{"hanzi":"主权","pinyin":"zhǔquán","vi":"chủ quyền"}],"traditional":"國土"},{"id":"国有","hanzi":"国有","pinyin":"guóyǒu","meaning_vi":"quốc hữu, thuộc sở hữu nhà nước","explanation":"国 (quốc – nhà nước) + 有 (hữu – sở hữu) → thuộc quyền sở hữu của nhà nước.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🏦","examples":[{"type":"basic","zh":"这是国有企业。","pinyin":"Zhè shì guóyǒuqǐyè.","vi":"Đây là doanh nghiệp nhà nước."},{"type":"simple","zh":"这片森林属于国有资产。","pinyin":"Zhè piàn sēnlín shǔyú guóyǒu zīchǎn.","vi":"Cánh rừng này thuộc tài sản nhà nước."},{"type":"compound","zh":"虽然这家银行是国有的，但是服务效率很高。","pinyin":"Suīrán zhè jiā yínháng shì guóyǒu de, dànshì fúwù xiàolǜ hěn gāo.","vi":"Tuy ngân hàng này thuộc nhà nước nhưng hiệu suất phục vụ rất cao."}],"related":[{"hanzi":"国企","pinyin":"guóqǐ","vi":"doanh nghiệp nhà nước"},{"hanzi":"私有","pinyin":"sīyǒu","vi":"tư hữu"},{"hanzi":"公有","pinyin":"gōngyǒu","vi":"công hữu"},{"hanzi":"民营","pinyin":"mínyíng","vi":"dân doanh"}],"traditional":"國有"},{"id":"裹","hanzi":"裹","pinyin":"guǒ","meaning_vi":"bọc, quấn, gói","explanation":"衣 (y – áo) chia đôi bao lấy 果 (quả) → lấy vải bọc kín lại, quấn quanh.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌯","examples":[{"type":"basic","zh":"她用纱布裹住伤口。","pinyin":"Tā yòng shābù guǒ zhù shāngkǒu.","vi":"Cô ấy dùng gạc quấn kín vết thương."},{"type":"simple","zh":"妈妈用毯子把婴儿裹得严严实实。","pinyin":"Māma yòng tǎnzi bǎ yīng'ér guǒ de yán yánshí shí.","vi":"Mẹ dùng chăn quấn em bé thật kín."},{"type":"compound","zh":"因为外面下大雪，所以他裹着围巾才出门。","pinyin":"Yīnwèi wàimiàn xià Dàxuě, suǒyǐ tā guǒzhe wéijīn cái chūmén.","vi":"Vì ngoài trời tuyết rơi dày nên anh ấy quấn khăn rồi mới ra ngoài."}],"related":[{"hanzi":"包裹","pinyin":"bāoguǒ","vi":"bưu kiện, bọc"},{"hanzi":"包","pinyin":"bāo","vi":"gói"},{"hanzi":"缠","pinyin":"chán","vi":"quấn"},{"hanzi":"裹挟","pinyin":"guǒxié","vi":"lôi cuốn"}]},{"id":"过半","hanzi":"过半","pinyin":"guòbàn","meaning_vi":"quá nửa, hơn một nửa","explanation":"过 (quá – vượt) + 半 (bán – nửa) → vượt quá một nửa.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"➗","examples":[{"type":"basic","zh":"赞成的人过半。","pinyin":"Zànchéng de rén guòbàn.","vi":"Số người tán thành đã quá nửa."},{"type":"simple","zh":"这个提案获得了过半数代表的支持。","pinyin":"Zhè ge tí'àn huòdéle guòbànshù dàibiǎo de zhīchí.","vi":"Đề án này được hơn một nửa số đại biểu ủng hộ."},{"type":"compound","zh":"虽然一年已经过半，但是计划才完成了三成。","pinyin":"Suīrán yì nián yǐjīng guòbàn, dànshì jìhuà cái wánchéngle sān chéng.","vi":"Tuy một năm đã qua quá nửa nhưng kế hoạch mới hoàn thành được ba phần mười."}],"related":[{"hanzi":"半数","pinyin":"bànshù","vi":"một nửa số"},{"hanzi":"多数","pinyin":"duōshù","vi":"đa số"},{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt quá"},{"hanzi":"过半数","pinyin":"guòbànshù","vi":"quá bán"}],"traditional":"過半"},{"id":"过不去","hanzi":"过不去","pinyin":"guòbuqù","meaning_vi":"không qua được; làm khó, gây khó dễ; áy náy","explanation":"过 (quá – qua) + 不去 (không đi được) → không thể đi qua; nghĩa bóng là làm khó ai (跟…过不去) hoặc thấy áy náy (心里过不去).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚧","examples":[{"type":"basic","zh":"前面修路，过不去。","pinyin":"Qiánmiàn xiūlù, guòbuqù.","vi":"Phía trước sửa đường, không qua được."},{"type":"simple","zh":"你何必总是跟自己过不去呢？","pinyin":"Nǐ hébì zǒngshì gēn zìjǐ guòbuqù ne?","vi":"Cần gì cậu cứ phải làm khó chính mình thế?"},{"type":"compound","zh":"虽然他原谅了我，但是我心里一直过不去。","pinyin":"Suīrán tā yuánliàngle wǒ, dànshì wǒ xīnlǐ yìzhí guòbuqù.","vi":"Tuy anh ấy đã tha thứ cho tôi nhưng trong lòng tôi vẫn mãi áy náy."}],"related":[{"hanzi":"过得去","pinyin":"guòdeqù","vi":"tạm được"},{"hanzi":"为难","pinyin":"wéinán","vi":"làm khó"},{"hanzi":"刁难","pinyin":"diāonàn","vi":"gây khó dễ"},{"hanzi":"内疚","pinyin":"nèijiù","vi":"áy náy"}],"traditional":"過不去"},{"id":"过错","hanzi":"过错","pinyin":"guòcuò","meaning_vi":"lỗi lầm, sai lầm","explanation":"过 (quá – lỗi) + 错 (thác – sai) → lỗi lầm, trách nhiệm do sai sót gây ra.","hsk_level":"7-9","tags":["danh-tu"],"image":"❌","examples":[{"type":"basic","zh":"这不是你的过错。","pinyin":"Zhèbú shì nǐ de guòcuò.","vi":"Đây không phải lỗi của cậu."},{"type":"simple","zh":"他勇敢地承认了自己的过错。","pinyin":"Tā yǒnggǎn de chéngrènle zìjǐ de guòcuò.","vi":"Anh ấy dũng cảm thừa nhận lỗi lầm của mình."},{"type":"compound","zh":"即使犯了过错，也要有改正的勇气。","pinyin":"Jíshǐ fànle guòcuò, yě yàoyǒu gǎizhèng de yǒngqì.","vi":"Dù có phạm lỗi thì cũng phải có dũng khí sửa chữa."}],"related":[{"hanzi":"错误","pinyin":"cuòwù","vi":"sai lầm"},{"hanzi":"过失","pinyin":"guòshī","vi":"sơ suất"},{"hanzi":"失误","pinyin":"shīwù","vi":"sai sót"},{"hanzi":"责任","pinyin":"zérèn","vi":"trách nhiệm"}],"traditional":"過錯"},{"id":"过道","hanzi":"过道","pinyin":"guòdào","meaning_vi":"lối đi, hành lang","explanation":"过 (quá – đi qua) + 道 (đạo – đường) → lối đi qua giữa các phòng hoặc hàng ghế.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🚪","examples":[{"type":"basic","zh":"别堵在过道上。","pinyin":"Bié dǔ zài guòdào shang.","vi":"Đừng đứng chắn lối đi."},{"type":"simple","zh":"我想要一个靠过道的座位。","pinyin":"Wǒ xiǎngyào yí ge kào guòdào de zuòwèi.","vi":"Tôi muốn một chỗ ngồi cạnh lối đi."},{"type":"compound","zh":"因为过道太窄，所以沙发搬不进去。","pinyin":"Yīnwèi guòdào tài zhǎi, suǒyǐ shāfā bān bu jìnqu.","vi":"Vì lối đi quá hẹp nên không khiêng sofa vào được."}],"related":[{"hanzi":"走廊","pinyin":"zǒuláng","vi":"hành lang"},{"hanzi":"通道","pinyin":"tōngdào","vi":"lối thông"},{"hanzi":"走道","pinyin":"zǒudào","vi":"lối đi"},{"hanzi":"靠窗","pinyin":"kàochuāng","vi":"cạnh cửa sổ"}],"traditional":"過道"},{"id":"过节","hanzi":"过节","pinyin":"guòjié","meaning_vi":"đón lễ, ăn Tết","explanation":"过 (quá – trải qua) + 节 (tiết – ngày lễ) → đón và ăn mừng ngày lễ tết.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎉","examples":[{"type":"basic","zh":"我们回家过节。","pinyin":"Wǒmen huíjiā guòjié.","vi":"Chúng tôi về nhà đón lễ."},{"type":"simple","zh":"过节的时候，街上到处挂满了红灯笼。","pinyin":"Guòjié de shíhou, jiēshang dàochù guà mǎnle hóngdēnglong.","vi":"Dịp lễ tết, khắp phố treo đầy đèn lồng đỏ."},{"type":"compound","zh":"虽然今年不能回家过节，但是我给父母寄了礼物。","pinyin":"Suīrán jīnnián bù néng huíjiā guòjié, dànshì wǒ gěi fùmǔ jìle lǐwù.","vi":"Tuy năm nay không thể về nhà đón lễ nhưng tôi đã gửi quà cho bố mẹ."}],"related":[{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"},{"hanzi":"过年","pinyin":"guònián","vi":"ăn Tết"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"chúc mừng"}],"traditional":"過節"},{"id":"过境","hanzi":"过境","pinyin":"guòjìng","meaning_vi":"quá cảnh, đi qua (lãnh thổ, khu vực)","explanation":"过 (quá – đi qua) + 境 (cảnh – biên giới) → đi qua lãnh thổ một nước để đến nơi khác; cũng nói bão đi qua (台风过境).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🛂","examples":[{"type":"basic","zh":"他在香港过境。","pinyin":"Tā zài Xiānggǎng guòjìng.","vi":"Anh ấy quá cảnh ở Hồng Kông."},{"type":"simple","zh":"持中国护照可以在这里免签过境。","pinyin":"Chí Zhōngguó hùzhào kěyǐ zài zhèlǐ miǎnqiān guòjìng.","vi":"Người cầm hộ chiếu Trung Quốc có thể quá cảnh miễn thị thực ở đây."},{"type":"compound","zh":"因为台风过境，所以所有航班都取消了。","pinyin":"Yīnwèi táifēng guòjìng, suǒyǐ suǒyǒu hángbān dōu qǔxiāo le.","vi":"Vì bão đi qua nên tất cả chuyến bay đều bị hủy."}],"related":[{"hanzi":"入境","pinyin":"rùjìng","vi":"nhập cảnh"},{"hanzi":"出境","pinyin":"chūjìng","vi":"xuất cảnh"},{"hanzi":"转机","pinyin":"zhuǎnjī","vi":"chuyển máy bay"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"thị thực"}],"traditional":"過境"},{"id":"过日子","hanzi":"过日子","pinyin":"guòrìzi","meaning_vi":"sống, sống qua ngày, lo liệu cuộc sống","explanation":"过 (quá – trải qua) + 日子 (nhật tử – ngày tháng) → trải qua ngày tháng, tức sống cuộc sống thường ngày.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🏠","examples":[{"type":"basic","zh":"他们想好好过日子。","pinyin":"Tāmen xiǎng hǎohǎo guòrìzi.","vi":"Họ muốn sống yên ổn với nhau."},{"type":"simple","zh":"小两口勤勤恳恳地过日子。","pinyin":"Xiǎoliǎngkǒu qín qínkěn kěn de guòrìzi.","vi":"Đôi vợ chồng trẻ chăm chỉ chịu khó sống qua ngày."},{"type":"compound","zh":"虽然家里不富裕，但是一家人过日子很开心。","pinyin":"Suīrán jiālǐ bú fùyù, dànshì yìjiārén guòrìzi hěn kāixīn.","vi":"Tuy nhà không giàu có nhưng cả nhà sống rất vui vẻ."}],"related":[{"hanzi":"生活","pinyin":"shēnghuó","vi":"cuộc sống"},{"hanzi":"日子","pinyin":"rìzi","vi":"ngày tháng"},{"hanzi":"过活","pinyin":"guòhuó","vi":"sống qua ngày"},{"hanzi":"度日","pinyin":"dùrì","vi":"sống qua ngày"}],"traditional":"過日子"},{"id":"过剩","hanzi":"过剩","pinyin":"guòshèng","meaning_vi":"dư thừa, quá thừa","explanation":"过 (quá – vượt) + 剩 (thặng – thừa) → thừa vượt mức cần thiết.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"市场上产品过剩。","pinyin":"Shìchǎng shang chǎnpǐn guòshèng.","vi":"Sản phẩm trên thị trường dư thừa."},{"type":"simple","zh":"这个行业已经出现了严重的产能过剩。","pinyin":"Zhè ge hángyè yǐjīng chūxiànle yánzhòng de chǎnnéng guòshèng.","vi":"Ngành này đã xuất hiện tình trạng dư thừa công suất nghiêm trọng."},{"type":"compound","zh":"如果营养过剩，就容易导致肥胖。","pinyin":"Rúguǒ yíngyǎng guòshèng, jiù róngyì dǎozhì féipàng.","vi":"Nếu dinh dưỡng dư thừa thì dễ dẫn đến béo phì."}],"related":[{"hanzi":"剩余","pinyin":"shèngyú","vi":"dư thừa"},{"hanzi":"多余","pinyin":"duōyú","vi":"thừa thãi"},{"hanzi":"短缺","pinyin":"duǎnquē","vi":"thiếu hụt"},{"hanzi":"饱和","pinyin":"bǎohé","vi":"bão hòa"}],"traditional":"過剩"},{"id":"过头","hanzi":"过头","pinyin":"guòtóu","meaning_vi":"quá mức, quá đà, quá trớn","explanation":"过 (quá – vượt) + 头 (đầu – giới hạn) → vượt quá giới hạn, quá đà; thường làm bổ ngữ (睡过头, 说过头).","hsk_level":"7-9","tags":["tinh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"话别说过头。","pinyin":"Huà biéshuō guòtóu.","vi":"Đừng nói quá lời."},{"type":"simple","zh":"他今天早上又睡过头了。","pinyin":"Tā jīntiān zǎoshang yòu shuìguòtóu le.","vi":"Sáng nay anh ấy lại ngủ quên mất."},{"type":"compound","zh":"虽然开玩笑可以活跃气氛，但是玩笑开过头就会伤人。","pinyin":"Suīrán kāiwánxiào kěyǐ huóyuè qìfēn, dànshì wánxiào kāi guòtóu jiù huì shāngrén.","vi":"Tuy đùa giỡn có thể làm không khí sôi nổi nhưng đùa quá trớn sẽ làm tổn thương người khác."}],"related":[{"hanzi":"过分","pinyin":"guòfèn","vi":"quá đáng"},{"hanzi":"过度","pinyin":"guòdù","vi":"quá độ"},{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"},{"hanzi":"睡过头","pinyin":"shuìguòtóu","vi":"ngủ quên"}],"traditional":"過頭"},{"id":"过往","hanzi":"过往","pinyin":"guòwǎng","meaning_vi":"qua lại; quá khứ, những gì đã qua","explanation":"过 (quá – qua) + 往 (vãng – đi) → đi qua đi lại, giao thiệp; cũng chỉ những chuyện đã qua.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚶","examples":[{"type":"basic","zh":"过往车辆很多。","pinyin":"Guòwǎng chēliàng hěn duō.","vi":"Xe cộ qua lại rất nhiều."},{"type":"simple","zh":"他不愿意再提起那段痛苦的过往。","pinyin":"Tā bú yuànyì zài tíqǐ nà duàn tòngkǔ de guòwǎng.","vi":"Anh ấy không muốn nhắc lại quá khứ đau khổ ấy."},{"type":"compound","zh":"虽然我们过往甚密，但是后来渐渐断了联系。","pinyin":"Suīrán wǒmen guòwǎng shèn mì, dànshì hòulái jiànjiàn duànle liánxì.","vi":"Tuy trước kia chúng tôi qua lại rất thân nhưng sau này dần mất liên lạc."}],"related":[{"hanzi":"往来","pinyin":"wǎnglái","vi":"qua lại"},{"hanzi":"过去","pinyin":"guòqù","vi":"quá khứ"},{"hanzi":"往事","pinyin":"wǎngshì","vi":"chuyện cũ"},{"hanzi":"来往","pinyin":"láiwǎng","vi":"giao thiệp"}],"traditional":"過往"},{"id":"过硬","hanzi":"过硬","pinyin":"guòyìng","meaning_vi":"vững vàng, đạt chuẩn, cứng tay nghề","explanation":"过 (quá – trải qua) + 硬 (ngạnh – cứng) → đã qua thử thách mà vẫn vững, chỉ chất lượng hay tay nghề đáng tin cậy.","hsk_level":"7-9","tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"他的技术很过硬。","pinyin":"Tā de jìshù hěn guòyìng.","vi":"Tay nghề của anh ấy rất vững."},{"type":"simple","zh":"这家工厂的产品质量过硬，深受欢迎。","pinyin":"Zhè jiā gōngchǎng de chǎnpǐn zhìliàng guòyìng, shēnshòu huānyíng.","vi":"Sản phẩm của nhà máy này chất lượng đạt chuẩn, rất được ưa chuộng."},{"type":"compound","zh":"只要本领过硬，就不怕找不到工作。","pinyin":"Zhǐyào běnlǐng guòyìng, jiù bú pà zhǎobudào gōngzuò.","vi":"Chỉ cần bản lĩnh vững vàng thì không sợ không tìm được việc."}],"related":[{"hanzi":"扎实","pinyin":"zhāshi","vi":"vững chắc"},{"hanzi":"可靠","pinyin":"kěkào","vi":"đáng tin cậy"},{"hanzi":"优良","pinyin":"yōuliáng","vi":"tốt"},{"hanzi":"本领","pinyin":"běnlǐng","vi":"bản lĩnh"}],"traditional":"過硬"},{"id":"过早","hanzi":"过早","pinyin":"guòzǎo","meaning_vi":"quá sớm, sớm quá","explanation":"过 (quá) + 早 (tảo – sớm) → sớm hơn mức thích hợp; ở Vũ Hán còn có nghĩa là ăn sáng.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"别过早下结论。","pinyin":"Bié guòzǎo xià jiélùn.","vi":"Đừng kết luận quá sớm."},{"type":"simple","zh":"他的父亲过早地离开了人世。","pinyin":"Tā de fùqīn guòzǎo de líkāile rénshì.","vi":"Cha anh ấy đã qua đời quá sớm."},{"type":"compound","zh":"如果孩子过早接触手机，就可能影响视力。","pinyin":"Rúguǒ háizi guòzǎo jiēchù shǒujī, jiù kěnéng yǐngxiǎng shìlì.","vi":"Nếu trẻ tiếp xúc với điện thoại quá sớm thì có thể ảnh hưởng thị lực."}],"related":[{"hanzi":"提早","pinyin":"tízǎo","vi":"sớm hơn"},{"hanzi":"过晚","pinyin":"guòwǎn","vi":"quá muộn"},{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"},{"hanzi":"早熟","pinyin":"zǎoshú","vi":"chín sớm"}],"traditional":"過早"},{"id":"还款","hanzi":"还款","pinyin":"huánkuǎn","meaning_vi":"trả nợ, hoàn trả tiền vay","explanation":"还 (hoàn – trả lại) + 款 (khoản – khoản tiền) → trả lại khoản tiền đã vay.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"每月按时还款。","pinyin":"Měiyuè ànshí huánkuǎn.","vi":"Mỗi tháng trả nợ đúng hạn."},{"type":"simple","zh":"银行提醒他明天是信用卡还款日。","pinyin":"Yínháng tíxǐng tā míngtiān shì xìnyòngkǎ huánkuǎn rì.","vi":"Ngân hàng nhắc anh ấy ngày mai là ngày thanh toán thẻ tín dụng."},{"type":"compound","zh":"如果逾期不还款，就会影响个人信用。","pinyin":"Rúguǒ yúqī bù huánkuǎn, jiù huì yǐngxiǎng gèrén xìnyòng.","vi":"Nếu quá hạn không trả nợ thì sẽ ảnh hưởng đến tín dụng cá nhân."}],"related":[{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"vay tiền"},{"hanzi":"借款","pinyin":"jièkuǎn","vi":"khoản vay"},{"hanzi":"欠款","pinyin":"qiànkuǎn","vi":"khoản nợ"},{"hanzi":"利息","pinyin":"lìxī","vi":"tiền lãi"}],"traditional":"還款"},{"id":"海岸","hanzi":"海岸","pinyin":"hǎi'àn","meaning_vi":"bờ biển","explanation":"海 (hải – biển) + 岸 (ngạn – bờ) → dải đất giáp với biển.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"船靠近了海岸。","pinyin":"Chuán kàojìnle hǎi'àn.","vi":"Con thuyền đã tiến gần bờ biển."},{"type":"simple","zh":"我们沿着海岸骑了一下午自行车。","pinyin":"Wǒmen yánzhe hǎi'àn qíle yí xiàwǔ zìxíngchē.","vi":"Chúng tôi đạp xe dọc bờ biển suốt một buổi chiều."},{"type":"compound","zh":"因为海岸线很长，所以这个国家渔业发达。","pinyin":"Yīnwèi hǎi'ànxiàn hěn cháng, suǒyǐ zhè ge guójiā yúyè fādá.","vi":"Vì đường bờ biển rất dài nên ngư nghiệp nước này phát triển."}],"related":[{"hanzi":"海岸线","pinyin":"hǎi'ànxiàn","vi":"đường bờ biển"},{"hanzi":"沿海","pinyin":"yánhǎi","vi":"ven biển"},{"hanzi":"海滩","pinyin":"hǎitān","vi":"bãi biển"},{"hanzi":"岸边","pinyin":"ànbiān","vi":"bờ"}]},{"id":"海盗","hanzi":"海盗","pinyin":"hǎidào","meaning_vi":"cướp biển, hải tặc","explanation":"海 (hải – biển) + 盗 (đạo – trộm cướp) → kẻ cướp hoạt động trên biển.","hsk_level":"7-9","tags":["danh-tu"],"image":"🏴‍☠️","examples":[{"type":"basic","zh":"海盗抢了商船。","pinyin":"Hǎidào qiǎngle shāngchuán.","vi":"Hải tặc đã cướp tàu buôn."},{"type":"simple","zh":"孩子们最喜欢听海盗寻宝的故事。","pinyin":"Háizimen zuì xǐhuan tīng hǎidào xúnbǎo de gùshi.","vi":"Bọn trẻ thích nhất nghe chuyện cướp biển đi tìm kho báu."},{"type":"compound","zh":"因为这一带常有海盗出没，所以商船都结伴航行。","pinyin":"Yīnwèi zhè yídài chángyǒu hǎidào chūmò, suǒyǐ shāngchuán dōu jiébàn hángxíng.","vi":"Vì vùng này thường có hải tặc lui tới nên các tàu buôn đều đi thành đoàn."}],"related":[{"hanzi":"强盗","pinyin":"qiángdào","vi":"kẻ cướp"},{"hanzi":"海盗船","pinyin":"hǎidàochuán","vi":"tàu cướp biển"},{"hanzi":"盗版","pinyin":"dàobǎn","vi":"hàng lậu"},{"hanzi":"海军","pinyin":"hǎijūn","vi":"hải quân"}],"traditional":"海盜"},{"id":"海量","hanzi":"海量","pinyin":"hǎiliàng","meaning_vi":"khối lượng khổng lồ; tửu lượng lớn; độ lượng","explanation":"海 (hải – biển) + 量 (lượng) → lượng lớn như biển; còn chỉ tửu lượng cao hoặc lòng độ lượng.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"网上有海量信息。","pinyin":"Wǎngshang yǒu hǎiliàng xìnxī.","vi":"Trên mạng có lượng thông tin khổng lồ."},{"type":"simple","zh":"这台服务器每天要处理海量数据。","pinyin":"Zhè tái fúwùqì měitiān yào chǔlǐ hǎiliàng shùjù.","vi":"Máy chủ này mỗi ngày phải xử lý lượng dữ liệu khổng lồ."},{"type":"compound","zh":"虽然网上有海量资料，但是真正有用的并不多。","pinyin":"Suīrán wǎngshang yǒu hǎiliàng zīliào, dànshì zhēnzhèng yǒuyòng de bìngbù duō.","vi":"Tuy trên mạng có vô số tài liệu nhưng thật sự hữu ích thì không nhiều."}],"related":[{"hanzi":"大量","pinyin":"dàliàng","vi":"số lượng lớn"},{"hanzi":"巨量","pinyin":"jùliàng","vi":"cực lớn"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"酒量","pinyin":"jiǔliàng","vi":"tửu lượng"}]},{"id":"海绵","hanzi":"海绵","pinyin":"hǎimián","meaning_vi":"bọt biển, miếng xốp","explanation":"海 (hải – biển) + 绵 (miên – bông mềm) → sinh vật biển mềm như bông; nay chỉ vật liệu xốp hút nước.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧽","examples":[{"type":"basic","zh":"用海绵擦桌子。","pinyin":"Yòng hǎimián cā zhuōzi.","vi":"Dùng miếng xốp lau bàn."},{"type":"simple","zh":"这块海绵吸水能力特别强。","pinyin":"Zhè kuài hǎimián xīshuǐ nénglì tèbié qiáng.","vi":"Miếng bọt biển này hút nước cực tốt."},{"type":"compound","zh":"如果你像海绵一样吸收知识，就会进步很快。","pinyin":"Rúguǒ nǐ xiàng hǎimián yíyàng xīshōu zhīshi, jiù huì jìnbù hěn kuài.","vi":"Nếu bạn hấp thụ kiến thức như miếng bọt biển thì sẽ tiến bộ rất nhanh."}],"related":[{"hanzi":"泡沫","pinyin":"pàomò","vi":"bọt xốp"},{"hanzi":"抹布","pinyin":"mābù","vi":"giẻ lau"},{"hanzi":"吸水","pinyin":"xīshuǐ","vi":"hút nước"},{"hanzi":"海绵城市","pinyin":"hǎimiánchéngshì","vi":"thành phố bọt biển"}],"traditional":"海綿"},{"id":"海面","hanzi":"海面","pinyin":"hǎimiàn","meaning_vi":"mặt biển","explanation":"海 (hải – biển) + 面 (diện – mặt) → bề mặt của biển.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌅","examples":[{"type":"basic","zh":"海面很平静。","pinyin":"Hǎimiàn hěn píngjìng.","vi":"Mặt biển rất yên ả."},{"type":"simple","zh":"一轮红日从海面上缓缓升起。","pinyin":"Yìlún hóngrì cóng hǎimiàn shang huǎnhuǎn shēngqǐ.","vi":"Vầng mặt trời đỏ từ từ nhô lên khỏi mặt biển."},{"type":"compound","zh":"虽然海面上风平浪静，但是海底暗流汹涌。","pinyin":"Suīrán hǎimiàn shangfēng píng làng jìng, dànshì hǎidǐ ànliú xiōngyǒng.","vi":"Tuy mặt biển sóng yên gió lặng nhưng dưới đáy dòng ngầm cuồn cuộn."}],"related":[{"hanzi":"海平面","pinyin":"hǎipíngmiàn","vi":"mực nước biển"},{"hanzi":"海底","pinyin":"hǎidǐ","vi":"đáy biển"},{"hanzi":"水面","pinyin":"shuǐmiàn","vi":"mặt nước"},{"hanzi":"海浪","pinyin":"hǎilàng","vi":"sóng biển"}]},{"id":"海滩","hanzi":"海滩","pinyin":"hǎitān","meaning_vi":"bãi biển","explanation":"海 (hải – biển) + 滩 (than – bãi) → bãi cát ven biển.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🏖️","examples":[{"type":"basic","zh":"我们去海滩玩吧。","pinyin":"Wǒmen qù hǎitān wán ba.","vi":"Chúng ta đi bãi biển chơi đi."},{"type":"simple","zh":"孩子们在海滩上堆起了沙堡。","pinyin":"Háizimen zài hǎitān shang duī qǐle shābǎo.","vi":"Bọn trẻ đắp lâu đài cát trên bãi biển."},{"type":"compound","zh":"因为海滩上人太多，所以我们去了旁边的小岛。","pinyin":"Yīnwèi hǎitān shang rén tài duō, suǒyǐ wǒmen qùle pángbiān de xiǎodǎo.","vi":"Vì bãi biển quá đông người nên chúng tôi ra hòn đảo nhỏ bên cạnh."}],"related":[{"hanzi":"沙滩","pinyin":"shātān","vi":"bãi cát"},{"hanzi":"海边","pinyin":"hǎibiān","vi":"bờ biển"},{"hanzi":"海岸","pinyin":"hǎi'àn","vi":"bờ biển"},{"hanzi":"游泳","pinyin":"yóuyǒng","vi":"bơi"}],"traditional":"海灘"},{"id":"海藻","hanzi":"海藻","pinyin":"hǎizǎo","meaning_vi":"rong biển, tảo biển","explanation":"海 (hải – biển) + 藻 (tảo – rong tảo) → các loài rong tảo sống ở biển.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"海藻可以吃。","pinyin":"Hǎizǎo kěyǐ chī.","vi":"Rong biển có thể ăn được."},{"type":"simple","zh":"潜水时我们看到了随波摆动的海藻。","pinyin":"Qiánshuǐ shí wǒmen kàndàole suíbō bǎidòng de hǎizǎo.","vi":"Khi lặn, chúng tôi thấy những đám rong biển đung đưa theo sóng."},{"type":"compound","zh":"因为海藻含有丰富的碘，所以经常吃对身体好。","pinyin":"Yīnwèi hǎizǎo hányǒu fēngfù de diǎn, suǒyǐ jīngcháng chī duì shēntǐ hǎo.","vi":"Vì rong biển giàu i-ốt nên ăn thường xuyên tốt cho sức khỏe."}],"related":[{"hanzi":"海带","pinyin":"hǎidài","vi":"tảo bẹ"},{"hanzi":"紫菜","pinyin":"zǐcài","vi":"rong biển khô"},{"hanzi":"藻类","pinyin":"zǎolèi","vi":"loài tảo"},{"hanzi":"海草","pinyin":"hǎicǎo","vi":"cỏ biển"}]},{"id":"害虫","hanzi":"害虫","pinyin":"hàichóng","meaning_vi":"sâu bọ có hại, côn trùng gây hại","explanation":"害 (hại) + 虫 (trùng – sâu bọ) → sâu bọ gây hại cho cây trồng hay con người.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐛","examples":[{"type":"basic","zh":"蚊子是害虫。","pinyin":"Wénzi shì hàichóng.","vi":"Muỗi là côn trùng có hại."},{"type":"simple","zh":"青蛙每天能吃掉大量害虫。","pinyin":"Qīngwā měitiān néng chīdiào dàliàng hàichóng.","vi":"Ếch mỗi ngày có thể ăn rất nhiều sâu bọ có hại."},{"type":"compound","zh":"如果不及时消灭害虫，庄稼就会减产。","pinyin":"Rúguǒ bù jíshí xiāomiè hàichóng, zhuāngjia jiù huì jiǎnchǎn.","vi":"Nếu không kịp thời diệt sâu hại thì mùa màng sẽ giảm sản lượng."}],"related":[{"hanzi":"益虫","pinyin":"yìchóng","vi":"côn trùng có ích"},{"hanzi":"虫害","pinyin":"chónghài","vi":"nạn sâu bệnh"},{"hanzi":"农药","pinyin":"nóngyào","vi":"thuốc trừ sâu"},{"hanzi":"昆虫","pinyin":"kūnchóng","vi":"côn trùng"}],"traditional":"害蟲"},{"id":"害臊","hanzi":"害臊","pinyin":"hàisào","meaning_vi":"xấu hổ, ngượng ngùng, mắc cỡ","explanation":"害 (hại – mắc phải) + 臊 (tao – thẹn) → mắc cỡ, thẹn thùng; khẩu ngữ, hay dùng 不害臊 (không biết xấu hổ).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"你真不害臊！","pinyin":"Nǐ zhēn bú hàisào!","vi":"Cậu thật không biết xấu hổ!"},{"type":"simple","zh":"小姑娘害臊地躲到了妈妈身后。","pinyin":"Xiǎo gūniang hàisào de duǒ dàole māma shēnhòu.","vi":"Cô bé ngượng ngùng nấp sau lưng mẹ."},{"type":"compound","zh":"虽然他已经二十岁了，但是跟女孩说话还会害臊。","pinyin":"Suīrán tā yǐjīng èrshí suì le, dànshì gēn nǚhái shuōhuà hái huì hàisào.","vi":"Tuy đã hai mươi tuổi nhưng cậu ấy nói chuyện với con gái vẫn còn mắc cỡ."}],"related":[{"hanzi":"害羞","pinyin":"hàixiū","vi":"xấu hổ"},{"hanzi":"难为情","pinyin":"nánwéiqíng","vi":"ngại ngùng"},{"hanzi":"脸红","pinyin":"liǎnhóng","vi":"đỏ mặt"},{"hanzi":"不要脸","pinyin":"búyàoliǎn","vi":"trơ trẽn"}]},{"id":"酣睡","hanzi":"酣睡","pinyin":"hānshuì","meaning_vi":"ngủ say, ngủ ngon lành","explanation":"酣 (hàm – say sưa) + 睡 (thụy – ngủ) → ngủ say sưa, ngon giấc.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"婴儿正在酣睡。","pinyin":"Yīng'ér zhèngzài hānshuì.","vi":"Em bé đang ngủ say."},{"type":"simple","zh":"小猫蜷在沙发上酣睡了一整个下午。","pinyin":"Xiǎomāo quán zài shāfā shang hānshuìle yì zhěnggè xiàwǔ.","vi":"Chú mèo con cuộn tròn trên sofa ngủ say cả buổi chiều."},{"type":"compound","zh":"虽然外面雷声很大，但是他依然在酣睡。","pinyin":"Suīrán wàimiàn léishēng hěn dà, dànshì tā yīrán zài hānshuì.","vi":"Tuy bên ngoài sấm rền rất to nhưng anh ấy vẫn ngủ say."}],"related":[{"hanzi":"熟睡","pinyin":"shúshuì","vi":"ngủ say"},{"hanzi":"沉睡","pinyin":"chénshuì","vi":"ngủ sâu"},{"hanzi":"入睡","pinyin":"rùshuì","vi":"đi vào giấc ngủ"},{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"}]},{"id":"函授","hanzi":"函授","pinyin":"hánshòu","meaning_vi":"đào tạo từ xa, hàm thụ","explanation":"函 (hàm – thư từ) + 授 (thụ – truyền dạy) → dạy học qua thư từ, nay gồm cả đào tạo từ xa.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✉️","examples":[{"type":"basic","zh":"他在读函授大学。","pinyin":"Tā zài dú hánshòu dàxué.","vi":"Anh ấy đang học đại học hàm thụ."},{"type":"simple","zh":"她一边工作一边参加函授学习。","pinyin":"Tā yìbiān gōngzuò yìbiān cānjiā hánshòu xuéxí.","vi":"Cô ấy vừa đi làm vừa theo học hệ đào tạo từ xa."},{"type":"compound","zh":"虽然是函授学历，但是他的专业能力很强。","pinyin":"Suīrán shì hánshòu xuélì, dànshì tā de zhuānyè nénglì hěn qiáng.","vi":"Tuy là bằng hệ hàm thụ nhưng năng lực chuyên môn của anh ấy rất giỏi."}],"related":[{"hanzi":"远程教育","pinyin":"yuǎnchéngjiàoyù","vi":"giáo dục từ xa"},{"hanzi":"自学","pinyin":"zìxué","vi":"tự học"},{"hanzi":"夜校","pinyin":"yèxiào","vi":"trường học buổi tối"},{"hanzi":"学历","pinyin":"xuélì","vi":"bằng cấp"}]},{"id":"涵盖","hanzi":"涵盖","pinyin":"hángài","meaning_vi":"bao hàm, bao quát, bao gồm","explanation":"涵 (hàm – chứa đựng) + 盖 (cái – che phủ) → chứa đựng và phủ trùm hết, tức bao quát.","hsk_level":"7-9","tags":["dong-tu"],"image":"☂️","examples":[{"type":"basic","zh":"课程涵盖面很广。","pinyin":"Kèchéng hángài miàn hěn guǎng.","vi":"Khóa học bao quát phạm vi rất rộng."},{"type":"simple","zh":"这本词典涵盖了五万多个常用词。","pinyin":"Zhè běn cídiǎn hángàile wǔ wàn duōge cháng yòngcí.","vi":"Cuốn từ điển này bao gồm hơn năm vạn từ thông dụng."},{"type":"compound","zh":"虽然报告很短，但是涵盖了所有重点。","pinyin":"Suīrán bàogào hěn duǎn, dànshì hángàile suǒyǒu zhòngdiǎn.","vi":"Tuy báo cáo rất ngắn nhưng đã bao quát mọi điểm trọng tâm."}],"related":[{"hanzi":"包括","pinyin":"bāokuò","vi":"bao gồm"},{"hanzi":"包含","pinyin":"bāohán","vi":"bao hàm"},{"hanzi":"覆盖","pinyin":"fùgài","vi":"bao phủ"},{"hanzi":"囊括","pinyin":"nángkuò","vi":"thâu tóm"}],"traditional":"涵蓋"},{"id":"涵义","hanzi":"涵义","pinyin":"hányì","meaning_vi":"hàm nghĩa, ý nghĩa","explanation":"涵 (hàm – chứa) + 义 (nghĩa) → ý nghĩa ẩn chứa bên trong; cũng viết là 含义.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"💭","examples":[{"type":"basic","zh":"这句话涵义很深。","pinyin":"Zhè jù huà hányì hěn shēn.","vi":"Câu nói này hàm nghĩa rất sâu."},{"type":"simple","zh":"这个成语的涵义你理解了吗？","pinyin":"Zhè ge chéngyǔ de hányì nǐ lǐjiěle ma?","vi":"Em đã hiểu hàm nghĩa của thành ngữ này chưa?"},{"type":"compound","zh":"虽然这首诗很短，但是涵义非常丰富。","pinyin":"Suīrán zhè shǒu shī hěn duǎn, dànshì hányì fēicháng fēngfù.","vi":"Tuy bài thơ này rất ngắn nhưng hàm nghĩa vô cùng phong phú."}],"related":[{"hanzi":"含义","pinyin":"hányì","vi":"hàm nghĩa"},{"hanzi":"意义","pinyin":"yìyì","vi":"ý nghĩa"},{"hanzi":"内涵","pinyin":"nèihán","vi":"nội hàm"},{"hanzi":"寓意","pinyin":"yùyì","vi":"ngụ ý"}],"traditional":"涵義"},{"id":"汗水","hanzi":"汗水","pinyin":"hànshuǐ","meaning_vi":"mồ hôi; công sức","explanation":"汗 (hãn – mồ hôi) + 水 (thủy – nước) → mồ hôi; nghĩa bóng là công sức lao động vất vả.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💦","examples":[{"type":"basic","zh":"汗水湿透了衣服。","pinyin":"Hànshuǐ shītòule yīfu.","vi":"Mồ hôi thấm ướt sũng quần áo."},{"type":"simple","zh":"每一枚奖牌都凝聚着运动员的汗水。","pinyin":"Měi yìméi jiǎngpái dōu níngjùzhe yùndòngyuán de hànshuǐ.","vi":"Mỗi tấm huy chương đều kết tinh mồ hôi của vận động viên."},{"type":"compound","zh":"只要付出汗水，就一定会有收获。","pinyin":"Zhǐyào fùchū hànshuǐ, jiù yídìng huì yǒu shōuhuò.","vi":"Chỉ cần đổ mồ hôi công sức thì nhất định sẽ có thu hoạch."}],"related":[{"hanzi":"出汗","pinyin":"chūhàn","vi":"ra mồ hôi"},{"hanzi":"泪水","pinyin":"lèishuǐ","vi":"nước mắt"},{"hanzi":"心血","pinyin":"xīnxuè","vi":"tâm huyết"},{"hanzi":"汗流浃背","pinyin":"hànliújiābèi","vi":"mồ hôi đầm đìa"}]},{"id":"旱","hanzi":"旱","pinyin":"hàn","meaning_vi":"hạn hán, khô hạn","explanation":"日 (nhật – mặt trời) + 干 (can – khô) → nắng làm khô cạn, tức hạn hán; còn chỉ đường bộ, trên cạn (旱路).","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🏜️","examples":[{"type":"basic","zh":"今年夏天特别旱。","pinyin":"Jīnnián xiàtiān tèbié hàn.","vi":"Mùa hè năm nay đặc biệt hạn hán."},{"type":"simple","zh":"地里旱得裂开了一道道口子。","pinyin":"Dì lǐ hàn de lièkāile yídào dào kǒuzi.","vi":"Ruộng khô hạn đến mức nứt nẻ từng đường."},{"type":"compound","zh":"因为天气太旱，所以玉米都枯死了。","pinyin":"Yīnwèi tiānqì tài hàn, suǒyǐ yùmǐ dōu kū sǐle.","vi":"Vì trời quá hạn nên ngô chết khô hết."}],"related":[{"hanzi":"干旱","pinyin":"gānhàn","vi":"khô hạn"},{"hanzi":"旱灾","pinyin":"hànzāi","vi":"nạn hạn hán"},{"hanzi":"涝","pinyin":"lào","vi":"úng lụt"},{"hanzi":"旱季","pinyin":"hànjì","vi":"mùa khô"}]},{"id":"旱灾","hanzi":"旱灾","pinyin":"hànzāi","meaning_vi":"nạn hạn hán","explanation":"旱 (hạn – khô hạn) + 灾 (tai – tai họa) → tai họa do hạn hán gây ra.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"这里发生了旱灾。","pinyin":"Zhèlǐ fāshēngle hànzāi.","vi":"Ở đây đã xảy ra hạn hán."},{"type":"simple","zh":"严重的旱灾让粮食大幅减产。","pinyin":"Yánzhòng de hànzāi ràng liángshi dàfú jiǎnchǎn.","vi":"Nạn hạn hán nghiêm trọng khiến lương thực giảm sản lượng mạnh."},{"type":"compound","zh":"虽然遭遇了旱灾，但是村民们没有放弃耕种。","pinyin":"Suīrán zāoyùle hànzāi, dànshì cūnmínmen méiyǒu fàngqì gēngzhòng.","vi":"Tuy gặp phải hạn hán nhưng dân làng không từ bỏ việc cày cấy."}],"related":[{"hanzi":"干旱","pinyin":"gānhàn","vi":"khô hạn"},{"hanzi":"水灾","pinyin":"shuǐzāi","vi":"lũ lụt"},{"hanzi":"灾害","pinyin":"zāihài","vi":"thiên tai"},{"hanzi":"灾民","pinyin":"zāimín","vi":"nạn nhân thiên tai"}],"traditional":"旱災"},{"id":"焊","hanzi":"焊","pinyin":"hàn","meaning_vi":"hàn (kim loại)","explanation":"火 (hỏa – lửa) + 旱 (hạn) → dùng nhiệt nung chảy để nối các chi tiết kim loại.","hsk_level":"7-9","tags":["dong-tu","nghe-nghiep"],"image":"🧑‍🏭","examples":[{"type":"basic","zh":"师傅在焊铁门。","pinyin":"Shīfu zài hàn tiě mén.","vi":"Bác thợ đang hàn cổng sắt."},{"type":"simple","zh":"他把断了的自行车架焊好了。","pinyin":"Tā bǎ duànle de zìxíng chējià hàn hǎo le.","vi":"Anh ấy đã hàn lại khung xe đạp bị gãy."},{"type":"compound","zh":"如果接口焊得不牢，就容易漏水。","pinyin":"Rúguǒ jiēkǒu hàn de bù láo, jiù róngyì lòushuǐ.","vi":"Nếu mối nối hàn không chắc thì dễ bị rò nước."}],"related":[{"hanzi":"焊接","pinyin":"hànjiē","vi":"hàn nối"},{"hanzi":"电焊","pinyin":"diànhàn","vi":"hàn điện"},{"hanzi":"焊工","pinyin":"hàngōng","vi":"thợ hàn"},{"hanzi":"焊锡","pinyin":"hànxī","vi":"thiếc hàn"}]},{"id":"航海","hanzi":"航海","pinyin":"hánghǎi","meaning_vi":"hàng hải, đi biển","explanation":"航 (hàng – đi thuyền) + 海 (hải – biển) → đi thuyền vượt biển.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"⛵","examples":[{"type":"basic","zh":"他从小热爱航海。","pinyin":"Tā cóngxiǎo rè'ài hánghǎi.","vi":"Từ nhỏ anh ấy đã đam mê đi biển."},{"type":"simple","zh":"郑和是中国古代伟大的航海家。","pinyin":"Zhènghé shì Zhōngguó gǔdài wěidà de hánghǎijiā.","vi":"Trịnh Hòa là nhà hàng hải vĩ đại thời cổ đại Trung Quốc."},{"type":"compound","zh":"虽然航海很危险，但是他还是想环游世界。","pinyin":"Suīrán hánghǎi hěn wēixiǎn, dànshì tā háishi xiǎng huányóu shìjiè.","vi":"Tuy đi biển rất nguy hiểm nhưng anh ấy vẫn muốn đi vòng quanh thế giới."}],"related":[{"hanzi":"航行","pinyin":"hángxíng","vi":"hành trình trên biển"},{"hanzi":"航海家","pinyin":"hánghǎijiā","vi":"nhà hàng hải"},{"hanzi":"船员","pinyin":"chuányuán","vi":"thủy thủ"},{"hanzi":"航运","pinyin":"hángyùn","vi":"vận tải đường thủy"}]},{"id":"航运","hanzi":"航运","pinyin":"hángyùn","meaning_vi":"vận tải đường thủy","explanation":"航 (hàng – đi thuyền) + 运 (vận – chuyên chở) → chuyên chở hàng hóa, hành khách bằng tàu thuyền.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"这里航运很发达。","pinyin":"Zhèlǐ hángyùn hěn fādá.","vi":"Vận tải đường thủy ở đây rất phát triển."},{"type":"simple","zh":"长江是中国最重要的内河航运通道。","pinyin":"Chángjiāng shì Zhōngguó zuì zhòngyào de nèihé hángyùn tōngdào.","vi":"Trường Giang là tuyến vận tải đường sông quan trọng nhất Trung Quốc."},{"type":"compound","zh":"因为航运成本较低，所以很多大宗货物都走海路。","pinyin":"Yīnwèi hángyùn chéngběn jiào dī, suǒyǐ hěn duō dàzōng huòwù dōu zǒu hǎi lù.","vi":"Vì chi phí vận tải thủy khá thấp nên nhiều hàng hóa khối lượng lớn đều đi đường biển."}],"related":[{"hanzi":"海运","pinyin":"hǎiyùn","vi":"vận tải biển"},{"hanzi":"空运","pinyin":"kōngyùn","vi":"vận tải hàng không"},{"hanzi":"港口","pinyin":"gǎngkǒu","vi":"bến cảng"},{"hanzi":"物流","pinyin":"wùliú","vi":"hậu cần"}],"traditional":"航運"},{"id":"毫不","hanzi":"毫不","pinyin":"háobù","meaning_vi":"không hề, chẳng chút nào","explanation":"毫 (hào – sợi lông, chút xíu) + 不 (bất – không) → không một chút nào; thường đi với động từ hai âm tiết.","hsk_level":"7-9","tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"他毫不犹豫。","pinyin":"Tā háobùyóuyù.","vi":"Anh ấy không hề do dự."},{"type":"simple","zh":"她毫不在乎别人的眼光。","pinyin":"Tā háobú zàihu biérén de yǎnguāng.","vi":"Cô ấy chẳng hề bận tâm ánh mắt người khác."},{"type":"compound","zh":"虽然对手很强，但是他毫不畏惧。","pinyin":"Suīrán duìshǒu hěn qiáng, dànshì tā háobú wèijù.","vi":"Tuy đối thủ rất mạnh nhưng anh ấy không hề sợ hãi."}],"related":[{"hanzi":"丝毫","pinyin":"sīháo","vi":"mảy may"},{"hanzi":"毫无","pinyin":"háowú","vi":"không hề có"},{"hanzi":"一点也不","pinyin":"yìdiǎnyěbù","vi":"chẳng chút nào"},{"hanzi":"绝不","pinyin":"juébù","vi":"tuyệt không"}]},{"id":"好比","hanzi":"好比","pinyin":"hǎobǐ","meaning_vi":"giống như, có thể ví như","explanation":"好 (hảo) + 比 (tỉ – so sánh) → có thể đem ra ví như, chẳng khác gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪞","examples":[{"type":"basic","zh":"人生好比一场旅行。","pinyin":"Rénshēng hǎobǐ yì chǎng lǚxíng.","vi":"Đời người giống như một chuyến du hành."},{"type":"simple","zh":"读书好比和古人交朋友。","pinyin":"Dúshū hǎobǐ hé gǔrén jiāopéngyou.","vi":"Đọc sách giống như kết bạn với người xưa."},{"type":"compound","zh":"如果说老师好比园丁，那么学生就是花朵。","pinyin":"Rúguǒshuō lǎoshī hǎobǐ yuándīng, nàme xuésheng jiùshì huāduǒ.","vi":"Nếu nói thầy cô giống như người làm vườn thì học sinh chính là những bông hoa."}],"related":[{"hanzi":"好像","pinyin":"hǎoxiàng","vi":"giống như"},{"hanzi":"比如","pinyin":"bǐrú","vi":"ví dụ"},{"hanzi":"如同","pinyin":"rútóng","vi":"như là"},{"hanzi":"比喻","pinyin":"bǐyù","vi":"ví von"}]},{"id":"好歹","hanzi":"好歹","pinyin":"hǎodǎi","meaning_vi":"dù sao, bất kể thế nào; tốt xấu; bất trắc","explanation":"好 (hảo – tốt) + 歹 (đãi – xấu) → tốt và xấu; làm phó từ nghĩa \"dù sao cũng\", làm danh từ chỉ điều bất trắc (有个好歹).","hsk_level":"7-9","tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"你好歹吃一点。","pinyin":"Nǐ hǎodǎi chī yìdiǎn.","vi":"Dù sao con cũng ăn một chút đi."},{"type":"simple","zh":"他这个人真是不知好歹。","pinyin":"Tā zhè ge rén zhēn shì bùzhī hǎodǎi.","vi":"Người này thật là không biết điều."},{"type":"compound","zh":"虽然考得不理想，但是好歹及格了。","pinyin":"Suīrán kǎo de bù lǐxiǎng, dànshì hǎodǎi jígé le.","vi":"Tuy thi không được như ý nhưng dù sao cũng đã đỗ."}],"related":[{"hanzi":"好坏","pinyin":"hǎohuài","vi":"tốt xấu"},{"hanzi":"无论如何","pinyin":"wúlùnrúhé","vi":"dù thế nào"},{"hanzi":"至少","pinyin":"zhìshǎo","vi":"ít nhất"},{"hanzi":"不知好歹","pinyin":"bùzhīhǎodǎi","vi":"không biết điều"}]},{"id":"好坏","hanzi":"好坏","pinyin":"hǎohuài","meaning_vi":"tốt xấu, chất lượng","explanation":"好 (hảo – tốt) + 坏 (hoại – xấu) → tốt và xấu, dùng để chỉ chất lượng hay mức độ.","hsk_level":"7-9","tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"好坏要分清。","pinyin":"Hǎohuài yào fēnqīng.","vi":"Tốt xấu phải phân biệt rõ."},{"type":"simple","zh":"产品质量的好坏决定了企业的命运。","pinyin":"Chǎnpǐn zhìliàng de hǎohuài juédìngle qǐyè de mìngyùn.","vi":"Chất lượng sản phẩm tốt hay xấu quyết định vận mệnh doanh nghiệp."},{"type":"compound","zh":"不管比赛结果好坏，我们都要坦然接受。","pinyin":"Bùguǎn bǐsài jiéguǒ hǎohuài, wǒmen dōu yào tǎnrán jiēshòu.","vi":"Bất kể kết quả trận đấu tốt hay xấu, chúng ta đều phải thản nhiên chấp nhận."}],"related":[{"hanzi":"好歹","pinyin":"hǎodǎi","vi":"tốt xấu"},{"hanzi":"优劣","pinyin":"yōuliè","vi":"ưu kém"},{"hanzi":"质量","pinyin":"zhìliàng","vi":"chất lượng"},{"hanzi":"是非","pinyin":"shìfēi","vi":"đúng sai"}],"traditional":"好壞"},{"id":"好家伙","hanzi":"好家伙","pinyin":"hǎojiāhuo","meaning_vi":"trời đất ơi, chà chà, ghê thật","explanation":"好 (hảo) + 家伙 (gia hỏa – gã, thứ) → thán từ khẩu ngữ biểu lộ sự ngạc nhiên hoặc thán phục.","hsk_level":"7-9","tags":["tro-tu","giao-tiep"],"image":"😲","examples":[{"type":"basic","zh":"好家伙，这么多人！","pinyin":"Hǎojiāhuo, zhème duō rén!","vi":"Trời đất, đông người thế!"},{"type":"simple","zh":"好家伙，你一个人吃了三碗饭！","pinyin":"Hǎojiāhuo, nǐ yígerén chīle sān wǎn fàn!","vi":"Chà chà, một mình cậu ăn hết ba bát cơm!"},{"type":"compound","zh":"好家伙，虽然只学了一个月，但是你说得真流利！","pinyin":"Hǎojiāhuo, suīrán zhǐ xuéle yí geyuè, dànshì nǐ shuō de zhēn liúlì!","vi":"Ghê thật, tuy mới học một tháng mà cậu nói lưu loát quá!"}],"related":[{"hanzi":"天哪","pinyin":"tiānna","vi":"trời ơi"},{"hanzi":"哎呀","pinyin":"āiyā","vi":"ôi chao"},{"hanzi":"家伙","pinyin":"jiāhuo","vi":"gã, thứ"},{"hanzi":"了不起","pinyin":"liǎobuqǐ","vi":"giỏi thật"}],"traditional":"好傢伙"},{"id":"好评","hanzi":"好评","pinyin":"hǎopíng","meaning_vi":"lời khen, đánh giá tốt","explanation":"好 (hảo – tốt) + 评 (bình – đánh giá) → lời đánh giá tốt.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"⭐","examples":[{"type":"basic","zh":"这部电影获得好评。","pinyin":"Zhè bù diànyǐng huòdé hǎopíng.","vi":"Bộ phim này nhận được đánh giá tốt."},{"type":"simple","zh":"买家给这家店铺留下了五星好评。","pinyin":"Mǎijiā gěi zhè jiā diànpù liúxiàle wǔxīng hǎopíng.","vi":"Người mua đã để lại đánh giá năm sao cho cửa hàng này."},{"type":"compound","zh":"因为服务很周到，所以这家酒店好评不断。","pinyin":"Yīnwèi fúwù hěn zhōudào, suǒyǐ zhè jiā jiǔdiàn hǎopíng búduàn.","vi":"Vì phục vụ rất chu đáo nên khách sạn này liên tục được khen."}],"related":[{"hanzi":"差评","pinyin":"chàpíng","vi":"đánh giá xấu"},{"hanzi":"评价","pinyin":"píngjià","vi":"đánh giá"},{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"口碑","pinyin":"kǒubēi","vi":"tiếng tăm"}],"traditional":"好評"},{"id":"好说","hanzi":"好说","pinyin":"hǎoshuō","meaning_vi":"dễ thôi, không thành vấn đề; quá khen","explanation":"好 (hảo – dễ) + 说 (thuyết – nói) → dễ bàn, dễ thu xếp; còn là lời đáp lịch sự khi được cảm ơn, khen ngợi.","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"👌","examples":[{"type":"basic","zh":"这事好说，交给我吧。","pinyin":"Zhè shì hǎoshuō, jiāogěi wǒ ba.","vi":"Việc này dễ thôi, để tôi lo."},{"type":"simple","zh":"您太客气了，好说好说。","pinyin":"Nín tài kèqi le, hǎoshuō hǎoshuō.","vi":"Anh khách sáo quá, không có gì đâu."},{"type":"compound","zh":"如果你真心想学，学费的事就好说。","pinyin":"Rúguǒ nǐ zhēnxīn xiǎng xué, xuéfèi de shì jiù hǎoshuō.","vi":"Nếu em thật lòng muốn học thì chuyện học phí dễ thôi."}],"related":[{"hanzi":"没问题","pinyin":"méiwèntí","vi":"không vấn đề"},{"hanzi":"好办","pinyin":"hǎobàn","vi":"dễ giải quyết"},{"hanzi":"商量","pinyin":"shāngliang","vi":"bàn bạc"},{"hanzi":"过奖","pinyin":"guòjiǎng","vi":"quá khen"}],"traditional":"好說"},{"id":"好笑","hanzi":"好笑","pinyin":"hǎoxiào","meaning_vi":"buồn cười, nực cười","explanation":"好 (hảo – dễ) + 笑 (tiếu – cười) → dễ khiến người ta cười; cũng mang nghĩa nực cười, lố bịch.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😂","examples":[{"type":"basic","zh":"这个笑话真好笑。","pinyin":"Zhè ge xiàohua zhēn hǎoxiào.","vi":"Câu chuyện cười này buồn cười thật."},{"type":"simple","zh":"他一本正经的样子让人觉得很好笑。","pinyin":"Tā yì běn zhèngjīng de yàngzi ràng rén juéde hěn hǎoxiào.","vi":"Bộ dạng nghiêm trang của anh ấy khiến người ta thấy rất buồn cười."},{"type":"compound","zh":"虽然这件事有点好笑，但是大家都忍住了。","pinyin":"Suīrán zhè jiàn shì yǒudiǎn hǎoxiào, dànshì dàjiā dōu rěn zhù le.","vi":"Tuy chuyện này hơi buồn cười nhưng mọi người đều nhịn được."}],"related":[{"hanzi":"可笑","pinyin":"kěxiào","vi":"nực cười"},{"hanzi":"搞笑","pinyin":"gǎoxiào","vi":"gây cười"},{"hanzi":"滑稽","pinyin":"huájī","vi":"khôi hài"},{"hanzi":"幽默","pinyin":"yōumò","vi":"hài hước"}]},{"id":"好心","hanzi":"好心","pinyin":"hǎoxīn","meaning_vi":"lòng tốt, có ý tốt, tốt bụng","explanation":"好 (hảo – tốt) + 心 (tâm – lòng) → tấm lòng tốt; cũng dùng như tính từ \"tốt bụng\".","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💗","examples":[{"type":"basic","zh":"谢谢你的好心。","pinyin":"Xièxie nǐ de hǎoxīn.","vi":"Cảm ơn lòng tốt của bạn."},{"type":"simple","zh":"一位好心的阿姨帮我找到了钱包。","pinyin":"Yí wèi hǎoxīn de āyí bāng wǒ zhǎodàole qiánbāo.","vi":"Một cô tốt bụng đã giúp tôi tìm được ví tiền."},{"type":"compound","zh":"虽然他是一片好心，但是方法用错了。","pinyin":"Suīrán tā shì yípiàn hǎoxīn, dànshì fāngfǎ yòng cuò le.","vi":"Tuy anh ấy có lòng tốt nhưng lại dùng sai cách."}],"related":[{"hanzi":"好意","pinyin":"hǎoyì","vi":"ý tốt"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"好心人","pinyin":"hǎoxīnrén","vi":"người tốt bụng"},{"hanzi":"热心","pinyin":"rèxīn","vi":"nhiệt tình"}]},{"id":"好心人","hanzi":"好心人","pinyin":"hǎoxīnrén","meaning_vi":"người tốt bụng, người hảo tâm","explanation":"好心 (hảo tâm – lòng tốt) + 人 (nhân – người) → người có lòng tốt, sẵn sàng giúp đỡ người khác.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"😇","examples":[{"type":"basic","zh":"他是个好心人。","pinyin":"Tā shì ge hǎoxīnrén.","vi":"Anh ấy là người tốt bụng."},{"type":"simple","zh":"一个好心人把迷路的孩子送回了家。","pinyin":"Yí ge hǎoxīnrén bǎ mílù de háizi sòng huíle jiā.","vi":"Một người tốt bụng đã đưa đứa trẻ lạc đường về nhà."},{"type":"compound","zh":"如果没有那位好心人帮忙，我们就赶不上火车了。","pinyin":"Rúguǒ méiyǒu nà wèi hǎoxīnrén bāngmáng, wǒmen jiù gǎnbushàng huǒchē le.","vi":"Nếu không có người tốt bụng đó giúp, chúng tôi đã không kịp chuyến tàu."}],"related":[{"hanzi":"好心","pinyin":"hǎoxīn","vi":"lòng tốt"},{"hanzi":"热心人","pinyin":"rèxīnrén","vi":"người nhiệt tình"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"坏人","pinyin":"huàirén","vi":"kẻ xấu"}]},{"id":"好意","hanzi":"好意","pinyin":"hǎoyì","meaning_vi":"ý tốt, thiện ý, lòng tốt","explanation":"好 (hảo – tốt) + 意 (ý – ý định) → ý định tốt đẹp dành cho người khác.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🤲","examples":[{"type":"basic","zh":"谢谢你的好意。","pinyin":"Xièxie nǐ de hǎoyì.","vi":"Cảm ơn ý tốt của bạn."},{"type":"simple","zh":"他的提醒完全是出于好意。","pinyin":"Tā de tíxǐng wánquán shì chūyú hǎoyì.","vi":"Lời nhắc của anh ấy hoàn toàn xuất phát từ ý tốt."},{"type":"compound","zh":"虽然我明白你的好意，但是这份礼物我不能收。","pinyin":"Suīrán wǒ míngbai nǐ de hǎoyì, dànshì zhè fèn lǐwù wǒ bù néng shōu.","vi":"Tuy tôi hiểu ý tốt của bạn nhưng món quà này tôi không thể nhận."}],"related":[{"hanzi":"好心","pinyin":"hǎoxīn","vi":"lòng tốt"},{"hanzi":"善意","pinyin":"shànyì","vi":"thiện ý"},{"hanzi":"恶意","pinyin":"èyì","vi":"ác ý"},{"hanzi":"心意","pinyin":"xīnyì","vi":"tấm lòng"}]},{"id":"好在","hanzi":"好在","pinyin":"hǎozài","meaning_vi":"may mà, may là, được cái là","explanation":"好 (hảo – tốt) + 在 (tại – ở chỗ) → điều tốt nằm ở chỗ…; dùng để nêu một điều kiện may mắn trong tình huống bất lợi.","hsk_level":"7-9","tags":["pho-tu"],"image":"🍀","examples":[{"type":"basic","zh":"好在没人受伤。","pinyin":"Hǎozài méi rén shòushāng.","vi":"May mà không ai bị thương."},{"type":"simple","zh":"下大雨了，好在我带了伞。","pinyin":"Xià dàyǔ le, hǎozài wǒ dàile sǎn.","vi":"Trời mưa to rồi, may là tôi có mang ô."},{"type":"compound","zh":"虽然路上堵车了，但是好在会议推迟了半小时。","pinyin":"Suīrán lùshang dǔchē le, dànshì hǎozài huìyì tuīchíle bànxiǎoshí.","vi":"Tuy trên đường bị tắc xe nhưng may là cuộc họp lùi lại nửa tiếng."}],"related":[{"hanzi":"幸亏","pinyin":"xìngkuī","vi":"may mà"},{"hanzi":"幸好","pinyin":"xìnghǎo","vi":"may thay"},{"hanzi":"多亏","pinyin":"duōkuī","vi":"nhờ có"},{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"}]},{"id":"号称","hanzi":"号称","pinyin":"hàochēng","meaning_vi":"được gọi là, nổi tiếng là, tự xưng là","explanation":"号 (hiệu – tên gọi) + 称 (xưng – gọi) → được mệnh danh là; cũng chỉ việc tự xưng, thường mang ý phóng đại.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📣","examples":[{"type":"basic","zh":"这里号称“春城”。","pinyin":"Zhèlǐ hàochēng \"chūnchéng\".","vi":"Nơi đây được gọi là \"thành phố mùa xuân\"."},{"type":"simple","zh":"这家店号称全市最好吃的火锅。","pinyin":"Zhè jiā diàn hàochēng quánshì zuì hǎochī de huǒguō.","vi":"Quán này tự xưng là lẩu ngon nhất thành phố."},{"type":"compound","zh":"这款手机虽然号称防水，但是掉进水里还是坏了。","pinyin":"Zhè kuǎn shǒujī suīrán hàochēng fángshuǐ, dànshì diào jìnshuǐ lǐ háishi huàile.","vi":"Mẫu điện thoại này tuy được quảng cáo là chống nước nhưng rơi xuống nước vẫn hỏng."}],"related":[{"hanzi":"称为","pinyin":"chēngwéi","vi":"được gọi là"},{"hanzi":"自称","pinyin":"zìchēng","vi":"tự xưng"},{"hanzi":"号","pinyin":"hào","vi":"danh hiệu"},{"hanzi":"著称","pinyin":"zhùchēng","vi":"nổi tiếng"}],"traditional":"號稱"},{"id":"浩劫","hanzi":"浩劫","pinyin":"hàojié","meaning_vi":"đại họa, thảm họa lớn, kiếp nạn","explanation":"浩 (hạo – to lớn) + 劫 (kiếp – tai kiếp) → tai họa vô cùng to lớn, thường dùng cho chiến tranh, thiên tai.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌋","examples":[{"type":"basic","zh":"那是一场浩劫。","pinyin":"Nàshì yì chǎng hàojié.","vi":"Đó là một thảm họa lớn."},{"type":"simple","zh":"这座古城在战争中经历了一场浩劫。","pinyin":"Zhè zuò gǔchéng zài zhànzhēng zhōng jīnglìle yì chǎng hàojié.","vi":"Tòa cổ thành này đã trải qua một đại họa trong chiến tranh."},{"type":"compound","zh":"即使经历了这场浩劫，人们也没有失去希望。","pinyin":"Jíshǐ jīnglìle zhè chǎng hàojié, rénmen yě méiyǒu shīqù xīwàng.","vi":"Dù trải qua thảm họa này, mọi người vẫn không mất hy vọng."}],"related":[{"hanzi":"灾难","pinyin":"zāinàn","vi":"tai nạn, thảm họa"},{"hanzi":"劫难","pinyin":"jiénàn","vi":"kiếp nạn"},{"hanzi":"灾害","pinyin":"zāihài","vi":"thiên tai"},{"hanzi":"战乱","pinyin":"zhànluàn","vi":"loạn lạc chiến tranh"}]},{"id":"耗","hanzi":"耗","pinyin":"hào","meaning_vi":"tiêu hao, tốn, hao phí; dây dưa, kéo dài","explanation":"耗 (hao – hao tổn) → tiêu tốn, làm hao hụt (sức lực, thời gian, tiền bạc); khẩu ngữ còn có nghĩa \"dây dưa, kéo dài\".","hsk_level":"7-9","tags":["dong-tu"],"image":"🔋","examples":[{"type":"basic","zh":"这车很耗油。","pinyin":"Zhè chē hěn hào yóu.","vi":"Chiếc xe này rất tốn xăng."},{"type":"simple","zh":"玩手机游戏特别耗电。","pinyin":"Wán shǒujī yóuxì tèbié hàodiàn.","vi":"Chơi game điện thoại đặc biệt tốn pin."},{"type":"compound","zh":"如果再这样耗下去，我们就会错过最好的机会。","pinyin":"Rúguǒ zài zhèyàng hào xiàqu, wǒmen jiù huì cuòguò zuìhǎo de jīhuì.","vi":"Nếu cứ dây dưa thế này nữa, chúng ta sẽ bỏ lỡ cơ hội tốt nhất."}],"related":[{"hanzi":"消耗","pinyin":"xiāohào","vi":"tiêu hao"},{"hanzi":"耗费","pinyin":"hàofèi","vi":"hao phí"},{"hanzi":"耗时","pinyin":"hàoshí","vi":"tốn thời gian"},{"hanzi":"损耗","pinyin":"sǔnhào","vi":"hao tổn"}]},{"id":"耗时","hanzi":"耗时","pinyin":"hàoshí","meaning_vi":"tốn thời gian, mất (bao lâu)","explanation":"耗 (hao – tiêu tốn) + 时 (thời – thời gian) → tiêu tốn thời gian, mất bao nhiêu thời gian để làm xong.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"这项工作很耗时。","pinyin":"Zhè xiàng gōngzuò hěn hàoshí.","vi":"Công việc này rất tốn thời gian."},{"type":"simple","zh":"这座大桥的建设耗时五年。","pinyin":"Zhè zuò Dàqiáo de jiànshè hàoshí wǔ nián.","vi":"Việc xây cây cầu lớn này mất năm năm."},{"type":"compound","zh":"因为手工制作非常耗时，所以价格比较高。","pinyin":"Yīnwèi shǒugōng zhìzuò fēicháng hàoshí, suǒyǐ jiàgé bǐjiào gāo.","vi":"Vì làm thủ công rất tốn thời gian nên giá khá cao."}],"related":[{"hanzi":"耗费","pinyin":"hàofèi","vi":"hao phí"},{"hanzi":"费时","pinyin":"fèishí","vi":"tốn thời gian"},{"hanzi":"省时","pinyin":"shěngshí","vi":"tiết kiệm thời gian"},{"hanzi":"历时","pinyin":"lìshí","vi":"kéo dài (thời gian)"}],"traditional":"耗時"},{"id":"喝彩","hanzi":"喝彩","pinyin":"hècǎi","meaning_vi":"reo hò khen ngợi, cổ vũ, hoan hô","explanation":"喝 (hát – hô to) + 彩 (thái – tiếng khen hay) → hô to tiếng khen, reo hò tán thưởng.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"👏","examples":[{"type":"basic","zh":"观众大声喝彩。","pinyin":"Guānzhòng dàshēng hècǎi.","vi":"Khán giả lớn tiếng reo hò."},{"type":"simple","zh":"他精彩的表演赢得了全场喝彩。","pinyin":"Tā jīngcǎi de biǎoyǎn yíng déle quánchǎng hècǎi.","vi":"Màn biểu diễn đặc sắc của anh ấy nhận được tràng hoan hô của cả khán phòng."},{"type":"compound","zh":"每当球员进球，看台上就响起一片喝彩声。","pinyin":"Měidāng qiúyuán jìnqiú, kàntái shang jiù xiǎngqǐ yípiàn hècǎi shēng.","vi":"Mỗi khi cầu thủ ghi bàn, trên khán đài lại vang lên tiếng reo hò."}],"related":[{"hanzi":"欢呼","pinyin":"huānhū","vi":"hoan hô"},{"hanzi":"鼓掌","pinyin":"gǔzhǎng","vi":"vỗ tay"},{"hanzi":"叫好","pinyin":"jiàohǎo","vi":"khen hay"},{"hanzi":"喝倒彩","pinyin":"hèdàocǎi","vi":"la ó chê bai"}]},{"id":"禾苗","hanzi":"禾苗","pinyin":"hémiáo","meaning_vi":"mạ, cây lúa non, mầm lúa","explanation":"禾 (hòa – cây lúa) + 苗 (miêu – mầm non) → cây lúa hoặc cây ngũ cốc còn non.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"禾苗长高了。","pinyin":"Hémiáo zhǎnggāo le.","vi":"Lúa non đã cao lên rồi."},{"type":"simple","zh":"一场春雨过后，田里的禾苗绿油油的。","pinyin":"Yì chǎng chūnyǔ guòhòu, tián lǐ de hémiáo lǜyóuyóu de.","vi":"Sau một trận mưa xuân, lúa non ngoài đồng xanh mơn mởn."},{"type":"compound","zh":"要是今年再不下雨，禾苗就要枯死了。","pinyin":"Yàoshi jīnnián zài bú xiàyǔ, hémiáo jiùyào kū sǐle.","vi":"Nếu năm nay còn không mưa thì lúa non sẽ chết khô mất."}],"related":[{"hanzi":"秧苗","pinyin":"yāngmiáo","vi":"cây mạ"},{"hanzi":"庄稼","pinyin":"zhuāngjia","vi":"hoa màu"},{"hanzi":"稻田","pinyin":"dàotián","vi":"ruộng lúa"},{"hanzi":"幼苗","pinyin":"yòumiáo","vi":"cây non"}]},{"id":"合乎","hanzi":"合乎","pinyin":"héhū","meaning_vi":"phù hợp với, hợp với","explanation":"合 (hợp – phù hợp) + 乎 (hồ – trợ từ, như 于) → phù hợp với (quy định, tiêu chuẩn, logic…); dùng trong văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"这合乎规定。","pinyin":"Zhè héhū guīdìng.","vi":"Điều này phù hợp với quy định."},{"type":"simple","zh":"他的说法完全合乎逻辑。","pinyin":"Tā de shuōfǎ wánquán héhū luójí.","vi":"Cách nói của anh ấy hoàn toàn hợp logic."},{"type":"compound","zh":"只要产品合乎标准，我们就可以签合同。","pinyin":"Zhǐyào chǎnpǐn héhū biāozhǔn, wǒmen jiù kěyǐ qiānhétong.","vi":"Chỉ cần sản phẩm phù hợp tiêu chuẩn, chúng ta có thể ký hợp đồng."}],"related":[{"hanzi":"符合","pinyin":"fúhé","vi":"phù hợp"},{"hanzi":"合理","pinyin":"hélǐ","vi":"hợp lý"},{"hanzi":"合情合理","pinyin":"héqínghélǐ","vi":"thấu tình đạt lý"},{"hanzi":"违背","pinyin":"wéibèi","vi":"trái với"}]},{"id":"合计","hanzi":"合计","pinyin":"héjì","meaning_vi":"tổng cộng, cộng lại; tính toán, bàn bạc","explanation":"合 (hợp – gộp lại) + 计 (kế – tính) → cộng gộp lại thành tổng; khẩu ngữ (đọc hé ji) còn nghĩa là tính toán, bàn tính.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"🧮","examples":[{"type":"basic","zh":"合计一百元。","pinyin":"Héjì yī bǎi yuán.","vi":"Tổng cộng một trăm tệ."},{"type":"simple","zh":"这几个月的开销合计超过了两万。","pinyin":"Zhè jǐ geyuè de kāixiāo héjì chāoguòle liǎng wàn.","vi":"Chi tiêu mấy tháng nay cộng lại đã vượt hai vạn."},{"type":"compound","zh":"既然大家意见不同，就先坐下来合计合计吧。","pinyin":"Jìrán dàjiā yìjiàn bùtóng, jiù xiān zuò xiàlai héjì héjì ba.","vi":"Đã mọi người ý kiến khác nhau thì trước hết hãy ngồi lại bàn tính đã."}],"related":[{"hanzi":"总计","pinyin":"zǒngjì","vi":"tổng cộng"},{"hanzi":"共计","pinyin":"gòngjì","vi":"cộng lại"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"},{"hanzi":"商量","pinyin":"shāngliang","vi":"bàn bạc"}],"traditional":"合計"},{"id":"合情合理","hanzi":"合情合理","pinyin":"héqíng-hélǐ","meaning_vi":"hợp tình hợp lý, thấu tình đạt lý","explanation":"Nghĩa đen: hợp với tình cảm (情 tình) và hợp với lẽ phải (理 lý) → cách làm vừa thấu tình vừa đạt lý, ai cũng chấp nhận được.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"这个要求合情合理。","pinyin":"Zhè ge yāoqiú héqínghélǐ.","vi":"Yêu cầu này hợp tình hợp lý."},{"type":"simple","zh":"法官作出了一个合情合理的判决。","pinyin":"Fǎguān zuòchūle yí ge héqínghélǐ de pànjué.","vi":"Thẩm phán đã đưa ra một phán quyết thấu tình đạt lý."},{"type":"compound","zh":"只要你的理由合情合理，老板就会同意请假。","pinyin":"Zhǐyào nǐ de lǐyóu héqínghélǐ, lǎobǎn jiù huì tóngyì qǐngjià.","vi":"Chỉ cần lý do của bạn hợp tình hợp lý, sếp sẽ đồng ý cho nghỉ phép."}],"related":[{"hanzi":"合理","pinyin":"hélǐ","vi":"hợp lý"},{"hanzi":"通情达理","pinyin":"tōngqíngdálǐ","vi":"thấu tình đạt lý"},{"hanzi":"无理取闹","pinyin":"wúlǐqǔnào","vi":"gây sự vô lý"},{"hanzi":"合乎","pinyin":"héhū","vi":"phù hợp với"}]},{"id":"何处","hanzi":"何处","pinyin":"héchù","meaning_vi":"nơi nào, chỗ nào, đâu","explanation":"何 (hà – gì, nào) + 处 (xứ – nơi chốn) → nơi nào; cách nói văn viết của 哪里.","hsk_level":"7-9","tags":["dai-tu","dia-diem"],"image":"❓","examples":[{"type":"basic","zh":"你来自何处？","pinyin":"Nǐ láizì héchù?","vi":"Bạn đến từ đâu?"},{"type":"simple","zh":"没有人知道他现在身在何处。","pinyin":"Méiyǒu rén zhīdào tā xiànzài shēn zài héchù.","vi":"Không ai biết hiện giờ anh ấy đang ở đâu."},{"type":"compound","zh":"无论你走到何处，都不要忘了自己的家乡。","pinyin":"Wúlùn nǐ zǒu dào héchù, dōu bú yào wàngle zìjǐ de jiāxiāng.","vi":"Dù bạn đi tới đâu cũng đừng quên quê hương mình."}],"related":[{"hanzi":"哪里","pinyin":"nǎlǐ","vi":"ở đâu"},{"hanzi":"何时","pinyin":"héshí","vi":"khi nào"},{"hanzi":"何人","pinyin":"hérén","vi":"người nào"},{"hanzi":"此处","pinyin":"cǐchù","vi":"nơi này"}],"traditional":"何處"},{"id":"何苦","hanzi":"何苦","pinyin":"hékǔ","meaning_vi":"hà tất, cần gì phải (khổ thế)","explanation":"何 (hà – sao) + 苦 (khổ – chịu khổ) → hà tất phải tự chuốc khổ; dùng trong câu hỏi tu từ để khuyên không nên làm.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"你这又是何苦呢？","pinyin":"Nǐ zhè yòu shì hékǔ ne?","vi":"Bạn làm vậy để làm gì chứ?"},{"type":"simple","zh":"为这点小事生气，何苦呢？","pinyin":"Wèi zhè diǎn xiǎoshì shēngqì, hékǔ ne?","vi":"Giận vì chuyện nhỏ này, cần gì chứ?"},{"type":"compound","zh":"既然他不领情，你又何苦一次次去帮他？","pinyin":"Jìrán tā bù lǐngqíng, nǐ yòu hékǔ yí cì cì qù bāng tā?","vi":"Đã anh ta không biết ơn thì bạn hà tất phải hết lần này đến lần khác giúp anh ta?"}],"related":[{"hanzi":"何必","pinyin":"hébì","vi":"hà tất"},{"hanzi":"犯不着","pinyin":"fànbuzháo","vi":"không đáng"},{"hanzi":"不必","pinyin":"búbì","vi":"không cần"},{"hanzi":"自讨苦吃","pinyin":"zìtǎokǔchī","vi":"tự chuốc khổ"}]},{"id":"何时","hanzi":"何时","pinyin":"héshí","meaning_vi":"khi nào, lúc nào","explanation":"何 (hà – nào) + 时 (thời – lúc) → lúc nào; cách nói văn viết của 什么时候.","hsk_level":"7-9","tags":["dai-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"你何时出发？","pinyin":"Nǐ héshí chūfā?","vi":"Bạn khi nào xuất phát?"},{"type":"simple","zh":"这场雨不知何时才会停。","pinyin":"Zhè chǎng yǔ bùzhī héshí cái huì tíng.","vi":"Không biết cơn mưa này bao giờ mới tạnh."},{"type":"compound","zh":"无论何时遇到困难，你都可以给我打电话。","pinyin":"Wúlùn héshí yùdào kùnnan, nǐ dōu kěyǐ gěi wǒ dǎdiànhuà.","vi":"Bất cứ khi nào gặp khó khăn, bạn đều có thể gọi điện cho tôi."}],"related":[{"hanzi":"什么时候","pinyin":"shénmeshíhou","vi":"lúc nào"},{"hanzi":"何处","pinyin":"héchù","vi":"nơi nào"},{"hanzi":"随时","pinyin":"suíshí","vi":"bất cứ lúc nào"},{"hanzi":"何日","pinyin":"hérì","vi":"ngày nào"}],"traditional":"何時"},{"id":"和尚","hanzi":"和尚","pinyin":"héshang","meaning_vi":"hòa thượng, nhà sư","explanation":"和尚 (hòa thượng) → người xuất gia tu hành theo đạo Phật (nam giới), trong khẩu ngữ chỉ nhà sư nói chung.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🧘","examples":[{"type":"basic","zh":"山上有个和尚。","pinyin":"Shān shang yǒu ge héshang.","vi":"Trên núi có một nhà sư."},{"type":"simple","zh":"寺庙里的和尚每天早上五点起床念经。","pinyin":"Sìmiào lǐ de héshang měitiān zǎoshang wǔ diǎn qǐchuáng niànjīng.","vi":"Các nhà sư trong chùa mỗi sáng năm giờ dậy tụng kinh."},{"type":"compound","zh":"虽然这个和尚年纪很小，但是已经能背很多经文了。","pinyin":"Suīrán zhè ge héshang niánjì hěn xiǎo, dànshì yǐjīng néng bèi hěn duō jīngwén le.","vi":"Tuy nhà sư này tuổi còn rất nhỏ nhưng đã thuộc được nhiều kinh văn."}],"related":[{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"尼姑","pinyin":"nígū","vi":"ni cô"},{"hanzi":"出家","pinyin":"chūjiā","vi":"xuất gia"},{"hanzi":"佛教","pinyin":"Fójiào","vi":"Phật giáo"}]},{"id":"河流","hanzi":"河流","pinyin":"héliú","meaning_vi":"sông ngòi, dòng sông","explanation":"河 (hà – sông) + 流 (lưu – dòng chảy) → dòng sông, chỉ sông ngòi nói chung.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"这条河流很长。","pinyin":"Zhè tiáo héliú hěn cháng.","vi":"Dòng sông này rất dài."},{"type":"simple","zh":"工厂的污水严重污染了附近的河流。","pinyin":"Gōngchǎng de wūshuǐ yánzhòng wūrǎnle fùjìn de héliú.","vi":"Nước thải nhà máy đã ô nhiễm nghiêm trọng sông ngòi gần đó."},{"type":"compound","zh":"因为这里河流众多，所以自古以来水运发达。","pinyin":"Yīnwèi zhèlǐ héliú zhòngduō, suǒyǐ zìgǔ yǐlái shuǐyùn fādá.","vi":"Vì nơi đây sông ngòi chằng chịt nên từ xưa giao thông đường thủy đã phát triển."}],"related":[{"hanzi":"江河","pinyin":"jiānghé","vi":"sông ngòi"},{"hanzi":"湖泊","pinyin":"húpō","vi":"hồ"},{"hanzi":"小溪","pinyin":"xiǎoxī","vi":"suối nhỏ"},{"hanzi":"流域","pinyin":"liúyù","vi":"lưu vực"}]},{"id":"核","hanzi":"核","pinyin":"hé","meaning_vi":"hạt (quả); hạt nhân (nguyên tử); kiểm tra, đối chiếu","explanation":"核 (hạch – hạt cứng trong quả) → phần cốt lõi ở giữa; mở rộng là hạt nhân (tế bào, nguyên tử) và kiểm tra đối chiếu (核对).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚛️","examples":[{"type":"basic","zh":"桃子的核很硬。","pinyin":"Táozi de hé hěn yìng.","vi":"Hạt quả đào rất cứng."},{"type":"simple","zh":"这种樱桃个儿大，核却很小。","pinyin":"Zhè zhǒng yīngtao gèr dà, hé què hěn xiǎo.","vi":"Loại anh đào này quả to mà hạt lại rất nhỏ."},{"type":"compound","zh":"虽然核能很清洁，但是核电站的安全必须严格把关。","pinyin":"Suīrán hénéng hěn qīngjié, dànshì hédiànzhàn de ānquán bìxū yángé bǎguān.","vi":"Tuy năng lượng hạt nhân rất sạch nhưng an toàn nhà máy điện hạt nhân phải được kiểm soát nghiêm ngặt."}],"related":[{"hanzi":"核心","pinyin":"héxīn","vi":"cốt lõi"},{"hanzi":"核能","pinyin":"hénéng","vi":"năng lượng hạt nhân"},{"hanzi":"核对","pinyin":"héduì","vi":"đối chiếu"},{"hanzi":"果核","pinyin":"guǒhé","vi":"hạt quả"}]},{"id":"核对","hanzi":"核对","pinyin":"héduì","meaning_vi":"đối chiếu, kiểm tra lại, soát lại","explanation":"核 (hạch – xem xét kỹ) + 对 (đối – so sánh) → so sánh đối chiếu để kiểm tra xem có chính xác không.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔍","examples":[{"type":"basic","zh":"请核对一下信息。","pinyin":"Qǐng héduì yíxià xìnxī.","vi":"Xin hãy kiểm tra lại thông tin."},{"type":"simple","zh":"会计正在核对这个月的账目。","pinyin":"Kuàijì zhèngzài héduì zhè geyuè de zhàngmù.","vi":"Kế toán đang đối chiếu sổ sách tháng này."},{"type":"compound","zh":"签字之前，你最好把合同内容再核对一遍，以免出错。","pinyin":"Qiānzì zhīqián, nǐ zuìhǎo bǎ hétong nèiróng zài héduì yíbiàn, yǐmiǎn chūcuò.","vi":"Trước khi ký, tốt nhất bạn nên soát lại nội dung hợp đồng một lượt để tránh sai sót."}],"related":[{"hanzi":"核实","pinyin":"héshí","vi":"xác minh"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"},{"hanzi":"校对","pinyin":"jiàoduì","vi":"hiệu đính"},{"hanzi":"对账","pinyin":"duìzhàng","vi":"đối chiếu sổ sách"}],"traditional":"核對"},{"id":"核桃","hanzi":"核桃","pinyin":"hétao","meaning_vi":"quả óc chó, hồ đào","explanation":"核 (hạch – hạt cứng) + 桃 (đào) → loại quả có hạt vỏ cứng giống quả đào, nhân ăn được, tức quả óc chó.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🌰","examples":[{"type":"basic","zh":"我爱吃核桃。","pinyin":"Wǒ ài chī hétao.","vi":"Tôi thích ăn quả óc chó."},{"type":"simple","zh":"奶奶说多吃核桃对大脑有好处。","pinyin":"Nǎinai shuō duō chī hétao duì dànǎo yǒu hǎochu.","vi":"Bà nói ăn nhiều quả óc chó tốt cho não."},{"type":"compound","zh":"核桃虽然营养丰富，但是一次不能吃太多。","pinyin":"Hétao suīrán yíngyǎng fēngfù, dànshì yí cì bù néng chī tài duō.","vi":"Quả óc chó tuy giàu dinh dưỡng nhưng không được ăn quá nhiều một lần."}],"related":[{"hanzi":"坚果","pinyin":"jiānguǒ","vi":"quả hạch"},{"hanzi":"花生","pinyin":"huāshēng","vi":"đậu phộng"},{"hanzi":"栗子","pinyin":"lìzi","vi":"hạt dẻ"},{"hanzi":"核桃仁","pinyin":"hétaorén","vi":"nhân óc chó"}]},{"id":"荷花","hanzi":"荷花","pinyin":"héhuā","meaning_vi":"hoa sen","explanation":"荷 (hà – cây sen) + 花 (hoa) → hoa sen, loài hoa nở mùa hè trong ao hồ.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🪷","examples":[{"type":"basic","zh":"荷花开了。","pinyin":"Héhuā kāi le.","vi":"Hoa sen nở rồi."},{"type":"simple","zh":"夏天，湖面上开满了粉红色的荷花。","pinyin":"Xiàtiān, húmiàn shang kāimǎnle fěnhóngsè de héhuā.","vi":"Mùa hè, mặt hồ nở đầy hoa sen hồng."},{"type":"compound","zh":"荷花虽然长在泥里，但是一点也不脏。","pinyin":"Héhuā suīrán zhǎng zài ní lǐ, dànshì yìdiǎn yě bù zāng.","vi":"Hoa sen tuy mọc trong bùn nhưng chẳng hề bẩn chút nào."}],"related":[{"hanzi":"莲花","pinyin":"liánhuā","vi":"hoa sen"},{"hanzi":"荷叶","pinyin":"héyè","vi":"lá sen"},{"hanzi":"莲子","pinyin":"liánzǐ","vi":"hạt sen"},{"hanzi":"池塘","pinyin":"chítáng","vi":"ao"}]},{"id":"贺电","hanzi":"贺电","pinyin":"hèdiàn","meaning_vi":"điện mừng, điện chúc mừng","explanation":"贺 (hạ – chúc mừng) + 电 (điện – điện báo) → bức điện gửi đi để chúc mừng, thường dùng trong ngoại giao.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"📨","examples":[{"type":"basic","zh":"总统发来了贺电。","pinyin":"Zǒngtǒng fā láile hèdiàn.","vi":"Tổng thống đã gửi điện mừng."},{"type":"simple","zh":"国家领导人向奥运冠军发去贺电。","pinyin":"Guójiā lǐngdǎorén xiàng Àoyùn guànjūn fā qù hèdiàn.","vi":"Lãnh đạo nhà nước gửi điện mừng tới nhà vô địch Olympic."},{"type":"compound","zh":"新总统一上任，各国就纷纷发来贺电。","pinyin":"Xīn zǒng tǒngyī shàngrèn, gèguó jiù fēnfēn fā lái hèdiàn.","vi":"Tân tổng thống vừa nhậm chức, các nước liền tới tấp gửi điện mừng."}],"related":[{"hanzi":"贺信","pinyin":"hèxìn","vi":"thư chúc mừng"},{"hanzi":"祝贺","pinyin":"zhùhè","vi":"chúc mừng"},{"hanzi":"贺卡","pinyin":"hèkǎ","vi":"thiệp chúc mừng"},{"hanzi":"电报","pinyin":"diànbào","vi":"điện báo"}],"traditional":"賀電"},{"id":"贺信","hanzi":"贺信","pinyin":"hèxìn","meaning_vi":"thư chúc mừng, thư mừng","explanation":"贺 (hạ – chúc mừng) + 信 (tín – thư) → lá thư gửi để chúc mừng.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"学校收到一封贺信。","pinyin":"Xuéxiào shōudào yì fēng hèxìn.","vi":"Nhà trường nhận được một bức thư chúc mừng."},{"type":"simple","zh":"校长在大会上宣读了校友的贺信。","pinyin":"Xiàozhǎng zài dàhuì shang xuāndúle xiàoyǒu de hèxìn.","vi":"Hiệu trưởng đọc thư chúc mừng của cựu học sinh tại đại hội."},{"type":"compound","zh":"公司成立十周年时，许多合作伙伴都寄来了贺信。","pinyin":"Gōngsī chénglì shí zhōunián shí, xǔduō hézuò huǒbàn dōu jì láile hèxìn.","vi":"Khi công ty tròn mười năm thành lập, nhiều đối tác đã gửi thư chúc mừng."}],"related":[{"hanzi":"贺电","pinyin":"hèdiàn","vi":"điện mừng"},{"hanzi":"贺词","pinyin":"hècí","vi":"lời chúc mừng"},{"hanzi":"贺卡","pinyin":"hèkǎ","vi":"thiệp mừng"},{"hanzi":"祝贺","pinyin":"zhùhè","vi":"chúc mừng"}],"traditional":"賀信"},{"id":"赫然","hanzi":"赫然","pinyin":"hèrán","meaning_vi":"sừng sững, đột ngột hiện ra; (giận) đùng đùng","explanation":"赫 (hách – rõ rệt, hiển hách) + 然 (nhiên – dáng vẻ) → một cách rõ ràng, đập vào mắt khiến người ta giật mình.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😲","examples":[{"type":"basic","zh":"门上赫然写着“禁止入内”。","pinyin":"Mén shang hèrán xiě zhe \"jìnzhǐ rù nèi\".","vi":"Trên cửa ghi rõ rành rành dòng chữ \"cấm vào\"."},{"type":"simple","zh":"打开盒子，一枚钻戒赫然出现在眼前。","pinyin":"Dǎkāi hézi, yìméi zuànjiè hèrán chū xiànzài yǎnqián.","vi":"Mở hộp ra, một chiếc nhẫn kim cương đột ngột hiện ra trước mắt."},{"type":"compound","zh":"他刚翻开名单，就看到自己的名字赫然在列。","pinyin":"Tā gāng fānkāi míngdān, jiù kàndào zìjǐ de míngzi hèrán zài liè.","vi":"Anh ấy vừa mở danh sách đã thấy tên mình nằm rõ rành rành trong đó."}],"related":[{"hanzi":"显然","pinyin":"xiǎnrán","vi":"rõ ràng"},{"hanzi":"突然","pinyin":"tūrán","vi":"đột nhiên"},{"hanzi":"显赫","pinyin":"xiǎnhè","vi":"hiển hách"},{"hanzi":"醒目","pinyin":"xǐngmù","vi":"nổi bật"}]},{"id":"黑白","hanzi":"黑白","pinyin":"hēibái","meaning_vi":"đen trắng; phải trái, đúng sai","explanation":"黑 (hắc – đen) + 白 (bạch – trắng) → màu đen và trắng; nghĩa bóng là phải trái, đúng sai.","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🎞️","examples":[{"type":"basic","zh":"这是黑白照片。","pinyin":"Zhè shì hēibái zhàopiàn.","vi":"Đây là ảnh đen trắng."},{"type":"simple","zh":"小时候我家只有一台黑白电视。","pinyin":"Xiǎoshíhou wǒ jiā zhǐyǒu yì tái hēibái diànshì.","vi":"Hồi nhỏ nhà tôi chỉ có một chiếc tivi đen trắng."},{"type":"compound","zh":"有些人为了利益颠倒黑白，所以我们要学会独立判断。","pinyin":"Yǒuxiērén wèile lìyì diāndǎohēibái, suǒyǐ wǒmen yào xuéhuì dúlì pànduàn.","vi":"Có người vì lợi ích mà đổi trắng thay đen, nên chúng ta phải học cách tự phán đoán."}],"related":[{"hanzi":"彩色","pinyin":"cǎisè","vi":"màu sắc"},{"hanzi":"是非","pinyin":"shìfēi","vi":"phải trái"},{"hanzi":"颠倒黑白","pinyin":"diāndǎohēibái","vi":"đổi trắng thay đen"},{"hanzi":"黑白分明","pinyin":"hēibáifēnmíng","vi":"trắng đen rõ ràng"}]},{"id":"黑手","hanzi":"黑手","pinyin":"hēishǒu","meaning_vi":"bàn tay đen, kẻ giật dây sau màn","explanation":"黑 (hắc – đen, mờ ám) + 手 (thủ – bàn tay) → bàn tay đen tối thao túng từ phía sau; chỉ thế lực giật dây.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🕵️","examples":[{"type":"basic","zh":"谁是幕后黑手？","pinyin":"Shéi shì mùhòu hēishǒu?","vi":"Ai là kẻ giật dây sau màn?"},{"type":"simple","zh":"警方终于查出了这起诈骗案的幕后黑手。","pinyin":"Jǐngfāng zhōngyú cháchūle zhè qǐ zhàpiàn àn de mùhòu hēishǒu.","vi":"Cảnh sát cuối cùng đã tìm ra kẻ giật dây vụ lừa đảo này."},{"type":"compound","zh":"即使黑手藏得再深，也总有被揪出来的一天。","pinyin":"Jíshǐ hēishǒu cáng de zài shēn, yě zǒngyǒu bèi jiū chūlai de yì tiān.","vi":"Dù bàn tay đen giấu kỹ đến đâu, cũng có ngày bị lôi ra ánh sáng."}],"related":[{"hanzi":"幕后","pinyin":"mùhòu","vi":"hậu trường"},{"hanzi":"操纵","pinyin":"cāozòng","vi":"thao túng"},{"hanzi":"主谋","pinyin":"zhǔmóu","vi":"kẻ chủ mưu"},{"hanzi":"黑心","pinyin":"hēixīn","vi":"lòng dạ đen tối"}]},{"id":"黑心","hanzi":"黑心","pinyin":"hēixīn","meaning_vi":"lòng dạ đen tối, bất lương, thất đức","explanation":"黑 (hắc – đen) + 心 (tâm – lòng) → lòng dạ đen tối, hám lợi không có lương tâm; hay dùng trong 黑心商家, 黑心钱.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🖤","examples":[{"type":"basic","zh":"这老板真黑心！","pinyin":"Zhè lǎobǎn zhēn hēixīn!","vi":"Ông chủ này thật thất đức!"},{"type":"simple","zh":"这些黑心商家在食品里乱加添加剂。","pinyin":"Zhèxiē hēixīn shāngjiā zài shípǐn lǐ luàn jiā tiānjiājì.","vi":"Những thương gia bất lương này cho bừa chất phụ gia vào thực phẩm."},{"type":"compound","zh":"虽然赚黑心钱来得快，但是早晚会受到法律惩罚。","pinyin":"Suīrán zhuàn hēixīn qián láide kuài, dànshì zǎo wǎnhuì shòudào fǎlǜ chéngfá.","vi":"Tuy kiếm tiền thất đức thì đến nhanh nhưng sớm muộn cũng bị pháp luật trừng phạt."}],"related":[{"hanzi":"良心","pinyin":"liángxīn","vi":"lương tâm"},{"hanzi":"狠心","pinyin":"hěnxīn","vi":"nhẫn tâm"},{"hanzi":"奸商","pinyin":"jiānshāng","vi":"gian thương"},{"hanzi":"好心","pinyin":"hǎoxīn","vi":"lòng tốt"}]},{"id":"横七竖八","hanzi":"横七竖八","pinyin":"héngqī-shùbā","meaning_vi":"ngổn ngang, bừa bộn, lộn xộn","explanation":"Nghĩa đen: bảy cái nằm ngang, tám cái dựng dọc → đồ vật hoặc người nằm ngổn ngang, lộn xộn không có trật tự.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧦","examples":[{"type":"basic","zh":"地上横七竖八的。","pinyin":"Dìshang héngqīshùbā de.","vi":"Dưới đất ngổn ngang bừa bộn."},{"type":"simple","zh":"教室里的椅子横七竖八地倒在地上。","pinyin":"Jiàoshì lǐ de yǐzi héngqīshùbā de dǎo zài dìshang.","vi":"Ghế trong lớp đổ ngổn ngang dưới đất."},{"type":"compound","zh":"聚会一结束，客厅里就横七竖八地堆满了空瓶子。","pinyin":"Jùhuì yì jiéshù, kètīng lǐ jiù héngqīshùbā de duīmǎnle kōng píngzi.","vi":"Buổi tiệc vừa kết thúc, phòng khách đã chất đầy chai rỗng ngổn ngang."}],"related":[{"hanzi":"乱七八糟","pinyin":"luànqībāzāo","vi":"lộn xộn"},{"hanzi":"杂乱无章","pinyin":"záluànwúzhāng","vi":"lộn xộn không trật tự"},{"hanzi":"井井有条","pinyin":"jǐngjǐngyǒutiáo","vi":"ngăn nắp gọn gàng"},{"hanzi":"东倒西歪","pinyin":"dōngdǎoxīwāi","vi":"xiêu vẹo nghiêng ngả"}],"traditional":"橫七豎八"},{"id":"横向","hanzi":"横向","pinyin":"héngxiàng","meaning_vi":"hàng ngang, theo chiều ngang, ngang cấp","explanation":"横 (hoành – ngang) + 向 (hướng – phương hướng) → theo chiều ngang; nghĩa mở rộng là giữa các bên ngang cấp (横向合作, 横向比较).","hsk_level":"7-9","tags":["tinh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"请横向排列。","pinyin":"Qǐng héngxiàng páiliè.","vi":"Xin hãy xếp theo hàng ngang."},{"type":"simple","zh":"我们需要加强部门之间的横向合作。","pinyin":"Wǒmen xūyào jiāqiáng bùmén zhījiān de héngxiàng hézuò.","vi":"Chúng ta cần tăng cường hợp tác ngang giữa các phòng ban."},{"type":"compound","zh":"如果只做横向比较，就看不出自己这些年的进步。","pinyin":"Rúguǒ zhǐ zuò héngxiàng bǐjiào, jiù kànbuchū zìjǐ zhèxiē nián de jìnbù.","vi":"Nếu chỉ so sánh ngang với người khác thì không thấy được tiến bộ của mình mấy năm qua."}],"related":[{"hanzi":"纵向","pinyin":"zòngxiàng","vi":"theo chiều dọc"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"nằm ngang"},{"hanzi":"横","pinyin":"héng","vi":"ngang"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"}],"traditional":"橫向"},{"id":"轰","hanzi":"轰","pinyin":"hōng","meaning_vi":"đùng, ầm (tiếng nổ); nổ, bắn phá; đuổi đi","explanation":"轰 (oanh – tiếng nổ lớn, ầm ầm) → tiếng nổ vang; làm động từ chỉ nổ phá, bắn phá hoặc xua đuổi.","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"他把狗轰走了。","pinyin":"Tā bǎ gǒu hōngzǒu le.","vi":"Anh ấy đuổi con chó đi rồi."},{"type":"simple","zh":"只听“轰”的一声，旧楼被炸倒了。","pinyin":"Zhǐ tīng \"hōng\" de yìshēng, jiù lóu bèi zhà dǎo le.","vi":"Chỉ nghe \"ầm\" một tiếng, tòa nhà cũ đã bị phá sập."},{"type":"compound","zh":"他一进门就大吵大闹，结果被保安轰了出去。","pinyin":"Tā yí jìnmén jiù dà chǎo dànào, jiéguǒ bèi bǎo'ān hōngle chūqu.","vi":"Anh ta vừa vào cửa đã làm ầm ĩ, kết quả bị bảo vệ đuổi ra ngoài."}],"related":[{"hanzi":"轰炸","pinyin":"hōngzhà","vi":"oanh tạc"},{"hanzi":"轰动","pinyin":"hōngdòng","vi":"chấn động"},{"hanzi":"轰隆","pinyin":"hōnglōng","vi":"ầm ầm"},{"hanzi":"赶走","pinyin":"gǎnzǒu","vi":"đuổi đi"}],"traditional":"轟"},{"id":"轰炸","hanzi":"轰炸","pinyin":"hōngzhà","meaning_vi":"ném bom, oanh tạc, dội bom","explanation":"轰 (oanh – nổ ầm) + 炸 (tạc – nổ) → dùng bom đạn tấn công dữ dội; nghĩa bóng là dồn dập tấn công (轰炸式广告).","hsk_level":"7-9","tags":["dong-tu"],"image":"✈️","examples":[{"type":"basic","zh":"敌机轰炸了桥梁。","pinyin":"Díjī hōngzhàle qiáoliáng.","vi":"Máy bay địch đã ném bom cây cầu."},{"type":"simple","zh":"这座城市在二战中多次遭到轰炸。","pinyin":"Zhè zuò chéngshì zài Èrzhàn zhōng duōcì zāodào hōngzhà.","vi":"Thành phố này nhiều lần bị oanh tạc trong Thế chiến thứ hai."},{"type":"compound","zh":"虽然天天被广告轰炸，但是我很少真的去买。","pinyin":"Suīrán tiāntiān bèi guǎnggào hōngzhà, dànshì wǒ hěn shǎo zhēn de qù mǎi.","vi":"Tuy ngày nào cũng bị quảng cáo dội bom nhưng tôi hiếm khi thực sự đi mua."}],"related":[{"hanzi":"轰","pinyin":"hōng","vi":"nổ, bắn phá"},{"hanzi":"爆炸","pinyin":"bàozhà","vi":"nổ"},{"hanzi":"空袭","pinyin":"kōngxí","vi":"không kích"},{"hanzi":"炮轰","pinyin":"pàohōng","vi":"pháo kích"}],"traditional":"轟炸"},{"id":"烘干","hanzi":"烘干","pinyin":"hōnggān","meaning_vi":"sấy khô, hong khô","explanation":"烘 (hồng – hơ, sấy bằng lửa) + 干 (can – khô) → dùng nhiệt sấy cho khô.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🌀","examples":[{"type":"basic","zh":"衣服烘干了。","pinyin":"Yīfu hōnggān le.","vi":"Quần áo đã sấy khô rồi."},{"type":"simple","zh":"下雨天可以用烘干机烘干衣服。","pinyin":"Xià yǔtiān kěyǐ yòng hōnggānjī hōnggān yīfu.","vi":"Ngày mưa có thể dùng máy sấy để sấy khô quần áo."},{"type":"compound","zh":"因为这件毛衣不能烘干，所以只能挂在阴凉处晾。","pinyin":"Yīnwèi zhè jiàn máoyī bù néng hōnggān, suǒyǐ zhǐnéng guà zài yīnliángchù liàng.","vi":"Vì chiếc áo len này không được sấy nên chỉ có thể treo hong ở chỗ râm mát."}],"related":[{"hanzi":"晒干","pinyin":"shàigān","vi":"phơi khô"},{"hanzi":"晾干","pinyin":"liànggān","vi":"hong khô"},{"hanzi":"烘干机","pinyin":"hōnggānjī","vi":"máy sấy"},{"hanzi":"吹干","pinyin":"chuīgān","vi":"thổi khô"}],"traditional":"烘乾"},{"id":"红灯","hanzi":"红灯","pinyin":"hóngdēng","meaning_vi":"đèn đỏ","explanation":"红 (hồng – đỏ) + 灯 (đăng – đèn) → đèn màu đỏ, nhất là đèn giao thông báo dừng; nghĩa bóng là tín hiệu cấm, cảnh báo.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"前面是红灯。","pinyin":"Qiánmiàn shì hóngdēng.","vi":"Phía trước là đèn đỏ."},{"type":"simple","zh":"他因为闯红灯被罚了两百块。","pinyin":"Tā yīnwèi chuǎnghóngdēng bèi fále liǎng bǎi kuài.","vi":"Anh ấy bị phạt hai trăm tệ vì vượt đèn đỏ."},{"type":"compound","zh":"即使路上没车，遇到红灯也要停下来。","pinyin":"Jíshǐ lùshang méi chē, yùdào hóngdēng yě yào tíngxiàlai.","vi":"Dù trên đường không có xe, gặp đèn đỏ cũng phải dừng lại."}],"related":[{"hanzi":"绿灯","pinyin":"lǜdēng","vi":"đèn xanh"},{"hanzi":"黄灯","pinyin":"huángdēng","vi":"đèn vàng"},{"hanzi":"闯红灯","pinyin":"chuǎnghóngdēng","vi":"vượt đèn đỏ"},{"hanzi":"红绿灯","pinyin":"hónglǜdēng","vi":"đèn giao thông"}],"traditional":"紅燈"},{"id":"红扑扑","hanzi":"红扑扑","pinyin":"hóngpūpū","meaning_vi":"đỏ hây hây, đỏ ửng, hồng hào","explanation":"红 (hồng – đỏ) + 扑扑 (từ láy gợi tả) → (mặt) đỏ hồng, ửng đỏ một cách tươi tắn.","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"☺️","examples":[{"type":"basic","zh":"她的脸红扑扑的。","pinyin":"Tā de liǎn hóngpūpū de.","vi":"Mặt cô ấy đỏ hây hây."},{"type":"simple","zh":"孩子们在雪地里玩得小脸红扑扑的。","pinyin":"Háizimen zài xuědì lǐ wán de xiǎo liǎn hóngpūpū de.","vi":"Bọn trẻ chơi trên tuyết đến khuôn mặt nhỏ đỏ ửng."},{"type":"compound","zh":"她刚跑完步回来，所以脸蛋红扑扑的。","pinyin":"Tā gāng pǎo wán bù huílai, suǒyǐ liǎndàn hóngpūpū de.","vi":"Cô ấy vừa chạy bộ về nên má đỏ hồng."}],"related":[{"hanzi":"红润","pinyin":"hóngrùn","vi":"hồng hào"},{"hanzi":"红彤彤","pinyin":"hóngtóngtóng","vi":"đỏ rực"},{"hanzi":"脸红","pinyin":"liǎnhóng","vi":"đỏ mặt"},{"hanzi":"苍白","pinyin":"cāngbái","vi":"xanh xao"}],"traditional":"紅撲撲"},{"id":"红薯","hanzi":"红薯","pinyin":"hóngshǔ","meaning_vi":"khoai lang","explanation":"红 (hồng – đỏ) + 薯 (thự – củ khoai) → khoai có vỏ đỏ, tức khoai lang.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍠","examples":[{"type":"basic","zh":"烤红薯真香。","pinyin":"Kǎohóngshǔ zhēn xiāng.","vi":"Khoai lang nướng thơm thật."},{"type":"simple","zh":"冬天街头常有人卖热乎乎的烤红薯。","pinyin":"Dōngtiān jiētóu cháng yǒurén mài rèhūhū de kǎohóngshǔ.","vi":"Mùa đông đầu phố thường có người bán khoai lang nướng nóng hổi."},{"type":"compound","zh":"红薯虽然便宜，但是营养价值很高。","pinyin":"Hóngshǔ suīrán piányi, dànshì yíngyǎngjiàzhí hěn gāo.","vi":"Khoai lang tuy rẻ nhưng giá trị dinh dưỡng rất cao."}],"related":[{"hanzi":"地瓜","pinyin":"dìguā","vi":"khoai lang"},{"hanzi":"土豆","pinyin":"tǔdòu","vi":"khoai tây"},{"hanzi":"山药","pinyin":"shānyao","vi":"củ mài"},{"hanzi":"烤红薯","pinyin":"kǎohóngshǔ","vi":"khoai lang nướng"}],"traditional":"紅薯"},{"id":"红眼","hanzi":"红眼","pinyin":"hóngyǎn","meaning_vi":"đỏ mắt (ghen tị); nổi giận; đau mắt đỏ","explanation":"红 (hồng – đỏ) + 眼 (nhãn – mắt) → mắt đỏ lên; nghĩa bóng là ghen tức (眼红) hoặc nổi giận đến đỏ mắt.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"他一着急就红眼。","pinyin":"Tā yì zháojí jiù hóngyǎn.","vi":"Anh ấy hễ sốt ruột là nổi nóng đỏ mắt."},{"type":"simple","zh":"看到别人发财，他就红眼了。","pinyin":"Kàndào biérén fācái, tā jiù hóngyǎn le.","vi":"Thấy người khác phát tài là anh ta đỏ mắt ghen tị."},{"type":"compound","zh":"虽然输了比赛，但是队员们没有红眼，而是平静地接受了结果。","pinyin":"Suīrán shūle bǐsài, dànshì duìyuánmen méiyǒu hóngyǎn, érshì píngjìng de jiēshòule jiéguǒ.","vi":"Tuy thua trận nhưng các cầu thủ không nổi nóng mà bình tĩnh chấp nhận kết quả."}],"related":[{"hanzi":"眼红","pinyin":"yǎnhóng","vi":"ghen tị"},{"hanzi":"嫉妒","pinyin":"jídù","vi":"đố kỵ"},{"hanzi":"红眼病","pinyin":"hóngyǎnbìng","vi":"bệnh đau mắt đỏ"},{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"}],"traditional":"紅眼"},{"id":"后备箱","hanzi":"后备箱","pinyin":"hòubèixiāng","meaning_vi":"cốp xe (ô tô)","explanation":"后 (hậu – phía sau) + 备 (bị – dự phòng) + 箱 (tương – thùng) → thùng chứa đồ ở đuôi xe ô tô.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"行李放后备箱。","pinyin":"Xíngli fàng hòubèixiāng.","vi":"Hành lý để trong cốp xe."},{"type":"simple","zh":"他打开后备箱，拿出一把雨伞。","pinyin":"Tā dǎkāi hòubèixiāng, náchū yì bǎ yǔsǎn.","vi":"Anh ấy mở cốp xe lấy ra một chiếc ô."},{"type":"compound","zh":"因为后备箱太小，所以只好把箱子放在后座上。","pinyin":"Yīnwèi hòubèixiāng tài xiǎo, suǒyǐ zhǐhǎo bǎ xiāngzi fàng zài hòuzuò shang.","vi":"Vì cốp xe quá nhỏ nên đành để vali ở ghế sau."}],"related":[{"hanzi":"汽车","pinyin":"qìchē","vi":"ô tô"},{"hanzi":"后座","pinyin":"hòuzuò","vi":"ghế sau"},{"hanzi":"行李","pinyin":"xíngli","vi":"hành lý"},{"hanzi":"备胎","pinyin":"bèitāi","vi":"lốp dự phòng"}],"traditional":"後備箱"},{"id":"后期","hanzi":"后期","pinyin":"hòuqī","meaning_vi":"giai đoạn sau, thời kỳ cuối, hậu kỳ","explanation":"后 (hậu – sau) + 期 (kỳ – thời kỳ) → giai đoạn sau cùng của một quá trình; trong điện ảnh còn chỉ khâu hậu kỳ.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"工程到了后期。","pinyin":"Gōngchéng dàole hòuqī.","vi":"Công trình đã bước vào giai đoạn cuối."},{"type":"simple","zh":"这部电影的后期制作花了半年时间。","pinyin":"Zhè bù diànyǐng de hòuqī zhìzuò huāle bàn nián shíjiān.","vi":"Phần hậu kỳ của bộ phim này mất nửa năm."},{"type":"compound","zh":"如果前期准备不充分，后期就会出现很多问题。","pinyin":"Rúguǒ qiánqī zhǔnbèi bù chōngfèn, hòuqī jiù huì chūxiàn hěn duō wèntí.","vi":"Nếu khâu chuẩn bị ban đầu không đầy đủ thì giai đoạn sau sẽ phát sinh nhiều vấn đề."}],"related":[{"hanzi":"前期","pinyin":"qiánqī","vi":"giai đoạn đầu"},{"hanzi":"中期","pinyin":"zhōngqī","vi":"giai đoạn giữa"},{"hanzi":"晚期","pinyin":"wǎnqī","vi":"thời kỳ cuối"},{"hanzi":"末期","pinyin":"mòqī","vi":"cuối kỳ"}],"traditional":"後期"},{"id":"后人","hanzi":"后人","pinyin":"hòurén","meaning_vi":"đời sau, hậu thế, con cháu","explanation":"后 (hậu – sau) + 人 (nhân – người) → những người của thế hệ sau; cũng chỉ con cháu đời sau.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👨‍👩‍👧","examples":[{"type":"basic","zh":"前人种树，后人乘凉。","pinyin":"Qiánrén zhòngshù, hòurén chéngliáng.","vi":"Đời trước trồng cây, đời sau hưởng bóng mát."},{"type":"simple","zh":"他的著作对后人影响很大。","pinyin":"Tā de zhù zuòduì hòurén yǐngxiǎng hěn dà.","vi":"Trước tác của ông có ảnh hưởng rất lớn tới hậu thế."},{"type":"compound","zh":"只有保护好这些古迹，后人才能看到历史的原貌。","pinyin":"Zhǐyǒu bǎohù hǎo zhèxiē gǔjì, hòurén cáinéng kàndào lìshǐ de yuánmào.","vi":"Chỉ có bảo vệ tốt những di tích này, đời sau mới có thể thấy được diện mạo lịch sử ban đầu."}],"related":[{"hanzi":"前人","pinyin":"qiánrén","vi":"người đời trước"},{"hanzi":"后代","pinyin":"hòudài","vi":"đời sau"},{"hanzi":"子孙","pinyin":"zǐsūn","vi":"con cháu"},{"hanzi":"后世","pinyin":"hòushì","vi":"hậu thế"}],"traditional":"後人"},{"id":"后台","hanzi":"后台","pinyin":"hòutái","meaning_vi":"hậu trường; chỗ dựa, ô dù; nền (máy tính)","explanation":"后 (hậu – sau) + 台 (đài – sân khấu) → phía sau sân khấu; nghĩa bóng là thế lực chống lưng; trong tin học là chạy nền, phần quản trị (back-end).","hsk_level":"7-9","tags":["danh-tu"],"image":"🎭","examples":[{"type":"basic","zh":"演员在后台化妆。","pinyin":"Yǎnyuán zài hòutái huàzhuāng.","vi":"Diễn viên đang trang điểm ở hậu trường."},{"type":"simple","zh":"这个程序会一直在后台运行。","pinyin":"Zhè ge chéngxù huì yìzhí zài hòutái yùnxíng.","vi":"Chương trình này sẽ luôn chạy ngầm."},{"type":"compound","zh":"他之所以这么嚣张，是因为有个很硬的后台。","pinyin":"Tā zhīsuǒyǐ zhème xiāozhāng, shì yīnwèi yǒu ge hěn yìng de hòutái.","vi":"Sở dĩ hắn ngang ngược như vậy là vì có ô dù rất vững."}],"related":[{"hanzi":"前台","pinyin":"qiántái","vi":"quầy lễ tân, sân khấu trước"},{"hanzi":"幕后","pinyin":"mùhòu","vi":"hậu trường"},{"hanzi":"靠山","pinyin":"kàoshān","vi":"chỗ dựa"},{"hanzi":"舞台","pinyin":"wǔtái","vi":"sân khấu"}],"traditional":"後臺"},{"id":"后退","hanzi":"后退","pinyin":"hòutuì","meaning_vi":"lùi lại, rút lui, thụt lùi","explanation":"后 (hậu – phía sau) + 退 (thoái – lui) → lùi về phía sau; nghĩa bóng là thụt lùi, kém đi.","hsk_level":"7-9","tags":["dong-tu"],"image":"⬅️","examples":[{"type":"basic","zh":"请往后退一步。","pinyin":"Qǐng wǎng hòutuì yí bù.","vi":"Xin lùi lại một bước."},{"type":"simple","zh":"看到那条大狗，孩子吓得连连后退。","pinyin":"Kàndào nà tiáo dà gǒu, háizi xià de liánlián hòutuì.","vi":"Thấy con chó to, đứa trẻ sợ hãi lùi liên tục."},{"type":"compound","zh":"学习如逆水行舟，不进则退，一旦放松就会后退。","pinyin":"Xuéxí rú nìshuǐxíngzhōu, bú jìn zé tuì, yídàn fàngsōng jiù huì hòutuì.","vi":"Học như thuyền ngược nước, không tiến ắt lùi, một khi lơi lỏng sẽ thụt lùi."}],"related":[{"hanzi":"前进","pinyin":"qiánjìn","vi":"tiến lên"},{"hanzi":"退步","pinyin":"tuìbù","vi":"thụt lùi"},{"hanzi":"撤退","pinyin":"chètuì","vi":"rút lui"},{"hanzi":"倒退","pinyin":"dàotuì","vi":"lùi lại"}],"traditional":"後退"},{"id":"后续","hanzi":"后续","pinyin":"hòuxù","meaning_vi":"tiếp theo, tiếp nối, về sau","explanation":"后 (hậu – sau) + 续 (tục – nối tiếp) → phần nối tiếp phía sau (后续工作, 后续报道).","hsk_level":"7-9","tags":["tinh-tu"],"image":"➡️","examples":[{"type":"basic","zh":"后续消息还没来。","pinyin":"Hòuxù xiāoxi hái méi lái.","vi":"Tin tức tiếp theo vẫn chưa có."},{"type":"simple","zh":"我们会继续关注此事的后续发展。","pinyin":"Wǒmen huì jìxù guānzhù cǐshì de hòuxù fāzhǎn.","vi":"Chúng tôi sẽ tiếp tục theo dõi diễn biến tiếp theo của sự việc."},{"type":"compound","zh":"合同签好以后，后续的工作就交给小李负责。","pinyin":"Hétong qiān hǎo yǐhòu, hòuxù de gōngzuò jiù jiāogěi xiǎo Lǐ fùzé.","vi":"Sau khi ký hợp đồng xong, công việc tiếp theo giao cho Tiểu Lý phụ trách."}],"related":[{"hanzi":"继续","pinyin":"jìxù","vi":"tiếp tục"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"后来","pinyin":"hòulái","vi":"sau này"},{"hanzi":"跟进","pinyin":"gēnjìn","vi":"theo sát"}],"traditional":"後續"},{"id":"后者","hanzi":"后者","pinyin":"hòuzhě","meaning_vi":"cái sau, người sau, cái thứ hai (trong hai)","explanation":"后 (hậu – sau) + 者 (giả – người, cái) → cái/người được nhắc đến sau trong hai thứ, đối lập với 前者.","hsk_level":"7-9","tags":["dai-tu"],"image":"2️⃣","examples":[{"type":"basic","zh":"我选后者。","pinyin":"Wǒ xuǎn hòuzhě.","vi":"Tôi chọn cái sau."},{"type":"simple","zh":"比起名气和金钱，他更看重后者。","pinyin":"Bǐqǐ míngqì hé jīnqián, tā gèng kànzhòng hòuzhě.","vi":"Giữa danh tiếng và tiền bạc, anh ấy coi trọng cái sau hơn."},{"type":"compound","zh":"前者价格便宜，但是后者质量更好。","pinyin":"Qiánzhě jiàgé piányi, dànshì hòuzhě zhìliàng gèng hǎo.","vi":"Cái trước giá rẻ, nhưng cái sau chất lượng tốt hơn."}],"related":[{"hanzi":"前者","pinyin":"qiánzhě","vi":"cái trước"},{"hanzi":"两者","pinyin":"liǎngzhě","vi":"cả hai"},{"hanzi":"后面","pinyin":"hòumiàn","vi":"phía sau"},{"hanzi":"或者","pinyin":"huòzhě","vi":"hoặc"}],"traditional":"後者"},{"id":"厚道","hanzi":"厚道","pinyin":"hòudao","meaning_vi":"thật thà, phúc hậu, tử tế","explanation":"厚 (hậu – dày, đôn hậu) + 道 (đạo – đạo đức) → đối xử với người khác thật thà, rộng lượng, không khắt khe.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🙂","examples":[{"type":"basic","zh":"他为人很厚道。","pinyin":"Tā wéirén hěn hòudao.","vi":"Anh ấy sống rất phúc hậu."},{"type":"simple","zh":"这样占朋友便宜，可不太厚道。","pinyin":"Zhèyàng zhàn péngyou piányi, kěbú tài hòudao.","vi":"Lợi dụng bạn bè như vậy thì không được tử tế lắm."},{"type":"compound","zh":"老张虽然话不多，但是做人厚道，大家都愿意和他合作。","pinyin":"Lǎo Zhāng suīrán huà bù duō, dànshì zuòrén hòudao, dàjiā dōu yuànyì hé tā hézuò.","vi":"Lão Trương tuy ít nói nhưng sống phúc hậu, mọi người đều muốn hợp tác với ông."}],"related":[{"hanzi":"忠厚","pinyin":"zhōnghòu","vi":"trung hậu"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"刻薄","pinyin":"kèbó","vi":"cay nghiệt"}]},{"id":"厚度","hanzi":"厚度","pinyin":"hòudù","meaning_vi":"độ dày, bề dày","explanation":"厚 (hậu – dày) + 度 (độ – mức độ) → mức độ dày của vật thể.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📏","examples":[{"type":"basic","zh":"这块木板的厚度够吗？","pinyin":"Zhè kuài mùbǎn de hòudù gòu ma?","vi":"Tấm ván này đủ độ dày không?"},{"type":"simple","zh":"这款手机的厚度只有七毫米。","pinyin":"Zhè kuǎn shǒujī de hòudù zhǐyǒu qī háomǐ.","vi":"Độ dày của mẫu điện thoại này chỉ có bảy mi-li-mét."},{"type":"compound","zh":"虽然冰面看起来很结实，但是厚度还不到十厘米。","pinyin":"Suīrán bīng miàn kànqilai hěn jiēshi, dànshì hòudù hái búdào shí límǐ.","vi":"Tuy mặt băng trông rất chắc nhưng độ dày còn chưa tới mười xăng-ti-mét."}],"related":[{"hanzi":"长度","pinyin":"chángdù","vi":"chiều dài"},{"hanzi":"宽度","pinyin":"kuāndù","vi":"chiều rộng"},{"hanzi":"高度","pinyin":"gāodù","vi":"chiều cao"},{"hanzi":"深度","pinyin":"shēndù","vi":"độ sâu"}]},{"id":"呼救","hanzi":"呼救","pinyin":"hūjiù","meaning_vi":"kêu cứu, cầu cứu","explanation":"呼 (hô – kêu gọi) + 救 (cứu – cứu giúp) → kêu to xin người khác đến cứu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🆘","examples":[{"type":"basic","zh":"有人在呼救！","pinyin":"Yǒurén zài hūjiù!","vi":"Có người đang kêu cứu!"},{"type":"simple","zh":"落水的男孩拼命挥手呼救。","pinyin":"Luòshuǐ de nánhái pīnmìng huīshǒu hūjiù.","vi":"Cậu bé rơi xuống nước liều mạng vẫy tay kêu cứu."},{"type":"compound","zh":"他一听到楼下的呼救声，就马上冲了下去。","pinyin":"Tā yì tīngdào lóuxià de hūjiù shēng, jiù mǎshàng chōngle xiàqu.","vi":"Anh ấy vừa nghe tiếng kêu cứu dưới lầu liền lao ngay xuống."}],"related":[{"hanzi":"求救","pinyin":"qiújiù","vi":"cầu cứu"},{"hanzi":"救命","pinyin":"jiùmìng","vi":"cứu mạng"},{"hanzi":"求助","pinyin":"qiúzhù","vi":"nhờ giúp đỡ"},{"hanzi":"呼喊","pinyin":"hūhǎn","vi":"hô hoán"}]},{"id":"呼应","hanzi":"呼应","pinyin":"hūyìng","meaning_vi":"hô ứng, ăn khớp với nhau; hưởng ứng, đáp lại","explanation":"呼 (hô – gọi) + 应 (ứng – đáp) → bên này gọi bên kia đáp; chỉ sự ăn khớp, phối hợp với nhau, nhất là trong văn chương.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔁","examples":[{"type":"basic","zh":"首尾互相呼应。","pinyin":"Shǒuwěi hùxiāng hūyìng.","vi":"Đầu và cuối hô ứng với nhau."},{"type":"simple","zh":"文章的结尾和开头巧妙地呼应。","pinyin":"Wénzhāng de jiéwěi hé kāitóu qiǎomiào de hūyìng.","vi":"Phần kết bài văn hô ứng khéo léo với phần mở đầu."},{"type":"compound","zh":"他在台上一提出倡议，台下的同学们就纷纷呼应。","pinyin":"Tā zài tái shang yì tíchū chàngyì, táixià de tóngxuémen jiù fēnfēn hūyìng.","vi":"Cậu ấy vừa nêu lời kêu gọi trên bục, các bạn bên dưới liền đồng loạt hưởng ứng."}],"related":[{"hanzi":"响应","pinyin":"xiǎngyìng","vi":"hưởng ứng"},{"hanzi":"照应","pinyin":"zhàoyìng","vi":"chiếu ứng"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"},{"hanzi":"呼唤","pinyin":"hūhuàn","vi":"kêu gọi"}],"traditional":"呼應"},{"id":"忽高忽低","hanzi":"忽高忽低","pinyin":"hūgāo-hūdī","meaning_vi":"lúc cao lúc thấp, lên xuống thất thường","explanation":"Nghĩa đen: chợt (忽 hốt) cao chợt thấp → lên xuống bất thường, không ổn định.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"📈","examples":[{"type":"basic","zh":"他的成绩忽高忽低。","pinyin":"Tā de chéngjì hūgāohūdī.","vi":"Thành tích của cậu ấy lúc cao lúc thấp."},{"type":"simple","zh":"这几天气温忽高忽低，很容易感冒。","pinyin":"Zhèjǐtiān qìwēn hūgāohūdī, hěn róngyì gǎnmào.","vi":"Mấy hôm nay nhiệt độ lên xuống thất thường, rất dễ bị cảm."},{"type":"compound","zh":"因为信号忽高忽低，所以视频通话总是卡住。","pinyin":"Yīnwèi xìnhào hūgāohūdī, suǒyǐ shìpín tōnghuà zǒngshì kǎzhù.","vi":"Vì tín hiệu lúc mạnh lúc yếu nên cuộc gọi video cứ bị đơ."}],"related":[{"hanzi":"时高时低","pinyin":"shígāoshídī","vi":"khi cao khi thấp"},{"hanzi":"起伏","pinyin":"qǐfú","vi":"lên xuống"},{"hanzi":"不稳定","pinyin":"bùwěndìng","vi":"không ổn định"},{"hanzi":"忽冷忽热","pinyin":"hūlěnghūrè","vi":"lúc nóng lúc lạnh"}]},{"id":"忽悠","hanzi":"忽悠","pinyin":"hūyou","meaning_vi":"lừa phỉnh, dụ dỗ, \"chém gió\"; đung đưa","explanation":"忽悠 (phương ngữ Đông Bắc) → vốn nghĩa đung đưa, chập chờn; nay phổ biến với nghĩa dùng lời ngon ngọt để lừa phỉnh người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤥","examples":[{"type":"basic","zh":"你别忽悠我。","pinyin":"Nǐ bié hūyou wǒ.","vi":"Bạn đừng lừa tôi."},{"type":"simple","zh":"他被推销员忽悠着买了一堆保健品。","pinyin":"Tā bèi tuīxiāoyuán hūyouzhe mǎile yìduī bǎojiànpǐn.","vi":"Ông ấy bị nhân viên bán hàng dụ mua cả đống thực phẩm chức năng."},{"type":"compound","zh":"虽然他说得天花乱坠，但是我知道他是在忽悠人。","pinyin":"Suīrán tā shuō de tiānhuā luàn zhuì, dànshì wǒ zhīdào tā shì zài hūyou rén.","vi":"Tuy anh ta nói hoa mỹ trên trời dưới đất nhưng tôi biết anh ta đang lừa người."}],"related":[{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa gạt"},{"hanzi":"骗","pinyin":"piàn","vi":"lừa"},{"hanzi":"糊弄","pinyin":"hùnong","vi":"qua quýt, lừa bịp"},{"hanzi":"吹牛","pinyin":"chuīniú","vi":"khoác lác"}]},{"id":"胡闹","hanzi":"胡闹","pinyin":"húnào","meaning_vi":"làm càn, quậy phá, làm bậy","explanation":"胡 (hồ – bừa bãi) + 闹 (náo – ồn ào, quấy) → làm ồn quấy phá một cách vô lý, bừa bãi.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"别胡闹了！","pinyin":"Bié húnào le!","vi":"Đừng quậy nữa!"},{"type":"simple","zh":"孩子们在病房里胡闹，被护士批评了。","pinyin":"Háizimen zài bìngfáng lǐ húnào, bèi hùshi pīpíng le.","vi":"Bọn trẻ quậy phá trong phòng bệnh, bị y tá nhắc nhở."},{"type":"compound","zh":"这件事关系到大家的安全，所以不能由着他胡闹。","pinyin":"Zhè jiàn shì guānxìdào dàjiā de ānquán, suǒyǐ bù néng yóuzhe tā húnào.","vi":"Chuyện này liên quan tới an toàn của mọi người nên không thể để mặc anh ta làm càn."}],"related":[{"hanzi":"胡来","pinyin":"húlái","vi":"làm bừa"},{"hanzi":"捣乱","pinyin":"dǎoluàn","vi":"quấy rối"},{"hanzi":"淘气","pinyin":"táoqì","vi":"nghịch ngợm"},{"hanzi":"胡说","pinyin":"húshuō","vi":"nói bậy"}],"traditional":"胡鬧"},{"id":"互访","hanzi":"互访","pinyin":"hùfǎng","meaning_vi":"thăm viếng lẫn nhau, trao đổi chuyến thăm","explanation":"互 (hỗ – lẫn nhau) + 访 (phỏng – thăm hỏi) → hai bên qua lại thăm viếng nhau, thường dùng trong ngoại giao.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"两国领导人互访。","pinyin":"Liǎngguó lǐngdǎorén hùfǎng.","vi":"Lãnh đạo hai nước thăm viếng lẫn nhau."},{"type":"simple","zh":"两所大学每年都会组织师生互访。","pinyin":"Liǎng suǒ dàxué měinián dōuhuì zǔzhī shīshēng hùfǎng.","vi":"Hai trường đại học mỗi năm đều tổ chức cho thầy trò thăm lẫn nhau."},{"type":"compound","zh":"通过频繁的互访，两国的关系越来越密切了。","pinyin":"Tōngguò pínfán de hùfǎng, liǎngguó de guānxì yuèláiyuè mìqiè le.","vi":"Thông qua các chuyến thăm lẫn nhau thường xuyên, quan hệ hai nước ngày càng mật thiết."}],"related":[{"hanzi":"访问","pinyin":"fǎngwèn","vi":"chuyến thăm"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"đến thăm"},{"hanzi":"互相","pinyin":"hùxiāng","vi":"lẫn nhau"}],"traditional":"互訪"},{"id":"护理","hanzi":"护理","pinyin":"hùlǐ","meaning_vi":"chăm sóc, điều dưỡng, hộ lý","explanation":"护 (hộ – bảo vệ) + 理 (lý – xử lý, chăm lo) → chăm sóc người bệnh; cũng dùng cho chăm sóc da, tóc (皮肤护理).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"她在医院做护理。","pinyin":"Tā zài yīyuàn zuò hùlǐ.","vi":"Cô ấy làm điều dưỡng ở bệnh viện."},{"type":"simple","zh":"手术后的病人需要细心护理。","pinyin":"Shǒushù hòu de bìngrén xūyào xìxīn hùlǐ.","vi":"Bệnh nhân sau phẫu thuật cần được chăm sóc tỉ mỉ."},{"type":"compound","zh":"因为父母年纪大了，所以他请了一位专业的护理人员。","pinyin":"Yīnwèi fùmǔ niánjì dà le, suǒyǐ tā qǐngle yí wèi zhuānyè de hùlǐ rényuán.","vi":"Vì bố mẹ đã lớn tuổi nên anh ấy thuê một nhân viên điều dưỡng chuyên nghiệp."}],"related":[{"hanzi":"护士","pinyin":"hùshi","vi":"y tá"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"看护","pinyin":"kānhù","vi":"trông nom"},{"hanzi":"保养","pinyin":"bǎoyǎng","vi":"bảo dưỡng"}],"traditional":"護理"},{"id":"糊","hanzi":"糊","pinyin":"hú","meaning_vi":"dán (bằng hồ); hồ dán; (cơm) cháy khét","explanation":"糊 (hồ – hồ dán, cháo đặc) → dán bằng hồ; cũng chỉ thức ăn bị cháy khét (饭糊了).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍳","examples":[{"type":"basic","zh":"饭烧糊了。","pinyin":"Fàn shāo hú le.","vi":"Cơm bị khê rồi."},{"type":"simple","zh":"奶奶用旧报纸把窗户缝糊上了。","pinyin":"Nǎinai yòng jiù bàozhǐ bǎ chuānghu fèng hú shang le.","vi":"Bà dùng báo cũ dán kín khe cửa sổ."},{"type":"compound","zh":"要是火开得太大，锅里的菜就容易糊。","pinyin":"Yàoshi huǒ kāi de tài dà, guō lǐ de cài jiù róngyì hú.","vi":"Nếu để lửa quá to thì món trong nồi dễ bị cháy."}],"related":[{"hanzi":"糨糊","pinyin":"jiànghu","vi":"hồ dán"},{"hanzi":"粘","pinyin":"zhān","vi":"dán"},{"hanzi":"烧焦","pinyin":"shāojiāo","vi":"cháy khét"},{"hanzi":"糊涂","pinyin":"hútu","vi":"hồ đồ"}]},{"id":"花卉","hanzi":"花卉","pinyin":"huāhuì","meaning_vi":"hoa cỏ, hoa kiểng","explanation":"花 (hoa) + 卉 (hủy – cỏ) → hoa và cây cỏ dùng để trang trí, thưởng ngoạn.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"💐","examples":[{"type":"basic","zh":"这里种满了花卉。","pinyin":"Zhèlǐ zhòng mǎnle huāhuì.","vi":"Nơi này trồng đầy hoa kiểng."},{"type":"simple","zh":"春节前花卉市场特别热闹。","pinyin":"Chūnjié qián huāhuì shìchǎng tèbié rènao.","vi":"Trước Tết, chợ hoa đặc biệt nhộn nhịp."},{"type":"compound","zh":"虽然养花卉很费心，但是看着它们开花很有成就感。","pinyin":"Suīrán yǎng huāhuì hěn fèixīn, dànshì kànzhe tāmen kāihuā hěn yǒu chéngjiùgǎn.","vi":"Tuy trồng hoa kiểng rất tốn công nhưng nhìn chúng nở hoa thấy rất thỏa mãn."}],"related":[{"hanzi":"花草","pinyin":"huācǎo","vi":"hoa cỏ"},{"hanzi":"盆栽","pinyin":"pénzāi","vi":"cây cảnh chậu"},{"hanzi":"园艺","pinyin":"yuányì","vi":"nghề làm vườn"},{"hanzi":"鲜花","pinyin":"xiānhuā","vi":"hoa tươi"}]},{"id":"花纹","hanzi":"花纹","pinyin":"huāwén","meaning_vi":"hoa văn, đường vân","explanation":"花 (hoa – đẹp, sặc sỡ) + 纹 (văn – vân, đường nét) → những đường nét, hình vẽ trang trí trên bề mặt đồ vật.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🌀","examples":[{"type":"basic","zh":"这块布花纹很美。","pinyin":"Zhè kuài bù huāwén hěn měi.","vi":"Tấm vải này hoa văn rất đẹp."},{"type":"simple","zh":"瓷碗上的花纹都是工人手工画的。","pinyin":"Cíwǎn shang de huāwén dōu shì gōngrén shǒugōng huà de.","vi":"Hoa văn trên bát sứ đều do thợ vẽ tay."},{"type":"compound","zh":"如果轮胎的花纹磨平了，就应该马上更换。","pinyin":"Rúguǒ lúntāi de huāwén mó píng le, jiù yīnggāi mǎshàng gēng huàn.","vi":"Nếu gai lốp xe đã mòn phẳng thì nên thay ngay."}],"related":[{"hanzi":"图案","pinyin":"tú'àn","vi":"họa tiết"},{"hanzi":"纹路","pinyin":"wénlù","vi":"đường vân"},{"hanzi":"条纹","pinyin":"tiáowén","vi":"sọc"},{"hanzi":"花样","pinyin":"huāyàng","vi":"kiểu hoa"}],"traditional":"花紋"},{"id":"哗变","hanzi":"哗变","pinyin":"huábiàn","meaning_vi":"binh biến, nổi loạn (quân đội)","explanation":"哗 (hoa – ồn ào) + 变 (biến – biến cố) → quân lính đột ngột làm loạn, chống lại cấp trên.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"⚔️","examples":[{"type":"basic","zh":"军队发生了哗变。","pinyin":"Jūnduì fāshēngle huábiàn.","vi":"Quân đội đã xảy ra binh biến."},{"type":"simple","zh":"士兵们因为长期领不到军饷而哗变。","pinyin":"Shìbīngmen yīnwèi chángqī lǐng budào jūnxiǎng ér huábiàn.","vi":"Binh lính nổi loạn vì lâu ngày không được lĩnh lương."},{"type":"compound","zh":"一旦部队哗变，政府就很难控制局势了。","pinyin":"Yídàn bùduì huábiàn, zhèngfǔ jiù hěn nán kòngzhì júshì le.","vi":"Một khi quân đội nổi loạn, chính phủ sẽ rất khó kiểm soát tình hình."}],"related":[{"hanzi":"叛变","pinyin":"pànbiàn","vi":"phản bội"},{"hanzi":"兵变","pinyin":"bīngbiàn","vi":"binh biến"},{"hanzi":"政变","pinyin":"zhèngbiàn","vi":"đảo chính"},{"hanzi":"起义","pinyin":"qǐyì","vi":"khởi nghĩa"}],"traditional":"嘩變"},{"id":"哗然","hanzi":"哗然","pinyin":"huárán","meaning_vi":"xôn xao, ồn ào phản đối","explanation":"哗 (hoa – ồn ào) + 然 (nhiên – dáng vẻ) → đám đông xôn xao, náo động (thường vì kinh ngạc, bất bình).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"全场一片哗然。","pinyin":"Quánchǎng yípiàn huárán.","vi":"Cả hội trường xôn xao."},{"type":"simple","zh":"这条新闻一出，舆论顿时哗然。","pinyin":"Zhè tiáo xīnwén yì chū, yúlùn dùnshí huárán.","vi":"Tin này vừa đưa ra, dư luận lập tức xôn xao."},{"type":"compound","zh":"裁判一宣布取消他的成绩，观众就哗然了。","pinyin":"Cáipàn yì xuānbù qǔxiāo tā de chéngjì, guānzhòng jiù huárán le.","vi":"Trọng tài vừa tuyên bố hủy thành tích của anh ấy, khán giả liền ồ lên phản đối."}],"related":[{"hanzi":"喧哗","pinyin":"xuānhuá","vi":"ồn ào"},{"hanzi":"轰动","pinyin":"hōngdòng","vi":"chấn động"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"kinh ngạc"},{"hanzi":"鸦雀无声","pinyin":"yāquèwúshēng","vi":"im phăng phắc"}],"traditional":"嘩然"},{"id":"滑稽","hanzi":"滑稽","pinyin":"huájī","meaning_vi":"khôi hài, buồn cười, hài hước","explanation":"滑稽 (hoạt kê) → vốn chỉ người ăn nói lém lỉnh; nay chỉ điệu bộ, lời nói gây cười; cũng là tên một loại hình hài kịch ở Thượng Hải.","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🤡","examples":[{"type":"basic","zh":"他的动作很滑稽。","pinyin":"Tā de dòngzuò hěn huájī.","vi":"Động tác của anh ấy rất buồn cười."},{"type":"simple","zh":"小丑滑稽的表演逗得孩子们哈哈大笑。","pinyin":"Xiǎochǒu huájī de biǎoyǎn dòu de háizimen hāhā dàxiào.","vi":"Màn biểu diễn khôi hài của chú hề khiến bọn trẻ cười ha hả."},{"type":"compound","zh":"他穿着爸爸的大西装，看起来既滑稽又可爱。","pinyin":"Tā chuānzhe bàba de dà xīzhuāng, kànqilai jì huájī yòu kě'ài.","vi":"Cậu bé mặc bộ vest rộng của bố, trông vừa buồn cười vừa đáng yêu."}],"related":[{"hanzi":"好笑","pinyin":"hǎoxiào","vi":"buồn cười"},{"hanzi":"幽默","pinyin":"yōumò","vi":"hài hước"},{"hanzi":"可笑","pinyin":"kěxiào","vi":"nực cười"},{"hanzi":"小丑","pinyin":"xiǎochǒu","vi":"chú hề"}]},{"id":"滑梯","hanzi":"滑梯","pinyin":"huátī","meaning_vi":"cầu trượt","explanation":"滑 (hoạt – trơn, trượt) + 梯 (thê – cái thang) → cái thang để trượt xuống, đồ chơi của trẻ em.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🛝","examples":[{"type":"basic","zh":"孩子在玩滑梯。","pinyin":"Háizi zài wán huátī.","vi":"Đứa trẻ đang chơi cầu trượt."},{"type":"simple","zh":"公园里新建了一个彩色的滑梯。","pinyin":"Gōngyuán lǐ xīnjiànle yí ge cǎisè de huátī.","vi":"Trong công viên mới xây một cầu trượt nhiều màu."},{"type":"compound","zh":"因为滑梯被太阳晒得很烫，所以小朋友们都不敢上去。","pinyin":"Yīnwèi huátī bèi tàiyáng shài de hěn tàng, suǒyǐ xiǎo péngyoumen dōu bù gǎn shàngqu.","vi":"Vì cầu trượt bị nắng chiếu nóng rát nên các bạn nhỏ đều không dám lên."}],"related":[{"hanzi":"秋千","pinyin":"qiūqiān","vi":"xích đu"},{"hanzi":"跷跷板","pinyin":"qiāoqiāobǎn","vi":"bập bênh"},{"hanzi":"游乐场","pinyin":"yóulèchǎng","vi":"khu vui chơi"},{"hanzi":"滑","pinyin":"huá","vi":"trượt"}]},{"id":"化身","hanzi":"化身","pinyin":"huàshēn","meaning_vi":"hóa thân, hiện thân","explanation":"化 (hóa – biến thành) + 身 (thân – thân thể) → hình thể mà thần Phật biến hóa ra; nghĩa bóng là hiện thân tiêu biểu cho một phẩm chất.","hsk_level":"7-9","tags":["danh-tu"],"image":"🦸","examples":[{"type":"basic","zh":"他是正义的化身。","pinyin":"Tā shì zhèngyì de huàshēn.","vi":"Anh ấy là hiện thân của chính nghĩa."},{"type":"simple","zh":"在孩子们眼里，圣诞老人就是快乐的化身。","pinyin":"Zài háizimen yǎn lǐ, Shèngdànlǎorén jiùshì kuàilè de huàshēn.","vi":"Trong mắt trẻ em, ông già Noel chính là hiện thân của niềm vui."},{"type":"compound","zh":"虽然故事里的狐狸化身为美女，但是最后还是露出了尾巴。","pinyin":"Suīrán gùshi lǐ de húli huàshēn wéi měinǚ, dànshì zuìhòu háishi lùchūle wěiba.","vi":"Tuy con cáo trong truyện hóa thân thành mỹ nữ nhưng cuối cùng vẫn lộ đuôi."}],"related":[{"hanzi":"象征","pinyin":"xiàngzhēng","vi":"tượng trưng"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại diện"},{"hanzi":"变身","pinyin":"biànshēn","vi":"biến hình"},{"hanzi":"体现","pinyin":"tǐxiàn","vi":"thể hiện"}]},{"id":"化纤","hanzi":"化纤","pinyin":"huàxiān","meaning_vi":"sợi hóa học, sợi tổng hợp","explanation":"化 (hóa – hóa học) + 纤 (tiêm – sợi) → viết tắt của 化学纤维, sợi chế tạo bằng phương pháp hóa học.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"🧵","examples":[{"type":"basic","zh":"这是化纤面料。","pinyin":"Zhè shì huàxiān miànliào.","vi":"Đây là vải sợi tổng hợp."},{"type":"simple","zh":"化纤衣服容易起静电。","pinyin":"Huàxiān yīfu róngyì qǐ jìngdiàn.","vi":"Quần áo sợi tổng hợp dễ bị tĩnh điện."},{"type":"compound","zh":"化纤衣服虽然便宜耐穿，但是夏天穿起来不太透气。","pinyin":"Huàxiān yīfu suīrán piányi nàichuān, dànshì xiàtiān chuān qilai bú tài tòuqì.","vi":"Quần áo sợi tổng hợp tuy rẻ và bền nhưng mặc mùa hè không thoáng lắm."}],"related":[{"hanzi":"纯棉","pinyin":"chúnmián","vi":"cotton nguyên chất"},{"hanzi":"纤维","pinyin":"xiānwéi","vi":"sợi"},{"hanzi":"面料","pinyin":"miànliào","vi":"vải"},{"hanzi":"涤纶","pinyin":"dílún","vi":"polyester"}],"traditional":"化纖"},{"id":"划时代","hanzi":"划时代","pinyin":"huàshídài","meaning_vi":"mang tính thời đại, đánh dấu bước ngoặt","explanation":"划 (hoạch – vạch ranh giới) + 时代 (thời đại) → vạch ra một thời đại mới, có ý nghĩa mở đầu kỷ nguyên mới.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"这是划时代的发明。","pinyin":"Zhè shì huàshídài de fāmíng.","vi":"Đây là phát minh mang tính thời đại."},{"type":"simple","zh":"互联网的出现具有划时代的意义。","pinyin":"Hùliánwǎng de chūxiàn jùyǒu huàshídài de yìyì.","vi":"Sự ra đời của Internet có ý nghĩa đánh dấu thời đại."},{"type":"compound","zh":"虽然当时没人重视，但是这项研究后来被证明是划时代的。","pinyin":"Suīrán dāngshí méi rén zhòngshì, dànshì zhè xiàng yánjiū hòulái bèi zhèngmíng shì huàshídài de.","vi":"Tuy lúc đó không ai coi trọng nhưng về sau nghiên cứu này được chứng minh là mang tính bước ngoặt."}],"related":[{"hanzi":"里程碑","pinyin":"lǐchéngbēi","vi":"cột mốc"},{"hanzi":"历史性","pinyin":"lìshǐxìng","vi":"mang tính lịch sử"},{"hanzi":"开创","pinyin":"kāichuàng","vi":"khai sáng"},{"hanzi":"时代","pinyin":"shídài","vi":"thời đại"}],"traditional":"劃時代"},{"id":"划算","hanzi":"划算","pinyin":"huásuàn","meaning_vi":"đáng đồng tiền, có lợi, hời","explanation":"划 (hoạch – tính toán) + 算 (toán – tính) → tính ra thấy có lợi, bỏ ra ít mà được nhiều.","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"💰","examples":[{"type":"basic","zh":"这样买很划算。","pinyin":"Zhèyàng mǎi hěn huásuàn.","vi":"Mua như vậy rất hời."},{"type":"simple","zh":"办一张年卡比每次单独买票划算多了。","pinyin":"Bàn yì zhāng nián kǎ bǐ měi cì dāndú mǎipiào huásuàn duō le.","vi":"Làm một thẻ năm hời hơn nhiều so với mỗi lần mua vé lẻ."},{"type":"compound","zh":"虽然打车贵一点，但是能节省一个小时，还是挺划算的。","pinyin":"Suīrán dǎchē guì yìdiǎn, dànshì néng jiéshěng yí ge xiǎoshí, háishi tǐng huásuàn de.","vi":"Tuy đi taxi đắt hơn chút nhưng tiết kiệm được một tiếng, vẫn khá đáng."}],"related":[{"hanzi":"合算","pinyin":"hésuàn","vi":"có lợi"},{"hanzi":"值得","pinyin":"zhíde","vi":"đáng giá"},{"hanzi":"实惠","pinyin":"shíhuì","vi":"thiết thực, rẻ"},{"hanzi":"吃亏","pinyin":"chīkuī","vi":"chịu thiệt"}]},{"id":"画展","hanzi":"画展","pinyin":"huàzhǎn","meaning_vi":"triển lãm tranh","explanation":"画 (họa – tranh) + 展 (triển – trưng bày) → cuộc trưng bày tranh vẽ cho công chúng xem.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🖼️","examples":[{"type":"basic","zh":"我们去看画展吧。","pinyin":"Wǒmen qù kàn huàzhǎn ba.","vi":"Chúng ta đi xem triển lãm tranh đi."},{"type":"simple","zh":"美术馆正在举办一场油画展。","pinyin":"Měishùguǎn zhèngzài jǔbàn yì chǎng yóu huàzhǎn.","vi":"Bảo tàng mỹ thuật đang tổ chức một cuộc triển lãm tranh sơn dầu."},{"type":"compound","zh":"这位年轻画家虽然没什么名气，但是画展吸引了很多观众。","pinyin":"Zhè wèi niánqīng huàjiā suīrán méi shénme míngqì, dànshì huàzhǎn xīyǐnle hěn duō guānzhòng.","vi":"Họa sĩ trẻ này tuy chưa có tiếng tăm nhưng triển lãm tranh đã thu hút rất nhiều khán giả."}],"related":[{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"triển lãm"},{"hanzi":"画家","pinyin":"huàjiā","vi":"họa sĩ"},{"hanzi":"美术馆","pinyin":"měishùguǎn","vi":"bảo tàng mỹ thuật"},{"hanzi":"作品","pinyin":"zuòpǐn","vi":"tác phẩm"}],"traditional":"畫展"},{"id":"话费","hanzi":"话费","pinyin":"huàfèi","meaning_vi":"cước điện thoại, phí gọi","explanation":"话 (thoại – lời nói, cuộc gọi) + 费 (phí – chi phí) → tiền cước gọi điện thoại.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📱","examples":[{"type":"basic","zh":"我该交话费了。","pinyin":"Wǒ gāi jiāo huàfèi le.","vi":"Tôi phải nạp tiền điện thoại rồi."},{"type":"simple","zh":"这个月的话费比上个月多了一倍。","pinyin":"Zhè geyuè de huàfèi bǐ shànggeyuè duōle yí bèi.","vi":"Cước điện thoại tháng này gấp đôi tháng trước."},{"type":"compound","zh":"因为经常打国际长途，所以他的话费特别高。","pinyin":"Yīnwèi jīngcháng dǎ Guójì chángtú, suǒyǐ tā de huàfèi tèbié gāo.","vi":"Vì thường gọi điện quốc tế nên cước điện thoại của anh ấy đặc biệt cao."}],"related":[{"hanzi":"流量","pinyin":"liúliàng","vi":"dung lượng data"},{"hanzi":"充值","pinyin":"chōngzhí","vi":"nạp tiền"},{"hanzi":"电话","pinyin":"diànhuà","vi":"điện thoại"},{"hanzi":"套餐","pinyin":"tàocān","vi":"gói cước"}],"traditional":"話費"},{"id":"话语","hanzi":"话语","pinyin":"huàyǔ","meaning_vi":"lời nói, lời lẽ, ngôn từ","explanation":"话 (thoại – lời) + 语 (ngữ – ngôn ngữ) → lời nói, cách diễn đạt bằng lời; cũng dùng trong 话语权 (quyền phát ngôn).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"💬","examples":[{"type":"basic","zh":"他的话语很温暖。","pinyin":"Tā de huàyǔ hěn wēnnuǎn.","vi":"Lời nói của anh ấy rất ấm áp."},{"type":"simple","zh":"老师鼓励的话语让我重新有了信心。","pinyin":"Lǎoshī gǔlì de huàyǔ ràng wǒ chóngxīn yǒule xìnxīn.","vi":"Lời động viên của thầy giúp tôi lấy lại tự tin."},{"type":"compound","zh":"虽然他的话语不多，但是每一句都说到了点子上。","pinyin":"Suīrán tā de huàyǔ bù duō, dànshì měi yíjù dōu shuōdàole diǎnzi shang.","vi":"Tuy anh ấy nói không nhiều nhưng câu nào cũng trúng điểm mấu chốt."}],"related":[{"hanzi":"言语","pinyin":"yányǔ","vi":"lời nói"},{"hanzi":"语言","pinyin":"yǔyán","vi":"ngôn ngữ"},{"hanzi":"话语权","pinyin":"huàyǔquán","vi":"quyền phát ngôn"},{"hanzi":"言辞","pinyin":"yáncí","vi":"lời lẽ"}],"traditional":"話語"},{"id":"怀里","hanzi":"怀里","pinyin":"huáilǐ","meaning_vi":"trong lòng, trong vòng tay","explanation":"怀 (hoài – lòng, ngực) + 里 (lý – bên trong) → phần trước ngực, trong vòng tay ôm.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🫂","examples":[{"type":"basic","zh":"孩子睡在妈妈怀里。","pinyin":"Háizi shuì zài māma huáilǐ.","vi":"Đứa trẻ ngủ trong lòng mẹ."},{"type":"simple","zh":"她把小猫紧紧抱在怀里。","pinyin":"Tā bǎ xiǎomāo jǐn jǐnbào zài huáilǐ.","vi":"Cô ấy ôm chặt chú mèo con vào lòng."},{"type":"compound","zh":"他一见到久别的女儿，就把她搂在了怀里。","pinyin":"Tā yí jiàndào jiǔ biéde nǚ'ér, jiù bǎ tā lǒu zài le huáilǐ.","vi":"Ông vừa thấy đứa con gái xa cách đã lâu liền ôm cô vào lòng."}],"related":[{"hanzi":"怀抱","pinyin":"huáibào","vi":"vòng tay"},{"hanzi":"拥抱","pinyin":"yōngbào","vi":"ôm"},{"hanzi":"胸前","pinyin":"xiōngqián","vi":"trước ngực"},{"hanzi":"搂","pinyin":"lǒu","vi":"ôm"}],"traditional":"懷裡"},{"id":"怀着","hanzi":"怀着","pinyin":"huáizhe","meaning_vi":"mang (trong lòng), ôm ấp (tâm trạng, hy vọng)","explanation":"怀 (hoài – ôm ấp trong lòng) + 着 (trợ từ tiếp diễn) → mang theo trong lòng một tâm trạng, ý định nào đó.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"他怀着希望出发了。","pinyin":"Tā huáizhe xīwàng chūfā le.","vi":"Anh ấy lên đường với niềm hy vọng."},{"type":"simple","zh":"我怀着激动的心情走进了考场。","pinyin":"Wǒ huáizhe jīdòng de xīnqíng zǒujìnle kǎochǎng.","vi":"Tôi bước vào phòng thi với tâm trạng hồi hộp."},{"type":"compound","zh":"虽然他怀着好意，但是说话的方式让人很不舒服。","pinyin":"Suīrán tā huáizhe hǎoyì, dànshì shuōhuà de fāngshì ràng rén hěn bù shūfu.","vi":"Tuy anh ấy có ý tốt nhưng cách nói chuyện khiến người ta rất khó chịu."}],"related":[{"hanzi":"怀有","pinyin":"huáiyǒu","vi":"mang, có (trong lòng)"},{"hanzi":"抱着","pinyin":"bàozhe","vi":"ôm, mang"},{"hanzi":"带着","pinyin":"dàizhe","vi":"mang theo"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"tâm trạng"}],"traditional":"懷著"},{"id":"槐树","hanzi":"槐树","pinyin":"huáishù","meaning_vi":"cây hòe","explanation":"槐 (hòe – cây hòe) + 树 (thụ – cây) → cây hòe, loài cây thân gỗ hoa trắng, thường trồng ở sân và ven đường phương Bắc Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"村口有棵老槐树。","pinyin":"Cūn kǒu yǒu kē lǎo huáishù.","vi":"Đầu làng có một cây hòe già."},{"type":"simple","zh":"每到五月，槐树开满了白色的花。","pinyin":"Měi dào Wǔyuè, huáishù kāimǎnle báisè de huā.","vi":"Cứ đến tháng năm, cây hòe lại nở đầy hoa trắng."},{"type":"compound","zh":"夏天一到，老人们就喜欢坐在槐树下乘凉聊天。","pinyin":"Xiàtiān yí dào, lǎo rénmen jiù xǐhuan zuò zài huáishù xià chéngliáng liáotiān.","vi":"Hè đến, các cụ già lại thích ngồi dưới gốc hòe hóng mát trò chuyện."}],"related":[{"hanzi":"槐花","pinyin":"huáihuā","vi":"hoa hòe"},{"hanzi":"柳树","pinyin":"liǔshù","vi":"cây liễu"},{"hanzi":"松树","pinyin":"sōngshù","vi":"cây thông"},{"hanzi":"树荫","pinyin":"shùyīn","vi":"bóng cây"}],"traditional":"槐樹"},{"id":"坏事","hanzi":"坏事","pinyin":"huàishì","meaning_vi":"việc xấu, chuyện xấu; làm hỏng việc","explanation":"坏 (hoại – xấu, hỏng) + 事 (sự – việc) → việc làm xấu; làm động từ nghĩa là làm hỏng chuyện.","hsk_level":"7-9","tags":["danh-tu"],"image":"😈","examples":[{"type":"basic","zh":"他从不做坏事。","pinyin":"Tā cóng bú zuò huàishì.","vi":"Anh ấy chưa bao giờ làm việc xấu."},{"type":"simple","zh":"坏事传千里，好事却不出门。","pinyin":"Huàishì chuán qiānlǐ, hǎoshì què bù chūmén.","vi":"Tiếng xấu đồn xa, việc tốt chẳng ai hay."},{"type":"compound","zh":"有时候坏事也能变成好事，只要你能从中吸取教训。","pinyin":"Yǒushíhou huàishì yě néng biànchéng hǎoshì, zhǐyào nǐ néng cóng zhōng xīqǔ jiàoxun.","vi":"Đôi khi chuyện xấu cũng có thể thành chuyện tốt, miễn là bạn rút ra được bài học từ đó."}],"related":[{"hanzi":"好事","pinyin":"hǎoshì","vi":"việc tốt"},{"hanzi":"坏人","pinyin":"huàirén","vi":"kẻ xấu"},{"hanzi":"错事","pinyin":"cuòshì","vi":"việc sai"},{"hanzi":"坏处","pinyin":"huàichu","vi":"tác hại"}],"traditional":"壞事"},{"id":"环球","hanzi":"环球","pinyin":"huánqiú","meaning_vi":"toàn cầu, vòng quanh thế giới","explanation":"环 (hoàn – vòng quanh) + 球 (cầu – quả địa cầu) → vòng quanh trái đất, khắp thế giới.","hsk_level":"7-9","tags":["tinh-tu","du-lich"],"image":"🌍","examples":[{"type":"basic","zh":"他想环球旅行。","pinyin":"Tā xiǎng huánqiú lǚxíng.","vi":"Anh ấy muốn du lịch vòng quanh thế giới."},{"type":"simple","zh":"这家航空公司开通了多条环球航线。","pinyin":"Zhè jiā hángkōng gōngsī kāitōngle duō tiáo huánqiú hángxiàn.","vi":"Hãng hàng không này đã mở nhiều đường bay toàn cầu."},{"type":"compound","zh":"虽然环球航行很危险，但是他还是决定独自出发。","pinyin":"Suīrán huánqiú hángxíng hěn wēixiǎn, dànshì tā háishi juédìng dúzì chūfā.","vi":"Tuy đi thuyền vòng quanh thế giới rất nguy hiểm nhưng anh ấy vẫn quyết định một mình lên đường."}],"related":[{"hanzi":"全球","pinyin":"quánqiú","vi":"toàn cầu"},{"hanzi":"世界","pinyin":"shìjiè","vi":"thế giới"},{"hanzi":"地球","pinyin":"dìqiú","vi":"trái đất"},{"hanzi":"国际","pinyin":"Guójì","vi":"quốc tế"}],"traditional":"環球"},{"id":"环绕","hanzi":"环绕","pinyin":"huánrào","meaning_vi":"bao quanh, vây quanh, xoay quanh","explanation":"环 (hoàn – vòng) + 绕 (nhiễu – quấn quanh) → bao vòng quanh hoặc chuyển động xoay quanh một vật.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪐","examples":[{"type":"basic","zh":"小村四面环绕着青山。","pinyin":"Xiǎo cūn sìmiàn huánràozhe qīngshān.","vi":"Bốn bề ngôi làng nhỏ được núi xanh bao quanh."},{"type":"simple","zh":"月球环绕地球运行一周大约需要二十七天。","pinyin":"Yuèqiú huánrào dìqiú yùnxíng yìzhōu dàyuē xūyào èr shíqī tiān.","vi":"Mặt trăng quay quanh trái đất một vòng mất khoảng hai mươi bảy ngày."},{"type":"compound","zh":"因为房子周围环绕着树林，所以夏天特别凉快。","pinyin":"Yīnwèi fángzi zhōuwéi huánràozhe shùlín, suǒyǐ xiàtiān tèbié liángkuai.","vi":"Vì quanh nhà có rừng cây bao bọc nên mùa hè rất mát mẻ."}],"related":[{"hanzi":"围绕","pinyin":"wéirào","vi":"xoay quanh"},{"hanzi":"包围","pinyin":"bāowéi","vi":"bao vây"},{"hanzi":"环抱","pinyin":"huánbào","vi":"ôm quanh"},{"hanzi":"绕","pinyin":"rào","vi":"vòng quanh"}],"traditional":"環繞"},{"id":"缓","hanzi":"缓","pinyin":"huǎn","meaning_vi":"chậm, từ từ; hoãn lại; hồi lại, hoàn hồn","explanation":"缓 (hoãn – chậm, thong thả) → chậm rãi; làm động từ là hoãn lại, hoặc hồi phục lại (缓过来).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐢","examples":[{"type":"basic","zh":"这事先缓一缓。","pinyin":"Zhè shìxiān huǎn yi huǎn.","vi":"Việc này cứ hoãn lại một chút đã."},{"type":"simple","zh":"他喝了口热水，才慢慢缓过来。","pinyin":"Tā hēle kǒu rèshuǐ, cái mànmàn huǎn guòlai.","vi":"Anh ấy uống một ngụm nước nóng mới dần hồi lại."},{"type":"compound","zh":"如果资金一时到不了位，项目就只能暂缓执行。","pinyin":"Rúguǒ zījīn yìshí dào buliǎo wèi, xiàngmù jiù zhǐnéng zànhuǎn zhíxíng.","vi":"Nếu vốn nhất thời chưa về kịp thì dự án chỉ có thể tạm hoãn thực hiện."}],"related":[{"hanzi":"缓慢","pinyin":"huǎnmàn","vi":"chậm chạp"},{"hanzi":"缓解","pinyin":"huǎnjiě","vi":"làm dịu"},{"hanzi":"暂缓","pinyin":"zànhuǎn","vi":"tạm hoãn"},{"hanzi":"急","pinyin":"jí","vi":"gấp"}],"traditional":"緩"},{"id":"缓缓","hanzi":"缓缓","pinyin":"huǎnhuǎn","meaning_vi":"từ từ, chầm chậm, thong thả","explanation":"缓 (hoãn – chậm) lặp lại → chậm rãi, từ từ từng chút một; thường dùng trong văn miêu tả.","hsk_level":"7-9","tags":["pho-tu"],"image":"🍃","examples":[{"type":"basic","zh":"火车缓缓开动了。","pinyin":"Huǒchē huǎnhuǎn kāidòng le.","vi":"Đoàn tàu từ từ chuyển bánh."},{"type":"simple","zh":"太阳缓缓地从海面上升起。","pinyin":"Tàiyáng huǎnhuǎn de cóng hǎimiàn shang shēngqǐ.","vi":"Mặt trời từ từ nhô lên khỏi mặt biển."},{"type":"compound","zh":"音乐一响起，大幕就缓缓拉开了。","pinyin":"Yīnyuè yì xiǎngqǐ, dà mù jiù huǎnhuǎn lākāi le.","vi":"Nhạc vừa vang lên, tấm màn lớn liền từ từ kéo ra."}],"related":[{"hanzi":"慢慢","pinyin":"mànmàn","vi":"từ từ"},{"hanzi":"徐徐","pinyin":"xúxú","vi":"thong thả"},{"hanzi":"缓慢","pinyin":"huǎnmàn","vi":"chậm chạp"},{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"}],"traditional":"緩緩"},{"id":"幻觉","hanzi":"幻觉","pinyin":"huànjué","meaning_vi":"ảo giác","explanation":"幻 (huyễn – hư ảo) + 觉 (giác – cảm giác) → cảm giác không có thật, thấy hoặc nghe những thứ không tồn tại.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"😵‍💫","examples":[{"type":"basic","zh":"这只是幻觉。","pinyin":"Zhè zhǐshì huànjué.","vi":"Đây chỉ là ảo giác."},{"type":"simple","zh":"高烧让他出现了幻觉。","pinyin":"Gāoshāo ràng tā chūxiànle huànjué.","vi":"Sốt cao khiến anh ấy bị ảo giác."},{"type":"compound","zh":"我刚才好像听见有人叫我，难道是幻觉吗？","pinyin":"Wǒ gāngcái hǎoxiàng tīngjiàn yǒurén jiào wǒ, nándào shì huànjué ma?","vi":"Vừa rồi tôi hình như nghe có người gọi, chẳng lẽ là ảo giác?"}],"related":[{"hanzi":"错觉","pinyin":"cuòjué","vi":"ảo giác, cảm giác sai"},{"hanzi":"幻想","pinyin":"huànxiǎng","vi":"ảo tưởng"},{"hanzi":"幻影","pinyin":"huànyǐng","vi":"ảo ảnh"},{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"}],"traditional":"幻覺"},{"id":"幻影","hanzi":"幻影","pinyin":"huànyǐng","meaning_vi":"ảo ảnh, bóng ma","explanation":"幻 (huyễn – hư ảo) + 影 (ảnh – bóng hình) → hình bóng hư ảo, không có thật.","hsk_level":"7-9","tags":["danh-tu"],"image":"👻","examples":[{"type":"basic","zh":"那只是个幻影。","pinyin":"Nà zhǐshì ge huànyǐng.","vi":"Đó chỉ là một ảo ảnh."},{"type":"simple","zh":"沙漠中的绿洲原来只是一个幻影。","pinyin":"Shāmò zhōng de lǜzhōu yuánlái zhǐshì yí ge huànyǐng.","vi":"Ốc đảo giữa sa mạc hóa ra chỉ là một ảo ảnh."},{"type":"compound","zh":"虽然那个身影一闪而过，但是我确定那不是幻影。","pinyin":"Suīrán nà ge shēnyǐng yì shǎn ér guò, dànshì wǒ quèdìng nà bú shì huànyǐng.","vi":"Tuy bóng người đó lướt qua trong chớp mắt nhưng tôi chắc chắn đó không phải ảo ảnh."}],"related":[{"hanzi":"幻觉","pinyin":"huànjué","vi":"ảo giác"},{"hanzi":"海市蜃楼","pinyin":"hǎishìshènlóu","vi":"ảo ảnh, ảo vọng"},{"hanzi":"影子","pinyin":"yǐngzi","vi":"cái bóng"},{"hanzi":"虚幻","pinyin":"xūhuàn","vi":"hư ảo"}]},{"id":"换成","hanzi":"换成","pinyin":"huànchéng","meaning_vi":"đổi thành, thay bằng","explanation":"换 (hoán – đổi) + 成 (thành – trở thành) → đổi cái này sang cái khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"请换成大号。","pinyin":"Qǐng huànchéng dàhào.","vi":"Xin đổi sang cỡ lớn."},{"type":"simple","zh":"我想把这些人民币换成越南盾。","pinyin":"Wǒ xiǎng bǎ zhèxiē rénmínbì huànchéng Yuènándùn.","vi":"Tôi muốn đổi chỗ nhân dân tệ này sang tiền đồng Việt Nam."},{"type":"compound","zh":"如果把这件事换成是你，你会怎么做呢？","pinyin":"Rúguǒ bǎ zhè jiàn shì huànchéng shì nǐ, nǐ huì zěnme zuò ne?","vi":"Nếu chuyện này đổi lại là bạn, bạn sẽ làm thế nào?"}],"related":[{"hanzi":"变成","pinyin":"biànchéng","vi":"biến thành"},{"hanzi":"改成","pinyin":"gǎichéng","vi":"sửa thành"},{"hanzi":"替换","pinyin":"tìhuàn","vi":"thay thế"},{"hanzi":"兑换","pinyin":"duìhuàn","vi":"đổi (tiền)"}],"traditional":"換成"},{"id":"换位","hanzi":"换位","pinyin":"huànwèi","meaning_vi":"đổi chỗ; đặt mình vào vị trí người khác; đảo lốp","explanation":"换 (hoán – đổi) + 位 (vị – vị trí) → đổi vị trí cho nhau; thường dùng trong 换位思考 (đặt mình vào vị trí người khác mà suy nghĩ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔀","examples":[{"type":"basic","zh":"我们换位坐吧。","pinyin":"Wǒmen huànwèi zuò ba.","vi":"Chúng ta đổi chỗ ngồi nhé."},{"type":"simple","zh":"遇到矛盾时，要学会换位思考。","pinyin":"Yùdào máodùn shí, yào xuéhuì huànwèisīkǎo.","vi":"Khi gặp mâu thuẫn, phải học cách đặt mình vào vị trí người khác."},{"type":"compound","zh":"如果你能换位想一想，就会理解他的难处。","pinyin":"Rúguǒ nǐ néng huànwèi xiǎng yi xiǎng, jiù huì lǐjiě tā de nánchù.","vi":"Nếu bạn có thể đặt mình vào vị trí đó mà nghĩ thử, bạn sẽ hiểu cái khó của anh ấy."}],"related":[{"hanzi":"换位思考","pinyin":"huànwèisīkǎo","vi":"đặt mình vào vị trí người khác"},{"hanzi":"对调","pinyin":"duìdiào","vi":"đổi cho nhau"},{"hanzi":"调换","pinyin":"diàohuàn","vi":"hoán đổi"},{"hanzi":"位置","pinyin":"wèizhi","vi":"vị trí"}],"traditional":"換位"},{"id":"换言之","hanzi":"换言之","pinyin":"huànyánzhī","meaning_vi":"nói cách khác, nói một cách khác","explanation":"换 (hoán – đổi) + 言 (ngôn – lời) + 之 (chi – nó) → đổi lời mà nói; dùng để diễn đạt lại ý trước theo cách khác, mang sắc thái văn viết.","hsk_level":"7-9","tags":["lien-tu"],"image":"🗨️","examples":[{"type":"basic","zh":"换言之，他输了。","pinyin":"Huànyánzhī, tā shū le.","vi":"Nói cách khác, anh ta đã thua."},{"type":"simple","zh":"他没有回复，换言之，他不同意。","pinyin":"Tā méiyǒu huífù, huànyánzhī, tā bù tóngyì.","vi":"Anh ấy không trả lời, nói cách khác là anh ấy không đồng ý."},{"type":"compound","zh":"这个方案成本太高，换言之，我们根本负担不起。","pinyin":"Zhè ge fāng'àn chéngběn tài gāo, huànyánzhī, wǒmen gēnběn fùdān bu qǐ.","vi":"Phương án này chi phí quá cao, nói cách khác, chúng ta hoàn toàn không gánh nổi."}],"related":[{"hanzi":"也就是说","pinyin":"yějiùshìshuō","vi":"tức là"},{"hanzi":"换句话说","pinyin":"huànjùhuàshuō","vi":"nói cách khác"},{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"},{"hanzi":"即","pinyin":"jí","vi":"tức là"}],"traditional":"換言之"},{"id":"患","hanzi":"患","pinyin":"huàn","meaning_vi":"mắc (bệnh); tai họa, hoạn nạn; lo lắng","explanation":"患 (hoạn – lo âu, tai họa) → mắc phải bệnh tật; danh từ chỉ tai họa (水患, 隐患).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"他患了重感冒。","pinyin":"Tā huànle zhòng gǎnmào.","vi":"Anh ấy bị cảm nặng."},{"type":"simple","zh":"她从小就患有严重的哮喘。","pinyin":"Tā cóngxiǎo jiù huànyǒu yánzhòng de xiāochuǎn.","vi":"Cô ấy từ nhỏ đã mắc bệnh hen suyễn nặng."},{"type":"compound","zh":"只要提前做好准备，就不怕会有后患。","pinyin":"Zhǐyào tíqián zuò hǎo zhǔnbèi, jiù bú pà huì yǒu hòuhuàn.","vi":"Chỉ cần chuẩn bị trước kỹ càng thì không sợ có hậu họa."}],"related":[{"hanzi":"患者","pinyin":"huànzhě","vi":"bệnh nhân"},{"hanzi":"患病","pinyin":"huànbìng","vi":"mắc bệnh"},{"hanzi":"隐患","pinyin":"yǐnhuàn","vi":"mối nguy tiềm ẩn"},{"hanzi":"有备无患","pinyin":"yǒubèiwúhuàn","vi":"có chuẩn bị thì không lo"}]},{"id":"患病","hanzi":"患病","pinyin":"huànbìng","meaning_vi":"mắc bệnh, bị bệnh","explanation":"患 (hoạn – mắc phải) + 病 (bệnh) → mắc bệnh, lâm bệnh.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他患病多年了。","pinyin":"Tā huànbìng duōnián le.","vi":"Ông ấy mắc bệnh nhiều năm rồi."},{"type":"simple","zh":"老年人患病的风险比年轻人高。","pinyin":"Lǎoniánrén huànbìng de fēngxiǎn bǐ niánqīngrén gāo.","vi":"Người già có nguy cơ mắc bệnh cao hơn người trẻ."},{"type":"compound","zh":"自从父亲患病以后，家里的担子就落到了他身上。","pinyin":"Zìcóng fùqīn huànbìng yǐhòu, jiālǐ de dànzi jiù luò dàole tā shēnshang.","vi":"Từ khi cha lâm bệnh, gánh nặng gia đình đổ lên vai anh ấy."}],"related":[{"hanzi":"生病","pinyin":"shēngbìng","vi":"bị ốm"},{"hanzi":"得病","pinyin":"débìng","vi":"mắc bệnh"},{"hanzi":"患者","pinyin":"huànzhě","vi":"bệnh nhân"},{"hanzi":"康复","pinyin":"kāngfù","vi":"bình phục"}]},{"id":"患有","hanzi":"患有","pinyin":"huànyǒu","meaning_vi":"mắc, bị (bệnh)","explanation":"患 (hoạn – mắc bệnh) + 有 (hữu – có) → đang mắc một căn bệnh nào đó; sau thường có tên bệnh.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"他患有糖尿病。","pinyin":"Tā huànyǒu tángniàobìng.","vi":"Ông ấy bị bệnh tiểu đường."},{"type":"simple","zh":"这位老人患有严重的心脏病。","pinyin":"Zhè wèi lǎorén huànyǒu yánzhòng de xīnzàngbìng.","vi":"Cụ già này mắc bệnh tim nặng."},{"type":"compound","zh":"由于他患有高血压，所以医生不让他吃太咸的东西。","pinyin":"Yóuyú tā huànyǒu gāoxuèyā, suǒyǐ yīshēng bú ràng tā chī tài xián de dōngxi.","vi":"Do bị cao huyết áp nên bác sĩ không cho ông ăn đồ quá mặn."}],"related":[{"hanzi":"患病","pinyin":"huànbìng","vi":"mắc bệnh"},{"hanzi":"得了","pinyin":"déle","vi":"bị (bệnh)"},{"hanzi":"病人","pinyin":"bìngrén","vi":"người bệnh"},{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"}]},{"id":"欢聚","hanzi":"欢聚","pinyin":"huānjù","meaning_vi":"sum họp vui vẻ, quây quần","explanation":"欢 (hoan – vui) + 聚 (tụ – tụ họp) → vui vẻ tụ họp lại với nhau.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🎉","examples":[{"type":"basic","zh":"全家人欢聚一堂。","pinyin":"Quán jiārén huānjùyìtáng.","vi":"Cả nhà sum họp vui vẻ."},{"type":"simple","zh":"老同学们毕业十年后又在母校欢聚。","pinyin":"Lǎo tóngxuémen bìyè shí nián hòu yòu zài mǔxiào huānjù.","vi":"Các bạn học cũ mười năm sau tốt nghiệp lại vui vẻ tụ họp ở trường xưa."},{"type":"compound","zh":"每到春节，不管离家多远，大家都会回来欢聚。","pinyin":"Měi dào Chūnjié, bùguǎn lí jiā duō yuǎn, dàjiā dōuhuì huílai huānjù.","vi":"Mỗi dịp Tết, dù xa nhà bao nhiêu, mọi người đều trở về sum họp."}],"related":[{"hanzi":"团聚","pinyin":"tuánjù","vi":"đoàn tụ"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi họp mặt"},{"hanzi":"团圆","pinyin":"tuányuán","vi":"đoàn viên"},{"hanzi":"离别","pinyin":"líbié","vi":"ly biệt"}],"traditional":"歡聚"},{"id":"欢快","hanzi":"欢快","pinyin":"huānkuài","meaning_vi":"vui tươi, rộn rã, vui vẻ","explanation":"欢 (hoan – vui) + 快 (khoái – sảng khoái) → vui tươi, nhẹ nhàng, nhịp điệu rộn ràng.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🎶","examples":[{"type":"basic","zh":"这首歌很欢快。","pinyin":"Zhè shǒu gē hěn huānkuài.","vi":"Bài hát này rất vui tươi."},{"type":"simple","zh":"孩子们迈着欢快的步子走进了校园。","pinyin":"Háizimen màizhe huānkuài de bùzi zǒujìnle xiàoyuán.","vi":"Bọn trẻ bước những bước chân rộn rã vào sân trường."},{"type":"compound","zh":"音乐一变得欢快起来，大家就跟着节奏跳起了舞。","pinyin":"Yīnyuè yí biànde huānkuài qilai, dàjiā jiù gēnzhe jiézòu tiào qǐle wǔ.","vi":"Nhạc vừa trở nên rộn ràng, mọi người liền nhảy theo nhịp."}],"related":[{"hanzi":"愉快","pinyin":"yúkuài","vi":"vui vẻ"},{"hanzi":"轻快","pinyin":"qīngkuài","vi":"nhẹ nhàng"},{"hanzi":"欢乐","pinyin":"huānlè","vi":"vui sướng"},{"hanzi":"沉闷","pinyin":"chénmèn","vi":"buồn tẻ"}],"traditional":"歡快"},{"id":"荒","hanzi":"荒","pinyin":"huāng","meaning_vi":"hoang vu, bỏ hoang; mất mùa; lụt nghề, sao nhãng","explanation":"荒 (hoang – hoang vu) → đất bỏ hoang, cỏ mọc um tùm; mở rộng là mất mùa (饥荒) hoặc kỹ năng bị mai một vì lâu không luyện.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏜️","examples":[{"type":"basic","zh":"这块地荒了。","pinyin":"Zhè kuài dì huāng le.","vi":"Mảnh đất này bỏ hoang rồi."},{"type":"simple","zh":"好几年没弹钢琴，手艺都荒了。","pinyin":"Hǎojǐnián méi tángāngqín, shǒuyì dōu huāng le.","vi":"Mấy năm không đánh đàn piano, tay nghề đều mai một cả."},{"type":"compound","zh":"因为年轻人都去城里打工了，所以村里很多田都荒着。","pinyin":"Yīnwèi niánqīngrén dōu qù chénglǐ dǎgōng le, suǒyǐ cūnlǐ hěn duō tián dōu huāng zhe.","vi":"Vì thanh niên đều lên thành phố làm thuê nên nhiều ruộng trong làng bị bỏ hoang."}],"related":[{"hanzi":"荒凉","pinyin":"huāngliáng","vi":"hoang vắng"},{"hanzi":"荒地","pinyin":"huāngdì","vi":"đất hoang"},{"hanzi":"饥荒","pinyin":"jīhuang","vi":"nạn đói"},{"hanzi":"荒废","pinyin":"huāngfèi","vi":"bỏ phế"}]},{"id":"慌乱","hanzi":"慌乱","pinyin":"huāngluàn","meaning_vi":"hoảng loạn, rối rít, cuống cuồng","explanation":"慌 (hoảng – hoảng hốt) + 乱 (loạn – rối loạn) → hoảng hốt đến mức rối loạn, mất bình tĩnh.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"他显得有些慌乱。","pinyin":"Tā xiǎnde yǒuxiē huāngluàn.","vi":"Anh ấy có vẻ hơi hoảng loạn."},{"type":"simple","zh":"听到火警，人们慌乱地往外跑。","pinyin":"Tīngdào huǒjǐng, rénmen huāngluàn de wǎng wài pǎo.","vi":"Nghe chuông báo cháy, mọi người hoảng loạn chạy ra ngoài."},{"type":"compound","zh":"即使遇到突发情况，你也不要慌乱，先冷静下来。","pinyin":"Jíshǐ yùdào tūfā qíngkuàng, nǐ yě bú yào huāngluàn, xiān lěngjìng xiàlai.","vi":"Dù gặp tình huống bất ngờ, bạn cũng đừng hoảng loạn, hãy bình tĩnh lại trước đã."}],"related":[{"hanzi":"慌张","pinyin":"huāngzhāng","vi":"hoảng hốt"},{"hanzi":"惊慌","pinyin":"jīnghuāng","vi":"kinh hoàng"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"cuống quýt"}],"traditional":"慌亂"},{"id":"皇宫","hanzi":"皇宫","pinyin":"huánggōng","meaning_vi":"hoàng cung, cung điện","explanation":"皇 (hoàng – vua) + 宫 (cung – cung điện) → cung điện nơi vua ở.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏯","examples":[{"type":"basic","zh":"这里曾是皇宫。","pinyin":"Zhèlǐ céng shì huánggōng.","vi":"Nơi đây từng là hoàng cung."},{"type":"simple","zh":"故宫是明清两代的皇宫。","pinyin":"Gùgōng shì Míngqīng liǎng dài de huánggōng.","vi":"Cố Cung là hoàng cung của hai triều Minh, Thanh."},{"type":"compound","zh":"虽然皇宫已经变成了博物馆，但是依然能感受到当年的气派。","pinyin":"Suīrán huánggōng yǐjīng biàn chéngle bówùguǎn, dànshì yīrán néng gǎn shòudào dāngnián de qìpài.","vi":"Tuy hoàng cung đã trở thành bảo tàng nhưng vẫn cảm nhận được vẻ uy nghi năm xưa."}],"related":[{"hanzi":"宫殿","pinyin":"gōngdiàn","vi":"cung điện"},{"hanzi":"皇帝","pinyin":"huángdì","vi":"hoàng đế"},{"hanzi":"故宫","pinyin":"gùgōng","vi":"Cố Cung"},{"hanzi":"王宫","pinyin":"wánggōng","vi":"vương cung"}],"traditional":"皇宮"},{"id":"皇上","hanzi":"皇上","pinyin":"huángshang","meaning_vi":"hoàng thượng, bệ hạ","explanation":"皇 (hoàng – vua) + 上 (thượng – bề trên) → cách gọi tôn kính dành cho vua đang tại vị.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"皇上驾到！","pinyin":"Huángshang jià dào!","vi":"Hoàng thượng giá lâm!"},{"type":"simple","zh":"大臣们跪在殿前等候皇上的命令。","pinyin":"Dàchénmen guì zài diàn qián děnghòu huángshang de mìnglìng.","vi":"Các đại thần quỳ trước điện chờ lệnh hoàng thượng."},{"type":"compound","zh":"虽然皇上很生气，但是他最后还是原谅了那位大臣。","pinyin":"Suīrán huángshang hěn shēngqì, dànshì tā zuìhòu háishi yuánliàngle nà wèi dàchén.","vi":"Tuy hoàng thượng rất giận nhưng cuối cùng vẫn tha thứ cho vị đại thần ấy."}],"related":[{"hanzi":"皇帝","pinyin":"huángdì","vi":"hoàng đế"},{"hanzi":"陛下","pinyin":"bìxià","vi":"bệ hạ"},{"hanzi":"大臣","pinyin":"dàchén","vi":"đại thần"},{"hanzi":"皇后","pinyin":"huánghòu","vi":"hoàng hậu"}]},{"id":"皇室","hanzi":"皇室","pinyin":"huángshì","meaning_vi":"hoàng thất, hoàng gia","explanation":"皇 (hoàng – vua) + 室 (thất – nhà, dòng họ) → gia tộc của vua, hoàng gia.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤴","examples":[{"type":"basic","zh":"他出身皇室。","pinyin":"Tā chūshēn huángshì.","vi":"Anh ấy xuất thân hoàng tộc."},{"type":"simple","zh":"英国皇室的婚礼吸引了全世界的目光。","pinyin":"Yīngguó huángshì de hūnlǐ xīyǐnle quánshìjiè de mùguāng.","vi":"Đám cưới hoàng gia Anh thu hút sự chú ý của cả thế giới."},{"type":"compound","zh":"虽然她出身皇室，但是生活非常简朴。","pinyin":"Suīrán tā chūshēn huángshì, dànshì shēnghuó fēicháng jiǎnpǔ.","vi":"Tuy xuất thân hoàng gia nhưng cô ấy sống rất giản dị."}],"related":[{"hanzi":"王室","pinyin":"wángshì","vi":"vương thất"},{"hanzi":"皇族","pinyin":"huángzú","vi":"hoàng tộc"},{"hanzi":"皇家","pinyin":"huángjiā","vi":"hoàng gia"},{"hanzi":"贵族","pinyin":"guìzú","vi":"quý tộc"}]},{"id":"谎话","hanzi":"谎话","pinyin":"huǎnghuà","meaning_vi":"lời nói dối","explanation":"谎 (hoang – dối trá) + 话 (thoại – lời nói) → lời nói không thật; mang sắc thái khẩu ngữ.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🤥","examples":[{"type":"basic","zh":"你别说谎话。","pinyin":"Nǐ biéshuō huǎnghuà.","vi":"Bạn đừng nói dối."},{"type":"simple","zh":"他的谎话很快就被妈妈识破了。","pinyin":"Tā de huǎnghuà hěn kuài jiù bèi māma shípò le.","vi":"Lời nói dối của cậu bé nhanh chóng bị mẹ vạch trần."},{"type":"compound","zh":"一个人如果经常说谎话，就再也没人相信他了。","pinyin":"Yígerén rúguǒ jīngcháng shuō huǎnghuà, jiù zài yě méi rén xiāngxìn tā le.","vi":"Một người nếu thường xuyên nói dối thì sẽ không còn ai tin nữa."}],"related":[{"hanzi":"谎言","pinyin":"huǎngyán","vi":"lời dối trá"},{"hanzi":"假话","pinyin":"jiǎhuà","vi":"lời giả dối"},{"hanzi":"实话","pinyin":"shíhuà","vi":"lời thật"},{"hanzi":"撒谎","pinyin":"sāhuǎng","vi":"nói dối"}],"traditional":"謊話"},{"id":"谎言","hanzi":"谎言","pinyin":"huǎngyán","meaning_vi":"lời nói dối, lời dối trá","explanation":"谎 (hoang – dối trá) + 言 (ngôn – lời) → lời dối trá; sắc thái trang trọng, văn viết hơn 谎话.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🎭","examples":[{"type":"basic","zh":"这完全是谎言。","pinyin":"Zhè wánquán shì huǎngyán.","vi":"Đây hoàn toàn là lời dối trá."},{"type":"simple","zh":"时间终于揭穿了他的谎言。","pinyin":"Shíjiān zhōngyú jiēchuānle tā de huǎngyán.","vi":"Thời gian cuối cùng đã vạch trần lời dối trá của hắn."},{"type":"compound","zh":"即使是善意的谎言，有时也会伤害别人。","pinyin":"Jíshǐ shì shànyì de huǎngyán, yǒushí yě huì shānghài biérén.","vi":"Dù là lời nói dối thiện ý, đôi khi cũng làm tổn thương người khác."}],"related":[{"hanzi":"谎话","pinyin":"huǎnghuà","vi":"lời nói dối"},{"hanzi":"真相","pinyin":"zhēnxiàng","vi":"sự thật"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"揭穿","pinyin":"jiēchuān","vi":"vạch trần"}],"traditional":"謊言"},{"id":"晃","hanzi":"晃","pinyin":"huàng","meaning_vi":"lắc, lắc lư, đung đưa; la cà, lang thang","explanation":"晃 (hoảng – lắc, lóe sáng) → lắc qua lắc lại; đọc huǎng khi mang nghĩa lóe lên, vụt qua.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍃","examples":[{"type":"basic","zh":"别晃桌子。","pinyin":"Bié huàng zhuōzi.","vi":"Đừng lắc cái bàn."},{"type":"simple","zh":"风一吹，树枝就轻轻地晃起来。","pinyin":"Fēng yì chuī, shùzhī jiù qīngqīng de huàng qǐlái.","vi":"Gió vừa thổi, cành cây liền khẽ đung đưa."},{"type":"compound","zh":"因为船晃得太厉害，所以很多乘客都晕船了。","pinyin":"Yīnwèi chuán huàng de tài lìhai, suǒyǐ hěn duō chéngkè dōu yūnchuán le.","vi":"Vì thuyền lắc quá dữ nên nhiều hành khách bị say sóng."}],"related":[{"hanzi":"摇晃","pinyin":"yáohuàng","vi":"lắc lư"},{"hanzi":"晃动","pinyin":"huàngdòng","vi":"rung lắc"},{"hanzi":"晃悠","pinyin":"huàngyou","vi":"đung đưa"},{"hanzi":"摇摆","pinyin":"yáobǎi","vi":"đong đưa"}]},{"id":"晃荡","hanzi":"晃荡","pinyin":"huàngdang","meaning_vi":"lắc lư, đung đưa, la cà lang thang","explanation":"晃 (hoảng – lắc) + 荡 (đãng – dập dềnh) → lắc lư dập dềnh; khẩu ngữ còn chỉ đi lang thang không mục đích.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛶","examples":[{"type":"basic","zh":"秋千在晃荡。","pinyin":"Qiūqiān zài huàngdang.","vi":"Chiếc xích đu đang đung đưa."},{"type":"simple","zh":"他整天在街上晃荡，什么也不干。","pinyin":"Tā zhěngtiān zài jiēshang huàngdang, shénme yě bú gàn.","vi":"Cả ngày anh ta lang thang ngoài phố, chẳng làm gì cả."},{"type":"compound","zh":"虽然水桶装得很满，但是他走路时一点儿也没晃荡。","pinyin":"Suīrán shuǐtǒng zhuāng de hěn mǎn, dànshì tā zǒulù shí yìdiǎnr yě méi huàngdang.","vi":"Tuy xô nước đầy ắp nhưng lúc anh ấy bước đi nó chẳng hề lắc lư chút nào."}],"related":[{"hanzi":"晃","pinyin":"huàng","vi":"lắc"},{"hanzi":"摇晃","pinyin":"yáohuàng","vi":"lắc lư"},{"hanzi":"游荡","pinyin":"yóudàng","vi":"lang thang"},{"hanzi":"闲逛","pinyin":"xiánguàng","vi":"đi dạo chơi"}],"traditional":"晃蕩"},{"id":"回归","hanzi":"回归","pinyin":"huíguī","meaning_vi":"trở về, quay về, hồi quy","explanation":"回 (hồi – quay lại) + 归 (quy – trở về) → quay về nơi hoặc trạng thái ban đầu; trong thống kê là \"hồi quy\".","hsk_level":"7-9","tags":["dong-tu"],"image":"🔙","examples":[{"type":"basic","zh":"生活回归平静。","pinyin":"Shēnghuó huíguī píngjìng.","vi":"Cuộc sống trở lại bình yên."},{"type":"simple","zh":"很多年轻人选择回归乡村生活。","pinyin":"Hěn duō niánqīngrén xuǎnzé huíguī xiāngcūn shēnghuó.","vi":"Nhiều người trẻ chọn quay về cuộc sống thôn quê."},{"type":"compound","zh":"如果大家都遵守规则，交通秩序就能回归正常。","pinyin":"Rúguǒ dàjiā dōu zūnshǒu guīzé, jiāotōng zhìxù jiù néng huíguī zhèngcháng.","vi":"Nếu mọi người đều tuân thủ quy tắc thì trật tự giao thông sẽ trở lại bình thường."}],"related":[{"hanzi":"返回","pinyin":"fǎnhuí","vi":"quay về"},{"hanzi":"归来","pinyin":"guīlái","vi":"trở về"},{"hanzi":"回到","pinyin":"huídào","vi":"về đến"},{"hanzi":"回归分析","pinyin":"huíguīfēnxī","vi":"phân tích hồi quy"}],"traditional":"回歸"},{"id":"回扣","hanzi":"回扣","pinyin":"huíkòu","meaning_vi":"tiền hoa hồng, tiền lại quả","explanation":"回 (hồi – trả lại) + 扣 (khấu – khấu trừ) → khoản tiền trích lại cho người môi giới; thường chỉ tiền lại quả, hối lộ ngầm.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他收了回扣。","pinyin":"Tā shōule huíkòu.","vi":"Anh ta đã nhận tiền lại quả."},{"type":"simple","zh":"医生收取药品回扣是违法的。","pinyin":"Yīshēng shōuqǔ yàopǐn huíkòu shì wéifǎ de.","vi":"Bác sĩ nhận tiền lại quả từ thuốc là phạm pháp."},{"type":"compound","zh":"一旦被发现拿回扣，他就会被公司开除。","pinyin":"Yídàn bèi fāxiàn ná huíkòu, tā jiù huì bèi gōngsī kāichú.","vi":"Một khi bị phát hiện ăn tiền lại quả, anh ta sẽ bị công ty sa thải."}],"related":[{"hanzi":"佣金","pinyin":"yōngjīn","vi":"tiền hoa hồng"},{"hanzi":"贿赂","pinyin":"huìlù","vi":"hối lộ"},{"hanzi":"提成","pinyin":"tíchéng","vi":"tiền trích phần trăm"},{"hanzi":"红包","pinyin":"hóngbāo","vi":"phong bì"}]},{"id":"回馈","hanzi":"回馈","pinyin":"huíkuì","meaning_vi":"đền đáp, báo đáp, phản hồi","explanation":"回 (hồi – trả lại) + 馈 (quỹ – biếu tặng) → đáp lại, đền đáp ơn nghĩa; cũng dùng với nghĩa \"phản hồi\".","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🎁","examples":[{"type":"basic","zh":"我们要回馈社会。","pinyin":"Wǒmen yào huíkuì shèhuì.","vi":"Chúng ta phải đền đáp xã hội."},{"type":"simple","zh":"商场推出了回馈老顾客的优惠活动。","pinyin":"Shāngchǎng tuīchūle huíkuì lǎo gùkè de yōuhuì huódòng.","vi":"Trung tâm thương mại tung ra chương trình ưu đãi tri ân khách hàng cũ."},{"type":"compound","zh":"他小时候受过很多人帮助，所以现在想回馈家乡。","pinyin":"Tā xiǎoshíhou shòuguo hěn duō rén bāngzhù, suǒyǐ xiànzài xiǎng huíkuì jiāxiāng.","vi":"Hồi nhỏ anh ấy được nhiều người giúp đỡ nên giờ muốn đền đáp quê hương."}],"related":[{"hanzi":"回报","pinyin":"huíbào","vi":"báo đáp"},{"hanzi":"反馈","pinyin":"fǎnkuì","vi":"phản hồi"},{"hanzi":"报答","pinyin":"bàodá","vi":"đền đáp"},{"hanzi":"馈赠","pinyin":"kuìzèng","vi":"biếu tặng"}],"traditional":"回饋"},{"id":"回落","hanzi":"回落","pinyin":"huíluò","meaning_vi":"giảm trở lại, hạ xuống lại","explanation":"回 (hồi – trở lại) + 落 (lạc – rơi xuống) → sau khi tăng lại hạ xuống; hay dùng cho giá cả, mực nước.","hsk_level":"7-9","tags":["dong-tu"],"image":"📉","examples":[{"type":"basic","zh":"油价开始回落。","pinyin":"Yóujià kāishǐ huíluò.","vi":"Giá xăng bắt đầu giảm trở lại."},{"type":"simple","zh":"雨停以后，河水慢慢回落了。","pinyin":"Yǔ tíng yǐhòu, héshuǐ mànmàn huíluò le.","vi":"Sau khi mưa tạnh, nước sông từ từ rút xuống."},{"type":"compound","zh":"虽然房价上个月涨了不少，但是这个月已经回落。","pinyin":"Suīrán fángjià shànggeyuè zhǎngle bùshǎo, dànshì zhè geyuè yǐjīng huíluò.","vi":"Tuy giá nhà tháng trước tăng khá nhiều nhưng tháng này đã giảm trở lại."}],"related":[{"hanzi":"回升","pinyin":"huíshēng","vi":"tăng trở lại"},{"hanzi":"下跌","pinyin":"xiàdiē","vi":"sụt giảm"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"giảm xuống"},{"hanzi":"降落","pinyin":"jiàngluò","vi":"hạ xuống"}]},{"id":"回升","hanzi":"回升","pinyin":"huíshēng","meaning_vi":"tăng trở lại, phục hồi","explanation":"回 (hồi – trở lại) + 升 (thăng – đi lên) → sau khi giảm lại tăng lên.","hsk_level":"7-9","tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"气温回升了。","pinyin":"Qìwēn huíshēng le.","vi":"Nhiệt độ đã tăng trở lại."},{"type":"simple","zh":"进入三月，各地气温逐渐回升。","pinyin":"Jìnrù Sānyuè, gèdì qìwēn zhújiàn huíshēng.","vi":"Sang tháng ba, nhiệt độ các nơi dần ấm trở lại."},{"type":"compound","zh":"只要消费者信心恢复，经济就会慢慢回升。","pinyin":"Zhǐyào xiāofèizhě xìnxīn huīfù, jīngjì jiù huì mànmàn huíshēng.","vi":"Chỉ cần niềm tin người tiêu dùng hồi phục, kinh tế sẽ dần đi lên trở lại."}],"related":[{"hanzi":"回落","pinyin":"huíluò","vi":"giảm trở lại"},{"hanzi":"上升","pinyin":"shàngshēng","vi":"tăng lên"},{"hanzi":"反弹","pinyin":"fǎntán","vi":"bật tăng"},{"hanzi":"复苏","pinyin":"fùsū","vi":"phục hồi"}]},{"id":"回首","hanzi":"回首","pinyin":"huíshǒu","meaning_vi":"ngoảnh lại, nhìn lại, hồi tưởng","explanation":"回 (hồi – quay lại) + 首 (thủ – đầu) → quay đầu nhìn lại; nghĩa bóng là nhớ lại quá khứ, dùng trong văn viết.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"回首往事，他笑了。","pinyin":"Huíshǒu wǎngshì, tā xiào le.","vi":"Nhìn lại chuyện cũ, anh ấy mỉm cười."},{"type":"simple","zh":"回首过去十年，我们经历了很多变化。","pinyin":"Huíshǒu guòqù shí nián, wǒmen jīnglìle hěn duō biànhuà.","vi":"Nhìn lại mười năm qua, chúng tôi đã trải qua rất nhiều thay đổi."},{"type":"compound","zh":"虽然那段日子很苦，但是现在回首起来却很温暖。","pinyin":"Suīrán nà duàn rìzi hěn kǔ, dànshì xiànzài huíshǒu qǐlái què hěn wēnnuǎn.","vi":"Tuy những ngày đó rất khổ nhưng giờ nhớ lại thì lại thấy ấm áp."}],"related":[{"hanzi":"回顾","pinyin":"huígù","vi":"nhìn lại"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi ức"},{"hanzi":"回头","pinyin":"huítóu","vi":"quay đầu"},{"hanzi":"往事","pinyin":"wǎngshì","vi":"chuyện cũ"}]},{"id":"回味","hanzi":"回味","pinyin":"huíwèi","meaning_vi":"dư vị; nghiền ngẫm, nhớ lại","explanation":"回 (hồi – trở lại) + 味 (vị – mùi vị) → vị còn đọng lại sau khi ăn uống; nghĩa bóng là ngẫm lại, nhớ lại điều đã trải qua.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍵","examples":[{"type":"basic","zh":"这茶回味无穷。","pinyin":"Zhè chá huíwèiwúqióng.","vi":"Trà này dư vị mãi không dứt."},{"type":"simple","zh":"他一直在回味昨晚那场精彩的演出。","pinyin":"Tā yìzhí zài huíwèi zuówǎn nà chǎng jīngcǎi de yǎnchū.","vi":"Anh ấy cứ mãi nhớ lại buổi biểu diễn tuyệt vời tối qua."},{"type":"compound","zh":"虽然那顿饭已经过去很久，但是我至今还在回味。","pinyin":"Suīrán nà dùn fàn yǐjīng guòqù hěn jiǔ, dànshì wǒ zhìjīn hái zài huíwèi.","vi":"Tuy bữa ăn đó đã lâu rồi nhưng đến giờ tôi vẫn còn nhớ hương vị."}],"related":[{"hanzi":"余味","pinyin":"yúwèi","vi":"dư vị"},{"hanzi":"回想","pinyin":"huíxiǎng","vi":"nhớ lại"},{"hanzi":"品味","pinyin":"pǐnwèi","vi":"thưởng thức"},{"hanzi":"回味无穷","pinyin":"huíwèiwúqióng","vi":"dư vị khó quên"}]},{"id":"汇聚","hanzi":"汇聚","pinyin":"huìjù","meaning_vi":"hội tụ, tụ họp, quy tụ","explanation":"汇 (hối – dòng nước đổ về) + 聚 (tụ – tụ lại) → nhiều nguồn đổ về một chỗ, hội tụ lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"人群汇聚在广场。","pinyin":"Rénqún huìjù zài guǎngchǎng.","vi":"Đám đông tụ họp ở quảng trường."},{"type":"simple","zh":"这次大会汇聚了全国各地的专家。","pinyin":"Zhè cì dàhuì huìjùle quánguó gèdì de zhuānjiā.","vi":"Đại hội lần này quy tụ chuyên gia khắp cả nước."},{"type":"compound","zh":"虽然每个人的力量很小，但是汇聚起来就很强大。","pinyin":"Suīrán měigerén de lìliàng hěn xiǎo, dànshì huìjù qǐlái jiù hěn qiángdà.","vi":"Tuy sức mỗi người rất nhỏ nhưng gộp lại thì rất mạnh."}],"related":[{"hanzi":"汇集","pinyin":"huìjí","vi":"tập hợp"},{"hanzi":"聚集","pinyin":"jùjí","vi":"tụ tập"},{"hanzi":"汇合","pinyin":"huìhé","vi":"hợp lưu"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"}],"traditional":"匯聚"},{"id":"会场","hanzi":"会场","pinyin":"huìchǎng","meaning_vi":"hội trường, nơi họp","explanation":"会 (hội – họp) + 场 (trường – nơi chốn) → nơi tổ chức hội họp.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏛️","examples":[{"type":"basic","zh":"会场里坐满了人。","pinyin":"Huìchǎng lǐ zuò mǎnle rén.","vi":"Hội trường đã kín người ngồi."},{"type":"simple","zh":"工作人员正在布置明天的会场。","pinyin":"Gōngzuò rényuán zhèngzài bùzhì míngtiān de huìchǎng.","vi":"Nhân viên đang bố trí hội trường cho ngày mai."},{"type":"compound","zh":"如果你提前到会场，就可以选个好位置。","pinyin":"Rúguǒ nǐ tíqián dào huìchǎng, jiù kěyǐ xuǎn ge hǎo wèizhì.","vi":"Nếu bạn đến hội trường sớm thì có thể chọn được chỗ tốt."}],"related":[{"hanzi":"会议","pinyin":"huìyì","vi":"cuộc họp"},{"hanzi":"场地","pinyin":"chǎngdì","vi":"địa điểm"},{"hanzi":"礼堂","pinyin":"lǐtáng","vi":"lễ đường"},{"hanzi":"会议室","pinyin":"huìyìshì","vi":"phòng họp"}],"traditional":"會場"},{"id":"会面","hanzi":"会面","pinyin":"huìmiàn","meaning_vi":"gặp mặt, gặp gỡ","explanation":"会 (hội – gặp) + 面 (diện – mặt) → gặp mặt nhau, thường mang sắc thái trang trọng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"两国领导人会面了。","pinyin":"Liǎngguó lǐngdǎorén huìmiàn le.","vi":"Lãnh đạo hai nước đã gặp mặt."},{"type":"simple","zh":"我们约好下午三点在咖啡馆会面。","pinyin":"Wǒmen yuē hǎo xiàwǔ sān diǎn zài kāfēiguǎn huìmiàn.","vi":"Chúng tôi hẹn gặp nhau ở quán cà phê lúc ba giờ chiều."},{"type":"compound","zh":"因为航班延误，所以原定的会面只好推迟。","pinyin":"Yīnwèi hángbān yánwù, suǒyǐ yuándìng de huìmiàn zhǐhǎo tuīchí.","vi":"Vì chuyến bay bị trễ nên cuộc gặp dự định đành phải lùi lại."}],"related":[{"hanzi":"见面","pinyin":"jiànmiàn","vi":"gặp mặt"},{"hanzi":"会见","pinyin":"huìjiàn","vi":"tiếp kiến"},{"hanzi":"会晤","pinyin":"huìwù","vi":"hội đàm"},{"hanzi":"约会","pinyin":"yuēhuì","vi":"hẹn hò"}],"traditional":"會面"},{"id":"会意","hanzi":"会意","pinyin":"huìyì","meaning_vi":"hiểu ý, lĩnh hội; (chữ) hội ý","explanation":"会 (hội – hiểu) + 意 (ý – ý tứ) → hiểu ý mà không cần nói ra; cũng là phép \"hội ý\" trong lục thư, ghép nghĩa các bộ phận như 休 = 人 + 木.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他会意地点点头。","pinyin":"Tā huìyì dediǎn diǎntóu.","vi":"Anh ấy hiểu ý, khẽ gật đầu."},{"type":"simple","zh":"她看了我一眼，我立刻会意了。","pinyin":"Tā kànle wǒ yìyǎn, wǒ lìkè huìyì le.","vi":"Cô ấy liếc nhìn tôi một cái, tôi lập tức hiểu ý."},{"type":"compound","zh":"虽然老师什么也没说，但是同学们都会意地笑了。","pinyin":"Suīrán lǎoshī shénme yě méi shuō, dànshì tóngxuémen dōu huìyì de xiào le.","vi":"Tuy thầy giáo không nói gì nhưng các bạn đều hiểu ý mà bật cười."}],"related":[{"hanzi":"领会","pinyin":"lǐnghuì","vi":"lĩnh hội"},{"hanzi":"会心","pinyin":"huìxīn","vi":"hiểu ý ngầm"},{"hanzi":"意会","pinyin":"yìhuì","vi":"ngầm hiểu"},{"hanzi":"形声","pinyin":"xíngshēng","vi":"chữ hình thanh"}],"traditional":"會意"},{"id":"会诊","hanzi":"会诊","pinyin":"huìzhěn","meaning_vi":"hội chẩn","explanation":"会 (hội – họp) + 诊 (chẩn – khám bệnh) → nhiều bác sĩ cùng khám và bàn bạc để chẩn đoán.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"专家正在会诊。","pinyin":"Zhuānjiā zhèngzài huìzhěn.","vi":"Các chuyên gia đang hội chẩn."},{"type":"simple","zh":"医院请了三位专家为他会诊。","pinyin":"Yīyuàn qǐngle sān wèi zhuānjiā wèi tā huìzhěn.","vi":"Bệnh viện mời ba chuyên gia hội chẩn cho anh ấy."},{"type":"compound","zh":"因为病情很复杂，所以医院决定组织专家会诊。","pinyin":"Yīnwèi bìngqíng hěn fùzá, suǒyǐ yīyuàn juédìng zǔzhī zhuānjiā huìzhěn.","vi":"Vì bệnh tình rất phức tạp nên bệnh viện quyết định tổ chức hội chẩn chuyên gia."}],"related":[{"hanzi":"诊断","pinyin":"zhěnduàn","vi":"chẩn đoán"},{"hanzi":"门诊","pinyin":"ménzhěn","vi":"khám ngoại trú"},{"hanzi":"确诊","pinyin":"quèzhěn","vi":"chẩn đoán xác định"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"}],"traditional":"會診"},{"id":"魂","hanzi":"魂","pinyin":"hún","meaning_vi":"hồn, linh hồn, tinh thần","explanation":"魂 (hồn – linh hồn) → phần tinh thần của con người; nghĩa bóng là cái hồn, tinh thần cốt lõi của sự vật.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"👻","examples":[{"type":"basic","zh":"他吓得丢了魂。","pinyin":"Tā xià de diūle hún.","vi":"Anh ta sợ đến mất hồn."},{"type":"simple","zh":"这首歌唱出了民族的魂。","pinyin":"Zhè shǒu gēchàng chūle mínzú de hún.","vi":"Bài hát này nói lên linh hồn của dân tộc."},{"type":"compound","zh":"自从见了她一面，他就像丢了魂一样。","pinyin":"Zìcóng jiànle tā yímiàn, tā jiù xiàng diūle hún yíyàng.","vi":"Từ khi gặp cô ấy một lần, anh ta cứ như người mất hồn."}],"related":[{"hanzi":"灵魂","pinyin":"línghún","vi":"linh hồn"},{"hanzi":"魂魄","pinyin":"húnpò","vi":"hồn phách"},{"hanzi":"鬼魂","pinyin":"guǐhún","vi":"hồn ma"},{"hanzi":"精神","pinyin":"jīngshén","vi":"tinh thần"}]},{"id":"豁","hanzi":"豁","pinyin":"huō","meaning_vi":"rách toác, sứt mẻ; liều, bất chấp","explanation":"豁 (khoát – rộng mở, toác ra) → đọc huō: rách toác, liều bỏ ra; đọc huò trong 豁达, 豁然 (rộng rãi, thông suốt).","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"衣服豁了个口子。","pinyin":"Yīfu huōle ge kǒuzi.","vi":"Áo bị toạc một đường."},{"type":"simple","zh":"为了救孩子，他豁上了性命。","pinyin":"Wèile jiù háizi, tā huō shàngle xìngmìng.","vi":"Để cứu đứa trẻ, anh ấy liều cả tính mạng."},{"type":"compound","zh":"虽然嘴唇豁了个口子，但是他还坚持比赛。","pinyin":"Suīrán zuǐchún huōle ge kǒuzi, dànshì tā hái jiānchí bǐsài.","vi":"Tuy môi bị rách một vết nhưng anh ấy vẫn kiên trì thi đấu."}],"related":[{"hanzi":"豁出去","pinyin":"huōchuqu","vi":"liều một phen"},{"hanzi":"豁口","pinyin":"huōkǒu","vi":"chỗ sứt mẻ"},{"hanzi":"豁达","pinyin":"huòdá","vi":"phóng khoáng"},{"hanzi":"豁然开朗","pinyin":"huòránkāilǎng","vi":"bỗng sáng tỏ"}]},{"id":"豁出去","hanzi":"豁出去","pinyin":"huōchuqu","meaning_vi":"liều một phen, bất chấp tất cả","explanation":"豁 (khoát – toác ra, bỏ ra) + 出去 (ra ngoài) → buông bỏ hết mà liều làm, bất chấp hậu quả.","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"我今天豁出去了！","pinyin":"Wǒ jīntiān huōchuqu le!","vi":"Hôm nay tôi liều một phen rồi!"},{"type":"simple","zh":"为了这次比赛，他决定豁出去拼一把。","pinyin":"Wèile zhè cì bǐsài, tā juédìng huōchuqu pīn yì bǎ.","vi":"Vì cuộc thi này, anh ấy quyết định liều mình đánh cược một phen."},{"type":"compound","zh":"既然已经没有退路，那就豁出去试一试吧。","pinyin":"Jìrán yǐjīng méiyǒu tuìlù, nà jiù huōchuqu shìyishì ba.","vi":"Đã không còn đường lui thì cứ liều thử một lần đi."}],"related":[{"hanzi":"拼命","pinyin":"pīnmìng","vi":"liều mạng"},{"hanzi":"孤注一掷","pinyin":"gūzhùyízhì","vi":"được ăn cả ngã về không"},{"hanzi":"豁","pinyin":"huō","vi":"liều bỏ ra"},{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"mạo hiểm"}]},{"id":"活儿","hanzi":"活儿","pinyin":"huór","meaning_vi":"việc, công việc (khẩu ngữ)","explanation":"活 (hoạt – sống, làm lụng) + 儿 (nhi – hậu tố) → khẩu ngữ chỉ công việc, nhất là việc chân tay.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"今天活儿很多。","pinyin":"Jīntiān huór hěn duō.","vi":"Hôm nay nhiều việc lắm."},{"type":"simple","zh":"他干活儿又快又仔细。","pinyin":"Tā gànhuór yòu kuài yòu zǐxì.","vi":"Anh ấy làm việc vừa nhanh vừa cẩn thận."},{"type":"compound","zh":"只要把手上的活儿干完，你就可以下班了。","pinyin":"Zhǐyào bǎshǒu shang de huór gàn wán, nǐ jiù kěyǐ xiàbān le.","vi":"Chỉ cần làm xong việc đang có trong tay là bạn có thể tan ca."}],"related":[{"hanzi":"干活儿","pinyin":"gànhuór","vi":"làm việc"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"công việc"},{"hanzi":"农活儿","pinyin":"nónghuór","vi":"việc đồng áng"},{"hanzi":"零活儿","pinyin":"línghuór","vi":"việc vặt"}],"traditional":"活兒"},{"id":"活期","hanzi":"活期","pinyin":"huóqī","meaning_vi":"không kỳ hạn (tiền gửi)","explanation":"活 (hoạt – linh hoạt) + 期 (kỳ – kỳ hạn) → kỳ hạn linh hoạt, tức tiền gửi không kỳ hạn, rút lúc nào cũng được.","hsk_level":"7-9","tags":["tinh-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"我存的是活期。","pinyin":"Wǒ cún de shì huóqī.","vi":"Tôi gửi không kỳ hạn."},{"type":"simple","zh":"活期存款的利息比定期低很多。","pinyin":"Huóqī cúnkuǎn de lìxī bǐ dìngqī dī hěn duō.","vi":"Lãi tiền gửi không kỳ hạn thấp hơn có kỳ hạn nhiều."},{"type":"compound","zh":"如果你随时要用钱，就最好存活期。","pinyin":"Rúguǒ nǐ suíshí yào yòngqián, jiù zuìhǎo cún huóqī.","vi":"Nếu bạn có thể cần tiền bất cứ lúc nào thì tốt nhất gửi không kỳ hạn."}],"related":[{"hanzi":"定期","pinyin":"dìngqī","vi":"có kỳ hạn"},{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"},{"hanzi":"利息","pinyin":"lìxī","vi":"tiền lãi"},{"hanzi":"储蓄","pinyin":"chǔxù","vi":"tiết kiệm"}]},{"id":"火暴","hanzi":"火暴","pinyin":"huǒbào","meaning_vi":"nóng nảy; sôi động, đắt khách","explanation":"火 (hỏa – lửa) + 暴 (bạo – dữ dội) → nóng như lửa: chỉ tính khí nóng nảy hoặc cảnh buôn bán, không khí rất sôi động (cũng viết 火爆).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"他脾气很火暴。","pinyin":"Tā píqi hěn huǒbào.","vi":"Tính anh ấy rất nóng nảy."},{"type":"simple","zh":"这家新开的餐厅生意特别火暴。","pinyin":"Zhè jiā xīn kāi de cāntīng shēngyi tèbié huǒbào.","vi":"Nhà hàng mới mở này buôn bán cực kỳ đắt khách."},{"type":"compound","zh":"虽然他性子火暴，但是心地非常善良。","pinyin":"Suīrán tā xìngzi huǒbào, dànshì xīndì fēicháng shànliáng.","vi":"Tuy tính anh ấy nóng nảy nhưng tấm lòng rất lương thiện."}],"related":[{"hanzi":"火爆","pinyin":"huǒbào","vi":"sôi động"},{"hanzi":"暴躁","pinyin":"bàozào","vi":"nóng nảy"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"},{"hanzi":"红火","pinyin":"hónghuo","vi":"thịnh vượng"}]},{"id":"火锅","hanzi":"火锅","pinyin":"huǒguō","meaning_vi":"lẩu","explanation":"火 (hỏa – lửa) + 锅 (oa – nồi) → nồi đặt trên lửa để nhúng đồ ăn, tức món lẩu.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"冬天最适合吃火锅。","pinyin":"Dōngtiān zuì shìhé chī huǒguō.","vi":"Mùa đông hợp nhất là ăn lẩu."},{"type":"simple","zh":"周末我们一家人去吃四川火锅。","pinyin":"Zhōumò wǒmen yìjiārén qù chī Sìchuān huǒguō.","vi":"Cuối tuần cả nhà tôi đi ăn lẩu Tứ Xuyên."},{"type":"compound","zh":"虽然重庆火锅很辣，但是我每次都吃得很开心。","pinyin":"Suīrán Chóngqìng huǒguō hěn là, dànshì wǒ měi cì dōu chī de hěn kāixīn.","vi":"Tuy lẩu Trùng Khánh rất cay nhưng lần nào tôi cũng ăn rất vui."}],"related":[{"hanzi":"锅底","pinyin":"guōdǐ","vi":"nước lẩu"},{"hanzi":"涮羊肉","pinyin":"shuànyángròu","vi":"lẩu nhúng thịt cừu"},{"hanzi":"麻辣","pinyin":"málà","vi":"cay tê"},{"hanzi":"火锅店","pinyin":"huǒguōdiàn","vi":"quán lẩu"}],"traditional":"火鍋"},{"id":"火花","hanzi":"火花","pinyin":"huǒhuā","meaning_vi":"tia lửa, tia sáng","explanation":"火 (hỏa – lửa) + 花 (hoa – bông hoa) → những đốm lửa bắn ra như hoa; nghĩa bóng là tia sáng của tư duy, tình cảm.","hsk_level":"7-9","tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"电线冒出了火花。","pinyin":"Diànxiàn mào chūle huǒhuā.","vi":"Dây điện tóe ra tia lửa."},{"type":"simple","zh":"两个人的讨论碰撞出了思想的火花。","pinyin":"Liǎng ge rén de tǎolùn pèngzhuàng chūle sīxiǎng de huǒhuā.","vi":"Cuộc thảo luận của hai người đã nảy ra những tia sáng tư tưởng."},{"type":"compound","zh":"一旦电线出现火花，就要马上切断电源。","pinyin":"Yídàn diànxiàn chūxiàn huǒhuā, jiùyào mǎshàng qiēduàn diànyuán.","vi":"Một khi dây điện tóe lửa thì phải ngắt nguồn điện ngay."}],"related":[{"hanzi":"火星","pinyin":"huǒxīng","vi":"đốm lửa"},{"hanzi":"火焰","pinyin":"huǒyàn","vi":"ngọn lửa"},{"hanzi":"灵感","pinyin":"línggǎn","vi":"cảm hứng"},{"hanzi":"闪光","pinyin":"shǎnguāng","vi":"ánh chớp"}]},{"id":"火辣辣","hanzi":"火辣辣","pinyin":"huǒlàlà","meaning_vi":"nóng bỏng, rát bỏng, nóng mặt","explanation":"火 (hỏa – lửa) + 辣辣 (lạt – cay, rát) → nóng rát như bị lửa đốt; tả nắng gắt, vết thương rát hoặc cảm giác xấu hổ nóng mặt.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌶️","examples":[{"type":"basic","zh":"太阳火辣辣的。","pinyin":"Tàiyáng huǒlàlà de.","vi":"Mặt trời nóng như thiêu."},{"type":"simple","zh":"被他批评后，我的脸火辣辣的。","pinyin":"Bèi tā pīpíng hòu, wǒ de liǎn huǒlàlà de.","vi":"Sau khi bị anh ấy phê bình, mặt tôi nóng bừng."},{"type":"compound","zh":"虽然伤口已经上了药，但是还是火辣辣地疼。","pinyin":"Suīrán shāngkǒu yǐjīng shàngle yào, dànshì háishi huǒlàlà de téng.","vi":"Tuy vết thương đã bôi thuốc nhưng vẫn đau rát."}],"related":[{"hanzi":"热辣辣","pinyin":"rèlàlà","vi":"nóng hừng hực"},{"hanzi":"火热","pinyin":"huǒrè","vi":"nóng bỏng"},{"hanzi":"滚烫","pinyin":"gǔntàng","vi":"nóng bỏng tay"},{"hanzi":"辣","pinyin":"là","vi":"cay"}]},{"id":"火速","hanzi":"火速","pinyin":"huǒsù","meaning_vi":"gấp rút, cấp tốc","explanation":"火 (hỏa – lửa) + 速 (tốc – nhanh) → nhanh như lửa cháy, cấp tốc.","hsk_level":"7-9","tags":["pho-tu"],"image":"⚡","examples":[{"type":"basic","zh":"请火速赶来！","pinyin":"Qǐng huǒsù gǎnlái!","vi":"Xin hãy đến gấp!"},{"type":"simple","zh":"消防队员接到电话后火速出发。","pinyin":"Xiāofáng duìyuán jiēdào diànhuà hòu huǒsù chūfā.","vi":"Lính cứu hỏa nhận điện thoại xong liền xuất phát cấp tốc."},{"type":"compound","zh":"一旦发现险情，救援队就会火速赶到现场。","pinyin":"Yídàn fāxiàn xiǎnqíng, jiùyuánduì jiù huì huǒsù gǎndào xiànchǎng.","vi":"Một khi phát hiện tình huống nguy hiểm, đội cứu hộ sẽ cấp tốc đến hiện trường."}],"related":[{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"},{"hanzi":"急速","pinyin":"jísù","vi":"cấp tốc"},{"hanzi":"立即","pinyin":"lìjí","vi":"lập tức"},{"hanzi":"飞速","pinyin":"fēisù","vi":"nhanh như bay"}]},{"id":"伙食","hanzi":"伙食","pinyin":"huǒshí","meaning_vi":"bữa ăn, cơm nước (tập thể)","explanation":"伙 (hỏa – nhóm người, bếp chung) + 食 (thực – ăn) → đồ ăn của bếp tập thể; chỉ chuyện cơm nước hằng ngày.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍱","examples":[{"type":"basic","zh":"学校伙食不错。","pinyin":"Xuéxiào huǒshí búcuò.","vi":"Cơm nước ở trường khá ổn."},{"type":"simple","zh":"公司每月给员工发伙食补贴。","pinyin":"Gōngsī měiyuè gěi yuángōng fā huǒshí bǔtiē.","vi":"Công ty hàng tháng phát trợ cấp tiền ăn cho nhân viên."},{"type":"compound","zh":"因为工地伙食太差，所以工人们都自己做饭。","pinyin":"Yīnwèi gōngdì huǒshí tài chà, suǒyǐ gōngrénmen dōu zìjǐ zuòfàn.","vi":"Vì cơm nước ở công trường quá tệ nên công nhân đều tự nấu ăn."}],"related":[{"hanzi":"饭菜","pinyin":"fàncài","vi":"cơm canh"},{"hanzi":"食堂","pinyin":"shítáng","vi":"nhà ăn"},{"hanzi":"伙食费","pinyin":"huǒshífèi","vi":"tiền ăn"},{"hanzi":"饮食","pinyin":"yǐnshí","vi":"ăn uống"}]},{"id":"或多或少","hanzi":"或多或少","pinyin":"huòduōhuòshǎo","meaning_vi":"ít nhiều, nhiều hay ít","explanation":"或 (hoặc) + 多 (đa – nhiều) + 或 (hoặc) + 少 (thiểu – ít) → hoặc nhiều hoặc ít, tức là ít nhiều đều có.","hsk_level":"7-9","tags":["pho-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"人人或多或少有缺点。","pinyin":"Rénrén huòduōhuòshǎo yǒu quēdiǎn.","vi":"Ai cũng ít nhiều có khuyết điểm."},{"type":"simple","zh":"每个人对未来或多或少都有些担心。","pinyin":"Měigerén duì wèilái huòduōhuòshǎo dōu yǒuxiē dānxīn.","vi":"Ai cũng ít nhiều có chút lo lắng về tương lai."},{"type":"compound","zh":"虽然他嘴上不承认，但是心里或多或少有点后悔。","pinyin":"Suīrán tā zuǐ shang bù chéngrèn, dànshì xīnli huòduōhuòshǎo yǒudiǎn hòuhuǐ.","vi":"Tuy ngoài miệng không thừa nhận nhưng trong lòng anh ấy ít nhiều cũng hối hận."}],"related":[{"hanzi":"多多少少","pinyin":"duōduōshǎoshǎo","vi":"ít nhiều"},{"hanzi":"多少","pinyin":"duōshǎo","vi":"bao nhiêu, ít nhiều"},{"hanzi":"有些","pinyin":"yǒuxiē","vi":"có phần"},{"hanzi":"稍微","pinyin":"shāowēi","vi":"hơi, chút ít"}]},{"id":"货车","hanzi":"货车","pinyin":"huòchē","meaning_vi":"xe tải, xe chở hàng","explanation":"货 (hóa – hàng hóa) + 车 (xa – xe) → xe chở hàng.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚚","examples":[{"type":"basic","zh":"一辆货车停在门口。","pinyin":"Yí liàng huòchē tíng zài ménkǒu.","vi":"Một chiếc xe tải đỗ trước cửa."},{"type":"simple","zh":"这条路晚上禁止大货车通行。","pinyin":"Zhè tiáo lù wǎnshang jìnzhǐ dà huòchē tōngxíng.","vi":"Con đường này cấm xe tải lớn lưu thông vào buổi tối."},{"type":"compound","zh":"因为货车超载，所以被交警拦了下来。","pinyin":"Yīnwèi huòchē chāozài, suǒyǐ bèi jiāojǐng lánle xiàlái.","vi":"Vì xe tải chở quá tải nên bị cảnh sát giao thông chặn lại."}],"related":[{"hanzi":"卡车","pinyin":"kǎchē","vi":"xe tải"},{"hanzi":"货物","pinyin":"huòwù","vi":"hàng hóa"},{"hanzi":"客车","pinyin":"kèchē","vi":"xe khách"},{"hanzi":"司机","pinyin":"sījī","vi":"tài xế"}],"traditional":"貨車"},{"id":"货物","hanzi":"货物","pinyin":"huòwù","meaning_vi":"hàng hóa","explanation":"货 (hóa – hàng) + 物 (vật – đồ vật) → hàng hóa dùng để mua bán, vận chuyển.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📦","examples":[{"type":"basic","zh":"货物已经发出了。","pinyin":"Huòwù yǐjīng fāchū le.","vi":"Hàng đã được gửi đi rồi."},{"type":"simple","zh":"工人们正在把货物搬上轮船。","pinyin":"Gōngrénmen zhèngzài bǎ huòwù bān shàng lúnchuán.","vi":"Công nhân đang chuyển hàng lên tàu thủy."},{"type":"compound","zh":"如果货物在运输中损坏，就由快递公司赔偿。","pinyin":"Rúguǒ huòwù zài yùnshū zhōng sǔnhuài, jiù yóu kuàidì gōngsī péicháng.","vi":"Nếu hàng hóa bị hư hỏng trong quá trình vận chuyển thì công ty chuyển phát sẽ bồi thường."}],"related":[{"hanzi":"商品","pinyin":"shāngpǐn","vi":"hàng hóa"},{"hanzi":"货车","pinyin":"huòchē","vi":"xe tải"},{"hanzi":"物品","pinyin":"wùpǐn","vi":"đồ vật"},{"hanzi":"运货","pinyin":"yùnhuò","vi":"chở hàng"}],"traditional":"貨物"},{"id":"祸害","hanzi":"祸害","pinyin":"huòhài","meaning_vi":"tai họa, mối họa; làm hại, phá hại","explanation":"祸 (họa – tai họa) + 害 (hại – làm hại) → điều hoặc kẻ gây tai họa; cũng dùng làm động từ \"làm hại\".","hsk_level":"7-9","tags":["danh-tu"],"image":"☠️","examples":[{"type":"basic","zh":"老鼠祸害庄稼。","pinyin":"Lǎoshǔ huòhài zhuāngjia.","vi":"Chuột phá hại mùa màng."},{"type":"simple","zh":"毒品是危害社会的一大祸害。","pinyin":"Dúpǐn shì wēihài shèhuì de yí dà huòhài.","vi":"Ma túy là một mối họa lớn gây hại cho xã hội."},{"type":"compound","zh":"如果不及时治理污染，就会祸害子孙后代。","pinyin":"Rúguǒ bù jíshí zhìlǐ wūrǎn, jiù huì huòhài zǐsūn hòudài.","vi":"Nếu không kịp thời xử lý ô nhiễm thì sẽ gây hại cho con cháu đời sau."}],"related":[{"hanzi":"灾祸","pinyin":"zāihuò","vi":"tai họa"},{"hanzi":"危害","pinyin":"wēihài","vi":"nguy hại"},{"hanzi":"祸根","pinyin":"huògēn","vi":"mầm họa"},{"hanzi":"损害","pinyin":"sǔnhài","vi":"tổn hại"}],"traditional":"禍害"},{"id":"霍乱","hanzi":"霍乱","pinyin":"huòluàn","meaning_vi":"bệnh tả, dịch tả","explanation":"霍 (hoắc – nhanh, đột ngột) + 乱 (loạn – rối loạn) → bệnh phát đột ngột gây rối loạn tiêu hóa nặng, tức dịch tả.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🦠","examples":[{"type":"basic","zh":"霍乱是一种传染病。","pinyin":"Huòluàn shì yì zhǒng chuánrǎnbìng.","vi":"Bệnh tả là một loại bệnh truyền nhiễm."},{"type":"simple","zh":"洪水过后，当地爆发了霍乱疫情。","pinyin":"Hóngshuǐ guòhòu, dāngdì bàofāle huòluàn yìqíng.","vi":"Sau trận lũ, địa phương bùng phát dịch tả."},{"type":"compound","zh":"如果饮用水不干净，就容易感染霍乱。","pinyin":"Rúguǒ yǐnyòngshuǐ bù gānjìng, jiù róngyì gǎnrǎn huòluàn.","vi":"Nếu nước uống không sạch thì dễ nhiễm bệnh tả."}],"related":[{"hanzi":"传染病","pinyin":"chuánrǎnbìng","vi":"bệnh truyền nhiễm"},{"hanzi":"瘟疫","pinyin":"wēnyì","vi":"ôn dịch"},{"hanzi":"疫苗","pinyin":"yìmiáo","vi":"vắc-xin"},{"hanzi":"腹泻","pinyin":"fùxiè","vi":"tiêu chảy"}],"traditional":"霍亂"},{"id":"肌肤","hanzi":"肌肤","pinyin":"jīfū","meaning_vi":"da thịt, làn da","explanation":"肌 (cơ – cơ thịt) + 肤 (phu – da) → da thịt, làn da; thường dùng trong văn viết.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧴","examples":[{"type":"basic","zh":"她肌肤白皙。","pinyin":"Tā jīfū báixī.","vi":"Làn da cô ấy trắng mịn."},{"type":"simple","zh":"冬天要注意保护肌肤，防止干燥。","pinyin":"Dōngtiān yào zhùyì bǎohù jīfū, fángzhǐ gānzào.","vi":"Mùa đông cần chú ý bảo vệ làn da, tránh bị khô."},{"type":"compound","zh":"如果长时间晒太阳，肌肤就容易变黑。","pinyin":"Rúguǒ cháng shíjiān shàitàiyáng, jīfū jiù róngyì biànhēi.","vi":"Nếu phơi nắng lâu thì da dễ bị đen."}],"related":[{"hanzi":"皮肤","pinyin":"pífū","vi":"da"},{"hanzi":"肌肉","pinyin":"jīròu","vi":"cơ bắp"},{"hanzi":"护肤","pinyin":"hùfū","vi":"dưỡng da"},{"hanzi":"肤色","pinyin":"fūsè","vi":"màu da"}],"traditional":"肌膚"},{"id":"积","hanzi":"积","pinyin":"jī","meaning_vi":"tích lũy, dồn lại, đọng lại; (toán) tích","explanation":"积 (tích – chất chứa) → dồn lại dần dần, tích lũy; trong toán học là \"tích\" của phép nhân.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"桌上积了灰。","pinyin":"Zhuō shang jīle huī.","vi":"Trên bàn bám đầy bụi."},{"type":"simple","zh":"他每个月都积下一点钱。","pinyin":"Tā měi geyuè dōu jī xià yìdiǎn qián.","vi":"Tháng nào anh ấy cũng dành dụm được chút tiền."},{"type":"compound","zh":"如果问题积得太多，就会越来越难解决。","pinyin":"Rúguǒ wèntí jī de tài duō, jiù huì yuèláiyuè nán jiějué.","vi":"Nếu vấn đề dồn lại quá nhiều thì sẽ càng ngày càng khó giải quyết."}],"related":[{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"},{"hanzi":"积攒","pinyin":"jīzǎn","vi":"dành dụm"},{"hanzi":"面积","pinyin":"miànjī","vi":"diện tích"},{"hanzi":"堆积","pinyin":"duījī","vi":"chất đống"}],"traditional":"積"},{"id":"基本功","hanzi":"基本功","pinyin":"jīběngōng","meaning_vi":"kỹ năng cơ bản, công phu nền tảng","explanation":"基本 (cơ bản) + 功 (công – công phu) → công phu nền tảng, những kỹ năng cơ bản phải luyện vững.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🥋","examples":[{"type":"basic","zh":"他的基本功很扎实。","pinyin":"Tā de jīběngōng hěn zhāshi.","vi":"Kỹ năng cơ bản của anh ấy rất vững."},{"type":"simple","zh":"学钢琴一定要先练好基本功。","pinyin":"Xué gāngqín yídìngyào xiān liàn hǎo jīběngōng.","vi":"Học piano nhất định phải luyện tốt kỹ năng cơ bản trước."},{"type":"compound","zh":"如果基本功不扎实，就很难学好高难度动作。","pinyin":"Rúguǒ jīběngōng bù zhāshi, jiù hěn nán xuéhǎo gāo nándù dòngzuò.","vi":"Nếu nền tảng không vững thì rất khó học tốt các động tác khó."}],"related":[{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu"},{"hanzi":"技能","pinyin":"jìnéng","vi":"kỹ năng"},{"hanzi":"基本","pinyin":"jīběn","vi":"cơ bản"}]},{"id":"基层","hanzi":"基层","pinyin":"jīcéng","meaning_vi":"cơ sở, cấp cơ sở","explanation":"基 (cơ – nền móng) + 层 (tầng – tầng lớp) → tầng dưới cùng, cấp cơ sở trong một tổ chức.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"他在基层工作。","pinyin":"Tā zài jīcéng gōngzuò.","vi":"Anh ấy làm việc ở cơ sở."},{"type":"simple","zh":"领导经常到基层了解群众的需要。","pinyin":"Lǐngdǎo jīngcháng dào jīcéng liǎojiě qúnzhòng de xūyào.","vi":"Lãnh đạo thường xuống cơ sở tìm hiểu nhu cầu của quần chúng."},{"type":"compound","zh":"虽然基层工作很辛苦，但是能学到很多东西。","pinyin":"Suīrán jīcéng gōngzuò hěn xīnkǔ, dànshì néng xuédào hěn duō dōngxi.","vi":"Tuy công việc ở cơ sở rất vất vả nhưng học được nhiều điều."}],"related":[{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"},{"hanzi":"高层","pinyin":"gāocéng","vi":"cấp cao"},{"hanzi":"群众","pinyin":"qúnzhòng","vi":"quần chúng"},{"hanzi":"社区","pinyin":"shèqū","vi":"khu dân cư"}],"traditional":"基層"},{"id":"基于","hanzi":"基于","pinyin":"jīyú","meaning_vi":"dựa trên, căn cứ vào, xuất phát từ","explanation":"基 (cơ – nền tảng) + 于 (vu – ở, tại) → lấy điều gì làm nền tảng, dựa trên.","hsk_level":"7-9","tags":["gioi-tu"],"image":"🏗️","examples":[{"type":"basic","zh":"这是基于事实的判断。","pinyin":"Zhè shì jīyú shìshí de pànduàn.","vi":"Đây là phán đoán dựa trên sự thật."},{"type":"simple","zh":"基于安全考虑，比赛被临时取消了。","pinyin":"Jīyú ānquán kǎolǜ, bǐsài bèi línshí qǔxiāo le.","vi":"Vì lý do an toàn, trận đấu bị hủy đột xuất."},{"type":"compound","zh":"因为这个结论基于大量数据，所以很有说服力。","pinyin":"Yīnwèi zhè ge jiélùn jīyú dàliàng shùjù, suǒyǐ hěn yǒu shuōfúlì.","vi":"Vì kết luận này dựa trên lượng lớn dữ liệu nên rất có sức thuyết phục."}],"related":[{"hanzi":"根据","pinyin":"gēnjù","vi":"căn cứ"},{"hanzi":"依据","pinyin":"yījù","vi":"dựa vào"},{"hanzi":"出于","pinyin":"chūyú","vi":"xuất phát từ"},{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"}],"traditional":"基於"},{"id":"激活","hanzi":"激活","pinyin":"jīhuó","meaning_vi":"kích hoạt","explanation":"激 (kích – kích thích) + 活 (hoạt – sống, hoạt động) → làm cho bắt đầu hoạt động, kích hoạt.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔓","examples":[{"type":"basic","zh":"请先激活账号。","pinyin":"Qǐng xiān jīhuó zhànghào.","vi":"Vui lòng kích hoạt tài khoản trước."},{"type":"simple","zh":"新买的银行卡需要激活才能使用。","pinyin":"Xīn mǎi de yínhángkǎ xūyào jīhuó cáinéng shǐyòng.","vi":"Thẻ ngân hàng mới phải kích hoạt mới dùng được."},{"type":"compound","zh":"如果收不到验证码，就无法激活这个软件。","pinyin":"Rúguǒ shōu búdào yànzhèngmǎ, jiù wúfǎ jīhuó zhè ge ruǎnjiàn.","vi":"Nếu không nhận được mã xác minh thì không thể kích hoạt phần mềm này."}],"related":[{"hanzi":"启动","pinyin":"qǐdòng","vi":"khởi động"},{"hanzi":"激发","pinyin":"jīfā","vi":"khơi dậy"},{"hanzi":"开通","pinyin":"kāitōng","vi":"mở dịch vụ"},{"hanzi":"注册","pinyin":"zhùcè","vi":"đăng ký"}]},{"id":"激起","hanzi":"激起","pinyin":"jīqǐ","meaning_vi":"khơi dậy, gây ra, dấy lên","explanation":"激 (kích – khích động) + 起 (khởi – dấy lên) → làm dấy lên, khơi dậy cảm xúc hay phản ứng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"石头激起了水花。","pinyin":"Shítou jīqǐle shuǐhuā.","vi":"Hòn đá làm bắn tung bọt nước."},{"type":"simple","zh":"这条新闻激起了网友的强烈不满。","pinyin":"Zhè tiáo xīnwén jīqǐle wǎngyǒu de qiángliè bùmǎn.","vi":"Tin này đã gây ra sự bất mãn mạnh mẽ của cư dân mạng."},{"type":"compound","zh":"虽然他只说了一句话，但是却激起了大家的斗志。","pinyin":"Suīrán tā zhǐ shuōle yíjùhuà, dànshì què jīqǐle dàjiā de dòuzhì.","vi":"Tuy anh ấy chỉ nói một câu nhưng lại khơi dậy ý chí chiến đấu của mọi người."}],"related":[{"hanzi":"引起","pinyin":"yǐnqǐ","vi":"gây ra"},{"hanzi":"激发","pinyin":"jīfā","vi":"khơi dậy"},{"hanzi":"唤起","pinyin":"huànqǐ","vi":"đánh thức"},{"hanzi":"掀起","pinyin":"xiānqǐ","vi":"dấy lên"}]},{"id":"及","hanzi":"及","pinyin":"jí","meaning_vi":"và, cùng; kịp; đạt đến","explanation":"及 (cập – đến, kịp) → vốn nghĩa đuổi kịp, đạt tới; trong văn viết dùng như liên từ \"và\" nối các danh từ.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔗","examples":[{"type":"basic","zh":"老师及学生都到了。","pinyin":"Lǎoshī jí xuésheng dōu dào le.","vi":"Thầy giáo và học sinh đều đã đến."},{"type":"simple","zh":"请带好身份证及相关材料。","pinyin":"Qǐng dài hǎo shēnfènzhèng jí xiāngguān cáiliào.","vi":"Vui lòng mang theo chứng minh thư và giấy tờ liên quan."},{"type":"compound","zh":"如果你现在出发，就还来得及赶上末班车。","pinyin":"Rúguǒ nǐ xiànzài chūfā, jiù hái láidejí gǎnshàng mòbānchē.","vi":"Nếu bạn xuất phát bây giờ thì vẫn kịp chuyến xe cuối."}],"related":[{"hanzi":"以及","pinyin":"yǐjí","vi":"cũng như"},{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"},{"hanzi":"来不及","pinyin":"láibují","vi":"không kịp"},{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan đến"}]},{"id":"及其","hanzi":"及其","pinyin":"jíqí","meaning_vi":"và (cái của nó), cùng với ... của mình","explanation":"及 (cập – và) + 其 (kỳ – của nó, của họ) → \"và ... của nó/họ\", nối danh từ sau với danh từ trước; dùng trong văn viết.","hsk_level":"7-9","tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"他及其家人都很好。","pinyin":"Tā jíqí jiārén dōu hěn hǎo.","vi":"Anh ấy và gia đình đều khỏe."},{"type":"simple","zh":"本文介绍了这种病的成因及其治疗方法。","pinyin":"Běnwén jièshàole zhè zhǒng bìng de chéngyīn jíqí zhìliáo fāngfǎ.","vi":"Bài viết giới thiệu nguyên nhân bệnh này và cách điều trị nó."},{"type":"compound","zh":"虽然公司已经道歉，但是消费者及其律师仍不满意。","pinyin":"Suīrán gōngsī yǐjīng dàoqiàn, dànshì xiāofèizhě jíqí lǜshī réng bù mǎnyì.","vi":"Tuy công ty đã xin lỗi nhưng người tiêu dùng và luật sư của họ vẫn chưa hài lòng."}],"related":[{"hanzi":"及","pinyin":"jí","vi":"và"},{"hanzi":"以及","pinyin":"yǐjí","vi":"cũng như"},{"hanzi":"其","pinyin":"qí","vi":"của nó"},{"hanzi":"和","pinyin":"hé","vi":"và"}]},{"id":"吉普","hanzi":"吉普","pinyin":"Jípǔ","meaning_vi":"xe jeep","explanation":"吉普 (cát phổ) → phiên âm từ \"Jeep\", loại xe việt dã; thường nói 吉普车.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚙","examples":[{"type":"basic","zh":"他开着一辆吉普。","pinyin":"Tā kāizhe yí liàng Jípǔ.","vi":"Anh ấy lái một chiếc xe jeep."},{"type":"simple","zh":"我们坐吉普车穿过了这片沙漠。","pinyin":"Wǒmen zuò jípǔchē chuānguòle zhè piàn shāmò.","vi":"Chúng tôi đi xe jeep băng qua vùng sa mạc này."},{"type":"compound","zh":"因为山路坑坑洼洼，所以只有吉普才开得上去。","pinyin":"Yīnwèi shānlù kēng kēngwā wā, suǒyǐ zhǐyǒu Jípǔ cái kāi de shàngqù.","vi":"Vì đường núi gồ ghề lồi lõm nên chỉ có xe jeep mới chạy lên được."}],"related":[{"hanzi":"吉普车","pinyin":"jípǔchē","vi":"xe jeep"},{"hanzi":"越野车","pinyin":"yuèyěchē","vi":"xe địa hình"},{"hanzi":"轿车","pinyin":"jiàochē","vi":"xe con"},{"hanzi":"卡车","pinyin":"kǎchē","vi":"xe tải"}]},{"id":"吉他","hanzi":"吉他","pinyin":"jítā","meaning_vi":"đàn ghi-ta","explanation":"吉他 (cát tha) → phiên âm từ \"guitar\", đàn ghi-ta.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎸","examples":[{"type":"basic","zh":"他会弹吉他。","pinyin":"Tā huì tán jítā.","vi":"Anh ấy biết chơi ghi-ta."},{"type":"simple","zh":"她每天晚上都在宿舍里练吉他。","pinyin":"Tā měitiān wǎnshang dōu zài sùshè li liàn jítā.","vi":"Tối nào cô ấy cũng tập ghi-ta trong ký túc xá."},{"type":"compound","zh":"虽然我学吉他才半年，但是已经能弹几首歌了。","pinyin":"Suīrán wǒ xué jítā cái bàn nián, dànshì yǐjīng néng tán jǐ shǒu gē le.","vi":"Tuy tôi mới học ghi-ta nửa năm nhưng đã đàn được vài bài."}],"related":[{"hanzi":"弹","pinyin":"tán","vi":"gảy đàn"},{"hanzi":"钢琴","pinyin":"gāngqín","vi":"đàn piano"},{"hanzi":"乐器","pinyin":"yuèqì","vi":"nhạc cụ"},{"hanzi":"小提琴","pinyin":"xiǎotíqín","vi":"đàn violin"}]},{"id":"吉祥物","hanzi":"吉祥物","pinyin":"jíxiángwù","meaning_vi":"linh vật","explanation":"吉祥 (cát tường – may mắn) + 物 (vật) → vật mang lại may mắn, linh vật đại diện cho sự kiện, tổ chức.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🐼","examples":[{"type":"basic","zh":"熊猫是吉祥物。","pinyin":"Xióngmāo shì jíxiángwù.","vi":"Gấu trúc là linh vật."},{"type":"simple","zh":"每届奥运会都会设计自己的吉祥物。","pinyin":"Měi jiè Àoyùnhuì dōuhuì shèjì zìjǐ de jíxiángwù.","vi":"Mỗi kỳ Olympic đều thiết kế linh vật riêng."},{"type":"compound","zh":"因为这个吉祥物非常可爱，所以纪念品很快就卖光了。","pinyin":"Yīnwèi zhè ge jíxiángwù fēicháng kě'ài, suǒyǐ jìniànpǐn hěn kuài jiù màiguāngle.","vi":"Vì linh vật này rất đáng yêu nên quà lưu niệm nhanh chóng bán hết."}],"related":[{"hanzi":"吉祥","pinyin":"jíxiáng","vi":"cát tường"},{"hanzi":"吉利","pinyin":"jílì","vi":"may mắn"},{"hanzi":"纪念品","pinyin":"jìniànpǐn","vi":"quà lưu niệm"},{"hanzi":"标志","pinyin":"biāozhì","vi":"biểu tượng"}]},{"id":"即","hanzi":"即","pinyin":"jí","meaning_vi":"tức là, chính là; ngay, liền","explanation":"即 (tức – tức là, ngay) → trong văn viết mang nghĩa \"tức là, chính là\" hoặc \"ngay lập tức\".","hsk_level":"7-9","tags":["pho-tu"],"image":"👉","examples":[{"type":"basic","zh":"鲁迅，即周树人。","pinyin":"Lǔxùn, jí Zhōushùrén.","vi":"Lỗ Tấn, tức Chu Thụ Nhân."},{"type":"simple","zh":"门票售完即止，请大家抓紧购买。","pinyin":"Ménpiào shòuwán jí zhǐ, qǐng dàjiā zhuājǐn gòumǎi.","vi":"Vé bán hết là dừng, mọi người hãy nhanh tay mua."},{"type":"compound","zh":"只要收到您的付款，我们即安排发货。","pinyin":"Zhǐyào shōudào nín de fùkuǎn, wǒmen jí ānpái fāhuò.","vi":"Chỉ cần nhận được tiền thanh toán của quý khách, chúng tôi sẽ sắp xếp giao hàng ngay."}],"related":[{"hanzi":"即使","pinyin":"jíshǐ","vi":"dù cho"},{"hanzi":"立即","pinyin":"lìjí","vi":"lập tức"},{"hanzi":"即将","pinyin":"jíjiāng","vi":"sắp sửa"},{"hanzi":"即便","pinyin":"jíbiàn","vi":"cho dù"}]},{"id":"即可","hanzi":"即可","pinyin":"jíkě","meaning_vi":"là được, liền có thể","explanation":"即 (tức – liền) + 可 (khả – có thể) → liền có thể, chỉ cần … là được; văn viết, tương đương 就可以.","hsk_level":"7-9","tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"扫码即可付款。","pinyin":"Sǎomǎ jíkě fùkuǎn.","vi":"Quét mã là thanh toán được."},{"type":"simple","zh":"报名者只需提供身份证复印件即可。","pinyin":"Bàomíng zhě zhǐxū tígōng shēnfènzhèng fùyìnjiàn jíkě.","vi":"Người đăng ký chỉ cần nộp bản sao chứng minh thư là được."},{"type":"compound","zh":"如果忘记密码，点击下方链接即可重新设置。","pinyin":"Rúguǒ wàngjì mìmǎ, diǎnjī xiàfāng liànjiē jíkě chóngxīn shèzhì.","vi":"Nếu quên mật khẩu, bấm vào đường link bên dưới là có thể đặt lại."}],"related":[{"hanzi":"就可以","pinyin":"jiùkěyǐ","vi":"là có thể"},{"hanzi":"便可","pinyin":"biànkě","vi":"liền có thể"},{"hanzi":"即","pinyin":"jí","vi":"ngay, liền"},{"hanzi":"只需","pinyin":"zhǐxū","vi":"chỉ cần"}]},{"id":"极少数","hanzi":"极少数","pinyin":"jíshǎoshù","meaning_vi":"số cực ít, thiểu số rất nhỏ","explanation":"极 (cực – rất) + 少数 (thiểu số – số ít) → số rất ít, một nhóm cực nhỏ.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"🤏","examples":[{"type":"basic","zh":"只有极少数人反对。","pinyin":"Zhǐyǒu jíshǎoshù rén fǎnduì.","vi":"Chỉ có rất ít người phản đối."},{"type":"simple","zh":"这种病只在极少数儿童身上出现。","pinyin":"Zhè zhǒng bìng zhǐ zài jíshǎoshù értóng shēnshang chūxiàn.","vi":"Bệnh này chỉ xuất hiện ở số rất ít trẻ em."},{"type":"compound","zh":"虽然大部分顾客很满意，但是极少数人还有意见。","pinyin":"Suīrán dàbùfen gùkè hěn mǎnyì, dànshì jíshǎoshù rén háiyǒu yìjiàn.","vi":"Tuy phần lớn khách hàng hài lòng nhưng vẫn có số rất ít người còn ý kiến."}],"related":[{"hanzi":"少数","pinyin":"shǎoshù","vi":"số ít"},{"hanzi":"多数","pinyin":"duōshù","vi":"đa số"},{"hanzi":"极个别","pinyin":"jígèbié","vi":"cá biệt"},{"hanzi":"绝大多数","pinyin":"juédàduōshù","vi":"tuyệt đại đa số"}],"traditional":"極少數"},{"id":"极为","hanzi":"极为","pinyin":"jíwéi","meaning_vi":"vô cùng, cực kỳ","explanation":"极 (cực – tột cùng) + 为 (vi – là) → ở mức tột cùng, cực kỳ; văn viết, thường đứng trước tính từ hai âm tiết.","hsk_level":"7-9","tags":["pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"情况极为严重。","pinyin":"Qíngkuàng jíwéi yánzhòng.","vi":"Tình hình cực kỳ nghiêm trọng."},{"type":"simple","zh":"这次发现对科学研究极为重要。","pinyin":"Zhè cì fāxiàn duì kēxué yánjiū jíwéi zhòngyào.","vi":"Phát hiện lần này vô cùng quan trọng đối với nghiên cứu khoa học."},{"type":"compound","zh":"因为当地气候极为干燥，所以很少有植物生长。","pinyin":"Yīnwèi dāngdì qìhòu jíwéi gānzào, suǒyǐ hěn shǎoyǒu zhíwù shēngzhǎng.","vi":"Vì khí hậu nơi đó cực kỳ khô hạn nên rất ít thực vật sinh trưởng."}],"related":[{"hanzi":"极其","pinyin":"jíqí","vi":"vô cùng"},{"hanzi":"十分","pinyin":"shífēn","vi":"rất"},{"hanzi":"非常","pinyin":"fēicháng","vi":"rất"},{"hanzi":"尤为","pinyin":"yóuwéi","vi":"đặc biệt"}],"traditional":"極為"},{"id":"急剧","hanzi":"急剧","pinyin":"jíjù","meaning_vi":"đột ngột, nhanh chóng, kịch liệt","explanation":"急 (cấp – gấp) + 剧 (kịch – dữ dội) → thay đổi gấp và mạnh, đột ngột.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"气温急剧下降。","pinyin":"Qìwēn jíjù xiàjiàng.","vi":"Nhiệt độ giảm đột ngột."},{"type":"simple","zh":"近几年这座城市的人口急剧增加。","pinyin":"Jìnjǐnián zhè zuò chéngshì de rénkǒu jíjù zēngjiā.","vi":"Mấy năm gần đây dân số thành phố này tăng vọt."},{"type":"compound","zh":"因为病情急剧恶化，所以他被送进了重症病房。","pinyin":"Yīnwèi bìngqíng jíjù èhuà, suǒyǐ tā bèi sòng jìnle zhòngzhèng bìngfáng.","vi":"Vì bệnh tình chuyển xấu đột ngột nên anh ấy được đưa vào phòng hồi sức."}],"related":[{"hanzi":"急速","pinyin":"jísù","vi":"nhanh chóng"},{"hanzi":"剧烈","pinyin":"jùliè","vi":"kịch liệt"},{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"},{"hanzi":"骤然","pinyin":"zhòurán","vi":"đột nhiên"}],"traditional":"急劇"},{"id":"急性","hanzi":"急性","pinyin":"jíxìng","meaning_vi":"cấp tính","explanation":"急 (cấp – gấp) + 性 (tính – tính chất) → (bệnh) phát gấp, cấp tính; 急性子 chỉ người nóng vội.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"他得了急性肠炎。","pinyin":"Tā déle jíxìng chángyán.","vi":"Anh ấy bị viêm ruột cấp tính."},{"type":"simple","zh":"急性阑尾炎必须尽快做手术。","pinyin":"Jíxìng lánwěiyán bìxū jǐnkuài zuò shǒushù.","vi":"Viêm ruột thừa cấp tính phải phẫu thuật càng sớm càng tốt."},{"type":"compound","zh":"如果急性病不及时治疗，就可能转成慢性病。","pinyin":"Rúguǒ jíxìngbìng bù jíshí zhìliáo, jiù kěnéng zhuǎn chéng mànxìngbìng.","vi":"Nếu bệnh cấp tính không được chữa kịp thời thì có thể chuyển thành mãn tính."}],"related":[{"hanzi":"慢性","pinyin":"mànxìng","vi":"mãn tính"},{"hanzi":"急诊","pinyin":"jízhěn","vi":"cấp cứu"},{"hanzi":"急性子","pinyin":"jíxìngzi","vi":"người nóng vội"},{"hanzi":"发炎","pinyin":"fāyán","vi":"viêm"}]},{"id":"急需","hanzi":"急需","pinyin":"jíxū","meaning_vi":"cần gấp; nhu cầu cấp bách","explanation":"急 (cấp – gấp) + 需 (nhu – cần) → cần gấp, nhu cầu cấp bách.","hsk_level":"7-9","tags":["dong-tu"],"image":"🆘","examples":[{"type":"basic","zh":"灾区急需食物。","pinyin":"Zāiqū jíxū shíwù.","vi":"Vùng thiên tai đang cần gấp lương thực."},{"type":"simple","zh":"这家医院急需一批有经验的护士。","pinyin":"Zhè jiā yīyuàn jíxū yìpī yǒu jīngyàn de hùshi.","vi":"Bệnh viện này đang cần gấp một nhóm y tá có kinh nghiệm."},{"type":"compound","zh":"因为病人急需输血，所以大家纷纷去献血。","pinyin":"Yīnwèi bìngrén jíxū shūxuè, suǒyǐ dàjiā fēnfēn qù xiànxiě.","vi":"Vì bệnh nhân cần truyền máu gấp nên mọi người lần lượt đi hiến máu."}],"related":[{"hanzi":"需要","pinyin":"xūyào","vi":"cần"},{"hanzi":"急用","pinyin":"jíyòng","vi":"cần dùng gấp"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"},{"hanzi":"必需","pinyin":"bìxū","vi":"thiết yếu"}]},{"id":"急于","hanzi":"急于","pinyin":"jíyú","meaning_vi":"vội, nóng lòng (làm gì)","explanation":"急 (cấp – vội) + 于 (vu – ở) → nóng vội muốn làm ngay việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏳","examples":[{"type":"basic","zh":"别急于下结论。","pinyin":"Bié jíyú xià jiélùn.","vi":"Đừng vội kết luận."},{"type":"simple","zh":"他急于证明自己的能力。","pinyin":"Tā jíyú zhèngmíng zìjǐ de nénglì.","vi":"Anh ấy nóng lòng chứng minh năng lực của mình."},{"type":"compound","zh":"如果你太急于求成，就容易犯错误。","pinyin":"Rúguǒ nǐ tài jíyúqiúchéng, jiù róngyì fàn cuòwù.","vi":"Nếu bạn quá nóng vội muốn thành công thì dễ mắc sai lầm."}],"related":[{"hanzi":"急着","pinyin":"jízhe","vi":"vội vã"},{"hanzi":"着急","pinyin":"zháojí","vi":"sốt ruột"},{"hanzi":"急于求成","pinyin":"jíyúqiúchéng","vi":"nôn nóng muốn thành"},{"hanzi":"迫切","pinyin":"pòqiè","vi":"bức thiết"}],"traditional":"急於"},{"id":"急转弯","hanzi":"急转弯","pinyin":"jízhuǎnwān","meaning_vi":"rẽ gấp, ngoặt gấp; khúc cua gấp; thay đổi đột ngột","explanation":"急 (cấp – gấp) + 转弯 (chuyển loan – rẽ, quẹo) → quẹo gấp; nghĩa bóng là đổi hướng, thái độ đột ngột; 脑筋急转弯 là câu đố mẹo.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"↩️","examples":[{"type":"basic","zh":"前方有急转弯。","pinyin":"Qiánfāng yǒu jízhuǎnwān.","vi":"Phía trước có khúc cua gấp."},{"type":"simple","zh":"司机一个急转弯，乘客差点摔倒。","pinyin":"Sījī yí ge jízhuǎnwān, chéngkè chàdiǎn shuāidǎo.","vi":"Tài xế ngoặt gấp một cái, hành khách suýt ngã."},{"type":"compound","zh":"因为前面突然有车，所以他只好来了个急转弯。","pinyin":"Yīnwèi qiánmiàn tūrán yǒu chē, suǒyǐ tā zhǐhǎo láile ge jízhuǎnwān.","vi":"Vì phía trước đột nhiên có xe nên anh ấy đành phải ngoặt gấp."}],"related":[{"hanzi":"转弯","pinyin":"zhuǎnwān","vi":"rẽ"},{"hanzi":"拐弯","pinyin":"guǎiwān","vi":"quẹo"},{"hanzi":"脑筋急转弯","pinyin":"nǎojīn jízhuǎnwān","vi":"câu đố mẹo"},{"hanzi":"掉头","pinyin":"diàotóu","vi":"quay đầu"}],"traditional":"急轉彎"},{"id":"脊梁","hanzi":"脊梁","pinyin":"jǐliang","meaning_vi":"sống lưng, xương sống; trụ cột","explanation":"脊 (tích – sống lưng) + 梁 (lương – xà nhà) → sống lưng như cây xà đỡ thân người; nghĩa bóng là trụ cột, khí phách.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🦴","examples":[{"type":"basic","zh":"他挺直了脊梁。","pinyin":"Tā tǐng zhíle jǐliang.","vi":"Anh ấy ưỡn thẳng sống lưng."},{"type":"simple","zh":"这些科学家是国家的脊梁。","pinyin":"Zhèxiē kēxuéjiā shì guójiā de jǐliang.","vi":"Những nhà khoa học này là trụ cột của đất nước."},{"type":"compound","zh":"即使生活再艰难，他也从不弯下脊梁。","pinyin":"Jíshǐ shēnghuó zài jiānnán, tā yě cóng bù wān xià jǐliang.","vi":"Dù cuộc sống khó khăn đến đâu, anh ấy cũng chưa từng khom lưng khuất phục."}],"related":[{"hanzi":"脊椎","pinyin":"jǐzhuī","vi":"cột sống"},{"hanzi":"脊背","pinyin":"jǐbèi","vi":"lưng"},{"hanzi":"骨干","pinyin":"gǔgàn","vi":"nòng cốt"},{"hanzi":"栋梁","pinyin":"dòngliáng","vi":"rường cột"}],"traditional":"脊樑"},{"id":"集会","hanzi":"集会","pinyin":"jíhuì","meaning_vi":"tụ họp, mít tinh; cuộc tụ họp, cuộc mít tinh","explanation":"集 (tập – tụ tập) + 会 (hội – họp) → nhiều người tụ họp lại, cuộc mít tinh.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"广场上举行集会。","pinyin":"Guǎngchǎng shang jǔxíng jíhuì.","vi":"Trên quảng trường tổ chức mít tinh."},{"type":"simple","zh":"公民依法享有集会和言论的自由。","pinyin":"Gōngmín yīfǎ xiǎngyǒu jíhuì hé yánlùn de zìyóu.","vi":"Công dân được hưởng quyền tự do hội họp và ngôn luận theo pháp luật."},{"type":"compound","zh":"如果要举行大型集会，就必须提前向警方申请。","pinyin":"Rúguǒ yào jǔxíng dàxíng jíhuì, jiù bìxū tíqián xiàng jǐngfāng shēnqǐng.","vi":"Nếu muốn tổ chức cuộc tụ họp lớn thì phải xin phép cảnh sát trước."}],"related":[{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi họp mặt"},{"hanzi":"集合","pinyin":"jíhé","vi":"tập hợp"},{"hanzi":"游行","pinyin":"yóuxíng","vi":"diễu hành"},{"hanzi":"会议","pinyin":"huìyì","vi":"hội nghị"}],"traditional":"集會"},{"id":"集结","hanzi":"集结","pinyin":"jíjié","meaning_vi":"tập kết, tập trung","explanation":"集 (tập – gom) + 结 (kết – kết lại) → gom lại một chỗ, tập kết lực lượng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪖","examples":[{"type":"basic","zh":"部队正在集结。","pinyin":"Bùduì zhèngzài jíjié.","vi":"Quân đội đang tập kết."},{"type":"simple","zh":"救援人员已经在山脚下集结完毕。","pinyin":"Jiùyuán rényuán yǐjīng zài shān jiǎoxià jíjié wánbì.","vi":"Lực lượng cứu hộ đã tập kết xong dưới chân núi."},{"type":"compound","zh":"一旦命令下达，各队就要马上到指定地点集结。","pinyin":"Yídàn mìnglìng xiàdá, gè duì jiùyào mǎshàng dào zhǐdìng dìdiǎn jíjié.","vi":"Một khi có lệnh, các đội phải lập tức tập kết tại địa điểm chỉ định."}],"related":[{"hanzi":"集合","pinyin":"jíhé","vi":"tập hợp"},{"hanzi":"聚集","pinyin":"jùjí","vi":"tụ tập"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"},{"hanzi":"部署","pinyin":"bùshǔ","vi":"triển khai"}],"traditional":"集結"},{"id":"集邮","hanzi":"集邮","pinyin":"jíyóu","meaning_vi":"sưu tầm tem","explanation":"集 (tập – sưu tập) + 邮 (bưu – bưu chính, tem thư) → sưu tầm tem thư.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"📮","examples":[{"type":"basic","zh":"爷爷喜欢集邮。","pinyin":"Yéye xǐhuan jíyóu.","vi":"Ông nội thích sưu tầm tem."},{"type":"simple","zh":"他集邮已经三十多年了。","pinyin":"Tā jíyóu yǐjīng sānshí duōnián le.","vi":"Ông ấy sưu tầm tem đã hơn ba mươi năm."},{"type":"compound","zh":"虽然现在很少人写信，但是集邮的人仍然不少。","pinyin":"Suīrán xiànzài hěn shǎo rén xiěxìn, dànshì jíyóu de rén réngrán bùshǎo.","vi":"Tuy bây giờ ít người viết thư nhưng người sưu tầm tem vẫn còn khá nhiều."}],"related":[{"hanzi":"邮票","pinyin":"yóupiào","vi":"tem"},{"hanzi":"收藏","pinyin":"shōucáng","vi":"sưu tầm"},{"hanzi":"邮局","pinyin":"yóujú","vi":"bưu điện"},{"hanzi":"爱好","pinyin":"àihào","vi":"sở thích"}],"traditional":"集郵"},{"id":"几率","hanzi":"几率","pinyin":"jīlǜ","meaning_vi":"xác suất, tỷ lệ khả năng","explanation":"几 (cơ – khả năng nhỏ) + 率 (suất – tỷ lệ) → tỷ lệ khả năng xảy ra, tức xác suất (cũng viết 机率).","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"🎲","examples":[{"type":"basic","zh":"中奖几率很低。","pinyin":"Zhòngjiǎng jīlǜ hěn dī.","vi":"Xác suất trúng thưởng rất thấp."},{"type":"simple","zh":"经常锻炼可以降低生病的几率。","pinyin":"Jīngcháng duànliàn kěyǐ jiàngdī shēngbìng de jīlǜ.","vi":"Thường xuyên tập luyện có thể giảm khả năng bị bệnh."},{"type":"compound","zh":"如果提前做好准备，成功的几率就会大很多。","pinyin":"Rúguǒ tíqián zuò hǎo zhǔnbèi, chénggōng de jīlǜ jiù huì dà hěn duō.","vi":"Nếu chuẩn bị kỹ từ trước thì khả năng thành công sẽ cao hơn nhiều."}],"related":[{"hanzi":"概率","pinyin":"gàilǜ","vi":"xác suất"},{"hanzi":"可能性","pinyin":"kěnéngxìng","vi":"khả năng"},{"hanzi":"比率","pinyin":"bǐlǜ","vi":"tỷ lệ"},{"hanzi":"机会","pinyin":"jīhuì","vi":"cơ hội"}],"traditional":"幾率"},{"id":"计","hanzi":"计","pinyin":"jì","meaning_vi":"tính, đếm; kế sách, mưu kế; dụng cụ đo","explanation":"计 (kế – tính toán, mưu kế) → tính đếm; danh từ chỉ kế sách, hoặc dụng cụ đo như 体温计 (nhiệt kế).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧮","examples":[{"type":"basic","zh":"门票按人头计费。","pinyin":"Ménpiào àn réntóu jì fèi.","vi":"Vé vào cửa tính tiền theo đầu người."},{"type":"simple","zh":"他想出了一条妙计，解决了难题。","pinyin":"Tā xiǎngchūle yì tiáo miàojì, jiějuéle nántí.","vi":"Anh ấy nghĩ ra một diệu kế, giải quyết được bài toán khó."},{"type":"compound","zh":"虽然这次失败了，但是从长远计，经验非常宝贵。","pinyin":"Suīrán zhè cì shībài le, dànshì cóng chángyuǎn jì, jīngyàn fēicháng bǎoguì.","vi":"Tuy lần này thất bại nhưng tính về lâu dài, kinh nghiệm này vô cùng quý giá."}],"related":[{"hanzi":"计算","pinyin":"jìsuàn","vi":"tính toán"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"},{"hanzi":"计划","pinyin":"jìhuà","vi":"kế hoạch"},{"hanzi":"温度计","pinyin":"wēndùjì","vi":"nhiệt kế"}],"traditional":"計"},{"id":"计时","hanzi":"计时","pinyin":"jìshí","meaning_vi":"tính giờ, bấm giờ","explanation":"计 (kế – tính) + 时 (thời – thời gian) → đo, tính thời gian.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"考试开始计时。","pinyin":"Kǎoshì kāishǐ jìshí.","vi":"Bài thi bắt đầu tính giờ."},{"type":"simple","zh":"裁判用秒表为每位选手计时。","pinyin":"Cáipàn yòng miǎobiǎo wèi měi wèi xuǎnshǒu jìshí.","vi":"Trọng tài dùng đồng hồ bấm giây tính giờ cho từng vận động viên."},{"type":"compound","zh":"因为停车场按小时计时收费，所以我们得快点儿。","pinyin":"Yīnwèi tíngchēchǎng àn xiǎoshí jìshí shōufèi, suǒyǐ wǒmen děi kuàidiǎnr.","vi":"Vì bãi đỗ xe tính tiền theo giờ nên chúng ta phải nhanh lên."}],"related":[{"hanzi":"计时器","pinyin":"jìshíqì","vi":"đồng hồ bấm giờ"},{"hanzi":"秒表","pinyin":"miǎobiǎo","vi":"đồng hồ bấm giây"},{"hanzi":"倒计时","pinyin":"dàojìshí","vi":"đếm ngược"},{"hanzi":"时间","pinyin":"shíjiān","vi":"thời gian"}],"traditional":"計時"},{"id":"记号","hanzi":"记号","pinyin":"jìhao","meaning_vi":"ký hiệu, dấu đánh dấu","explanation":"记 (ký – ghi) + 号 (hiệu – dấu hiệu) → dấu ghi lại để nhận biết.","hsk_level":"7-9","tags":["danh-tu"],"image":"✏️","examples":[{"type":"basic","zh":"我做了个记号。","pinyin":"Wǒ zuòle ge jìhao.","vi":"Tôi đã đánh một dấu."},{"type":"simple","zh":"他在书上重要的地方画了记号。","pinyin":"Tā zài shū shang zhòngyào de dìfang huàle jìhao.","vi":"Anh ấy đánh dấu những chỗ quan trọng trong sách."},{"type":"compound","zh":"如果你不做记号，就很容易找不到回去的路。","pinyin":"Rúguǒ nǐ bú zuò jìhao, jiù hěn róngyì zhǎobúdào huíqù de lù.","vi":"Nếu bạn không đánh dấu thì rất dễ không tìm được đường về."}],"related":[{"hanzi":"标记","pinyin":"biāojì","vi":"đánh dấu"},{"hanzi":"符号","pinyin":"fúhào","vi":"ký hiệu"},{"hanzi":"标志","pinyin":"biāozhì","vi":"dấu hiệu"},{"hanzi":"记号笔","pinyin":"jìhaobǐ","vi":"bút đánh dấu"}],"traditional":"記號"},{"id":"纪念碑","hanzi":"纪念碑","pinyin":"jìniànbēi","meaning_vi":"đài tưởng niệm, bia kỷ niệm","explanation":"纪念 (kỷ niệm – ghi nhớ) + 碑 (bi – tấm bia) → bia, đài dựng lên để tưởng nhớ người hoặc sự kiện.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🗿","examples":[{"type":"basic","zh":"广场中央有座纪念碑。","pinyin":"Guǎngchǎng zhōngyāng yǒu zuò jìniànbēi.","vi":"Giữa quảng trường có một đài tưởng niệm."},{"type":"simple","zh":"人们在纪念碑前献上了鲜花。","pinyin":"Rénmen zài jìniànbēi qián xiànshàngle xiānhuā.","vi":"Mọi người dâng hoa trước đài tưởng niệm."},{"type":"compound","zh":"虽然纪念碑已经有百年历史，但是保存得很完好。","pinyin":"Suīrán jìniànbēi yǐjīng yǒu bǎinián lìshǐ, dànshì bǎocún de hěn wánhǎo.","vi":"Tuy đài tưởng niệm đã có lịch sử trăm năm nhưng vẫn được bảo tồn rất tốt."}],"related":[{"hanzi":"纪念","pinyin":"jìniàn","vi":"kỷ niệm"},{"hanzi":"纪念馆","pinyin":"jìniànguǎn","vi":"nhà tưởng niệm"},{"hanzi":"石碑","pinyin":"shíbēi","vi":"bia đá"},{"hanzi":"烈士","pinyin":"lièshì","vi":"liệt sĩ"}],"traditional":"紀念碑"},{"id":"纪念日","hanzi":"纪念日","pinyin":"jìniànrì","meaning_vi":"ngày kỷ niệm","explanation":"纪念 (kỷ niệm) + 日 (nhật – ngày) → ngày dùng để kỷ niệm một sự kiện.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"今天是结婚纪念日。","pinyin":"Jīntiān shì jiéhūn jìniànrì.","vi":"Hôm nay là ngày kỷ niệm ngày cưới."},{"type":"simple","zh":"每到纪念日，他都会给妻子送花。","pinyin":"Měi dào jìniànrì, tā dōuhuì gěi qīzi sòng huā.","vi":"Cứ đến ngày kỷ niệm, anh ấy đều tặng hoa cho vợ."},{"type":"compound","zh":"如果你忘了纪念日，她就一定会生气。","pinyin":"Rúguǒ nǐ wàngle jìniànrì, tā jiù yídìng huì shēngqì.","vi":"Nếu anh quên ngày kỷ niệm thì cô ấy nhất định sẽ giận."}],"related":[{"hanzi":"纪念","pinyin":"jìniàn","vi":"kỷ niệm"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"},{"hanzi":"周年","pinyin":"zhōunián","vi":"tròn năm"},{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"đài tưởng niệm"}],"traditional":"紀念日"},{"id":"忌","hanzi":"忌","pinyin":"jì","meaning_vi":"kiêng, kiêng kỵ; đố kỵ, ghen ghét","explanation":"忌 (kỵ – kiêng, ghen) → kiêng tránh điều gì; cũng mang nghĩa đố kỵ, ghen ghét.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"感冒时忌吃辣。","pinyin":"Gǎnmào shí jì chī là.","vi":"Khi bị cảm nên kiêng đồ cay."},{"type":"simple","zh":"做事情最忌半途而废。","pinyin":"Zuò shìqing zuì jì bàntú'érfèi.","vi":"Làm việc kỵ nhất là bỏ dở giữa chừng."},{"type":"compound","zh":"因为他刚做完手术，所以医生叮嘱他忌烟忌酒。","pinyin":"Yīnwèi tā gāng zuòwán shǒushù, suǒyǐ yīshēng dīngzhǔ tā jìyān jì jiǔ.","vi":"Vì anh ấy vừa phẫu thuật xong nên bác sĩ dặn phải kiêng thuốc lá và rượu."}],"related":[{"hanzi":"禁忌","pinyin":"jìnjì","vi":"cấm kỵ"},{"hanzi":"忌口","pinyin":"jìkǒu","vi":"kiêng ăn"},{"hanzi":"妒忌","pinyin":"dùjì","vi":"đố kỵ"},{"hanzi":"顾忌","pinyin":"gùjì","vi":"e ngại"}]},{"id":"剂","hanzi":"剂","pinyin":"jì","meaning_vi":"thang, liều (thuốc); chế phẩm, chất (pha chế)","explanation":"剂 (tễ – thuốc đã pha chế) → lượng từ cho thang thuốc; cũng chỉ chất pha chế như 洗涤剂 (chất tẩy rửa), 防腐剂 (chất bảo quản).","hsk_level":"7-9","tags":["luong-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"医生开了三剂中药。","pinyin":"Yīshēng kāile sān jì zhōngyào.","vi":"Bác sĩ kê ba thang thuốc Bắc."},{"type":"simple","zh":"这剂药要分早晚两次服用。","pinyin":"Zhè jì yào yào fēn zǎowǎn liǎng cì fúyòng.","vi":"Thang thuốc này phải chia uống sáng và tối."},{"type":"compound","zh":"如果吃完这几剂药还不好，就再来复诊。","pinyin":"Rúguǒ chīwán zhè jǐ jì yào hái bù hǎo, jiù zài lái fùzhěn.","vi":"Nếu uống hết mấy thang thuốc này mà vẫn chưa khỏi thì đến tái khám."}],"related":[{"hanzi":"药剂","pinyin":"yàojì","vi":"dược phẩm"},{"hanzi":"剂量","pinyin":"jìliàng","vi":"liều lượng"},{"hanzi":"针剂","pinyin":"zhēnjì","vi":"thuốc tiêm"},{"hanzi":"防腐剂","pinyin":"fángfǔjì","vi":"chất bảo quản"}],"traditional":"劑"},{"id":"继","hanzi":"继","pinyin":"jì","meaning_vi":"tiếp, tiếp nối, kế tục","explanation":"继 (kế – nối tiếp) → nối tiếp, kế tục; hay dùng trong văn viết với cấu trúc 继…之后 và trong từ ghép như 继续, 继承.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏭️","examples":[{"type":"basic","zh":"继电脑之后，手机也普及了。","pinyin":"Jì diànnǎo zhīhòu, shǒujī yě pǔjí le.","vi":"Tiếp sau máy tính, điện thoại di động cũng trở nên phổ biến."},{"type":"simple","zh":"继上次失利后，他们这次终于赢了。","pinyin":"Jì shàngcì shīlì hòu, tāmen zhè cì zhōngyú yíng le.","vi":"Sau lần thất bại trước, lần này cuối cùng họ đã thắng."},{"type":"compound","zh":"继去年夺冠之后，他们今年又拿了冠军，因此球迷们非常兴奋。","pinyin":"Jì qùnián duóguàn zhīhòu, tāmen jīnnián yòu nále guànjūn, yīncǐ qiúmímen fēicháng xīngfèn.","vi":"Tiếp sau chức vô địch năm ngoái, năm nay họ lại giành chức vô địch, vì vậy người hâm mộ vô cùng phấn khích."}],"related":[{"hanzi":"继续","pinyin":"jìxù","vi":"tiếp tục"},{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"相继","pinyin":"xiāngjì","vi":"lần lượt"},{"hanzi":"继任","pinyin":"jìrèn","vi":"kế nhiệm"}],"traditional":"繼"},{"id":"继父","hanzi":"继父","pinyin":"jìfù","meaning_vi":"cha dượng","explanation":"继 (kế – nối tiếp) + 父 (phụ – cha) → cha kế, tức cha dượng.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨","examples":[{"type":"basic","zh":"继父对我很好。","pinyin":"Jìfù duì wǒ hěn hǎo.","vi":"Cha dượng đối xử với tôi rất tốt."},{"type":"simple","zh":"他从小跟着继父一起长大。","pinyin":"Tā cóngxiǎo gēnzhe jìfù yìqǐ zhǎngdà.","vi":"Từ nhỏ anh ấy đã lớn lên cùng cha dượng."},{"type":"compound","zh":"虽然没有血缘关系，但是继父比谁都疼我。","pinyin":"Suīrán méiyǒu xuèyuán guānxi, dànshì jìfù bǐ shéi dōu téng wǒ.","vi":"Tuy không có quan hệ máu mủ nhưng cha dượng thương tôi hơn ai hết."}],"related":[{"hanzi":"继母","pinyin":"jìmǔ","vi":"mẹ kế"},{"hanzi":"养父","pinyin":"yǎngfù","vi":"cha nuôi"},{"hanzi":"亲生","pinyin":"qīnshēng","vi":"ruột thịt"},{"hanzi":"后爸","pinyin":"hòubà","vi":"bố dượng"}],"traditional":"繼父"},{"id":"继母","hanzi":"继母","pinyin":"jìmǔ","meaning_vi":"mẹ kế","explanation":"继 (kế – nối tiếp) + 母 (mẫu – mẹ) → mẹ kế.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"她是我的继母。","pinyin":"Tā shì wǒ de jìmǔ.","vi":"Bà ấy là mẹ kế của tôi."},{"type":"simple","zh":"童话里的继母常常被写成坏人。","pinyin":"Tónghuà li de jìmǔ chángcháng bèi xiě chéng huàirén.","vi":"Mẹ kế trong truyện cổ tích thường bị miêu tả là người xấu."},{"type":"compound","zh":"虽然刚开始有些陌生，但是我现在和继母相处得很好。","pinyin":"Suīrán gāng kāishǐ yǒuxiē mòshēng, dànshì wǒ xiànzài hé jìmǔ xiāngchǔ de hěn hǎo.","vi":"Tuy lúc đầu có chút xa lạ nhưng giờ tôi và mẹ kế sống với nhau rất hòa thuận."}],"related":[{"hanzi":"继父","pinyin":"jìfù","vi":"cha dượng"},{"hanzi":"后妈","pinyin":"hòumā","vi":"mẹ ghẻ"},{"hanzi":"养母","pinyin":"yǎngmǔ","vi":"mẹ nuôi"},{"hanzi":"生母","pinyin":"shēngmǔ","vi":"mẹ đẻ"}],"traditional":"繼母"},{"id":"祭","hanzi":"祭","pinyin":"jì","meaning_vi":"cúng tế, tế lễ","explanation":"祭 (tế – cúng tế) → dâng lễ vật cúng thần linh, tổ tiên; khi đọc zhài là họ người.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🕯️","examples":[{"type":"basic","zh":"清明节要祭祖。","pinyin":"Qīngmíngjié yào jìzǔ.","vi":"Tết Thanh Minh phải cúng tổ tiên."},{"type":"simple","zh":"古人常在春天举行祭天仪式。","pinyin":"Gǔrén cháng zài chūntiān jǔxíng jìtiān yíshì.","vi":"Người xưa thường tổ chức lễ tế trời vào mùa xuân."},{"type":"compound","zh":"每年除夕，我们全家先祭祖，然后才吃年夜饭。","pinyin":"Měinián Chúxī, wǒmen quánjiā xiān jìzǔ, ránhòu cái chī niányèfàn.","vi":"Đêm giao thừa hằng năm, cả nhà tôi cúng tổ tiên trước rồi mới ăn bữa cơm tất niên."}],"related":[{"hanzi":"祭祀","pinyin":"jìsì","vi":"cúng tế"},{"hanzi":"祭奠","pinyin":"jìdiàn","vi":"tế điện"},{"hanzi":"祭品","pinyin":"jìpǐn","vi":"lễ vật"},{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"}]},{"id":"祭奠","hanzi":"祭奠","pinyin":"jìdiàn","meaning_vi":"cúng viếng, tế điện, tưởng niệm","explanation":"祭 (tế – cúng) + 奠 (điện – dâng lễ cho người đã khuất) → dâng lễ vật, tưởng niệm người đã mất.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"💐","examples":[{"type":"basic","zh":"他们去墓地祭奠亲人。","pinyin":"Tāmen qù mùdì jìdiàn qīnrén.","vi":"Họ đến nghĩa trang viếng người thân."},{"type":"simple","zh":"人们手捧鲜花祭奠遇难者。","pinyin":"Rénmen shǒu pěng xiānhuā jìdiàn yùnànzhě.","vi":"Mọi người cầm hoa tưởng niệm các nạn nhân."},{"type":"compound","zh":"虽然老人已经去世十年，但是家人每年都来祭奠他。","pinyin":"Suīrán lǎorén yǐjīng qùshì shí nián, dànshì jiārén měinián dōu lái jìdiàn tā.","vi":"Tuy ông cụ đã mất mười năm nhưng năm nào người nhà cũng đến viếng."}],"related":[{"hanzi":"祭祀","pinyin":"jìsì","vi":"cúng tế"},{"hanzi":"悼念","pinyin":"dàoniàn","vi":"tưởng niệm"},{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"},{"hanzi":"缅怀","pinyin":"miǎnhuái","vi":"tưởng nhớ"}]},{"id":"祭祀","hanzi":"祭祀","pinyin":"jìsì","meaning_vi":"cúng tế, tế tự","explanation":"祭 (tế – cúng) + 祀 (tự – thờ cúng) → cúng tế thần linh, tổ tiên theo nghi lễ.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"这是祭祀用的鼎。","pinyin":"Zhè shì jìsì yòng de dǐng.","vi":"Đây là chiếc đỉnh dùng để cúng tế."},{"type":"simple","zh":"古代皇帝每年都要祭祀天地。","pinyin":"Gǔdài huángdì měinián dōu yào jìsì tiāndì.","vi":"Hoàng đế thời xưa năm nào cũng phải tế trời đất."},{"type":"compound","zh":"因为祭祀活动非常隆重，所以村民们提前一个月就开始准备。","pinyin":"Yīnwèi jìsì huódòng fēicháng lóngzhòng, suǒyǐ cūnmínmen tíqián yí geyuè jiù kāishǐ zhǔnbèi.","vi":"Vì lễ cúng tế rất long trọng nên dân làng bắt đầu chuẩn bị trước một tháng."}],"related":[{"hanzi":"祭","pinyin":"jì","vi":"cúng tế"},{"hanzi":"祭奠","pinyin":"jìdiàn","vi":"tế điện"},{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"},{"hanzi":"供奉","pinyin":"gòngfèng","vi":"thờ phụng"}]},{"id":"加深","hanzi":"加深","pinyin":"jiāshēn","meaning_vi":"làm sâu sắc thêm, đào sâu","explanation":"加 (gia – thêm) + 深 (thâm – sâu) → làm cho sâu thêm (hiểu biết, tình cảm, mâu thuẫn...).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"误会加深了。","pinyin":"Wùhuì jiāshēn le.","vi":"Hiểu lầm càng sâu thêm."},{"type":"simple","zh":"这次旅行加深了我们之间的友谊。","pinyin":"Zhè cì lǚxíng jiāshēnle wǒmen zhījiān de yǒuyì.","vi":"Chuyến đi này làm tình bạn giữa chúng tôi thêm sâu sắc."},{"type":"compound","zh":"只要多读几遍原文，你对作品的理解就会加深。","pinyin":"Zhǐyào duō dú jǐ biàn yuánwén, nǐ duì zuòpǐn de lǐjiě jiù huì jiāshēn.","vi":"Chỉ cần đọc nguyên văn thêm vài lần, bạn sẽ hiểu tác phẩm sâu hơn."}],"related":[{"hanzi":"深化","pinyin":"shēnhuà","vi":"đào sâu"},{"hanzi":"加强","pinyin":"jiāqiáng","vi":"tăng cường"},{"hanzi":"深入","pinyin":"shēnrù","vi":"đi sâu"},{"hanzi":"加重","pinyin":"jiāzhòng","vi":"nặng thêm"}]},{"id":"加重","hanzi":"加重","pinyin":"jiāzhòng","meaning_vi":"tăng nặng, nặng thêm, trầm trọng thêm","explanation":"加 (gia – thêm) + 重 (trọng – nặng) → làm nặng thêm (gánh nặng, bệnh tình, ngữ khí...).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"他的病加重了。","pinyin":"Tā de bìng jiāzhòng le.","vi":"Bệnh của anh ấy nặng thêm rồi."},{"type":"simple","zh":"物价上涨加重了家庭的经济负担。","pinyin":"Wùjià shàngzhǎng jiāzhòngle jiātíng de jīngjì fùdān.","vi":"Vật giá tăng làm nặng thêm gánh nặng kinh tế của gia đình."},{"type":"compound","zh":"如果感冒了还不休息，病情就会加重。","pinyin":"Rúguǒ gǎnmàole hái bù xiūxi, bìngqíng jiù huì jiāzhòng.","vi":"Nếu bị cảm mà vẫn không nghỉ ngơi thì bệnh sẽ nặng thêm."}],"related":[{"hanzi":"减轻","pinyin":"jiǎnqīng","vi":"giảm nhẹ"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"加深","pinyin":"jiāshēn","vi":"sâu thêm"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"}]},{"id":"家禽","hanzi":"家禽","pinyin":"jiāqín","meaning_vi":"gia cầm","explanation":"家 (gia – nhà) + 禽 (cầm – loài chim) → loài chim nuôi trong nhà như gà, vịt, ngỗng.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐔","examples":[{"type":"basic","zh":"鸡鸭都是家禽。","pinyin":"Jī yā dōu shì jiāqín.","vi":"Gà và vịt đều là gia cầm."},{"type":"simple","zh":"农民在院子里养了很多家禽。","pinyin":"Nóngmín zài yuànzi li yǎngle hěn duō jiāqín.","vi":"Nông dân nuôi rất nhiều gia cầm trong sân."},{"type":"compound","zh":"一旦发现禽流感，附近的家禽就要全部处理掉。","pinyin":"Yídàn fāxiàn qínliúgǎn, fùjìn de jiāqín jiùyào quánbù chǔlǐ diào.","vi":"Một khi phát hiện cúm gia cầm, toàn bộ gia cầm gần đó phải được tiêu hủy."}],"related":[{"hanzi":"家畜","pinyin":"jiāchù","vi":"gia súc"},{"hanzi":"禽流感","pinyin":"qínliúgǎn","vi":"cúm gia cầm"},{"hanzi":"飞禽","pinyin":"fēiqín","vi":"chim muông"},{"hanzi":"养殖","pinyin":"yǎngzhí","vi":"chăn nuôi"}]},{"id":"家用","hanzi":"家用","pinyin":"jiāyòng","meaning_vi":"dùng trong gia đình, gia dụng; chi tiêu gia đình","explanation":"家 (gia – nhà) + 用 (dụng – dùng) → dùng trong nhà; làm danh từ chỉ tiền chi tiêu trong gia đình.","hsk_level":"7-9","tags":["tinh-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"这是家用电器。","pinyin":"Zhè shì jiāyòng diànqì.","vi":"Đây là đồ điện gia dụng."},{"type":"simple","zh":"他每个月给父母一些钱补贴家用。","pinyin":"Tā měi geyuè gěi fùmǔ yìxiē qián bǔtiē jiāyòng.","vi":"Mỗi tháng anh ấy gửi bố mẹ ít tiền phụ chi tiêu trong nhà."},{"type":"compound","zh":"虽然这台打印机是家用的，但是质量很不错。","pinyin":"Suīrán zhè tái dǎyìnjī shì jiāyòng de, dànshì zhìliàng hěn búcuò.","vi":"Tuy chiếc máy in này là loại dùng trong gia đình nhưng chất lượng rất tốt."}],"related":[{"hanzi":"家电","pinyin":"jiādiàn","vi":"đồ điện gia dụng"},{"hanzi":"商用","pinyin":"shāngyòng","vi":"dùng thương mại"},{"hanzi":"日用品","pinyin":"rìyòngpǐn","vi":"đồ dùng hằng ngày"},{"hanzi":"开支","pinyin":"kāizhī","vi":"chi tiêu"}]},{"id":"家政","hanzi":"家政","pinyin":"jiāzhèng","meaning_vi":"việc nhà; dịch vụ giúp việc gia đình","explanation":"家 (gia – nhà) + 政 (chính – việc quản lý) → quản lý việc nhà; nay thường chỉ dịch vụ giúp việc gia đình.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🧹","examples":[{"type":"basic","zh":"她在家政公司工作。","pinyin":"Tā zài jiāzhèng gōngsī gōngzuò.","vi":"Cô ấy làm ở công ty dịch vụ giúp việc."},{"type":"simple","zh":"我们请了一位家政阿姨照顾老人。","pinyin":"Wǒmen qǐngle yí wèi jiāzhèng āyí zhàogù lǎorén.","vi":"Chúng tôi thuê một cô giúp việc để chăm sóc người già."},{"type":"compound","zh":"因为夫妻俩工作都很忙，所以经常请家政来打扫卫生。","pinyin":"Yīnwèi fūqī liǎ gōngzuò dōu hěn máng, suǒyǐ jīngcháng qǐng jiāzhèng lái dǎsǎo wèishēng.","vi":"Vì hai vợ chồng đều bận rộn nên thường thuê người giúp việc đến dọn dẹp."}],"related":[{"hanzi":"家务","pinyin":"jiāwù","vi":"việc nhà"},{"hanzi":"保姆","pinyin":"bǎomǔ","vi":"người giúp việc"},{"hanzi":"钟点工","pinyin":"zhōngdiǎngōng","vi":"giúp việc theo giờ"},{"hanzi":"家政服务","pinyin":"jiāzhèngfúwù","vi":"dịch vụ gia đình"}]},{"id":"嘉年华","hanzi":"嘉年华","pinyin":"jiāniánhuá","meaning_vi":"lễ hội carnival, hội vui chơi","explanation":"嘉 (gia – tốt đẹp) + 年华 (niên hoa – năm tháng tươi đẹp) → phiên âm kiêm nghĩa từ \"carnival\", lễ hội vui chơi lớn.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎡","examples":[{"type":"basic","zh":"周末有个嘉年华。","pinyin":"Zhōumò yǒu ge jiāniánhuá.","vi":"Cuối tuần có một lễ hội carnival."},{"type":"simple","zh":"孩子们在嘉年华上玩得特别开心。","pinyin":"Háizimen zài jiāniánhuá shang wán de tèbié kāixīn.","vi":"Bọn trẻ chơi rất vui ở lễ hội carnival."},{"type":"compound","zh":"虽然嘉年华门票不便宜，但是来玩的人还是很多。","pinyin":"Suīrán jiāniánhuá ménpiào bù piányi, dànshì lái wán de rén háishi hěn duō.","vi":"Tuy vé lễ hội carnival không rẻ nhưng người đến chơi vẫn rất đông."}],"related":[{"hanzi":"狂欢节","pinyin":"kuánghuānjié","vi":"lễ hội hóa trang"},{"hanzi":"游乐园","pinyin":"yóulèyuán","vi":"công viên giải trí"},{"hanzi":"庆典","pinyin":"qìngdiǎn","vi":"lễ mừng"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày hội"}],"traditional":"嘉年華"},{"id":"假定","hanzi":"假定","pinyin":"jiǎdìng","meaning_vi":"giả định, giả sử","explanation":"假 (giả – mượn, tạm) + 定 (định – xác định) → tạm coi là đúng để suy luận, giả định.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"假定他说的是真的。","pinyin":"Jiǎdìng tā shuō de shì zhēn de.","vi":"Giả sử điều anh ta nói là thật."},{"type":"simple","zh":"我们先假定这个方案可行。","pinyin":"Wǒmen xiān jiǎdìng zhè ge fāng'àn kěxíng.","vi":"Chúng ta tạm giả định phương án này khả thi."},{"type":"compound","zh":"假定明天下雨，那么运动会就得推迟。","pinyin":"Jiǎdìng míngtiān xiàyǔ, nàme yùndònghuì jiù děi tuīchí.","vi":"Giả sử ngày mai mưa thì đại hội thể thao phải hoãn lại."}],"related":[{"hanzi":"假设","pinyin":"jiǎshè","vi":"giả thiết"},{"hanzi":"假如","pinyin":"jiǎrú","vi":"giả như"},{"hanzi":"设想","pinyin":"shèxiǎng","vi":"hình dung"},{"hanzi":"假使","pinyin":"jiǎshǐ","vi":"nếu như"}]},{"id":"驾","hanzi":"驾","pinyin":"jià","meaning_vi":"lái, điều khiển, cưỡi; (kính xưng) ngài","explanation":"驾 (giá – đóng ngựa vào xe) → vốn là thắng ngựa kéo xe; nay là lái, điều khiển; còn dùng kính xưng như 劳驾, 大驾.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🐎","examples":[{"type":"basic","zh":"他驾着马车走了。","pinyin":"Tā jiàzhe mǎchē zǒu le.","vi":"Anh ấy đánh xe ngựa đi rồi."},{"type":"simple","zh":"飞行员驾着飞机安全降落了。","pinyin":"Fēixíngyuán jiàzhe fēijī ānquán jiàngluò le.","vi":"Phi công lái máy bay hạ cánh an toàn."},{"type":"compound","zh":"虽然风浪很大，但是老渔民仍驾着小船出海了。","pinyin":"Suīrán fēnglàng hěn dà, dànshì lǎo yúmín réng jiàzhe xiǎochuán chūhǎi le.","vi":"Tuy sóng gió rất lớn nhưng ông lão ngư dân vẫn lái thuyền nhỏ ra khơi."}],"related":[{"hanzi":"驾驶","pinyin":"jiàshǐ","vi":"lái, điều khiển"},{"hanzi":"驾照","pinyin":"jiàzhào","vi":"bằng lái"},{"hanzi":"劳驾","pinyin":"láojià","vi":"làm phiền"},{"hanzi":"驾车","pinyin":"jiàchē","vi":"lái xe"}],"traditional":"駕"},{"id":"驾车","hanzi":"驾车","pinyin":"jiàchē","meaning_vi":"lái xe","explanation":"驾 (giá – điều khiển) + 车 (xa – xe) → lái xe; sắc thái trang trọng hơn 开车.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"请勿酒后驾车。","pinyin":"Qǐngwù jiǔhòu jiàchē.","vi":"Không lái xe sau khi uống rượu."},{"type":"simple","zh":"他每天驾车上下班，要花一个小时。","pinyin":"Tā měitiān jiàchē shàngxiàbān, yào huā yí ge xiǎoshí.","vi":"Hằng ngày anh ấy lái xe đi làm, mất một tiếng đồng hồ."},{"type":"compound","zh":"如果驾车时打电话，就很容易发生事故。","pinyin":"Rúguǒ jiàchē shí dǎdiànhuà, jiù hěn róngyì fāshēng shìgù.","vi":"Nếu vừa lái xe vừa gọi điện thì rất dễ xảy ra tai nạn."}],"related":[{"hanzi":"开车","pinyin":"kāichē","vi":"lái xe"},{"hanzi":"驾驶","pinyin":"jiàshǐ","vi":"điều khiển"},{"hanzi":"驾照","pinyin":"jiàzhào","vi":"bằng lái"},{"hanzi":"酒驾","pinyin":"jiǔjià","vi":"lái xe khi say"}],"traditional":"駕車"},{"id":"架势","hanzi":"架势","pinyin":"jiàshi","meaning_vi":"tư thế, điệu bộ, dáng vẻ; tình thế, tình hình","explanation":"架 (giá – khung, thế đứng) + 势 (thế – dáng, thế) → dáng vẻ, điệu bộ; khẩu ngữ còn chỉ tình thế, chiều hướng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧍","examples":[{"type":"basic","zh":"看他那架势！","pinyin":"Kàn tā nà jiàshi!","vi":"Nhìn cái điệu bộ của anh ta kìa!"},{"type":"simple","zh":"看这架势，今天肯定要下大雨。","pinyin":"Kàn zhè jiàshi, jīntiān kěndìng yào xià dàyǔ.","vi":"Nhìn tình hình này, hôm nay chắc chắn sẽ mưa to."},{"type":"compound","zh":"虽然他摆出一副专家的架势，但是其实什么都不懂。","pinyin":"Suīrán tā bǎichū yí fù zhuānjiā de jiàshi, dànshì qíshí shénme dōu bù dǒng.","vi":"Tuy anh ta ra vẻ chuyên gia nhưng thật ra chẳng hiểu gì cả."}],"related":[{"hanzi":"姿势","pinyin":"zīshì","vi":"tư thế"},{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"},{"hanzi":"样子","pinyin":"yàngzi","vi":"dáng vẻ"},{"hanzi":"阵势","pinyin":"zhènshì","vi":"thế trận"}],"traditional":"架勢"},{"id":"架子","hanzi":"架子","pinyin":"jiàzi","meaning_vi":"giá, khung; thói làm cao","explanation":"架 (giá – cái giá) + 子 (tử – hậu tố) → giá đỡ, khung sườn; nghĩa bóng là thói làm cao, ra vẻ (摆架子).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🗄️","examples":[{"type":"basic","zh":"书放在架子上。","pinyin":"Shū fàng zài jiàzi shang.","vi":"Sách để trên giá."},{"type":"simple","zh":"这位教授一点儿架子也没有。","pinyin":"Zhè wèi jiàoshòu yìdiǎnr jiàzi yě méiyǒu.","vi":"Vị giáo sư này chẳng làm cao chút nào."},{"type":"compound","zh":"虽然他当了经理，但是从来不摆架子。","pinyin":"Suīrán tā dāngle jīnglǐ, dànshì cóngláibù bǎijiàzi.","vi":"Tuy đã làm giám đốc nhưng anh ấy chưa bao giờ làm cao."}],"related":[{"hanzi":"书架","pinyin":"shūjià","vi":"giá sách"},{"hanzi":"摆架子","pinyin":"bǎijiàzi","vi":"làm cao"},{"hanzi":"框架","pinyin":"kuàngjià","vi":"khung"},{"hanzi":"衣架","pinyin":"yījià","vi":"móc áo"}]},{"id":"奸诈","hanzi":"奸诈","pinyin":"jiānzhà","meaning_vi":"gian trá, xảo quyệt","explanation":"奸 (gian – gian tà) + 诈 (trá – lừa dối) → gian xảo, lừa lọc.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🦊","examples":[{"type":"basic","zh":"这个商人很奸诈。","pinyin":"Zhè ge shāngrén hěn jiānzhà.","vi":"Thương nhân này rất gian xảo."},{"type":"simple","zh":"他脸上露出了奸诈的笑容。","pinyin":"Tā liǎn shang lùchūle jiānzhà de xiàoróng.","vi":"Trên mặt hắn lộ ra nụ cười gian xảo."},{"type":"compound","zh":"虽然他外表老实，但是内心非常奸诈。","pinyin":"Suīrán tā wàibiǎo lǎoshi, dànshì nèixīn fēicháng jiānzhà.","vi":"Tuy bề ngoài hắn có vẻ thật thà nhưng bên trong rất gian trá."}],"related":[{"hanzi":"狡猾","pinyin":"jiǎohuá","vi":"xảo quyệt"},{"hanzi":"阴险","pinyin":"yīnxiǎn","vi":"nham hiểm"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"thành thật"},{"hanzi":"奸商","pinyin":"jiānshāng","vi":"gian thương"}],"traditional":"奸詐"},{"id":"歼灭","hanzi":"歼灭","pinyin":"jiānmiè","meaning_vi":"tiêu diệt","explanation":"歼 (tiêm – giết sạch) + 灭 (diệt – diệt) → tiêu diệt hoàn toàn, thường dùng trong quân sự.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"敌军被全部歼灭。","pinyin":"Díjūn bèi quánbù jiānmiè.","vi":"Quân địch bị tiêu diệt toàn bộ."},{"type":"simple","zh":"这场战斗歼灭了敌人一个师。","pinyin":"Zhè chǎng zhàndòu jiānmièle dírén yí ge shī.","vi":"Trận đánh này đã tiêu diệt một sư đoàn địch."},{"type":"compound","zh":"因为情报准确，所以我军很快歼灭了来犯之敌。","pinyin":"Yīnwèi qíngbào zhǔnquè, suǒyǐ wǒ jūn hěn kuài jiānmièle láifàn zhī dí.","vi":"Vì tình báo chính xác nên quân ta nhanh chóng tiêu diệt quân địch xâm phạm."}],"related":[{"hanzi":"消灭","pinyin":"xiāomiè","vi":"tiêu diệt"},{"hanzi":"击败","pinyin":"jībài","vi":"đánh bại"},{"hanzi":"摧毁","pinyin":"cuīhuǐ","vi":"phá hủy"},{"hanzi":"战斗","pinyin":"zhàndòu","vi":"chiến đấu"}],"traditional":"殲滅"},{"id":"间断","hanzi":"间断","pinyin":"jiànduàn","meaning_vi":"gián đoạn, đứt quãng","explanation":"间 (gián – cách ra) + 断 (đoạn – đứt) → bị ngắt quãng, không liên tục; thường dùng ở dạng phủ định 不间断, 从未间断.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏸️","examples":[{"type":"basic","zh":"雨下了一夜没间断。","pinyin":"Yǔ xiàle yí yè méi jiànduàn.","vi":"Mưa suốt đêm không ngớt."},{"type":"simple","zh":"他坚持跑步十年，从未间断过。","pinyin":"Tā jiānchí pǎobù shí nián, cóngwèi jiànduàn guo.","vi":"Anh ấy kiên trì chạy bộ mười năm, chưa từng gián đoạn."},{"type":"compound","zh":"如果学习经常间断，就很难取得进步。","pinyin":"Rúguǒ xuéxí jīngcháng jiànduàn, jiù hěn nán qǔdé jìnbù.","vi":"Nếu việc học thường xuyên bị gián đoạn thì rất khó tiến bộ."}],"related":[{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"不间断","pinyin":"bújiànduàn","vi":"không ngừng"},{"hanzi":"停顿","pinyin":"tíngdùn","vi":"ngừng lại"}],"traditional":"間斷"},{"id":"间隙","hanzi":"间隙","pinyin":"jiànxì","meaning_vi":"khe hở, khoảng trống; lúc rảnh giữa chừng","explanation":"间 (gián – khoảng giữa) + 隙 (khích – khe hở) → khe hở giữa hai vật; cũng chỉ khoảng thời gian trống giữa chừng.","hsk_level":"7-9","tags":["danh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"门和墙之间有间隙。","pinyin":"Mén hé qiáng zhījiān yǒu jiànxì.","vi":"Giữa cửa và tường có khe hở."},{"type":"simple","zh":"他利用工作间隙给家里打了个电话。","pinyin":"Tā lìyòng gōngzuò jiànxì gěi jiāli dǎle ge diànhuà.","vi":"Anh ấy tranh thủ lúc rảnh giữa giờ làm gọi điện về nhà."},{"type":"compound","zh":"虽然比赛间隙只有几分钟，但是教练还是调整了战术。","pinyin":"Suīrán bǐsài jiànxì zhǐyǒu jǐ fēnzhōng, dànshì jiàoliàn háishi tiáozhěngle zhànshù.","vi":"Tuy thời gian nghỉ giữa trận chỉ vài phút nhưng huấn luyện viên vẫn điều chỉnh chiến thuật."}],"related":[{"hanzi":"缝隙","pinyin":"fèngxì","vi":"khe hở"},{"hanzi":"空隙","pinyin":"kòngxì","vi":"khoảng trống"},{"hanzi":"间隔","pinyin":"jiàngé","vi":"khoảng cách"},{"hanzi":"空闲","pinyin":"kòngxián","vi":"lúc rảnh"}],"traditional":"間隙"},{"id":"肩负","hanzi":"肩负","pinyin":"jiānfù","meaning_vi":"gánh vác, đảm nhận","explanation":"肩 (kiên – vai) + 负 (phụ – mang, gánh) → vác trên vai; nghĩa bóng là gánh vác trách nhiệm, sứ mệnh.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎒","examples":[{"type":"basic","zh":"他肩负重任。","pinyin":"Tā jiānfù zhòngrèn.","vi":"Anh ấy gánh vác trọng trách."},{"type":"simple","zh":"年轻一代肩负着建设国家的使命。","pinyin":"Niánqīng yídài jiānfùzhe jiànshè guójiā de shǐmìng.","vi":"Thế hệ trẻ gánh vác sứ mệnh xây dựng đất nước."},{"type":"compound","zh":"因为肩负着全家的希望，所以他学习格外努力。","pinyin":"Yīnwèi jiānfùzhe quánjiā de xīwàng, suǒyǐ tā xuéxí géwài nǔlì.","vi":"Vì gánh trên vai hy vọng của cả nhà nên anh ấy học hành đặc biệt chăm chỉ."}],"related":[{"hanzi":"承担","pinyin":"chéngdān","vi":"đảm nhận"},{"hanzi":"担负","pinyin":"dānfù","vi":"gánh vác"},{"hanzi":"责任","pinyin":"zérèn","vi":"trách nhiệm"},{"hanzi":"使命","pinyin":"shǐmìng","vi":"sứ mệnh"}],"traditional":"肩負"},{"id":"艰险","hanzi":"艰险","pinyin":"jiānxiǎn","meaning_vi":"gian nguy, gian khổ và hiểm nguy","explanation":"艰 (gian – khó khăn) + 险 (hiểm – nguy hiểm) → vừa gian khổ vừa nguy hiểm.","hsk_level":"7-9","tags":["tinh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"前方道路艰险。","pinyin":"Qiánfāng dàolù jiānxiǎn.","vi":"Con đường phía trước đầy gian nguy."},{"type":"simple","zh":"他们经历了千辛万苦和种种艰险。","pinyin":"Tāmen jīnglìle qiānxīnwànkǔ hé zhǒngzhǒng jiānxiǎn.","vi":"Họ đã trải qua muôn vàn gian khổ và đủ loại hiểm nguy."},{"type":"compound","zh":"虽然这次探险十分艰险，但是队员们都没有退缩。","pinyin":"Suīrán zhè cì tànxiǎn shífēn jiānxiǎn, dànshì duìyuánmen dōu méiyǒu tuìsuō.","vi":"Tuy chuyến thám hiểm này vô cùng gian nguy nhưng các thành viên đều không lùi bước."}],"related":[{"hanzi":"艰难","pinyin":"jiānnán","vi":"gian nan"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"艰苦","pinyin":"jiānkǔ","vi":"gian khổ"},{"hanzi":"险峻","pinyin":"xiǎnjùn","vi":"hiểm trở"}],"traditional":"艱險"},{"id":"兼","hanzi":"兼","pinyin":"jiān","meaning_vi":"kiêm, đồng thời; gấp đôi","explanation":"兼 (kiêm – tay cầm hai bó lúa) → cùng lúc có hoặc làm hai việc trở lên, kiêm nhiệm.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎭","examples":[{"type":"basic","zh":"他是厂长兼书记。","pinyin":"Tā shì chǎngzhǎng jiān shūjì.","vi":"Ông ấy là giám đốc nhà máy kiêm bí thư."},{"type":"simple","zh":"这部手机美观与实用兼而有之。","pinyin":"Zhè bù shǒujī měiguān yǔ shíyòng jiān ér yǒu zhī.","vi":"Chiếc điện thoại này vừa đẹp vừa thực dụng."},{"type":"compound","zh":"虽然他白天上班，但是晚上还兼做家教。","pinyin":"Suīrán tā báitiān shàngbān, dànshì wǎnshang hái jiān zuò jiājiào.","vi":"Tuy ban ngày đi làm nhưng buổi tối anh ấy còn kiêm dạy kèm."}],"related":[{"hanzi":"兼任","pinyin":"jiānrèn","vi":"kiêm nhiệm"},{"hanzi":"兼职","pinyin":"jiānzhí","vi":"làm thêm"},{"hanzi":"兼顾","pinyin":"jiāngù","vi":"lo cả hai"},{"hanzi":"兼备","pinyin":"jiānbèi","vi":"có đủ cả"}]},{"id":"兼任","hanzi":"兼任","pinyin":"jiānrèn","meaning_vi":"kiêm nhiệm, kiêm chức","explanation":"兼 (kiêm) + 任 (nhiệm – đảm nhiệm) → cùng lúc đảm nhiệm thêm chức vụ khác.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他兼任班主任。","pinyin":"Tā jiānrèn bānzhǔrèn.","vi":"Anh ấy kiêm giáo viên chủ nhiệm."},{"type":"simple","zh":"王教授还兼任学校图书馆馆长。","pinyin":"Wáng jiàoshòu hái jiānrèn xuéxiào túshūguǎn guǎn zhǎng.","vi":"Giáo sư Vương còn kiêm giám đốc thư viện của trường."},{"type":"compound","zh":"因为人手不够，所以经理只好兼任销售主管。","pinyin":"Yīnwèi rénshǒu búgòu, suǒyǐ jīnglǐ zhǐhǎo jiānrèn xiāoshòu zhǔguǎn.","vi":"Vì thiếu người nên giám đốc đành kiêm luôn trưởng phòng kinh doanh."}],"related":[{"hanzi":"兼职","pinyin":"jiānzhí","vi":"làm thêm"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"专任","pinyin":"zhuānrèn","vi":"chuyên trách"},{"hanzi":"兼","pinyin":"jiān","vi":"kiêm"}]},{"id":"监护","hanzi":"监护","pinyin":"jiānhù","meaning_vi":"giám hộ, theo dõi chăm sóc","explanation":"监 (giám – trông coi) + 护 (hộ – bảo vệ) → trông nom bảo vệ; về pháp luật là giám hộ người chưa thành niên, trong y học là theo dõi bệnh nhân.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🛡️","examples":[{"type":"basic","zh":"父母是孩子的监护人。","pinyin":"Fùmǔ shì háizi de jiānhùrén.","vi":"Cha mẹ là người giám hộ của con."},{"type":"simple","zh":"病人术后被送进重症监护室。","pinyin":"Bìngrén shùhòu bèi sòng jìn zhòngzhèng jiānhù shì.","vi":"Sau phẫu thuật bệnh nhân được đưa vào phòng chăm sóc đặc biệt."},{"type":"compound","zh":"如果父母不能履行监护职责，法院就可以另行指定。","pinyin":"Rúguǒ fùmǔ bù néng lǚxíng jiānhù zhízé, fǎyuàn jiù kěyǐ lìngxíng zhǐdìng.","vi":"Nếu cha mẹ không thể thực hiện trách nhiệm giám hộ thì tòa án có thể chỉ định người khác."}],"related":[{"hanzi":"监护人","pinyin":"jiānhùrén","vi":"người giám hộ"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"},{"hanzi":"监督","pinyin":"jiāndū","vi":"giám sát"}],"traditional":"監護"},{"id":"减免","hanzi":"减免","pinyin":"jiǎnmiǎn","meaning_vi":"giảm hoặc miễn, miễn giảm","explanation":"减 (giảm) + 免 (miễn) → giảm bớt hoặc miễn hẳn (thuế, học phí, hình phạt...).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"学费可以减免。","pinyin":"Xuéfèi kěyǐ jiǎnmiǎn.","vi":"Học phí có thể được miễn giảm."},{"type":"simple","zh":"政府决定为小企业减免部分税收。","pinyin":"Zhèngfǔ jué dìngwèi xiǎoqǐyè jiǎnmiǎn bùfen shuìshōu.","vi":"Chính phủ quyết định miễn giảm một phần thuế cho doanh nghiệp nhỏ."},{"type":"compound","zh":"如果家庭经济困难，就可以申请减免学费。","pinyin":"Rúguǒ jiātíng jīngjì kùnnan, jiù kěyǐ shēnqǐng jiǎnmiǎn xuéfèi.","vi":"Nếu gia đình khó khăn về kinh tế thì có thể xin miễn giảm học phí."}],"related":[{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"giảm bớt"},{"hanzi":"免除","pinyin":"miǎnchú","vi":"miễn trừ"},{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"优惠","pinyin":"yōuhuì","vi":"ưu đãi"}],"traditional":"減免"},{"id":"减弱","hanzi":"减弱","pinyin":"jiǎnruò","meaning_vi":"suy yếu, yếu đi, giảm bớt","explanation":"减 (giảm) + 弱 (nhược – yếu) → yếu đi, giảm cường độ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔉","examples":[{"type":"basic","zh":"风势渐渐减弱。","pinyin":"Fēngshì jiànjiàn jiǎnruò.","vi":"Sức gió dần dần yếu đi."},{"type":"simple","zh":"随着年龄增长，他的视力明显减弱了。","pinyin":"Suízhe niánlíng zēngzhǎng, tā de shìlì míngxiǎn jiǎnruò le.","vi":"Cùng với tuổi tác, thị lực của ông ấy giảm rõ rệt."},{"type":"compound","zh":"虽然台风已经减弱，但是大家仍要注意安全。","pinyin":"Suīrán táifēng yǐjīng jiǎnruò, dànshì dàjiā réng yào zhùyì ānquán.","vi":"Tuy bão đã suy yếu nhưng mọi người vẫn phải chú ý an toàn."}],"related":[{"hanzi":"增强","pinyin":"zēngqiáng","vi":"tăng cường"},{"hanzi":"削弱","pinyin":"xuēruò","vi":"làm suy yếu"},{"hanzi":"衰退","pinyin":"shuāituì","vi":"suy thoái"},{"hanzi":"减轻","pinyin":"jiǎnqīng","vi":"giảm nhẹ"}],"traditional":"減弱"},{"id":"减压","hanzi":"减压","pinyin":"jiǎnyā","meaning_vi":"giảm áp lực, xả stress; giảm áp (suất)","explanation":"减 (giảm) + 压 (áp – sức ép) → giảm áp suất; nghĩa thường dùng là giải tỏa áp lực tinh thần.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🧘","examples":[{"type":"basic","zh":"运动可以减压。","pinyin":"Yùndòng kěyǐ jiǎnyā.","vi":"Vận động có thể giảm căng thẳng."},{"type":"simple","zh":"很多上班族靠听音乐来减压。","pinyin":"Hěn duō shàngbānzú kào tīng yīnyuè lái jiǎnyā.","vi":"Nhiều dân công sở nghe nhạc để giải tỏa áp lực."},{"type":"compound","zh":"如果学习压力太大，就要学会适当减压。","pinyin":"Rúguǒ xuéxí yālì tài dà, jiùyào xuéhuì shìdàng jiǎnyā.","vi":"Nếu áp lực học tập quá lớn thì phải biết cách giải tỏa hợp lý."}],"related":[{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"thả lỏng"},{"hanzi":"解压","pinyin":"jiěyā","vi":"giải tỏa áp lực"},{"hanzi":"缓解","pinyin":"huǎnjiě","vi":"làm dịu"}],"traditional":"減壓"},{"id":"检察","hanzi":"检察","pinyin":"jiǎnchá","meaning_vi":"kiểm sát","explanation":"检 (kiểm – kiểm tra) + 察 (sát – xem xét) → xem xét, điều tra; trong pháp luật chỉ công tác kiểm sát, truy tố.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他在检察院工作。","pinyin":"Tā zài jiǎncháyuàn gōngzuò.","vi":"Anh ấy làm việc ở viện kiểm sát."},{"type":"simple","zh":"检察机关依法对此案提起公诉。","pinyin":"Jiǎnchá jīguān yīfǎ duì cǐ àn tíqǐ gōngsù.","vi":"Cơ quan kiểm sát truy tố vụ án này theo pháp luật."},{"type":"compound","zh":"一旦证据确凿，检察官就会向法院提起诉讼。","pinyin":"Yídàn zhèngjù quèzáo, jiǎncháguān jiù huì xiàng fǎyuàn tíqǐ sùsòng.","vi":"Một khi chứng cứ xác thực, kiểm sát viên sẽ khởi tố lên tòa án."}],"related":[{"hanzi":"检察院","pinyin":"jiǎncháyuàn","vi":"viện kiểm sát"},{"hanzi":"检察官","pinyin":"jiǎncháguān","vi":"kiểm sát viên"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"},{"hanzi":"起诉","pinyin":"qǐsù","vi":"khởi tố"}],"traditional":"檢察"},{"id":"简称","hanzi":"简称","pinyin":"jiǎnchēng","meaning_vi":"gọi tắt, tên viết tắt","explanation":"简 (giản – gọn) + 称 (xưng – gọi) → gọi gọn lại, tên gọi tắt.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🔤","examples":[{"type":"basic","zh":"北京大学简称北大。","pinyin":"Běijīngdàxué jiǎnchēng Běidà.","vi":"Đại học Bắc Kinh gọi tắt là Bắc Đại."},{"type":"simple","zh":"世界贸易组织的简称是世贸组织。","pinyin":"Shìjièmàoyìzǔzhī de jiǎnchēng shì Shìmàozǔzhī.","vi":"Tên gọi tắt của Tổ chức Thương mại Thế giới là WTO."},{"type":"compound","zh":"因为全称太长，所以大家习惯用简称。","pinyin":"Yīnwèi quánchēng tài cháng, suǒyǐ dàjiā xí guànyòng jiǎnchēng.","vi":"Vì tên đầy đủ quá dài nên mọi người quen dùng tên gọi tắt."}],"related":[{"hanzi":"全称","pinyin":"quánchēng","vi":"tên đầy đủ"},{"hanzi":"缩写","pinyin":"suōxiě","vi":"viết tắt"},{"hanzi":"名称","pinyin":"míngchēng","vi":"tên gọi"},{"hanzi":"称呼","pinyin":"chēnghu","vi":"xưng hô"}],"traditional":"簡稱"},{"id":"简短","hanzi":"简短","pinyin":"jiǎnduǎn","meaning_vi":"ngắn gọn","explanation":"简 (giản – gọn) + 短 (đoản – ngắn) → ngắn gọn, ít lời.","hsk_level":"7-9","tags":["tinh-tu"],"image":"✂️","examples":[{"type":"basic","zh":"他的发言很简短。","pinyin":"Tā de fāyán hěn jiǎnduǎn.","vi":"Bài phát biểu của anh ấy rất ngắn gọn."},{"type":"simple","zh":"校长在开学典礼上做了简短的讲话。","pinyin":"Xiàozhǎng zài kāixué diǎnlǐ shang zuòle jiǎnduǎn de jiǎnghuà.","vi":"Hiệu trưởng có bài phát biểu ngắn gọn tại lễ khai giảng."},{"type":"compound","zh":"虽然信写得很简短，但是充满了感情。","pinyin":"Suīrán xìn xiě de hěn jiǎnduǎn, dànshì chōngmǎnle gǎnqíng.","vi":"Tuy lá thư viết rất ngắn gọn nhưng chan chứa tình cảm."}],"related":[{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"súc tích"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"đơn giản"},{"hanzi":"冗长","pinyin":"rǒngcháng","vi":"dài dòng"},{"hanzi":"扼要","pinyin":"èyào","vi":"tóm tắt"}],"traditional":"簡短"},{"id":"简洁","hanzi":"简洁","pinyin":"jiǎnjié","meaning_vi":"ngắn gọn, súc tích, gọn gàng","explanation":"简 (giản – gọn) + 洁 (khiết – sạch) → gọn và sạch, súc tích, không rườm rà.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📝","examples":[{"type":"basic","zh":"文章语言简洁。","pinyin":"Wénzhāng yǔyán jiǎnjié.","vi":"Ngôn ngữ bài viết súc tích."},{"type":"simple","zh":"这个房间的设计简洁又大方。","pinyin":"Zhè ge fángjiān de shèjì jiǎnjié yòu dàfang.","vi":"Thiết kế căn phòng này gọn gàng mà trang nhã."},{"type":"compound","zh":"如果文章写得简洁明了，读者就更容易理解。","pinyin":"Rúguǒ wénzhāng xiě de jiǎnjié míngliǎo, dúzhě jiù gèng róngyì lǐjiě.","vi":"Nếu bài viết ngắn gọn rõ ràng thì người đọc sẽ dễ hiểu hơn."}],"related":[{"hanzi":"简练","pinyin":"jiǎnliàn","vi":"gọn gàng"},{"hanzi":"简短","pinyin":"jiǎnduǎn","vi":"ngắn gọn"},{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"lắm lời"},{"hanzi":"精炼","pinyin":"jīngliàn","vi":"cô đọng"}],"traditional":"簡潔"},{"id":"简易","hanzi":"简易","pinyin":"jiǎnyì","meaning_vi":"đơn giản, giản tiện, sơ sài","explanation":"简 (giản – đơn giản) + 易 (dị – dễ) → đơn giản dễ làm; thường chỉ thứ dựng tạm, giản tiện.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🛖","examples":[{"type":"basic","zh":"这是个简易棚子。","pinyin":"Zhè shì ge jiǎnyì péngzi.","vi":"Đây là một cái lán dựng tạm."},{"type":"simple","zh":"工人们住在工地旁的简易房里。","pinyin":"Gōngrénmen zhùzài gōngdì páng de jiǎnyì fáng li.","vi":"Công nhân ở trong những căn nhà tạm cạnh công trường."},{"type":"compound","zh":"虽然这个工具很简易，但是用起来非常方便。","pinyin":"Suīrán zhè ge gōngjù hěn jiǎnyì, dànshì yòng qǐlái fēicháng fāngbiàn.","vi":"Tuy dụng cụ này rất đơn giản nhưng dùng lại vô cùng tiện lợi."}],"related":[{"hanzi":"简单","pinyin":"jiǎndān","vi":"đơn giản"},{"hanzi":"简便","pinyin":"jiǎnbiàn","vi":"giản tiện"},{"hanzi":"容易","pinyin":"róngyì","vi":"dễ dàng"},{"hanzi":"复杂","pinyin":"fùzá","vi":"phức tạp"}],"traditional":"簡易"},{"id":"见钱眼开","hanzi":"见钱眼开","pinyin":"jiànqián-yǎnkāi","meaning_vi":"thấy tiền sáng mắt, hám tiền","explanation":"Nghĩa đen: 见 (kiến – thấy) 钱 (tiền) 眼 (nhãn – mắt) 开 (khai – mở) → thấy tiền là mắt mở to; nghĩa bóng chỉ kẻ tham tiền, chỉ biết lợi ích riêng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤑","examples":[{"type":"basic","zh":"他是个见钱眼开的人。","pinyin":"Tā shì ge jiànqiányǎnkāi de rén.","vi":"Hắn là kẻ thấy tiền sáng mắt."},{"type":"simple","zh":"那个见钱眼开的商人又涨价了。","pinyin":"Nà ge jiànqiányǎnkāi de shāngrén yòu zhǎngjià le.","vi":"Gã thương nhân hám tiền đó lại tăng giá nữa rồi."},{"type":"compound","zh":"如果你见钱眼开，就很容易被别人利用。","pinyin":"Rúguǒ nǐ jiànqiányǎnkāi, jiù hěn róngyì bèi biérén lìyòng.","vi":"Nếu bạn thấy tiền là sáng mắt thì rất dễ bị người khác lợi dụng."}],"related":[{"hanzi":"唯利是图","pinyin":"wéilìshìtú","vi":"chỉ biết chạy theo lợi"},{"hanzi":"贪财","pinyin":"tāncái","vi":"tham tiền"},{"hanzi":"爱财如命","pinyin":"àicáirúmìng","vi":"coi tiền như mạng"},{"hanzi":"财迷","pinyin":"cáimí","vi":"kẻ mê tiền"}],"traditional":"見錢眼開"},{"id":"见外","hanzi":"见外","pinyin":"jiànwài","meaning_vi":"khách sáo, coi như người ngoài","explanation":"见 (kiến – xem như) + 外 (ngoại – người ngoài) → coi người khác như người ngoài, tức khách sáo; thường dùng trong câu 别见外.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"别见外，随便坐。","pinyin":"Bié jiànwài, suíbiàn zuò.","vi":"Đừng khách sáo, cứ ngồi tự nhiên."},{"type":"simple","zh":"咱们是老朋友了，你就别见外了。","pinyin":"Zánmen shì lǎopéngyou le, nǐ jiù bié jiànwài le.","vi":"Chúng ta là bạn cũ rồi, cậu đừng khách sáo nữa."},{"type":"compound","zh":"如果你再这么客气，就太见外了。","pinyin":"Rúguǒ nǐ zài zhème kèqi, jiù tài jiànwài le.","vi":"Nếu cậu còn khách khí thế này thì coi tôi là người ngoài quá."}],"related":[{"hanzi":"客气","pinyin":"kèqi","vi":"khách sáo"},{"hanzi":"外人","pinyin":"wàirén","vi":"người ngoài"},{"hanzi":"拘束","pinyin":"jūshù","vi":"gò bó"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"tự nhiên"}],"traditional":"見外"},{"id":"见证","hanzi":"见证","pinyin":"jiànzhèng","meaning_vi":"chứng kiến, làm chứng; bằng chứng, người làm chứng","explanation":"见 (kiến – thấy) + 证 (chứng – làm chứng) → tận mắt thấy và làm chứng; cũng chỉ vật làm chứng, bằng chứng.","hsk_level":"7-9","tags":["dong-tu"],"image":"👁️","examples":[{"type":"basic","zh":"我见证了他的成长。","pinyin":"Wǒ jiànzhèngle tā de chéngzhǎng.","vi":"Tôi đã chứng kiến sự trưởng thành của cậu ấy."},{"type":"simple","zh":"这座古桥见证了城市几百年的变迁。","pinyin":"Zhè zuò gǔ qiáo jiànzhèngle chéngshì jǐ bǎinián de biànqiān.","vi":"Cây cầu cổ này đã chứng kiến mấy trăm năm đổi thay của thành phố."},{"type":"compound","zh":"虽然婚礼很简单，但是有亲友们的见证就足够了。","pinyin":"Suīrán hūnlǐ hěn jiǎndān, dànshì yǒu qīnyǒumen de jiànzhèng jiù zúgòu le.","vi":"Tuy đám cưới rất đơn giản nhưng có người thân bạn bè chứng kiến là đủ rồi."}],"related":[{"hanzi":"证人","pinyin":"zhèngrén","vi":"nhân chứng"},{"hanzi":"目睹","pinyin":"mùdǔ","vi":"tận mắt thấy"},{"hanzi":"见证人","pinyin":"jiànzhèngrén","vi":"người làm chứng"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng minh"}],"traditional":"見證"},{"id":"建筑物","hanzi":"建筑物","pinyin":"jiànzhùwù","meaning_vi":"công trình kiến trúc, tòa nhà","explanation":"建筑 (kiến trúc – xây dựng) + 物 (vật) → vật được xây dựng nên, công trình kiến trúc.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏢","examples":[{"type":"basic","zh":"这座建筑物很高。","pinyin":"Zhè zuò jiànzhùwù hěn gāo.","vi":"Tòa nhà này rất cao."},{"type":"simple","zh":"地震中很多老建筑物都倒塌了。","pinyin":"Dìzhèn zhōng hěn duō lǎo jiànzhùwù dōu dǎotā le.","vi":"Trong trận động đất nhiều công trình cũ đã sụp đổ."},{"type":"compound","zh":"因为这座建筑物有三百年历史，所以被列为文物。","pinyin":"Yīnwèi zhè zuò jiànzhùwù yǒu sān bǎinián lìshǐ, suǒyǐ bèi lièwéi wénwù.","vi":"Vì công trình này có lịch sử ba trăm năm nên được xếp hạng di tích."}],"related":[{"hanzi":"建筑","pinyin":"jiànzhù","vi":"kiến trúc"},{"hanzi":"大楼","pinyin":"dàlóu","vi":"tòa nhà lớn"},{"hanzi":"房屋","pinyin":"fángwū","vi":"nhà cửa"},{"hanzi":"建造","pinyin":"jiànzào","vi":"xây dựng"}],"traditional":"建築物"},{"id":"贱","hanzi":"贱","pinyin":"jiàn","meaning_vi":"rẻ; hèn mọn, thấp hèn; đê tiện, hèn hạ","explanation":"贱 (tiện – rẻ, thấp hèn) → giá rẻ; địa vị thấp hèn; nghĩa xấu là hèn hạ, đê tiện (khẩu ngữ còn dùng để mắng yêu).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🪙","examples":[{"type":"basic","zh":"今年菜价很贱。","pinyin":"Jīnnián cài jià hěn jiàn.","vi":"Năm nay giá rau rất rẻ."},{"type":"simple","zh":"他认为工作没有贵贱之分。","pinyin":"Tā rènwéi gōngzuò méiyǒu guìjiàn zhī fēn.","vi":"Anh ấy cho rằng công việc không phân sang hèn."},{"type":"compound","zh":"虽然那批货卖得很贱，但是还是没人要。","pinyin":"Suīrán nà pī huò mài de hěn jiàn, dànshì háishi méi rén yào.","vi":"Tuy lô hàng đó bán rất rẻ nhưng vẫn không ai mua."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"贵","pinyin":"guì","vi":"đắt, quý"},{"hanzi":"低贱","pinyin":"dījiàn","vi":"thấp hèn"},{"hanzi":"贵贱","pinyin":"guìjiàn","vi":"sang hèn"}],"traditional":"賤"},{"id":"鉴赏","hanzi":"鉴赏","pinyin":"jiànshǎng","meaning_vi":"thưởng thức, giám định và thưởng ngoạn","explanation":"鉴 (giám – soi xét) + 赏 (thưởng – thưởng thức) → xem xét đánh giá và thưởng thức (nghệ thuật, đồ cổ...).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🖼️","examples":[{"type":"basic","zh":"他很会鉴赏古董。","pinyin":"Tā hěn huì jiànshǎng gǔdǒng.","vi":"Ông ấy rất giỏi thẩm định đồ cổ."},{"type":"simple","zh":"这门课培养学生的艺术鉴赏能力。","pinyin":"Zhè mén kè péiyǎng xuésheng de yìshù jiànshǎng nénglì.","vi":"Môn học này bồi dưỡng năng lực thưởng thức nghệ thuật của học sinh."},{"type":"compound","zh":"只要多看名家作品，你的鉴赏水平就会提高。","pinyin":"Zhǐyào duō kàn míngjiā zuòpǐn, nǐ de jiànshǎng shuǐpíng jiù huì tígāo.","vi":"Chỉ cần xem nhiều tác phẩm danh gia, trình độ thưởng thức của bạn sẽ nâng cao."}],"related":[{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức"},{"hanzi":"鉴定","pinyin":"jiàndìng","vi":"giám định"},{"hanzi":"品味","pinyin":"pǐnwèi","vi":"thưởng thức"},{"hanzi":"收藏","pinyin":"shōucáng","vi":"sưu tầm"}],"traditional":"鑑賞"},{"id":"僵","hanzi":"僵","pinyin":"jiāng","meaning_vi":"cứng đờ, bế tắc, căng thẳng","explanation":"僵 (cương – cứng đờ) → cứng đờ không cử động được; nghĩa bóng là tình thế bế tắc, quan hệ căng thẳng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🧊","examples":[{"type":"basic","zh":"我的手冻僵了。","pinyin":"Wǒ de shǒu dòngjiāng le.","vi":"Tay tôi cóng cứng rồi."},{"type":"simple","zh":"两个人的关系最近闹得很僵。","pinyin":"Liǎng ge rén de guānxi zuìjìn nào de hěn jiāng.","vi":"Gần đây quan hệ hai người trở nên rất căng thẳng."},{"type":"compound","zh":"如果双方都不肯让步，谈判就会僵在那里。","pinyin":"Rúguǒ shuāngfāng dōu bùkěn ràngbù, tánpàn jiù huì jiāng zài nàlǐ.","vi":"Nếu hai bên đều không chịu nhượng bộ thì cuộc đàm phán sẽ bế tắc."}],"related":[{"hanzi":"僵硬","pinyin":"jiāngyìng","vi":"cứng đờ"},{"hanzi":"僵局","pinyin":"jiāngjú","vi":"thế bế tắc"},{"hanzi":"僵持","pinyin":"jiāngchí","vi":"giằng co"},{"hanzi":"冻僵","pinyin":"dòngjiāng","vi":"cóng cứng"}]},{"id":"讲述","hanzi":"讲述","pinyin":"jiǎngshù","meaning_vi":"kể, kể lại, thuật lại","explanation":"讲 (giảng – nói) + 述 (thuật – trình bày) → kể lại, thuật lại sự việc, câu chuyện.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"奶奶在讲述往事。","pinyin":"Nǎinai zài jiǎngshù wǎngshì.","vi":"Bà đang kể lại chuyện xưa."},{"type":"simple","zh":"这部电影讲述了一个感人的故事。","pinyin":"Zhè bù diànyǐng jiǎngshùle yí ge gǎnrén de gùshi.","vi":"Bộ phim này kể một câu chuyện cảm động."},{"type":"compound","zh":"虽然他讲述得很平静，但是大家都听得流泪了。","pinyin":"Suīrán tā jiǎngshù de hěn píngjìng, dànshì dàjiā dōu tīng de liúlèi le.","vi":"Tuy anh ấy kể rất bình thản nhưng mọi người nghe đều rơi nước mắt."}],"related":[{"hanzi":"叙述","pinyin":"xùshù","vi":"tường thuật"},{"hanzi":"描述","pinyin":"miáoshù","vi":"miêu tả"},{"hanzi":"讲","pinyin":"jiǎng","vi":"nói, kể"},{"hanzi":"陈述","pinyin":"chénshù","vi":"trình bày"}],"traditional":"講述"},{"id":"奖品","hanzi":"奖品","pinyin":"jiǎngpǐn","meaning_vi":"phần thưởng, giải thưởng (hiện vật)","explanation":"奖 (tưởng – khen thưởng) + 品 (phẩm – vật phẩm) → vật phẩm dùng để thưởng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🏆","examples":[{"type":"basic","zh":"这是比赛的奖品。","pinyin":"Zhè shì bǐsài de jiǎngpǐn.","vi":"Đây là phần thưởng của cuộc thi."},{"type":"simple","zh":"他把奖品送给了班上的同学。","pinyin":"Tā bǎ jiǎngpǐn sònggěile bānshang de tóngxué.","vi":"Cậu ấy tặng phần thưởng cho bạn cùng lớp."},{"type":"compound","zh":"如果你答对所有题目，就能获得一份奖品。","pinyin":"Rúguǒ nǐ dáduì suǒyǒu tímù, jiù néng huòdé yí fèn jiǎngpǐn.","vi":"Nếu bạn trả lời đúng tất cả câu hỏi thì sẽ nhận được một phần quà."}],"related":[{"hanzi":"奖励","pinyin":"jiǎnglì","vi":"khen thưởng"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"},{"hanzi":"奖项","pinyin":"jiǎngxiàng","vi":"hạng mục giải"},{"hanzi":"礼品","pinyin":"lǐpǐn","vi":"quà tặng"}],"traditional":"獎品"},{"id":"奖项","hanzi":"奖项","pinyin":"jiǎngxiàng","meaning_vi":"giải thưởng, hạng mục giải","explanation":"奖 (tưởng – giải thưởng) + 项 (hạng – hạng mục) → các hạng mục giải thưởng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🥇","examples":[{"type":"basic","zh":"这部电影获得多个奖项。","pinyin":"Zhè bù diànyǐng huòdé duōge jiǎngxiàng.","vi":"Bộ phim này giành được nhiều giải thưởng."},{"type":"simple","zh":"今年的音乐节一共设了十个奖项。","pinyin":"Jīnnián de yīnyuèjié yígòng shèle shí ge jiǎngxiàng.","vi":"Liên hoan âm nhạc năm nay có tổng cộng mười hạng mục giải."},{"type":"compound","zh":"虽然他没得到最高奖项，但是表现已经非常出色。","pinyin":"Suīrán tā méi dédào zuì gāo jiǎngxiàng, dànshì biǎoxiàn yǐjīng fēicháng chūsè.","vi":"Tuy anh ấy không đoạt giải cao nhất nhưng màn thể hiện đã rất xuất sắc."}],"related":[{"hanzi":"奖品","pinyin":"jiǎngpǐn","vi":"phần thưởng"},{"hanzi":"大奖","pinyin":"dàjiǎng","vi":"giải lớn"},{"hanzi":"获奖","pinyin":"huòjiǎng","vi":"đoạt giải"},{"hanzi":"颁奖","pinyin":"bānjiǎng","vi":"trao giải"}],"traditional":"獎項"},{"id":"交付","hanzi":"交付","pinyin":"jiāofù","meaning_vi":"giao, bàn giao, chuyển giao","explanation":"交 (giao – trao) + 付 (phó – giao cho) → trao cho, bàn giao (hàng hóa, công trình, nhiệm vụ).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📦","examples":[{"type":"basic","zh":"新房下月交付。","pinyin":"Xīnfáng xiàyuè jiāofù.","vi":"Nhà mới sẽ bàn giao vào tháng sau."},{"type":"simple","zh":"这批订单必须在月底前交付客户。","pinyin":"Zhè pī dìngdān bìxū zài yuèdǐ qián jiāofù kèhù.","vi":"Lô đơn hàng này phải giao cho khách trước cuối tháng."},{"type":"compound","zh":"一旦工程验收合格，就可以正式交付使用。","pinyin":"Yídàn gōngchéng yànshōu hégé, jiù kěyǐ zhèngshì jiāofù shǐyòng.","vi":"Một khi công trình nghiệm thu đạt yêu cầu thì có thể chính thức bàn giao đưa vào sử dụng."}],"related":[{"hanzi":"交给","pinyin":"jiāogěi","vi":"giao cho"},{"hanzi":"移交","pinyin":"yíjiāo","vi":"chuyển giao"},{"hanzi":"支付","pinyin":"zhīfù","vi":"chi trả"},{"hanzi":"交货","pinyin":"jiāohuò","vi":"giao hàng"}]},{"id":"交集","hanzi":"交集","pinyin":"jiāojí","meaning_vi":"đan xen; điểm chung, giao điểm; giao (tập hợp)","explanation":"交 (giao – giao nhau) + 集 (tập – tụ lại) → nhiều thứ cùng đan xen (cảm xúc lẫn lộn); nay hay dùng nghĩa điểm chung, sự giao thoa; trong toán là phép giao của tập hợp.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔀","examples":[{"type":"basic","zh":"他悲喜交集。","pinyin":"Tā bēi xǐ jiāojí.","vi":"Anh ấy buồn vui lẫn lộn."},{"type":"simple","zh":"我们俩的生活圈子几乎没有交集。","pinyin":"Wǒmen liǎ de shēnghuó quānzi jīhū méiyǒu jiāojí.","vi":"Cuộc sống của hai chúng tôi gần như không có điểm giao nhau."},{"type":"compound","zh":"虽然毕业后很少见面，但是我们的工作仍有交集。","pinyin":"Suīrán bìyè hòu hěn shǎojiàn miàn, dànshì wǒmen de gōngzuò réng yǒu jiāojí.","vi":"Tuy sau khi tốt nghiệp ít gặp nhau nhưng công việc của chúng tôi vẫn có liên quan."}],"related":[{"hanzi":"交叉","pinyin":"jiāochā","vi":"giao nhau"},{"hanzi":"百感交集","pinyin":"bǎigǎnjiāojí","vi":"trăm mối cảm xúc"},{"hanzi":"并集","pinyin":"bìngjí","vi":"phép hợp"},{"hanzi":"共同点","pinyin":"gòngtóngdiǎn","vi":"điểm chung"}]},{"id":"交界","hanzi":"交界","pinyin":"Jiāojiè","meaning_vi":"giáp ranh, chung biên giới","explanation":"交 (giao – tiếp giáp) + 界 (giới – ranh giới) → hai vùng tiếp giáp nhau ở đường ranh giới.","hsk_level":"7-9","tags":["dong-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"两省在此交界。","pinyin":"Liǎng shěng zài cǐ Jiāojiè.","vi":"Hai tỉnh giáp ranh tại đây."},{"type":"simple","zh":"这个小镇位于三国交界的地方。","pinyin":"Zhè ge xiǎozhèn wèiyú Sānguó Jiāojiè de dìfang.","vi":"Thị trấn nhỏ này nằm ở nơi giáp ranh ba nước."},{"type":"compound","zh":"因为地处两省交界，所以这里的口音很特别。","pinyin":"Yīnwèi dìchǔ liǎng shěng Jiāojiè, suǒyǐ zhèlǐ de kǒuyīn hěn tèbié.","vi":"Vì nằm ở chỗ giáp ranh hai tỉnh nên giọng nói ở đây rất đặc biệt."}],"related":[{"hanzi":"边界","pinyin":"biānjiè","vi":"biên giới"},{"hanzi":"接壤","pinyin":"jiērǎng","vi":"tiếp giáp"},{"hanzi":"界线","pinyin":"jièxiàn","vi":"đường ranh giới"},{"hanzi":"边境","pinyin":"biānjìng","vi":"vùng biên"}]},{"id":"交情","hanzi":"交情","pinyin":"jiāoqing","meaning_vi":"tình bạn, giao tình","explanation":"交 (giao – qua lại) + 情 (tình – tình cảm) → tình cảm hình thành qua giao du, tình bạn.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"我们交情很深。","pinyin":"Wǒmen jiāoqing hěn shēn.","vi":"Tình bạn của chúng tôi rất sâu sắc."},{"type":"simple","zh":"他俩有二十多年的交情了。","pinyin":"Tā liǎ yǒu èrshí duōnián de jiāoqing le.","vi":"Hai người họ có giao tình hơn hai mươi năm rồi."},{"type":"compound","zh":"虽然我们交情不错，但是原则问题不能让步。","pinyin":"Suīrán wǒmen jiāoqing búcuò, dànshì yuánzé wèntí bù néng ràngbù.","vi":"Tuy chúng ta thân nhau nhưng vấn đề nguyên tắc thì không thể nhượng bộ."}],"related":[{"hanzi":"友情","pinyin":"yǒuqíng","vi":"tình bạn"},{"hanzi":"交往","pinyin":"jiāowǎng","vi":"qua lại"},{"hanzi":"情谊","pinyin":"qíngyì","vi":"tình nghĩa"},{"hanzi":"关系","pinyin":"guānxi","vi":"quan hệ"}]},{"id":"郊外","hanzi":"郊外","pinyin":"jiāowài","meaning_vi":"ngoại ô, vùng ven","explanation":"郊 (giao – vùng ven thành) + 外 (ngoại – bên ngoài) → vùng bên ngoài thành phố, ngoại ô.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🌳","examples":[{"type":"basic","zh":"周末去郊外玩吧。","pinyin":"Zhōumò qù jiāowài wán ba.","vi":"Cuối tuần đi chơi ngoại ô nhé."},{"type":"simple","zh":"他在郊外买了一套带花园的房子。","pinyin":"Tā zài jiāowài mǎile yítào dài huāyuán de fángzi.","vi":"Anh ấy mua một căn nhà có vườn ở ngoại ô."},{"type":"compound","zh":"虽然郊外离市区很远，但是空气特别新鲜。","pinyin":"Suīrán jiāowài lí shìqū hěn yuǎn, dànshì kōngqì tèbié xīnxiān.","vi":"Tuy ngoại ô cách nội thành xa nhưng không khí rất trong lành."}],"related":[{"hanzi":"郊区","pinyin":"jiāoqū","vi":"vùng ngoại ô"},{"hanzi":"市区","pinyin":"shìqū","vi":"nội thành"},{"hanzi":"郊游","pinyin":"jiāoyóu","vi":"đi chơi ngoại ô"},{"hanzi":"乡下","pinyin":"xiāngxia","vi":"nông thôn"}]},{"id":"郊游","hanzi":"郊游","pinyin":"jiāoyóu","meaning_vi":"đi chơi ngoại ô, dã ngoại","explanation":"郊 (giao – ngoại ô) + 游 (du – đi chơi) → đi chơi, dã ngoại ở vùng ngoại ô.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧺","examples":[{"type":"basic","zh":"明天我们去郊游。","pinyin":"Míngtiān wǒmen qù jiāoyóu.","vi":"Ngày mai chúng ta đi dã ngoại."},{"type":"simple","zh":"春天是全家一起郊游的好时候。","pinyin":"Chūntiān shì quánjiā yìqǐ jiāoyóu de hǎo shíhou.","vi":"Mùa xuân là thời điểm tốt để cả nhà cùng đi dã ngoại."},{"type":"compound","zh":"如果明天天气好，我们就带孩子去郊游。","pinyin":"Rúguǒ míngtiān tiānqì hǎo, wǒmen jiù dàiháizi qù jiāoyóu.","vi":"Nếu mai trời đẹp, chúng ta sẽ đưa con đi dã ngoại."}],"related":[{"hanzi":"野餐","pinyin":"yěcān","vi":"picnic"},{"hanzi":"郊外","pinyin":"jiāowài","vi":"ngoại ô"},{"hanzi":"春游","pinyin":"chūnyóu","vi":"đi chơi xuân"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"du lịch"}],"traditional":"郊遊"},{"id":"娇惯","hanzi":"娇惯","pinyin":"jiāoguàn","meaning_vi":"nuông chiều, chiều hư","explanation":"娇 (kiều – yêu kiều, nũng nịu) + 惯 (quán – chiều theo thói) → chiều chuộng quá mức, làm hư.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🍭","examples":[{"type":"basic","zh":"别娇惯孩子。","pinyin":"Bié jiāoguàn háizi.","vi":"Đừng nuông chiều con cái."},{"type":"simple","zh":"她从小被父母娇惯，什么家务都不会。","pinyin":"Tā cóngxiǎo bèi fùmǔ jiāoguàn, shénme jiāwù dōu bú huì.","vi":"Từ nhỏ cô ấy được bố mẹ nuông chiều, việc nhà gì cũng không biết."},{"type":"compound","zh":"如果总是娇惯孩子，他们就很难学会独立。","pinyin":"Rúguǒ zǒngshì jiāoguàn háizi, tāmen jiù hěn nán xuéhuì dúlì.","vi":"Nếu cứ nuông chiều con thì chúng rất khó học được tính tự lập."}],"related":[{"hanzi":"溺爱","pinyin":"nì'ài","vi":"cưng chiều"},{"hanzi":"宠爱","pinyin":"chǒng'ài","vi":"yêu chiều"},{"hanzi":"惯坏","pinyin":"guànhuài","vi":"chiều hư"},{"hanzi":"娇气","pinyin":"jiāoqi","vi":"yếu đuối, nhõng nhẽo"}],"traditional":"嬌慣"},{"id":"胶囊","hanzi":"胶囊","pinyin":"jiāonáng","meaning_vi":"viên nang","explanation":"胶 (giao – keo, gelatin) + 囊 (nang – túi) → túi nhỏ làm bằng gelatin chứa thuốc, viên nang.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"每天吃两粒胶囊。","pinyin":"Měitiān chī liǎng lì jiāonáng.","vi":"Mỗi ngày uống hai viên nang."},{"type":"simple","zh":"这种胶囊要用温水吞服。","pinyin":"Zhè zhǒng jiāonáng yào yòng wēn shuǐ tūnfú.","vi":"Loại viên nang này phải nuốt với nước ấm."},{"type":"compound","zh":"如果孩子吞不下胶囊，就可以打开倒出药粉。","pinyin":"Rúguǒ háizi tūn búxià jiāonáng, jiù kěyǐ dǎkāi dào chū yào fěn.","vi":"Nếu trẻ không nuốt được viên nang thì có thể mở ra lấy bột thuốc."}],"related":[{"hanzi":"药片","pinyin":"yàopiàn","vi":"viên thuốc"},{"hanzi":"药丸","pinyin":"yàowán","vi":"viên hoàn"},{"hanzi":"胶水","pinyin":"jiāoshuǐ","vi":"keo dán"},{"hanzi":"时间胶囊","pinyin":"shíjiānjiāonáng","vi":"hộp thời gian"}],"traditional":"膠囊"},{"id":"胶片","hanzi":"胶片","pinyin":"jiāopiàn","meaning_vi":"phim (chụp ảnh), phim nhựa","explanation":"胶 (giao – nhựa) + 片 (phiến – tấm mỏng) → tấm nhựa mỏng phủ chất cảm quang, phim chụp ảnh.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎞️","examples":[{"type":"basic","zh":"他还在用胶片相机。","pinyin":"Tā hái zài yòng jiāopiàn xiàngjī.","vi":"Anh ấy vẫn còn dùng máy ảnh phim."},{"type":"simple","zh":"这部老电影是用胶片拍摄的。","pinyin":"Zhè bù lǎo diànyǐng shì yòng jiāopiàn pāishè de.","vi":"Bộ phim cũ này được quay bằng phim nhựa."},{"type":"compound","zh":"虽然数码相机很方便，但是很多人还是喜欢胶片的感觉。","pinyin":"Suīrán shùmǎ xiàngjī hěn fāngbiàn, dànshì hěn duō rén háishi xǐhuan jiāopiàn de gǎnjué.","vi":"Tuy máy ảnh kỹ thuật số rất tiện nhưng nhiều người vẫn thích cảm giác của phim."}],"related":[{"hanzi":"底片","pinyin":"dǐpiàn","vi":"phim âm bản"},{"hanzi":"胶卷","pinyin":"jiāojuǎn","vi":"cuộn phim"},{"hanzi":"相机","pinyin":"xiàngjī","vi":"máy ảnh"},{"hanzi":"数码","pinyin":"shùmǎ","vi":"kỹ thuật số"}],"traditional":"膠片"},{"id":"焦","hanzi":"焦","pinyin":"jiāo","meaning_vi":"cháy, khét; sốt ruột, lo âu","explanation":"焦 (tiêu – cháy sém) → bị lửa đốt cháy sém, khét; nghĩa bóng là lo lắng, sốt ruột như lửa đốt.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"米饭烧焦了。","pinyin":"Mǐfàn shāojiāo le.","vi":"Cơm bị cháy rồi."},{"type":"simple","zh":"等了半天还没消息，他心里很焦。","pinyin":"Děngle bàn tiān hái méi xiāoxi, tā xīnli hěn jiāo.","vi":"Đợi mãi vẫn chưa có tin, trong lòng anh ấy rất nóng ruột."},{"type":"compound","zh":"如果火开得太大，面包就会烤焦。","pinyin":"Rúguǒ huǒ kāi de tài dà, miànbāo jiù huì kǎojiāo.","vi":"Nếu để lửa quá to thì bánh mì sẽ bị nướng cháy."}],"related":[{"hanzi":"焦急","pinyin":"jiāojí","vi":"sốt ruột"},{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"烧焦","pinyin":"shāojiāo","vi":"cháy khét"},{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"}]},{"id":"焦躁","hanzi":"焦躁","pinyin":"jiāozào","meaning_vi":"bồn chồn, nôn nóng, bực bội","explanation":"焦 (tiêu – nóng ruột) + 躁 (táo – bứt rứt) → lo lắng bồn chồn, không yên.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"他显得很焦躁。","pinyin":"Tā xiǎnde hěn jiāozào.","vi":"Anh ấy trông rất bồn chồn."},{"type":"simple","zh":"堵车一个多小时，司机们都焦躁起来。","pinyin":"Dǔchē yí ge duō xiǎoshí, sījīmen dōu jiāozào qǐlái.","vi":"Tắc đường hơn một tiếng, các tài xế đều trở nên bực bội."},{"type":"compound","zh":"因为一直没收到录取通知，所以她越来越焦躁。","pinyin":"Yīnwèi yìzhí méi shōudào lùqǔ tōngzhī, suǒyǐ tā yuèláiyuè jiāozào.","vi":"Vì mãi chưa nhận được giấy báo trúng tuyển nên cô ấy ngày càng bồn chồn."}],"related":[{"hanzi":"焦急","pinyin":"jiāojí","vi":"sốt ruột"},{"hanzi":"烦躁","pinyin":"fánzào","vi":"bực bội"},{"hanzi":"急躁","pinyin":"jízào","vi":"nóng vội"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình tĩnh"}]},{"id":"礁石","hanzi":"礁石","pinyin":"jiāoshí","meaning_vi":"đá ngầm","explanation":"礁 (tiêu – đá ngầm) + 石 (thạch – đá) → đá nhô lên hoặc nằm ngầm dưới mặt biển.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🪨","examples":[{"type":"basic","zh":"海浪拍打着礁石。","pinyin":"Hǎilàng pāidǎzhe jiāoshí.","vi":"Sóng biển vỗ vào đá ngầm."},{"type":"simple","zh":"孩子们坐在礁石上看日落。","pinyin":"Háizimen zuò zài jiāoshí shang kàn rìluò.","vi":"Bọn trẻ ngồi trên mỏm đá ngắm hoàng hôn."},{"type":"compound","zh":"因为夜里看不清礁石，所以渔船不敢靠岸。","pinyin":"Yīnwèi yèli kànbuqīng jiāoshí, suǒyǐ yúchuán bù gǎn kào'àn.","vi":"Vì ban đêm không nhìn rõ đá ngầm nên thuyền đánh cá không dám cập bờ."}],"related":[{"hanzi":"暗礁","pinyin":"ànjiāo","vi":"đá ngầm ẩn"},{"hanzi":"珊瑚礁","pinyin":"shānhújiāo","vi":"rạn san hô"},{"hanzi":"触礁","pinyin":"chùjiāo","vi":"mắc cạn đá ngầm"},{"hanzi":"岩石","pinyin":"yánshí","vi":"nham thạch"}]},{"id":"绞","hanzi":"绞","pinyin":"jiǎo","meaning_vi":"xoắn, vắt, quấn; treo cổ","explanation":"绞 (giảo – vặn xoắn) → xoắn các sợi lại, vặn vắt; cũng chỉ hình phạt treo cổ (绞刑).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌀","examples":[{"type":"basic","zh":"她把毛巾绞干了。","pinyin":"Tā bǎ máojīn jiǎo gān le.","vi":"Cô ấy vắt khô khăn mặt."},{"type":"simple","zh":"这道难题让我绞尽了脑汁。","pinyin":"Zhè dào nántí ràng wǒ jiǎo jìnle nǎozhī.","vi":"Bài toán khó này khiến tôi vắt óc suy nghĩ."},{"type":"compound","zh":"如果钓线绞在一起，就很难解开了。","pinyin":"Rúguǒ diào xiàn jiǎo zài yìqǐ, jiù hěn nán jiěkāi le.","vi":"Nếu dây câu xoắn vào nhau thì rất khó gỡ ra."}],"related":[{"hanzi":"拧","pinyin":"nǐng","vi":"vắt, vặn"},{"hanzi":"缠绕","pinyin":"chánrào","vi":"quấn quanh"},{"hanzi":"绞尽脑汁","pinyin":"jiǎojìnnǎozhī","vi":"vắt óc suy nghĩ"},{"hanzi":"绞刑","pinyin":"jiǎoxíng","vi":"án treo cổ"}],"traditional":"絞"},{"id":"矫正","hanzi":"矫正","pinyin":"jiǎozhèng","meaning_vi":"nắn chỉnh, uốn nắn, chỉnh sửa","explanation":"矫 (kiểu – uốn cho thẳng) + 正 (chính – ngay) → uốn cho ngay, sửa cho đúng (răng, thị lực, tư thế, sai lệch).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🦷","examples":[{"type":"basic","zh":"他在矫正牙齿。","pinyin":"Tā zài jiǎozhèng yáchǐ.","vi":"Cậu ấy đang niềng răng."},{"type":"simple","zh":"戴眼镜可以矫正近视带来的问题。","pinyin":"Dài yǎnjìng kěyǐ jiǎozhèng jìnshì dàilái de wèntí.","vi":"Đeo kính có thể khắc phục vấn đề do cận thị gây ra."},{"type":"compound","zh":"如果坐姿不正确，就要尽早矫正。","pinyin":"Rúguǒ zuòzī bú zhèngquè, jiùyào jǐnzǎo jiǎozhèng.","vi":"Nếu tư thế ngồi không đúng thì phải sớm chỉnh lại."}],"related":[{"hanzi":"纠正","pinyin":"jiūzhèng","vi":"sửa chữa"},{"hanzi":"改正","pinyin":"gǎizhèng","vi":"sửa đúng"},{"hanzi":"矫治","pinyin":"jiǎozhì","vi":"chữa trị nắn chỉnh"},{"hanzi":"校正","pinyin":"jiàozhèng","vi":"hiệu chỉnh"}],"traditional":"矯正"},{"id":"搅","hanzi":"搅","pinyin":"jiǎo","meaning_vi":"khuấy, trộn; quấy rầy","explanation":"搅 (giảo – khuấy) → dùng que khuấy cho đều; nghĩa bóng là quấy rầy, làm rối.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥄","examples":[{"type":"basic","zh":"把咖啡搅一搅。","pinyin":"Bǎ kāfēi jiǎo yi jiǎo.","vi":"Khuấy cà phê một chút."},{"type":"simple","zh":"他正在睡觉，你别去搅他。","pinyin":"Tā zhèngzài shuìjiào, nǐ bié qù jiǎo tā.","vi":"Anh ấy đang ngủ, đừng đi quấy rầy."},{"type":"compound","zh":"如果不把面糊搅匀，蛋糕就会有疙瘩。","pinyin":"Rúguǒ bù bǎ miànhú jiǎo yún, dàngāo jiù huì yǒu gēda.","vi":"Nếu không khuấy đều bột thì bánh sẽ bị vón cục."}],"related":[{"hanzi":"搅拌","pinyin":"jiǎobàn","vi":"khuấy trộn"},{"hanzi":"打搅","pinyin":"dǎjiǎo","vi":"quấy rầy"},{"hanzi":"搅和","pinyin":"jiǎohuo","vi":"làm rối"},{"hanzi":"拌","pinyin":"bàn","vi":"trộn"}],"traditional":"攪"},{"id":"缴","hanzi":"缴","pinyin":"jiǎo","meaning_vi":"nộp, đóng; thu giữ","explanation":"缴 (giảo/chước – nộp, giao nộp) → nộp, đóng (thuế, phí); cũng chỉ thu giữ vũ khí (缴获).","hsk_level":"7-9","tags":["dong-tu"],"image":"📥","examples":[{"type":"basic","zh":"请按时缴税。","pinyin":"Qǐng ànshí jiǎoshuì.","vi":"Vui lòng nộp thuế đúng hạn."},{"type":"simple","zh":"警察缴了歹徒手里的刀。","pinyin":"Jǐngchá jiǎole dǎitú shǒuli de dāo.","vi":"Cảnh sát tước con dao trong tay tên côn đồ."},{"type":"compound","zh":"如果不按时缴水电费，就会被停水停电。","pinyin":"Rúguǒ bú ànshí jiǎo shuǐdiànfèi, jiù huì bèi tíngshuǐ tíngdiàn.","vi":"Nếu không đóng tiền điện nước đúng hạn thì sẽ bị cắt điện nước."}],"related":[{"hanzi":"缴纳","pinyin":"jiǎonà","vi":"nộp"},{"hanzi":"上缴","pinyin":"shàngjiǎo","vi":"nộp lên"},{"hanzi":"缴获","pinyin":"jiǎohuò","vi":"thu giữ"},{"hanzi":"交","pinyin":"jiāo","vi":"nộp, giao"}],"traditional":"繳"},{"id":"缴费","hanzi":"缴费","pinyin":"jiǎofèi","meaning_vi":"đóng phí, nộp tiền","explanation":"缴 (giảo – nộp) + 费 (phí – chi phí) → nộp các khoản phí.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"请先去窗口缴费。","pinyin":"Qǐng xiān qù chuāngkǒu jiǎofèi.","vi":"Vui lòng ra quầy đóng phí trước."},{"type":"simple","zh":"现在用手机就可以在网上缴费。","pinyin":"Xiànzài yòng shǒujī jiù kěyǐ zài wǎngshang jiǎofèi.","vi":"Bây giờ dùng điện thoại là có thể đóng phí trực tuyến."},{"type":"compound","zh":"如果超过缴费期限，就要支付滞纳金。","pinyin":"Rúguǒ chāoguò jiǎofèi qīxiàn, jiùyào zhīfù zhìnàjīn.","vi":"Nếu quá hạn đóng phí thì phải trả tiền phạt chậm nộp."}],"related":[{"hanzi":"付款","pinyin":"fùkuǎn","vi":"thanh toán"},{"hanzi":"缴纳","pinyin":"jiǎonà","vi":"nộp"},{"hanzi":"收费","pinyin":"shōufèi","vi":"thu phí"},{"hanzi":"费用","pinyin":"fèiyong","vi":"chi phí"}],"traditional":"繳費"},{"id":"叫板","hanzi":"叫板","pinyin":"jiàobǎn","meaning_vi":"thách thức, thách đấu; (kịch) xướng dẫn","explanation":"叫 (khiếu – kêu) + 板 (bản – nhịp phách) → trong hí kịch là kéo dài câu nói để ra hiệu nhạc công vào nhịp; khẩu ngữ nay là thách thức, thách đấu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥊","examples":[{"type":"basic","zh":"他敢跟老板叫板。","pinyin":"Tā gǎn gēn lǎobǎn jiàobǎn.","vi":"Anh ta dám thách thức sếp."},{"type":"simple","zh":"这家新公司公开向行业老大叫板。","pinyin":"Zhè jiā xīn gōngsī gōngkāi xiàng hángyè lǎodà jiàobǎn.","vi":"Công ty mới này công khai thách thức ông lớn trong ngành."},{"type":"compound","zh":"虽然对手实力很强，但是他还是敢于叫板。","pinyin":"Suīrán duìshǒu shílì hěn qiáng, dànshì tā háishi gǎnyú jiàobǎn.","vi":"Tuy đối thủ rất mạnh nhưng anh ấy vẫn dám thách đấu."}],"related":[{"hanzi":"挑战","pinyin":"tiǎozhàn","vi":"thách thức"},{"hanzi":"较劲","pinyin":"jiàojìn","vi":"đọ sức"},{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"挑衅","pinyin":"tiǎoxìn","vi":"khiêu khích"}]},{"id":"叫好","hanzi":"叫好","pinyin":"jiàohǎo","meaning_vi":"khen hay, reo hò cổ vũ","explanation":"叫 (khiếu – kêu lên) + 好 (hảo – hay) → hô lên \"hay!\", reo hò tán thưởng.","hsk_level":"7-9","tags":["dong-tu"],"image":"👏","examples":[{"type":"basic","zh":"观众纷纷叫好。","pinyin":"Guānzhòng fēnfēn jiàohǎo.","vi":"Khán giả nhao nhao khen hay."},{"type":"simple","zh":"他的精彩表演赢得了全场叫好。","pinyin":"Tā de jīngcǎi biǎoyǎn yíng déle quánchǎng jiàohǎo.","vi":"Màn biểu diễn tuyệt vời của anh ấy được cả khán phòng reo hò."},{"type":"compound","zh":"虽然影评人都为这部电影叫好，但是票房却不理想。","pinyin":"Suīrán yǐngpíngrén dōu wèi zhè bù diànyǐng jiàohǎo, dànshì piàofáng què bù lǐxiǎng.","vi":"Tuy giới phê bình đều khen hay bộ phim này nhưng doanh thu phòng vé lại không như mong đợi."}],"related":[{"hanzi":"喝彩","pinyin":"hècǎi","vi":"reo hò khen"},{"hanzi":"鼓掌","pinyin":"gǔzhǎng","vi":"vỗ tay"},{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"叫座","pinyin":"jiàozuò","vi":"hút khách"}]},{"id":"轿车","hanzi":"轿车","pinyin":"jiàochē","meaning_vi":"xe con, xe hơi","explanation":"轿 (kiệu – cái kiệu) + 车 (xa – xe) → vốn là xe có mui như kiệu; nay chỉ xe con chở người.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚘","examples":[{"type":"basic","zh":"他买了辆新轿车。","pinyin":"Tā mǎile liàng xīn jiàochē.","vi":"Anh ấy mua một chiếc xe con mới."},{"type":"simple","zh":"一辆黑色轿车停在了公司门口。","pinyin":"Yí liàng hēisè jiàochē tíng zài le gōngsī ménkǒu.","vi":"Một chiếc xe con màu đen dừng trước cửa công ty."},{"type":"compound","zh":"虽然这辆轿车不大，但是坐五个人也不挤。","pinyin":"Suīrán zhè liàng jiàochē búdà, dànshì zuò wǔ ge rén yě bù jǐ.","vi":"Tuy chiếc xe con này không lớn nhưng ngồi năm người cũng không chật."}],"related":[{"hanzi":"汽车","pinyin":"qìchē","vi":"ô tô"},{"hanzi":"小汽车","pinyin":"xiǎoqìchē","vi":"xe hơi nhỏ"},{"hanzi":"货车","pinyin":"huòchē","vi":"xe tải"},{"hanzi":"私家车","pinyin":"sījiāchē","vi":"xe riêng"}],"traditional":"轎車"},{"id":"较劲","hanzi":"较劲","pinyin":"jiàojìn","meaning_vi":"đọ sức, ganh đua, đối đầu","explanation":"较 (giảo – so sánh) + 劲 (kình – sức lực) → so sức với nhau, ganh đua; cũng chỉ cố tình đối nghịch với ai.","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"两队正在较劲。","pinyin":"Liǎng duì zhèngzài jiàojìn.","vi":"Hai đội đang đọ sức với nhau."},{"type":"simple","zh":"这两家超市一直在价格上较劲。","pinyin":"Zhè liǎng jiā chāoshì yìzhí zài jiàgé shang jiàojìn.","vi":"Hai siêu thị này luôn ganh đua nhau về giá."},{"type":"compound","zh":"如果你总跟自己较劲，就会活得很累。","pinyin":"Rúguǒ nǐ zǒng gēn zìjǐ jiàojìn, jiù huì huó de hěn lèi.","vi":"Nếu bạn cứ khắt khe với bản thân thì sẽ sống rất mệt mỏi."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"叫板","pinyin":"jiàobǎn","vi":"thách thức"},{"hanzi":"对着干","pinyin":"duìzhegàn","vi":"làm ngược lại"}],"traditional":"較勁"},{"id":"教条","hanzi":"教条","pinyin":"jiàotiáo","meaning_vi":"giáo điều","explanation":"教 (giáo – dạy) + 条 (điều – điều khoản) → những điều răn dạy cứng nhắc; chỉ cách nghĩ máy móc, giáo điều.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"📜","examples":[{"type":"basic","zh":"别太教条了。","pinyin":"Bié tài jiàotiáo le.","vi":"Đừng giáo điều quá."},{"type":"simple","zh":"他做事总是照搬书本上的教条。","pinyin":"Tā zuòshì zǒngshì zhàobān shūběn shang de jiàotiáo.","vi":"Anh ta làm việc luôn rập khuôn theo giáo điều trong sách."},{"type":"compound","zh":"如果把理论当成教条，就无法解决实际问题。","pinyin":"Rúguǒ bǎ lǐlùn dàngchéng jiàotiáo, jiù wúfǎ jiějué shíjì wèntí.","vi":"Nếu coi lý luận là giáo điều thì không thể giải quyết vấn đề thực tế."}],"related":[{"hanzi":"教条主义","pinyin":"jiàotiáozhǔyì","vi":"chủ nghĩa giáo điều"},{"hanzi":"死板","pinyin":"sǐbǎn","vi":"cứng nhắc"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"规条","pinyin":"guītiáo","vi":"quy định"}],"traditional":"教條"},{"id":"阶梯","hanzi":"阶梯","pinyin":"jiētī","meaning_vi":"bậc thang; nấc thang (bóng)","explanation":"阶 (giai – bậc) + 梯 (thê – thang) → bậc thang; nghĩa bóng là nấc thang, con đường đi lên.","hsk_level":"7-9","tags":["danh-tu"],"image":"🪜","examples":[{"type":"basic","zh":"请小心脚下的阶梯。","pinyin":"Qǐng xiǎoxīn jiǎoxià de jiētī.","vi":"Xin cẩn thận bậc thang dưới chân."},{"type":"simple","zh":"书籍是人类进步的阶梯。","pinyin":"Shūjí shì rénlèi jìnbù de jiētī.","vi":"Sách là nấc thang tiến bộ của nhân loại."},{"type":"compound","zh":"只要一步步踏上阶梯，你就能到达顶端。","pinyin":"Zhǐyào yí bùbù tàshàng jiētī, nǐ jiù néng dàodá dǐngduān.","vi":"Chỉ cần từng bước bước lên bậc thang, bạn sẽ đến được đỉnh."}],"related":[{"hanzi":"楼梯","pinyin":"lóutī","vi":"cầu thang"},{"hanzi":"台阶","pinyin":"táijiē","vi":"bậc thềm"},{"hanzi":"阶段","pinyin":"jiēduàn","vi":"giai đoạn"},{"hanzi":"阶梯教室","pinyin":"jiētījiàoshì","vi":"giảng đường bậc thang"}],"traditional":"階梯"},{"id":"接班","hanzi":"接班","pinyin":"jiēbān","meaning_vi":"nhận ca, tiếp quản, kế nhiệm","explanation":"接 (tiếp – nhận) + 班 (ban – ca làm việc) → nhận ca của người trước; nghĩa rộng là tiếp quản, kế nhiệm.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"晚上八点接班。","pinyin":"Wǎnshang bā diǎn jiēbān.","vi":"Tám giờ tối nhận ca."},{"type":"simple","zh":"老板希望儿子将来接班管理公司。","pinyin":"Lǎobǎn xīwàng érzi jiānglái jiēbān guǎnlǐ gōngsī.","vi":"Ông chủ mong con trai sau này tiếp quản công ty."},{"type":"compound","zh":"因为接班的护士还没到，所以她只好继续值班。","pinyin":"Yīnwèi jiēbān de hùshi hái méi dào, suǒyǐ tā zhǐhǎo jìxù zhíbān.","vi":"Vì y tá nhận ca chưa đến nên cô ấy đành tiếp tục trực."}],"related":[{"hanzi":"接班人","pinyin":"jiēbānrén","vi":"người kế nhiệm"},{"hanzi":"交班","pinyin":"jiāobān","vi":"giao ca"},{"hanzi":"值班","pinyin":"zhíbān","vi":"trực ca"},{"hanzi":"接替","pinyin":"jiētì","vi":"thay thế"}]},{"id":"接济","hanzi":"接济","pinyin":"jiējì","meaning_vi":"giúp đỡ, tiếp tế (vật chất)","explanation":"接 (tiếp – nối) + 济 (tế – cứu giúp) → giúp đỡ về tiền bạc, vật chất cho người khó khăn.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤲","examples":[{"type":"basic","zh":"他常接济穷人。","pinyin":"Tā cháng jiējì qióngrén.","vi":"Ông ấy thường giúp đỡ người nghèo."},{"type":"simple","zh":"大学期间，亲戚们经常接济他。","pinyin":"Dàxué qījiān, qīnqimen jīngcháng jiējì tā.","vi":"Trong thời gian đại học, họ hàng thường giúp đỡ anh ấy."},{"type":"compound","zh":"虽然自己也不富裕，但是她还是常常接济邻居。","pinyin":"Suīrán zìjǐ yě bú fùyù, dànshì tā háishi chángcháng jiējì línjū.","vi":"Tuy bản thân cũng không khá giả nhưng bà ấy vẫn thường giúp đỡ hàng xóm."}],"related":[{"hanzi":"救济","pinyin":"jiùjì","vi":"cứu tế"},{"hanzi":"资助","pinyin":"zīzhù","vi":"tài trợ"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"援助","pinyin":"yuánzhù","vi":"viện trợ"}],"traditional":"接濟"},{"id":"接见","hanzi":"接见","pinyin":"jiējiàn","meaning_vi":"tiếp kiến, tiếp đón","explanation":"接 (tiếp – đón) + 见 (kiến – gặp) → người có địa vị cao tiếp đón, gặp mặt người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤵","examples":[{"type":"basic","zh":"总统接见了代表。","pinyin":"Zǒngtǒng jiējiànle dàibiǎo.","vi":"Tổng thống đã tiếp kiến các đại biểu."},{"type":"simple","zh":"校长亲自接见了获奖的学生。","pinyin":"Xiàozhǎng qīnzì jiējiànle huòjiǎng de xuésheng.","vi":"Hiệu trưởng đích thân tiếp đón các học sinh đoạt giải."},{"type":"compound","zh":"因为部长临时有事，所以接见被推迟到明天。","pinyin":"Yīnwèi bùzhǎng línshí yǒushì, suǒyǐ jiējiàn bèi tuī chídào míngtiān.","vi":"Vì bộ trưởng bận việc đột xuất nên buổi tiếp kiến bị hoãn đến ngày mai."}],"related":[{"hanzi":"会见","pinyin":"huìjiàn","vi":"hội kiến"},{"hanzi":"接待","pinyin":"jiēdài","vi":"tiếp đãi"},{"hanzi":"召见","pinyin":"zhàojiàn","vi":"triệu kiến"},{"hanzi":"会面","pinyin":"huìmiàn","vi":"gặp mặt"}],"traditional":"接見"},{"id":"接力","hanzi":"接力","pinyin":"jiēlì","meaning_vi":"tiếp sức, chạy tiếp sức","explanation":"接 (tiếp – nối) + 力 (lực – sức) → nối tiếp sức nhau; chỉ môn chạy tiếp sức hoặc việc làm nối tiếp nhau.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"他参加了接力赛。","pinyin":"Tā cānjiāle jiēlìsài.","vi":"Anh ấy tham gia cuộc thi chạy tiếp sức."},{"type":"simple","zh":"我们班在四百米接力中得了第一。","pinyin":"Wǒmen bān zài sì bǎimǐ jiēlì zhōng déle dìyī.","vi":"Lớp chúng tôi đạt giải nhất nội dung tiếp sức bốn trăm mét."},{"type":"compound","zh":"虽然第一棒落后了，但是大家接力追上了对手。","pinyin":"Suīrán dìyī bàng luòhòu le, dànshì dàjiā jiēlì zhuīshàngle duìshǒu.","vi":"Tuy chặng đầu bị tụt lại nhưng mọi người tiếp sức nhau đuổi kịp đối thủ."}],"related":[{"hanzi":"接力棒","pinyin":"jiēlìbàng","vi":"gậy tiếp sức"},{"hanzi":"接力赛","pinyin":"jiēlìsài","vi":"cuộc thi tiếp sức"},{"hanzi":"传递","pinyin":"chuándì","vi":"chuyền"},{"hanzi":"赛跑","pinyin":"sàipǎo","vi":"chạy đua"}]},{"id":"接手","hanzi":"接手","pinyin":"jiēshǒu","meaning_vi":"tiếp nhận, tiếp quản (công việc)","explanation":"接 (tiếp – nhận) + 手 (thủ – tay) → nhận lấy từ tay người khác, tiếp quản công việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🫱","examples":[{"type":"basic","zh":"这个项目由我接手。","pinyin":"Zhè ge xiàngmù yóu wǒ jiēshǒu.","vi":"Dự án này do tôi tiếp quản."},{"type":"simple","zh":"他接手这家餐厅以后，生意好多了。","pinyin":"Tā jiēshǒu zhè jiā cāntīng yǐhòu, shēngyi hǎoduō le.","vi":"Từ khi anh ấy tiếp quản nhà hàng này, việc kinh doanh tốt hơn nhiều."},{"type":"compound","zh":"如果你不想干了，就找个人来接手吧。","pinyin":"Rúguǒ nǐ bù xiǎng gàn le, jiù zhǎo gerén lái jiēshǒu ba.","vi":"Nếu bạn không muốn làm nữa thì tìm người đến tiếp quản đi."}],"related":[{"hanzi":"接管","pinyin":"jiēguǎn","vi":"tiếp quản"},{"hanzi":"接替","pinyin":"jiētì","vi":"thay thế"},{"hanzi":"接班","pinyin":"jiēbān","vi":"nhận ca"},{"hanzi":"移交","pinyin":"yíjiāo","vi":"bàn giao"}]},{"id":"接送","hanzi":"接送","pinyin":"jiēsòng","meaning_vi":"đưa đón","explanation":"接 (tiếp – đón) + 送 (tống – đưa) → đón về và đưa đi.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🚸","examples":[{"type":"basic","zh":"我每天接送孩子。","pinyin":"Wǒ měitiān jiēsòng háizi.","vi":"Ngày nào tôi cũng đưa đón con."},{"type":"simple","zh":"酒店提供免费的机场接送服务。","pinyin":"Jiǔdiàn tígōng miǎnfèi de jīchǎng jiēsòng fúwù.","vi":"Khách sạn cung cấp dịch vụ đưa đón sân bay miễn phí."},{"type":"compound","zh":"因为父母工作太忙，所以爷爷负责接送孙子上学。","pinyin":"Yīnwèi fùmǔ gōngzuò tài máng, suǒyǐ yéye fùzé jiēsòng sūnzi shàngxué.","vi":"Vì bố mẹ quá bận nên ông nội phụ trách đưa đón cháu đi học."}],"related":[{"hanzi":"迎接","pinyin":"yíngjiē","vi":"đón tiếp"},{"hanzi":"送行","pinyin":"sòngxíng","vi":"tiễn đưa"},{"hanzi":"班车","pinyin":"bānchē","vi":"xe đưa đón"},{"hanzi":"接人","pinyin":"jiērén","vi":"đón người"}]},{"id":"接替","hanzi":"接替","pinyin":"jiētì","meaning_vi":"thay thế, tiếp nhận (chức vụ)","explanation":"接 (tiếp – nhận) + 替 (thế – thay) → nhận thay vị trí, công việc của người khác.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔁","examples":[{"type":"basic","zh":"谁来接替他？","pinyin":"Shéi lái jiētì tā?","vi":"Ai sẽ thay thế anh ấy?"},{"type":"simple","zh":"新经理下个月正式接替老张的职位。","pinyin":"Xīn jīnglǐ xiàgeyuè zhèngshì jiētì lǎo Zhāng de zhíwèi.","vi":"Giám đốc mới sẽ chính thức thay thế vị trí của ông Trương vào tháng sau."},{"type":"compound","zh":"虽然他刚刚接替这份工作，但是已经很熟练了。","pinyin":"Suīrán tā gānggāng jiētì zhè fèn gōngzuò, dànshì yǐjīng hěn shúliàn le.","vi":"Tuy anh ấy mới tiếp nhận công việc này nhưng đã rất thành thạo."}],"related":[{"hanzi":"代替","pinyin":"dàitì","vi":"thay thế"},{"hanzi":"接任","pinyin":"jiērèn","vi":"nhận chức"},{"hanzi":"接手","pinyin":"jiēshǒu","vi":"tiếp quản"},{"hanzi":"取代","pinyin":"qǔdài","vi":"thay thế hẳn"}]},{"id":"接听","hanzi":"接听","pinyin":"jiētīng","meaning_vi":"nghe máy, trả lời điện thoại","explanation":"接 (tiếp – nhận) + 听 (thính – nghe) → nhận cuộc gọi và nghe, tức nghe máy.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📞","examples":[{"type":"basic","zh":"他没接听电话。","pinyin":"Tā méi jiētīng diànhuà.","vi":"Anh ấy không nghe máy."},{"type":"simple","zh":"开会的时候请不要接听手机。","pinyin":"Kāihuì de shíhou qǐng bú yào jiētīng shǒujī.","vi":"Trong lúc họp vui lòng không nghe điện thoại."},{"type":"compound","zh":"如果对方无人接听，就请稍后再拨。","pinyin":"Rúguǒ duìfāng wúrén jiētīng, jiù qǐng shāohòu zài bō.","vi":"Nếu đầu bên kia không ai nghe máy, xin vui lòng gọi lại sau."}],"related":[{"hanzi":"接电话","pinyin":"jiēdiànhuà","vi":"nghe điện thoại"},{"hanzi":"挂断","pinyin":"guàduàn","vi":"cúp máy"},{"hanzi":"来电","pinyin":"láidiàn","vi":"cuộc gọi đến"},{"hanzi":"拨打","pinyin":"bōdǎ","vi":"gọi điện"}],"traditional":"接聽"},{"id":"接通","hanzi":"接通","pinyin":"jiētōng","meaning_vi":"nối thông, kết nối","explanation":"接 (tiếp – nối) + 通 (thông – thông suốt) → nối cho thông, kết nối (điện thoại, nguồn điện, mạng).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔌","examples":[{"type":"basic","zh":"电话终于接通了。","pinyin":"Diànhuà zhōngyú jiētōng le.","vi":"Cuối cùng điện thoại cũng kết nối được."},{"type":"simple","zh":"工人们正在为新楼接通电源。","pinyin":"Gōngrénmen zhèngzài wèi xīn lóu jiētōng diànyuán.","vi":"Công nhân đang nối nguồn điện cho tòa nhà mới."},{"type":"compound","zh":"因为山里信号太差，所以电话很久才接通。","pinyin":"Yīnwèi shān li xìnhào tài chà, suǒyǐ diànhuà hěn jiǔ cái jiētōng.","vi":"Vì sóng trong núi quá yếu nên mãi lâu điện thoại mới kết nối được."}],"related":[{"hanzi":"连接","pinyin":"liánjiē","vi":"kết nối"},{"hanzi":"打通","pinyin":"dǎtōng","vi":"gọi được"},{"hanzi":"断开","pinyin":"duànkāi","vi":"ngắt kết nối"},{"hanzi":"接线","pinyin":"jiēxiàn","vi":"nối dây"}]},{"id":"劫","hanzi":"劫","pinyin":"jié","meaning_vi":"cướp, cưỡng đoạt; kiếp nạn","explanation":"劫 (kiếp – cướp đoạt) → dùng vũ lực cướp đoạt; danh từ chỉ tai họa, kiếp nạn (gốc từ Phật giáo).","hsk_level":"7-9","tags":["dong-tu"],"image":"🦹","examples":[{"type":"basic","zh":"他被人劫了钱包。","pinyin":"Tā bèi rén jiéle qiánbāo.","vi":"Anh ấy bị cướp mất ví."},{"type":"simple","zh":"他在那次车祸中逃过了一劫。","pinyin":"Tā zài nà cì chēhuò zhōng táoguò le yì jié.","vi":"Anh ấy đã thoát được kiếp nạn trong vụ tai nạn xe đó."},{"type":"compound","zh":"虽然歹徒想劫车，但是司机机智地报了警。","pinyin":"Suīrán dǎitú xiǎng jiéchē, dànshì sījī jīzhì de bàole jǐng.","vi":"Tuy tên côn đồ định cướp xe nhưng tài xế đã nhanh trí báo cảnh sát."}],"related":[{"hanzi":"抢劫","pinyin":"qiǎngjié","vi":"cướp giật"},{"hanzi":"劫持","pinyin":"jiéchí","vi":"bắt cóc"},{"hanzi":"浩劫","pinyin":"hàojié","vi":"đại họa"},{"hanzi":"劫难","pinyin":"jiénàn","vi":"kiếp nạn"}]},{"id":"劫持","hanzi":"劫持","pinyin":"jiéchí","meaning_vi":"bắt cóc, cưỡng đoạt, không tặc","explanation":"劫 (kiếp – cướp) + 持 (trì – giữ) → cướp và khống chế (người, máy bay, xe...).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"✈️","examples":[{"type":"basic","zh":"飞机被劫持了。","pinyin":"Fēijī bèi jiéchí le.","vi":"Máy bay đã bị cướp."},{"type":"simple","zh":"歹徒劫持了一名人质逃进大楼。","pinyin":"Dǎitú jiéchíle yì míng rénzhì táo jìn dàlóu.","vi":"Tên côn đồ bắt một con tin rồi chạy vào tòa nhà."},{"type":"compound","zh":"一旦发现有人劫持车辆，就要立即报警。","pinyin":"Yídàn fāxiàn yǒurén jiéchí chēliàng, jiùyào lìjí bàojǐng.","vi":"Một khi phát hiện có người cướp xe thì phải báo cảnh sát ngay."}],"related":[{"hanzi":"绑架","pinyin":"bǎngjià","vi":"bắt cóc"},{"hanzi":"人质","pinyin":"rénzhì","vi":"con tin"},{"hanzi":"劫机","pinyin":"jiéjī","vi":"cướp máy bay"},{"hanzi":"挟持","pinyin":"xiéchí","vi":"khống chế"}]},{"id":"结识","hanzi":"结识","pinyin":"jiéshí","meaning_vi":"quen biết, làm quen","explanation":"结 (kết – kết giao) + 识 (thức – biết) → kết giao làm quen với ai.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙋","examples":[{"type":"basic","zh":"我在旅途中结识了她。","pinyin":"Wǒ zài lǚtú zhōng jiéshíle tā.","vi":"Tôi quen cô ấy trong chuyến đi."},{"type":"simple","zh":"他在大学里结识了很多好朋友。","pinyin":"Tā zài dàxué li jiéshíle hěn duō hǎopéngyou.","vi":"Anh ấy quen được nhiều bạn tốt ở đại học."},{"type":"compound","zh":"如果你多参加活动，就能结识更多同行。","pinyin":"Rúguǒ nǐ duō cānjiā huódòng, jiù néng jiéshí gèng duō tóngháng.","vi":"Nếu bạn tham gia nhiều hoạt động thì sẽ quen biết được nhiều người cùng nghề hơn."}],"related":[{"hanzi":"认识","pinyin":"rènshi","vi":"quen biết"},{"hanzi":"结交","pinyin":"jiéjiāo","vi":"kết giao"},{"hanzi":"相识","pinyin":"xiāngshí","vi":"quen nhau"},{"hanzi":"交往","pinyin":"jiāowǎng","vi":"qua lại"}],"traditional":"結識"},{"id":"结尾","hanzi":"结尾","pinyin":"jiéwěi","meaning_vi":"phần kết, đoạn cuối; kết thúc","explanation":"结 (kết – kết thúc) + 尾 (vĩ – đuôi) → phần đuôi, phần kết của bài viết, câu chuyện; cũng dùng làm động từ \"kết thúc\".","hsk_level":"7-9","tags":["danh-tu"],"image":"🔚","examples":[{"type":"basic","zh":"电影的结尾很感人。","pinyin":"Diànyǐng de jiéwěi hěn gǎnrén.","vi":"Đoạn kết của bộ phim rất cảm động."},{"type":"simple","zh":"这篇作文的结尾写得有点儿仓促。","pinyin":"Zhè piān zuòwén de jiéwěi xiě de yǒudiǎnr cāngcù.","vi":"Phần kết của bài văn này viết hơi vội vàng."},{"type":"compound","zh":"虽然开头很平淡，但是小说的结尾出人意料。","pinyin":"Suīrán kāitóu hěn píngdàn, dànshì xiǎoshuō de jiéwěi chūrényìliào.","vi":"Tuy mở đầu khá nhạt nhưng phần kết của cuốn tiểu thuyết lại bất ngờ."}],"related":[{"hanzi":"开头","pinyin":"kāitóu","vi":"mở đầu"},{"hanzi":"结局","pinyin":"jiéjú","vi":"kết cục"},{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"},{"hanzi":"收尾","pinyin":"shōuwěi","vi":"kết thúc, hoàn tất"}],"traditional":"結尾"},{"id":"截","hanzi":"截","pinyin":"jié","meaning_vi":"cắt, chặn; khúc, đoạn","explanation":"截 (tiệt – cắt đứt) → cắt ra một đoạn, chặn lại; làm lượng từ chỉ một khúc, một đoạn.","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"他截住了那个球。","pinyin":"Tā jié zhùle nà ge qiú.","vi":"Anh ấy chặn được quả bóng đó."},{"type":"simple","zh":"请把这根木头截成两段。","pinyin":"Qǐng bǎ zhè gēn mùtou jié chéng liǎng duàn.","vi":"Hãy cắt khúc gỗ này thành hai đoạn."},{"type":"compound","zh":"虽然只剩下半截铅笔，但是他舍不得扔掉。","pinyin":"Suīrán zhǐ shèngxià bànjié qiānbǐ, dànshì tā shěbude rēngdiào.","vi":"Tuy chỉ còn nửa mẩu bút chì nhưng cậu ấy vẫn không nỡ vứt."}],"related":[{"hanzi":"截止","pinyin":"jiézhǐ","vi":"hết hạn"},{"hanzi":"拦截","pinyin":"lánjié","vi":"chặn lại"},{"hanzi":"截图","pinyin":"jiétú","vi":"chụp màn hình"},{"hanzi":"一截","pinyin":"yìjié","vi":"một khúc"}]},{"id":"解救","hanzi":"解救","pinyin":"jiějiù","meaning_vi":"giải cứu, cứu thoát","explanation":"解 (giải – gỡ ra) + 救 (cứu – cứu) → gỡ khỏi nguy hiểm, giải cứu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🦸","examples":[{"type":"basic","zh":"人质被成功解救。","pinyin":"Rénzhì bèi chénggōng jiějiù.","vi":"Con tin đã được giải cứu thành công."},{"type":"simple","zh":"消防员从废墟中解救出三名工人。","pinyin":"Xiāofángyuán cóng fèixū zhōng jiějiù chū sān míng gōngrén.","vi":"Lính cứu hỏa đã cứu ba công nhân ra khỏi đống đổ nát."},{"type":"compound","zh":"如果不是警察及时赶到，他们就无法被解救。","pinyin":"Rúguǒ bú shì jǐngchá jíshí gǎndào, tāmen jiù wúfǎ bèi jiějiù.","vi":"Nếu cảnh sát không đến kịp thì họ đã không thể được giải cứu."}],"related":[{"hanzi":"营救","pinyin":"yíngjiù","vi":"cứu viện"},{"hanzi":"拯救","pinyin":"zhěngjiù","vi":"cứu vớt"},{"hanzi":"援救","pinyin":"yuánjiù","vi":"cứu giúp"},{"hanzi":"解围","pinyin":"jiěwéi","vi":"giải vây"}]},{"id":"解脱","hanzi":"解脱","pinyin":"jiětuō","meaning_vi":"giải thoát, thoát khỏi","explanation":"解 (giải – cởi) + 脱 (thoát – thoát ra) → cởi bỏ, thoát khỏi ràng buộc, khổ não; trong Phật giáo là giải thoát.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🕊️","examples":[{"type":"basic","zh":"他终于解脱了。","pinyin":"Tā zhōngyú jiětuō le.","vi":"Cuối cùng anh ấy cũng được giải thoát."},{"type":"simple","zh":"考完试后，我感到一种彻底的解脱。","pinyin":"Kǎowán shì hòu, wǒ gǎndào yì zhǒng chèdǐ de jiětuō.","vi":"Thi xong, tôi cảm thấy hoàn toàn được giải thoát."},{"type":"compound","zh":"如果你一直想着过去，就永远无法解脱。","pinyin":"Rúguǒ nǐ yìzhí xiǎngzhe guòqù, jiù yǒngyuǎn wúfǎ jiětuō.","vi":"Nếu bạn cứ mãi nghĩ về quá khứ thì sẽ không bao giờ thoát ra được."}],"related":[{"hanzi":"摆脱","pinyin":"bǎituō","vi":"thoát khỏi"},{"hanzi":"解放","pinyin":"jiěfàng","vi":"giải phóng"},{"hanzi":"释放","pinyin":"shìfàng","vi":"giải tỏa"},{"hanzi":"逃脱","pinyin":"táotuō","vi":"trốn thoát"}],"traditional":"解脫"},{"id":"解围","hanzi":"解围","pinyin":"jiěwéi","meaning_vi":"giải vây, gỡ thế bí","explanation":"解 (giải – gỡ) + 围 (vi – vòng vây) → phá vòng vây; nghĩa bóng là giúp ai thoát khỏi tình huống khó xử.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🛟","examples":[{"type":"basic","zh":"多亏你替我解围。","pinyin":"Duōkuī nǐ tì wǒ jiěwéi.","vi":"May mà có bạn gỡ rối giúp tôi."},{"type":"simple","zh":"他用一个笑话为尴尬的主持人解围。","pinyin":"Tāyòng yí gè xiàohua wèi gāngà de zhǔchírén jiěwéi.","vi":"Anh ấy dùng một câu chuyện cười để gỡ thế bí cho người dẫn chương trình đang lúng túng."},{"type":"compound","zh":"当时如果没有老师出来解围，我就不知道怎么办了。","pinyin":"Dāngshí rúguǒ méiyǒu lǎoshī chūlái jiěwéi, wǒ jiù bù zhīdào zěnmebàn le.","vi":"Lúc đó nếu không có thầy ra giải vây thì tôi chẳng biết làm sao."}],"related":[{"hanzi":"解救","pinyin":"jiějiù","vi":"giải cứu"},{"hanzi":"救场","pinyin":"jiùchǎng","vi":"cứu nguy"},{"hanzi":"突围","pinyin":"tūwéi","vi":"phá vây"},{"hanzi":"尴尬","pinyin":"gāngà","vi":"khó xử"}],"traditional":"解圍"},{"id":"解析","hanzi":"解析","pinyin":"jiěxī","meaning_vi":"phân tích, giải thích; giải tích","explanation":"解 (giải – tách ra) + 析 (tích – phân tích) → tách ra để phân tích, giải thích tường tận; trong toán là giải tích.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔬","examples":[{"type":"basic","zh":"老师解析了这道题。","pinyin":"Lǎoshī jiěxīle zhè dào tí.","vi":"Thầy giáo đã phân tích bài này."},{"type":"simple","zh":"这本书详细解析了历年考试真题。","pinyin":"Zhè běn shū xiángxì jiěxīle lìnián kǎoshì zhēn tí.","vi":"Cuốn sách này phân tích chi tiết đề thi các năm."},{"type":"compound","zh":"如果数据解析出错，结论就会完全不同。","pinyin":"Rúguǒ shùjù jiěxī chūcuò, jiélùn jiù huì wánquán bùtóng.","vi":"Nếu phân tích dữ liệu sai thì kết luận sẽ hoàn toàn khác."}],"related":[{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"解释","pinyin":"jiěshì","vi":"giải thích"},{"hanzi":"解读","pinyin":"jiědú","vi":"giải đọc"},{"hanzi":"解析几何","pinyin":"jiěxījǐhé","vi":"hình học giải tích"}]},{"id":"介入","hanzi":"介入","pinyin":"jièrù","meaning_vi":"can thiệp, nhúng tay vào","explanation":"介 (giới – ở giữa) + 入 (nhập – vào) → xen vào giữa, can thiệp vào sự việc.","hsk_level":"7-9","tags":["dong-tu"],"image":"✋","examples":[{"type":"basic","zh":"警方已经介入调查。","pinyin":"Jǐngfāng yǐjīng jièrù diàochá.","vi":"Cảnh sát đã vào cuộc điều tra."},{"type":"simple","zh":"他不想介入别人的家庭矛盾。","pinyin":"Tā bù xiǎng jièrù biérén de jiātíng máodùn.","vi":"Anh ấy không muốn can thiệp vào mâu thuẫn gia đình người khác."},{"type":"compound","zh":"如果政府不及时介入，房价就会继续上涨。","pinyin":"Rúguǒ zhèngfǔ bù jíshí jièrù, fángjià jiù huì jìxù shàngzhǎng.","vi":"Nếu chính phủ không kịp thời can thiệp thì giá nhà sẽ tiếp tục tăng."}],"related":[{"hanzi":"干预","pinyin":"gānyù","vi":"can thiệp"},{"hanzi":"插手","pinyin":"chāshǒu","vi":"nhúng tay"},{"hanzi":"参与","pinyin":"cānyù","vi":"tham gia"},{"hanzi":"干涉","pinyin":"gānshè","vi":"can thiệp"}]},{"id":"介意","hanzi":"介意","pinyin":"jièyì","meaning_vi":"để bụng, bận tâm, phiền lòng","explanation":"介 (giới – vướng mắc) + 意 (ý – lòng) → vướng bận trong lòng, để bụng; hay dùng trong câu hỏi lịch sự 你介意…吗.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙏","examples":[{"type":"basic","zh":"你介意我抽烟吗？","pinyin":"Nǐ jièyì wǒ chōuyān ma?","vi":"Bạn có phiền nếu tôi hút thuốc không?"},{"type":"simple","zh":"他说话直，你别太介意。","pinyin":"Tā shuōhuà zhí, nǐ bié tài jièyì.","vi":"Anh ấy nói thẳng, bạn đừng để bụng quá."},{"type":"compound","zh":"虽然他嘴上说不介意，但是心里还是有点难过。","pinyin":"Suīrán tā zuǐ shang shuō bú jièyì, dànshì xīnli háishi yǒudiǎn nánguò.","vi":"Tuy ngoài miệng nói không bận tâm nhưng trong lòng anh ấy vẫn hơi buồn."}],"related":[{"hanzi":"在意","pinyin":"zàiyì","vi":"để ý"},{"hanzi":"在乎","pinyin":"zàihu","vi":"quan tâm"},{"hanzi":"计较","pinyin":"jìjiào","vi":"so đo"},{"hanzi":"不介意","pinyin":"bújièyì","vi":"không phiền"}]},{"id":"介于","hanzi":"介于","pinyin":"jièyú","meaning_vi":"nằm giữa, ở giữa (hai thứ)","explanation":"介 (giới – ở giữa) + 于 (vu – ở) → nằm ở khoảng giữa hai thứ; thường dùng trong khung 介于…之间.","hsk_level":"7-9","tags":["dong-tu"],"image":"↔️","examples":[{"type":"basic","zh":"温度介于两者之间。","pinyin":"Wēndù jièyú liǎngzhě zhījiān.","vi":"Nhiệt độ nằm giữa hai mức đó."},{"type":"simple","zh":"这种颜色介于红色和橙色之间。","pinyin":"Zhè zhǒng yánsè jièyú hóngsè hé chéngsè zhījiān.","vi":"Màu này nằm giữa màu đỏ và màu cam."},{"type":"compound","zh":"虽然他的成绩介于及格和优秀之间，但是进步很快。","pinyin":"Suīrán tā de chéngjì jièyú jígé hé yōuxiù zhījiān, dànshì jìnbù hěn kuài.","vi":"Tuy điểm của cậu ấy chỉ ở giữa mức đạt và giỏi, nhưng tiến bộ rất nhanh."}],"related":[{"hanzi":"处于","pinyin":"chǔyú","vi":"ở vào"},{"hanzi":"位于","pinyin":"wèiyú","vi":"nằm ở"},{"hanzi":"之间","pinyin":"zhījiān","vi":"ở giữa"},{"hanzi":"介入","pinyin":"jièrù","vi":"can thiệp"}],"traditional":"介於"},{"id":"戒烟","hanzi":"戒烟","pinyin":"jièyān","meaning_vi":"cai thuốc lá","explanation":"戒 (giới – kiêng, bỏ) + 烟 (yên – thuốc lá) → bỏ hút thuốc lá.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🚭","examples":[{"type":"basic","zh":"爸爸终于戒烟了。","pinyin":"Bàba zhōngyú jièyān le.","vi":"Bố cuối cùng cũng cai thuốc rồi."},{"type":"simple","zh":"医生建议他马上戒烟。","pinyin":"Yīshēng jiànyì tā mǎshàng jièyān.","vi":"Bác sĩ khuyên anh ấy cai thuốc ngay."},{"type":"compound","zh":"如果你真的想戒烟，就先把家里的烟都扔掉。","pinyin":"Rúguǒ nǐ zhēn de xiǎng jièyān, jiù xiān bǎ jiālǐ de yān dōu rēngdiào.","vi":"Nếu bạn thật sự muốn cai thuốc thì hãy vứt hết thuốc lá trong nhà trước đã."}],"related":[{"hanzi":"戒酒","pinyin":"jièjiǔ","vi":"cai rượu"},{"hanzi":"抽烟","pinyin":"chōuyān","vi":"hút thuốc"},{"hanzi":"吸烟","pinyin":"xīyān","vi":"hút thuốc"},{"hanzi":"香烟","pinyin":"xiāngyān","vi":"thuốc lá điếu"}],"traditional":"戒菸"},{"id":"届时","hanzi":"届时","pinyin":"jièshí","meaning_vi":"đến lúc đó, khi ấy","explanation":"届 (giới – đến kỳ) + 时 (thời – lúc) → khi đến thời điểm đã định; dùng trong văn viết, thông báo trang trọng.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"届时请准时到场。","pinyin":"Jièshí qǐng zhǔnshí dàochǎng.","vi":"Đến lúc đó xin mời có mặt đúng giờ."},{"type":"simple","zh":"届时我们会通知大家具体地点。","pinyin":"Jièshí wǒmen huì tōngzhī dàjiā jùtǐ dìdiǎn.","vi":"Đến lúc đó chúng tôi sẽ thông báo địa điểm cụ thể cho mọi người."},{"type":"compound","zh":"如果明天下雨，届时比赛就改到室内进行。","pinyin":"Rúguǒ míngtiān xiàyǔ, jièshí bǐsài jiù gǎi dào shìnèi jìnxíng.","vi":"Nếu mai trời mưa thì đến lúc đó trận đấu sẽ chuyển vào trong nhà."}],"related":[{"hanzi":"到时候","pinyin":"dàoshíhou","vi":"đến lúc đó"},{"hanzi":"届满","pinyin":"jièmǎn","vi":"mãn nhiệm kỳ"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"đúng giờ"},{"hanzi":"按时","pinyin":"ànshí","vi":"đúng hạn"}],"traditional":"屆時"},{"id":"界线","hanzi":"界线","pinyin":"jièxiàn","meaning_vi":"đường ranh giới, giới hạn","explanation":"界 (giới – ranh giới) + 线 (tuyến – đường) → đường phân chia ranh giới; nghĩa bóng là giới hạn phân biệt hai điều.","hsk_level":"7-9","tags":["danh-tu"],"image":"🚧","examples":[{"type":"basic","zh":"两国的界线很清楚。","pinyin":"Liǎngguó de jièxiàn hěn qīngchu.","vi":"Đường biên giới giữa hai nước rất rõ ràng."},{"type":"simple","zh":"我们要分清工作和生活的界线。","pinyin":"Wǒmen yào fēnqīng gōngzuò hé shēnghuó de jièxiàn.","vi":"Chúng ta cần phân rõ ranh giới giữa công việc và cuộc sống."},{"type":"compound","zh":"虽然他们是好朋友，但是公私的界线一直分得很清。","pinyin":"Suīrán tāmen shì hǎopéngyou, dànshì gōngsī de jièxiàn yìzhí fēn de hěn qīng.","vi":"Tuy họ là bạn thân nhưng ranh giới giữa việc công và việc tư luôn được tách bạch."}],"related":[{"hanzi":"边界","pinyin":"biānjiè","vi":"biên giới"},{"hanzi":"界限","pinyin":"jièxiàn","vi":"giới hạn"},{"hanzi":"分界","pinyin":"fēnjiè","vi":"phân giới"},{"hanzi":"划清","pinyin":"huàqīng","vi":"vạch rõ"}],"traditional":"界線"},{"id":"借条","hanzi":"借条","pinyin":"jiètiáo","meaning_vi":"giấy vay nợ, giấy nhận nợ","explanation":"借 (tá – vay) + 条 (điều – mảnh giấy) → mảnh giấy ghi khoản vay để làm bằng chứng.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📝","examples":[{"type":"basic","zh":"他写了一张借条。","pinyin":"Tā xiěle yì zhāng jiètiáo.","vi":"Anh ấy đã viết một tờ giấy vay nợ."},{"type":"simple","zh":"借钱给别人时最好让对方打个借条。","pinyin":"Jièqián gěi biérén shí zuìhǎo ràng duìfāng dǎ gè jiètiáo.","vi":"Khi cho người khác vay tiền tốt nhất nên bảo họ viết giấy nhận nợ."},{"type":"compound","zh":"因为当时没有写借条，所以他现在很难要回那笔钱。","pinyin":"Yīnwèi dāngshí méiyǒu xiě jiètiáo, suǒyǐ tā xiànzài hěn nán yào huí nà bǐ qián.","vi":"Vì lúc đó không viết giấy vay nợ nên bây giờ anh ấy rất khó đòi lại khoản tiền ấy."}],"related":[{"hanzi":"欠条","pinyin":"qiàntiáo","vi":"giấy nợ"},{"hanzi":"收条","pinyin":"shōutiáo","vi":"giấy biên nhận"},{"hanzi":"借款","pinyin":"jièkuǎn","vi":"khoản vay"},{"hanzi":"借钱","pinyin":"jièqián","vi":"vay tiền"}],"traditional":"借條"},{"id":"借用","hanzi":"借用","pinyin":"jièyòng","meaning_vi":"mượn dùng, vay mượn","explanation":"借 (tá – mượn) + 用 (dụng – dùng) → mượn để dùng; cũng chỉ mượn ý tưởng, câu chữ cho mục đích khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"能借用一下你的笔吗？","pinyin":"Néng jièyòng yíxià nǐ de bǐ ma?","vi":"Cho mình mượn cây bút của bạn một chút được không?"},{"type":"simple","zh":"这篇文章借用了一句古诗。","pinyin":"Zhè piān wénzhāng jièyòngle yíjù gǔshī.","vi":"Bài văn này mượn một câu thơ cổ."},{"type":"compound","zh":"如果你要借用会议室，就得提前一天申请。","pinyin":"Rúguǒ nǐ yào jièyòng huìyìshì, jiù děi tí qiányìtiān shēnqǐng.","vi":"Nếu bạn muốn mượn phòng họp thì phải đăng ký trước một ngày."}],"related":[{"hanzi":"借","pinyin":"jiè","vi":"mượn"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"},{"hanzi":"挪用","pinyin":"nuóyòng","vi":"dùng sai mục đích"},{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"}]},{"id":"金子","hanzi":"金子","pinyin":"jīnzi","meaning_vi":"vàng","explanation":"金 (kim – vàng) + 子 (tử – hậu tố) → vàng, kim loại quý; cách nói khẩu ngữ của 黄金.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🪙","examples":[{"type":"basic","zh":"这块金子很重。","pinyin":"Zhè kuài jīnzi hěn zhòng.","vi":"Thỏi vàng này rất nặng."},{"type":"simple","zh":"古时候人们用金子来交换东西。","pinyin":"Gǔshíhou rénmen yòng jīnzi lái jiāohuàn dōngxi.","vi":"Thời xưa người ta dùng vàng để trao đổi đồ vật."},{"type":"compound","zh":"是金子总会发光的，只要你坚持努力，就一定会成功。","pinyin":"Shì jīnzi zǒng huì fāguāng de, zhǐyào nǐ jiānchí nǔlì, jiù yídìng huì chénggōng.","vi":"Vàng thì sớm muộn cũng tỏa sáng, chỉ cần bạn kiên trì cố gắng thì nhất định sẽ thành công."}],"related":[{"hanzi":"黄金","pinyin":"huángjīn","vi":"vàng"},{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"},{"hanzi":"银子","pinyin":"yínzi","vi":"bạc"},{"hanzi":"金色","pinyin":"jīnsè","vi":"màu vàng kim"}]},{"id":"津贴","hanzi":"津贴","pinyin":"jīntiē","meaning_vi":"phụ cấp, trợ cấp","explanation":"津 (tân – thấm, giúp đỡ) + 贴 (thiếp – bù thêm) → khoản tiền bù thêm ngoài lương.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"公司发了交通津贴。","pinyin":"Gōngsī fāle jiāotōng jīntiē.","vi":"Công ty đã phát phụ cấp đi lại."},{"type":"simple","zh":"在高温天气下工作的人能拿到额外津贴。","pinyin":"Zài gāowēn tiānqì xià gōngzuò de rén néng nádào éwài jīntiē.","vi":"Người làm việc trong thời tiết nắng nóng được nhận thêm phụ cấp."},{"type":"compound","zh":"虽然这份工作工资不高，但是津贴很多。","pinyin":"Suīrán zhè fèn gōngzuò gōngzī bù gāo, dànshì jīntiē hěn duō.","vi":"Tuy công việc này lương không cao nhưng phụ cấp rất nhiều."}],"related":[{"hanzi":"补贴","pinyin":"bǔtiē","vi":"trợ cấp"},{"hanzi":"补助","pinyin":"bǔzhù","vi":"tiền hỗ trợ"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"},{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"}],"traditional":"津貼"},{"id":"筋","hanzi":"筋","pinyin":"jīn","meaning_vi":"gân, gân xanh, thớ dai","explanation":"筋 (cân – gân) → gân cơ, mạch máu nổi dưới da, hoặc vật có thớ dai giống gân.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"他的脚抽筋了。","pinyin":"Tā de jiǎo chōujīn le.","vi":"Chân anh ấy bị chuột rút rồi."},{"type":"simple","zh":"他气得脖子上的青筋都露出来了。","pinyin":"Tā qì de bózi shang de qīngjīn dōu lù chūlái le.","vi":"Anh ta tức đến nỗi gân xanh trên cổ nổi cả lên."},{"type":"compound","zh":"因为游泳前没做热身，所以他的腿突然抽筋了。","pinyin":"Yīnwèi yóuyǒng qián méi zuò rèshēn, suǒyǐ tā de tuǐ tūrán chōujīn le.","vi":"Vì không khởi động trước khi bơi nên chân anh ấy đột nhiên bị chuột rút."}],"related":[{"hanzi":"抽筋","pinyin":"chōujīn","vi":"chuột rút"},{"hanzi":"青筋","pinyin":"qīngjīn","vi":"gân xanh"},{"hanzi":"筋骨","pinyin":"jīngǔ","vi":"gân cốt"},{"hanzi":"肌肉","pinyin":"jīròu","vi":"cơ bắp"}]},{"id":"仅次于","hanzi":"仅次于","pinyin":"jǐncìyú","meaning_vi":"chỉ đứng sau, chỉ kém","explanation":"仅 (cận – chỉ) + 次 (thứ – xếp sau) + 于 (vu – so với) → chỉ xếp sau một đối tượng, tức đứng thứ hai.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥈","examples":[{"type":"basic","zh":"他的成绩仅次于我。","pinyin":"Tā de chéngjì jǐncìyú wǒ.","vi":"Thành tích của cậu ấy chỉ sau tôi."},{"type":"simple","zh":"这座山的高度仅次于珠穆朗玛峰。","pinyin":"Zhè zuò shān de gāodù jǐncìyú Zhūmùlǎngmǎfēng.","vi":"Độ cao của ngọn núi này chỉ đứng sau đỉnh Everest."},{"type":"compound","zh":"虽然这家公司的销量仅次于对手，但是利润却最高。","pinyin":"Suīrán zhè jiā gōngsī de xiāoliàng jǐncìyú duìshǒu, dànshì lìrùn què zuì gāo.","vi":"Tuy doanh số của công ty này chỉ đứng sau đối thủ nhưng lợi nhuận lại cao nhất."}],"related":[{"hanzi":"第二","pinyin":"dì'èr","vi":"thứ hai"},{"hanzi":"亚军","pinyin":"yàjūn","vi":"á quân"},{"hanzi":"名列","pinyin":"míngliè","vi":"xếp hạng"},{"hanzi":"首屈一指","pinyin":"shǒuqūyìzhǐ","vi":"đứng đầu"}],"traditional":"僅次於"},{"id":"尽头","hanzi":"尽头","pinyin":"jìntóu","meaning_vi":"chỗ tận cùng, điểm cuối","explanation":"尽 (tận – hết) + 头 (đầu – đầu mút) → chỗ hết, đầu mút cuối cùng của con đường hay sự việc.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🔚","examples":[{"type":"basic","zh":"走廊尽头是厕所。","pinyin":"Zǒuláng jìntóu shì cèsuǒ.","vi":"Cuối hành lang là nhà vệ sinh."},{"type":"simple","zh":"我们沿着小路一直走到了尽头。","pinyin":"Wǒmen yánzhe xiǎolù yì zhízǒu dàole jìntóu.","vi":"Chúng tôi men theo con đường nhỏ đi đến tận cùng."},{"type":"compound","zh":"即使看不到路的尽头，我们也要继续往前走。","pinyin":"Jíshǐ kàn búdào lù de jìntóu, wǒmen yě yào jìxù wǎng qián zǒu.","vi":"Dù không nhìn thấy cuối con đường, chúng ta vẫn phải tiếp tục đi về phía trước."}],"related":[{"hanzi":"终点","pinyin":"zhōngdiǎn","vi":"điểm cuối"},{"hanzi":"末端","pinyin":"mòduān","vi":"đầu mút"},{"hanzi":"无尽","pinyin":"wújìn","vi":"vô tận"},{"hanzi":"开头","pinyin":"kāitóu","vi":"khởi đầu"}],"traditional":"盡頭"},{"id":"尽早","hanzi":"尽早","pinyin":"jǐnzǎo","meaning_vi":"càng sớm càng tốt, sớm nhất có thể","explanation":"尽 (tận – hết mức) + 早 (tảo – sớm) → sớm hết mức có thể.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏩","examples":[{"type":"basic","zh":"请尽早回复我。","pinyin":"Qǐng jǐnzǎo huífù wǒ.","vi":"Xin hãy trả lời tôi càng sớm càng tốt."},{"type":"simple","zh":"你最好尽早去医院做个检查。","pinyin":"Nǐ zuìhǎo jǐnzǎo qù yīyuàn zuò gè jiǎnchá.","vi":"Tốt nhất bạn nên sớm đến bệnh viện kiểm tra."},{"type":"compound","zh":"如果想买到便宜的机票，就要尽早预订。","pinyin":"Rúguǒ xiǎng mǎi dào piányi de jīpiào, jiùyào jǐnzǎo yùdìng.","vi":"Nếu muốn mua được vé máy bay rẻ thì phải đặt càng sớm càng tốt."}],"related":[{"hanzi":"尽快","pinyin":"jǐnkuài","vi":"càng nhanh càng tốt"},{"hanzi":"及早","pinyin":"jízǎo","vi":"sớm, kịp thời"},{"hanzi":"早日","pinyin":"zǎorì","vi":"sớm ngày"},{"hanzi":"尽量","pinyin":"jǐnliàng","vi":"cố hết sức"}],"traditional":"儘早"},{"id":"紧凑","hanzi":"紧凑","pinyin":"jǐncòu","meaning_vi":"gọn, chặt chẽ, sít sao","explanation":"紧 (khẩn – chặt) + 凑 (thấu – gom lại) → gom sát nhau, không có chỗ thừa; dùng cho lịch trình, bố cục, cốt truyện.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🗓️","examples":[{"type":"basic","zh":"今天的日程很紧凑。","pinyin":"Jīntiān de rìchéng hěn jǐncòu.","vi":"Lịch trình hôm nay rất sít sao."},{"type":"simple","zh":"这辆车的设计非常紧凑。","pinyin":"Zhè liàng chē de shèjì fēicháng jǐncòu.","vi":"Thiết kế của chiếc xe này rất gọn."},{"type":"compound","zh":"虽然房间不大，但是布置得很紧凑，住着很舒服。","pinyin":"Suīrán fángjiān búdà, dànshì bùzhì de hěn jǐncòu, zhùzhe hěn shūfu.","vi":"Tuy phòng không rộng nhưng được bố trí rất gọn gàng, ở rất thoải mái."}],"related":[{"hanzi":"紧密","pinyin":"jǐnmì","vi":"chặt chẽ"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"},{"hanzi":"松散","pinyin":"sōngsǎn","vi":"lỏng lẻo"},{"hanzi":"凑","pinyin":"còu","vi":"gom góp"}],"traditional":"緊湊"},{"id":"紧接着","hanzi":"紧接着","pinyin":"jǐnjiēzhe","meaning_vi":"ngay sau đó, liền theo","explanation":"紧 (khẩn – sát) + 接着 (tiếp – nối theo) → nối sát ngay sau, không có khoảng cách.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏭️","examples":[{"type":"basic","zh":"紧接着下起了大雨。","pinyin":"Jǐnjiēzhe xià qǐle dàyǔ.","vi":"Ngay sau đó trời đổ mưa to."},{"type":"simple","zh":"第一节课结束后紧接着是数学考试。","pinyin":"Dìyī jié kè jiéshù hòu jǐnjiēzhe shì shùxué kǎoshì.","vi":"Tiết đầu tiên kết thúc là liền ngay bài thi toán."},{"type":"compound","zh":"因为刚开完会，紧接着又要出差，所以他累坏了。","pinyin":"Yīnwèi gāng kāi wán huì, jǐnjiēzhe yòu yào chūchāi, suǒyǐ tā lèi huàile.","vi":"Vì vừa họp xong, ngay sau đó lại phải đi công tác nên anh ấy mệt rã rời."}],"related":[{"hanzi":"接着","pinyin":"jiēzhe","vi":"tiếp theo"},{"hanzi":"随后","pinyin":"suíhòu","vi":"sau đó"},{"hanzi":"然后","pinyin":"ránhòu","vi":"rồi thì"},{"hanzi":"立刻","pinyin":"lìkè","vi":"lập tức"}],"traditional":"緊接著"},{"id":"紧缩","hanzi":"紧缩","pinyin":"jǐnsuō","meaning_vi":"thắt chặt, cắt giảm","explanation":"紧 (khẩn – siết) + 缩 (súc – co lại) → siết cho nhỏ lại; dùng cho chi tiêu, ngân sách, chính sách kinh tế.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"公司正在紧缩开支。","pinyin":"Gōngsī zhèngzài jǐnsuō kāizhī.","vi":"Công ty đang thắt chặt chi tiêu."},{"type":"simple","zh":"政府决定紧缩货币政策。","pinyin":"Zhèngfǔ juédìng jǐnsuō huòbìzhèngcè.","vi":"Chính phủ quyết định thắt chặt chính sách tiền tệ."},{"type":"compound","zh":"由于经济不景气，很多企业不得不紧缩预算。","pinyin":"Yóuyú jīngjì bùjǐngqì, hěn duō qǐyè bùdébù jǐnsuō yùsuàn.","vi":"Do kinh tế suy thoái, nhiều doanh nghiệp buộc phải cắt giảm ngân sách."}],"related":[{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"缩减","pinyin":"suōjiǎn","vi":"cắt giảm"},{"hanzi":"扩张","pinyin":"kuòzhāng","vi":"mở rộng"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"tiết kiệm"}],"traditional":"緊縮"},{"id":"锦旗","hanzi":"锦旗","pinyin":"jǐnqí","meaning_vi":"cờ thêu khen tặng, cờ lụa","explanation":"锦 (cẩm – gấm) + 旗 (kỳ – cờ) → lá cờ bằng gấm lụa, tặng để cảm ơn hoặc khen thưởng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎌","examples":[{"type":"basic","zh":"病人送来一面锦旗。","pinyin":"Bìngrén sòng lái yímiàn jǐnqí.","vi":"Bệnh nhân mang đến tặng một lá cờ thêu."},{"type":"simple","zh":"墙上挂满了各单位送的锦旗。","pinyin":"Qiáng shang guà mǎnle gè dānwèi sòng de jǐnqí.","vi":"Trên tường treo đầy cờ thêu do các đơn vị tặng."},{"type":"compound","zh":"因为警察帮她找回了钱包，所以她特地送去一面锦旗。","pinyin":"Yīnwèi jǐngchá bāng tā zhǎohuíle qiánbāo, suǒyǐ tā tèdì sòngqù yímiàn jǐnqí.","vi":"Vì cảnh sát giúp cô tìm lại ví nên cô đặc biệt mang tặng một lá cờ thêu."}],"related":[{"hanzi":"旗子","pinyin":"qízi","vi":"lá cờ"},{"hanzi":"奖状","pinyin":"jiǎngzhuàng","vi":"bằng khen"},{"hanzi":"锦绣","pinyin":"jǐnxiù","vi":"gấm vóc"},{"hanzi":"表彰","pinyin":"biǎozhāng","vi":"tuyên dương"}],"traditional":"錦旗"},{"id":"劲头","hanzi":"劲头","pinyin":"jìntóu","meaning_vi":"sự hăng hái, nhiệt huyết, sức lực","explanation":"劲 (kình – sức) + 头 (đầu – hậu tố) → sức lực và sự hăng hái khi làm việc gì.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他干活很有劲头。","pinyin":"Tā gànhuó hěn yǒu jìntóu.","vi":"Anh ấy làm việc rất hăng hái."},{"type":"simple","zh":"年轻人学习的劲头真让人佩服。","pinyin":"Niánqīngrén xuéxí de jìntóu zhēn ràng rén pèifú.","vi":"Sự hăng say học tập của người trẻ thật khiến người ta khâm phục."},{"type":"compound","zh":"虽然已经六十岁了，但是他工作的劲头一点儿也不比年轻人差。","pinyin":"Suīrán yǐjīng liùshí suì le, dànshì tā gōngzuò de jìntóu yìdiǎnr yě bùbǐ niánqīngrén chà.","vi":"Tuy đã sáu mươi tuổi nhưng nhiệt huyết làm việc của ông không hề thua người trẻ."}],"related":[{"hanzi":"干劲","pinyin":"gànjìn","vi":"nhiệt huyết làm việc"},{"hanzi":"劲儿","pinyin":"jìnr","vi":"sức"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"积极","pinyin":"jījí","vi":"tích cực"}],"traditional":"勁頭"},{"id":"近年来","hanzi":"近年来","pinyin":"jìnniánlái","meaning_vi":"những năm gần đây","explanation":"近年 (cận niên – những năm gần) + 来 (lai – trở lại đây) → từ mấy năm gần đây cho đến nay.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"近年来物价上涨了。","pinyin":"Jìnniánlái wùjià shàngzhǎng le.","vi":"Những năm gần đây giá cả đã tăng."},{"type":"simple","zh":"近年来越来越多的人选择网上购物。","pinyin":"Jìnniánlái yuèláiyuè duō de rén xuǎnzé wǎngshàng gòuwù.","vi":"Những năm gần đây ngày càng nhiều người chọn mua sắm trực tuyến."},{"type":"compound","zh":"虽然近年来这座城市发展很快，但是交通问题也越来越严重。","pinyin":"Suīrán jìnniánlái zhè zuò chéngshì fāzhǎn hěn kuài, dànshì jiāotōng wèntí yě yuèláiyuè yánzhòng.","vi":"Tuy mấy năm gần đây thành phố này phát triển rất nhanh nhưng vấn đề giao thông cũng ngày càng nghiêm trọng."}],"related":[{"hanzi":"近年","pinyin":"jìnnián","vi":"những năm gần đây"},{"hanzi":"近来","pinyin":"jìnlái","vi":"gần đây"},{"hanzi":"最近","pinyin":"zuìjìn","vi":"dạo này"},{"hanzi":"多年来","pinyin":"duōniánlái","vi":"nhiều năm nay"}],"traditional":"近年來"},{"id":"进场","hanzi":"进场","pinyin":"jìnchǎng","meaning_vi":"vào sân, vào hội trường","explanation":"进 (tiến – vào) + 场 (trường – sân, nơi tổ chức) → đi vào nơi thi đấu, biểu diễn; còn chỉ máy bay tiếp cận đường băng.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏟️","examples":[{"type":"basic","zh":"观众开始进场了。","pinyin":"Guānzhòng kāishǐ jìnchǎng le.","vi":"Khán giả bắt đầu vào sân rồi."},{"type":"simple","zh":"球员们在掌声中依次进场。","pinyin":"Qiúyuánmen zài zhǎngshēng zhōng yīcì jìnchǎng.","vi":"Các cầu thủ lần lượt vào sân trong tiếng vỗ tay."},{"type":"compound","zh":"如果没有门票，就不能进场看演唱会。","pinyin":"Rúguǒ méiyǒu ménpiào, jiù bù néng jìnchǎng kàn yǎnchànghuì.","vi":"Nếu không có vé thì không thể vào xem buổi hòa nhạc."}],"related":[{"hanzi":"入场","pinyin":"rùchǎng","vi":"vào cửa"},{"hanzi":"退场","pinyin":"tuìchǎng","vi":"rời sân"},{"hanzi":"出场","pinyin":"chūchǎng","vi":"ra sân"},{"hanzi":"场地","pinyin":"chǎngdì","vi":"sân bãi"}],"traditional":"進場"},{"id":"进出","hanzi":"进出","pinyin":"jìnchū","meaning_vi":"ra vào, xuất nhập","explanation":"进 (tiến – vào) + 出 (xuất – ra) → đi vào và đi ra; cũng chỉ thu chi, xuất nhập hàng hóa.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚪","examples":[{"type":"basic","zh":"这里禁止车辆进出。","pinyin":"Zhèlǐ jìnzhǐ chēliàng jìnchū.","vi":"Ở đây cấm xe cộ ra vào."},{"type":"simple","zh":"每天进出这栋大楼的人有好几千。","pinyin":"Měitiān jìnchū zhè dòng dàlóu de rén yǒu hǎo jǐqiān.","vi":"Mỗi ngày có đến mấy nghìn người ra vào tòa nhà này."},{"type":"compound","zh":"自从小区装了门禁，外人就不能随便进出了。","pinyin":"Zìcóng xiǎoqū zhuāngle ménjìn, wàirén jiù bù néng suíbiàn jìnchū le.","vi":"Từ khi khu dân cư lắp hệ thống kiểm soát cửa, người ngoài không thể tùy tiện ra vào nữa."}],"related":[{"hanzi":"出入","pinyin":"chūrù","vi":"ra vào"},{"hanzi":"进口","pinyin":"jìnkǒu","vi":"nhập khẩu"},{"hanzi":"出口","pinyin":"chūkǒu","vi":"xuất khẩu"},{"hanzi":"进进出出","pinyin":"jìnjìnchūchū","vi":"ra ra vào vào"}],"traditional":"進出"},{"id":"进度","hanzi":"进度","pinyin":"jìndù","meaning_vi":"tiến độ","explanation":"进 (tiến – tiến lên) + 度 (độ – mức) → mức độ tiến triển của công việc.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"工程进度很慢。","pinyin":"Gōngchéng jìndù hěn màn.","vi":"Tiến độ công trình rất chậm."},{"type":"simple","zh":"老板每天都要检查项目的进度。","pinyin":"Lǎobǎn měitiān dōu yào jiǎnchá xiàng mùde jìndù.","vi":"Ngày nào sếp cũng kiểm tra tiến độ dự án."},{"type":"compound","zh":"因为连续下了一周大雨，所以施工进度推迟了。","pinyin":"Yīnwèi liánxù xiàle yìzhōu dàyǔ, suǒyǐ shīgōng jìndù tuīchí le.","vi":"Vì mưa to liên tục suốt một tuần nên tiến độ thi công bị chậm lại."}],"related":[{"hanzi":"进展","pinyin":"jìnzhǎn","vi":"tiến triển"},{"hanzi":"进程","pinyin":"jìnchéng","vi":"tiến trình"},{"hanzi":"速度","pinyin":"sùdù","vi":"tốc độ"},{"hanzi":"计划","pinyin":"jìhuà","vi":"kế hoạch"}],"traditional":"進度"},{"id":"禁不住","hanzi":"禁不住","pinyin":"jīnbuzhù","meaning_vi":"không nhịn được, không chịu nổi","explanation":"禁 (câm – chịu đựng) + 不住 (bất trụ – không giữ được) → không kìm nén được; cũng chỉ không chịu nổi tác động.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😂","examples":[{"type":"basic","zh":"她禁不住笑了。","pinyin":"Tā jīnbuzhù xiào le.","vi":"Cô ấy không nhịn được cười."},{"type":"simple","zh":"孩子们禁不住美食的诱惑。","pinyin":"Háizimen jīnbuzhù měishí de yòuhuò.","vi":"Bọn trẻ không cưỡng lại được sức hấp dẫn của đồ ăn ngon."},{"type":"compound","zh":"虽然他想忍住眼泪，但是看到母亲时还是禁不住哭了。","pinyin":"Suīrán tā xiǎng rěn zhù yǎnlèi, dànshì kàndào mǔqīn shí háishì jīnbuzhù kū le.","vi":"Tuy muốn kìm nước mắt nhưng khi nhìn thấy mẹ, anh ấy vẫn không nhịn được mà khóc."}],"related":[{"hanzi":"忍不住","pinyin":"rěnbuzhù","vi":"không nhịn được"},{"hanzi":"经不住","pinyin":"jīngbuzhù","vi":"không chịu nổi"},{"hanzi":"不由得","pinyin":"bùyóude","vi":"bất giác"},{"hanzi":"禁得住","pinyin":"jīndezhù","vi":"chịu được"}]},{"id":"禁忌","hanzi":"禁忌","pinyin":"jìnjì","meaning_vi":"điều cấm kỵ, kiêng kỵ","explanation":"禁 (cấm) + 忌 (kỵ – kiêng) → điều bị cấm, phải kiêng; trong y học còn là chống chỉ định.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🚫","examples":[{"type":"basic","zh":"每个民族都有禁忌。","pinyin":"Měi gè mínzú dōu yǒu jìnjì.","vi":"Dân tộc nào cũng có những điều cấm kỵ."},{"type":"simple","zh":"去别的国家旅游要了解当地的禁忌。","pinyin":"Qù biéde guójiā lǚyóu yào liǎojiě dāngdì de jìnjì.","vi":"Đi du lịch nước khác cần tìm hiểu những điều kiêng kỵ ở đó."},{"type":"compound","zh":"如果不懂饮食禁忌，就可能在宴会上闹笑话。","pinyin":"Rúguǒ bù dǒng yǐnshí jìnjì, jiù kěnéng zài yànhuì shang nàoxiàohua.","vi":"Nếu không biết những kiêng kỵ trong ăn uống thì có thể bị cười chê trong bữa tiệc."}],"related":[{"hanzi":"忌讳","pinyin":"jìhuì","vi":"kiêng kỵ"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"},{"hanzi":"避讳","pinyin":"bìhuì","vi":"kiêng tránh"},{"hanzi":"忌口","pinyin":"jìkǒu","vi":"kiêng ăn"}]},{"id":"禁区","hanzi":"禁区","pinyin":"jìnqū","meaning_vi":"khu vực cấm, vùng cấm","explanation":"禁 (cấm) + 区 (khu – vùng) → vùng không được vào; trong bóng đá là vòng cấm địa.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"⛔","examples":[{"type":"basic","zh":"这里是军事禁区。","pinyin":"Zhèlǐ shì jūnshì jìnqū.","vi":"Đây là khu vực cấm quân sự."},{"type":"simple","zh":"他在禁区内被对方球员绊倒了。","pinyin":"Tā zài jìnqū nèi bèi duìfāng qiúyuán bàndǎo le.","vi":"Anh ấy bị cầu thủ đối phương ngáng ngã trong vòng cấm."},{"type":"compound","zh":"即使你是记者，也不能擅自进入禁区。","pinyin":"Jíshǐ nǐ shì jìzhě, yě bù néng shànzì jìnrù jìnqū.","vi":"Dù bạn là phóng viên cũng không được tự tiện vào khu vực cấm."}],"related":[{"hanzi":"禁地","pinyin":"jìndì","vi":"vùng cấm"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"},{"hanzi":"区域","pinyin":"qūyù","vi":"khu vực"},{"hanzi":"雷区","pinyin":"léiqū","vi":"bãi mìn"}],"traditional":"禁區"},{"id":"经","hanzi":"经","pinyin":"jīng","meaning_vi":"qua, thông qua, trải qua; kinh sách","explanation":"经 (kinh – sợi dọc, đi qua) → đi qua, trải qua; cũng chỉ sách kinh điển như 佛经.","hsk_level":"7-9","tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"经研究，同意你的申请。","pinyin":"Jīng yánjiū, tóngyì nǐ de shēnqǐng.","vi":"Qua xem xét, đồng ý với đơn của bạn."},{"type":"simple","zh":"这班火车经南京开往上海。","pinyin":"Zhè bān huǒchē jīng Nánjīng kāiwǎng Shànghǎi.","vi":"Chuyến tàu này đi qua Nam Kinh đến Thượng Hải."},{"type":"compound","zh":"虽然经医生多次治疗，但是他的病还是没有好转。","pinyin":"Suīrán jīng yīshēng duōcì zhìliáo, dànshì tā de bìng háishì méiyǒu hǎozhuǎn.","vi":"Tuy đã được bác sĩ điều trị nhiều lần nhưng bệnh của anh ấy vẫn không đỡ."}],"related":[{"hanzi":"经过","pinyin":"jīngguò","vi":"đi qua, trải qua"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"kinh nghiệm"},{"hanzi":"佛经","pinyin":"fójīng","vi":"kinh Phật"}],"traditional":"經"},{"id":"经久不息","hanzi":"经久不息","pinyin":"jīngjiǔ-bùxī","meaning_vi":"kéo dài mãi không dứt","explanation":"经久 (kinh cửu – trải qua lâu) + 不息 (bất tức – không ngừng) → kéo dài rất lâu không dứt; thường nói về tiếng vỗ tay, tiếng hoan hô.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👏","examples":[{"type":"basic","zh":"掌声经久不息。","pinyin":"Zhǎngshēng jīngjiǔbùxī.","vi":"Tiếng vỗ tay kéo dài mãi không dứt."},{"type":"simple","zh":"演出结束后，台下响起了经久不息的掌声。","pinyin":"Yǎnchū jiéshù hòu, táixià xiǎngqǐle jīngjiǔbùxī de zhǎngshēng.","vi":"Buổi diễn kết thúc, dưới khán đài vang lên tràng pháo tay không ngớt."},{"type":"compound","zh":"因为他的演讲非常感人，所以会场里的掌声经久不息。","pinyin":"Yīnwèi tā de yǎnjiǎng fēicháng gǎnrén, suǒyǐ huìchǎng lǐ de zhǎngshēng jīngjiǔbùxī.","vi":"Vì bài diễn thuyết của ông rất xúc động nên tiếng vỗ tay trong hội trường kéo dài mãi không dứt."}],"related":[{"hanzi":"掌声","pinyin":"zhǎngshēng","vi":"tiếng vỗ tay"},{"hanzi":"欢呼","pinyin":"huānhū","vi":"hoan hô"},{"hanzi":"川流不息","pinyin":"chuānliúbùxī","vi":"nườm nượp không ngớt"},{"hanzi":"久久","pinyin":"jiǔjiǔ","vi":"rất lâu"}],"traditional":"經久不息"},{"id":"经贸","hanzi":"经贸","pinyin":"jīngmào","meaning_vi":"kinh tế thương mại","explanation":"经 (kinh – kinh tế) + 贸 (mậu – mậu dịch) → cách gọi tắt của kinh tế và thương mại.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🤝","examples":[{"type":"basic","zh":"两国经贸往来频繁。","pinyin":"Liǎngguó jīngmào wǎnglái pínfán.","vi":"Hai nước có quan hệ kinh tế thương mại qua lại thường xuyên."},{"type":"simple","zh":"他在一家经贸公司当翻译。","pinyin":"Tā zài yìjiā jīngmào gōngsī dāng fānyì.","vi":"Anh ấy làm phiên dịch ở một công ty kinh tế thương mại."},{"type":"compound","zh":"随着经贸合作不断加深，两国的关系也越来越好。","pinyin":"Suízhe jīngmào hézuò búduàn jiāshēn, liǎngguó de guānxi yě yuèláiyuè hǎo.","vi":"Cùng với việc hợp tác kinh tế thương mại không ngừng sâu rộng, quan hệ hai nước cũng ngày càng tốt đẹp."}],"related":[{"hanzi":"经济","pinyin":"jīngjì","vi":"kinh tế"},{"hanzi":"贸易","pinyin":"màoyì","vi":"thương mại"},{"hanzi":"外贸","pinyin":"wàimào","vi":"ngoại thương"},{"hanzi":"经商","pinyin":"jīngshāng","vi":"kinh doanh"}],"traditional":"經貿"},{"id":"经受","hanzi":"经受","pinyin":"jīngshòu","meaning_vi":"trải qua, chịu đựng, chịu được","explanation":"经 (kinh – trải qua) + 受 (thụ – chịu) → trải qua và chịu đựng thử thách, khó khăn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"他经受了考验。","pinyin":"Tā jīngshòule kǎoyàn.","vi":"Anh ấy đã vượt qua thử thách."},{"type":"simple","zh":"这座桥经受住了大地震的考验。","pinyin":"Zhè zuò qiáo jīngshòu zhùle dà dìzhèn de kǎoyàn.","vi":"Cây cầu này đã chịu được thử thách của trận động đất lớn."},{"type":"compound","zh":"虽然经受了很多挫折，但是她从来没有放弃梦想。","pinyin":"Suīrán jīngshòule hěn duō cuòzhé, dànshì tā cónglái méiyǒu fàngqì mèngxiǎng.","vi":"Tuy đã trải qua nhiều thất bại nhưng cô ấy chưa bao giờ từ bỏ ước mơ."}],"related":[{"hanzi":"承受","pinyin":"chéngshòu","vi":"chịu đựng"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải qua"},{"hanzi":"遭受","pinyin":"zāoshòu","vi":"gặp phải"},{"hanzi":"忍受","pinyin":"rěnshòu","vi":"nhẫn nhịn"}],"traditional":"經受"},{"id":"荆棘","hanzi":"荆棘","pinyin":"jīngjí","meaning_vi":"bụi gai, chông gai","explanation":"荆 (kinh – cây gai) + 棘 (cức – cây có gai) → bụi cây đầy gai; nghĩa bóng là khó khăn, trở ngại.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌵","examples":[{"type":"basic","zh":"山坡上长满了荆棘。","pinyin":"Shānpō shang zhǎngmǎnle jīngjí.","vi":"Trên sườn núi mọc đầy bụi gai."},{"type":"simple","zh":"创业的道路上充满了荆棘。","pinyin":"Chuàngyè de dào lùshang chōngmǎnle jīngjí.","vi":"Con đường khởi nghiệp đầy rẫy chông gai."},{"type":"compound","zh":"即使前面布满荆棘，他也决心走下去。","pinyin":"Jíshǐ qiánmiàn bùmǎn jīngjí, tā yě juéxīn zǒu xiàqù.","vi":"Dù phía trước đầy chông gai, anh ấy vẫn quyết tâm đi tiếp."}],"related":[{"hanzi":"披荆斩棘","pinyin":"pījīngzhǎnjí","vi":"vượt mọi chông gai"},{"hanzi":"坎坷","pinyin":"kǎnkě","vi":"gập ghềnh"},{"hanzi":"障碍","pinyin":"zhàng'ài","vi":"trở ngại"},{"hanzi":"刺","pinyin":"cì","vi":"gai"}],"traditional":"荊棘"},{"id":"惊","hanzi":"惊","pinyin":"jīng","meaning_vi":"giật mình, kinh ngạc; làm kinh động","explanation":"惊 (kinh – sợ, giật mình) → bất ngờ mà sợ hãi; cũng là làm cho kinh động.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"我吃了一惊。","pinyin":"Wǒ chīle yì jīng.","vi":"Tôi giật cả mình."},{"type":"simple","zh":"一声巨响把熟睡的孩子惊醒了。","pinyin":"Yìshēng jùxiǎng bǎ shúshuì de háizi jīngxǐng le.","vi":"Một tiếng nổ lớn làm đứa bé đang ngủ say giật mình tỉnh giấc."},{"type":"compound","zh":"他听到这个消息时大吃一惊，因为他根本没想到会这样。","pinyin":"Tā tīngdào zhè gè xiāoxi shí dàchīyìjīng, yīnwèi tā gēnběn méi xiǎngdào huì zhèyàng.","vi":"Anh ấy vô cùng kinh ngạc khi nghe tin này, vì anh hoàn toàn không ngờ lại như vậy."}],"related":[{"hanzi":"吃惊","pinyin":"chījīng","vi":"giật mình"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"chấn động"},{"hanzi":"惊喜","pinyin":"jīngxǐ","vi":"bất ngờ vui mừng"}],"traditional":"驚"},{"id":"惊诧","hanzi":"惊诧","pinyin":"jīngchà","meaning_vi":"kinh ngạc, sửng sốt","explanation":"惊 (kinh – bất ngờ) + 诧 (sá – lạ lùng) → ngạc nhiên vì điều lạ; thường dùng trong văn viết.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"大家都很惊诧。","pinyin":"Dàjiā dōu hěn jīngchà.","vi":"Mọi người đều rất sửng sốt."},{"type":"simple","zh":"他的决定让所有人感到惊诧。","pinyin":"Tā de juédìng ràng suǒyǒurén gǎndào jīngchà.","vi":"Quyết định của anh ấy khiến tất cả mọi người kinh ngạc."},{"type":"compound","zh":"虽然大家早有准备，但是看到结果时还是十分惊诧。","pinyin":"Suīrán dàjiā zǎo yǒu zhǔnbèi, dànshì kàndào jiéguǒ shí háishì shífēn jīngchà.","vi":"Tuy mọi người đã chuẩn bị từ trước nhưng khi thấy kết quả vẫn vô cùng sửng sốt."}],"related":[{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"},{"hanzi":"诧异","pinyin":"chàyì","vi":"ngạc nhiên"},{"hanzi":"惊奇","pinyin":"jīngqí","vi":"lấy làm lạ"},{"hanzi":"吃惊","pinyin":"chījīng","vi":"giật mình"}],"traditional":"驚詫"},{"id":"惊慌","hanzi":"惊慌","pinyin":"jīnghuāng","meaning_vi":"hoảng sợ, hoảng hốt","explanation":"惊 (kinh – sợ) + 慌 (hoảng – rối) → sợ hãi đến rối loạn.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😨","examples":[{"type":"basic","zh":"他显得很惊慌。","pinyin":"Tā xiǎnde hěn jīnghuāng.","vi":"Anh ấy trông rất hoảng hốt."},{"type":"simple","zh":"地震发生时大家惊慌地跑出了大楼。","pinyin":"Dìzhèn fāshēng shí dàjiā jīnghuāng de pǎochūle dàlóu.","vi":"Khi động đất xảy ra, mọi người hoảng hốt chạy ra khỏi tòa nhà."},{"type":"compound","zh":"遇到火灾时千万不要惊慌，而是要冷静地找安全出口。","pinyin":"Yùdào huǒzāi shí qiānwàn bú yào jīnghuāng, érshì yào lěngjìng de zhǎo ānquán chūkǒu.","vi":"Khi gặp hỏa hoạn tuyệt đối đừng hoảng sợ, mà phải bình tĩnh tìm lối thoát an toàn."}],"related":[{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"},{"hanzi":"慌张","pinyin":"huāngzhāng","vi":"luống cuống"},{"hanzi":"恐慌","pinyin":"kǒnghuāng","vi":"khủng hoảng, hoảng loạn"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"}],"traditional":"驚慌"},{"id":"惊醒","hanzi":"惊醒","pinyin":"jīngxǐng","meaning_vi":"giật mình tỉnh giấc, làm bừng tỉnh","explanation":"惊 (kinh – giật mình) + 醒 (tỉnh – thức) → giật mình tỉnh dậy; cũng là làm ai bừng tỉnh.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🛌","examples":[{"type":"basic","zh":"雷声把我惊醒了。","pinyin":"Léishēng bǎ wǒ jīngxǐng le.","vi":"Tiếng sấm làm tôi giật mình tỉnh giấc."},{"type":"simple","zh":"半夜他被一阵电话铃声惊醒。","pinyin":"Bànyè tā bèi yízhèn diànhuà língshēng jīngxǐng.","vi":"Nửa đêm anh ấy bị tiếng chuông điện thoại làm giật mình tỉnh dậy."},{"type":"compound","zh":"因为做了一个噩梦，所以她半夜突然惊醒了。","pinyin":"Yīnwèi zuòle yí gè èmèng, suǒyǐ tā bànyè tūrán jīngxǐng le.","vi":"Vì gặp ác mộng nên nửa đêm cô ấy đột nhiên giật mình tỉnh dậy."}],"related":[{"hanzi":"醒来","pinyin":"xǐnglái","vi":"tỉnh dậy"},{"hanzi":"吵醒","pinyin":"chǎoxǐng","vi":"đánh thức (vì ồn)"},{"hanzi":"惊动","pinyin":"jīngdòng","vi":"làm kinh động"},{"hanzi":"清醒","pinyin":"qīngxǐng","vi":"tỉnh táo"}],"traditional":"驚醒"},{"id":"精练","hanzi":"精练","pinyin":"jīngliàn","meaning_vi":"ngắn gọn súc tích, tinh luyện","explanation":"精 (tinh – tinh túy) + 练 (luyện – rèn giũa) → được gọt giũa kỹ, câu chữ ngắn gọn mà súc tích.","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"他的语言很精练。","pinyin":"Tā de yǔyán hěn jīngliàn.","vi":"Ngôn ngữ của anh ấy rất súc tích."},{"type":"simple","zh":"老师要求我们把文章写得更精练一些。","pinyin":"Lǎoshī yāoqiú wǒmen bǎ wénzhāng xiě de gèng jīngliàn yìxiē.","vi":"Thầy giáo yêu cầu chúng tôi viết bài văn súc tích hơn một chút."},{"type":"compound","zh":"虽然这首诗只有四句，但是语言非常精练。","pinyin":"Suīrán zhè shǒu shī zhǐyǒu sì jù, dànshì yǔyán fēicháng jīngliàn.","vi":"Tuy bài thơ này chỉ có bốn câu nhưng ngôn ngữ vô cùng súc tích."}],"related":[{"hanzi":"精炼","pinyin":"jīngliàn","vi":"tinh luyện"},{"hanzi":"简练","pinyin":"jiǎnliàn","vi":"gọn gàng"},{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"ngắn gọn"},{"hanzi":"啰唆","pinyin":"luōsuo","vi":"dài dòng"}],"traditional":"精練"},{"id":"精妙","hanzi":"精妙","pinyin":"jīngmiào","meaning_vi":"tinh xảo, tuyệt diệu","explanation":"精 (tinh – tinh xảo) + 妙 (diệu – kỳ diệu) → tinh tế và tuyệt diệu; thường dùng để khen tác phẩm nghệ thuật, kỹ thuật.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"这幅画构思精妙。","pinyin":"Zhè fú huà gòusī jīngmiào.","vi":"Bức tranh này có ý tưởng tuyệt diệu."},{"type":"simple","zh":"魔术师精妙的表演让观众看呆了。","pinyin":"Móshùshī jīngmiào de biǎoyǎn ràng guānzhòng kàndāi le.","vi":"Màn biểu diễn tuyệt diệu của ảo thuật gia khiến khán giả xem đến ngây người."},{"type":"compound","zh":"虽然这只手表很小，但是内部结构非常精妙。","pinyin":"Suīrán zhè zhī shǒubiǎo hěn xiǎo, dànshì nèibù jiégòu fēicháng jīngmiào.","vi":"Tuy chiếc đồng hồ này rất nhỏ nhưng cấu tạo bên trong vô cùng tinh xảo."}],"related":[{"hanzi":"巧妙","pinyin":"qiǎomiào","vi":"khéo léo"},{"hanzi":"精美","pinyin":"jīngměi","vi":"tinh mỹ"},{"hanzi":"奇妙","pinyin":"qímiào","vi":"kỳ diệu"},{"hanzi":"精致","pinyin":"jīngzhì","vi":"tinh tế"}]},{"id":"精明","hanzi":"精明","pinyin":"jīngmíng","meaning_vi":"khôn khéo, tinh tường, sắc sảo","explanation":"精 (tinh – tinh tường) + 明 (minh – sáng suốt) → tinh tường sáng suốt, giỏi tính toán.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🦊","examples":[{"type":"basic","zh":"她是个精明的商人。","pinyin":"Tā shì gè jīngmíng de shāngrén.","vi":"Bà ấy là một thương nhân khôn khéo."},{"type":"simple","zh":"这个老板做生意非常精明。","pinyin":"Zhè gè lǎobǎn zuòshēngyi fēicháng jīngmíng.","vi":"Ông chủ này làm ăn rất khôn ngoan."},{"type":"compound","zh":"虽然他看起来很老实，但是其实非常精明。","pinyin":"Suīrán tā kànqǐlái hěn lǎoshi, dànshì qíshí fēicháng jīngmíng.","vi":"Tuy anh ta trông có vẻ thật thà nhưng thực ra rất tinh ranh."}],"related":[{"hanzi":"聪明","pinyin":"cōngmíng","vi":"thông minh"},{"hanzi":"精明能干","pinyin":"jīngmíngnénggàn","vi":"giỏi giang tháo vát"},{"hanzi":"机灵","pinyin":"jīling","vi":"lanh lợi"},{"hanzi":"糊涂","pinyin":"hútu","vi":"hồ đồ"}]},{"id":"精神病","hanzi":"精神病","pinyin":"jīngshénbìng","meaning_vi":"bệnh tâm thần, rối loạn tâm thần","explanation":"精神 (tinh thần) + 病 (bệnh) → bệnh về tinh thần, rối loạn tâm thần.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🧠","examples":[{"type":"basic","zh":"他患有精神病。","pinyin":"Tā huànyǒu jīngshénbìng.","vi":"Anh ấy mắc bệnh tâm thần."},{"type":"simple","zh":"这位医生专门研究精神病的治疗。","pinyin":"Zhè wèi yīshēng zhuānmén yánjiū jīngshénbìng de zhìliáo.","vi":"Vị bác sĩ này chuyên nghiên cứu điều trị bệnh tâm thần."},{"type":"compound","zh":"如果长期压力太大，就有可能引发精神病。","pinyin":"Rúguǒ chángqī yālì tài dà, jiù yǒukěnéng yǐnfā jīngshénbìng.","vi":"Nếu áp lực quá lớn trong thời gian dài thì có thể gây ra bệnh tâm thần."}],"related":[{"hanzi":"精神","pinyin":"jīngshén","vi":"tinh thần"},{"hanzi":"心理","pinyin":"xīnlǐ","vi":"tâm lý"},{"hanzi":"抑郁症","pinyin":"yìyùzhèng","vi":"bệnh trầm cảm"},{"hanzi":"精神科","pinyin":"jīngshénkē","vi":"khoa tâm thần"}]},{"id":"精细","hanzi":"精细","pinyin":"jīngxì","meaning_vi":"tinh xảo, tỉ mỉ, kỹ lưỡng","explanation":"精 (tinh – tinh túy, kỹ càng) + 细 (tế – nhỏ, kỹ) → làm rất kỹ đến từng chi tiết nhỏ; dùng cho đồ vật, công việc hay cách làm.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这件绣品很精细。","pinyin":"Zhè jiàn xiù pǐn hěn jīngxì.","vi":"Bức tranh thêu này rất tinh xảo."},{"type":"simple","zh":"这块手表的零件加工得十分精细。","pinyin":"Zhè kuài shǒubiǎo de língjiàn jiāgōng de shífēn jīngxì.","vi":"Linh kiện của chiếc đồng hồ này được gia công vô cùng tỉ mỉ."},{"type":"compound","zh":"虽然这项活儿很精细，但是她从来不嫌麻烦。","pinyin":"Suīrán zhè xiàng huór hěn jīngxì, dànshì tā cóngláibù xiánmáfan.","vi":"Tuy công việc này rất tỉ mỉ nhưng cô ấy chưa bao giờ ngại phiền."}],"related":[{"hanzi":"精致","pinyin":"jīngzhì","vi":"tinh xảo"},{"hanzi":"细致","pinyin":"xìzhì","vi":"tỉ mỉ"},{"hanzi":"精密","pinyin":"jīngmì","vi":"chính xác cao"},{"hanzi":"粗糙","pinyin":"cūcāo","vi":"thô ráp"}],"traditional":"精細"},{"id":"精英","hanzi":"精英","pinyin":"jīngyīng","meaning_vi":"tinh hoa, người ưu tú, giới tinh anh","explanation":"精 (tinh – tinh túy) + 英 (anh – người tài giỏi) → những người xuất sắc nhất trong một tập thể hay một ngành.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏅","examples":[{"type":"basic","zh":"他们都是行业精英。","pinyin":"Tāmen dōu shì hángyè jīngyīng.","vi":"Họ đều là tinh hoa của ngành."},{"type":"simple","zh":"这家公司吸引了全国各地的技术精英。","pinyin":"Zhè jiā gōngsī xīyǐnle quánguó gèdì de jìshù jīngyīng.","vi":"Công ty này thu hút nhân tài kỹ thuật từ khắp cả nước."},{"type":"compound","zh":"即使身边都是精英，他也没有失去自信。","pinyin":"Jíshǐ shēnbiān dōu shì jīngyīng, tā yě méiyǒu shīqù zìxìn.","vi":"Dù xung quanh toàn người ưu tú, anh ấy vẫn không mất tự tin."}],"related":[{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"英才","pinyin":"yīngcái","vi":"anh tài"},{"hanzi":"精华","pinyin":"jīnghuá","vi":"tinh hoa"},{"hanzi":"骨干","pinyin":"gǔgàn","vi":"nòng cốt"}]},{"id":"颈部","hanzi":"颈部","pinyin":"jǐngbù","meaning_vi":"vùng cổ, phần cổ","explanation":"颈 (cảnh – cổ) + 部 (bộ – bộ phận) → phần cổ trên cơ thể; cách nói trang trọng, hay dùng trong y học.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧣","examples":[{"type":"basic","zh":"他颈部受了伤。","pinyin":"Tā jǐngbù shòule shāng.","vi":"Anh ấy bị thương ở cổ."},{"type":"simple","zh":"长时间低头看手机容易引起颈部疼痛。","pinyin":"Cháng shíjiān dītóu kàn shǒujī róngyì yǐnqǐ jǐngbù téngtòng.","vi":"Cúi đầu xem điện thoại lâu dễ gây đau cổ."},{"type":"compound","zh":"如果颈部总是发酸，就应该多做些伸展运动。","pinyin":"Rúguǒ jǐngbù zǒngshì fā suān, jiù yīnggāi duō zuò xiē shēnzhǎn yùndòng.","vi":"Nếu cổ thường xuyên mỏi thì nên tập các động tác giãn cơ nhiều hơn."}],"related":[{"hanzi":"脖子","pinyin":"bózi","vi":"cái cổ"},{"hanzi":"颈椎","pinyin":"jǐngzhuī","vi":"đốt sống cổ"},{"hanzi":"肩膀","pinyin":"jiānbǎng","vi":"vai"},{"hanzi":"头部","pinyin":"tóubù","vi":"vùng đầu"}],"traditional":"頸部"},{"id":"景观","hanzi":"景观","pinyin":"jǐngguān","meaning_vi":"cảnh quan, phong cảnh","explanation":"景 (cảnh – phong cảnh) + 观 (quan – nhìn ngắm, quang cảnh) → cảnh vật tự nhiên hoặc nhân tạo có thể ngắm nhìn.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"这里的景观很独特。","pinyin":"Zhèlǐ de jǐngguān hěn dútè.","vi":"Cảnh quan ở đây rất độc đáo."},{"type":"simple","zh":"城市新建的河边景观吸引了不少游客。","pinyin":"Chéngshì xīnjiàn de hébiān jǐngguān xīyǐnle bùshǎo yóukè.","vi":"Cảnh quan ven sông mới xây của thành phố thu hút không ít du khách."},{"type":"compound","zh":"因为过度开发，所以这片海岸的自然景观遭到了破坏。","pinyin":"Yīnwèi guòdù kāifā, suǒyǐ zhè piàn hǎi'àn de zìrán jǐngguān zāodàole pòhuài.","vi":"Vì khai thác quá mức nên cảnh quan tự nhiên của bờ biển này bị phá hoại."}],"related":[{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"},{"hanzi":"景色","pinyin":"jǐngsè","vi":"cảnh sắc"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"},{"hanzi":"奇观","pinyin":"qíguān","vi":"kỳ quan"}],"traditional":"景觀"},{"id":"景区","hanzi":"景区","pinyin":"jǐngqū","meaning_vi":"khu du lịch, khu thắng cảnh","explanation":"景 (cảnh – phong cảnh) + 区 (khu – khu vực) → khu vực có cảnh đẹp được quản lý để đón khách tham quan.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🎫","examples":[{"type":"basic","zh":"景区门票不贵。","pinyin":"Jǐngqū ménpiào bú guì.","vi":"Vé vào khu du lịch không đắt."},{"type":"simple","zh":"国庆节期间各大景区都挤满了游客。","pinyin":"Guóqìngjié qījiān gè dà jǐngqū dōu jǐmǎnle yóukè.","vi":"Dịp Quốc khánh các khu du lịch lớn đều chật kín du khách."},{"type":"compound","zh":"要是早上八点前进景区，就能避开排队的人群。","pinyin":"Yàoshi zǎoshang bā diǎn qiánjìn jǐngqū, jiù néng bìkāi páiduì de rénqún.","vi":"Nếu vào khu du lịch trước tám giờ sáng thì có thể tránh được đám đông xếp hàng."}],"related":[{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"},{"hanzi":"风景区","pinyin":"fēngjǐngqū","vi":"khu phong cảnh"},{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"},{"hanzi":"游客","pinyin":"yóukè","vi":"du khách"}],"traditional":"景區"},{"id":"警车","hanzi":"警车","pinyin":"jǐngchē","meaning_vi":"xe cảnh sát","explanation":"警 (cảnh – cảnh sát, cảnh giác) + 车 (xa – xe) → xe chuyên dùng của cảnh sát.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚓","examples":[{"type":"basic","zh":"门口停着一辆警车。","pinyin":"Ménkǒu tíngzhe yí liàng jǐngchē.","vi":"Trước cửa đỗ một chiếc xe cảnh sát."},{"type":"simple","zh":"远处传来一阵刺耳的警车鸣笛声。","pinyin":"Yuǎnchù chuánlái yízhèn cì'ěr de jǐngchē míngdí shēng.","vi":"Từ xa vọng lại tiếng còi xe cảnh sát chói tai."},{"type":"compound","zh":"一看到警车开过来，那几个小偷就四处逃跑了。","pinyin":"Yí kàndào jǐngchē kāi guòlái, nà jǐ ge xiǎotōu jiù sìchù táopǎo le.","vi":"Vừa thấy xe cảnh sát chạy tới, mấy tên trộm liền chạy tán loạn."}],"related":[{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"救护车","pinyin":"jiùhùchē","vi":"xe cứu thương"},{"hanzi":"消防车","pinyin":"xiāofángchē","vi":"xe cứu hỏa"},{"hanzi":"警笛","pinyin":"jǐngdí","vi":"còi cảnh sát"}],"traditional":"警車"},{"id":"警官","hanzi":"警官","pinyin":"jǐngguān","meaning_vi":"sĩ quan cảnh sát, viên cảnh sát","explanation":"警 (cảnh – cảnh sát) + 官 (quan – quan chức) → người cảnh sát có chức vụ; cũng dùng để gọi cảnh sát một cách lịch sự.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"👮","examples":[{"type":"basic","zh":"警官，我的钱包丢了。","pinyin":"Jǐngguān, wǒ de qiánbāo diū le.","vi":"Thưa anh cảnh sát, tôi bị mất ví."},{"type":"simple","zh":"那位警官耐心地记录了事情的经过。","pinyin":"Nà wèi jǐngguān nàixīn de jìlù leshì qing de jīngguò.","vi":"Viên cảnh sát ấy kiên nhẫn ghi lại diễn biến sự việc."},{"type":"compound","zh":"虽然警官很年轻，但是他处理案子非常老练。","pinyin":"Suīrán jǐngguān hěn niánqīng, dànshì tā chǔlǐ ànzi fēicháng lǎoliàn.","vi":"Tuy viên cảnh sát còn trẻ nhưng xử lý vụ án rất lão luyện."}],"related":[{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"军官","pinyin":"jūnguān","vi":"sĩ quan quân đội"},{"hanzi":"警车","pinyin":"jǐngchē","vi":"xe cảnh sát"},{"hanzi":"法官","pinyin":"fǎguān","vi":"thẩm phán"}]},{"id":"竞技","hanzi":"竞技","pinyin":"jìngjì","meaning_vi":"thi đấu, tranh tài (kỹ năng, thể thao)","explanation":"竞 (cạnh – tranh đua) + 技 (kỹ – kỹ năng) → tranh tài về kỹ năng, thường là thi đấu thể thao.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏟️","examples":[{"type":"basic","zh":"体育竞技很激烈。","pinyin":"Tǐyù jìngjì hěn jīliè.","vi":"Thi đấu thể thao rất quyết liệt."},{"type":"simple","zh":"他从小就对电子竞技特别感兴趣。","pinyin":"Tā cóngxiǎo jiù duì diànzǐ jìngjì tèbié gǎnxìngqù.","vi":"Từ nhỏ cậu ấy đã đặc biệt hứng thú với thể thao điện tử."},{"type":"compound","zh":"竞技比赛虽然讲究输赢，但是更重要的是公平。","pinyin":"Jìngjì bǐsài suīrán jiǎngjiu shūyíng, dànshì gèng zhòngyào de shì gōngpíng.","vi":"Thi đấu tuy coi trọng thắng thua nhưng quan trọng hơn là công bằng."}],"related":[{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"竞赛","pinyin":"jìngsài","vi":"cuộc thi"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"trận đấu"},{"hanzi":"技艺","pinyin":"jìyì","vi":"kỹ nghệ"}],"traditional":"競技"},{"id":"竞相","hanzi":"竞相","pinyin":"jìngxiāng","meaning_vi":"đua nhau, tranh nhau","explanation":"竞 (cạnh – tranh đua) + 相 (tương – lẫn nhau) → đua nhau cùng làm một việc; văn viết, đứng trước động từ.","hsk_level":"7-9","tags":["pho-tu"],"image":"🌸","examples":[{"type":"basic","zh":"百花竞相开放。","pinyin":"Bǎi huā jìngxiāng kāifàng.","vi":"Trăm hoa đua nhau nở rộ."},{"type":"simple","zh":"各大品牌竞相推出新款手机。","pinyin":"Gè dà pǐnpái jìngxiāng tuīchū xīnkuǎn shǒujī.","vi":"Các thương hiệu lớn đua nhau tung ra điện thoại mẫu mới."},{"type":"compound","zh":"因为这只股票涨得太快，所以投资者竞相买入。","pinyin":"Yīnwèi zhè zhī gǔpiào zhǎng de tài kuài, suǒyǐ tóuzīzhě jìngxiāng mǎirù.","vi":"Vì cổ phiếu này tăng quá nhanh nên nhà đầu tư đua nhau mua vào."}],"related":[{"hanzi":"争相","pinyin":"zhēngxiāng","vi":"tranh nhau"},{"hanzi":"纷纷","pinyin":"fēnfēn","vi":"tới tấp"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"争先恐后","pinyin":"zhēngxiānkǒnghòu","vi":"tranh nhau lên trước"}],"traditional":"競相"},{"id":"竟","hanzi":"竟","pinyin":"jìng","meaning_vi":"vậy mà, lại, không ngờ; rốt cuộc","explanation":"竟 (cánh – rốt cuộc, không ngờ) → biểu thị kết quả ngoài dự đoán, giống 竟然; văn viết, đứng trước động từ.","hsk_level":"7-9","tags":["pho-tu"],"image":"😲","examples":[{"type":"basic","zh":"他竟一句话也没说。","pinyin":"Tā jìng yíjùhuà yě méi shuō.","vi":"Vậy mà anh ta chẳng nói lấy một câu."},{"type":"simple","zh":"我们找了半天的钥匙竟在他口袋里。","pinyin":"Wǒmen zhǎole bàn tiān de yàoshi jìng zài tā kǒudai lǐ.","vi":"Chiếc chìa khóa chúng tôi tìm cả buổi hóa ra lại nằm trong túi anh ấy."},{"type":"compound","zh":"虽然只学了半年，但是她的中文竟说得这么流利。","pinyin":"Suīrán zhǐ xuéle bàn nián, dànshì tā de Zhōngwén jìng shuō de zhème liúlì.","vi":"Tuy chỉ học nửa năm nhưng không ngờ cô ấy nói tiếng Trung trôi chảy đến vậy."}],"related":[{"hanzi":"竟然","pinyin":"jìngrán","vi":"vậy mà, không ngờ"},{"hanzi":"居然","pinyin":"jūrán","vi":"lại, vậy mà"},{"hanzi":"究竟","pinyin":"jiūjìng","vi":"rốt cuộc"},{"hanzi":"毕竟","pinyin":"bìjìng","vi":"dù sao"}]},{"id":"竟敢","hanzi":"竟敢","pinyin":"jìnggǎn","meaning_vi":"dám cả gan, lại dám","explanation":"竟 (cánh – không ngờ) + 敢 (cảm – dám) → không ngờ lại dám làm điều quá phận; mang ý trách móc, phẫn nộ.","hsk_level":"7-9","tags":["dong-tu"],"image":"😠","examples":[{"type":"basic","zh":"你竟敢骗我！","pinyin":"Nǐ jìnggǎn piàn wǒ!","vi":"Mày dám lừa tao à!"},{"type":"simple","zh":"这个小偷竟敢在警察局门口偷车。","pinyin":"Zhè ge xiǎotōu jìnggǎn zài jǐngchájú ménkǒu tōu chē.","vi":"Tên trộm này dám cả gan trộm xe ngay trước cửa đồn cảnh sát."},{"type":"compound","zh":"他不但不认错，竟敢当着大家的面顶撞老师。","pinyin":"Tā búdàn bú rèncuò, jìnggǎn dāngzhe dàjiā de miàn dǐngzhuàng lǎoshī.","vi":"Cậu ta không những không nhận lỗi mà còn dám cãi lại thầy giáo trước mặt mọi người."}],"related":[{"hanzi":"竟然","pinyin":"jìngrán","vi":"vậy mà"},{"hanzi":"胆敢","pinyin":"dǎngǎn","vi":"cả gan"},{"hanzi":"敢于","pinyin":"gǎnyú","vi":"dám"},{"hanzi":"大胆","pinyin":"dàdǎn","vi":"to gan"}]},{"id":"敬","hanzi":"敬","pinyin":"jìng","meaning_vi":"kính trọng, tôn kính; mời (rượu, trà) một cách cung kính","explanation":"敬 (kính – cung kính, tôn trọng) → tôn trọng người khác; cũng chỉ việc cung kính mời đồ uống, như 敬茶, 敬酒.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我敬您一杯。","pinyin":"Wǒ jìng nín yì bēi.","vi":"Tôi xin kính anh một ly."},{"type":"simple","zh":"新娘按照习俗给公公婆婆敬茶。","pinyin":"Xīnniáng ànzhào xísú gěi gōnggong pópo jìngchá.","vi":"Cô dâu theo phong tục dâng trà cho bố mẹ chồng."},{"type":"compound","zh":"你敬人一尺，别人就会敬你一丈。","pinyin":"Nǐ jìng rén yì chǐ, biérén jiù huì jìng nǐ yí zhàng.","vi":"Bạn kính người một thước, người ta sẽ kính bạn một trượng."}],"related":[{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"敬礼","pinyin":"jìnglǐ","vi":"chào"},{"hanzi":"敬酒","pinyin":"jìngjiǔ","vi":"mời rượu"},{"hanzi":"恭敬","pinyin":"gōngjìng","vi":"cung kính"}]},{"id":"敬酒","hanzi":"敬酒","pinyin":"jìngjiǔ","meaning_vi":"mời rượu, nâng ly chúc","explanation":"敬 (kính – cung kính) + 酒 (tửu – rượu) → cung kính nâng ly mời rượu người khác trong bữa tiệc.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🥂","examples":[{"type":"basic","zh":"新郎挨桌敬酒。","pinyin":"Xīnláng āi zhuō jìngjiǔ.","vi":"Chú rể đi từng bàn mời rượu."},{"type":"simple","zh":"经理端起杯子向客户敬酒。","pinyin":"Jīnglǐ duān qǐ bēizi xiàng kèhù jìngjiǔ.","vi":"Giám đốc nâng ly mời rượu khách hàng."},{"type":"compound","zh":"如果长辈向你敬酒，你就应该站起来回敬。","pinyin":"Rúguǒ zhǎngbèi xiàng nǐ jìngjiǔ, nǐ jiù yīnggāi zhànqǐlái huíjìng.","vi":"Nếu bậc trên mời rượu bạn thì bạn nên đứng dậy mời lại."}],"related":[{"hanzi":"干杯","pinyin":"gānbēi","vi":"cạn ly"},{"hanzi":"碰杯","pinyin":"pèngbēi","vi":"cụng ly"},{"hanzi":"劝酒","pinyin":"quànjiǔ","vi":"ép rượu"},{"hanzi":"回敬","pinyin":"huíjìng","vi":"mời lại"}]},{"id":"敬佩","hanzi":"敬佩","pinyin":"jìngpèi","meaning_vi":"kính phục, khâm phục","explanation":"敬 (kính – tôn kính) + 佩 (bội – bội phục) → vừa tôn trọng vừa phục tài năng, phẩm chất của người khác.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"👏","examples":[{"type":"basic","zh":"我很敬佩她。","pinyin":"Wǒ hěn jìngpèi tā.","vi":"Tôi rất khâm phục cô ấy."},{"type":"simple","zh":"他舍己救人的勇气令所有人敬佩。","pinyin":"Tā shějǐ jiùrén de yǒngqì lìng suǒyǒurén jìngpèi.","vi":"Lòng dũng cảm quên mình cứu người của anh khiến mọi người kính phục."},{"type":"compound","zh":"虽然他身体残疾，但是他乐观的态度让人十分敬佩。","pinyin":"Suīrán tā shēntǐ cánjí, dànshì tā lèguān de tàidù ràng rén shífēn jìngpèi.","vi":"Tuy bị khuyết tật nhưng thái độ lạc quan của anh khiến người ta vô cùng khâm phục."}],"related":[{"hanzi":"佩服","pinyin":"pèifú","vi":"bội phục"},{"hanzi":"钦佩","pinyin":"qīnpèi","vi":"khâm phục"},{"hanzi":"敬重","pinyin":"jìngzhòng","vi":"kính trọng"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"}]},{"id":"敬请","hanzi":"敬请","pinyin":"jìngqǐng","meaning_vi":"kính mời, kính mong, xin vui lòng","explanation":"敬 (kính – cung kính) + 请 (thỉnh – mời, xin) → cách nói trang trọng để mời hoặc đề nghị ai làm gì; hay dùng trong thông báo, thiệp mời.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📨","examples":[{"type":"basic","zh":"敬请大家多提意见。","pinyin":"Jìngqǐng dàjiā duō tí yìjiàn.","vi":"Kính mong mọi người góp nhiều ý kiến."},{"type":"simple","zh":"敬请各位乘客保管好随身物品。","pinyin":"Jìngqǐng gèwèi chéngkè bǎoguǎn hǎo suíshēn wùpǐn.","vi":"Kính đề nghị quý hành khách giữ gìn tư trang cẩn thận."},{"type":"compound","zh":"由于系统正在升级，所以部分服务暂停，敬请谅解。","pinyin":"Yóuyú xìtǒng zhèngzài shēngjí, suǒyǐ bùfen fúwù zàntíng, jìngqǐng liàngjiě.","vi":"Do hệ thống đang nâng cấp nên một số dịch vụ tạm ngừng, kính mong thông cảm."}],"related":[{"hanzi":"恭请","pinyin":"gōngqǐng","vi":"cung kính mời"},{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"mời"},{"hanzi":"光临","pinyin":"guānglín","vi":"ghé thăm"},{"hanzi":"谅解","pinyin":"liàngjiě","vi":"thông cảm"}],"traditional":"敬請"},{"id":"敬重","hanzi":"敬重","pinyin":"jìngzhòng","meaning_vi":"kính trọng, tôn trọng sâu sắc","explanation":"敬 (kính – tôn kính) + 重 (trọng – coi trọng) → hết sức tôn trọng ai vì đức độ, nhân cách.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🎖️","examples":[{"type":"basic","zh":"村民都敬重他。","pinyin":"Cūnmín dōu jìngzhòng tā.","vi":"Dân làng đều kính trọng ông ấy."},{"type":"simple","zh":"这位老医生的人品深受病人敬重。","pinyin":"Zhè wèi lǎo yīshēng de rénpǐn shēnshòu bìngrén jìngzhòng.","vi":"Nhân cách của vị bác sĩ già này được bệnh nhân hết mực kính trọng."},{"type":"compound","zh":"只要你真诚待人，别人就会敬重你。","pinyin":"Zhǐyào nǐ zhēnchéng dàirén, biérén jiù huì jìngzhòng nǐ.","vi":"Chỉ cần bạn đối xử chân thành, người khác sẽ kính trọng bạn."}],"related":[{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"tôn trọng"},{"hanzi":"敬佩","pinyin":"jìngpèi","vi":"khâm phục"},{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"coi thường"}]},{"id":"境地","hanzi":"境地","pinyin":"jìngdì","meaning_vi":"hoàn cảnh, tình cảnh, cảnh ngộ","explanation":"境 (cảnh – cảnh giới, hoàn cảnh) + 地 (địa – nơi chốn) → tình thế mà một người đang lâm vào, thường là khó khăn.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧗","examples":[{"type":"basic","zh":"他陷入了尴尬的境地。","pinyin":"Tā xiànrùle gāngà de jìngdì.","vi":"Anh ấy rơi vào tình cảnh khó xử."},{"type":"simple","zh":"公司因为资金链断裂而走到了破产的境地。","pinyin":"Gōngsī yīnwèi zījīn liàn duànliè ér zǒu dàole pòchǎn de jìngdì.","vi":"Công ty vì đứt dòng vốn mà đi đến bờ phá sản."},{"type":"compound","zh":"如果再不改变策略，我们就会落到无路可走的境地。","pinyin":"Rúguǒ zài bù gǎibiàn cèlüè, wǒmen jiù huì luò dào wú lù kě zǒu de jìngdì.","vi":"Nếu còn không đổi chiến lược, chúng ta sẽ rơi vào cảnh không lối thoát."}],"related":[{"hanzi":"处境","pinyin":"chǔjìng","vi":"hoàn cảnh"},{"hanzi":"境况","pinyin":"jìngkuàng","vi":"tình hình"},{"hanzi":"困境","pinyin":"kùnjìng","vi":"cảnh khốn khó"},{"hanzi":"地步","pinyin":"dìbù","vi":"nông nỗi"}]},{"id":"境内","hanzi":"境内","pinyin":"jìngnèi","meaning_vi":"trong nước, trong lãnh thổ, trong địa phận","explanation":"境 (cảnh – biên giới) + 内 (nội – bên trong) → phạm vi bên trong biên giới một nước hoặc địa phận một vùng.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🗺️","examples":[{"type":"basic","zh":"境内航班已经恢复。","pinyin":"Jìngnèi hángbān yǐjīng huīfù.","vi":"Các chuyến bay nội địa đã được khôi phục."},{"type":"simple","zh":"长江流经中国境内十多个省份。","pinyin":"Chángjiāng liújīng Zhōngguó jìngnèi shí duōge shěngfèn.","vi":"Sông Trường Giang chảy qua hơn mười tỉnh trong lãnh thổ Trung Quốc."},{"type":"compound","zh":"只要在境内消费，就可以用这张卡付款。","pinyin":"Zhǐyào zài jìngnèi xiāofèi, jiù kěyǐ yòng zhè zhāng kǎ fùkuǎn.","vi":"Chỉ cần chi tiêu trong nước là có thể thanh toán bằng thẻ này."}],"related":[{"hanzi":"境外","pinyin":"jìngwài","vi":"nước ngoài"},{"hanzi":"国内","pinyin":"guónèi","vi":"trong nước"},{"hanzi":"入境","pinyin":"rùjìng","vi":"nhập cảnh"},{"hanzi":"边境","pinyin":"biānjìng","vi":"biên giới"}],"traditional":"境內"},{"id":"境外","hanzi":"境外","pinyin":"jìngwài","meaning_vi":"ngoài lãnh thổ, nước ngoài","explanation":"境 (cảnh – biên giới) + 外 (ngoại – bên ngoài) → khu vực bên ngoài biên giới quốc gia.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"✈️","examples":[{"type":"basic","zh":"他经常去境外出差。","pinyin":"Tā jīngcháng qù jìngwài chūchāi.","vi":"Anh ấy thường đi công tác nước ngoài."},{"type":"simple","zh":"这家企业的大部分资金来自境外投资者。","pinyin":"Zhè jiā qǐyè de dàbùfen zījīn láizì jìngwài tóuzīzhě.","vi":"Phần lớn vốn của doanh nghiệp này đến từ nhà đầu tư nước ngoài."},{"type":"compound","zh":"如果你要去境外旅游，就得提前办好签证。","pinyin":"Rúguǒ nǐ yào qù jìngwài lǚyóu, jiù děi tíqián bànhǎo qiānzhèng.","vi":"Nếu bạn muốn du lịch nước ngoài thì phải làm visa trước."}],"related":[{"hanzi":"境内","pinyin":"jìngnèi","vi":"trong nước"},{"hanzi":"国外","pinyin":"guówài","vi":"nước ngoài"},{"hanzi":"出境","pinyin":"chūjìng","vi":"xuất cảnh"},{"hanzi":"海外","pinyin":"hǎiwài","vi":"hải ngoại"}]},{"id":"静止","hanzi":"静止","pinyin":"jìngzhǐ","meaning_vi":"đứng yên, bất động, tĩnh lặng","explanation":"静 (tĩnh – yên lặng) + 止 (chỉ – dừng) → dừng lại, không chuyển động.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏸️","examples":[{"type":"basic","zh":"画面突然静止了。","pinyin":"Huàmiàn tūrán jìngzhǐ le.","vi":"Hình ảnh đột nhiên đứng im."},{"type":"simple","zh":"湖面静止得像一面巨大的镜子。","pinyin":"Húmiàn jìngzhǐ de xiàng yímiàn jùdà de jìngzi.","vi":"Mặt hồ phẳng lặng như một tấm gương khổng lồ."},{"type":"compound","zh":"车辆完全静止以后，乘客才可以解开安全带。","pinyin":"Chēliàng wánquán jìngzhǐ yǐhòu, chéngkè cái kěyǐ jiěkāi ānquándài.","vi":"Sau khi xe dừng hẳn, hành khách mới được tháo dây an toàn."}],"related":[{"hanzi":"停止","pinyin":"tíngzhǐ","vi":"dừng"},{"hanzi":"运动","pinyin":"yùndòng","vi":"chuyển động"},{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"静态","pinyin":"jìngtài","vi":"trạng thái tĩnh"}],"traditional":"靜止"},{"id":"揪","hanzi":"揪","pinyin":"jiū","meaning_vi":"túm, nắm chặt, níu kéo","explanation":"揪 (thu – nắm chặt kéo) → dùng tay túm chặt rồi kéo; nghĩa bóng: 揪心 là thắt lòng, 揪出 là lôi ra.","hsk_level":"7-9","tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"他揪住了小偷。","pinyin":"Tā jiūzhùle xiǎotōu.","vi":"Anh ấy túm được tên trộm."},{"type":"simple","zh":"妈妈一把揪住孩子的耳朵把他拉回家。","pinyin":"Māma yì bǎ jiūzhù háizi de ěrduo bǎ tā lā huíjiā.","vi":"Mẹ túm tai đứa bé kéo về nhà."},{"type":"compound","zh":"一听到孩子失踪的消息，她的心就揪紧了。","pinyin":"Yì tīngdào háizi shīzōng de xiāoxi, tā de xīn jiù jiū jǐn le.","vi":"Vừa nghe tin đứa trẻ mất tích, lòng cô ấy liền thắt lại."}],"related":[{"hanzi":"抓","pinyin":"zhuā","vi":"bắt, nắm"},{"hanzi":"拽","pinyin":"zhuài","vi":"lôi, kéo"},{"hanzi":"揪心","pinyin":"jiūxīn","vi":"thắt lòng"},{"hanzi":"拉","pinyin":"lā","vi":"kéo"}]},{"id":"久违","hanzi":"久违","pinyin":"jiǔwéi","meaning_vi":"lâu không gặp, đã lâu không có","explanation":"久 (cửu – lâu) + 违 (vi – xa cách) → xa cách đã lâu; dùng khi gặp lại người quen hoặc cảm nhận lại điều lâu không có.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"久违了，老朋友！","pinyin":"Jiǔwéi le, lǎopéngyou!","vi":"Lâu quá không gặp, bạn cũ!"},{"type":"simple","zh":"今天终于见到了久违的阳光。","pinyin":"Jīntiān zhōngyú jiàndàole jiǔwéi de yángguāng.","vi":"Hôm nay cuối cùng cũng thấy ánh nắng đã lâu vắng bóng."},{"type":"compound","zh":"虽然工作很累，但是回到家乡让他找回了久违的轻松。","pinyin":"Suīrán gōngzuò hěn lèi, dànshì huídào jiāxiāng ràng tā zhǎohuíle jiǔwéi de qīngsōng.","vi":"Tuy công việc mệt nhưng về quê giúp anh tìm lại cảm giác thư thái đã lâu không có."}],"related":[{"hanzi":"好久不见","pinyin":"hǎojiǔbújiàn","vi":"lâu rồi không gặp"},{"hanzi":"久仰","pinyin":"jiǔyǎng","vi":"ngưỡng mộ đã lâu"},{"hanzi":"重逢","pinyin":"chóngféng","vi":"gặp lại"},{"hanzi":"阔别","pinyin":"kuòbié","vi":"xa cách lâu"}],"traditional":"久違"},{"id":"久仰","hanzi":"久仰","pinyin":"jiǔyǎng","meaning_vi":"ngưỡng mộ đã lâu, nghe danh đã lâu","explanation":"久 (cửu – lâu) + 仰 (ngưỡng – ngưỡng mộ) → lời xã giao lịch sự khi lần đầu gặp người có tiếng: nghe danh đã lâu.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"久仰大名，幸会幸会！","pinyin":"Jiǔyǎng dàmíng, xìnghuì xìnghuì!","vi":"Nghe danh đã lâu, hân hạnh được gặp!"},{"type":"simple","zh":"我久仰王教授在语言学方面的成就。","pinyin":"Wǒ jiǔyǎng Wáng jiàoshòu zài yǔyánxué fāngmiàn de chéngjiù.","vi":"Tôi ngưỡng mộ đã lâu thành tựu ngôn ngữ học của giáo sư Vương."},{"type":"compound","zh":"虽然久仰您的大名，但是今天才有机会当面请教。","pinyin":"Suīrán jiǔyǎng nín de dàmíng, dànshì jīntiān cái yǒujī huì dāngmiàn qǐngjiào.","vi":"Tuy nghe danh ngài đã lâu nhưng hôm nay mới có dịp trực tiếp thỉnh giáo."}],"related":[{"hanzi":"幸会","pinyin":"xìnghuì","vi":"hân hạnh được gặp"},{"hanzi":"久违","pinyin":"jiǔwéi","vi":"lâu không gặp"},{"hanzi":"仰慕","pinyin":"yǎngmù","vi":"ngưỡng mộ"},{"hanzi":"大名","pinyin":"dàmíng","vi":"đại danh"}]},{"id":"酒楼","hanzi":"酒楼","pinyin":"jiǔlóu","meaning_vi":"nhà hàng, tửu lầu","explanation":"酒 (tửu – rượu) + 楼 (lâu – tòa nhà nhiều tầng) → nhà hàng lớn bán đồ ăn và rượu, thường có nhiều tầng.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏮","examples":[{"type":"basic","zh":"这家酒楼生意很好。","pinyin":"Zhè jiā jiǔlóu shēngyi hěn hǎo.","vi":"Tửu lầu này làm ăn rất phát đạt."},{"type":"simple","zh":"我们在街口的酒楼订了两桌年夜饭。","pinyin":"Wǒmen zài jiē kǒu de jiǔlóu dìngle liǎng zhuō niányèfàn.","vi":"Chúng tôi đặt hai bàn cơm tất niên ở nhà hàng đầu phố."},{"type":"compound","zh":"因为这家酒楼的早茶很有名，所以周末总是排长队。","pinyin":"Yīnwèi zhè jiā jiǔlóu de zǎochá hěn yǒumíng, suǒyǐ zhōumò zǒngshì pái chángduì.","vi":"Vì món điểm tâm sáng của tửu lầu này rất nổi tiếng nên cuối tuần luôn xếp hàng dài."}],"related":[{"hanzi":"饭店","pinyin":"fàndiàn","vi":"nhà hàng"},{"hanzi":"餐馆","pinyin":"cānguǎn","vi":"quán ăn"},{"hanzi":"酒店","pinyin":"jiǔdiàn","vi":"khách sạn"},{"hanzi":"茶楼","pinyin":"chálóu","vi":"trà lâu"}],"traditional":"酒樓"},{"id":"救治","hanzi":"救治","pinyin":"jiùzhì","meaning_vi":"cứu chữa, cấp cứu điều trị","explanation":"救 (cứu – cứu giúp) + 治 (trị – chữa trị) → cứu chữa người bệnh, người bị thương nặng.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"伤员正在救治中。","pinyin":"Shāngyuán zhèngzài jiùzhì zhōng.","vi":"Người bị thương đang được cấp cứu."},{"type":"simple","zh":"医生们连夜救治了十几名车祸伤者。","pinyin":"Yīshēngmen liányè jiùzhìle shíjǐ míng chēhuò shāngzhě.","vi":"Các bác sĩ cấp cứu suốt đêm hơn mười nạn nhân tai nạn xe."},{"type":"compound","zh":"因为救治及时，所以老人很快脱离了危险。","pinyin":"Yīnwèi jiùzhì jíshí, suǒyǐ lǎorén hěn kuài tuōlíle wēixiǎn.","vi":"Nhờ được cứu chữa kịp thời nên cụ già nhanh chóng qua cơn nguy hiểm."}],"related":[{"hanzi":"抢救","pinyin":"qiǎngjiù","vi":"cấp cứu"},{"hanzi":"治疗","pinyin":"zhìliáo","vi":"điều trị"},{"hanzi":"救护","pinyin":"jiùhù","vi":"cứu hộ"},{"hanzi":"医治","pinyin":"yīzhì","vi":"chữa trị"}]},{"id":"就餐","hanzi":"就餐","pinyin":"jiùcān","meaning_vi":"dùng bữa, ăn cơm","explanation":"就 (tựu – đến, tới) + 餐 (xan – bữa ăn) → đến dùng bữa; cách nói trang trọng của 吃饭.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"请到二楼就餐。","pinyin":"Qǐng dào èr lóu jiùcān.","vi":"Mời lên tầng hai dùng bữa."},{"type":"simple","zh":"员工可以凭工卡在食堂免费就餐。","pinyin":"Yuángōng kěyǐ píng gōng kǎ zài shítáng miǎnfèi jiùcān.","vi":"Nhân viên có thể dùng thẻ để ăn miễn phí ở nhà ăn."},{"type":"compound","zh":"如果就餐人数超过十位，就需要提前预订包间。","pinyin":"Rúguǒ jiùcān rénshù chāoguò shíwèi, jiù xūyào tíqián yùdìng bāojiān.","vi":"Nếu số người dùng bữa hơn mười thì cần đặt phòng riêng trước."}],"related":[{"hanzi":"用餐","pinyin":"yòngcān","vi":"dùng bữa"},{"hanzi":"进餐","pinyin":"jìncān","vi":"ăn bữa"},{"hanzi":"餐厅","pinyin":"cāntīng","vi":"nhà ăn"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"ăn cơm"}]},{"id":"就地","hanzi":"就地","pinyin":"jiùdì","meaning_vi":"tại chỗ, ngay tại nơi đó","explanation":"就 (tựu – theo, dựa vào) + 地 (địa – nơi chốn) → làm ngay tại nơi đang ở, không chuyển đi đâu.","hsk_level":"7-9","tags":["pho-tu"],"image":"📍","examples":[{"type":"basic","zh":"他们就地休息。","pinyin":"Tāmen jiùdì xiūxi.","vi":"Họ nghỉ ngơi tại chỗ."},{"type":"simple","zh":"警察将这批假货就地销毁了。","pinyin":"Jǐngchá jiāng zhè pī jiǎhuò jiùdì xiāohuǐ le.","vi":"Cảnh sát tiêu hủy lô hàng giả này ngay tại chỗ."},{"type":"compound","zh":"一旦发生地震，室内人员就应该就地躲避。","pinyin":"Yídàn fāshēng dìzhèn, shìnèi rényuán jiù yīnggāi jiùdì duǒbì.","vi":"Một khi xảy ra động đất, người trong nhà nên tìm chỗ trú ngay tại chỗ."}],"related":[{"hanzi":"当场","pinyin":"dāngchǎng","vi":"tại trận"},{"hanzi":"就近","pinyin":"jiùjìn","vi":"gần nhất"},{"hanzi":"原地","pinyin":"yuándì","vi":"chỗ cũ"},{"hanzi":"现场","pinyin":"xiànchǎng","vi":"hiện trường"}]},{"id":"就任","hanzi":"就任","pinyin":"jiùrèn","meaning_vi":"nhậm chức, nhận chức","explanation":"就 (tựu – đến, nhận) + 任 (nhậm – chức vụ) → chính thức đảm nhận một chức vụ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎗️","examples":[{"type":"basic","zh":"新校长下月就任。","pinyin":"Xīn xiàozhǎng xiàyuè jiùrèn.","vi":"Hiệu trưởng mới nhậm chức vào tháng sau."},{"type":"simple","zh":"他就任总经理以后推出了一系列改革。","pinyin":"Tā jiùrèn zǒngjīnglǐ yǐhòu tuīchūle yíxìliè gǎigé.","vi":"Sau khi nhậm chức tổng giám đốc, ông ấy đưa ra loạt cải cách."},{"type":"compound","zh":"虽然刚就任不久，但是她已经赢得了员工的信任。","pinyin":"Suīrán gāng jiùrèn bùjiǔ, dànshì tā yǐjīng yíng déle yuángōng de xìnrèn.","vi":"Tuy mới nhậm chức chưa lâu nhưng bà đã giành được lòng tin của nhân viên."}],"related":[{"hanzi":"上任","pinyin":"shàngrèn","vi":"lên nhậm chức"},{"hanzi":"就职","pinyin":"jiùzhí","vi":"nhậm chức"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"rời chức"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"}]},{"id":"就诊","hanzi":"就诊","pinyin":"jiùzhěn","meaning_vi":"đi khám bệnh","explanation":"就 (tựu – đến) + 诊 (chẩn – khám bệnh) → đến bệnh viện, phòng khám để được bác sĩ khám.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"请带好证件就诊。","pinyin":"Qǐng dài hǎo zhèngjiàn jiùzhěn.","vi":"Vui lòng mang theo giấy tờ khi đi khám."},{"type":"simple","zh":"他发烧三天了才去医院就诊。","pinyin":"Tā fāshāo sān tiānle cái qù yīyuàn jiùzhěn.","vi":"Anh ấy sốt ba ngày rồi mới đến bệnh viện khám."},{"type":"compound","zh":"如果症状持续加重，就应该立即就诊。","pinyin":"Rúguǒ zhèngzhuàng chíxù jiāzhòng, jiù yīnggāi lìjí jiùzhěn.","vi":"Nếu triệu chứng tiếp tục nặng thêm thì nên đi khám ngay."}],"related":[{"hanzi":"看病","pinyin":"kànbìng","vi":"khám bệnh"},{"hanzi":"门诊","pinyin":"ménzhěn","vi":"khám ngoại trú"},{"hanzi":"挂号","pinyin":"guàhào","vi":"lấy số khám"},{"hanzi":"复诊","pinyin":"fùzhěn","vi":"tái khám"}],"traditional":"就診"},{"id":"就座","hanzi":"就座","pinyin":"jiùzuò","meaning_vi":"ngồi vào chỗ, an tọa","explanation":"就 (tựu – đến) + 座 (tọa – chỗ ngồi) → ngồi vào chỗ đã định; cách nói trang trọng.","hsk_level":"7-9","tags":["dong-tu"],"image":"💺","examples":[{"type":"basic","zh":"请各位来宾就座。","pinyin":"Qǐng gèwèi láibīn jiùzuò.","vi":"Xin mời quý khách ngồi vào chỗ."},{"type":"simple","zh":"嘉宾们按照座位卡依次就座。","pinyin":"Jiābīnmen ànzhào zuòwèi kǎ yīcì jiùzuò.","vi":"Các khách mời lần lượt ngồi theo thẻ tên."},{"type":"compound","zh":"等所有观众就座以后，演出才正式开始。","pinyin":"Děng suǒyǒu guānzhòng jiùzuò yǐhòu, yǎnchū cái zhèngshì kāishǐ.","vi":"Đợi mọi khán giả ngồi vào chỗ rồi buổi diễn mới chính thức bắt đầu."}],"related":[{"hanzi":"入座","pinyin":"rùzuò","vi":"vào chỗ"},{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"},{"hanzi":"落座","pinyin":"luòzuò","vi":"ngồi xuống"},{"hanzi":"离席","pinyin":"líxí","vi":"rời chỗ"}]},{"id":"菊花","hanzi":"菊花","pinyin":"júhuā","meaning_vi":"hoa cúc","explanation":"菊 (cúc – cây cúc) + 花 (hoa) → hoa cúc, loài hoa của mùa thu; 菊花茶 là trà hoa cúc.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌼","examples":[{"type":"basic","zh":"秋天菊花开了。","pinyin":"Qiūtiān júhuā kāi le.","vi":"Mùa thu hoa cúc nở rồi."},{"type":"simple","zh":"奶奶每天都会泡一杯菊花茶。","pinyin":"Nǎinai měitiān dōuhuì pào yì bēi júhuāchá.","vi":"Ngày nào bà cũng pha một tách trà hoa cúc."},{"type":"compound","zh":"因为菊花能清热降火，所以夏天很多人用它泡茶。","pinyin":"Yīnwèi júhuā néng qīngrè jiànghuǒ, suǒyǐ xiàtiān hěn duō rén yòng tā pàochá.","vi":"Vì hoa cúc giúp thanh nhiệt nên mùa hè nhiều người dùng để pha trà."}],"related":[{"hanzi":"菊花茶","pinyin":"júhuāchá","vi":"trà hoa cúc"},{"hanzi":"梅花","pinyin":"méihuā","vi":"hoa mai"},{"hanzi":"兰花","pinyin":"lánhuā","vi":"hoa lan"},{"hanzi":"花瓣","pinyin":"huābàn","vi":"cánh hoa"}]},{"id":"橘子","hanzi":"橘子","pinyin":"júzi","meaning_vi":"quả quýt","explanation":"橘 (quất – cây quýt) + 子 (tử – hậu tố danh từ) → quả quýt.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍊","examples":[{"type":"basic","zh":"这个橘子很甜。","pinyin":"Zhè ge júzi hěn tián.","vi":"Quả quýt này rất ngọt."},{"type":"simple","zh":"她剥了一个橘子分给弟弟吃。","pinyin":"Tā bāole yí ge júzi fēngěi dìdi chī.","vi":"Cô ấy bóc một quả quýt chia cho em trai ăn."},{"type":"compound","zh":"橘子虽然好吃，但是一次吃太多容易上火。","pinyin":"Júzi suīrán hǎochī, dànshì yí cì chī tài duō róngyì shànghuǒ.","vi":"Quýt tuy ngon nhưng ăn nhiều một lúc dễ bị nóng trong."}],"related":[{"hanzi":"橙子","pinyin":"chéngzi","vi":"quả cam"},{"hanzi":"柚子","pinyin":"yòuzi","vi":"quả bưởi"},{"hanzi":"橘子汁","pinyin":"júzizhī","vi":"nước quýt"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"trái cây"}]},{"id":"举报","hanzi":"举报","pinyin":"jǔbào","meaning_vi":"tố giác, báo cáo vi phạm","explanation":"举 (cử – nêu ra) + 报 (báo – báo cáo) → báo cho cơ quan chức năng biết hành vi sai phạm của người khác.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📢","examples":[{"type":"basic","zh":"有人举报了他。","pinyin":"Yǒurén jǔbàole tā.","vi":"Có người đã tố giác hắn."},{"type":"simple","zh":"市民可以拨打热线举报违法行为。","pinyin":"Shìmín kěyǐ bōdǎ rèxiàn jǔbào wéifǎ xíngwéi.","vi":"Người dân có thể gọi đường dây nóng để tố giác hành vi phạm pháp."},{"type":"compound","zh":"如果发现食品安全问题，就请及时向有关部门举报。","pinyin":"Rúguǒ fāxiàn shípǐn ānquán wèntí, jiù qǐng jíshí xiàng yǒuguān bùmén jǔbào.","vi":"Nếu phát hiện vấn đề an toàn thực phẩm, hãy kịp thời báo với cơ quan liên quan."}],"related":[{"hanzi":"揭发","pinyin":"jiēfā","vi":"vạch trần"},{"hanzi":"检举","pinyin":"jiǎnjǔ","vi":"tố giác"},{"hanzi":"告发","pinyin":"gàofā","vi":"tố cáo"},{"hanzi":"投诉","pinyin":"tóusù","vi":"khiếu nại"}],"traditional":"舉報"},{"id":"举措","hanzi":"举措","pinyin":"jǔcuò","meaning_vi":"biện pháp, động thái, hành động","explanation":"举 (cử – hành động) + 措 (thố – sắp đặt, biện pháp) → biện pháp được đưa ra để giải quyết vấn đề; văn viết.","hsk_level":"7-9","tags":["danh-tu"],"image":"📋","examples":[{"type":"basic","zh":"这是一项新举措。","pinyin":"Zhè shì yí xiàng xīn jǔcuò.","vi":"Đây là một biện pháp mới."},{"type":"simple","zh":"政府出台了多项鼓励生育的举措。","pinyin":"Zhèngfǔ chūtáile duōxiàng gǔlì shēngyù de jǔcuò.","vi":"Chính phủ ban hành nhiều biện pháp khuyến khích sinh con."},{"type":"compound","zh":"这些环保举措虽然成本很高，但是长期来看非常值得。","pinyin":"Zhèxiē huánbǎo jǔcuò suīrán chéngběn hěn gāo, dànshì chángqī lái kàn fēicháng zhíde.","vi":"Các biện pháp bảo vệ môi trường này tuy tốn kém nhưng về lâu dài rất đáng."}],"related":[{"hanzi":"措施","pinyin":"cuòshī","vi":"biện pháp"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách làm"},{"hanzi":"行动","pinyin":"xíngdòng","vi":"hành động"},{"hanzi":"政策","pinyin":"zhèngcè","vi":"chính sách"}],"traditional":"舉措"},{"id":"举例","hanzi":"举例","pinyin":"jǔlì","meaning_vi":"nêu ví dụ, lấy ví dụ","explanation":"举 (cử – nêu lên) + 例 (lệ – ví dụ) → đưa ra ví dụ để minh họa; hay dùng 举例来说, 举个例子.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"💡","examples":[{"type":"basic","zh":"请你举例说明。","pinyin":"Qǐng nǐ jǔlì shuōmíng.","vi":"Mời bạn nêu ví dụ minh họa."},{"type":"simple","zh":"老师举例讲解了这个语法的用法。","pinyin":"Lǎoshī jǔlì jiǎngjiěle zhè ge yǔfǎ de yòngfǎ.","vi":"Thầy giáo lấy ví dụ giảng giải cách dùng ngữ pháp này."},{"type":"compound","zh":"如果光讲道理太抽象，就不如多举例让大家理解。","pinyin":"Rúguǒ guāng jiǎngdàolǐ tài chōuxiàng, jiù bùrú duō jǔlì ràng dàjiā lǐjiě.","vi":"Nếu chỉ nói lý thuyết thì quá trừu tượng, chi bằng nêu nhiều ví dụ cho mọi người hiểu."}],"related":[{"hanzi":"例子","pinyin":"lìzi","vi":"ví dụ"},{"hanzi":"比如","pinyin":"bǐrú","vi":"ví như"},{"hanzi":"例如","pinyin":"lìrú","vi":"chẳng hạn"},{"hanzi":"说明","pinyin":"shuōmíng","vi":"giải thích"}],"traditional":"舉例"},{"id":"举世无双","hanzi":"举世无双","pinyin":"jǔshì-wúshuāng","meaning_vi":"độc nhất vô nhị, có một không hai","explanation":"举 (cử – cả, toàn) + 世 (thế – thế gian) + 无 (vô – không) + 双 (song – đôi) → khắp thế gian không có cái thứ hai; ý nói độc nhất, không gì sánh bằng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"这件国宝举世无双。","pinyin":"Zhè jiàn guóbǎo jǔshìwúshuāng.","vi":"Báu vật quốc gia này có một không hai."},{"type":"simple","zh":"这座古城的建筑艺术堪称举世无双。","pinyin":"Zhè zuò gǔchéng de jiànzhù yìshù kānchēng jǔshìwúshuāng.","vi":"Nghệ thuật kiến trúc của cổ thành này có thể nói là độc nhất vô nhị."},{"type":"compound","zh":"虽然他的技艺举世无双，但是他为人非常谦虚。","pinyin":"Suīrán tā de jìyì jǔshìwúshuāng, dànshì tā wéirén fēicháng qiānxū.","vi":"Tuy tài nghệ của ông không ai sánh bằng nhưng ông sống rất khiêm tốn."}],"related":[{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"无与伦比","pinyin":"wúyǔlúnbǐ","vi":"không gì sánh bằng"},{"hanzi":"举世闻名","pinyin":"jǔshìwénmíng","vi":"nổi tiếng khắp thế giới"},{"hanzi":"绝无仅有","pinyin":"juéwújǐnyǒu","vi":"cực kỳ hiếm có"}],"traditional":"舉世無雙"},{"id":"举止","hanzi":"举止","pinyin":"jǔzhǐ","meaning_vi":"cử chỉ, phong thái, cách cư xử","explanation":"举 (cử – cử động) + 止 (chỉ – dừng, dáng điệu) → cử chỉ, điệu bộ và cách đối xử với người khác.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🕴️","examples":[{"type":"basic","zh":"她举止很优雅。","pinyin":"Tā jǔzhǐ hěn yōuyǎ.","vi":"Cử chỉ của cô ấy rất tao nhã."},{"type":"simple","zh":"他得体的举止给面试官留下了好印象。","pinyin":"Tā détǐ de jǔzhǐ gěi miànshìguān liúxiàle hǎo yìnxiàng.","vi":"Cách cư xử đúng mực của anh để lại ấn tượng tốt cho người phỏng vấn."},{"type":"compound","zh":"因为那个人举止可疑，所以保安一直盯着他。","pinyin":"Yīnwèi nàgerén jǔzhǐ kěyí, suǒyǐ bǎo'ān yìzhí dīngzhe tā.","vi":"Vì người đó có cử chỉ đáng ngờ nên bảo vệ cứ theo dõi anh ta."}],"related":[{"hanzi":"言行","pinyin":"yánxíng","vi":"lời nói và việc làm"},{"hanzi":"举动","pinyin":"jǔdòng","vi":"hành động"},{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"谈吐","pinyin":"tántǔ","vi":"cách ăn nói"}],"traditional":"舉止"},{"id":"举重","hanzi":"举重","pinyin":"jǔzhòng","meaning_vi":"cử tạ, nâng tạ","explanation":"举 (cử – nâng lên) + 重 (trọng – vật nặng) → nâng vật nặng; môn thể thao cử tạ.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"他是举重冠军。","pinyin":"Tā shì jǔzhòng guànjūn.","vi":"Anh ấy là nhà vô địch cử tạ."},{"type":"simple","zh":"她每周去健身房练三次举重。","pinyin":"Tā měizhōu qù jiànshēnfáng liàn sāncì jǔzhòng.","vi":"Cô ấy đến phòng tập tập tạ ba lần mỗi tuần."},{"type":"compound","zh":"如果举重前不热身，就很容易拉伤腰部。","pinyin":"Rúguǒ jǔzhòng qián bú rèshēn, jiù hěn róngyì lāshāng yāobù.","vi":"Nếu không khởi động trước khi nâng tạ thì rất dễ bị căng cơ lưng."}],"related":[{"hanzi":"杠铃","pinyin":"gànglíng","vi":"tạ đòn"},{"hanzi":"哑铃","pinyin":"yǎlíng","vi":"tạ tay"},{"hanzi":"健身","pinyin":"jiànshēn","vi":"tập thể hình"},{"hanzi":"举起","pinyin":"jǔqǐ","vi":"nâng lên"}],"traditional":"舉重"},{"id":"巨额","hanzi":"巨额","pinyin":"jù'é","meaning_vi":"(số tiền) khổng lồ, cực lớn","explanation":"巨 (cự – to lớn) + 额 (ngạch – định mức, số tiền) → số tiền hoặc số lượng rất lớn; thường làm định ngữ: 巨额资金, 巨额债务.","hsk_level":"7-9","tags":["tinh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"公司欠下巨额债务。","pinyin":"Gōngsī qiàn xià jù'é zhàiwù.","vi":"Công ty mắc khoản nợ khổng lồ."},{"type":"simple","zh":"这位富商向灾区捐出了一笔巨额善款。","pinyin":"Zhè wèi fùshāng xiàng zāiqū juān chūle yì bǐ jù'é shànkuǎn.","vi":"Vị thương gia giàu có quyên góp khoản tiền từ thiện khổng lồ cho vùng thiên tai."},{"type":"compound","zh":"即使获得巨额投资，这个项目也不一定能成功。","pinyin":"Jíshǐ huòdé jù'é tóuzī, zhè ge xiàngmù yě bù yídìng néng chénggōng.","vi":"Dù nhận được khoản đầu tư khổng lồ, dự án này cũng chưa chắc thành công."}],"related":[{"hanzi":"巨大","pinyin":"jùdà","vi":"to lớn"},{"hanzi":"金额","pinyin":"jīn'é","vi":"số tiền"},{"hanzi":"巨款","pinyin":"jùkuǎn","vi":"món tiền lớn"},{"hanzi":"数额","pinyin":"shù'é","vi":"số lượng"}],"traditional":"巨額"},{"id":"巨人","hanzi":"巨人","pinyin":"jùrén","meaning_vi":"người khổng lồ","explanation":"巨 (cự – to lớn) + 人 (nhân – người) → người to lớn khác thường; nghĩa bóng chỉ người có tầm ảnh hưởng lớn.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🗿","examples":[{"type":"basic","zh":"他像个巨人一样。","pinyin":"Tā xiàng ge jùrén yíyàng.","vi":"Anh ta như một người khổng lồ."},{"type":"simple","zh":"牛顿说他是站在巨人的肩膀上。","pinyin":"Niúdùn shuō tā shì zhàn zài jùrén de jiānbǎng shàng.","vi":"Newton nói ông đứng trên vai những người khổng lồ."},{"type":"compound","zh":"虽然他在思想上是巨人，但是在生活上却像个孩子。","pinyin":"Suīrán tā zài sīxiǎng shàng shì jùrén, dànshì zài shēnghuó shàng què xiàng ge háizi.","vi":"Tuy về tư tưởng ông là người khổng lồ nhưng trong đời sống lại như đứa trẻ."}],"related":[{"hanzi":"巨头","pinyin":"jùtóu","vi":"ông trùm"},{"hanzi":"伟人","pinyin":"wěirén","vi":"vĩ nhân"},{"hanzi":"矮人","pinyin":"ǎirén","vi":"người lùn"},{"hanzi":"巨大","pinyin":"jùdà","vi":"to lớn"}]},{"id":"巨头","hanzi":"巨头","pinyin":"jùtóu","meaning_vi":"ông trùm, đại gia, gã khổng lồ (trong ngành)","explanation":"巨 (cự – to lớn) + 头 (đầu – người đứng đầu) → nhân vật hoặc công ty có thế lực lớn nhất trong một lĩnh vực.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🦈","examples":[{"type":"basic","zh":"他是地产巨头。","pinyin":"Tā shì dìchǎn jùtóu.","vi":"Ông ấy là trùm bất động sản."},{"type":"simple","zh":"几家科技巨头正在争夺人工智能市场。","pinyin":"Jǐ jiā kējì jùtóu zhèngzài zhēngduó réngōngzhìnéng shìchǎng.","vi":"Mấy gã khổng lồ công nghệ đang tranh giành thị trường trí tuệ nhân tạo."},{"type":"compound","zh":"即使是行业巨头，如果不创新也会被淘汰。","pinyin":"Jíshǐ shì hángyè jùtóu, rúguǒ bú chuàngxīn yě huì bèi táotài.","vi":"Dù là ông lớn trong ngành, nếu không đổi mới cũng sẽ bị đào thải."}],"related":[{"hanzi":"大亨","pinyin":"dàhēng","vi":"đại gia"},{"hanzi":"寡头","pinyin":"guǎtóu","vi":"đầu sỏ"},{"hanzi":"龙头","pinyin":"lóngtóu","vi":"đầu tàu"},{"hanzi":"巨人","pinyin":"jùrén","vi":"người khổng lồ"}],"traditional":"巨頭"},{"id":"巨星","hanzi":"巨星","pinyin":"jùxīng","meaning_vi":"siêu sao, ngôi sao lớn","explanation":"巨 (cự – to lớn) + 星 (tinh – ngôi sao) → sao khổng lồ trong thiên văn; nghĩa bóng chỉ siêu sao giải trí, thể thao.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🌟","examples":[{"type":"basic","zh":"她是国际巨星。","pinyin":"Tā shì Guójì jùxīng.","vi":"Cô ấy là siêu sao quốc tế."},{"type":"simple","zh":"这位篮球巨星退役后开了一所学校。","pinyin":"Zhè wèi lánqiú jùxīng tuìyì hòu kāile yì suǒ xuéxiào.","vi":"Siêu sao bóng rổ này sau khi giải nghệ đã mở một trường học."},{"type":"compound","zh":"虽然他已经是巨星了，但是对待粉丝仍然很亲切。","pinyin":"Suīrán tā yǐjīng shì jùxīng le, dànshì duìdài fěnsī réngrán hěn qīnqiè.","vi":"Tuy đã là siêu sao nhưng anh vẫn rất thân thiện với người hâm mộ."}],"related":[{"hanzi":"明星","pinyin":"míngxīng","vi":"ngôi sao"},{"hanzi":"歌星","pinyin":"gēxīng","vi":"ca sĩ nổi tiếng"},{"hanzi":"偶像","pinyin":"ǒuxiàng","vi":"thần tượng"},{"hanzi":"球星","pinyin":"qiúxīng","vi":"ngôi sao bóng đá"}]},{"id":"巨型","hanzi":"巨型","pinyin":"jùxíng","meaning_vi":"cỡ lớn, khổng lồ, siêu lớn","explanation":"巨 (cự – to lớn) + 型 (hình – kiểu, cỡ) → loại có kích thước cực lớn; thường làm định ngữ: 巨型油轮, 巨型计算机.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚢","examples":[{"type":"basic","zh":"港口停着巨型油轮。","pinyin":"Gǎngkǒu tíngzhe jùxíng yóulún.","vi":"Ở cảng đang neo một tàu chở dầu khổng lồ."},{"type":"simple","zh":"广场上竖起了一块巨型广告屏。","pinyin":"Guǎngchǎng shàng shùqǐle yíkuài jùxíng guǎnggào píng.","vi":"Trên quảng trường dựng một màn hình quảng cáo khổng lồ."},{"type":"compound","zh":"因为这台巨型机器太重，所以只能用吊车搬运。","pinyin":"Yīnwèi zhè tái jùxíng jīqì tài zhòng, suǒyǐ zhǐnéng yòng diàochē bānyùn.","vi":"Vì cỗ máy khổng lồ này quá nặng nên chỉ có thể dùng cần cẩu vận chuyển."}],"related":[{"hanzi":"大型","pinyin":"dàxíng","vi":"cỡ lớn"},{"hanzi":"小型","pinyin":"xiǎoxíng","vi":"cỡ nhỏ"},{"hanzi":"微型","pinyin":"wēixíng","vi":"siêu nhỏ"},{"hanzi":"巨大","pinyin":"jùdà","vi":"to lớn"}]},{"id":"剧目","hanzi":"剧目","pinyin":"jùmù","meaning_vi":"vở diễn, tiết mục kịch, danh mục vở diễn","explanation":"剧 (kịch – vở kịch) + 目 (mục – danh mục) → các vở kịch, vở diễn trong chương trình biểu diễn.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"今晚上演新剧目。","pinyin":"Jīnwǎn shàngyǎn xīn jùmù.","vi":"Tối nay công diễn vở mới."},{"type":"simple","zh":"这家剧院每个月都会更换演出剧目。","pinyin":"Zhè jiā jùyuàn měi geyuè dōuhuì gēng huàn yǎnchū jùmù.","vi":"Nhà hát này tháng nào cũng thay đổi vở diễn."},{"type":"compound","zh":"虽然这些都是传统剧目，但是导演加入了很多新元素。","pinyin":"Suīrán zhèxiē dōu shì chuántǒng jùmù, dànshì dǎoyǎn jiārùle hěn duō xīn yuánsù.","vi":"Tuy đều là vở truyền thống nhưng đạo diễn đã thêm nhiều yếu tố mới."}],"related":[{"hanzi":"节目","pinyin":"jiémù","vi":"tiết mục"},{"hanzi":"剧本","pinyin":"jùběn","vi":"kịch bản"},{"hanzi":"剧院","pinyin":"jùyuàn","vi":"nhà hát"},{"hanzi":"戏剧","pinyin":"xìjù","vi":"kịch"}],"traditional":"劇目"},{"id":"剧情","hanzi":"剧情","pinyin":"jùqíng","meaning_vi":"cốt truyện, tình tiết (phim, kịch)","explanation":"剧 (kịch – vở kịch, phim) + 情 (tình – tình tiết) → diễn biến câu chuyện trong phim, kịch.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"这部剧剧情紧凑。","pinyin":"Zhè bù jù jùqíng jǐncòu.","vi":"Bộ phim này cốt truyện chặt chẽ."},{"type":"simple","zh":"观众都猜不到这部电影的剧情走向。","pinyin":"Guānzhòng dōu cāi búdào zhè bù diànyǐng de jùqíng zǒuxiàng.","vi":"Khán giả đều không đoán được diễn biến cốt truyện của bộ phim này."},{"type":"compound","zh":"虽然演员阵容很强大，但是剧情实在太老套了。","pinyin":"Suīrán yǎnyuán zhènróng hěn qiángdà, dànshì jùqíng shízài tài lǎotào le.","vi":"Tuy dàn diễn viên rất hùng hậu nhưng cốt truyện thật sự quá cũ."}],"related":[{"hanzi":"情节","pinyin":"qíngjié","vi":"tình tiết"},{"hanzi":"剧本","pinyin":"jùběn","vi":"kịch bản"},{"hanzi":"剧透","pinyin":"jùtòu","vi":"tiết lộ nội dung phim"},{"hanzi":"故事","pinyin":"gùshi","vi":"câu chuyện"}],"traditional":"劇情"},{"id":"剧团","hanzi":"剧团","pinyin":"jùtuán","meaning_vi":"đoàn kịch, đoàn nghệ thuật","explanation":"剧 (kịch – kịch) + 团 (đoàn – đoàn thể) → tập thể biểu diễn kịch, tuồng, ca kịch.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎪","examples":[{"type":"basic","zh":"他加入了京剧团。","pinyin":"Tā jiārùle jīng jùtuán.","vi":"Anh ấy gia nhập đoàn Kinh kịch."},{"type":"simple","zh":"这个剧团每年都会到乡村巡回演出。","pinyin":"Zhè ge jùtuán měinián dōuhuì dào xiāngcūn xúnhuí yǎnchū.","vi":"Đoàn kịch này năm nào cũng lưu diễn ở nông thôn."},{"type":"compound","zh":"由于观众越来越少，所以这个老剧团差点儿解散。","pinyin":"Yóuyú guānzhòng yuèláiyuè shǎo, suǒyǐ zhè ge lǎo jùtuán chàdiǎnr jiěsàn.","vi":"Do khán giả ngày càng ít nên đoàn kịch lâu năm này suýt giải tán."}],"related":[{"hanzi":"剧组","pinyin":"jùzǔ","vi":"đoàn làm phim"},{"hanzi":"乐团","pinyin":"yuètuán","vi":"dàn nhạc"},{"hanzi":"剧院","pinyin":"jùyuàn","vi":"nhà hát"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"}],"traditional":"劇團"},{"id":"剧院","hanzi":"剧院","pinyin":"jùyuàn","meaning_vi":"nhà hát, rạp hát","explanation":"剧 (kịch – kịch) + 院 (viện – nơi, tòa nhà) → công trình dùng để biểu diễn kịch, ca nhạc.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏛️","examples":[{"type":"basic","zh":"我们去剧院看戏。","pinyin":"Wǒmen qù jùyuàn kànxì.","vi":"Chúng tôi đến nhà hát xem kịch."},{"type":"simple","zh":"这座大剧院是市中心的地标建筑。","pinyin":"Zhè zuò dà jùyuàn shì shìzhōngxīn de dìbiāo jiànzhù.","vi":"Nhà hát lớn này là công trình biểu tượng của trung tâm thành phố."},{"type":"compound","zh":"如果演出开始后才到剧院，就只能等中场休息再入场。","pinyin":"Rúguǒ yǎnchū kāishǐ hòu cái dào jùyuàn, jiù zhǐnéng děng zhōngchǎng xiūxi zài rùchǎng.","vi":"Nếu tới nhà hát sau khi buổi diễn bắt đầu thì phải đợi giờ giải lao mới được vào."}],"related":[{"hanzi":"电影院","pinyin":"diànyǐngyuàn","vi":"rạp chiếu phim"},{"hanzi":"剧场","pinyin":"jùchǎng","vi":"rạp hát"},{"hanzi":"歌剧院","pinyin":"gējùyuàn","vi":"nhà hát opera"},{"hanzi":"舞台","pinyin":"wǔtái","vi":"sân khấu"}],"traditional":"劇院"},{"id":"剧组","hanzi":"剧组","pinyin":"jùzǔ","meaning_vi":"đoàn làm phim, ê-kíp sản xuất","explanation":"剧 (kịch – phim, kịch) + 组 (tổ – nhóm) → toàn bộ diễn viên và nhân viên sản xuất của một bộ phim, vở kịch.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎥","examples":[{"type":"basic","zh":"剧组正在拍夜戏。","pinyin":"Jùzǔ zhèngzài pāi yè xì.","vi":"Đoàn phim đang quay cảnh đêm."},{"type":"simple","zh":"剧组在沙漠里拍了整整两个月。","pinyin":"Jùzǔ zài shāmò lǐ pāile zhěngzhěng liǎng geyuè.","vi":"Đoàn phim quay ở sa mạc suốt hai tháng."},{"type":"compound","zh":"因为主演突然生病，所以整个剧组不得不停工。","pinyin":"Yīnwèi zhǔyǎn tūrán shēngbìng, suǒyǐ zhěngge jùzǔ bùdébù tínggōng.","vi":"Vì diễn viên chính đột nhiên ốm nên cả đoàn phim buộc phải ngừng quay."}],"related":[{"hanzi":"剧团","pinyin":"jùtuán","vi":"đoàn kịch"},{"hanzi":"导演","pinyin":"dǎoyǎn","vi":"đạo diễn"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"拍摄","pinyin":"pāishè","vi":"quay phim"}],"traditional":"劇組"},{"id":"据此","hanzi":"据此","pinyin":"jùcǐ","meaning_vi":"căn cứ vào đó, theo đó","explanation":"据 (cứ – căn cứ) + 此 (thử – này, đó) → dựa vào điều vừa nói để suy ra hoặc hành động; văn viết trang trọng.","hsk_level":"7-9","tags":["pho-tu"],"image":"📑","examples":[{"type":"basic","zh":"据此可以得出结论。","pinyin":"Jùcǐ kěyǐ déchū jiélùn.","vi":"Căn cứ vào đó có thể rút ra kết luận."},{"type":"simple","zh":"公司据此调整了明年的销售计划。","pinyin":"Gōngsī jùcǐ tiáozhěngle míngnián de xiāoshòu jìhuà.","vi":"Công ty căn cứ vào đó điều chỉnh kế hoạch bán hàng năm sau."},{"type":"compound","zh":"既然调查结果已经出来了，我们就应该据此做出决定。","pinyin":"Jìrán diàochá jiéguǒ yǐjīng chūlái le, wǒmen jiù yīnggāi jùcǐ zuòchū juédìng.","vi":"Kết quả điều tra đã có thì chúng ta nên căn cứ vào đó mà quyết định."}],"related":[{"hanzi":"根据","pinyin":"gēnjù","vi":"căn cứ"},{"hanzi":"依据","pinyin":"yījù","vi":"dựa theo"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"vì vậy"},{"hanzi":"由此","pinyin":"yóucǐ","vi":"từ đó"}],"traditional":"據此"},{"id":"距","hanzi":"距","pinyin":"jù","meaning_vi":"cách (bao xa); khoảng cách","explanation":"距 (cự – cự ly, khoảng cách) → cách xa bao nhiêu về không gian hoặc thời gian; văn viết, như 距离, 相距.","hsk_level":"7-9","tags":["gioi-tu"],"image":"📏","examples":[{"type":"basic","zh":"学校距车站不远。","pinyin":"Xuéxiào jù chēzhàn bù yuǎn.","vi":"Trường học cách nhà ga không xa."},{"type":"simple","zh":"距期末考试只剩下三天了。","pinyin":"Jù qīmò kǎoshì zhǐ shèngxià sān tiān le.","vi":"Chỉ còn ba ngày nữa là đến kỳ thi cuối kỳ."},{"type":"compound","zh":"虽然这里距市中心有二十公里，但是交通很方便。","pinyin":"Suīrán zhèlǐ jù shìzhōngxīn yǒu èrshí gōnglǐ, dànshì jiāotōng hěn fāngbiàn.","vi":"Tuy nơi đây cách trung tâm hai mươi cây số nhưng giao thông rất thuận tiện."}],"related":[{"hanzi":"距离","pinyin":"jùlí","vi":"khoảng cách"},{"hanzi":"差距","pinyin":"chājù","vi":"chênh lệch"},{"hanzi":"相距","pinyin":"xiāngjù","vi":"cách nhau"},{"hanzi":"间距","pinyin":"jiānjù","vi":"khoảng cách giữa"}]},{"id":"锯","hanzi":"锯","pinyin":"jù","meaning_vi":"cưa (gỗ, kim loại); cái cưa","explanation":"锯 (cứ – cái cưa) → dụng cụ có lưỡi răng để cắt gỗ, kim loại; làm động từ nghĩa là cưa.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"🪚","examples":[{"type":"basic","zh":"他把木头锯断了。","pinyin":"Tā bǎ mùtou jù duàn le.","vi":"Anh ấy cưa đứt khúc gỗ."},{"type":"simple","zh":"爷爷用锯把旧桌子锯成了几块。","pinyin":"Yéye yòng jù bǎ jiù zhuōzi jù chéngle jǐ kuài.","vi":"Ông nội dùng cưa cưa chiếc bàn cũ thành mấy mảnh."},{"type":"compound","zh":"如果树枝挡住了窗户，就把它锯掉吧。","pinyin":"Rúguǒ shùzhī dǎngzhùle chuānghu, jiù bǎ tā jùdiào ba.","vi":"Nếu cành cây che mất cửa sổ thì cưa nó đi."}],"related":[{"hanzi":"锯子","pinyin":"jùzi","vi":"cái cưa"},{"hanzi":"电锯","pinyin":"diànjù","vi":"cưa máy"},{"hanzi":"砍","pinyin":"kǎn","vi":"chặt"},{"hanzi":"斧头","pinyin":"fǔtóu","vi":"cái rìu"}],"traditional":"鋸"},{"id":"聚集","hanzi":"聚集","pinyin":"jùjí","meaning_vi":"tụ tập, tập trung, hội tụ","explanation":"聚 (tụ – họp lại) + 集 (tập – tập hợp) → nhiều người hoặc vật tập trung lại một chỗ.","hsk_level":"7-9","tags":["dong-tu"],"image":"👥","examples":[{"type":"basic","zh":"门口聚集了很多人。","pinyin":"Ménkǒu jùjíle hěn duō rén.","vi":"Trước cửa tụ tập rất đông người."},{"type":"simple","zh":"广场上聚集着等待看烟花的市民。","pinyin":"Guǎngchǎng shàng jùjízhe děngdài kàn yānhuā de shìmín.","vi":"Trên quảng trường tụ tập đông đảo người dân chờ xem pháo hoa."},{"type":"compound","zh":"因为这里交通便利，所以大量高科技企业聚集在此。","pinyin":"Yīnwèi zhèlǐ jiāotōng biànlì, suǒyǐ dàliàng gāokējì qǐyè jùjí zài cǐ.","vi":"Vì giao thông thuận tiện nên rất nhiều doanh nghiệp công nghệ cao tập trung ở đây."}],"related":[{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi họp mặt"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"},{"hanzi":"分散","pinyin":"fēnsàn","vi":"phân tán"},{"hanzi":"汇集","pinyin":"huìjí","vi":"hội tụ"}]},{"id":"卷子","hanzi":"卷子","pinyin":"juànzi","meaning_vi":"bài thi, giấy thi","explanation":"卷 (quyển – tờ giấy, bài thi) + 子 (tử – hậu tố danh từ) → tờ bài thi, bài kiểm tra; khi đọc juǎn zi còn chỉ món bánh cuộn hấp.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"老师在批改卷子。","pinyin":"Lǎoshī zài pīgǎi juànzi.","vi":"Thầy giáo đang chấm bài thi."},{"type":"simple","zh":"考试结束铃一响，学生们就交了卷子。","pinyin":"Kǎoshì jiéshù líng yì xiǎng, xuéshengmen jiù jiāole juànzi.","vi":"Chuông hết giờ vừa reo, học sinh liền nộp bài thi."},{"type":"compound","zh":"如果写完卷子还有时间，就要认真检查一遍。","pinyin":"Rúguǒ xiěwán juànzi háiyǒu shíjiān, jiùyào rènzhēn jiǎnchá yíbiàn.","vi":"Nếu làm xong bài thi mà vẫn còn thời gian thì phải kiểm tra lại cẩn thận."}],"related":[{"hanzi":"试卷","pinyin":"shìjuàn","vi":"đề thi"},{"hanzi":"考卷","pinyin":"kǎojuàn","vi":"bài thi"},{"hanzi":"答卷","pinyin":"dájuàn","vi":"bài làm"},{"hanzi":"交卷","pinyin":"jiāojuàn","vi":"nộp bài"}]},{"id":"决议","hanzi":"决议","pinyin":"juéyì","meaning_vi":"nghị quyết; thông qua nghị quyết","explanation":"决 (quyết – quyết định) + 议 (nghị – bàn bạc) → quyết định được hội nghị bàn bạc và thông qua.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"会议通过了决议。","pinyin":"Huìyì tōngguòle juéyì.","vi":"Hội nghị đã thông qua nghị quyết."},{"type":"simple","zh":"董事会作出了关闭这家工厂的决议。","pinyin":"Dǒngshìhuì zuòchūle guānbì zhè jiā gōngchǎng de juéyì.","vi":"Hội đồng quản trị ra nghị quyết đóng cửa nhà máy này."},{"type":"compound","zh":"既然大会已经通过了决议，各部门就必须认真执行。","pinyin":"Jìrán dàhuì yǐjīng tōngguòle juéyì, gè bùmén jiù bìxū rènzhēn zhíxíng.","vi":"Đại hội đã thông qua nghị quyết thì các bộ phận phải nghiêm túc thực hiện."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"议案","pinyin":"yì'àn","vi":"dự thảo"},{"hanzi":"表决","pinyin":"biǎojué","vi":"biểu quyết"},{"hanzi":"会议","pinyin":"huìyì","vi":"hội nghị"}],"traditional":"決議"},{"id":"绝缘","hanzi":"绝缘","pinyin":"juéyuán","meaning_vi":"cách điện; cách biệt, không dính dáng","explanation":"绝 (tuyệt – cắt đứt) + 缘 (duyên – mối liên hệ) → cắt đứt liên hệ; trong điện học là cách điện, nghĩa bóng là hoàn toàn xa lạ với điều gì.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔌","examples":[{"type":"basic","zh":"橡胶可以绝缘。","pinyin":"Xiàngjiāo kěyǐ juéyuán.","vi":"Cao su có thể cách điện."},{"type":"simple","zh":"电工修电线时一定要戴绝缘手套。","pinyin":"Diàngōng xiū diànxiàn shí yídìngyào dài juéyuán shǒutào.","vi":"Thợ điện khi sửa dây điện nhất định phải đeo găng tay cách điện."},{"type":"compound","zh":"虽然他很有才华，但是他似乎与名利绝缘。","pinyin":"Suīrán tā hěn yǒu cáihuá, dànshì tā sìhū yǔ mínglì juéyuán.","vi":"Tuy rất có tài nhưng anh ấy dường như chẳng dính dáng gì đến danh lợi."}],"related":[{"hanzi":"绝缘体","pinyin":"juéyuántǐ","vi":"chất cách điện"},{"hanzi":"导电","pinyin":"dǎodiàn","vi":"dẫn điện"},{"hanzi":"隔绝","pinyin":"géjué","vi":"cách ly"},{"hanzi":"电线","pinyin":"diànxiàn","vi":"dây điện"}],"traditional":"絕緣"},{"id":"绝招","hanzi":"绝招","pinyin":"juézhāo","meaning_vi":"tuyệt chiêu, ngón nghề độc đáo","explanation":"绝 (tuyệt – tuyệt diệu, độc nhất) + 招 (chiêu – chiêu thức) → chiêu thức, kỹ năng đặc biệt người khác không có, thường dùng khi quyết định thắng thua.","hsk_level":"7-9","tags":["danh-tu"],"image":"🥋","examples":[{"type":"basic","zh":"这是他的绝招。","pinyin":"Zhè shì tā de juézhāo.","vi":"Đây là tuyệt chiêu của anh ấy."},{"type":"simple","zh":"奶奶做红烧肉有一个不外传的绝招。","pinyin":"Nǎinai zuò hóngshāoròu yǒu yí ge bú wàichuán de juézhāo.","vi":"Bà có một bí quyết không truyền ra ngoài khi làm món thịt kho tàu."},{"type":"compound","zh":"即使对手很强，他也能靠这个绝招反败为胜。","pinyin":"Jíshǐ duìshǒu hěn qiáng, tā yě néng kào zhè ge juézhāo fǎn bài wéi shèng.","vi":"Dù đối thủ rất mạnh, anh ấy vẫn có thể nhờ tuyệt chiêu này mà lật ngược thế trận."}],"related":[{"hanzi":"绝技","pinyin":"juéjì","vi":"tuyệt kỹ"},{"hanzi":"秘诀","pinyin":"mìjué","vi":"bí quyết"},{"hanzi":"招数","pinyin":"zhāoshù","vi":"chiêu thức"},{"hanzi":"本领","pinyin":"běnlǐng","vi":"bản lĩnh"}],"traditional":"絕招"},{"id":"倔","hanzi":"倔","pinyin":"juè","meaning_vi":"bướng, cứng đầu","explanation":"倔 (quật – cứng cỏi, bướng) → tính khí cứng đầu, không chịu khuất phục; thường dùng trong 倔强; đọc juè thì chỉ tính cục cằn.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🐂","examples":[{"type":"basic","zh":"这孩子脾气真倔。","pinyin":"Zhè háizi píqi zhēn juè.","vi":"Đứa bé này tính bướng thật."},{"type":"simple","zh":"老人倔得谁的劝也不听。","pinyin":"Lǎorén juè de shéi de quàn yě bù tīng.","vi":"Ông cụ cứng đầu đến mức ai khuyên cũng không nghe."},{"type":"compound","zh":"虽然他性子很倔，但是心地非常善良。","pinyin":"Suīrán tā xìngzi hěn juè, dànshì xīndì fēicháng shànliáng.","vi":"Tuy tính anh ấy rất bướng nhưng tấm lòng vô cùng lương thiện."}],"related":[{"hanzi":"倔强","pinyin":"juéjiàng","vi":"bướng bỉnh"},{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"},{"hanzi":"顽固","pinyin":"wángù","vi":"ngoan cố"},{"hanzi":"听话","pinyin":"tīnghuà","vi":"ngoan ngoãn"}]},{"id":"倔强","hanzi":"倔强","pinyin":"juéjiàng","meaning_vi":"bướng bỉnh, kiên cường, không chịu khuất phục","explanation":"倔 (quật – cứng cỏi) + 强 (cường – mạnh, cứng) → tính cách cứng rắn, không chịu cúi đầu; có thể khen (kiên cường) hoặc chê (bướng).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😤","examples":[{"type":"basic","zh":"她是个倔强的女孩。","pinyin":"Tā shì ge juéjiàng de nǚhái.","vi":"Cô ấy là một cô gái bướng bỉnh."},{"type":"simple","zh":"他倔强地咬着嘴唇不让眼泪流下来。","pinyin":"Tā juéjiàng de yǎozhe zuǐchún bú ràng yǎnlèi liú xiàlái.","vi":"Cậu ấy cứng cỏi cắn chặt môi không để nước mắt rơi."},{"type":"compound","zh":"即使摔倒了很多次，倔强的他也不肯放弃。","pinyin":"Jíshǐ shuāidǎole hěn duōcì, juéjiàng de tā yě bùkěn fàngqì.","vi":"Dù ngã rất nhiều lần, cậu bé kiên cường ấy vẫn không chịu bỏ cuộc."}],"related":[{"hanzi":"倔","pinyin":"jué","vi":"bướng"},{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"顽强","pinyin":"wánqiáng","vi":"ngoan cường"}],"traditional":"倔強"},{"id":"爵士","hanzi":"爵士","pinyin":"juéshì","meaning_vi":"hiệp sĩ, tước Sir; nhạc jazz","explanation":"爵 (tước – tước vị) + 士 (sĩ – người có học, kẻ sĩ) → tước hiệp sĩ ở châu Âu; đồng thời là phiên âm của jazz, như 爵士乐.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎷","examples":[{"type":"basic","zh":"我喜欢听爵士乐。","pinyin":"Wǒ xǐhuan tīng juéshìyuè.","vi":"Tôi thích nghe nhạc jazz."},{"type":"simple","zh":"这位科学家被英国女王授予爵士称号。","pinyin":"Zhè wèi kēxuéjiā bèi Yīngguó nǚwáng shòuyǔ juéshì chēnghào.","vi":"Nhà khoa học này được Nữ hoàng Anh phong tước hiệp sĩ."},{"type":"compound","zh":"虽然我不太懂爵士乐，但是这家酒吧的现场演奏很迷人。","pinyin":"Suīrán wǒ bú tài dǒng juéshìyuè, dànshì zhè jiā jiǔbā de xiànchǎng yǎnzòu hěn mírén.","vi":"Tuy tôi không hiểu lắm về jazz nhưng buổi diễn trực tiếp ở quán bar này rất cuốn hút."}],"related":[{"hanzi":"爵士乐","pinyin":"juéshìyuè","vi":"nhạc jazz"},{"hanzi":"爵位","pinyin":"juéwèi","vi":"tước vị"},{"hanzi":"骑士","pinyin":"qíshì","vi":"kỵ sĩ"},{"hanzi":"摇滚","pinyin":"yáogǔn","vi":"nhạc rock"}]},{"id":"嚼","hanzi":"嚼","pinyin":"jiáo","meaning_vi":"nhai","explanation":"嚼 (tước – nhai) → dùng răng nghiền nát thức ăn; trong từ văn viết như 咀嚼 đọc jué.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"😋","examples":[{"type":"basic","zh":"他在嚼口香糖。","pinyin":"Tā zài jiáo kǒuxiāngtáng.","vi":"Anh ấy đang nhai kẹo cao su."},{"type":"simple","zh":"吃饭的时候要细嚼慢咽才有利于消化。","pinyin":"Chīfàn de shíhou yào xì jiáo màn yàn cái yǒulìyú xiāohuà.","vi":"Khi ăn phải nhai kỹ nuốt chậm mới tốt cho tiêu hóa."},{"type":"compound","zh":"因为这块牛肉太硬了，所以爷爷怎么也嚼不动。","pinyin":"Yīnwèi zhè kuài niúròu tài yìng le, suǒyǐ yéye zěnme yě jiáo búdòng.","vi":"Vì miếng thịt bò này quá dai nên ông nội nhai mãi không nổi."}],"related":[{"hanzi":"咀嚼","pinyin":"jǔjué","vi":"nhai"},{"hanzi":"咽","pinyin":"yàn","vi":"nuốt"},{"hanzi":"咬","pinyin":"yǎo","vi":"cắn"},{"hanzi":"吞","pinyin":"tūn","vi":"nuốt chửng"}]},{"id":"军官","hanzi":"军官","pinyin":"jūnguān","meaning_vi":"sĩ quan quân đội","explanation":"军 (quân – quân đội) + 官 (quan – quan chức) → người có cấp bậc chỉ huy trong quân đội.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🎖️","examples":[{"type":"basic","zh":"他父亲是一名军官。","pinyin":"Tā fùqīn shì yì míng jūnguān.","vi":"Bố anh ấy là một sĩ quan quân đội."},{"type":"simple","zh":"年轻的军官带领士兵完成了救援任务。","pinyin":"Niánqīng de jūnguān dàilǐng shìbīng wánchéngle jiùyuán rènwu.","vi":"Viên sĩ quan trẻ dẫn dắt binh sĩ hoàn thành nhiệm vụ cứu hộ."},{"type":"compound","zh":"虽然他已经是高级军官了，但是仍然和士兵同吃同住。","pinyin":"Suīrán tā yǐjīng shì gāojí jūnguān le, dànshì réngrán hé shìbīng tóng chī tóng zhù.","vi":"Tuy đã là sĩ quan cao cấp nhưng ông vẫn ăn ở cùng binh sĩ."}],"related":[{"hanzi":"士兵","pinyin":"shìbīng","vi":"binh sĩ"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"},{"hanzi":"将军","pinyin":"jiāngjūn","vi":"tướng quân"},{"hanzi":"警官","pinyin":"jǐngguān","vi":"sĩ quan cảnh sát"}],"traditional":"軍官"},{"id":"俊","hanzi":"俊","pinyin":"jùn","meaning_vi":"đẹp trai, tuấn tú; tài giỏi","explanation":"俊 (tuấn – đẹp, tài giỏi) → dung mạo đẹp đẽ, khôi ngô; nghĩa gốc là người tài xuất chúng, như 英俊, 俊杰.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😎","examples":[{"type":"basic","zh":"这小伙子长得真俊。","pinyin":"Zhè xiǎohuǒzi zhǎngde zhēn jùn.","vi":"Chàng trai này trông thật tuấn tú."},{"type":"simple","zh":"新娘穿着婚纱显得格外俊俏。","pinyin":"Xīnniáng chuānzhe hūnshā xiǎnde géwài jùnqiào.","vi":"Cô dâu mặc váy cưới trông đặc biệt xinh đẹp."},{"type":"compound","zh":"虽然他长得俊，但是大家更喜欢他的好脾气。","pinyin":"Suīrán tā zhǎngde jùn, dànshì dàjiā gèng xǐhuan tā de hǎo píqi.","vi":"Tuy anh ấy đẹp trai nhưng mọi người thích tính tình tốt của anh hơn."}],"related":[{"hanzi":"英俊","pinyin":"yīngjùn","vi":"anh tuấn"},{"hanzi":"帅","pinyin":"shuài","vi":"đẹp trai"},{"hanzi":"俊俏","pinyin":"jùnqiào","vi":"xinh xắn"},{"hanzi":"俊杰","pinyin":"jùnjié","vi":"tuấn kiệt"}]},{"id":"骏马","hanzi":"骏马","pinyin":"jùnmǎ","meaning_vi":"tuấn mã, ngựa tốt","explanation":"骏 (tuấn – ngựa tốt) + 马 (mã – ngựa) → con ngựa khỏe đẹp, chạy nhanh.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐎","examples":[{"type":"basic","zh":"草原上跑着几匹骏马。","pinyin":"Cǎoyuán shàng pǎozhe jǐ pǐ jùnmǎ.","vi":"Trên thảo nguyên có mấy con tuấn mã đang chạy."},{"type":"simple","zh":"牧民骑着骏马在草原上飞奔。","pinyin":"Mùmín qízhe jùnmǎ zài cǎoyuán shàng fēibēn.","vi":"Người chăn nuôi cưỡi tuấn mã phi nhanh trên thảo nguyên."},{"type":"compound","zh":"即使是一匹骏马，如果没有好骑手也跑不出好成绩。","pinyin":"Jíshǐ shì yì pǐ jùnmǎ, rúguǒ méiyǒu hǎo qíshǒu yě pǎo bù chū hǎo chéngjì.","vi":"Dù là tuấn mã, nếu không có người cưỡi giỏi cũng không chạy được thành tích tốt."}],"related":[{"hanzi":"马匹","pinyin":"mǎpǐ","vi":"ngựa"},{"hanzi":"千里马","pinyin":"qiānlǐmǎ","vi":"ngựa thiên lý"},{"hanzi":"骑马","pinyin":"qímǎ","vi":"cưỡi ngựa"},{"hanzi":"奔驰","pinyin":"bēnchí","vi":"phi nhanh"}],"traditional":"駿馬"},{"id":"卡片","hanzi":"卡片","pinyin":"kǎpiàn","meaning_vi":"tấm thẻ, tấm thiếp","explanation":"卡 (ca – thẻ, phiên âm card) + 片 (phiến – tấm mỏng) → tấm giấy cứng nhỏ dùng để ghi chép, chúc mừng hoặc học từ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🃏","examples":[{"type":"basic","zh":"我用卡片背单词。","pinyin":"Wǒ yòng kǎpiàn bèi dāncí.","vi":"Tôi dùng thẻ để học thuộc từ vựng."},{"type":"simple","zh":"孩子们给老师写了感谢卡片。","pinyin":"Háizimen gěi lǎoshī xiěle gǎnxiè kǎpiàn.","vi":"Bọn trẻ viết thiệp cảm ơn tặng cô giáo."},{"type":"compound","zh":"如果把重点写在卡片上，就可以随时拿出来复习。","pinyin":"Rúguǒ bǎ zhòngdiǎn xiě zài kǎpiàn shàng, jiù kěyǐ suíshí ná chūlái fùxí.","vi":"Nếu viết các ý chính lên thẻ thì có thể lấy ra ôn bất cứ lúc nào."}],"related":[{"hanzi":"贺卡","pinyin":"hèkǎ","vi":"thiệp chúc mừng"},{"hanzi":"名片","pinyin":"míngpiàn","vi":"danh thiếp"},{"hanzi":"明信片","pinyin":"míngxìnpiàn","vi":"bưu thiếp"},{"hanzi":"卡","pinyin":"kǎ","vi":"thẻ"}]},{"id":"卡子","hanzi":"卡子","pinyin":"qiǎzi","meaning_vi":"cái kẹp, kẹp tóc; trạm kiểm soát","explanation":"卡 (ca/khải – kẹp, chặn) + 子 (tử – hậu tố danh từ) → vật dùng để kẹp giữ như kẹp tóc; cũng chỉ trạm gác chặn đường.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"📎","examples":[{"type":"basic","zh":"她头上别着卡子。","pinyin":"Tā tóushang biézhe qiǎzi.","vi":"Trên đầu cô ấy cài một chiếc kẹp tóc."},{"type":"simple","zh":"妈妈用一个小卡子把窗帘固定住了。","pinyin":"Māma yòng yí ge xiǎo qiǎzi bǎ chuānglián gùdìng zhù le.","vi":"Mẹ dùng một cái kẹp nhỏ cố định rèm cửa."},{"type":"compound","zh":"因为头发总是挡眼睛，所以她买了几个卡子。","pinyin":"Yīnwèi tóufa zǒngshì dǎng yǎnjing, suǒyǐ tā mǎile jǐ ge qiǎzi.","vi":"Vì tóc cứ che mắt nên cô ấy mua mấy cái kẹp tóc."}],"related":[{"hanzi":"发卡","pinyin":"fàqiǎ","vi":"kẹp tóc"},{"hanzi":"夹子","pinyin":"jiāzi","vi":"cái kẹp"},{"hanzi":"关卡","pinyin":"guānqiǎ","vi":"trạm kiểm soát"},{"hanzi":"别针","pinyin":"biézhēn","vi":"ghim băng"}]},{"id":"开办","hanzi":"开办","pinyin":"kāibàn","meaning_vi":"mở, thành lập (trường, công ty...)","explanation":"开 (khai – mở) + 办 (biện – làm, lo liệu) → mở ra và bắt đầu vận hành một cơ sở như trường học, nhà máy, cửa hàng.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏫","examples":[{"type":"basic","zh":"他开办了一所学校。","pinyin":"Tā kāibànle yì suǒ xuéxiào.","vi":"Ông ấy đã mở một trường học."},{"type":"simple","zh":"这家银行在农村开办了多个网点。","pinyin":"Zhè jiā yínháng zài nóngcūn kāibànle duōge wǎngdiǎn.","vi":"Ngân hàng này mở nhiều điểm giao dịch ở nông thôn."},{"type":"compound","zh":"如果想开办一家公司，就要先去工商局登记。","pinyin":"Rúguǒ xiǎng kāibàn yìjiā gōngsī, jiùyào xiān qù gōngshāng jú dēngjì.","vi":"Nếu muốn thành lập công ty thì phải đăng ký ở cục công thương trước."}],"related":[{"hanzi":"创办","pinyin":"chuàngbàn","vi":"sáng lập"},{"hanzi":"开设","pinyin":"kāishè","vi":"mở"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"tổ chức"},{"hanzi":"停办","pinyin":"tíngbàn","vi":"đình chỉ"}],"traditional":"開辦"},{"id":"开场","hanzi":"开场","pinyin":"kāichǎng","meaning_vi":"mở màn, bắt đầu; phần mở đầu","explanation":"开 (khai – mở) + 场 (trường – buổi, màn diễn) → buổi diễn, cuộc họp, trận đấu bắt đầu.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"演出七点开场。","pinyin":"Yǎnchū qīdiǎn kāichǎng.","vi":"Buổi diễn mở màn lúc bảy giờ."},{"type":"simple","zh":"比赛刚开场主队就进了一个球。","pinyin":"Bǐsài gāng kāichǎng zhǔduì jiù jìnle yí ge qiú.","vi":"Trận đấu vừa bắt đầu đội chủ nhà đã ghi một bàn."},{"type":"compound","zh":"既然电影已经开场了，我们就悄悄进去吧。","pinyin":"Jìrán diànyǐng yǐjīng kāichǎng le, wǒmen jiù qiāoqiāo jìnqù ba.","vi":"Phim đã bắt đầu rồi thì chúng ta lặng lẽ vào thôi."}],"related":[{"hanzi":"开幕","pinyin":"kāimù","vi":"khai mạc"},{"hanzi":"散场","pinyin":"sànchǎng","vi":"tan buổi"},{"hanzi":"开场白","pinyin":"kāichǎngbái","vi":"lời mở đầu"},{"hanzi":"开始","pinyin":"kāishǐ","vi":"bắt đầu"}],"traditional":"開場"},{"id":"开场白","hanzi":"开场白","pinyin":"kāichǎngbái","meaning_vi":"lời mở đầu, lời dạo đầu","explanation":"开场 (khai trường – mở màn) + 白 (bạch – lời thoại) → lời nói mở màn của vở kịch; nay chỉ lời mở đầu bài phát biểu, bài viết.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🎤","examples":[{"type":"basic","zh":"他的开场白很幽默。","pinyin":"Tā de kāichǎngbái hěn yōumò.","vi":"Lời mở đầu của anh ấy rất hài hước."},{"type":"simple","zh":"主持人用一个小故事作为开场白。","pinyin":"Zhǔchírén yòng yí ge xiǎo gùshi zuòwéi kāichǎngbái.","vi":"Người dẫn chương trình dùng một câu chuyện nhỏ làm lời mở đầu."},{"type":"compound","zh":"如果开场白能吸引听众，那么后面的演讲就容易多了。","pinyin":"Rúguǒ kāichǎngbái néng xīyǐn tīngzhòng, nàme hòumiàn de yǎnjiǎng jiù róngyì duō le.","vi":"Nếu lời mở đầu thu hút được người nghe thì phần diễn thuyết sau sẽ dễ hơn nhiều."}],"related":[{"hanzi":"开场","pinyin":"kāichǎng","vi":"mở màn"},{"hanzi":"结束语","pinyin":"jiéshùyǔ","vi":"lời kết"},{"hanzi":"引言","pinyin":"yǐnyán","vi":"lời dẫn"},{"hanzi":"致辞","pinyin":"zhìcí","vi":"phát biểu"}],"traditional":"開場白"},{"id":"开动","hanzi":"开动","pinyin":"kāidòng","meaning_vi":"khởi động, cho chạy; lên đường","explanation":"开 (khai – mở) + 动 (động – chuyển động) → làm cho máy móc, xe cộ bắt đầu chạy; nghĩa bóng 开动脑筋 là động não.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚙️","examples":[{"type":"basic","zh":"火车开动了。","pinyin":"Huǒchē kāidòng le.","vi":"Tàu hỏa chuyển bánh rồi."},{"type":"simple","zh":"大家开动脑筋想想有没有更好的办法。","pinyin":"Dàjiā kāidòng nǎojīn xiǎng xiang yǒuméiyǒu gèng hǎo de bànfǎ.","vi":"Mọi người hãy động não nghĩ xem có cách nào tốt hơn không."},{"type":"compound","zh":"机器一开动，车间里就响起了轰隆隆的声音。","pinyin":"Jīqì yì kāidòng, chējiān lǐ jiù xiǎngqǐle hōng lōnglōng de shēngyīn.","vi":"Máy vừa khởi động, trong xưởng liền vang lên tiếng ầm ầm."}],"related":[{"hanzi":"启动","pinyin":"qǐdòng","vi":"khởi động"},{"hanzi":"发动","pinyin":"fādòng","vi":"nổ máy"},{"hanzi":"停止","pinyin":"tíngzhǐ","vi":"dừng"},{"hanzi":"运转","pinyin":"yùnzhuǎn","vi":"vận hành"}],"traditional":"開動"},{"id":"开发区","hanzi":"开发区","pinyin":"kāifāqū","meaning_vi":"khu phát triển, khu kinh tế mới","explanation":"开发 (khai phát – khai thác, phát triển) + 区 (khu – khu vực) → khu vực được quy hoạch để thu hút đầu tư, phát triển công nghiệp.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏗️","examples":[{"type":"basic","zh":"他在开发区上班。","pinyin":"Tā zài kāifāqū shàngbān.","vi":"Anh ấy làm việc ở khu phát triển."},{"type":"simple","zh":"新建的开发区吸引了上百家外资企业。","pinyin":"Xīnjiàn de kāifāqū xīyǐnle shàng bǎijiā wàizī qǐyè.","vi":"Khu phát triển mới xây thu hút hàng trăm doanh nghiệp vốn ngoại."},{"type":"compound","zh":"自从建了开发区以后，这个小镇就变得越来越热闹。","pinyin":"Zìcóng jiànle kāifāqū yǐhòu, zhè ge xiǎozhèn jiù biànde yuèláiyuè rènao.","vi":"Từ khi xây khu phát triển, thị trấn nhỏ này ngày càng sầm uất."}],"related":[{"hanzi":"开发","pinyin":"kāifā","vi":"phát triển"},{"hanzi":"工业园","pinyin":"gōngyèyuán","vi":"khu công nghiệp"},{"hanzi":"特区","pinyin":"tèqū","vi":"đặc khu"},{"hanzi":"开发商","pinyin":"kāifāshāng","vi":"nhà phát triển"}],"traditional":"開發區"},{"id":"开发商","hanzi":"开发商","pinyin":"kāifāshāng","meaning_vi":"nhà phát triển, chủ đầu tư (bất động sản, sản phẩm)","explanation":"开发 (khai phát – phát triển) + 商 (thương – nhà buôn) → công ty đầu tư xây dựng bất động sản hoặc phát triển sản phẩm như phần mềm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"开发商还没交房。","pinyin":"Kāifāshāng hái méi jiāo fáng.","vi":"Chủ đầu tư vẫn chưa bàn giao nhà."},{"type":"simple","zh":"这款游戏的开发商是一家小公司。","pinyin":"Zhè kuǎn yóuxì de kāifāshāng shì yìjiā xiǎo gōngsī.","vi":"Nhà phát triển trò chơi này là một công ty nhỏ."},{"type":"compound","zh":"如果开发商延期交房，业主就有权要求赔偿。","pinyin":"Rúguǒ kāifāshāng yánqī jiāo fáng, yèzhǔ jiù yǒuquán yāoqiú péicháng.","vi":"Nếu chủ đầu tư bàn giao nhà chậm, chủ hộ có quyền yêu cầu bồi thường."}],"related":[{"hanzi":"房地产","pinyin":"fángdìchǎn","vi":"bất động sản"},{"hanzi":"开发区","pinyin":"kāifāqū","vi":"khu phát triển"},{"hanzi":"业主","pinyin":"yèzhǔ","vi":"chủ sở hữu"},{"hanzi":"承包商","pinyin":"chéngbāoshāng","vi":"nhà thầu"}],"traditional":"開發商"},{"id":"开工","hanzi":"开工","pinyin":"kāigōng","meaning_vi":"khởi công, bắt đầu làm việc","explanation":"开 (khai – mở) + 工 (công – công việc) → nhà máy bắt đầu sản xuất hoặc công trình bắt đầu thi công.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👷","examples":[{"type":"basic","zh":"新大桥明天开工。","pinyin":"Xīn Dàqiáo míngtiān kāigōng.","vi":"Cây cầu mới khởi công vào ngày mai."},{"type":"simple","zh":"春节过后工厂陆续开工了。","pinyin":"Chūnjié guòhòu gōngchǎng lùxù kāigōng le.","vi":"Sau Tết các nhà máy lần lượt hoạt động trở lại."},{"type":"compound","zh":"因为原材料迟迟没到，所以工程一直没能开工。","pinyin":"Yīnwèi yuáncáiliào chíchí méi dào, suǒyǐ gōngchéng yìzhí méi néng kāigōng.","vi":"Vì nguyên liệu mãi chưa về nên công trình vẫn chưa thể khởi công."}],"related":[{"hanzi":"动工","pinyin":"dònggōng","vi":"động thổ"},{"hanzi":"完工","pinyin":"wángōng","vi":"hoàn công"},{"hanzi":"停工","pinyin":"tínggōng","vi":"ngừng việc"},{"hanzi":"施工","pinyin":"shīgōng","vi":"thi công"}],"traditional":"開工"},{"id":"开垦","hanzi":"开垦","pinyin":"kāikěn","meaning_vi":"khai hoang, vỡ đất","explanation":"开 (khai – mở) + 垦 (khẩn – vỡ đất) → cày xới đất hoang để biến thành ruộng trồng trọt.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🚜","examples":[{"type":"basic","zh":"他们开垦了荒地。","pinyin":"Tāmen kāikěnle huāngdì.","vi":"Họ đã khai hoang đất trống."},{"type":"simple","zh":"农民们在山坡上开垦出一片梯田。","pinyin":"Nóngmínmen zài shānpō shàng kāikěn chū yípiàn tītián.","vi":"Nông dân khai phá trên sườn núi được một vùng ruộng bậc thang."},{"type":"compound","zh":"虽然开垦荒地很辛苦，但是第一年就有了好收成。","pinyin":"Suīrán kāikěn huāngdì hěn xīnkǔ, dànshì dìyī nián jiù yǒule hǎo shōucheng.","vi":"Tuy khai hoang rất vất vả nhưng ngay năm đầu đã được mùa."}],"related":[{"hanzi":"荒地","pinyin":"huāngdì","vi":"đất hoang"},{"hanzi":"耕地","pinyin":"gēngdì","vi":"đất canh tác"},{"hanzi":"开荒","pinyin":"kāihuāng","vi":"khai hoang"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng trọt"}],"traditional":"開墾"},{"id":"开口","hanzi":"开口","pinyin":"kāikǒu","meaning_vi":"mở miệng, lên tiếng","explanation":"开 (khai – mở) + 口 (khẩu – miệng) → mở miệng nói; thường dùng khi ngại ngùng chưa dám nói, như 难以开口.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他终于开口了。","pinyin":"Tā zhōngyú kāikǒu le.","vi":"Cuối cùng anh ấy cũng lên tiếng."},{"type":"simple","zh":"她不好意思开口向朋友借钱。","pinyin":"Tā bù hǎoyìsi kāikǒu xiàng péngyou jièqián.","vi":"Cô ấy ngại mở miệng hỏi vay tiền bạn."},{"type":"compound","zh":"如果你有困难，就尽管开口，我一定帮你。","pinyin":"Rúguǒ nǐ yǒu kùnnan, jiù jǐnguǎn kāikǒu, wǒ yídìng bāng nǐ.","vi":"Nếu bạn gặp khó khăn cứ việc nói, tôi nhất định giúp."}],"related":[{"hanzi":"张口","pinyin":"zhāngkǒu","vi":"há miệng"},{"hanzi":"闭嘴","pinyin":"bìzuǐ","vi":"im miệng"},{"hanzi":"说话","pinyin":"shuōhuà","vi":"nói chuyện"},{"hanzi":"口子","pinyin":"kǒuzi","vi":"vết rách"}],"traditional":"開口"},{"id":"开启","hanzi":"开启","pinyin":"kāiqǐ","meaning_vi":"mở, mở ra, bật (chức năng)","explanation":"开 (khai – mở) + 启 (khải – mở ra) → mở cửa, mở thiết bị hoặc bật một chức năng; nghĩa bóng là mở ra một giai đoạn mới.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔓","examples":[{"type":"basic","zh":"请开启蓝牙功能。","pinyin":"Qǐng kāiqǐ Lányá gōngnéng.","vi":"Vui lòng bật chức năng Bluetooth."},{"type":"simple","zh":"大学毕业后他开启了人生的新篇章。","pinyin":"Dàxué bìyè hòu tā kāiqǐle rénshēng de xīn piānzhāng.","vi":"Sau khi tốt nghiệp đại học, anh ấy mở ra chương mới của cuộc đời."},{"type":"compound","zh":"只要开启了定位服务，就能实时看到孩子的位置。","pinyin":"Zhǐyào kāiqǐle dìngwèi fúwù, jiù néng shíshí kàndào háizi de wèizhi.","vi":"Chỉ cần bật dịch vụ định vị là có thể xem vị trí của con theo thời gian thực."}],"related":[{"hanzi":"打开","pinyin":"dǎkāi","vi":"mở"},{"hanzi":"关闭","pinyin":"guānbì","vi":"đóng"},{"hanzi":"启动","pinyin":"qǐdòng","vi":"khởi động"},{"hanzi":"开通","pinyin":"kāitōng","vi":"kích hoạt"}],"traditional":"開啟"},{"id":"开枪","hanzi":"开枪","pinyin":"kāiqiāng","meaning_vi":"nổ súng, bắn súng","explanation":"开 (khai – mở, phát) + 枪 (thương – súng) → bóp cò cho súng nổ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔫","examples":[{"type":"basic","zh":"警察向天开枪。","pinyin":"Jǐngchá xiàng tiān kāiqiāng.","vi":"Cảnh sát bắn chỉ thiên."},{"type":"simple","zh":"猎人举起猎枪准备向野猪开枪。","pinyin":"Lièrén jǔqǐ lièqiāng zhǔnbèi xiàng yězhū kāiqiāng.","vi":"Người thợ săn giơ súng chuẩn bị bắn con lợn rừng."},{"type":"compound","zh":"如果嫌疑人不放下武器，警察就会开枪。","pinyin":"Rúguǒ xiányírén bú fàngxià wǔqì, jǐngchá jiù huì kāiqiāng.","vi":"Nếu nghi phạm không bỏ vũ khí xuống, cảnh sát sẽ nổ súng."}],"related":[{"hanzi":"射击","pinyin":"shèjī","vi":"bắn"},{"hanzi":"枪声","pinyin":"qiāngshēng","vi":"tiếng súng"},{"hanzi":"子弹","pinyin":"zǐdàn","vi":"viên đạn"},{"hanzi":"手枪","pinyin":"shǒuqiāng","vi":"súng ngắn"}],"traditional":"開槍"},{"id":"开销","hanzi":"开销","pinyin":"kāixiāo","meaning_vi":"chi tiêu, chi phí; chi trả","explanation":"开 (khai – chi ra) + 销 (tiêu – tiêu dùng) → khoản tiền phải chi ra cho sinh hoạt, công việc.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"这个月开销很大。","pinyin":"Zhè geyuè kāixiāo hěn dà.","vi":"Tháng này chi tiêu rất lớn."},{"type":"simple","zh":"大城市的生活开销比小城市高得多。","pinyin":"Dàchéngshì de shēnghuó kāixiāo bǐ xiǎo chéngshì gāo de duō.","vi":"Chi phí sinh hoạt ở thành phố lớn cao hơn nhiều so với thành phố nhỏ."},{"type":"compound","zh":"因为孩子上了大学，所以家里的开销一下子增加了。","pinyin":"Yīnwèi háizi shàngle dàxué, suǒyǐ jiālǐ de kāixiāo yíxiàzi zēngjiā le.","vi":"Vì con vào đại học nên chi tiêu trong nhà bỗng tăng lên."}],"related":[{"hanzi":"开支","pinyin":"kāizhī","vi":"chi tiêu"},{"hanzi":"花费","pinyin":"huāfèi","vi":"chi phí"},{"hanzi":"费用","pinyin":"fèiyòng","vi":"phí tổn"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"}],"traditional":"開銷"},{"id":"开张","hanzi":"开张","pinyin":"kāizhāng","meaning_vi":"khai trương; mở hàng (giao dịch đầu tiên trong ngày)","explanation":"开 (khai – mở) + 张 (trương – giương ra, bày ra) → cửa hàng bắt đầu kinh doanh; cũng chỉ giao dịch đầu tiên trong ngày.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🎊","examples":[{"type":"basic","zh":"新店明天开张。","pinyin":"Xīndiàn míngtiān kāizhāng.","vi":"Cửa hàng mới khai trương vào ngày mai."},{"type":"simple","zh":"饭馆开张那天门口放了很多鞭炮。","pinyin":"Fànguǎn kāizhāng nà tiān ménkǒu fàngle hěn duō biānpào.","vi":"Hôm quán ăn khai trương, trước cửa đốt rất nhiều pháo."},{"type":"compound","zh":"虽然店已经开了一上午，但是还没开张。","pinyin":"Suīrán diàn yǐjīng kāile yí shàngwǔ, dànshì hái méi kāizhāng.","vi":"Tuy cửa hàng đã mở cả buổi sáng nhưng vẫn chưa mở hàng được."}],"related":[{"hanzi":"开业","pinyin":"kāiyè","vi":"khai trương"},{"hanzi":"营业","pinyin":"yíngyè","vi":"kinh doanh"},{"hanzi":"倒闭","pinyin":"dǎobì","vi":"đóng cửa phá sản"},{"hanzi":"关门","pinyin":"guānmén","vi":"đóng cửa"}],"traditional":"開張"},{"id":"凯歌","hanzi":"凯歌","pinyin":"kǎigē","meaning_vi":"khúc khải hoàn, bài ca chiến thắng","explanation":"凯 (khải – khải hoàn, thắng trận) + 歌 (ca – bài hát) → bài ca mừng chiến thắng; hay dùng 奏凯歌, 高奏凯歌.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎺","examples":[{"type":"basic","zh":"战士们唱着凯歌回来了。","pinyin":"Zhànshìmen chàngzhe kǎigē huílái le.","vi":"Các chiến sĩ hát khúc khải hoàn trở về."},{"type":"simple","zh":"球队一路高奏凯歌杀进了决赛。","pinyin":"Qiúduì yílù gāo zòu kǎigē shājìnle juésài.","vi":"Đội bóng liên tiếp ca khúc khải hoàn tiến thẳng vào trận chung kết."},{"type":"compound","zh":"虽然开局不利，但是他们最终还是奏响了凯歌。","pinyin":"Suīrán kāijú búlì, dànshì tāmen zuìzhōng háishi zòu xiǎngle kǎigē.","vi":"Tuy khởi đầu bất lợi nhưng cuối cùng họ vẫn ca khúc khải hoàn."}],"related":[{"hanzi":"凯旋","pinyin":"kǎixuán","vi":"khải hoàn"},{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"战歌","pinyin":"zhàngē","vi":"bài ca chiến đấu"},{"hanzi":"欢呼","pinyin":"huānhū","vi":"reo hò"}],"traditional":"凱歌"},{"id":"堪称","hanzi":"堪称","pinyin":"kānchēng","meaning_vi":"có thể gọi là, xứng đáng được coi là","explanation":"堪 (kham – có thể, đáng) + 称 (xưng – gọi là) → xứng đáng được gọi là; dùng để đánh giá cao, văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏅","examples":[{"type":"basic","zh":"这道菜堪称一绝。","pinyin":"Zhè dào cài kānchēng yì jué.","vi":"Món này có thể gọi là tuyệt phẩm."},{"type":"simple","zh":"这座大桥堪称现代工程的奇迹。","pinyin":"Zhè zuò Dàqiáo kānchēng xiàndài gōngchéng de qíjì.","vi":"Cây cầu này xứng đáng là kỳ tích của kỹ thuật hiện đại."},{"type":"compound","zh":"虽然他只有二十岁，但是他的棋艺堪称大师级。","pinyin":"Suīrán tā zhǐyǒu èrshí suì, dànshì tā de qíyì kānchēng dàshījí.","vi":"Tuy mới hai mươi tuổi nhưng tài đánh cờ của cậu có thể coi là đẳng cấp bậc thầy."}],"related":[{"hanzi":"可谓","pinyin":"kěwèi","vi":"có thể nói là"},{"hanzi":"称得上","pinyin":"chēngdeshàng","vi":"đáng gọi là"},{"hanzi":"号称","pinyin":"hàochēng","vi":"được gọi là"},{"hanzi":"不愧","pinyin":"búkuì","vi":"xứng đáng"}],"traditional":"堪稱"},{"id":"侃大山","hanzi":"侃大山","pinyin":"kǎndàshān","meaning_vi":"tán gẫu, tán phét, chém gió","explanation":"侃 (khản – nói chuyện dông dài) + 大山 (đại sơn – núi lớn) → tán chuyện trên trời dưới biển; khẩu ngữ phương Bắc.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"他们在院子里侃大山。","pinyin":"Tāmen zài yuànzi lǐ kǎndàshān.","vi":"Họ đang tán gẫu trong sân."},{"type":"simple","zh":"几个老同学凑在一起，一侃大山就是一晚上。","pinyin":"Jǐ ge lǎo tóngxué còu zài yìqǐ, yì kǎndàshān jiùshì yì wǎnshang.","vi":"Mấy bạn học cũ tụ lại, hễ tán phét là hết cả buổi tối."},{"type":"compound","zh":"与其在这儿侃大山，不如赶紧把作业写完。","pinyin":"Yǔqí zài zhèr kǎndàshān, bùrú gǎnjǐn bǎ zuòyè xiěwán.","vi":"Thay vì ngồi đây chém gió, chi bằng mau làm xong bài tập."}],"related":[{"hanzi":"聊天","pinyin":"liáotiān","vi":"nói chuyện phiếm"},{"hanzi":"闲聊","pinyin":"xiánliáo","vi":"tán gẫu"},{"hanzi":"吹牛","pinyin":"chuīniú","vi":"khoác lác"},{"hanzi":"唠嗑","pinyin":"làokē","vi":"tán chuyện"}]},{"id":"看得出","hanzi":"看得出","pinyin":"kàndechū","meaning_vi":"có thể thấy, nhìn ra được","explanation":"看 (khán – nhìn) + 得 (đắc – được) + 出 (xuất – ra) → nhìn mà nhận ra được điều gì; phủ định là 看不出.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"👀","examples":[{"type":"basic","zh":"看得出他很紧张。","pinyin":"Kàndechū tā hěn jǐnzhāng.","vi":"Có thể thấy anh ấy rất căng thẳng."},{"type":"simple","zh":"从她的笑容里看得出她很满意。","pinyin":"Cóng tā de xiàoróng lǐ kàndechū tā hěn mǎnyì.","vi":"Nhìn nụ cười của cô ấy có thể thấy cô rất hài lòng."},{"type":"compound","zh":"虽然他嘴上不说，但是看得出他心里很难过。","pinyin":"Suīrán tā zuǐ shang bù shuō, dànshì kàndechū tā xīnlǐ hěn nánguò.","vi":"Tuy ngoài miệng không nói nhưng có thể thấy trong lòng anh ấy rất buồn."}],"related":[{"hanzi":"看不出","pinyin":"kànbùchū","vi":"không nhìn ra"},{"hanzi":"看出","pinyin":"kànchū","vi":"nhìn ra"},{"hanzi":"看样子","pinyin":"kànyàngzi","vi":"xem chừng"},{"hanzi":"显然","pinyin":"xiǎnrán","vi":"rõ ràng"}]},{"id":"看护","hanzi":"看护","pinyin":"kānhù","meaning_vi":"chăm sóc, trông nom (người bệnh)","explanation":"看 (khán – trông coi) + 护 (hộ – bảo vệ, chăm sóc) → trông nom, chăm sóc người bệnh, người già; xưa còn chỉ y tá.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🧑‍⚕️","examples":[{"type":"basic","zh":"她在医院看护母亲。","pinyin":"Tā zài yīyuàn kānhù mǔqīn.","vi":"Cô ấy ở bệnh viện chăm sóc mẹ."},{"type":"simple","zh":"他请了一个保姆专门看护卧床的父亲。","pinyin":"Tā qǐngle yí ge bǎomǔ zhuānmén kānhù wòchuáng de fùqīn.","vi":"Anh ấy thuê một người giúp việc chuyên chăm sóc người cha nằm liệt giường."},{"type":"compound","zh":"因为白天要上班，所以晚上才能去看护病人。","pinyin":"Yīnwèi báitiān yào shàngbān, suǒyǐ wǎnshang cáinéng qù kānhù bìngrén.","vi":"Vì ban ngày phải đi làm nên tối mới có thể đi chăm người bệnh."}],"related":[{"hanzi":"护理","pinyin":"hùlǐ","vi":"điều dưỡng"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"看管","pinyin":"kānguǎn","vi":"trông coi"},{"hanzi":"护士","pinyin":"hùshi","vi":"y tá"}],"traditional":"看護"},{"id":"看热闹","hanzi":"看热闹","pinyin":"kànrènao","meaning_vi":"xem náo nhiệt, hóng chuyện","explanation":"看 (khán – xem) + 热闹 (nhiệt náo – náo nhiệt) → đứng xem cảnh đông vui hoặc chuyện ồn ào của người khác, thường chỉ đứng ngoài không giúp.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🍿","examples":[{"type":"basic","zh":"街上很多人在看热闹。","pinyin":"Jiēshang hěn duō rén zài kànrènao.","vi":"Trên phố rất nhiều người đang hóng chuyện."},{"type":"simple","zh":"孩子们跑到村口去看热闹了。","pinyin":"Háizimen pǎo dào cūn kǒu qù kànrènao le.","vi":"Bọn trẻ chạy ra đầu làng xem náo nhiệt."},{"type":"compound","zh":"发生车祸时，与其站在旁边看热闹，不如赶快打电话报警。","pinyin":"Fāshēng chēhuò shí, yǔqí zhàn zài pángbiān kànrènao, bùrú gǎnkuài dǎdiànhuà bàojǐng.","vi":"Khi xảy ra tai nạn, thay vì đứng bên cạnh hóng chuyện, chi bằng mau gọi báo cảnh sát."}],"related":[{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"},{"hanzi":"围观","pinyin":"wéiguān","vi":"vây xem"},{"hanzi":"凑热闹","pinyin":"còurènao","vi":"góp vui"},{"hanzi":"旁观","pinyin":"pángguān","vi":"đứng ngoài xem"}],"traditional":"看熱鬧"},{"id":"看似","hanzi":"看似","pinyin":"kànsì","meaning_vi":"trông có vẻ, nhìn như","explanation":"看 (khán – nhìn) + 似 (tự – giống như) → bề ngoài trông như vậy nhưng thực tế có thể khác; văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎭","examples":[{"type":"basic","zh":"这道题看似简单。","pinyin":"Zhè dào tí kànsì jiǎndān.","vi":"Bài này trông có vẻ đơn giản."},{"type":"simple","zh":"这个看似普通的小镇藏着很多故事。","pinyin":"Zhè ge kànsì pǔtōng de xiǎozhèn cángzhe hěn duō gùshi.","vi":"Thị trấn nhỏ trông có vẻ bình thường này ẩn chứa nhiều câu chuyện."},{"type":"compound","zh":"他看似漫不经心，其实每个细节都考虑到了。","pinyin":"Tā kànsì mànbùjīngxīn, qíshí měi ge xìjié dōu kǎolǜ dào le.","vi":"Anh ấy trông có vẻ hờ hững nhưng thực ra đã tính đến từng chi tiết."}],"related":[{"hanzi":"好像","pinyin":"hǎoxiàng","vi":"hình như"},{"hanzi":"似乎","pinyin":"sìhū","vi":"dường như"},{"hanzi":"貌似","pinyin":"màosì","vi":"bề ngoài như"},{"hanzi":"看起来","pinyin":"kànqǐlái","vi":"trông có vẻ"}]},{"id":"看台","hanzi":"看台","pinyin":"kàntái","meaning_vi":"khán đài","explanation":"看 (khán – xem) + 台 (đài – bục, đài cao) → khu vực ghế ngồi bậc thang cho khán giả trong sân vận động.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏟️","examples":[{"type":"basic","zh":"看台上坐满了球迷。","pinyin":"Kàntái shàng zuò mǎnle qiúmí.","vi":"Trên khán đài chật kín cổ động viên."},{"type":"simple","zh":"球迷们在看台上挥舞着国旗。","pinyin":"Qiúmímen zài kàntái shàng huīwǔzhe guóqí.","vi":"Các cổ động viên vẫy cờ trên khán đài."},{"type":"compound","zh":"虽然下着大雨，但是看台上的观众没有一个离开。","pinyin":"Suīrán xiàzhe dàyǔ, dànshì kàntái shàng de guānzhòng méiyǒu yí ge líkāi.","vi":"Tuy trời mưa to nhưng không khán giả nào trên khán đài rời đi."}],"related":[{"hanzi":"体育场","pinyin":"tǐyùchǎng","vi":"sân vận động"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"},{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"},{"hanzi":"球场","pinyin":"qiúchǎng","vi":"sân bóng"}],"traditional":"看臺"},{"id":"看样子","hanzi":"看样子","pinyin":"kànyàngzi","meaning_vi":"xem chừng, xem ra, có vẻ như","explanation":"看 (khán – nhìn) + 样子 (dạng tử – dáng vẻ) → nhìn tình hình mà phán đoán; đứng đầu câu như 看起来.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤔","examples":[{"type":"basic","zh":"看样子要下雨了。","pinyin":"Kànyàngzi yào xiàyǔ le.","vi":"Xem chừng sắp mưa rồi."},{"type":"simple","zh":"看样子他今天心情不太好。","pinyin":"Kànyàngzi tā jīntiān xīnqíng bú tài hǎo.","vi":"Xem ra hôm nay tâm trạng anh ấy không tốt lắm."},{"type":"compound","zh":"看样子堵车很严重，所以我们得换一条路走。","pinyin":"Kànyàngzi dǔchē hěn yánzhòng, suǒyǐ wǒmen děi huàn yì tiáo lù zǒu.","vi":"Xem chừng tắc đường rất nghiêm trọng nên chúng ta phải đổi đường khác."}],"related":[{"hanzi":"看来","pinyin":"kànlái","vi":"xem ra"},{"hanzi":"好像","pinyin":"hǎoxiàng","vi":"hình như"},{"hanzi":"看起来","pinyin":"kànqǐlái","vi":"trông có vẻ"},{"hanzi":"似乎","pinyin":"sìhū","vi":"dường như"}],"traditional":"看樣子"},{"id":"看中","hanzi":"看中","pinyin":"kànzhòng","meaning_vi":"ưng ý, chọn được, nhắm trúng","explanation":"看 (khán – nhìn) + 中 (trúng – trúng, vừa ý) → nhìn qua và thấy ưng, quyết định chọn.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"😍","examples":[{"type":"basic","zh":"我看中了这件大衣。","pinyin":"Wǒ kànzhòngle zhè jiàn dàyī.","vi":"Tôi ưng chiếc áo khoác này rồi."},{"type":"simple","zh":"老板看中了他踏实肯干的性格。","pinyin":"Lǎobǎn kànzhòngle tā tāshi kěn gàn de xìnggé.","vi":"Ông chủ ưng tính cách chăm chỉ chịu làm của anh ấy."},{"type":"compound","zh":"虽然她看中了那套房子，但是价格实在太高了。","pinyin":"Suīrán tā kànzhòngle nà tào fángzi, dànshì jiàgé shízài tài gāo le.","vi":"Tuy cô ấy ưng căn nhà đó nhưng giá thật sự quá cao."}],"related":[{"hanzi":"看上","pinyin":"kànshàng","vi":"ưng, để mắt tới"},{"hanzi":"相中","pinyin":"xiāngzhòng","vi":"chọn trúng"},{"hanzi":"看重","pinyin":"kànzhòng","vi":"coi trọng"},{"hanzi":"中意","pinyin":"zhòngyì","vi":"vừa ý"}]},{"id":"看重","hanzi":"看重","pinyin":"kànzhòng","meaning_vi":"coi trọng, đánh giá cao","explanation":"看 (khán – nhìn nhận) + 重 (trọng – nặng, quan trọng) → coi là quan trọng, đánh giá cao giá trị của ai hay điều gì.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"⚖️","examples":[{"type":"basic","zh":"他很看重友情。","pinyin":"Tā hěn kànzhòng yǒuqíng.","vi":"Anh ấy rất coi trọng tình bạn."},{"type":"simple","zh":"这家公司更看重员工的实际能力。","pinyin":"Zhè jiā gōngsī gèng kànzhòng yuángōng de shíjì nénglì.","vi":"Công ty này coi trọng năng lực thực tế của nhân viên hơn."},{"type":"compound","zh":"如果你太看重别人的评价，就会活得很累。","pinyin":"Rúguǒ nǐ tài kànzhòng biérén de píngjià, jiù huì huó de hěn lèi.","vi":"Nếu bạn quá coi trọng đánh giá của người khác thì sẽ sống rất mệt mỏi."}],"related":[{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"看中","pinyin":"kànzhòng","vi":"ưng ý"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"}]},{"id":"抗拒","hanzi":"抗拒","pinyin":"kàngjù","meaning_vi":"kháng cự, chống lại, cưỡng lại","explanation":"抗 (kháng – chống lại) + 拒 (cự – từ chối, cự tuyệt) → chống đối, không chịu chấp nhận; như 不可抗拒 là không thể cưỡng lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"孩子抗拒去医院。","pinyin":"Háizi kàngjù qù yīyuàn.","vi":"Đứa bé không chịu đi bệnh viện."},{"type":"simple","zh":"很少有人能抗拒美食的诱惑。","pinyin":"Hěn shǎoyǒu rén néng kàngjù měishí de yòuhuò.","vi":"Hiếm ai có thể cưỡng lại sự cám dỗ của món ngon."},{"type":"compound","zh":"即使心里很抗拒，他也只好按照父母的安排去做。","pinyin":"Jíshǐ xīnlǐ hěn kàngjù, tā yě zhǐhǎo ànzhào fùmǔ de ānpái qù zuò.","vi":"Dù trong lòng rất chống đối, anh ấy cũng đành làm theo sắp đặt của bố mẹ."}],"related":[{"hanzi":"抵抗","pinyin":"dǐkàng","vi":"chống cự"},{"hanzi":"拒绝","pinyin":"jùjué","vi":"từ chối"},{"hanzi":"反抗","pinyin":"fǎnkàng","vi":"phản kháng"},{"hanzi":"接受","pinyin":"jiēshòu","vi":"chấp nhận"}]},{"id":"抗争","hanzi":"抗争","pinyin":"kàngzhēng","meaning_vi":"đấu tranh, chống trả","explanation":"抗 (kháng – chống lại) + 争 (tranh – tranh đấu) → đứng lên đấu tranh chống lại bất công, áp bức hoặc số phận.","hsk_level":"7-9","tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"他们与命运抗争。","pinyin":"Tāmen yǔ mìngyùn kàngzhēng.","vi":"Họ đấu tranh với số phận."},{"type":"simple","zh":"工人们为了合理的工资不断抗争。","pinyin":"Gōngrénmen wèile hélǐ de gōngzī búduàn kàngzhēng.","vi":"Công nhân không ngừng đấu tranh vì mức lương hợp lý."},{"type":"compound","zh":"虽然病情很严重，但是她一直在顽强地与病魔抗争。","pinyin":"Suīrán bìngqíng hěn yánzhòng, dànshì tā yìzhí zài wánqiáng de yǔ bìngmó kàngzhēng.","vi":"Tuy bệnh tình rất nặng nhưng cô ấy vẫn kiên cường chống chọi với bệnh tật."}],"related":[{"hanzi":"斗争","pinyin":"dòuzhēng","vi":"đấu tranh"},{"hanzi":"反抗","pinyin":"fǎnkàng","vi":"phản kháng"},{"hanzi":"抵抗","pinyin":"dǐkàng","vi":"chống cự"},{"hanzi":"屈服","pinyin":"qūfú","vi":"khuất phục"}],"traditional":"抗爭"},{"id":"考量","hanzi":"考量","pinyin":"kǎoliáng","meaning_vi":"cân nhắc, xem xét; sự cân nhắc","explanation":"考 (khảo – xem xét) + 量 (lượng – đo lường) → xem xét, cân nhắc kỹ các mặt trước khi quyết định.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"⚖️","examples":[{"type":"basic","zh":"这需要全面考量。","pinyin":"Zhè xūyào quánmiàn kǎoliáng.","vi":"Việc này cần cân nhắc toàn diện."},{"type":"simple","zh":"公司在选址时主要考量交通和成本。","pinyin":"Gōngsī zài xuǎnzhǐ shí zhǔyào kǎoliáng jiāotōng hé chéngběn.","vi":"Khi chọn địa điểm, công ty chủ yếu cân nhắc giao thông và chi phí."},{"type":"compound","zh":"由于台风即将到来，所以出于安全考量，主办方决定把比赛推迟到下周。","pinyin":"Yóuyú táifēng jíjiāng dàolái, suǒyǐ chūyú ānquán kǎoliáng, zhǔbànfāng juédìng bǎ bǐsài tuī chídào xiàzhōu.","vi":"Do bão sắp đến nên vì lý do an toàn, ban tổ chức quyết định hoãn trận đấu sang tuần sau."}],"related":[{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"suy xét"},{"hanzi":"衡量","pinyin":"héngliáng","vi":"cân nhắc"},{"hanzi":"权衡","pinyin":"quánhéng","vi":"cân đo"},{"hanzi":"斟酌","pinyin":"zhēnzhuó","vi":"đắn đo"}]},{"id":"烤","hanzi":"烤","pinyin":"kǎo","meaning_vi":"nướng, quay; hơ (lửa)","explanation":"烤 (khảo – nướng) → dùng lửa hoặc nhiệt làm chín thức ăn; cũng chỉ hơ cho ấm, như 烤火.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍢","examples":[{"type":"basic","zh":"我们晚上去吃烤肉。","pinyin":"Wǒmen wǎnshang qù chī kǎoròu.","vi":"Tối nay chúng ta đi ăn thịt nướng."},{"type":"simple","zh":"妈妈在烤箱里烤了一个巧克力蛋糕。","pinyin":"Māma zài kǎoxiāng lǐ kǎole yí ge qiǎokèlì dàngāo.","vi":"Mẹ nướng một chiếc bánh sô-cô-la trong lò."},{"type":"compound","zh":"如果把面包烤得太久，就会变得又干又硬。","pinyin":"Rúguǒ bǎ miànbāo kǎo de tài jiǔ, jiù huì biànde yòu gān yòu yìng.","vi":"Nếu nướng bánh mì quá lâu thì sẽ trở nên khô và cứng."}],"related":[{"hanzi":"烤鸭","pinyin":"kǎoyā","vi":"vịt quay"},{"hanzi":"烧烤","pinyin":"shāokǎo","vi":"đồ nướng"},{"hanzi":"烤箱","pinyin":"kǎoxiāng","vi":"lò nướng"},{"hanzi":"煎","pinyin":"jiān","vi":"rán"}]},{"id":"科幻","hanzi":"科幻","pinyin":"kēhuàn","meaning_vi":"khoa học viễn tưởng","explanation":"科 (khoa – khoa học) + 幻 (huyễn – ảo tưởng) → viết tắt của 科学幻想, thể loại tác phẩm tưởng tượng dựa trên khoa học.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"👽","examples":[{"type":"basic","zh":"他爱看科幻小说。","pinyin":"Tā ài kàn kēhuàn xiǎoshuō.","vi":"Anh ấy thích đọc tiểu thuyết khoa học viễn tưởng."},{"type":"simple","zh":"这部科幻电影讲的是人类移民火星的故事。","pinyin":"Zhè bù kēhuàn diànyǐng jiǎng de shì rénlèi yímín huǒxīng de gùshi.","vi":"Bộ phim khoa học viễn tưởng này kể chuyện loài người di cư lên sao Hỏa."},{"type":"compound","zh":"很多过去只出现在科幻作品里的技术，如今已经变成了现实。","pinyin":"Hěn duō guòqù zhǐ chū xiànzài kēhuàn zuòpǐn lǐ de jìshù, rújīn yǐjīng biàn chéngle xiànshí.","vi":"Nhiều công nghệ trước đây chỉ có trong tác phẩm viễn tưởng, nay đã thành hiện thực."}],"related":[{"hanzi":"幻想","pinyin":"huànxiǎng","vi":"ảo tưởng"},{"hanzi":"科学","pinyin":"kēxué","vi":"khoa học"},{"hanzi":"外星人","pinyin":"wàixīngrén","vi":"người ngoài hành tinh"},{"hanzi":"奇幻","pinyin":"qíhuàn","vi":"kỳ ảo"}]},{"id":"壳","hanzi":"壳","pinyin":"ké","meaning_vi":"vỏ, mai, vỏ cứng","explanation":"壳 (xác – vỏ cứng) → lớp vỏ cứng bọc bên ngoài như vỏ trứng, mai rùa; khẩu ngữ đọc ké, văn viết đọc qiào như 地壳.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🐚","examples":[{"type":"basic","zh":"鸡蛋壳很薄。","pinyin":"Jīdàn ké hěn báo.","vi":"Vỏ trứng gà rất mỏng."},{"type":"simple","zh":"小乌龟把头缩进了壳里。","pinyin":"Xiǎo wūguī bǎ tóu suōjìnle ké lǐ.","vi":"Chú rùa con rụt đầu vào trong mai."},{"type":"compound","zh":"如果手机壳太厚，就会影响散热。","pinyin":"Rúguǒ shǒujīké tài hòu, jiù huì yǐngxiǎng sànrè.","vi":"Nếu ốp điện thoại quá dày thì sẽ ảnh hưởng tản nhiệt."}],"related":[{"hanzi":"贝壳","pinyin":"bèiké","vi":"vỏ sò"},{"hanzi":"外壳","pinyin":"wàiké","vi":"vỏ ngoài"},{"hanzi":"蛋壳","pinyin":"dànké","vi":"vỏ trứng"},{"hanzi":"地壳","pinyin":"dìqiào","vi":"vỏ Trái Đất"}],"traditional":"殼"},{"id":"可悲","hanzi":"可悲","pinyin":"kěbēi","meaning_vi":"đáng buồn, đáng thương, bi đát","explanation":"可 (khả – đáng) + 悲 (bi – buồn thương) → đáng để buồn, đáng thương xót; thường mang ý phê phán.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"这真是可悲。","pinyin":"Zhè zhēn shì kěbēi.","vi":"Điều này thật đáng buồn."},{"type":"simple","zh":"最可悲的是他至今还没认识到自己的错误。","pinyin":"Zuì kěbēi de shì tā zhìjīn hái méi rènshi dào zìjǐ de cuòwù.","vi":"Đáng buồn nhất là đến giờ anh ta vẫn chưa nhận ra lỗi của mình."},{"type":"compound","zh":"虽然他很有钱，但是连一个真心朋友都没有，实在可悲。","pinyin":"Suīrán tā hěn yǒuqián, dànshì lián yí ge zhēnxīn péngyou dōu méiyǒu, shízài kěbēi.","vi":"Tuy rất giàu nhưng đến một người bạn thật lòng cũng không có, thật đáng buồn."}],"related":[{"hanzi":"可怜","pinyin":"kělián","vi":"đáng thương"},{"hanzi":"悲哀","pinyin":"bēi'āi","vi":"bi ai"},{"hanzi":"可惜","pinyin":"kěxī","vi":"đáng tiếc"},{"hanzi":"可喜","pinyin":"kěxǐ","vi":"đáng mừng"}]},{"id":"可不是","hanzi":"可不是","pinyin":"kěbushì","meaning_vi":"đúng vậy, chứ còn gì nữa","explanation":"可 (khả – nhấn mạnh) + 不是 (bất thị – chẳng phải) → chẳng phải thế sao; khẩu ngữ, dùng để đồng tình mạnh với người nói trước.","hsk_level":"7-9","tags":["pho-tu","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"可不是嘛，太贵了！","pinyin":"Kěbushì ma, tài guì le!","vi":"Đúng thế, đắt quá đi!"},{"type":"simple","zh":"可不是，今年夏天热得出奇。","pinyin":"Kěbushì, jīnnián xiàtiān rè de chūqí.","vi":"Chứ còn gì nữa, mùa hè năm nay nóng lạ thường."},{"type":"compound","zh":"你说他最近瘦了？可不是，因为工作太忙，所以他天天加班。","pinyin":"Nǐ shuō tā zuìjìn shòu le? kěbushì, yīnwèi gōngzuò tài máng, suǒyǐ tā tiāntiān jiābān.","vi":"Bạn bảo dạo này anh ấy gầy đi à? Đúng vậy, vì công việc quá bận nên ngày nào anh ấy cũng tăng ca."}],"related":[{"hanzi":"可不","pinyin":"kěbu","vi":"đúng thế"},{"hanzi":"就是","pinyin":"jiùshì","vi":"đúng vậy"},{"hanzi":"没错","pinyin":"méicuò","vi":"không sai"},{"hanzi":"当然","pinyin":"dāngrán","vi":"đương nhiên"}]},{"id":"可乘之机","hanzi":"可乘之机","pinyin":"kěchéng-zhījī","meaning_vi":"kẽ hở để lợi dụng, cơ hội để thừa cơ","explanation":"可 (khả – có thể) + 乘 (thừa – lợi dụng) + 之 (chi – của) + 机 (cơ – cơ hội) → cơ hội mà đối phương có thể lợi dụng; hay dùng 给…可乘之机.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕳️","examples":[{"type":"basic","zh":"不要给小偷可乘之机。","pinyin":"Bú yào gěi xiǎotōu kěchéngzhījī.","vi":"Đừng tạo kẽ hở cho kẻ trộm lợi dụng."},{"type":"simple","zh":"系统漏洞给黑客留下了可乘之机。","pinyin":"Xìtǒng lòudòng gěi hēikè liúxiàle kěchéngzhījī.","vi":"Lỗ hổng hệ thống tạo kẽ hở cho tin tặc lợi dụng."},{"type":"compound","zh":"如果管理制度不严格，就会给不法分子可乘之机。","pinyin":"Rúguǒ guǎnlǐ zhìdù bù yángé, jiù huì gěi bùfǎ fènzǐ kěchéngzhījī.","vi":"Nếu chế độ quản lý không chặt chẽ thì sẽ tạo kẽ hở cho phần tử phạm pháp."}],"related":[{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"},{"hanzi":"乘机","pinyin":"chéngjī","vi":"thừa cơ"},{"hanzi":"趁虚而入","pinyin":"chènxū'érrù","vi":"thừa lúc sơ hở mà vào"},{"hanzi":"机会","pinyin":"jīhuì","vi":"cơ hội"}],"traditional":"可乘之機"},{"id":"可耻","hanzi":"可耻","pinyin":"kěchǐ","meaning_vi":"đáng xấu hổ, nhục nhã, đáng khinh","explanation":"可 (khả – đáng) + 耻 (sỉ – xấu hổ, nhục) → đáng phải hổ thẹn; dùng để lên án hành vi sai trái.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"说谎是可耻的。","pinyin":"Shuōhuǎng shì kěchǐ de.","vi":"Nói dối là đáng xấu hổ."},{"type":"simple","zh":"他背叛朋友的行为实在太可耻了。","pinyin":"Tā bèipàn péngyou de xíngwéi shízài tài kěchǐ le.","vi":"Hành vi phản bội bạn bè của hắn thật quá đáng khinh."},{"type":"compound","zh":"失败并不可耻，可耻的是因为害怕失败而不敢尝试。","pinyin":"Shībài bìngbù kěchǐ, kěchǐ de shì yīnwèi hàipà shībài ér bù gǎn chángshì.","vi":"Thất bại không đáng xấu hổ, đáng xấu hổ là vì sợ thất bại mà không dám thử."}],"related":[{"hanzi":"羞耻","pinyin":"xiūchǐ","vi":"xấu hổ"},{"hanzi":"无耻","pinyin":"wúchǐ","vi":"vô liêm sỉ"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vẻ vang"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"}],"traditional":"可恥"},{"id":"可谓","hanzi":"可谓","pinyin":"kěwèi","meaning_vi":"có thể nói là, quả là","explanation":"可 (khả – có thể) + 谓 (vị – gọi là, nói) → có thể nói là; văn viết, dùng để đánh giá, tổng kết.","hsk_level":"7-9","tags":["dong-tu"],"image":"💬","examples":[{"type":"basic","zh":"此次活动可谓成功。","pinyin":"Cǐcì huódòng kěwèi chénggōng.","vi":"Hoạt động lần này có thể nói là thành công."},{"type":"simple","zh":"这场比赛可谓本届最精彩的一场。","pinyin":"Zhè chǎng bǐsài kěwèi běnjiè zuì jīngcǎi de yì chǎng.","vi":"Trận đấu này có thể nói là hay nhất mùa giải."},{"type":"compound","zh":"虽然只用了三年，但是这家公司的发展可谓神速。","pinyin":"Suīrán zhǐ yòngle sān nián, dànshì zhè jiā gōngsī de fāzhǎn kěwèi shénsù.","vi":"Tuy chỉ mất ba năm nhưng sự phát triển của công ty này quả là thần tốc."}],"related":[{"hanzi":"堪称","pinyin":"kānchēng","vi":"xứng đáng gọi là"},{"hanzi":"所谓","pinyin":"suǒwèi","vi":"cái gọi là"},{"hanzi":"称得上","pinyin":"chēngdeshàng","vi":"đáng gọi là"},{"hanzi":"简直","pinyin":"jiǎnzhí","vi":"quả thật"}],"traditional":"可謂"},{"id":"可笑","hanzi":"可笑","pinyin":"kěxiào","meaning_vi":"buồn cười, nực cười, lố bịch","explanation":"可 (khả – đáng) + 笑 (tiếu – cười) → đáng để cười; có thể là hài hước hoặc mang ý chê là lố bịch.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😆","examples":[{"type":"basic","zh":"他的想法真可笑。","pinyin":"Tā de xiǎngfǎ zhēn kěxiào.","vi":"Suy nghĩ của anh ta thật nực cười."},{"type":"simple","zh":"现在想起来，当时的担心实在可笑。","pinyin":"Xiànzài xiǎngqǐlái, dāngshí de dānxīn shízài kěxiào.","vi":"Bây giờ nghĩ lại, nỗi lo lúc đó thật buồn cười."},{"type":"compound","zh":"虽然这个借口很可笑，但是他说得一本正经。","pinyin":"Suīrán zhè ge jièkǒu hěn kěxiào, dànshì tā shuō de yì běn zhèngjīng.","vi":"Tuy cái cớ này rất nực cười nhưng anh ta nói rất nghiêm túc."}],"related":[{"hanzi":"好笑","pinyin":"hǎoxiào","vi":"buồn cười"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"đáng yêu"},{"hanzi":"荒唐","pinyin":"huāngtáng","vi":"hoang đường"},{"hanzi":"滑稽","pinyin":"huájī","vi":"khôi hài"}]},{"id":"可信","hanzi":"可信","pinyin":"kěxìn","meaning_vi":"đáng tin, có thể tin được","explanation":"可 (khả – có thể) + 信 (tín – tin) → có thể tin được; dùng cho lời nói, tin tức, nguồn số liệu hoặc con người.","hsk_level":"7-9","tags":["tinh-tu","nhan-thuc"],"image":"🤝","examples":[{"type":"basic","zh":"这个消息可信吗？","pinyin":"Zhè ge xiāoxi kěxìn ma?","vi":"Tin này có đáng tin không?"},{"type":"simple","zh":"专家认为这份调查报告的数据可信。","pinyin":"Zhuānjiā rènwéi zhè fèn diàochá bàogào de shùjù kěxìn.","vi":"Chuyên gia cho rằng số liệu của báo cáo điều tra này đáng tin cậy."},{"type":"compound","zh":"因为他从来不说假话，所以他的话很可信。","pinyin":"Yīnwèi tā cóngláibù shuō jiǎhuà, suǒyǐ tā dehuà hěn kěxìn.","vi":"Vì anh ấy chưa bao giờ nói dối nên lời anh ấy rất đáng tin."}],"related":[{"hanzi":"可靠","pinyin":"kěkào","vi":"đáng tin cậy"},{"hanzi":"信任","pinyin":"xìnrèn","vi":"tin tưởng"},{"hanzi":"可疑","pinyin":"kěyí","vi":"đáng ngờ"},{"hanzi":"诚信","pinyin":"chéngxìn","vi":"chữ tín"}]},{"id":"可疑","hanzi":"可疑","pinyin":"kěyí","meaning_vi":"khả nghi, đáng ngờ","explanation":"可 (khả – đáng) + 疑 (nghi – ngờ vực) → đáng để nghi ngờ; hay dùng cho người, hành vi, đồ vật lạ.","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"门口有个可疑的人。","pinyin":"Ménkǒu yǒu ge kěyí de rén.","vi":"Ở cửa có một người khả nghi."},{"type":"simple","zh":"保安发现了一个没人认领的可疑包裹。","pinyin":"Bǎo'ān fāxiànle yí ge méi rén rènlǐng de kěyí bāoguǒ.","vi":"Bảo vệ phát hiện một kiện hàng khả nghi không ai nhận."},{"type":"compound","zh":"如果看到可疑的情况，就马上打电话报警。","pinyin":"Rúguǒ kàndào kěyí de qíngkuàng, jiù mǎshàng dǎdiànhuà bàojǐng.","vi":"Nếu thấy tình huống khả nghi thì lập tức gọi điện báo cảnh sát."}],"related":[{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"},{"hanzi":"可信","pinyin":"kěxìn","vi":"đáng tin"},{"hanzi":"嫌疑","pinyin":"xiányí","vi":"hiềm nghi"},{"hanzi":"疑点","pinyin":"yídiǎn","vi":"điểm đáng ngờ"}]},{"id":"客房","hanzi":"客房","pinyin":"kèfáng","meaning_vi":"phòng nghỉ (khách sạn), phòng cho khách ở","explanation":"客 (khách – khách) + 房 (phòng – căn phòng) → phòng dành cho khách ngủ lại, ở nhà riêng hoặc khách sạn.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🛏️","examples":[{"type":"basic","zh":"客房已经打扫好了。","pinyin":"Kèfáng yǐjīng dǎsǎo hǎo le.","vi":"Phòng nghỉ cho khách đã được dọn dẹp xong."},{"type":"simple","zh":"这家酒店一共有三百多间客房。","pinyin":"Zhè jiā jiǔdiàn yí gòngyǒu sān bǎi duō jiān kèfáng.","vi":"Khách sạn này có tổng cộng hơn ba trăm phòng."},{"type":"compound","zh":"因为正赶上旅游旺季，所以酒店的客房全满了。","pinyin":"Yīnwèi zhèng gǎnshàng lǚyóu wàngjì, suǒyǐ jiǔdiàn de kèfáng quán mǎn le.","vi":"Vì đúng vào mùa du lịch cao điểm nên phòng khách sạn đã kín hết."}],"related":[{"hanzi":"酒店","pinyin":"jiǔdiàn","vi":"khách sạn"},{"hanzi":"房间","pinyin":"fángjiān","vi":"căn phòng"},{"hanzi":"客厅","pinyin":"kètīng","vi":"phòng khách (sinh hoạt)"},{"hanzi":"标准间","pinyin":"biāozhǔnjiān","vi":"phòng tiêu chuẩn"}]},{"id":"客机","hanzi":"客机","pinyin":"kèjī","meaning_vi":"máy bay chở khách","explanation":"客 (khách – hành khách) + 机 (cơ – máy, máy bay) → máy bay dùng để chở hành khách, khác với máy bay chở hàng hay quân sự.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"✈️","examples":[{"type":"basic","zh":"一架客机起飞了。","pinyin":"Yí jià kèjī qǐfēi le.","vi":"Một chiếc máy bay chở khách đã cất cánh."},{"type":"simple","zh":"这种大型客机可以坐五百多名乘客。","pinyin":"Zhè zhǒng dàxíng kèjī kěyǐ zuò wǔ bǎi duō míng chéngkè.","vi":"Loại máy bay chở khách cỡ lớn này chở được hơn năm trăm hành khách."},{"type":"compound","zh":"虽然遇到了强气流，但是客机还是安全降落了。","pinyin":"Suīrán yùdàole qiáng qìliú, dànshì kèjī háishì ānquán jiàngluò le.","vi":"Tuy gặp luồng khí mạnh nhưng máy bay chở khách vẫn hạ cánh an toàn."}],"related":[{"hanzi":"飞机","pinyin":"fēijī","vi":"máy bay"},{"hanzi":"航班","pinyin":"hángbān","vi":"chuyến bay"},{"hanzi":"货机","pinyin":"huòjī","vi":"máy bay chở hàng"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"sân bay"}],"traditional":"客機"},{"id":"恳求","hanzi":"恳求","pinyin":"kěnqiú","meaning_vi":"khẩn cầu, van nài, nài nỉ","explanation":"恳 (khẩn – thành khẩn) + 求 (cầu – xin) → tha thiết xin người khác làm hay tha thứ điều gì.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"她恳求父母原谅。","pinyin":"Tā kěnqiú fùmǔ yuánliàng.","vi":"Cô ấy khẩn cầu bố mẹ tha thứ."},{"type":"simple","zh":"他红着眼睛恳求医生救救他的孩子。","pinyin":"Tā hóng zheyǎn jing kěnqiú yīshēng jiù jiu tā de háizi.","vi":"Anh ấy đỏ hoe mắt van xin bác sĩ cứu lấy con mình."},{"type":"compound","zh":"尽管他一再恳求，老板也没有改变主意。","pinyin":"Jǐnguǎn tā yízài kěnqiú, lǎobǎn yě méiyǒu gǎibiàn zhǔyi.","vi":"Dù anh ấy năn nỉ hết lần này đến lần khác, ông chủ vẫn không đổi ý."}],"related":[{"hanzi":"请求","pinyin":"qǐngqiú","vi":"thỉnh cầu"},{"hanzi":"哀求","pinyin":"āiqiú","vi":"van xin"},{"hanzi":"诚恳","pinyin":"chéngkěn","vi":"thành khẩn"},{"hanzi":"要求","pinyin":"yāoqiú","vi":"yêu cầu"}],"traditional":"懇求"},{"id":"空荡荡","hanzi":"空荡荡","pinyin":"kōngdàngdàng","meaning_vi":"trống trơn, vắng tanh, trống trải","explanation":"空 (không – trống) + 荡荡 (đãng đãng – mênh mang) → trống rỗng hoàn toàn, không có người hay đồ vật.","hsk_level":"7-9","tags":["tinh-tu","dia-diem"],"image":"🏚️","examples":[{"type":"basic","zh":"教室里空荡荡的。","pinyin":"Jiàoshì li kōngdàngdàng de.","vi":"Trong lớp học trống trơn."},{"type":"simple","zh":"孩子们都走了，家里一下子变得空荡荡的。","pinyin":"Háizimen dōu zǒu le, jiāli yíxiàzi biànde kōngdàngdàng de.","vi":"Bọn trẻ đi hết, trong nhà bỗng trở nên trống trải."},{"type":"compound","zh":"因为大家都回家过年了，所以街上空荡荡的。","pinyin":"Yīnwèi dàjiā dōu huíjiā guònián le, suǒyǐ jiēshang kōngdàngdàng de.","vi":"Vì mọi người đều về quê ăn Tết nên đường phố vắng tanh."}],"related":[{"hanzi":"空旷","pinyin":"kōngkuàng","vi":"trống trải"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng vẻ"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"},{"hanzi":"空空","pinyin":"kōngkōng","vi":"trống không"}],"traditional":"空蕩蕩"},{"id":"空地","hanzi":"空地","pinyin":"kòngdì","meaning_vi":"bãi đất trống, khoảng trống","explanation":"空 (không – trống, đọc kòng) + 地 (địa – đất) → mảnh đất bỏ trống chưa xây dựng hay sử dụng.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🟫","examples":[{"type":"basic","zh":"楼前有一块空地。","pinyin":"Lóu qián yǒu yíkuài kòngdì.","vi":"Trước tòa nhà có một bãi đất trống."},{"type":"simple","zh":"孩子们放学后常在这块空地上踢球。","pinyin":"Háizimen fàngxué hòu cháng zài zhè kuài kòngdì shang tī qiú.","vi":"Bọn trẻ tan học thường đá bóng trên bãi đất trống này."},{"type":"compound","zh":"如果把这片空地利用起来，就可以建一个小公园。","pinyin":"Rúguǒ bǎ zhè piàn kòngdì lìyòng qǐlái, jiù kěyǐ jiàn yí ge xiǎo gōngyuán.","vi":"Nếu tận dụng bãi đất trống này thì có thể xây một công viên nhỏ."}],"related":[{"hanzi":"空间","pinyin":"kōngjiān","vi":"không gian"},{"hanzi":"空儿","pinyin":"kòngr","vi":"lúc rảnh, chỗ trống"},{"hanzi":"广场","pinyin":"guǎngchǎng","vi":"quảng trường"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"}]},{"id":"空难","hanzi":"空难","pinyin":"kōngnàn","meaning_vi":"tai nạn máy bay, thảm họa hàng không","explanation":"空 (không – trên không) + 难 (nạn – tai nạn) → tai nạn xảy ra với máy bay trên không hoặc khi cất hạ cánh.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"💥","examples":[{"type":"basic","zh":"空难很少发生。","pinyin":"Kōngnàn hěn shǎo fāshēng.","vi":"Tai nạn máy bay rất hiếm khi xảy ra."},{"type":"simple","zh":"这次空难造成了一百多人遇难。","pinyin":"Zhè cì kōngnàn zào chéngle yī bǎi duō rén yùnàn.","vi":"Vụ tai nạn máy bay lần này làm hơn một trăm người thiệt mạng."},{"type":"compound","zh":"虽然空难的概率很低，但是她还是不敢坐飞机。","pinyin":"Suīrán kōngnàn de gàilǜ hěn dī, dànshì tā háishì bù gǎn zuòfēijī.","vi":"Tuy xác suất tai nạn máy bay rất thấp nhưng cô ấy vẫn không dám đi máy bay."}],"related":[{"hanzi":"车祸","pinyin":"chēhuò","vi":"tai nạn giao thông"},{"hanzi":"灾难","pinyin":"zāinàn","vi":"thảm họa"},{"hanzi":"遇难","pinyin":"yùnàn","vi":"gặp nạn"},{"hanzi":"客机","pinyin":"kèjī","vi":"máy bay chở khách"}],"traditional":"空難"},{"id":"恐慌","hanzi":"恐慌","pinyin":"kǒnghuāng","meaning_vi":"hoảng loạn, hoang mang, khủng hoảng tâm lý","explanation":"恐 (khủng – sợ) + 慌 (hoảng – cuống, rối) → sợ hãi đến mức rối loạn, thường dùng cho tâm lý đám đông.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"大家不要恐慌。","pinyin":"Dàjiā bú yào kǒnghuāng.","vi":"Mọi người đừng hoảng loạn."},{"type":"simple","zh":"这条假消息在网上引起了很大的恐慌。","pinyin":"Zhè tiáo jiǎ xiāoxi zài wǎngshang yǐnqǐle hěn dà de kǒnghuāng.","vi":"Tin giả này đã gây ra sự hoang mang lớn trên mạng."},{"type":"compound","zh":"一旦人们陷入恐慌，就会出现抢购的现象。","pinyin":"Yídàn rénmen xiànrù kǒnghuāng, jiù huì chūxiàn qiǎnggòu de xiànxiàng.","vi":"Một khi mọi người rơi vào hoảng loạn thì sẽ xảy ra hiện tượng tranh mua."}],"related":[{"hanzi":"惊慌","pinyin":"jīnghuāng","vi":"hoảng hốt"},{"hanzi":"恐惧","pinyin":"kǒngjù","vi":"sợ hãi"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"慌张","pinyin":"huāngzhāng","vi":"luống cuống"}]},{"id":"恐龙","hanzi":"恐龙","pinyin":"kǒnglóng","meaning_vi":"khủng long","explanation":"恐 (khủng – đáng sợ) + 龙 (long – rồng) → loài bò sát khổng lồ thời tiền sử trông như rồng đáng sợ.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦖","examples":[{"type":"basic","zh":"恐龙早就灭绝了。","pinyin":"Kǒnglóng zǎojiù mièjué le.","vi":"Khủng long đã tuyệt chủng từ lâu."},{"type":"simple","zh":"我儿子特别喜欢看有关恐龙的书。","pinyin":"Wǒ érzi tèbié xǐhuan kàn yǒuguān kǒnglóng de shū.","vi":"Con trai tôi đặc biệt thích đọc sách về khủng long."},{"type":"compound","zh":"虽然恐龙已经消失了，但是科学家找到了很多它们的化石。","pinyin":"Suīrán kǒnglóng yǐjīng xiāoshī le, dànshì kēxuéjiā zhǎodàole hěn duō tāmen de huàshí.","vi":"Tuy khủng long đã biến mất nhưng các nhà khoa học tìm được rất nhiều hóa thạch của chúng."}],"related":[{"hanzi":"化石","pinyin":"huàshí","vi":"hóa thạch"},{"hanzi":"灭绝","pinyin":"mièjué","vi":"tuyệt chủng"},{"hanzi":"龙","pinyin":"lóng","vi":"rồng"},{"hanzi":"博物馆","pinyin":"bówùguǎn","vi":"bảo tàng"}],"traditional":"恐龍"},{"id":"控告","hanzi":"控告","pinyin":"kònggào","meaning_vi":"tố cáo, khởi kiện, buộc tội","explanation":"控 (khống – tố cáo) + 告 (cáo – báo, kiện) → đưa đơn lên cơ quan pháp luật để buộc tội ai đó.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他控告了那家公司。","pinyin":"Tā kònggàole nà jiā gōngsī.","vi":"Anh ấy đã khởi kiện công ty đó."},{"type":"simple","zh":"几名员工联名控告经理违法解雇他们。","pinyin":"Jǐ míng yuángōng liánmíng kònggào jīnglǐ wéifǎ jiěgù tāmen.","vi":"Mấy nhân viên cùng ký tên tố cáo giám đốc sa thải họ trái luật."},{"type":"compound","zh":"如果对方继续侵权，我们就到法院去控告他。","pinyin":"Rúguǒ duìfāng jìxù qīnquán, wǒmen jiù dào fǎyuàn qù kònggào tā.","vi":"Nếu bên kia tiếp tục xâm phạm quyền lợi thì chúng tôi sẽ ra tòa kiện họ."}],"related":[{"hanzi":"起诉","pinyin":"qǐsù","vi":"khởi tố"},{"hanzi":"指控","pinyin":"zhǐkòng","vi":"cáo buộc"},{"hanzi":"举报","pinyin":"jǔbào","vi":"tố giác"},{"hanzi":"被告","pinyin":"bèigào","vi":"bị cáo"}]},{"id":"抠","hanzi":"抠","pinyin":"kōu","meaning_vi":"moi, khều, cạy; keo kiệt","explanation":"抠 (khu – moi, móc) → dùng ngón tay hay vật nhọn moi móc ra; khẩu ngữ còn chỉ người keo kiệt (很抠).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"👆","examples":[{"type":"basic","zh":"别抠鼻子！","pinyin":"Bié kōu bízi!","vi":"Đừng ngoáy mũi!"},{"type":"simple","zh":"他用手指把卡在缝里的硬币抠了出来。","pinyin":"Tāyòng shǒuzhǐ bǎ qiǎ zài fèng li de yìngbì kōule chūlái.","vi":"Anh ấy dùng ngón tay khều đồng xu kẹt trong khe ra."},{"type":"compound","zh":"虽然他挣得不少，但是花钱特别抠。","pinyin":"Suīrán tā zhèngde bùshǎo, dànshì huāqián tèbié kōu.","vi":"Tuy anh ta kiếm được không ít nhưng tiêu tiền cực kỳ keo kiệt."}],"related":[{"hanzi":"挖","pinyin":"wā","vi":"đào, moi"},{"hanzi":"小气","pinyin":"xiǎoqi","vi":"keo kiệt"},{"hanzi":"吝啬","pinyin":"lìnsè","vi":"bủn xỉn"},{"hanzi":"抠门儿","pinyin":"kōuménr","vi":"hà tiện"}],"traditional":"摳"},{"id":"口吃","hanzi":"口吃","pinyin":"kǒuchī","meaning_vi":"nói lắp, cà lăm","explanation":"口 (khẩu – miệng) + 吃 (ngật – nói lắp) → nói không trôi chảy, hay lặp âm hoặc ngắc ngứ.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🗣️","examples":[{"type":"basic","zh":"他从小就口吃。","pinyin":"Tā cóngxiǎo jiù kǒuchī.","vi":"Cậu ấy bị nói lắp từ nhỏ."},{"type":"simple","zh":"经过长时间的练习，他口吃的毛病好多了。","pinyin":"Jīngguò cháng shíjiān de liànxí, tā kǒuchī de máobìng hǎoduō le.","vi":"Qua thời gian dài luyện tập, tật nói lắp của anh ấy đã đỡ nhiều."},{"type":"compound","zh":"虽然他有点儿口吃，但是演讲时非常自信。","pinyin":"Suīrán tā yǒudiǎnr kǒuchī, dànshì yǎnjiǎng shí fēicháng zìxìn.","vi":"Tuy anh ấy hơi nói lắp nhưng khi diễn thuyết lại rất tự tin."}],"related":[{"hanzi":"结巴","pinyin":"jiēba","vi":"nói lắp"},{"hanzi":"流利","pinyin":"liúlì","vi":"lưu loát"},{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"},{"hanzi":"说话","pinyin":"shuōhuà","vi":"nói chuyện"}]},{"id":"口感","hanzi":"口感","pinyin":"kǒugǎn","meaning_vi":"cảm giác khi ăn, độ ngon miệng, kết cấu món ăn","explanation":"口 (khẩu – miệng) + 感 (cảm – cảm giác) → cảm giác trong miệng khi ăn uống: giòn, mềm, dai, mịn…","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"😋","examples":[{"type":"basic","zh":"这种面包口感很软。","pinyin":"Zhè zhǒng miànbāo kǒugǎn hěn ruǎn.","vi":"Loại bánh mì này ăn rất mềm."},{"type":"simple","zh":"这款酸奶口感细腻，很受年轻人欢迎。","pinyin":"Zhè kuǎn suānnǎi kǒugǎn xìnì, hěn shòu niánqīngrén huānyíng.","vi":"Loại sữa chua này mịn miệng, rất được giới trẻ ưa chuộng."},{"type":"compound","zh":"如果米饭煮得太久，口感就会变差。","pinyin":"Rúguǒ mǐfàn zhǔ de tài jiǔ, kǒugǎn jiù huì biàn chà.","vi":"Nếu cơm nấu quá lâu thì ăn sẽ mất ngon."}],"related":[{"hanzi":"味道","pinyin":"wèidao","vi":"mùi vị"},{"hanzi":"口味","pinyin":"kǒuwèi","vi":"khẩu vị"},{"hanzi":"香脆","pinyin":"xiāngcuì","vi":"thơm giòn"},{"hanzi":"嚼劲","pinyin":"jiáojìn","vi":"độ dai"}]},{"id":"口径","hanzi":"口径","pinyin":"kǒujìng","meaning_vi":"cỡ nòng, đường kính miệng; quan điểm, cách nói thống nhất","explanation":"口 (khẩu – miệng) + 径 (kính – đường kính) → đường kính miệng ống, nòng súng; nghĩa bóng: lập trường, cách phát ngôn chung.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🎯","examples":[{"type":"basic","zh":"大家要统一口径。","pinyin":"Dàjiā yào tǒngyī kǒujìng.","vi":"Mọi người phải thống nhất cách nói."},{"type":"simple","zh":"这种水管的口径比普通的大一倍。","pinyin":"Zhè zhǒng shuǐguǎn de kǒujìng bǐ pǔtōng de dàyí bèi.","vi":"Loại ống nước này có đường kính lớn gấp đôi loại thường."},{"type":"compound","zh":"如果各部门说法口径不一，就会让客户产生怀疑。","pinyin":"Rúguǒ gè bùmén shuōfǎ kǒujìng bù yī, jiù huì ràng kèhù chǎnshēng huáiyí.","vi":"Nếu các bộ phận nói mỗi người một kiểu thì sẽ khiến khách hàng sinh nghi."}],"related":[{"hanzi":"直径","pinyin":"zhíjìng","vi":"đường kính"},{"hanzi":"说法","pinyin":"shuōfǎ","vi":"cách nói"},{"hanzi":"立场","pinyin":"lìchǎng","vi":"lập trường"},{"hanzi":"统一","pinyin":"tǒngyī","vi":"thống nhất"}],"traditional":"口徑"},{"id":"口令","hanzi":"口令","pinyin":"kǒulìng","meaning_vi":"khẩu lệnh; mật khẩu","explanation":"口 (khẩu – miệng) + 令 (lệnh – mệnh lệnh) → mệnh lệnh hô bằng miệng; cũng là mật khẩu, ám hiệu để xác nhận.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🔑","examples":[{"type":"basic","zh":"请输入口令。","pinyin":"Qǐng shūrù kǒulìng.","vi":"Vui lòng nhập mật khẩu."},{"type":"simple","zh":"教官一喊口令，大家就立刻站好了队。","pinyin":"Jiàoguān yì hǎn kǒulìng, dàjiā jiù lìkè zhàn hǎole duì.","vi":"Huấn luyện viên vừa hô khẩu lệnh, mọi người lập tức đứng vào hàng."},{"type":"compound","zh":"如果说不出口令，哨兵就不让你进去。","pinyin":"Rúguǒ shuōbuchū kǒulìng, shàobīng jiù bú ràng nǐ jìnqù.","vi":"Nếu không nói được mật khẩu thì lính gác sẽ không cho vào."}],"related":[{"hanzi":"命令","pinyin":"mìnglìng","vi":"mệnh lệnh"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"mật mã"},{"hanzi":"暗号","pinyin":"ànhào","vi":"ám hiệu"},{"hanzi":"指令","pinyin":"zhǐlìng","vi":"chỉ lệnh"}]},{"id":"口哨","hanzi":"口哨","pinyin":"kǒushào","meaning_vi":"huýt sáo, tiếng huýt sáo","explanation":"口 (khẩu – miệng) + 哨 (tiếu – còi) → tiếng còi phát ra bằng miệng; hay dùng 吹口哨.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"😗","examples":[{"type":"basic","zh":"他会吹口哨。","pinyin":"Tā huì chuīkǒushào.","vi":"Anh ấy biết huýt sáo."},{"type":"simple","zh":"他一边洗车，一边吹着口哨。","pinyin":"Tā yìbiān xǐchē, yìbiān chuīzhe kǒushào.","vi":"Anh ấy vừa rửa xe vừa huýt sáo."},{"type":"compound","zh":"因为考试考得很好，所以他一路吹着口哨回了家。","pinyin":"Yīnwèi kǎoshì kǎo de hěn hǎo, suǒyǐ tā yílù chuīzhe kǒushào huíle jiā.","vi":"Vì thi rất tốt nên cậu ấy huýt sáo suốt dọc đường về nhà."}],"related":[{"hanzi":"哨子","pinyin":"shàozi","vi":"cái còi"},{"hanzi":"吹","pinyin":"chuī","vi":"thổi"},{"hanzi":"口琴","pinyin":"kǒuqín","vi":"kèn harmonica"},{"hanzi":"哨声","pinyin":"shàoshēng","vi":"tiếng còi"}]},{"id":"口水","hanzi":"口水","pinyin":"kǒushuǐ","meaning_vi":"nước bọt, nước miếng","explanation":"口 (khẩu – miệng) + 水 (thủy – nước) → nước trong miệng; 流口水 còn chỉ thèm thuồng.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🤤","examples":[{"type":"basic","zh":"宝宝流口水了。","pinyin":"Bǎobao liúkǒushuǐ le.","vi":"Em bé chảy nước dãi rồi."},{"type":"simple","zh":"一闻到烤肉的香味，我就忍不住流口水。","pinyin":"Yì wéndào kǎoròu de xiāngwèi, wǒ jiù rěnbúzhù liúkǒushuǐ.","vi":"Vừa ngửi thấy mùi thịt nướng, tôi đã không nhịn được chảy nước miếng."},{"type":"compound","zh":"虽然他说得口水都干了，但是对方还是不同意。","pinyin":"Suīrán tā shuō de kǒushuǐ dōu gān le, dànshì duìfāng háishì bù tóngyì.","vi":"Tuy anh ấy nói đến khô cả nước bọt nhưng đối phương vẫn không đồng ý."}],"related":[{"hanzi":"唾液","pinyin":"tuòyè","vi":"nước bọt"},{"hanzi":"流口水","pinyin":"liúkǒushuǐ","vi":"chảy nước miếng"},{"hanzi":"嘴巴","pinyin":"zuǐba","vi":"miệng"},{"hanzi":"馋","pinyin":"chán","vi":"thèm"}]},{"id":"口香糖","hanzi":"口香糖","pinyin":"kǒuxiāngtáng","meaning_vi":"kẹo cao su","explanation":"口 (khẩu – miệng) + 香 (hương – thơm) + 糖 (đường – kẹo) → kẹo nhai cho thơm miệng.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍬","examples":[{"type":"basic","zh":"我嚼着口香糖。","pinyin":"Wǒ jiáozhe kǒuxiāngtáng.","vi":"Tôi đang nhai kẹo cao su."},{"type":"simple","zh":"请不要把口香糖随便吐在地上。","pinyin":"Qǐng bú yào bǎ kǒuxiāngtáng suíbiàn tǔ zài dìshang.","vi":"Xin đừng tùy tiện nhổ kẹo cao su xuống đất."},{"type":"compound","zh":"坐飞机时如果耳朵难受，就嚼一块口香糖吧。","pinyin":"Zuòfēijī shí rúguǒ ěrduo nánshòu, jiù jiáo yíkuài kǒuxiāngtáng ba.","vi":"Khi đi máy bay nếu thấy ù tai thì hãy nhai một viên kẹo cao su."}],"related":[{"hanzi":"糖果","pinyin":"tángguǒ","vi":"kẹo"},{"hanzi":"嚼","pinyin":"jiáo","vi":"nhai"},{"hanzi":"薄荷","pinyin":"bòhe","vi":"bạc hà"},{"hanzi":"泡泡糖","pinyin":"pàopaotáng","vi":"kẹo thổi bong bóng"}]},{"id":"口罩","hanzi":"口罩","pinyin":"kǒuzhào","meaning_vi":"khẩu trang","explanation":"口 (khẩu – miệng) + 罩 (tráo – cái chụp, che) → vật che miệng mũi để chống bụi, vi khuẩn.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"😷","examples":[{"type":"basic","zh":"出门记得戴口罩。","pinyin":"Chūmén jìde dài kǒuzhào.","vi":"Ra ngoài nhớ đeo khẩu trang."},{"type":"simple","zh":"空气污染严重的时候，很多人都戴着口罩。","pinyin":"Kōngqì wūrǎn yánzhòng de shíhou, hěn duō rén dōu dàizhe kǒuzhào.","vi":"Khi ô nhiễm không khí nghiêm trọng, nhiều người đều đeo khẩu trang."},{"type":"compound","zh":"如果你感冒了，就最好戴上口罩，免得传染别人。","pinyin":"Rúguǒ nǐ gǎnmào le, jiù zuìhǎo dàishang kǒuzhào, miǎnde chuánrǎn biérén.","vi":"Nếu bạn bị cảm thì tốt nhất nên đeo khẩu trang để khỏi lây cho người khác."}],"related":[{"hanzi":"戴","pinyin":"dài","vi":"đeo"},{"hanzi":"防护","pinyin":"fánghù","vi":"phòng hộ"},{"hanzi":"手套","pinyin":"shǒutào","vi":"găng tay"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"}]},{"id":"口子","hanzi":"口子","pinyin":"kǒuzi","meaning_vi":"vết cắt, vết rách, chỗ hở, lỗ hổng","explanation":"口 (khẩu – miệng, chỗ mở) + 子 (tử – hậu tố) → chỗ hở, vết rách; cũng dùng làm lượng từ chỉ người trong nhà (两口子).","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🩹","examples":[{"type":"basic","zh":"手上划了个口子。","pinyin":"Shǒushang huále ge kǒuzi.","vi":"Tay bị cứa một vết."},{"type":"simple","zh":"风太大，帐篷被刮开了一道口子。","pinyin":"Fēng tài dà, zhàngpeng bèi guā kāile yídào kǒuzi.","vi":"Gió quá to, lều bị thổi rách một đường."},{"type":"compound","zh":"因为堤坝上出现了一个口子，所以村民们连夜去抢修。","pinyin":"Yīnwèi dībà shang chūxiànle yí ge kǒuzi, suǒyǐ cūnmínmen liányè qù qiǎngxiū.","vi":"Vì con đê xuất hiện một chỗ vỡ nên dân làng suốt đêm đi gia cố."}],"related":[{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"缺口","pinyin":"quēkǒu","vi":"chỗ khuyết"},{"hanzi":"裂缝","pinyin":"lièfèng","vi":"vết nứt"},{"hanzi":"两口子","pinyin":"liǎngkǒuzi","vi":"hai vợ chồng"}]},{"id":"扣留","hanzi":"扣留","pinyin":"kòuliú","meaning_vi":"tạm giữ, giam giữ, tịch thu","explanation":"扣 (khấu – giữ lại) + 留 (lưu – để lại) → giữ người hay đồ vật lại không cho đi, thường do cơ quan chức năng.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"他的护照被扣留了。","pinyin":"Tā de hùzhào bèi kòuliú le.","vi":"Hộ chiếu của anh ấy đã bị tạm giữ."},{"type":"simple","zh":"海关扣留了一批没有手续的货物。","pinyin":"Hǎiguān kòuliúle yìpī méiyǒu shǒuxù de huòwù.","vi":"Hải quan đã tạm giữ một lô hàng không có giấy tờ."},{"type":"compound","zh":"因为他酒后开车，所以驾照被交警扣留了。","pinyin":"Yīnwèi tā jiǔhòu kāichē, suǒyǐ jiàzhào bèi jiāojǐng kòuliú le.","vi":"Vì lái xe sau khi uống rượu nên bằng lái của anh ta bị cảnh sát giao thông giữ lại."}],"related":[{"hanzi":"扣押","pinyin":"kòuyā","vi":"tạm giữ"},{"hanzi":"拘留","pinyin":"jūliú","vi":"tạm giam"},{"hanzi":"没收","pinyin":"mòshōu","vi":"tịch thu"},{"hanzi":"释放","pinyin":"shìfàng","vi":"thả ra"}]},{"id":"哭泣","hanzi":"哭泣","pinyin":"kūqì","meaning_vi":"khóc, khóc lóc, khóc thút thít","explanation":"哭 (khốc – khóc) + 泣 (khấp – khóc không thành tiếng) → khóc sụt sùi; văn viết hơn 哭.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"她独自哭泣。","pinyin":"Tā dúzì kūqì.","vi":"Cô ấy khóc một mình."},{"type":"simple","zh":"听到这个消息，她低着头默默地哭泣。","pinyin":"Tīngdào zhè ge xiāoxi, tā dīzhe tóu mòmò de kūqì.","vi":"Nghe tin này, cô ấy cúi đầu lặng lẽ khóc."},{"type":"compound","zh":"即使心里再难过，他也从不在别人面前哭泣。","pinyin":"Jíshǐ xīnli zài nánguò, tā yě cóng bú zài biérén miànqián kūqì.","vi":"Dù trong lòng buồn đến đâu, anh ấy cũng chưa bao giờ khóc trước mặt người khác."}],"related":[{"hanzi":"哭","pinyin":"kū","vi":"khóc"},{"hanzi":"流泪","pinyin":"liúlèi","vi":"rơi nước mắt"},{"hanzi":"抽泣","pinyin":"chōuqì","vi":"thút thít"},{"hanzi":"欢笑","pinyin":"huānxiào","vi":"cười vui"}]},{"id":"哭笑不得","hanzi":"哭笑不得","pinyin":"kūxiào-bùdé","meaning_vi":"dở khóc dở cười","explanation":"Nghĩa đen: khóc không được, cười cũng không được → nghĩa bóng: tình huống vừa buồn cười vừa bực mình, không biết phản ứng thế nào.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😅","examples":[{"type":"basic","zh":"这事真让人哭笑不得。","pinyin":"Zhè shì zhēn ràng rén kūxiàobùdé.","vi":"Chuyện này thật khiến người ta dở khóc dở cười."},{"type":"simple","zh":"他把盐当成糖放进了咖啡，弄得大家哭笑不得。","pinyin":"Tā bǎ yán dàngchéng táng fàngjìnle kāfēi, nòng de dàjiā kūxiàobùdé.","vi":"Anh ấy cho muối vào cà phê thay đường, làm mọi người dở khóc dở cười."},{"type":"compound","zh":"虽然孩子是一片好心，但是他的做法让妈妈哭笑不得。","pinyin":"Suīrán háizi shì yípiàn hǎoxīn, dànshì tā de zuòfǎ ràng māma kūxiàobùdé.","vi":"Tuy đứa trẻ có lòng tốt nhưng cách làm của nó khiến mẹ dở khóc dở cười."}],"related":[{"hanzi":"啼笑皆非","pinyin":"tíxiàojiēfēi","vi":"dở khóc dở cười"},{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"đành chịu"},{"hanzi":"尴尬","pinyin":"gāngà","vi":"ngượng ngùng"},{"hanzi":"好笑","pinyin":"hǎoxiào","vi":"buồn cười"}]},{"id":"窟窿","hanzi":"窟窿","pinyin":"kūlong","meaning_vi":"lỗ thủng, hang hốc; lỗ hổng (tài chính)","explanation":"窟 (quật – hang) + 窿 (long – lỗ) → lỗ hổng, chỗ thủng; nghĩa bóng: khoản thiếu hụt, nợ nần.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🕳️","examples":[{"type":"basic","zh":"袜子破了个窟窿。","pinyin":"Wàzi pòle ge kūlong.","vi":"Tất bị thủng một lỗ."},{"type":"simple","zh":"老鼠在墙角咬出了一个大窟窿。","pinyin":"Lǎoshǔ zài qiángjiǎo yǎo chūle yí ge dà kūlong.","vi":"Chuột gặm ở góc tường thành một cái lỗ to."},{"type":"compound","zh":"因为公司亏损严重，所以财务上留下了一个大窟窿。","pinyin":"Yīnwèi gōngsī kuīsǔn yánzhòng, suǒyǐ cáiwù shang liúxiàle yí ge dà kūlong.","vi":"Vì công ty lỗ nặng nên để lại một lỗ hổng tài chính lớn."}],"related":[{"hanzi":"洞","pinyin":"dòng","vi":"lỗ, hang"},{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"},{"hanzi":"缺口","pinyin":"quēkǒu","vi":"chỗ khuyết"},{"hanzi":"补","pinyin":"bǔ","vi":"vá"}]},{"id":"苦力","hanzi":"苦力","pinyin":"kǔlì","meaning_vi":"cu li, lao động chân tay nặng nhọc","explanation":"苦 (khổ – cực nhọc) + 力 (lực – sức) → người làm việc nặng bằng sức lực, hoặc công việc khổ sai.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🧱","examples":[{"type":"basic","zh":"他在码头当苦力。","pinyin":"Tā zài mǎtóu dāng kǔlì.","vi":"Anh ấy làm cu li ở bến cảng."},{"type":"simple","zh":"那时候他每天卖苦力，只能赚几块钱。","pinyin":"Nàshíhou tā měitiān màikǔlì, zhǐnéng zhuàn jǐ kuài qián.","vi":"Hồi đó ngày nào anh ấy cũng bán sức lao động, chỉ kiếm được vài đồng."},{"type":"compound","zh":"虽然干的是苦力活，但是他从来不抱怨。","pinyin":"Suīrán gàn de shì kǔlì huó, dànshì tā cóngláibú bàoyuàn.","vi":"Tuy làm công việc nặng nhọc nhưng anh ấy chưa bao giờ than phiền."}],"related":[{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"劳动","pinyin":"láodòng","vi":"lao động"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"},{"hanzi":"民工","pinyin":"míngōng","vi":"lao động phổ thông"}]},{"id":"苦练","hanzi":"苦练","pinyin":"kǔliàn","meaning_vi":"khổ luyện, luyện tập chăm chỉ","explanation":"苦 (khổ – vất vả) + 练 (luyện – luyện tập) → luyện tập gian khổ, bền bỉ.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"他每天苦练投篮。","pinyin":"Tā měitiān kǔliàn tóulán.","vi":"Ngày nào anh ấy cũng khổ luyện ném rổ."},{"type":"simple","zh":"经过三年的苦练，她终于登上了世界舞台。","pinyin":"Jīngguò sān nián de kǔliàn, tā zhōngyú dēngshàngle shìjiè wǔtái.","vi":"Sau ba năm khổ luyện, cô ấy cuối cùng đã bước lên sân khấu thế giới."},{"type":"compound","zh":"只要你肯苦练，就一定能把这首曲子弹好。","pinyin":"Zhǐyào nǐ kěn kǔliàn, jiù yídìng néng bǎ zhè shǒu qǔzi tán hǎo.","vi":"Chỉ cần bạn chịu khổ luyện thì nhất định sẽ chơi tốt bản nhạc này."}],"related":[{"hanzi":"练习","pinyin":"liànxí","vi":"luyện tập"},{"hanzi":"刻苦","pinyin":"kèkǔ","vi":"chịu khó"},{"hanzi":"训练","pinyin":"xùnliàn","vi":"huấn luyện"},{"hanzi":"勤学苦练","pinyin":"qínxuékǔliàn","vi":"chăm học khổ luyện"}],"traditional":"苦練"},{"id":"苦难","hanzi":"苦难","pinyin":"kǔnàn","meaning_vi":"khổ nạn, đau khổ, gian truân","explanation":"苦 (khổ – đau khổ) + 难 (nạn – tai họa) → những khổ đau, hoạn nạn mà con người phải chịu.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌧️","examples":[{"type":"basic","zh":"他经历过很多苦难。","pinyin":"Tā jīnglìguò hěn duō kǔnàn.","vi":"Ông ấy đã trải qua rất nhiều khổ nạn."},{"type":"simple","zh":"战争给当地人民带来了深重的苦难。","pinyin":"Zhànzhēng gěi dāngdì rénmín dàiláile shēnzhòng de kǔnàn.","vi":"Chiến tranh đã mang lại khổ đau sâu nặng cho người dân địa phương."},{"type":"compound","zh":"尽管一生充满苦难，她也始终保持着乐观。","pinyin":"Jǐnguǎn yìshēng chōngmǎn kǔnàn, tā yě shǐzhōng bǎochízhe lèguān.","vi":"Dù cả đời đầy khổ nạn, bà ấy vẫn luôn giữ được sự lạc quan."}],"related":[{"hanzi":"灾难","pinyin":"zāinàn","vi":"tai họa"},{"hanzi":"痛苦","pinyin":"tòngkǔ","vi":"đau khổ"},{"hanzi":"磨难","pinyin":"mónàn","vi":"gian truân"},{"hanzi":"幸福","pinyin":"xìngfú","vi":"hạnh phúc"}],"traditional":"苦難"},{"id":"苦笑","hanzi":"苦笑","pinyin":"kǔxiào","meaning_vi":"cười gượng, cười khổ","explanation":"苦 (khổ – đắng, khổ) + 笑 (tiếu – cười) → cười trong lúc không vui, cười một cách bất lực.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"他无奈地苦笑了一下。","pinyin":"Tā wúnài de kǔxiàole yíxià.","vi":"Anh ấy cười khổ một cách bất lực."},{"type":"simple","zh":"听了朋友的玩笑，她只是摇摇头苦笑。","pinyin":"Tīngle péngyou de wánxiào, tā zhǐshì yáo yaotóu kǔxiào.","vi":"Nghe bạn đùa, cô ấy chỉ lắc đầu cười gượng."},{"type":"compound","zh":"虽然心里很难受，但是他还是对大家苦笑着说没事。","pinyin":"Suīrán xīnli hěn nánshòu, dànshì tā háishì duì dàjiā kǔxiàozhe shuō méishì.","vi":"Tuy trong lòng rất khó chịu nhưng anh ấy vẫn cười gượng nói với mọi người là không sao."}],"related":[{"hanzi":"微笑","pinyin":"wēixiào","vi":"mỉm cười"},{"hanzi":"无奈","pinyin":"wúnài","vi":"bất lực"},{"hanzi":"冷笑","pinyin":"lěngxiào","vi":"cười nhạt"},{"hanzi":"苦恼","pinyin":"kǔnǎo","vi":"phiền não"}]},{"id":"酷似","hanzi":"酷似","pinyin":"kùsì","meaning_vi":"giống hệt, giống y như","explanation":"酷 (khốc – cực kỳ) + 似 (tự – giống) → giống đến mức gần như không phân biệt được.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"👯","examples":[{"type":"basic","zh":"他长得酷似父亲。","pinyin":"Tā zhǎngde kùsì fùqīn.","vi":"Anh ấy trông giống hệt bố."},{"type":"simple","zh":"这块石头的形状酷似一只趴着的乌龟。","pinyin":"Zhè kuài shítou de xíngzhuàng kùsì yì zhī pāzhe de wūguī.","vi":"Hình dáng hòn đá này giống hệt một con rùa đang nằm bò."},{"type":"compound","zh":"因为她的声音酷似那位歌星，所以常被请去模仿表演。","pinyin":"Yīnwèi tā de shēngyīn kùsì nà wèi gēxīng, suǒyǐ cháng bèi qǐng qù mófǎng biǎoyǎn.","vi":"Vì giọng cô ấy giống hệt ca sĩ đó nên thường được mời đi biểu diễn giả giọng."}],"related":[{"hanzi":"相似","pinyin":"xiāngsì","vi":"tương tự"},{"hanzi":"好像","pinyin":"hǎoxiàng","vi":"giống như"},{"hanzi":"一模一样","pinyin":"yìmúyíyàng","vi":"giống y đúc"},{"hanzi":"类似","pinyin":"lèisì","vi":"tương tự"}]},{"id":"夸奖","hanzi":"夸奖","pinyin":"kuājiǎng","meaning_vi":"khen ngợi, khen thưởng, tán dương","explanation":"夸 (khoa – khen, khoe) + 奖 (tưởng – khen thưởng) → nói lời khen về ưu điểm, thành tích của người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"老师夸奖了他。","pinyin":"Lǎoshī kuājiǎngle tā.","vi":"Thầy giáo đã khen cậu ấy."},{"type":"simple","zh":"客人们都夸奖妈妈做的菜又香又好看。","pinyin":"Kèrénmen dōu kuājiǎng māma zuò de cài yòu xiāng yòu hǎokàn.","vi":"Khách đều khen món mẹ nấu vừa thơm vừa đẹp mắt."},{"type":"compound","zh":"虽然得到了领导的夸奖，但是他并没有骄傲。","pinyin":"Suīrán dédàole lǐngdǎo de kuājiǎng, dànshì tā bìng méiyǒu jiāo'ào.","vi":"Tuy được lãnh đạo khen ngợi nhưng anh ấy không hề kiêu ngạo."}],"related":[{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"biểu dương"},{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"},{"hanzi":"夸耀","pinyin":"kuāyào","vi":"khoe khoang"}],"traditional":"誇獎"},{"id":"夸夸其谈","hanzi":"夸夸其谈","pinyin":"kuākuā-qítán","meaning_vi":"ba hoa khoác lác, nói suông, chém gió","explanation":"Nghĩa đen: nói năng khoa trương rỗng tuếch → nghĩa bóng: nói to tát, viển vông mà không có thực chất, không làm được.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"他只会夸夸其谈。","pinyin":"Tā zhǐ huì kuākuāqítán.","vi":"Anh ta chỉ biết nói khoác."},{"type":"simple","zh":"开会时他夸夸其谈，却提不出一个具体方案。","pinyin":"Kāihuì shí tā kuākuāqítán, què tí bu chū yí ge jùtǐ fāng'àn.","vi":"Khi họp anh ta ba hoa đủ điều nhưng không đưa ra được phương án cụ thể nào."},{"type":"compound","zh":"与其在这儿夸夸其谈，不如马上动手去做。","pinyin":"Yǔqí zài zhèr kuākuāqítán, bùrú mǎshàng dòngshǒu qù zuò.","vi":"Thay vì ngồi đây nói suông, chi bằng bắt tay vào làm ngay."}],"related":[{"hanzi":"吹牛","pinyin":"chuīniú","vi":"khoác lác"},{"hanzi":"空谈","pinyin":"kōngtán","vi":"nói suông"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thực"},{"hanzi":"侃大山","pinyin":"kǎndàshān","vi":"tán gẫu"}],"traditional":"誇誇其談"},{"id":"夸耀","hanzi":"夸耀","pinyin":"kuāyào","meaning_vi":"khoe khoang, phô trương","explanation":"夸 (khoa – khoe) + 耀 (diệu – chói sáng) → khoe ra cho người khác thấy cái hay của mình; thường mang ý chê.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🦚","examples":[{"type":"basic","zh":"他喜欢夸耀自己。","pinyin":"Tā xǐhuan kuāyào zìjǐ.","vi":"Anh ta thích khoe khoang bản thân."},{"type":"simple","zh":"她总是在朋友面前夸耀自己的新车。","pinyin":"Tā zǒngshì zài péngyou miànqián kuāyào zìjǐ de xīnchē.","vi":"Cô ta luôn khoe chiếc xe mới trước mặt bạn bè."},{"type":"compound","zh":"虽然他取得了很大的成就，但是从不向别人夸耀。","pinyin":"Suīrán tā qǔ déle hěn dà de chéngjiù, dànshì cóng bú xiàng biérén kuāyào.","vi":"Tuy đạt được thành tựu lớn nhưng anh ấy chưa bao giờ khoe khoang với ai."}],"related":[{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe mẽ"},{"hanzi":"夸奖","pinyin":"kuājiǎng","vi":"khen ngợi"},{"hanzi":"吹嘘","pinyin":"chuīxū","vi":"khoác lác"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"}],"traditional":"誇耀"},{"id":"垮","hanzi":"垮","pinyin":"kuǎ","meaning_vi":"sụp đổ, đổ sập; suy sụp","explanation":"垮 (khóa – đổ, sập) → đổ sập xuống; nghĩa bóng: thất bại, suy sụp (身体垮了, 公司垮了).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏚️","examples":[{"type":"basic","zh":"那座旧桥垮了。","pinyin":"Nà zuò jiù qiáo kuǎ le.","vi":"Cây cầu cũ đó đã sập."},{"type":"simple","zh":"连续加班一个月，他的身体终于累垮了。","pinyin":"Liánxù jiābān yí geyuè, tā de shēntǐ zhōngyú lèikuǎ le.","vi":"Tăng ca liên tục một tháng, cơ thể anh ấy cuối cùng đã kiệt sức suy sụp."},{"type":"compound","zh":"即使遇到再大的困难，我们也不能被打垮。","pinyin":"Jíshǐ yùdào zài dà de kùnnan, wǒmen yě bù néng bèi dǎkuǎ.","vi":"Dù gặp khó khăn lớn đến đâu, chúng ta cũng không thể bị đánh gục."}],"related":[{"hanzi":"倒塌","pinyin":"dǎotā","vi":"đổ sập"},{"hanzi":"崩溃","pinyin":"bēngkuì","vi":"sụp đổ"},{"hanzi":"打垮","pinyin":"dǎkuǎ","vi":"đánh gục"},{"hanzi":"垮台","pinyin":"kuǎtái","vi":"sụp đổ, mất quyền"}]},{"id":"跨国","hanzi":"跨国","pinyin":"kuàguó","meaning_vi":"xuyên quốc gia, đa quốc gia","explanation":"跨 (khóa – vượt qua) + 国 (quốc – nước) → vượt qua biên giới một nước; thường dùng 跨国公司, 跨国婚姻.","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🌐","examples":[{"type":"basic","zh":"他在跨国公司上班。","pinyin":"Tā zài kuàguógōngsī shàngbān.","vi":"Anh ấy làm việc ở công ty đa quốc gia."},{"type":"simple","zh":"警方破获了一个跨国诈骗团伙。","pinyin":"Jǐngfāng pòhuòle yí ge kuàguó zhàpiàn tuánhuǒ.","vi":"Cảnh sát đã triệt phá một băng lừa đảo xuyên quốc gia."},{"type":"compound","zh":"因为是跨国合作，所以双方经常要开视频会议。","pinyin":"Yīnwèi shì kuàguó hézuò, suǒyǐ shuāngfāng jīngcháng yào kāi shìpínhuìyì.","vi":"Vì là hợp tác xuyên quốc gia nên hai bên thường phải họp trực tuyến."}],"related":[{"hanzi":"国际","pinyin":"Guójì","vi":"quốc tế"},{"hanzi":"跨越","pinyin":"kuàyuè","vi":"vượt qua"},{"hanzi":"全球","pinyin":"quánqiú","vi":"toàn cầu"},{"hanzi":"外企","pinyin":"wàiqǐ","vi":"doanh nghiệp nước ngoài"}],"traditional":"跨國"},{"id":"跨越","hanzi":"跨越","pinyin":"kuàyuè","meaning_vi":"vượt qua, băng qua","explanation":"跨 (khóa – bước qua) + 越 (việt – vượt) → vượt qua sông núi, giới hạn hay giai đoạn.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"大桥跨越长江。","pinyin":"Dàqiáo kuàyuè Chángjiāng.","vi":"Cây cầu lớn bắc qua sông Trường Giang."},{"type":"simple","zh":"这条铁路跨越了三个省，全长一千多公里。","pinyin":"Zhè tiáo tiělù kuàyuèle sān ge shěng, quáncháng yī qiān duō gōnglǐ.","vi":"Tuyến đường sắt này đi qua ba tỉnh, dài hơn một nghìn cây số."},{"type":"compound","zh":"只要大家团结一心，就能跨越眼前的困难。","pinyin":"Zhǐyào dàjiā tuánjié yìxīn, jiù néng kuàyuè yǎnqián de kùnnan.","vi":"Chỉ cần mọi người đồng lòng thì có thể vượt qua khó khăn trước mắt."}],"related":[{"hanzi":"超越","pinyin":"chāoyuè","vi":"vượt lên"},{"hanzi":"穿越","pinyin":"chuānyuè","vi":"xuyên qua"},{"hanzi":"跨国","pinyin":"kuàguó","vi":"xuyên quốc gia"},{"hanzi":"越过","pinyin":"yuèguò","vi":"vượt qua"}]},{"id":"快捷","hanzi":"快捷","pinyin":"kuàijié","meaning_vi":"nhanh chóng, tiện lợi, nhanh gọn","explanation":"快 (khoái – nhanh) + 捷 (tiệp – nhanh nhẹn) → nhanh và tiện; hay dùng 快捷方式 (lối tắt), 快捷酒店.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"⚡","examples":[{"type":"basic","zh":"网上支付很快捷。","pinyin":"Wǎngshang zhīfù hěn kuàijié.","vi":"Thanh toán trực tuyến rất nhanh gọn."},{"type":"simple","zh":"高铁为人们提供了快捷的出行方式。","pinyin":"Gāotiě wèirénmen tígōngle kuàijié de chūxíng fāngshì.","vi":"Tàu cao tốc mang đến cho mọi người cách đi lại nhanh chóng."},{"type":"compound","zh":"如果在桌面上建一个快捷方式，就能更方便地打开软件。","pinyin":"Rúguǒ zài zhuōmiàn shang jiàn yí ge kuàijié fāngshì, jiù néng gèng fāngbiàn de dǎkāi ruǎnjiàn.","vi":"Nếu tạo một lối tắt trên màn hình thì có thể mở phần mềm tiện hơn."}],"related":[{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"},{"hanzi":"便捷","pinyin":"biànjié","vi":"tiện lợi"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"thuận tiện"},{"hanzi":"缓慢","pinyin":"huǎnmàn","vi":"chậm chạp"}]},{"id":"宽泛","hanzi":"宽泛","pinyin":"kuānfàn","meaning_vi":"rộng, bao quát, chung chung","explanation":"宽 (khoan – rộng) + 泛 (phiếm – rộng khắp, chung chung) → phạm vi rộng, không cụ thể; thường dùng cho đề tài, khái niệm.","hsk_level":"7-9","tags":["tinh-tu","nhan-thuc"],"image":"🌫️","examples":[{"type":"basic","zh":"这个题目太宽泛了。","pinyin":"Zhè ge tímù tài kuānfàn le.","vi":"Đề tài này quá rộng."},{"type":"simple","zh":"“文化”是一个含义十分宽泛的概念。","pinyin":"\"Wénhuà\" shì yí ge hányì shífēn kuānfàn de gàiniàn.","vi":"\"Văn hóa\" là một khái niệm có hàm nghĩa vô cùng rộng."},{"type":"compound","zh":"如果论文的范围太宽泛，就很难写得深入。","pinyin":"Rúguǒ lùnwén de fànwéi tài kuānfàn, jiù hěn nán xiě de shēnrù.","vi":"Nếu phạm vi luận văn quá rộng thì rất khó viết sâu."}],"related":[{"hanzi":"广泛","pinyin":"guǎngfàn","vi":"rộng rãi"},{"hanzi":"笼统","pinyin":"lǒngtǒng","vi":"chung chung"},{"hanzi":"具体","pinyin":"jùtǐ","vi":"cụ thể"},{"hanzi":"空泛","pinyin":"kōngfàn","vi":"trống rỗng, chung chung"}],"traditional":"寬泛"},{"id":"宽恕","hanzi":"宽恕","pinyin":"kuānshù","meaning_vi":"tha thứ, khoan thứ","explanation":"宽 (khoan – rộng lượng) + 恕 (thứ – tha thứ) → rộng lòng tha thứ cho lỗi lầm của người khác.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🕊️","examples":[{"type":"basic","zh":"请你宽恕我吧。","pinyin":"Qǐng nǐ kuānshù wǒ ba.","vi":"Xin bạn hãy tha thứ cho tôi."},{"type":"simple","zh":"他犯下的错误很难得到大家的宽恕。","pinyin":"Tā fàn xià de cuòwù hěn nándé dào dàjiā de kuānshù.","vi":"Lỗi lầm anh ta gây ra rất khó được mọi người tha thứ."},{"type":"compound","zh":"虽然他伤害过她，但是她最终还是选择了宽恕。","pinyin":"Suīrán tā shānghàiguo tā, dànshì tā zuìzhōng háishì xuǎnzéle kuānshù.","vi":"Tuy anh ta từng làm tổn thương cô ấy nhưng cuối cùng cô ấy vẫn chọn tha thứ."}],"related":[{"hanzi":"原谅","pinyin":"yuánliàng","vi":"tha thứ"},{"hanzi":"饶恕","pinyin":"ráoshù","vi":"tha tội"},{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"},{"hanzi":"报复","pinyin":"bàofù","vi":"trả thù"}],"traditional":"寬恕"},{"id":"框","hanzi":"框","pinyin":"kuàng","meaning_vi":"khung; đóng khung, giới hạn","explanation":"框 (khuông – khung) → khung bao quanh cửa, ảnh, kính; làm động từ: khoanh lại, giới hạn trong khuôn khổ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🖼️","examples":[{"type":"basic","zh":"请在框里打勾。","pinyin":"Qǐng zài kuàng li dǎgōu.","vi":"Vui lòng đánh dấu vào ô."},{"type":"simple","zh":"他给全家福配了一个木头框。","pinyin":"Tā gěi quánjiāfú pèile yí ge mùtou kuàng.","vi":"Anh ấy lắp một cái khung gỗ cho bức ảnh gia đình."},{"type":"compound","zh":"如果总被旧规矩框住，就很难有新的想法。","pinyin":"Rúguǒ zǒng bèi jiù guīju kuàng zhù, jiù hěn nán yǒu xīn de xiǎngfǎ.","vi":"Nếu cứ bị quy tắc cũ bó buộc thì rất khó có ý tưởng mới."}],"related":[{"hanzi":"框架","pinyin":"kuàngjià","vi":"khung, khuôn khổ"},{"hanzi":"镜框","pinyin":"jìngkuàng","vi":"khung ảnh, gọng kính"},{"hanzi":"门框","pinyin":"ménkuàng","vi":"khung cửa"},{"hanzi":"边框","pinyin":"biānkuàng","vi":"viền khung"}]},{"id":"狂欢","hanzi":"狂欢","pinyin":"kuánghuān","meaning_vi":"vui chơi cuồng nhiệt, liên hoan thả cửa","explanation":"狂 (cuồng – điên cuồng) + 欢 (hoan – vui) → vui chơi hết mình, náo nhiệt không kìm chế.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎉","examples":[{"type":"basic","zh":"大家狂欢到深夜。","pinyin":"Dàjiā kuánghuān dào shēnyè.","vi":"Mọi người vui chơi cuồng nhiệt đến khuya."},{"type":"simple","zh":"球队夺冠后，球迷们涌上街头狂欢。","pinyin":"Qiúduì duóguàn hòu, qiúmímen yǒng shàng jiētóu kuánghuān.","vi":"Sau khi đội bóng vô địch, người hâm mộ đổ ra đường ăn mừng cuồng nhiệt."},{"type":"compound","zh":"虽然狂欢了一整夜，但是第二天他照样按时上班。","pinyin":"Suīrán kuánghuānle yì zhěngyè, dànshì dì'èrtiān tā zhàoyàng ànshí shàngbān.","vi":"Tuy quẩy suốt cả đêm nhưng hôm sau anh ấy vẫn đi làm đúng giờ."}],"related":[{"hanzi":"狂欢节","pinyin":"kuánghuānjié","vi":"lễ hội carnival"},{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"ăn mừng"},{"hanzi":"欢乐","pinyin":"huānlè","vi":"vui vẻ"},{"hanzi":"派对","pinyin":"pàiduì","vi":"bữa tiệc"}],"traditional":"狂歡"},{"id":"狂欢节","hanzi":"狂欢节","pinyin":"kuánghuānjié","meaning_vi":"lễ hội carnival, lễ hội hóa trang","explanation":"狂欢 (cuồng hoan – vui chơi cuồng nhiệt) + 节 (tiết – lễ hội) → lễ hội đường phố lớn với diễu hành, hóa trang, ca múa.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"巴西的狂欢节很有名。","pinyin":"Bāxī de kuánghuānjié hěn yǒumíng.","vi":"Lễ hội carnival ở Brazil rất nổi tiếng."},{"type":"simple","zh":"每年狂欢节期间，街上都有盛大的游行。","pinyin":"Měinián kuánghuānjié qījiān, jiē Shangdōu yǒu shèngdà de yóuxíng.","vi":"Mỗi năm vào dịp lễ hội carnival, trên phố đều có cuộc diễu hành hoành tráng."},{"type":"compound","zh":"如果你二月去那里旅游，就能赶上热闹的狂欢节。","pinyin":"Rúguǒ nǐ Èryuè qù nàli lǚyóu, jiù néng gǎnshàng rènao de kuánghuānjié.","vi":"Nếu bạn đến đó du lịch vào tháng hai thì có thể đúng dịp lễ hội carnival náo nhiệt."}],"related":[{"hanzi":"狂欢","pinyin":"kuánghuān","vi":"vui chơi cuồng nhiệt"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"},{"hanzi":"游行","pinyin":"yóuxíng","vi":"diễu hành"},{"hanzi":"面具","pinyin":"miànjù","vi":"mặt nạ"}],"traditional":"狂歡節"},{"id":"狂热","hanzi":"狂热","pinyin":"kuángrè","meaning_vi":"cuồng nhiệt, cuồng tín, say mê điên cuồng","explanation":"狂 (cuồng – điên cuồng) + 热 (nhiệt – nóng) → nhiệt tình đến mức quá đà, mất lý trí.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他是个狂热的球迷。","pinyin":"Tā shì ge kuángrè de qiúmí.","vi":"Anh ấy là một người hâm mộ bóng đá cuồng nhiệt."},{"type":"simple","zh":"这几年，人们对网上购物的狂热有增无减。","pinyin":"Zhè jǐ nián, rénmen duì wǎngshang gòuwù de kuángrè yǒu zēng wú jiǎn.","vi":"Mấy năm nay, cơn sốt mua sắm trực tuyến của mọi người chỉ tăng chứ không giảm."},{"type":"compound","zh":"即使你对投资很狂热，也要保持冷静的头脑。","pinyin":"Jíshǐ nǐ duì tóuzī hěn kuángrè, yě yào bǎochí lěngjìng de tóunǎo.","vi":"Dù bạn cuồng nhiệt với đầu tư đến đâu cũng phải giữ cái đầu lạnh."}],"related":[{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"疯狂","pinyin":"fēngkuáng","vi":"điên cuồng"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"},{"hanzi":"痴迷","pinyin":"chīmí","vi":"say mê"}],"traditional":"狂熱"},{"id":"矿藏","hanzi":"矿藏","pinyin":"kuàngcáng","meaning_vi":"tài nguyên khoáng sản, mỏ khoáng sản","explanation":"矿 (khoáng – khoáng sản) + 藏 (tàng – cất giấu) → khoáng sản nằm sâu trong lòng đất.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛏️","examples":[{"type":"basic","zh":"这里矿藏丰富。","pinyin":"Zhèlǐ kuàngcáng fēngfù.","vi":"Nơi đây giàu khoáng sản."},{"type":"simple","zh":"地质队在山区发现了大量的铁矿藏。","pinyin":"Dìzhì duì zài shānqū fāxiànle dàliàng de tiě kuàngcáng.","vi":"Đội địa chất phát hiện trữ lượng lớn quặng sắt ở vùng núi."},{"type":"compound","zh":"虽然这个地区矿藏丰富，但是开采条件很差。","pinyin":"Suīrán zhè ge dìqū kuàngcáng fēngfù, dànshì kāicǎi tiáojiàn hěn chà.","vi":"Tuy vùng này giàu khoáng sản nhưng điều kiện khai thác rất kém."}],"related":[{"hanzi":"矿产","pinyin":"kuàngchǎn","vi":"khoáng sản"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"开采","pinyin":"kāicǎi","vi":"khai thác"},{"hanzi":"煤矿","pinyin":"méikuàng","vi":"mỏ than"}],"traditional":"礦藏"},{"id":"扩","hanzi":"扩","pinyin":"kuò","meaning_vi":"mở rộng, khuếch trương","explanation":"扩 (khuếch – mở rộng) → làm cho to ra, rộng ra; thường đứng trong từ ghép như 扩大, 扩建, 扩招.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"↔️","examples":[{"type":"basic","zh":"学校要扩招了。","pinyin":"Xuéxiào yào kuòzhāo le.","vi":"Trường sắp mở rộng tuyển sinh."},{"type":"simple","zh":"为了缓解交通压力，这条马路正在扩宽。","pinyin":"Wèile huǎnjiě jiāotōng yālì, zhè tiáo mǎlù zhèngzài kuò kuān.","vi":"Để giảm áp lực giao thông, con đường này đang được mở rộng."},{"type":"compound","zh":"因为客户越来越多，所以工厂决定再扩一条生产线。","pinyin":"Yīnwèi kèhù yuèláiyuè duō, suǒyǐ gōngchǎng juédìng zài kuò yì tiáo shēngchǎnxiàn.","vi":"Vì khách hàng ngày càng nhiều nên nhà máy quyết định mở thêm một dây chuyền sản xuất."}],"related":[{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"扩建","pinyin":"kuòjiàn","vi":"xây mở rộng"},{"hanzi":"扩展","pinyin":"kuòzhǎn","vi":"phát triển rộng"},{"hanzi":"扩张","pinyin":"kuòzhāng","vi":"bành trướng"}],"traditional":"擴"},{"id":"括弧","hanzi":"括弧","pinyin":"kuòhú","meaning_vi":"dấu ngoặc đơn","explanation":"括 (quát – bao gồm) + 弧 (hồ – đường cong) → dấu hình cung dùng để bao phần chú thích trong câu.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🔣","examples":[{"type":"basic","zh":"请把答案写在括弧里。","pinyin":"Qǐng bǎ dá'àn xiě zài kuòhú li.","vi":"Hãy viết đáp án vào trong ngoặc đơn."},{"type":"simple","zh":"括弧里的内容是对前面词语的解释。","pinyin":"Kuòhú li de nèiróng shì duì qiánmiàn cíyǔ de jiěshì.","vi":"Nội dung trong ngoặc đơn là giải thích cho từ ngữ phía trước."},{"type":"compound","zh":"如果括弧里的字可以省略，就说明它不是重点。","pinyin":"Rúguǒ kuòhú li de zì kěyǐ shěnglüè, jiù shuōmíng tā bú shì zhòngdiǎn.","vi":"Nếu chữ trong ngoặc đơn có thể lược bỏ thì chứng tỏ nó không phải trọng điểm."}],"related":[{"hanzi":"括号","pinyin":"kuòhào","vi":"dấu ngoặc"},{"hanzi":"引号","pinyin":"yǐnhào","vi":"dấu ngoặc kép"},{"hanzi":"标点","pinyin":"biāodiǎn","vi":"dấu câu"},{"hanzi":"注释","pinyin":"zhùshì","vi":"chú thích"}]},{"id":"阔绰","hanzi":"阔绰","pinyin":"kuòchuò","meaning_vi":"xa hoa, rủng rỉnh, tiêu tiền rộng tay","explanation":"阔 (khoát – rộng, giàu) + 绰 (xước – dư dả) → sống sung túc, tiêu xài hào phóng, phô trương.","hsk_level":"7-9","tags":["tinh-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"他出手很阔绰。","pinyin":"Tā chūshǒu hěn kuòchuò.","vi":"Anh ta ra tay rất hào phóng."},{"type":"simple","zh":"他每次请客都选最贵的饭店，显得十分阔绰。","pinyin":"Tā měi cì qǐngkè dōu xuǎn zuì guì de fàndiàn, xiǎnde shífēn kuòchuò.","vi":"Lần nào mời khách anh ta cũng chọn nhà hàng đắt nhất, tỏ ra rất rủng rỉnh."},{"type":"compound","zh":"虽然他现在生活阔绰，但是小时候家里非常穷。","pinyin":"Suīrán tā xiànzài shēnghuó kuòchuò, dànshì xiǎoshíhou jiāli fēicháng qióng.","vi":"Tuy giờ anh ấy sống xa hoa nhưng hồi nhỏ nhà rất nghèo."}],"related":[{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"},{"hanzi":"豪华","pinyin":"háohuá","vi":"xa hoa"},{"hanzi":"富有","pinyin":"fùyǒu","vi":"giàu có"},{"hanzi":"寒酸","pinyin":"hánsuān","vi":"nghèo hèn, keo kiệt"}],"traditional":"闊綽"},{"id":"拉动","hanzi":"拉动","pinyin":"lādòng","meaning_vi":"kéo; thúc đẩy, kích thích (kinh tế)","explanation":"拉 (lạp – kéo) + 动 (động – chuyển động) → kéo cho chuyển động; nghĩa bóng: kích thích tăng trưởng (拉动经济, 拉动消费).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"旅游拉动了消费。","pinyin":"Lǚyóu lādòngle xiāofèi.","vi":"Du lịch đã kích thích tiêu dùng."},{"type":"simple","zh":"政府希望通过基础建设来拉动经济增长。","pinyin":"Zhèngfǔ xīwàng tōngguò jīchǔ jiànshè lái lādòng jīngjì zēngzhǎng.","vi":"Chính phủ hy vọng thông qua xây dựng hạ tầng để thúc đẩy tăng trưởng kinh tế."},{"type":"compound","zh":"一旦新机场建成，就会拉动周边地区的发展。","pinyin":"Yídàn xīn jīchǎng jiànchéng, jiù huì lādòng zhōubiān dìqū de fāzhǎn.","vi":"Một khi sân bay mới xây xong thì sẽ thúc đẩy sự phát triển của khu vực xung quanh."}],"related":[{"hanzi":"带动","pinyin":"dàidòng","vi":"kéo theo"},{"hanzi":"推动","pinyin":"tuīdòng","vi":"thúc đẩy"},{"hanzi":"刺激","pinyin":"cìjī","vi":"kích thích"},{"hanzi":"促进","pinyin":"cùjìn","vi":"xúc tiến"}],"traditional":"拉動"},{"id":"拉拢","hanzi":"拉拢","pinyin":"lālǒng","meaning_vi":"lôi kéo, mua chuộc","explanation":"拉 (lạp – kéo) + 拢 (lũng – gom lại) → kéo người khác về phe mình bằng lợi ích, thường mang nghĩa xấu.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🧲","examples":[{"type":"basic","zh":"他想拉拢我。","pinyin":"Tā xiǎng lālǒng wǒ.","vi":"Anh ta muốn lôi kéo tôi."},{"type":"simple","zh":"他到处请客送礼，想拉拢公司的老客户。","pinyin":"Tā dàochù qǐngkè sònglǐ, xiǎng lālǒng gōngsī de lǎo kèhù.","vi":"Anh ta khắp nơi mời mọc tặng quà, muốn lôi kéo khách hàng cũ của công ty."},{"type":"compound","zh":"不管对方怎么拉拢，他都坚持自己的原则。","pinyin":"Bùguǎn duìfāng zěnme lālǒng, tā dōu jiānchí zìjǐ de yuánzé.","vi":"Bất kể bên kia lôi kéo thế nào, anh ấy vẫn giữ vững nguyên tắc của mình."}],"related":[{"hanzi":"收买","pinyin":"shōumǎi","vi":"mua chuộc"},{"hanzi":"笼络","pinyin":"lǒngluò","vi":"lung lạc"},{"hanzi":"拉关系","pinyin":"lāguānxi","vi":"chạy quan hệ"},{"hanzi":"排挤","pinyin":"páijǐ","vi":"chèn ép"}],"traditional":"拉攏"},{"id":"拉锁","hanzi":"拉锁","pinyin":"lāsuǒ","meaning_vi":"khóa kéo, phéc-mơ-tuya","explanation":"拉 (lạp – kéo) + 锁 (tỏa – khóa) → loại khóa kéo trên quần áo, túi xách; còn gọi 拉链.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"🤐","examples":[{"type":"basic","zh":"你的拉锁开了。","pinyin":"Nǐ de lāsuǒ kāi le.","vi":"Khóa kéo của bạn bị mở rồi."},{"type":"simple","zh":"这件外套的拉锁坏了，拉不上去。","pinyin":"Zhè jiàn wàitào de lāsuǒ huàile, lā bu shàngqù.","vi":"Khóa kéo của chiếc áo khoác này hỏng rồi, không kéo lên được."},{"type":"compound","zh":"如果拉锁卡住了，就在上面抹点儿蜡试试。","pinyin":"Rúguǒ lāsuǒ qiǎzhù le, jiù zài shàngmiàn mǒ diǎnr là shìshi.","vi":"Nếu khóa kéo bị kẹt thì thử bôi chút sáp lên xem."}],"related":[{"hanzi":"拉链","pinyin":"lāliàn","vi":"khóa kéo"},{"hanzi":"扣子","pinyin":"kòuzi","vi":"cúc áo"},{"hanzi":"外套","pinyin":"wàitào","vi":"áo khoác"},{"hanzi":"背包","pinyin":"bēibāo","vi":"ba lô"}],"traditional":"拉鎖"},{"id":"腊月","hanzi":"腊月","pinyin":"Làyuè","meaning_vi":"tháng chạp (tháng 12 âm lịch)","explanation":"腊 (lạp – lễ cúng cuối năm, đồ hun khói) + 月 (nguyệt – tháng) → tháng mười hai âm lịch, tháng chuẩn bị đón Tết.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🧧","examples":[{"type":"basic","zh":"腊月快到了。","pinyin":"Làyuè kuài dào le.","vi":"Sắp đến tháng chạp rồi."},{"type":"simple","zh":"每到腊月，家家户户都开始准备年货。","pinyin":"Měi dào Làyuè, jiājiāhùhù dōu kāishǐ zhǔnbèi niánhuò.","vi":"Mỗi khi đến tháng chạp, nhà nhà đều bắt đầu sắm sửa đồ Tết."},{"type":"compound","zh":"因为腊月二十三是小年，所以那天要祭灶神。","pinyin":"Yīnwèi Làyuè èr shísān shì xiǎo nián, suǒyǐ nà tiān yào jì Zàoshén.","vi":"Vì ngày hai mươi ba tháng chạp là Tết ông Táo nên hôm đó phải cúng Táo quân."}],"related":[{"hanzi":"正月","pinyin":"Zhēngyuè","vi":"tháng giêng"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"农历","pinyin":"nónglì","vi":"âm lịch"},{"hanzi":"腊肉","pinyin":"làròu","vi":"thịt hun khói"}],"traditional":"臘月"},{"id":"蜡","hanzi":"蜡","pinyin":"là","meaning_vi":"sáp, nến","explanation":"蜡 (lạp – sáp) → chất sáp từ động vật, thực vật hay dầu mỏ; cũng chỉ cây nến.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🕯️","examples":[{"type":"basic","zh":"地板上打了蜡。","pinyin":"Dìbǎn shang dǎle là.","vi":"Sàn nhà đã được đánh sáp."},{"type":"simple","zh":"停电了，奶奶点上了一根蜡。","pinyin":"Tíngdiàn le, nǎinai diǎn shangle yìgēn là.","vi":"Mất điện, bà thắp lên một cây nến."},{"type":"compound","zh":"如果给汽车打一层蜡，就能更好地保护车漆。","pinyin":"Rúguǒ gěi qìchē dǎ yīcéng là, jiù néng gèng hǎo de bǎohù chē qī.","vi":"Nếu đánh một lớp sáp cho ô tô thì có thể bảo vệ lớp sơn tốt hơn."}],"related":[{"hanzi":"蜡烛","pinyin":"làzhú","vi":"cây nến"},{"hanzi":"蜂蜡","pinyin":"fēnglà","vi":"sáp ong"},{"hanzi":"打蜡","pinyin":"dǎlà","vi":"đánh sáp"},{"hanzi":"味同嚼蜡","pinyin":"wèitóngjiáolà","vi":"nhạt như nhai sáp"}],"traditional":"蠟"},{"id":"蜡烛","hanzi":"蜡烛","pinyin":"làzhú","meaning_vi":"cây nến","explanation":"蜡 (lạp – sáp) + 烛 (chúc – đuốc, đèn) → cây nến làm bằng sáp có bấc để thắp sáng.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🕯️","examples":[{"type":"basic","zh":"她吹灭了蜡烛。","pinyin":"Tā chuīmièle làzhú.","vi":"Cô ấy thổi tắt nến."},{"type":"simple","zh":"生日蛋糕上插着二十根五颜六色的蜡烛。","pinyin":"Shēngrì dàngāo shang chāzhe èrshí gēn wǔyánliùsè de làzhú.","vi":"Trên bánh sinh nhật cắm hai mươi cây nến đủ màu sắc."},{"type":"compound","zh":"因为突然停电了，所以我们只好点蜡烛吃晚饭。","pinyin":"Yīnwèi tūrán tíngdiàn le, suǒyǐ wǒmen zhǐhǎo diǎn làzhú chī wǎnfàn.","vi":"Vì đột nhiên mất điện nên chúng tôi đành thắp nến ăn tối."}],"related":[{"hanzi":"蜡","pinyin":"là","vi":"sáp"},{"hanzi":"灯","pinyin":"dēng","vi":"đèn"},{"hanzi":"烛光","pinyin":"zhúguāng","vi":"ánh nến"},{"hanzi":"点燃","pinyin":"diǎnrán","vi":"đốt cháy"}],"traditional":"蠟燭"},{"id":"啦啦队","hanzi":"啦啦队","pinyin":"lālāduì","meaning_vi":"đội cổ vũ","explanation":"啦啦 (lạp lạp – tiếng hô cổ vũ) + 队 (đội – đội) → nhóm người hò reo cổ vũ cho đội thi đấu.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"📣","examples":[{"type":"basic","zh":"她参加了啦啦队。","pinyin":"Tā cānjiāle lālāduì.","vi":"Cô ấy đã tham gia đội cổ vũ."},{"type":"simple","zh":"比赛开始前，啦啦队在场边跳起了舞。","pinyin":"Bǐsài kāishǐ qián, lālāduì zài chǎng biān tiào qǐle wǔ.","vi":"Trước khi trận đấu bắt đầu, đội cổ vũ nhảy múa bên sân."},{"type":"compound","zh":"虽然我们队输了，但是啦啦队一直在为我们加油。","pinyin":"Suīrán wǒmen duì shū le, dànshì lālāduì yìzhí zài wèi wǒmen jiāyóu.","vi":"Tuy đội chúng tôi thua nhưng đội cổ vũ vẫn luôn cổ vũ cho chúng tôi."}],"related":[{"hanzi":"加油","pinyin":"jiāyóu","vi":"cố lên"},{"hanzi":"球迷","pinyin":"qiúmí","vi":"người hâm mộ"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"},{"hanzi":"助威","pinyin":"zhùwēi","vi":"cổ vũ"}],"traditional":"啦啦隊"},{"id":"来访","hanzi":"来访","pinyin":"láifǎng","meaning_vi":"đến thăm, sang thăm","explanation":"来 (lai – đến) + 访 (phỏng – thăm hỏi) → đến thăm chính thức hoặc xã giao, thường dùng cho khách, đoàn đại biểu.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"欢迎各位来访！","pinyin":"Huānyíng gèwèi láifǎng!","vi":"Chào mừng quý vị đến thăm!"},{"type":"simple","zh":"下周有一个外国代表团到我们学校来访。","pinyin":"Xiàzhōu yǒu yí ge wàiguó dàibiǎotuán dào wǒmen xuéxiào láifǎng.","vi":"Tuần sau có một đoàn đại biểu nước ngoài đến thăm trường chúng tôi."},{"type":"compound","zh":"如果有客人来访，就请先在前台登记。","pinyin":"Rúguǒ yǒu kèrén láifǎng, jiù qǐng xiān zài qiántái dēngjì.","vi":"Nếu có khách đến thăm thì xin đăng ký trước ở quầy lễ tân."}],"related":[{"hanzi":"访问","pinyin":"fǎngwèn","vi":"thăm viếng"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"đến thăm"},{"hanzi":"来宾","pinyin":"láibīn","vi":"khách mời"},{"hanzi":"出访","pinyin":"chūfǎng","vi":"đi thăm nước ngoài"}],"traditional":"來訪"},{"id":"来临","hanzi":"来临","pinyin":"láilín","meaning_vi":"đến, tới, sắp tới","explanation":"来 (lai – đến) + 临 (lâm – đến gần) → (thời điểm, sự kiện) đến gần, ập tới; văn viết.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"🌅","examples":[{"type":"basic","zh":"春天来临了。","pinyin":"Chūntiān láilín le.","vi":"Mùa xuân đã đến."},{"type":"simple","zh":"暴风雨来临之前，渔民们都把船开回了港口。","pinyin":"Bàofēngyǔ láilín zhīqián, yúmínmen dōu bǎ chuán kāi huíle gǎngkǒu.","vi":"Trước khi bão đến, ngư dân đều đưa thuyền về cảng."},{"type":"compound","zh":"虽然考试即将来临，但是他看起来一点儿也不紧张。","pinyin":"Suīrán kǎoshì jíjiāng láilín, dànshì tā kànqǐlái yìdiǎnr yě bù jǐnzhāng.","vi":"Tuy kỳ thi sắp đến nhưng cậu ấy trông chẳng căng thẳng chút nào."}],"related":[{"hanzi":"到来","pinyin":"dàolái","vi":"đến"},{"hanzi":"降临","pinyin":"jiànglín","vi":"giáng lâm"},{"hanzi":"来到","pinyin":"láidào","vi":"đi tới"},{"hanzi":"即将","pinyin":"jíjiāng","vi":"sắp sửa"}],"traditional":"來臨"},{"id":"来年","hanzi":"来年","pinyin":"láinián","meaning_vi":"năm tới, sang năm","explanation":"来 (lai – sắp tới) + 年 (niên – năm) → năm sau, năm kế tiếp; hay dùng trong lời chúc.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"祝你来年好运！","pinyin":"Zhù nǐ láinián hǎoyùn!","vi":"Chúc bạn năm tới may mắn!"},{"type":"simple","zh":"农民们希望来年能有一个好收成。","pinyin":"Nóngmínmen xīwàng láinián néng yǒu yí ge hǎo shōucheng.","vi":"Nông dân mong năm tới được mùa."},{"type":"compound","zh":"如果今年计划完不成，就只能推到来年了。","pinyin":"Rúguǒ jīnnián jìhuà wán buchéng, jiù zhǐnéng tuī dào láinián le.","vi":"Nếu năm nay không hoàn thành kế hoạch thì chỉ có thể dời sang năm sau."}],"related":[{"hanzi":"明年","pinyin":"míngnián","vi":"năm sau"},{"hanzi":"今年","pinyin":"jīnnián","vi":"năm nay"},{"hanzi":"新年","pinyin":"xīnnián","vi":"năm mới"},{"hanzi":"往年","pinyin":"wǎngnián","vi":"những năm trước"}],"traditional":"來年"},{"id":"来源于","hanzi":"来源于","pinyin":"láiyuányú","meaning_vi":"bắt nguồn từ, xuất phát từ","explanation":"来源 (lai nguyên – nguồn gốc) + 于 (vu – từ) → có nguồn gốc từ đâu.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🌱","examples":[{"type":"basic","zh":"这个词来源于英语。","pinyin":"Zhè ge cí láiyuányú Yīngyǔ.","vi":"Từ này bắt nguồn từ tiếng Anh."},{"type":"simple","zh":"他的灵感来源于小时候在农村的生活。","pinyin":"Tā de línggǎn láiyuányú xiǎoshíhou zài nóngcūn de shēnghuó.","vi":"Cảm hứng của anh ấy bắt nguồn từ cuộc sống ở nông thôn hồi nhỏ."},{"type":"compound","zh":"因为这些数据来源于官方统计，所以比较可靠。","pinyin":"Yīnwèi zhèxiē shùjù láiyuányú guānfāng tǒngjì, suǒyǐ bǐjiào kěkào.","vi":"Vì những số liệu này lấy từ thống kê chính thức nên tương đối đáng tin."}],"related":[{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"来自","pinyin":"láizì","vi":"đến từ"},{"hanzi":"源于","pinyin":"yuányú","vi":"bắt nguồn từ"}],"traditional":"來源於"},{"id":"栏","hanzi":"栏","pinyin":"lán","meaning_vi":"lan can, hàng rào; chuồng; cột, mục (báo, bảng)","explanation":"栏 (lan – hàng rào, lan can) → hàng rào ngăn chắn; chuồng gia súc; cũng chỉ cột, mục trên báo hay biểu mẫu.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🚧","examples":[{"type":"basic","zh":"请填写姓名栏。","pinyin":"Qǐng tiánxiě xìngmíng lán.","vi":"Vui lòng điền vào mục họ tên."},{"type":"simple","zh":"这位作家每周在报纸上写一个专栏。","pinyin":"Zhè wèi zuòjiā měizhōu zài bàozhǐ shang xiě yí ge zhuānlán.","vi":"Nhà văn này mỗi tuần viết một chuyên mục trên báo."},{"type":"compound","zh":"虽然他是第一次参加跨栏比赛，但是跑得非常快。","pinyin":"Suīrán tā shì dìyīcì cānjiā kuàlán bǐsài, dànshì pǎo de fēicháng kuài.","vi":"Tuy là lần đầu thi chạy vượt rào nhưng anh ấy chạy rất nhanh."}],"related":[{"hanzi":"栏杆","pinyin":"lángān","vi":"lan can"},{"hanzi":"栏目","pinyin":"lánmù","vi":"chuyên mục"},{"hanzi":"专栏","pinyin":"zhuānlán","vi":"chuyên mục"},{"hanzi":"围栏","pinyin":"wéilán","vi":"hàng rào"}],"traditional":"欄"},{"id":"栏杆","hanzi":"栏杆","pinyin":"lángān","meaning_vi":"lan can, tay vịn","explanation":"栏 (lan – lan can) + 杆 (can – cây sào, thanh) → hàng thanh chắn dọc cầu, ban công, cầu thang.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🌉","examples":[{"type":"basic","zh":"请扶好栏杆。","pinyin":"Qǐng fú hǎo lángān.","vi":"Xin vịn chắc lan can."},{"type":"simple","zh":"她靠在阳台的栏杆上看远处的风景。","pinyin":"Tā kào zài yángtái de lángān shang kàn yuǎnchù de fēngjǐng.","vi":"Cô ấy tựa vào lan can ban công ngắm phong cảnh phía xa."},{"type":"compound","zh":"因为桥上的栏杆太低，所以孩子们在那儿玩很危险。","pinyin":"Yīnwèi qiáo shang de lángān tài dī, suǒyǐ háizimen zài nàr wán hěn wēixiǎn.","vi":"Vì lan can trên cầu quá thấp nên trẻ con chơi ở đó rất nguy hiểm."}],"related":[{"hanzi":"扶手","pinyin":"fúshǒu","vi":"tay vịn"},{"hanzi":"护栏","pinyin":"hùlán","vi":"rào chắn"},{"hanzi":"阳台","pinyin":"yángtái","vi":"ban công"},{"hanzi":"楼梯","pinyin":"lóutī","vi":"cầu thang"}],"traditional":"欄杆"},{"id":"揽","hanzi":"揽","pinyin":"lǎn","meaning_vi":"ôm, kéo vào lòng; ôm đồm, nhận lấy; lôi kéo","explanation":"揽 (lãm – ôm, nắm lấy) → ôm vào lòng; nhận hết về mình (揽活儿, 揽责任); lôi kéo khách (揽客).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🫂","examples":[{"type":"basic","zh":"妈妈把孩子揽在怀里。","pinyin":"Māma bǎ háizi lǎn zài huáili.","vi":"Mẹ ôm đứa trẻ vào lòng."},{"type":"simple","zh":"他什么事都往自己身上揽，结果累坏了。","pinyin":"Tā shénmeshì dōu wǎng zìjǐ shēnshang lǎn, jiéguǒ lèi huàile.","vi":"Việc gì anh ấy cũng ôm vào mình, kết quả là mệt rã rời."},{"type":"compound","zh":"既然这件事是你揽下来的，就应该负责到底。","pinyin":"Jìrán zhè jiàn shì shì nǐ lǎn xiàlái de, jiù yīnggāi fùzé dàodǐ.","vi":"Đã là việc bạn nhận lấy thì phải chịu trách nhiệm đến cùng."}],"related":[{"hanzi":"拥抱","pinyin":"yōngbào","vi":"ôm"},{"hanzi":"承揽","pinyin":"chénglǎn","vi":"nhận thầu"},{"hanzi":"包揽","pinyin":"bāolǎn","vi":"ôm đồm"},{"hanzi":"招揽","pinyin":"zhāolǎn","vi":"chào mời"}],"traditional":"攬"},{"id":"缆车","hanzi":"缆车","pinyin":"lǎnchē","meaning_vi":"cáp treo","explanation":"缆 (lãm – dây cáp) + 车 (xa – xe) → toa chạy trên dây cáp, đưa khách lên núi.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🚡","examples":[{"type":"basic","zh":"我们坐缆车上山吧。","pinyin":"Wǒmen zuò lǎnchē shàngshān ba.","vi":"Chúng ta đi cáp treo lên núi nhé."},{"type":"simple","zh":"坐在缆车里可以看到整片山谷的风景。","pinyin":"Zuò zài lǎnchē li kěyǐ kàndào zhěng piàn shāngǔ de fēngjǐng.","vi":"Ngồi trong cáp treo có thể ngắm toàn cảnh thung lũng."},{"type":"compound","zh":"因为风太大，所以缆车今天暂停运行。","pinyin":"Yīnwèi fēng tài dà, suǒyǐ lǎnchē jīntiān zàntíng yùnxíng.","vi":"Vì gió quá to nên hôm nay cáp treo tạm ngừng hoạt động."}],"related":[{"hanzi":"索道","pinyin":"suǒdào","vi":"đường cáp treo"},{"hanzi":"景区","pinyin":"jǐngqū","vi":"khu du lịch"},{"hanzi":"登山","pinyin":"dēngshān","vi":"leo núi"},{"hanzi":"电缆","pinyin":"diànlǎn","vi":"cáp điện"}],"traditional":"纜車"},{"id":"懒得","hanzi":"懒得","pinyin":"lǎnde","meaning_vi":"lười, chẳng buồn, không muốn (làm gì)","explanation":"懒 (lãn – lười) + 得 (đắc – trợ từ) → chẳng thiết làm việc gì vì lười hoặc chán.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥱","examples":[{"type":"basic","zh":"我懒得做饭。","pinyin":"Wǒ lǎnde zuòfàn.","vi":"Tôi lười nấu cơm."},{"type":"simple","zh":"外面太冷了，我今天懒得出门。","pinyin":"Wàimiàn tài lěng le, wǒ jīntiān lǎnde chūmén.","vi":"Bên ngoài lạnh quá, hôm nay tôi chẳng buồn ra ngoài."},{"type":"compound","zh":"因为他总是不讲道理，所以我懒得跟他争论。","pinyin":"Yīnwèi tā zǒngshì bù jiǎngdàolǐ, suǒyǐ wǒ lǎnde gēn tā zhēnglùn.","vi":"Vì anh ta lúc nào cũng vô lý nên tôi chẳng buồn tranh cãi với anh ta."}],"related":[{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"},{"hanzi":"不想","pinyin":"bùxiǎng","vi":"không muốn"},{"hanzi":"懒洋洋","pinyin":"lǎnyángyáng","vi":"uể oải"},{"hanzi":"勤快","pinyin":"qínkuai","vi":"siêng năng"}],"traditional":"懶得"},{"id":"滥用","hanzi":"滥用","pinyin":"lànyòng","meaning_vi":"lạm dụng, dùng bừa bãi","explanation":"滥 (lạm – quá mức, bừa bãi) + 用 (dụng – dùng) → dùng quá mức hoặc sai mục đích.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚠️","examples":[{"type":"basic","zh":"不要滥用药物。","pinyin":"Bú yào lànyòng yàowù.","vi":"Đừng lạm dụng thuốc."},{"type":"simple","zh":"那名官员因为滥用职权被调查了。","pinyin":"Nà míng guānyuán yīnwèi lànyòng zhíquán bèi diàochá le.","vi":"Viên quan chức đó bị điều tra vì lạm dụng chức quyền."},{"type":"compound","zh":"如果长期滥用抗生素，就会让细菌产生抗药性。","pinyin":"Rúguǒ chángqī lànyòng kàngshēngsù, jiù huì ràng xìjūn chǎnshēng kàngyàoxìng.","vi":"Nếu lạm dụng kháng sinh lâu dài thì sẽ khiến vi khuẩn kháng thuốc."}],"related":[{"hanzi":"滥用职权","pinyin":"lànyòngzhíquán","vi":"lạm quyền"},{"hanzi":"误用","pinyin":"wùyòng","vi":"dùng sai"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"},{"hanzi":"泛滥","pinyin":"fànlàn","vi":"tràn lan"}],"traditional":"濫用"},{"id":"狼","hanzi":"狼","pinyin":"láng","meaning_vi":"con sói","explanation":"狼 (lang – chó sói) → loài thú hoang ăn thịt, sống theo bầy; nghĩa bóng chỉ kẻ hung ác, tham lam.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐺","examples":[{"type":"basic","zh":"远处传来狼叫声。","pinyin":"Yuǎnchù chuánlái láng jiàoshēng.","vi":"Từ xa vọng lại tiếng sói hú."},{"type":"simple","zh":"一群狼在雪地里追赶着一只受伤的鹿。","pinyin":"Yìqún láng zài xuědì li zhuīgǎnzhe yì zhī shòushāng de lù.","vi":"Một bầy sói đang đuổi theo một con nai bị thương trên tuyết."},{"type":"compound","zh":"虽然狼看起来很凶，但是它们一般不主动攻击人。","pinyin":"Suīrán láng kànqǐlái hěn xiōng, dànshì tāmen yìbān bù zhǔdòng gōngjī rén.","vi":"Tuy sói trông rất dữ nhưng chúng thường không chủ động tấn công người."}],"related":[{"hanzi":"狐狸","pinyin":"húli","vi":"cáo"},{"hanzi":"老虎","pinyin":"lǎohǔ","vi":"hổ"},{"hanzi":"狼狈","pinyin":"lángbèi","vi":"nhếch nhác"},{"hanzi":"狼吞虎咽","pinyin":"lángtūnhǔyàn","vi":"ăn ngấu nghiến"}]},{"id":"浪","hanzi":"浪","pinyin":"làng","meaning_vi":"sóng; phóng túng, lêu lổng","explanation":"浪 (lãng – sóng nước) → làn sóng; cũng chỉ sự buông thả, phóng đãng (浪费, 流浪).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"今天海上浪很大。","pinyin":"Jīntiān hǎishang làng hěn dà.","vi":"Hôm nay trên biển sóng rất to."},{"type":"simple","zh":"一个大浪打过来，把他们的小船掀翻了。","pinyin":"Yí ge dàlàng dǎ guòlái, bǎ tāmen de xiǎochuán xiānfān le.","vi":"Một con sóng lớn ập tới làm lật chiếc thuyền nhỏ của họ."},{"type":"compound","zh":"因为风浪太大，所以今天的船班都取消了。","pinyin":"Yīnwèi fēnglàng tài dà, suǒyǐ jīntiān de chuán bān dōu qǔxiāo le.","vi":"Vì sóng gió quá lớn nên các chuyến tàu hôm nay đều bị hủy."}],"related":[{"hanzi":"波浪","pinyin":"bōlàng","vi":"sóng"},{"hanzi":"海浪","pinyin":"hǎilàng","vi":"sóng biển"},{"hanzi":"浪潮","pinyin":"làngcháo","vi":"làn sóng, trào lưu"},{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"}]},{"id":"劳动力","hanzi":"劳动力","pinyin":"láodònglì","meaning_vi":"sức lao động, lực lượng lao động, nhân lực","explanation":"劳动 (lao động) + 力 (lực – sức) → khả năng làm việc của con người; cũng chỉ người lao động nói chung.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👷","examples":[{"type":"basic","zh":"这里劳动力便宜。","pinyin":"Zhèlǐ láodònglì piányi.","vi":"Ở đây nhân công rẻ."},{"type":"simple","zh":"很多年轻劳动力都去了大城市打工。","pinyin":"Hěn duō niánqīng láodònglì dōu qùle dàchéngshì dǎgōng.","vi":"Nhiều lao động trẻ đều lên thành phố lớn làm thuê."},{"type":"compound","zh":"因为农村缺少劳动力，所以很多土地都荒了。","pinyin":"Yīnwèi nóngcūn quēshǎo láodònglì, suǒyǐ hěn duō tǔdì dōu huāng le.","vi":"Vì nông thôn thiếu nhân lực nên nhiều ruộng đất bị bỏ hoang."}],"related":[{"hanzi":"人力","pinyin":"rénlì","vi":"nhân lực"},{"hanzi":"劳动","pinyin":"láodòng","vi":"lao động"},{"hanzi":"劳务","pinyin":"láowù","vi":"dịch vụ lao động"},{"hanzi":"工人","pinyin":"gōngrén","vi":"công nhân"}],"traditional":"勞動力"},{"id":"劳务","hanzi":"劳务","pinyin":"láowù","meaning_vi":"lao vụ, dịch vụ lao động, công việc làm thuê","explanation":"劳 (lao – lao động) + 务 (vụ – công việc) → công việc lao động làm để lấy thù lao; hay dùng 劳务费, 劳务输出.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"他拿到了劳务费。","pinyin":"Tā nádàole láowùfèi.","vi":"Anh ấy đã nhận được tiền công."},{"type":"simple","zh":"每年都有大批工人通过劳务输出到国外工作。","pinyin":"Měinián dōu yǒu dàpī gōngrén tōngguò láowù shūchū dào guówài gōngzuò.","vi":"Mỗi năm đều có rất nhiều công nhân đi xuất khẩu lao động ra nước ngoài."},{"type":"compound","zh":"如果签了劳务合同，就要按照合同规定完成工作。","pinyin":"Rúguǒ qiānle láowù hétong, jiùyào ànzhào hétong guīdìng wánchéng gōngzuò.","vi":"Nếu đã ký hợp đồng lao động thì phải hoàn thành công việc theo quy định hợp đồng."}],"related":[{"hanzi":"劳动力","pinyin":"láodònglì","vi":"sức lao động"},{"hanzi":"服务","pinyin":"fúwù","vi":"dịch vụ"},{"hanzi":"报酬","pinyin":"bàochou","vi":"thù lao"},{"hanzi":"雇佣","pinyin":"gùyōng","vi":"thuê mướn"}],"traditional":"勞務"},{"id":"牢记","hanzi":"牢记","pinyin":"láojì","meaning_vi":"ghi nhớ, khắc ghi","explanation":"牢 (lao – chắc chắn) + 记 (ký – ghi nhớ) → nhớ thật chắc, không quên.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"请牢记密码。","pinyin":"Qǐng láojì mìmǎ.","vi":"Hãy ghi nhớ mật khẩu."},{"type":"simple","zh":"我一直牢记着父亲临走前对我说的话。","pinyin":"Wǒ yìzhí láojìzhe fùqīn línzǒu qián duì wǒ shuō dehuà.","vi":"Tôi luôn khắc ghi lời cha dặn trước lúc ra đi."},{"type":"compound","zh":"只要牢记这几条安全规定，就不容易出事故。","pinyin":"Zhǐyào láojì zhè jǐ tiáo ānquán guīdìng, jiù bù róngyì chū shìgù.","vi":"Chỉ cần ghi nhớ mấy quy định an toàn này thì sẽ khó xảy ra tai nạn."}],"related":[{"hanzi":"记住","pinyin":"jìzhù","vi":"nhớ lấy"},{"hanzi":"铭记","pinyin":"míngjì","vi":"khắc ghi"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"quên"},{"hanzi":"牢牢","pinyin":"láoláo","vi":"chắc chắn"}],"traditional":"牢記"},{"id":"牢牢","hanzi":"牢牢","pinyin":"láoláo","meaning_vi":"chắc chắn, vững vàng, chặt chẽ","explanation":"牢 (lao – chắc chắn) lặp lại → rất chắc, rất chặt; thường đi với 记住, 抓住, 握住.","hsk_level":"7-9","tags":["pho-tu","nhan-thuc"],"image":"🔒","examples":[{"type":"basic","zh":"他牢牢抓住绳子。","pinyin":"Tā láoláo zhuāzhù shéngzi.","vi":"Anh ấy nắm chặt sợi dây."},{"type":"simple","zh":"老师讲的这些重点，我都牢牢记在心里了。","pinyin":"Lǎoshī jiǎng de zhèxiē zhòngdiǎn, wǒ dōu láo láojì zài xīnli le.","vi":"Những trọng điểm thầy giảng, tôi đều ghi nhớ chắc trong lòng."},{"type":"compound","zh":"只要牢牢抓住这次机会，你就能成功。","pinyin":"Zhǐyào láoláo zhuāzhù zhè cì jīhuì, nǐ jiù néng chénggōng.","vi":"Chỉ cần nắm chắc cơ hội lần này thì bạn sẽ thành công."}],"related":[{"hanzi":"牢固","pinyin":"láogù","vi":"vững chắc"},{"hanzi":"紧紧","pinyin":"jǐnjǐn","vi":"chặt chẽ"},{"hanzi":"牢记","pinyin":"láojì","vi":"ghi nhớ"},{"hanzi":"稳稳","pinyin":"wěnwěn","vi":"vững vàng"}]},{"id":"老伴儿","hanzi":"老伴儿","pinyin":"lǎobànr","meaning_vi":"bạn đời (vợ hoặc chồng khi đã già)","explanation":"老 (lão – già) + 伴 (bạn – bạn đồng hành) + 儿 (nhi hóa) → người bạn đời cùng nhau sống đến già; cách gọi thân mật.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👵","examples":[{"type":"basic","zh":"这是我的老伴儿。","pinyin":"Zhè shì wǒ de lǎobànr.","vi":"Đây là bà nhà tôi."},{"type":"simple","zh":"每天晚饭后，爷爷都和老伴儿去公园散步。","pinyin":"Měitiān wǎnfàn hòu, yéye dōu hé lǎobànr qù gōngyuán sànbù.","vi":"Mỗi tối sau bữa cơm, ông đều cùng bà đi dạo công viên."},{"type":"compound","zh":"自从老伴儿去世以后，他一个人住在老房子里。","pinyin":"Zìcóng lǎobànr qùshì yǐhòu, tā yígerén zhùzài lǎo fángzi li.","vi":"Từ khi bạn đời qua đời, ông ấy sống một mình trong căn nhà cũ."}],"related":[{"hanzi":"老伴","pinyin":"lǎobàn","vi":"bạn đời"},{"hanzi":"伴侣","pinyin":"bànlǚ","vi":"bạn đời"},{"hanzi":"夫妻","pinyin":"fūqī","vi":"vợ chồng"},{"hanzi":"老两口","pinyin":"lǎoliǎngkǒu","vi":"đôi vợ chồng già"}],"traditional":"老伴兒"},{"id":"老大","hanzi":"老大","pinyin":"lǎodà","meaning_vi":"con cả; đại ca, người đứng đầu; rất","explanation":"老 (lão – tiền tố) + 大 (đại – lớn) → người con lớn nhất; cũng chỉ thủ lĩnh một nhóm, hoặc làm phó từ nghĩa \"rất\" (老大不高兴).","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👑","examples":[{"type":"basic","zh":"我是家里的老大。","pinyin":"Wǒ shì jiāli de lǎodà.","vi":"Tôi là con cả trong nhà."},{"type":"simple","zh":"他是这个乐队的老大，什么事都由他决定。","pinyin":"Tā shì zhè ge yuèduì de lǎodà, shénmeshì dōu yóu tā juédìng.","vi":"Anh ấy là trưởng nhóm của ban nhạc này, việc gì cũng do anh ấy quyết."},{"type":"compound","zh":"因为是家里的老大，所以他从小就很照顾弟弟妹妹。","pinyin":"Yīnwèi shì jiāli de lǎodà, suǒyǐ tā cóngxiǎo jiù hěn zhàogù dìdi mèimei.","vi":"Vì là con cả trong nhà nên từ nhỏ anh ấy đã rất chăm sóc các em."}],"related":[{"hanzi":"老二","pinyin":"lǎo'èr","vi":"con thứ hai"},{"hanzi":"老幺","pinyin":"lǎoyāo","vi":"con út"},{"hanzi":"大哥","pinyin":"dàgē","vi":"anh cả"},{"hanzi":"首领","pinyin":"shǒulǐng","vi":"thủ lĩnh"}]},{"id":"老汉","hanzi":"老汉","pinyin":"lǎohàn","meaning_vi":"ông già, ông lão","explanation":"老 (lão – già) + 汉 (hán – người đàn ông) → người đàn ông lớn tuổi, thường ở nông thôn.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"老汉正在喂鸡。","pinyin":"Lǎohàn zhèngzài wèi jī.","vi":"Ông lão đang cho gà ăn."},{"type":"simple","zh":"村口的老汉每天都坐在树下抽烟。","pinyin":"Cūn kǒu de lǎohàn měitiān dōu zuò zài shù xià chōuyān.","vi":"Ông lão ở đầu làng ngày nào cũng ngồi dưới gốc cây hút thuốc."},{"type":"compound","zh":"虽然老汉已经七十多岁了，但是身体还很硬朗。","pinyin":"Suīrán lǎohàn yǐjīng qīshí duō suì le, dànshì shēntǐ hái hěn yìnglang.","vi":"Tuy ông lão đã hơn bảy mươi tuổi nhưng sức khỏe vẫn còn rất cứng cáp."}],"related":[{"hanzi":"老人","pinyin":"lǎorén","vi":"người già"},{"hanzi":"老头儿","pinyin":"lǎotóur","vi":"ông già"},{"hanzi":"大爷","pinyin":"dàye","vi":"ông, bác"},{"hanzi":"老太太","pinyin":"lǎotàitai","vi":"bà cụ"}],"traditional":"老漢"},{"id":"老化","hanzi":"老化","pinyin":"lǎohuà","meaning_vi":"lão hóa, xuống cấp, già hóa","explanation":"老 (lão – già) + 化 (hóa – biến thành) → trở nên già cũ: cơ thể, vật liệu, dân số hay kiến thức lỗi thời.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"⏳","examples":[{"type":"basic","zh":"电线已经老化了。","pinyin":"Diànxiàn yǐjīng lǎohuà le.","vi":"Dây điện đã xuống cấp rồi."},{"type":"simple","zh":"人口老化是很多国家面临的共同问题。","pinyin":"Rénkǒu lǎohuà shì hěn duō guójiā miànlín de gòngtóng wèntí.","vi":"Già hóa dân số là vấn đề chung mà nhiều nước đang đối mặt."},{"type":"compound","zh":"如果不经常学习，知识就会慢慢老化。","pinyin":"Rúguǒ bù jīngcháng xuéxí, zhīshi jiù huì mànmàn lǎohuà.","vi":"Nếu không thường xuyên học tập thì kiến thức sẽ dần lỗi thời."}],"related":[{"hanzi":"衰老","pinyin":"shuāilǎo","vi":"già yếu"},{"hanzi":"老龄化","pinyin":"lǎolínghuà","vi":"già hóa"},{"hanzi":"更新","pinyin":"gēngxīn","vi":"đổi mới"},{"hanzi":"磨损","pinyin":"mósǔn","vi":"hao mòn"}]},{"id":"老人家","hanzi":"老人家","pinyin":"lǎorénjia","meaning_vi":"cụ, ông bà (cách gọi kính trọng người già)","explanation":"老人 (lão nhân – người già) + 家 (gia – hậu tố tôn kính) → cách gọi lịch sự, kính trọng dành cho người lớn tuổi.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧓","examples":[{"type":"basic","zh":"老人家，您慢点儿走。","pinyin":"Lǎorénjia, nín màn diǎnr zǒu.","vi":"Cụ ơi, cụ đi chậm thôi ạ."},{"type":"simple","zh":"他每个周末都回老家看望两位老人家。","pinyin":"Tā měi ge zhōumò dōu huílǎojiā kànwàng liǎng wèi lǎorénjia.","vi":"Cuối tuần nào anh ấy cũng về quê thăm hai cụ."},{"type":"compound","zh":"虽然老人家年纪大了，但是记性还特别好。","pinyin":"Suīrán lǎorénjia niánjì dà le, dànshì jìxing hái tèbié hǎo.","vi":"Tuy cụ đã cao tuổi nhưng trí nhớ vẫn đặc biệt tốt."}],"related":[{"hanzi":"老人","pinyin":"lǎorén","vi":"người già"},{"hanzi":"长辈","pinyin":"zhǎngbèi","vi":"bề trên"},{"hanzi":"老年人","pinyin":"lǎoniánrén","vi":"người cao tuổi"},{"hanzi":"大爷","pinyin":"dàye","vi":"ông, bác"}]},{"id":"老实说","hanzi":"老实说","pinyin":"lǎoshíshuō","meaning_vi":"nói thật, thành thật mà nói","explanation":"老实 (lão thực – thật thà) + 说 (thuyết – nói) → nói thật lòng; dùng ở đầu câu như một lời rào đón.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙋","examples":[{"type":"basic","zh":"老实说，我不喜欢。","pinyin":"Lǎoshíshuō, wǒ bù xǐhuan.","vi":"Nói thật, tôi không thích."},{"type":"simple","zh":"老实说，这部电影没有我想象的那么好看。","pinyin":"Lǎoshíshuō, zhè bù diànyǐng méiyǒu wǒ xiǎngxiàng de nàme hǎokàn.","vi":"Nói thật, bộ phim này không hay như tôi tưởng."},{"type":"compound","zh":"老实说，虽然我很想帮你，但是我也没有那么多钱。","pinyin":"Lǎoshíshuō, suīrán wǒ hěn xiǎng bāng nǐ, dànshì wǒ yě méiyǒu nàme duō qián.","vi":"Nói thật, tuy tôi rất muốn giúp bạn nhưng tôi cũng không có nhiều tiền như thế."}],"related":[{"hanzi":"说实话","pinyin":"shuōshíhuà","vi":"nói thật"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thẳng thắn"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"其实","pinyin":"qíshí","vi":"thật ra"}],"traditional":"老實說"},{"id":"老远","hanzi":"老远","pinyin":"lǎoyuǎn","meaning_vi":"rất xa, xa tít","explanation":"老 (lão – rất, khẩu ngữ) + 远 (viễn – xa) → khoảng cách rất xa; khẩu ngữ.","hsk_level":"7-9","tags":["pho-tu","dia-diem"],"image":"🔭","examples":[{"type":"basic","zh":"他老远就看见我了。","pinyin":"Tā lǎoyuǎn jiù kànjiàn wǒ le.","vi":"Từ xa tít anh ấy đã nhìn thấy tôi."},{"type":"simple","zh":"她老远跑来看我，我真的很感动。","pinyin":"Tā lǎoyuǎn pǎo lái kàn wǒ, wǒ zhēn de hěn gǎndòng.","vi":"Cô ấy lặn lội từ xa đến thăm tôi, tôi thật sự rất cảm động."},{"type":"compound","zh":"虽然离得老远，但是我还是闻到了花香。","pinyin":"Suīrán lí de lǎoyuǎn, dànshì wǒ háishì wéndàole huāxiāng.","vi":"Tuy cách rất xa nhưng tôi vẫn ngửi thấy hương hoa."}],"related":[{"hanzi":"遥远","pinyin":"yáoyuǎn","vi":"xa xôi"},{"hanzi":"远处","pinyin":"yuǎnchù","vi":"nơi xa"},{"hanzi":"老半天","pinyin":"lǎobàntiān","vi":"rất lâu"},{"hanzi":"附近","pinyin":"fùjìn","vi":"gần đây"}],"traditional":"老遠"},{"id":"姥爷","hanzi":"姥爷","pinyin":"lǎoye","meaning_vi":"ông ngoại","explanation":"姥 (lão – bà ngoại, mẹ) + 爷 (gia – ông) → ông ngoại, cách gọi khẩu ngữ ở miền Bắc Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👴","examples":[{"type":"basic","zh":"姥爷今年八十岁。","pinyin":"Lǎoye jīnnián bāshí suì.","vi":"Năm nay ông ngoại tám mươi tuổi."},{"type":"simple","zh":"放暑假时，我常去乡下的姥爷家玩儿。","pinyin":"Fàngshǔjià shí, wǒ cháng qù xiāngxià de lǎoye jiā wánr.","vi":"Nghỉ hè tôi thường về nhà ông ngoại ở quê chơi."},{"type":"compound","zh":"虽然姥爷不识字，但是他讲的故事特别有意思。","pinyin":"Suīrán lǎoye bù shízì, dànshì tā jiǎng de gùshi tèbié yǒuyìsi.","vi":"Tuy ông ngoại không biết chữ nhưng chuyện ông kể cực kỳ thú vị."}],"related":[{"hanzi":"姥姥","pinyin":"lǎolao","vi":"bà ngoại"},{"hanzi":"外公","pinyin":"wàigōng","vi":"ông ngoại"},{"hanzi":"爷爷","pinyin":"yéye","vi":"ông nội"},{"hanzi":"外孙","pinyin":"wàisūn","vi":"cháu ngoại"}],"traditional":"姥爺"},{"id":"潦草","hanzi":"潦草","pinyin":"liáocǎo","meaning_vi":"nguệch ngoạc, cẩu thả, qua loa","explanation":"潦 (lạo – cẩu thả) + 草 (thảo – sơ sài, chữ thảo) → viết chữ nguệch ngoạc hoặc làm việc qua loa.","hsk_level":"7-9","tags":["tinh-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"他的字写得很潦草。","pinyin":"Tā de zì xiě de hěn liáocǎo.","vi":"Chữ anh ấy viết rất nguệch ngoạc."},{"type":"simple","zh":"医生开的药方太潦草，我一个字也看不懂。","pinyin":"Yīshēng kāi de yàofāng tài liáocǎo, wǒ yí ge zì yě kànbudǒng.","vi":"Đơn thuốc bác sĩ kê viết quá nguệch ngoạc, tôi không đọc được chữ nào."},{"type":"compound","zh":"如果作业写得太潦草，老师就会让你重写。","pinyin":"Rúguǒ zuòyè xiě de tài liáocǎo, lǎoshī jiù huì ràng nǐ chóng xiě.","vi":"Nếu bài tập viết quá cẩu thả thì thầy sẽ bắt bạn viết lại."}],"related":[{"hanzi":"马虎","pinyin":"mǎhu","vi":"cẩu thả"},{"hanzi":"草率","pinyin":"cǎoshuài","vi":"qua loa"},{"hanzi":"工整","pinyin":"gōngzhěng","vi":"ngay ngắn"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"nghiêm túc"}]},{"id":"涝","hanzi":"涝","pinyin":"lào","meaning_vi":"úng lụt, ngập úng","explanation":"涝 (lạo – úng nước) → mưa nhiều làm ruộng đồng ngập nước; trái với 旱 (hạn).","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"🌧️","examples":[{"type":"basic","zh":"今年夏天涝了。","pinyin":"Jīnnián xiàtiān lào le.","vi":"Mùa hè năm nay bị úng lụt."},{"type":"simple","zh":"连下了半个月的雨，地里的庄稼都涝了。","pinyin":"Lián xiàle bàn geyuè de yǔ, dì li de zhuāngjia dōu lào le.","vi":"Mưa liền nửa tháng, hoa màu ngoài đồng đều bị ngập úng."},{"type":"compound","zh":"因为这里地势低，所以一下大雨就容易涝。","pinyin":"Yīnwèi zhèlǐ dìshì dī, suǒyǐ yíxià dàyǔ jiù róngyì lào.","vi":"Vì địa thế ở đây thấp nên hễ mưa to là dễ bị úng."}],"related":[{"hanzi":"旱","pinyin":"hàn","vi":"hạn hán"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"内涝","pinyin":"nèilào","vi":"ngập úng"},{"hanzi":"排水","pinyin":"páishuǐ","vi":"thoát nước"}],"traditional":"澇"},{"id":"乐器","hanzi":"乐器","pinyin":"yuèqì","meaning_vi":"nhạc cụ","explanation":"乐 (nhạc – âm nhạc) + 器 (khí – đồ dùng) → dụng cụ dùng để chơi nhạc.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎻","examples":[{"type":"basic","zh":"你会什么乐器？","pinyin":"Nǐ huì shénme yuèqì?","vi":"Bạn biết chơi nhạc cụ gì?"},{"type":"simple","zh":"二胡是一种很有特色的中国传统乐器。","pinyin":"Èrhú shì yì zhǒng hěn yǒu tèsè de Zhōngguó chuántǒng yuèqì.","vi":"Đàn nhị là một loại nhạc cụ truyền thống Trung Quốc rất đặc sắc."},{"type":"compound","zh":"如果从小学一种乐器，就能培养孩子的耐心。","pinyin":"Rúguǒ cóng xiǎoxué yì zhǒng yuèqì, jiù néng péiyǎng háizi de nàixīn.","vi":"Nếu học một nhạc cụ từ nhỏ thì có thể rèn luyện tính kiên nhẫn cho trẻ."}],"related":[{"hanzi":"音乐","pinyin":"yīnyuè","vi":"âm nhạc"},{"hanzi":"钢琴","pinyin":"gāngqín","vi":"đàn piano"},{"hanzi":"乐队","pinyin":"yuèduì","vi":"ban nhạc"},{"hanzi":"演奏","pinyin":"yǎnzòu","vi":"biểu diễn nhạc"}],"traditional":"樂器"},{"id":"乐园","hanzi":"乐园","pinyin":"lèyuán","meaning_vi":"thiên đường, khu vui chơi","explanation":"乐 (lạc – vui) + 园 (viên – vườn) → khu vườn vui vẻ; chỉ nơi vui chơi hoặc chốn thiên đường.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎡","examples":[{"type":"basic","zh":"这里是孩子们的乐园。","pinyin":"Zhèlǐ shì háizimen de lèyuán.","vi":"Đây là thiên đường của trẻ con."},{"type":"simple","zh":"周末我们全家去了新开的水上乐园。","pinyin":"Zhōumò wǒmen quán jiāqùle xīn kāi de shuǐshàng lèyuán.","vi":"Cuối tuần cả nhà chúng tôi đi công viên nước mới mở."},{"type":"compound","zh":"虽然这个乐园不大，但是游乐项目非常多。","pinyin":"Suīrán zhè ge lèyuán búdà, dànshì yóulè xiàngmù fēichángduō.","vi":"Tuy khu vui chơi này không lớn nhưng trò chơi rất nhiều."}],"related":[{"hanzi":"天堂","pinyin":"tiāntáng","vi":"thiên đường"},{"hanzi":"游乐场","pinyin":"yóulèchǎng","vi":"khu vui chơi"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"công viên"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"vui vẻ"}],"traditional":"樂園"},{"id":"了结","hanzi":"了结","pinyin":"liǎojié","meaning_vi":"kết thúc, giải quyết xong, thanh toán dứt điểm","explanation":"了 (liễu – xong, hết) + 结 (kết – kết thúc) → giải quyết cho xong xuôi một việc, vụ án, món nợ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"这件事已经了结了。","pinyin":"Zhè jiàn shì yǐjīng liǎojié le.","vi":"Chuyện này đã giải quyết xong rồi."},{"type":"simple","zh":"双方经过协商，终于了结了这场官司。","pinyin":"Shuāngfāng jīngguò xiéshāng, zhōngyú liǎojiéle zhè chǎng guānsi.","vi":"Hai bên qua thương lượng cuối cùng đã kết thúc vụ kiện này."},{"type":"compound","zh":"只要把欠的钱还清，我们之间的事就算了结了。","pinyin":"Zhǐyào bǎ qiàn de qián huán qīng, wǒmen zhījiān de shì jiù suànliǎo jiéle.","vi":"Chỉ cần trả hết tiền nợ thì chuyện giữa chúng ta coi như xong."}],"related":[{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"},{"hanzi":"解决","pinyin":"jiějué","vi":"giải quyết"},{"hanzi":"了却","pinyin":"liǎoquè","vi":"giải quyết xong"},{"hanzi":"完结","pinyin":"wánjié","vi":"hoàn tất"}],"traditional":"了結"},{"id":"了却","hanzi":"了却","pinyin":"liǎoquè","meaning_vi":"hoàn thành, giải quyết xong, toại (tâm nguyện)","explanation":"了 (liễu – xong) + 却 (khước – bỏ đi) → giải quyết xong cho nhẹ lòng; thường đi với 心愿, 心事.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🕊️","examples":[{"type":"basic","zh":"他终于了却了心愿。","pinyin":"Tā zhōngyú liǎoquèle xīnyuàn.","vi":"Cuối cùng ông ấy đã toại nguyện."},{"type":"simple","zh":"看到儿子成家，老人了却了一桩心事。","pinyin":"Kàndào érzi chéngjiā, lǎorén liǎoquèle yì zhuāng xīnshì.","vi":"Thấy con trai lập gia đình, ông cụ đã trút được một nỗi lòng."},{"type":"compound","zh":"如果能回故乡看一眼，我就了却了最后的心愿。","pinyin":"Rúguǒ néng huí gùxiāng kàn yìyǎn, wǒ jiù liǎoquèle zuìhòu de xīnyuàn.","vi":"Nếu được về quê nhìn một lần thì tôi đã toại tâm nguyện cuối cùng."}],"related":[{"hanzi":"了结","pinyin":"liǎojié","vi":"kết thúc"},{"hanzi":"心愿","pinyin":"xīnyuàn","vi":"tâm nguyện"},{"hanzi":"完成","pinyin":"wánchéng","vi":"hoàn thành"},{"hanzi":"实现","pinyin":"shíxiàn","vi":"thực hiện"}],"traditional":"了卻"},{"id":"勒","hanzi":"勒","pinyin":"lè","meaning_vi":"ghìm (cương); ép buộc; khắc","explanation":"勒 (lặc – dây cương) → kéo cương ghìm ngựa; nghĩa mở rộng: ép buộc (勒令), khắc chữ (勒石); đọc lēi khi nghĩa là buộc chặt.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🐎","examples":[{"type":"basic","zh":"他勒住了马。","pinyin":"Tā lè zhùle mǎ.","vi":"Anh ấy ghìm cương ngựa lại."},{"type":"simple","zh":"因为违反规定，这家工厂被勒令停产。","pinyin":"Yīnwèi wéifǎn guīdìng, zhè jiā gōngchǎng bèi lèlìng tíngchǎn.","vi":"Vì vi phạm quy định, nhà máy này bị buộc phải ngừng sản xuất."},{"type":"compound","zh":"如果他不及时勒住缰绳，马就会冲下山坡。","pinyin":"Rúguǒ tā bù jíshí lè zhù jiāngshéng, mǎ jiù huì chōng xiàshān pō.","vi":"Nếu anh ấy không kịp ghìm dây cương thì ngựa sẽ lao xuống dốc."}],"related":[{"hanzi":"勒令","pinyin":"lèlìng","vi":"ra lệnh buộc"},{"hanzi":"勒索","pinyin":"lèsuǒ","vi":"tống tiền"},{"hanzi":"缰绳","pinyin":"jiāngshéng","vi":"dây cương"},{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"ép buộc"}]},{"id":"类别","hanzi":"类别","pinyin":"lèibié","meaning_vi":"loại, hạng mục, phân loại","explanation":"类 (loại – loại) + 别 (biệt – phân biệt) → nhóm được phân chia theo đặc điểm chung.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🗂️","examples":[{"type":"basic","zh":"这些书属于什么类别？","pinyin":"Zhèxiē shū shǔyú shénme lèibié?","vi":"Những cuốn sách này thuộc loại nào?"},{"type":"simple","zh":"商品按照不同的类别摆放在不同的货架上。","pinyin":"Shāngpǐn ànzhào bùtóng de lèibié bǎifàng zài bùtóng de huòjià shang.","vi":"Hàng hóa được bày trên các kệ khác nhau theo từng loại."},{"type":"compound","zh":"如果把文件按类别整理好，就很容易找到。","pinyin":"Rúguǒ bǎ wénjiàn àn lèibié zhěnglǐ hǎo, jiù hěn róngyì zhǎodào.","vi":"Nếu sắp xếp tài liệu theo loại thì sẽ rất dễ tìm."}],"related":[{"hanzi":"种类","pinyin":"zhǒnglèi","vi":"chủng loại"},{"hanzi":"分类","pinyin":"fēnlèi","vi":"phân loại"},{"hanzi":"类型","pinyin":"lèixíng","vi":"loại hình"},{"hanzi":"级别","pinyin":"jíbié","vi":"cấp bậc"}],"traditional":"類別"},{"id":"累计","hanzi":"累计","pinyin":"lěijì","meaning_vi":"cộng dồn, tính tổng, tổng cộng","explanation":"累 (lũy – chồng chất) + 计 (kế – tính) → cộng dồn các con số lại để tính tổng.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"🧮","examples":[{"type":"basic","zh":"我们累计走了二十公里。","pinyin":"Wǒmen lěijì zǒule èrshí gōnglǐ.","vi":"Chúng tôi đã đi tổng cộng hai mươi cây số."},{"type":"simple","zh":"这个视频的播放量已经累计超过一百万次。","pinyin":"Zhè ge shìpín de bōfàng liàng yǐjīng lěijì chāoguò yī bǎiwàn cì.","vi":"Lượt xem của video này cộng dồn đã vượt quá một triệu."},{"type":"compound","zh":"虽然每天只存十块钱，但是一年累计下来也有三千多。","pinyin":"Suīrán měitiān zhǐ cún shí kuài qián, dànshì yì nián lěijì xiàlái yě yǒu sān qiān duō.","vi":"Tuy mỗi ngày chỉ để dành mười đồng, nhưng cộng dồn cả năm cũng được hơn ba nghìn."}],"related":[{"hanzi":"累积","pinyin":"lěijī","vi":"tích lũy"},{"hanzi":"总计","pinyin":"zǒngjì","vi":"tổng cộng"},{"hanzi":"合计","pinyin":"héjì","vi":"cộng lại"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"}],"traditional":"累計"},{"id":"棱角","hanzi":"棱角","pinyin":"léngjiǎo","meaning_vi":"góc cạnh, sự sắc sảo, tính gai góc","explanation":"棱 (lăng – cạnh) + 角 (giác – góc) → góc cạnh của đồ vật; nghĩa bóng chỉ tính cách sắc sảo, gai góc.","hsk_level":"7-9","tags":["danh-tu"],"image":"📐","examples":[{"type":"basic","zh":"这块石头棱角很尖。","pinyin":"Zhè kuài shítou léngjiǎo hěn jiān.","vi":"Hòn đá này góc cạnh rất sắc."},{"type":"simple","zh":"经过多年磨炼，他性格上的棱角少了很多。","pinyin":"Jīngguò duōnián móliàn, tā xìnggé shang de léngjiǎo shǎole hěn duō.","vi":"Qua nhiều năm tôi luyện, tính cách gai góc của anh ấy đã bớt đi nhiều."},{"type":"compound","zh":"因为桌子的棱角太尖，所以妈妈给它包上了软垫。","pinyin":"Yīnwèi zhuōzi de léngjiǎo tài jiān, suǒyǐ māma gěi tā bāo shangle ruǎn diàn.","vi":"Vì góc bàn quá nhọn nên mẹ đã bọc đệm mềm vào."}],"related":[{"hanzi":"棱","pinyin":"léng","vi":"cạnh"},{"hanzi":"角落","pinyin":"jiǎoluò","vi":"góc"},{"hanzi":"锋芒","pinyin":"fēngmáng","vi":"sự sắc sảo"},{"hanzi":"圆滑","pinyin":"yuánhuá","vi":"khéo léo, tròn trịa"}],"traditional":"稜角"},{"id":"冷冻","hanzi":"冷冻","pinyin":"lěngdòng","meaning_vi":"đông lạnh, cấp đông","explanation":"冷 (lãnh – lạnh) + 冻 (đống – đông cứng) → làm lạnh đến đông cứng để bảo quản.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🧊","examples":[{"type":"basic","zh":"肉要冷冻保存。","pinyin":"Ròu yào lěngdòng bǎocún.","vi":"Thịt cần bảo quản đông lạnh."},{"type":"simple","zh":"我把剩下的饺子放进冰箱冷冻起来了。","pinyin":"Wǒ bǎ shèngxià de jiǎozi fàngjìn bīngxiāng lěngdòng qǐlái le.","vi":"Tôi đã cho chỗ sủi cảo còn lại vào tủ lạnh cấp đông."},{"type":"compound","zh":"如果买回来的鱼不马上冷冻，就很容易变质。","pinyin":"Rúguǒ mǎi huílái de yú bù mǎshàng lěngdòng, jiù hěn róngyì biànzhì.","vi":"Nếu cá mua về không cấp đông ngay thì rất dễ bị hỏng."}],"related":[{"hanzi":"冷藏","pinyin":"lěngcáng","vi":"ướp lạnh"},{"hanzi":"解冻","pinyin":"jiědòng","vi":"rã đông"},{"hanzi":"速冻","pinyin":"sùdòng","vi":"cấp đông nhanh"},{"hanzi":"冰箱","pinyin":"bīngxiāng","vi":"tủ lạnh"}],"traditional":"冷凍"},{"id":"冷酷无情","hanzi":"冷酷无情","pinyin":"lěngkù-wúqíng","meaning_vi":"lạnh lùng tàn nhẫn, vô tình","explanation":"冷酷 (lãnh khốc – lạnh lùng, tàn khốc) + 无情 (vô tình – không có tình cảm) → lạnh lùng, tàn nhẫn, không chút tình người.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🥶","examples":[{"type":"basic","zh":"他是个冷酷无情的人。","pinyin":"Tā shì ge lěngkùwúqíng de rén.","vi":"Anh ta là người lạnh lùng vô tình."},{"type":"simple","zh":"老板冷酷无情地辞退了生病的员工。","pinyin":"Lǎobǎn lěngkùwúqíng de cítuìle shēngbìng de yuángōng.","vi":"Ông chủ lạnh lùng sa thải nhân viên đang bị ốm."},{"type":"compound","zh":"虽然他看起来冷酷无情，但是心里其实很关心大家。","pinyin":"Suīrán tā kànqǐlái lěngkùwúqíng, dànshì xīnli qíshí hěn guānxīn dàjiā.","vi":"Tuy trông anh ấy lạnh lùng vô tình nhưng trong lòng thật ra rất quan tâm mọi người."}],"related":[{"hanzi":"冷酷","pinyin":"lěngkù","vi":"lạnh lùng tàn khốc"},{"hanzi":"无情","pinyin":"wúqíng","vi":"vô tình"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"}],"traditional":"冷酷無情"},{"id":"冷笑","hanzi":"冷笑","pinyin":"lěngxiào","meaning_vi":"cười nhạt, cười khẩy","explanation":"冷 (lãnh – lạnh) + 笑 (tiếu – cười) → nụ cười lạnh lùng, tỏ ý khinh miệt hoặc bất mãn.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😏","examples":[{"type":"basic","zh":"他冷笑了一声。","pinyin":"Tā lěngxiàole yìshēng.","vi":"Anh ta cười khẩy một tiếng."},{"type":"simple","zh":"听完我的解释，她只是冷笑着摇了摇头。","pinyin":"Tīng wán wǒ de jiěshì, tā zhǐshì lěngxiàozhe yáole yáotóu.","vi":"Nghe xong lời giải thích của tôi, cô ấy chỉ cười nhạt và lắc đầu."},{"type":"compound","zh":"对手一看到我们的阵容，就忍不住冷笑起来。","pinyin":"Duìshǒu yí kàndào wǒmen de zhènróng, jiù rěnbúzhù lěngxiào qǐlái.","vi":"Đối thủ vừa thấy đội hình của chúng tôi đã không nhịn được cười khẩy."}],"related":[{"hanzi":"嘲笑","pinyin":"cháoxiào","vi":"chế giễu"},{"hanzi":"苦笑","pinyin":"kǔxiào","vi":"cười gượng"},{"hanzi":"讥笑","pinyin":"jīxiào","vi":"cười nhạo"},{"hanzi":"微笑","pinyin":"wēixiào","vi":"mỉm cười"}]},{"id":"离谱儿","hanzi":"离谱儿","pinyin":"lípǔr","meaning_vi":"quá đáng, vô lý, lệch chuẩn","explanation":"离 (ly – rời) + 谱 (phổ – bản nhạc, khuôn mẫu) + 儿 → lệch khỏi khuôn phép, vượt quá mức hợp lý; khẩu ngữ miền Bắc Trung Quốc.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤪","examples":[{"type":"basic","zh":"这价格太离谱儿了！","pinyin":"Zhè jiàgé tài lípǔr le!","vi":"Giá này vô lý quá!"},{"type":"simple","zh":"他说的理由离谱儿得让人想笑。","pinyin":"Tā shuō de lǐyóu lípǔr de ràng rén xiǎng xiào.","vi":"Lý do anh ta đưa ra vô lý đến mức khiến người ta buồn cười."},{"type":"compound","zh":"即使你再生气，也不能做这么离谱儿的事。","pinyin":"Jíshǐ nǐ zài shēngqì, yě bù néng zuò zhème lípǔr de shì.","vi":"Dù có giận đến đâu, bạn cũng không được làm chuyện quá đáng như vậy."}],"related":[{"hanzi":"离谱","pinyin":"lípǔ","vi":"quá đáng"},{"hanzi":"靠谱","pinyin":"kàopǔ","vi":"đáng tin cậy"},{"hanzi":"过分","pinyin":"guòfèn","vi":"quá mức"},{"hanzi":"荒唐","pinyin":"huāngtáng","vi":"hoang đường"}],"traditional":"離譜兒"},{"id":"离职","hanzi":"离职","pinyin":"lízhí","meaning_vi":"nghỉ việc, thôi việc","explanation":"离 (ly – rời) + 职 (chức – chức vụ) → rời khỏi chức vụ, thôi việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚪","examples":[{"type":"basic","zh":"她上个月离职了。","pinyin":"Tā shànggeyuè lízhí le.","vi":"Cô ấy đã nghỉ việc tháng trước."},{"type":"simple","zh":"离职前要把手头的工作交接清楚。","pinyin":"Lízhí qián yào bǎ shǒutóu de gōngzuò jiāojiē qīngchu.","vi":"Trước khi nghỉ việc phải bàn giao rõ ràng công việc đang làm."},{"type":"compound","zh":"因为公司要搬到外地，所以不少员工选择了离职。","pinyin":"Yīnwèi gōngsī yào bān dào wàidì, suǒyǐ bùshǎo yuángōng xuǎnzéle lízhí.","vi":"Vì công ty chuyển đi nơi khác nên không ít nhân viên chọn nghỉ việc."}],"related":[{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"入职","pinyin":"rùzhí","vi":"nhận việc"},{"hanzi":"在职","pinyin":"zàizhí","vi":"đang tại chức"},{"hanzi":"离开","pinyin":"líkāi","vi":"rời đi"}],"traditional":"離職"},{"id":"礼服","hanzi":"礼服","pinyin":"lǐfú","meaning_vi":"lễ phục, trang phục dạ hội","explanation":"礼 (lễ – nghi lễ) + 服 (phục – quần áo) → quần áo mặc trong dịp trang trọng.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👗","examples":[{"type":"basic","zh":"她穿了一件白色礼服。","pinyin":"Tā chuānle yí jiàn báisè lǐfú.","vi":"Cô ấy mặc một bộ lễ phục màu trắng."},{"type":"simple","zh":"参加晚宴的客人都穿着正式的礼服。","pinyin":"Cānjiā wǎnyàn de kèrén dōu chuānzhe zhèngshì de lǐfú.","vi":"Khách dự tiệc tối đều mặc lễ phục trang trọng."},{"type":"compound","zh":"虽然这套礼服很贵，但是婚礼上只穿一次。","pinyin":"Suīrán zhè tào lǐfú hěn guì, dànshì hūnlǐ shang zhǐ chuān yí cì.","vi":"Tuy bộ lễ phục này rất đắt nhưng chỉ mặc một lần trong đám cưới."}],"related":[{"hanzi":"晚礼服","pinyin":"wǎnlǐfú","vi":"váy dạ hội"},{"hanzi":"西服","pinyin":"xīfú","vi":"com lê"},{"hanzi":"婚纱","pinyin":"hūnshā","vi":"váy cưới"},{"hanzi":"礼仪","pinyin":"lǐyí","vi":"lễ nghi"}],"traditional":"禮服"},{"id":"礼品","hanzi":"礼品","pinyin":"lǐpǐn","meaning_vi":"quà tặng, lễ vật","explanation":"礼 (lễ – quà lễ) + 品 (phẩm – đồ vật) → đồ vật dùng làm quà tặng.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🎁","examples":[{"type":"basic","zh":"商场里有礼品包装服务。","pinyin":"Shāngchǎng li yǒu lǐpǐn bāozhuāng fúwù.","vi":"Trung tâm thương mại có dịch vụ gói quà."},{"type":"simple","zh":"公司给每位客户准备了一份新年礼品。","pinyin":"Gōngsī gěi měi wèi kèhù zhǔnbèile yí fèn xīnnián lǐpǐn.","vi":"Công ty chuẩn bị cho mỗi khách hàng một phần quà năm mới."},{"type":"compound","zh":"如果礼品太贵重，对方就会不好意思收下。","pinyin":"Rúguǒ lǐpǐn tài guìzhòng, duìfāng jiù huì bù hǎoyìsi shōuxià.","vi":"Nếu quà quá đắt giá thì đối phương sẽ ngại nhận."}],"related":[{"hanzi":"礼物","pinyin":"lǐwù","vi":"quà"},{"hanzi":"纪念品","pinyin":"jìniànpǐn","vi":"quà lưu niệm"},{"hanzi":"送礼","pinyin":"sònglǐ","vi":"tặng quà"},{"hanzi":"赠品","pinyin":"zèngpǐn","vi":"hàng tặng kèm"}],"traditional":"禮品"},{"id":"礼仪","hanzi":"礼仪","pinyin":"lǐyí","meaning_vi":"lễ nghi, phép lịch sự, nghi thức","explanation":"礼 (lễ – lễ phép) + 仪 (nghi – nghi thức) → các phép tắc, nghi thức trong giao tiếp và nghi lễ.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🙇","examples":[{"type":"basic","zh":"餐桌礼仪很重要。","pinyin":"Cānzhuō lǐyí hěn zhòngyào.","vi":"Phép lịch sự trên bàn ăn rất quan trọng."},{"type":"simple","zh":"新员工入职前要参加商务礼仪培训。","pinyin":"Xīn yuángōng rùzhí qián yào cānjiā shāngwù lǐyí péixùn.","vi":"Nhân viên mới phải tham gia khóa đào tạo lễ nghi kinh doanh trước khi vào làm."},{"type":"compound","zh":"因为各国的礼仪不同，所以出国前最好先了解一下。","pinyin":"Yīnwèi gèguó de lǐyí bùtóng, suǒyǐ chūguó qián zuìhǎo xiān liǎojiě yíxià.","vi":"Vì lễ nghi mỗi nước khác nhau nên trước khi ra nước ngoài tốt nhất nên tìm hiểu trước."}],"related":[{"hanzi":"礼貌","pinyin":"lǐmào","vi":"lễ phép"},{"hanzi":"礼节","pinyin":"lǐjié","vi":"lễ tiết"},{"hanzi":"仪式","pinyin":"yíshì","vi":"nghi thức"},{"hanzi":"礼服","pinyin":"lǐfú","vi":"lễ phục"}],"traditional":"禮儀"},{"id":"理会","hanzi":"理会","pinyin":"lǐhuì","meaning_vi":"để ý, đếm xỉa đến, hiểu","explanation":"理 (lý – để ý, xử lý) + 会 (hội – lĩnh hội) → để ý đến, đáp lại; thường dùng trong câu phủ định \"不理会\".","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙉","examples":[{"type":"basic","zh":"别理会他的话。","pinyin":"Bié lǐhuì tā dehuà.","vi":"Đừng để ý lời anh ta."},{"type":"simple","zh":"我喊了好几声，他都没有理会我。","pinyin":"Wǒ hǎnle hǎojǐ shēng, tā dōu méiyǒu lǐhuì wǒ.","vi":"Tôi gọi mấy tiếng mà anh ấy chẳng thèm để ý."},{"type":"compound","zh":"即使别人在背后议论，她也从不理会。","pinyin":"Jíshǐ biérén zài bèihòu yìlùn, tā yě cóng bù lǐhuì.","vi":"Dù người khác bàn tán sau lưng, cô ấy cũng chưa bao giờ bận tâm."}],"related":[{"hanzi":"理睬","pinyin":"lǐcǎi","vi":"đoái hoài"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"hiểu"},{"hanzi":"领会","pinyin":"lǐnghuì","vi":"lĩnh hội"},{"hanzi":"不理","pinyin":"bùlǐ","vi":"phớt lờ"}],"traditional":"理會"},{"id":"理科","hanzi":"理科","pinyin":"lǐkē","meaning_vi":"khối tự nhiên, các ngành khoa học tự nhiên","explanation":"理 (lý – vật lý, lý học) + 科 (khoa – ngành) → các môn khoa học tự nhiên như toán, lý, hóa, sinh; đối lập với 文科.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"我高中学的是理科。","pinyin":"Wǒ gāo zhōngxué de shì lǐkē.","vi":"Hồi cấp ba tôi học khối tự nhiên."},{"type":"simple","zh":"他的理科成绩一直比文科好得多。","pinyin":"Tā de lǐkē chéngjì yìzhí bǐ wénkē hǎo de duō.","vi":"Điểm các môn tự nhiên của cậu ấy luôn tốt hơn nhiều so với các môn xã hội."},{"type":"compound","zh":"虽然她是理科生，但是写的文章也非常漂亮。","pinyin":"Suīrán tā shì lǐkē shēng, dànshì xiě de wénzhāng yě fēicháng piàoliang.","vi":"Tuy là học sinh khối tự nhiên nhưng cô ấy viết văn cũng rất hay."}],"related":[{"hanzi":"文科","pinyin":"wénkē","vi":"khối xã hội"},{"hanzi":"工科","pinyin":"gōngkē","vi":"khối kỹ thuật"},{"hanzi":"理工","pinyin":"lǐgōng","vi":"khoa học kỹ thuật"},{"hanzi":"学科","pinyin":"xuékē","vi":"môn học"}]},{"id":"理念","hanzi":"理念","pinyin":"lǐniàn","meaning_vi":"triết lý, quan niệm, tư tưởng","explanation":"理 (lý – đạo lý) + 念 (niệm – ý nghĩ) → tư tưởng, quan niệm làm kim chỉ nam cho cách làm.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"我们的经营理念是诚信。","pinyin":"Wǒmen de jīngyíng lǐniàn shì chéngxìn.","vi":"Triết lý kinh doanh của chúng tôi là chữ tín."},{"type":"simple","zh":"这所学校非常重视快乐教育的理念。","pinyin":"Zhè suǒ xuéxiào fēicháng zhòngshì kuàilè jiàoyù de lǐniàn.","vi":"Trường này rất coi trọng triết lý giáo dục vui vẻ."},{"type":"compound","zh":"因为两人的设计理念完全不同，所以合作得并不顺利。","pinyin":"Yīnwèi liǎng rén de shèjì lǐniàn wánquán bùtóng, suǒyǐ hézuò de bìngbú shùnlì.","vi":"Vì quan niệm thiết kế của hai người hoàn toàn khác nhau nên hợp tác không suôn sẻ."}],"related":[{"hanzi":"观念","pinyin":"guānniàn","vi":"quan niệm"},{"hanzi":"理想","pinyin":"lǐxiǎng","vi":"lý tưởng"},{"hanzi":"思想","pinyin":"sīxiǎng","vi":"tư tưởng"},{"hanzi":"宗旨","pinyin":"zōngzhǐ","vi":"tôn chỉ"}]},{"id":"理事","hanzi":"理事","pinyin":"lǐshì","meaning_vi":"ủy viên hội đồng, thành viên ban điều hành","explanation":"理 (lý – quản lý) + 事 (sự – việc) → người lo liệu công việc; chỉ thành viên hội đồng của một tổ chức, hiệp hội.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是协会的理事。","pinyin":"Tā shì xiéhuì de lǐshì.","vi":"Ông ấy là ủy viên của hiệp hội."},{"type":"simple","zh":"新一届理事将在下个月的大会上选出。","pinyin":"Xīn yí jiè lǐshì jiāng zài xiàgeyuè de dàhuì shang xuǎnchū.","vi":"Ban ủy viên khóa mới sẽ được bầu tại đại hội tháng sau."},{"type":"compound","zh":"如果理事们都同意，这个方案就可以正式实施。","pinyin":"Rúguǒ lǐshìmen dōu tóngyì, zhè ge fāng'àn jiù kěyǐ zhèngshì shíshī.","vi":"Nếu các ủy viên đều đồng ý thì phương án này có thể chính thức thực hiện."}],"related":[{"hanzi":"理事会","pinyin":"lǐshìhuì","vi":"hội đồng quản trị"},{"hanzi":"董事","pinyin":"dǒngshì","vi":"thành viên HĐQT"},{"hanzi":"会长","pinyin":"huìzhǎng","vi":"hội trưởng"},{"hanzi":"委员","pinyin":"wěiyuán","vi":"ủy viên"}]},{"id":"力度","hanzi":"力度","pinyin":"lìdù","meaning_vi":"mức độ, cường độ, sức mạnh","explanation":"力 (lực – sức) + 度 (độ – mức) → mức độ mạnh yếu của sức lực hay biện pháp; hay đi với 加大.","hsk_level":"7-9","tags":["danh-tu"],"image":"💪","examples":[{"type":"basic","zh":"政府加大了打击力度。","pinyin":"Zhèngfǔ jiādàle dǎjī lìdù.","vi":"Chính phủ đã tăng cường mức độ trấn áp."},{"type":"simple","zh":"这次促销活动的优惠力度比去年大多了。","pinyin":"Zhè cì cùxiāo huódòng de yōuhuì lìdù bǐ qùnián dàduō le.","vi":"Mức ưu đãi của đợt khuyến mãi này lớn hơn năm ngoái nhiều."},{"type":"compound","zh":"如果改革力度不够，问题就很难从根本上解决。","pinyin":"Rúguǒ gǎigé lìdù búgòu, wèntí jiù hěn nán cóng gēnběn shang jiějué.","vi":"Nếu mức độ cải cách không đủ thì vấn đề khó giải quyết tận gốc."}],"related":[{"hanzi":"力量","pinyin":"lìliang","vi":"sức mạnh"},{"hanzi":"强度","pinyin":"qiángdù","vi":"cường độ"},{"hanzi":"程度","pinyin":"chéngdù","vi":"mức độ"},{"hanzi":"加大","pinyin":"jiādà","vi":"tăng thêm"}]},{"id":"力求","hanzi":"力求","pinyin":"lìqiú","meaning_vi":"cố gắng hết sức, ra sức đạt được","explanation":"力 (lực – dốc sức) + 求 (cầu – tìm, mong) → dốc sức để đạt được điều gì; thường đi với 完美, 准确.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"我们力求做到最好。","pinyin":"Wǒmen lìqiú zuòdào zuìhǎo.","vi":"Chúng tôi cố gắng làm tốt nhất."},{"type":"simple","zh":"这篇报道力求客观地反映事实。","pinyin":"Zhè piān bàodào lìqiú kèguān de fǎnyìng shìshí.","vi":"Bài báo này cố gắng phản ánh sự thật một cách khách quan."},{"type":"compound","zh":"虽然时间很紧，但是我们仍然力求每个细节都不出错。","pinyin":"Suīrán shíjiān hěn jǐn, dànshì wǒmen réngrán lìqiú měi ge xìjié dōu bù chūcuò.","vi":"Tuy thời gian gấp nhưng chúng tôi vẫn cố gắng để mọi chi tiết không sai sót."}],"related":[{"hanzi":"力争","pinyin":"lìzhēng","vi":"ra sức giành"},{"hanzi":"追求","pinyin":"zhuīqiú","vi":"theo đuổi"},{"hanzi":"努力","pinyin":"nǔlì","vi":"nỗ lực"},{"hanzi":"务求","pinyin":"wùqiú","vi":"nhất định phải"}]},{"id":"历届","hanzi":"历届","pinyin":"lìjiè","meaning_vi":"các khóa trước, các kỳ trước","explanation":"历 (lịch – trải qua) + 届 (giới – khóa, kỳ) → tất cả các khóa, các kỳ đã qua.","hsk_level":"7-9","tags":["tinh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"历届冠军都来了。","pinyin":"Lìjiè guànjūn dōu lái le.","vi":"Các nhà vô địch các kỳ trước đều đã đến."},{"type":"simple","zh":"这次的参赛人数是历届比赛中最多的。","pinyin":"Zhè cì de cānsài rénshù shì lìjiè bǐsài zhōng zuì duō de.","vi":"Số người dự thi lần này đông nhất trong các kỳ thi từ trước đến nay."},{"type":"compound","zh":"虽然历届毕业生都很优秀，但是今年的成绩尤其突出。","pinyin":"Suīrán lìjiè bìyèshēng dōu hěn yōuxiù, dànshì jīnnián de chéngjì yóuqí tūchū.","vi":"Tuy sinh viên tốt nghiệp các khóa đều xuất sắc nhưng thành tích năm nay đặc biệt nổi bật."}],"related":[{"hanzi":"届","pinyin":"jiè","vi":"khóa, kỳ"},{"hanzi":"本届","pinyin":"běnjiè","vi":"khóa này"},{"hanzi":"历年","pinyin":"lìnián","vi":"các năm qua"},{"hanzi":"历次","pinyin":"lìcì","vi":"các lần trước"}],"traditional":"歷屆"},{"id":"历经","hanzi":"历经","pinyin":"lìjīng","meaning_vi":"trải qua","explanation":"历 (lịch – trải) + 经 (kinh – qua) → trải qua (nhiều gian nan, thời gian dài); dùng trong văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏔️","examples":[{"type":"basic","zh":"他历经了许多磨难。","pinyin":"Tā lìjīngle xǔduō mónàn.","vi":"Anh ấy đã trải qua nhiều gian truân."},{"type":"simple","zh":"这座古桥历经八百年风雨仍然完好。","pinyin":"Zhè zuò gǔ qiáo lìjīng bā bǎinián fēngyǔ réngrán wánhǎo.","vi":"Cây cầu cổ này trải qua tám trăm năm mưa gió vẫn nguyên vẹn."},{"type":"compound","zh":"虽然历经三次失败，但是他们最终还是研制成功了。","pinyin":"Suīrán lìjīng sāncì shībài, dànshì tāmen zuìzhōng háishi yánzhì chénggōng le.","vi":"Tuy trải qua ba lần thất bại nhưng cuối cùng họ vẫn chế tạo thành công."}],"related":[{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"},{"hanzi":"经过","pinyin":"jīngguò","vi":"trải qua"},{"hanzi":"历时","pinyin":"lìshí","vi":"kéo dài"},{"hanzi":"饱经","pinyin":"bǎojīng","vi":"nếm trải đủ"}],"traditional":"歷經"},{"id":"历时","hanzi":"历时","pinyin":"lìshí","meaning_vi":"kéo dài, mất (bao lâu)","explanation":"历 (lịch – trải qua) + 时 (thời – thời gian) → trải qua một khoảng thời gian; dùng để nói độ dài của sự việc.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"会议历时三天。","pinyin":"Huìyì lìshí sān tiān.","vi":"Hội nghị kéo dài ba ngày."},{"type":"simple","zh":"这项工程历时五年才全部完工。","pinyin":"Zhè xiàng gōngchéng lìshí wǔ nián cái quánbù wángōng.","vi":"Công trình này kéo dài năm năm mới hoàn thành toàn bộ."},{"type":"compound","zh":"因为谈判历时太久，所以双方都有些疲惫了。","pinyin":"Yīnwèi tánpàn lìshí tài jiǔ, suǒyǐ shuāngfāng dōu yǒuxiē píbèi le.","vi":"Vì đàm phán kéo dài quá lâu nên cả hai bên đều có phần mệt mỏi."}],"related":[{"hanzi":"历经","pinyin":"lìjīng","vi":"trải qua"},{"hanzi":"持续","pinyin":"chíxù","vi":"kéo dài"},{"hanzi":"耗时","pinyin":"hàoshí","vi":"tốn thời gian"},{"hanzi":"为期","pinyin":"wéiqī","vi":"trong thời hạn"}],"traditional":"歷時"},{"id":"立方","hanzi":"立方","pinyin":"lìfāng","meaning_vi":"lập phương, khối (mét khối)","explanation":"立 (lập – dựng đứng) + 方 (phương – vuông) → khối vuông; trong toán là lũy thừa bậc ba, khẩu ngữ chỉ mét khối.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📦","examples":[{"type":"basic","zh":"二的立方是八。","pinyin":"Èr de lìfāng shì bā.","vi":"Lập phương của hai là tám."},{"type":"simple","zh":"这辆卡车一次能运二十立方的沙子。","pinyin":"Zhè liàng kǎchē yí cì néng yùn èrshí lìfāng de shāzi.","vi":"Chiếc xe tải này mỗi lần chở được hai mươi khối cát."},{"type":"compound","zh":"如果你知道边长，就能求出它的立方。","pinyin":"Rúguǒ nǐ zhīdào biāncháng, jiù néng qiú chū tā de lìfāng.","vi":"Nếu bạn biết độ dài cạnh thì có thể tính ra lập phương của nó."}],"related":[{"hanzi":"立方米","pinyin":"lìfāngmǐ","vi":"mét khối"},{"hanzi":"平方","pinyin":"píngfāng","vi":"bình phương"},{"hanzi":"立方体","pinyin":"lìfāngtǐ","vi":"hình lập phương"},{"hanzi":"体积","pinyin":"tǐjī","vi":"thể tích"}]},{"id":"立方米","hanzi":"立方米","pinyin":"lìfāngmǐ","meaning_vi":"mét khối","explanation":"立方 (lập phương) + 米 (mễ – mét) → đơn vị thể tích bằng khối lập phương có cạnh 1 mét.","hsk_level":"7-9","tags":["luong-tu","so-luong"],"image":"🧱","examples":[{"type":"basic","zh":"水池有十立方米。","pinyin":"Shuǐchí yǒu shí lìfāngmǐ.","vi":"Bể nước có mười mét khối."},{"type":"simple","zh":"我家上个月一共用了十五立方米的水。","pinyin":"Wǒ jiā shànggeyuè yí gòngyòngle shíwǔ lìfāngmǐ de shuǐ.","vi":"Tháng trước nhà tôi dùng tổng cộng mười lăm mét khối nước."},{"type":"compound","zh":"如果每立方米木材涨价十元，那么成本就会增加不少。","pinyin":"Rúguǒ měi lìfāngmǐ mùcái zhǎngjià shí yuán, nàme chéngběn jiù huì zēngjiā bùshǎo.","vi":"Nếu mỗi mét khối gỗ tăng giá mười tệ thì chi phí sẽ tăng không ít."}],"related":[{"hanzi":"立方","pinyin":"lìfāng","vi":"khối"},{"hanzi":"平方米","pinyin":"píngfāngmǐ","vi":"mét vuông"},{"hanzi":"公升","pinyin":"gōngshēng","vi":"lít"},{"hanzi":"体积","pinyin":"tǐjī","vi":"thể tích"}]},{"id":"立功","hanzi":"立功","pinyin":"lìgōng","meaning_vi":"lập công","explanation":"立 (lập – dựng nên) + 功 (công – công lao) → lập nên công lao, có đóng góp xuất sắc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎖️","examples":[{"type":"basic","zh":"这次他又立功了。","pinyin":"Zhè cì tā yòu lìgōng le.","vi":"Lần này anh ấy lại lập công."},{"type":"simple","zh":"消防员因救出十几名群众而立功受奖。","pinyin":"Xiāofángyuán yīn jiùchū shíjǐ míng qúnzhòng ér lìgōng shòu jiǎng.","vi":"Người lính cứu hỏa lập công được khen thưởng vì cứu hơn chục người dân."},{"type":"compound","zh":"只要你这次能立功，就有机会得到提拔。","pinyin":"Zhǐyào nǐ zhè cì néng lìgōng, jiù yǒujī huì dédào tíbá.","vi":"Chỉ cần lần này bạn lập công thì sẽ có cơ hội được đề bạt."}],"related":[{"hanzi":"功劳","pinyin":"gōngláo","vi":"công lao"},{"hanzi":"立功赎罪","pinyin":"lìgōngshúzuì","vi":"lập công chuộc tội"},{"hanzi":"功臣","pinyin":"gōngchén","vi":"công thần"},{"hanzi":"建功","pinyin":"jiàngōng","vi":"lập công"}]},{"id":"立交桥","hanzi":"立交桥","pinyin":"lìjiāoqiáo","meaning_vi":"cầu vượt, nút giao nhiều tầng","explanation":"立 (lập – lập thể) + 交 (giao – giao nhau) + 桥 (kiều – cầu) → cầu tại nút giao thông nhiều tầng.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"前面有座立交桥。","pinyin":"Qiánmiàn yǒu zuò lìjiāoqiáo.","vi":"Phía trước có một cây cầu vượt."},{"type":"simple","zh":"北京的立交桥又多又复杂，很容易走错。","pinyin":"Běijīng de lìjiāoqiáo yòu duō yòu fùzá, hěn róngyì zǒucuò.","vi":"Cầu vượt ở Bắc Kinh vừa nhiều vừa phức tạp, rất dễ đi nhầm."},{"type":"compound","zh":"自从这座立交桥建成以后，路口就再也不堵车了。","pinyin":"Zìcóng zhè zuò lìjiāoqiáo jiànchéng yǐhòu, lùkǒu jiù zài yě bù dǔchē le.","vi":"Từ khi cầu vượt này xây xong, ngã tư không còn tắc đường nữa."}],"related":[{"hanzi":"天桥","pinyin":"tiānqiáo","vi":"cầu vượt bộ hành"},{"hanzi":"高架桥","pinyin":"gāojiàqiáo","vi":"cầu cạn"},{"hanzi":"路口","pinyin":"lùkǒu","vi":"ngã tư"},{"hanzi":"桥梁","pinyin":"qiáoliáng","vi":"cầu"}],"traditional":"立交橋"},{"id":"利害","hanzi":"利害","pinyin":"lìhài","meaning_vi":"lợi hại, được mất","explanation":"利 (lợi – lợi ích) + 害 (hại – tác hại) → cái lợi và cái hại; khi đọc lì hai thì nghĩa là \"ghê gớm\".","hsk_level":"7-9","tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"你要想清楚其中的利害。","pinyin":"Nǐ yào xiǎng qīngchu qízhōng de lìhài.","vi":"Bạn phải nghĩ rõ lợi hại trong đó."},{"type":"simple","zh":"两家公司之间存在直接的利害关系。","pinyin":"Liǎng jiā gōngsī zhījiān cúnzài zhíjiē de lìhài guānxi.","vi":"Giữa hai công ty có quan hệ lợi hại trực tiếp."},{"type":"compound","zh":"只有把利害都分析清楚，我们才能做出正确的决定。","pinyin":"Zhǐyǒu bǎ lìhài dōu fēnxī qīngchu, wǒmen cáinéng zuòchū zhèngquè de juédìng.","vi":"Chỉ khi phân tích rõ lợi hại, chúng ta mới đưa ra được quyết định đúng đắn."}],"related":[{"hanzi":"利弊","pinyin":"lìbì","vi":"lợi và hại"},{"hanzi":"得失","pinyin":"déshī","vi":"được mất"},{"hanzi":"利益","pinyin":"lìyì","vi":"lợi ích"},{"hanzi":"厉害","pinyin":"lìhai","vi":"lợi hại, ghê gớm"}]},{"id":"励志","hanzi":"励志","pinyin":"lìzhì","meaning_vi":"truyền cảm hứng, khích lệ ý chí","explanation":"励 (lệ – khích lệ) + 志 (chí – ý chí) → khích lệ ý chí phấn đấu; thường dùng như tính từ, ví dụ \"励志故事\".","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🌟","examples":[{"type":"basic","zh":"这是一部励志电影。","pinyin":"Zhè shì yí bù lìzhì diànyǐng.","vi":"Đây là một bộ phim truyền cảm hứng."},{"type":"simple","zh":"他从农村孩子成长为科学家的经历非常励志。","pinyin":"Tā cóng nóngcūn háizi chéngzhǎng wéi kēxuéjiā de jīnglì fēicháng lìzhì.","vi":"Hành trình từ đứa trẻ nông thôn trở thành nhà khoa học của anh ấy rất truyền cảm hứng."},{"type":"compound","zh":"每当我想放弃的时候，就会读一读这本励志书。","pinyin":"Měidāng wǒ xiǎng fàngqì de shíhou, jiù huì dú yi dú zhè běn lìzhì shū.","vi":"Mỗi khi muốn bỏ cuộc, tôi lại đọc cuốn sách truyền động lực này."}],"related":[{"hanzi":"鼓励","pinyin":"gǔlì","vi":"khích lệ"},{"hanzi":"激励","pinyin":"jīlì","vi":"thúc đẩy"},{"hanzi":"志向","pinyin":"zhìxiàng","vi":"chí hướng"},{"hanzi":"励志故事","pinyin":"lìzhìgùshi","vi":"câu chuyện truyền cảm hứng"}],"traditional":"勵志"},{"id":"连滚带爬","hanzi":"连滚带爬","pinyin":"liángǔn-dàipá","meaning_vi":"vừa lăn vừa bò, cuống cuồng tháo chạy","explanation":"连 (liên – vừa) + 滚 (cổn – lăn) + 带 (đới – kèm) + 爬 (ba – bò) → vừa lăn vừa bò; chỉ dáng chạy hốt hoảng, thảm hại.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"小偷连滚带爬地逃跑了。","pinyin":"Xiǎotōu liángǔndàipá de táopǎo le.","vi":"Tên trộm vừa lăn vừa bò tháo chạy."},{"type":"simple","zh":"听到狗叫，他吓得连滚带爬地冲下了山坡。","pinyin":"Tīngdào gǒu jiào, tā xià de liángǔndàipá de chōng xiàle shānpō.","vi":"Nghe chó sủa, anh ta sợ đến mức lăn lộn lao xuống sườn đồi."},{"type":"compound","zh":"一听说老虎跑出来了，游客们就连滚带爬地往外跑。","pinyin":"Yì tīngshuō lǎohǔ pǎo chūlái le, yóukèmen jiù liángǔndàipá de wǎng wài pǎo.","vi":"Vừa nghe tin hổ sổng chuồng, du khách đã cuống cuồng chạy ra ngoài."}],"related":[{"hanzi":"狼狈","pinyin":"lángbèi","vi":"thảm hại"},{"hanzi":"抱头鼠窜","pinyin":"bàotóushǔcuàn","vi":"ôm đầu chạy trốn"},{"hanzi":"滚","pinyin":"gǔn","vi":"lăn"},{"hanzi":"爬","pinyin":"pá","vi":"bò"}],"traditional":"連滾帶爬"},{"id":"连绵","hanzi":"连绵","pinyin":"liánmián","meaning_vi":"liên miên, trùng điệp, kéo dài không dứt","explanation":"连 (liên – nối) + 绵 (miên – kéo dài như sợi tơ) → nối tiếp kéo dài không dứt; dùng cho núi non, mưa.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"窗外阴雨连绵。","pinyin":"Chuāng wài yīnyǔ liánmián.","vi":"Ngoài cửa sổ mưa dầm liên miên."},{"type":"simple","zh":"远处是一片连绵起伏的青山。","pinyin":"Yuǎnchù shì yípiàn liánmián qǐfú de qīngshān.","vi":"Phía xa là dãy núi xanh trùng điệp nhấp nhô."},{"type":"compound","zh":"因为这几天大雨连绵，所以河水涨得很快。","pinyin":"Yīnwèi zhèjǐtiān dàyǔ liánmián, suǒyǐ héshuǐ zhǎng de hěn kuài.","vi":"Vì mấy ngày nay mưa lớn liên miên nên nước sông dâng rất nhanh."}],"related":[{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"绵延","pinyin":"miányán","vi":"kéo dài"},{"hanzi":"不断","pinyin":"búduàn","vi":"không ngừng"},{"hanzi":"起伏","pinyin":"qǐfú","vi":"nhấp nhô"}],"traditional":"連綿"},{"id":"连锁店","hanzi":"连锁店","pinyin":"liánsuǒdiàn","meaning_vi":"cửa hàng chuỗi","explanation":"连锁 (liên tỏa – nối thành chuỗi) + 店 (điếm – cửa hàng) → cửa hàng thuộc một hệ thống chuỗi cùng thương hiệu.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏪","examples":[{"type":"basic","zh":"这是一家咖啡连锁店。","pinyin":"Zhè shì yìjiā kāfēi liánsuǒdiàn.","vi":"Đây là một cửa hàng thuộc chuỗi cà phê."},{"type":"simple","zh":"这个品牌在全国开了三百多家连锁店。","pinyin":"Zhè ge pǐnpái zài quánguó kāile sān bǎi duō jiā liánsuǒdiàn.","vi":"Thương hiệu này đã mở hơn ba trăm cửa hàng chuỗi trên cả nước."},{"type":"compound","zh":"虽然连锁店的价格不便宜，但是质量比较有保障。","pinyin":"Suīrán liánsuǒdiàn de jiàgé bù piányi, dànshì zhìliàng bǐjiào yǒu bǎozhàng.","vi":"Tuy giá ở cửa hàng chuỗi không rẻ nhưng chất lượng khá được đảm bảo."}],"related":[{"hanzi":"连锁","pinyin":"liánsuǒ","vi":"chuỗi"},{"hanzi":"分店","pinyin":"fēndiàn","vi":"chi nhánh"},{"hanzi":"加盟店","pinyin":"jiāméngdiàn","vi":"cửa hàng nhượng quyền"},{"hanzi":"超市","pinyin":"chāoshì","vi":"siêu thị"}],"traditional":"連鎖店"},{"id":"帘子","hanzi":"帘子","pinyin":"liánzi","meaning_vi":"rèm, mành","explanation":"帘 (liêm – rèm) + 子 (hậu tố danh từ) → tấm rèm, mành treo để che cửa.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🪟","examples":[{"type":"basic","zh":"请把帘子拉上。","pinyin":"Qǐng bǎ liánzi lā shang.","vi":"Làm ơn kéo rèm lại."},{"type":"simple","zh":"门口挂着一块蓝色的布帘子。","pinyin":"Ménkǒu guàzhe yíkuài lánsè de bù liánzi.","vi":"Ở cửa treo một tấm rèm vải màu xanh."},{"type":"compound","zh":"因为阳光太刺眼，所以奶奶把竹帘子放了下来。","pinyin":"Yīnwèi yángguāng tài cìyǎn, suǒyǐ nǎinai bǎ zhú liánzi fàngle xiàlái.","vi":"Vì nắng chói quá nên bà hạ tấm mành tre xuống."}],"related":[{"hanzi":"窗帘","pinyin":"chuānglián","vi":"rèm cửa sổ"},{"hanzi":"门帘","pinyin":"ménlián","vi":"rèm cửa ra vào"},{"hanzi":"竹帘","pinyin":"zhúlián","vi":"mành tre"},{"hanzi":"遮挡","pinyin":"zhēdǎng","vi":"che chắn"}],"traditional":"簾子"},{"id":"怜惜","hanzi":"怜惜","pinyin":"liánxī","meaning_vi":"thương xót, thương tiếc, xót thương","explanation":"怜 (liên – thương) + 惜 (tích – tiếc, quý) → thương xót và trân trọng người hoặc vật yếu ớt.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"大家都很怜惜她。","pinyin":"Dàjiā dōu hěn liánxī tā.","vi":"Mọi người đều rất thương xót cô ấy."},{"type":"simple","zh":"看着那只受伤的小猫，他心里充满了怜惜。","pinyin":"Kànzhe nà zhī shòushāng de xiǎomāo, tā xīnli chōngmǎnle liánxī.","vi":"Nhìn chú mèo con bị thương, lòng anh ấy tràn đầy xót thương."},{"type":"compound","zh":"虽然她很怜惜这个孩子，但是也不能一直帮他。","pinyin":"Suīrán tā hěn liánxī zhè ge háizi, dànshì yě bù néng yìzhí bāng tā.","vi":"Tuy rất thương đứa trẻ này nhưng cô ấy cũng không thể giúp nó mãi."}],"related":[{"hanzi":"可怜","pinyin":"kělián","vi":"đáng thương"},{"hanzi":"怜悯","pinyin":"liánmǐn","vi":"thương hại"},{"hanzi":"爱惜","pinyin":"àixī","vi":"quý trọng"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"đồng cảm"}],"traditional":"憐惜"},{"id":"莲子","hanzi":"莲子","pinyin":"liánzǐ","meaning_vi":"hạt sen","explanation":"莲 (liên – sen) + 子 (tử – hạt) → hạt của cây sen, dùng nấu chè, làm thuốc.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🪷","examples":[{"type":"basic","zh":"莲子可以煮汤。","pinyin":"Liánzǐ kěyǐ zhǔ tāng.","vi":"Hạt sen có thể nấu canh."},{"type":"simple","zh":"妈妈煮了一锅红枣莲子粥给我们当早饭。","pinyin":"Māma zhǔle yì guō hóngzǎo liánzǐ zhōu gěi wǒmen dāng zǎofàn.","vi":"Mẹ nấu một nồi cháo táo đỏ hạt sen cho chúng tôi ăn sáng."},{"type":"compound","zh":"如果莲子没有去芯，吃起来就会有点儿苦。","pinyin":"Rúguǒ liánzǐ méiyǒu qù xīn, chī qǐlái jiù huì yǒudiǎnr kǔ.","vi":"Nếu hạt sen chưa bỏ tâm thì ăn sẽ hơi đắng."}],"related":[{"hanzi":"莲花","pinyin":"liánhuā","vi":"hoa sen"},{"hanzi":"莲藕","pinyin":"lián'ǒu","vi":"củ sen"},{"hanzi":"莲心","pinyin":"liánxīn","vi":"tâm sen"},{"hanzi":"荷花","pinyin":"héhuā","vi":"hoa sen"}],"traditional":"蓮子"},{"id":"联邦","hanzi":"联邦","pinyin":"liánbāng","meaning_vi":"liên bang","explanation":"联 (liên – liên kết) + 邦 (bang – nước) → nhà nước gồm nhiều bang hợp lại.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"德国是联邦国家。","pinyin":"Dé guóshì liánbāng guójiā.","vi":"Đức là một nhà nước liên bang."},{"type":"simple","zh":"这项法律需要由联邦政府统一执行。","pinyin":"Zhè xiàng fǎlǜ xūyào yóu liánbāng zhèngfǔ tǒngyī zhíxíng.","vi":"Luật này cần được chính phủ liên bang thống nhất thi hành."},{"type":"compound","zh":"虽然各州有自己的法律，但是也必须遵守联邦宪法。","pinyin":"Suīrán gè zhōu yǒu zìjǐ de fǎlǜ, dànshì yě bìxū zūnshǒu liánbāng xiànfǎ.","vi":"Tuy các bang có luật riêng nhưng vẫn phải tuân thủ hiến pháp liên bang."}],"related":[{"hanzi":"联盟","pinyin":"liánméng","vi":"liên minh"},{"hanzi":"州","pinyin":"zhōu","vi":"bang"},{"hanzi":"联合","pinyin":"liánhé","vi":"liên hợp"},{"hanzi":"邦交","pinyin":"bāngjiāo","vi":"bang giao"}],"traditional":"聯邦"},{"id":"廉正","hanzi":"廉正","pinyin":"liánzhèng","meaning_vi":"liêm chính, trong sạch ngay thẳng","explanation":"廉 (liêm – trong sạch) + 正 (chính – ngay thẳng) → trong sạch, ngay thẳng, không tham nhũng.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"他为官廉正。","pinyin":"Tā wéi guān liánzhèng.","vi":"Ông ấy làm quan liêm chính."},{"type":"simple","zh":"一个廉正的法官不会接受任何人的礼物。","pinyin":"Yí ge liánzhèng de fǎguān bú huì jiēshòu rènhé rén de lǐwù.","vi":"Một thẩm phán liêm chính sẽ không nhận quà của bất kỳ ai."},{"type":"compound","zh":"正因为他一生廉正，所以去世后百姓都很怀念他。","pinyin":"Zhèng yīnwèi tā yìshēng liánzhèng, suǒyǐ qùshì hòu bǎixìng dōu hěn huáiniàn tā.","vi":"Chính vì cả đời liêm chính nên sau khi ông mất, dân chúng đều rất nhớ ông."}],"related":[{"hanzi":"廉洁","pinyin":"liánjié","vi":"liêm khiết"},{"hanzi":"正直","pinyin":"zhèngzhí","vi":"chính trực"},{"hanzi":"清廉","pinyin":"qīnglián","vi":"thanh liêm"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"tham nhũng"}]},{"id":"脸颊","hanzi":"脸颊","pinyin":"liǎnjiá","meaning_vi":"má, gò má","explanation":"脸 (kiểm – mặt) + 颊 (giáp – má) → hai bên má trên khuôn mặt.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"☺️","examples":[{"type":"basic","zh":"她的脸颊红红的。","pinyin":"Tā de liǎnjiá hóng hóng de.","vi":"Má cô ấy đỏ hồng."},{"type":"simple","zh":"一滴眼泪顺着他的脸颊慢慢流了下来。","pinyin":"Yì dī yǎnlèi shùnzhe tā de liǎnjiá mànmàn liúle xiàlái.","vi":"Một giọt nước mắt từ từ lăn xuống má anh ấy."},{"type":"compound","zh":"因为外面风太大，所以孩子的脸颊被吹得通红。","pinyin":"Yīnwèi wàimiàn fēng tài dà, suǒyǐ háizi de liǎnjiá bèi chuī de tōnghóng.","vi":"Vì ngoài trời gió to nên má đứa bé bị thổi đỏ ửng."}],"related":[{"hanzi":"脸蛋","pinyin":"liǎndàn","vi":"má, khuôn mặt"},{"hanzi":"面颊","pinyin":"miànjiá","vi":"gò má"},{"hanzi":"酒窝","pinyin":"jiǔwō","vi":"lúm đồng tiền"},{"hanzi":"脸","pinyin":"liǎn","vi":"mặt"}],"traditional":"臉頰"},{"id":"炼","hanzi":"炼","pinyin":"liàn","meaning_vi":"luyện, tinh luyện, nung chảy","explanation":"炼 (luyện) → dùng lửa nung nấu để làm tinh khiết kim loại, dầu…; nghĩa bóng là rèn luyện.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔥","examples":[{"type":"basic","zh":"他们在这里炼钢。","pinyin":"Tāmen zài zhèlǐ liàngāng.","vi":"Họ luyện thép ở đây."},{"type":"simple","zh":"古人用这种炉子炼铁、打造农具。","pinyin":"Gǔrén yòng zhè zhǒng lúzi liàntiě, dǎzào nóngjù.","vi":"Người xưa dùng loại lò này để luyện sắt, rèn nông cụ."},{"type":"compound","zh":"只有经过高温反复炼制，钢材才会这么坚硬。","pinyin":"Zhǐyǒu jīngguò gāowēn fǎnfù liànzhì, gāngcái cái huì zhème jiānyìng.","vi":"Chỉ khi được luyện đi luyện lại ở nhiệt độ cao, thép mới cứng như vậy."}],"related":[{"hanzi":"锻炼","pinyin":"duànliàn","vi":"rèn luyện"},{"hanzi":"炼钢","pinyin":"liàngāng","vi":"luyện thép"},{"hanzi":"提炼","pinyin":"tíliàn","vi":"tinh chế"},{"hanzi":"修炼","pinyin":"xiūliàn","vi":"tu luyện"}],"traditional":"煉"},{"id":"良","hanzi":"良","pinyin":"liáng","meaning_vi":"tốt, lương thiện; loại khá","explanation":"良 (lương – tốt, hiền lành) → tốt đẹp; thường dùng trong từ ghép văn viết như 良好, 善良, 良心.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"他用心良苦。","pinyin":"Tā yòngxīnliángkǔ.","vi":"Anh ấy đã rất dụng tâm."},{"type":"simple","zh":"这家医院的医疗设备优良，服务也很好。","pinyin":"Zhè jiā yīyuàn de yīliáo shèbèi yōuliáng, fúwù yě hěn hǎo.","vi":"Bệnh viện này có thiết bị y tế tốt, dịch vụ cũng rất tốt."},{"type":"compound","zh":"虽然他的成绩只是良，但是进步已经很明显了。","pinyin":"Suīrán tā de chéngjì zhǐshì liáng, dànshì jìnbù yǐjīng hěn míngxiǎn le.","vi":"Tuy điểm của cậu ấy chỉ đạt loại khá nhưng tiến bộ đã rất rõ rệt."}],"related":[{"hanzi":"良好","pinyin":"liánghǎo","vi":"tốt đẹp"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"良心","pinyin":"liángxīn","vi":"lương tâm"},{"hanzi":"优良","pinyin":"yōuliáng","vi":"ưu tú"}]},{"id":"两口子","hanzi":"两口子","pinyin":"liǎngkǒuzi","meaning_vi":"hai vợ chồng","explanation":"两 (lưỡng – hai) + 口 (khẩu – miệng, người) + 子 → hai người trong một nhà, tức hai vợ chồng; khẩu ngữ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"💑","examples":[{"type":"basic","zh":"他们两口子很恩爱。","pinyin":"Tāmen liǎngkǒuzi hěn ēn'ài.","vi":"Hai vợ chồng họ rất yêu thương nhau."},{"type":"simple","zh":"隔壁两口子每天晚饭后都一起去散步。","pinyin":"Gébì liǎngkǒuzi měitiān wǎnfàn hòu dōu yìqǐ qù sànbù.","vi":"Hai vợ chồng nhà bên mỗi tối sau bữa cơm đều cùng đi dạo."},{"type":"compound","zh":"虽然两口子偶尔吵架，但是很快就和好了。","pinyin":"Suīrán liǎngkǒuzi ǒu'ěr chǎojià, dànshì hěn kuài jiù héhǎo le.","vi":"Tuy hai vợ chồng thỉnh thoảng cãi nhau nhưng làm lành rất nhanh."}],"related":[{"hanzi":"夫妻","pinyin":"fūqī","vi":"vợ chồng"},{"hanzi":"小两口","pinyin":"xiǎoliǎngkǒu","vi":"vợ chồng trẻ"},{"hanzi":"老两口","pinyin":"lǎoliǎngkǒu","vi":"vợ chồng già"},{"hanzi":"夫妇","pinyin":"fūfù","vi":"phu phụ"}],"traditional":"兩口子"},{"id":"两栖","hanzi":"两栖","pinyin":"liǎngqī","meaning_vi":"lưỡng cư; hoạt động hai lĩnh vực","explanation":"两 (lưỡng – hai) + 栖 (thê – sống, đậu) → sống được cả trên cạn và dưới nước; nghĩa bóng chỉ người làm được hai ngành.","hsk_level":"7-9","tags":["tinh-tu","dong-vat"],"image":"🐸","examples":[{"type":"basic","zh":"青蛙是两栖动物。","pinyin":"Qīngwā shì liǎngqī dòngwù.","vi":"Ếch là động vật lưỡng cư."},{"type":"simple","zh":"他是演艺圈里少见的两栖明星。","pinyin":"Tā shì yǎnyìquān li shǎojiàn de liǎngqī míngxīng.","vi":"Anh ấy là ngôi sao hiếm hoi hoạt động ở cả hai lĩnh vực trong giới giải trí."},{"type":"compound","zh":"因为这种车是两栖的，所以既能在路上跑，也能在水里开。","pinyin":"Yīnwèi zhè zhǒng chē shì liǎngqī de, suǒyǐ jì néng zài lùshang pǎo, yě néng zài shuǐ li kāi.","vi":"Vì loại xe này là xe lưỡng cư nên vừa chạy được trên đường vừa đi được dưới nước."}],"related":[{"hanzi":"两栖动物","pinyin":"liǎngqīdòngwù","vi":"động vật lưỡng cư"},{"hanzi":"栖息","pinyin":"qīxī","vi":"cư trú"},{"hanzi":"青蛙","pinyin":"qīngwā","vi":"con ếch"},{"hanzi":"水陆","pinyin":"shuǐlù","vi":"thủy bộ"}],"traditional":"兩棲"},{"id":"亮点","hanzi":"亮点","pinyin":"liàngdiǎn","meaning_vi":"điểm nhấn, điểm sáng, điểm nổi bật","explanation":"亮 (lượng – sáng) + 点 (điểm) → điểm sáng nổi bật, phần đáng chú ý nhất.","hsk_level":"7-9","tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"这是本次展览的亮点。","pinyin":"Zhè shì běn cì zhǎnlǎn de liàngdiǎn.","vi":"Đây là điểm nhấn của triển lãm lần này."},{"type":"simple","zh":"这部手机最大的亮点是拍照效果特别好。","pinyin":"Zhè bù shǒujī zuì dà de liàngdiǎn shì pāizhào xiàoguǒ tèbié hǎo.","vi":"Điểm nổi bật nhất của chiếc điện thoại này là chụp ảnh đặc biệt đẹp."},{"type":"compound","zh":"虽然整场比赛很沉闷，但是最后的进球成了唯一的亮点。","pinyin":"Suīrán zhěng chǎng bǐsài hěn chénmèn, dànshì zuìhòu de jìnqiú chéngle wéiyī de liàngdiǎn.","vi":"Tuy cả trận đấu khá tẻ nhạt nhưng bàn thắng cuối cùng trở thành điểm sáng duy nhất."}],"related":[{"hanzi":"特色","pinyin":"tèsè","vi":"đặc sắc"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"},{"hanzi":"闪光点","pinyin":"shǎnguāngdiǎn","vi":"điểm sáng"}],"traditional":"亮點"},{"id":"亮丽","hanzi":"亮丽","pinyin":"liànglì","meaning_vi":"tươi sáng, rực rỡ, đẹp đẽ","explanation":"亮 (lượng – sáng) + 丽 (lệ – đẹp) → sáng sủa và đẹp đẽ.","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🌈","examples":[{"type":"basic","zh":"她今天穿得很亮丽。","pinyin":"Tā jīntiān chuān de hěn liànglì.","vi":"Hôm nay cô ấy ăn mặc rất rực rỡ."},{"type":"simple","zh":"雨后的城市显得格外清新亮丽。","pinyin":"Yǔ hòu de chéngshì xiǎnde géwài qīngxīn liànglì.","vi":"Thành phố sau mưa trông đặc biệt tươi mới, rực rỡ."},{"type":"compound","zh":"如果把墙刷成黄色，房间就会显得更亮丽。","pinyin":"Rúguǒ bǎ qiáng shuā chéng huángsè, fángjiān jiù huì xiǎnde gèng liànglì.","vi":"Nếu sơn tường màu vàng thì căn phòng sẽ trông tươi sáng hơn."}],"related":[{"hanzi":"美丽","pinyin":"měilì","vi":"đẹp"},{"hanzi":"靓丽","pinyin":"liànglì","vi":"xinh tươi"},{"hanzi":"鲜艳","pinyin":"xiānyàn","vi":"tươi thắm"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"}],"traditional":"亮麗"},{"id":"亮相","hanzi":"亮相","pinyin":"liàngxiàng","meaning_vi":"ra mắt, xuất hiện trước công chúng, tạo dáng (kịch)","explanation":"亮 (lượng – phô ra) + 相 (tướng – dáng vẻ) → vốn là động tác tạo dáng trên sân khấu kinh kịch; nay chỉ ra mắt, xuất hiện công khai.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"新车今天正式亮相。","pinyin":"Xīnchē jīntiān zhèngshì liàngxiàng.","vi":"Mẫu xe mới hôm nay chính thức ra mắt."},{"type":"simple","zh":"这位歌手第一次在电视节目中亮相。","pinyin":"Zhè wèi gēshǒu dìyīcì zài diànshì jiémù zhōng liàngxiàng.","vi":"Ca sĩ này lần đầu xuất hiện trên chương trình truyền hình."},{"type":"compound","zh":"虽然她只亮相了几分钟，但是给观众留下了深刻印象。","pinyin":"Suīrán tā zhǐ liàngxiàngle jǐ fēnzhōng, dànshì gěi guānzhòng liúxiàle shēnkè yìnxiàng.","vi":"Tuy cô ấy chỉ xuất hiện vài phút nhưng đã để lại ấn tượng sâu sắc cho khán giả."}],"related":[{"hanzi":"登场","pinyin":"dēngchǎng","vi":"lên sân khấu"},{"hanzi":"露面","pinyin":"lòumiàn","vi":"lộ diện"},{"hanzi":"首发","pinyin":"shǒufā","vi":"ra mắt lần đầu"},{"hanzi":"出场","pinyin":"chūchǎng","vi":"ra sân"}]},{"id":"疗法","hanzi":"疗法","pinyin":"liáofǎ","meaning_vi":"liệu pháp, phương pháp điều trị","explanation":"疗 (liệu – chữa bệnh) + 法 (pháp – phương pháp) → cách thức chữa bệnh.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这是一种新疗法。","pinyin":"Zhè shì yì zhǒng xīnliáofǎ.","vi":"Đây là một liệu pháp mới."},{"type":"simple","zh":"医生建议他试试中西医结合的疗法。","pinyin":"Yīshēng jiànyì tā shìshi Zhōngxīyījiéhé de liáofǎ.","vi":"Bác sĩ khuyên anh ấy thử liệu pháp kết hợp Đông Tây y."},{"type":"compound","zh":"如果这种疗法有效，就能帮助很多病人。","pinyin":"Rúguǒ zhè zhǒng liáofǎ yǒuxiào, jiù néng bāngzhù hěn duō bìngrén.","vi":"Nếu liệu pháp này hiệu quả thì có thể giúp được rất nhiều bệnh nhân."}],"related":[{"hanzi":"治疗","pinyin":"zhìliáo","vi":"điều trị"},{"hanzi":"疗效","pinyin":"liáoxiào","vi":"hiệu quả điều trị"},{"hanzi":"疗程","pinyin":"liáochéng","vi":"liệu trình"},{"hanzi":"理疗","pinyin":"lǐliáo","vi":"vật lý trị liệu"}],"traditional":"療法"},{"id":"疗效","hanzi":"疗效","pinyin":"liáoxiào","meaning_vi":"hiệu quả điều trị, công hiệu","explanation":"疗 (liệu – chữa bệnh) + 效 (hiệu – hiệu quả) → hiệu quả của việc chữa bệnh.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"这种药疗效很好。","pinyin":"Zhè zhǒng yào liáoxiào hěn hǎo.","vi":"Loại thuốc này hiệu quả điều trị rất tốt."},{"type":"simple","zh":"新药的疗效还需要更多试验来证明。","pinyin":"Xīn yào de liáoxiào hái xūyào gèng duō shìyàn lái zhèngmíng.","vi":"Hiệu quả điều trị của thuốc mới còn cần thêm thử nghiệm để chứng minh."},{"type":"compound","zh":"因为疗效不明显，所以医生决定换一种药。","pinyin":"Yīnwèi liáoxiào bù míngxiǎn, suǒyǐ yīshēng juédìng huàn yì zhǒng yào.","vi":"Vì hiệu quả điều trị không rõ rệt nên bác sĩ quyết định đổi thuốc khác."}],"related":[{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"疗法","pinyin":"liáofǎ","vi":"liệu pháp"},{"hanzi":"药效","pinyin":"yàoxiào","vi":"tác dụng của thuốc"},{"hanzi":"副作用","pinyin":"fùzuòyòng","vi":"tác dụng phụ"}],"traditional":"療效"},{"id":"料到","hanzi":"料到","pinyin":"liàodào","meaning_vi":"đoán trước, lường trước","explanation":"料 (liệu – liệu tính, đoán) + 到 (đáo – tới) → đoán trước được; thường dùng dạng 没料到.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🔮","examples":[{"type":"basic","zh":"我早就料到了。","pinyin":"Wǒ zǎojiù liàodào le.","vi":"Tôi đã đoán trước từ lâu rồi."},{"type":"simple","zh":"谁也没料到比赛时会下起大雨。","pinyin":"Shéi yě méi liàodào bǐsài shí huì xià qǐ dàyǔ.","vi":"Không ai ngờ lúc thi đấu lại đổ mưa lớn."},{"type":"compound","zh":"如果早料到会堵车，我们就提前出发了。","pinyin":"Rúguǒ zǎo liàodào huì dǔchē, wǒmen jiù tíqián chūfā le.","vi":"Nếu đã lường trước sẽ tắc đường thì chúng tôi đã xuất phát sớm hơn."}],"related":[{"hanzi":"预料","pinyin":"yùliào","vi":"dự liệu"},{"hanzi":"意料","pinyin":"yìliào","vi":"liệu trước"},{"hanzi":"想到","pinyin":"xiǎngdào","vi":"nghĩ tới"},{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự đoán"}]},{"id":"料理","hanzi":"料理","pinyin":"liàolǐ","meaning_vi":"lo liệu, thu xếp; nấu nướng; món ăn (ẩm thực)","explanation":"料 (liệu – liệu lý) + 理 (lý – xử lý) → lo liệu, thu xếp công việc; nghĩa mới chỉ món ăn, ẩm thực (như 日本料理).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍱","examples":[{"type":"basic","zh":"她在料理家务。","pinyin":"Tā zài liàolǐ jiāwù.","vi":"Cô ấy đang lo liệu việc nhà."},{"type":"simple","zh":"我们周末去吃了一顿日本料理。","pinyin":"Wǒmen zhōumò qù chīle yí dùn Rìběn liàolǐ.","vi":"Cuối tuần chúng tôi đã đi ăn một bữa món Nhật."},{"type":"compound","zh":"父亲去世后，所有的后事都是由哥哥料理的。","pinyin":"Fùqīn qùshì hòu, suǒyǒu de hòushì dōu shì yóu gēge liàolǐ de.","vi":"Sau khi bố mất, mọi việc hậu sự đều do anh trai lo liệu."}],"related":[{"hanzi":"处理","pinyin":"chǔlǐ","vi":"xử lý"},{"hanzi":"打理","pinyin":"dǎlǐ","vi":"quán xuyến"},{"hanzi":"菜肴","pinyin":"càiyáo","vi":"món ăn"},{"hanzi":"烹饪","pinyin":"pēngrèn","vi":"nấu nướng"}]},{"id":"劣势","hanzi":"劣势","pinyin":"lièshì","meaning_vi":"thế yếu, bất lợi","explanation":"劣 (liệt – kém) + 势 (thế – tình thế) → tình thế kém, ở vào thế bất lợi; trái nghĩa 优势.","hsk_level":"7-9","tags":["danh-tu"],"image":"📉","examples":[{"type":"basic","zh":"我们处于劣势。","pinyin":"Wǒmen chǔyú lièshì.","vi":"Chúng ta đang ở thế yếu."},{"type":"simple","zh":"身高不够是他打篮球的最大劣势。","pinyin":"Shēngāo búgòu shì tā dǎlánqiú de zuì dà lièshì.","vi":"Chiều cao không đủ là điểm bất lợi lớn nhất khi anh ấy chơi bóng rổ."},{"type":"compound","zh":"虽然上半场处于劣势，但是他们下半场成功逆转了。","pinyin":"Suīrán shàngbànchǎng chǔyú lièshì, dànshì tāmen xiàbànchǎng chénggōng nìzhuǎn le.","vi":"Tuy hiệp một ở thế yếu nhưng sang hiệp hai họ đã lội ngược dòng thành công."}],"related":[{"hanzi":"优势","pinyin":"yōushì","vi":"ưu thế"},{"hanzi":"弱点","pinyin":"ruòdiǎn","vi":"điểm yếu"},{"hanzi":"不利","pinyin":"búlì","vi":"bất lợi"},{"hanzi":"劣质","pinyin":"lièzhì","vi":"kém chất lượng"}],"traditional":"劣勢"},{"id":"劣质","hanzi":"劣质","pinyin":"lièzhì","meaning_vi":"kém chất lượng, hàng dỏm","explanation":"劣 (liệt – kém) + 质 (chất – chất lượng) → chất lượng kém.","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"🚫","examples":[{"type":"basic","zh":"这是劣质产品。","pinyin":"Zhè shì lièzhì chǎnpǐn.","vi":"Đây là sản phẩm kém chất lượng."},{"type":"simple","zh":"装修时千万不要用劣质的材料。","pinyin":"Zhuāngxiū shí qiānwàn bú yào yòng lièzhì de cáiliào.","vi":"Khi sửa nhà tuyệt đối đừng dùng vật liệu kém chất lượng."},{"type":"compound","zh":"因为买了劣质轮胎，所以车在高速上爆胎了。","pinyin":"Yīnwèi mǎile lièzhì lúntāi, suǒyǐ chē zài gāosù shang bàotāi le.","vi":"Vì mua phải lốp kém chất lượng nên xe bị nổ lốp trên đường cao tốc."}],"related":[{"hanzi":"优质","pinyin":"yōuzhì","vi":"chất lượng cao"},{"hanzi":"质量","pinyin":"zhìliàng","vi":"chất lượng"},{"hanzi":"伪劣","pinyin":"wěiliè","vi":"giả và kém"},{"hanzi":"次品","pinyin":"cìpǐn","vi":"hàng thứ phẩm"}],"traditional":"劣質"},{"id":"猎犬","hanzi":"猎犬","pinyin":"lièquǎn","meaning_vi":"chó săn","explanation":"猎 (liệp – săn bắn) + 犬 (khuyển – chó) → chó được nuôi để đi săn.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐕","examples":[{"type":"basic","zh":"这只猎犬鼻子很灵。","pinyin":"Zhè zhī lièquǎn bízi hěn líng.","vi":"Con chó săn này mũi rất thính."},{"type":"simple","zh":"猎人带着两只猎犬进了树林。","pinyin":"Lièrén dàizhe liǎng zhī lièquǎn jìnle shùlín.","vi":"Người thợ săn dẫn theo hai con chó săn vào rừng."},{"type":"compound","zh":"一旦闻到兔子的气味，猎犬就会立刻追上去。","pinyin":"Yídàn wéndào tùzi de qìwèi, lièquǎn jiù huì lìkè zhuī shangqù.","vi":"Một khi ngửi thấy mùi thỏ, chó săn sẽ lập tức đuổi theo."}],"related":[{"hanzi":"猎人","pinyin":"lièrén","vi":"thợ săn"},{"hanzi":"打猎","pinyin":"dǎliè","vi":"đi săn"},{"hanzi":"警犬","pinyin":"jǐngquǎn","vi":"chó nghiệp vụ"},{"hanzi":"狗","pinyin":"gǒu","vi":"chó"}],"traditional":"獵犬"},{"id":"猎人","hanzi":"猎人","pinyin":"lièrén","meaning_vi":"thợ săn","explanation":"猎 (liệp – săn bắn) + 人 (nhân – người) → người đi săn thú.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🏹","examples":[{"type":"basic","zh":"猎人在山上打猎。","pinyin":"Lièrén zài shān shang dǎliè.","vi":"Người thợ săn đi săn trên núi."},{"type":"simple","zh":"这位老猎人对森林里的每条路都很熟悉。","pinyin":"Zhè wèi lǎo lièrén duì sēnlín li de měi tiáo lù dōu hěn shúxī.","vi":"Người thợ săn già này rất thông thuộc mọi lối đi trong rừng."},{"type":"compound","zh":"虽然狐狸很狡猾，但是最终还是被猎人发现了。","pinyin":"Suīrán húli hěn jiǎohuá, dànshì zuìzhōng háishi bèi lièrén fāxiàn le.","vi":"Tuy con cáo rất xảo quyệt nhưng cuối cùng vẫn bị thợ săn phát hiện."}],"related":[{"hanzi":"打猎","pinyin":"dǎliè","vi":"đi săn"},{"hanzi":"猎物","pinyin":"lièwù","vi":"con mồi"},{"hanzi":"猎枪","pinyin":"lièqiāng","vi":"súng săn"},{"hanzi":"猎犬","pinyin":"lièquǎn","vi":"chó săn"}],"traditional":"獵人"},{"id":"裂缝","hanzi":"裂缝","pinyin":"lièfèng","meaning_vi":"vết nứt, khe nứt","explanation":"裂 (liệt – nứt) + 缝 (phùng – khe hở) → khe hở do bị nứt ra.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🧱","examples":[{"type":"basic","zh":"墙上有一道裂缝。","pinyin":"Qiáng shang yǒu yídào lièfèng.","vi":"Trên tường có một vết nứt."},{"type":"simple","zh":"地震过后，马路上出现了很多裂缝。","pinyin":"Dìzhèn guòhòu, mǎ lùshang chūxiànle hěn duō lièfèng.","vi":"Sau trận động đất, trên đường xuất hiện rất nhiều vết nứt."},{"type":"compound","zh":"如果窗户玻璃上有裂缝，就要尽快换掉。","pinyin":"Rúguǒ chuānghu bōli shang yǒu lièfèng, jiùyào jǐnkuài huàn diào.","vi":"Nếu kính cửa sổ có vết nứt thì phải thay càng sớm càng tốt."}],"related":[{"hanzi":"裂开","pinyin":"lièkāi","vi":"nứt ra"},{"hanzi":"缝隙","pinyin":"fèngxì","vi":"khe hở"},{"hanzi":"破裂","pinyin":"pòliè","vi":"vỡ, rạn"},{"hanzi":"分裂","pinyin":"fēnliè","vi":"chia rẽ"}],"traditional":"裂縫"},{"id":"咧嘴","hanzi":"咧嘴","pinyin":"liězuǐ","meaning_vi":"nhe răng, toét miệng (cười), nhăn mặt","explanation":"咧 (liệt – toét, nhe) + 嘴 (chủy – miệng) → mở toét miệng ra, khi cười hoặc khi đau.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😁","examples":[{"type":"basic","zh":"他咧嘴一笑。","pinyin":"Tā liězuǐ yí xiào.","vi":"Anh ấy toét miệng cười."},{"type":"simple","zh":"孩子拿到糖，高兴得咧嘴直笑。","pinyin":"Háizi nádào táng, gāoxìng de liězuǐ zhí xiào.","vi":"Đứa bé được kẹo, vui đến mức toét miệng cười mãi."},{"type":"compound","zh":"因为伤口太疼了，所以他忍不住咧嘴吸了口气。","pinyin":"Yīnwèi shāngkǒu tài téng le, suǒyǐ tā rěnbúzhù liězuǐ xīle kǒuqì.","vi":"Vì vết thương đau quá nên anh ấy không nhịn được nhăn mặt hít một hơi."}],"related":[{"hanzi":"笑","pinyin":"xiào","vi":"cười"},{"hanzi":"龇牙咧嘴","pinyin":"zīyáliězuǐ","vi":"nhe răng nhăn mặt"},{"hanzi":"嘴巴","pinyin":"zuǐba","vi":"miệng"},{"hanzi":"傻笑","pinyin":"shǎxiào","vi":"cười ngây ngô"}]},{"id":"拎","hanzi":"拎","pinyin":"līn","meaning_vi":"xách, nhấc lên","explanation":"拎 (linh – xách) → cầm treo vật nặng trong tay mà xách đi; khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"👜","examples":[{"type":"basic","zh":"她拎着一个包。","pinyin":"Tā līnzhe yí ge bāo.","vi":"Cô ấy xách một cái túi."},{"type":"simple","zh":"妈妈从超市拎回来两大袋水果。","pinyin":"Māma cóng chāoshì līn huílái liǎng dà dài shuǐguǒ.","vi":"Mẹ xách từ siêu thị về hai túi to hoa quả."},{"type":"compound","zh":"虽然箱子不大，但是拎起来却特别沉。","pinyin":"Suīrán xiāngzi búdà, dànshì līn qǐlái què tèbié chén.","vi":"Tuy chiếc vali không to nhưng xách lên lại rất nặng."}],"related":[{"hanzi":"提","pinyin":"tí","vi":"xách"},{"hanzi":"拿","pinyin":"ná","vi":"cầm"},{"hanzi":"背","pinyin":"bēi","vi":"cõng, đeo"},{"hanzi":"扛","pinyin":"káng","vi":"vác"}]},{"id":"临","hanzi":"临","pinyin":"lín","meaning_vi":"đến gần, kề sát, sắp, khi sắp","explanation":"临 (lâm – đến, gần) → đến gần, đối diện; trước động từ chỉ \"sắp, lúc sắp\" (临走, 临睡).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔜","examples":[{"type":"basic","zh":"临走前他说了一句话。","pinyin":"Línzǒu qián tā shuōle yíjùhuà.","vi":"Trước lúc đi anh ấy nói một câu."},{"type":"simple","zh":"这家酒店背山临海，风景特别美。","pinyin":"Zhè jiā jiǔdiàn bèishān línhǎi, fēngjǐng tèbié měi.","vi":"Khách sạn này tựa núi nhìn ra biển, phong cảnh rất đẹp."},{"type":"compound","zh":"每次临考试的时候，他就紧张得睡不着觉。","pinyin":"Měi cì lín kǎoshì de shíhou, tā jiù jǐnzhāng de shuìbùzháo jiào.","vi":"Mỗi lần sắp thi, cậu ấy lại căng thẳng đến mất ngủ."}],"related":[{"hanzi":"面临","pinyin":"miànlín","vi":"đối mặt"},{"hanzi":"光临","pinyin":"guānglín","vi":"ghé thăm"},{"hanzi":"临时","pinyin":"línshí","vi":"tạm thời"},{"hanzi":"来临","pinyin":"láilín","vi":"đến"}],"traditional":"臨"},{"id":"临街","hanzi":"临街","pinyin":"línjiē","meaning_vi":"mặt phố, hướng ra đường","explanation":"临 (lâm – kề sát) + 街 (nhai – phố) → nằm sát mặt đường, quay ra phố.","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏘️","examples":[{"type":"basic","zh":"我家是临街的房子。","pinyin":"Wǒ jiā shì línjiē de fángzi.","vi":"Nhà tôi là nhà mặt phố."},{"type":"simple","zh":"他在临街的地方开了一家小面馆。","pinyin":"Tā zài línjiē de dìfang kāile yìjiā xiǎo miànguǎn.","vi":"Anh ấy mở một quán mì nhỏ ở mặt phố."},{"type":"compound","zh":"因为卧室临街，所以晚上总能听到汽车的声音。","pinyin":"Yīnwèi wòshì línjiē, suǒyǐ wǎnshang zǒngnéng tīngdào qìchē de shēngyīn.","vi":"Vì phòng ngủ quay ra đường nên buổi tối lúc nào cũng nghe tiếng xe."}],"related":[{"hanzi":"街道","pinyin":"jiēdào","vi":"đường phố"},{"hanzi":"门面","pinyin":"ménmiàn","vi":"mặt tiền"},{"hanzi":"沿街","pinyin":"yánjiē","vi":"dọc phố"},{"hanzi":"铺面","pinyin":"pùmiàn","vi":"mặt bằng cửa hàng"}],"traditional":"臨街"},{"id":"灵","hanzi":"灵","pinyin":"líng","meaning_vi":"nhạy, linh hoạt; linh nghiệm, hiệu nghiệm","explanation":"灵 (linh – linh hoạt, linh nghiệm) → nhanh nhạy, khéo léo; cũng chỉ có hiệu quả, linh nghiệm.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"这个办法真灵！","pinyin":"Zhè ge bànfǎ zhēn líng!","vi":"Cách này hiệu nghiệm thật!"},{"type":"simple","zh":"狗的鼻子比人的灵多了。","pinyin":"Gǒu de bízi bǐ rén de líng duō le.","vi":"Mũi chó thính hơn mũi người nhiều."},{"type":"compound","zh":"虽然这孩子年纪小，但是脑子特别灵。","pinyin":"Suīrán zhè háizi niánjì xiǎo, dànshì nǎozi tèbié líng.","vi":"Tuy đứa trẻ còn nhỏ nhưng đầu óc rất nhanh nhạy."}],"related":[{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"灵敏","pinyin":"língmǐn","vi":"nhạy bén"},{"hanzi":"机灵","pinyin":"jīling","vi":"lanh lợi"},{"hanzi":"灵验","pinyin":"língyàn","vi":"linh nghiệm"}],"traditional":"靈"},{"id":"灵机一动","hanzi":"灵机一动","pinyin":"língjī-yídòng","meaning_vi":"chợt nảy ra ý hay, lóe lên sáng kiến","explanation":"灵机 (linh cơ – sự nhanh trí) + 一动 (nhất động – vừa động) → trí óc vừa chuyển động đã nảy ra ý hay.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"他灵机一动，想出了办法。","pinyin":"Tā língjīyídòng, xiǎngchūle bànfǎ.","vi":"Anh ấy chợt lóe lên ý, nghĩ ra cách."},{"type":"simple","zh":"小女孩灵机一动，用发卡打开了锁。","pinyin":"Xiǎo nǚhái língjīyídòng, yòng fàqiǎ dǎkāile suǒ.","vi":"Cô bé chợt nảy ra ý, dùng kẹp tóc mở được ổ khóa."},{"type":"compound","zh":"正当大家没办法的时候，老王灵机一动，就想到了一个好主意。","pinyin":"Zhèngdāng dàjiā méi bànfǎ de shíhou, lǎo Wáng língjīyídòng, jiù xiǎngdàole yí ge hǎo zhǔyi.","vi":"Đúng lúc mọi người bó tay, ông Vương chợt lóe sáng kiến và nghĩ ra một ý hay."}],"related":[{"hanzi":"灵感","pinyin":"línggǎn","vi":"cảm hứng"},{"hanzi":"急中生智","pinyin":"jízhōngshēngzhì","vi":"cái khó ló cái khôn"},{"hanzi":"主意","pinyin":"zhǔyi","vi":"ý kiến"},{"hanzi":"机智","pinyin":"jīzhì","vi":"nhanh trí"}],"traditional":"靈機一動"},{"id":"零钱","hanzi":"零钱","pinyin":"língqián","meaning_vi":"tiền lẻ, tiền tiêu vặt","explanation":"零 (linh – lẻ) + 钱 (tiền) → tiền lẻ, tiền mệnh giá nhỏ; cũng chỉ tiền tiêu vặt.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🪙","examples":[{"type":"basic","zh":"你有零钱吗？","pinyin":"Nǐ yǒu língqián ma?","vi":"Bạn có tiền lẻ không?"},{"type":"simple","zh":"妈妈每个星期给我五十块零钱。","pinyin":"Māma měi ge xīngqī gěi wǒ wǔshí kuài língqián.","vi":"Mỗi tuần mẹ cho tôi năm mươi tệ tiền tiêu vặt."},{"type":"compound","zh":"因为司机找不开一百块，所以我只好去换零钱。","pinyin":"Yīnwèi sījī zhǎo bù kāi yī bǎi kuài, suǒyǐ wǒ zhǐhǎo qù huàn língqián.","vi":"Vì tài xế không có tiền thối tờ một trăm nên tôi đành đi đổi tiền lẻ."}],"related":[{"hanzi":"零花钱","pinyin":"línghuāqián","vi":"tiền tiêu vặt"},{"hanzi":"找零","pinyin":"zhǎolíng","vi":"thối tiền"},{"hanzi":"整钱","pinyin":"zhěngqián","vi":"tiền chẵn"},{"hanzi":"硬币","pinyin":"yìngbì","vi":"tiền xu"}],"traditional":"零錢"},{"id":"零售","hanzi":"零售","pinyin":"língshòu","meaning_vi":"bán lẻ","explanation":"零 (linh – lẻ) + 售 (thụ – bán) → bán lẻ từng món, số lượng nhỏ; trái với 批发.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"这家店只零售不批发。","pinyin":"Zhè jiā diàn zhǐ língshòu bù pīfā.","vi":"Cửa hàng này chỉ bán lẻ không bán buôn."},{"type":"simple","zh":"今年网上零售的总额又创了新高。","pinyin":"Jīnnián wǎngshang língshòu de zǒng'é yòu chuàngle xīngāo.","vi":"Năm nay tổng doanh số bán lẻ trực tuyến lại lập kỷ lục mới."},{"type":"compound","zh":"如果零售价格太高，顾客就会去别家买。","pinyin":"Rúguǒ língshòu jiàgé tài gāo, gùkè jiù huì qù bié jiā mǎi.","vi":"Nếu giá bán lẻ quá cao, khách sẽ sang chỗ khác mua."}],"related":[{"hanzi":"批发","pinyin":"pīfā","vi":"bán buôn"},{"hanzi":"零售商","pinyin":"língshòushāng","vi":"nhà bán lẻ"},{"hanzi":"出售","pinyin":"chūshòu","vi":"bán ra"},{"hanzi":"售价","pinyin":"shòujià","vi":"giá bán"}]},{"id":"领队","hanzi":"领队","pinyin":"lǐngduì","meaning_vi":"trưởng đoàn, người dẫn đoàn; dẫn đội","explanation":"领 (lĩnh – dẫn dắt) + 队 (đội – đoàn) → người dẫn dắt một đoàn, một đội.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🚩","examples":[{"type":"basic","zh":"他是我们的领队。","pinyin":"Tā shì wǒmen de lǐngduì.","vi":"Anh ấy là trưởng đoàn của chúng tôi."},{"type":"simple","zh":"领队提醒大家八点在酒店门口集合。","pinyin":"Lǐngduì tíxǐng dàjiā bā diǎn zài jiǔdiàn ménkǒu jíhé.","vi":"Trưởng đoàn nhắc mọi người tám giờ tập trung trước cửa khách sạn."},{"type":"compound","zh":"如果路上遇到问题，你们就马上联系领队。","pinyin":"Rúguǒ lùshang yùdào wèntí, nǐmen jiù mǎshàng liánxì lǐngduì.","vi":"Nếu trên đường gặp vấn đề, các bạn hãy liên lạc ngay với trưởng đoàn."}],"related":[{"hanzi":"导游","pinyin":"dǎoyóu","vi":"hướng dẫn viên"},{"hanzi":"队长","pinyin":"duìzhǎng","vi":"đội trưởng"},{"hanzi":"带队","pinyin":"dàiduì","vi":"dẫn đội"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"}],"traditional":"領隊"},{"id":"领军","hanzi":"领军","pinyin":"lǐngjūn","meaning_vi":"dẫn đầu, đi đầu; cầm quân","explanation":"领 (lĩnh – dẫn) + 军 (quân – quân đội) → cầm quân; nghĩa bóng là dẫn đầu một lĩnh vực (领军人物, 领军企业).","hsk_level":"7-9","tags":["dong-tu"],"image":"🥇","examples":[{"type":"basic","zh":"他是行业的领军人物。","pinyin":"Tā shì hángyè de lǐngjūn rénwù.","vi":"Ông ấy là nhân vật dẫn đầu trong ngành."},{"type":"simple","zh":"这家公司在新能源领域一直处于领军地位。","pinyin":"Zhè jiā gōngsī zài xīnnéngyuán lǐngyù yìzhí chǔyú lǐngjūn dìwèi.","vi":"Công ty này luôn giữ vị trí dẫn đầu trong lĩnh vực năng lượng mới."},{"type":"compound","zh":"因为有老将领军，所以这支年轻的队伍表现很稳定。","pinyin":"Yīnwèi yǒu lǎojiàng lǐngjūn, suǒyǐ zhè zhī niánqīng de duìwu biǎoxiàn hěn wěndìng.","vi":"Vì có lão tướng dẫn dắt nên đội trẻ này thi đấu rất ổn định."}],"related":[{"hanzi":"带头","pinyin":"dàitóu","vi":"dẫn đầu"},{"hanzi":"领先","pinyin":"lǐngxiān","vi":"dẫn trước"},{"hanzi":"率领","pinyin":"shuàilǐng","vi":"thống lĩnh"},{"hanzi":"龙头","pinyin":"lóngtóu","vi":"đầu tàu"}],"traditional":"領軍"},{"id":"领养","hanzi":"领养","pinyin":"lǐngyǎng","meaning_vi":"nhận nuôi","explanation":"领 (lĩnh – nhận) + 养 (dưỡng – nuôi) → nhận về để nuôi (trẻ em, thú cưng).","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🤱","examples":[{"type":"basic","zh":"我们领养了一只狗。","pinyin":"Wǒmen lǐngyǎngle yì zhī gǒu.","vi":"Chúng tôi đã nhận nuôi một con chó."},{"type":"simple","zh":"这对夫妻从孤儿院领养了一个女孩。","pinyin":"Zhè duì fūqī cóng gū'éryuàn lǐngyǎngle yí ge nǚhái.","vi":"Đôi vợ chồng này nhận nuôi một bé gái từ trại trẻ mồ côi."},{"type":"compound","zh":"如果你真想养宠物，就去动物中心领养吧。","pinyin":"Rúguǒ nǐ zhēn xiǎng yǎng chǒngwù, jiù qù dòngwù zhōngxīn lǐngyǎng ba.","vi":"Nếu bạn thật sự muốn nuôi thú cưng thì hãy đến trung tâm động vật nhận nuôi."}],"related":[{"hanzi":"收养","pinyin":"shōuyǎng","vi":"nhận nuôi"},{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi dưỡng"},{"hanzi":"养子","pinyin":"yǎngzǐ","vi":"con nuôi"},{"hanzi":"孤儿","pinyin":"gū'ér","vi":"trẻ mồ côi"}],"traditional":"領養"},{"id":"溜达","hanzi":"溜达","pinyin":"liūda","meaning_vi":"đi dạo, đi lòng vòng","explanation":"溜 (lưu – trượt, đi lững thững) + 达 (đạt) → đi dạo thong thả; khẩu ngữ phương Bắc.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🚶","examples":[{"type":"basic","zh":"我们出去溜达溜达。","pinyin":"Wǒmen chūqù liūda liūda.","vi":"Chúng ta ra ngoài đi dạo một chút."},{"type":"simple","zh":"爷爷每天吃完早饭都去公园溜达一圈。","pinyin":"Yéye měitiān chīwán zǎofàn dōu qù gōngyuán liūda yìquān.","vi":"Ông nội mỗi ngày ăn sáng xong đều ra công viên đi dạo một vòng."},{"type":"compound","zh":"既然今天没什么事，我们就去街上溜达一会儿吧。","pinyin":"Jìrán jīntiān méi shénmeshì, wǒmen jiù qù jiēshang liūda yíhuìr ba.","vi":"Đã hôm nay không có việc gì thì chúng ta ra phố đi dạo một lúc đi."}],"related":[{"hanzi":"散步","pinyin":"sànbù","vi":"đi dạo"},{"hanzi":"逛","pinyin":"guàng","vi":"dạo chơi"},{"hanzi":"遛","pinyin":"liù","vi":"dắt đi dạo"},{"hanzi":"闲逛","pinyin":"xiánguàng","vi":"đi lang thang"}],"traditional":"溜達"},{"id":"浏览器","hanzi":"浏览器","pinyin":"liúlǎnqì","meaning_vi":"trình duyệt (web)","explanation":"浏览 (lưu lãm – xem lướt) + 器 (khí – công cụ) → phần mềm dùng để xem các trang web.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"请打开浏览器。","pinyin":"Qǐng dǎkāi liúlǎnqì.","vi":"Hãy mở trình duyệt."},{"type":"simple","zh":"这个网页在手机浏览器里显示不正常。","pinyin":"Zhè ge wǎngyè zài shǒujī liúlǎnqì li xiǎnshì bú zhèngcháng.","vi":"Trang web này hiển thị không bình thường trên trình duyệt điện thoại."},{"type":"compound","zh":"如果浏览器太旧，有些网站就打不开。","pinyin":"Rúguǒ liúlǎnqì tài jiù, yǒuxiē wǎngzhàn jiù dǎ bù kāi.","vi":"Nếu trình duyệt quá cũ thì một số trang web sẽ không mở được."}],"related":[{"hanzi":"浏览","pinyin":"liúlǎn","vi":"xem lướt"},{"hanzi":"网页","pinyin":"wǎngyè","vi":"trang web"},{"hanzi":"网站","pinyin":"wǎngzhàn","vi":"website"},{"hanzi":"搜索引擎","pinyin":"sōusuǒyǐnqíng","vi":"công cụ tìm kiếm"}],"traditional":"瀏覽器"},{"id":"流畅","hanzi":"流畅","pinyin":"liúchàng","meaning_vi":"trôi chảy, lưu loát, mượt mà","explanation":"流 (lưu – chảy) + 畅 (sướng – thông suốt) → trôi chảy, không vấp váp; dùng cho lời nói, văn viết, vận hành máy.","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"她的汉语说得很流畅。","pinyin":"Tā de Hànyǔ shuō de hěn liúchàng.","vi":"Cô ấy nói tiếng Trung rất lưu loát."},{"type":"simple","zh":"换了新电脑以后，游戏运行得非常流畅。","pinyin":"Huànle xīn diànnǎo yǐhòu, yóuxì yùnxíng de fēicháng liúchàng.","vi":"Sau khi đổi máy tính mới, trò chơi chạy rất mượt."},{"type":"compound","zh":"虽然文章写得很流畅，但是内容有点儿空洞。","pinyin":"Suīrán wénzhāng xiě de hěn liúchàng, dànshì nèiróng yǒudiǎnr kōngdòng.","vi":"Tuy bài văn viết rất trôi chảy nhưng nội dung hơi rỗng."}],"related":[{"hanzi":"流利","pinyin":"liúlì","vi":"lưu loát"},{"hanzi":"顺畅","pinyin":"shùnchàng","vi":"thông suốt"},{"hanzi":"通顺","pinyin":"tōngshùn","vi":"trôi chảy"},{"hanzi":"卡顿","pinyin":"kǎdùn","vi":"giật, lag"}],"traditional":"流暢"},{"id":"流程","hanzi":"流程","pinyin":"liúchéng","meaning_vi":"quy trình, trình tự","explanation":"流 (lưu – dòng chảy) + 程 (trình – trình tự) → trình tự các bước tiến hành một công việc.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"请先了解办事流程。","pinyin":"Qǐng xiān liǎojiě bànshì liúchéng.","vi":"Hãy tìm hiểu quy trình làm thủ tục trước."},{"type":"simple","zh":"公司简化了报销流程，现在快多了。","pinyin":"Gōngsī jiǎnhuàle bàoxiāo liúchéng, xiànzài kuài duō le.","vi":"Công ty đã đơn giản hóa quy trình thanh toán, giờ nhanh hơn nhiều."},{"type":"compound","zh":"只要按照流程操作，就不会出现安全问题。","pinyin":"Zhǐyào ànzhào liúchéng cāozuò, jiù bú huì chūxiàn ānquán wèntí.","vi":"Chỉ cần thao tác theo đúng quy trình thì sẽ không xảy ra vấn đề an toàn."}],"related":[{"hanzi":"程序","pinyin":"chéngxù","vi":"trình tự"},{"hanzi":"步骤","pinyin":"bùzhòu","vi":"bước"},{"hanzi":"环节","pinyin":"huánjié","vi":"khâu"},{"hanzi":"流程图","pinyin":"liúchéngtú","vi":"sơ đồ quy trình"}]},{"id":"流氓","hanzi":"流氓","pinyin":"liúmáng","meaning_vi":"côn đồ, lưu manh; hành vi đồi bại","explanation":"流 (lưu – trôi dạt) + 氓 (manh – dân) → kẻ lang thang vô lại, côn đồ; cũng chỉ hành vi sàm sỡ (耍流氓).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🦹","examples":[{"type":"basic","zh":"那几个人是流氓。","pinyin":"Nà jǐ ge rén shì liúmáng.","vi":"Mấy người đó là bọn côn đồ."},{"type":"simple","zh":"警察很快抓住了在街上闹事的流氓。","pinyin":"Jǐngchá hěn kuài zhuāzhùle zài jiēshang nàoshì de liúmáng.","vi":"Cảnh sát nhanh chóng bắt được tên côn đồ gây rối trên phố."},{"type":"compound","zh":"如果有人在车上耍流氓，就应该马上报警。","pinyin":"Rúguǒ yǒurén zài chē shang shuǎliúmáng, jiù yīnggāi mǎshàng bàojǐng.","vi":"Nếu có kẻ giở trò đồi bại trên xe thì nên báo cảnh sát ngay."}],"related":[{"hanzi":"无赖","pinyin":"wúlài","vi":"vô lại"},{"hanzi":"坏蛋","pinyin":"huàidàn","vi":"kẻ xấu"},{"hanzi":"歹徒","pinyin":"dǎitú","vi":"kẻ cướp"},{"hanzi":"耍流氓","pinyin":"shuǎliúmáng","vi":"giở trò lưu manh"}]},{"id":"流入","hanzi":"流入","pinyin":"liúrù","meaning_vi":"chảy vào, đổ vào","explanation":"流 (lưu – chảy) + 入 (nhập – vào) → chảy vào; nghĩa rộng chỉ tiền, người, hàng hóa đổ vào.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"这条河流入大海。","pinyin":"Zhè tiáo hé liúrù dàhǎi.","vi":"Con sông này đổ ra biển lớn."},{"type":"simple","zh":"大量外资流入了这个新兴市场。","pinyin":"Dàliàng wàizī liúrùle zhè ge xīnxīng shìchǎng.","vi":"Lượng lớn vốn ngoại đã đổ vào thị trường mới nổi này."},{"type":"compound","zh":"一旦污水流入河里，鱼就会大量死亡。","pinyin":"Yídàn wūshuǐ liúrù hé li, yú jiù huì dàliàng sǐwáng.","vi":"Một khi nước thải chảy vào sông, cá sẽ chết hàng loạt."}],"related":[{"hanzi":"流出","pinyin":"liúchū","vi":"chảy ra"},{"hanzi":"流向","pinyin":"liúxiàng","vi":"chảy về"},{"hanzi":"涌入","pinyin":"yǒngrù","vi":"tràn vào"},{"hanzi":"注入","pinyin":"zhùrù","vi":"rót vào"}]},{"id":"流水","hanzi":"流水","pinyin":"liúshuǐ","meaning_vi":"nước chảy; doanh thu, dòng tiền","explanation":"流 (lưu – chảy) + 水 (thủy – nước) → nước chảy; trong kinh doanh chỉ doanh thu, sổ thu chi (流水账).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🚰","examples":[{"type":"basic","zh":"请用流水洗手。","pinyin":"Qǐng yòng liúshuǐ xǐshǒu.","vi":"Hãy rửa tay bằng nước chảy."},{"type":"simple","zh":"这家小店每天的流水有五六千元。","pinyin":"Zhè jiā xiǎodiàn měitiān de liúshuǐ yǒu wǔ liù qiān yuán.","vi":"Cửa hàng nhỏ này mỗi ngày doanh thu khoảng năm sáu nghìn tệ."},{"type":"compound","zh":"虽然山里没有路，但是顺着流水走就能找到村子。","pinyin":"Suīrán shān li méiyǒu lù, dànshì shùnzhe liúshuǐ zǒu jiù néng zhǎodào cūnzi.","vi":"Tuy trong núi không có đường nhưng men theo dòng nước chảy sẽ tìm thấy làng."}],"related":[{"hanzi":"流水线","pinyin":"liúshuǐxiàn","vi":"dây chuyền"},{"hanzi":"流水账","pinyin":"liúshuǐzhàng","vi":"sổ thu chi"},{"hanzi":"营业额","pinyin":"yíngyè'é","vi":"doanh thu"},{"hanzi":"溪水","pinyin":"xīshuǐ","vi":"nước suối"}]},{"id":"流淌","hanzi":"流淌","pinyin":"liútǎng","meaning_vi":"chảy, tuôn chảy","explanation":"流 (lưu – chảy) + 淌 (thảng – chảy nhỏ giọt) → chất lỏng chảy liên tục; văn viết, giàu hình ảnh.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"💧","examples":[{"type":"basic","zh":"小溪静静地流淌。","pinyin":"Xiǎoxī jìng jìng de liútǎng.","vi":"Dòng suối nhỏ lặng lẽ chảy."},{"type":"simple","zh":"汗水顺着他的额头不停地流淌下来。","pinyin":"Hànshuǐ shùnzhe tā de étóu bùtíng de liútǎng xiàlái.","vi":"Mồ hôi không ngừng chảy xuống từ trán anh ấy."},{"type":"compound","zh":"每当听到这首歌，温暖就在我心中流淌。","pinyin":"Měidāng tīngdào zhè shǒu gē, wēnnuǎn jiù zài wǒ xīnzhōng liútǎng.","vi":"Mỗi khi nghe bài hát này, sự ấm áp lại tuôn chảy trong lòng tôi."}],"related":[{"hanzi":"流动","pinyin":"liúdòng","vi":"lưu động"},{"hanzi":"流淌着","pinyin":"liútǎngzhe","vi":"đang chảy"},{"hanzi":"溪流","pinyin":"xīliú","vi":"dòng suối"},{"hanzi":"流出","pinyin":"liúchū","vi":"chảy ra"}]},{"id":"流向","hanzi":"流向","pinyin":"liúxiàng","meaning_vi":"hướng chảy, dòng chảy; chảy về","explanation":"流 (lưu – chảy) + 向 (hướng) → hướng chảy của nước; nghĩa rộng chỉ hướng di chuyển của tiền, người, hàng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧭","examples":[{"type":"basic","zh":"这条河的流向是由西向东。","pinyin":"Zhè tiáo hé de liúxiàng shì yóu xī xiàng dōng.","vi":"Hướng chảy của con sông này là từ tây sang đông."},{"type":"simple","zh":"警方正在调查这笔钱的最终流向。","pinyin":"Jǐngfāng zhèngzài diàochá zhè bǐ qián de zuìzhōng liúxiàng.","vi":"Cảnh sát đang điều tra nơi cuối cùng số tiền này chảy về."},{"type":"compound","zh":"因为大城市机会多，所以年轻人大多流向了那里。","pinyin":"Yīnwèi dàchéngshì jīhuì duō, suǒyǐ niánqīngrén dàduō liúxiàngle nàlǐ.","vi":"Vì thành phố lớn nhiều cơ hội nên phần lớn người trẻ đổ về đó."}],"related":[{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"},{"hanzi":"流入","pinyin":"liúrù","vi":"chảy vào"},{"hanzi":"去向","pinyin":"qùxiàng","vi":"nơi đến"},{"hanzi":"走向","pinyin":"zǒuxiàng","vi":"xu hướng"}]},{"id":"流血","hanzi":"流血","pinyin":"liúxuè","meaning_vi":"chảy máu, đổ máu","explanation":"流 (lưu – chảy) + 血 (huyết – máu) → máu chảy ra; nghĩa rộng chỉ đổ máu, hy sinh.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"他的手指流血了。","pinyin":"Tā de shǒuzhǐ liúxuè le.","vi":"Ngón tay anh ấy chảy máu rồi."},{"type":"simple","zh":"孩子摔了一跤，膝盖流血了。","pinyin":"Háizi shuāile yì jiāo, xīgài liúxuè le.","vi":"Đứa bé ngã một cái, đầu gối chảy máu."},{"type":"compound","zh":"如果伤口一直流血，就得赶紧去医院。","pinyin":"Rúguǒ shāngkǒu yìzhí liúxuè, jiù děi gǎnjǐn qù yīyuàn.","vi":"Nếu vết thương cứ chảy máu mãi thì phải mau đến bệnh viện."}],"related":[{"hanzi":"出血","pinyin":"chūxiě","vi":"xuất huyết"},{"hanzi":"止血","pinyin":"zhǐxuè","vi":"cầm máu"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"流汗","pinyin":"liúhàn","vi":"đổ mồ hôi"}]},{"id":"流转","hanzi":"流转","pinyin":"liúzhuǎn","meaning_vi":"luân chuyển, lưu chuyển; trôi đi","explanation":"流 (lưu – chảy) + 转 (chuyển – xoay chuyển) → chuyển dời không ngừng; dùng cho hàng hóa, vốn, đất đai, thời gian.","hsk_level":"7-9","tags":["dong-tu"],"image":"♻️","examples":[{"type":"basic","zh":"时光流转，转眼十年。","pinyin":"Shíguāng liúzhuǎn, zhuǎnyǎn shí nián.","vi":"Thời gian trôi đi, chớp mắt đã mười năm."},{"type":"simple","zh":"这批文物曾在多个国家之间流转。","pinyin":"Zhè pī wénwù céng zài duōge guójiā zhījiān liúzhuǎn.","vi":"Lô cổ vật này từng luân chuyển qua nhiều quốc gia."},{"type":"compound","zh":"如果资金流转不畅，企业就会陷入困境。","pinyin":"Rúguǒ zījīn liúzhuǎn bú chàng, qǐyè jiù huì xiànrù kùnjìng.","vi":"Nếu vốn luân chuyển không thông suốt, doanh nghiệp sẽ rơi vào khó khăn."}],"related":[{"hanzi":"流通","pinyin":"liútōng","vi":"lưu thông"},{"hanzi":"周转","pinyin":"zhōuzhuǎn","vi":"quay vòng"},{"hanzi":"转让","pinyin":"zhuǎnràng","vi":"chuyển nhượng"},{"hanzi":"流动","pinyin":"liúdòng","vi":"lưu động"}],"traditional":"流轉"},{"id":"留心","hanzi":"留心","pinyin":"liúxīn","meaning_vi":"để ý, lưu tâm, cẩn thận","explanation":"留 (lưu – giữ lại) + 心 (tâm – lòng) → giữ lòng chú ý vào điều gì.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"👀","examples":[{"type":"basic","zh":"过马路要留心。","pinyin":"Guòmǎlù yào liúxīn.","vi":"Qua đường phải để ý."},{"type":"simple","zh":"你留心一下，看他什么时候回来。","pinyin":"Nǐ liúxīn yíxià, kàn tā shénme shíhou huílái.","vi":"Bạn để ý xem khi nào anh ấy về nhé."},{"type":"compound","zh":"只要你平时多留心，就能发现生活中的小乐趣。","pinyin":"Zhǐyào nǐ píngshí duō liúxīn, jiù néng fāxiàn shēnghuó zhōng de xiǎo lèqù.","vi":"Chỉ cần thường ngày để ý hơn, bạn sẽ phát hiện những niềm vui nhỏ trong cuộc sống."}],"related":[{"hanzi":"留意","pinyin":"liúyì","vi":"lưu ý"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"cẩn thận"},{"hanzi":"注意","pinyin":"zhùyì","vi":"chú ý"},{"hanzi":"用心","pinyin":"yòngxīn","vi":"chú tâm"}]},{"id":"留意","hanzi":"留意","pinyin":"liúyì","meaning_vi":"lưu ý, chú ý, để tâm","explanation":"留 (lưu – giữ) + 意 (ý – ý nghĩ) → để ý nghĩ ở lại vào việc gì, tức chú ý, lưu tâm.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"📌","examples":[{"type":"basic","zh":"请留意车门。","pinyin":"Qǐng liúyì chēmén.","vi":"Xin chú ý cửa xe."},{"type":"simple","zh":"我一直在留意有没有合适的房子出租。","pinyin":"Wǒ yìzhí zài liúyì yǒuméiyǒu héshì de fángzi chūzū.","vi":"Tôi vẫn luôn để ý xem có nhà phù hợp cho thuê không."},{"type":"compound","zh":"如果你留意天气预报，就不会忘记带伞了。","pinyin":"Rúguǒ nǐ liúyì tiānqì yùbào, jiù bú huì wàngjì dài sǎn le.","vi":"Nếu bạn để ý dự báo thời tiết thì đã không quên mang ô."}],"related":[{"hanzi":"留心","pinyin":"liúxīn","vi":"để ý"},{"hanzi":"注意","pinyin":"zhùyì","vi":"chú ý"},{"hanzi":"关注","pinyin":"guānzhù","vi":"quan tâm"},{"hanzi":"在意","pinyin":"zàiyì","vi":"để bụng"}]},{"id":"遛","hanzi":"遛","pinyin":"liù","meaning_vi":"dắt đi dạo; đi dạo","explanation":"遛 (lựu – đi thong thả) → đi dạo chậm rãi; thường dùng là dắt chó, chim đi dạo (遛狗, 遛鸟).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🦮","examples":[{"type":"basic","zh":"他每天早上遛狗。","pinyin":"Tā měitiān zǎoshang liùgǒu.","vi":"Sáng nào anh ấy cũng dắt chó đi dạo."},{"type":"simple","zh":"公园里有不少老人提着鸟笼遛鸟。","pinyin":"Gōngyuán li yǒu bùshǎo lǎorén tízhe niǎolóng liù niǎo.","vi":"Trong công viên có không ít cụ già xách lồng chim đi dạo."},{"type":"compound","zh":"即使下着小雨，她也要带狗出去遛一圈。","pinyin":"Jíshǐ xiàzhe xiǎoyǔ, tā yě yào dài gǒu chūqù liù yìquān.","vi":"Dù trời mưa phùn, cô ấy cũng phải dắt chó ra ngoài đi một vòng."}],"related":[{"hanzi":"遛狗","pinyin":"liùgǒu","vi":"dắt chó đi dạo"},{"hanzi":"溜达","pinyin":"liūda","vi":"đi dạo"},{"hanzi":"散步","pinyin":"sànbù","vi":"tản bộ"},{"hanzi":"逛","pinyin":"guàng","vi":"dạo"}]},{"id":"柳树","hanzi":"柳树","pinyin":"liǔshù","meaning_vi":"cây liễu","explanation":"柳 (liễu) + 树 (thụ – cây) → cây liễu, cành mềm rủ xuống, thường trồng ven hồ.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"湖边有很多柳树。","pinyin":"Húbiān yǒu hěn duō liǔshù.","vi":"Ven hồ có rất nhiều cây liễu."},{"type":"simple","zh":"春风一吹，河边的柳树就发芽了。","pinyin":"Chūnfēng yì chuī, hébiān de liǔshù jiù fāyá le.","vi":"Gió xuân vừa thổi, hàng liễu bên sông đã đâm chồi."},{"type":"compound","zh":"因为柳树容易成活，所以很多城市把它种在河边。","pinyin":"Yīnwèi liǔshù róngyì chénghuó, suǒyǐ hěn duō chéngshì bǎ tā zhòng zài hébiān.","vi":"Vì cây liễu dễ sống nên nhiều thành phố trồng nó ven sông."}],"related":[{"hanzi":"杨柳","pinyin":"yángliǔ","vi":"dương liễu"},{"hanzi":"垂柳","pinyin":"chuíliǔ","vi":"liễu rủ"},{"hanzi":"柳条","pinyin":"liǔtiáo","vi":"cành liễu"},{"hanzi":"树木","pinyin":"shùmù","vi":"cây cối"}],"traditional":"柳樹"},{"id":"笼统","hanzi":"笼统","pinyin":"lǒngtǒng","meaning_vi":"chung chung, mơ hồ, thiếu cụ thể","explanation":"笼 (lung – bao trùm) + 统 (thống – gộp chung) → gộp chung lại, không phân tích cụ thể.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"你说得太笼统了。","pinyin":"Nǐ shuō de tài lǒngtǒng le.","vi":"Bạn nói chung chung quá."},{"type":"simple","zh":"这份报告写得很笼统，看不出具体问题。","pinyin":"Zhè fèn bàogào xiě de hěn lǒngtǒng, kànbùchū jùtǐ wèntí.","vi":"Bản báo cáo này viết rất chung chung, không thấy được vấn đề cụ thể."},{"type":"compound","zh":"如果计划太笼统，大家就不知道从哪里开始做。","pinyin":"Rúguǒ jìhuà tài lǒngtǒng, dàjiā jiù bù zhīdào cóng nǎlǐ kāishǐ zuò.","vi":"Nếu kế hoạch quá chung chung thì mọi người sẽ không biết bắt đầu từ đâu."}],"related":[{"hanzi":"具体","pinyin":"jùtǐ","vi":"cụ thể"},{"hanzi":"模糊","pinyin":"móhu","vi":"mơ hồ"},{"hanzi":"概括","pinyin":"gàikuò","vi":"khái quát"},{"hanzi":"含糊","pinyin":"hánhu","vi":"lấp lửng"}],"traditional":"籠統"},{"id":"笼子","hanzi":"笼子","pinyin":"lóngzi","meaning_vi":"lồng, chuồng","explanation":"笼 (lung – lồng) + 子 (hậu tố) → lồng nhốt chim, thú.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪺","examples":[{"type":"basic","zh":"鸟在笼子里唱歌。","pinyin":"Niǎo zài lóngzi li chànggē.","vi":"Con chim hót trong lồng."},{"type":"simple","zh":"他把小兔子放进了一个铁笼子里。","pinyin":"Tā bǎ xiǎo tùzi fàngjìnle yí ge tiě lóngzi li.","vi":"Anh ấy đặt chú thỏ con vào một cái lồng sắt."},{"type":"compound","zh":"因为笼子没关好，所以鹦鹉趁机飞走了。","pinyin":"Yīnwèi lóngzi méi guān hǎo, suǒyǐ yīngwǔ chènjī fēi zǒu le.","vi":"Vì lồng không đóng kỹ nên con vẹt nhân cơ hội bay mất."}],"related":[{"hanzi":"鸟笼","pinyin":"niǎolóng","vi":"lồng chim"},{"hanzi":"蒸笼","pinyin":"zhēnglóng","vi":"xửng hấp"},{"hanzi":"牢笼","pinyin":"láolóng","vi":"lồng giam"},{"hanzi":"灯笼","pinyin":"dēnglong","vi":"đèn lồng"}],"traditional":"籠子"},{"id":"聋","hanzi":"聋","pinyin":"lóng","meaning_vi":"điếc","explanation":"聋 (lung – điếc) → tai không nghe được; gồm 龙 chỉ âm và 耳 (tai) chỉ nghĩa.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🧏","examples":[{"type":"basic","zh":"他的左耳聋了。","pinyin":"Tā de zuǒ ěrlóng le.","vi":"Tai trái của ông ấy bị điếc rồi."},{"type":"simple","zh":"音乐声太大，我耳朵都快被震聋了。","pinyin":"Yīnyuè shēng tài dà, wǒ ěrduo dōu kuài bèi zhènlóng le.","vi":"Tiếng nhạc to quá, tai tôi sắp bị điếc rồi."},{"type":"compound","zh":"虽然奶奶耳朵有点儿聋，但是眼睛还很好。","pinyin":"Suīrán nǎinai ěrduo yǒudiǎnr lóng, dànshì yǎnjing hái hěn hǎo.","vi":"Tuy tai bà hơi lãng nhưng mắt vẫn còn rất tốt."}],"related":[{"hanzi":"聋人","pinyin":"lóngrén","vi":"người điếc"},{"hanzi":"耳聋","pinyin":"ěrlóng","vi":"điếc tai"},{"hanzi":"聋哑","pinyin":"lóngyǎ","vi":"câm điếc"},{"hanzi":"听力","pinyin":"tīnglì","vi":"thính lực"}],"traditional":"聾"},{"id":"聋人","hanzi":"聋人","pinyin":"lóngrén","meaning_vi":"người điếc, người khiếm thính","explanation":"聋 (lung – điếc) + 人 (nhân – người) → người bị điếc, khiếm thính.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤟","examples":[{"type":"basic","zh":"聋人用手语交流。","pinyin":"Lóngrén yòng shǒuyǔ jiāoliú.","vi":"Người điếc giao tiếp bằng ngôn ngữ ký hiệu."},{"type":"simple","zh":"这家咖啡馆的服务员都是聋人。","pinyin":"Zhè jiā kāfēiguǎn de fúwùyuán dōu shì lóngrén.","vi":"Nhân viên phục vụ của quán cà phê này đều là người khiếm thính."},{"type":"compound","zh":"虽然他是聋人，但是舞跳得比很多人都好。","pinyin":"Suīrán tā shì lóngrén, dànshì wǔ tiào de bǐ hěn duō rén dōu hǎo.","vi":"Tuy là người khiếm thính nhưng anh ấy nhảy giỏi hơn nhiều người."}],"related":[{"hanzi":"聋","pinyin":"lóng","vi":"điếc"},{"hanzi":"手语","pinyin":"shǒuyǔ","vi":"ngôn ngữ ký hiệu"},{"hanzi":"盲人","pinyin":"mángrén","vi":"người mù"},{"hanzi":"残疾人","pinyin":"cánjírén","vi":"người khuyết tật"}],"traditional":"聾人"},{"id":"芦花","hanzi":"芦花","pinyin":"lúhuā","meaning_vi":"hoa lau, bông lau","explanation":"芦 (lô – cây lau sậy) + 花 (hoa) → bông hoa trắng như bông của cây lau sậy, nở vào mùa thu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"河边开满了芦花。","pinyin":"Hébiān kāimǎnle lúhuā.","vi":"Ven sông nở đầy hoa lau."},{"type":"simple","zh":"秋风吹过，白色的芦花像雪一样飘起来。","pinyin":"Qiū fēng chuī guò, báisè de lúhuā xiàng xuě yíyàng piāo qǐlái.","vi":"Gió thu thổi qua, những bông lau trắng bay lên như tuyết."},{"type":"compound","zh":"每当秋天来临，湖边的芦花就会吸引很多摄影爱好者。","pinyin":"Měidāng qiūtiān láilín, húbiān de lúhuā jiù huì xīyǐn hěn duō shèyǐng àihàozhě.","vi":"Mỗi khi thu đến, hoa lau ven hồ lại thu hút rất nhiều người mê chụp ảnh."}],"related":[{"hanzi":"芦苇","pinyin":"lúwěi","vi":"lau sậy"},{"hanzi":"芦荡","pinyin":"lúdàng","vi":"đầm lau"},{"hanzi":"花絮","pinyin":"huāxù","vi":"bông hoa tơ"},{"hanzi":"荻花","pinyin":"díhuā","vi":"hoa lách"}],"traditional":"蘆花"},{"id":"炉子","hanzi":"炉子","pinyin":"lúzi","meaning_vi":"bếp lò, lò","explanation":"炉 (lô – lò) + 子 (hậu tố) → cái lò để đun nấu, sưởi ấm.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🔥","examples":[{"type":"basic","zh":"炉子上在烧水。","pinyin":"Lúzi shang zài shāoshuǐ.","vi":"Trên bếp lò đang đun nước."},{"type":"simple","zh":"冬天屋里生着炉子，暖和极了。","pinyin":"Dōngtiān wū li shēngzhe lúzi, nuǎnhuo jíle.","vi":"Mùa đông trong nhà đốt lò, ấm áp vô cùng."},{"type":"compound","zh":"如果晚上不把炉子灭掉，就可能会发生危险。","pinyin":"Rúguǒ wǎnshang bù bǎ lúzi mièdiào, jiù kěnéng huì fāshēng wēixiǎn.","vi":"Nếu buổi tối không tắt lò thì có thể xảy ra nguy hiểm."}],"related":[{"hanzi":"火炉","pinyin":"huǒlú","vi":"lò lửa"},{"hanzi":"煤炉","pinyin":"méilú","vi":"lò than"},{"hanzi":"烤炉","pinyin":"kǎolú","vi":"lò nướng"},{"hanzi":"锅炉","pinyin":"guōlú","vi":"nồi hơi"}],"traditional":"爐子"},{"id":"卤味","hanzi":"卤味","pinyin":"lǔwèi","meaning_vi":"đồ kho, món om ngũ vị (lỗ vị)","explanation":"卤 (lỗ – nước kho ngũ vị) + 味 (vị – món, mùi vị) → các món ninh trong nước tương và gia vị như chân gà, trứng, đậu phụ.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍗","examples":[{"type":"basic","zh":"我想买点儿卤味。","pinyin":"Wǒ xiǎng mǎi diǎnr lǔwèi.","vi":"Tôi muốn mua ít đồ kho."},{"type":"simple","zh":"这家店的卤味是用老配方做的。","pinyin":"Zhè jiā diàn de lǔwèi shì yòng lǎo pèifāng zuò de.","vi":"Món lỗ vị của tiệm này được làm theo công thức cổ truyền."},{"type":"compound","zh":"虽然卤味很好吃，但是太咸了不能多吃。","pinyin":"Suīrán lǔwèi hěn hǎochī, dànshì tài xiánle bù néng duō chī.","vi":"Tuy đồ kho rất ngon nhưng mặn quá, không ăn nhiều được."}],"related":[{"hanzi":"卤蛋","pinyin":"lǔdàn","vi":"trứng kho"},{"hanzi":"卤肉","pinyin":"lǔròu","vi":"thịt kho"},{"hanzi":"熟食","pinyin":"shúshí","vi":"đồ ăn chín"},{"hanzi":"鸭脖","pinyin":"yābó","vi":"cổ vịt"}],"traditional":"滷味"},{"id":"鲁莽","hanzi":"鲁莽","pinyin":"lǔmǎng","meaning_vi":"lỗ mãng, liều lĩnh, hấp tấp","explanation":"鲁 (lỗ – đần, thô) + 莽 (mãng – thô bạo) → thô lỗ, hấp tấp, làm việc không suy nghĩ.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🐂","examples":[{"type":"basic","zh":"你别这么鲁莽。","pinyin":"Nǐ bié zhème lǔmǎng.","vi":"Bạn đừng hấp tấp như vậy."},{"type":"simple","zh":"他因为一时鲁莽，说了伤人的话。","pinyin":"Tā yīnwèi yìshí lǔmǎng, shuōle shāngrén dehuà.","vi":"Vì nhất thời lỗ mãng, anh ấy đã nói những lời làm tổn thương người khác."},{"type":"compound","zh":"如果做决定太鲁莽，就很可能后悔一辈子。","pinyin":"Rúguǒ zuò juédìng tài lǔmǎng, jiù hěn kěnéng hòuhuǐ yíbèizi.","vi":"Nếu quyết định quá liều lĩnh thì rất có thể sẽ hối hận cả đời."}],"related":[{"hanzi":"冲动","pinyin":"chōngdòng","vi":"bốc đồng"},{"hanzi":"莽撞","pinyin":"mǎngzhuàng","vi":"lỗ mãng"},{"hanzi":"粗鲁","pinyin":"cūlǔ","vi":"thô lỗ"},{"hanzi":"谨慎","pinyin":"jǐnshèn","vi":"thận trọng"}],"traditional":"魯莽"},{"id":"录制","hanzi":"录制","pinyin":"lùzhì","meaning_vi":"ghi âm, ghi hình, thu","explanation":"录 (lục – ghi chép) + 制 (chế – chế tác) → ghi lại âm thanh, hình ảnh để làm thành sản phẩm.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎙️","examples":[{"type":"basic","zh":"我们在录制节目。","pinyin":"Wǒmen zài lùzhì jiémù.","vi":"Chúng tôi đang ghi hình chương trình."},{"type":"simple","zh":"这首歌是在一个小录音棚里录制的。","pinyin":"Zhè shǒu gē shì zài yí ge xiǎo lùyīnpéng li lùzhì de.","vi":"Bài hát này được thu âm trong một phòng thu nhỏ."},{"type":"compound","zh":"因为录制时外面太吵，所以我们只好重来一遍。","pinyin":"Yīnwèi lùzhì shí wàimiàn tài chǎo, suǒyǐ wǒmen zhǐhǎo chónglái yíbiàn.","vi":"Vì lúc thu bên ngoài ồn quá nên chúng tôi đành làm lại một lần."}],"related":[{"hanzi":"录音","pinyin":"lùyīn","vi":"ghi âm"},{"hanzi":"录像","pinyin":"lùxiàng","vi":"ghi hình"},{"hanzi":"拍摄","pinyin":"pāishè","vi":"quay phim"},{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"}],"traditional":"錄製"},{"id":"鹿","hanzi":"鹿","pinyin":"lù","meaning_vi":"con hươu, con nai","explanation":"鹿 (lộc – hươu) → loài thú ăn cỏ, con đực thường có sừng phân nhánh.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦌","examples":[{"type":"basic","zh":"草地上有一只鹿。","pinyin":"Cǎo dìshang yǒu yì zhī lù.","vi":"Trên bãi cỏ có một con hươu."},{"type":"simple","zh":"在奈良的公园里，游客可以给鹿喂饼干。","pinyin":"Zài Nàiliáng de gōngyuán li, yóukè kěyǐ gěi lù wèi bǐnggān.","vi":"Ở công viên Nara, du khách có thể cho hươu ăn bánh quy."},{"type":"compound","zh":"一听到脚步声，那只小鹿就飞快地跑进了树林。","pinyin":"Yì tīngdào jiǎobùshēng, nà zhī xiǎo lù jiù fēikuài de pǎo jìnle shùlín.","vi":"Vừa nghe tiếng bước chân, chú nai con đã chạy vụt vào rừng."}],"related":[{"hanzi":"梅花鹿","pinyin":"méihuālù","vi":"hươu sao"},{"hanzi":"长颈鹿","pinyin":"chángjǐnglù","vi":"hươu cao cổ"},{"hanzi":"鹿角","pinyin":"lùjiǎo","vi":"sừng hươu"},{"hanzi":"驯鹿","pinyin":"xùnlù","vi":"tuần lộc"}]},{"id":"路灯","hanzi":"路灯","pinyin":"lùdēng","meaning_vi":"đèn đường","explanation":"路 (lộ – đường) + 灯 (đăng – đèn) → đèn chiếu sáng dọc đường phố.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🏮","examples":[{"type":"basic","zh":"街上的路灯亮了。","pinyin":"Jiēshang de lùdēng liàng le.","vi":"Đèn đường trên phố đã sáng."},{"type":"simple","zh":"这条小巷没有路灯，晚上特别黑。","pinyin":"Zhè tiáo xiǎoxiàng méiyǒu lùdēng, wǎnshang tèbié hēi.","vi":"Con hẻm này không có đèn đường, buổi tối rất tối."},{"type":"compound","zh":"自从装了新路灯，晚上出来散步的人就多了。","pinyin":"Zìcóng zhuāngle xīn lùdēng, wǎnshang chūlái sànbù de rén jiù duō le.","vi":"Từ khi lắp đèn đường mới, người ra ngoài đi dạo buổi tối đã đông hơn."}],"related":[{"hanzi":"红绿灯","pinyin":"hónglǜdēng","vi":"đèn giao thông"},{"hanzi":"灯光","pinyin":"dēngguāng","vi":"ánh đèn"},{"hanzi":"街灯","pinyin":"jiēdēng","vi":"đèn phố"},{"hanzi":"照明","pinyin":"zhàomíng","vi":"chiếu sáng"}],"traditional":"路燈"},{"id":"路段","hanzi":"路段","pinyin":"lùduàn","meaning_vi":"đoạn đường","explanation":"路 (lộ – đường) + 段 (đoạn) → một đoạn của con đường, tuyến đường.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"这个路段经常堵车。","pinyin":"Zhè ge lùduàn jīngcháng dǔchē.","vi":"Đoạn đường này thường xuyên tắc."},{"type":"simple","zh":"前方路段正在施工，请绕道行驶。","pinyin":"Qiánfāng lùduàn zhèngzài shīgōng, qǐng ràodào xíngshǐ.","vi":"Đoạn đường phía trước đang thi công, xin đi đường vòng."},{"type":"compound","zh":"因为这个路段弯道很多，所以司机必须减速慢行。","pinyin":"Yīnwèi zhè ge lùduàn wāndào hěn duō, suǒyǐ sījī bìxū jiǎnsù mànxíng.","vi":"Vì đoạn đường này có nhiều khúc cua nên tài xế phải giảm tốc độ."}],"related":[{"hanzi":"路况","pinyin":"lùkuàng","vi":"tình trạng đường"},{"hanzi":"路线","pinyin":"lùxiàn","vi":"tuyến đường"},{"hanzi":"路口","pinyin":"lùkǒu","vi":"ngã tư"},{"hanzi":"地段","pinyin":"dìduàn","vi":"khu vực"}]},{"id":"路况","hanzi":"路况","pinyin":"lùkuàng","meaning_vi":"tình trạng giao thông, tình trạng mặt đường","explanation":"路 (lộ – đường) + 况 (huống – tình hình) → tình hình của con đường như mặt đường, lưu lượng xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"今天路况不太好。","pinyin":"Jīntiān lùkuàng bú tài hǎo.","vi":"Hôm nay tình hình giao thông không tốt lắm."},{"type":"simple","zh":"出发前最好先在手机上查一下路况。","pinyin":"Chūfā qián zuìhǎo xiān zài shǒujī shang chá yíxià lùkuàng.","vi":"Trước khi xuất phát tốt nhất nên tra tình hình giao thông trên điện thoại."},{"type":"compound","zh":"如果路况好的话，我们一个小时就能到机场。","pinyin":"Rúguǒ lùkuàng hǎo dehuà, wǒmen yí ge xiǎoshí jiù néng dào jīchǎng.","vi":"Nếu đường thông thoáng thì một tiếng là chúng ta đến sân bay."}],"related":[{"hanzi":"路段","pinyin":"lùduàn","vi":"đoạn đường"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"giao thông"},{"hanzi":"堵车","pinyin":"dǔchē","vi":"tắc đường"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"tình hình"}],"traditional":"路況"},{"id":"路面","hanzi":"路面","pinyin":"lùmiàn","meaning_vi":"mặt đường","explanation":"路 (lộ – đường) + 面 (diện – bề mặt) → bề mặt của con đường.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚧","examples":[{"type":"basic","zh":"雨后路面很滑。","pinyin":"Yǔ hòu lùmiàn hěn huá.","vi":"Sau mưa mặt đường rất trơn."},{"type":"simple","zh":"工人们正在连夜修补破损的路面。","pinyin":"Gōngrénmen zhèngzài liányè xiūbǔ pòsǔn de lùmiàn.","vi":"Công nhân đang làm suốt đêm để vá mặt đường bị hư hỏng."},{"type":"compound","zh":"因为路面结了冰，所以好几辆车都滑到了路边。","pinyin":"Yīnwèi lùmiàn jiéle bīng, suǒyǐ hǎojǐ liàng chē dōu huá dàole lùbiān.","vi":"Vì mặt đường đóng băng nên mấy chiếc xe đã trượt ra lề đường."}],"related":[{"hanzi":"地面","pinyin":"dìmiàn","vi":"mặt đất"},{"hanzi":"路况","pinyin":"lùkuàng","vi":"tình trạng đường"},{"hanzi":"马路","pinyin":"mǎlù","vi":"đường cái"},{"hanzi":"柏油路","pinyin":"bǎiyóulù","vi":"đường nhựa"}]},{"id":"路人","hanzi":"路人","pinyin":"lùrén","meaning_vi":"người qua đường, người dưng","explanation":"路 (lộ – đường) + 人 (nhân – người) → người đi ngang qua đường; nghĩa bóng là người xa lạ, không liên quan.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🚶‍♂️","examples":[{"type":"basic","zh":"一位路人帮了我。","pinyin":"Yí wèi lùrén bāngle wǒ.","vi":"Một người qua đường đã giúp tôi."},{"type":"simple","zh":"老人摔倒后，几个路人马上把他扶了起来。","pinyin":"Lǎorén shuāidǎo hòu, jǐ ge lùrén mǎshàng bǎ tā fúle qǐlái.","vi":"Sau khi cụ già ngã, mấy người qua đường lập tức đỡ cụ dậy."},{"type":"compound","zh":"虽然他们曾经是好朋友，但是现在已经形同路人。","pinyin":"Suīrán tāmen céngjīng shì hǎopéngyou, dànshì xiànzài yǐjīng xíngtóng lùrén.","vi":"Tuy họ từng là bạn thân nhưng giờ đã như người dưng."}],"related":[{"hanzi":"行人","pinyin":"xíngrén","vi":"người đi bộ"},{"hanzi":"陌生人","pinyin":"mòshēngrén","vi":"người lạ"},{"hanzi":"过客","pinyin":"guòkè","vi":"khách qua đường"},{"hanzi":"旁人","pinyin":"pángrén","vi":"người ngoài"}]},{"id":"路子","hanzi":"路子","pinyin":"lùzi","meaning_vi":"cách, con đường, đường đi nước bước; quan hệ","explanation":"路 (lộ – đường) + 子 (hậu tố) → con đường; nghĩa bóng là cách làm, hướng đi hoặc mối quan hệ để làm việc.","hsk_level":"7-9","tags":["danh-tu"],"image":"🗝️","examples":[{"type":"basic","zh":"这个路子走得通。","pinyin":"Zhè ge lùzi zǒu de tōng.","vi":"Cách này đi được đấy."},{"type":"simple","zh":"他想找个路子把产品卖到国外去。","pinyin":"Tā xiǎng zhǎo ge lùzi bǎ chǎnpǐn mài dào guówài qù.","vi":"Anh ấy muốn tìm cách đưa sản phẩm ra bán ở nước ngoài."},{"type":"compound","zh":"如果原来的路子行不通，我们就换个思路试试。","pinyin":"Rúguǒ yuánlái de lùzi xíngbùtōng, wǒmen jiù huàn ge sīlù shìshi.","vi":"Nếu cách cũ không ổn thì chúng ta đổi hướng suy nghĩ thử xem."}],"related":[{"hanzi":"门路","pinyin":"ménlù","vi":"đường đi nước bước"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách"},{"hanzi":"思路","pinyin":"sīlù","vi":"hướng suy nghĩ"},{"hanzi":"途径","pinyin":"tújìng","vi":"con đường"}]},{"id":"旅程","hanzi":"旅程","pinyin":"lǚchéng","meaning_vi":"hành trình, chuyến đi","explanation":"旅 (lữ – đi xa) + 程 (trình – chặng đường) → chặng đường của chuyến đi.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"祝你旅程愉快！","pinyin":"Zhù nǐ lǚchéng yúkuài!","vi":"Chúc bạn có chuyến đi vui vẻ!"},{"type":"simple","zh":"这次旅程让我认识了很多新朋友。","pinyin":"Zhè cì lǚchéng ràng wǒ rènshile hěn duō xīnpéngyou.","vi":"Chuyến đi lần này giúp tôi quen được nhiều bạn mới."},{"type":"compound","zh":"虽然旅程很辛苦，但是沿途的风景让人难忘。","pinyin":"Suīrán lǚchéng hěn xīnkǔ, dànshì yántú de fēngjǐng ràng rén nánwàng.","vi":"Tuy hành trình vất vả nhưng phong cảnh dọc đường khiến người ta khó quên."}],"related":[{"hanzi":"旅途","pinyin":"lǚtú","vi":"chuyến đi"},{"hanzi":"行程","pinyin":"xíngchéng","vi":"lịch trình"},{"hanzi":"旅行","pinyin":"lǚxíng","vi":"du lịch"},{"hanzi":"路程","pinyin":"lùchéng","vi":"quãng đường"}]},{"id":"旅途","hanzi":"旅途","pinyin":"lǚtú","meaning_vi":"chuyến đi, dọc đường đi","explanation":"旅 (lữ – đi xa) + 途 (đồ – đường) → con đường trong chuyến đi xa; nhấn mạnh quá trình trên đường.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🚆","examples":[{"type":"basic","zh":"旅途中要注意安全。","pinyin":"Lǚtú zhōng yào zhùyì ānquán.","vi":"Trên đường đi phải chú ý an toàn."},{"type":"simple","zh":"长途火车上，我们聊天打发旅途的时间。","pinyin":"Chángtú huǒchē shang, wǒmen liáotiān dǎfā lǚtú de shíjiān.","vi":"Trên chuyến tàu đường dài, chúng tôi trò chuyện cho qua thời gian."},{"type":"compound","zh":"因为旅途太远，所以我们在中途住了一晚。","pinyin":"Yīnwèi lǚtú tài yuǎn, suǒyǐ wǒmen zài zhōngtú zhùle yì wǎn.","vi":"Vì đường đi quá xa nên chúng tôi nghỉ lại một đêm giữa đường."}],"related":[{"hanzi":"旅程","pinyin":"lǚchéng","vi":"hành trình"},{"hanzi":"路途","pinyin":"lùtú","vi":"đường sá"},{"hanzi":"途中","pinyin":"túzhōng","vi":"giữa đường"},{"hanzi":"长途","pinyin":"chángtú","vi":"đường dài"}]},{"id":"铝","hanzi":"铝","pinyin":"lǚ","meaning_vi":"nhôm","explanation":"铝 (lữ – nhôm) → bộ 钅 (kim loại) + 吕 (chỉ âm) → kim loại nhẹ màu trắng bạc, ký hiệu Al.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🥫","examples":[{"type":"basic","zh":"这个锅是铝做的。","pinyin":"Zhè ge guō shì lǚ zuò de.","vi":"Cái nồi này làm bằng nhôm."},{"type":"simple","zh":"铝的重量轻，常用来制造飞机零件。","pinyin":"Lǚ de zhòngliàng qīng, cháng yònglái zhìzào fēijī língjiàn.","vi":"Nhôm nhẹ nên thường được dùng chế tạo linh kiện máy bay."},{"type":"compound","zh":"因为铝罐可以回收，所以请不要随便扔掉。","pinyin":"Yīnwèi lǚ guàn kěyǐ huíshōu, suǒyǐ qǐng bú yào suíbiàn rēngdiào.","vi":"Vì lon nhôm có thể tái chế nên xin đừng vứt bừa."}],"related":[{"hanzi":"铝合金","pinyin":"lǚhéjīn","vi":"hợp kim nhôm"},{"hanzi":"铁","pinyin":"tiě","vi":"sắt"},{"hanzi":"铜","pinyin":"tóng","vi":"đồng"},{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"}],"traditional":"鋁"},{"id":"屡","hanzi":"屡","pinyin":"lǚ","meaning_vi":"nhiều lần, liên tiếp","explanation":"屡 (lũ – nhiều lần) → lặp đi lặp lại nhiều lần; văn viết, hay gặp trong 屡次, 屡见不鲜.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他屡战屡败。","pinyin":"Tā lǚ zhàn lǚ bài.","vi":"Anh ta đánh trận nào thua trận nấy."},{"type":"simple","zh":"这家公司屡次被消费者投诉。","pinyin":"Zhè jiā gōngsī lǚcì bèi xiāofèizhě tóusù.","vi":"Công ty này nhiều lần bị người tiêu dùng khiếu nại."},{"type":"compound","zh":"虽然屡遭失败，但是他从来没有放弃过。","pinyin":"Suīrán lǚzāo shībài, dànshì tā cónglái méiyǒu fàngqì guo.","vi":"Tuy liên tiếp thất bại nhưng anh ấy chưa bao giờ bỏ cuộc."}],"related":[{"hanzi":"屡次","pinyin":"lǚcì","vi":"nhiều lần"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy"},{"hanzi":"多次","pinyin":"duōcì","vi":"nhiều lần"},{"hanzi":"一再","pinyin":"yízài","vi":"hết lần này đến lần khác"}],"traditional":"屢"},{"id":"缕","hanzi":"缕","pinyin":"lǚ","meaning_vi":"sợi, làn, sợi chỉ (lượng từ cho vật mảnh như tóc, khói); tỉ mỉ","explanation":"缕 (lũ – sợi tơ) → sợi chỉ; làm lượng từ cho vật mảnh dài như 一缕头发, 一缕阳光, 一缕炊烟.","hsk_level":"7-9","tags":["luong-tu"],"image":"🧵","examples":[{"type":"basic","zh":"一缕阳光照进来。","pinyin":"Yì lǚ yáng guāngzhào jìnlái.","vi":"Một tia nắng chiếu vào."},{"type":"simple","zh":"屋顶上升起了一缕淡淡的炊烟。","pinyin":"Wūdǐng shangshēng qǐle yì lǚ dàndàn de chuīyān.","vi":"Trên mái nhà bốc lên một làn khói bếp mờ nhạt."},{"type":"compound","zh":"每当微风吹过，她额前的一缕头发就轻轻飘动。","pinyin":"Měidāng wēifēng chuī guò, tā é qián de yì lǚ tóufa jiù qīngqīng piāodòng.","vi":"Mỗi khi gió nhẹ thổi qua, lọn tóc trước trán cô ấy lại khẽ bay."}],"related":[{"hanzi":"丝","pinyin":"sī","vi":"sợi tơ"},{"hanzi":"线","pinyin":"xiàn","vi":"sợi chỉ"},{"hanzi":"一丝","pinyin":"yìsī","vi":"một chút"},{"hanzi":"千丝万缕","pinyin":"qiānsīwànlǚ","vi":"chằng chịt"}],"traditional":"縷"},{"id":"率","hanzi":"率","pinyin":"lǜ","meaning_vi":"tỷ lệ, suất","explanation":"率 (suất – tỷ lệ) → tỷ lệ giữa hai đại lượng; thường làm hậu tố: 效率, 比率, 出生率 (đọc shuài khi nghĩa \"dẫn dắt\").","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"今年的出生率下降了。","pinyin":"Jīnnián de chūshēnglǜ xiàjiàng le.","vi":"Tỷ lệ sinh năm nay đã giảm."},{"type":"simple","zh":"这台新机器的工作效率提高了一倍。","pinyin":"Zhè tái xīn jīqì de gōngzuò xiàolǜ tígāole yí bèi.","vi":"Hiệu suất làm việc của chiếc máy mới này tăng gấp đôi."},{"type":"compound","zh":"如果失业率继续上升，政府就得出台新政策。","pinyin":"Rúguǒ shīyèlǜ jìxù shàngshēng, zhèngfǔ jiù děi chūtái xīn zhèngcè.","vi":"Nếu tỷ lệ thất nghiệp tiếp tục tăng, chính phủ sẽ phải ban hành chính sách mới."}],"related":[{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"},{"hanzi":"比率","pinyin":"bǐlǜ","vi":"tỷ lệ"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"频率","pinyin":"pínlǜ","vi":"tần suất"}]},{"id":"绿地","hanzi":"绿地","pinyin":"lǜdì","meaning_vi":"bãi cỏ xanh, khu cây xanh","explanation":"绿 (lục – xanh lá) + 地 (địa – đất) → khu đất trồng cỏ cây trong thành phố.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"小区里有一片绿地。","pinyin":"Xiǎoqū li yǒu yípiàn lǜdì.","vi":"Trong khu dân cư có một bãi cỏ xanh."},{"type":"simple","zh":"城市应该给市民留出更多的绿地。","pinyin":"Chéngshì yīnggāi gěi shìmín liú chū gèng duō de lǜdì.","vi":"Thành phố nên dành nhiều khu cây xanh hơn cho người dân."},{"type":"compound","zh":"虽然这里的房价很高，但是附近的绿地特别多。","pinyin":"Suīrán zhèlǐ de fángjià hěn gāo, dànshì fùjìn de lǜdì tèbié duō.","vi":"Tuy giá nhà ở đây rất cao nhưng xung quanh có rất nhiều khu cây xanh."}],"related":[{"hanzi":"草地","pinyin":"cǎodì","vi":"bãi cỏ"},{"hanzi":"绿化","pinyin":"lǜhuà","vi":"phủ xanh"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"công viên"},{"hanzi":"草坪","pinyin":"cǎopíng","vi":"thảm cỏ"}],"traditional":"綠地"},{"id":"绿灯","hanzi":"绿灯","pinyin":"lǜdēng","meaning_vi":"đèn xanh; bật đèn xanh (cho phép)","explanation":"绿 (lục – xanh) + 灯 (đăng – đèn) → đèn xanh giao thông; nghĩa bóng là sự cho phép tiến hành.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🟢","examples":[{"type":"basic","zh":"绿灯亮了，走吧。","pinyin":"Lǜdēng liàng le, zǒu ba.","vi":"Đèn xanh rồi, đi thôi."},{"type":"simple","zh":"公司已经给这个项目开了绿灯。","pinyin":"Gōngsī yǐjīng gěi zhè ge xiàngmù kāile lǜdēng.","vi":"Công ty đã bật đèn xanh cho dự án này."},{"type":"compound","zh":"即使是绿灯，过马路时也要先看看两边。","pinyin":"Jíshǐ shì lǜdēng, guòmǎlù shí yě yào xiān kànkan liǎngbiān.","vi":"Dù là đèn xanh, khi qua đường cũng phải nhìn hai bên trước."}],"related":[{"hanzi":"红灯","pinyin":"hóngdēng","vi":"đèn đỏ"},{"hanzi":"黄灯","pinyin":"huángdēng","vi":"đèn vàng"},{"hanzi":"红绿灯","pinyin":"hónglǜdēng","vi":"đèn giao thông"},{"hanzi":"放行","pinyin":"fàngxíng","vi":"cho qua"}],"traditional":"綠燈"},{"id":"孪生","hanzi":"孪生","pinyin":"luánshēng","meaning_vi":"sinh đôi","explanation":"孪 (loan – song sinh) + 生 (sinh – sinh ra) → sinh đôi cùng một lần.","hsk_level":"7-9","tags":["tinh-tu","gia-dinh"],"image":"👯","examples":[{"type":"basic","zh":"她们是孪生姐妹。","pinyin":"Tāmen shì luánshēng jiěmèi.","vi":"Họ là chị em sinh đôi."},{"type":"simple","zh":"这对孪生兄弟长得一模一样。","pinyin":"Zhè duì luánshēng xiōngdì zhǎngde yìmúyíyàng.","vi":"Cặp anh em sinh đôi này giống nhau như đúc."},{"type":"compound","zh":"虽然是孪生姐妹，但是她们的性格完全不同。","pinyin":"Suīrán shì luánshēng jiěmèi, dànshì tāmen de xìnggé wánquán bùtóng.","vi":"Tuy là chị em sinh đôi nhưng tính cách họ hoàn toàn khác nhau."}],"related":[{"hanzi":"双胞胎","pinyin":"shuāngbāotāi","vi":"cặp song sinh"},{"hanzi":"同胞","pinyin":"tóngbāo","vi":"cùng cha mẹ"},{"hanzi":"兄弟","pinyin":"xiōngdì","vi":"anh em"},{"hanzi":"姐妹","pinyin":"jiěmèi","vi":"chị em"}],"traditional":"孿生"},{"id":"卵","hanzi":"卵","pinyin":"luǎn","meaning_vi":"trứng, noãn","explanation":"卵 (noãn – trứng) → trứng của động vật, tế bào trứng.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🥚","examples":[{"type":"basic","zh":"鱼在水里产卵。","pinyin":"Yú zài shuǐ li chǎnluǎn.","vi":"Cá đẻ trứng dưới nước."},{"type":"simple","zh":"每年春天，青蛙都会在池塘里产下大量的卵。","pinyin":"Měinián chūntiān, qīngwā dōuhuì zài chítáng li chǎnxià dàliàng de luǎn.","vi":"Mỗi mùa xuân, ếch đều đẻ rất nhiều trứng trong ao."},{"type":"compound","zh":"如果水的温度太低，这些鱼卵就无法孵化。","pinyin":"Rúguǒ shuǐ de wēndù tài dī, zhèxiē yúluǎn jiù wúfǎ fūhuà.","vi":"Nếu nhiệt độ nước quá thấp thì những trứng cá này không thể nở."}],"related":[{"hanzi":"产卵","pinyin":"chǎnluǎn","vi":"đẻ trứng"},{"hanzi":"卵石","pinyin":"luǎnshí","vi":"sỏi cuội"},{"hanzi":"鸡蛋","pinyin":"jīdàn","vi":"trứng gà"},{"hanzi":"孵化","pinyin":"fūhuà","vi":"ấp nở"}]},{"id":"乱七八糟","hanzi":"乱七八糟","pinyin":"luànqī-bāzāo","meaning_vi":"lộn xộn, bừa bộn, rối tinh rối mù","explanation":"乱 (loạn – rối) + 七八 (thất bát – bảy tám, nhiều) + 糟 (tao – hỏng) → rối tung lên bảy tám kiểu; chỉ tình trạng hỗn loạn, bừa bãi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌀","examples":[{"type":"basic","zh":"房间乱七八糟的。","pinyin":"Fángjiān luànqībāzāo de.","vi":"Căn phòng bừa bộn hết cả."},{"type":"simple","zh":"他把桌上的文件弄得乱七八糟。","pinyin":"Tā bǎ zhuō shang de wénjiàn nòng de luànqībāzāo.","vi":"Anh ấy làm tài liệu trên bàn rối tung lên."},{"type":"compound","zh":"因为孩子们在家玩了一整天，所以客厅被弄得乱七八糟。","pinyin":"Yīnwèi háizimen zài jiā wánle yìzhěngtiān, suǒyǐ kètīng bèi nòng de luànqībāzāo.","vi":"Vì bọn trẻ chơi ở nhà cả ngày nên phòng khách bị bày bừa lộn xộn."}],"related":[{"hanzi":"杂乱无章","pinyin":"záluànwúzhāng","vi":"lộn xộn không trật tự"},{"hanzi":"一团糟","pinyin":"yìtuánzāo","vi":"rối như canh hẹ"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"井井有条","pinyin":"jǐngjǐngyǒutiáo","vi":"ngăn nắp"}],"traditional":"亂七八糟"},{"id":"抡","hanzi":"抡","pinyin":"lūn","meaning_vi":"vung, quăng, múa (tay, vật nặng)","explanation":"抡 (luân – vung) → vung mạnh cánh tay hoặc vật nặng theo vòng tròn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔨","examples":[{"type":"basic","zh":"他抡起了大锤。","pinyin":"Tā lūn qǐle dàchuí.","vi":"Anh ấy vung chiếc búa tạ lên."},{"type":"simple","zh":"那个人抡起拳头就朝他打了过去。","pinyin":"Nàgerén lūn qǐ quántou jiù cháo tā dǎle guòqù.","vi":"Người đó vung nắm đấm đánh về phía anh ấy."},{"type":"compound","zh":"虽然斧头很重，但是他抡起来一点儿也不费劲。","pinyin":"Suīrán fǔtou hěn zhòng, dànshì tā lūn qǐlái yìdiǎnr yě bú fèijìn.","vi":"Tuy chiếc rìu rất nặng nhưng anh ấy vung lên chẳng tốn chút sức nào."}],"related":[{"hanzi":"挥","pinyin":"huī","vi":"vẫy, vung"},{"hanzi":"甩","pinyin":"shuǎi","vi":"quăng"},{"hanzi":"摇","pinyin":"yáo","vi":"lắc"},{"hanzi":"舞","pinyin":"wǔ","vi":"múa"}],"traditional":"掄"},{"id":"轮换","hanzi":"轮换","pinyin":"lúnhuàn","meaning_vi":"luân phiên, thay phiên","explanation":"轮 (luân – bánh xe, lần lượt) + 换 (hoán – đổi) → lần lượt thay đổi cho nhau.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔃","examples":[{"type":"basic","zh":"我们轮换值班。","pinyin":"Wǒmen lúnhuàn zhíbān.","vi":"Chúng tôi thay phiên trực ca."},{"type":"simple","zh":"教练让几名替补队员轮换上场。","pinyin":"Jiàoliàn ràng jǐ míng tìbǔ duìyuán lúnhuàn shàngchǎng.","vi":"Huấn luyện viên cho vài cầu thủ dự bị luân phiên ra sân."},{"type":"compound","zh":"如果农田不轮换种植，土地就会越来越贫瘠。","pinyin":"Rúguǒ nóngtián bù lúnhuàn zhòngzhí, tǔdì jiù huì yuèláiyuè pínjí.","vi":"Nếu ruộng không luân canh thì đất sẽ ngày càng cằn cỗi."}],"related":[{"hanzi":"轮流","pinyin":"lúnliú","vi":"thay phiên"},{"hanzi":"交替","pinyin":"jiāotì","vi":"luân phiên"},{"hanzi":"替换","pinyin":"tìhuàn","vi":"thay thế"},{"hanzi":"值班","pinyin":"zhíbān","vi":"trực ca"}],"traditional":"輪換"},{"id":"罗","hanzi":"罗","pinyin":"luó","meaning_vi":"lưới bắt chim; giăng bắt, tập hợp; họ La","explanation":"罗 (la – lưới) → lưới bắt chim; nghĩa rộng là giăng lưới, thu gom, bày ra (网罗, 罗列); cũng là họ La.","hsk_level":"7-9","tags":["danh-tu"],"image":"🕸️","examples":[{"type":"basic","zh":"这家店门可罗雀。","pinyin":"Zhè jiā diàn mén kě luó què.","vi":"Cửa hàng này vắng tanh như chùa bà đanh."},{"type":"simple","zh":"这家公司网罗了大批优秀人才。","pinyin":"Zhè jiā gōngsī wǎngluóle dàpī yōuxiù réncái.","vi":"Công ty này đã chiêu mộ được rất nhiều nhân tài xuất sắc."},{"type":"compound","zh":"虽然罗老师已经退休了，但是还常来学校看学生。","pinyin":"Suīrán Luó lǎoshī yǐjīng tuìxiū le, dànshì hái cháng lái xuéxiào kàn xuésheng.","vi":"Tuy thầy La đã nghỉ hưu nhưng vẫn thường đến trường thăm học sinh."}],"related":[{"hanzi":"网罗","pinyin":"wǎngluó","vi":"chiêu mộ, thu gom"},{"hanzi":"罗列","pinyin":"luóliè","vi":"liệt kê"},{"hanzi":"包罗万象","pinyin":"bāoluówànxiàng","vi":"bao quát mọi thứ"},{"hanzi":"门可罗雀","pinyin":"ménkěluóquè","vi":"vắng tanh"}],"traditional":"羅"},{"id":"萝卜","hanzi":"萝卜","pinyin":"luóbo","meaning_vi":"củ cải","explanation":"萝 (la – dây leo) + 卜 (bặc) → củ cải, thường là củ cải trắng; 胡萝卜 là cà rốt.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🥕","examples":[{"type":"basic","zh":"我爱吃萝卜汤。","pinyin":"Wǒ ài chī luóbo tāng.","vi":"Tôi thích ăn canh củ cải."},{"type":"simple","zh":"冬天的萝卜又甜又脆，生吃也很好吃。","pinyin":"Dōngtiān de luóbo yòu tián yòu cuì, shēngchī yě hěn hǎochī.","vi":"Củ cải mùa đông vừa ngọt vừa giòn, ăn sống cũng rất ngon."},{"type":"compound","zh":"因为萝卜价格便宜，所以奶奶一次买了好几斤。","pinyin":"Yīnwèi luóbo jiàgé piányi, suǒyǐ nǎinai yí cì mǎile hǎojǐ jīn.","vi":"Vì củ cải rẻ nên bà mua một lúc mấy cân."}],"related":[{"hanzi":"胡萝卜","pinyin":"húluóbo","vi":"cà rốt"},{"hanzi":"白萝卜","pinyin":"báiluóbo","vi":"củ cải trắng"},{"hanzi":"蔬菜","pinyin":"shūcài","vi":"rau củ"},{"hanzi":"萝卜干","pinyin":"luóbogān","vi":"củ cải khô"}],"traditional":"蘿蔔"},{"id":"螺丝","hanzi":"螺丝","pinyin":"luósī","meaning_vi":"đinh vít, ốc vít","explanation":"螺 (loa – ốc xoắn) + 丝 (ti – sợi) → vật có rãnh xoắn như vỏ ốc dùng để vặn chặt.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔩","examples":[{"type":"basic","zh":"这颗螺丝松了。","pinyin":"Zhè kē luósī sōng le.","vi":"Con ốc vít này lỏng rồi."},{"type":"simple","zh":"他用螺丝刀把椅子的螺丝拧紧了。","pinyin":"Tāyòng luósīdāo bǎ yǐzi de luósī nǐngjǐn le.","vi":"Anh ấy dùng tua vít vặn chặt ốc của chiếc ghế."},{"type":"compound","zh":"如果少装一颗螺丝，整个书架就可能会倒。","pinyin":"Rúguǒ shǎo zhuāng yì kē luósī, zhěngge shūjià jiù kěnéng huì dǎo.","vi":"Nếu thiếu một con ốc thì cả giá sách có thể bị đổ."}],"related":[{"hanzi":"螺丝刀","pinyin":"luósīdāo","vi":"tua vít"},{"hanzi":"螺母","pinyin":"luómǔ","vi":"đai ốc"},{"hanzi":"钉子","pinyin":"dīngzi","vi":"cái đinh"},{"hanzi":"拧","pinyin":"nǐng","vi":"vặn"}],"traditional":"螺絲"},{"id":"裸","hanzi":"裸","pinyin":"luǒ","meaning_vi":"trần, khỏa thân, để lộ","explanation":"裸 (khỏa – trần truồng) → không mặc quần áo, không che phủ; hay gặp trong 裸露, 赤裸, 裸眼.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🫥","examples":[{"type":"basic","zh":"他裸着上身干活。","pinyin":"Tā luǒzhe shàngshēn gànhuó.","vi":"Anh ấy cởi trần làm việc."},{"type":"simple","zh":"她的裸眼视力只有零点三。","pinyin":"Tā de luǒyǎn shìlì zhǐyǒu língdiǎn sān.","vi":"Thị lực mắt thường của cô ấy chỉ có 0,3."},{"type":"compound","zh":"如果裸手去碰化学药品，就很容易受伤。","pinyin":"Rúguǒ luǒ shǒu qù pèng huàxué yàopǐn, jiù hěn róngyì shòushāng.","vi":"Nếu tay trần chạm vào hóa chất thì rất dễ bị thương."}],"related":[{"hanzi":"裸露","pinyin":"luǒlù","vi":"lộ ra"},{"hanzi":"赤裸","pinyin":"chìluǒ","vi":"trần truồng"},{"hanzi":"裸眼","pinyin":"luǒyǎn","vi":"mắt thường"},{"hanzi":"光着","pinyin":"guāngzhe","vi":"để trần"}]},{"id":"裸露","hanzi":"裸露","pinyin":"luǒlù","meaning_vi":"lộ ra, trơ trụi, phơi bày","explanation":"裸 (khỏa – trần) + 露 (lộ – lộ ra) → không có gì che phủ, để lộ ra ngoài.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏜️","examples":[{"type":"basic","zh":"电线裸露在外面。","pinyin":"Diànxiàn luǒlù zài wàimiàn.","vi":"Dây điện bị lộ ra bên ngoài."},{"type":"simple","zh":"山坡上的树被砍光了，只剩下裸露的岩石。","pinyin":"Shānpō shang de shù bèi kǎn guāng le, zhǐ shèngxià luǒlù de yánshí.","vi":"Cây trên sườn đồi bị chặt sạch, chỉ còn trơ lại đá."},{"type":"compound","zh":"如果皮肤长时间裸露在阳光下，就容易被晒伤。","pinyin":"Rúguǒ pífū cháng shíjiān luǒlù zài yángguāng xià, jiù róngyì bèi shàishāng.","vi":"Nếu da phơi dưới nắng lâu thì dễ bị cháy nắng."}],"related":[{"hanzi":"暴露","pinyin":"bàolù","vi":"bại lộ"},{"hanzi":"露出","pinyin":"lùchū","vi":"lộ ra"},{"hanzi":"外露","pinyin":"wàilù","vi":"lộ ra ngoài"},{"hanzi":"覆盖","pinyin":"fùgài","vi":"che phủ"}]},{"id":"落地","hanzi":"落地","pinyin":"luòdì","meaning_vi":"rơi xuống đất; hạ cánh; (dự án) đi vào thực tế","explanation":"落 (lạc – rơi) + 地 (địa – đất) → rơi xuống đất, chạm đất; nghĩa mới là chính sách, dự án được triển khai thực tế.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛬","examples":[{"type":"basic","zh":"飞机安全落地了。","pinyin":"Fēijī ānquán luòdì le.","vi":"Máy bay đã hạ cánh an toàn."},{"type":"simple","zh":"杯子落地的一瞬间就摔得粉碎。","pinyin":"Bēizi luòdì de yíshùnjiān jiù shuāi de fěnsuì.","vi":"Chiếc cốc vừa chạm đất đã vỡ tan tành."},{"type":"compound","zh":"只有政策真正落地，老百姓才能得到实惠。","pinyin":"Zhǐyǒu zhèngcè zhēnzhèng luòdì, lǎobǎixìng cáinéng dédào shíhuì.","vi":"Chỉ khi chính sách thực sự được triển khai, người dân mới được hưởng lợi."}],"related":[{"hanzi":"着陆","pinyin":"zhuólù","vi":"hạ cánh"},{"hanzi":"降落","pinyin":"jiàngluò","vi":"hạ xuống"},{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện"},{"hanzi":"落地窗","pinyin":"luòdìchuāng","vi":"cửa kính sát đất"}]},{"id":"落下","hanzi":"落下","pinyin":"luòxià","meaning_vi":"rơi xuống, hạ xuống","explanation":"落 (lạc – rơi) + 下 (hạ – xuống) → rơi từ trên xuống; khi đọc là là xià thì nghĩa là bỏ quên, bị tụt lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"树叶慢慢落下。","pinyin":"Shùyè mànmàn luòxià.","vi":"Lá cây từ từ rơi xuống."},{"type":"simple","zh":"太阳从西边的山后落下去了。","pinyin":"Tàiyáng cóng xībiān de shān hòu luòxià qù le.","vi":"Mặt trời đã lặn xuống sau núi phía tây."},{"type":"compound","zh":"演出一结束，舞台上的大幕就缓缓落下了。","pinyin":"Yǎnchū yì jiéshù, wǔtái shang de dà mù jiù huǎnhuǎn luòxià le.","vi":"Buổi diễn vừa kết thúc, tấm màn lớn trên sân khấu liền từ từ hạ xuống."}],"related":[{"hanzi":"落","pinyin":"luò","vi":"rơi"},{"hanzi":"掉下","pinyin":"diàoxià","vi":"rơi xuống"},{"hanzi":"降落","pinyin":"jiàngluò","vi":"hạ cánh"},{"hanzi":"升起","pinyin":"shēngqǐ","vi":"bay lên"}]},{"id":"麻","hanzi":"麻","pinyin":"má","meaning_vi":"cây gai, sợi gai; tê, tê dại; rỗ","explanation":"麻 (ma – cây gai) → cây gai lấy sợi dệt vải; cũng chỉ cảm giác tê (手麻了) hoặc vị tê của hoa tiêu.","hsk_level":"7-9","tags":["danh-tu"],"image":"🌿","examples":[{"type":"basic","zh":"我的腿坐麻了。","pinyin":"Wǒ de tuǐ zuò má le.","vi":"Tôi ngồi lâu tê cả chân."},{"type":"simple","zh":"这件衬衫是用麻做的，穿着很凉快。","pinyin":"Zhè jiàn chènshān shì yòng má zuò de, chuānzhe hěn liángkuai.","vi":"Chiếc áo sơ mi này làm bằng vải gai, mặc rất mát."},{"type":"compound","zh":"因为花椒放得太多，所以我的舌头都吃麻了。","pinyin":"Yīnwèi huājiāo fàng de tài duō, suǒyǐ wǒ de shétou dōu chī má le.","vi":"Vì cho quá nhiều hoa tiêu nên ăn xong lưỡi tôi tê cả đi."}],"related":[{"hanzi":"麻木","pinyin":"mámù","vi":"tê dại"},{"hanzi":"麻辣","pinyin":"málà","vi":"cay tê"},{"hanzi":"芝麻","pinyin":"zhīma","vi":"vừng"},{"hanzi":"麻布","pinyin":"mábù","vi":"vải gai"}]},{"id":"麻将","hanzi":"麻将","pinyin":"májiàng","meaning_vi":"mạt chược","explanation":"麻将 (ma tướng) → trò chơi bài 4 người dùng 136–144 quân bài, rất phổ biến ở Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🀄","examples":[{"type":"basic","zh":"他们在打麻将。","pinyin":"Tāmen zài dǎ májiàng.","vi":"Họ đang chơi mạt chược."},{"type":"simple","zh":"过年的时候，一家人常常围在一起打麻将。","pinyin":"Guònián de shíhou, yìjiārén chángcháng wéi zài yìqǐ dǎ májiàng.","vi":"Dịp Tết, cả nhà thường quây quần chơi mạt chược."},{"type":"compound","zh":"虽然打麻将很有意思，但是玩得太久对身体不好。","pinyin":"Suīrán dǎ májiàng hěn yǒuyìsi, dànshì wán de tài jiǔ duì shēntǐ bù hǎo.","vi":"Tuy chơi mạt chược rất vui nhưng chơi quá lâu không tốt cho sức khỏe."}],"related":[{"hanzi":"扑克","pinyin":"pūkè","vi":"bài tây"},{"hanzi":"象棋","pinyin":"xiàngqí","vi":"cờ tướng"},{"hanzi":"打牌","pinyin":"dǎpái","vi":"đánh bài"},{"hanzi":"棋牌","pinyin":"qípái","vi":"cờ bài"}],"traditional":"麻將"},{"id":"麻辣","hanzi":"麻辣","pinyin":"málà","meaning_vi":"cay tê","explanation":"麻 (ma – tê) + 辣 (lạt – cay) → vừa tê vừa cay, hương vị đặc trưng của ẩm thực Tứ Xuyên.","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🌶️","examples":[{"type":"basic","zh":"我喜欢吃麻辣火锅。","pinyin":"Wǒ xǐhuan chī málà huǒguō.","vi":"Tôi thích ăn lẩu cay tê."},{"type":"simple","zh":"这道麻辣豆腐是四川的家常菜。","pinyin":"Zhè dào málà dòufu shì Sìchuān de jiāchángcài.","vi":"Món đậu phụ cay tê này là món ăn gia đình của Tứ Xuyên."},{"type":"compound","zh":"如果你不能吃辣，就别点麻辣口味的。","pinyin":"Rúguǒ nǐ bù néng chī là, jiù bié diǎn málà kǒuwèi de.","vi":"Nếu bạn không ăn được cay thì đừng gọi vị cay tê."}],"related":[{"hanzi":"麻婆豆腐","pinyin":"mápódòufu","vi":"đậu phụ Ma Bà"},{"hanzi":"花椒","pinyin":"huājiāo","vi":"hoa tiêu"},{"hanzi":"辣椒","pinyin":"làjiāo","vi":"ớt"},{"hanzi":"火锅","pinyin":"huǒguō","vi":"lẩu"}]},{"id":"马后炮","hanzi":"马后炮","pinyin":"mǎhòupào","meaning_vi":"nói vuốt đuôi, việc đã rồi mới bàn","explanation":"马 (mã – con ngựa) + 后 (hậu – sau) + 炮 (pháo) → trong cờ tướng là pháo đặt sau mã để chiếu; nghĩa bóng chỉ hành động hay lời khuyên đến quá muộn.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"别说马后炮了。","pinyin":"Biéshuō mǎhòupào le.","vi":"Đừng nói vuốt đuôi nữa."},{"type":"simple","zh":"事情都结束了，你现在提建议就是马后炮。","pinyin":"Shìqing dōu jiéshù le, nǐ xiànzài tí jiànyì jiùshì mǎhòupào.","vi":"Chuyện đã xong rồi, giờ bạn mới góp ý là nói vuốt đuôi."},{"type":"compound","zh":"如果你早就看出问题，为什么现在才放马后炮？","pinyin":"Rúguǒ nǐ zǎojiù kànchū wèntí, wèishénme xiànzài cái fàng mǎhòupào?","vi":"Nếu bạn đã sớm nhìn ra vấn đề, sao giờ mới nói khi mọi việc đã rồi?"}],"related":[{"hanzi":"事后诸葛亮","pinyin":"shìhòu Zhūgěliàng","vi":"khôn sau việc đã rồi"},{"hanzi":"亡羊补牢","pinyin":"wángyángbǔláo","vi":"mất bò mới lo làm chuồng"},{"hanzi":"先见之明","pinyin":"xiānjiànzhīmíng","vi":"tầm nhìn xa"},{"hanzi":"放炮","pinyin":"fàngpào","vi":"bắn pháo"}],"traditional":"馬後炮"},{"id":"马力","hanzi":"马力","pinyin":"mǎlì","meaning_vi":"mã lực","explanation":"马 (mã – ngựa) + 力 (lực – sức) → sức ngựa, đơn vị công suất; khẩu ngữ \"开足马力\" nghĩa là dốc hết sức.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🏎️","examples":[{"type":"basic","zh":"这辆车马力很大。","pinyin":"Zhè liàng chē mǎlì hěn dà.","vi":"Chiếc xe này mã lực rất lớn."},{"type":"simple","zh":"这台发动机的功率达到了三百马力。","pinyin":"Zhè tái fādòngjī de gōnglǜ dádàole sān bǎi mǎlì.","vi":"Công suất của động cơ này đạt tới ba trăm mã lực."},{"type":"compound","zh":"为了按时交货，工厂开足马力日夜生产。","pinyin":"Wèile ànshí jiāohuò, gōngchǎng kāi zú mǎlì rìyè shēngchǎn.","vi":"Để giao hàng đúng hạn, nhà máy dốc hết công suất sản xuất ngày đêm."}],"related":[{"hanzi":"功率","pinyin":"gōnglǜ","vi":"công suất"},{"hanzi":"发动机","pinyin":"fādòngjī","vi":"động cơ"},{"hanzi":"动力","pinyin":"dònglì","vi":"động lực"},{"hanzi":"引擎","pinyin":"yǐnqíng","vi":"động cơ"}],"traditional":"馬力"},{"id":"马桶","hanzi":"马桶","pinyin":"mǎtǒng","meaning_vi":"bồn cầu, bô","explanation":"马 (mã) + 桶 (dũng – thùng) → cái bô thời xưa; nay chỉ bồn cầu xả nước.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🚽","examples":[{"type":"basic","zh":"厕所的马桶堵了。","pinyin":"Cèsuǒ de mǎtǒng dǔ le.","vi":"Bồn cầu trong nhà vệ sinh bị tắc rồi."},{"type":"simple","zh":"用完马桶以后记得冲水。","pinyin":"Yòngwán mǎtǒng yǐhòu jìde chōngshuǐ.","vi":"Dùng xong bồn cầu nhớ xả nước."},{"type":"compound","zh":"因为马桶一直漏水，所以我们请了师傅来修。","pinyin":"Yīnwèi mǎtǒng yìzhí lòushuǐ, suǒyǐ wǒmen qǐngle shīfu lái xiū.","vi":"Vì bồn cầu cứ rò nước nên chúng tôi đã gọi thợ đến sửa."}],"related":[{"hanzi":"厕所","pinyin":"cèsuǒ","vi":"nhà vệ sinh"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"phòng vệ sinh"},{"hanzi":"冲水","pinyin":"chōngshuǐ","vi":"xả nước"},{"hanzi":"洗手池","pinyin":"xǐshǒuchí","vi":"bồn rửa tay"}],"traditional":"馬桶"},{"id":"马戏","hanzi":"马戏","pinyin":"mǎxì","meaning_vi":"xiếc","explanation":"马 (mã – ngựa) + 戏 (hí – trò diễn) → vốn là trò diễn cưỡi ngựa; nay chỉ nghệ thuật xiếc nói chung.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎪","examples":[{"type":"basic","zh":"孩子们爱看马戏。","pinyin":"Háizimen ài kàn mǎxì.","vi":"Trẻ con thích xem xiếc."},{"type":"simple","zh":"马戏团的小丑逗得观众哈哈大笑。","pinyin":"Mǎxìtuán de xiǎochǒu dòu de guānzhòng hāhā dàxiào.","vi":"Chú hề của đoàn xiếc làm khán giả cười ha hả."},{"type":"compound","zh":"虽然马戏表演很精彩，但是很多人反对用动物表演。","pinyin":"Suīrán mǎxì biǎoyǎn hěn jīngcǎi, dànshì hěn duō rén fǎnduì yòng dòngwù biǎoyǎn.","vi":"Tuy biểu diễn xiếc rất đặc sắc nhưng nhiều người phản đối dùng động vật biểu diễn."}],"related":[{"hanzi":"马戏团","pinyin":"mǎxìtuán","vi":"đoàn xiếc"},{"hanzi":"杂技","pinyin":"zájì","vi":"tạp kỹ"},{"hanzi":"小丑","pinyin":"xiǎochǒu","vi":"chú hề"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"biểu diễn"}],"traditional":"馬戲"},{"id":"码","hanzi":"码","pinyin":"mǎ","meaning_vi":"mã, số; cỡ (giày, quần áo); xếp chồng; yard (lượng từ)","explanation":"码 (mã – con số, ký hiệu) → con số, mã; làm lượng từ chỉ cỡ hoặc đơn vị yard; làm động từ nghĩa là xếp chồng.","hsk_level":"7-9","tags":["luong-tu"],"image":"🔢","examples":[{"type":"basic","zh":"你穿多大码的鞋？","pinyin":"Nǐ chuān duō dàmǎ de xié?","vi":"Bạn đi giày cỡ bao nhiêu?"},{"type":"simple","zh":"工人把砖头整整齐齐地码在墙边。","pinyin":"Gōngrén bǎ zhuāntou zhěng zhěngqí qí de mǎ zài qiáng biān.","vi":"Công nhân xếp gạch ngay ngắn sát chân tường."},{"type":"compound","zh":"如果这件衣服小了，就去店里换个大一码的。","pinyin":"Rúguǒ zhè jiàn yīfu xiǎo le, jiù qù diàn li huàn ge dàyì mǎ de.","vi":"Nếu cái áo này chật thì ra cửa hàng đổi cỡ lớn hơn một số."}],"related":[{"hanzi":"号码","pinyin":"hàomǎ","vi":"số"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"mật khẩu"},{"hanzi":"尺码","pinyin":"chǐmǎ","vi":"kích cỡ"},{"hanzi":"二维码","pinyin":"èrwéimǎ","vi":"mã QR"}],"traditional":"碼"},{"id":"埋藏","hanzi":"埋藏","pinyin":"máicáng","meaning_vi":"chôn giấu, cất giấu, ẩn chứa","explanation":"埋 (mai – chôn) + 藏 (tàng – cất giấu) → chôn sâu dưới đất để giấu; nghĩa bóng là giấu kín trong lòng.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛏️","examples":[{"type":"basic","zh":"这里埋藏着宝藏。","pinyin":"Zhèlǐ máicángzhe bǎozàng.","vi":"Nơi đây có chôn giấu kho báu."},{"type":"simple","zh":"他把这段往事埋藏在心底很多年。","pinyin":"Tā bǎ zhè duàn wǎngshì máicáng zài xīndǐ hěn duōnián.","vi":"Anh ấy chôn giấu chuyện cũ này trong lòng suốt nhiều năm."},{"type":"compound","zh":"虽然这片沙漠很荒凉，但是地下埋藏着丰富的石油。","pinyin":"Suīrán zhè piàn shāmò hěn huāngliáng, dànshì dìxià máicángzhe fēngfù de shíyóu.","vi":"Tuy vùng sa mạc này rất hoang vắng nhưng dưới lòng đất có trữ lượng dầu mỏ phong phú."}],"related":[{"hanzi":"埋","pinyin":"mái","vi":"chôn"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"蕴藏","pinyin":"yùncáng","vi":"tiềm tàng"},{"hanzi":"宝藏","pinyin":"bǎozàng","vi":"kho báu"}]},{"id":"买不起","hanzi":"买不起","pinyin":"mǎibuqǐ","meaning_vi":"không đủ tiền mua, mua không nổi","explanation":"买 (mãi – mua) + 不起 (không nổi) → không đủ khả năng tài chính để mua.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"💸","examples":[{"type":"basic","zh":"这辆车我买不起。","pinyin":"Zhè liàng chē wǒ mǎibuqǐ.","vi":"Chiếc xe này tôi mua không nổi."},{"type":"simple","zh":"市中心的房子太贵了，年轻人根本买不起。","pinyin":"Shìzhōngxīn de fángzi tài guì le, niánqīngrén gēnběn mǎibuqǐ.","vi":"Nhà ở trung tâm thành phố đắt quá, người trẻ hoàn toàn không mua nổi."},{"type":"compound","zh":"因为当时工资很低，所以他连一台电脑都买不起。","pinyin":"Yīnwèi dāngshí gōngzī hěn dī, suǒyǐ tā lián yì tái diànnǎo dōu mǎibuqǐ.","vi":"Vì lúc đó lương rất thấp nên anh ấy đến một chiếc máy tính cũng không mua nổi."}],"related":[{"hanzi":"买得起","pinyin":"mǎideqǐ","vi":"mua nổi"},{"hanzi":"用不起","pinyin":"yòngbuqǐ","vi":"dùng không nổi"},{"hanzi":"昂贵","pinyin":"ángguì","vi":"đắt đỏ"},{"hanzi":"付不起","pinyin":"fùbuqǐ","vi":"trả không nổi"}],"traditional":"買不起"},{"id":"卖弄","hanzi":"卖弄","pinyin":"màinong","meaning_vi":"khoe khoang, phô trương, ra vẻ","explanation":"卖 (mại – bán, đem ra) + 弄 (lộng – bày trò) → cố ý đem tài năng, hiểu biết của mình ra khoe; mang nghĩa chê.","hsk_level":"7-9","tags":["dong-tu"],"image":"🦚","examples":[{"type":"basic","zh":"他总爱卖弄学问。","pinyin":"Tā zǒng ài màinong xuéwen.","vi":"Anh ta luôn thích khoe khoang kiến thức."},{"type":"simple","zh":"她在客人面前卖弄自己会说几句法语。","pinyin":"Tā zài kèrén miànqián màinong zìjǐ huì shuō jǐ jù Fǎyǔ.","vi":"Cô ấy khoe trước mặt khách rằng mình biết nói vài câu tiếng Pháp."},{"type":"compound","zh":"即使你真的很有本事，也不要到处卖弄。","pinyin":"Jíshǐ nǐ zhēn de hěn yǒuběnshi, yě bú yào dàochù màinong.","vi":"Cho dù bạn thật sự giỏi giang thì cũng đừng đi khắp nơi khoe khoang."}],"related":[{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"显摆","pinyin":"xiǎnbai","vi":"khoe mẽ"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"卖关子","pinyin":"màiguānzi","vi":"úp mở, làm bí ẩn"}],"traditional":"賣弄"},{"id":"蛮","hanzi":"蛮","pinyin":"mán","meaning_vi":"khá, rất (khẩu ngữ); man rợ, ngang ngược","explanation":"蛮 (man – rợ, ngang ngược); trong khẩu ngữ miền Nam Trung Quốc dùng như phó từ \"khá, rất\", tương đương 挺.","hsk_level":"7-9","tags":["pho-tu"],"image":"👌","examples":[{"type":"basic","zh":"这件衣服蛮好看的。","pinyin":"Zhè jiàn yīfu mán hǎokàn de.","vi":"Bộ quần áo này khá đẹp đấy."},{"type":"simple","zh":"我觉得这家小店的菜味道蛮不错。","pinyin":"Wǒ juéde zhè jiā xiǎodiàn de cài wèidào mán búcuò.","vi":"Tôi thấy món ăn của quán nhỏ này vị khá ngon."},{"type":"compound","zh":"虽然路有点远，但是一路上的风景蛮漂亮的。","pinyin":"Suīrán lù yǒudiǎn yuǎn, dànshì yílùshang de fēngjǐng mán piàoliang de.","vi":"Tuy đường hơi xa nhưng phong cảnh dọc đường khá đẹp."}],"related":[{"hanzi":"挺","pinyin":"tǐng","vi":"khá, rất"},{"hanzi":"野蛮","pinyin":"yěmán","vi":"dã man"},{"hanzi":"蛮横","pinyin":"mánhèng","vi":"ngang ngược"},{"hanzi":"相当","pinyin":"xiāngdāng","vi":"tương đối"}],"traditional":"蠻"},{"id":"瞒","hanzi":"瞒","pinyin":"mán","meaning_vi":"giấu, giấu giếm, che giấu","explanation":"瞒 (man – che mắt, lừa) → giấu sự thật không cho người khác biết.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤫","examples":[{"type":"basic","zh":"你别瞒着我了。","pinyin":"Nǐ bié mánzhe wǒ le.","vi":"Bạn đừng giấu tôi nữa."},{"type":"simple","zh":"他生病的事一直瞒着家里人。","pinyin":"Tā shēngbìng de shì yìzhí mánzhe jiā lǐrén.","vi":"Chuyện anh ấy bị bệnh vẫn luôn giấu người nhà."},{"type":"compound","zh":"如果你早点告诉我，而不是瞒着我，我就不会这么生气了。","pinyin":"Rúguǒ nǐ zǎodiǎn gàosu wǒ, ér bú shì mánzhe wǒ, wǒ jiù bú huì zhème shēngqì le.","vi":"Nếu bạn nói sớm với tôi thay vì giấu tôi thì tôi đã không giận như vậy."}],"related":[{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"che giấu"},{"hanzi":"欺瞒","pinyin":"qīmán","vi":"lừa dối"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thẳng thắn"},{"hanzi":"瞒天过海","pinyin":"mántiānguòhǎi","vi":"che trời qua biển"}],"traditional":"瞞"},{"id":"慢慢来","hanzi":"慢慢来","pinyin":"mànmànlái","meaning_vi":"cứ từ từ, đừng vội","explanation":"慢慢 (mạn mạn – chầm chậm) + 来 (lai – làm) → cứ từ từ mà làm, không cần vội; câu nói khích lệ, trấn an.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🐢","examples":[{"type":"basic","zh":"别着急，慢慢来。","pinyin":"Biézháojí, mànmànlái.","vi":"Đừng sốt ruột, cứ từ từ."},{"type":"simple","zh":"学汉语不能急，我们一步一步慢慢来。","pinyin":"Xué Hànyǔ bù néng jí, wǒmen yí bù yi bù mànmànlái.","vi":"Học tiếng Trung không thể vội, chúng ta cứ từng bước từ từ."},{"type":"compound","zh":"虽然你现在还做得不好，但是慢慢来，总会进步的。","pinyin":"Suīrán nǐ xiànzài hái zuò de bù hǎo, dànshì mànmànlái, zǒng huì jìnbù de.","vi":"Tuy bây giờ bạn làm chưa tốt nhưng cứ từ từ, rồi sẽ tiến bộ thôi."}],"related":[{"hanzi":"别着急","pinyin":"biézháojí","vi":"đừng vội"},{"hanzi":"不急","pinyin":"bùjí","vi":"không vội"},{"hanzi":"慢慢","pinyin":"mànmàn","vi":"từ từ"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiệm tiến"}],"traditional":"慢慢來"},{"id":"漫","hanzi":"漫","pinyin":"màn","meaning_vi":"tràn, ngập; khắp, tràn lan; tùy ý","explanation":"漫 (mạn – nước tràn lan) → nước tràn ra ngập khắp; mở rộng chỉ sự tràn khắp, không bị gò bó.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"河水漫过了堤岸。","pinyin":"Héshuǐ mànguò le dī'àn.","vi":"Nước sông đã tràn qua bờ đê."},{"type":"simple","zh":"大雨下了一夜，雨水漫进了一楼的商店。","pinyin":"Dàyǔ xiàle yí yè, yǔshuǐ màn jìnle yī lóu de shāngdiàn.","vi":"Mưa lớn suốt một đêm, nước mưa tràn vào các cửa hàng ở tầng một."},{"type":"compound","zh":"一旦水位继续上涨，河水就会漫到村子里来。","pinyin":"Yídàn shuǐwèi jìxù shàngzhǎng, héshuǐ jiù huì màn dào cūnzi lǐ lái.","vi":"Một khi mực nước tiếp tục dâng, nước sông sẽ tràn vào trong làng."}],"related":[{"hanzi":"漫长","pinyin":"màncháng","vi":"dài đằng đẵng"},{"hanzi":"弥漫","pinyin":"mímàn","vi":"tràn ngập"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"lãng mạn"},{"hanzi":"漫山遍野","pinyin":"mànshānbiànyě","vi":"khắp núi khắp đồng"}]},{"id":"漫游","hanzi":"漫游","pinyin":"mànyóu","meaning_vi":"đi dạo chơi khắp nơi, chu du; chuyển vùng (di động)","explanation":"漫 (mạn – tùy ý, tràn khắp) + 游 (du – đi chơi) → đi chơi khắp nơi không định trước; trong viễn thông là chuyển vùng.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🗺️","examples":[{"type":"basic","zh":"我想去欧洲漫游。","pinyin":"Wǒ xiǎng qù Ōuzhōu mànyóu.","vi":"Tôi muốn đi chu du châu Âu."},{"type":"simple","zh":"出国前记得开通手机的国际漫游服务。","pinyin":"Chūguó qián jìde kāitōng shǒujī de Guójì mànyóu fúwù.","vi":"Trước khi ra nước ngoài nhớ đăng ký dịch vụ chuyển vùng quốc tế cho điện thoại."},{"type":"compound","zh":"他辞职以后背着包漫游了半个中国，因为他想看看外面的世界。","pinyin":"Tā cízhí yǐhòu bēizhe bāo mànyóule bàn gè Zhōngguó, yīnwèi tā xiǎng kànkan wàimiàn de shìjiè.","vi":"Sau khi nghỉ việc, anh ấy đeo ba lô đi khắp nửa Trung Quốc vì muốn ngắm nhìn thế giới bên ngoài."}],"related":[{"hanzi":"游览","pinyin":"yóulǎn","vi":"du ngoạn"},{"hanzi":"周游","pinyin":"zhōuyóu","vi":"chu du"},{"hanzi":"旅行","pinyin":"lǚxíng","vi":"du lịch"},{"hanzi":"漫步","pinyin":"mànbù","vi":"dạo bước"}],"traditional":"漫遊"},{"id":"忙活","hanzi":"忙活","pinyin":"mánghuo","meaning_vi":"bận rộn, tất bật làm việc","explanation":"忙 (mang – bận) + 活 (hoạt – việc làm) → bận bịu làm việc liên tục; dùng nhiều trong khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🏃","examples":[{"type":"basic","zh":"妈妈在厨房忙活。","pinyin":"Māma zài chúfáng mánghuo.","vi":"Mẹ đang tất bật trong bếp."},{"type":"simple","zh":"为了准备婚礼，全家人忙活了一个多月。","pinyin":"Wèile zhǔnbèi hūnlǐ, quán jiārén mánghuole yí gè duō yuè.","vi":"Để chuẩn bị đám cưới, cả nhà đã bận rộn hơn một tháng."},{"type":"compound","zh":"虽然忙活了一整天，但是大家一点儿也不觉得累。","pinyin":"Suīrán mánghuole yìzhěngtiān, dànshì dàjiā yìdiǎnr yě bù juéde lèi.","vi":"Tuy bận rộn suốt cả ngày nhưng mọi người chẳng thấy mệt chút nào."}],"related":[{"hanzi":"忙碌","pinyin":"mánglù","vi":"bận rộn"},{"hanzi":"干活","pinyin":"gànhuó","vi":"làm việc"},{"hanzi":"瞎忙","pinyin":"xiāmáng","vi":"bận vô ích"},{"hanzi":"清闲","pinyin":"qīngxián","vi":"nhàn rỗi"}]},{"id":"忙乱","hanzi":"忙乱","pinyin":"mángluàn","meaning_vi":"bận rộn rối tung, luống cuống","explanation":"忙 (mang – bận) + 乱 (loạn – rối) → bận đến mức rối loạn, không có trật tự.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😵","examples":[{"type":"basic","zh":"早上总是很忙乱。","pinyin":"Zǎoshang zǒngshì hěn mángluàn.","vi":"Buổi sáng lúc nào cũng tất bật rối tung."},{"type":"simple","zh":"搬家那天，屋里一片忙乱，东西到处都是。","pinyin":"Bānjiā nà tiān, wū lǐ yípiàn mángluàn, dōngxi dàochù dōu shì.","vi":"Hôm chuyển nhà, trong phòng bề bộn rối ren, đồ đạc vứt khắp nơi."},{"type":"compound","zh":"如果提前做好计划，就不会在考试前这么忙乱了。","pinyin":"Rúguǒ tíqián zuò hǎo jìhuà, jiù bú huì zài kǎoshì qián zhème mángluàn le.","vi":"Nếu lên kế hoạch trước thì sẽ không luống cuống như thế trước kỳ thi."}],"related":[{"hanzi":"忙碌","pinyin":"mánglù","vi":"bận rộn"},{"hanzi":"慌乱","pinyin":"huāngluàn","vi":"hoảng loạn"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"从容","pinyin":"cóngróng","vi":"thong thả"}],"traditional":"忙亂"},{"id":"矛头","hanzi":"矛头","pinyin":"máotóu","meaning_vi":"mũi giáo; mũi nhọn (của sự công kích, phê phán)","explanation":"矛 (mâu – cây giáo) + 头 (đầu – đầu mũi) → mũi giáo; nghĩa bóng chỉ hướng nhắm tới của sự công kích, phê bình.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"矛头指向了经理。","pinyin":"Máotóu zhǐxiàngle jīnglǐ.","vi":"Mũi nhọn chỉ trích nhắm vào giám đốc."},{"type":"simple","zh":"这篇文章的矛头直指食品安全问题。","pinyin":"Zhè piān wénzhāng de máotóu zhí zhǐ shípǐn ānquán wèntí.","vi":"Mũi nhọn của bài viết này nhắm thẳng vào vấn đề an toàn thực phẩm."},{"type":"compound","zh":"出了事故以后，大家都把矛头对准了司机，但是真正的原因是刹车坏了。","pinyin":"Chūleshì gù yǐhòu, dàjiā dōu bǎ máotóu duìzhǔnle sījī, dànshì zhēnzhèng de yuányīn shì shāchē huàile.","vi":"Sau tai nạn, mọi người đều chĩa mũi nhọn vào tài xế, nhưng nguyên nhân thật sự là phanh bị hỏng."}],"related":[{"hanzi":"矛","pinyin":"máo","vi":"giáo"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"针对","pinyin":"zhēnduì","vi":"nhắm vào"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"}],"traditional":"矛頭"},{"id":"茅台","hanzi":"茅台","pinyin":"máotái","meaning_vi":"Mao Đài (thị trấn ở Quý Châu); rượu Mao Đài","explanation":"茅台 (Mao Đài) → tên một thị trấn ở tỉnh Quý Châu, nổi tiếng với loại rượu trắng cùng tên; thường gọi tắt rượu Mao Đài.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🍶","examples":[{"type":"basic","zh":"这瓶茅台很贵。","pinyin":"Zhè píng máotái hěn guì.","vi":"Chai Mao Đài này rất đắt."},{"type":"simple","zh":"爷爷过生日，爸爸特意买了一瓶茅台。","pinyin":"Yéye guòshēngrì, bàba tèyì mǎile yì píng máotái.","vi":"Sinh nhật ông nội, bố đặc biệt mua một chai Mao Đài."},{"type":"compound","zh":"虽然茅台的名气很大，但是我还是觉得它的味道太冲了。","pinyin":"Suīrán máotái de míngqì hěn dà, dànshì wǒ háishì juéde tā de wèidào tài chòng le.","vi":"Tuy Mao Đài rất nổi tiếng nhưng tôi vẫn thấy vị của nó quá nồng."}],"related":[{"hanzi":"茅台酒","pinyin":"máotáijiǔ","vi":"rượu Mao Đài"},{"hanzi":"白酒","pinyin":"báijiǔ","vi":"rượu trắng"},{"hanzi":"贵州","pinyin":"Guìzhōu","vi":"Quý Châu"},{"hanzi":"名酒","pinyin":"míngjiǔ","vi":"rượu nổi tiếng"}],"traditional":"茅臺"},{"id":"茅台酒","hanzi":"茅台酒","pinyin":"máotáijiǔ","meaning_vi":"rượu Mao Đài","explanation":"茅台 (Mao Đài – địa danh ở Quý Châu) + 酒 (tửu – rượu) → loại rượu trắng nổi tiếng nhất Trung Quốc, thường dùng trong quốc yến.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🍶","examples":[{"type":"basic","zh":"他送了我两瓶茅台酒。","pinyin":"Tā sòngle wǒ liǎng píng máotáijiǔ.","vi":"Anh ấy tặng tôi hai chai rượu Mao Đài."},{"type":"simple","zh":"茅台酒常常出现在重要的国宴上。","pinyin":"Máotáijiǔ chángcháng chū xiànzài zhòngyào de guóyàn shang.","vi":"Rượu Mao Đài thường xuất hiện trong các bữa quốc yến quan trọng."},{"type":"compound","zh":"因为茅台酒越放越香，所以很多人喜欢买来收藏。","pinyin":"Yīnwèi máotáijiǔ yuè fàng yuè xiāng, suǒyǐ hěn duō rén xǐhuan mǎi lái shōucáng.","vi":"Vì rượu Mao Đài càng để lâu càng thơm nên nhiều người thích mua về sưu tầm."}],"related":[{"hanzi":"茅台","pinyin":"máotái","vi":"Mao Đài"},{"hanzi":"白酒","pinyin":"báijiǔ","vi":"rượu trắng"},{"hanzi":"啤酒","pinyin":"píjiǔ","vi":"bia"},{"hanzi":"葡萄酒","pinyin":"pútaojiǔ","vi":"rượu vang"}],"traditional":"茅臺酒"},{"id":"冒昧","hanzi":"冒昧","pinyin":"màomèi","meaning_vi":"mạo muội, đường đột, xin phép mạn phép","explanation":"冒 (mạo – liều, xông lên) + 昧 (muội – không rõ) → không biết phép tắc mà liều làm; thường dùng khiêm tốn khi xin phép.","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"恕我冒昧问一句。","pinyin":"Shù wǒ màomèi wèn yíjù.","vi":"Thứ lỗi cho tôi mạo muội hỏi một câu."},{"type":"simple","zh":"我冒昧地给您写这封信，希望得到您的帮助。","pinyin":"Wǒ màomèi de gěi nín xiě zhè fēng xìn, xīwàng dédào nín de bāngzhù.","vi":"Tôi mạo muội viết lá thư này cho ngài, mong nhận được sự giúp đỡ của ngài."},{"type":"compound","zh":"虽然这样问有点冒昧，但是我真的很想知道您的看法。","pinyin":"Suīrán zhèyàng wèn yǒudiǎn màomèi, dànshì wǒ zhēn de hěn xiǎng zhīdào nín de kànfǎ.","vi":"Tuy hỏi như vậy hơi đường đột nhưng tôi thật sự rất muốn biết ý kiến của ngài."}],"related":[{"hanzi":"冒犯","pinyin":"màofàn","vi":"mạo phạm"},{"hanzi":"唐突","pinyin":"tángtū","vi":"đường đột"},{"hanzi":"失礼","pinyin":"shīlǐ","vi":"thất lễ"},{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"làm phiền"}]},{"id":"没劲","hanzi":"没劲","pinyin":"méijìn","meaning_vi":"chán, vô vị; không có sức, uể oải","explanation":"没 (một – không có) + 劲 (kình – sức lực, hứng thú) → không có sức; thường dùng nghĩa \"chán, vô vị\".","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😑","examples":[{"type":"basic","zh":"这部电影真没劲。","pinyin":"Zhè bù diànyǐng zhēn méijìn.","vi":"Bộ phim này chán thật."},{"type":"simple","zh":"发烧以后我浑身没劲，什么都不想做。","pinyin":"Fāshāo yǐhòu wǒ húnshēn méijìn, shénme dōu bù xiǎng zuò.","vi":"Sau khi bị sốt, tôi cả người uể oải, chẳng muốn làm gì."},{"type":"compound","zh":"如果每天都重复一样的工作，就会觉得生活很没劲。","pinyin":"Rúguǒ měitiān dōu chóngfù yíyàng de gōngzuò, jiù huì juéde shēnghuó hěn méijìn.","vi":"Nếu ngày nào cũng lặp lại cùng một công việc thì sẽ thấy cuộc sống rất nhàm chán."}],"related":[{"hanzi":"没意思","pinyin":"méiyìsi","vi":"chán"},{"hanzi":"无聊","pinyin":"wúliáo","vi":"vô vị"},{"hanzi":"有劲","pinyin":"yǒujìn","vi":"hăng hái, thú vị"},{"hanzi":"乏力","pinyin":"fálì","vi":"mệt mỏi"}],"traditional":"沒勁"},{"id":"没落","hanzi":"没落","pinyin":"mòluò","meaning_vi":"suy tàn, sa sút, lụi tàn","explanation":"没 (một – chìm) + 落 (lạc – rơi) → chìm xuống, rơi rụng; chỉ sự suy tàn của gia tộc, giai cấp, ngành nghề.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏚️","examples":[{"type":"basic","zh":"这个家族渐渐没落了。","pinyin":"Zhè ge jiāzú jiànjiàn mòluò le.","vi":"Gia tộc này dần dần suy tàn."},{"type":"simple","zh":"随着网络的发展，很多传统行业开始没落。","pinyin":"Suízhe wǎngluò de fāzhǎn, hěn duō chuántǒng hángyè kāishǐ mòluò.","vi":"Cùng với sự phát triển của Internet, nhiều ngành nghề truyền thống bắt đầu lụi tàn."},{"type":"compound","zh":"虽然这座古镇已经没落，但是每年还是有不少游客来参观。","pinyin":"Suīrán zhè zuò gǔzhèn yǐjīng mòluò, dànshì měinián háishì yǒu bùshǎo yóukè lái cānguān.","vi":"Tuy thị trấn cổ này đã suy tàn nhưng mỗi năm vẫn có không ít du khách đến tham quan."}],"related":[{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy sụp"},{"hanzi":"衰败","pinyin":"shuāibài","vi":"suy bại"},{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"thịnh vượng"},{"hanzi":"没落贵族","pinyin":"mòluòguìzú","vi":"quý tộc sa sút"}],"traditional":"沒落"},{"id":"没说的","hanzi":"没说的","pinyin":"méishuōde","meaning_vi":"khỏi phải nói, không chê vào đâu được; chuyện đương nhiên","explanation":"没 (không) + 说的 (điều để nói) → chẳng có gì để bàn: hoặc là tốt đến mức không chê được, hoặc là việc đương nhiên phải làm.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"他的人品没说的。","pinyin":"Tā de rénpǐn méishuōde.","vi":"Nhân phẩm của anh ấy khỏi phải bàn."},{"type":"simple","zh":"咱们是老朋友了，帮这点儿忙没说的。","pinyin":"Zánmen shì lǎopéngyou le, bāng zhè diǎnr máng méishuōde.","vi":"Chúng ta là bạn cũ rồi, giúp chút việc này là chuyện đương nhiên."},{"type":"compound","zh":"这家饭店虽然价格有点贵，但是菜的味道真是没说的。","pinyin":"Zhè jiā fàndiàn suīrán jiàgé yǒudiǎn guì, dànshì cài de wèidào zhēn shì méishuōde.","vi":"Nhà hàng này tuy giá hơi đắt nhưng hương vị món ăn thật không chê vào đâu được."}],"related":[{"hanzi":"没问题","pinyin":"méiwèntí","vi":"không vấn đề"},{"hanzi":"不用说","pinyin":"búyòngshuō","vi":"khỏi nói"},{"hanzi":"无可挑剔","pinyin":"wúkětiāoti","vi":"không thể chê"},{"hanzi":"好说","pinyin":"hǎoshuō","vi":"dễ thôi"}],"traditional":"沒說的"},{"id":"没意思","hanzi":"没意思","pinyin":"méiyìsi","meaning_vi":"chán, vô vị, không thú vị","explanation":"没 (không có) + 意思 (ý tứ – thú vị, ý nghĩa) → không có gì thú vị, nhàm chán.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🥱","examples":[{"type":"basic","zh":"这个游戏太没意思了。","pinyin":"Zhè ge yóuxì tài méiyìsi le.","vi":"Trò chơi này chán quá."},{"type":"simple","zh":"一个人过周末真没意思，我们出去走走吧。","pinyin":"Yígèrénguò zhōumò zhēn méiyìsi, wǒmen chūqù zǒu zou ba.","vi":"Một mình qua cuối tuần thật chán, chúng ta ra ngoài đi dạo đi."},{"type":"compound","zh":"虽然这本书很有名，但是我读了几页就觉得没意思。","pinyin":"Suīrán zhè běn shū hěn yǒumíng, dànshì wǒ dúle jǐ yè jiù juéde méiyìsi.","vi":"Tuy cuốn sách này rất nổi tiếng nhưng tôi đọc vài trang đã thấy chán."}],"related":[{"hanzi":"有意思","pinyin":"yǒuyìsi","vi":"thú vị"},{"hanzi":"无聊","pinyin":"wúliáo","vi":"nhàm chán"},{"hanzi":"没劲","pinyin":"méijìn","vi":"chán"},{"hanzi":"乏味","pinyin":"fáwèi","vi":"tẻ nhạt"}],"traditional":"沒意思"},{"id":"没辙","hanzi":"没辙","pinyin":"méizhé","meaning_vi":"hết cách, bó tay, chịu thua","explanation":"没 (không có) + 辙 (triệt – vết bánh xe, lối đi) → không có lối đi, hết cách xoay xở; khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤷","examples":[{"type":"basic","zh":"这事我也没辙了。","pinyin":"Zhè shì wǒ yě méizhé le.","vi":"Việc này tôi cũng bó tay rồi."},{"type":"simple","zh":"孩子一哭，爸爸就完全没辙了。","pinyin":"Háizi yì kū, bàba jiù wánquán méizhé le.","vi":"Đứa bé vừa khóc là bố hoàn toàn hết cách."},{"type":"compound","zh":"如果连医生都没辙，我们就只能换一家医院试试了。","pinyin":"Rúguǒ lián yīshēng dōu méizhé, wǒmen jiù zhǐnéng huàn yìjiā yīyuàn shìshi le.","vi":"Nếu ngay cả bác sĩ cũng bó tay thì chúng ta chỉ có thể đổi sang bệnh viện khác thử xem."}],"related":[{"hanzi":"没办法","pinyin":"méibànfǎ","vi":"không có cách"},{"hanzi":"无计可施","pinyin":"wújìkěshī","vi":"hết kế"},{"hanzi":"有辙","pinyin":"yǒuzhé","vi":"có cách"},{"hanzi":"束手无策","pinyin":"shùshǒuwúcè","vi":"bó tay"}],"traditional":"沒轍"},{"id":"没准儿","hanzi":"没准儿","pinyin":"méizhǔnr","meaning_vi":"có lẽ, không chừng, chưa chắc","explanation":"没 (không) + 准儿 (chuẩn – chắc chắn) → không chắc chắn; dùng như \"không chừng, có khi\".","hsk_level":"7-9","tags":["pho-tu"],"image":"🤔","examples":[{"type":"basic","zh":"他没准儿已经走了。","pinyin":"Tā méizhǔnr yǐjīng zǒu le.","vi":"Không chừng anh ấy đi rồi."},{"type":"simple","zh":"你去问问老王，他没准儿知道答案。","pinyin":"Nǐ qù wèn wen lǎo Wáng, tā méizhǔnr zhīdào dá'àn.","vi":"Bạn đi hỏi lão Vương xem, có khi anh ấy biết đáp án."},{"type":"compound","zh":"天这么阴，没准儿下午就会下雨，所以你最好带把伞。","pinyin":"Tiān zhème yīn, méizhǔnr xiàwǔ jiù huì xiàyǔ, suǒyǐ nǐ zuìhǎo dài bǎ sǎn.","vi":"Trời âm u thế này, không chừng chiều sẽ mưa, nên tốt nhất bạn mang theo ô."}],"related":[{"hanzi":"也许","pinyin":"yěxǔ","vi":"có lẽ"},{"hanzi":"说不定","pinyin":"shuōbudìng","vi":"không chừng"},{"hanzi":"可能","pinyin":"kěnéng","vi":"có thể"},{"hanzi":"一定","pinyin":"yídìng","vi":"nhất định"}],"traditional":"沒準兒"},{"id":"玫瑰","hanzi":"玫瑰","pinyin":"méigui","meaning_vi":"hoa hồng","explanation":"玫瑰 (mai khôi) → hoa hồng, biểu tượng của tình yêu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌹","examples":[{"type":"basic","zh":"他送我一束玫瑰。","pinyin":"Tā sòng wǒ yí shù méigui.","vi":"Anh ấy tặng tôi một bó hoa hồng."},{"type":"simple","zh":"情人节那天，花店里的玫瑰特别贵。","pinyin":"Qíngrénjié nà tiān, huādiàn lǐ de méigui tèbié guì.","vi":"Ngày lễ tình nhân, hoa hồng trong tiệm hoa đặc biệt đắt."},{"type":"compound","zh":"玫瑰虽然很漂亮，但是茎上有刺，摘的时候要小心。","pinyin":"Méigui suīrán hěn piàoliang, dànshì jīng shang yǒu cì, zhāi de shíhou yào xiǎoxīn.","vi":"Hoa hồng tuy rất đẹp nhưng thân có gai, khi hái phải cẩn thận."}],"related":[{"hanzi":"玫瑰花","pinyin":"méiguihuā","vi":"hoa hồng"},{"hanzi":"月季","pinyin":"yuèjì","vi":"hồng nguyệt quế"},{"hanzi":"花束","pinyin":"huāshù","vi":"bó hoa"},{"hanzi":"百合","pinyin":"bǎihé","vi":"hoa bách hợp"}]},{"id":"眉开眼笑","hanzi":"眉开眼笑","pinyin":"méikāi-yǎnxiào","meaning_vi":"mặt mày hớn hở, cười tít mắt","explanation":"Nghĩa đen: lông mày giãn ra, đôi mắt cười → nghĩa bóng: vui mừng hớn hở, mặt mày rạng rỡ.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😄","examples":[{"type":"basic","zh":"他听了眉开眼笑。","pinyin":"Tā tīngle méikāiyǎnxiào.","vi":"Anh ấy nghe xong cười tít mắt."},{"type":"simple","zh":"奶奶收到孙子的礼物，高兴得眉开眼笑。","pinyin":"Nǎinai shōudào sūnzi de lǐwù, gāoxìng de méikāiyǎnxiào.","vi":"Bà nhận được quà của cháu, vui đến mức mặt mày hớn hở."},{"type":"compound","zh":"一听说明天放假，孩子们就眉开眼笑，因为可以去公园玩了。","pinyin":"Yì tīngshuō míngtiān fàngjià, háizimen jiù méikāiyǎnxiào, yīnwèi kěyǐ qù gōngyuán wán le.","vi":"Vừa nghe nói mai được nghỉ, bọn trẻ liền cười tít mắt vì có thể đi công viên chơi."}],"related":[{"hanzi":"喜笑颜开","pinyin":"xǐxiàoyánkāi","vi":"mặt mày rạng rỡ"},{"hanzi":"笑逐颜开","pinyin":"xiàozhúyánkāi","vi":"tươi cười hớn hở"},{"hanzi":"愁眉苦脸","pinyin":"chóuméikǔliǎn","vi":"mặt ủ mày chau"},{"hanzi":"开心","pinyin":"kāixīn","vi":"vui vẻ"}],"traditional":"眉開眼笑"},{"id":"煤矿","hanzi":"煤矿","pinyin":"méikuàng","meaning_vi":"mỏ than","explanation":"煤 (môi – than đá) + 矿 (khoáng – mỏ) → mỏ than đá.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"⛏️","examples":[{"type":"basic","zh":"他在煤矿工作。","pinyin":"Tā zài méikuàng gōngzuò.","vi":"Anh ấy làm việc ở mỏ than."},{"type":"simple","zh":"这座小城是靠附近的煤矿发展起来的。","pinyin":"Zhè zuò xiǎochéng shì kào fùjìn de méikuàng fāzhǎn qǐlái de.","vi":"Thành phố nhỏ này phát triển nhờ mỏ than ở gần đó."},{"type":"compound","zh":"因为煤矿下面的工作很危险，所以安全措施一定要做好。","pinyin":"Yīnwèi méikuàng xiàmiàn de gōngzuò hěn wēixiǎn, suǒyǐ ānquán cuòshī yídìngyào zuò hǎo.","vi":"Vì công việc dưới mỏ than rất nguy hiểm nên biện pháp an toàn nhất định phải làm tốt."}],"related":[{"hanzi":"煤炭","pinyin":"méitàn","vi":"than đá"},{"hanzi":"矿工","pinyin":"kuànggōng","vi":"thợ mỏ"},{"hanzi":"矿山","pinyin":"kuàngshān","vi":"khu mỏ"},{"hanzi":"煤气","pinyin":"méiqì","vi":"khí gas"}],"traditional":"煤礦"},{"id":"每当","hanzi":"每当","pinyin":"měidāng","meaning_vi":"mỗi khi, mỗi lần, hễ","explanation":"每 (mỗi) + 当 (đương – vào lúc) → mỗi khi đến lúc…; thường đi với 时/的时候 và 总/都.","hsk_level":"7-9","tags":["gioi-tu","thoi-gian"],"image":"🔁","examples":[{"type":"basic","zh":"每当下雨，我就想家。","pinyin":"Měidāng xiàyǔ, wǒ jiù xiǎngjiā.","vi":"Mỗi khi trời mưa, tôi lại nhớ nhà."},{"type":"simple","zh":"每当听到这首歌，我都会想起大学时光。","pinyin":"Měidāng tīngdào zhè shǒu gē, wǒ dōuhuì xiǎngqǐ dàxué shíguāng.","vi":"Mỗi khi nghe bài hát này, tôi đều nhớ lại thời đại học."},{"type":"compound","zh":"每当我遇到困难的时候，他总是第一个站出来帮我。","pinyin":"Měidāng wǒ yùdào kùnnan de shíhou, tā zǒngshì dìyī gè zhàn chūlái bāng wǒ.","vi":"Mỗi khi tôi gặp khó khăn, anh ấy luôn là người đầu tiên đứng ra giúp tôi."}],"related":[{"hanzi":"每逢","pinyin":"měiféng","vi":"mỗi dịp"},{"hanzi":"每次","pinyin":"měicì","vi":"mỗi lần"},{"hanzi":"每当…时","pinyin":"měidāng shí","vi":"mỗi khi"},{"hanzi":"一…就","pinyin":"yī jiù","vi":"hễ…là"}],"traditional":"每當"},{"id":"每逢","hanzi":"每逢","pinyin":"měiféng","meaning_vi":"mỗi khi, mỗi dịp, cứ đến","explanation":"每 (mỗi) + 逢 (phùng – gặp) → mỗi lần gặp dịp; thường đi với ngày lễ, ngày tháng.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"每逢周末，他都去钓鱼。","pinyin":"Měiféng zhōumò, tā dōu qù diàoyú.","vi":"Cứ đến cuối tuần, anh ấy đều đi câu cá."},{"type":"simple","zh":"每逢春节，火车站里都挤满了回家的人。","pinyin":"Měiféng Chūnjié, huǒchēzhàn lǐ dōu jǐmǎnle huíjiā de rén.","vi":"Mỗi dịp Tết, nhà ga đều chật kín người về quê."},{"type":"compound","zh":"每逢佳节倍思亲，所以中秋节我一定要给父母打个电话。","pinyin":"Měiféng jiājié bèi sīqīn, suǒyǐ Zhōngqiūjié wǒ yídìngyào gěi fùmǔ dǎ ge diànhuà.","vi":"Mỗi dịp lễ lại càng nhớ người thân, nên Trung thu tôi nhất định phải gọi điện cho bố mẹ."}],"related":[{"hanzi":"每当","pinyin":"měidāng","vi":"mỗi khi"},{"hanzi":"相逢","pinyin":"xiāngféng","vi":"gặp gỡ"},{"hanzi":"逢年过节","pinyin":"féngniánguòjié","vi":"dịp lễ Tết"},{"hanzi":"每次","pinyin":"měicì","vi":"mỗi lần"}]},{"id":"美景","hanzi":"美景","pinyin":"měijǐng","meaning_vi":"cảnh đẹp","explanation":"美 (mỹ – đẹp) + 景 (cảnh – phong cảnh) → phong cảnh đẹp.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🏞️","examples":[{"type":"basic","zh":"山顶的美景让人难忘。","pinyin":"Shāndǐng de měijǐng ràng rén nánwàng.","vi":"Cảnh đẹp trên đỉnh núi khiến người ta khó quên."},{"type":"simple","zh":"我们一边喝咖啡，一边欣赏窗外的美景。","pinyin":"Wǒmen yìbiān hē kāfēi, yìbiān xīnshǎng chuāng wài de měijǐng.","vi":"Chúng tôi vừa uống cà phê vừa ngắm cảnh đẹp ngoài cửa sổ."},{"type":"compound","zh":"虽然爬山很累，但是看到山上的美景，大家都觉得值了。","pinyin":"Suīrán páshān hěn lèi, dànshì kàndào shān shang de měijǐng, dàjiā dōu juéde zhí le.","vi":"Tuy leo núi rất mệt nhưng nhìn thấy cảnh đẹp trên núi, mọi người đều thấy đáng."}],"related":[{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"},{"hanzi":"景色","pinyin":"jǐngsè","vi":"cảnh sắc"},{"hanzi":"风光","pinyin":"fēngguāng","vi":"phong quang"},{"hanzi":"良辰美景","pinyin":"liángchénměijǐng","vi":"cảnh đẹp giờ lành"}]},{"id":"美人","hanzi":"美人","pinyin":"měirén","meaning_vi":"người đẹp, mỹ nhân","explanation":"美 (mỹ – đẹp) + 人 (nhân – người) → người đẹp, thường chỉ phụ nữ đẹp.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💃","examples":[{"type":"basic","zh":"她是有名的美人。","pinyin":"Tā shì yǒumíng de měirén.","vi":"Cô ấy là một mỹ nhân nổi tiếng."},{"type":"simple","zh":"这幅画里的美人穿着一件红色的长裙。","pinyin":"Zhè fú huà lǐ de měirén chuānzhe yí jiàn hóngsè de chángqún.","vi":"Người đẹp trong bức tranh này mặc một chiếc váy dài màu đỏ."},{"type":"compound","zh":"虽然她从小就是个美人，但是她更希望别人欣赏她的才华。","pinyin":"Suīrán tā cóngxiǎo jiùshì gè měirén, dànshì tā gèng xīwàng biérén xīnshǎng tā de cáihuá.","vi":"Tuy từ nhỏ cô ấy đã là một người đẹp nhưng cô càng mong người khác trân trọng tài năng của mình."}],"related":[{"hanzi":"美女","pinyin":"měinǚ","vi":"mỹ nữ"},{"hanzi":"佳人","pinyin":"jiārén","vi":"giai nhân"},{"hanzi":"美貌","pinyin":"měimào","vi":"nhan sắc"},{"hanzi":"帅哥","pinyin":"shuàigē","vi":"trai đẹp"}]},{"id":"美味","hanzi":"美味","pinyin":"měiwèi","meaning_vi":"món ngon, mỹ vị; ngon","explanation":"美 (mỹ – đẹp, ngon) + 味 (vị – mùi vị) → mùi vị ngon; chỉ món ăn ngon.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"😋","examples":[{"type":"basic","zh":"这道菜真是美味。","pinyin":"Zhè dào cài zhēn shì měiwèi.","vi":"Món này thật là ngon."},{"type":"simple","zh":"海边的小饭馆有各种新鲜美味的海鲜。","pinyin":"Hǎibiān de xiǎofànguǎn yǒu gèzhǒng xīnxiān měiwèi de hǎixiān.","vi":"Quán ăn nhỏ bên biển có đủ loại hải sản tươi ngon."},{"type":"compound","zh":"即使是最普通的食材，在他手里也能变成美味。","pinyin":"Jíshǐ shì zuì pǔtōng de shícái, zài tā shǒulǐ yě néng biànchéng měiwèi.","vi":"Cho dù là nguyên liệu bình thường nhất, qua tay anh ấy cũng có thể thành món ngon."}],"related":[{"hanzi":"可口","pinyin":"kěkǒu","vi":"ngon miệng"},{"hanzi":"佳肴","pinyin":"jiāyáo","vi":"món ngon"},{"hanzi":"好吃","pinyin":"hǎochī","vi":"ngon"},{"hanzi":"山珍海味","pinyin":"shānzhēnhǎiwèi","vi":"sơn hào hải vị"}]},{"id":"美滋滋","hanzi":"美滋滋","pinyin":"měizīzī","meaning_vi":"vui sướng, khoái chí, sung sướng","explanation":"美 (mỹ – vui thích) + 滋滋 (lặp âm tăng sắc thái) → trong lòng vui sướng, khoái chí.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😊","examples":[{"type":"basic","zh":"他心里美滋滋的。","pinyin":"Tā xīnlǐ měizīzī de.","vi":"Trong lòng anh ấy sướng rơn."},{"type":"simple","zh":"拿到第一个月的工资，她心里美滋滋的。","pinyin":"Nádào dìyī gèyuè de gōngzī, tā xīnlǐ měizīzī de.","vi":"Nhận được tháng lương đầu tiên, trong lòng cô ấy vui sướng lắm."},{"type":"compound","zh":"因为老师当着全班的面表扬了他，所以他一整天都美滋滋的。","pinyin":"Yīnwèi lǎoshī dāngzhe quánbān de miàn biǎoyángle tā, suǒyǐ tā yìzhěngtiān dōu měizīzī de.","vi":"Vì cô giáo khen cậu ấy trước cả lớp nên cả ngày cậu ấy đều khoái chí."}],"related":[{"hanzi":"乐滋滋","pinyin":"lèzīzī","vi":"vui sướng"},{"hanzi":"喜滋滋","pinyin":"xǐzīzī","vi":"vui mừng"},{"hanzi":"得意","pinyin":"déyì","vi":"đắc ý"},{"hanzi":"开心","pinyin":"kāixīn","vi":"vui vẻ"}]},{"id":"门铃","hanzi":"门铃","pinyin":"ménlíng","meaning_vi":"chuông cửa","explanation":"门 (môn – cửa) + 铃 (linh – chuông) → chuông gắn ở cửa.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🔔","examples":[{"type":"basic","zh":"外面的门铃响了。","pinyin":"Wàimiàn de ménlíng xiǎng le.","vi":"Chuông cửa bên ngoài reo rồi."},{"type":"simple","zh":"我按了好几次门铃，可是没有人开门。","pinyin":"Wǒ ànle hǎojǐ cì ménlíng, kěshì méiyǒu rén kāimén.","vi":"Tôi bấm chuông cửa mấy lần nhưng không có ai mở."},{"type":"compound","zh":"如果门铃坏了，客人来了就只能敲门了。","pinyin":"Rúguǒ ménlíng huàile, kèrén láile jiù zhǐnéng qiāomén le.","vi":"Nếu chuông cửa hỏng thì khách đến chỉ có thể gõ cửa."}],"related":[{"hanzi":"铃声","pinyin":"língshēng","vi":"tiếng chuông"},{"hanzi":"敲门","pinyin":"qiāomén","vi":"gõ cửa"},{"hanzi":"门口","pinyin":"ménkǒu","vi":"cửa ra vào"},{"hanzi":"对讲机","pinyin":"duìjiǎngjī","vi":"bộ đàm, chuông hình"}],"traditional":"門鈴"},{"id":"门路","hanzi":"门路","pinyin":"ménlu","meaning_vi":"cách, đường đi nước bước; quan hệ, cửa sau","explanation":"门 (môn – cửa) + 路 (lộ – đường) → cửa và đường; chỉ cách thức làm việc hoặc mối quan hệ để nhờ vả.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚪","examples":[{"type":"basic","zh":"他门路很广。","pinyin":"Tā ménlu hěn guǎng.","vi":"Anh ta có nhiều mối quan hệ."},{"type":"simple","zh":"为了给孩子找个好学校，他到处找门路。","pinyin":"Wèile gěi háizi zhǎo gè hǎo xuéxiào, tā dàochù zhǎoménlu.","vi":"Để tìm trường tốt cho con, anh ta đi khắp nơi tìm đường nhờ vả."},{"type":"compound","zh":"虽然他刚来这个城市，但是很快就摸到了做生意的门路。","pinyin":"Suīrán tā gāng lái zhè ge chéngshì, dànshì hěn kuài jiù mō dàole zuòshēngyi de ménlu.","vi":"Tuy mới đến thành phố này nhưng anh ấy nhanh chóng nắm được cách làm ăn."}],"related":[{"hanzi":"路子","pinyin":"lùzi","vi":"cách, đường"},{"hanzi":"关系","pinyin":"guānxi","vi":"quan hệ"},{"hanzi":"门道","pinyin":"méndao","vi":"bí quyết"},{"hanzi":"途径","pinyin":"tújìng","vi":"con đường"}],"traditional":"門路"},{"id":"闷","hanzi":"闷","pinyin":"mēn","meaning_vi":"ngột ngạt, bí; ủ kín; im lặng không nói","explanation":"闷 (muộn – bí bách) đọc mēn: không khí không thông, ngột ngạt; cũng là đậy kín, ủ; (đọc mèn: buồn chán).","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"😮‍💨","examples":[{"type":"basic","zh":"屋里太闷了。","pinyin":"Wū lǐ tài mēn le.","vi":"Trong phòng ngột ngạt quá."},{"type":"simple","zh":"快下雨了，天气闷得让人喘不过气。","pinyin":"Kuài xiàyǔ le, tiānqì mēn de ràng rén chuǎnbuguò qì.","vi":"Sắp mưa rồi, thời tiết oi bức khiến người ta thở không nổi."},{"type":"compound","zh":"如果房间里一直不开窗，就会让人觉得很闷。","pinyin":"Rúguǒ fángjiān lǐ yìzhí bù kāi chuāng, jiù huì ràng rén juéde hěn mēn.","vi":"Nếu phòng cứ đóng kín cửa sổ thì sẽ khiến người ta thấy rất ngột ngạt."}],"related":[{"hanzi":"闷热","pinyin":"mēnrè","vi":"oi bức"},{"hanzi":"沉闷","pinyin":"chénmèn","vi":"nặng nề"},{"hanzi":"烦闷","pinyin":"fánmèn","vi":"buồn bực"},{"hanzi":"闷声","pinyin":"mēnshēng","vi":"im lặng"}],"traditional":"悶"},{"id":"盟友","hanzi":"盟友","pinyin":"méngyǒu","meaning_vi":"đồng minh","explanation":"盟 (minh – liên minh, thề ước) + 友 (hữu – bạn) → bạn đồng minh cùng liên kết.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"两国是多年盟友。","pinyin":"Liǎng guóshì duōnián méngyǒu.","vi":"Hai nước là đồng minh lâu năm."},{"type":"simple","zh":"在这次选举中，他失去了很多重要的盟友。","pinyin":"Zài zhè cì xuǎnjǔ zhōng, tā shīqùle hěn duō zhòngyào de méngyǒu.","vi":"Trong cuộc bầu cử lần này, ông ấy đã mất nhiều đồng minh quan trọng."},{"type":"compound","zh":"虽然两家公司过去是竞争对手，但是现在成了盟友。","pinyin":"Suīrán liǎng jiā gōngsī guòqù shì jìngzhēng duìshǒu, dànshì xiànzài chéngle méngyǒu.","vi":"Tuy hai công ty trước đây là đối thủ cạnh tranh nhưng giờ đã thành đồng minh."}],"related":[{"hanzi":"联盟","pinyin":"liánméng","vi":"liên minh"},{"hanzi":"同盟","pinyin":"tóngméng","vi":"đồng minh"},{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"đối tác"},{"hanzi":"对手","pinyin":"duìshǒu","vi":"đối thủ"}]},{"id":"朦胧","hanzi":"朦胧","pinyin":"ménglóng","meaning_vi":"mờ ảo, mông lung, lờ mờ","explanation":"朦胧 (mông lung) → ánh trăng mờ mờ; chỉ cảnh vật hay cảm giác không rõ ràng.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌫️","examples":[{"type":"basic","zh":"月色很朦胧。","pinyin":"Yuèsè hěn ménglóng.","vi":"Ánh trăng rất mờ ảo."},{"type":"simple","zh":"清晨的湖面上笼罩着一层朦胧的雾气。","pinyin":"Qīngchén de húmiàn shang lǒngzhàozhe yīcéng ménglóng de wùqì.","vi":"Buổi sáng sớm, mặt hồ bao phủ một lớp sương mờ ảo."},{"type":"compound","zh":"虽然那时候年纪还小，但是我心里已经有了一种朦胧的感觉。","pinyin":"Suīrán nàshíhou niánjì hái xiǎo, dànshì wǒ xīnlǐ yǐjīng yǒule yì zhǒng ménglóng de gǎnjué.","vi":"Tuy lúc ấy còn nhỏ tuổi nhưng trong lòng tôi đã có một cảm giác mơ hồ."}],"related":[{"hanzi":"模糊","pinyin":"móhu","vi":"mơ hồ"},{"hanzi":"朦朦胧胧","pinyin":"méngménglónglóng","vi":"mờ mờ ảo ảo"},{"hanzi":"清晰","pinyin":"qīngxī","vi":"rõ nét"},{"hanzi":"隐约","pinyin":"yǐnyuē","vi":"thấp thoáng"}],"traditional":"朦朧"},{"id":"猛然","hanzi":"猛然","pinyin":"měngrán","meaning_vi":"đột nhiên, bỗng nhiên, bất thình lình","explanation":"猛 (mãnh – mạnh, đột ngột) + 然 (nhiên – hậu tố) → xảy ra đột ngột và mạnh mẽ.","hsk_level":"7-9","tags":["pho-tu"],"image":"⚡","examples":[{"type":"basic","zh":"他猛然站了起来。","pinyin":"Tā měngrán zhànle qǐlái.","vi":"Anh ấy đột nhiên đứng bật dậy."},{"type":"simple","zh":"走到半路，我猛然想起钥匙忘在家里了。","pinyin":"Zǒu dào bànlù, wǒ měngrán xiǎngqǐ yàoshi wàng zài jiālǐ le.","vi":"Đi được nửa đường, tôi bỗng nhớ ra chìa khóa để quên ở nhà."},{"type":"compound","zh":"司机猛然踩下刹车，所以车上的乘客都往前冲了一下。","pinyin":"Sījī měngrán cǎi xià shāchē, suǒyǐ chē shang de chéngkè dōu wǎng qián chōngle yíxià.","vi":"Tài xế đột ngột đạp phanh nên hành khách trên xe đều chúi người về phía trước."}],"related":[{"hanzi":"突然","pinyin":"tūrán","vi":"đột nhiên"},{"hanzi":"忽然","pinyin":"hūrán","vi":"bỗng nhiên"},{"hanzi":"猛地","pinyin":"měngde","vi":"bất thình lình"},{"hanzi":"骤然","pinyin":"zhòurán","vi":"đột ngột"}]},{"id":"梦幻","hanzi":"梦幻","pinyin":"mènghuàn","meaning_vi":"mộng ảo, ảo mộng, huyền ảo như mơ","explanation":"梦 (mộng – giấc mơ) + 幻 (huyễn – ảo) → cảnh tượng như trong mơ, không có thật.","hsk_level":"7-9","tags":["danh-tu"],"image":"🦄","examples":[{"type":"basic","zh":"这里美得像梦幻。","pinyin":"Zhèlǐ měi de xiàng mènghuàn.","vi":"Nơi này đẹp như mộng ảo."},{"type":"simple","zh":"夜晚的城堡亮起灯光，看起来充满了梦幻色彩。","pinyin":"Yèwǎn de chéngbǎo liàng qǐ dēngguāng, kànqǐlái chōngmǎnle mènghuàn sècǎi.","vi":"Lâu đài ban đêm lên đèn, trông tràn đầy sắc màu huyền ảo."},{"type":"compound","zh":"虽然那段经历像梦幻一样美好，但是我们终究要回到现实。","pinyin":"Suīrán nà duàn jīnglì xiàng mènghuàn yíyàng měihǎo, dànshì wǒmen zhōngjiū yào huídào xiànshí.","vi":"Tuy trải nghiệm ấy đẹp như mơ nhưng rốt cuộc chúng ta vẫn phải trở về hiện thực."}],"related":[{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"ước mơ"},{"hanzi":"幻想","pinyin":"huànxiǎng","vi":"ảo tưởng"},{"hanzi":"虚幻","pinyin":"xūhuàn","vi":"hư ảo"},{"hanzi":"现实","pinyin":"xiànshí","vi":"hiện thực"}],"traditional":"夢幻"},{"id":"迷惑不解","hanzi":"迷惑不解","pinyin":"míhuò-bùjiě","meaning_vi":"hoang mang khó hiểu, không sao hiểu nổi","explanation":"迷惑 (mê hoặc – mơ hồ, rối trí) + 不解 (bất giải – không hiểu) → rối trí, không sao hiểu được.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"😕","examples":[{"type":"basic","zh":"大家都迷惑不解。","pinyin":"Dàjiā dōu míhuòbùjiě.","vi":"Mọi người đều hoang mang khó hiểu."},{"type":"simple","zh":"他突然辞职，让同事们迷惑不解。","pinyin":"Tā tūrán cízhí, ràng tóngshìmen míhuòbùjiě.","vi":"Anh ấy đột nhiên nghỉ việc khiến đồng nghiệp đều không sao hiểu nổi."},{"type":"compound","zh":"虽然老师解释了好几遍，但是有些学生还是迷惑不解。","pinyin":"Suīrán lǎoshī jiěshìle hǎojǐ biàn, dànshì yǒuxiē xuésheng háishì míhuòbùjiě.","vi":"Tuy thầy đã giải thích mấy lần nhưng một số học sinh vẫn hoang mang khó hiểu."}],"related":[{"hanzi":"困惑","pinyin":"kùnhuò","vi":"bối rối"},{"hanzi":"百思不解","pinyin":"bǎisībùjiě","vi":"nghĩ mãi không ra"},{"hanzi":"疑惑","pinyin":"yíhuò","vi":"nghi hoặc"},{"hanzi":"恍然大悟","pinyin":"huǎngrándàwù","vi":"bừng tỉnh hiểu ra"}]},{"id":"谜","hanzi":"谜","pinyin":"mí","meaning_vi":"câu đố; điều bí ẩn","explanation":"谜 (mê – câu đố) → câu đố; mở rộng chỉ sự việc bí ẩn chưa ai giải thích được.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"❓","examples":[{"type":"basic","zh":"这是一个千古之谜。","pinyin":"Zhè shì yí gè qiāngǔ zhī mí.","vi":"Đây là một bí ẩn nghìn đời."},{"type":"simple","zh":"金字塔是怎么建成的，至今还是个谜。","pinyin":"Jīnzìtǎ shì zěnme jiànchéng de, zhìjīn háishì gè mí.","vi":"Kim tự tháp được xây dựng thế nào đến nay vẫn là một bí ẩn."},{"type":"compound","zh":"虽然警察调查了很久，但是他失踪的原因仍然是个谜。","pinyin":"Suīrán jǐngchá diàochále hěn jiǔ, dànshì tā shīzōng de yuányīn réngrán shì gè mí.","vi":"Tuy cảnh sát đã điều tra rất lâu nhưng nguyên nhân anh ta mất tích vẫn là một bí ẩn."}],"related":[{"hanzi":"谜语","pinyin":"míyǔ","vi":"câu đố"},{"hanzi":"谜底","pinyin":"mídǐ","vi":"lời giải đố"},{"hanzi":"猜谜","pinyin":"cāimí","vi":"đoán đố"},{"hanzi":"谜团","pinyin":"mítuán","vi":"mớ bí ẩn"}],"traditional":"謎"},{"id":"谜语","hanzi":"谜语","pinyin":"míyǔ","meaning_vi":"câu đố","explanation":"谜 (mê – đố) + 语 (ngữ – lời) → lời đố, câu đố để người khác đoán.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🧩","examples":[{"type":"basic","zh":"我们来猜谜语吧。","pinyin":"Wǒmen lái cāi míyǔ ba.","vi":"Chúng ta chơi đoán câu đố đi."},{"type":"simple","zh":"元宵节的时候，灯笼上常常挂着谜语。","pinyin":"Yuánxiāojié de shíhou, dēnglong shang chángcháng guàzhe míyǔ.","vi":"Vào Tết Nguyên Tiêu, trên đèn lồng thường treo các câu đố."},{"type":"compound","zh":"这个谜语虽然看起来很简单，但是很多大人都猜不出来。","pinyin":"Zhè ge míyǔ suīrán kànqǐlái hěn jiǎndān, dànshì hěn duō dàrén dōu cāi bu chūlái.","vi":"Câu đố này tuy trông rất đơn giản nhưng nhiều người lớn đều đoán không ra."}],"related":[{"hanzi":"谜","pinyin":"mí","vi":"câu đố"},{"hanzi":"谜底","pinyin":"mídǐ","vi":"lời giải"},{"hanzi":"猜谜","pinyin":"cāimí","vi":"đoán đố"},{"hanzi":"灯谜","pinyin":"dēngmí","vi":"câu đố đèn lồng"}],"traditional":"謎語"},{"id":"秘方","hanzi":"秘方","pinyin":"mìfāng","meaning_vi":"bài thuốc bí truyền, công thức bí mật","explanation":"秘 (bí – bí mật) + 方 (phương – phương thuốc, công thức) → phương thuốc hay công thức được giữ kín.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"📜","examples":[{"type":"basic","zh":"这是祖传秘方。","pinyin":"Zhè shì zǔchuán mìfāng.","vi":"Đây là bài thuốc bí truyền của tổ tiên."},{"type":"simple","zh":"这家店的红烧肉用的是老板的秘方。","pinyin":"Zhè jiā diàn de hóngshāoròu yòng de shì lǎobǎn de mìfāng.","vi":"Món thịt kho của quán này dùng công thức bí mật của ông chủ."},{"type":"compound","zh":"虽然他说有治头疼的秘方，但是我还是更相信医生。","pinyin":"Suīrán tā shuō yǒu zhì tóuténg de mìfāng, dànshì wǒ háishì gèng xiāngxìn yīshēng.","vi":"Tuy anh ta nói có bài thuốc bí truyền chữa đau đầu nhưng tôi vẫn tin bác sĩ hơn."}],"related":[{"hanzi":"秘诀","pinyin":"mìjué","vi":"bí quyết"},{"hanzi":"偏方","pinyin":"piānfāng","vi":"bài thuốc dân gian"},{"hanzi":"配方","pinyin":"pèifāng","vi":"công thức"},{"hanzi":"药方","pinyin":"yàofāng","vi":"đơn thuốc"}]},{"id":"秘诀","hanzi":"秘诀","pinyin":"mìjué","meaning_vi":"bí quyết","explanation":"秘 (bí – bí mật) + 诀 (quyết – phương pháp then chốt) → phương pháp then chốt ít người biết để thành công.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔑","examples":[{"type":"basic","zh":"成功没有秘诀。","pinyin":"Chénggōng méiyǒu mìjué.","vi":"Thành công không có bí quyết nào cả."},{"type":"simple","zh":"奶奶长寿的秘诀就是每天早睡早起。","pinyin":"Nǎinai chángshòu de mìjué jiùshì měitiān zǎo shuì zǎoqǐ.","vi":"Bí quyết sống lâu của bà là ngày nào cũng ngủ sớm dậy sớm."},{"type":"compound","zh":"如果你想知道学好外语的秘诀，那就是每天坚持练习。","pinyin":"Rúguǒ nǐ xiǎng zhīdào xuéhǎo wàiyǔ de mìjué, nà jiùshì měitiān jiānchí liànxí.","vi":"Nếu bạn muốn biết bí quyết học giỏi ngoại ngữ thì đó là kiên trì luyện tập mỗi ngày."}],"related":[{"hanzi":"诀窍","pinyin":"juéqiào","vi":"mẹo, bí quyết"},{"hanzi":"窍门","pinyin":"qiàomén","vi":"mẹo"},{"hanzi":"秘方","pinyin":"mìfāng","vi":"công thức bí mật"},{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"}],"traditional":"秘訣"},{"id":"密不可分","hanzi":"密不可分","pinyin":"mìbù-kěfēn","meaning_vi":"gắn bó mật thiết, không thể tách rời","explanation":"密 (mật – khít, gần) + 不可分 (bất khả phân – không thể tách) → gắn chặt với nhau, không thể tách rời.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔗","examples":[{"type":"basic","zh":"两者密不可分。","pinyin":"Liǎngzhě mìbùkěfēn.","vi":"Hai thứ gắn bó không thể tách rời."},{"type":"simple","zh":"健康和饮食习惯是密不可分的。","pinyin":"Jiànkāng hé yǐnshí xíguàn shì mìbùkěfēn de.","vi":"Sức khỏe và thói quen ăn uống gắn bó mật thiết với nhau."},{"type":"compound","zh":"因为语言和文化密不可分，所以学外语也要了解当地文化。","pinyin":"Yīnwèi yǔyán hé wénhuà mìbùkěfēn, suǒyǐ xué wàiyǔ yě yào liǎojiě dāngdì wénhuà.","vi":"Vì ngôn ngữ và văn hóa không thể tách rời nên học ngoại ngữ cũng cần hiểu văn hóa bản địa."}],"related":[{"hanzi":"息息相关","pinyin":"xīxīxiāngguān","vi":"liên quan mật thiết"},{"hanzi":"紧密","pinyin":"jǐnmì","vi":"chặt chẽ"},{"hanzi":"密切","pinyin":"mìqiè","vi":"mật thiết"},{"hanzi":"不可分割","pinyin":"bùkěfēngē","vi":"không thể chia cắt"}]},{"id":"蜜","hanzi":"蜜","pinyin":"mì","meaning_vi":"mật ong; mật, ngọt ngào","explanation":"蜜 (mật) → mật do ong làm ra; nghĩa mở rộng chỉ sự ngọt ngào.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍯","examples":[{"type":"basic","zh":"这罐蜜特别甜。","pinyin":"Zhè guàn mì tèbié tián.","vi":"Hũ mật này đặc biệt ngọt."},{"type":"simple","zh":"她往茶里加了一勺蜜，味道好多了。","pinyin":"Tā wǎng chá lǐjiāle yì sháo mì, wèidào hǎoduō le.","vi":"Cô ấy cho thêm một thìa mật vào trà, vị ngon hơn nhiều."},{"type":"compound","zh":"虽然这些蜜是野生的，但是价格并不太贵。","pinyin":"Suīrán zhèxiē mì shì yěshēng de, dànshì jiàgé bìngbú tài guì.","vi":"Tuy mật này là mật rừng nhưng giá cũng không quá đắt."}],"related":[{"hanzi":"蜂蜜","pinyin":"fēngmì","vi":"mật ong"},{"hanzi":"甜蜜","pinyin":"tiánmì","vi":"ngọt ngào"},{"hanzi":"蜜蜂","pinyin":"mìfēng","vi":"con ong"},{"hanzi":"蜜月","pinyin":"mìyuè","vi":"tuần trăng mật"}]},{"id":"蜜月","hanzi":"蜜月","pinyin":"mìyuè","meaning_vi":"tuần trăng mật","explanation":"蜜 (mật – ngọt ngào) + 月 (nguyệt – tháng) → tháng ngọt ngào đầu tiên sau khi cưới.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"💑","examples":[{"type":"basic","zh":"他们去海边度蜜月。","pinyin":"Tāmen qù hǎibiān dùmìyuè.","vi":"Họ đi biển hưởng tuần trăng mật."},{"type":"simple","zh":"结婚以后，他们打算去日本度蜜月。","pinyin":"Jiéhūn yǐhòu, tāmen dǎsuàn qù Rìběn dùmìyuè.","vi":"Sau khi cưới, họ dự định sang Nhật Bản hưởng tuần trăng mật."},{"type":"compound","zh":"虽然蜜月只有一个星期，但是他们留下了很多美好的回忆。","pinyin":"Suīrán mìyuè zhǐyǒu yí gè xīngqī, dànshì tāmen liúxiàle hěn duō měihǎo de huíyì.","vi":"Tuy tuần trăng mật chỉ có một tuần nhưng họ đã để lại nhiều kỷ niệm đẹp."}],"related":[{"hanzi":"度蜜月","pinyin":"dùmìyuè","vi":"hưởng tuần trăng mật"},{"hanzi":"新婚","pinyin":"xīnhūn","vi":"mới cưới"},{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"đám cưới"},{"hanzi":"蜜月期","pinyin":"mìyuèqī","vi":"thời kỳ trăng mật"}]},{"id":"免","hanzi":"免","pinyin":"miǎn","meaning_vi":"miễn, miễn trừ; tránh khỏi; bãi miễn","explanation":"免 (miễn) → được tha, không phải chịu; tránh khỏi; cũng chỉ cách chức.","hsk_level":"7-9","tags":["dong-tu"],"image":"🆓","examples":[{"type":"basic","zh":"学生的门票全免了。","pinyin":"Xuésheng de ménpiào quán miǎn le.","vi":"Vé vào cửa của học sinh được miễn hoàn toàn."},{"type":"simple","zh":"六岁以下的儿童坐公交车免票。","pinyin":"Liù suì yǐxià de értóng zuò gōngjiāochē miǎnpiào.","vi":"Trẻ em dưới sáu tuổi đi xe buýt được miễn vé."},{"type":"compound","zh":"出门前看看天气预报，以免路上被雨淋湿。","pinyin":"Chū ménqián kànkan tiānqì yùbào, yǐmiǎn lùshang bèi yǔ línshī.","vi":"Trước khi ra ngoài xem dự báo thời tiết, để tránh bị mưa ướt dọc đường."}],"related":[{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"},{"hanzi":"以免","pinyin":"yǐmiǎn","vi":"để tránh"},{"hanzi":"免除","pinyin":"miǎnchú","vi":"miễn trừ"}]},{"id":"免不了","hanzi":"免不了","pinyin":"miǎnbuliǎo","meaning_vi":"không tránh khỏi, khó tránh","explanation":"免 (miễn – tránh) + 不了 (không được) → không thể tránh được.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤷","examples":[{"type":"basic","zh":"吵架是免不了的。","pinyin":"Chǎojià shì miǎnbuliǎo de.","vi":"Cãi nhau là điều không tránh khỏi."},{"type":"simple","zh":"刚开始工作，免不了会犯一些错误。","pinyin":"Gāng kāishǐ gōngzuò, miǎnbuliǎo huì fàn yìxiē cuòwù.","vi":"Mới bắt đầu làm việc thì khó tránh khỏi mắc vài sai sót."},{"type":"compound","zh":"既然要出国留学，就免不了要吃一些苦。","pinyin":"Jìrán yào chūguó liúxué, jiù miǎnbuliǎo yào chī yìxiē kǔ.","vi":"Đã muốn đi du học thì không tránh khỏi phải chịu chút vất vả."}],"related":[{"hanzi":"难免","pinyin":"nánmiǎn","vi":"khó tránh"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"},{"hanzi":"不可避免","pinyin":"bùkěbìmiǎn","vi":"không thể tránh"},{"hanzi":"少不了","pinyin":"shǎobuliǎo","vi":"không thể thiếu"}]},{"id":"免职","hanzi":"免职","pinyin":"miǎnzhí","meaning_vi":"cách chức, miễn nhiệm","explanation":"免 (miễn – bãi bỏ) + 职 (chức – chức vụ) → bãi bỏ chức vụ của ai đó.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📤","examples":[{"type":"basic","zh":"他被免职了。","pinyin":"Tā bèi miǎnzhí le.","vi":"Ông ấy bị cách chức rồi."},{"type":"simple","zh":"那位局长因为受贿被免职了。","pinyin":"Nà wèi júzhǎng yīnwèi shòuhuì bèi miǎnzhí le.","vi":"Vị cục trưởng đó bị cách chức vì nhận hối lộ."},{"type":"compound","zh":"如果事故调查证明他有责任，他就会被免职。","pinyin":"Rúguǒ shìgù diàochá zhèngmíng tā yǒuzérèn, tā jiù huì bèi miǎnzhí.","vi":"Nếu điều tra tai nạn chứng minh ông ta có trách nhiệm thì ông ta sẽ bị cách chức."}],"related":[{"hanzi":"撤职","pinyin":"chèzhí","vi":"cách chức"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"任职","pinyin":"rènzhí","vi":"nhậm chức"},{"hanzi":"解雇","pinyin":"jiěgù","vi":"sa thải"}],"traditional":"免職"},{"id":"缅怀","hanzi":"缅怀","pinyin":"miǎnhuái","meaning_vi":"tưởng nhớ, hoài niệm","explanation":"缅 (miến – xa xôi) + 怀 (hoài – nhớ) → nhớ về người hay việc đã qua, mang sắc thái trang trọng, tôn kính.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🕯️","examples":[{"type":"basic","zh":"我们缅怀先烈。","pinyin":"Wǒmen miǎnhuái xiānliè.","vi":"Chúng ta tưởng nhớ các anh hùng liệt sĩ."},{"type":"simple","zh":"清明节人们会去扫墓，缅怀去世的亲人。","pinyin":"Qīngmíngjié rénmen huì qù sǎomù, miǎnhuái qùshì de qīnrén.","vi":"Tết Thanh Minh mọi người đi tảo mộ, tưởng nhớ người thân đã khuất."},{"type":"compound","zh":"虽然老校长已经去世多年，但是大家每年都会聚在一起缅怀他。","pinyin":"Suīrán lǎo xiàozhǎng yǐjīng qùshì duōnián, dànshì dàjiā měinián dōuhuì jù zài yìqǐ miǎnhuái tā.","vi":"Tuy thầy hiệu trưởng cũ đã mất nhiều năm nhưng năm nào mọi người cũng tụ họp tưởng nhớ thầy."}],"related":[{"hanzi":"怀念","pinyin":"huáiniàn","vi":"hoài niệm"},{"hanzi":"纪念","pinyin":"jìniàn","vi":"kỷ niệm"},{"hanzi":"悼念","pinyin":"dàoniàn","vi":"tưởng niệm"},{"hanzi":"追思","pinyin":"zhuīsī","vi":"nhớ lại"}],"traditional":"緬懷"},{"id":"面部","hanzi":"面部","pinyin":"miànbù","meaning_vi":"vùng mặt, khuôn mặt","explanation":"面 (diện – mặt) + 部 (bộ – bộ phận) → bộ phận mặt trên cơ thể; dùng trong văn viết, y học.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🙂","examples":[{"type":"basic","zh":"他面部受了伤。","pinyin":"Tā miànbù shòule shāng.","vi":"Anh ấy bị thương ở vùng mặt."},{"type":"simple","zh":"这款手机可以通过面部识别来解锁。","pinyin":"Zhè kuǎn shǒujī kěyǐ tōngguò miànbù shíbié lái jiěsuǒ.","vi":"Mẫu điện thoại này có thể mở khóa bằng nhận diện khuôn mặt."},{"type":"compound","zh":"因为天气太冷，所以他的面部皮肤又干又红。","pinyin":"Yīnwèi tiānqì tài lěng, suǒyǐ tā de miànbù pífū yòu gān yòu hóng.","vi":"Vì thời tiết quá lạnh nên da mặt anh ấy vừa khô vừa đỏ."}],"related":[{"hanzi":"脸部","pinyin":"liǎnbù","vi":"vùng mặt"},{"hanzi":"面孔","pinyin":"miànkǒng","vi":"gương mặt"},{"hanzi":"表情","pinyin":"biǎoqíng","vi":"nét mặt"},{"hanzi":"五官","pinyin":"wǔguān","vi":"ngũ quan"}]},{"id":"面粉","hanzi":"面粉","pinyin":"miànfěn","meaning_vi":"bột mì","explanation":"面 (miến – lúa mì, bột) + 粉 (phấn – bột) → bột xay từ lúa mì.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🌾","examples":[{"type":"basic","zh":"我去买袋面粉。","pinyin":"Wǒqù mǎi dài miànfěn.","vi":"Tôi đi mua một túi bột mì."},{"type":"simple","zh":"包饺子需要先用面粉和水和面。","pinyin":"Bāojiǎozi xūyào xiān yòng miànfěn hé shuǐ huómiàn.","vi":"Gói sủi cảo cần dùng bột mì và nước nhào bột trước."},{"type":"compound","zh":"如果家里的面粉放得太久，就容易生虫。","pinyin":"Rúguǒ jiālǐ de miànfěn fàng de tài jiǔ, jiù róngyì shēngchóng.","vi":"Nếu bột mì trong nhà để quá lâu thì dễ sinh mọt."}],"related":[{"hanzi":"面条","pinyin":"miàntiáo","vi":"mì sợi"},{"hanzi":"面包","pinyin":"miànbāo","vi":"bánh mì"},{"hanzi":"淀粉","pinyin":"diànfěn","vi":"tinh bột"},{"hanzi":"小麦","pinyin":"xiǎomài","vi":"lúa mì"}],"traditional":"麵粉"},{"id":"面面俱到","hanzi":"面面俱到","pinyin":"miànmiàn-jùdào","meaning_vi":"chu toàn mọi mặt, chu đáo đủ đường","explanation":"Nghĩa đen: mặt nào cũng được đến → nghĩa bóng: chăm lo chu toàn mọi phương diện; đôi khi chê dàn trải, thiếu trọng tâm.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧭","examples":[{"type":"basic","zh":"他做事面面俱到。","pinyin":"Tā zuòshì miànmiànjùdào.","vi":"Anh ấy làm việc chu toàn mọi mặt."},{"type":"simple","zh":"写文章不必面面俱到，要突出重点。","pinyin":"Xiě wénzhāng búbì miànmiànjùdào, yào tūchū zhòngdiǎn.","vi":"Viết bài không cần ôm đồm mọi mặt, phải làm nổi bật trọng điểm."},{"type":"compound","zh":"虽然他考虑得面面俱到，但是计划还是出了问题。","pinyin":"Suīrán tā kǎolǜ de miànmiànjùdào, dànshì jìhuà háishì chūle wèntí.","vi":"Tuy anh ấy đã cân nhắc chu toàn mọi mặt nhưng kế hoạch vẫn gặp trục trặc."}],"related":[{"hanzi":"周到","pinyin":"zhōudào","vi":"chu đáo"},{"hanzi":"全面","pinyin":"quánmiàn","vi":"toàn diện"},{"hanzi":"无微不至","pinyin":"wúwēibúzhì","vi":"chăm sóc tận tình"},{"hanzi":"顾此失彼","pinyin":"gùcǐshībǐ","vi":"lo được này mất kia"}]},{"id":"苗","hanzi":"苗","pinyin":"miáo","meaning_vi":"mầm, mạ, cây non; dân tộc Miêu (H'Mông)","explanation":"苗 (miêu – mạ non) → cây non mới mọc; cũng là tên dân tộc Miêu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"田里的苗长高了。","pinyin":"Tián lǐ de miáo zhǎnggāo le.","vi":"Mạ ngoài ruộng đã cao lên rồi."},{"type":"simple","zh":"春天一到，农民们就开始在地里种苗了。","pinyin":"Chūntiān yí dào, nóngmínmen jiù kāishǐ zài dì lǐ zhòngmiáo le.","vi":"Mùa xuân vừa đến, nông dân bắt đầu trồng cây non ngoài đồng."},{"type":"compound","zh":"如果这几天不下雨，地里的苗就会干死。","pinyin":"Rúguǒ zhèjǐtiān bú xiàyǔ, dì lǐ de miáo jiù huì gān sǐ.","vi":"Nếu mấy ngày này không mưa thì cây non ngoài đồng sẽ khô chết."}],"related":[{"hanzi":"幼苗","pinyin":"yòumiáo","vi":"cây non"},{"hanzi":"树苗","pinyin":"shùmiáo","vi":"cây giống"},{"hanzi":"苗头","pinyin":"miáotou","vi":"dấu hiệu"},{"hanzi":"苗族","pinyin":"Miáozú","vi":"dân tộc Miêu"}]},{"id":"苗头","hanzi":"苗头","pinyin":"miáotou","meaning_vi":"dấu hiệu ban đầu, manh nha, chiều hướng","explanation":"苗 (miêu – mầm) + 头 (đầu) → mầm mới nhú; nghĩa bóng là dấu hiệu ban đầu của một xu hướng.","hsk_level":"7-9","tags":["danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"情况有点苗头了。","pinyin":"Qíngkuàng yǒudiǎn miáotou le.","vi":"Tình hình đã có chút manh nha rồi."},{"type":"simple","zh":"老师发现了早恋的苗头，就找他谈了谈。","pinyin":"Lǎoshī fāxiànle zǎoliàn de miáotou, jiù zhǎo tā tánle tán.","vi":"Thầy giáo phát hiện dấu hiệu yêu sớm nên đã tìm cậu ấy nói chuyện."},{"type":"compound","zh":"一旦发现不好的苗头，就要马上采取措施。","pinyin":"Yídàn fāxiàn bù hǎo de miáotou, jiùyào mǎshàng cǎiqǔ cuòshī.","vi":"Một khi phát hiện dấu hiệu xấu thì phải lập tức có biện pháp."}],"related":[{"hanzi":"迹象","pinyin":"jìxiàng","vi":"dấu hiệu"},{"hanzi":"征兆","pinyin":"zhēngzhào","vi":"điềm báo"},{"hanzi":"趋势","pinyin":"qūshì","vi":"xu hướng"},{"hanzi":"端倪","pinyin":"duānní","vi":"manh mối"}],"traditional":"苗頭"},{"id":"庙","hanzi":"庙","pinyin":"miào","meaning_vi":"miếu, chùa, đền","explanation":"庙 (miếu) → nơi thờ thần thánh, tổ tiên hoặc Phật.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🛕","examples":[{"type":"basic","zh":"山上有座庙。","pinyin":"Shān shang yǒu zuò miào.","vi":"Trên núi có một ngôi miếu."},{"type":"simple","zh":"每年春节，奶奶都要去庙里烧香。","pinyin":"Měinián Chūnjié, nǎinai dōu yào qù miào lǐ shāoxiāng.","vi":"Tết năm nào bà cũng đi chùa thắp hương."},{"type":"compound","zh":"这座庙虽然不大，但是已经有五百多年的历史了。","pinyin":"Zhè zuò miào suīrán búdà, dànshì yǐjīng yǒu wǔ bǎi duōnián de lìshǐ le.","vi":"Ngôi miếu này tuy không lớn nhưng đã có lịch sử hơn năm trăm năm."}],"related":[{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"庙会","pinyin":"miàohuì","vi":"hội chùa"},{"hanzi":"寺","pinyin":"sì","vi":"chùa"},{"hanzi":"烧香","pinyin":"shāoxiāng","vi":"thắp hương"}],"traditional":"廟"},{"id":"庙会","hanzi":"庙会","pinyin":"miàohuì","meaning_vi":"hội chùa, hội đền","explanation":"庙 (miếu – chùa, đền) + 会 (hội – hội họp) → phiên chợ, lễ hội tổ chức gần chùa miếu vào dịp lễ Tết.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"春节我们去逛庙会。","pinyin":"Chūnjié wǒmen qù guàng miàohuì.","vi":"Tết chúng tôi đi dạo hội chùa."},{"type":"simple","zh":"庙会上有很多好吃的小吃和民间表演。","pinyin":"Miàohuì shang yǒu hěn duō hǎochī de xiǎochī hé mínjiān biǎoyǎn.","vi":"Ở hội chùa có nhiều món ăn vặt ngon và các tiết mục biểu diễn dân gian."},{"type":"compound","zh":"虽然庙会上人山人海，但是孩子们玩得特别开心。","pinyin":"Suīrán miàohuì shang rénshānrénhǎi, dànshì háizimen wán de tèbié kāixīn.","vi":"Tuy hội chùa đông nghịt người nhưng bọn trẻ chơi rất vui."}],"related":[{"hanzi":"庙","pinyin":"miào","vi":"miếu"},{"hanzi":"集市","pinyin":"jíshì","vi":"phiên chợ"},{"hanzi":"灯会","pinyin":"dēnghuì","vi":"hội đèn lồng"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"}],"traditional":"廟會"},{"id":"民用","hanzi":"民用","pinyin":"mínyòng","meaning_vi":"dân dụng, dùng cho dân sự","explanation":"民 (dân – nhân dân) + 用 (dụng – dùng) → dùng cho dân thường, đối lập với quân dụng.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"这是民用飞机。","pinyin":"Zhè shì mínyòng fēijī.","vi":"Đây là máy bay dân dụng."},{"type":"simple","zh":"很多军用技术后来都变成了民用产品。","pinyin":"Hěn duō jūnyòng jìshù hòulái dōu biàn chéngle mínyòng chǎnpǐn.","vi":"Nhiều công nghệ quân sự sau này đều trở thành sản phẩm dân dụng."},{"type":"compound","zh":"虽然这个机场以前是军用的，但是现在已经改成民用了。","pinyin":"Suīrán zhè ge jīchǎng yǐqián shì jūnyòng de, dànshì xiànzài yǐjīng gǎichéng mínyòng le.","vi":"Tuy sân bay này trước đây dùng cho quân sự nhưng giờ đã chuyển sang dân dụng."}],"related":[{"hanzi":"军用","pinyin":"jūnyòng","vi":"quân dụng"},{"hanzi":"民间","pinyin":"mínjiān","vi":"dân gian"},{"hanzi":"商用","pinyin":"shāngyòng","vi":"thương mại"},{"hanzi":"家用","pinyin":"jiāyòng","vi":"gia dụng"}]},{"id":"名贵","hanzi":"名贵","pinyin":"míngguì","meaning_vi":"quý giá, quý hiếm, nổi tiếng và đắt giá","explanation":"名 (danh – nổi tiếng) + 贵 (quý – đắt, quý) → nổi tiếng và quý giá.","hsk_level":"7-9","tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"这是一种名贵的花。","pinyin":"Zhè shì yì zhǒng míngguì de huā.","vi":"Đây là một loài hoa quý hiếm."},{"type":"simple","zh":"他收藏了很多名贵的字画。","pinyin":"Tā shōucángle hěn duō míngguì de zìhuà.","vi":"Ông ấy sưu tầm rất nhiều thư họa quý giá."},{"type":"compound","zh":"虽然这块手表很名贵，但是他平时很少戴。","pinyin":"Suīrán zhè kuài shǒubiǎo hěn míngguì, dànshì tā píngshí hěn shǎo dài.","vi":"Tuy chiếc đồng hồ này rất quý giá nhưng anh ấy hiếm khi đeo."}],"related":[{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý báu"},{"hanzi":"贵重","pinyin":"guìzhòng","vi":"quý giá"},{"hanzi":"昂贵","pinyin":"ángguì","vi":"đắt đỏ"},{"hanzi":"廉价","pinyin":"liánjià","vi":"rẻ tiền"}],"traditional":"名貴"},{"id":"名气","hanzi":"名气","pinyin":"míngqi","meaning_vi":"danh tiếng, tiếng tăm","explanation":"名 (danh – tên tuổi) + 气 (khí – thanh thế) → tiếng tăm, mức độ nổi tiếng; khẩu ngữ.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌟","examples":[{"type":"basic","zh":"他在当地很有名气。","pinyin":"Tā zài dāngdì hěn yǒu míngqi.","vi":"Ông ấy rất có tiếng ở địa phương."},{"type":"simple","zh":"这家老字号的名气越来越大。","pinyin":"Zhè jiālǎo zìhào de míngqi yuèláiyuè dà.","vi":"Danh tiếng của cửa hàng lâu đời này ngày càng lớn."},{"type":"compound","zh":"虽然这个歌手名气不大，但是他的歌很好听。","pinyin":"Suīrán zhè ge gēshǒu míngqi búdà, dànshì tā de gē hěn hǎotīng.","vi":"Tuy ca sĩ này không mấy tiếng tăm nhưng bài hát của anh ấy rất hay."}],"related":[{"hanzi":"名声","pinyin":"míngshēng","vi":"danh tiếng"},{"hanzi":"名誉","pinyin":"míngyù","vi":"danh dự"},{"hanzi":"出名","pinyin":"chūmíng","vi":"nổi tiếng"},{"hanzi":"知名度","pinyin":"zhīmíngdù","vi":"độ nổi tiếng"}],"traditional":"名氣"},{"id":"名声","hanzi":"名声","pinyin":"míngshēng","meaning_vi":"danh tiếng, tiếng tăm","explanation":"名 (danh – tên tuổi) + 声 (thanh – tiếng) → tiếng tăm, lời đánh giá của xã hội về một người, một tổ chức.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📣","examples":[{"type":"basic","zh":"他的名声很好。","pinyin":"Tā de míngshēng hěn hǎo.","vi":"Danh tiếng của anh ấy rất tốt."},{"type":"simple","zh":"这件事严重影响了公司的名声。","pinyin":"Zhè jiàn shì yánzhòng yǐngxiǎngle gōngsī de míngshēng.","vi":"Việc này ảnh hưởng nghiêm trọng đến danh tiếng của công ty."},{"type":"compound","zh":"一旦名声坏了，就很难再让别人相信你。","pinyin":"Yídàn míngshēng huàile, jiù hěn nán zài ràng biérén xiāngxìn nǐ.","vi":"Một khi danh tiếng đã hỏng thì rất khó khiến người khác tin bạn lần nữa."}],"related":[{"hanzi":"名气","pinyin":"míngqi","vi":"tiếng tăm"},{"hanzi":"名誉","pinyin":"míngyù","vi":"danh dự"},{"hanzi":"声誉","pinyin":"shēngyù","vi":"thanh danh"},{"hanzi":"口碑","pinyin":"kǒubēi","vi":"tiếng lành"}],"traditional":"名聲"},{"id":"名言","hanzi":"名言","pinyin":"míngyán","meaning_vi":"danh ngôn, câu nói nổi tiếng","explanation":"名 (danh – nổi tiếng) + 言 (ngôn – lời nói) → câu nói nổi tiếng được nhiều người trích dẫn.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💬","examples":[{"type":"basic","zh":"这是孔子的名言。","pinyin":"Zhè shì Kǒngzǐ de míngyán.","vi":"Đây là câu danh ngôn của Khổng Tử."},{"type":"simple","zh":"他把一句名言贴在书桌上鼓励自己。","pinyin":"Tā bǎ yíjù míngyán tiē zài shūzhuō shang gǔlì zìjǐ.","vi":"Anh ấy dán một câu danh ngôn lên bàn học để tự khích lệ mình."},{"type":"compound","zh":"虽然这句名言很短，但是包含了深刻的道理。","pinyin":"Suīrán zhè jù míngyán hěn duǎn, dànshì bāohánle shēnkè de dàolǐ.","vi":"Tuy câu danh ngôn này rất ngắn nhưng chứa đựng đạo lý sâu sắc."}],"related":[{"hanzi":"格言","pinyin":"géyán","vi":"châm ngôn"},{"hanzi":"名句","pinyin":"míngjù","vi":"câu nổi tiếng"},{"hanzi":"谚语","pinyin":"yànyǔ","vi":"tục ngữ"},{"hanzi":"座右铭","pinyin":"zuòyòumíng","vi":"phương châm sống"}]},{"id":"名著","hanzi":"名著","pinyin":"míngzhù","meaning_vi":"tác phẩm nổi tiếng, kiệt tác","explanation":"名 (danh – nổi tiếng) + 著 (trứ – tác phẩm) → tác phẩm văn học, học thuật nổi tiếng.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📚","examples":[{"type":"basic","zh":"我喜欢读名著。","pinyin":"Wǒ xǐhuan dú míngzhù.","vi":"Tôi thích đọc tác phẩm nổi tiếng."},{"type":"simple","zh":"《红楼梦》是中国古典文学四大名著之一。","pinyin":"Hónglóumèng shì Zhōngguó gǔdiǎn wénxué sìdàmíngzhù zhīyī.","vi":"\"Hồng Lâu Mộng\" là một trong tứ đại danh tác của văn học cổ điển Trung Quốc."},{"type":"compound","zh":"虽然很多名著读起来有点难，但是越读越有味道。","pinyin":"Suīrán hěn duō míngzhù dú qǐlái yǒudiǎn nán, dànshì yuè dú yuè yǒu wèidao.","vi":"Tuy nhiều tác phẩm nổi tiếng đọc hơi khó nhưng càng đọc càng thấm."}],"related":[{"hanzi":"经典","pinyin":"jīngdiǎn","vi":"kinh điển"},{"hanzi":"作品","pinyin":"zuòpǐn","vi":"tác phẩm"},{"hanzi":"巨著","pinyin":"jùzhù","vi":"tác phẩm đồ sộ"},{"hanzi":"著作","pinyin":"zhùzuò","vi":"trước tác"}]},{"id":"模拟","hanzi":"模拟","pinyin":"mónǐ","meaning_vi":"mô phỏng, bắt chước; thi thử","explanation":"模 (mô – khuôn mẫu) + 拟 (nghĩ – phỏng theo) → làm theo khuôn mẫu, mô phỏng tình huống thật.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🖥️","examples":[{"type":"basic","zh":"我们做了模拟考试。","pinyin":"Wǒmen zuòle mónǐ kǎoshì.","vi":"Chúng tôi đã làm bài thi thử."},{"type":"simple","zh":"飞行员要先在电脑上模拟飞行。","pinyin":"Fēixíngyuán yào xiān zài diànnǎo shang mónǐ fēixíng.","vi":"Phi công phải mô phỏng bay trên máy tính trước."},{"type":"compound","zh":"因为这次演习模拟了真实的火灾，所以大家都很紧张。","pinyin":"Yīnwèi zhè cì yǎnxí mónǐle zhēnshí de huǒzāi, suǒyǐ dàjiā dōu hěn jǐnzhāng.","vi":"Vì buổi diễn tập lần này mô phỏng một vụ hỏa hoạn thật nên mọi người đều rất căng thẳng."}],"related":[{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"},{"hanzi":"仿真","pinyin":"fǎngzhēn","vi":"mô phỏng"},{"hanzi":"模型","pinyin":"móxíng","vi":"mô hình"},{"hanzi":"演习","pinyin":"yǎnxí","vi":"diễn tập"}],"traditional":"模擬"},{"id":"磨损","hanzi":"磨损","pinyin":"mósǔn","meaning_vi":"mài mòn, hao mòn","explanation":"磨 (ma – cọ xát) + 损 (tổn – hư hại) → bị cọ xát lâu ngày mà hư hao.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚙️","examples":[{"type":"basic","zh":"轮胎磨损了。","pinyin":"Lúntāi mósǔn le.","vi":"Lốp xe bị mòn rồi."},{"type":"simple","zh":"这双鞋穿了三年，鞋底已经严重磨损。","pinyin":"Zhè shuāng xié chuānle sān nián, xiédǐ yǐjīng yánzhòng mósǔn.","vi":"Đôi giày này đi ba năm rồi, đế giày đã mòn nặng."},{"type":"compound","zh":"如果机器零件磨损了，就要及时更换。","pinyin":"Rúguǒ jīqì língjiàn mósǔn le, jiùyào jíshí gēng huàn.","vi":"Nếu linh kiện máy bị mài mòn thì phải thay kịp thời."}],"related":[{"hanzi":"损耗","pinyin":"sǔnhào","vi":"hao tổn"},{"hanzi":"磨","pinyin":"mó","vi":"mài"},{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hỏng"},{"hanzi":"耐磨","pinyin":"nàimó","vi":"chịu mài mòn"}],"traditional":"磨損"},{"id":"蘑菇","hanzi":"蘑菇","pinyin":"mógu","meaning_vi":"nấm","explanation":"蘑菇 (ma cô) → các loại nấm ăn được; khẩu ngữ còn có nghĩa \"lề mề, dây dưa\".","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍄","examples":[{"type":"basic","zh":"我爱吃蘑菇。","pinyin":"Wǒ ài chī mógu.","vi":"Tôi thích ăn nấm."},{"type":"simple","zh":"下过雨以后，树林里长出了很多蘑菇。","pinyin":"Xiàguo yǔ yǐhòu, shùlín lǐ zhǎngchūle hěn duō mógu.","vi":"Sau cơn mưa, trong rừng mọc lên rất nhiều nấm."},{"type":"compound","zh":"野生蘑菇虽然看起来很漂亮，但是有的有毒，不能随便吃。","pinyin":"Yěshēng mógu suīrán kànqǐlái hěn piàoliang, dànshì yǒude yǒudú, bù néng suíbiàn chī.","vi":"Nấm dại tuy trông rất đẹp nhưng có loại có độc, không được ăn bừa."}],"related":[{"hanzi":"香菇","pinyin":"xiānggū","vi":"nấm hương"},{"hanzi":"木耳","pinyin":"mù'ěr","vi":"mộc nhĩ"},{"hanzi":"蔬菜","pinyin":"shūcài","vi":"rau củ"},{"hanzi":"菌类","pinyin":"jūnlèi","vi":"loài nấm"}]},{"id":"抹","hanzi":"抹","pinyin":"mǒ","meaning_vi":"bôi, quệt, trát; lau; xóa bỏ","explanation":"抹 (mạt – xoa, bôi) đọc mǒ: bôi lên, quệt đi, xóa bỏ; (đọc mā: lau chùi).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🧴","examples":[{"type":"basic","zh":"面包上抹点果酱。","pinyin":"Miànbāo shang mǒ diǎn guǒjiàng.","vi":"Phết chút mứt lên bánh mì."},{"type":"simple","zh":"出门前她在脸上抹了一层防晒霜。","pinyin":"Chū ménqián tā zài liǎn shang mǒle yīcéng fángshàishuāng.","vi":"Trước khi ra ngoài cô ấy bôi một lớp kem chống nắng lên mặt."},{"type":"compound","zh":"虽然他擦掉了黑板上的字，但是抹不掉心里的记忆。","pinyin":"Suīrán tā cādiàole hēibǎn shang de zì, dànshì mǒ bu diào xīnlǐ de jìyì.","vi":"Tuy anh ấy đã xóa chữ trên bảng nhưng không xóa được ký ức trong lòng."}],"related":[{"hanzi":"涂抹","pinyin":"túmǒ","vi":"bôi trát"},{"hanzi":"抹布","pinyin":"mābù","vi":"giẻ lau"},{"hanzi":"擦","pinyin":"cā","vi":"lau"},{"hanzi":"抹杀","pinyin":"mǒshā","vi":"xóa bỏ, phủ nhận"}]},{"id":"莫非","hanzi":"莫非","pinyin":"mòfēi","meaning_vi":"lẽ nào, chẳng lẽ, phải chăng","explanation":"莫 (mạc – chẳng) + 非 (phi – không phải) → chẳng phải là…; dùng trong câu hỏi phỏng đoán.","hsk_level":"7-9","tags":["pho-tu"],"image":"🧐","examples":[{"type":"basic","zh":"莫非他生病了？","pinyin":"Mòfēi tā shēngbìng le?","vi":"Lẽ nào anh ấy bị ốm?"},{"type":"simple","zh":"他今天一句话也不说，莫非遇到什么麻烦了？","pinyin":"Tā jīntiān yíjùhuà yě bù shuō, mòfēi yùdào shénme máfan le?","vi":"Hôm nay anh ấy chẳng nói câu nào, phải chăng gặp chuyện gì phiền phức?"},{"type":"compound","zh":"门没锁，灯也开着，莫非有人比我们先到了？","pinyin":"Mén méi suǒ, dēng yě kāi zhe, mòfēi yǒurén bǐ wǒmen xiān dào le?","vi":"Cửa không khóa, đèn cũng bật, lẽ nào có người đến trước chúng ta?"}],"related":[{"hanzi":"难道","pinyin":"nándào","vi":"chẳng lẽ"},{"hanzi":"难不成","pinyin":"nánbuchéng","vi":"lẽ nào"},{"hanzi":"莫","pinyin":"mò","vi":"chớ, chẳng"},{"hanzi":"或许","pinyin":"huòxǔ","vi":"có lẽ"}]},{"id":"莫过于","hanzi":"莫过于","pinyin":"mòguòyú","meaning_vi":"không gì bằng, không gì hơn","explanation":"莫 (mạc – không gì) + 过 (quá – vượt) + 于 (ư – so với) → không gì vượt hơn được; dùng nhấn mạnh mức cao nhất.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏆","examples":[{"type":"basic","zh":"最开心的莫过于回家。","pinyin":"Zuì kāixīn de mòguòyú huíjiā.","vi":"Vui nhất không gì bằng được về nhà."},{"type":"simple","zh":"人生最大的幸福莫过于身体健康。","pinyin":"Rénshēng zuì dà de xìngfú mòguòyú shēntǐ jiànkāng.","vi":"Hạnh phúc lớn nhất đời người không gì bằng có sức khỏe."},{"type":"compound","zh":"对父母来说，最让他们骄傲的莫过于孩子有出息，所以他们总是全力支持孩子。","pinyin":"Duì fùmǔ lái shuō, zuì ràng tāmen jiāo'ào de mòguòyú háizi yǒuchūxi, suǒyǐ tāmen zǒngshì quánlì zhīchí háizi.","vi":"Với cha mẹ, điều tự hào nhất không gì bằng con cái thành đạt, nên họ luôn dốc sức ủng hộ con."}],"related":[{"hanzi":"莫非","pinyin":"mòfēi","vi":"lẽ nào"},{"hanzi":"不如","pinyin":"bùrú","vi":"không bằng"},{"hanzi":"最","pinyin":"zuì","vi":"nhất"},{"hanzi":"无过于","pinyin":"wúguòyú","vi":"không gì hơn"}],"traditional":"莫過於"},{"id":"漠然","hanzi":"漠然","pinyin":"mòrán","meaning_vi":"thờ ơ, lạnh nhạt, dửng dưng","explanation":"漠 (mạc – lạnh nhạt) + 然 (nhiên – dáng vẻ) → dáng vẻ lạnh lùng, không quan tâm đến chuyện xung quanh.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😐","examples":[{"type":"basic","zh":"他漠然地看着我。","pinyin":"Tā mòrán de kànzhe wǒ.","vi":"Anh ấy thờ ơ nhìn tôi."},{"type":"simple","zh":"听到这个坏消息，她只是漠然地点了点头。","pinyin":"Tīngdào zhè ge huài xiāoxi, tā zhǐshì mòrán dediǎnle diǎntóu.","vi":"Nghe tin xấu này, cô ấy chỉ dửng dưng gật đầu."},{"type":"compound","zh":"虽然路人都很同情他，但是他自己却显得很漠然。","pinyin":"Suīrán lùrén dōu hěn tóngqíng tā, dànshì tā zìjǐ què xiǎnde hěn mòrán.","vi":"Tuy người qua đường đều thương cảm anh ta, nhưng bản thân anh ta lại tỏ ra rất dửng dưng."}],"related":[{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh lùng"},{"hanzi":"淡漠","pinyin":"dànmò","vi":"hờ hững"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"关心","pinyin":"guānxīn","vi":"quan tâm"}]},{"id":"墨","hanzi":"墨","pinyin":"mò","meaning_vi":"mực (tàu), mực viết","explanation":"墨 (mặc – mực), gồm 黑 (hắc – đen) + 土 (thổ – đất) → thỏi mực đen làm từ muội than để viết thư pháp; nghĩa rộng là mực nói chung.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🖋️","examples":[{"type":"basic","zh":"砚台里没墨了。","pinyin":"Yàntai lǐ méi mò le.","vi":"Trong nghiên hết mực rồi."},{"type":"simple","zh":"爷爷每天早上都磨墨练书法。","pinyin":"Yéye měitiān zǎo Shangdōu mó mò liàn shūfǎ.","vi":"Sáng nào ông nội cũng mài mực luyện thư pháp."},{"type":"compound","zh":"因为墨还没干，所以你别用手碰这幅字。","pinyin":"Yīnwèi mò hái méi gān, suǒyǐ nǐ bié yòng shǒu pèng zhè fú zì.","vi":"Vì mực chưa khô nên cậu đừng lấy tay chạm vào bức chữ này."}],"related":[{"hanzi":"墨水","pinyin":"mòshuǐ","vi":"mực nước"},{"hanzi":"笔墨","pinyin":"bǐmò","vi":"bút mực"},{"hanzi":"墨汁","pinyin":"mòzhī","vi":"mực tàu lỏng"},{"hanzi":"砚台","pinyin":"yàntai","vi":"nghiên mực"}]},{"id":"默读","hanzi":"默读","pinyin":"mòdú","meaning_vi":"đọc thầm","explanation":"默 (mặc – im lặng) + 读 (độc – đọc) → đọc bằng mắt, không phát ra tiếng.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"请大家默读课文。","pinyin":"Qǐng dàjiā mòdú kèwén.","vi":"Mời cả lớp đọc thầm bài khóa."},{"type":"simple","zh":"他在图书馆里安静地默读一本小说。","pinyin":"Tā zài túshūguǎn lǐ ānjìng de mòdú yì běn xiǎoshuō.","vi":"Anh ấy lặng lẽ đọc thầm một cuốn tiểu thuyết trong thư viện."},{"type":"compound","zh":"如果默读时总是动嘴唇，就会影响阅读速度。","pinyin":"Rúguǒ mòdú shí zǒngshì dòng zuǐchún, jiù huì yǐngxiǎng yuèdú sùdù.","vi":"Nếu khi đọc thầm cứ mấp máy môi thì sẽ ảnh hưởng đến tốc độ đọc."}],"related":[{"hanzi":"朗读","pinyin":"lǎngdú","vi":"đọc to"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"đọc"},{"hanzi":"默写","pinyin":"mòxiě","vi":"viết chính tả theo trí nhớ"},{"hanzi":"沉默","pinyin":"chénmò","vi":"im lặng"}],"traditional":"默讀"},{"id":"谋害","hanzi":"谋害","pinyin":"móuhài","meaning_vi":"mưu hại, âm mưu giết hại","explanation":"谋 (mưu – tính kế) + 害 (hại – làm hại) → lập mưu để hãm hại, giết người.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🗡️","examples":[{"type":"basic","zh":"他被人谋害了。","pinyin":"Tā bèi rén móuhài le.","vi":"Anh ta đã bị người ta mưu hại."},{"type":"simple","zh":"警方怀疑死者是被亲戚谋害的。","pinyin":"Jǐngfāng huáiyí sǐzhě shì bèi qīnqi móuhài de.","vi":"Cảnh sát nghi ngờ nạn nhân bị chính người thân mưu hại."},{"type":"compound","zh":"虽然他曾计划谋害对手，但是最后没敢动手。","pinyin":"Suīrán tā céng jìhuà móuhài duìshǒu, dànshì zuìhòu méi gǎn dòngshǒu.","vi":"Tuy hắn từng lên kế hoạch mưu hại đối thủ, nhưng cuối cùng không dám ra tay."}],"related":[{"hanzi":"谋杀","pinyin":"móushā","vi":"mưu sát"},{"hanzi":"陷害","pinyin":"xiànhài","vi":"hãm hại"},{"hanzi":"阴谋","pinyin":"yīnmóu","vi":"âm mưu"},{"hanzi":"杀害","pinyin":"shāhài","vi":"sát hại"}],"traditional":"謀害"},{"id":"亩","hanzi":"亩","pinyin":"mǔ","meaning_vi":"mẫu (đơn vị diện tích ruộng ≈ 666,7 m²)","explanation":"亩 (mẫu) → đơn vị đo diện tích ruộng đất của Trung Quốc, 1 亩 ≈ 666,7 m², 15 亩 = 1 hecta.","hsk_level":"7-9","tags":["luong-tu","so-luong"],"image":"🌾","examples":[{"type":"basic","zh":"他家有十亩地。","pinyin":"Tā jiā yǒu shí mǔ dì.","vi":"Nhà anh ấy có mười mẫu đất."},{"type":"simple","zh":"今年这几亩稻田的收成特别好。","pinyin":"Jīnnián zhè jǐ mǔ dàotián de shōucheng tèbié hǎo.","vi":"Năm nay mấy mẫu ruộng lúa này được mùa đặc biệt."},{"type":"compound","zh":"即使只有三亩果园，他也打理得井井有条。","pinyin":"Jíshǐ zhǐyǒu sān mǔ guǒyuán, tā yě dǎlǐ de jǐngjǐngyǒutiáo.","vi":"Dù chỉ có ba mẫu vườn cây ăn quả, anh ấy vẫn chăm sóc đâu ra đấy."}],"related":[{"hanzi":"田地","pinyin":"tiándì","vi":"ruộng đất"},{"hanzi":"公顷","pinyin":"gōngqǐng","vi":"hecta"},{"hanzi":"平方米","pinyin":"píngfāngmǐ","vi":"mét vuông"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"}],"traditional":"畝"},{"id":"牡丹","hanzi":"牡丹","pinyin":"mǔdān","meaning_vi":"hoa mẫu đơn","explanation":"牡丹 (mẫu đơn) → loài hoa to, rực rỡ, được coi là “vua các loài hoa” ở Trung Quốc, tượng trưng cho phú quý.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌺","examples":[{"type":"basic","zh":"牡丹开得真美！","pinyin":"Mǔdān kāi de zhēn měi!","vi":"Hoa mẫu đơn nở đẹp quá!"},{"type":"simple","zh":"洛阳每年四月都会举办牡丹花会。","pinyin":"Luòyáng měinián Sìyuè dōuhuì jǔbàn mǔdān huāhuì.","vi":"Tháng Tư hằng năm Lạc Dương đều tổ chức hội hoa mẫu đơn."},{"type":"compound","zh":"因为牡丹象征富贵，所以很多人家里挂牡丹画。","pinyin":"Yīnwèi mǔdān xiàngzhēng fùguì, suǒyǐ hěn duō rénjiā lǐ guà mǔdān huà.","vi":"Vì mẫu đơn tượng trưng cho phú quý nên nhiều nhà treo tranh hoa mẫu đơn."}],"related":[{"hanzi":"花卉","pinyin":"huāhuì","vi":"hoa cỏ"},{"hanzi":"芍药","pinyin":"sháoyao","vi":"hoa thược dược"},{"hanzi":"富贵","pinyin":"fùguì","vi":"phú quý"},{"hanzi":"鲜花","pinyin":"xiānhuā","vi":"hoa tươi"}]},{"id":"木板","hanzi":"木板","pinyin":"mùbǎn","meaning_vi":"tấm ván gỗ, tấm gỗ","explanation":"木 (mộc – gỗ) + 板 (bản – tấm phẳng) → tấm gỗ phẳng, ván gỗ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪵","examples":[{"type":"basic","zh":"地上铺着木板。","pinyin":"Dìshang pūzhe mùbǎn.","vi":"Dưới sàn lát ván gỗ."},{"type":"simple","zh":"爸爸用几块木板给小狗搭了个窝。","pinyin":"Bàba yòng jǐ kuài mùbǎn gěi xiǎogǒu dāle gè wō.","vi":"Bố dùng mấy tấm ván gỗ dựng cho chó con một cái chuồng."},{"type":"compound","zh":"这块木板虽然看起来很旧，但是还挺结实的。","pinyin":"Zhè kuài mùbǎn suīrán kànqǐlái hěn jiù, dànshì hái tǐng jiēshi de.","vi":"Tấm ván này tuy trông rất cũ nhưng vẫn khá chắc chắn."}],"related":[{"hanzi":"木头","pinyin":"mùtou","vi":"gỗ"},{"hanzi":"木材","pinyin":"mùcái","vi":"gỗ vật liệu"},{"hanzi":"地板","pinyin":"dìbǎn","vi":"sàn nhà"},{"hanzi":"钉子","pinyin":"dīngzi","vi":"cái đinh"}]},{"id":"木材","hanzi":"木材","pinyin":"mùcái","meaning_vi":"gỗ (nguyên liệu), vật liệu gỗ","explanation":"木 (mộc – gỗ) + 材 (tài – vật liệu) → gỗ dùng làm vật liệu xây dựng, đóng đồ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🌲","examples":[{"type":"basic","zh":"这批木材很贵。","pinyin":"Zhè pī mùcái hěn guì.","vi":"Lô gỗ này rất đắt."},{"type":"simple","zh":"这家工厂从国外进口了大量木材。","pinyin":"Zhè jiā gōngchǎng cóng guówài jìnkǒule dàliàng mùcái.","vi":"Nhà máy này đã nhập khẩu một lượng lớn gỗ từ nước ngoài."},{"type":"compound","zh":"如果木材没有晒干，就容易开裂变形。","pinyin":"Rúguǒ mùcái méiyǒu shàigān, jiù róngyì kāiliè biànxíng.","vi":"Nếu gỗ chưa phơi khô thì dễ nứt và cong vênh."}],"related":[{"hanzi":"木头","pinyin":"mùtou","vi":"gỗ"},{"hanzi":"原材料","pinyin":"yuáncáiliào","vi":"nguyên liệu"},{"hanzi":"森林","pinyin":"sēnlín","vi":"rừng"},{"hanzi":"砍伐","pinyin":"kǎnfá","vi":"chặt phá"}]},{"id":"木匠","hanzi":"木匠","pinyin":"mùjiàng","meaning_vi":"thợ mộc","explanation":"木 (mộc – gỗ) + 匠 (tượng – thợ thủ công) → người thợ làm đồ gỗ.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🔨","examples":[{"type":"basic","zh":"他爷爷是木匠。","pinyin":"Tā yéye shì mùjiàng.","vi":"Ông nội anh ấy là thợ mộc."},{"type":"simple","zh":"村里的老木匠做了一张漂亮的书桌。","pinyin":"Cūnlǐ de lǎo mùjiàng zuòle yì zhāng piàoliang de shūzhuō.","vi":"Ông thợ mộc già trong làng đóng một chiếc bàn học rất đẹp."},{"type":"compound","zh":"虽然他只是个木匠，但是做的家具很有名。","pinyin":"Suīrán tā zhǐshì gè mùjiàng, dànshì zuò de jiājù hěn yǒumíng.","vi":"Tuy ông ấy chỉ là thợ mộc nhưng đồ gỗ ông làm rất nổi tiếng."}],"related":[{"hanzi":"工匠","pinyin":"gōngjiàng","vi":"thợ thủ công"},{"hanzi":"铁匠","pinyin":"tiějiàng","vi":"thợ rèn"},{"hanzi":"木工","pinyin":"mùgōng","vi":"nghề mộc"},{"hanzi":"家具","pinyin":"jiājù","vi":"đồ nội thất"}]},{"id":"木偶","hanzi":"木偶","pinyin":"mù'ǒu","meaning_vi":"con rối (gỗ); bù nhìn","explanation":"木 (mộc – gỗ) + 偶 (ngẫu – hình nhân) → hình nhân bằng gỗ, con rối; nghĩa bóng chỉ người bị kẻ khác điều khiển.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎎","examples":[{"type":"basic","zh":"孩子们爱看木偶戏。","pinyin":"Háizimen ài kàn mù'ǒuxì.","vi":"Bọn trẻ thích xem múa rối."},{"type":"simple","zh":"老艺人用细线灵活地操纵着木偶。","pinyin":"Lǎo yìrén yòng xìxiàn línghuó de cāozòngzhe mù'ǒu.","vi":"Người nghệ nhân già dùng dây mảnh điều khiển con rối rất linh hoạt."},{"type":"compound","zh":"他虽然是公司老板，但是只是别人手中的木偶。","pinyin":"Tā suīrán shì gōngsī lǎobǎn, dànshì zhǐshì bié rénshǒu zhōng de mù'ǒu.","vi":"Tuy là ông chủ công ty, nhưng anh ta chỉ là con rối trong tay người khác."}],"related":[{"hanzi":"木偶戏","pinyin":"mù'ǒuxì","vi":"múa rối"},{"hanzi":"傀儡","pinyin":"kuǐlěi","vi":"bù nhìn"},{"hanzi":"玩偶","pinyin":"wán'ǒu","vi":"búp bê"},{"hanzi":"操纵","pinyin":"cāozòng","vi":"điều khiển"}]},{"id":"目的地","hanzi":"目的地","pinyin":"mùdìdì","meaning_vi":"nơi đến, điểm đến","explanation":"目的 (mục đích) + 地 (địa – nơi chốn) → nơi muốn đi tới.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"📍","examples":[{"type":"basic","zh":"我们到目的地了。","pinyin":"Wǒmen dào mùdìdì le.","vi":"Chúng ta đến nơi rồi."},{"type":"simple","zh":"导航显示离目的地还有五公里。","pinyin":"Dǎoháng xiǎnshì lí mùdìdì háiyǒu wǔ gōnglǐ.","vi":"Định vị cho thấy còn năm cây số nữa là đến nơi."},{"type":"compound","zh":"一旦到达目的地，我就给你发消息。","pinyin":"Yídàn dàodá mùdìdì, wǒ jiù gěi nǐ fā xiāoxi.","vi":"Hễ đến nơi là mình nhắn tin cho cậu ngay."}],"related":[{"hanzi":"目的","pinyin":"mùdì","vi":"mục đích"},{"hanzi":"终点","pinyin":"zhōngdiǎn","vi":"điểm cuối"},{"hanzi":"出发地","pinyin":"chūfādì","vi":"nơi xuất phát"},{"hanzi":"旅途","pinyin":"lǚtú","vi":"chuyến đi"}]},{"id":"沐浴露","hanzi":"沐浴露","pinyin":"mùyùlù","meaning_vi":"sữa tắm","explanation":"沐浴 (mộc dục – tắm gội) + 露 (lộ – dạng nước sánh) → dung dịch dùng để tắm.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🧴","examples":[{"type":"basic","zh":"沐浴露用完了。","pinyin":"Mùyùlù yòng wánle.","vi":"Sữa tắm dùng hết rồi."},{"type":"simple","zh":"这款沐浴露有淡淡的柠檬香味。","pinyin":"Zhè kuǎn mùyùlù yǒu dàndàn de níngméng xiāngwèi.","vi":"Loại sữa tắm này có mùi chanh thoang thoảng."},{"type":"compound","zh":"因为我皮肤敏感，所以只用无香料的沐浴露。","pinyin":"Yīnwèi wǒ pífū mǐngǎn, suǒyǐ zhǐ yòng wú xiāngliào de mùyùlù.","vi":"Vì da tôi nhạy cảm nên tôi chỉ dùng sữa tắm không hương liệu."}],"related":[{"hanzi":"洗发水","pinyin":"xǐfàshuǐ","vi":"dầu gội"},{"hanzi":"香皂","pinyin":"xiāngzào","vi":"xà phòng thơm"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"tắm"},{"hanzi":"沐浴","pinyin":"mùyù","vi":"tắm gội"}]},{"id":"牧场","hanzi":"牧场","pinyin":"mùchǎng","meaning_vi":"đồng cỏ chăn nuôi, trang trại chăn nuôi","explanation":"牧 (mục – chăn thả) + 场 (trường – bãi) → bãi chăn thả gia súc, trang trại.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🐄","examples":[{"type":"basic","zh":"牧场上有很多牛。","pinyin":"Mùchǎng shang yǒu hěn duō niú.","vi":"Trên đồng cỏ có rất nhiều bò."},{"type":"simple","zh":"暑假我们去内蒙古的牧场骑马。","pinyin":"Shǔjià wǒmen qù Nèiměnggǔ de mùchǎng qímǎ.","vi":"Kỳ nghỉ hè chúng tôi đến trang trại ở Nội Mông cưỡi ngựa."},{"type":"compound","zh":"虽然牧场离城市很远，但是空气特别新鲜。","pinyin":"Suīrán mùchǎng lí chéngshì hěn yuǎn, dànshì kōngqì tèbié xīnxiān.","vi":"Tuy trang trại cách thành phố rất xa nhưng không khí đặc biệt trong lành."}],"related":[{"hanzi":"牧民","pinyin":"mùmín","vi":"dân chăn nuôi"},{"hanzi":"草原","pinyin":"cǎoyuán","vi":"thảo nguyên"},{"hanzi":"放牧","pinyin":"fàngmù","vi":"chăn thả"},{"hanzi":"农场","pinyin":"nóngchǎng","vi":"nông trại"}],"traditional":"牧場"},{"id":"牧民","hanzi":"牧民","pinyin":"mùmín","meaning_vi":"dân chăn nuôi, người chăn thả gia súc","explanation":"牧 (mục – chăn thả) + 民 (dân – người) → người sống bằng nghề chăn thả gia súc.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🐑","examples":[{"type":"basic","zh":"牧民很热情好客。","pinyin":"Mùmín hěn rèqíng hàokè.","vi":"Người chăn nuôi rất nhiệt tình hiếu khách."},{"type":"simple","zh":"草原上的牧民赶着羊群慢慢回家。","pinyin":"Cǎoyuán shang de mùmín gǎnzhe yángqún mànmàn huíjiā.","vi":"Người chăn nuôi trên thảo nguyên lùa đàn cừu chậm rãi về nhà."},{"type":"compound","zh":"每到冬天，牧民就要把牛羊赶到山下避寒。","pinyin":"Měi dào dōngtiān, mùmín jiùyào bǎ niúyáng gǎndào Shānxià bìhán.","vi":"Cứ đến mùa đông, dân chăn nuôi lại phải lùa bò cừu xuống núi tránh rét."}],"related":[{"hanzi":"牧场","pinyin":"mùchǎng","vi":"đồng cỏ"},{"hanzi":"放牧","pinyin":"fàngmù","vi":"chăn thả"},{"hanzi":"游牧","pinyin":"yóumù","vi":"du mục"},{"hanzi":"农民","pinyin":"nóngmín","vi":"nông dân"}]},{"id":"募捐","hanzi":"募捐","pinyin":"mùjuān","meaning_vi":"quyên góp, kêu gọi quyên góp","explanation":"募 (mộ – chiêu mộ, kêu gọi) + 捐 (quyên – góp) → kêu gọi mọi người quyên góp tiền của.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤲","examples":[{"type":"basic","zh":"学校正在募捐。","pinyin":"Xuéxiào zhèngzài mùjuān.","vi":"Trường đang quyên góp."},{"type":"simple","zh":"志愿者在街头为灾区儿童募捐。","pinyin":"Zhìyuànzhě zài jiētóu wèi zāiqū értóng mùjuān.","vi":"Tình nguyện viên quyên góp trên phố cho trẻ em vùng thiên tai."},{"type":"compound","zh":"如果大家都参加募捐，就能帮助更多病人。","pinyin":"Rúguǒ dàjiā dōu cānjiā mùjuān, jiù néng bāngzhù gèng duō bìngrén.","vi":"Nếu mọi người đều tham gia quyên góp thì có thể giúp được nhiều bệnh nhân hơn."}],"related":[{"hanzi":"捐款","pinyin":"juānkuǎn","vi":"quyên tiền"},{"hanzi":"捐赠","pinyin":"juānzèng","vi":"hiến tặng"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"招募","pinyin":"zhāomù","vi":"chiêu mộ"}]},{"id":"墓碑","hanzi":"墓碑","pinyin":"mùbēi","meaning_vi":"bia mộ","explanation":"墓 (mộ – mồ mả) + 碑 (bi – tấm bia đá) → tấm bia đá dựng trước mộ.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🪦","examples":[{"type":"basic","zh":"墓碑上刻着名字。","pinyin":"Mùbēi shang kèzhe míngzi.","vi":"Trên bia mộ có khắc tên."},{"type":"simple","zh":"清明节他去给奶奶的墓碑擦灰。","pinyin":"Qīngmíngjié tā qù gěi nǎinai de mùbēi cā huī.","vi":"Tiết Thanh minh anh ấy đi lau bụi bia mộ của bà nội."},{"type":"compound","zh":"虽然墓碑已经很旧了，但是上面的字还看得清。","pinyin":"Suīrán mùbēi yǐjīng hěn jiù le, dànshì shàngmian de zì hái kàn de qīng.","vi":"Tuy bia mộ đã rất cũ nhưng chữ trên đó vẫn còn đọc rõ."}],"related":[{"hanzi":"墓地","pinyin":"mùdì","vi":"nghĩa trang"},{"hanzi":"坟墓","pinyin":"fénmù","vi":"mồ mả"},{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"đài tưởng niệm"},{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"}]},{"id":"墓地","hanzi":"墓地","pinyin":"mùdì","meaning_vi":"nghĩa trang, nghĩa địa, khu mộ","explanation":"墓 (mộ – mồ mả) + 地 (địa – đất, nơi) → khu đất chôn cất người chết.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"⚰️","examples":[{"type":"basic","zh":"墓地在山坡上。","pinyin":"Mùdì zài shānpō shang.","vi":"Nghĩa trang nằm trên sườn đồi."},{"type":"simple","zh":"每年清明，全家人都去墓地祭拜祖先。","pinyin":"Měinián qīngmíng, quán jiārén dōu qù mùdì jìbài zǔxiān.","vi":"Thanh minh hằng năm, cả nhà đều ra nghĩa trang cúng viếng tổ tiên."},{"type":"compound","zh":"因为城市墓地越来越贵，所以有人选择海葬。","pinyin":"Yīnwèi chéngshì mùdì yuèláiyuè guì, suǒyǐ yǒurén xuǎnzé hǎizàng.","vi":"Vì đất nghĩa trang ở thành phố ngày càng đắt nên có người chọn thủy táng trên biển."}],"related":[{"hanzi":"坟墓","pinyin":"fénmù","vi":"mồ mả"},{"hanzi":"墓碑","pinyin":"mùbēi","vi":"bia mộ"},{"hanzi":"公墓","pinyin":"gōngmù","vi":"nghĩa trang công cộng"},{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"}]},{"id":"幕","hanzi":"幕","pinyin":"mù","meaning_vi":"màn, rèm; màn (kịch); màn hình","explanation":"幕 (mạc – tấm màn che) → tấm màn sân khấu, màn chiếu; còn làm lượng từ chỉ màn kịch hoặc một cảnh tượng.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"大幕慢慢拉开了。","pinyin":"Dà mù mànmàn lākāi le.","vi":"Tấm màn lớn từ từ kéo ra."},{"type":"simple","zh":"这部话剧一共有三幕，第二幕最精彩。","pinyin":"Zhè bù huàjù yí gòngyǒu sān mù, dì'èr mù zuì jīngcǎi.","vi":"Vở kịch này có tất cả ba màn, màn thứ hai hay nhất."},{"type":"compound","zh":"每当想起那一幕，我就忍不住流泪。","pinyin":"Měidāng xiǎngqǐ nà yí mù, wǒ jiù rěnbúzhù liúlèi.","vi":"Mỗi khi nhớ lại cảnh tượng ấy, tôi lại không cầm được nước mắt."}],"related":[{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"},{"hanzi":"开幕","pinyin":"kāimù","vi":"khai mạc"},{"hanzi":"闭幕","pinyin":"bìmù","vi":"bế mạc"},{"hanzi":"字幕","pinyin":"zìmù","vi":"phụ đề"}]},{"id":"幕后","hanzi":"幕后","pinyin":"mùhòu","meaning_vi":"hậu trường, sau màn, đằng sau (không công khai)","explanation":"幕 (mạc – màn sân khấu) + 后 (hậu – sau) → phía sau màn; nghĩa bóng là âm thầm, giấu mặt.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"他是幕后英雄。","pinyin":"Tā shì mùhòu yīngxióng.","vi":"Anh ấy là người hùng thầm lặng."},{"type":"simple","zh":"警方终于查出了这起案件的幕后黑手。","pinyin":"Jǐngfāng zhōngyú cháchūle zhè qǐ ànjiàn de mùhòu hēishǒu.","vi":"Cảnh sát cuối cùng đã tìm ra kẻ chủ mưu giấu mặt của vụ án này."},{"type":"compound","zh":"虽然观众看不到他们，但是幕后人员同样辛苦。","pinyin":"Suīrán guānzhòng kàn budào tāmen, dànshì mùhòu rényuán tóngyàng xīnkǔ.","vi":"Tuy khán giả không nhìn thấy họ, nhưng những người làm hậu trường cũng vất vả không kém."}],"related":[{"hanzi":"台前","pinyin":"táiqián","vi":"trước sân khấu"},{"hanzi":"后台","pinyin":"hòutái","vi":"hậu đài"},{"hanzi":"内幕","pinyin":"nèimù","vi":"nội tình"},{"hanzi":"幕后黑手","pinyin":"mùhòuhēishǒu","vi":"kẻ chủ mưu giấu mặt"}],"traditional":"幕後"},{"id":"穆斯林","hanzi":"穆斯林","pinyin":"Mùsīlín","meaning_vi":"người Hồi giáo, tín đồ Hồi giáo","explanation":"Phiên âm từ tiếng Ả Rập “Muslim” → tín đồ đạo Hồi (伊斯兰教).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🕌","examples":[{"type":"basic","zh":"他是穆斯林。","pinyin":"Tā shì Mùsīlín.","vi":"Anh ấy là người Hồi giáo."},{"type":"simple","zh":"这家餐厅专门为穆斯林顾客提供清真菜。","pinyin":"Zhè jiā cāntīng zhuānmén wèi Mùsīlín gùkè tígōng qīngzhēn cài.","vi":"Nhà hàng này chuyên phục vụ món Halal cho khách Hồi giáo."},{"type":"compound","zh":"因为穆斯林不吃猪肉，所以聚餐时要注意点菜。","pinyin":"Yīnwèi Mùsīlín bù chī zhūròu, suǒyǐ jùcān shí yào zhùyì diǎncài.","vi":"Vì người Hồi giáo không ăn thịt lợn nên khi ăn chung cần chú ý gọi món."}],"related":[{"hanzi":"伊斯兰教","pinyin":"Yīsīlánjiào","vi":"đạo Hồi"},{"hanzi":"清真","pinyin":"qīngzhēn","vi":"Halal"},{"hanzi":"清真寺","pinyin":"qīngzhēnsì","vi":"nhà thờ Hồi giáo"},{"hanzi":"信徒","pinyin":"xìntú","vi":"tín đồ"}]},{"id":"哪知道","hanzi":"哪知道","pinyin":"nǎzhīdào","meaning_vi":"ai ngờ, nào ngờ, đâu biết","explanation":"哪 (na – đâu) + 知道 (tri đạo – biết) → “đâu có biết”, dùng để nói sự việc xảy ra ngoài dự đoán.","hsk_level":"7-9","tags":["pho-tu","giao-tiep"],"image":"😲","examples":[{"type":"basic","zh":"哪知道他会来！","pinyin":"Nǎzhīdào tā huì lái!","vi":"Ai ngờ anh ấy lại đến!"},{"type":"simple","zh":"我以为天会晴，哪知道下午下起了大雨。","pinyin":"Wǒ yǐwéi tiān huì qíng, nǎzhīdào xiàwǔ xià qǐle dàyǔ.","vi":"Tôi tưởng trời sẽ nắng, nào ngờ buổi chiều đổ mưa to."},{"type":"compound","zh":"虽然准备得很充分，但是哪知道考试题目全变了。","pinyin":"Suīrán zhǔnbèi de hěn chōngfèn, dànshì nǎzhīdào kǎoshì tímù quán biàn le.","vi":"Tuy đã chuẩn bị rất kỹ, nhưng nào ngờ đề thi thay đổi hoàn toàn."}],"related":[{"hanzi":"没想到","pinyin":"méixiǎngdào","vi":"không ngờ"},{"hanzi":"谁知道","pinyin":"shéizhīdào","vi":"ai ngờ"},{"hanzi":"不料","pinyin":"búliào","vi":"chẳng ngờ"},{"hanzi":"竟然","pinyin":"jìngrán","vi":"vậy mà"}]},{"id":"乃","hanzi":"乃","pinyin":"nǎi","meaning_vi":"là, chính là; bèn, thế là","explanation":"乃 (nãi) → từ văn ngôn, nghĩa “là, chính là” hoặc “bèn, thế là”; thường dùng trong văn viết trang trọng, thành ngữ.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"失败乃成功之母。","pinyin":"Shībài nǎi chénggōng zhī mǔ.","vi":"Thất bại là mẹ thành công."},{"type":"simple","zh":"这座古桥乃是明朝时期修建的。","pinyin":"Zhè zuò gǔ qiáo nǎishì míngcháo shíqī xiūjiàn de.","vi":"Cây cầu cổ này chính là được xây vào thời nhà Minh."},{"type":"compound","zh":"因为诚信乃立身之本，所以他从不说谎。","pinyin":"Yīnwèi chéngxìn nǎi lìshēn zhī běn, suǒyǐ tā cóng bù shuōhuǎng.","vi":"Vì chữ tín là gốc rễ để lập thân nên anh ấy không bao giờ nói dối."}],"related":[{"hanzi":"乃至","pinyin":"nǎizhì","vi":"thậm chí"},{"hanzi":"即","pinyin":"jí","vi":"tức là"},{"hanzi":"便是","pinyin":"biànshì","vi":"chính là"},{"hanzi":"是","pinyin":"shì","vi":"là"}]},{"id":"乃至","hanzi":"乃至","pinyin":"nǎizhì","meaning_vi":"thậm chí, cho đến cả","explanation":"乃 (nãi – bèn) + 至 (chí – đến) → cho đến cả; dùng để nêu phạm vi hoặc mức độ tăng dần.","hsk_level":"7-9","tags":["lien-tu"],"image":"📈","examples":[{"type":"basic","zh":"全国乃至全球都关注。","pinyin":"Quánguó nǎizhì quánqiú dōu guānzhù.","vi":"Cả nước, thậm chí toàn cầu đều quan tâm."},{"type":"simple","zh":"这项发明影响了中国乃至世界的发展。","pinyin":"Zhè xiàng fāmíng yǐngxiǎngle Zhōngguó nǎizhì shìjiè de fāzhǎn.","vi":"Phát minh này đã ảnh hưởng đến sự phát triển của Trung Quốc, thậm chí cả thế giới."},{"type":"compound","zh":"如果不及时治疗，就会影响工作乃至生命。","pinyin":"Rúguǒ bù jíshí zhìliáo, jiù huì yǐngxiǎng gōngzuò nǎizhì shēngmìng.","vi":"Nếu không chữa trị kịp thời thì sẽ ảnh hưởng đến công việc, thậm chí cả tính mạng."}],"related":[{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"},{"hanzi":"以至","pinyin":"yǐzhì","vi":"đến nỗi"},{"hanzi":"直至","pinyin":"zhízhì","vi":"cho đến"},{"hanzi":"乃","pinyin":"nǎi","vi":"là, bèn"}]},{"id":"耐","hanzi":"耐","pinyin":"nài","meaning_vi":"chịu, chịu đựng, bền (với)","explanation":"耐 (nại – chịu đựng) → chịu được, bền với nóng, lạnh, mài mòn…; hay ghép thành 耐热, 耐用, 耐心.","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"这种植物很耐旱。","pinyin":"Zhè zhǒng zhíwù hěn nàihàn.","vi":"Loài cây này chịu hạn rất tốt."},{"type":"simple","zh":"这双登山鞋又轻又耐磨，很适合远足。","pinyin":"Zhè shuāng dēngshān xié yòu qīng yòu nàimó, hěn shìhé yuǎnzú.","vi":"Đôi giày leo núi này vừa nhẹ vừa bền, rất hợp đi bộ đường dài."},{"type":"compound","zh":"虽然这个锅有点重，但是特别耐用。","pinyin":"Suīrán zhè ge guō yǒudiǎn zhòng, dànshì tèbié nàiyòng.","vi":"Tuy cái nồi này hơi nặng nhưng cực kỳ bền."}],"related":[{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"},{"hanzi":"耐用","pinyin":"nàiyòng","vi":"bền"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"},{"hanzi":"耐烦","pinyin":"nàifán","vi":"chịu khó"}]},{"id":"耐性","hanzi":"耐性","pinyin":"nàixìng","meaning_vi":"tính kiên nhẫn, sự nhẫn nại","explanation":"耐 (nại – chịu đựng) + 性 (tính – tính cách) → tính chịu đựng, sự kiên nhẫn.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"⏳","examples":[{"type":"basic","zh":"他很有耐性。","pinyin":"Tā hěn yǒu nàixìng.","vi":"Anh ấy rất kiên nhẫn."},{"type":"simple","zh":"教小孩子写字需要很大的耐性。","pinyin":"Jiāo xiǎoháizi xiězì xūyào hěn dà de nàixìng.","vi":"Dạy trẻ nhỏ viết chữ cần rất nhiều kiên nhẫn."},{"type":"compound","zh":"因为等了两个小时，所以他渐渐失去了耐性。","pinyin":"Yīnwèi děngle liǎng gè xiǎoshí, suǒyǐ tā jiànjiàn shīqùle nàixìng.","vi":"Vì đã đợi hai tiếng đồng hồ nên anh ấy dần mất kiên nhẫn."}],"related":[{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"},{"hanzi":"性子","pinyin":"xìngzi","vi":"tính tình"},{"hanzi":"急躁","pinyin":"jízào","vi":"nóng nảy"}]},{"id":"南瓜","hanzi":"南瓜","pinyin":"nánguā","meaning_vi":"bí đỏ, bí ngô","explanation":"南 (nam – phương Nam) + 瓜 (qua – quả họ bầu bí) → loại bí quả to, ruột vàng, bí đỏ.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🎃","examples":[{"type":"basic","zh":"我喜欢喝南瓜粥。","pinyin":"Wǒ xǐhuan hē nánguā zhōu.","vi":"Tôi thích ăn cháo bí đỏ."},{"type":"simple","zh":"万圣节孩子们把南瓜刻成了灯笼。","pinyin":"Wànshèngjié háizimen bǎ nánguā kè chéngle dēnglong.","vi":"Dịp Halloween bọn trẻ khắc quả bí ngô thành đèn lồng."},{"type":"compound","zh":"虽然南瓜外皮很硬，但是蒸熟后又甜又软。","pinyin":"Suīrán nánguā wàipí hěn yìng, dànshì zhēng shú hòu yòu tián yòu ruǎn.","vi":"Tuy vỏ bí đỏ rất cứng nhưng hấp chín rồi thì vừa ngọt vừa mềm."}],"related":[{"hanzi":"冬瓜","pinyin":"dōngguā","vi":"bí đao"},{"hanzi":"西瓜","pinyin":"xīguā","vi":"dưa hấu"},{"hanzi":"黄瓜","pinyin":"huángguā","vi":"dưa chuột"},{"hanzi":"蔬菜","pinyin":"shūcài","vi":"rau củ"}]},{"id":"难处","hanzi":"难处","pinyin":"nánchu","meaning_vi":"khó khăn, nỗi khó xử, nỗi khổ","explanation":"难 (nan – khó) + 处 (xứ – chỗ) → chỗ khó, nỗi khó khăn riêng của mỗi người.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"😓","examples":[{"type":"basic","zh":"每个人都有难处。","pinyin":"Měigèrén dōu yǒu nánchu.","vi":"Ai cũng có nỗi khó khăn riêng."},{"type":"simple","zh":"有什么难处你尽管跟我说。","pinyin":"Yǒu shénme nánchu nǐ jǐnguǎn gēn wǒ shuō.","vi":"Có khó khăn gì cậu cứ nói với mình."},{"type":"compound","zh":"如果你有难处，就别不好意思开口。","pinyin":"Rúguǒ nǐ yǒu nánchu, jiù bié bù hǎoyìsi kāikǒu.","vi":"Nếu bạn có khó khăn thì đừng ngại mở lời."}],"related":[{"hanzi":"困难","pinyin":"kùnnan","vi":"khó khăn"},{"hanzi":"苦衷","pinyin":"kǔzhōng","vi":"nỗi khổ tâm"},{"hanzi":"难题","pinyin":"nántí","vi":"vấn đề khó"},{"hanzi":"好处","pinyin":"hǎochu","vi":"cái lợi"}],"traditional":"難處"},{"id":"难得一见","hanzi":"难得一见","pinyin":"nándé-yíjiàn","meaning_vi":"hiếm thấy, hiếm khi gặp","explanation":"难得 (nan đắc – khó có được) + 一见 (nhất kiến – thấy một lần) → khó mà thấy được, cực kỳ hiếm.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌠","examples":[{"type":"basic","zh":"这是难得一见的美景。","pinyin":"Zhè shì nándéyíjiàn de měijǐng.","vi":"Đây là cảnh đẹp hiếm thấy."},{"type":"simple","zh":"昨晚天空出现了难得一见的流星雨。","pinyin":"Zuówǎn tiānkōng chūxiànle nándéyíjiàn de liúxīngyǔ.","vi":"Tối qua trên trời xuất hiện trận mưa sao băng hiếm thấy."},{"type":"compound","zh":"因为这种鸟难得一见，所以摄影师等了一整天。","pinyin":"Yīnwèi zhè zhǒng niǎo nándéyíjiàn, suǒyǐ shèyǐngshī děngle yìzhěngtiān.","vi":"Vì loài chim này rất hiếm gặp nên nhiếp ảnh gia đã chờ suốt cả ngày."}],"related":[{"hanzi":"难得","pinyin":"nándé","vi":"hiếm có"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"少见","pinyin":"shǎojiàn","vi":"ít thấy"},{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"quá quen thuộc"}],"traditional":"難得一見"},{"id":"难点","hanzi":"难点","pinyin":"nándiǎn","meaning_vi":"điểm khó, chỗ khó","explanation":"难 (nan – khó) + 点 (điểm) → điểm khó nhất cần vượt qua hoặc giải quyết.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🧩","examples":[{"type":"basic","zh":"这课的难点是语法。","pinyin":"Zhè kè de nándiǎn shì yǔfǎ.","vi":"Điểm khó của bài này là ngữ pháp."},{"type":"simple","zh":"老师把这道题的难点又讲了一遍。","pinyin":"Lǎoshī bǎ zhè dào tí de nándiǎn yòu jiǎngle yíbiàn.","vi":"Thầy giáo giảng lại một lần nữa chỗ khó của bài này."},{"type":"compound","zh":"只要突破了这个技术难点，项目就能按时完成。","pinyin":"Zhǐyào tūpòle zhè ge jìshù nándiǎn, xiàngmù jiù néng ànshí wánchéng.","vi":"Chỉ cần vượt qua điểm khó kỹ thuật này, dự án sẽ hoàn thành đúng hạn."}],"related":[{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"难题","pinyin":"nántí","vi":"bài toán khó"},{"hanzi":"要点","pinyin":"yàodiǎn","vi":"điểm chính"},{"hanzi":"疑点","pinyin":"yídiǎn","vi":"điểm nghi vấn"}],"traditional":"難點"},{"id":"难说","hanzi":"难说","pinyin":"nánshuō","meaning_vi":"khó nói, khó đoán, chưa chắc","explanation":"难 (nan – khó) + 说 (thuyết – nói) → khó nói trước, khó khẳng định; cũng có nghĩa khó mở lời.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤷","examples":[{"type":"basic","zh":"结果还很难说。","pinyin":"Jiéguǒ hái hěn nánshuō.","vi":"Kết quả vẫn còn khó nói."},{"type":"simple","zh":"明天会不会下雨，现在还真难说。","pinyin":"Míngtiān huìbuhuì xiàyǔ, xiànzài hái zhēn nánshuō.","vi":"Mai có mưa hay không, giờ thật khó đoán."},{"type":"compound","zh":"虽然他平时成绩很好，但是这次能不能考上还难说。","pinyin":"Suīrán tā píngshí chéngjì hěn hǎo, dànshì zhè cì néng bu néng kǎoshàng hái nánshuō.","vi":"Tuy bình thường cậu ấy học rất giỏi, nhưng lần này có đỗ hay không vẫn chưa chắc."}],"related":[{"hanzi":"说不定","pinyin":"shuōbudìng","vi":"không chừng"},{"hanzi":"不好说","pinyin":"bùhǎoshuō","vi":"khó nói"},{"hanzi":"难讲","pinyin":"nánjiǎng","vi":"khó nói"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"chắc chắn"}],"traditional":"難說"},{"id":"难为情","hanzi":"难为情","pinyin":"nánwéiqíng","meaning_vi":"ngượng ngùng, xấu hổ, ngại","explanation":"难 (nan – khó) + 为情 (vi tình – giữ thể diện) → khó giữ thể diện, cảm thấy ngượng ngùng.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"她觉得很难为情。","pinyin":"Tā juéde hěn nánwéiqíng.","vi":"Cô ấy cảm thấy rất ngượng."},{"type":"simple","zh":"被老师当众表扬，他难为情地低下了头。","pinyin":"Bèi lǎoshī dāngzhòng biǎoyáng, tā nánwéiqíng de dīxiàle tóu.","vi":"Được thầy khen trước lớp, cậu ấy ngượng ngùng cúi đầu."},{"type":"compound","zh":"虽然说错了话有点难为情，但是他马上道了歉。","pinyin":"Suīrán shuō cuòle huà yǒudiǎn nánwéiqíng, dànshì tā mǎshàng dàole qiàn.","vi":"Tuy lỡ lời có hơi ngại, nhưng anh ấy đã xin lỗi ngay."}],"related":[{"hanzi":"害羞","pinyin":"hàixiū","vi":"e thẹn"},{"hanzi":"不好意思","pinyin":"bùhǎoyìsi","vi":"ngại ngùng"},{"hanzi":"尴尬","pinyin":"gāngà","vi":"khó xử"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"}],"traditional":"難為情"},{"id":"难以想象","hanzi":"难以想象","pinyin":"nányǐ-xiǎngxiàng","meaning_vi":"khó mà tưởng tượng, không thể tưởng tượng nổi","explanation":"难以 (nan dĩ – khó mà) + 想象 (tưởng tượng) → khó có thể hình dung nổi.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"🤯","examples":[{"type":"basic","zh":"这简直难以想象。","pinyin":"Zhè jiǎnzhí nányǐxiǎngxiàng.","vi":"Điều này quả thật khó mà tưởng tượng."},{"type":"simple","zh":"十年前，手机支付还是难以想象的事。","pinyin":"Shí niánqián, shǒujī zhīfù háishi nányǐxiǎngxiàng de shì.","vi":"Mười năm trước, thanh toán bằng điện thoại vẫn là chuyện khó tưởng tượng."},{"type":"compound","zh":"如果没有互联网，我们的生活就难以想象。","pinyin":"Rúguǒ méiyǒu Hùliánwǎng, wǒmen de shēnghuó jiù nányǐxiǎngxiàng.","vi":"Nếu không có Internet thì cuộc sống của chúng ta thật khó hình dung."}],"related":[{"hanzi":"想象","pinyin":"xiǎngxiàng","vi":"tưởng tượng"},{"hanzi":"难以置信","pinyin":"nányǐzhìxìn","vi":"khó tin"},{"hanzi":"不可思议","pinyin":"bùkěsīyì","vi":"không thể tin nổi"},{"hanzi":"难以","pinyin":"nányǐ","vi":"khó mà"}],"traditional":"難以想象"},{"id":"难以置信","hanzi":"难以置信","pinyin":"nányǐ-zhìxìn","meaning_vi":"khó tin, không thể tin được","explanation":"难以 (nan dĩ – khó mà) + 置信 (trí tín – đặt lòng tin) → khó mà tin được.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"😮","examples":[{"type":"basic","zh":"这消息令人难以置信。","pinyin":"Zhè xiāoxi lìngrén nányǐzhìxìn.","vi":"Tin này thật khó tin."},{"type":"simple","zh":"他一个人搬动了这台冰箱，真是难以置信。","pinyin":"Tā yígèrén bāndòngle zhè tái bīngxiāng, zhēn shì nányǐzhìxìn.","vi":"Anh ấy một mình khiêng được cái tủ lạnh này, thật không thể tin nổi."},{"type":"compound","zh":"虽然结果难以置信，但是数据确实没有错。","pinyin":"Suīrán jiéguǒ nányǐzhìxìn, dànshì shùjù quèshí méiyǒu cuò.","vi":"Tuy kết quả khó tin nhưng số liệu thực sự không sai."}],"related":[{"hanzi":"不可思议","pinyin":"bùkěsīyì","vi":"khó tin nổi"},{"hanzi":"难以想象","pinyin":"nányǐxiǎngxiàng","vi":"khó tưởng tượng"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"tin tưởng"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"}],"traditional":"難以置信"},{"id":"挠","hanzi":"挠","pinyin":"náo","meaning_vi":"gãi, cào; cản trở","explanation":"挠 (nạo – gãi) → dùng móng tay gãi nhẹ; nghĩa khác là cản trở, khuất phục (như trong 不屈不挠).","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"🤚","examples":[{"type":"basic","zh":"他挠了挠头。","pinyin":"Tā náole náotóu.","vi":"Anh ấy gãi gãi đầu."},{"type":"simple","zh":"小猫用爪子挠破了新买的沙发。","pinyin":"Xiǎomāo yòng zhuǎzi náo pòle xīn mǎi de shāfā.","vi":"Mèo con dùng móng cào rách chiếc sofa mới mua."},{"type":"compound","zh":"虽然被蚊子咬的地方很痒，但是千万别用手挠。","pinyin":"Suīrán bèi wénzi yǎo de dìfang hěn yǎng, dànshì qiānwàn bié yòng shǒu náo.","vi":"Tuy chỗ muỗi đốt rất ngứa nhưng tuyệt đối đừng lấy tay gãi."}],"related":[{"hanzi":"抓","pinyin":"zhuā","vi":"gãi, cào"},{"hanzi":"痒","pinyin":"yǎng","vi":"ngứa"},{"hanzi":"挠痒痒","pinyin":"náoyǎngyang","vi":"gãi ngứa"},{"hanzi":"不屈不挠","pinyin":"bùqūbùnáo","vi":"kiên cường bất khuất"}],"traditional":"撓"},{"id":"恼羞成怒","hanzi":"恼羞成怒","pinyin":"nǎoxiū-chéngnù","meaning_vi":"thẹn quá hóa giận","explanation":"恼 (não – bực) + 羞 (tu – thẹn) + 成 (thành – trở thành) + 怒 (nộ – giận) → vì xấu hổ, bực bội mà nổi giận.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😡","examples":[{"type":"basic","zh":"他恼羞成怒了。","pinyin":"Tā nǎoxiūchéngnù le.","vi":"Anh ta thẹn quá hóa giận."},{"type":"simple","zh":"被人揭穿谎言后，他恼羞成怒地摔门走了。","pinyin":"Bèi rén jiēchuān huǎngyán hòu, tā nǎoxiūchéngnù de shuāimén zǒu le.","vi":"Bị vạch trần lời nói dối, anh ta thẹn quá hóa giận đóng sầm cửa bỏ đi."},{"type":"compound","zh":"因为当众被批评，所以他恼羞成怒，跟经理吵了起来。","pinyin":"Yīnwèi dāngzhòng bèi pīpíng, suǒyǐ tā nǎoxiūchéngnù, gēn jīnglǐ chǎole qǐlái.","vi":"Vì bị phê bình trước mặt mọi người nên anh ta thẹn quá hóa giận, cãi nhau với giám đốc."}],"related":[{"hanzi":"恼火","pinyin":"nǎohuǒ","vi":"bực tức"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"xấu hổ"},{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"气急败坏","pinyin":"qìjíbàihuài","vi":"tức tối cuống cuồng"}],"traditional":"惱羞成怒"},{"id":"脑筋","hanzi":"脑筋","pinyin":"nǎojīn","meaning_vi":"đầu óc, trí óc; cách nghĩ","explanation":"脑 (não – bộ não) + 筋 (cân – gân) → bộ óc, khả năng suy nghĩ; cũng chỉ lối tư duy, quan niệm.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"这孩子脑筋很灵。","pinyin":"Zhè háizi nǎojīn hěn líng.","vi":"Đứa trẻ này đầu óc rất nhanh nhạy."},{"type":"simple","zh":"为了解决这个问题，大家都动了不少脑筋。","pinyin":"Wèile jiějué zhè ge wèntí, dàjiā dōu dòngle bùshǎo nǎojīn.","vi":"Để giải quyết vấn đề này, mọi người đã phải động não không ít."},{"type":"compound","zh":"如果你总是用老脑筋看问题，就跟不上时代了。","pinyin":"Rúguǒ nǐ zǒngshì yòng lǎo nǎojīn kàn wèntí, jiù gēnbushàng shídài le.","vi":"Nếu cậu cứ nhìn vấn đề bằng lối nghĩ cũ thì sẽ không theo kịp thời đại."}],"related":[{"hanzi":"动脑筋","pinyin":"dòngnǎojīn","vi":"suy nghĩ, động não"},{"hanzi":"伤脑筋","pinyin":"shāngnǎojīn","vi":"đau đầu"},{"hanzi":"头脑","pinyin":"tóunǎo","vi":"đầu óc"},{"hanzi":"脑子","pinyin":"nǎozi","vi":"bộ óc"}],"traditional":"腦筋"},{"id":"闹事","hanzi":"闹事","pinyin":"nàoshì","meaning_vi":"gây chuyện, gây rối","explanation":"闹 (náo – làm ầm ĩ) + 事 (sự – việc) → làm ầm lên, gây rối trật tự.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚨","examples":[{"type":"basic","zh":"有人在门口闹事。","pinyin":"Yǒurén zài ménkǒu nàoshì.","vi":"Có người gây rối ở cổng."},{"type":"simple","zh":"几个喝醉的年轻人在酒吧里闹事。","pinyin":"Jǐ gè hēzuì de niánqīngrén zài jiǔbā lǐ nàoshì.","vi":"Mấy thanh niên say rượu gây rối trong quán bar."},{"type":"compound","zh":"如果再有人闹事，保安就会马上报警。","pinyin":"Rúguǒ zài yǒurén nàoshì, bǎo'ān jiù huì mǎshàng bàojǐng.","vi":"Nếu còn ai gây chuyện nữa, bảo vệ sẽ báo cảnh sát ngay."}],"related":[{"hanzi":"惹事","pinyin":"rěshì","vi":"gây sự"},{"hanzi":"捣乱","pinyin":"dǎoluàn","vi":"quấy rối"},{"hanzi":"滋事","pinyin":"zīshì","vi":"gây chuyện"},{"hanzi":"闹","pinyin":"nào","vi":"làm ầm ĩ"}],"traditional":"鬧事"},{"id":"闹着玩儿","hanzi":"闹着玩儿","pinyin":"nàozhewánr","meaning_vi":"đùa giỡn, nói chơi, làm cho vui","explanation":"闹 (náo – đùa nghịch) + 着 + 玩儿 (chơi) → đùa cho vui; hay dùng phủ định 不是闹着玩儿的 = không phải chuyện đùa.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😜","examples":[{"type":"basic","zh":"我是闹着玩儿的。","pinyin":"Wǒ shì nàozhewánr de.","vi":"Tôi chỉ đùa thôi."},{"type":"simple","zh":"开车可不是闹着玩儿的，一定要小心。","pinyin":"Kāichē kěbúshì nàozhewánr de, yídìngyào xiǎoxīn.","vi":"Lái xe không phải chuyện đùa đâu, nhất định phải cẩn thận."},{"type":"compound","zh":"虽然他只是闹着玩儿，但是小妹妹当真了。","pinyin":"Suīrán tā zhǐshì nàozhewánr, dànshì xiǎomèimei dàngzhēn le.","vi":"Tuy anh ấy chỉ đùa thôi nhưng em gái nhỏ lại tưởng thật."}],"related":[{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"đùa"},{"hanzi":"玩笑","pinyin":"wánxiào","vi":"trò đùa"},{"hanzi":"当真","pinyin":"dàngzhēn","vi":"tưởng thật"},{"hanzi":"逗","pinyin":"dòu","vi":"trêu"}],"traditional":"鬧著玩兒"},{"id":"呐喊","hanzi":"呐喊","pinyin":"nàhǎn","meaning_vi":"hò hét, reo hò, hô hào","explanation":"呐 (nột – kêu to) + 喊 (hám – hét) → hò reo lớn tiếng để cổ vũ hoặc kêu gọi.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"📣","examples":[{"type":"basic","zh":"球迷们大声呐喊。","pinyin":"Qiúmímen dàshēng nàhǎn.","vi":"Các cổ động viên hò hét vang dội."},{"type":"simple","zh":"观众在看台上为运动员呐喊助威。","pinyin":"Guānzhòng zài kàntái shang wèi yùndòngyuán nàhǎn zhùwēi.","vi":"Khán giả trên khán đài hò reo cổ vũ cho vận động viên."},{"type":"compound","zh":"虽然嗓子都喊哑了，但是他还在为队友呐喊。","pinyin":"Suīrán sǎngzi dōu hǎn yǎ le, dànshì tā hái zài wèi duìyǒu nàhǎn.","vi":"Tuy đã khản cả giọng nhưng anh ấy vẫn hò reo cổ vũ đồng đội."}],"related":[{"hanzi":"喊叫","pinyin":"hǎnjiào","vi":"la hét"},{"hanzi":"欢呼","pinyin":"huānhū","vi":"reo hò"},{"hanzi":"助威","pinyin":"zhùwēi","vi":"cổ vũ"},{"hanzi":"呼喊","pinyin":"hūhǎn","vi":"kêu gọi"}],"traditional":"吶喊"},{"id":"内存","hanzi":"内存","pinyin":"nèicún","meaning_vi":"bộ nhớ trong, RAM","explanation":"内 (nội – bên trong) + 存 (tồn – lưu giữ) → bộ nhớ trong của máy tính, điện thoại.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💾","examples":[{"type":"basic","zh":"手机内存不够了。","pinyin":"Shǒujī nèicún búgòu le.","vi":"Bộ nhớ điện thoại không đủ rồi."},{"type":"simple","zh":"打开太多程序会占用大量内存。","pinyin":"Dǎkāi tài duō chéngxù huì zhànyòng dàliàng nèicún.","vi":"Mở quá nhiều chương trình sẽ chiếm rất nhiều bộ nhớ."},{"type":"compound","zh":"如果手机内存满了，就拍不了照片了。","pinyin":"Rúguǒ shǒujī nèicún mǎn le, jiù pāi buliǎo zhàopiàn le.","vi":"Nếu bộ nhớ điện thoại đầy thì không chụp ảnh được nữa."}],"related":[{"hanzi":"硬盘","pinyin":"yìngpán","vi":"ổ cứng"},{"hanzi":"存储","pinyin":"cúnchǔ","vi":"lưu trữ"},{"hanzi":"容量","pinyin":"róngliàng","vi":"dung lượng"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"máy tính"}],"traditional":"內存"},{"id":"内阁","hanzi":"内阁","pinyin":"nèigé","meaning_vi":"nội các","explanation":"内 (nội – bên trong) + 阁 (các – lầu gác) → vốn là cơ quan trong cung vua; nay chỉ nội các gồm thủ tướng và các bộ trưởng.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"新内阁成立了。","pinyin":"Xīn nèigé chénglì le.","vi":"Nội các mới đã được thành lập."},{"type":"simple","zh":"首相宣布对内阁进行大规模改组。","pinyin":"Shǒuxiàng xuānbù duì nèigé jìnxíng dàguīmó gǎizǔ.","vi":"Thủ tướng tuyên bố cải tổ nội các trên quy mô lớn."},{"type":"compound","zh":"因为丑闻不断，所以整个内阁被迫辞职。","pinyin":"Yīnwèi chǒuwén búduàn, suǒyǐ zhěnggè nèigé bèipò cízhí.","vi":"Vì bê bối liên tiếp nên toàn bộ nội các buộc phải từ chức."}],"related":[{"hanzi":"首相","pinyin":"shǒuxiàng","vi":"thủ tướng"},{"hanzi":"政府","pinyin":"zhèngfǔ","vi":"chính phủ"},{"hanzi":"部长","pinyin":"bùzhǎng","vi":"bộ trưởng"},{"hanzi":"组阁","pinyin":"zǔgé","vi":"lập nội các"}],"traditional":"內閣"},{"id":"内向","hanzi":"内向","pinyin":"nèixiàng","meaning_vi":"hướng nội, khép kín, ít nói","explanation":"内 (nội – bên trong) + 向 (hướng) → tính cách hướng vào trong, ít nói, ngại giao tiếp.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🤐","examples":[{"type":"basic","zh":"她性格比较内向。","pinyin":"Tā xìnggé bǐjiào nèixiàng.","vi":"Tính cô ấy khá hướng nội."},{"type":"simple","zh":"内向的他在聚会上总是坐在角落里。","pinyin":"Nèixiàng de tā zài jùhuì shang zǒngshì zuò zài jiǎoluò lǐ.","vi":"Vốn hướng nội, ở các buổi tiệc anh ấy luôn ngồi trong góc."},{"type":"compound","zh":"虽然他很内向，但是跟熟人在一起时话很多。","pinyin":"Suīrán tā hěn nèixiàng, dànshì gēn shúrén zài yìqǐ shí huà hěn duō.","vi":"Tuy anh ấy rất hướng nội, nhưng khi ở cùng người quen thì nói rất nhiều."}],"related":[{"hanzi":"外向","pinyin":"wàixiàng","vi":"hướng ngoại"},{"hanzi":"性格","pinyin":"xìnggé","vi":"tính cách"},{"hanzi":"腼腆","pinyin":"miǎntiǎn","vi":"bẽn lẽn"},{"hanzi":"孤僻","pinyin":"gūpì","vi":"khó gần"}],"traditional":"內向"},{"id":"能人","hanzi":"能人","pinyin":"néngrén","meaning_vi":"người tài, người giỏi","explanation":"能 (năng – có tài) + 人 (nhân – người) → người có năng lực, giỏi giang.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🦸","examples":[{"type":"basic","zh":"他是村里的能人。","pinyin":"Tā shì cūnlǐ de néngrén.","vi":"Anh ấy là người tài giỏi trong làng."},{"type":"simple","zh":"公司请来一位能人负责新项目。","pinyin":"Gōngsī qǐng lái yí wèi néngrén fùzé xīn xiàngmù.","vi":"Công ty mời về một người tài phụ trách dự án mới."},{"type":"compound","zh":"虽然团队里能人很多，但是缺少一个好领导。","pinyin":"Suīrán tuánduì lǐ néngrén hěn duō, dànshì quēshǎo yí gè hǎo lǐngdǎo.","vi":"Tuy trong nhóm có nhiều người giỏi nhưng lại thiếu một người lãnh đạo tốt."}],"related":[{"hanzi":"能手","pinyin":"néngshǒu","vi":"người thạo việc"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"能干","pinyin":"nénggàn","vi":"giỏi giang"},{"hanzi":"高手","pinyin":"gāoshǒu","vi":"cao thủ"}]},{"id":"尼龙","hanzi":"尼龙","pinyin":"nílóng","meaning_vi":"ni lông, nylon","explanation":"Phiên âm từ tiếng Anh “nylon” → loại sợi tổng hợp nhẹ, bền, dùng làm vải, dây.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧵","examples":[{"type":"basic","zh":"这是尼龙绳。","pinyin":"Zhè shì nílóng shéng.","vi":"Đây là dây ni lông."},{"type":"simple","zh":"这个尼龙背包又轻又防水。","pinyin":"Zhè ge nílóng bèibāo yòu qīng yòu fángshuǐ.","vi":"Chiếc ba lô nylon này vừa nhẹ vừa chống nước."},{"type":"compound","zh":"虽然尼龙袜子很结实，但是穿久了脚不透气。","pinyin":"Suīrán nílóng wàzi hěn jiēshi, dànshì chuān jiǔle jiǎo bú tòuqì.","vi":"Tuy tất nylon rất bền nhưng đi lâu chân bị bí."}],"related":[{"hanzi":"纤维","pinyin":"xiānwéi","vi":"sợi"},{"hanzi":"塑料","pinyin":"sùliào","vi":"nhựa"},{"hanzi":"布料","pinyin":"bùliào","vi":"vải"},{"hanzi":"棉","pinyin":"mián","vi":"bông"}],"traditional":"尼龍"},{"id":"泥潭","hanzi":"泥潭","pinyin":"nítán","meaning_vi":"vũng bùn, vũng lầy; (bóng) tình thế bế tắc","explanation":"泥 (nê – bùn) + 潭 (đàm – vũng sâu) → vũng bùn lầy; nghĩa bóng chỉ hoàn cảnh khó thoát ra.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🕳️","examples":[{"type":"basic","zh":"车陷进了泥潭。","pinyin":"Chē xiàn jìnle nítán.","vi":"Xe bị sa xuống vũng lầy."},{"type":"simple","zh":"这家公司已经陷入了债务的泥潭。","pinyin":"Zhè jiā gōngsī yǐjīng xiànrùle zhàiwù de nítán.","vi":"Công ty này đã sa vào vũng lầy nợ nần."},{"type":"compound","zh":"一旦陷进赌博的泥潭，就很难再爬出来。","pinyin":"Yídàn xiàn jìn dǔbó de nítán, jiù hěn nán zài pá chūlái.","vi":"Một khi đã sa vào vũng lầy cờ bạc thì rất khó thoát ra."}],"related":[{"hanzi":"泥沼","pinyin":"nízhǎo","vi":"đầm lầy"},{"hanzi":"泥土","pinyin":"nítǔ","vi":"bùn đất"},{"hanzi":"困境","pinyin":"kùnjìng","vi":"cảnh khốn khó"},{"hanzi":"陷入","pinyin":"xiànrù","vi":"sa vào"}]},{"id":"泥土","hanzi":"泥土","pinyin":"nítǔ","meaning_vi":"bùn đất, đất","explanation":"泥 (nê – bùn) + 土 (thổ – đất) → đất, bùn đất.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🟫","examples":[{"type":"basic","zh":"鞋上全是泥土。","pinyin":"Xié shang quán shì nítǔ.","vi":"Giày dính đầy bùn đất."},{"type":"simple","zh":"雨后的空气里有一股泥土的清香。","pinyin":"Yǔ hòu de kōngqì lǐ yǒu yì gǔ nítǔ de qīngxiāng.","vi":"Không khí sau mưa thoang thoảng mùi thơm của đất."},{"type":"compound","zh":"因为这里的泥土很肥沃，所以庄稼长得特别好。","pinyin":"Yīnwèi zhèlǐ de nítǔ hěn féiwò, suǒyǐ zhuāngjia zhǎngde tèbié hǎo.","vi":"Vì đất ở đây rất màu mỡ nên hoa màu mọc rất tốt."}],"related":[{"hanzi":"土壤","pinyin":"tǔrǎng","vi":"thổ nhưỡng"},{"hanzi":"泥巴","pinyin":"níbā","vi":"bùn"},{"hanzi":"尘土","pinyin":"chéntǔ","vi":"bụi đất"},{"hanzi":"沙土","pinyin":"shātǔ","vi":"đất cát"}]},{"id":"拟","hanzi":"拟","pinyin":"nǐ","meaning_vi":"dự định; soạn thảo, phác thảo; mô phỏng","explanation":"拟 (nghĩ – dự tính, phỏng theo) → dự định làm gì (văn viết); soạn thảo văn bản (拟稿); mô phỏng (模拟).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📝","examples":[{"type":"basic","zh":"请先拟个提纲。","pinyin":"Qǐng xiān nǐ gè tígāng.","vi":"Hãy phác thảo một dàn ý trước."},{"type":"simple","zh":"公司拟于下个月在河内开设分店。","pinyin":"Gōngsī nǐ yú xiàgeyuè zài Hénèi kāishè fēndiàn.","vi":"Công ty dự định mở chi nhánh tại Hà Nội vào tháng sau."},{"type":"compound","zh":"合同拟好以后，就请律师再检查一遍。","pinyin":"Hétong nǐ hǎo yǐhòu, jiù qǐng lǜshī zài jiǎnchá yíbiàn.","vi":"Soạn xong hợp đồng thì nhờ luật sư kiểm tra lại một lượt."}],"related":[{"hanzi":"拟定","pinyin":"nǐdìng","vi":"soạn định"},{"hanzi":"草拟","pinyin":"cǎonǐ","vi":"phác thảo"},{"hanzi":"模拟","pinyin":"mónǐ","vi":"mô phỏng"},{"hanzi":"打算","pinyin":"dǎsuan","vi":"dự định"}],"traditional":"擬"},{"id":"逆","hanzi":"逆","pinyin":"nì","meaning_vi":"ngược, trái, nghịch","explanation":"逆 (nghịch – ngược lại) → đi ngược chiều, trái với; thường gặp trong 逆风, 逆时针, 叛逆.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"我们逆风骑车。","pinyin":"Wǒmen nìfēng qíchē.","vi":"Chúng tôi đạp xe ngược gió."},{"type":"simple","zh":"请按逆时针方向拧开瓶盖。","pinyin":"Qǐng àn nìshízhēn fāngxiàng nǐngkāi pínggài.","vi":"Hãy vặn nắp chai theo chiều ngược kim đồng hồ."},{"type":"compound","zh":"即使是逆水行舟，我们也要坚持到底。","pinyin":"Jíshǐ shì nìshuǐxíngzhōu, wǒmen yě yào jiānchí dàodǐ.","vi":"Dù là chèo thuyền ngược nước, chúng ta cũng phải kiên trì đến cùng."}],"related":[{"hanzi":"顺","pinyin":"shùn","vi":"thuận"},{"hanzi":"逆风","pinyin":"nìfēng","vi":"ngược gió"},{"hanzi":"逆境","pinyin":"nìjìng","vi":"nghịch cảnh"},{"hanzi":"叛逆","pinyin":"pànnì","vi":"nổi loạn"}]},{"id":"匿名","hanzi":"匿名","pinyin":"nìmíng","meaning_vi":"giấu tên, nặc danh","explanation":"匿 (nặc – giấu) + 名 (danh – tên) → giấu tên, không để lộ danh tính.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🕵️","examples":[{"type":"basic","zh":"他匿名捐了一笔钱。","pinyin":"Tā nìmíng juānle yìbǐqián.","vi":"Anh ấy quyên góp một khoản tiền giấu tên."},{"type":"simple","zh":"警方收到了一封匿名举报信。","pinyin":"Jǐngfāng shōudàole yì fēng nìmíng jǔbào xìn.","vi":"Cảnh sát nhận được một lá thư tố giác nặc danh."},{"type":"compound","zh":"因为问卷是匿名的，所以大家都敢说真话。","pinyin":"Yīnwèi wènjuàn shì nìmíng de, suǒyǐ dàjiā dōu gǎn shuō zhēn huà.","vi":"Vì phiếu khảo sát là ẩn danh nên mọi người đều dám nói thật."}],"related":[{"hanzi":"化名","pinyin":"huàmíng","vi":"tên giả"},{"hanzi":"实名","pinyin":"shímíng","vi":"tên thật"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"},{"hanzi":"署名","pinyin":"shǔmíng","vi":"ký tên"}]},{"id":"年限","hanzi":"年限","pinyin":"niánxiàn","meaning_vi":"thời hạn (số năm), niên hạn","explanation":"年 (niên – năm) + 限 (hạn – giới hạn) → số năm được quy định, thời hạn tính bằng năm.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"合同年限是三年。","pinyin":"Hétong niánxiàn shì sān nián.","vi":"Thời hạn hợp đồng là ba năm."},{"type":"simple","zh":"这台机器的使用年限大约是十年。","pinyin":"Zhè tái jīqì de shǐyòng niánxiàn dàyuē shì shí nián.","vi":"Tuổi thọ sử dụng của chiếc máy này khoảng mười năm."},{"type":"compound","zh":"如果工作年限不满五年，就不能申请这个职位。","pinyin":"Rúguǒ gōngzuò niánxiàn bùmǎn wǔ nián, jiù bù néng shēnqǐng zhè ge zhíwèi.","vi":"Nếu số năm kinh nghiệm chưa đủ năm năm thì không thể ứng tuyển vị trí này."}],"related":[{"hanzi":"期限","pinyin":"qīxiàn","vi":"thời hạn"},{"hanzi":"工龄","pinyin":"gōnglíng","vi":"thâm niên"},{"hanzi":"年头","pinyin":"niántóu","vi":"số năm"},{"hanzi":"有效期","pinyin":"yǒuxiàoqī","vi":"thời hạn hiệu lực"}]},{"id":"年薪","hanzi":"年薪","pinyin":"niánxīn","meaning_vi":"lương năm, lương hằng năm","explanation":"年 (niên – năm) + 薪 (tân – lương bổng) → tổng tiền lương trong một năm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"他的年薪很高。","pinyin":"Tā de niánxīn hěn gāo.","vi":"Lương năm của anh ấy rất cao."},{"type":"simple","zh":"这家公司给新经理开出了百万年薪。","pinyin":"Zhè jiā gōngsī gěi xīn jīnglǐ kāi chūle bǎiwàn niánxīn.","vi":"Công ty này trả cho giám đốc mới mức lương năm một triệu tệ."},{"type":"compound","zh":"虽然年薪不算高，但是这份工作很稳定。","pinyin":"Suīrán niánxīn búsuàn gāo, dànshì zhè fèn gōngzuò hěn wěndìng.","vi":"Tuy lương năm không cao lắm nhưng công việc này rất ổn định."}],"related":[{"hanzi":"月薪","pinyin":"yuèxīn","vi":"lương tháng"},{"hanzi":"薪水","pinyin":"xīnshui","vi":"tiền lương"},{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"}]},{"id":"年夜饭","hanzi":"年夜饭","pinyin":"niányèfàn","meaning_vi":"bữa cơm tất niên (đêm giao thừa)","explanation":"年夜 (niên dạ – đêm cuối năm) + 饭 (phạn – bữa cơm) → bữa cơm đoàn viên của gia đình vào đêm giao thừa.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"全家一起吃年夜饭。","pinyin":"Quánjiā yìqǐ chī niányèfàn.","vi":"Cả nhà cùng ăn cơm tất niên."},{"type":"simple","zh":"妈妈从早上就开始准备丰盛的年夜饭。","pinyin":"Māma cóng zǎoshang jiù kāishǐ zhǔnbèi fēngshèng de niányèfàn.","vi":"Mẹ bắt đầu chuẩn bị bữa cơm giao thừa thịnh soạn từ sáng sớm."},{"type":"compound","zh":"即使工作再忙，他也要赶回家吃年夜饭。","pinyin":"Jíshǐ gōngzuò zài máng, tā yě yào gǎn huíjiā chī niányèfàn.","vi":"Dù công việc bận đến mấy, anh ấy cũng phải về kịp ăn bữa cơm tất niên."}],"related":[{"hanzi":"除夕","pinyin":"Chúxī","vi":"đêm giao thừa"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết"},{"hanzi":"团圆","pinyin":"tuányuán","vi":"đoàn viên"},{"hanzi":"饺子","pinyin":"jiǎozi","vi":"sủi cảo"}],"traditional":"年夜飯"},{"id":"年终","hanzi":"年终","pinyin":"niánzhōng","meaning_vi":"cuối năm","explanation":"年 (niên – năm) + 终 (chung – kết thúc) → thời điểm cuối năm.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"年终奖发了吗？","pinyin":"Niánzhōngjiǎng fāle ma?","vi":"Thưởng cuối năm phát chưa?"},{"type":"simple","zh":"公司在年终会对每个员工进行考核。","pinyin":"Gōngsī zài niánzhōng huì duì měi gè yuángōng jìnxíng kǎohé.","vi":"Vào cuối năm công ty sẽ đánh giá từng nhân viên."},{"type":"compound","zh":"因为年终工作太多，所以大家天天加班。","pinyin":"Yīnwèi niánzhōng gōngzuò tài duō, suǒyǐ dàjiā tiāntiān jiābān.","vi":"Vì cuối năm việc quá nhiều nên ngày nào mọi người cũng tăng ca."}],"related":[{"hanzi":"年底","pinyin":"niándǐ","vi":"cuối năm"},{"hanzi":"年初","pinyin":"niánchū","vi":"đầu năm"},{"hanzi":"年终奖","pinyin":"niánzhōngjiǎng","vi":"thưởng cuối năm"},{"hanzi":"总结","pinyin":"zǒngjié","vi":"tổng kết"}],"traditional":"年終"},{"id":"黏","hanzi":"黏","pinyin":"nián","meaning_vi":"dính, dẻo; bám (dính)","explanation":"黏 (niêm – dính) gồm 黍 (thử – lúa nếp) → dẻo dính như gạo nếp; cũng dùng chỉ người hay bám lấy người khác.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🍯","examples":[{"type":"basic","zh":"糯米饭很黏。","pinyin":"Nuò mǐfàn hěn nián.","vi":"Cơm nếp rất dẻo dính."},{"type":"simple","zh":"手上沾了蜂蜜，黏糊糊的很难受。","pinyin":"Shǒushang zhānle fēngmì, niánhūhū de hěn nánshòu.","vi":"Tay dính mật ong, nhớp nháp rất khó chịu."},{"type":"compound","zh":"虽然这孩子很黏妈妈，但是上学后独立多了。","pinyin":"Suīrán zhè háizi hěn nián māma, dànshì shàngxué hòu dúlì duō le.","vi":"Tuy đứa bé này rất hay bám mẹ, nhưng từ khi đi học đã tự lập hơn nhiều."}],"related":[{"hanzi":"黏糊","pinyin":"niánhu","vi":"dính nhớp"},{"hanzi":"粘贴","pinyin":"zhāntiē","vi":"dán"},{"hanzi":"糯米","pinyin":"nuòmǐ","vi":"gạo nếp"},{"hanzi":"胶水","pinyin":"jiāoshuǐ","vi":"keo dán"}]},{"id":"念书","hanzi":"念书","pinyin":"niànshū","meaning_vi":"đi học, học hành; đọc sách","explanation":"念 (niệm – đọc) + 书 (thư – sách) → đọc sách, học; trong khẩu ngữ thường chỉ đi học.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎒","examples":[{"type":"basic","zh":"他在北京念书。","pinyin":"Tā zài Běijīng niànshū.","vi":"Cậu ấy đang đi học ở Bắc Kinh."},{"type":"simple","zh":"她小时候家里穷，没机会念书。","pinyin":"Tā xiǎoshíhou jiālǐ qióng, méi jīhuì niànshū.","vi":"Hồi nhỏ nhà cô ấy nghèo, không có cơ hội đi học."},{"type":"compound","zh":"只要你肯好好念书，爸妈就一定支持你。","pinyin":"Zhǐyào nǐ kěn hǎohǎo niànshū, bàmā jiù yídìng zhīchí nǐ.","vi":"Chỉ cần con chịu học hành chăm chỉ, bố mẹ nhất định sẽ ủng hộ con."}],"related":[{"hanzi":"读书","pinyin":"dúshū","vi":"đọc sách, đi học"},{"hanzi":"上学","pinyin":"shàngxué","vi":"đi học"},{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"朗读","pinyin":"lǎngdú","vi":"đọc to"}],"traditional":"念書"},{"id":"酿造","hanzi":"酿造","pinyin":"niàngzào","meaning_vi":"ủ, lên men (rượu, giấm, tương…)","explanation":"酿 (nhưỡng – ủ men) + 造 (tạo – làm ra) → làm rượu, giấm, nước tương… bằng cách lên men.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍶","examples":[{"type":"basic","zh":"这瓶酒是自家酿造的。","pinyin":"Zhè píng jiǔ shì zìjiā niàngzào de.","vi":"Chai rượu này là nhà tự ủ."},{"type":"simple","zh":"这家工厂用传统方法酿造酱油。","pinyin":"Zhè jiā gōngchǎng yòng chuántǒng fāngfǎ niàngzào jiàngyóu.","vi":"Nhà máy này ủ nước tương theo phương pháp truyền thống."},{"type":"compound","zh":"因为酿造时间长达三年，所以这种醋特别香。","pinyin":"Yīnwèi niàngzào shíjiān chángdá sān nián, suǒyǐ zhè zhǒng cù tèbié xiāng.","vi":"Vì thời gian ủ lên tới ba năm nên loại giấm này đặc biệt thơm."}],"related":[{"hanzi":"酿酒","pinyin":"niàngjiǔ","vi":"nấu rượu"},{"hanzi":"发酵","pinyin":"fājiào","vi":"lên men"},{"hanzi":"啤酒","pinyin":"píjiǔ","vi":"bia"},{"hanzi":"酒厂","pinyin":"jiǔchǎng","vi":"nhà máy rượu"}],"traditional":"釀造"},{"id":"娘","hanzi":"娘","pinyin":"niáng","meaning_vi":"mẹ; cô gái","explanation":"娘 (nương) → cách gọi mẹ trong khẩu ngữ, phương ngữ; cũng chỉ phụ nữ trẻ (姑娘, 新娘).","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"娘，我回来了！","pinyin":"Niáng, wǒ huílái le!","vi":"Mẹ ơi, con về rồi!"},{"type":"simple","zh":"他每个月都给老家的娘寄钱。","pinyin":"Tā měi gèyuè dōu gěi lǎojiā de niáng jì qián.","vi":"Tháng nào anh ấy cũng gửi tiền cho mẹ ở quê."},{"type":"compound","zh":"虽然娘不识字，但是她教会了我做人的道理。","pinyin":"Suīrán niáng bù shízì, dànshì tā jiāohuìle wǒ zuòrén de dàolǐ.","vi":"Tuy mẹ không biết chữ, nhưng mẹ đã dạy tôi đạo lý làm người."}],"related":[{"hanzi":"爹","pinyin":"diē","vi":"cha"},{"hanzi":"姑娘","pinyin":"gūniang","vi":"cô gái"},{"hanzi":"新娘","pinyin":"xīnniáng","vi":"cô dâu"},{"hanzi":"母亲","pinyin":"mǔqīn","vi":"mẹ"}]},{"id":"鸟巢","hanzi":"鸟巢","pinyin":"niǎocháo","meaning_vi":"tổ chim; sân vận động Tổ Chim (Bắc Kinh)","explanation":"鸟 (điểu – chim) + 巢 (sào – tổ) → tổ chim; cũng là tên gọi sân vận động quốc gia Bắc Kinh (Olympic 2008).","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🪺","examples":[{"type":"basic","zh":"树上有个鸟巢。","pinyin":"Shù shang yǒu gè niǎocháo.","vi":"Trên cây có một tổ chim."},{"type":"simple","zh":"我们参观了奥运会主场馆鸟巢。","pinyin":"Wǒmen cānguānle Àoyùnhuì zhǔchǎng guǎn niǎocháo.","vi":"Chúng tôi đã tham quan sân vận động chính Tổ Chim của Olympic."},{"type":"compound","zh":"如果你把鸟巢弄坏了，鸟妈妈就不会回来了。","pinyin":"Rúguǒ nǐ bǎ niǎocháo nòng huàile, niǎo māma jiù bú huì huílái le.","vi":"Nếu em làm hỏng tổ chim thì chim mẹ sẽ không quay lại nữa."}],"related":[{"hanzi":"巢穴","pinyin":"cháoxué","vi":"hang ổ"},{"hanzi":"鸟窝","pinyin":"niǎowō","vi":"tổ chim"},{"hanzi":"水立方","pinyin":"Shuǐlìfāng","vi":"Khối Nước"},{"hanzi":"鸟类","pinyin":"niǎolèi","vi":"loài chim"}],"traditional":"鳥巢"},{"id":"尿","hanzi":"尿","pinyin":"niào","meaning_vi":"nước tiểu; đi tiểu","explanation":"尿 (niệu) gồm 尸 (thân thể) + 水 (nước) → nước thải ra từ cơ thể, nước tiểu; cũng làm động từ đi tiểu.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🚽","examples":[{"type":"basic","zh":"宝宝尿裤子了。","pinyin":"Bǎobao niàokùzi le.","vi":"Em bé tè ra quần rồi."},{"type":"simple","zh":"医生让他明天早上去医院验尿。","pinyin":"Yīshēng ràng tā míngtiān zǎo shangqù yīyuàn yànniào.","vi":"Bác sĩ bảo anh ấy sáng mai đến bệnh viện xét nghiệm nước tiểu."},{"type":"compound","zh":"如果尿的颜色太深，就说明你喝水太少了。","pinyin":"Rúguǒ niào de yánsè tài shēn, jiù shuōmíng nǐ hēshuǐ tài shǎo le.","vi":"Nếu nước tiểu màu quá sẫm thì chứng tỏ bạn uống quá ít nước."}],"related":[{"hanzi":"小便","pinyin":"xiǎobiàn","vi":"tiểu tiện"},{"hanzi":"尿布","pinyin":"niàobù","vi":"tã"},{"hanzi":"厕所","pinyin":"cèsuǒ","vi":"nhà vệ sinh"},{"hanzi":"尿检","pinyin":"niàojiǎn","vi":"xét nghiệm nước tiểu"}]},{"id":"扭头","hanzi":"扭头","pinyin":"niǔtóu","meaning_vi":"quay đầu, ngoảnh đầu","explanation":"扭 (nữu – vặn, xoay) + 头 (đầu) → xoay đầu, ngoảnh mặt; cũng chỉ quay người bỏ đi.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"↩️","examples":[{"type":"basic","zh":"她扭头看了我一眼。","pinyin":"Tā niǔtóu kànle wǒ yìyǎn.","vi":"Cô ấy ngoảnh đầu nhìn tôi một cái."},{"type":"simple","zh":"他听完一句话都没说，扭头就走了。","pinyin":"Tā tīng wán yíjùhuà dōu méi shuō, niǔtóu jiù zǒu le.","vi":"Nghe xong anh ấy chẳng nói câu nào, quay đầu bỏ đi luôn."},{"type":"compound","zh":"一听到有人叫他的名字，他就马上扭头去看。","pinyin":"Yì tīngdào yǒurén jiào tā de míngzi, tā jiù mǎshàng niǔtóu qù kàn.","vi":"Vừa nghe có người gọi tên mình, anh ấy liền quay đầu lại nhìn."}],"related":[{"hanzi":"回头","pinyin":"huítóu","vi":"quay đầu lại"},{"hanzi":"转身","pinyin":"zhuǎnshēn","vi":"quay người"},{"hanzi":"扭","pinyin":"niǔ","vi":"vặn, xoay"},{"hanzi":"低头","pinyin":"dītóu","vi":"cúi đầu"}],"traditional":"扭頭"},{"id":"纽扣","hanzi":"纽扣","pinyin":"niǔkòu","meaning_vi":"cúc áo, khuy áo","explanation":"纽 (nữu – núm) + 扣 (khấu – cài) → khuy, cúc để cài áo.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"🔘","examples":[{"type":"basic","zh":"我的纽扣掉了。","pinyin":"Wǒ de niǔkòu diào le.","vi":"Cúc áo của tôi bị rơi rồi."},{"type":"simple","zh":"奶奶戴上老花镜帮我缝好了纽扣。","pinyin":"Nǎinai dàishang lǎohuājìng bāng wǒ féng hǎole niǔkòu.","vi":"Bà đeo kính lão khâu lại cúc áo cho tôi."},{"type":"compound","zh":"因为纽扣扣错了一个，所以整件衬衫都歪了。","pinyin":"Yīnwèi niǔkòu kòu cuòle yí gè, suǒyǐ zhěng jiàn chènshān dōu wāi le.","vi":"Vì cài lệch một chiếc cúc nên cả chiếc áo sơ mi bị xộc xệch."}],"related":[{"hanzi":"扣子","pinyin":"kòuzi","vi":"cúc áo"},{"hanzi":"拉链","pinyin":"lāliàn","vi":"khóa kéo"},{"hanzi":"衬衫","pinyin":"chènshān","vi":"áo sơ mi"},{"hanzi":"缝","pinyin":"féng","vi":"khâu"}],"traditional":"紐扣"},{"id":"农场","hanzi":"农场","pinyin":"nóngchǎng","meaning_vi":"nông trại, nông trường","explanation":"农 (nông – nghề nông) + 场 (trường – nơi, bãi) → nơi trồng trọt, chăn nuôi quy mô lớn.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🚜","examples":[{"type":"basic","zh":"他在农场工作。","pinyin":"Tā zài nóngchǎng gōngzuò.","vi":"Anh ấy làm việc ở nông trại."},{"type":"simple","zh":"周末我们带孩子去农场摘草莓。","pinyin":"Zhōumò wǒmen dàiháizi qù nóngchǎng zhāi cǎoméi.","vi":"Cuối tuần chúng tôi đưa con đến nông trại hái dâu tây."},{"type":"compound","zh":"虽然农场的工作很累，但是他觉得很充实。","pinyin":"Suīrán nóngchǎng de gōngzuò hěn lèi, dànshì tā juéde hěn chōngshí.","vi":"Tuy công việc ở nông trại rất mệt nhưng anh ấy thấy rất có ý nghĩa."}],"related":[{"hanzi":"牧场","pinyin":"mùchǎng","vi":"trang trại chăn nuôi"},{"hanzi":"农民","pinyin":"nóngmín","vi":"nông dân"},{"hanzi":"农业","pinyin":"nóngyè","vi":"nông nghiệp"},{"hanzi":"庄园","pinyin":"zhuāngyuán","vi":"điền trang"}],"traditional":"農場"},{"id":"农民工","hanzi":"农民工","pinyin":"nóngmíngōng","meaning_vi":"lao động nhập cư (từ nông thôn ra thành phố)","explanation":"农民 (nông dân) + 工 (công – công nhân) → người nông dân lên thành phố làm thuê.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👷","examples":[{"type":"basic","zh":"他是一名农民工。","pinyin":"Tā shì yì míng nóngmíngōng.","vi":"Anh ấy là một lao động nông thôn lên thành phố."},{"type":"simple","zh":"春节前，大批农民工坐火车回老家。","pinyin":"Chūnjié qián, dàpī nóngmíngōng zuò huǒchē huílǎojiā.","vi":"Trước Tết, rất đông lao động nhập cư đi tàu về quê."},{"type":"compound","zh":"虽然农民工建设了城市，但是他们的收入并不高。","pinyin":"Suīrán nóngmíngōng jiànshèle chéngshì, dànshì tāmen de shōurù bìngbù gāo.","vi":"Tuy lao động nhập cư xây dựng nên thành phố, nhưng thu nhập của họ không hề cao."}],"related":[{"hanzi":"打工","pinyin":"dǎgōng","vi":"làm thuê"},{"hanzi":"农民","pinyin":"nóngmín","vi":"nông dân"},{"hanzi":"工人","pinyin":"gōngrén","vi":"công nhân"},{"hanzi":"民工","pinyin":"míngōng","vi":"thợ làm thuê"}],"traditional":"農民工"},{"id":"农作物","hanzi":"农作物","pinyin":"nóngzuòwù","meaning_vi":"cây trồng, hoa màu","explanation":"农 (nông) + 作物 (tác vật – cây trồng) → các loại cây trồng trong nông nghiệp như lúa, ngô, đậu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌽","examples":[{"type":"basic","zh":"农作物长势很好。","pinyin":"Nóngzuòwù zhǎngshì hěn hǎo.","vi":"Cây trồng phát triển rất tốt."},{"type":"simple","zh":"这场大旱让很多农作物都枯死了。","pinyin":"Zhè chǎng dà hàn ràng hěn duō nóngzuòwù dōu kū sǐle.","vi":"Trận hạn hán lớn này khiến nhiều hoa màu chết khô."},{"type":"compound","zh":"如果农药用得太多，农作物就会有残留。","pinyin":"Rúguǒ nóngyào yòng de tài duō, nóngzuòwù jiù huì yǒu cánliú.","vi":"Nếu dùng quá nhiều thuốc trừ sâu thì hoa màu sẽ bị tồn dư."}],"related":[{"hanzi":"庄稼","pinyin":"zhuāngjia","vi":"hoa màu"},{"hanzi":"粮食","pinyin":"liángshi","vi":"lương thực"},{"hanzi":"收成","pinyin":"shōucheng","vi":"mùa màng"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng trọt"}],"traditional":"農作物"},{"id":"浓缩","hanzi":"浓缩","pinyin":"nóngsuō","meaning_vi":"cô đặc, cô đọng; (cà phê) espresso","explanation":"浓 (nùng – đặc) + 缩 (súc – co lại) → làm cho đặc lại; nghĩa bóng là cô đọng nội dung.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"☕","examples":[{"type":"basic","zh":"我要一杯浓缩咖啡。","pinyin":"Wǒ yào yì bēi nóngsuō kāfēi.","vi":"Cho tôi một tách cà phê espresso."},{"type":"simple","zh":"这本小书浓缩了作者一生的经验。","pinyin":"Zhè běn xiǎo shū nóngsuōle zuòzhě yìshēng de jīngyàn.","vi":"Cuốn sách nhỏ này cô đọng kinh nghiệm cả đời của tác giả."},{"type":"compound","zh":"因为这种果汁是浓缩的，所以要兑水再喝。","pinyin":"Yīnwèi zhè zhǒng guǒzhī shì nóngsuō de, suǒyǐ yào duì shuǐ zài hē.","vi":"Vì loại nước ép này là dạng cô đặc nên phải pha thêm nước rồi mới uống."}],"related":[{"hanzi":"浓","pinyin":"nóng","vi":"đặc"},{"hanzi":"压缩","pinyin":"yāsuō","vi":"nén"},{"hanzi":"精华","pinyin":"jīnghuá","vi":"tinh hoa"},{"hanzi":"稀释","pinyin":"xīshì","vi":"pha loãng"}],"traditional":"濃縮"},{"id":"女婿","hanzi":"女婿","pinyin":"nǚxu","meaning_vi":"con rể","explanation":"女 (nữ – con gái) + 婿 (tế – chồng) → chồng của con gái, con rể.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🤵","examples":[{"type":"basic","zh":"这是我的女婿。","pinyin":"Zhè shì wǒ de nǚxu.","vi":"Đây là con rể tôi."},{"type":"simple","zh":"老两口对这个女婿特别满意。","pinyin":"Lǎoliǎngkǒu duì zhè ge nǚxu tèbié mǎnyì.","vi":"Hai ông bà rất hài lòng với cậu con rể này."},{"type":"compound","zh":"虽然女婿是外国人，但是他很懂中国的礼节。","pinyin":"Suīrán nǚxu shì wàiguórén, dànshì tā hěn dǒng Zhōngguó de lǐjié.","vi":"Tuy con rể là người nước ngoài nhưng rất hiểu lễ nghi Trung Quốc."}],"related":[{"hanzi":"儿媳","pinyin":"érxí","vi":"con dâu"},{"hanzi":"岳父","pinyin":"yuèfù","vi":"bố vợ"},{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"chồng"},{"hanzi":"女儿","pinyin":"nǚ'ér","vi":"con gái"}]},{"id":"暖烘烘","hanzi":"暖烘烘","pinyin":"nuǎnhōnghōng","meaning_vi":"ấm áp, ấm sực","explanation":"暖 (noãn – ấm) + 烘烘 (hồng – sưởi, hơ lặp lại) → ấm sực, ấm áp dễ chịu; cũng chỉ cảm giác ấm lòng.","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🔥","examples":[{"type":"basic","zh":"屋里暖烘烘的。","pinyin":"Wū lǐ nuǎnhōnghōng de.","vi":"Trong nhà ấm sực."},{"type":"simple","zh":"晒过的被子盖在身上暖烘烘的。","pinyin":"Shàiguo de bèizi gài zài shēnshang nuǎnhōnghōng de.","vi":"Chăn đã phơi nắng đắp lên người thấy ấm áp."},{"type":"compound","zh":"虽然外面下着大雪，但是心里却暖烘烘的。","pinyin":"Suīrán wàimiàn xiàzhe Dàxuě, dànshì xīnlǐ què nuǎnhōnghōng de.","vi":"Tuy bên ngoài tuyết rơi dày, nhưng trong lòng lại thấy ấm áp."}],"related":[{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"ấm"},{"hanzi":"热乎乎","pinyin":"rèhūhū","vi":"nóng hổi"},{"hanzi":"冷冰冰","pinyin":"lěngbīngbīng","vi":"lạnh tanh"}]},{"id":"诺言","hanzi":"诺言","pinyin":"nuòyán","meaning_vi":"lời hứa","explanation":"诺 (nặc – đồng ý, hứa) + 言 (ngôn – lời) → lời đã hứa.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"他实现了诺言。","pinyin":"Tā shíxiànle nuòyán.","vi":"Anh ấy đã thực hiện lời hứa."},{"type":"simple","zh":"你可千万不能违背当初的诺言。","pinyin":"Nǐ kě qiānwàn bù néng wéibèi dāngchū de nuòyán.","vi":"Cậu tuyệt đối không được làm trái lời hứa lúc đầu."},{"type":"compound","zh":"既然许下了诺言，就一定要说到做到。","pinyin":"Jìrán xǔxiàle nuòyán, jiù yídìngyào shuōdào zuòdào.","vi":"Đã hứa thì nhất định phải nói được làm được."}],"related":[{"hanzi":"承诺","pinyin":"chéngnuò","vi":"cam kết"},{"hanzi":"许诺","pinyin":"xǔnuò","vi":"hứa hẹn"},{"hanzi":"誓言","pinyin":"shìyán","vi":"lời thề"},{"hanzi":"守信","pinyin":"shǒuxìn","vi":"giữ chữ tín"}],"traditional":"諾言"},{"id":"拍板","hanzi":"拍板","pinyin":"pāibǎn","meaning_vi":"quyết định, chốt (vấn đề); gõ phách","explanation":"拍 (phách – vỗ) + 板 (bản – tấm phách gỗ) → gõ phách; nghĩa bóng là người có quyền đưa ra quyết định cuối cùng.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔨","examples":[{"type":"basic","zh":"这事由老板拍板。","pinyin":"Zhè shìyóu lǎobǎn pāibǎn.","vi":"Chuyện này do sếp quyết định."},{"type":"simple","zh":"经过讨论，市长终于拍板同意了方案。","pinyin":"Jīngguò tǎolùn, shìzhǎng zhōngyú pāibǎn tóngyìle fāng'àn.","vi":"Sau khi thảo luận, thị trưởng cuối cùng đã chốt đồng ý phương án."},{"type":"compound","zh":"如果经理不拍板，我们就不能签合同。","pinyin":"Rúguǒ jīnglǐ bù pāibǎn, wǒmen jiù bù néng qiānhétong.","vi":"Nếu giám đốc không quyết thì chúng ta không thể ký hợp đồng."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"定案","pinyin":"dìng'àn","vi":"chốt phương án"},{"hanzi":"做主","pinyin":"zuòzhǔ","vi":"làm chủ"},{"hanzi":"拍卖","pinyin":"pāimài","vi":"đấu giá"}]},{"id":"拍卖","hanzi":"拍卖","pinyin":"pāimài","meaning_vi":"bán đấu giá","explanation":"拍 (phách – gõ búa) + 卖 (mại – bán) → bán bằng cách đấu giá, gõ búa chốt giá cao nhất.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🧑‍⚖️","examples":[{"type":"basic","zh":"这幅画将被拍卖。","pinyin":"Zhè fú huà jiāng bèi pāimài.","vi":"Bức tranh này sắp được đem đấu giá."},{"type":"simple","zh":"那块古董手表在拍卖会上卖出了高价。","pinyin":"Nà kuài gǔdǒng shǒubiǎo zài pāimàihuì shang màichūle gāojià.","vi":"Chiếc đồng hồ cổ ấy được bán giá cao tại buổi đấu giá."},{"type":"compound","zh":"因为公司欠债太多，所以法院拍卖了它的大楼。","pinyin":"Yīnwèi gōngsī qiànzhài tài duō, suǒyǐ fǎyuàn pāimàile tā de dàlóu.","vi":"Vì công ty nợ quá nhiều nên tòa án đã bán đấu giá tòa nhà của nó."}],"related":[{"hanzi":"拍卖会","pinyin":"pāimàihuì","vi":"buổi đấu giá"},{"hanzi":"竞拍","pinyin":"jìngpāi","vi":"đấu giá"},{"hanzi":"成交","pinyin":"chéngjiāo","vi":"chốt giao dịch"},{"hanzi":"起价","pinyin":"qǐjià","vi":"giá khởi điểm"}],"traditional":"拍賣"},{"id":"拍戏","hanzi":"拍戏","pinyin":"pāixì","meaning_vi":"quay phim, đóng phim","explanation":"拍 (phách – chụp, quay) + 戏 (hí – vở diễn) → quay phim, đóng phim truyền hình.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎥","examples":[{"type":"basic","zh":"她正在横店拍戏。","pinyin":"Tā zhèngzài héng diàn pāixì.","vi":"Cô ấy đang quay phim ở Hoành Điếm."},{"type":"simple","zh":"那位演员拍戏时不小心摔伤了腿。","pinyin":"Nà wèi yǎnyuán pāixì shí bù xiǎoxīn shuāishāngle tuǐ.","vi":"Nam diễn viên đó không may ngã bị thương ở chân khi đang quay phim."},{"type":"compound","zh":"虽然拍戏很辛苦，但是她从来不叫累。","pinyin":"Suīrán pāixì hěn xīnkǔ, dànshì tā cóngláibú jiào lèi.","vi":"Tuy đóng phim rất vất vả nhưng cô ấy chưa bao giờ kêu mệt."}],"related":[{"hanzi":"拍电影","pinyin":"pāidiànyǐng","vi":"quay phim điện ảnh"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"导演","pinyin":"dǎoyǎn","vi":"đạo diễn"},{"hanzi":"剧组","pinyin":"jùzǔ","vi":"đoàn làm phim"}],"traditional":"拍戲"},{"id":"牌照","hanzi":"牌照","pinyin":"páizhào","meaning_vi":"giấy phép (kinh doanh); biển số xe","explanation":"牌 (bài – tấm biển) + 照 (chiếu – giấy chứng nhận) → giấy phép do nhà nước cấp; biển số xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚘","examples":[{"type":"basic","zh":"这辆车没有牌照。","pinyin":"Zhè liàng chē méiyǒu páizhào.","vi":"Chiếc xe này không có biển số."},{"type":"simple","zh":"在上海买车牌照要花很多钱。","pinyin":"Zài Shànghǎi mǎi chē páizhào yào huā hěn duō qián.","vi":"Ở Thượng Hải mua biển số xe phải tốn rất nhiều tiền."},{"type":"compound","zh":"如果没有营业牌照，饭店就不能开业。","pinyin":"Rúguǒ méiyǒu yíngyè páizhào, fàndiàn jiù bù néng kāiyè.","vi":"Nếu không có giấy phép kinh doanh thì nhà hàng không thể khai trương."}],"related":[{"hanzi":"车牌","pinyin":"chēpái","vi":"biển số xe"},{"hanzi":"执照","pinyin":"zhízhào","vi":"giấy phép"},{"hanzi":"驾照","pinyin":"jiàzhào","vi":"bằng lái"},{"hanzi":"许可证","pinyin":"xǔkězhèng","vi":"giấy phép"}]},{"id":"攀","hanzi":"攀","pinyin":"pān","meaning_vi":"leo, trèo (bám lên); bám víu, trèo cao","explanation":"攀 (phan – vịn mà leo) → bám tay trèo lên cao; nghĩa bóng là bám víu người có địa vị (攀关系).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧗","examples":[{"type":"basic","zh":"他攀上了山顶。","pinyin":"Tā pān shàngle shāndǐng.","vi":"Anh ấy đã trèo lên đỉnh núi."},{"type":"simple","zh":"小猴子抓着树枝，一下子攀到了树上。","pinyin":"Xiǎo hóuzi zhuāzhe shùzhī, yíxiàzi pān dàole shù shang.","vi":"Chú khỉ con bám cành cây, thoắt cái đã leo lên ngọn cây."},{"type":"compound","zh":"即使悬崖再陡，他也要攀上去拍日出。","pinyin":"Jíshǐ xuányá zài dǒu, tā yě yào pān shàngqù pāi rìchū.","vi":"Dù vách núi dốc đến đâu, anh ấy cũng phải leo lên chụp bình minh."}],"related":[{"hanzi":"攀登","pinyin":"pāndēng","vi":"leo trèo"},{"hanzi":"攀岩","pinyin":"pānyán","vi":"leo núi đá"},{"hanzi":"爬","pinyin":"pá","vi":"leo, bò"},{"hanzi":"高攀","pinyin":"gāopān","vi":"trèo cao"}]},{"id":"盼","hanzi":"盼","pinyin":"pàn","meaning_vi":"mong, trông mong, ngóng chờ","explanation":"盼 (phán – trông ngóng) gồm 目 (mắt) + 分 → đưa mắt trông chờ, mong mỏi điều gì.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙏","examples":[{"type":"basic","zh":"孩子们盼着过年。","pinyin":"Háizimen pànzhe guònián.","vi":"Bọn trẻ mong đến Tết."},{"type":"simple","zh":"妈妈天天盼着在国外的儿子回家。","pinyin":"Māma tiāntiān pànzhe zài guówài de érzi huíjiā.","vi":"Ngày nào mẹ cũng ngóng con trai ở nước ngoài về nhà."},{"type":"compound","zh":"虽然盼了很久，但是这封信始终没有来。","pinyin":"Suīrán pànle hěn jiǔ, dànshì zhè fēng xìn shǐzhōng méiyǒu lái.","vi":"Tuy đã trông ngóng rất lâu nhưng lá thư ấy mãi vẫn không đến."}],"related":[{"hanzi":"盼望","pinyin":"pànwàng","vi":"mong đợi"},{"hanzi":"期盼","pinyin":"qīpàn","vi":"mong chờ"},{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"等待","pinyin":"děngdài","vi":"chờ đợi"}]},{"id":"抛","hanzi":"抛","pinyin":"pāo","meaning_vi":"ném, tung, quăng; vứt bỏ","explanation":"抛 (phao – ném) → ném, tung ra xa; nghĩa bóng là vứt bỏ, bỏ lại (抛弃).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚾","examples":[{"type":"basic","zh":"他把球抛给我。","pinyin":"Tā bǎ qiú pāo gěi wǒ.","vi":"Anh ấy tung quả bóng cho tôi."},{"type":"simple","zh":"新娘转过身，把花束抛向了人群。","pinyin":"Xīnniáng zhuǎn guòshēn, bǎ huāshù pāo xiàngle rénqún.","vi":"Cô dâu quay lưng lại, tung bó hoa về phía đám đông."},{"type":"compound","zh":"虽然他被父母抛下了，但是他从不怨恨。","pinyin":"Suīrán tā bèi fùmǔ pāoxià le, dànshì tā cóng bú yuànhèn.","vi":"Tuy bị cha mẹ bỏ rơi nhưng anh ấy chưa bao giờ oán hận."}],"related":[{"hanzi":"扔","pinyin":"rēng","vi":"ném"},{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"投","pinyin":"tóu","vi":"ném"},{"hanzi":"抛开","pinyin":"pāokāi","vi":"gạt bỏ"}],"traditional":"拋"},{"id":"抛开","hanzi":"抛开","pinyin":"pāokāi","meaning_vi":"gạt bỏ, gác lại, vứt bỏ","explanation":"抛 (phao – ném) + 开 (khai – ra xa) → ném ra xa; nghĩa bóng là gạt bỏ, không nghĩ đến nữa.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"抛开烦恼吧！","pinyin":"Pāokāi fánnǎo ba!","vi":"Hãy gạt bỏ phiền muộn đi!"},{"type":"simple","zh":"抛开成见，他其实是个很不错的人。","pinyin":"Pāokāi chéngjiàn, tā qíshí shì gè hěn búcuò de rén.","vi":"Gạt bỏ định kiến thì anh ấy thực ra là người khá tốt."},{"type":"compound","zh":"只要抛开杂念，你就能专心复习了。","pinyin":"Zhǐyào pāokāi zániàn, nǐ jiù néng zhuānxīn fùxí le.","vi":"Chỉ cần gạt bỏ tạp niệm, bạn sẽ có thể chuyên tâm ôn bài."}],"related":[{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"放下","pinyin":"fàngxià","vi":"buông bỏ"},{"hanzi":"撇开","pinyin":"piēkāi","vi":"gạt sang bên"},{"hanzi":"摆脱","pinyin":"bǎituō","vi":"thoát khỏi"}],"traditional":"拋開"},{"id":"刨","hanzi":"刨","pinyin":"páo","meaning_vi":"đào, bới, cuốc; trừ đi (khẩu ngữ)","explanation":"刨 (bào) → đọc páo: đào, bới đất; trừ ra (刨去). Đọc bào: cái bào, bào gỗ.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛏️","examples":[{"type":"basic","zh":"小狗在刨土。","pinyin":"Xiǎogǒu zài páo tǔ.","vi":"Chú chó con đang bới đất."},{"type":"simple","zh":"爷爷在地里刨了一上午的红薯。","pinyin":"Yéye zài dì lǐ páole yí shàngwǔ de hóngshǔ.","vi":"Ông nội đào khoai lang ngoài ruộng cả buổi sáng."},{"type":"compound","zh":"刨去房租和饭钱，这个月就剩不了多少了。","pinyin":"Páo qù fángzū hé fàn qián, zhè geyuè jiù shèng buliǎo duōshǎo le.","vi":"Trừ tiền nhà và tiền ăn đi thì tháng này chẳng còn lại bao nhiêu."}],"related":[{"hanzi":"挖","pinyin":"wā","vi":"đào"},{"hanzi":"刨根问底","pinyin":"páogēnwèndǐ","vi":"truy đến tận cùng"},{"hanzi":"铲","pinyin":"chǎn","vi":"xúc"},{"hanzi":"刨子","pinyin":"bàozi","vi":"cái bào"}]},{"id":"跑车","hanzi":"跑车","pinyin":"pǎochē","meaning_vi":"xe thể thao, xe đua","explanation":"跑 (bào – chạy) + 车 (xa – xe) → xe chạy nhanh, xe thể thao; xe đạp đua.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🏎️","examples":[{"type":"basic","zh":"他买了辆跑车。","pinyin":"Tā mǎile liàng pǎochē.","vi":"Anh ta mua một chiếc xe thể thao."},{"type":"simple","zh":"一辆红色跑车从我身边飞快地开过。","pinyin":"Yí liàng hóngsè pǎochē cóng wǒ shēnbiān fēikuài de kāi guò.","vi":"Một chiếc xe thể thao màu đỏ phóng vụt qua bên cạnh tôi."},{"type":"compound","zh":"虽然跑车很酷，但是在市区根本开不快。","pinyin":"Suīrán pǎochē hěn kù, dànshì zài shìqū gēnběn kāi bukuài.","vi":"Tuy xe thể thao rất ngầu nhưng trong nội thành hoàn toàn không chạy nhanh được."}],"related":[{"hanzi":"赛车","pinyin":"sàichē","vi":"xe đua"},{"hanzi":"轿车","pinyin":"jiàochē","vi":"xe con"},{"hanzi":"豪车","pinyin":"háochē","vi":"xe sang"},{"hanzi":"越野车","pinyin":"yuèyěchē","vi":"xe địa hình"}],"traditional":"跑車"},{"id":"跑龙套","hanzi":"跑龙套","pinyin":"pǎolóngtào","meaning_vi":"đóng vai phụ, vai quần chúng; làm việc vặt","explanation":"跑 (chạy) + 龙套 (long sáo – áo rồng của vai lính trong kinh kịch) → chạy vai quần chúng; nghĩa bóng là làm phụ, không quan trọng.","hsk_level":"7-9","tags":["thanh-ngu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"他年轻时常跑龙套。","pinyin":"Tā niánqīng shícháng pǎolóngtào.","vi":"Hồi trẻ anh ấy thường đóng vai quần chúng."},{"type":"simple","zh":"很多大明星刚出道时都在剧组跑龙套。","pinyin":"Hěn duōdà míngxīng gāng chūdào shí dōu zài jùzǔ pǎolóngtào.","vi":"Nhiều ngôi sao lớn khi mới vào nghề đều đóng vai phụ trong đoàn phim."},{"type":"compound","zh":"虽然我在项目里只是跑龙套，但是学到了很多。","pinyin":"Suīrán wǒ zài xiàngmù lǐ zhǐshì pǎolóngtào, dànshì xuédàole hěn duō.","vi":"Tuy trong dự án tôi chỉ làm việc phụ, nhưng đã học được rất nhiều."}],"related":[{"hanzi":"配角","pinyin":"pèijué","vi":"vai phụ"},{"hanzi":"主角","pinyin":"zhǔjué","vi":"vai chính"},{"hanzi":"群众演员","pinyin":"qúnzhòngyǎnyuán","vi":"diễn viên quần chúng"},{"hanzi":"打杂","pinyin":"dǎzá","vi":"làm việc vặt"}],"traditional":"跑龍套"},{"id":"胚胎","hanzi":"胚胎","pinyin":"pēitāi","meaning_vi":"phôi, phôi thai","explanation":"胚 (phôi – mầm) + 胎 (thai) → phôi thai, giai đoạn đầu của sinh vật; nghĩa bóng là mầm mống ban đầu.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"胚胎发育得很好。","pinyin":"Pēitāi fāyù de hěn hǎo.","vi":"Phôi thai phát triển rất tốt."},{"type":"simple","zh":"科学家在实验室里研究小鼠的胚胎。","pinyin":"Kēxuéjiā zài shíyànshì lǐ yánjiū xiǎoshǔ de pēitāi.","vi":"Các nhà khoa học nghiên cứu phôi chuột trong phòng thí nghiệm."},{"type":"compound","zh":"如果胚胎移植成功，她明年就能当妈妈了。","pinyin":"Rúguǒ pēitāi yízhí chénggōng, tā míngnián jiù néng dāng māma le.","vi":"Nếu chuyển phôi thành công, sang năm cô ấy sẽ được làm mẹ."}],"related":[{"hanzi":"胎儿","pinyin":"tāi'ér","vi":"thai nhi"},{"hanzi":"怀孕","pinyin":"huáiyùn","vi":"mang thai"},{"hanzi":"细胞","pinyin":"xìbāo","vi":"tế bào"},{"hanzi":"发育","pinyin":"fāyù","vi":"phát triển"}]},{"id":"陪葬","hanzi":"陪葬","pinyin":"péizàng","meaning_vi":"chôn theo, tuẫn táng","explanation":"陪 (bồi – đi kèm) + 葬 (táng – chôn) → chôn theo người chết (đồ vật hoặc người); nghĩa bóng là bị liên lụy chịu chết theo.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"⚱️","examples":[{"type":"basic","zh":"这些都是陪葬品。","pinyin":"Zhèxiē dōu shì péizàngpǐn.","vi":"Đây đều là đồ tùy táng."},{"type":"simple","zh":"考古学家在古墓里发现了大量陪葬的陶器。","pinyin":"Kǎogǔxué jiā zài gǔmù lǐ fāxiànle dàliàng péizàng de táoqì.","vi":"Các nhà khảo cổ phát hiện rất nhiều đồ gốm chôn theo trong mộ cổ."},{"type":"compound","zh":"如果你继续这样冒险，整个公司都要给你陪葬。","pinyin":"Rúguǒ nǐ jìxù zhèyàng màoxiǎn, zhěnggè gōngsī dōu yào gěi nǐ péizàng.","vi":"Nếu anh cứ tiếp tục mạo hiểm như vậy, cả công ty sẽ phải chết chùm theo anh."}],"related":[{"hanzi":"殉葬","pinyin":"xùnzàng","vi":"tuẫn táng"},{"hanzi":"陪葬品","pinyin":"péizàngpǐn","vi":"đồ tùy táng"},{"hanzi":"古墓","pinyin":"gǔmù","vi":"mộ cổ"},{"hanzi":"埋葬","pinyin":"máizàng","vi":"chôn cất"}]},{"id":"赔钱","hanzi":"赔钱","pinyin":"péiqián","meaning_vi":"lỗ vốn; bồi thường tiền","explanation":"赔 (bồi – đền, lỗ) + 钱 (tiền) → mất tiền, lỗ vốn; đền tiền cho người khác.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"这笔生意赔钱了。","pinyin":"Zhè bǐ shēngyi péiqián le.","vi":"Vụ làm ăn này lỗ rồi."},{"type":"simple","zh":"他不小心撞坏了邻居的车，只好赔钱。","pinyin":"Tā bù xiǎoxīn zhuàng huàile línjū de chē, zhǐhǎo péiqián.","vi":"Anh ấy vô ý đâm hỏng xe hàng xóm, đành phải đền tiền."},{"type":"compound","zh":"即使这次赔钱了，我们也要保证产品质量。","pinyin":"Jíshǐ zhè cì péiqián le, wǒmen yě yào bǎozhèng chǎnpǐn zhìliàng.","vi":"Dù lần này có lỗ, chúng ta cũng phải đảm bảo chất lượng sản phẩm."}],"related":[{"hanzi":"赚钱","pinyin":"zhuànqián","vi":"kiếm lời"},{"hanzi":"亏本","pinyin":"kuīběn","vi":"lỗ vốn"},{"hanzi":"赔偿","pinyin":"péicháng","vi":"bồi thường"},{"hanzi":"赔本","pinyin":"péiběn","vi":"lỗ vốn"}],"traditional":"賠錢"},{"id":"配件","hanzi":"配件","pinyin":"pèijiàn","meaning_vi":"linh kiện, phụ kiện, phụ tùng","explanation":"配 (phối – kèm theo) + 件 (kiện – bộ phận) → bộ phận, phụ kiện lắp kèm máy móc, thiết bị.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔩","examples":[{"type":"basic","zh":"手机配件很便宜。","pinyin":"Shǒujī pèijiàn hěn piányi.","vi":"Phụ kiện điện thoại rất rẻ."},{"type":"simple","zh":"这家店专门卖汽车配件和工具。","pinyin":"Zhè jiā diàn zhuānmén mài qìchē pèijiàn hé gōngjù.","vi":"Cửa hàng này chuyên bán phụ tùng ô tô và dụng cụ."},{"type":"compound","zh":"因为原厂配件太贵，所以他买了副厂的。","pinyin":"Yīnwèi yuán chǎng pèijiàn tài guì, suǒyǐ tā mǎile fù chǎng de.","vi":"Vì phụ tùng chính hãng quá đắt nên anh ấy mua hàng thay thế."}],"related":[{"hanzi":"零件","pinyin":"língjiàn","vi":"linh kiện"},{"hanzi":"部件","pinyin":"bùjiàn","vi":"bộ phận"},{"hanzi":"附件","pinyin":"fùjiàn","vi":"phụ kiện"},{"hanzi":"装配","pinyin":"zhuāngpèi","vi":"lắp ráp"}]},{"id":"配送","hanzi":"配送","pinyin":"pèisòng","meaning_vi":"giao hàng, phân phối","explanation":"配 (phối – sắp xếp) + 送 (tống – đưa) → soạn hàng theo đơn rồi giao đến tay khách.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🚚","examples":[{"type":"basic","zh":"商品免费配送。","pinyin":"Shāngpǐn miǎnfèi pèisòng.","vi":"Hàng hóa được giao miễn phí."},{"type":"simple","zh":"这家超市可以在一小时内配送到家。","pinyin":"Zhè jiā chāoshì kěyǐ zài yì xiǎoshí nèi pèisòng dàojiā.","vi":"Siêu thị này có thể giao hàng đến nhà trong vòng một giờ."},{"type":"compound","zh":"如果配送地址填错了，包裹就会被退回。","pinyin":"Rúguǒ pèisòng dìzhǐ tián cuò le, bāoguǒ jiù huì bèi tuìhuí.","vi":"Nếu điền sai địa chỉ giao hàng thì bưu kiện sẽ bị trả lại."}],"related":[{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"},{"hanzi":"送货","pinyin":"sònghuò","vi":"giao hàng"},{"hanzi":"物流","pinyin":"wùliú","vi":"logistics"},{"hanzi":"外卖","pinyin":"wàimài","vi":"đồ ăn giao tận nơi"}]},{"id":"配音","hanzi":"配音","pinyin":"pèiyīn","meaning_vi":"lồng tiếng","explanation":"配 (phối – ghép vào) + 音 (âm – âm thanh) → ghép giọng nói, âm thanh vào phim ảnh.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎙️","examples":[{"type":"basic","zh":"她给动画片配音。","pinyin":"Tā gěi dònghuàpiàn pèiyīn.","vi":"Cô ấy lồng tiếng cho phim hoạt hình."},{"type":"simple","zh":"这部外国电影的中文配音非常自然。","pinyin":"Zhè bù wàiguó diànyǐng de Zhōngwén pèiyīn fēicháng zìrán.","vi":"Phần lồng tiếng Trung của bộ phim nước ngoài này rất tự nhiên."},{"type":"compound","zh":"虽然配音演员不露脸，但是他们的声音大家都熟悉。","pinyin":"Suīrán pèiyīn yǎnyuán bú lòuliǎn, dànshì tāmen de shēngyīn dàjiā dōu shúxi.","vi":"Tuy diễn viên lồng tiếng không lộ mặt, nhưng ai cũng quen với giọng của họ."}],"related":[{"hanzi":"字幕","pinyin":"zìmù","vi":"phụ đề"},{"hanzi":"声音","pinyin":"shēngyīn","vi":"giọng nói"},{"hanzi":"旁白","pinyin":"pángbái","vi":"lời dẫn"},{"hanzi":"录音","pinyin":"lùyīn","vi":"thu âm"}]},{"id":"蓬勃","hanzi":"蓬勃","pinyin":"péngbó","meaning_vi":"mạnh mẽ, phồn thịnh, tràn đầy sức sống","explanation":"蓬 (bồng – um tùm) + 勃 (bột – bừng lên) → phát triển mạnh mẽ, tràn trề sức sống.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"他朝气蓬勃。","pinyin":"Tā zhāoqìpéngbó.","vi":"Anh ấy tràn đầy sức sống."},{"type":"simple","zh":"近几年，电子商务发展得十分蓬勃。","pinyin":"Jìnjǐnián, diànzǐshāngwù fāzhǎn de shífēn péngbó.","vi":"Mấy năm gần đây, thương mại điện tử phát triển hết sức mạnh mẽ."},{"type":"compound","zh":"因为政策支持，所以这个行业正蓬勃发展。","pinyin":"Yīnwèi zhèngcè zhīchí, suǒyǐ zhè ge hángyè zhèng péngbó fāzhǎn.","vi":"Nhờ chính sách hỗ trợ nên ngành này đang phát triển mạnh mẽ."}],"related":[{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"tràn đầy sức sống"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"thịnh vượng"},{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"}]},{"id":"鹏程万里","hanzi":"鹏程万里","pinyin":"péngchéng-wànlǐ","meaning_vi":"tiền đồ rộng mở, tương lai xán lạn","explanation":"鹏 (bằng – chim đại bàng thần) + 程 (trình – chặng đường) + 万里 (vạn lý) → chim bằng bay vạn dặm; chúc tiền đồ rộng lớn. Gốc từ sách Trang Tử.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦅","examples":[{"type":"basic","zh":"祝你鹏程万里！","pinyin":"Zhù nǐ péngchéngwànlǐ!","vi":"Chúc bạn tiền đồ rộng mở!"},{"type":"simple","zh":"毕业典礼上，校长祝同学们鹏程万里。","pinyin":"Bìyè diǎnlǐ shang, xiàozhǎng zhù tóngxuémen péngchéngwànlǐ.","vi":"Tại lễ tốt nghiệp, hiệu trưởng chúc các em tương lai xán lạn."},{"type":"compound","zh":"只要你坚持努力，将来就一定能鹏程万里。","pinyin":"Zhǐyào nǐ jiānchí nǔlì, jiānglái jiù yídìng néng péngchéngwànlǐ.","vi":"Chỉ cần em kiên trì nỗ lực, sau này nhất định sẽ có tiền đồ rộng mở."}],"related":[{"hanzi":"前程似锦","pinyin":"qiánchéngsìjǐn","vi":"tiền đồ như gấm"},{"hanzi":"前途","pinyin":"qiántú","vi":"tiền đồ"},{"hanzi":"一帆风顺","pinyin":"yìfānfēngshùn","vi":"thuận buồm xuôi gió"},{"hanzi":"大展宏图","pinyin":"dàzhǎnhóngtú","vi":"thỏa chí lớn"}],"traditional":"鵬程萬里"}];
